do
    local environment = getgenv()
    local previousLibrary = environment.PhowgLibrary
    local previousData = environment.PhowgData
    local previousFunc = environment.PhowgFunc
    if previousLibrary and type(previousLibrary.Unload) == 'function' and not previousLibrary.Unloaded then
        local ok, err = pcall(previousLibrary.Unload, previousLibrary)
        if not ok then
            error('[Phowg] previous instance failed to unload: ' .. tostring(err))
        end
    end
    if type(previousFunc) == 'table' then
        local stop = previousFunc.stop_runtime_features or previousFunc.StopRuntimeFeatures
        if type(stop) == 'function' then
            local ok, problem
            if previousFunc.stop_runtime_features then
                ok, problem = pcall(stop, previousFunc)
            else
                ok, problem = pcall(stop)
            end
            if not ok then error('[phowg] previous runtime cleanup failed: ' .. tostring(problem)) end
        end
    end
    if type(previousData) == 'table' then
        local flight = previousData.FlyConnection
        if type(flight) == 'table' and type(flight.Disconnect) == 'function' then
            flight:Disconnect()
            previousData.FlyConnection = nil
        end
        if previousData.AutoBlockAnimId then
            local animations = game:GetService('ReplicatedStorage'):FindFirstChild('ClientAnimations')
            local block = animations and animations:FindFirstChild('Block')
            if block and block.AnimationId == 'rbxassetid://0' then
                block.AnimationId = previousData.AutoBlockAnimId
            end
        end
        previousData.IsRespawning = true
        for key, value in pairs(previousData) do
            if typeof(value) == 'RBXScriptConnection' then
                value:Disconnect()
                previousData[key] = nil
            end
        end
        for _, key in ipairs({ 'HeartbeatFns', 'LoopTokens', 'PunishmentTargets' }) do
            if type(previousData[key]) == 'table' then
                table.clear(previousData[key])
            end
        end
        for _, key in ipairs({
            'Flying',
            'WallWalking',
            'VelocityActive',
            'VoidActive',
            'UndergroundActive',
            'DesyncActive',
        }) do
            previousData[key] = false
        end
        if type(previousData.CSyncTable) == 'table' then
            previousData.CSyncTable[2] = false
        end
        if type(previousData.GrenadeControlledParts) == 'table' then
            for part, state in pairs(previousData.GrenadeControlledParts) do
                state.released = true
                if state.molotovConnection then
                    state.molotovConnection:Disconnect()
                end
                if typeof(state.position) == 'Instance' then
                    state.position:Destroy()
                end
                if typeof(part) == 'Instance' and part.Parent then
                    if part.CFrame == state.molotovAppliedCFrame and typeof(state.molotovNativeCFrame) == 'CFrame' then
                        part.CFrame = state.molotovNativeCFrame
                    end
                    part.CanCollide = state.canCollide
                    part.CanQuery = state.canQuery
                end
            end
            previousData.GrenadeControlledParts = nil
        end
        local flyVehicle = previousData.FlyVehicle
        if type(flyVehicle) == 'table' then
            if flyVehicle.Connection then
                flyVehicle.Connection:Disconnect()
            end
            for force, enabled in pairs(flyVehicle.NativeForces or {}) do
                if typeof(force) == 'Instance' and force.Parent and force.Enabled == false then
                    force.Enabled = enabled
                end
            end
            local part = flyVehicle.Part
            if typeof(part) == 'Instance' and part.Parent and part.Anchored == false then
                part.Anchored = flyVehicle.Anchored
            end
            previousData.FlyVehicle = nil
        end
        for _, key in ipairs({
            'FlyCore',
            'FlyBodyVelocity',
            'FlyBodyGyro',
            'FlyLinearVelocity',
            'FlyOrientation',
            'FlyAttachment',
            'WallWalkCore',
            'ServerMovementCore',
        }) do
            local instance = previousData[key]
            if typeof(instance) == 'Instance' then
                instance:Destroy()
            end
            previousData[key] = nil
        end
    end
    environment.PhowgData = nil
    environment.PhowgLibrary = nil
    environment.PhowgFunc = nil
end
local StartupTiming = { Started = os.clock(), Stages = {}, Sources = {} }
local RuntimeRepository = 'https://raw.githubusercontent.com/0124091829571209581725098175/quioehgroiuhoiuqgferrgsfdg/'
local RuntimeRoot = RuntimeRepository .. 'db2a9ece006ae3c8acc692016340027c7a9708bf/runtime/'
local RuntimeFolder = getgenv().PhowgScriptFolder or 'C:/Users/expra/AppData/Local/Potassium/scripts/Linoria'
local RuntimeSources, RuntimeAssets = {}, {}
getgenv().PhowgRuntimeAssets = RuntimeAssets
local function runtime_path(relative)
    assert(type(writefile) == 'function' and type(makefolder) == 'function' and type(isfolder) == 'function', 'runtime downloads require filesystem support')
    if not isfolder(RuntimeFolder) then
        makefolder(RuntimeFolder)
    end
    local folder = RuntimeFolder
    for part in relative:gmatch('([^/]+)/') do
        folder = folder .. '/' .. part
        if not isfolder(folder) then
            makefolder(folder)
        end
    end
    return RuntimeFolder .. '/' .. relative
end
local ComponentURLs = {
    ['LinoriaLibrary.lua'] = RuntimeRoot .. 'components/LinoriaLibrary.lua',
    ['ThemeManager.luau'] = RuntimeRoot .. 'components/ThemeManager.luau',
    ['SaveManager.luau'] = RuntimeRoot .. 'components/SaveManager.luau',
}
local ComponentManifest = {
    ['LinoriaLibrary.lua'] = 56,
    ['SaveManager.luau'] = 9,
    ['ThemeManager.luau'] = 3,
}
local ComponentPolicy = 'github'

local function load_component(file, url)
    local began = os.clock()
    local requirements = {
        ['LinoriaLibrary.lua'] = {
            'RegisterControl',
            'CreateWindow',
            'QueueUIWork',
            'RunCallback',
            'SetUIFontSize',
            'SetReducedMotion',
            'FlushDeferredLayouts',
        },
        ['SaveManager.luau'] = {
            'ApplyConfig',
            'CaptureCurrent',
            'RegisterState',
            'RemoveAutoload',
            'OnControlChanged',
        },
        ['ThemeManager.luau'] = { 'SetLibrary', 'ApplyToTab' },
    }
    local failures = {}
    local function candidate(source, origin)
        if type(source) ~= 'string' then
            failures[#failures + 1] = origin .. ': expected source text, received ' .. type(source)
            return nil
        end
        source = source:gsub('^' .. string.char(239, 187, 191), '')
        local revision = tonumber(source:match('PhowgRevision%s*=%s*(%d+)')) or 0
        if revision ~= ComponentManifest[file] then
            failures[#failures + 1] = origin
                .. ': expected component revision '
                .. tostring(ComponentManifest[file])
                .. ', received '
                .. tostring(revision)
            return nil
        end
        local compileAt = os.clock()
        local chunk, problem = loadstring(source, '@' .. file)
        StartupTiming.Stages[file .. ' compile'] = os.clock() - compileAt
        if not chunk then
            failures[#failures + 1] = origin .. ': ' .. tostring(problem)
            return nil
        end
        return { Chunk = chunk, Origin = origin, Revision = revision, Source = source }
    end
    local function run(selected)
        local executeAt = os.clock()
        local result = selected.Chunk()
        StartupTiming.Stages[file .. ' initialize'] = os.clock() - executeAt
        if type(result) ~= 'table' then
            error('[Phowg] ' .. file .. ' returned an invalid component')
        end
        for _, method in ipairs(requirements[file] or {}) do
            if type(result[method]) ~= 'function' then
                error('[Phowg] ' .. file .. ' is missing API ' .. method)
            end
        end
        StartupTiming.ComponentVersions = StartupTiming.ComponentVersions or {}
        StartupTiming.ComponentVersions[file] = selected.Revision
        StartupTiming.Stages[file] = os.clock() - began
        StartupTiming.Sources[file] = selected.Origin
        writefile(runtime_path('components/' .. file), selected.Source)
        RuntimeSources[file] = selected.Source
        return result
    end
    if RuntimeSources[file] then
        local selected = candidate(RuntimeSources[file], 'github startup: ' .. file)
        if selected then return run(selected) end
    end
    local separator = url:find('?', 1, true) and '&' or '?'
    local fetched, source = pcall(function()
        return game:HttpGet(url .. separator .. 'phowg_revision=' .. tostring(ComponentManifest[file] or 0), true)
    end)
    if fetched then
        local selected = candidate(source, 'hosted: ' .. file)
        if selected then
            return run(selected)
        end
    else
        failures[#failures + 1] = 'hosted: ' .. tostring(source)
    end
    for attempt = 1, 2 do
        local retryURL = attempt == 2 and url:gsub('/refs/heads/', '/') or url
        local retrySeparator = retryURL:find('?', 1, true) and '&' or '?'
        local token = tostring(os.time())
            .. '-'
            .. tostring(math.floor(os.clock() * 1000000))
            .. '-'
            .. tostring(math.random(1, 1000000000))
        local ok, fresh = pcall(function()
            return game:HttpGet(retryURL .. retrySeparator .. 'phowg_retry=' .. token, true)
        end)
        local origin = 'hosted retry ' .. tostring(attempt) .. ': ' .. file
        if ok then
            local selected = candidate(fresh, origin)
            if selected then
                return run(selected)
            end
        else
            failures[#failures + 1] = origin .. ': ' .. tostring(fresh)
        end
    end
    error('[Phowg] Could not load the custom ' .. file .. ': ' .. table.concat(failures, '; '))
end
local Library = load_component('LinoriaLibrary.lua', ComponentURLs['LinoriaLibrary.lua'])
