Library:BeginStartupIntro()
Library:SetStartupProgress('downloading runtime manifest', 0.02)
do
    local http = game:GetService('HttpService')
    local manifest = http:JSONDecode(game:HttpGet(RuntimeRoot .. 'manifest.json', true))
    assert(type(manifest.Files) == 'table', 'invalid runtime manifest')
    for index, file in ipairs(manifest.Files) do
        assert(type(file.Target) == 'string' and not file.Target:find('..', 1, true) and not file.Target:find(':', 1, true), 'invalid runtime path')
        local path = runtime_path(file.Target)
        local component = file.Target:match('^components/(.+%.lua[u]?)$')
        if component then
            if not RuntimeSources[component] then
                local source = game:HttpGet(RuntimeRoot .. file.Path, true)
                assert(#source == file.Bytes, 'incomplete component: ' .. component)
                assert(loadstring(source, '@' .. component))
                writefile(path, source)
                RuntimeSources[component] = source
            end
        else
            local reusable = false
            if type(readfile) == 'function' then
                local ok, bytes, version = pcall(function()
                    return readfile(path), readfile(path .. '.version')
                end)
                reusable = ok and #bytes == file.Bytes and version == file.Sha
            end
            if not reusable then
                local bytes = game:HttpGet(RuntimeRoot .. file.Path, true)
                assert(type(bytes) == 'string' and #bytes == file.Bytes, 'incomplete asset: ' .. file.Target)
                writefile(path, bytes)
                writefile(path .. '.version', file.Sha)
            end
            RuntimeAssets[file.Target] = path
        end
        Library:SetStartupProgress('downloading ' .. file.Target, 0.02 + index / #manifest.Files * 0.1)
    end
end
