do
    local inputs = game:GetService('UserInputService')
    local mouse = game:GetService('Players').LocalPlayer:GetMouse()
    local register, createWindow = Library.RegisterControl, Library.CreateWindow
    Library.PopupOwners, Library.PopupClosers = {}, {}
    Library.ControlsReady = false
    Library.PendingControlCallbacks = {}
    function Library:FlushControlCallbacks()
        if not self.ControlsReady or self.ConfigLoading or self.SuppressSave or self.Unloaded then
            return
        end
        local pending = self.PendingControlCallbacks
        self.PendingControlCallbacks = {}
        local ordered = {}
        for control, entry in pairs(pending) do
            ordered[#ordered + 1] = { Control = control, Entry = entry }
        end
        table.sort(ordered, function(a, b)
            return (a.Control.RegistrationSequence or 0) < (b.Control.RegistrationSequence or 0)
        end)
        for _, item in ipairs(ordered) do
            local entry = item.Entry
            if entry.Callback then
                entry.Callback(true)
            end
            if entry.Changed then
                entry.Changed(true)
            end
        end
    end
    function Library:IsControlVisible(frame)
        local current = frame
        while current do
            if current == self.ScreenGui then
                return current.Enabled
            end
            if current:IsA('GuiObject') and not current.Visible then
                return false
            end
            current = current.Parent
        end
        return false
    end
    function Library:ClosePopups(except)
        for frame in pairs(table.clone(self.OpenedFrames)) do
            if not (self.IsPopupAncestor and self:IsPopupAncestor(frame, except) or frame == except) then
                local close = self.PopupClosers[frame]
                if close then
                    close()
                elseif frame.Parent then
                    frame.Visible = false
                end
                self.OpenedFrames[frame] = nil
            end
        end
    end
    function Library:PrunePopups()
        for frame in pairs(table.clone(self.OpenedFrames)) do
            local owner = self.PopupOwners[frame]
            if not self:IsControlVisible(frame) or (owner and not self:IsControlVisible(owner)) then
                local close = self.PopupClosers[frame]
                if close then
                    close()
                elseif frame.Parent then
                    frame.Visible = false
                end
                self.OpenedFrames[frame] = nil
            end
        end
    end
    function Library:MouseIsOverOpenedFrame(region)
        self:PrunePopups()
        local settings = self.GetSettingsBox and region and self:GetSettingsBox(region)
        for frame in pairs(self.OpenedFrames) do
            local position, size = frame.AbsolutePosition, frame.AbsoluteSize
            if
                not (self.IsPopupAncestor and self:IsPopupAncestor(frame, settings))
                and size.X > 0
                and size.Y > 0
                and mouse.X >= position.X
                and mouse.X <= position.X + size.X
                and mouse.Y >= position.Y
                and mouse.Y <= position.Y + size.Y
            then
                return true
            end
        end
        return false
    end
    function Library:RegisterControl(index, control, owner, label, row)
        register(self, index, control, owner, label, row)
        local function bind(field, callback)
            if type(callback) ~= 'function' then
                return callback
            end
            local revision = 0
            return function(...)
                if self.SafeModeControlAllowed and not self.SafeModeControlAllowed(index, control, select(1, ...)) then
                    return
                end
                if self.ScriptData and self.ScriptData.Unloading then
                    return callback(...)
                end
                revision = revision + 1
                local current = revision
                local arguments = table.pack(...)
                local function dispatch(immediate)
                    local function run()
                        if self.Unloaded or current ~= revision then
                            return
                        end
                        if not self.ControlsReady or self.ConfigLoading or self.SuppressSave then
                            self.PendingControlCallbacks[control] = self.PendingControlCallbacks[control] or {}
                            self.PendingControlCallbacks[control][field] = dispatch
                            return
                        end
                        if
                            self.SafeModeControlAllowed
                            and not self.SafeModeControlAllowed(index, control, arguments[1])
                        then
                            return
                        end
                        local ok, problem = self:RunCallback(callback, table.unpack(arguments, 1, arguments.n))
                        if not ok then
                            warn('[phowg] control ' .. tostring(index) .. ': ' .. tostring(problem))
                        end
                    end
                    if immediate then
                        run()
                    else
                        self:QueueUIWork(control, run, field)
                    end
                end
                if not self.ControlsReady or self.ConfigLoading or self.SuppressSave then
                    self.PendingControlCallbacks[control] = self.PendingControlCallbacks[control] or {}
                    self.PendingControlCallbacks[control][field] = dispatch
                    return
                end
                return callback(table.unpack(arguments, 1, arguments.n))
            end
        end
        control.Callback = bind('Callback', control.Callback)
        if control.OnChanged then
            local changed = control.OnChanged
            control.OnChanged = function(item, callback)
                return changed(item, bind('Changed', callback))
            end
        end
        if control.Type == 'Toggle' and control.Value and control.Callback then
            control.Callback(control.Value)
        end
        local openName, closeName
        if control.OpenDropdown then
            openName, closeName = 'OpenDropdown', 'CloseDropdown'
        elseif control.Type == 'ColorPicker' then
            openName, closeName = 'Show', 'Hide'
        end
        if openName then
            local open, close = control[openName], control[closeName]
            control[openName] = function(item, ...)
                if row and not self:IsControlVisible(row) then
                    return
                end
                local anchor = row or owner and owner.Container
                local settings = self.GetSettingsBox and self:GetSettingsBox(anchor)
                self:ClosePopups(settings)
                local previous = table.clone(self.OpenedFrames)
                open(item, ...)
                for frame in pairs(self.OpenedFrames) do
                    if not previous[frame] then
                        self.PopupOwners[frame] = anchor
                        self.PopupClosers[frame] = function()
                            close(item)
                        end
                    end
                end
            end
        end
    end
    function Library:CreateWindow(...)
        local window = createWindow(self, ...)
        local toggle, addTab = self.Toggle, window.AddTab
        self.Toggle = function(instance, ...)
            self:ClosePopups()
            return toggle(self, ...)
        end
        window.AddTab = function(instance, ...)
            local tab = addTab(instance, ...)
            local hide = tab.HideTab
            tab.HideTab = function(item, ...)
                self:ClosePopups()
                return hide(item, ...)
            end
            return tab
        end
        return window
    end
    Library:GiveSignal(inputs.InputEnded:Connect(function(input)
        Library.ConsumedInputs[input] = nil
    end))
    Library:GiveSignal(inputs.InputBegan:Connect(function(input)
        Library:PrunePopups()
        if input.KeyCode == Enum.KeyCode.Escape then
