local function getvoidcframe()
    local mode = Options and Options.void_mode and Options.void_mode.Value or 'unkillable'
    if mode == 'anti matrix' then
        return AntiMatrixCFrame
    end
    if mode == 'random' then
        return CFrame.new(math.random(-1000000, 1000000), 1000000, math.random(-1000000, 1000000))
    end
    return VoidCFrame
end
