function phowg:target_search_active()
    local state = Data.TargetSearch
    return state ~= nil and state.Active == true and not Data.SafeMode and not Library.Unloaded and not Data.Unloading
end
function phowg:target_search_engaged()
    local state = Data.TargetSearch
    return phowg:target_search_active()
        and state.Mode == 'target'
        and state.Target ~= nil
        and state.Target.Parent == Players
end
function phowg:auto_bounty_enabled()
    return not phowg:target_search_active()
        and Toggles.auto_bounty ~= nil
        and Toggles.auto_bounty.Value == true
        and Data.AutoBounty ~= nil
        and not Data.SafeMode
        and not Library.Unloaded
end
function phowg:ragebot_action_enabled(name)
    if phowg:target_search_active() then
        return name == 'auto_kill' and phowg:target_search_engaged()
    end
    local control = Toggles[name]
    return control ~= nil and control.Value == true or phowg:auto_bounty_enabled() and not Data.PunishmentGunActive
end
