local function localactionblocked(allowKnocked: boolean?): boolean
    if Data.SafeMode then
        return true
    end
    local character = LocalPlayer.Character
    local humanoid = character and character:FindFirstChildOfClass('Humanoid')
    if Data['IsRespawning'] or not character or not character.Parent or not humanoid or humanoid.Health <= 0 then
        return true
    end
    local effects = character:FindFirstChild('BodyEffects')
    if not effects then
        return true
    end
    for _, name in ipairs({ 'Dead', 'K.O', 'KO', 'SDeath' }) do
        local value = effects:FindFirstChild(name)
        if value and value.Value == true and (name == 'Dead' or name == 'SDeath' or not allowKnocked) then
            return true
        end
    end
    return false
end
local function localshootblocked(): boolean
    if localactionblocked() then
        return true
    end
    local character = LocalPlayer.Character
    local effects = character and character:FindFirstChild('BodyEffects')
    for _, name in ipairs({ 'Attacking', 'Eating' }) do
        local state = effects and effects:FindFirstChild(name)
        if state and state.Value == true then
            return true
        end
    end
    return false
end
local function normalizeweaponname(name): string
    local normalized = tostring(name or ''):lower():gsub('[^%w]', '')
    if normalized == 'db' or normalized == 'doublebarrel' then
        return 'doublebarrelsg'
    end
    return normalized
end
