function phowg:gun_weapon_choices(bracketed, extra)
    local values, seen = {}, {}
    local function add(name)
        local key = normalizeweaponname(name)
        if seen[key] then
            return
        end
        seen[key] = true
        values[#values + 1] = bracketed and name or key == 'flintlockrifle' and 'flintlock + rifle' or key
    end
    for _, name in ipairs(extra or {}) do
        add(name)
    end
    for _, name in ipairs(Data.GunWeaponNames) do
        add(name)
    end
    return values
end
function phowg:is_gun_weapon(name)
    local key = normalizeweaponname(name)
    return Data.GunWeaponKeys[key] == true or key == 'flamethrower'
end
function phowg:tool_grip_allowed(tool)
    return typeof(tool) == 'Instance'
        and tool:IsA('Tool')
        and not phowg:is_gun_weapon(tool.Name)
        and not tool:FindFirstChild('Ammo')
        and not tool:FindFirstChild('MaxAmmo')
        and not tool:FindFirstChild('GunClient')
        and not tool:FindFirstChild('GunClientAutomatic')
        and not tool:FindFirstChild('GunClientBurst')
        and not tool:FindFirstChild('GunClientShotgun')
        and not tool:FindFirstChild('GunClientAutomaticShotgun')
        and not tool:FindFirstChild('Range')
end
Data.RagebotGunChoices =
    { 'rifle', 'double barrel sg', 'aug', 'lmg', 'revolver', 'flintlock', 'deagle', 'combat', 'knife' }
function phowg:ragebot_melee_weapon(value)
    if type(value) == 'string' then
        local name = normalizeweaponname(value)
        return (name == 'combat' or name == 'knife') and name or nil
    end
    if type(value) == 'table' then
        local combat, knife = false, false
        for key, active in pairs(value) do
            local label = type(key) == 'number' and active or active and key
            local name = normalizeweaponname(label)
            combat, knife = combat or name == 'combat', knife or name == 'knife'
        end
        return knife and 'knife' or combat and 'combat' or nil
    end
    return nil
end
function phowg:ragebot_gun_names(value, multi)
    if value == nil then
        value = Options.auto_kill_weapon and Options.auto_kill_weapon.Value
    end
    if multi == nil then
        multi = Options.gun_shoot_method and Options.gun_shoot_method.Value == 'china hack'
    end
    local melee = phowg:ragebot_melee_weapon(value)
    if melee then
        multi = false
    end
    local cache = Data.RagebotSelectionCache
    if
        cache
        and cache.Value == value
        and cache.Multi == multi
        and cache.Revision == (Data.ToolSelectionRevision or 0)
    then
        return table.clone(cache.Names)
    end
    local selected = {}
    local function add(name)
        local key = normalizeweaponname(name)
        if key == 'flintlockrifle' then
            selected.flintlock = true
            key = 'rifle'
        end
        selected[key] = true
    end
    if type(value) == 'table' then
        for key, active in pairs(value) do
            if type(key) == 'number' and type(active) == 'string' then
                add(active)
            elseif type(key) == 'string' and active then
                add(key)
            end
        end
    elseif type(value) == 'string' then
        add(value)
    end
    local names = {}
    if melee then
        names[1] = melee
    end
    for _, label in ipairs(Data.RagebotGunChoices) do
        if melee then
            break
        end
        local key = normalizeweaponname(label)
        if selected[key] then
            names[#names + 1] = key
            if not multi then
                break
            end
        end
    end
    if #names == 0 then
        names[1] = 'rifle'
    end
    Data.RagebotSelectionCache =
        { Value = value, Multi = multi, Revision = Data.ToolSelectionRevision or 0, Names = names }
    return table.clone(names)
end
function phowg:is_ragebot_gun_selected(tool)
    if not tool or not phowg:is_gun_weapon(tool.Name) then
        return false
    end
    local name = normalizeweaponname(tool.Name)
    for _, key in ipairs(phowg:ragebot_gun_names()) do
        if name == key then
            return true
        end
    end
    return false
end
function phowg:ragebot_gun_value(value, multi)
    local names = phowg:ragebot_gun_names(value, multi)
    if not multi then
        return names[1] == 'doublebarrelsg' and 'double barrel sg' or names[1]
    end
    local result = {}
    for _, name in ipairs(names) do
        result[name == 'doublebarrelsg' and 'double barrel sg' or name] = true
    end
    return result
end
function phowg:sync_ragebot_weapon_mode()
    Data.ToolSelectionRevision = (Data.ToolSelectionRevision or 0) + 1
    Data.RagebotSelectionCache = nil
    local option = Options.auto_kill_weapon
    if not option then
        return
    end
    local multi = Options.gun_shoot_method
            and Options.gun_shoot_method.Value == 'china hack'
            and not phowg:ragebot_melee_weapon(option.Value)
        or false
    local value = phowg:ragebot_gun_value(option.Value, multi)
    if option.SetMulti then
        option:SetMulti(multi, value)
    else
        option.Multi = multi
    end
    option:SetValue(value, true)
end
function phowg:sync_gun_weapon_choices()
    for _, spec in ipairs({
        { 'kill_aura_weapon', false },
        { 'loadout_weapons', true, { '[Knife]' } },
        { 'skin_selected_weapon', true, { '[Knife]', '[SilencerAR]', '[DrumGun]' } },
    }) do
        local option = Options[spec[1]]
        if option then
            local values = phowg:gun_weapon_choices(spec[2], spec[3])
            local same = #values == #option.Values
            if same then
                for index, value in ipairs(values) do
                    if option.Values[index] ~= value then
                        same = false
                        break
                    end
                end
            end
            if not same then
                local selected = option.Value
                option:SetValues(values)
                option:SetValue(selected)
            end
        end
    end
    if Options.item_weapon and getignoreditemnames then
        Options.item_weapon:SetValues(getignoreditemnames())
    end
end
local function createbodymover(className: string, parent: BasePart)
    local character = LocalPlayer.Character
    if not parent or not parent:IsA('BasePart') or not parent.Parent then
        error('[Phowg] invalid mover parent', 2)
    end
    if character and parent:IsDescendantOf(character) then
        error('[Phowg] refused ' .. className .. ' on local character', 2)
    end
    return Instance.new(className, parent)
end
local function applyflyvelocity(root)
    if not Data['Flying'] or Data['FlyCharacter'] ~= LocalPlayer.Character or not root or not root.Parent then
        return
    end
    local vehicle = Data['FlyVehicle']
    local core = vehicle and vehicle.Part or Data['FlyCore']
    if
        vehicle
        and (
            vehicle.Owner.Parent ~= Workspace:FindFirstChild('Vehicles')
            or vehicle.Owner.Name ~= LocalPlayer.Name
            or not core:IsDescendantOf(Workspace)
        )
    then
        return
    end
    local bodyVelocity = Data['FlyBodyVelocity']
    local bodyGyro = Data['FlyBodyGyro']
    if
        not core
        or (not vehicle and core.Parent ~= Workspace)
        or core:IsDescendantOf(LocalPlayer.Character)
        or not bodyVelocity
        or bodyVelocity.Parent ~= core
        or not bodyGyro
        or bodyGyro.Parent ~= core
    then
        stopfly()
        warn('[Phowg] fly stopped: mover left its workspace Core')
        return
    end
    if Data['Flinging'] then
        if bodyVelocity and bodyVelocity.Parent then
            bodyVelocity.MaxForce = Vector3.zero
        end
        if bodyGyro and bodyGyro.Parent then
            bodyGyro.MaxTorque = Vector3.zero
        end
        return
    end
    local direction = Vector3.zero
    local camera = Workspace.CurrentCamera
    if not UserInputService:GetFocusedTextBox() then
        if camera then
            local cameraCF = camera.CFrame
            if UserInputService:IsKeyDown(Enum.KeyCode.W) then
                direction += cameraCF.LookVector
            end
            if UserInputService:IsKeyDown(Enum.KeyCode.S) then
                direction -= cameraCF.LookVector
            end
            if UserInputService:IsKeyDown(Enum.KeyCode.A) then
                direction -= cameraCF.RightVector
            end
            if UserInputService:IsKeyDown(Enum.KeyCode.D) then
                direction += cameraCF.RightVector
            end
        end
        if UserInputService:IsKeyDown(Enum.KeyCode.Space) then
            direction += Vector3.yAxis
        end
        if UserInputService:IsKeyDown(Enum.KeyCode.LeftControl) then
            direction -= Vector3.yAxis
        end
    end
    local speed = (Options.fly_speed and Options.fly_speed.Value) or 500
    local velocity = direction.Magnitude > 0 and direction.Unit * speed or Vector3.zero
    if math.abs(velocity.Y) < 0.001 then
        Data['FlyIdleAt'] = Data['FlyIdleAt'] or tick()
        local idleY = (tick() - Data['FlyIdleAt']) % 2 < 1 and 0.10 or -0.10
        velocity += Vector3.new(0, idleY, 0)
    else
        Data['FlyIdleAt'] = nil
    end
    Data['FlyVelocity'] = velocity
    if vehicle then
        for force, enabled in pairs(vehicle.NativeForces) do
            if force.Parent ~= core then
                if force.Enabled == false then
                    force.Enabled = enabled
                end
                vehicle.NativeForces[force] = nil
            elseif force.Enabled then
                force.Enabled = false
            end
        end
        root = core
    end
    root.Anchored = false
    root.AssemblyLinearVelocity = Vector3.zero
    root.Velocity = Vector3.zero
    root.AssemblyAngularVelocity = Vector3.zero
    root.RotVelocity = Vector3.zero
    if bodyVelocity and bodyVelocity.Parent then
        bodyVelocity.MaxForce = Vector3.new(9e9, 9e9, 9e9)
        bodyVelocity.Velocity = Vector3.zero
        bodyVelocity.Velocity = velocity
    end
    if bodyGyro and bodyGyro.Parent then
        local serverFacing = not vehicle and Data['CSyncTable'][2] and Data['AppliedServerCF']
        local bodyFlight = not vehicle and ((Options.fly_method and Options.fly_method.Value) or 'body') == 'body'
        local facing = typeof(serverFacing) == 'CFrame' and serverFacing
            or bodyFlight and camera and camera.CFrame
            or Data['FlyFacing']
        if typeof(facing) == 'CFrame' then
            local spin = Data['SpinbotRotation']
            local angle = not serverFacing and spin and spin.Character == Data['FlyCharacter'] and spin.Angle or 0
            local rotation = CFrame.Angles(0, angle or 0, 0) * facing.Rotation
            bodyGyro.CFrame = rotation
            if bodyFlight then
                root.CFrame = CFrame.new(root.Position) * rotation
            end
        end
        bodyGyro.MaxTorque = bodyFlight and Vector3.zero or Vector3.new(9e9, 9e9, 9e9)
    end
    root.AssemblyLinearVelocity = velocity
    root.Velocity = velocity
end
local function isrpgmovementtag(tag: string?, allowReturn: boolean): boolean
    return tag == 'DeflectRPG' or (allowReturn and tag == 'DeflectRPGReturn')
end
local function reloadvoidactive()
    if not isreloading then
        return false
    end
    local supportTarget = Data.SupportHead or Data.CurrentActionTarget or Data.CurrentMainTarget
    local supportMode = supportTarget and Data.PunishmentTargets and Data.PunishmentTargets[supportTarget]
    local support = Data.PunishmentGunActive == true
        and (supportMode == 'knock target' or supportMode == 'stomp target')
    if
        not support
        and not (
            Data.Settings
            and Data.Settings.Hide
            and rageboton
            and rageboton()
            and phowg:ragebot_action_enabled('auto_kill')
        )
    then
        return false
    end
    local pending = phowg.reload_pending and phowg:reload_pending(LocalPlayer.Character)
    if not isreloading() and not pending then
        return false
    end
    if not support then
        return true
    end
    local target = support and supportTarget or Data.CurrentActionTarget
    if support and (isdead(target) or isknocked(target)) then
        return false
    end
    local character = target and target.Parent and target.Character
    local humanoid = character and character:FindFirstChildOfClass('Humanoid')
    return humanoid ~= nil
        and humanoid.Health > 0
        and not (Data['SupportCompletedTargets'] and Data['SupportCompletedTargets'][target])
end
local function idlemovementtag(tag)
    return tag == 'Desync' or tag == 'Underground' or tag == 'Void' or tag == 'VoidTwitch' or tag == 'VoidSpamOut'
end
function movementblocked(prio, tag)
    for key, entry in pairs(Data['MovementOverrides'] or {}) do
        if entry.character ~= LocalPlayer.Character or tick() >= entry.expires then
            Data['MovementOverrides'][key] = nil
        elseif entry.prio < prio then
            return true
        end
    end
    if idlemovementtag(tag) then
        for _, hold in pairs(Data['MoveToHolds'] or {}) do
            if not hold.Stopped and hold.Character == LocalPlayer.Character and hold.Priority < prio then
                return true
            end
        end
    end
    return false
end
function claimmovement(prio, tag)
    if idlemovementtag(tag) then
        return
    end
    Data['MovementOverrides'] = Data['MovementOverrides'] or {}
    Data['MovementOverrides'][tag or 'MoveTo'] =
        { character = LocalPlayer.Character, expires = tick() + 0.15, prio = prio, tag = tag }
    for index = #Data['CSync'].Queue, 1, -1 do
        local entry = Data['CSync'].Queue[index]
        if idlemovementtag(entry.tag) or (entry.prio > prio and entry.tag ~= tag) then
            table.remove(Data['CSync'].Queue, index)
        end
    end
end
function releasemovement(tag)
    if Data['MovementOverrides'] then
        Data['MovementOverrides'][tag] = nil
    end
    for index = #Data['CSync'].Queue, 1, -1 do
        if Data['CSync'].Queue[index].tag == tag then
            table.remove(Data['CSync'].Queue, index)
        end
    end
    if phowg.cancel_c_frame_movement and Data.AppliedServerTag == tag then
        phowg:cancel_c_frame_movement({ [tag] = true })
    end
end
function stopmovetohold(name)
    local hold = Data['MoveToHolds'] and Data['MoveToHolds'][name]
    if not hold then
        return
    end
    hold.Stopped = true
    Data['MoveToHolds'][name] = nil
    if Data['MovementOverrides'] then
        Data['MovementOverrides'][hold.Tag] = nil
    end
    for index = #Data['CSync'].Queue, 1, -1 do
        if Data['CSync'].Queue[index].hold == hold then
            table.remove(Data['CSync'].Queue, index)
        end
    end
    if Data['AppliedServerHold'] == hold and phowg.cancel_c_frame_movement then
        phowg:cancel_c_frame_movement({ [hold.Tag] = true })
    end
end
function startmovetohold(name, cf, prio, valid, arrive)
    stopmovetohold(name)
    Data['MoveToHolds'] = Data['MoveToHolds'] or {}
    local hold = {
        Name = name,
        CFrame = cf,
        Priority = prio or 79,
        Tag = 'Hold:' .. name,
        Character = LocalPlayer.Character,
        Valid = valid,
        Arrive = arrive,
        Stopped = false,
    }
    function hold:Stop()
        if Data['MoveToHolds'][self.Name] == self then
            stopmovetohold(self.Name)
        else
            self.Stopped = true
        end
    end
    function hold:Update(position)
        if not self.Stopped then
            self.CFrame = position
        end
    end
    Data['MoveToHolds'][name] = hold
    return hold
end
local function validmovetohold(hold)
    return not hold
        or (
            not hold.Stopped
            and Data['MoveToHolds']
            and Data['MoveToHolds'][hold.Name] == hold
            and hold.Character == LocalPlayer.Character
            and (not hold.Valid or hold.Valid())
        )
end
function movetoholdtick()
    local best
    for name, hold in pairs(Data['MoveToHolds'] or {}) do
        if not validmovetohold(hold) then
            stopmovetohold(name)
        elseif not movementblocked(hold.Priority, hold.Tag) and (not best or hold.Priority < best.Priority) then
            best = hold
        end
    end
    if best and not localactionblocked() and not Data['IsRespawning'] and not Data['Buying'] then
        set_server_cframe(best.CFrame, nil, best.Priority, best.Tag, false, best, best.Arrive)
    end
end
do
    local connection
    local running = false
    local active
    -- tiny idle Y stir so the server still sees movement while set_server_cframe
    -- holds us in place; kept deliberately small so it does not visibly bob
    local fakeMovementSpeed = 0.02
    local function movementbody()
        if Library.Unloaded or Data.SafeMode or localactionblocked() then
            return
        end
        local character = LocalPlayer.Character
        local root = character and character:FindFirstChild('HumanoidRootPart')
        local humanoid = character and character:FindFirstChildOfClass('Humanoid')
        local torso = character
            and (
                character:FindFirstChild('UpperTorso')
                or character:FindFirstChild('Torso')
                or character:FindFirstChild('LowerTorso')
            )
        if
            not character
            or not character.Parent
            or not root
            or not root:IsA('BasePart')
            or root.Parent ~= character
            or not torso
            or not torso:IsA('BasePart')
            or not humanoid
            or not (humanoid.Health >= 1)
        then
            return
        end
        return character, root
    end
    local function finitevector(value)
        return value.X == value.X and value.Y == value.Y and value.Z == value.Z and value.Magnitude < math.huge
    end
    local function finitecframe(value)
        return finitevector(value.Position)
            and finitevector(value.RightVector)
            and finitevector(value.UpVector)
            and finitevector(value.LookVector)
    end
    local function idle_movement_eligible(character, root, humanoid)
        if Data.Flying or not humanoid or humanoid.Sit or humanoid.Jump or humanoid.MoveDirection.Magnitude >= 0.01 then
            return false
        end
        if not root or root.Parent ~= character then
            return false
        end
        local velocity = root.AssemblyLinearVelocity
        local state = humanoid:GetState()
        return math.abs(velocity.Y) < 1.5
            and Vector3.new(velocity.X, 0, velocity.Z).Magnitude < 0.5
            and state ~= Enum.HumanoidStateType.Jumping
            and state ~= Enum.HumanoidStateType.Freefall
            and state ~= Enum.HumanoidStateType.FallingDown
            and state ~= Enum.HumanoidStateType.Seated
    end
    local function finishmovement(restored)
        local state = active
        active = nil
        if not restored and Data.ServerMovementVelocity and Data.ServerMovementVelocity.Parent then
            Data.ServerMovementVelocity.MaxForce = Vector3.zero
        end
        Data.CSyncTable[2] = false
        Data.MoveToInFlight = nil
        if state then
            if
                state.ArrivalThread
                and state.ArrivalThread ~= coroutine.running()
                and coroutine.status(state.ArrivalThread) ~= 'dead'
            then
                pcall(task.cancel, state.ArrivalThread)
            end
            local root = state.Root
            if root.Parent == state.Character and LocalPlayer.Character == state.Character then
                if not restored then
                    root.CFrame = state.Original
                    Data.CSyncTable[1] = state.Original
                end
                if state.Velocity and not restored and not Data.Flying then
                    local humanoid = state.Character:FindFirstChildOfClass('Humanoid')
                    if idle_movement_eligible(state.Character, root, humanoid) then
                        root.AssemblyLinearVelocity = state.Velocity
                    end
                end
                if state.Anchored and not Data.Flying then
