            Data.ServerMovementInputConnection = nil
        end
        if Data.ServerMovementCore then
            Data.ServerMovementCore:Destroy()
            Data.ServerMovementCore = nil
        end
        Data.ServerMovementVelocity, Data.ServerMovementRoot = nil, nil
        if phowg.set_c_frame_hook then
            phowg:set_c_frame_hook(false)
        end
