    local function execute(entry)
        local TargetCFrame, prio, tag = entry.cf, entry.prio, entry.tag
        local char, Hold, OnArrive = entry.character, entry.hold, entry.arrive
        local savingSession = entry.savingSession
        if tag == 'Saving' and (not savingSession or not phowg:auto_save_session_valid(savingSession)) then
            return
        end
        local stompTarget, stompCharacter = entry.stompTarget, entry.stompCharacter
        local voidExitRevision, purchaseBatch = entry.voidExitRevision, entry.purchaseBatch
        local purchaseVoidReturn, idleState = entry.purchaseVoidReturn, entry.idleState
        local voidSpamState, voidSpamRevision = entry.voidSpamState, entry.voidSpamRevision
        local voidReturnRevision, supportBuyTarget = entry.voidReturnRevision, entry.supportBuyTarget
        local arrivalTarget, arrivalCharacter, arrivalTool =
            entry.arrivalTarget, entry.arrivalCharacter, entry.arrivalTool
        if
            tag == 'VoidExit' and (voidExitRevision ~= Data.VoidExitRevision or Data.VoidActive or reloadvoidactive())
        then
            return
        end
        if
            Data.RagebotIdle
            and (tag == 'Combat' or tag == 'TargetStrafe' or tag == 'RagebotVoidReturn' or tag == 'VoidExit')
        then
            return
        end
        if tag == 'RagebotIdle' and not phowg:ragebot_idle_hiding(idleState) then
            return
        end
        if tag == 'VoidSpamOut' and not phowg:void_spam_out_active() then
            return
        end
        if tag == 'Buy' and not Data.Buying then
            return
        end
        if
            purchaseBatch
            and (
                Data.PurchaseBatch ~= purchaseBatch
                or purchaseBatch.Done
                or purchaseBatch.Cancelled
                or Data.BuyTargetCF ~= TargetCFrame
            )
        then
            return
        end
        if tag == 'PurchaseVoidReturn' and not phowg:purchase_void_return_valid(purchaseVoidReturn) then
            return
        end
        if
            tag == 'RagebotVoid'
            and (not phowg:ragebot_void_move_valid(voidSpamState) or voidSpamState.Revision ~= voidSpamRevision)
        then
            return
        end
        if
            tag == 'RagebotVoidReturn'
            and (
                voidReturnRevision ~= Data.RagebotVoidExitRevision
                or Data.VoidActive
                or reloadvoidactive()
                or phowg:ragebot_void_move_valid(Data.RagebotVoidSpam)
            )
        then
            return
        end
        if not validmovetohold(Hold) or movementblocked(prio, tag) then
            return
        end
        if
            tag == 'KillAura'
            and (
                not arrivalTarget
                or Data['KillAuraTarget'] ~= arrivalTarget
                or arrivalTarget.Character ~= arrivalCharacter
                or not (Toggles.full_rage and Toggles.full_rage.Value)
                or not killauraenabled()
                or not killauravalidtarget(arrivalTarget)
            )
        then
            return
        end
        if tag == 'ReloadVoid' and not reloadvoidactive() then
            return
        end
        if tag == 'Desync' and not Data['DesyncActive'] then
            return
        end
        if tag == 'Underground' and not Data['UndergroundActive'] then
            return
        end
        if (tag == 'Void' or tag == 'VoidTwitch') and not Data['VoidActive'] then
            return
        end
        if
            tag == 'Combat'
            and arrivalTarget
            and Data['SupportCompletedTargets']
            and Data['SupportCompletedTargets'][arrivalTarget]
        then
            return
        end
        if
            tag == 'Combat'
            and arrivalTarget
            and (
                Data.CurrentActionTarget ~= arrivalTarget
                or arrivalTarget.Character ~= arrivalCharacter
                or isknocked(arrivalTarget)
                or isdead(arrivalTarget)
            )
        then
            return
        end
        if tag == 'Combat' and phowg.support_armor_blocked and phowg:support_armor_blocked(arrivalTarget) then
            return
        end
        if
            tag == 'Stomp'
            and (
                not stompTarget
                or Data.CurrentActionTarget ~= stompTarget
                or stompTarget.Character ~= stompCharacter
                or not isvalidstomptarget(stompTarget)
            )
        then
            return
        end
        if supportBuyTarget and not (Data['PunishmentTargets'] and Data['PunishmentTargets'][supportBuyTarget]) then
            return
        end
        if Data['RPGUnloading'] and isrpgmovementtag(tag, true) then
            return
        end
        if tag == 'DeflectRPG' and not Data['RPGMoveActive'] then
            return
        end
        if Data['RPGMoveActive'] and not isrpgmovementtag(tag, true) then
            return
        end
        if tag == 'Combat' and reloadvoidactive() then
            set_server_cframe(getvoidcframe(), nil, Data['PRIO'].PUNISH, 'ReloadVoid')
            return
        end
        local execChar, Root = movementbody()
        if execChar ~= char or Root ~= entry.root then
            return
        end
        local clientCF = savingSession and phowg:auto_save_client_frame(savingSession) or Root.CFrame
        if phowg.set_c_frame_hook then
            phowg:set_c_frame_hook(true)
        end
        Data.CSyncTable[1], Data.CSyncTable[2] = clientCF, true
        local wasAnchored = Root.Anchored
        if wasAnchored then
            Root.Anchored = false
        end
        local moveRevision = Data.CFrameMoveRevision or 0
        local startedAt = tick()
        Data['MoveToInFlight'] = Root
        Data['AppliedServerCF'] = TargetCFrame
        Data['AppliedServerHold'] = Hold
        Data['AppliedServerAt'] = tick()
        Data['AppliedServerTag'] = tag
        Data['AppliedServerCharacter'] = execChar
        active = { Root = Root, Character = execChar, Original = clientCF, Anchored = wasAnchored }
        if
            Toggles.server_position_indicator
            and Toggles.server_position_indicator.Value
            and serverpositionindicatortick
        then
            local ok, err = pcall(serverpositionindicatortick, 0)
            if not ok and tick() >= (Data.ServerIndicatorErrorAt or 0) then
                Data.ServerIndicatorErrorAt = tick() + 5
                warn('[Phowg] server indicator: ' .. tostring(err))
            end
        end
        if Toggles.local_desynced_position and Toggles.local_desynced_position.Value then
            local ok, err = pcall(syncvisualizer, TargetCFrame, Data['CSyncTable'][1])
            if not ok and (not Data['VisualizerErrorAt'] or tick() - Data['VisualizerErrorAt'] >= 5) then
                Data['VisualizerErrorAt'] = tick()
                warn('[Phowg] visualizer: ' .. tostring(err))
            end
        end
        local moveOK, moveError = pcall(function()
            local currentCharacter, currentRoot = movementbody()
            if currentCharacter ~= execChar or currentRoot ~= Root then
                return
            end
            local humanoid = execChar:FindFirstChildOfClass('Humanoid')
            local velocity = Root.AssemblyLinearVelocity
            if idle_movement_eligible(execChar, Root, humanoid) and phowg.create_fly_core then
                if
                    Data.ServerMovementRoot ~= Root
                    or not Data.ServerMovementCore
                    or Data.ServerMovementCore.Parent ~= Workspace
                then
                    if Data.ServerMovementInputConnection then
                        Data.ServerMovementInputConnection:Disconnect()
                    end
                    if Data.ServerMovementCore then
                        Data.ServerMovementCore:Destroy()
                    end
                    local core = phowg.create_fly_core(Root)
                    Data.ServerMovementCore, Data.ServerMovementRoot = core, Root
                    local mover = createbodymover('BodyVelocity', core)
                    mover.Name, mover.P, mover.MaxForce = 'PhowgServerMovementVelocity', 100000, Vector3.zero
                    Data.ServerMovementVelocity = mover
                    Data.ServerMovementInputConnection = phowg.connect_shared(
                        humanoid:GetPropertyChangedSignal('MoveDirection'),
                        function()
                            if humanoid.MoveDirection.Magnitude >= 0.01 and mover.Parent then
                                mover.MaxForce = Vector3.zero
                            end
                        end,
                        humanoid,
                        'server movement input',
                        0,
                        'property/MoveDirection',
                        humanoid
                    )
                end
                local mover = Data.ServerMovementVelocity
                local direction = math.floor(tick() * 5) % 2 == 0 and fakeMovementSpeed or -fakeMovementSpeed
                active.Velocity = velocity
                mover.Velocity = Vector3.new(0, direction, 0)
                mover.MaxForce = Vector3.new(0, 9e9, 0)
            elseif Data.ServerMovementVelocity and Data.ServerMovementVelocity.Parent then
                Data.ServerMovementVelocity.MaxForce = Vector3.zero
            end
            Root.CFrame = TargetCFrame
            local spam = Data.RagebotVoidSpam
            if
                tag == 'Combat'
                and spam
                and not spam.Void
                and spam.Character == execChar
                and spam.Target == Data.CurrentActionTarget
            then
                spam.StrafeCFrame, spam.StrafeAt = TargetCFrame, tick()
            end
            if OnArrive and validmovetohold(Hold) then
                local function arrive()
                    if
                        Data.MoveToInFlight ~= Root
                        or moveRevision ~= (Data.CFrameMoveRevision or 0)
                        or movementbody() ~= execChar
                        or not validmovetohold(Hold)
                    then
                        return
                    end
                    local arrivedOK, arrivedError = pcall(OnArrive, Root)
                    if not arrivedOK and tick() - (Data['MoveToArriveErrorAt'] or -math.huge) >= 5 then
                        Data['MoveToArriveErrorAt'] = tick()
                        warn('[Phowg] set_server_cframe callback: ' .. tostring(arrivedError))
                    end
                end
                if tag == 'Stomp' then
                    arrive()
                else
                    local state = active
                    local thread = task.spawn(arrive)
                    if active == state then
                        state.ArrivalThread = thread
                    end
                end
            end
            if moveRevision ~= (Data.CFrameMoveRevision or 0) then
                return
            end
            if Data['Flying'] then
                applyflyvelocity(Root)
            end
            local combatArrivalValid = false
            if
                arrivalTarget
                and arrivalTarget.Character == arrivalCharacter
                and arrivalTool
                and arrivalTool.Parent == execChar
            then
                local targetRoot = arrivalCharacter and arrivalCharacter:FindFirstChild('HumanoidRootPart')
                local arrivalMode = Options.target_strafe_mode and Options.target_strafe_mode.Value
                local arrivalRadius = arrivalMode == 'chinese' and select(2, phowg:chinese_strafe_band(arrivalTool))
                    or arrivalMode == 'orbit' and 45
                    or 52
                arrivalRadius = arrivalRadius or 52
                if targetRoot then
                    arrivalRadius = math.max(
                        arrivalRadius,
                        (predpos(targetRoot.Position, arrivalCharacter, 2.5, nil, true) - targetRoot.Position).Magnitude
                            + 52
                    )
                end
                if
                    targetRoot
                    and (Root.Position - targetRoot.Position).Magnitude <= arrivalRadius
                    and not isreloading()
                then
                    combatArrivalValid = true
                    local now = tick()
                    if
                        Data['CombatArrivalTarget'] ~= arrivalTarget
                        or Data['CombatArrivalCharacter'] ~= arrivalCharacter
                        or Data['CombatArrivalTool'] ~= arrivalTool
                        or now - (Data['CombatArrivalLastAt'] or 0) > 0.3
                    then
                        Data['CombatArrivalAt'] = now
                    end
                    Data['CombatArrivalTarget'] = arrivalTarget
                    Data['CombatArrivalCharacter'] = arrivalCharacter
                    Data['CombatArrivalTool'] = arrivalTool
                    Data['CombatArrivalLastAt'] = now
                end
            end
            if not combatArrivalValid then
                Data['CombatArrivalAt'] = nil
                Data['CombatArrivalLastAt'] = nil
                Data['CombatArrivalTarget'] = nil
                Data['CombatArrivalCharacter'] = nil
                Data['CombatArrivalTool'] = nil
            end
            RunService.RenderStepped:Wait()
        end)
        if moveRevision ~= (Data.CFrameMoveRevision or 0) then
            if wasAnchored and Root.Parent and Data.MoveToInFlight ~= Root and not Data.Flying then
                Root.Anchored = true
            end
            return
        end
        if Root.Parent == execChar and LocalPlayer.Character == execChar then
            local restoreCF = clientCF
            if moveOK and Data['Flying'] and TargetCFrame.Position.Magnitude < 100000 then
                local displacement = Root.Position - TargetCFrame.Position
                if tag == 'Saving' then
                    local velocity = Data.FlyVelocity
                    displacement = typeof(velocity) == 'Vector3'
                            and finitevector(velocity)
                            and velocity * math.clamp(tick() - startedAt, 0, 0.25)
                        or Vector3.zero
                end
                local speed = (Options.fly_speed and Options.fly_speed.Value) or 500
                local maxDisplacement = speed * math.clamp(tick() - startedAt, 1 / 60, 0.25) * 2 + 4
                if
                    displacement.X == displacement.X
                    and displacement.Y == displacement.Y
                    and displacement.Z == displacement.Z
                    and displacement.Magnitude <= maxDisplacement
                then
                    restoreCF = CFrame.new(clientCF.Position + displacement) * clientCF.Rotation
                end
            end
            Root.CFrame = restoreCF
            Data['CSyncTable'][1] = restoreCF
            if savingSession and Data.AutoSaveSession == savingSession then
                savingSession.ClientCFrame, savingSession.ClientFrameAt = restoreCF, tick()
            end
        end
        finishmovement(true)
        if not moveOK and (not Data['MoveToErrorAt'] or tick() - Data['MoveToErrorAt'] >= 5) then
            Data['MoveToErrorAt'] = tick()
            warn('[Phowg] set_server_cframe: ' .. tostring(moveError))
        end
        if Data['IsRespawning'] or not Root.Parent or LocalPlayer.Character ~= execChar then
            Data['CSyncTable'][2] = false
            Data['MoveToActive'] = false
            Data['MoveToTargetCF'] = nil
            hidevisualizer()
            return
        end
        if Data['Flying'] and movementbody() == execChar then
            applyflyvelocity(Root)
        end
        if wasAnchored and Root.Parent and not Data['Flying'] then
            Root.Anchored = true
        end
    end
    local function step()
        local mover, root = Data.ServerMovementVelocity, Data.ServerMovementRoot
        if mover and mover.Parent and mover.MaxForce ~= Vector3.zero then
            local character = LocalPlayer.Character
            local humanoid = character and character:FindFirstChildOfClass('Humanoid')
            if not idle_movement_eligible(character, root, humanoid) then
                mover.MaxForce = Vector3.zero
            else
                mover.Velocity =
                    Vector3.new(0, math.floor(tick() * 5) % 2 == 0 and fakeMovementSpeed or -fakeMovementSpeed, 0)
            end
        end
        if running then
            return
        end
        if not movementbody() then
            phowg:cancel_c_frame_movement()
            return
        end
        local queue = Data.CSync.Queue
        local best
        local now = tick()
        for index = #queue, 1, -1 do
            local entry = queue[index]
            if entry.character ~= LocalPlayer.Character or now - entry.t > 0.3 then
                table.remove(queue, index)
            elseif not best or entry.prio < best.prio or (entry.prio == best.prio and entry.t < best.t) then
                best = entry
            end
        end
        if not best then
            if now - (Data.MoveToLastAt or 0) >= 0.06 then
                Data.MoveToActive, Data.MoveToTargetCF = false, nil
                stopworker()
                syncvisualizer()
            end
            return
        end
        for index, entry in ipairs(queue) do
            if entry == best then
                table.remove(queue, index)
                break
            end
        end
        running = true
        local ok, err = pcall(execute, best)
        if not ok then
            finishmovement()
            if now >= (Data.ServerCFrameErrorAt or 0) then
                Data.ServerCFrameErrorAt = now + 5
                warn('[Phowg] set_server_cframe: ' .. tostring(err))
            end
        end
        running = false
    end
    local function ensureworker()
        if connection then
            return
        end
        connection = RunService.Heartbeat:Connect(step)
        Data.ServerCFrameConnection = connection
    end
    set_server_cframe = LPH_NO_VIRTUALIZE(
        function(PositionOrCFrame, LookAtPosition, Prio, Tag, _IsReplay, Hold, OnArrive)
            local char, root = movementbody()
            if not char then
                return
            end
            if not PositionOrCFrame then
                return
            end
            local TargetCFrame
            if typeof(PositionOrCFrame) == 'Vector3' then
                if LookAtPosition and typeof(LookAtPosition) == 'Vector3' then
                    TargetCFrame = CFrame.new(PositionOrCFrame, LookAtPosition)
                else
                    TargetCFrame = CFrame.new(PositionOrCFrame)
                end
            elseif typeof(PositionOrCFrame) == 'CFrame' then
                TargetCFrame = PositionOrCFrame
            else
                return false
            end
            if not finitecframe(TargetCFrame) then
                return false
            end
            local prio = typeof(Prio) == 'number' and Prio or Data['PRIO'].IDLE
            if prio ~= prio or math.abs(prio) == math.huge then
                return false
            end
            local tag: string? = typeof(Tag) == 'string' and Tag or nil
            if tag == 'VoidSpamOut' and not phowg:void_spam_out_active() then
                return false
            end
            local stompTarget = tag == 'Stomp' and Data.CurrentActionTarget or nil
            local stompCharacter = stompTarget and stompTarget.Character
            local voidExitRevision = tag == 'VoidExit' and Data.VoidExitRevision
            if tag == 'VoidExit' and (Data.VoidActive or reloadvoidactive()) then
                return
            end
            local purchaseBatch = tag == 'Buy' and Data.PurchaseBatch or nil
            if tag == 'Buy' and not Data.Buying then
                return
            end
            local purchaseVoidReturn = tag == 'PurchaseVoidReturn' and Data.PurchaseVoidReturn or nil
            if tag == 'PurchaseVoidReturn' and not phowg:purchase_void_return_valid(purchaseVoidReturn) then
                return
            end
            if
                Data.RagebotIdle
                and (tag == 'Combat' or tag == 'TargetStrafe' or tag == 'RagebotVoidReturn' or tag == 'VoidExit')
            then
                return
            end
            local idleState = tag == 'RagebotIdle' and Data.RagebotIdle
            if tag == 'RagebotIdle' and not phowg:ragebot_idle_hiding(idleState) then
                return
            end
            local voidSpamState = tag == 'RagebotVoid' and Data.RagebotVoidSpam or nil
            local voidSpamRevision = voidSpamState and voidSpamState.Revision
            local voidReturnRevision = tag == 'RagebotVoidReturn' and Data.RagebotVoidExitRevision
            if
                tag == 'RagebotVoidReturn'
                and (
                    voidReturnRevision ~= Data.RagebotVoidExitRevision
                    or Data.VoidActive
                    or reloadvoidactive()
                    or phowg:ragebot_void_move_valid(Data.RagebotVoidSpam)
                )
            then
                return
            end
            if
                tag == 'RagebotVoid'
                and (not phowg:ragebot_void_move_valid(voidSpamState) or voidSpamState.Revision ~= voidSpamRevision)
            then
                return
            end
            if tag == 'Combat' and phowg.support_armor_blocked and phowg:support_armor_blocked(Data.CurrentActionTarget) then
                return
            end
            if not validmovetohold(Hold) or movementblocked(prio, tag) then
                return
            end
            if tag == 'ReloadVoid' and not reloadvoidactive() then
                return
            end
            local supportBuyTarget = tag == 'Buy' and Data['BuyingSupportTarget'] or nil
            if
                Options
                and Options.void_mode
                and Options.void_mode.Value == 'anti matrix'
                and (
                    tag == 'Void'
                    or tag == 'VoidTwitch'
                    or tag == 'ReloadVoid'
                    or TargetCFrame.Position == VoidCFrame.Position
                )
            then
                TargetCFrame = AntiMatrixCFrame
            end
            if Data['RPGMoveActive'] and not isrpgmovementtag(tag, true) then
                return
            end
            local arrivalTarget = tag == 'Combat' and Data['CurrentActionTarget']
                or tag == 'KillAura' and Data['KillAuraTarget']
                or nil
            local arrivalCharacter = arrivalTarget and arrivalTarget.Character
            local arrivalTool = char:FindFirstChildOfClass('Tool')
            claimmovement(prio, tag)
            local now = tick()
            Data['LastMoveToAt'] = now
            Data['LastServerCF'] = TargetCFrame
            Data['MoveToTargetCF'] = TargetCFrame
            Data['MoveToActive'] = true
            Data['MoveToLastAt'] = now
            Data['DisplayCF'] = TargetCFrame
            Data['DisplayAt'] = now
            if
                tag == 'Combat'
                or tag == 'Saving'
                or prio == Data['PRIO'].PUNISH
                or prio == Data['PRIO'].SAVING
                or prio == Data['PRIO'].STOMP
                or prio == Data['PRIO'].KNIFE
                or prio == Data['PRIO'].ARREST
            then
                Data['LastCombatMoveAt'] = now
            end
            local queue = Data.CSync.Queue
            local entry
            for _, pending in ipairs(queue) do
                if pending.tag == tag then
                    entry = pending
                    break
                end
            end
            if not entry then
                entry = {}
                queue[#queue + 1] = entry
            end
            entry.cf, entry.prio, entry.tag, entry.t = TargetCFrame, prio, tag, now
            entry.hold, entry.arrive, entry.character, entry.root = Hold, OnArrive, char, root
            entry.savingSession = tag == 'Saving' and Data.AutoSaveSession or nil
            entry.stompTarget, entry.stompCharacter = stompTarget, stompCharacter
            entry.voidExitRevision, entry.purchaseBatch = voidExitRevision, purchaseBatch
            entry.purchaseVoidReturn, entry.idleState = purchaseVoidReturn, idleState
            entry.voidSpamState, entry.voidSpamRevision = voidSpamState, voidSpamRevision
            entry.voidReturnRevision, entry.supportBuyTarget = voidReturnRevision, supportBuyTarget
            entry.arrivalTarget, entry.arrivalCharacter, entry.arrivalTool =
                arrivalTarget, arrivalCharacter, arrivalTool
            ensureworker()
            return true
        end
    )
    local hookedcframe
    local cframeHookInstalled = false
    local cframeHook
    function phowg:set_c_frame_hook(enabled)
        if enabled then
            if cframeHookInstalled or Library.Unloaded then
                return
            end
            hookedcframe = hookmm(game, '__index', cframeHook)
            cframeHookInstalled = true
        elseif cframeHookInstalled then
            hookmm(game, '__index', hookedcframe)
            cframeHookInstalled = false
        end
    end
    function phowg:cancel_c_frame_movement(tags)
        for index = #Data.CSync.Queue, 1, -1 do
            if not tags or tags[Data.CSync.Queue[index].tag] then
                table.remove(Data.CSync.Queue, index)
            end
        end
        local tag = Data.AppliedServerTag
        if tags and tag and not tags[tag] then
            if not active and #Data.CSync.Queue == 0 then
                stopworker()
            end
            return false
        end
        Data.CFrameMoveRevision = (Data.CFrameMoveRevision or 0) + 1
        finishmovement()
        Data.AppliedServerCF, Data.AppliedServerTag, Data.AppliedServerCharacter = nil, nil, nil
        Data.AppliedServerAt, Data.AppliedServerHold = nil, nil
        Data.MoveToActive, Data.MoveToTargetCF, Data.DisplayCF = false, nil, nil
        if #Data.CSync.Queue == 0 or Library.Unloaded then
            stopworker()
        end
        return true
    end

    cframeHook = LPH_NO_VIRTUALIZE(function(Self, Key)
        if Key ~= 'CFrame' or not Data.CSyncTable[2] or Data.IsRespawning or checkcall() then
            return hookedcframe(Self, Key)
        end
        local character = LocalPlayer and LocalPlayer.Character
        if not character then
            return hookedcframe(Self, Key)
        end
        local callerMethod = getnamecallmethod and getnamecallmethod()
        local root = Local_Parts.Character == character and Local_Parts.Root
        if not root or root.Parent ~= character then
            root = character:FindFirstChild('HumanoidRootPart')
        end
        if Self == root then
            local humanoid = Local_Parts.Character == character and Local_Parts.Humanoid
            if not humanoid or humanoid.Parent ~= character then
                humanoid = character:FindFirstChildOfClass('Humanoid')
            end
            local stash = Data.CSyncTable[1]
            if humanoid and humanoid.Health > 0 and typeof(stash) == 'CFrame' then
                if stash.Position.Magnitude < 10000 then
                    Local_Data.ClientPos = stash
                    getgenv().PhowgClientPos = stash
                end
                if callerMethod and setnamecallmethod and getnamecallmethod() ~= callerMethod then
                    pcall(setnamecallmethod, callerMethod)
                end
                return stash
            end
        end
        if callerMethod and setnamecallmethod and getnamecallmethod() ~= callerMethod then
            pcall(setnamecallmethod, callerMethod)
        end
        return hookedcframe(Self, Key)
    end)
end

Data['money'] = 0
Data['lastStompRemoteTick'] = 0
Data['StompNotifyAt'] = Data['StompNotifyAt'] or {}
Data['StompWatch'] = Data['StompWatch'] or {}
Data['ArrestWatch'] = Data['ArrestWatch'] or {}
Data['DefaultWindowTitle'] = 'phowg host'
Data['Window'] = Library:CreateWindow({
    Title = Data['DefaultWindowTitle'],
    Center = false,
    AutoShow = true,
    Size = UDim2.fromOffset(560, 650),
})
local AnimPlayerNames = {}
Data.StartupTiming = StartupTiming
Data.SharedSignals = {}
Data.SharedSignalCounts = { Signals = 0, Handlers = 0, Workers = 0 }
Data.RetiredScopes = setmetatable({}, { __mode = 'k' })
Data.CleanupRegistry = {}
Data.Performance = { Enabled = false, Samples = {}, Frames = 0, Seconds = 0, Spikes = 0, MaxFrame = 0 }
Data.HeartbeatJobs = {}
Data.HeartbeatOrder = {}
Data.InformationHz = 10
Data.PreviewHz = 30
Data.VisualLeases = {}
Data.VisualUsage = 0
Data.CosmeticQuality = 1
function phowg:visual_number(name, fallback, minimum, maximum)
    local value = tonumber(Options[name] and Options[name].Value)
    if not value or value ~= value or math.abs(value) == math.huge then
        return fallback
    end
    return math.clamp(value, minimum, maximum)
end
function phowg:acquire_visual(owner, cost, kind)
    cost = math.max(0, math.ceil(cost))
    local previous = Data.VisualLeases[owner]
    local budget = phowg:visual_number('cosmetic_budget', 2000, 100, 10000)
    if Data.VisualUsage - (previous and previous.Cost or 0) + cost > budget then
        return false
    end
    Data.VisualUsage = Data.VisualUsage - (previous and previous.Cost or 0) + cost
    if previous then
        previous.Cost, previous.Kind = cost, kind
    else
        Data.VisualLeases[owner] = { Cost = cost, Kind = kind }
    end
    return true
end
function phowg:release_visual(owner)
    local previous = Data.VisualLeases[owner]
    if previous then
        Data.VisualUsage = math.max(0, Data.VisualUsage - previous.Cost)
        Data.VisualLeases[owner] = nil
    end
end
function phowg:cosmetic_visible(position)
    if typeof(position) ~= 'Vector3' then
        return false
    end
    local camera = Workspace.CurrentCamera
    if not camera then
        return false
    end
    return (position - camera.CFrame.Position).Magnitude <= phowg:visual_number('cosmetic_distance', 1000, 100, 5000)
end
function phowg:apply_visual_preset(name)
    if Library and Library.ConfigLoading then
        return
    end
    local presets = {
        low = {
            bullet_visual_rate = 30,
            cosmetic_quality = 35,
            cosmetic_budget = 600,
            cosmetic_distance = 600,
            shot_effect_rate = 12,
            shot_sound_rate = 12,
            shot_sound_voices = 2,
            prediction_preview_rate = 15,
        },
        balanced = {
            bullet_visual_rate = 60,
            cosmetic_quality = 75,
            cosmetic_budget = 2000,
            cosmetic_distance = 1000,
            shot_effect_rate = 20,
            shot_sound_rate = 20,
            shot_sound_voices = 4,
            prediction_preview_rate = 30,
        },
        high = {
            bullet_visual_rate = 90,
            cosmetic_quality = 100,
            cosmetic_budget = 3000,
