function phowg:cleanup_scope(scope, reason)
    if not scope and Data.CleanupFinished then
        return
    end
    if scope and Data.RetiredScopes[scope] then
        return
    end
    if scope then
        Data.RetiredScopes[scope] = true
    else
        Data.SharedSignalsClosed = true
    end
    for _, record in pairs(Data.SharedSignals) do
        for _, entry in ipairs(record.Snapshot or table.clone(record.List)) do
            if not scope or (entry.Ancestors and entry.Ancestors[scope]) or phowg:scope_contains(scope, entry.Owner) then
                entry:Disconnect()
            end
            if scope then
                for thread, threadScope in pairs(entry.Threads) do
                    if phowg:scope_contains(scope, threadScope) then
                        if thread ~= coroutine.running() then
                            pcall(task.cancel, thread)
                        end
                        entry.Threads[thread] = nil
                        if not entry.Frame then
                            Data.SharedSignalCounts.Workers -= 1
                        end
                    end
                end
            end
        end
    end
