        loops = 10,
        ['heartbeat jobs'] = 10,
        ['visual render jobs'] = 10,
        ['background work'] = 10,
        ['protection checks'] = 10,
        ['server cframe'] = 20,
        ['esp runtime'] = 40,
        ['legacy visuals'] = 95,
        ['runtime exports'] = 100,
        ['character state'] = 30,
        ['avatar cache'] = 80,
        ['visual budget'] = 90,
    }
    local ordered = table.clone(Data.CleanupOrder or {})
    local sequence = {}
    for index, name in ipairs(ordered) do
        sequence[name] = index
    end
    table.sort(ordered, function(a, b)
        local left, right = phases[a] or 50, phases[b] or 50
        return left < right or left == right and sequence[a] < sequence[b]
    end)
    for _, name in ipairs(ordered) do
        local callback = Data.CleanupRegistry[name]
        local ok, err = pcall(callback, scope, reason)
