        end
    end
    if not scope then
        Data.CleanupFinished = true
        Data.SharedSignalSweep, Data.SharedSignalChannels = nil, nil
        if getgenv().PhowgSharedConnect == connectshared then
            getgenv().PhowgSharedConnect = nil
        end
    end
end
