    for _, name in ipairs(Data.HeartbeatOrder) do
        local job = Data.HeartbeatJobs[name]
        local enabled = job.Enabled == nil or job.Enabled() == true
        if not enabled and job.Active == false then
            continue
        end
        if job.Active ~= enabled and not job.Running then
            job.First, job.Elapsed = true, 0
        end
        local interval = job.Interval
        if interval == 'information' then
            interval = 1 / Data.InformationHz
        elseif interval == 'preview' then
            interval = 1 / Data.PreviewHz
        end
        job.Elapsed += delta
        if not job.Running and (job.First or interval == 0 or job.Elapsed >= interval) then
            local elapsed = job.Elapsed
            job.Elapsed = interval > 0 and job.Elapsed % interval or 0
            job.First = false
            job.Active = enabled
            job.Running = true
            job.Scope = LocalPlayer.Character
            if job.Direct then
                local started = Data.Performance.Enabled and os.clock()
                local ok, err = pcall(Data.HeartbeatFns[name], elapsed)
                if started then
                    phowg:record_performance('heartbeat/' .. name .. '/elapsed', os.clock() - started)
                end
                job.Running, job.Scope = false, nil
                if not ok and tick() - (job.ErrorAt or 0) > 5 then
                    job.ErrorAt = tick()
                    warn('[Phowg] heartbeat ' .. name .. ': ' .. tostring(err))
                end
                continue
            end
            if not job.Worker then
                job.Worker = coroutine.create(function(step)
                    while not Data.SharedSignalsClosed and Data.HeartbeatJobs[name] == job do
                        local started = Data.Performance.Enabled and os.clock()
                        local ok, err = pcall(Data.HeartbeatFns[name], step)
                        if started then
                            phowg:record_performance('heartbeat/' .. name, os.clock() - started)
                        end
                        job.Running = false
                        job.Scope = nil
                        if not ok and tick() - (job.ErrorAt or 0) > 5 then
                            job.ErrorAt = tick()
                            warn('[Phowg] heartbeat ' .. name .. ': ' .. tostring(err))
                        end
                        if Data.SharedSignalsClosed or Data.HeartbeatJobs[name] ~= job then
                            break
                        end
                        step = coroutine.yield()
                    end
                end)
            end
            local workAt = Data.Performance.Enabled and os.clock()
            task.spawn(job.Worker, elapsed)
            if workAt then
                phowg:record_performance('heartbeat/' .. name .. '/initial execution', os.clock() - workAt)
            end
        end
    end
end
