    local sweep = Data.SharedSignalSweep
    if not sweep then
        sweep = { Records = {}, Index = 1 }
        for _, record in pairs(Data.SharedSignals) do
            sweep.Records[#sweep.Records + 1] = record
        end
        Data.SharedSignalSweep = sweep
    end
    local last = math.min(#sweep.Records, sweep.Index + (limit or #sweep.Records) - 1)
    for index = sweep.Index, last do
        local record = sweep.Records[index]
        if not record.Connection.Connected then
