    Data.ActionsBlocked = true
    for player, targetRoot in pairs(Data.FrozenRoots or {}) do
        if targetRoot and targetRoot.Parent then
            targetRoot.Anchored = false
        end
        Data.FrozenRoots[player] = nil
    end
    phowg:stop_gun_fire()
    phowg:cancel_c_frame_movement()
    if phowg.cancel_auto_save then
        phowg:cancel_auto_save()
    end
    if assiststomprelease then
        assiststomprelease(Data.AssistStompTarget)
    end
    Data.TargetStrafeTarget, Data.KillAuraTarget = nil, nil
end
function registerheartbeat(Name, Fn, Interval, Enabled, Direct)
    local actions, tracking = Data.HeartbeatActions, Data.HeartbeatTracking
    Data['HeartbeatFns'][Name] = function(...)
        if actions[Name] and localactionblocked() then
            phowg:cancel_blocked_actions()
            return
        end
        Data.ActionsBlocked = nil
        if tracking[Name] and (Data.IsRespawning or not LocalPlayer.Character or not Workspace.CurrentCamera) then
            return
        end
        return Fn(...)
    end
    local previous = Data.HeartbeatJobs[Name]
    if previous and previous.Worker and previous.Worker ~= coroutine.running() then
        pcall(task.cancel, previous.Worker)
    end
    if not previous then
        table.insert(Data.HeartbeatOrder, Name)
    end
    local defaults = Data.HeartbeatDefaults
    Data.HeartbeatJobs[Name] = {
        Direct = Direct == true,
        Interval = Interval or defaults[Name] or 0,
        Enabled = Enabled or Data.HeartbeatGates[Name],
        Action = actions[Name] == true,
        Elapsed = 0,
        First = true,
        Running = false,
        Sequence = Data.HeartbeatJobs[Name] and Data.HeartbeatJobs[Name].Sequence or #Data.HeartbeatOrder,
    }
    Data.HeartbeatOrderDirty = true
end
Data.RenderJobs, Data.RenderOrder = {}, {}
Data.RenderOrderSet = {}
function phowg:compact_render_jobs()
    if not Data.RenderOrderDirty or Data.RenderDispatching then
        return
    end
    local write = 1
    for _, name in ipairs(Data.RenderOrder) do
        local job = Data.RenderJobs[name]
        if job and job.Connected then
            Data.RenderOrder[write] = name
            write += 1
        else
            Data.RenderOrderSet[name] = nil
        end
    end
    for index = #Data.RenderOrder, write, -1 do
        Data.RenderOrder[index] = nil
    end
    Data.RenderOrderDirty = false
    if #Data.RenderOrder == 0 and Data.RenderDispatcher then
        Data.RenderDispatcher:Disconnect()
        Data.RenderDispatcher = nil
    end
end
function phowg:run_render_jobs(delta)
    if Data.RenderDispatching or Data.SharedSignalsClosed then
        return
    end
    phowg:compact_render_jobs()
    Data.RenderDispatching = true
    for _, name in ipairs(Data.RenderOrder) do
        local job = Data.RenderJobs[name]
        if not job or not job.Connected or job.Running then
            continue
        end
        if not job.Worker then
            job.Worker = coroutine.create(function(step)
                while job.Connected and not Data.SharedSignalsClosed do
                    local ok, problem = pcall(job.Callback, step)
                    job.Running = false
                    if not ok and tick() - (job.ErrorAt or -math.huge) > 5 then
                        job.ErrorAt = tick()
                        warn('[Phowg] render ' .. name .. ': ' .. tostring(problem))
                    end
                    if not job.Connected then
                        return
                    end
                    step = coroutine.yield()
                end
            end)
        end
        job.Running = true
        task.spawn(job.Worker, delta)
    end
    Data.RenderDispatching = false
end
function phowg:register_render(callback, owner, label)
    local name = label or tostring(callback)
    local previous = Data.RenderJobs[name]
    if previous then
        previous:Disconnect()
    end
    if not Data.RenderOrderSet[name] then
        Data.RenderOrder[#Data.RenderOrder + 1] = name
        Data.RenderOrderSet[name] = true
    end
    local job: { [string]: any } = { Callback = callback, Owner = owner, Connected = true, Running = false }
    function job:Disconnect()
        if not self.Connected then
            return
        end
        self.Connected = false
        if self.Worker and self.Worker ~= coroutine.running() then
            pcall(task.cancel, self.Worker)
        end
        self.Callback, self.Owner, self.Worker = nil, nil, nil
        if Data.RenderJobs[name] == self then
            Data.RenderJobs[name] = nil
        end
        Data.RenderOrderDirty = true
    end
    Data.RenderJobs[name] = job
    if not Data.RenderDispatcher then
        Data.RenderDispatcher = create_connection(
            'VisualRenderDispatcher',
            connectshared(
                RunService.RenderStepped,
                phowg_callbacks.run_render_jobs,
                RunService,
                'frame/visual dispatcher',
                0,
                'event/RenderStepped',
                RunService
            )
        )
    end
    return job
end
phowg:register_cleanup('visual render jobs', function(scope)
    for _, job in pairs(Data.RenderJobs) do
        if not scope or phowg:scope_contains(scope, job.Owner) then
            job:Disconnect()
        end
    end
    if not scope then
        if Data.RenderDispatcher then
            Data.RenderDispatcher:Disconnect()
            Data.RenderDispatcher = nil
        end
        table.clear(Data.RenderJobs)
        table.clear(Data.RenderOrder)
        table.clear(Data.RenderOrderSet)
    end
end)
function gethumanoid(character)
    character = character or LocalPlayer.Character
    return character and character:FindFirstChildOfClass('Humanoid') or nil
end
function phowg:is_armor_purchase(label)
    local name = normalizeweaponname(label)
    return name == 'highmedium'
        or (string.find(name, 'armor', 1, true) ~= nil and string.find(name, 'ammo', 1, true) == nil)
end
function phowg:purchase_blocks_shooting()
    return Data.MaskBuying or (Data.Buying and not Data.BuyingArmor)
end
function phowg:support_armor_blocked(target)
    if not target or not (Data.PunishmentTargets and Data.PunishmentTargets[target]) then
        return false
    end
    return Data.PendingSupport ~= nil and Data.PendingSupport[target] ~= nil
end
function phowg:self_protect_enabled()
    return not Library.Unloaded
        and not Data.SafeMode
        and Toggles.protect_player_self ~= nil
        and Toggles.protect_player_self.Value == true
end
function phowg:other_protection_enabled()
    return not Library.Unloaded
        and not Data.SafeMode
        and Toggles.punishment_enabled ~= nil
        and Toggles.punishment_enabled.Value == true
end
function phowg:report_protection_enabled()
    return not Library.Unloaded
        and not Data.SafeMode
        and Toggles.protect_reports ~= nil
        and Toggles.protect_reports.Value == true
end
function phowg:israel_support_enabled()
    return phowg:other_protection_enabled() or phowg:self_protect_enabled() or phowg:report_protection_enabled()
end
function phowg:support_request_allowed(victim, reason)
    if reason == 'report' then
        return phowg:report_protection_enabled()
    end
    if victim == LocalPlayer then
        return phowg:self_protect_enabled()
    end
    return phowg:other_protection_enabled()
        and (
            victim == nil
            or Toggles.protect_whitelisted ~= nil
                and Toggles.protect_whitelisted.Value == true
                and Data.IsraelWhitelist ~= nil
                and Data.IsraelWhitelist[victim] == true
        )
end
function phowg:support_combat_pending()
    return phowg:israel_support_enabled()
        and (next(Data.PendingSupport or {}) ~= nil or next(Data.PunishmentTargets or {}) ~= nil)
end
function phowg:next_support_target()
    if not phowg:israel_support_enabled() then
        return nil
    end
    local first, order
    for target in pairs(Data.PunishmentTargets or {}) do
        local session = Data.SupportTargetSessions and Data.SupportTargetSessions[target]
        local sequence = session and session.Order or math.huge
        if target.Parent and (not first or sequence < order or sequence == order and target.UserId < first.UserId) then
            first, order = target, sequence
        end
    end
    for target, pending in pairs(Data.PendingSupport or {}) do
        if target.Parent and (not first or (pending.Order or math.huge) < order) then
            first, order = target, pending.Order or math.huge
        end
    end
    return first
end
function phowg:select_support_head()
    local first = phowg:next_support_target()
    local previous = Data.SupportHead
    Data.SupportHead = first
    if first then
        if Data.CurrentActionTarget ~= first then
            Data.RagebotArrival, Data.GunFocusTarget, Data.GunFocusAt, Data.GunAimTarget, Data.GunAimAt =
                nil, nil, nil, nil, nil
            local held = Data.HeldGunFire
            if held and held.Target ~= first and (held.Owner == 'Ragebot' or held.Owner == 'Support') then
                phowg:stop_gun_fire()
            end
        end
        Data.SingleLockedTarget, Data.CurrentMainTarget, Data.CurrentActionTarget = first, first, first
    elseif previous then
        if Data.SingleLockedTarget == previous then
            Data.SingleLockedTarget = nil
        end
        if Data.CurrentMainTarget == previous then
            Data.CurrentMainTarget = nil
        end
        if Data.CurrentActionTarget == previous then
            Data.CurrentActionTarget = nil
        end
        local held = Data.HeldGunFire
        if held and held.Target == previous then
            phowg:stop_gun_fire()
        end
    end
    return first
end
function phowg:ready_support_targets(targets)
    local first = phowg:next_support_target()
    if not first then
        return targets
    end
    if Data.PendingSupport and Data.PendingSupport[first] or phowg:support_armor_blocked(first) then
        return {}
    end
    for _, target in ipairs(targets) do
        if target == first then
            return { first }
        end
    end
    return {}
end
function phowg:combat_runtime()
    local runtime = Data.CombatRuntime
    if not runtime or runtime.Character ~= LocalPlayer.Character then
        runtime = {
            Character = LocalPlayer.Character,
            Tools = setmetatable({}, { __mode = 'k' }),
            Requests = 0,
            Blasts = 0,
            Ammo = 0,
            Hits = 0,
            Damage = 0,
            Errors = 0,
            CacheBuilds = 0,
            Started = tick(),
            Phase = 'idle',
            Reason = 'no firing request',
            Since = tick(),
            Transitions = 0,
        }
        Data.CombatRuntime = runtime
    end
    return runtime
end
function phowg:set_combat_state(phase, reason, owner, target)
    local runtime = phowg:combat_runtime()
    if runtime.Phase ~= phase or runtime.Reason ~= reason or runtime.Owner ~= owner or runtime.Target ~= target then
        runtime.Phase, runtime.Reason, runtime.Owner, runtime.Target, runtime.Since =
            phase, reason, owner, target, tick()
        runtime.Transitions += 1
    end
    return runtime
end
function phowg:equipment_owner(): string?
    local lease = Data.EquipmentLease
    if
        lease
        and (
            lease.Character ~= LocalPlayer.Character
            or tick() >= lease.Until
            or lease.Owner == 'reload'
                and not Data.GunReloadSelection
                and not (isreloading and isreloading())
                and not phowg:reload_pending(lease.Character)
        )
    then
        Data.EquipmentLease = nil
        lease = nil
    end
    if Data.NukeGrenadeJob then
        return 'nuke'
    end
    if Data.Buying then
        return 'purchase'
    end
    if Data.Sorting then
        return 'sorting'
    end
    if
        Data.GunReloadSelection
        or isreloading and isreloading()
        or phowg.reload_pending and phowg:reload_pending(LocalPlayer.Character)
    then
        return 'reload'
    end
    if Data.LoadoutReloadJob then
        return 'loadout reload'
    end
    return lease and lease.Owner or nil
end
function phowg:release_equipment(owner, tool)
    local lease = Data.EquipmentLease
    if lease and (not owner or lease.Owner == owner) and (not tool or lease.Tool == tool) then
        Data.EquipmentLease = nil
    end
end
function phowg:request_equipment(owner: string, tool, mode: string, job)
    local purchaseOwner: boolean = owner == 'purchase'
    local reloadOwner: boolean = owner == 'reload'
    local character = LocalPlayer.Character
    local pack = LocalPlayer:FindFirstChild('Backpack')
    if not character or not pack or not tool or Library.Unloaded or Data.SharedSignalsClosed or Data.IsRespawning then
        return false, 'character unavailable'
    end
    if tool.Parent ~= character and tool.Parent ~= pack then
        return false, 'tool unavailable'
    end
    local busy: string? = phowg:equipment_owner()
    if not purchaseOwner and localactionblocked() then
        return false, 'local character unavailable'
    end
    if busy == 'purchase' or busy == 'sorting' or busy == 'reload' or busy == 'nuke' then
        if busy ~= owner then
            return false, busy .. ' owns equipment'
        end
    elseif busy == 'loadout reload' and job ~= Data.LoadoutReloadJob then
        return false, busy .. ' owns equipment'
    end
    local lease = Data.EquipmentLease
    if lease and lease.Owner ~= owner then
        return false, lease.Owner .. ' owns equipment'
    end
    if mode ~= 'unequip' and not phowg:tool_equip_ready(tool) then
        return false, 'tool is still loading'
    end
    lease = { Owner = owner, Tool = tool, Character = character, Until = tick() + (reloadOwner and 8 or 0.15) }
    Data.EquipmentLease = lease
    local ok, problem = pcall(function()
        if mode == 'unequip' then
            if tool.Parent == character then
                phowg:deactivate_tool(tool)
                tool.Parent = pack
            end
        elseif mode == 'last' then
            if tool.Parent == character then
                tool.Parent = pack
            end
            tool.Parent = character
        elseif mode == 'exclusive' then
            local humanoid = character:FindFirstChildOfClass('Humanoid')
            if humanoid then
                humanoid:EquipTool(tool)
            else
                tool.Parent = character
            end
        elseif tool.Parent ~= character then
            tool.Parent = character
        end
    end)
    if not reloadOwner or not ok then
        if Data.EquipmentLease == lease then
            Data.EquipmentLease = nil
        end
    end
    if ok and phowg.invalidate_china_gun_cache then
        phowg:invalidate_china_gun_cache(tool)
    end
    if ok then
        return true, nil
    end
    return false, tostring(problem)
end
function phowg:combat_can_fire(owner, tool, target)
    local source = owner
    if owner == 'china' or owner == 'combat' then
        source = nil
    end
    local reason, phase
    if Library.Unloaded or Data.SharedSignalsClosed then
        phase, reason = 'idle', 'script stopped'
    elseif Data.IsRespawning or not LocalPlayer.Character then
        phase, reason = 'respawning', 'character unavailable'
    elseif localshootblocked() then
        phase, reason = 'paused', 'local character cannot shoot'
    elseif
        source == 'Ragebot'
        and phowg:target_search_active()
        and (not phowg:target_search_engaged() or target ~= Data.TargetSearch.Target)
    then
        phase, reason = 'acquiring', 'server search target filtered'
    elseif
        source == 'Ragebot'
        and phowg:auto_bounty_enabled()
        and not Data.PunishmentGunActive
        and not phowg:auto_bounty_target_allowed(target)
    then
        phase, reason = 'acquiring', 'bounty target filtered'
    elseif source == 'KillAura' and phowg.kill_aura_in_void and phowg:kill_aura_in_void() then
        phase, reason = 'paused', 'hidden in void'
    elseif source == 'KillAura' and target and not killauravalidtarget(target) then
        phase, reason = 'acquiring', 'target filtered'
    elseif Data.NukeGrenadeJob or Data.AutoGrenadeThrowJob then
        phase, reason = 'paused', 'grenade activation'
    elseif Data.RPGMoveActive then
        phase, reason = 'evading', 'explosive evasion'
    elseif phowg:purchase_blocks_shooting() then
        phase, reason = 'buying', 'purchase in progress'
    elseif
        isreloading()
        or Data.GunReloadSelection
        or phowg.reload_pending and phowg:reload_pending(LocalPlayer.Character)
    then
        phase, reason = 'reloading', 'reload in progress'
    elseif Data.Sorting or Data.LoadoutReloadJob then
        phase, reason = 'paused', 'inventory operation'
    elseif phowg.sticky_shot_blocked and phowg:sticky_shot_blocked(target, source) then
        phase, reason = 'paused', 'sticky aim shoot conditions'
    elseif target and phowg.chinese_transfer_active and phowg:chinese_transfer_active(target) then
        phase, reason = 'positioning', 'killing'
    elseif target and (not target.Parent or not target.Character) then
        phase, reason = 'acquiring', 'target unavailable'
    elseif tool and tool.Parent ~= LocalPlayer.Character then
        phase, reason = 'equipping', 'gun not equipped'
    end
    if reason then
        phowg:set_combat_state(phase, reason, owner, target)
        return false
    end
    return true
end
function phowg:combat_tool_stats(tool)
    local runtime = phowg:combat_runtime()
    local state = runtime.Tools[tool]
    if not state then
        state = { Sent = 0, Ammo = 0, Hits = 0, Damage = 0 }
        runtime.Tools[tool] = state
    end
    return state, runtime
end
function phowg:record_combat_request(tool, packets, china, target)
    if typeof(tool) ~= 'Instance' or not tool:IsA('Tool') then
        return
    end
    local state, runtime = phowg:combat_tool_stats(tool)
    runtime.Requests += packets
    runtime.LastShot = tick()
    if china then
        runtime.Blasts += 1
        state.Sent += 1
        state.LastSent = tick()
        state.Target, state.TargetCharacter = target, target and target.Character
    end
end
function phowg:record_combat_ammo(tool, spent)
    local runtime = Data.CombatRuntime
    local state = runtime and runtime.Character == LocalPlayer.Character and runtime.Tools[tool]
    if not state or not state.LastSent or tick() - state.LastSent > 2 then
        return
    end
    local count = math.clamp(tonumber(spent) or 0, 0, 1000)
    state.Ammo += count
    state.LastAmmo = tick()
    runtime.Ammo += count
end
function phowg:record_combat_hit(player, damage, weapon)
    local runtime = phowg:combat_runtime()
    runtime.Hits += 1
    runtime.Damage += math.max(0, tonumber(damage) or 0)
    for tool, state in pairs(runtime.Tools) do
        if
            state.Target == player
            and state.TargetCharacter == player.Character
            and tool.Name == weapon
            and tick() - (state.LastSent or -math.huge) < 2
        then
            state.Hits += 1
            state.Damage += math.max(0, tonumber(damage) or 0)
            break
        end
    end
end
function phowg:combat_diagnostics_text()
    local runtime = phowg:combat_runtime()
    local pending = Data.GunReloadPending
    local lease = phowg:equipment_owner()
    local lines = {
        string.format('combat: %s / %s', runtime.Phase, runtime.Reason),
        string.format('requests: %d | blasts: %d | ammo used: %d', runtime.Requests, runtime.Blasts, runtime.Ammo),
        string.format(
            'confirmed hits: %d | damage: %.0f | send errors: %d',
            runtime.Hits,
            runtime.Damage,
            runtime.Errors
        ),
        'equipment owner: '
            .. tostring(lease or 'available')
            .. ' | pending reload: '
            .. (pending and pending.Tool and pending.Tool.Name or 'none'),
    }
    for tool, state in pairs(runtime.Tools) do
        if tool.Parent == LocalPlayer.Character then
            lines[#lines + 1] =
                string.format('%s: shots %d | ammo %d | hits %d', tool.Name, state.Sent, state.Ammo, state.Hits)
        end
    end
    lines[#lines + 1] = 'gun cache rebuilds: ' .. tostring(runtime.CacheBuilds)
    if phowg.native_hit_feedback_enabled and not phowg:native_hit_feedback_enabled() then
        lines[#lines + 1] = 'hit confirmation inactive'
    end
    return table.concat(lines, '\n')
end
registerheartbeat('CombatState', function()
    if Library.Unloaded or Data.SharedSignalsClosed then
        return
    end
    local held = Data.HeldGunFire
    local target = held and held.Target or Data.CurrentActionTarget or Data.StickyTarget
    local owner = held and held.Owner or 'combat'
    if not phowg:combat_can_fire(owner, held and held.Tool, target) then
        if held then
            phowg:stop_gun_fire(held.Owner)
        end
        return
    end
    if held and held.ChinaHack and tick() - (held.RequestedAt or 0) > 0.35 then
        phowg:stop_gun_fire(held.Owner)
        phowg:set_combat_state('acquiring', 'firing request expired', owner, target)
    elseif held or tick() - (phowg:combat_runtime().LastShot or -math.huge) < 0.2 then
        phowg:set_combat_state('firing', 'killing', owner, target)
    elseif type(Data.CurrentStatus) == 'string' and Data.CurrentStatus:find('stomping', 1, true) then
        phowg:set_combat_state('stomping', 'finishing target', owner, target)
    elseif target then
        phowg:set_combat_state('acquiring', 'waiting for firing request', owner, target)
    else
        phowg:set_combat_state('idle', 'no target', owner, nil)
    end
end, 0.1)
phowg:register_cleanup('combat runtime', function(scope, reason)
    if not scope or reason == 'unload' or scope == LocalPlayer.Character or scope == Data.ManagedCharacter then
        Data.EquipmentLease, Data.CombatRuntime, Data.CombatFrameMs = nil, nil, nil
    end
end)
function phowg:deactivate_tool(tool)
    local character = LocalPlayer.Character
    if not tool or not character or tool.Parent ~= character or not tool:IsA('Tool') then
        return false
    end
    return pcall(tool.Deactivate, tool)
end
function phowg:queue_removed_gun_stop(tool, character)
    Data.RemovedGunStops = Data.RemovedGunStops or setmetatable({}, { __mode = 'k' })
    if Data.RemovedGunStops[tool] then
        return
    end
    local pending = { Character = character }
    Data.RemovedGunStops[tool] = pending
    task.defer(function()
        if Data.RemovedGunStops[tool] ~= pending then
            return
        end
        Data.RemovedGunStops[tool] = nil
        if
            not Library.Unloaded
            and LocalPlayer.Character == character
            and tool.Parent ~= character
            and not (Data.GunReloadSelection and Data.GunReloadSelection.Tool == tool)
        then
            phowg:stop_gun_fire(nil, tool)
        end
    end)
end
function phowg:stop_gun_fire(owner, tool)
    local held = Data.HeldGunFire
    if not held or (owner and held.Owner ~= owner) or (tool and held.Tool ~= tool) then
        return
    end
    Data.HeldGunFire = nil
    phowg:deactivate_tool(held.Tool)
    if held.ChinaHack and held.Owner == 'Ragebot' and phowg.china_release_extra and not phowg:china_multi_active() then
        phowg:china_release_extra()
    end
end
function phowg:gun_shoot_method(owner, target)
    if target and Data.PunishmentTargets and Data.PunishmentTargets[target] then
        return 'perfect hit'
    end
    return Options.gun_shoot_method and Options.gun_shoot_method.Value or 'shoot redirect'
end
function phowg:activate_gun_fire(held, interval)
    local tool, target, character = held.Tool, held.Target, held.Character
    if character ~= LocalPlayer.Character or not tool or tool.Parent ~= character then
        return false
    end
    local ammo = tool:FindFirstChild('Ammo')
    local reload = tool:FindFirstChild('Reloading') or tool:FindFirstChild('Reload')
    if
        ammo and ammo.Value <= 0
        or reload and reload.Value == true
        or Data.SupportGunReloads and Data.SupportGunReloads[tool]
    then
        return false
    end
    if held.LastActivate == nil then
        local cooldown = tool:FindFirstChild('ShootingCooldown')
        held.Automatic = tool:FindFirstChild('GunClientAutomatic') ~= nil
            or tool:FindFirstChild('GunClientAutomaticShotgun') ~= nil
        held.LastActivate, held.LastShotAt, held.Ammo = -math.huge, -math.huge, ammo and ammo.Value
        held.RetryAfter = math.max(0.15, (cooldown and tonumber(cooldown.Value) or 0) + 0.05)
    end
    local now = tick()
    if ammo then
        if held.Ammo and ammo.Value < held.Ammo then
            held.LastShotAt = now
        end
        held.Ammo = ammo.Value
    end
    if held.Automatic and now - math.max(held.LastActivate, held.LastShotAt) < held.RetryAfter then
        return true
    end
    local minimumInterval = math.max(0, interval or 0)
    if now - held.LastActivate < minimumInterval then
        return true
    end
    local retryAutomatic = held.Automatic and held.LastActivate > -math.huge
    held.LastActivate = now
    local ok = pcall(function()
        if retryAutomatic or held.Owner == 'Ragebot' and not held.Automatic then
            phowg:deactivate_tool(tool)
        end
        tool:Activate()
    end)
    if not ok then
        return false
    end
    if target and Data.PunishmentTargets and Data.PunishmentTargets[target] then
        Data.SupportTargetSessions = Data.SupportTargetSessions or {}
        local session = Data.SupportTargetSessions[target] or {}
        Data.SupportTargetSessions[target] = session
        session.Tool, session.Character = tool, character
    end
    Data.RecentlyShotAt = now
    return true
end
function phowg:fire_gun(owner, tool, target, interval)
    if phowg.combat_can_fire and not phowg:combat_can_fire(owner, tool, target) then
        phowg:stop_gun_fire(owner)
        return false
    end
    if phowg.combat_ammo_paused and phowg:combat_ammo_paused() then
        phowg:stop_gun_fire(owner)
        return false
    end
    if not phowg:smart_attack_ready(target, owner) then
        phowg:stop_gun_fire(owner)
        return false
    end
    if phowg.support_multi_selected and phowg:support_multi_selected(target, owner) then
        return phowg:fire_support_loadout(owner, target, interval)
    end
    if
        (owner == 'Ragebot' or owner == 'Support' or owner == 'KillAura')
        and phowg:gun_shoot_method(owner, target) == 'china hack'
    then
        return phowg:china_fire_gun(owner, tool, target)
    end
    local character = LocalPlayer.Character
    if
        not tool
        or tool.Parent ~= character
        or localshootblocked()
        or isreloading()
        or phowg:purchase_blocks_shooting()
        or phowg:support_armor_blocked(target)
        or Data.RPGMoveActive
        or Data.SupportGunReloads and Data.SupportGunReloads[tool]
    then
        phowg:stop_gun_fire(owner)
        return false
    end
    local ammo = tool:FindFirstChild('Ammo')
    if ammo and ammo.Value <= 0 then
        phowg:stop_gun_fire(owner)
        return false
    end
    local held = Data.HeldGunFire
    local method = phowg:gun_shoot_method(owner, target)
    if held and held.Owner ~= owner then
        local priority = { Ragebot = 30, Support = 20, KillAura = 10, FullAuto = 0 }
        if (priority[held.Owner] or 0) > (priority[owner] or 0) then
            return false
        end
    end
    if
        held
        and (
            held.ChinaHack
            or held.ShootMethod ~= method
            or held.Tool ~= tool
            or held.Owner ~= owner
            or held.Character ~= character
            or held.Target ~= target
            or held.TargetCharacter ~= (target and target.Character)
        )
    then
        phowg:stop_gun_fire()
        held = nil
    end
    if not held then
        local cooldown = tool:FindFirstChild('ShootingCooldown')
        held = {
            Guns = nil :: any,
            Owner = owner,
            ShootMethod = method,
            Tool = tool,
            Character = character,
            Target = target,
            TargetCharacter = target and target.Character,
            Automatic = tool:FindFirstChild('GunClientAutomatic') ~= nil
                or tool:FindFirstChild('GunClientAutomaticShotgun') ~= nil,
            LastActivate = -math.huge,
            LastShotAt = -math.huge,
            Ammo = ammo and ammo.Value,
            RetryAfter = math.max(0.15, (cooldown and tonumber(cooldown.Value) or 0) + 0.05),
        }
        Data.HeldGunFire = held
    else
        held.Target, held.TargetCharacter = target, target and target.Character
    end
    if phowg:activate_gun_fire(held, interval) then
        return true
    end
    phowg:stop_gun_fire(owner)
    return false
end
registerheartbeat('CombatFireGuard', function()
    local held = Data.HeldGunFire
    if not held then
        return
    end
    if
        held.Character ~= LocalPlayer.Character
        or held.Tool.Parent ~= held.Character
        or localshootblocked()
        or isreloading()
        or phowg:purchase_blocks_shooting()
        or phowg:support_armor_blocked(held.Target)
        or Data.RPGMoveActive
    then
        phowg:stop_gun_fire()
        return
    end
    local target = held.Target
    if not phowg:smart_attack_ready(target, held.Owner) then
        phowg:stop_gun_fire(held.Owner)
        return
    end
    if
        target
        and (not target.Parent or target.Character ~= held.TargetCharacter or isdead(target) or isknocked(target))
    then
        phowg:stop_gun_fire()
        return
    end
    if
        held.Owner == 'Ragebot'
        and (not (rageboton() or punishmentactive()) or not phowg:ragebot_action_enabled('auto_kill'))
    then
        phowg:stop_gun_fire()
    elseif
        held.Owner == 'KillAura'
        and (not killauraenabled() or killaurabusy() or phowg:kill_aura_in_void() or not killauravalidtarget(target))
    then
        phowg:stop_gun_fire()
    elseif
        held.Owner == 'Support'
        and (
            not phowg:israel_support_enabled()
            or Data.PunishmentGunActive
            or not (Toggles.full_rage and Toggles.full_rage.Value)
            or Data.RapeTarget ~= target
            or (Data.SupportCompletedTargets and Data.SupportCompletedTargets[target])
        )
    then
        phowg:stop_gun_fire()
    elseif
        held.Owner == 'FullAuto'
        and (
            not (Toggles.full_auto and Toggles.full_auto.Value)
            or UserInputService:GetFocusedTextBox()
            or not UserInputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton1)
        )
    then
        phowg:stop_gun_fire()
    end
end)
phowg:register_cleanup('held gun fire', function(scope)
    local held = Data.HeldGunFire
    if held and (not scope or scope == held.Character or (held.Target and scope == held.TargetCharacter)) then
        phowg:stop_gun_fire()
    end
end)
local function updatesuspension()
    if localactionblocked() then
        phowg:stop_gun_fire()
        table.clear(Data['CSync'].Queue)
        Data['CSync'].PendingCF = nil
        Data['MoveToActive'] = false
        Data['MoveToTargetCF'] = nil
        Data['CombatArrivalAt'] = nil
        Data['CombatArrivalLastAt'] = nil
        if Data['ActionsSuspended'] then
            return
        end
        Data['ActionsSuspended'] = true
        Data['SuspendedMovement'] =
            { fly = Data['Flying'], wallwalk = Data['WallWalking'], velocity = Data['VelocityActive'] }
        if Data['Flying'] and stopfly then
            stopfly()
        end
        if Data['WallWalking'] and stopwallwalk then
            stopwallwalk()
        end
        if Data['VelocityActive'] and stopvelocity then
            stopvelocity()
        end
        if stopnoclip then
            stopnoclip()
        end
        if stopflingstate then
            stopflingstate()
        end
        if stoprpgmove then
            stoprpgmove(false)
        end
        local character = LocalPlayer.Character
        if character then
            for _, tool in ipairs(character:GetChildren()) do
                if tool:IsA('Tool') then
                    pcall(function()
                        phowg:deactivate_tool(tool)
                    end)
                end
            end
        end
        if hidevisualizer then
            hidevisualizer()
        end
        return
    end
    if not Data['ActionsSuspended'] then
        return
    end
    Data['ActionsSuspended'] = false
    Data['TargetListCache'] = nil
    local movement = Data['SuspendedMovement'] or {}
    Data['SuspendedMovement'] = nil
    if movement.fly and Toggles.fly and Toggles.fly.Value then
        startfly()
    elseif movement.wallwalk and Toggles.wallwalk and Toggles.wallwalk.Value then
        startwallwalk()
    elseif movement.velocity and Toggles.speed_velocity and Toggles.speed_velocity.Value then
        startvelocity()
    end
    if punishmentactive and punishmentactive() then
        applypunishmentmodes()
        ragebot_on()
    end
    if Toggles.noclip and Toggles.noclip.Value then
        nocliptick()
    end
    if Toggles.walkspeed_enabled and Toggles.walkspeed_enabled.Value then
        starthumanoidwalkspeed()
    end
    if Toggles.jumppower_enabled and Toggles.jumppower_enabled.Value then
        starthumanoidjumppower()
    end
    if Toggles.remove_slowdowns and Toggles.remove_slowdowns.Value then
        startremoveslowdowns()
    end
    if Toggles.remove_jump_cooldown and Toggles.remove_jump_cooldown.Value then
        startremovejumpcooldown()
    end
    if Toggles.disable_states and Toggles.disable_states.Value then
        apply_disable_states()
    end
end
function intelligence:classify_tool(Tool)
    if not Tool then
        return nil
    end
    local Handle = Tool:FindFirstChild('Handle')
    if not Handle then
        return nil
    end
    local Offset = Vector3.new(0, 0, -Handle.Size.Z / 2)
    local AmmoObj = Tool:FindFirstChild('Ammo')
    local Ammo = AmmoObj and AmmoObj.Value or 0
    local MaxAmmo = Tool:FindFirstChild('MaxAmmo') and Tool.MaxAmmo.Value or 0
    local Gun = Tool:FindFirstChild('GunClient') ~= nil
    local Shotgun = Tool:FindFirstChild('GunClientShotgun') ~= nil
    local Automatic = Tool:FindFirstChild('GunClientAutomatic') ~= nil
    if not Automatic then
        for _, d in ipairs(Tool:GetDescendants()) do
            if string.find(string.lower(d.Name), 'automatic', 1, true) then
                Automatic = true
                break
            end
        end
    end
    local Client = not (Gun or Shotgun or Automatic)
    return {
        instance = Tool,
        handle = Handle,
        offset = Offset,
        ammo = Ammo,
        max_ammo = MaxAmmo,
        has_ammo = AmmoObj ~= nil,
        gun = Gun,
        shotgun = Shotgun,
        automatic = Automatic,
        client = Client,
    }
end
function intelligence:get_tool_cache()
    local Tool = LocalPlayer.Character and LocalPlayer.Character:FindFirstChildOfClass('Tool') or nil
    return intelligence:classify_tool(Tool)
end
function intelligence:get_data_cache(player: Player)
    local Plr = player or LocalPlayer
    if not Plr then
        return nil
    end
    local DF = Plr:FindFirstChild('DataFolder')
    if not DF then
        return nil
    end
    local Info = DF:FindFirstChild('Information')
    local Crew = Info and Info:FindFirstChild('Crew') or DF:FindFirstChild('Crew')
    local Wanted = Info and Info:FindFirstChild('Wanted') or DF:FindFirstChild('Wanted')
    local Currency = DF:FindFirstChild('Currency')
    local Muscle = DF:FindFirstChild('MuscleInformation') or (Info and Info:FindFirstChild('MuscleInformation'))
    local Char = Plr.Character
    local BE = Char and Char:FindFirstChild('BodyEffects') or nil
    local Cuff = BE and BE:FindFirstChild('Cuff') or nil
    local CuffVal = Cuff and Cuff.Value or nil
    local Grabbed = BE and BE:FindFirstChild('Grabbed') or nil
    local Carrying = Grabbed and Grabbed.Value or nil
    return {
        Crew = Crew and Crew.Value or nil,
        Wanted = Wanted and Wanted.Value or nil,
        Currency = Currency and Currency.Value or nil,
        MuscleInformation = Muscle and Muscle.Value or nil,
        Cuff = CuffVal,
        Jailed = CuffVal == true,
        carrying = Carrying,
        Carrying = Carrying,
    }
end
function intelligence:get_status_cache(player: Player)
    local Plr = player or LocalPlayer
    if not intelligence:get_character_cache(Plr) then
        return nil
    end
    local Char = Plr.Character
    local BE = Char:FindFirstChild('BodyEffects')
    if not BE then
        return nil
    end
    local function get_val(Name)
        local V = BE:FindFirstChild(Name)
        return V and V.Value or nil
    end
    local Grabbed = Char:FindFirstChild('GRABBING_CONSTRAINT', true) ~= nil
    if not Grabbed then
        Grabbed = Char:FindFirstChild('GRABBING_CONSTRAINT') ~= nil
    end
    local GrabbedObj = BE:FindFirstChild('Grabbed')
    local Carrying = GrabbedObj and GrabbedObj.Value or nil
    return {
        MousePos = get_val('MousePos'),
        FireArmor = get_val('FireArmor'),
        Armor = get_val('Armor'),
        Dead = get_val('Dead'),
        Defense = get_val('Defense'),
        Anonymous = get_val('Anonymous'),
        Reload = get_val('Reload'),
        ['K.O'] = get_val('K.O') or get_val('KO'),
        SDeath = get_val('SDeath'),
        Grabbed = Grabbed,
        carrying = Carrying,
        Carrying = Carrying,
    }
end
function phowg:character_snapshot(character)
    if not character or not character.Parent then
        return nil
    end
    Data.CharacterSnapshots = Data.CharacterSnapshots or setmetatable({}, { __mode = 'k' })
    local saved = Data.CharacterSnapshots[character]
    local frame = Data.MotionFrame or 0
    if
        saved
        and saved.Frame == frame
        and saved.Root
        and saved.Root.Parent == character
        and saved.Humanoid
        and saved.Humanoid.Parent == character
    then
        return saved
    end
    saved = {
        Frame = frame,
        Root = character:FindFirstChild('HumanoidRootPart'),
        Humanoid = character:FindFirstChildOfClass('Humanoid'),
        Head = character:FindFirstChild('Head'),
        Torso = character:FindFirstChild('UpperTorso') or character:FindFirstChild('Torso'),
        BodyEffects = character:FindFirstChild('BodyEffects'),
    }
    Data.CharacterSnapshots[character] = saved
    return saved
end
function intelligence:get_character_cache(player: Player)
    if not player then
        return nil
    end
    local Plr = player
    if not Plr.Character then
        return nil
    end
    local Char = Plr.Character
    if not Char.Parent or not Char:IsDescendantOf(Workspace) then
        return nil
    end
    local snapshot = phowg:character_snapshot(Char)
    local Hum = snapshot and snapshot.Humanoid
    if not Hum then
        return nil
    end
    if Hum.Health <= 0 then
        local effects = Char:FindFirstChild('BodyEffects')
        local dead = effects and effects:FindFirstChild('Dead')
        local knocked = effects and (effects:FindFirstChild('K.O') or effects:FindFirstChild('KO'))
        if not ((dead and dead.Value == true) or (knocked and knocked.Value == true)) then
            return nil
        end
    end
    local Root = snapshot.Root
    if not Root or not Root.Parent then
        return nil
    end
    if not snapshot.Head then
        return nil
    end
    if not snapshot.Torso then
        return nil
    end
    if not Root:IsA('BasePart') then
        return nil
    end
    local BE = snapshot.BodyEffects
    if BE then
        local S = BE:FindFirstChild('SDeath')
        if S and S.Value then
            return nil
        end
    end
    return Char
end
function IntelligenceHandler:Cache_Tool()
    return intelligence:get_tool_cache()
end
function hookequippedtools(Character)
    hooklocaltools(Character)
end
function phowg:clear_local_data(scope)
    local record = Data.LocalState
    if not record or scope and record.Character ~= scope then
        return
    end
    Data.LocalState = nil
    for name, connection in pairs(record.Connections) do
        connection:Disconnect()
        if Connections[name] == connection then
            Connections[name] = nil
        end
        local index = table.find(Library.Signals, connection)
        if index then
            table.remove(Library.Signals, index)
        end
    end
    Local_Parts.BodyEffects, Local_Parts.Armor, Local_Parts.FireArmor, Local_Parts.Attacking, Local_Parts.GunFiring =
        nil, nil, nil, nil, nil
    Local_Data.Stomped, Local_Data.Dead, Local_Data.Knocked = false, false, false
    Local_Data.carrying, Local_Data.Carrying, Local_Data.Armor, Local_Data.FireArmor = nil, nil, nil, nil
end
function phowg:bind_local_data(character, bodyEffects)
    if not character or character ~= LocalPlayer.Character then
        return
    end
    if bodyEffects == nil then
        bodyEffects = character:FindFirstChild('BodyEffects')
    end
    local previous = Data.LocalState
    if previous and previous.Character == character and previous.BodyEffects == bodyEffects then
        return
    end
    phowg:clear_local_data()
    local record: { [string]: any } =
        { Character = character, BodyEffects = bodyEffects, Values = {}, Connections = {} }
    Data.LocalState = record
    Local_Parts.BodyEffects = bodyEffects or nil
    if not bodyEffects then
        updatesuspension()
        return
    end
    local tracked = {
        SDeath = true,
        Dead = true,
        ['K.O'] = true,
        KO = true,
        Armor = true,
        FireArmor = true,
        Grabbed = true,
        Attacking = true,
        Reload = true,
        Reloading = true,
        GunFiring = true,
    }
    local function active()
        return Data.LocalState == record and LocalPlayer.Character == character and bodyEffects.Parent == character
    end
    local function sync(key, changed)
        if not active() then
            return
        end
        local value = record.Values[key]
        if key == 'SDeath' or key == 'Dead' or key == 'K.O' or key == 'KO' then
            local stomped, dead = record.Values.SDeath, record.Values.Dead
            local knocked = record.Values['K.O'] or record.Values.KO
            Local_Data.Stomped = stomped and stomped.Value == true or false
            Local_Data.Dead = dead and dead.Value == true or false
            Local_Data.Knocked = knocked and knocked.Value == true or false
            updatesuspension()
        elseif key == 'Reload' or key == 'Reloading' then
            local reload, reloading = record.Values.Reload, record.Values.Reloading
            if phowg.track_loadout_reload then
                phowg:track_loadout_reload(
                    character,
                    reload and reload.Value == true or reloading and reloading.Value == true or false
                )
            end
        elseif key == 'GunFiring' then
            Local_Parts.GunFiring = value
            if value and value.Value == false and phowg.queue_loadout_ammo_check then
                phowg:queue_loadout_ammo_check(character)
            end
        elseif key == 'Grabbed' then
            Local_Data.carrying = value and value.Value or nil
            Local_Data.Carrying = Local_Data.carrying
        elseif key == 'Attacking' then
            Local_Parts.Attacking = value
            if value and value.Value == true then
                Data.RecentlyAttacked = tick()
                local tool = character:FindFirstChildOfClass('Tool')
                if changed and phowg.play_skin_attack and tool and tool:GetAttribute('Attacking') == nil then
                    phowg:play_skin_attack(tool)
                end
            end
        else
            Local_Parts[key] = value
            Local_Data[key] = value and value.Value or nil
        end
    end
    local function release(key)
        local name = 'LocalData/' .. key
        local connection = record.Connections[name]
        if connection then
            connection:Disconnect()
            record.Connections[name] = nil
            if Connections[name] == connection then
                Connections[name] = nil
            end
            local index = table.find(Library.Signals, connection)
            if index then
                table.remove(Library.Signals, index)
            end
        end
    end
    local function observe(value, changed)
        local key = value.Name
        if not active() or not tracked[key] or not value:IsA('ValueBase') or record.Values[key] == value then
            return
        end
        release(key)
        record.Values[key] = value
        local name = 'LocalData/' .. key
        record.Connections[name] = create_connection(
            name,
            connectshared(value:GetPropertyChangedSignal('Value'), function()
                if record.Values[key] == value then
                    sync(key, true)
                end
            end, value, 'character data/value', -100, 'property/Value', value)
        )
        sync(key, changed)
    end
    record.Connections['LocalData/Added'] = create_connection(
        'LocalData/Added',
        connectshared(bodyEffects.ChildAdded, function(value)
            observe(value, true)
        end, bodyEffects, 'character data/added', -100, 'event/ChildAdded', bodyEffects)
    )
    record.Connections['LocalData/Removed'] = create_connection(
        'LocalData/Removed',
        connectshared(bodyEffects.ChildRemoved, function(value)
            local key = value.Name
            if not active() or record.Values[key] ~= value then
                return
            end
            release(key)
            record.Values[key] = nil
            local replacement = bodyEffects:FindFirstChild(key)
            if replacement then
                observe(replacement, true)
            else
                sync(key, true)
            end
        end, bodyEffects, 'character data/removed', -100, 'event/ChildRemoved', bodyEffects)
    )
    for _, value in ipairs(bodyEffects:GetChildren()) do
        observe(value, false)
    end
    updatesuspension()
end
local function track_dead(character)
    phowg:bind_local_data(character)
    if phowg.queue_auto_armor then
        phowg:queue_auto_armor('Armor')
        phowg:queue_auto_armor('FireArmor')
    end
end
function alivedrawing(d)
    if d == nil then
        return false
    end
    local ok, vis = pcall(function()
        return d.Visible
    end)
    if not ok then
        return false
    end
    local ok2 = pcall(function()
        d.Visible = vis
    end)
    return ok2
end
function newdrawingline(color, thickness, z)
    if not (Drawing and Drawing.new) then
        return nil
    end
    local ok, line = pcall(function()
        return Drawing.new('Line')
    end)
    if not (ok and line) then
        return nil
    end
    line.Color = color or Color3.fromRGB(255, 255, 255)
    line.Thickness = thickness or 1
    line.Transparency = 1
    line.Visible = false
    if z then
        line.ZIndex = z
    end
    return line
end
function newdrawingcircle()
    if not (Drawing and Drawing.new) then
        return nil
    end
    local ok, c = pcall(function()
        local cc = Drawing.new('Circle')
        cc.Thickness = 1
        cc.Filled = false
        cc.NumSides = 64
        cc.Visible = false
        cc.ZIndex = 2
        return cc
    end)
    if not (ok and c) then
        return nil
    end
    pcall(function()
        c.Transparency = 1
    end)
    return c
end
function circleworks()
    if Data['CircleOK'] ~= nil then
        return Data['CircleOK']
    end
    local ok = false
    if Drawing and Drawing.new then
        local okNew, c = pcall(function()
            return Drawing.new('Circle')
        end)
        if okNew and c then
            local okProps = pcall(function()
                c.Radius = 150
                c.Visible = false
                if c.Radius ~= 150 then
                    error('bad circle')
                end
            end)
            pcall(function()
                if c.Remove then
                    c:Remove()
                end
            end)
            ok = okProps
        end
    end
    Data['CircleOK'] = ok
    return ok
end
function phowg:update_main_fov(prefix, mousePos, radius, color, show)
    Data.MainFOVViews = Data.MainFOVViews or {}
    local view = Data.MainFOVViews[prefix]
    if not show then
        if view then
            view.Root.Visible = false
        end
        return
    end
    if not Data.StatusGui or not Data.StatusGui.Parent then
        return
    end
    if not view or not view.Root.Parent then
        local root = Instance.new('Frame')
        root.Name = prefix .. ' fov'
        root.AnchorPoint = Vector2.new(0.5, 0.5)
        root.BackgroundTransparency = 1
        root.BorderSizePixel = 0
        root.ZIndex = 2
        root.Parent = Data.StatusGui
        local corner = Instance.new('UICorner')
        corner.CornerRadius = UDim.new(1, 0)
        corner.Parent = root
        local outline = Instance.new('UIStroke')
        outline.Thickness = 3
        outline.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
        outline.Parent = root
        local face = Instance.new('Frame')
        face.Size = UDim2.fromScale(1, 1)
        face.BackgroundTransparency = 1
        face.BorderSizePixel = 0
        face.ZIndex = 3
        face.Parent = root
        local faceCorner = Instance.new('UICorner')
        faceCorner.CornerRadius = UDim.new(1, 0)
        faceCorner.Parent = face
        local stroke = Instance.new('UIStroke')
        stroke.Thickness = 1
        stroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
        stroke.Parent = face
        view = { Root = root, Face = face, Stroke = stroke, Outline = outline }
        Data.MainFOVViews[prefix] = view
    end
    local filled = Toggles[prefix .. '_fov_filled']
    local outlined = Toggles[prefix .. '_fov_outline']
    local fillColor = Options[prefix .. '_fov_fill_color']
    local outlineColor = Options[prefix .. '_fov_outline_color']
    view.Root.Position = UDim2.fromOffset(mousePos.X, mousePos.Y)
    view.Root.Size = UDim2.fromOffset(radius * 2, radius * 2)
    view.Root.Visible = true
    view.Stroke.Color = color
    view.Face.BackgroundColor3 = fillColor and fillColor.Value or Color3.new(1, 1, 1)
    view.Face.BackgroundTransparency = filled
            and filled.Value
            and math.clamp(fillColor and fillColor.Transparency or 0.85, 0, 1)
        or 1
    view.Outline.Color = outlineColor and outlineColor.Value or Color3.new(1, 1, 1)
    view.Outline.Enabled = outlined and outlined.Value or false
end
phowg:register_cleanup('main aim fov', function(scope, reason)
    if reason == 'unload' or scope == LocalPlayer.Character or scope == Data.ManagedCharacter then
        for _, view in pairs(Data.MainFOVViews or {}) do
            view.Root:Destroy()
        end
        Data.MainFOVViews = nil
    end
end)
function updatefovring(poolKey, mousePos, radius, color, show)
    local pool = Data[poolKey]
    if not pool then
        pool = {}
        Data[poolKey] = pool
    end
    local N = 40
    if show then
        for i = 1, N do
            local a1 = (i - 1) / N * math.pi * 2
            local a2 = i / N * math.pi * 2
            local line = pool[i]
            if not alivedrawing(line) then
                line = newdrawingline(color, 1, 2)
                pool[i] = line
            end
            if line then
                local okDraw = pcall(function()
                    line.From = mousePos + Vector2.new(math.cos(a1) * radius, math.sin(a1) * radius)
                    line.To = mousePos + Vector2.new(math.cos(a2) * radius, math.sin(a2) * radius)
                    line.Color = color
                    line.Visible = true
                end)
                if not okDraw then
                    pool[i] = nil
                end
            end
        end
    end
    for i = (show and N or 0) + 1, #pool do
        if pool[i] then
            pool[i].Visible = false
        end
    end
end
function rebuilddrawings()
    for _, l in pairs(Data['GrenadeTracerPool'] or {}) do
        pcall(function()
            if l and l.Remove then
                l:Remove()
            end
        end)
    end
    Data['GrenadeTracerPool'] = {}
    for _, key in ipairs({ 'SilentFOVRing', 'StickyFOVRing', 'AssistFOVRing' }) do
        for _, l in pairs(Data[key] or {}) do
            pcall(function()
                if l and l.Remove then
                    l:Remove()
                end
            end)
        end
        Data[key] = nil
    end
    if Data.RebuildAimDrawings then
        pcall(Data.RebuildAimDrawings)
    end
end
function healdrawings()
    if not alivedrawing(Data['TargetVisualTracer']) then
        Data['TargetVisualTracer'] = nil
    end
    if Data['CrosshairLines'] then
        for i, l in pairs(Data['CrosshairLines']) do
            if not alivedrawing(l) then
                Data['CrosshairLines'][i] = nil
            end
        end
    end
    if Data['GrenadeTracerPool'] then
        for i, l in pairs(Data['GrenadeTracerPool']) do
            if not alivedrawing(l) then
                Data['GrenadeTracerPool'][i] = nil
            end
        end
    end
    rebuilddrawings()
end
function drawinghealthtick()
    local now = tick()
    if now - (Data['DrawingHealthAt'] or 0) < 2 then
        return
    end
    Data['DrawingHealthAt'] = now
    local dead = 0
    local function sweep(pool)
        if not pool then
            return
        end
        for i, l in pairs(pool) do
            if not alivedrawing(l) then
                pool[i] = nil
                dead = dead + 1
            end
        end
    end
    if not alivedrawing(Data['TargetVisualTracer']) then
        Data['TargetVisualTracer'] = nil
    end
    sweep(Data['CrosshairLines'])
    sweep(Data['GrenadeTracerPool'])
    sweep(Data['SilentFOVRing'])
    sweep(Data['StickyFOVRing'])
    sweep(Data['AssistFOVRing'])
    if dead > 0 and Data.RebuildAimDrawings then
        pcall(Data.RebuildAimDrawings)
    end
end
registerheartbeat('DrawingHealth', drawinghealthtick)
function getorcreategrenadetracer(Index)
    if not alivedrawing(Data['GrenadeTracerPool'][Index]) then
        Data['GrenadeTracerPool'][Index] = newdrawingline(Color3.fromRGB(255, 80, 80), 1.5)
    end
    return Data['GrenadeTracerPool'][Index]
end
function phowg:restore_material_part(part, cache)
    local original = cache and cache[part]
    if not original then
        return
    end
    if original.m ~= nil then
        pcall(function()
            part.Material = original.m
        end)
    end
    if original.c ~= nil then
        pcall(function()
            part.Color = original.c
        end)
    end
    cache[part] = nil
end
function phowg:material_appearance(object, flat, cache)
    local record = cache[object]
    if not flat then
        if not record then
            return
        end
        cache[object] = nil
        for property, value in pairs(record.Properties or {}) do
            pcall(function()
                object[property] = value
            end)
        end
        if record.Parent then
            local restored = pcall(function()
                object.Parent = record.Parent
            end)
            if not restored then
                pcall(function()
                    object:Destroy()
                end)
            end
        end
        return
    end
    local properties = {}
    if object:IsA('BasePart') then
        properties[#properties + 1] = 'MaterialVariant'
    end
    if object:IsA('MeshPart') then
        properties[#properties + 1] = 'TextureID'
    elseif object:IsA('SpecialMesh') then
        properties[#properties + 1] = 'TextureId'
    elseif object:IsA('Decal') or object:IsA('Texture') then
        properties[#properties + 1] = 'Texture'
    elseif object:IsA('Shirt') then
        properties[#properties + 1] = 'ShirtTemplate'
    elseif object:IsA('Pants') then
        properties[#properties + 1] = 'PantsTemplate'
    elseif object:IsA('ShirtGraphic') then
        properties[#properties + 1] = 'Graphic'
    elseif object:IsA('CharacterMesh') then
        properties[#properties + 1] = 'BaseTextureId'
        properties[#properties + 1] = 'OverlayTextureId'
    end
    if object:IsA('SurfaceAppearance') then
        if not record and object.Parent then
            record = { Parent = object.Parent, Properties = {} }
            cache[object] = record
        end
        if record and object.Parent then
            object.Parent = nil
        end
    end
    for _, property in ipairs(properties) do
        local ok, value = pcall(function()
            return object[property]
        end)
        if ok and (type(value) == 'string' or type(value) == 'number') then
            if not record then
                record = { Properties = {} }
                cache[object] = record
            end
            if record.Properties[property] == nil then
                record.Properties[property] = value
            end
            local blank = type(value) == 'number' and 0 or ''
            if value ~= blank then
                pcall(function()
                    object[property] = blank
                end)
            end
        end
    end
end
function phowg:restore_material_appearances(cache)
    for object in pairs(cache or {}) do
        phowg:material_appearance(object, false, cache)
    end
end
function visualstyle()
    local matName = (Options and Options.local_desynced_position_value and Options.local_desynced_position_value.Value)
        or 'forcefield'
    local col = (Options and Options.local_desynced_position_color and Options.local_desynced_position_color.Value)
        or Color3.fromRGB(255, 255, 255)
    local mat = Enum.Material.ForceField
    if matName == 'neon' then
        mat = Enum.Material.Neon
    end
    return mat, col, matName == 'original'
end
function hidevisualizer()
    if phowg.clear_desync_aura then phowg:clear_desync_aura() end
    Data['VisualShown'] = false
    local model = Data['VisualizeModel']
    local state = Data['VisualPhysicsState']
    if model and Data.VisualParkedModel ~= model then
        local parts = state and state.Model == model and state.Parts or model:GetDescendants()
        for _, ghost in pairs(parts) do
            if ghost:IsA('BasePart') and ghost.Parent then
                ghost.CanCollide, ghost.CanTouch, ghost.CanQuery = false, false, false
                ghost.Transparency = 1
            end
        end
        if model.PrimaryPart and model.PrimaryPart.Parent then
            model:SetPrimaryPartCFrame(CFrame.new(1000, 1000, 1000))
        end
        model.Parent = nil
        Data.VisualParkedModel = model
    end
    local hl = Data['VisualizeHighlight']
    if hl then
        hl.Enabled = false
    end
end
function phowg:bind_visual_physics(model)
    local state = { Model = model, Parts = {}, Seen = {}, Connections = {} }
    Data['VisualPhysicsState'] = state
    local function bind(part)
        if not part:IsA('BasePart') or state.Seen[part] then
            return
        end
        state.Seen[part] = true
        state.Parts[#state.Parts + 1] = part
        part.Anchored, part.CanCollide, part.CanTouch, part.CanQuery, part.Massless = true, false, false, false, true
        if not Data['VisualShown'] then
            part.Transparency = 1
        end
        for _, property in ipairs({ 'CanCollide', 'CanTouch', 'CanQuery' }) do
            state.Connections[#state.Connections + 1] = part:GetPropertyChangedSignal(property):Connect(function()
                if part[property] then
                    part[property] = false
                end
            end)
        end
    end
    for _, part in ipairs(model:GetDescendants()) do
        bind(part)
    end
    state.Connections[#state.Connections + 1] = model.DescendantAdded:Connect(bind)
    state.Connections[#state.Connections + 1] = model.Destroying:Connect(function()
        if Data.VisualizeModel == model then
            phowg:restore_material_appearances(Data.VisualAppearance)
            Data.VisualAppearance, Data.VisualAppearanceOriginal = nil, nil
        end
        for _, connection in ipairs(state.Connections) do
            connection:Disconnect()
        end
        table.clear(state.Connections)
        table.clear(state.Parts)
        table.clear(state.Seen)
        if Data['VisualPhysicsState'] == state then
            Data['VisualPhysicsState'] = nil
        end
    end)
end

function phowg:clone_visual_character(character, includeTool)
    local archivable = character.Archivable
    character.Archivable = true
    local ok, model = pcall(function()
        return character:Clone()
    end)
    character.Archivable = archivable
    if not ok or not model then
        return nil
    end
    for _, child in ipairs(model:GetChildren()) do
        if
            not (
                child:IsA('BasePart')
                or child:IsA('Accessory')
                or child:IsA('Humanoid')
                or child:IsA('Clothing')
                or child:IsA('ShirtGraphic')
                or child:IsA('BodyColors')
                or child:IsA('CharacterMesh')
                or includeTool and child:IsA('Tool')
            )
            or child.Name == 'Cuff'
            or child.Name == 'Cuffs'
        then
            child:Destroy()
        end
    end
    for _, child in ipairs(model:GetDescendants()) do
        if
            child:IsA('LuaSourceContainer')
            or child:IsA('Animator')
            or child:IsA('Sound')
            or child:IsA('ParticleEmitter')
            or child:IsA('Trail')
            or child:IsA('Beam')
            or child:IsA('GuiBase3d')
            or child:IsA('LayerCollector')
            or child:IsA('BodyMover')
            or child:IsA('Constraint')
            or child:IsA('JointInstance')
        then
            child:Destroy()
        elseif child:IsA('BasePart') then
            child.Anchored, child.CanCollide, child.CanTouch, child.CanQuery, child.CastShadow, child.Massless =
                true, false, false, false, false, true
            child.LocalTransparencyModifier = 0
        end
    end
    local humanoid = model:FindFirstChildOfClass('Humanoid')
    if not humanoid then
        humanoid = Instance.new('Humanoid')
        local source = character:FindFirstChildOfClass('Humanoid')
        if source then
            humanoid.RigType = source.RigType
        end
        humanoid.Parent = model
    end
    humanoid.DisplayDistanceType = Enum.HumanoidDisplayDistanceType.None
    humanoid.AutoRotate, humanoid.BreakJointsOnDeath, humanoid.RequiresNeck = false, false, false
    humanoid.Health, humanoid.MaxHealth = 100, 100
    pcall(function()
        humanoid.EvaluateStateMachine = false
    end)
    model.PrimaryPart = model:FindFirstChild('HumanoidRootPart')
    return model
end
function buildvisualizer(char)
    local target = char or (LocalPlayer and LocalPlayer.Character)
    if not target or not target.Parent or not target:FindFirstChild('HumanoidRootPart') then
        return false
    end
    local model = phowg:clone_visual_character(target, true)
    if not model then
        return false
    end
    phowg:restore_material_appearances(Data.VisualAppearance)
    if phowg.clear_desync_aura then phowg:clear_desync_aura() end
    if Data['VisualizeModel'] then
        Data['VisualizeModel']:Destroy()
    end
    Data.VisualAppearance, Data.VisualAppearanceOriginal = {}, nil
    model.Name = 'visualize'
    Data['VisualizeModel'], Data['VisualParts'], Data['VisualToolParts'], Data['VisualPose'] = model, {}, {}, {}
    Data['VisualCharacter'], Data['VisualShown'] = target, false
    phowg:bind_visual_physics(model)
    Data.VisualSourceParts = {}
    for _, part in ipairs(model:GetChildren()) do
        if part:IsA('BasePart') then
            Data['VisualParts'][part.Name] = part
            Data.VisualSourceParts[part.Name] = target:FindFirstChild(part.Name)
            part.Transparency = 1
        elseif part:IsA('Accessory') then
            local source = target:FindFirstChild(part.Name)
            local handle, sourceHandle = part:FindFirstChild('Handle'), source and source:FindFirstChild('Handle')
            if handle and sourceHandle then
                handle.Transparency = 1
                Data['VisualToolParts'][#Data['VisualToolParts'] + 1] = { ghost = handle, source = sourceHandle }
            end
        elseif part:IsA('Tool') then
            local tool = target:FindFirstChild(part.Name)
            for _, ghost in ipairs(part:GetDescendants()) do
                if ghost:IsA('BasePart') then
                    ghost.Transparency = 1
                    local source = tool and tool:FindFirstChild(ghost.Name, true)
                    if
                        source
                        and source:IsA('BasePart')
                        and ghost.Name ~= 'Handle'
                        and ghost.Name ~= 'Cuff'
                        and ghost.Name ~= 'Cuffs'
                    then
                        Data['VisualToolParts'][#Data['VisualToolParts'] + 1] = { ghost = ghost, source = source }
                    end
                end
            end
        end
    end
    local hl = Instance.new('Highlight')
    hl.Name, hl.Adornee, hl.DepthMode = 'VisualizeHighlight', model, Enum.HighlightDepthMode.AlwaysOnTop
    hl.FillTransparency, hl.OutlineTransparency, hl.Enabled, hl.Parent = 0.5, 0, false, model
    Data['VisualizeHighlight'] = hl
    Data.VisualDirty = false
    local connections = Data.VisualPhysicsState.Connections
    local function changed(child)
        if Data.VisualizeModel ~= model then
            return
        end
        if
            child:IsA('BasePart')
            or child:IsA('Accessory')
            or child:IsA('Tool')
            or child:IsA('Clothing')
            or child:IsA('ShirtGraphic')
            or child:IsA('BodyColors')
            or child:IsA('CharacterMesh')
        then
            Data.VisualDirty = true
        end
    end
    connections[#connections + 1] = target.ChildAdded:Connect(changed)
    connections[#connections + 1] = target.ChildRemoved:Connect(changed)
    local function tool_part(child)
        if
            child:IsA('BasePart')
            and (child:FindFirstAncestorOfClass('Tool') or child:FindFirstAncestorOfClass('Accessory'))
        then
            changed(child)
        end
    end
    connections[#connections + 1] = target.DescendantAdded:Connect(tool_part)
    connections[#connections + 1] = target.DescendantRemoving:Connect(tool_part)
    for _, child in ipairs(target:GetChildren()) do
        if
            child:IsA('Clothing')
            or child:IsA('ShirtGraphic')
            or child:IsA('BodyColors')
            or child:IsA('CharacterMesh')
        then
            connections[#connections + 1] = child.Changed:Connect(function()
                changed(child)
            end)
        end
    end
    hidevisualizer()
    return true
end
function phowg:session_visualizer_active(tag)
    if tag == 'FakePosition' then
        local state = Data.FakePosition
        return state ~= nil
            and not state.Paused
            and state.Character == LocalPlayer.Character
            and not phowg:fake_position_blocked()
    end
    if tag == 'RagebotIdle' then
        return phowg:ragebot_idle_hiding(Data.RagebotIdle)
    end
    if tag == 'VoidSpamOut' then
        return phowg:void_spam_out_active() and not Data.Buying
    end
    if tag == 'Void' or tag == 'VoidTwitch' then
        return Data.VoidActive == true and not Data.Buying
    elseif tag == 'ReloadVoid' then
        return reloadvoidactive() and not Data.Buying
    elseif tag == 'RagebotVoid' then
        return phowg:ragebot_void_move_valid(Data.RagebotVoidSpam)
    elseif tag == 'Buy' then
        return Data.Buying == true
    elseif tag == 'PurchaseVoidReturn' then
        return phowg:purchase_void_return_valid(Data.PurchaseVoidReturn)
    end
    if tag == 'TargetStrafe' then
        local target = Data.TargetStrafeTarget
        return Data.TargetStrafeActive == true
            and phowg:toggle_enabled('target_strafe_enabled')
            and target ~= nil
            and target.Parent ~= nil
            and target.Character ~= nil
    elseif tag == 'Underground' then
        return Data.UndergroundActive == true
            and phowg:toggle_enabled('underground')
            and not Data.Buying
            and not Data.VoidActive
    elseif tag == 'Desync' then
        return Data.DesyncActive == true
            and phowg:toggle_enabled('desync_rotation')
            and not Data.Buying
            and not Data.VoidActive
    end
    return true
end
function phowg:server_display_position(character, root)
    local tag, now = Data.AppliedServerTag, tick()
    local active = phowg:session_visualizer_active(tag)
    if tag == 'Combat' then
        active = (rageboton() or punishmentactive()) and Data.CurrentActionTarget ~= nil
    elseif tag == 'KillAura' then
        active = killauraenabled() and Toggles.full_rage and Toggles.full_rage.Value and Data.KillAuraTarget ~= nil
    elseif isrpgmovementtag(tag, false) then
        active = Data.RPGMoveActive
    end
    local age = now - (Data.AppliedServerAt or -math.huge)
    local inFlight = Data.MoveToInFlight == root
    local hold = Data.AppliedServerHold
    local held = hold and validmovetohold(hold)
    local buying = tag == 'Buy' and Data.Buying == true
    if
        active
        and Data.AppliedServerCharacter == character
        and typeof(Data.AppliedServerCF) == 'CFrame'
        and age >= 0
        and (inFlight or held or buying or age < 0.2)
    then
        return Data.AppliedServerCF.Position, Data.AppliedServerCF, age, true, tag
    end
    local pending = phowg.pending_server_movement and phowg:pending_server_movement()
    if pending then
        return pending.cf.Position, pending.cf, now - pending.t, true, pending.tag
    end
    local fakeFrame, fakeAge = phowg:fake_position_snapshot(character, root)
    if fakeFrame then
        return fakeFrame.Position, fakeFrame, fakeAge, true, 'FakePosition'
    end
    return root.Position, root.CFrame, 0, false, nil
end
function syncvisualizer(_appliedCFrame: CFrame?, sourceCFrame: CFrame?)
    local on = Toggles
        and Toggles.local_desynced_position
        and Toggles.local_desynced_position.Value
        and not localactionblocked()
    if not on then
        hidevisualizer()
        return
    end
    local char = LocalPlayer and LocalPlayer.Character or nil
    local hrp = char and char:FindFirstChild('HumanoidRootPart') or nil
    local hum = char and char:FindFirstChildOfClass('Humanoid') or nil
    if not (char and hrp and hrp.Parent and hum and hum.Health > 0) then
        hidevisualizer()
        return
    end

    local _, dest, _, active, tag = phowg:server_display_position(char, hrp)
    Data.FakePositionVisualized = active and tag == 'FakePosition'
    if not active or typeof(dest) ~= 'CFrame' then
        hidevisualizer()
        return
    end

    local savedClientFrame = Data.MoveToInFlight == hrp
        and Data.CSyncTable
        and Data.CSyncTable[2]
        and Data.CSyncTable[1]
    local clientFrame = sourceCFrame or (typeof(savedClientFrame) == 'CFrame' and savedClientFrame) or hrp.CFrame
    if (dest.Position - clientFrame.Position).Magnitude < 3 then
        hidevisualizer()
        return
    end
    local dx, dy, dz = dest.X, dest.Y, dest.Z
    if dx ~= dx or dy ~= dy or dz ~= dz or dest.Position.Magnitude > 100000000 then
        hidevisualizer()
        return
    end

    local model = Data['VisualizeModel']
    if Data.VisualDirty then
        buildvisualizer(char)
        model = Data.VisualizeModel
    end
    if
        not model
        or Data['VisualCharacter'] ~= char
        or not Data['VisualParts']
        or not Data['VisualParts']['HumanoidRootPart']
        or not Data['VisualParts']['HumanoidRootPart'].Parent
    then
        buildvisualizer(char)
        model = Data['VisualizeModel']
    end
    if not model then
        hidevisualizer()
        return
    end

    local mat, col, useOrig = visualstyle()
    if Data.VisualAppearanceOriginal ~= useOrig then
        Data.VisualAppearance = Data.VisualAppearance or {}
        if useOrig then
            phowg:restore_material_appearances(Data.VisualAppearance)
        else
            for _, object in ipairs(model:GetDescendants()) do
                phowg:material_appearance(object, true, Data.VisualAppearance)
            end
        end
        Data.VisualAppearanceOriginal = useOrig
    end
    local hl = Data['VisualizeHighlight']
    if not hl or hl.Parent ~= model then
        if hl then
            pcall(function()
                hl:Destroy()
            end)
        end
        hl = Instance.new('Highlight')
        hl.Name = 'VisualizeHighlight'
        hl.Adornee = model
        hl.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
        hl.FillColor = col
        hl.FillTransparency = useOrig and 1 or 0.5
        hl.OutlineTransparency = 0
        hl.OutlineColor = col
        hl.Enabled = true
        hl.Parent = model
        Data['VisualizeHighlight'] = hl
    else
        hl.Adornee = model
        hl.FillColor = col
        hl.FillTransparency = useOrig and 1 or 0.5
        hl.OutlineColor = col
        hl.Enabled = true
    end

    local hrpCF = sourceCFrame or hrp.CFrame
    local pose = Data.VisualPose
    if not pose then
        pose = {}
        Data.VisualPose = pose
    end
    local refreshPose = sourceCFrame ~= nil
        or Data.MoveToInFlight ~= hrp
        or not (Data.CSyncTable and Data.CSyncTable[2])
    local base = dest
    local userAlpha = (
        Options
        and Options.local_desynced_position_color
        and Options.local_desynced_position_color.Transparency
    ) or 0.2

    local function show(ghost, source, isRoot)
        if ghost and ghost.Parent and source and source.Parent then
            local offset = isRoot and CFrame.identity or pose[ghost]
            if not isRoot and (refreshPose or not offset) then
                local sc = source.CFrame
                if sc.X ~= sc.X or sc.Y ~= sc.Y or sc.Z ~= sc.Z then
                    return
                end
                local reference = hrpCF
                if
                    not refreshPose
                    and typeof(savedClientFrame) == 'CFrame'
                    and (sc.Position - savedClientFrame.Position).Magnitude
                        < (sc.Position - reference.Position).Magnitude
                then
                    reference = savedClientFrame
                end
                offset = reference:ToObjectSpace(sc)
                pose[ghost] = offset
            end
            if useOrig then
                ghost.Material = source.Material
                ghost.Color = source.Color
                ghost.Transparency = source.Transparency
            else
                ghost.Material = mat
                ghost.Color = col
                ghost.Transparency = isRoot and 1 or math.max(source.Transparency, userAlpha)
            end
            ghost.CFrame = base * offset
        end
    end

    for name, ghost in pairs(Data['VisualParts'] or {}) do
        local live = Data.VisualSourceParts and Data.VisualSourceParts[name]
        if live and live.Parent then
            show(ghost, live, name == 'HumanoidRootPart')
        end
    end

    for _, entry in ipairs(Data['VisualToolParts'] or {}) do
        show(entry.ghost, entry.source, false)
    end

    if not model.PrimaryPart or not model.PrimaryPart.Parent then
        hidevisualizer()
        return
    end
    Data.VisualParkedModel = nil
    Data['VisualShown'] = true
    if model.Parent ~= Workspace then
        model.Parent = Workspace
    end
end
function phowg:update_session_visualizer(delta)
    if phowg:toggle_enabled('server_position_indicator') and serverpositionindicatortick then
        serverpositionindicatortick(delta or 0)
    end
    if phowg:toggle_enabled('local_desynced_position') then
        syncvisualizer()
    elseif Data.VisualShown then
        hidevisualizer()
    end
end
function phowg:set_session_visualizer_updates()
    local enabled = phowg:toggle_enabled('local_desynced_position') or phowg:toggle_enabled('server_position_indicator')
    local previous = Connections.SessionVisualizer
    if Library.Unloaded or Data.SharedSignalsClosed then
        enabled = false
    end
    if not enabled then
        if previous then
            previous:Disconnect()
            Connections.SessionVisualizer = nil
        end
        hidevisualizer()
    elseif not previous then
        create_connection(
            'SessionVisualizer',
            phowg:register_render(phowg_callbacks.update_session_visualizer, RunService, 'frame/position visuals')
        )
    end
    if serverpositionindicatortick then
        serverpositionindicatortick(0)
    end
    if enabled then
        phowg:update_session_visualizer()
    end
end
function phowg:attach_spoof_accessory(accessory, char, applyScaling)
    if applyScaling then
        local humanoid = char:FindFirstChildOfClass('Humanoid')
        if humanoid then
            pcall(function()
                humanoid:AddAccessory(accessory)
            end)
        end
    end
    local handle = accessory:FindFirstChild('Handle')
    if not handle or not handle:IsA('BasePart') then
        return false
    end
    local attachment, bodyAttachment
    for _, candidate in ipairs(handle:GetChildren()) do
        if candidate:IsA('Attachment') then
            for _, part in ipairs(char:GetChildren()) do
                if part:IsA('BasePart') then
                    local match = part:FindFirstChild(candidate.Name)
                    if match and match:IsA('Attachment') then
                        attachment, bodyAttachment = candidate, match
                        break
                    end
                end
            end
            if bodyAttachment then
                break
            end
        end
    end
    local body = bodyAttachment and bodyAttachment.Parent or char:FindFirstChild('Head')
    if not body or not body:IsA('BasePart') then
        return false
    end
    for _, descendant in ipairs(accessory:GetDescendants()) do
        if descendant:IsA('BasePart') then
            descendant.Anchored, descendant.CanCollide, descendant.CanTouch, descendant.CanQuery, descendant.Massless =
                false, false, false, false, true
        elseif
            descendant:IsA('JointInstance')
            and (descendant.Name == 'AccessoryWeld' or descendant.Part0 == handle or descendant.Part1 == handle)
        then
            local other = descendant.Part0 == handle and descendant.Part1 or descendant.Part0
            if not other or not other:IsDescendantOf(accessory) then
                descendant:Destroy()
            end
        end
    end
    local c0 = bodyAttachment and bodyAttachment.CFrame or CFrame.new(0, body.Size.Y * 0.5, 0)
    local c1 = attachment and attachment.CFrame or accessory.AttachmentPoint
    handle.CFrame = body.CFrame * c0 * c1:Inverse()
    handle.AssemblyLinearVelocity, handle.AssemblyAngularVelocity = Vector3.zero, Vector3.zero
    local weld = Instance.new('Weld')
    weld.Name, weld.Part0, weld.Part1, weld.C0, weld.C1, weld.Parent = 'AccessoryWeld', body, handle, c0, c1, handle
    accessory.Parent = char
    return true
end
function createattachment(Accessory, Name, TargetChar)
    local char = TargetChar or (LocalPlayer and LocalPlayer.Character) or nil
    if not (Accessory and char and char.Parent) then
        return
    end
    Data['SpoofAccObjCache'] = Data['SpoofAccObjCache'] or {}
    Data['SpoofAccFail'] = Data['SpoofAccFail'] or {}
    if type(Accessory) == 'number' then
        local cached = Data['SpoofAccObjCache'][Accessory]
        if cached then
            Accessory = cached:Clone()
        else
            if Data['SpoofAccFail'][Accessory] then
                return
            end
            local ok, objs = pcall(function()
                return game:GetObjects('rbxassetid://' .. Accessory)
            end)
            if ok and objs and objs[1] then
                Data['SpoofAccObjCache'][Accessory] = objs[1]
                Accessory = objs[1]:Clone()
            else
                Data['SpoofAccFail'][Accessory] = true
                return
            end
        end
    end
    if not Accessory then
        return
    end
    if not char.Parent then
        return
    end
    Accessory.Name = Name
    if not phowg:attach_spoof_accessory(Accessory, char, true) then
        Accessory:Destroy()
    end
end
function removeattachment(Name)
