        return
    end
    local Accessory = LocalPlayer.Character:FindFirstChild(Name)
    if not Accessory then
        return
    end
    for _, Obj in pairs(Accessory:GetDescendants()) do
        if Obj:IsA('Weld') or Obj:IsA('WeldConstraint') then
            Obj:Destroy()
        end
    end
    Accessory:Destroy()
end
function phowg:queue_background(lane, key, callback, optional)
    if Data.SharedSignalsClosed or Library.Unloaded then
        return
    end
    Data.BackgroundQueues = Data.BackgroundQueues or {}
    local queue = Data.BackgroundQueues[lane]
    if not queue then
        queue = { Items = {}, Keys = {}, Head = 1, Tail = 0, Name = lane }
        Data.BackgroundQueues[lane] = queue
    end
    local entry = queue.Keys[key]
    if entry then
        entry.Callback, entry.Revision = callback, entry.Revision + 1
        entry.Optional = entry.Optional and optional == true
        return
    end
    entry = { Key = key, Callback = callback, Revision = 1, Optional = optional == true }
    queue.Tail += 1
    queue.Items[queue.Tail], queue.Keys[key] = entry, entry
end
function phowg:run_background_work()
    if not Data.StartupReady or Library.SuppressSave or Data.SharedSignalsClosed then
        return
    end
    local started = os.clock()
    while (Data.BackgroundActive or 0) < 4 and os.clock() - started < 0.002 do
        local selected, score
        for lane, queue in pairs(Data.BackgroundQueues or {}) do
            local ready = not queue.Worker
                and queue.Head <= queue.Tail
                and (lane ~= 'startup asset warmup' or not Library.StartupIntro or Library.StartupIntroPlayed)
                and (lane ~= 'protection' or (Data.ShieldActiveChecks or 0) == 0)
                and tick() >= (queue.ReadyAt or 0)
            local first = queue.Items[queue.Head]
            local priority = lane == 'protection' and 0
                or lane == 'metadata' and 1
                or (first and first.Optional or lane:find('warmup', 1, true)) and 3
                or 2
            if ready and (not score or priority < score) then
                selected, score = queue, priority
            end
        end
        if not selected then
            break
        end
        local queue = selected
        local entry = queue.Items[queue.Head]
        queue.Items[queue.Head], queue.Head = nil, queue.Head + 1
        local revision = entry.Revision
        local worker = coroutine.create(function()
            entry.Running = true
            local ok, problem = pcall(entry.Callback)
            entry.Running, queue.Worker = false, nil
            Data.BackgroundActive = math.max(0, (Data.BackgroundActive or 1) - 1)
            queue.ReadyAt = tick() + (queue.Name == 'metadata' and 0.05 or 0)
            if Data.SharedSignalsClosed or Library.Unloaded then
                return
            end
            if not ok then
                Data.BackgroundFailures = (Data.BackgroundFailures or 0) + 1
                warn('[phowg] background ' .. queue.Name .. ': ' .. tostring(problem))
            end
            if entry.Revision ~= revision then
                queue.Tail += 1
                queue.Items[queue.Tail] = entry
            else
                queue.Keys[entry.Key] = nil
            end
            if queue.Head > queue.Tail then
                table.clear(queue.Items)
                queue.Head, queue.Tail = 1, 0
            end
        end)
        queue.Worker = worker
        Data.BackgroundActive = (Data.BackgroundActive or 0) + 1
        task.spawn(worker)
    end
end
registerheartbeat('BackgroundWork', phowg.run_background_work, 0, function()
    for _, queue in pairs(Data.BackgroundQueues or {}) do
        if queue.Head <= queue.Tail then
            return true
        end
    end
    return false
end, true)
phowg:register_cleanup('background work', function(_, reason)
    if reason ~= 'unload' then
        return
    end
    for _, queue in pairs(Data.BackgroundQueues or {}) do
        if queue.Worker and queue.Worker ~= coroutine.running() then
            pcall(task.cancel, queue.Worker)
        end
        table.clear(queue.Items)
        table.clear(queue.Keys)
        queue.Worker = nil
    end
    Data.BackgroundActive = 0
end)
function fetchgroupname(CrewId)
    local NumId = tonumber(CrewId)
    if not NumId then
        return tostring(CrewId)
    end
    if Data['CrewNameCache'][NumId] then
        return Data['CrewNameCache'][NumId]
    end
    local nowG = tick()
    if Data['CrewNameAt'][NumId] and nowG - Data['CrewNameAt'][NumId] < 5 then
        return tostring(CrewId)
    end
    if Data['CrewNameFailAt'][NumId] and nowG - Data['CrewNameFailAt'][NumId] < 5 then
        return tostring(CrewId)
    end
    Data['CrewNameAt'][NumId] = nowG
    local Success, Res = pcall(function()
        if game.HttpGet then
            local Raw = game:HttpGet('https://groups.roblox.com/v1/groups/' .. tostring(NumId))
            if type(Raw) == 'string' and #Raw > 2 and string.sub(Raw, 1, 1) == '{' then
                local ShootData = HttpService:JSONDecode(Raw)
                if ShootData and ShootData['name'] then
                    return ShootData['name']
                end
            end
        end
        return nil
    end)
    if Success and Res and type(Res) == 'string' and #Res > 0 then
        Data['CrewNameCache'][NumId] = Res
        Data['CrewNameFailAt'][NumId] = nil
        return Res
    end
    local Success2, Info = pcall(function()
        if NumId and NumId > 0 then
            return GroupService:GetGroupInfoAsync(NumId)
        end
        return nil
    end)
    if Success2 and Info and Info.Name then
        Data['CrewNameCache'][NumId] = Info.Name
        Data['CrewNameFailAt'][NumId] = nil
        return Info.Name
    end
    Data['CrewNameFailAt'][NumId] = tick()
    return tostring(CrewId)
end
function getplayercrewid(Player)
    if not Player then
        return nil
    end
    if Data['CrewMemo'] == nil then
        Data['CrewMemo'] = {}
    end
    local nowC = tick()
    local cm = Data['CrewMemo'][Player]
    if cm and nowC - cm.at < 5 then
        return cm.val
    end
    local res = nil
    local DataFolder = Player:FindFirstChild('DataFolder')
    if DataFolder then
        local Information = DataFolder:FindFirstChild('Information')
        local Crew = (Information and Information:FindFirstChild('Crew')) or DataFolder:FindFirstChild('Crew')
        if Crew and Crew.Value ~= nil then
            local ValStr = tostring(Crew.Value)
            if ValStr ~= '' and ValStr ~= '0' and ValStr ~= 'nil' then
                res = ValStr
            end
        end
    end
    Data['CrewMemoN'] = (Data['CrewMemoN'] or 0) + 1
    if Data['CrewMemoN'] > 200 then
        local oldest, oldestK = math.huge, nil
        for k, v in pairs(Data['CrewMemo']) do
            if v.at < oldest then
                oldest = v.at
                oldestK = k
            end
        end
        if oldestK then
            Data['CrewMemo'][oldestK] = nil
        end
        Data['CrewMemoN'] = Data['CrewMemoN'] - 1
    end
    Data['CrewMemo'][Player] = { val = res, at = nowC }
    return res
end
function iscrewwhitelisted(plr)
