function requestcrewdropdown()
    if not (Options and Options.crew_select) then
        return
    end
    local nowR = tick()
    if Data['UpdatingCrew'] then
        Data['CrewUpdatePending'] = true
        return
    end
    if nowR - (Data['CrewDropdownAt'] or 0) < 5 then
        if not Data['CrewUpdatePending'] then
            Data['CrewUpdatePending'] = true
            local waitLeft = 5 - (nowR - (Data['CrewDropdownAt'] or 0))
            if waitLeft < 0 then
                waitLeft = 0
            end
            task.delay(waitLeft, function()
                Data['CrewUpdatePending'] = false
                updatecrewdropdown()
            end)
        end
        return
    end
    updatecrewdropdown()
end
function updatecrewdropdown()
    if not (Options and Options.crew_select) then
        return
    end
    if Data['UpdatingCrew'] then
        Data['CrewUpdatePending'] = true
        return
    end
    local nowU = tick()
    if nowU - (Data['CrewDropdownAt'] or 0) < 5 then
        if not Data['CrewUpdatePending'] then
            Data['CrewUpdatePending'] = true
            local waitLeft = 5 - (nowU - (Data['CrewDropdownAt'] or 0))
            if waitLeft < 0 then
                waitLeft = 0
            end
            task.delay(waitLeft, function()
                Data['CrewUpdatePending'] = false
                updatecrewdropdown()
            end)
        end
        return
    end
    Data['UpdatingCrew'] = true
    Data['CrewDropdownAt'] = tick()
    task.spawn(function()
        local CrewCounts = {}
        for _, Plr in ipairs(Players:GetPlayers()) do
            local CrewId = getplayercrewid(Plr)
            if CrewId then
                CrewCounts[CrewId] = (CrewCounts[CrewId] or 0) + 1
            end
        end
        for CrewId in pairs(CrewCounts) do
            local Nid = tonumber(CrewId)
            if not Nid or not Data['CrewNameCache'][Nid] then
                phowg:queue_background('metadata', 'crew/' .. tostring(CrewId), function()
                    fetchgroupname(CrewId)
                    if Nid and Data['CrewNameCache'][Nid] then
                        requestcrewdropdown()
                    end
                end)
            end
        end
        local CrewList = {}
        local NewDisplayToId = {}
        for CrewId, Count in pairs(CrewCounts) do
            local NumId = tonumber(CrewId)
            local GroupName = (NumId and Data['CrewNameCache'][NumId]) or tostring(CrewId)
            local DisplayName = GroupName .. ' { ' .. tostring(Count) .. ' }'
            NewDisplayToId[DisplayName] = CrewId
            NewDisplayToId[CrewId] = CrewId
            table.insert(CrewList, DisplayName)
        end
        table.sort(CrewList)
        Data['CrewDisplayToId'] = NewDisplayToId
        Options.crew_select:SetValues(CrewList)
        if Options.whitelist_crew_select then
            Options.whitelist_crew_select:SetValues(CrewList)
        end
        pushcrewesp()
        Data['UpdatingCrew'] = false
        if Data['CrewUpdatePending'] then
            Data['CrewUpdatePending'] = false
            local since = tick() - (Data['CrewDropdownAt'] or 0)
            local delayFor = 5 - since
            if delayFor < 0 then
                delayFor = 0
            end
            task.delay(delayFor, updatecrewdropdown)
        end
    end)
end
function resolvecrewid(Selected)
    if not Selected or tostring(Selected) == '' then
        return nil
    end
    local map = Data['CrewDisplayToId'] or {}
    if map[Selected] then
        return tostring(map[Selected])
    end
    local text = tostring(Selected)
    local base = text:match('^(.-)%s*{%s*%d+%s*}%s*$') or text
    base = base:match('^%s*(.-)%s*$') or base
    if map[base] then
        return tostring(map[base])
    end
    for _, Plr in ipairs(Players:GetPlayers()) do
        if Plr ~= LocalPlayer then
            local cid = getplayercrewid(Plr)
            if cid then
                local num = tonumber(cid)
                local gname = (num and Data['CrewNameCache'][num]) or cid
                if tostring(gname) == base or tostring(cid) == base or tostring(cid) == text then
                    return tostring(cid)
                end
            end
        end
    end
    return nil
end
function lockcrewtargets(TargetCrewId, clearFirst)
    if clearFirst then
        Data['LockedTargets'] = {}
        Data['TargetWatchlist'] = {}
        if Data['DropdownTargets'] == nil then
            Data['DropdownTargets'] = {}
        end
        for plr, _ in pairs(Data['DropdownTargets']) do
            Data['DropdownTargets'][plr] = nil
        end
    end
    if Data['DropdownTargets'] == nil then
        Data['DropdownTargets'] = {}
    end
    local count = 0
    for _, Plr in ipairs(Players:GetPlayers()) do
        if Plr ~= LocalPlayer and getplayercrewid(Plr) == tostring(TargetCrewId) then
            Data['LockedTargets'][Plr] = true
            Data['DropdownTargets'][Plr] = true
            Data['TargetWatchlist'][Plr.UserId] = true
            Data['TargetWatchlist'][Plr.Name] = true
            count = count + 1
        end
    end
    return count
end
function fetchcrewicon(CrewId)
    local cid = tostring(CrewId or '')
    if cid == '' then
        return nil
    end
    if Data['CrewIconCache'] == nil then
        Data['CrewIconCache'] = {}
    end
    if Data['CrewIconAttemptAt'] == nil then
        Data['CrewIconAttemptAt'] = {}
    end
    local nowI = tick()
    local cached = Data['CrewIconCache'][cid]
    if cached ~= nil then
        if cached then
            return cached
        end
        if nowI - (Data['CrewIconFailAt'] and Data['CrewIconFailAt'][cid] or 0) < 5 then
            return nil
        end
        if nowI - (Data['CrewIconAttemptAt'][cid] or 0) < 5 then
            return nil
        end
        Data['CrewIconCache'][cid] = nil
    else
        if nowI - (Data['CrewIconAttemptAt'][cid] or 0) < 5 then
            return nil
        end
    end
    if nowI - (Data['CrewIconAt'] or 0) < 1 then
        return nil
    end
    Data['CrewIconAttemptAt'][cid] = nowI
    Data['CrewIconAt'] = nowI
    Data['CrewIconCache'][cid] = false
    task.spawn(function()
        local function valid_image(raw)
            if type(raw) ~= 'string' or #raw < 100 then
                return false
            end
            if string.sub(raw, 2, 4) == 'PNG' then
                return true
            end
            local b1, b2 = string.byte(raw, 1, 2)
            if b1 == 255 and b2 == 216 then
                return true
            end
            return false
        end
        local bytes = nil
        local emblem = nil
        local numCid = tonumber(cid)
        if numCid and Data['CrewNameCache'] and Data['CrewNameCache'][numCid] == nil then
            fetchgroupname(cid)
        end
        local ok, info = pcall(function()
            return GroupService:GetGroupInfoAsync(numCid)
        end)
        if ok and type(info) == 'table' then
            emblem = info.EmblemUrl or info.EmblemId or info.emblemUrl or info.emblemId
        end
        if emblem then
            local estr = tostring(emblem)
            if string.sub(estr, 1, 4) == 'http' then
                local okd, rawd = pcall(function()
                    return game:HttpGet(estr)
                end)
                if okd and valid_image(rawd) then
                    bytes = rawd
                end
            end
            if not bytes then
                local assetId = estr:match('id=(%d+)') or estr:match('rbxassetid://(%d+)')
                if assetId then
                    local oka, rawa = pcall(function()
                        return game:HttpGet('https://assetdelivery.roblox.com/v1/asset/?id=' .. assetId)
                    end)
                    if oka and valid_image(rawa) then
                        bytes = rawa
                    end
                end
            end
        end
        Data['CrewIconCache'][cid] = bytes or false
        if not bytes then
            if Data['CrewIconFailAt'] == nil then
                Data['CrewIconFailAt'] = {}
            end
            Data['CrewIconFailAt'][cid] = tick()
        end
        pushcrewesp()
    end)
    return nil
end
function pushcrewesp()
    local esp = getgenv and getgenv().ESP or nil
    if not (esp and esp.Configure) then
        return
    end
    if esp.CrewNames == nil then
        esp.CrewNames = {}
    end
    if esp.CrewIds == nil then
        esp.CrewIds = {}
    end
    if esp.CrewIcons == nil then
        esp.CrewIcons = {}
    end
    if esp.CrewCounts == nil then
        esp.CrewCounts = {}
    end
    local counts = {}
    for _, Plr in ipairs(Players:GetPlayers()) do
        local cid = getplayercrewid(Plr)
        if not cid then
            esp.CrewNames[Plr] = nil
            esp.CrewIds[Plr] = nil
        else
            local key = tostring(cid)
            local num = tonumber(key)
            esp.CrewNames[Plr] = (num and Data['CrewNameCache'][num]) or key
            esp.CrewIds[Plr] = key
            counts[key] = (counts[key] or 0) + 1
            local icon = Data['CrewIconCache'] and Data['CrewIconCache'][key] or nil
            if type(icon) == 'string' then
                esp.CrewIcons[key] = icon
            else
                esp.CrewIcons[key] = nil
                fetchcrewicon(key)
            end
        end
    end
    for key, n in pairs(counts) do
        esp.CrewCounts[key] = n
    end
    for key, _ in pairs(esp.CrewCounts) do
        if counts[key] == nil then
            esp.CrewCounts[key] = nil
        end
    end
end
function monitorplayercrew(Plr)
    local function hook_crew(Crew)
        create_connection(
            'Crew Watch ' .. tostring(Plr.UserId),
            connectshared(Crew:GetPropertyChangedSignal('Value'), function()
                requestcrewdropdown()
            end, Crew, 'event/Crew:GetPropertyChangedSignal(Value)', 0, 'property/Value', Crew)
        )
        requestcrewdropdown()
    end
    local DataFolder = Plr:FindFirstChild('DataFolder')
    if DataFolder then
        local Info = DataFolder:FindFirstChild('Information')
        if Info then
            local Crew = Info:FindFirstChild('Crew')
            if Crew then
                hook_crew(Crew)
            else
                connectshared(Info.ChildAdded, function(c)
                    if c.Name == 'Crew' then
                        hook_crew(c)
                    end
                end, Info, 'event/Info.ChildAdded', 0, 'event/ChildAdded', Info)
            end
        else
            connectshared(DataFolder.ChildAdded, function(c)
                if c.Name == 'Information' then
                    local Crew = c:FindFirstChild('Crew')
                    if Crew then
                        hook_crew(Crew)
                    else
                        connectshared(c.ChildAdded, function(c2)
                            if c2.Name == 'Crew' then
                                hook_crew(c2)
                            end
                        end, c, 'event/c.ChildAdded', 0, 'event/ChildAdded', c)
                    end
                end
            end, DataFolder, 'event/DataFolder.ChildAdded', 0, 'event/ChildAdded', DataFolder)
        end
    else
        connectshared(Plr.ChildAdded, function(c)
            if c.Name == 'DataFolder' then
                monitorplayercrew(Plr)
            end
        end, Plr, 'event/Plr.ChildAdded', 0, 'event/ChildAdded', Plr)
    end
end
