function isstomped(Player)
    local character = Player and Player.Character
    local effects = character and character:FindFirstChild('BodyEffects')
    local stomped = effects and effects:FindFirstChild('SDeath')
    local alternate = effects and effects:FindFirstChild('SDead')
    return stomped and stomped.Value == true or alternate and alternate.Value == true or false
