    return isstomped(Player)
end
function isknocked(Player)
    local character = Player and Player.Character
    local BodyEffects = character and character:FindFirstChild('BodyEffects')
    if not BodyEffects or isstomped(Player) then
        return false
    end
    local dead = BodyEffects:FindFirstChild('Dead')
    local knocked = BodyEffects:FindFirstChild('K.O') or BodyEffects:FindFirstChild('KO')
    return (dead and dead.Value == true) or (knocked and knocked.Value == true) or false
end
local function supporttargetfinished(player, mode)
    if
        not player
        or not player.Parent
        or iswhitelistedplayer(player)
        or iscrewwhitelisted(player)
        or (Data['RageWhitelist'] and Data['RageWhitelist'][player])
    then
        return true
    end
    local character = player.Character
    local tracked = Data['SupportTargetCharacters'] and Data['SupportTargetCharacters'][player]
    if tracked and character ~= tracked then
        return true
    end
    if not character then
        return false
    end
    if isstomped(player) then
        return true
    end
    local humanoid = character:FindFirstChildOfClass('Humanoid')
    if
        humanoid
        and humanoid.Health <= 0
        and (not isknocked(player) or humanoid:GetState() == Enum.HumanoidStateType.Dead)
    then
        return true
    end
    if mode == 'knock target' then
        return isknocked(player)
    end
    if mode == 'fling target' then
        local root = character:FindFirstChild('HumanoidRootPart')
        return root ~= nil and root.Position.Magnitude > 10000
    end
    return false
end
function getdistancetoplayer(Player)
    if not LocalPlayer.Character then
        return math.huge
    end
    local MyRoot = getroot(LocalPlayer.Character)
    local TargetRoot = intelligence:get_character_cache(Player) and getroot(Player.Character)
    if not MyRoot or not TargetRoot then
        return math.huge
    end
    local myPos = (Local_Data['ClientPos'] and Local_Data['ClientPos'].Position) or MyRoot.CFrame.Position
    return (myPos - TargetRoot.CFrame.Position).Magnitude
end
function gunshootorigin(handle, nativeOrigin)
    local character = LocalPlayer and LocalPlayer.Character
    local root = character and character:FindFirstChild('HumanoidRootPart')
    if not root then
        return nil
    end
    local muzzle = handle and handle:FindFirstChild('Muzzle')
    local position = typeof(nativeOrigin) == 'Vector3' and nativeOrigin
        or muzzle and muzzle.WorldPosition
        or handle and handle.Position
    local applied = Data.AppliedServerCF
    local age = tick() - (Data.AppliedServerAt or -math.huge)
    if
        Data.AppliedServerCharacter == character
        and typeof(applied) == 'CFrame'
        and age >= 0
        and age <= 0.15
        and (
            Data.AppliedServerTag == 'Combat'
            or Data.AppliedServerTag == 'KillAura'
            or Data.AppliedServerTag == 'TargetStrafe'
            or Data.AppliedServerTag == 'Desync'
        )
    then
        if typeof(position) == 'Vector3' then
            local client = (Data.CSyncTable[2] or Data.MoveToInFlight == root) and Data.CSyncTable[1] or root.CFrame
            if typeof(client) == 'CFrame' then
                local offset = client:PointToObjectSpace(position)
                local serverOffset = applied:PointToObjectSpace(position)
                if serverOffset.Magnitude < offset.Magnitude then
                    offset = serverOffset
                end
                local grip = Data.GripWallbang
                local manipulated = grip and handle and grip.Tool == handle.Parent and grip.Tool.Grip == grip.Applied
                if offset.Magnitude < 12 or manipulated then
                    return applied:PointToWorldSpace(offset)
                end
            end
        end
        return applied.Position + Vector3.new(0, 1.5, 0)
    end
    if typeof(position) == 'Vector3' then
        return position
    end
    return root.Position + Vector3.new(0, 1.5, 0)
end
function phowg:rebase_gun_origin(shot)
    if
        type(shot) ~= 'table'
        or shot.Shooter ~= LocalPlayer.Character
        or shot.ReplicatedShot
        or shot.isReflecting
        or shot.TrailOnly
    then
        return false
    end
    local handle = shot.Handle
    local tool = typeof(handle) == 'Instance' and handle.Parent
    if not tool or not tool:IsA('Tool') or tool.Parent ~= shot.Shooter or not tool:FindFirstChild('Ammo') then
        return false
    end
    local muzzle = handle:FindFirstChild('Muzzle')
    local native = typeof(shot.ForcedOrigin) == 'Vector3' and shot.ForcedOrigin
        or muzzle and muzzle.WorldPosition
        or handle.Position
    local origin = gunshootorigin(handle, native)
    if not phowg:perfect_hit_vector(native) or not phowg:perfect_hit_vector(origin) then
        return false
    end
    local delta = origin - native
    if delta.Magnitude < 0.001 then
        return false
    end
    shot.ForcedOrigin, shot.Origin = origin, origin
    if typeof(shot.AimPosition) == 'Vector3' then
        shot.AimPosition += delta
    end
    return true
end
function phowg:redirect_gun_packet(handle, origin, point, hitPart)
    local pending = Data.RedirectGunShots
    local thread = coroutine.running()
    local shot = pending and pending[thread]
    if not shot then
        if phowg.sticky_redirect_packet then
            return phowg:sticky_redirect_packet(handle, origin)
        end
        return nil
    end
    if Library.Unloaded or Data.SharedSignalsClosed or localshootblocked() then
        pending[thread] = nil
        return nil
    end
    local age = tick() - shot.At
    if
        age < 0
        or age > 0.15
        or shot.Character ~= LocalPlayer.Character
        or shot.Target and shot.Target.Character ~= shot.TargetCharacter
    then
        pending[thread] = nil
        return nil
    end
    if
        handle ~= shot.Handle
        or handle.Parent == nil
        or handle.Parent.Parent ~= shot.Character
        or typeof(origin) ~= 'Vector3'
        or typeof(point) ~= 'Vector3'
    then
        return nil
    end
    if (point - shot.Point).Magnitude > 0.05 or hitPart ~= shot.Hit then
        return nil
    end
    local target, _position, _part, source = phowg:get_gun_shot_target()
    pending[thread] = nil
    if target ~= shot.Target or source ~= shot.Source then
        return nil
    end
    return shot.Origin
end
function phowg:target_vehicle(character)
    local folder = Workspace:FindFirstChild('Vehicles')
    if not folder or not character then
        return nil
    end
    local player = Players:GetPlayerFromCharacter(character)
    return folder:FindFirstChild(player and player.Name or character.Name)
end
function phowg:reset_movement_resolver()
    Data.ResolvedMotion, Data.TeleportCycles, Data.SmartAttackSamples = nil, nil, nil
    Data.MotionSampleSeen = nil
end
function phowg:resolver_auto_adapt()
    return Toggles.headshots_resolver
        and Toggles.headshots_resolver.Value
        and (not Toggles.ragebot_resolver_auto_adapt or Toggles.ragebot_resolver_auto_adapt.Value)
end
function phowg:adapt_motion_estimate(state, position, now, fast, broad, acceleration)
    local rate = state.Vehicle and broad * 0.6 + fast * 0.4 or fast * 0.85 + broad * 0.15
    if not phowg:resolver_auto_adapt() then
        state.Adaptive = nil
        return rate, acceleration
    end
    local previous = state.Adaptive
    local interval = previous and now - previous.At or 0
    local adapt: { [string]: any } = previous
        or {
            FastError = 0,
            BroadError = 0,
            Jitter = 0,
            Noise = 0,
            Confidence = 1,
            LeadScale = 1,
            SampleWindow = 0.16,
            RecentWindow = 0.045,
            Count = 0,
        }
    local turn = 0
    if previous and interval >= 0.008 and interval <= 0.3 then
        local step = (position - adapt.Position).Magnitude
        local fastError = (position - (adapt.Position + adapt.Fast * interval)).Magnitude
        local broadError = (position - (adapt.Position + adapt.Broad * interval)).Magnitude
        adapt.FastError = adapt.FastError * 0.75 + fastError * 0.25
        adapt.BroadError = adapt.BroadError * 0.75 + broadError * 0.25
        local cadence = adapt.Interval or interval
        local jitter = math.abs(interval - cadence) / math.max(interval, cadence, 0.008)
        adapt.Jitter = adapt.Jitter * 0.8 + jitter * 0.2
        adapt.Noise = adapt.Noise * 0.75 + math.clamp(math.min(fastError, broadError) / math.max(1, step), 0, 2) * 0.25
        if fast.Magnitude > 5 and adapt.Fast.Magnitude > 5 then
            turn = (1 - math.clamp(fast.Unit:Dot(adapt.Fast.Unit), -1, 1)) * 0.5
        end
        local total = adapt.FastError + adapt.BroadError
        local weight = total > 0.05 and math.clamp(adapt.BroadError / total, 0.65, 0.95)
            or (state.Vehicle and 0.65 or 0.85)
        if fast.Magnitude > 5 and broad.Magnitude > 5 and fast.Unit:Dot(broad.Unit) < 0.3 then
            weight = 0.95
        end
        rate = fast * weight + broad * (1 - weight)
        adapt.Confidence = math.clamp(1 - adapt.Noise * 0.5 - adapt.Jitter * 0.2 - turn * 0.4, 0.35, 1)
        adapt.SampleWindow = math.clamp(0.12 + adapt.Jitter * 0.04, 0.1, 0.16)
        adapt.RecentWindow = math.clamp(interval * 1.25, 0.025, 0.05)
    end
    adapt.LeadScale = 1
    adapt.At, adapt.Position, adapt.Fast, adapt.Broad = now, position, fast, broad
    adapt.Interval = interval > 0 and interval or adapt.Interval
    adapt.Count += 1
    state.Adaptive = adapt
    return rate, acceleration * adapt.Confidence * (1 - turn)
end
function phowg:resolver_anchor_fresh(state, now)
    return state
        and state.ResolverAnchor
        and (now or tick()) - (state.LastJumpAt or -math.huge) <= (state.AnchorTimeout or 0.6)
end
function phowg:update_resolver_cluster(state, position, now, jumped)
    if not (Toggles.headshots_resolver and Toggles.headshots_resolver.Value) or state.Vehicle then
        return
    end
    local samples = state.ClusterSamples or {}
    state.ClusterSamples = samples
    if
        position.Y > -1000
        and position.Magnitude < 100000
        and (not state.ClusterSampleAt or now - state.ClusterSampleAt >= 0.04)
    then
        samples[#samples + 1] = { Position = position, At = now }
        state.ClusterSampleAt = now
    end
    while #samples > 64 or #samples > 0 and now - samples[1].At > 2.75 do
        table.remove(samples, 1)
    end
    if not jumped or #samples < 4 or now - (state.ClusterScanAt or 0) < 0.09 then
        return
    end
    state.ClusterScanAt = now
    local radius = phowg:visual_number('resolver_position_weight', 1.5, 0.1, 3) * 9.6
    local bonus = phowg:visual_number('resolver_out_of_void_bonus', 0.2, 0, 1) * 25
    local root = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild('HumanoidRootPart')
    local distance = root and (position - root.Position).Magnitude or 0
    local penalty = phowg:visual_number('resolver_forget_rate', 80, 0, 100) / 40
    radius = math.clamp(
        radius + (math.abs(position.X) + math.abs(position.Z) < 8955 and bonus or 0) - distance / 100 * penalty,
        1,
        40
    )
    local accuracy = phowg:visual_number('resolver_accuracy', 76.82, 50, 100)
    local required = math.clamp(math.floor((1 + 0.6525 * ((accuracy - 50) / 50)) * 3 + 0.5), 3, 10)
    local bestCount, bestPosition, bestAt = 0, nil, 0
    for _, anchor in ipairs(samples) do
        local count, total, weightTotal, newest = 0, Vector3.zero, 0, 0
        for _, sample in ipairs(samples) do
            local distanceSquared = (sample.Position - anchor.Position).Magnitude ^ 2
            if distanceSquared <= radius * radius then
                local weight = (1 - distanceSquared / (radius * radius) * 0.65) / (1 + now - sample.At)
                count += 1
                total += sample.Position * weight
                weightTotal += weight
                newest = math.max(newest, sample.At)
            end
        end
        if count >= required and newest > now - 0.6 and count > bestCount then
            bestCount, bestPosition, bestAt = count, total / weightTotal, newest
        end
    end
    if bestPosition then
        state.ClusterPosition, state.ClusterAt = bestPosition, bestAt
    end
end
function phowg:update_movement_resolver(state, root, now, jumped)
    local position = root.Position
    if not (Toggles.headshots_resolver and Toggles.headshots_resolver.Value) or state.Vehicle then
        state.ResolverAnchor, state.JumpPoints, state.JumpTimes = nil, nil, nil
        state.LastRootPosition = position
        return
    end
    phowg:update_resolver_cluster(state, position, now, jumped)
    local radius = phowg:visual_number('ragebot_resolver_radius', 6, 1, 15)
    local automatic = phowg:resolver_auto_adapt()
    if automatic and state.Adaptive then
        radius = math.clamp(radius + state.Adaptive.Jitter * 2, 2, 12)
    end
    local window = phowg:visual_number('ragebot_resolver_window', 1.5, 0.5, 3)
    local required = phowg:visual_number('ragebot_resolver_jumps', 3, 3, 10)
    local points, times = state.JumpPoints or {}, state.JumpTimes or {}
    state.JumpPoints, state.JumpTimes = points, times
    for index = #times, 1, -1 do
        if now - times[index] > window then
            table.remove(times, index)
        end
    end
    for index = #points, 1, -1 do
        local point = points[index]
        for visitIndex = #point.Arrivals, 1, -1 do
            if now - point.Arrivals[visitIndex] > window then
                table.remove(point.Arrivals, visitIndex)
            end
        end
        point.Visits = #point.Arrivals
        if point.Visits == 0 then
            table.remove(points, index)
        end
    end
    if state.ResolverAnchor and not table.find(points, state.ResolverAnchor) then
        state.ResolverAnchor = nil
    end
    local function visit(value)
        if not phowg:perfect_hit_vector(value) then
            return
        end
        local point
        for _, candidate in ipairs(points) do
            if (candidate.Position - value).Magnitude <= radius then
                point = candidate
                break
            end
        end
        if not point then
            point = { Position = value, Visits = 0, At = now, Arrivals = {} }
            points[#points + 1] = point
            if #points > 24 then
                table.remove(points, 1)
            end
        end
        point.Arrivals[#point.Arrivals + 1] = now
        point.Position, point.Visits, point.At = value, #point.Arrivals, now
        return point
    end
    if jumped then
        if #points == 0 and state.LastRootPosition then
            visit(state.LastRootPosition)
        end
        visit(position)
        times[#times + 1] = now
        local period = state.LastJumpAt and now - state.LastJumpAt
        if automatic and period and period > 0 and period <= window then
            state.JumpInterval = state.JumpInterval and state.JumpInterval * 0.7 + period * 0.3 or period
        end
        state.AnchorTimeout = automatic and state.JumpInterval and math.clamp(state.JumpInterval * 3.5, 0.25, 1.2)
            or 0.6
        state.LastJumpAt = now
        if #times >= required and #points >= 2 then
            local best
            for _, candidate in ipairs(points) do
                if
                    candidate.Visits >= 2
                    and candidate.Position.Y > -1000
                    and candidate.Position.Magnitude < 100000
                    and (
                        not best
                        or candidate.Visits > best.Visits
                        or candidate.Visits == best.Visits and candidate.At > best.At
                    )
                then
                    best = candidate
                end
            end
            local hold = automatic
                    and state.JumpInterval
                    and math.clamp(state.JumpInterval * math.max(2, #points) * 3, 0.4, 1.25)
                or 0.85
            if best and (not state.ResolverAnchor or now >= (state.ResolverAnchorUntil or 0)) then
                state.ResolverAnchor, state.ResolverAnchorUntil = best, now + hold
            end
        end
    elseif state.ResolverAnchor and (position - state.ResolverAnchor.Position).Magnitude <= radius then
        state.ResolverAnchor.Position, state.ResolverAnchor.At = position, now
    end
    if state.LastJumpAt and now - state.LastJumpAt > (state.AnchorTimeout or 0.6) then
        state.ResolverAnchor = nil
    end
    if position.Y > -1000 and position.Magnitude < 100000 then
        state.LastSafePosition = position
    end
    state.LastRootPosition = position
end
function phowg:resolve_target_motion(character, root)
    local zero = Vector3.zero
    if Library.Unloaded or not character or not character.Parent or not root or root.Parent ~= character then
        return zero, zero, 0
    end
    local vehicle = phowg:target_vehicle(character)
    local source = root
    if vehicle then
        if vehicle:IsA('BasePart') then
            source = vehicle
        elseif vehicle:IsA('Model') then
            source = vehicle.PrimaryPart
                or vehicle:FindFirstChildWhichIsA('VehicleSeat', true)
                or vehicle:FindFirstChildWhichIsA('Seat', true)
                or vehicle:FindFirstChildWhichIsA('BasePart', true)
                or root
        end
    end
    local position = source.Position
    if
        typeof(position) ~= 'Vector3'
        or position.X ~= position.X
        or position.Y ~= position.Y
        or position.Z ~= position.Z
        or position.Magnitude > 1000000
    then
        return zero, zero, 0
    end
    Data.ResolvedMotion = Data.ResolvedMotion or setmetatable({}, { __mode = 'k' })
    local now = tick()
    local state: { [string]: any }? = Data.ResolvedMotion[character]
    if
        not state
        or state.Root ~= root
        or state.Source ~= source
        or state.Vehicle ~= vehicle
        or now < state.At
        or now - state.At > 0.4
    then
        state = {
            Root = root,
            Source = source,
            Vehicle = vehicle,
            Position = position,
            At = now,
            ChangedAt = now,
            ReplicationInterval = 1 / 30,
            Rate = zero,
            Acceleration = zero,
            Samples = { { At = now, Position = position } },
        }
        Data.ResolvedMotion[character] = state
        phowg:update_movement_resolver(state, root, now, false)
        return zero, zero, 0
    end
    local elapsed = now - state.At
    if elapsed >= 1 / 240 then
        local delta = position - state.Position
        local snapshot = phowg:character_snapshot(character)
        local humanoid = snapshot and snapshot.Humanoid
        local maximum = vehicle and 1000 or humanoid and humanoid.FloorMaterial == Enum.Material.Air and 1200 or 500
        if phowg:resolver_auto_adapt() and state.Adaptive then
            maximum = math.max(maximum, math.min(6000, state.Adaptive.Fast.Magnitude * 1.5))
        end
        local resolving = Toggles.headshots_resolver and Toggles.headshots_resolver.Value
        local threshold = resolving and phowg:visual_number('ragebot_resolver_distance', 48, 24, 200) or 24
        local multiplier = 2
        if phowg:resolver_auto_adapt() and state.Adaptive and state.Adaptive.Count >= 4 then
            multiplier = 1.25
        end
        local expected = state.Rate.Magnitude * elapsed * 2.5
        local jumped = delta.Magnitude > math.max(threshold, maximum * elapsed * multiplier, expected)
        if
            jumped
            and phowg:resolver_auto_adapt()
            and delta.Magnitude > 0
            and position.Y > -1000
            and state.Position.Y > -1000
        then
            local speed = delta.Magnitude / elapsed
            local large = state.LargeStepRun
            local continuous = large
                and now - large.At <= 0.2
                and large.Direction:Dot(delta.Unit) > 0.985
                and math.abs(speed - large.Speed) / math.max(speed, large.Speed, 1) < 0.2
            state.LargeStepRun =
                { At = now, Speed = speed, Direction = delta.Unit, Count = continuous and large.Count + 1 or 1 }
            if state.LargeStepRun.Count >= 3 and speed <= 6000 then
                jumped = false
                maximum = math.max(maximum, speed * 1.25)
            end
        elseif not jumped then
            state.LargeStepRun = nil
        end
        phowg:update_movement_resolver(state, root, now, jumped)
        if jumped then
            state.Samples = { { At = now, Position = position } }
            state.Rate, state.Acceleration, state.ChangedAt = zero, zero, now
            state.Adaptive = nil
        else
            local samples = state.Samples
            if delta.Magnitude > 0.001 then
                local updateInterval = now - state.ChangedAt
                if updateInterval >= 1 / 240 and updateInterval <= 0.15 then
                    local previousInterval = state.LastReplicationInterval or updateInterval
                    state.ReplicationJitter = (state.ReplicationJitter or 0) * 0.65
                        + math.abs(updateInterval - previousInterval)
                            / math.max(updateInterval, previousInterval)
                            * 0.35
                    state.LastReplicationInterval = updateInterval
                    state.ReplicationInterval = math.clamp(
                        (state.ReplicationInterval or updateInterval) * 0.65 + updateInterval * 0.35,
                        1 / 240,
                        0.1
                    )
                end
                state.ChangedAt = now
                samples[#samples + 1] = { At = now, Position = position }
                while
                    #samples > 12
                    or #samples > 2
                        and now - samples[1].At > (state.Adaptive and state.Adaptive.SampleWindow or 0.16)
                do
                    table.remove(samples, 1)
                end
                local first = samples[1]
                local recent = first
                local recentWindow = math.max(
                    state.Adaptive and state.Adaptive.RecentWindow or (vehicle and 0.045 or 0.025),
                    (state.ReplicationInterval or 1 / 30) * 2
                )
                for index = #samples - 1, 1, -1 do
                    recent = samples[index]
                    if now - recent.At >= recentWindow then
                        break
                    end
                end
                local duration = now - first.At
                local recentDuration = now - recent.At
                if duration >= 0.012 and recentDuration >= 0.012 then
                    local broad = (position - first.Position) / duration
                    local fast = (position - recent.Position) / recentDuration
                    local rate = vehicle and broad * 0.6 + fast * 0.4 or fast * 0.85 + broad * 0.15
                    if rate.Magnitude > maximum then
                        rate = rate.Unit * maximum
                    end
                    local acceleration = zero
                    local earlyDuration = recent.At - first.At
                    if
                        not vehicle
                        and (state.ReplicationJitter or 0) < 0.15
                        and earlyDuration >= 0.025
                        and recentDuration >= 0.025
                    then
                        local early = (recent.Position - first.Position) / earlyDuration
                        acceleration = (fast - early) / ((earlyDuration + recentDuration) * 0.5)
                        if acceleration.Magnitude > 1200 then
                            acceleration = acceleration.Unit * 1200
                        end
                        if early.Magnitude > 8 and fast.Magnitude > 8 and early:Dot(fast) < 0 then
                            acceleration = zero
                        end
                    end
                    rate, acceleration = phowg:adapt_motion_estimate(state, position, now, fast, broad, acceleration)
                    local previous = samples[#samples - 1]
                    local stepTime = previous and now - previous.At or 0
                    if not vehicle and stepTime >= 0.008 then
                        local instant = (position - previous.Position) / stepTime
                        if
                            instant.Magnitude > 1
                            and (rate:Dot(instant) < 0 or fast.Magnitude > 1 and fast.Unit:Dot(instant.Unit) < 0.5)
                        then
                            rate, acceleration = instant, zero
                        end
                    end
                    if rate.Magnitude > maximum then
                        rate = rate.Unit * maximum
                    end
                    state.Rate, state.Acceleration = rate, acceleration
                end
            elseif now - state.ChangedAt >= math.clamp((state.ReplicationInterval or 1 / 30) * 4, 0.18, 0.35) then
                state.Rate, state.Acceleration = zero, zero
                state.Samples = { { At = now, Position = position } }
            end
        end
        state.Position, state.At = position, now
    end
    return state.Rate, state.Acceleration or zero, math.clamp(now - state.ChangedAt, 0, 0.12)
end
function phowg:sticky_motion_required()
    return phowg:toggle_enabled('target_strafe_enabled')
        or phowg:toggle_enabled('prediction_visualization')
        or phowg:toggle_enabled('grenade_tp')
        or phowg:toggle_enabled('aim_assist_enabled')
        or phowg:toggle_enabled('kill_aura_enabled')
        or rageboton()
        or Data.PunishmentGunActive == true
        or phowg:gun_shoot_method('StickyAim', Data.StickyTarget) ~= 'shoot redirect'
end
function phowg:sample_target_motion()
    local idleSticky = Data.StickyTarget
    local sampleSticky = not idleSticky or phowg:sticky_motion_required()
    local seen = Data.MotionSampleSeen or setmetatable({}, { __mode = 'k' })
    Data.MotionSampleSeen = seen
    table.clear(seen)
    local function resolve(target)
        local character = target and target.Character
        if character and not seen[character] and (sampleSticky or character ~= idleSticky.Character) then
            seen[character] = true
            local root = character:FindFirstChild('HumanoidRootPart')
            phowg:resolve_target_motion(character, root)
        end
    end
    resolve(Data.StickyTarget)
    resolve(Data.SilentAimStickyTarget)
    resolve(Data.TargetStrafeTarget)
    resolve(Data.CurrentActionTarget)
    resolve(Data.CurrentMainTarget)
    resolve(Data.SingleLockedTarget)
    resolve(Data.KillAuraTarget)
    for target, active in pairs(Data.LockedTargets or {}) do
        if active then
            resolve(target)
        end
    end
    for target, active in pairs(Data.SilentAimStickyTargets or {}) do
        if active then
            resolve(target)
        end
    end
    if
        phowg.get_gun_shot_target
        and (
            phowg:perfect_hit_mode()
            or Toggles.silent_aim_enabled and Toggles.silent_aim_enabled.Value
            or phowg:ragebot_action_enabled('auto_kill') and (rageboton() or Data.PunishmentGunActive)
        )
    then
        resolve(phowg:get_gun_shot_target())
    end
end
function phowg:motion_lead(character, root, horizon, adaptive, ignoreResolver)
    local velocity, acceleration, age = phowg:resolve_target_motion(character, root)
    local motion = Data.ResolvedMotion and Data.ResolvedMotion[character]
    if
        not ignoreResolver
        and motion
        and phowg:resolver_anchor_fresh(motion)
        and (motion.ResolverAnchor.Position - root.Position).Magnitude
            > phowg:visual_number('ragebot_resolver_radius', 6, 1, 15)
    then
        return Vector3.zero, Vector3.zero, age
    end
    local duration = math.clamp(horizon + (adaptive and 0 or math.min(age, 0.1)), 0, 1)
    local correction = acceleration * (0.5 * duration * duration)
    local correctionLimit = math.max(1, velocity.Magnitude * duration * 0.3)
    if correction.Magnitude > correctionLimit then
        correction = correction.Unit * correctionLimit
    end
    local lead = velocity * duration + correction
    if lead.Magnitude > 500 then
        lead = lead.Unit * 500
    end
    return lead, velocity, age
end
function phowg:prediction_profile(character, root, velocity)
    local motion = Data.ResolvedMotion and Data.ResolvedMotion[character]
    if motion and motion.Vehicle then
        return 'vehicle'
    end
    local snapshot = phowg:character_snapshot(character)
    local humanoid = snapshot and snapshot.Humanoid
    local airborne = humanoid and humanoid.FloorMaterial == Enum.Material.Air or math.abs(velocity.Y) > 6
    local horizontal = Vector3.new(velocity.X, 0, velocity.Z).Magnitude
    if airborne or horizontal >= 60 then
        return 'airborne'
    end
    return 'ground'
end
function phowg:airborne_strafe_lead(character, root, horizon, velocity)
    local motion = Data.ResolvedMotion and Data.ResolvedMotion[character]
    local samples = motion and motion.Samples
    if not samples or #samples < 2 then
        if motion then
            motion.FlightPrediction = nil
        end
        return phowg:motion_lead(character, root, horizon, true, true)
    end
    if velocity.Magnitude < 0.01 then
        motion.FlightPrediction = nil
        return Vector3.zero, Vector3.zero
    end
    local latest, previous = samples[#samples], samples[#samples - 1]
    local interval = latest.At - previous.At
    if interval < 0.008 or interval > 0.3 then
        return phowg:motion_lead(character, root, horizon, true, true)
    end
    local fast = (latest.Position - previous.Position) / interval
    if fast.Magnitude < 0.01 then
        motion.FlightPrediction = nil
        return Vector3.zero, Vector3.zero
    end
    if fast.Magnitude > 6000 then
        return phowg:motion_lead(character, root, horizon, true, true)
    end
    local state: { [string]: any }? = motion.FlightPrediction
    if not state or latest.At < state.At then
        state = {
            At = latest.At,
            Position = latest.Position,
            Fast = fast,
            Velocity = velocity,
            Acceleration = Vector3.zero,
            Interval = interval,
            SmoothError = 1,
            FastError = 1,
            AccelerationError = 1,
        }
        motion.FlightPrediction = state
    elseif latest.At > state.At then
        local duration = latest.At - state.At
        if duration > 0.3 then
            motion.FlightPrediction = nil
            return phowg:motion_lead(character, root, horizon, true, true)
        end
        local actual = latest.Position - state.Position
        local divisor = math.max(1, actual.Magnitude)
        local function error_for(displacement)
            return math.clamp((actual - displacement).Magnitude / divisor, 0, 4)
        end
        local blend = 1 - math.exp(-12 * duration)
        state.SmoothError += (error_for(state.Velocity * duration) - state.SmoothError) * blend
        state.FastError += (error_for(state.Fast * duration) - state.FastError) * blend
        state.AccelerationError += (error_for(
            state.Fast * duration + state.Acceleration * (0.5 * duration * (duration + state.Interval))
        ) - state.AccelerationError) * blend
        local acceleration = (fast - state.Fast) / math.max((duration + interval) * 0.5, 0.008)
        if acceleration.Magnitude > 1200 then
            acceleration = acceleration.Unit * 1200
        end
        if fast.Magnitude < 1 or state.Fast.Magnitude > 1 and fast.Unit:Dot(state.Fast.Unit) < 0.5 then
            acceleration = Vector3.zero
        end
        state.At, state.Position, state.Fast, state.Velocity, state.Acceleration, state.Interval =
            latest.At, latest.Position, fast, velocity, acceleration, interval
    end
    local fastWeight = 1 / (0.05 + state.FastError)
    local smoothWeight = 1 / (0.05 + state.SmoothError)
    local rate = (fast * fastWeight + velocity * smoothWeight) / (fastWeight + smoothWeight)
    local turn = fast.Magnitude > 1 and velocity.Magnitude > 1 and fast.Unit:Dot(velocity.Unit) < 0.5
    if turn then
        rate = fast
    end
    local accelerationWeight =
        math.clamp((math.min(state.FastError, state.SmoothError) + 0.05) / (state.AccelerationError + 0.05), 0, 1)
    local correction = turn and Vector3.zero
        or state.Acceleration * (0.5 * horizon * (horizon + interval) * accelerationWeight)
    local limit = math.max(1, rate.Magnitude * horizon * 0.35)
    if correction.Magnitude > limit then
        correction = correction.Unit * limit
    end
    local lead = rate * horizon + correction
    local maximumAge = math.clamp((motion.ReplicationInterval or 1 / 30) * 4, 0.18, 0.35)
    if tick() - latest.At > maximumAge then
        return Vector3.zero, Vector3.zero
    end
    return lead, rate
end
function phowg:adaptive_prediction(character, root, ignoreResolver)
    local velocity, _, age = phowg:resolve_target_motion(character, root)
    local profile = phowg:prediction_profile(character, root, velocity)
    local airborne = profile == 'airborne'
    if not airborne then
        local motion = Data.ResolvedMotion and Data.ResolvedMotion[character]
        if motion then
            motion.FlightPrediction = nil
        end
    end
    local ping = Data.StrafePing or 0
    local motion = Data.ResolvedMotion and Data.ResolvedMotion[character]
    local replication = motion and motion.ReplicationInterval or 1 / 30
    local frame = math.clamp((Data.CombatFrameMs or (1000 / 60)) / 1000, 1 / 240, 1 / 30)
    local horizon = ping * 2 + math.min(age, 0.1) + math.clamp(replication * 0.5, 0, 0.05) + frame
    horizon = math.clamp(horizon, 0.035, airborne and 0.5 or 0.35)
    local lead
    if airborne and ignoreResolver then
        lead, velocity = phowg:airborne_strafe_lead(character, root, horizon, velocity)
    else
        lead = phowg:motion_lead(character, root, horizon, true, ignoreResolver)
    end
    local maximum = airborne and 500 or 150
    if lead.Magnitude > maximum then
        lead = lead.Unit * maximum
    end
    return lead, velocity
end
function phowg:smart_attack_ready(target, owner)
    if owner ~= 'Ragebot' or not Data.Settings.Smart then
        return true
    end
    local character = target and target.Character
    local root = character and character:FindFirstChild('HumanoidRootPart')
    if not root then
        return false
    end
    local velocity = phowg:resolve_target_motion(character, root)
    Data.SmartAttackSamples = Data.SmartAttackSamples or setmetatable({}, { __mode = 'k' })
    local state = Data.SmartAttackSamples[target]
    if not state or state.Character ~= character then
        state = { Character = character }
        Data.SmartAttackSamples[target] = state
    end
    if velocity.Magnitude > phowg:visual_number('ragebot_smart_speed', 12, 0, 100) then
        state.StillSince = nil
        return false
    end
    local now = tick()
    state.StillSince = state.StillSince or now
    return now - state.StillSince >= phowg:visual_number('ragebot_smart_settle', 0.15, 0, 0.5)
end
function phowg:resolved_root_position(character, root)
    phowg:resolve_target_motion(character, root)
    local state = Data.ResolvedMotion and Data.ResolvedMotion[character]
    if not state or not (Toggles.headshots_resolver and Toggles.headshots_resolver.Value) then
        return root.Position
    end
    local anchor = state.ResolverAnchor
    if phowg:resolver_anchor_fresh(state) then
        return anchor.Position
    end
    if
        state.ClusterPosition
        and tick() - (state.ClusterAt or 0) < 0.6
        and tick() - (state.LastJumpAt or 0) < 0.6
        and (
            root.Position.Y < -1000
            or (state.ClusterPosition - root.Position).Magnitude
                > phowg:visual_number('ragebot_resolver_distance', 48, 24, 200)
        )
    then
        return state.ClusterPosition
    end
    if root.Position.Y < -1000 and state.LastSafePosition then
        return state.LastSafePosition
    end
    return root.Position
end
function phowg:stable_prediction_lead(character, root, lead, velocity)
    local holds = Data.StablePredictionLead
    if not holds then
        holds = setmetatable({}, { __mode = 'k' })
        Data.StablePredictionLead = holds
    end
    local now = tick()
    local state = holds[character]
    if not state or state.Root ~= root then
        state = { Root = root, Lead = lead, At = now }
        holds[character] = state
        return lead
    end
    if lead.Magnitude > 0.05 then
        state.Lead, state.At = lead, now
        return lead
    end
    if now - state.At <= 0.2 and velocity and velocity.Magnitude > 0.5 then
        return state.Lead
    end
    state.Lead, state.At = lead, now
    return lead
end
function predpos(partPos, char, amt, multiplier, stable)
    if typeof(partPos) ~= 'Vector3' or not char then
        return partPos
    end
    local root = char:FindFirstChild('HumanoidRootPart')
    if not root then
        return partPos
    end
    local height = partPos.Y
    local resolved = stable and root.Position or phowg:resolved_root_position(char, root)
    if phowg:perfect_hit_vector(resolved) then
        partPos = partPos + (resolved - root.Position)
    end
    local now = tick()
    if Data.StrafePingAt == nil or now - Data.StrafePingAt >= 0.5 then
        Data.StrafePingAt = now
        local ok, ping = pcall(function()
            return LocalPlayer:GetNetworkPing()
        end)
        Data.StrafePing = ok and type(ping) == 'number' and ping == ping and math.clamp(ping, 0, 0.2) or 0
    end
    local lead, velocity = phowg:adaptive_prediction(char, root, stable)
    if stable then
        lead = phowg:stable_prediction_lead(char, root, lead, velocity)
    end
    lead *= 1.2
    local humanoid = char:FindFirstChildOfClass('Humanoid')
    local motion = Data.ResolvedMotion and Data.ResolvedMotion[char]
    if humanoid and humanoid.FloorMaterial ~= Enum.Material.Air and not (motion and motion.Vehicle) then
        return Vector3.new(partPos.X + lead.X, height, partPos.Z + lead.Z)
    end
    return partPos + Vector3.new(lead.X, lead.Y * 0.7, lead.Z)
end
phowg:register_cleanup('strafe prediction', function(scope, reason)
    if reason == 'unload' or scope == LocalPlayer.Character then
        Data.ResolvedMotion = nil
        Data.MotionSampleSeen = nil
        Data.StrafePingAt = nil
        Data.StrafePing = nil
        Data.SmartStrafeCache = nil
        Data.SmartStrafe = nil
        Data.StrafeMuzzleOffsets = nil
        Data.StablePredictionLead = nil
    else
        if Data.ResolvedMotion then
            Data.ResolvedMotion[scope] = nil
        end
        if Data.StablePredictionLead then
            Data.StablePredictionLead[scope] = nil
        end
        for target, cached in pairs(Data.SmartStrafeCache or {}) do
            if scope == target or scope == cached.character then
                Data.SmartStrafeCache[target] = nil
            end
        end
    end
end)
function ispointinsidepart(part, point)
    if not part or not part.Parent or not part:IsA('BasePart') then
        return false
    end
    local ok, lp = pcall(function()
        return part.CFrame:PointToObjectSpace(point)
    end)
    if not ok or typeof(lp) ~= 'Vector3' then
        return false
    end
    local s = part.Size
    local e = 0.2
    return math.abs(lp.X) <= s.X / 2 + e and math.abs(lp.Y) <= s.Y / 2 + e and math.abs(lp.Z) <= s.Z / 2 + e
end
function phowg:restore_wallbang_hitboxes()
    for player, entry in pairs(Data.HitboxSet or {}) do
        if entry.part and entry.part.Parent then
            entry.part.Size = entry.size
        end
        if entry.hum and entry.hum.Parent and entry.hh ~= nil then
            entry.hum.HipHeight = entry.hh
        end
    end
    Data.HitboxSet = nil
end
function phowg:wallbang_filter(objects)
    if not Data.WallbangIgnored then
        return objects
    end
    local list = table.clone(objects)
    for _, object in ipairs(Data.WallbangIgnored) do
        if object.Parent and not table.find(list, object) then
            list[#list + 1] = object
        end
    end
    return list
end
function phowg:apply_wallbang(enabled)
    Data.AroundWallbangCache = nil
    Data.StrafeFilterRevision = (Data.StrafeFilterRevision or 0) + 1
    phowg:restore_wallbang_hitboxes()
    local saved = Data.WallbangModuleState
    if saved and saved.Module.Ignored == saved.Applied then
        saved.Module.Ignored = saved.Original
    end
    Data.WallbangModuleState, Data.WallbangIgnored = nil, nil
    phowg:set_grip_wallbang_observer(enabled)
    return true
end
phowg:register_cleanup('wallbang module', function(_, reason)
    if reason ~= 'unload' then
        return
    end
    phowg:restore_wallbang_hitboxes()
    local saved = Data.WallbangModuleState
    if saved and saved.Module.Ignored == saved.Applied then
        saved.Module.Ignored = saved.Original
    end
    Data.WallbangModuleState, Data.WallbangIgnored = nil, nil
end)
function gunwallclear(Target, origin)
    local myChar = LocalPlayer and LocalPlayer.Character
    local tch = Target and Target.Character or nil
    if not tch then
        return false
    end
    local aim = getreppart(tch) or tch:FindFirstChild('HumanoidRootPart')
    if not aim then
        return false
    end
    local from = origin or gunshootorigin()
    if not from then
        return true
    end
    local to = aim.Position
    local dir = to - from
    local dist = dir.Magnitude
    if dist < 0.5 then
        return true
    end
    local params = RaycastParams.new()
    params.FilterType = Enum.RaycastFilterType.Exclude
    params.FilterDescendantsInstances = phowg:wallbang_filter({ myChar, tch })
    params.RespectCanCollide = true
    params.IgnoreWater = true
    local cur = from
    local remain = dist
    for _ = 1, 4 do
        if remain <= 0.5 then
            return true
        end
        local hit = Workspace:Raycast(cur, dir.Unit * remain, params)
        if not hit or (hit.Instance and hit.Instance:IsDescendantOf(tch)) then
            return true
        end
        if hit.Instance and ispointinsidepart(hit.Instance, from) then
            local adv = (hit.Position - cur).Magnitude + 0.5
            if adv >= remain then
                return true
            end
            cur = cur + dir.Unit * adv
            remain = (to - cur).Magnitude
        else
            return false
        end
    end
    return true
end
local function getstraferotation(mode, root)
    if mode == 'random' then
        return CFrame.new().Rotation
    end
    if mode == 'random rotation' then
        return CFrame.Angles(
            math.rad(math.random(-180, 180)),
            math.rad(math.random(-180, 180)),
            math.rad(math.random(-180, 180))
        )
    end
    local cf = root and root.CFrame or CFrame.new()
    if (Data['CSyncTable'][2] or Data['MoveToInFlight'] == root) and typeof(Data['CSyncTable'][1]) == 'CFrame' then
        cf = Data['CSyncTable'][1]
    end
    local look = cf.LookVector
    local direction = Vector3.new(look.X, 0, look.Z)
    if direction.Magnitude < 0.001 then
        direction = Vector3.new(0, 0, -1)
    end
    return CFrame.lookAt(Vector3.zero, direction.Unit).Rotation
end
function phowg:strafe_ground_position(position, targetCharacter)
    local character = LocalPlayer.Character
    local root = character and character:FindFirstChild('HumanoidRootPart')
    if not root or typeof(position) ~= 'Vector3' then
        return position
    end
    local now = tick()
    local cache = Data.StrafeFloor
    if not cache or cache.Character ~= character or cache.Target ~= targetCharacter then
        local groundParams = RaycastParams.new()
        groundParams.FilterType = Enum.RaycastFilterType.Exclude
        local excluded = targetCharacter and { character, targetCharacter } or { character }
        local playersFolder = Workspace:FindFirstChild('Players')
        if playersFolder then
            excluded[#excluded + 1] = playersFolder
        end
        groundParams.FilterDescendantsInstances = excluded
        groundParams.RespectCanCollide, groundParams.IgnoreWater = true, true
        cache = { Character = character, Target = targetCharacter, At = now, Hits = {}, Params = groundParams }
        Data.StrafeFloor = cache
    elseif now - cache.At >= 0.05 or now < cache.At then
        table.clear(cache.Hits)
        cache.At = now
    end
    local humanoid = character:FindFirstChildOfClass('Humanoid')
    local leg = character:FindFirstChild('Left Leg')
    local clearance = math.max(
        2.25,
        (root.Size and root.Size.Y or 2) * 0.5
            + math.max(0, humanoid and humanoid.HipHeight or 2)
            + (leg and leg.Size.Y or 0)
    ) + 0.25
    local targetRoot = targetCharacter and targetCharacter:FindFirstChild('HumanoidRootPart')
    local referenceY = targetRoot and targetRoot.Position.Y or position.Y
    local probeY = math.max(position.Y, referenceY) + 32
    local key = tostring(position.X) .. ':' .. tostring(position.Z) .. ':' .. tostring(probeY)
    local cached = cache.Hits[key]
    if cached == nil then
        local hit = Workspace:Raycast(
            Vector3.new(position.X, probeY, position.Z),
            Vector3.new(0, -(probeY - math.min(position.Y, referenceY) + 256), 0),
            cache.Params
        )
        cached = hit and hit.Position and hit.Position.Y or false
        cache.Hits[key] = cached
    end
    local y = cached ~= false and math.max(position.Y, cached + clearance) or position.Y
    return Vector3.new(position.X, y, position.Z)
end
function phowg:strafe_ground_c_frame(cf, targetCharacter)
    if typeof(cf) ~= 'CFrame' then
        return cf
    end
    return CFrame.new(phowg:strafe_ground_position(cf.Position, targetCharacter)) * cf.Rotation
end
function phowg:orbit_strafe_c_frame(center, targetCharacter, indoor)
    local radius = tonumber(Options.target_strafe_radius and Options.target_strafe_radius.Value) or 15
    local height = tonumber(Options.target_strafe_height and Options.target_strafe_height.Value) or 0
    local speed = tonumber(Options.target_strafe_speed and Options.target_strafe_speed.Value) or 3
    local angle = tick() * math.pi * 2 * speed
    local position = center + Vector3.new(math.cos(angle) * radius, height, math.sin(angle) * radius)
    if not indoor then
        position = phowg:strafe_ground_position(position, targetCharacter)
    end
    return CFrame.lookAt(position, Vector3.new(center.X, position.Y, center.Z))
end
phowg:register_cleanup('strafe floor', function(scope)
    local cache = Data.StrafeFloor
    if cache and (not scope or scope == cache.Character or scope == cache.Target) then
        Data.StrafeFloor = nil
    end
end)
function phowg:record_strafe_muzzle(shot)
    local handle = shot.Handle
    if typeof(handle) ~= 'Instance' or not handle:IsA('BasePart') or typeof(shot.ForcedOrigin) ~= 'Vector3' then
        return
    end
    local offset = handle.CFrame:PointToObjectSpace(shot.ForcedOrigin)
    if offset.Magnitude ~= offset.Magnitude or offset.Magnitude > 12 then
        return
    end
    Data.StrafeMuzzleOffsets = Data.StrafeMuzzleOffsets or setmetatable({}, { __mode = 'k' })
    Data.StrafeMuzzleOffsets[handle] = offset
end
local function gettoolhandleoffset(character, tool)
    local root = character and character:FindFirstChild('HumanoidRootPart')
    if not root or not tool or tool.Parent ~= character then
        return nil, nil
    end
    local handle = tool:FindFirstChild('Handle')
    if not handle or not handle:IsA('BasePart') then
        return nil, nil
    end
    local rootCF, handleCF = root:GetPivot() * root.PivotOffset:Inverse(), handle.CFrame
    local nativeOffset = Data.StrafeMuzzleOffsets and Data.StrafeMuzzleOffsets[handle]
    local position
    if nativeOffset then
        position = handleCF:PointToWorldSpace(nativeOffset)
    else
        local default = tool:FindFirstChild('Default')
        local mesh = default and default:FindFirstChild('Mesh')
        local muzzle = mesh and mesh:FindFirstChild('Muzzle')
        if not muzzle then
            local name = normalizeweaponname(tool.Name)
            if name == 'revolver' then
                nativeOffset = Vector3.new(-1, 0.4, 0)
            elseif name == 'flintlock' or name == 'deagle' then
                nativeOffset = Vector3.new(0, 0.382, -1.568)
            elseif name == 'rifle' then
                nativeOffset = Vector3.new(0, 0.25, 2.5)
            elseif name == 'doublebarrelsg' then
                nativeOffset = Vector3.new(0, 0.35, -2.2)
            end
            muzzle = not nativeOffset and handle:FindFirstChild('Muzzle') or nil
        end
        if muzzle and muzzle:IsA('Attachment') then
            position = muzzle.WorldPosition
        elseif nativeOffset then
            position = handleCF:PointToWorldSpace(nativeOffset)
        else
            position = handleCF.Position
        end
    end
    local direction = position - handleCF.Position
    if direction.Magnitude < 0.01 then
        direction = handleCF.UpVector
    end
    direction = rootCF:VectorToObjectSpace(direction)
    if direction.Magnitude < 0.01 then
        direction = rootCF:VectorToObjectSpace(handleCF.LookVector)
    end
    if direction.Magnitude < 0.01 then
        direction = Vector3.new(0, 0, -1)
    end
    return rootCF:PointToObjectSpace(position), direction.Unit
end
function phowg:smart_strafe_rotation(heading, direction, fallbackRotation, roll)
    local localUp = Vector3.yAxis
    if math.abs(heading.Unit:Dot(localUp)) > 0.98 then
        localUp = Vector3.xAxis
    end
    local worldUp = fallbackRotation.UpVector
    if math.abs(direction.Unit:Dot(worldUp)) > 0.98 then
        worldUp = fallbackRotation.RightVector
    end
    local localFrame = CFrame.lookAt(Vector3.zero, heading, localUp)
    local worldFrame = CFrame.lookAt(Vector3.zero, direction, worldUp)
    return worldFrame.Rotation * CFrame.Angles(0, 0, roll or 0) * localFrame.Rotation:Inverse()
end
function phowg:smart_strafe_c_frame(position, aimPosition, muzzleOffset, muzzleDirection, fallbackRotation, roll)
    local delta = aimPosition - position
    if delta.Magnitude < 0.001 then
        return CFrame.new(position) * fallbackRotation, false
    end
    local direction = muzzleDirection.Magnitude < 0.001 and Vector3.new(0, 0, -1) or muzzleDirection.Unit
    local along = muzzleOffset:Dot(direction)
    local discriminant = along * along + delta:Dot(delta) - muzzleOffset:Dot(muzzleOffset)
    local travel = discriminant >= 0 and -along + math.sqrt(discriminant) or -1
    local aligned = travel > 0.001
    local heading = aligned and muzzleOffset + direction * travel or direction
    return CFrame.new(position) * phowg:smart_strafe_rotation(heading, delta, fallbackRotation, roll), aligned
end
function phowg:smart_strafe_muzzle_c_frame(origin, aimPosition, muzzleOffset, muzzleDirection, fallbackRotation, roll)
    local direction = aimPosition - origin
    if direction.Magnitude < 0.001 then
        return CFrame.new(origin - fallbackRotation:VectorToWorldSpace(muzzleOffset)) * fallbackRotation, false
    end
    local heading = muzzleDirection.Magnitude < 0.001 and Vector3.new(0, 0, -1) or muzzleDirection.Unit
    local rotation = phowg:smart_strafe_rotation(heading, direction, fallbackRotation, roll)
    return CFrame.new(origin - rotation:VectorToWorldSpace(muzzleOffset)) * rotation, true
end
function phowg:strafe_aim_part(target)
    local character = target and target.Character
    if not character then
        return nil
    end
    return character:FindFirstChild('Head')
        or character:FindFirstChild('UpperTorso')
        or character:FindFirstChild('Torso')
        or character:FindFirstChild('HumanoidRootPart')
end
function phowg:strafe_shot_params(character, targetCharacter)
    local params = RaycastParams.new()
    params.FilterType = Enum.RaycastFilterType.Exclude
    local excluded = { character, targetCharacter }
    local ignored = Workspace:FindFirstChild('Ignored')
    if ignored then
        excluded[#excluded + 1] = ignored
    end
    params.FilterDescendantsInstances = excluded
    params.IgnoreWater = true
    return params
end
function phowg:refresh_native_shot_params(params)
    if params.FilterType ~= Enum.RaycastFilterType.Exclude then
        return
    end
    local now = tick()
    local ignored = Data.NativeShotIgnored
    if not ignored or now >= (Data.NativeShotIgnoredAt or 0) then
        local list, seen = {}, {}
        local function add(object)
            if typeof(object) == 'Instance' and object.Parent and not seen[object] then
                seen[object] = true
                list[#list + 1] = object
            end
        end
        local module = Data.StrafeGunModule
        if not module then
            local source = ReplicatedStorage:FindFirstChild('MainModule')
            if source then
                local ok, result = pcall(require, source)
                if ok and type(result) == 'table' then
                    module, Data.StrafeGunModule = result, result
                end
            end
        end
        for _, object in ipairs(type(module) == 'table' and type(module.Ignored) == 'table' and module.Ignored or {}) do
            add(object)
        end
        for _, player in ipairs(Players:GetPlayers()) do
            local character = player.Character
            local flight = character and character:FindFirstChild('BatmanFlight')
            if
                character
                and (
                    character:GetAttribute('AdminInvisible') == true
                    or character:GetAttribute('BatmanFlight') == true
                        and flight
                        and flight:GetAttribute('HumanoidFlight') ~= true
                )
            then
                add(character)
            end
        end
        ignored, Data.NativeShotIgnored, Data.NativeShotIgnoredAt = list, list, now + 0.25
    end
    local filters = Data.NativeShotFilters
    if not filters then
        filters = setmetatable({}, { __mode = 'k' })
        Data.NativeShotFilters = filters
    end
    local state = filters[params]
    if state and state.List == ignored then
        return
    end
    if not state then
        state = { Base = params.FilterDescendantsInstances }
        filters[params] = state
    end
    local excluded = table.clone(state.Base)
    for _, object in ipairs(ignored) do
        if not table.find(excluded, object) then
            excluded[#excluded + 1] = object
        end
    end
    params.FilterDescendantsInstances = excluded
    state.List = ignored
end
function phowg:strafe_shot_clear(origin, position, params)
    local direction = position - origin
    if direction.Magnitude <= 0.05 then
        return true, 1, nil
    end
    phowg:refresh_native_shot_params(params)
    local hit = Workspace:Raycast(origin, direction, params)
    if not hit then
        return true, 1, nil
    end
    return false, math.clamp((hit.Position - origin).Magnitude / direction.Magnitude, 0, 1), hit
end
function phowg:smart_strafe_pose_aligned(cf, position, muzzleOffset, muzzleDirection)
    local delta = position - cf:PointToWorldSpace(muzzleOffset)
    return delta.Magnitude > 0.05 and cf:VectorToWorldSpace(muzzleDirection):Dot(delta.Unit) >= 0.9995
end
function phowg:chinese_cover_allowed(part)
    if
        not part
        or not part.Parent
        or not part:IsA('BasePart')
        or part.CanQuery == false
        or (part.Transparency or 0) > 0.05
        or (part.LocalTransparencyModifier or 0) > 0.05
    then
        return false
    end
    local assembly = part.AssemblyRootPart
    return part.Anchored or assembly ~= nil and assembly.Anchored == true
end
function phowg:chinese_wall_point(part: any, position: any, face: number?)
    if not phowg:chinese_cover_allowed(part) then
        return nil
    end
    local half = part.Size * 0.5
    local point = part.CFrame:PointToObjectSpace(position)
    local best, bestNormal, bestThickness, bestDistance
    for axisIndex, axis in ipairs({ 'X', 'Y', 'Z' }) do
        if face and face ~= axisIndex * 2 - 1 and face ~= axisIndex * 2 then
            continue
        end
        local thickness = tonumber(part.Size[axis]) or 0
        local normal = axis == 'X' and Vector3.xAxis or axis == 'Y' and Vector3.yAxis or Vector3.zAxis
        local other = axis == 'X' and math.min(tonumber(part.Size.Y) or 0, tonumber(part.Size.Z) or 0)
            or axis == 'Y' and math.min(tonumber(part.Size.X) or 0, tonumber(part.Size.Z) or 0)
            or math.min(tonumber(part.Size.X) or 0, tonumber(part.Size.Y) or 0)
        if thickness > 0.02 and other > 0.02 then
            local sign = (tonumber(point[axis]) or 0) >= 0 and 1 or -1
            if face then
                sign = face % 2 == 1 and 1 or -1
            end
            normal = normal * sign
            local x = math.clamp(tonumber(point.X) or 0, -(tonumber(half.X) or 0), tonumber(half.X) or 0)
            local y = math.clamp(tonumber(point.Y) or 0, -(tonumber(half.Y) or 0), tonumber(half.Y) or 0)
            local z = math.clamp(tonumber(point.Z) or 0, -(tonumber(half.Z) or 0), tonumber(half.Z) or 0)
            if axis == 'X' then
                x = half.X * sign
            elseif axis == 'Y' then
                y = half.Y * sign
            else
                z = half.Z * sign
            end
            local surface = part.CFrame:PointToWorldSpace(Vector3.new(x, y, z))
            local distance = (surface - position).Magnitude
            if not bestDistance or distance < bestDistance then
                best, bestNormal, bestThickness, bestDistance =
                    surface, part.CFrame:VectorToWorldSpace(normal), thickness, distance
            end
        end
    end
    return best, bestNormal, bestThickness
end
function phowg:chinese_character_hull(character, tool)
    local root = character and character:FindFirstChild('HumanoidRootPart')
    if not root then
        return nil
    end
    local now, saved = tick(), Data.ChineseHull
    local physical = root:GetPivot() * root.PivotOffset:Inverse()
    if not saved or saved.Character ~= character or now >= saved.Expires then
        local names = Data.ChineseBodyPartNames
        if not names then
            names = {}
            for _, name in ipairs({
                'HumanoidRootPart',
                'Head',
                'Torso',
                'UpperTorso',
                'LowerTorso',
                'Left Arm',
                'Right Arm',
                'Left Leg',
                'Right Leg',
                'LeftUpperArm',
                'LeftLowerArm',
                'LeftHand',
                'RightUpperArm',
                'RightLowerArm',
                'RightHand',
                'LeftUpperLeg',
                'LeftLowerLeg',
                'LeftFoot',
                'RightUpperLeg',
                'RightLowerLeg',
                'RightFoot',
            }) do
                names[name] = true
            end
            Data.ChineseBodyPartNames = names
        end
        local minimum, maximum
        for _, object in ipairs(character:GetChildren()) do
            local accessory = object:IsA('Accessory')
            local part = accessory and object:FindFirstChild('Handle') or object
            if part and (names[part.Name] or accessory) and part:IsA('BasePart') then
                local frame = part == root and physical or part.CFrame
                local relative, half = physical:ToObjectSpace(frame), part.Size * 0.5
                for x = -1, 1, 2 do
                    for y = -1, 1, 2 do
                        for z = -1, 1, 2 do
                            local point = relative:PointToWorldSpace(Vector3.new(half.X * x, half.Y * y, half.Z * z))
                            minimum = minimum
                                    and Vector3.new(
                                        math.min(minimum.X, point.X),
                                        math.min(minimum.Y, point.Y),
                                        math.min(minimum.Z, point.Z)
                                    )
                                or point
                            maximum = maximum
                                    and Vector3.new(
                                        math.max(maximum.X, point.X),
                                        math.max(maximum.Y, point.Y),
                                        math.max(maximum.Z, point.Z)
                                    )
                                or point
                        end
                    end
                end
            end
        end
        if not minimum then
            return nil
        end
        local padding = Vector3.new(0.35, 0.35, 0.35)
        minimum, maximum = minimum - padding, maximum + padding
        local corners = { Vector3.zero }
        for x = 0, 1 do
            for y = 0, 1 do
                for z = 0, 1 do
                    corners[#corners + 1] = Vector3.new(
                        x == 0 and minimum.X or maximum.X,
                        y == 0 and minimum.Y or maximum.Y,
                        z == 0 and minimum.Z or maximum.Z
                    )
                end
            end
        end
        saved = {
            Character = character,
            Expires = now + 0.2,
            Corners = corners,
            Tools = setmetatable({}, { __mode = 'k' }),
        }
        Data.ChineseHull = saved
    end
    local key = tool or character
    local hull = saved.Tools[key]
    if not hull then
        hull = { Corners = saved.Corners }
        saved.Tools[key] = hull
    end
    local head = character:FindFirstChild('Head')
    local handle = tool and tool:FindFirstChild('Handle')
    hull.Head = head and physical:PointToObjectSpace(head.Position)
    hull.Handle = handle and physical:PointToObjectSpace(handle.Position)
    return hull
end
function phowg:chinese_hull_depth(part, cf, hull)
    if not hull then
        return nil
    end
    local depth = math.huge
    for _, corner in ipairs(hull.Corners) do
        depth = math.min(depth, phowg:chinese_wall_depth(part, cf:PointToWorldSpace(corner)))
        if depth <= 0 then
            return nil
        end
    end
    return depth
end
function phowg:chinese_shape_hidden(part, cf, hull)
    if part:IsA('Part') and part.Shape == Enum.PartType.Block then
        return true
    end
    local params = Data.ChineseShapeParams
    if not params then
        params = RaycastParams.new()
        params.FilterType, params.IgnoreWater = Enum.RaycastFilterType.Include, true
        Data.ChineseShapeParams = params
    end
    params.FilterDescendantsInstances = { part }
    local reach = part.Size.Magnitude + 1
    for index = 1, #hull.Corners + (hull.Handle and 1 or 0) do
        local point = cf:PointToWorldSpace(hull.Corners[index] or hull.Handle)
        local radial = point - part.Position
        local direction = radial.Magnitude > 0.001 and radial.Unit or part.CFrame.RightVector
        local outside = point + direction * reach
        local hit = Workspace:Raycast(outside, point - outside, params)
        if not hit or hit.Instance ~= part or (hit.Position - outside).Magnitude >= reach - 0.001 then
            return false
        end
    end
    return true
end
function phowg:chinese_shot_clear(origin, position, cached, cf, hull)
    local wall = cached.wall
    if not phowg:chinese_cover_allowed(wall) or not ispointinsidepart(wall, origin) then
        return false
    end
    local now = tick()
    local ranked = Players:GetAttribute('RankedWallShotsBanned')
    local previous = cached.ValidatedShot
    local revision = Data.StrafeFilterRevision or 0
    if
        previous
        and previous.Wall == wall
        and previous.WallCF == wall.CFrame
        and previous.WallSize == wall.Size
        and previous.CF == cf
        and previous.Hull == hull
        and previous.Ranked == ranked
        and previous.Revision == revision
        and now - previous.At < 0.05
        and (previous.Origin - origin).Magnitude <= 0.01
        and (previous.Position - position).Magnitude <= 0.01
    then
        return previous.Clear
    end
    local function finish(clear)
        cached.ValidatedShot = {
            Wall = wall,
            WallCF = wall.CFrame,
            WallSize = wall.Size,
            CF = cf,
            Hull = hull,
            Ranked = ranked,
            Revision = revision,
            At = now,
            Origin = origin,
            Position = position,
            Clear = clear,
        }
        return clear
    end
    if cf and hull and not phowg:chinese_hull_depth(wall, cf, hull) then
        return finish(false)
    end
    if not cached.wallParams or now >= (cached.ShotFilterAt or 0) or cached.ShotFilterRevision ~= revision then
        local params = RaycastParams.new()
        params.FilterType = Enum.RaycastFilterType.Exclude
        local excluded = table.clone(cached.params.FilterDescendantsInstances)
        local saved = Data.WallbangModuleState
        local module = saved and saved.Module or Data.StrafeGunModule
        if not module and now >= (Data.StrafeGunModuleAt or 0) then
            Data.StrafeGunModuleAt = now + 2
            local source = ReplicatedStorage:FindFirstChild('MainModule')
            if source then
                local ok, result = pcall(require, source)
                if ok and type(result) == 'table' then
                    module = result
                    Data.StrafeGunModule = result
                end
            end
        end
        for _, object in ipairs(type(module) == 'table' and type(module.Ignored) == 'table' and module.Ignored or {}) do
            if typeof(object) == 'Instance' and object.Parent and not table.find(excluded, object) then
                excluded[#excluded + 1] = object
            end
        end
        params.FilterDescendantsInstances, params.IgnoreWater = excluded, true
        cached.wallParams, cached.ShotFilterAt, cached.ShotFilterRevision = params, now + 0.5, revision
    end
    if not phowg:strafe_shot_clear(origin, position, cached.wallParams) then
        return finish(false)
    end
    if hull and hull.Handle and cf then
        local handleOrigin = cf:PointToWorldSpace(hull.Handle)
        if
            not ispointinsidepart(wall, handleOrigin)
            or not phowg:strafe_shot_clear(handleOrigin, position, cached.wallParams)
        then
            return finish(false)
        end
    end
    if cf and hull and not phowg:chinese_shape_hidden(wall, cf, hull) then
        return finish(false)
    end
    if ranked then
        if not cf or not hull or not hull.Head then
            return finish(false)
        end
        local map = Workspace:FindFirstChild('MAP')
        if not map then
            return finish(false)
        end
        local params = cached.HeadParams
        if not params then
            params = RaycastParams.new()
            params.FilterType = Enum.RaycastFilterType.Include
            params.RespectCanCollide = true
            cached.HeadParams = params
        end
        params.FilterDescendantsInstances = { map }
        local head = cf:PointToWorldSpace(hull.Head)
        if Workspace:Raycast(head, origin - head, params) then
            return finish(false)
        end
    end
    return finish(true)
end
function phowg:chinese_wall_depth(part: any, point: any)
    local localPoint = part.CFrame:PointToObjectSpace(point)
    local half = part.Size * 0.5
    return math.min(half.X - math.abs(localPoint.X), half.Y - math.abs(localPoint.Y), half.Z - math.abs(localPoint.Z))
end
function phowg:chinese_wall_pose(
    part: any,
    origin: any,
    aimPosition: any,
    offset: any,
    direction: any,
    rotation: any,
    normal: any,
    hull: any
)
    local function solve(roll, freeRotation)
        local trialOrigin = origin
        local function pose(point)
            if freeRotation then
                return CFrame.new(point - freeRotation:VectorToWorldSpace(offset)) * freeRotation, true
            end
            return phowg:smart_strafe_muzzle_c_frame(point, aimPosition, offset, direction, rotation, roll)
        end
        local cf, aligned = pose(trialOrigin)
        if not cf or not aligned or not hull then
            return nil, false, trialOrigin
        end
        local half = part.Size * 0.5
        for _ = 1, 3 do
            local point = part.CFrame:PointToObjectSpace(trialOrigin)
            local minimum, maximum = Vector3.zero, Vector3.zero
            for index = 1, #hull.Corners + (hull.Handle and 1 or 0) do
                local corner = hull.Corners[index] or hull.Handle
                local relative = part.CFrame:VectorToObjectSpace(cf:VectorToWorldSpace(corner - offset))
                minimum = Vector3.new(
                    math.min((tonumber(minimum.X) or 0), (tonumber(relative.X) or 0)),
                    math.min((tonumber(minimum.Y) or 0), (tonumber(relative.Y) or 0)),
                    math.min((tonumber(minimum.Z) or 0), (tonumber(relative.Z) or 0))
                )
                maximum = Vector3.new(
                    math.max((tonumber(maximum.X) or 0), (tonumber(relative.X) or 0)),
                    math.max((tonumber(maximum.Y) or 0), (tonumber(relative.Y) or 0)),
                    math.max((tonumber(maximum.Z) or 0), (tonumber(relative.Z) or 0))
                )
            end
            local function fit(axis)
                local extent = (tonumber(half[axis]) or 0) - 0.01
                local low, high = -extent - (tonumber(minimum[axis]) or 0), extent - (tonumber(maximum[axis]) or 0)
                if low > high then
                    return nil
                end
                return math.clamp(tonumber(point[axis]) or 0, tonumber(low) or 0, tonumber(high) or 0)
            end
            local x, y, z = fit('X'), fit('Y'), fit('Z')
            if not x or not y or not z then
                return nil, false, trialOrigin
            end
            local adjusted = Vector3.new(x, y, z)
            if (adjusted - point).Magnitude <= 0.001 then
                break
            end
            trialOrigin = part.CFrame:PointToWorldSpace(adjusted)
            cf, aligned = pose(trialOrigin)
            if not cf or not aligned then
                return nil, false, trialOrigin
            end
            if freeRotation then
                break
            end
        end
        return cf, aligned, trialOrigin, roll, freeRotation ~= nil
    end
    for _, requested in ipairs({ 0, math.pi * 0.5, -math.pi * 0.5, math.pi * 0.25, -math.pi * 0.25 }) do
        local cf, aligned, point, roll = solve(requested)
        if
            cf
            and phowg:chinese_hull_depth(part, cf, hull)
            and (not hull.Handle or phowg:chinese_wall_depth(part, cf:PointToWorldSpace(hull.Handle)) > 0)
        then
            return cf, aligned, point, roll
        end
    end
    local orientations = Data.ChineseBoxOrientations
    if not orientations then
        orientations = {}
        for _, forward in ipairs({
            Vector3.xAxis,
            -Vector3.xAxis,
            Vector3.yAxis,
            -Vector3.yAxis,
            Vector3.zAxis,
            -Vector3.zAxis,
        }) do
            local up = math.abs(forward.Y) > 0.9 and Vector3.zAxis or Vector3.yAxis
            local basis = CFrame.lookAt(Vector3.zero, forward, up)
            for step = 0, 3 do
                orientations[#orientations + 1] = basis * CFrame.Angles(0, 0, step * math.pi * 0.5)
            end
        end
        Data.ChineseBoxOrientations = orientations
    end
    for _, orientation in ipairs(orientations) do
        local cf, aligned, point, roll, free = solve(0, part.CFrame.Rotation * orientation)
        if
            cf
            and phowg:chinese_hull_depth(part, cf, hull)
            and (not hull.Handle or phowg:chinese_wall_depth(part, cf:PointToWorldSpace(hull.Handle)) > 0)
        then
            return cf, aligned, point, roll, free
        end
    end
    return nil, false, origin
end
function phowg:take_chinese_search_work(cached, now)
    local workers = Data.ChineseWorkers or {}
    Data.ChineseWorkers = workers
    cached.WorkRequestedAt = now
    if not cached.WorkQueued then
        workers[#workers + 1] = cached
        cached.WorkQueued = true
    end
    while #workers > 0 do
        local first = workers[1]
        if now - (first.WorkRequestedAt or -math.huge) <= 0.25 and first.localCharacter == LocalPlayer.Character then
            break
        end
        first.WorkQueued = nil
        table.remove(workers, 1)
    end
    if now < (Data.ChineseWorkAt or 0) or workers[1] ~= cached then
        return false
    end
    table.remove(workers, 1)
    cached.WorkQueued = nil
    Data.ChineseWorkAt = now + 0.05
    return true
end
function phowg:chinese_depth_range(surface: any, normal: any, center: any, radius: number, lower: number, upper: number)
    local delta = surface - center
    local projection = tonumber(delta:Dot(normal)) or 0
    local square = tonumber(delta:Dot(delta)) or math.huge
    local discriminant = projection * projection + radius * radius - square
    if discriminant < 0 then
        return nil
    end
    local reach = math.sqrt(discriminant)
    local first, last = math.max(lower, projection - reach), math.min(upper, projection + reach)
    if first > last then
        return nil
    end
    return first, last
end
function phowg:chinese_strafe_band(tool)
    local value = tool and tool:FindFirstChild('Range')
    local range = value and tonumber(value.Value) or tool and tonumber(tool:GetAttribute('Range')) or 200
    if not range or range ~= range or range <= 0 or range == math.huge then
        return nil
    end
    local maximum = math.min(300, math.max(range - 40, range * 0.5))
    if maximum < 10 then
        return nil
    end
    return 10, maximum
end
function phowg:chinese_travel_advance(cached, applied)
    local route = cached and cached.Travel
    if not route then
        return true
    end
    if Data.ChineseTravelOwner ~= cached then
        return false
    end
    local point = route.Points[route.Stage]
    if typeof(applied) == 'CFrame' and point and (applied.Position - point.Position).Magnitude < 2 then
        route.Stage += 1
        if route.Stage > #route.Points then
            cached.ArrivedCF, cached.ArrivedWall = route.Final, route.Wall
            cached.Travel = nil
            return true
        end
    end
    return false
end
function phowg:chinese_transfer_active(target)
    if not Options.target_strafe_mode or Options.target_strafe_mode.Value ~= 'chinese' then
        return false
    end
    local cached = Data.SmartStrafeCache and Data.SmartStrafeCache[target]
    return cached ~= nil
        and cached.mode == 'chinese'
        and cached.localCharacter == LocalPlayer.Character
        and cached.character == (target and target.Character)
        and (
            cached.VoidFallback == true
            or cached.Travel ~= nil and tick() - (cached.Travel.UpdatedAt or -math.huge) <= 0.5
        )
end
function phowg:chinese_travel_c_frame(destination, cached, center)
    local character = LocalPlayer.Character
    local root = character and character:FindFirstChild('HumanoidRootPart')
    if not root then
        return nil
    end
    local age = tick() - (Data.AppliedServerAt or -math.huge)
    local applied = Data.AppliedServerCharacter == character and age >= 0 and age <= 0.25 and Data.AppliedServerCF
        or nil
    local from = typeof(applied) == 'CFrame' and applied or Local_Data.ClientPos or root.CFrame
    if typeof(from) ~= 'CFrame' then
        from = root.CFrame
    end
    if Data.ChineseTravelOwner ~= cached then
        cached.Travel, cached.ArrivedCF, cached.ArrivedWall = nil, nil, nil
        Data.ChineseTravelOwner = cached
    end
    local route = cached.Travel
    if route then
        local changedWall = route.Wall ~= cached.wall
        local shallower = route.Depth > math.min(center.Y, destination.Position.Y) - 60
        local interrupted = route.Stage > 1
            and from.Position.Y > route.Depth + 2
            and (route.Stage ~= 3 or (from.Position - route.Final.Position).Magnitude >= 2)
        if changedWall or shallower or interrupted then
            route = nil
            cached.Travel = nil
        end
    end
    if route then
        local changed = (route.Final.Position - destination.Position).Magnitude > 0.05
        if changed and route.Stage == 3 then
            route = nil
            cached.Travel = nil
        else
            route.Final = destination
            route.Points[2] = CFrame.new(destination.Position.X, route.Depth, destination.Position.Z)
                * destination.Rotation
            route.Points[3] = destination
        end
    end
    if not route then
        local arrived = cached.ArrivedCF
        if
            arrived
            and cached.ArrivedWall == cached.wall
            and (arrived.Position - destination.Position).Magnitude <= 0.05
            and (from.Position - destination.Position).Magnitude <= 0.25
        then
            cached.ArrivedCF = destination
            return destination
        end
        local depth = math.min(center.Y, from.Position.Y, destination.Position.Y) - 60
        if cached.wall then
            depth = math.min(depth, cached.wall.Position.Y - cached.wall.Size.Magnitude * 0.5 - 25)
        end
        route = {
            Final = destination,
            Wall = cached.wall,
            Depth = depth,
            Stage = 1,
            Points = {
                CFrame.new(from.Position.X, depth, from.Position.Z) * destination.Rotation,
                CFrame.new(destination.Position.X, depth, destination.Position.Z) * destination.Rotation,
                destination,
            },
        }
        cached.Travel = route
    end
    route.UpdatedAt = tick()
    if phowg:chinese_travel_advance(cached, applied) then
        return destination
    end
    return route.Points[route.Stage]
end
function phowg:cancel_chinese_strafe()
    local active = Data.ChineseHolding == true
    for _, entry in pairs(Data.SmartStrafeCache or {}) do
        if entry.mode == 'chinese' then
            for _, cached in pairs(entry.ToolCaches or { entry }) do
                cached.Search, cached.Travel, cached.VoidFallback, cached.FallbackCF, cached.RandomFallback, cached.FallbackAt, cached.ValidatedShot =
                    nil, nil, nil, nil, nil, nil, nil
                cached.ArrivedCF, cached.ArrivedWall = nil, nil
                cached.NextSearchAt, cached.SearchCenter, cached.SearchRange = nil, nil, nil
                cached.WorkQueued, cached.WorkRequestedAt = nil, nil
                cached.wall, cached.wallCF, cached.cf, cached.clear = nil, nil, nil, false
            end
        end
    end
    Data.ChineseTravelOwner = nil
    Data.ChineseHull = nil
    Data.ChineseGeometryCache = nil
    for _, cached in ipairs(Data.ChineseWorkers or {}) do
        cached.WorkQueued, cached.WorkRequestedAt = nil, nil
    end
    Data.ChineseHolding, Data.ChineseRequestedAt, Data.ChineseWorkAt, Data.ChineseWorkers = nil, nil, nil, nil
    if Data.SmartStrafe and Data.SmartStrafe.mode == 'chinese' then
        Data.SmartStrafe = nil
    end
    if active then
        releasemovement('Combat')
        releasemovement('TargetStrafe')
        phowg:cancel_c_frame_movement({ Combat = true, TargetStrafe = true })
    end
end
function phowg:chinese_fallback_c_frame(cached)
    cached.Travel, cached.wallCF, cached.wall, cached.ValidatedShot = nil, nil, nil, nil
    cached.ArrivedCF, cached.ArrivedWall, Data.ChineseTravelOwner = nil, nil, nil
    cached.RandomFallback, cached.clear = nil, false
    cached.VoidFallback = true
    cached.FallbackCF = getvoidcframe()
    cached.cf = cached.FallbackCF
    return cached.FallbackCF
end
function phowg:chinese_nearby_parts(cached, origin, radius, params, slot)
    local cache = Data.ChineseGeometryCache
    if not cache then
        cache = setmetatable({}, { __mode = 'k' })
        Data.ChineseGeometryCache = cache
    end
    local character = cached.character
    local record = cache[character]
    local filters = params.FilterDescendantsInstances
    local same = record
        and record.LocalCharacter == cached.localCharacter
        and record.FilterType == params.FilterType
        and record.RespectCanCollide == params.RespectCanCollide
        and record.MaxParts == params.MaxParts
        and #record.Filters == #filters
    if same then
        for index, filter in ipairs(filters) do
            if record.Filters[index] ~= filter then
                same = false
                break
            end
        end
    end
    if not same then
        record = {
            LocalCharacter = cached.localCharacter,
            Filters = table.clone(filters),
            FilterType = params.FilterType,
            RespectCanCollide = params.RespectCanCollide,
            MaxParts = params.MaxParts,
            Queries = {},
        }
        cache[character] = record
    end
    slot = radius == 300 and 0 or slot
    local entry = record.Queries[slot]
    local now = tick()
    if
        entry
        and entry.Radius == radius
        and now - entry.At < 0.2
        and (entry.Origin == origin or entry.Complete and (entry.Origin - origin).Magnitude + radius <= entry.Coverage)
    then
        return entry.Parts
    end
    local coverage = record.Partial and radius or radius + 10
    local parts = Workspace:GetPartBoundsInRadius(origin, coverage, params)
    local complete = params.MaxParts == 0 or #parts < params.MaxParts
    if not complete and coverage > radius then
        record.Partial = true
        parts = Workspace:GetPartBoundsInRadius(origin, radius, params)
        coverage = radius
    end
    record.Queries[slot] =
        { Origin = origin, Radius = radius, Coverage = coverage, Complete = complete, At = now, Parts = parts }
    return parts
end
function phowg:chinese_strafe_c_frame(
    target,
    tool,
    cached: any,
    center: any,
    aimPosition: any,
    offset: any,
    direction: any,
    rotation: any
)
    local minimum, maximum = phowg:chinese_strafe_band(tool)
    if
        type(minimum) ~= 'number'
        or type(maximum) ~= 'number'
        or Data.SafeMode
        or Library.Unloaded
        or Data.SharedSignalsClosed
    then
        return nil
    end
    local targetRoot = target.Character and target.Character:FindFirstChild('HumanoidRootPart')
    if not targetRoot then
        return nil
    end
    center = targetRoot.Position
    local now = tick()
    local hull = phowg:chinese_character_hull(cached.localCharacter, tool)
    if not hull then
        return nil
    end
    local function evaluate(part, face)
        local surface, normal, thickness = phowg:chinese_wall_point(part, aimPosition, face)
        local wallThickness = tonumber(thickness)
        if not surface or not wallThickness then
            return nil
        end
        local inset = 0.01
        local lower, upper = phowg:chinese_depth_range(surface, normal, aimPosition, maximum, inset, wallThickness - inset)
        if not lower or not upper then
            return nil
        end
        local depths = { math.clamp(wallThickness * 0.5, lower, upper), (lower + upper) * 0.5, upper, lower }
        for index = 1, 4 do
            local depth = depths[index]
            if not depth then
                break
            end
            local origin = surface - normal * math.clamp(depth, lower, upper)
            local cf, aligned, adjustedOrigin, roll, free =
                phowg:chinese_wall_pose(part, origin, aimPosition, offset, direction, rotation, normal, hull)
            origin = adjustedOrigin
            if cf and index == 1 then
                local worldOffset = cf:VectorToWorldSpace(offset)
                local rootSurface = origin + normal * depth - worldOffset
                local rootLower, rootUpper = phowg:chinese_depth_range(rootSurface, normal, center, maximum, lower, upper)
                if rootLower and rootUpper then
                    lower, upper = rootLower, rootUpper
                    local delta = tonumber(normal:Dot(worldOffset)) or 0
                    depths[2] = math.clamp((wallThickness - delta) * 0.5, lower, upper)
                    depths[3], depths[4] = upper, (lower + upper) * 0.5
                end
            end
            if
                cf
                and aligned
                and (cf.Position - center).Magnitude <= maximum
                and (cf.Position - center).Magnitude >= minimum
                and (origin - aimPosition).Magnitude <= maximum
                and (free or phowg:smart_strafe_pose_aligned(cf, aimPosition, offset, direction))
            then
                local inside = math.min(
                    tonumber(phowg:chinese_wall_depth(part, origin)) or 0,
                    tonumber(phowg:chinese_hull_depth(part, cf, hull)) or 0
                )
                if inside > 0.001 then
                    cached.wall = part
                    if phowg:chinese_shot_clear(origin, aimPosition, cached, cf, hull) then
                        cached.wallDepth, cached.wallNormal, cached.roll, cached.wallFace =
                            inside, normal, roll or 0, face
                        cached.FreeRotation = free == true
                        return cf
                    end
                end
            end
        end
        cached.wall = nil
        return nil
    end
    if not phowg:take_chinese_search_work(cached, now) then
        local pose = cached.wall and cached.wall.Parent and cached.wallCF
        if pose and phowg:chinese_cover_allowed(cached.wall) and phowg:chinese_hull_depth(cached.wall, pose, hull) then
            local distance = (pose.Position - center).Magnitude
            if distance >= minimum and distance <= maximum then
                return pose
            end
        end
        return nil
    end
    if cached.wall and cached.wall.Parent then
        local previous = cached.wallCF
        if previous and phowg:chinese_cover_allowed(cached.wall) then
            local cf, aligned =
                phowg:smart_strafe_c_frame(previous.Position, aimPosition, offset, direction, rotation, cached.roll)
            if cached.FreeRotation then
                cf, aligned = previous, true
            end
            local origin = cf and cf:PointToWorldSpace(offset)
            local distance = cf and (cf.Position - center).Magnitude
            if
                cf
                and aligned
                and distance >= minimum
                and distance <= maximum
                and (origin - aimPosition).Magnitude <= maximum
                and phowg:chinese_hull_depth(cached.wall, cf, hull)
                and phowg:chinese_shot_clear(origin, aimPosition, cached, cf, hull)
            then
                cached.wallCF, cached.cf, cached.clear = cf, cf, true
                cached.center, cached.aim, cached.offset, cached.direction = center, aimPosition, offset, direction
                cached.VoidFallback, cached.FallbackCF, cached.Search = nil, nil, nil
                Data.SmartStrafe = cached
                return cf
            end
        end
        local cf = evaluate(cached.wall, cached.wallFace)
        if cf then
            cached.wallCF, cached.cf, cached.clear = cf, cf, true
            cached.center, cached.aim, cached.offset, cached.direction = center, aimPosition, offset, direction
            cached.VoidFallback, cached.FallbackCF, cached.Search, cached.RandomFallback = nil, nil, nil, nil
            Data.SmartStrafe = cached
            return cf
        end
        cached.wall, cached.wallCF, cached.wallDepth = nil, nil, nil
    end
    local search = cached.Search
    if search and (search.Range ~= maximum or (search.Center - center).Magnitude >= 15) then
        search = nil
        cached.Search = nil
    end
    if not search then
        if
            now < (cached.NextSearchAt or 0)
            and cached.SearchCenter
            and (center - cached.SearchCenter).Magnitude < 15
            and cached.SearchRange == maximum
        then
            return nil
        end
        local params = OverlapParams.new()
        params.FilterType = Enum.RaycastFilterType.Exclude
        local excluded = { cached.localCharacter, cached.character }
        local ignored, players = Workspace:FindFirstChild('Ignored'), Workspace:FindFirstChild('Players')
        if ignored then
            excluded[#excluded + 1] = ignored
        end
        if players then
            excluded[#excluded + 1] = players
        end
        params.FilterDescendantsInstances, params.RespectCanCollide, params.MaxParts = excluded, false, 128
        local probeParams = phowg:strafe_shot_params(cached.localCharacter, cached.character)
        probeParams.FilterDescendantsInstances = excluded
        probeParams.RespectCanCollide = false
        cached.chineseProbeParams = probeParams
        search = {
            Center = center,
            Range = maximum,
            Params = params,
            Query = 0,
            Parts = {},
            Index = 1,
            Candidates = {},
            CandidateIndex = 1,
            Seen = {},
            Probe = 0,
            ProbesDone = 0,
            ProbePhase = 0,
            ProbeSeen = {},
        }
        cached.Search, cached.SearchCenter, cached.SearchRange = search, center, maximum
    end
    local began = os.clock()
    local checked = 0
    if search.ProbePhase == 0 then
        search.ProbePhase = 1
        for _ = 1, 2 do
            local probe = search.Probe
            local horizontal = math.max(0, probe - 2)
            local angle = (horizontal % 24) * math.pi / 12
            local layer = math.floor(horizontal / 24)
            local height = probe < 2 and 0 or layer == 1 and -12 or layer == 2 and 12 or 0
            search.Probe = (probe + 1) % 74
            search.ProbesDone += 1
            local radial = probe == 0 and Vector3.yAxis * -1
                or probe == 1 and Vector3.yAxis
                or Vector3.new(math.cos(angle), 0, math.sin(angle))
            local from = Vector3.new(center.X, aimPosition.Y + height, center.Z)
            local hit = Workspace:Raycast(from, radial * 300, cached.chineseProbeParams or cached.params)
            local part = hit and hit.Instance
            if part and now - (search.ProbeSeen[part] or -math.huge) >= 0.25 then
                search.ProbeSeen[part] = now
                checked += 1
                local cf = evaluate(part)
                if cf then
                    cached.wallCF, cached.cf, cached.clear = cf, cf, true
                    cached.center, cached.aim, cached.offset, cached.direction = center, aimPosition, offset, direction
                    cached.VoidFallback, cached.FallbackCF, cached.Search, cached.RandomFallback = nil, nil, nil, nil
                    cached.NextSearchAt = nil
                    Data.SmartStrafe = cached
                    return cf
                end
            end
        end
    else
        search.ProbePhase = 0
    end
    if search.Index <= #search.Parts then
        local last = math.min(#search.Parts, search.Index + 15)
        for index = search.Index, last do
            local part: any = search.Parts[index]
            if not search.Seen[part] then
                search.Seen[part] = true
                for face = 1, 6 do
                    local surface = phowg:chinese_wall_point(part, aimPosition, face)
                    if surface then
                        local distance = (surface - center).Magnitude
                        if distance <= 300 + math.min(tonumber(part.Size.Magnitude) or 0, 300) then
                            search.Candidates[#search.Candidates + 1] = {
                                Part = part,
                                Face = face,
                                Distance = distance,
                                Depth = math.min(
                                    tonumber(part.Size.X) or 0,
                                    tonumber(part.Size.Y) or 0,
                                    tonumber(part.Size.Z) or 0
                                ) * 0.5,
                            }
                        end
                    end
                end
            end
        end
        search.Index = last + 1
        if search.Index <= #search.Parts then
            return nil
        end
        table.sort(search.Candidates, function(a, b)
            if a.Distance ~= b.Distance then
                return a.Distance > b.Distance
            end
            return a.Depth > b.Depth
        end)
    end
    while search.CandidateIndex <= #search.Candidates and checked < 4 and os.clock() - began < 0.0015 do
        local candidate = search.Candidates[search.CandidateIndex]
        search.CandidateIndex += 1
        checked += 1
        local cf = evaluate(candidate.Part, candidate.Face)
        if cf then
            cached.wallCF, cached.cf, cached.clear = cf, cf, true
            cached.center, cached.aim, cached.offset, cached.direction = center, aimPosition, offset, direction
            cached.VoidFallback, cached.FallbackCF, cached.Search, cached.RandomFallback = nil, nil, nil, nil
            cached.NextSearchAt = nil
            Data.SmartStrafe = cached
            return cf
        end
        if os.clock() - began >= 0.0015 then
            break
        end
    end
    if search.CandidateIndex <= #search.Candidates then
        return nil
    end
    local queries = search.Saturated and 31 or 19
    if search.Query >= queries then
        if search.ProbesDone < 74 then
            return nil
        end
        cached.Search, cached.wall, cached.wallCF, cached.Travel = nil, nil, nil, nil
        cached.NextSearchAt = now + 0.35
        return nil
    end
    search.Query += 1
    if search.Query == 1 then
        search.NearAt = now + 0.75
    end
    local origin, radius = center, 300
    if search.Query >= 2 and search.Query <= 7 then
        local axis = math.floor((search.Query - 2) / 2)
        local sign = search.Query % 2 == 0 and 1 or -1
        local axisDirection = axis == 0 and Vector3.xAxis or axis == 1 and Vector3.yAxis or Vector3.zAxis
        origin, radius = center + axisDirection * sign * 200, 140
    elseif search.Query > 7 then
        local sector = search.Query - 8
        local angle = (sector % 12) * math.pi / 6
        local height = sector < 12 and 0 or sector % 2 == 0 and -120 or 120
        origin = center + Vector3.new(math.cos(angle) * 200, height, math.sin(angle) * 200)
        radius = 140
    end
    search.Parts = phowg:chinese_nearby_parts(cached, origin, radius, search.Params, search.Query)
    if #search.Parts >= 128 then
        search.Saturated = true
    end
    search.Index, search.Candidates, search.CandidateIndex = 1, {}, 1
    return nil
end
registerheartbeat(
    'ChineseStrafeLifecycle',
    function()
        local owns = rageboton()
            or punishmentactive()
            or Toggles.target_strafe_enabled and Toggles.target_strafe_enabled.Value and Data.TargetStrafeActive
            or Toggles.kill_aura_enabled and Toggles.kill_aura_enabled.Value
        if
            Data.SafeMode
            or not owns
            or not Options.target_strafe_mode
            or Options.target_strafe_mode.Value ~= 'chinese'
            or tick() - (Data.ChineseRequestedAt or -math.huge) > 0.25
        then
            phowg:cancel_chinese_strafe()
        end
    end,
    0,
    function()
        return Data.ChineseHolding == true
    end,
    true
)
phowg:register_cleanup('chinese strafe', function(scope)
    if not scope or scope == LocalPlayer.Character or scope == Data.ManagedCharacter then
        phowg:cancel_chinese_strafe()
        return
    end
    for _, cached in pairs(Data.SmartStrafeCache or {}) do
        if scope == cached.character or scope == cached.tool then
            phowg:cancel_chinese_strafe()
            return
        end
    end
end)

function phowg:smart_strafe_ready(target, tool, cf)
    local character = LocalPlayer.Character
    local targetCharacter = target and target.Character
    local targetRoot = targetCharacter and targetCharacter:FindFirstChild('HumanoidRootPart')
    local aim = phowg:strafe_aim_part(target)
    local offset, direction = gettoolhandleoffset(character, tool)
    if typeof(cf) ~= 'CFrame' or not targetRoot or not aim or not offset or not direction then
        return false
    end
    local distance = (cf.Position - targetRoot.Position).Magnitude
    local cached = Data.SmartStrafeCache and Data.SmartStrafeCache[target]
    if cached and cached.mode == 'chinese' and (cached.VoidFallback or cached.Travel) then
        return false
    end
    local wallPose = cached
        and cached.character == targetCharacter
        and cached.localCharacter == character
        and cached.tool == tool
        and cached.mode == 'chinese'
        and cached.wallCF
        and (cached.wallCF.Position - cf.Position).Magnitude <= 0.25
        and cached.wall
        and cached.wall.Parent
        and ispointinsidepart(cached.wall, cf:PointToWorldSpace(offset))
    local minimum, maximum = 9.99, 52
    if cached and cached.mode == 'chinese' then
        if not wallPose or cached.Travel then
            return false
        end
        minimum, maximum = phowg:chinese_strafe_band(tool)
        if not minimum then
            return false
        end
    end
    if
        distance < minimum
        or distance > maximum
        or not (wallPose and cached.FreeRotation)
            and not phowg:smart_strafe_pose_aligned(cf, aim.Position, offset, direction)
    then
        return false
    end
    if wallPose then
        local hull = phowg:chinese_character_hull(character, tool)
        return hull ~= nil and phowg:chinese_shot_clear(cf:PointToWorldSpace(offset), aim.Position, cached, cf, hull)
    end
    local params = cached
            and cached.character == targetCharacter
            and cached.localCharacter == character
            and cached.params
        or phowg:strafe_shot_params(character, targetCharacter)
    local clear = phowg:strafe_shot_clear(cf:PointToWorldSpace(offset), aim.Position, params)
    return clear
end
function phowg:smart_strafe_arrival(target, tool, root)
    local character = LocalPlayer.Character
    local tag = Data.AppliedServerTag
    if
        not character
        or not root
        or root.Parent ~= character
        or Data.MoveToInFlight ~= root
        or not Data.CSyncTable[2]
        or Data.AppliedServerCharacter ~= character
        or (tag ~= 'Combat' and tag ~= 'TargetStrafe')
    then
        return false
    end
    local applied = Data.AppliedServerCF
    local cf = root.CFrame
    if typeof(applied) ~= 'CFrame' or (cf.Position - applied.Position).Magnitude > 0.25 then
        return false
    end
    local transit = Data.SmartStrafeCache and Data.SmartStrafeCache[target]
    if transit and transit.mode == 'chinese' and transit.VoidFallback then
        return false
    end
    if transit and transit.mode == 'chinese' and transit.Travel then
        if not phowg:chinese_travel_advance(transit, cf) then
            return false
        end
    end
    local offset, direction = gettoolhandleoffset(character, tool)
    local aim = phowg:strafe_aim_part(target)
    if not offset or not direction or not aim then
        return false
    end
    if
        not (transit and transit.mode == 'chinese' and transit.FreeRotation)
        and not phowg:smart_strafe_pose_aligned(cf, aim.Position, offset, direction)
    then
        local cached = Data.SmartStrafeCache and Data.SmartStrafeCache[target]
        local repaired, aligned
        if cached and cached.mode == 'chinese' and cached.wall then
            local hull = phowg:chinese_character_hull(character, tool)
            local rotation = getstraferotation('chinese', root)
            repaired, aligned =
                phowg:smart_strafe_c_frame(cf.Position, aim.Position, offset, direction, rotation, cached.roll)
            if not repaired or not aligned or not phowg:chinese_hull_depth(cached.wall, repaired, hull) then
                repaired, aligned = phowg:chinese_wall_pose(
                    cached.wall,
                    cf:PointToWorldSpace(offset),
                    aim.Position,
                    offset,
                    direction,
                    rotation,
                    cached.wallNormal,
                    hull
                )
            end
            if repaired and not phowg:chinese_hull_depth(cached.wall, repaired, hull) then
                return false
            end
        else
            repaired, aligned = phowg:smart_strafe_c_frame(
                cf.Position,
                aim.Position,
                offset,
                direction,
                getstraferotation('smart', root),
                cached and cached.roll
            )
        end
        if not aligned or not repaired then
            return false
        end
        local routing = false
        if cached and cached.mode == 'chinese' and (repaired.Position - cf.Position).Magnitude > 0.05 then
            local targetRoot = target.Character and target.Character:FindFirstChild('HumanoidRootPart')
            if not targetRoot then
                return false
            end
            cached.wallCF, cached.cf = repaired, repaired
            repaired = phowg:chinese_travel_c_frame(repaired, cached, targetRoot.Position)
            if not repaired then
                return false
            end
            routing = true
        end
        root.CFrame = repaired
        Data.AppliedServerCF, Data.LastServerCF, Data.DisplayCF, Data.MoveToTargetCF =
            repaired, repaired, repaired, repaired
        cf = repaired
        if syncvisualizer and Toggles.local_desynced_position and Toggles.local_desynced_position.Value then
            pcall(syncvisualizer)
        end
        if routing then
            return false
        end
    end
    return phowg:smart_strafe_ready(target, tool, cf)
end
function phowg:teleport_camp_c_frame(target, tool)
    local character = target and target.Character
    local root = character and getroot(character)
    if not root then
        return nil
    end
    phowg:resolved_root_position(character, root)
    local motion = Data.ResolvedMotion and Data.ResolvedMotion[character]
    local anchor = motion and motion.ResolverAnchor
    Data.TeleportCycles = Data.TeleportCycles or setmetatable({}, { __mode = 'k' })
    if not phowg:resolver_anchor_fresh(motion) then
        Data.TeleportCycles[target] = nil
        return nil
    end
    local now = tick()
    local state = Data.TeleportCycles[target]
    if not state or state.Character ~= character or state.LocalCharacter ~= LocalPlayer.Character then
        state = { Character = character, LocalCharacter = LocalPlayer.Character }
        Data.TeleportCycles[target] = state
    end
    if state.Anchor ~= anchor or not state.AnchorPosition or (state.AnchorPosition - anchor.Position).Magnitude > 1 then
        state.NextPose = nil
    end
    state.Anchor, state.AnchorPosition, state.LastSwap = anchor, anchor.Position, motion.LastJumpAt
    local mode = Options.target_strafe_mode and Options.target_strafe_mode.Value or 'orbit'
    if not state.CFrame or not state.NextPose or now >= state.NextPose then
        local anchorPosition = state.AnchorPosition
        local destination
        if mode == 'random' or mode == 'random rotation' then
            destination = anchorPosition + Vector3.new(math.random(-10, 10), math.random(-10, 10), math.random(-10, 10))
        else
            local angle = now * 4
            destination = phowg:strafe_ground_position(
                anchorPosition + Vector3.new(math.cos(angle) * 8, 3, math.sin(angle) * 8),
                character
            )
        end
        local localRoot = LocalPlayer.Character and getroot(LocalPlayer.Character)
        state.CFrame = CFrame.new(destination) * getstraferotation(mode, localRoot)
        state.NextPose = now + 0.1
    end
    return state.CFrame
end
phowg:register_cleanup('teleport camping', function(scope, reason)
    if reason == 'unload' or scope == LocalPlayer.Character then
        Data.TeleportCycles = nil
    end
    for target, state in pairs(Data.TeleportCycles or {}) do
        if scope == target or scope == state.Character then
            Data.TeleportCycles[target] = nil
        end
    end
end)

function getgunstrafecframe(target, tool, mode, maxRadius)
    local character = LocalPlayer.Character
    local root = character and character:FindFirstChild('HumanoidRootPart')
    local targetCharacter = target and target.Character
    local targetRoot = targetCharacter and targetCharacter:FindFirstChild('HumanoidRootPart')
    if not root or not targetRoot then
        return nil
    end
    local smart = mode == 'smart' or mode == 'chinese'
    local center = predpos(targetRoot.Position, targetCharacter, 2.5, nil, true)
    if mode == 'random' or mode == 'random rotation' then
        local position = center + Vector3.new(math.random(-10, 10), math.random(-10, 10), math.random(-10, 10))
        return CFrame.new(position) * getstraferotation(mode, root)
    end
    if mode == 'spaz' then
        local position = phowg:strafe_ground_position(
            center + Vector3.new(math.random(-15, 15), 10, math.random(-15, 15)),
            targetCharacter
        )
        return CFrame.new(position) * getstraferotation(mode, root)
    end
    if not smart then
        return phowg:orbit_strafe_c_frame(center, targetCharacter, true)
    end
    local aimPart = phowg:strafe_aim_part(target) or targetRoot
    local aimPosition = aimPart.Position
    local forward = phowg:resolve_target_motion(targetCharacter, targetRoot)
    forward = Vector3.new(forward.X, 0, forward.Z)
    if forward.Magnitude < 0.1 then
        local humanoid = targetCharacter:FindFirstChildOfClass('Humanoid')
        forward = humanoid and humanoid.MoveDirection or Vector3.zero
    end
    if forward.Magnitude < 0.1 then
        forward = targetRoot.CFrame.LookVector
    end
    forward = Vector3.new(forward.X, 0, forward.Z)
    if forward.Magnitude < 0.1 then
        forward = Vector3.new(0, 0, -1)
    end
    forward = forward.Unit
    local muzzleOffset, muzzleDirection = gettoolhandleoffset(character, tool)
    muzzleOffset = muzzleOffset or Vector3.new(0, 1, -1)
    muzzleDirection = muzzleDirection or Vector3.new(0, 0, -1)
    local maximumRadius = math.clamp(tonumber(maxRadius) or 50, 10, 50)
    if maximumRadius ~= maximumRadius then
        maximumRadius = 50
    end
    local now = tick()
    local phase = math.floor(now / 0.05)
    local rotation = getstraferotation(mode, root)
    Data.SmartStrafeCache = Data.SmartStrafeCache or setmetatable({}, { __mode = 'k' })
    local cache = Data.SmartStrafeCache
    local previous = cache[target]
    local toolCaches = mode == 'chinese' and previous and previous.ToolCaches or nil
    local toolKey = tool or false
    local cached = toolCaches and toolCaches[toolKey] or previous
    if
        not cached
        or cached.character ~= targetCharacter
        or cached.localCharacter ~= character
        or cached.tool ~= tool
        or cached.maxRadius ~= maximumRadius
        or cached.mode ~= mode
    then
        local groundParams = phowg:strafe_shot_params(character, targetCharacter)
        local excluded = groundParams.FilterDescendantsInstances
        local playersFolder = Workspace:FindFirstChild('Players')
        if playersFolder then
            excluded[#excluded + 1] = playersFolder
            groundParams.FilterDescendantsInstances = excluded
        end
        groundParams.RespectCanCollide = true
        cached = {
            target = target,
            character = targetCharacter,
            localCharacter = character,
            tool = tool,
            maxRadius = maximumRadius,
            mode = mode,
            params = phowg:strafe_shot_params(character, targetCharacter),
            groundParams = groundParams,
            floors = {},
        }
        if mode == 'chinese' then
            toolCaches = toolCaches or setmetatable({}, { __mode = 'k' })
            toolCaches[toolKey], cached.ToolCaches = cached, toolCaches
        end
    end
    cache[target] = cached
    if mode == 'chinese' then
        Data.ChineseHolding, Data.ChineseRequestedAt = true, now
        local cf =
