    local humanoid = character:FindFirstChildOfClass('Humanoid')
    local leg = character:FindFirstChild('Left Leg')
    local clearance = math.max(
        2.25,
        root.Size.Y * 0.5 + math.max(0, humanoid and humanoid.HipHeight or 2) + (leg and leg.Size.Y or 0)
    ) + 0.25
    local wallChecks = 0
    local refineWalls = cached.phase ~= phase
        or cached.clear
        or cached.center and (center - cached.center).Magnitude >= 0.05
        or cached.aim and (aimPosition - cached.aim).Magnitude >= 0.05
        or cached.offset and (muzzleOffset - cached.offset).Magnitude >= 0.01
        or cached.direction and (muzzleDirection - cached.direction).Magnitude >= 0.01
    local function evaluate(cf, aligned)
        local origin = cf:PointToWorldSpace(muzzleOffset)
        local distance = (cf.Position - center).Magnitude
