    end
    local function candidate(angle, radius, height, requestedRoll)
        local position = center + Vector3.new(math.cos(angle) * radius, height or 0, math.sin(angle) * radius)
        local heights = cached.floors[height or 0]
        if not heights then
            heights = {}
            cached.floors[height or 0] = heights
        end
        local radii = heights[radius]
        if not radii then
            radii = {}
            heights[radius] = radii
        end
        local floor = radii[angle]
        if floor == nil then
            local hit =
                Workspace:Raycast(position + Vector3.new(0, 1.5, 0), Vector3.new(0, -24, 0), cached.groundParams)
            floor = hit and hit.Position.Y <= position.Y - 0.25 and hit.Position.Y or false
            radii[angle] = floor
        end
        if floor ~= false then
            position = Vector3.new(position.X, math.max(position.Y, floor + clearance), position.Z)
        end
        local roll = requestedRoll or 0
        local cf, aligned = phowg:smart_strafe_c_frame(position, aimPosition, muzzleOffset, muzzleDirection, rotation, roll)
        local clear, progress, hit, origin = evaluate(cf, aligned)
        if clear then
            return cf, true, progress, roll
        end
        local bestCF, bestProgress, bestRoll = cf, progress, roll
        if refineWalls and hit and (hit.Position - origin).Magnitude <= 3 and wallChecks < 4 then
            wallChecks = wallChecks + 1
            for index, trialRoll in ipairs({ roll, roll + math.pi * 0.5, roll - math.pi * 0.5, roll + math.pi }) do
                if index > 1 then
                    cf, aligned = phowg:smart_strafe_c_frame(
                        position,
                        aimPosition,
                        muzzleOffset,
                        muzzleDirection,
