                    end
                end
                if
                    hit
                    and hit.Instance
                    and hit.Instance:IsA('BasePart')
                    and typeof(hit.Normal) == 'Vector3'
                    and (hit.Position - origin).Magnitude <= 3
                then
                    local insetOrigin = hit.Position - hit.Normal
                    local insetCF, insetAligned = phowg:smart_strafe_muzzle_c_frame(
                        insetOrigin,
                        aimPosition,
                        muzzleOffset,
                        muzzleDirection,
                        rotation,
                        trialRoll
                    )
                    local offset = insetCF.Position - center
                    if
                        (insetCF.Position - position).Magnitude <= 3
                        and Vector3.new(offset.X, 0, offset.Z).Magnitude <= maximumRadius + 0.05
                        and offset.Magnitude <= 52
                    then
                        local insetClear, insetProgress = evaluate(insetCF, insetAligned)
                        if insetClear then
                            return insetCF, true, insetProgress, trialRoll
                        end
                        if insetProgress > bestProgress then
