        if
            cached.phase == phase
            and cached.center
            and (center - cached.center).Magnitude < 0.05
            and cached.aim
            and (aimPosition - cached.aim).Magnitude < 0.05
            and cached.offset
            and (muzzleOffset - cached.offset).Magnitude < 0.01
            and cached.direction
            and (muzzleDirection - cached.direction).Magnitude < 0.01
