        then
            cached.clear, cached.roll, cached.cf = previousClear, previousRoll, previousCF
            Data.SmartStrafe = cached
            return previousCF
        end
    end
    local function commit(cf, angle, radius, height, clear, roll)
        cached.angle, cached.radius, cached.height, cached.clear = angle, radius, height, clear
        cached.phase, cached.at, cached.center, cached.aim, cached.offset, cached.rotation =
            phase, now, center, aimPosition, muzzleOffset, rotation
        cached.direction, cached.roll, cached.cf = muzzleDirection, roll, cf
        Data.SmartStrafe = cached
        return cf
    end
    local baseAngle = math.atan2(forward.Z, forward.X)
    local angleIndex = phase * 7 % 24
    local minimumMove = math.min(4, (cached.radius or maximumRadius) * 0.5)
    local fallback, fallbackAngle, fallbackRadius, fallbackHeight, fallbackScore, fallbackRoll
    local function consider(angle, radius, height, lowerRadius)
        local cf, clear, progress, roll = candidate(angle, radius, height)
        if previousCF and radius >= cached.radius and (cf.Position - previousCF.Position).Magnitude < minimumMove then
            return nil
        end
        if clear then
            if lowerRadius and radius - lowerRadius > 0.25 then
                local low, high = lowerRadius, radius
                for _ = 1, 6 do
                    if high - low <= 0.25 then
                        break
                    end
                    local mid = (low + high) * 0.5
                    local refined, refinedClear, _refinedProgress, refinedRoll = candidate(angle, mid, height, roll)
                    if refinedClear then
                        high = mid
                        if (refined.Position - center).Magnitude <= (cf.Position - center).Magnitude then
                            cf, radius, roll = refined, mid, refinedRoll
                        end
                    else
                        low = mid
                    end
                end
            end
            return commit(cf, angle, radius, height, true, roll)
        end
        local score = progress * 8 - radius * 0.1 - math.abs(height or 0) * 0.03
        if not fallbackScore or score > fallbackScore then
            fallback, fallbackAngle, fallbackRadius, fallbackHeight, fallbackScore, fallbackRoll =
                cf, angle, radius, height, score, roll
        end
        return nil
    end
    local lastRadius
    for _, requestedRadius in ipairs({ 10, 12, 15, 20, 30, 40, 50 }) do
        local radius = math.min(requestedRadius, maximumRadius)
        if radius ~= lastRadius then
            for index = 0, 23 do
                local angle = baseAngle + (angleIndex + index * 11) % 24 * math.pi / 12
                local cf = consider(angle, radius, 0, lastRadius)
                if cf then
                    return cf
                end
            end
