    if previousCF and previousClear then
        return commit(previousCF, cached.angle, cached.radius, cached.height, true, previousRoll)
    end
    if fallback then
        return commit(fallback, fallbackAngle, fallbackRadius, fallbackHeight, false, fallbackRoll)
    end
    local angle = baseAngle + angleIndex * math.pi / 12
