function phowg:auto_kill_gun_mode()
    local names = phowg:ragebot_gun_names()
    for _, name in ipairs(names) do
        local tool = getweapontool(name)
        local ammo = tool and tool:FindFirstChild('Ammo')
        if ammo and type(ammo.Value) == 'number' and ammo.Value > 0 then
            return name
        end
    end
    for _, name in ipairs(names) do
        if getweapontool(name) then
            return name
        end
    end
    return names[1]
end
function isgunshootable(Target, GunMode)
    if Data['SupportCompletedTargets'] and Data['SupportCompletedTargets'][Target] then
        return false
    end
    if not intelligence:get_character_cache(Target) then
        return false
    end
    if isknocked(Target) or isdead(Target) then
        return false
    end
    local ch = Target.Character
    if not ch then
        return false
    end
    if ch:FindFirstChild('GRABBING_CONSTRAINT') then
        return false
    end
    if ch:FindFirstChildOfClass('ForceField') then
        return false
    end
    if Data['ArrestWatch'] and Data['ArrestWatch'][Target] then
        return false
    end
    if isvalidstomptarget(Target) then
        return false
    end
    if GunMode == 'flamethrower' and Data['FlameUntargetable'] and Data['FlameUntargetable'][Target] then
        return false
    end
    local character = LocalPlayer.Character
    if
        not character
        or not character:FindFirstChild('HumanoidRootPart')
        or not ch:FindFirstChild('HumanoidRootPart')
    then
        return false
    end
    return true
end
function pickguntarget(Targets, GunMode)
    local now = tick()
    local myChar = LocalPlayer and LocalPlayer.Character
    local myRoot = myChar and getroot(myChar)
    if not myRoot then
        return nil
    end
    local myPos = (Local_Data['ClientPos'] and Local_Data['ClientPos'].Position) or myRoot.Position
    local focus = Data.GunFocusTarget
    local bestPun, bestRest, nextPun, nextRest
    local bestPunDistance, bestRestDistance, nextPunDistance, nextRestDistance =
        math.huge, math.huge, math.huge, math.huge
    local focusDistance, focusValid
    local punishments = Data.PunishmentTargets
    for _, player in ipairs(Targets) do
        if isgunshootable(player, GunMode) then
            local root = player.Character and getroot(player.Character)
            if root then
                local delta = myPos - root.Position
                local distance = delta:Dot(delta)
                if punishments and punishments[player] then
                    if distance < bestPunDistance then
                        bestPun, bestPunDistance = player, distance
                    end
                    if player ~= focus and distance < nextPunDistance then
                        nextPun, nextPunDistance = player, distance
                    end
                else
                    if distance < bestRestDistance then
                        bestRest, bestRestDistance = player, distance
                    end
                    if player ~= focus and distance < nextRestDistance then
                        nextRest, nextRestDistance = player, distance
                    end
                end
                if player == focus and focus.Parent and focus ~= LocalPlayer then
                    focusValid, focusDistance = true, distance
                end
            end
        end
    end
    local best = bestPun or bestRest
    if not best then
        Data.GunFocusTarget, Data.GunFocusAt, Data.GunAimTarget, Data.GunAimAt = nil, nil, nil, nil
        return nil
    end
    if not focusValid then
        Data.GunFocusTarget, Data.GunFocusAt = best, now
        return best
    end
    local focusIsPun = punishments and punishments[focus]
    if
        (bestPun and not focusIsPun)
        or (
            not focusIsPun
            and best ~= focus
            and math.sqrt(focusDistance) - math.sqrt(bestPun and bestPunDistance or bestRestDistance) > 12
        )
    then
        Data.GunFocusTarget, Data.GunFocusAt = best, now
        return best
    end
    if now - (Data.GunFocusAt or 0) >= 1.5 then
        local nextTarget = not focusIsPun and (nextPun or nextRest) or focus
        Data.GunFocusTarget, Data.GunFocusAt = nextTarget or focus, now
        return nextTarget or focus
    end
    return focus
end
function haslockedsources()
    for _ in pairs(Data['DropdownTargets'] or {}) do
        return true
    end
    for _ in pairs(Data['LockedTargets'] or {}) do
        return true
    end
    for _ in pairs(Data['PunishmentTargets'] or {}) do
        return true
    end
    return false
end
do
    local zombies = setmetatable({}, { __mode = 'kv' })
    local nextId = 0
    local cachedFolder, cachedAt, cachedModels = nil, -math.huge, {}
    function phowg:is_zombie_model(model)
        local folder = Workspace:FindFirstChild('Players')
        if
            not folder
            or not model
            or not model:IsA('Model')
            or not model:IsDescendantOf(folder)
            or Players:GetPlayerFromCharacter(model)
        then
            return false
        end
        local node = model
        while node and node ~= folder do
            if node.Name == '[ZOMBIE]' then
                return true
            end
            node = node.Parent
        end
        return false
    end
    function phowg:is_zombie_target(target)
        return type(target) == 'table' and target.ZombieModel ~= nil and phowg:is_zombie_model(target.ZombieModel)
    end
    function phowg:zombie_aim_target(model)
        if not phowg:is_zombie_model(model) or not model:FindFirstChildOfClass('Humanoid') then
            return nil
        end
        local target = zombies[model]
        if not target then
            nextId -= 1
            target = setmetatable({ ZombieModel = model, UserId = nextId, Name = '[ZOMBIE]', DisplayName = 'Zombie' }, {
                __index = function(_, key)
                    if key == 'Character' then
                        return model
                    end
                    if key == 'Parent' then
                        return model.Parent
                    end
                    return nil
                end,
            })
            function target:FindFirstChild()
                return nil
            end
            function target:GetAttribute(name)
                return model:GetAttribute(name)
            end
            function target:IsA()
                return false
            end
            zombies[model] = target
        end
        return target
    end
    function phowg:aim_candidates(includeZombies, zombiesOnly)
        local candidates = zombiesOnly and {} or Players:GetPlayers()
        local folder = includeZombies and Workspace:FindFirstChild('Players')
        if not folder then
            return candidates
        end
        local now = tick()
        if cachedFolder ~= folder or now - cachedAt >= 0.2 then
            cachedFolder, cachedAt, cachedModels = folder, now, {}
            local queue = {}
            for _, child in ipairs(folder:GetChildren()) do
                if child.Name == '[ZOMBIE]' and (child:IsA('Model') or child:IsA('Folder')) then
                    queue[#queue + 1] = child
                end
            end
            local index = 1
            while index <= #queue do
                local model = queue[index]
                index += 1
                if model:IsA('Model') and model:FindFirstChildOfClass('Humanoid') then
                    if phowg:is_zombie_model(model) then
                        cachedModels[#cachedModels + 1] = model
                    end
                else
                    for _, child in ipairs(model:GetChildren()) do
                        if child:IsA('Model') or child:IsA('Folder') then
                            queue[#queue + 1] = child
                        end
                    end
                end
            end
        end
        for _, model in ipairs(cachedModels) do
            local target = phowg:zombie_aim_target(model)
            if target and not isdead(target) then
                candidates[#candidates + 1] = target
            end
        end
        return candidates
    end
    phowg:register_cleanup('zombie targets', function(scope, reason)
        if reason == 'unload' or not scope or scope == cachedFolder then
            cachedFolder, cachedAt, cachedModels = nil, -math.huge, {}
            table.clear(zombies)
        elseif typeof(scope) == 'Instance' and scope:IsA('Model') then
            zombies[scope] = nil
            cachedAt = -math.huge
        end
    end)
end
function phowg:sticky_checks_pass(plr)
    if not plr then
        return false
    end
    if Library.StickyWhitelist and Library.StickyWhitelist[plr] then
        return false
    end
    if not (Toggles.sticky_aim_checks_enabled and Toggles.sticky_aim_checks_enabled.Value) then
        return true
    end
    local checks = Options.sticky_aim_check_types and Options.sticky_aim_check_types.Value
    if type(checks) ~= 'table' then
        return true
    end
    if checks['not zombie'] and phowg:is_zombie_target(plr) then
        return false
    end
    if
        checks.whitelisted
        and (
            (Data.FullWhitelist and Data.FullWhitelist[plr])
            or (Data.RageWhitelist and Data.RageWhitelist[plr])
            or (Data.IsraelWhitelist and Data.IsraelWhitelist[plr])
            or (Library.FullWhitelist and Library.FullWhitelist[plr])
            or (Library.SilentWhitelist and Library.SilentWhitelist[plr])
            or (Library.StickyWhitelist and Library.StickyWhitelist[plr])
            or (Library.IsraelWhitelist and Library.IsraelWhitelist[plr])
        )
    then
        return false
    end
    if checks.crew or Toggles.sticky_ignore_crew and Toggles.sticky_ignore_crew.Value then
        local crew = getplayercrewid(plr)
        if
            crew
            and (
                (Data.WhitelistedCrews and Data.WhitelistedCrews[tostring(crew)])
                or crew == getplayercrewid(LocalPlayer)
            )
        then
            return false
        end
    end
    local character = plr.Character
    if checks.grabbed and character and character:FindFirstChild('GRABBING_CONSTRAINT', true) then
        return false
    end
    return true
end
function phowg:sticky_character(plr)
    local character = plr and plr.Character
    if not character or not character.Parent or not character:IsDescendantOf(Workspace) then
        return nil
    end
    if
        not character:FindFirstChildOfClass('Humanoid')
        or not character:FindFirstChild('HumanoidRootPart')
        or not character:FindFirstChild('Head')
    then
        return nil
    end
    if not character:FindFirstChild('UpperTorso') and not character:FindFirstChild('Torso') then
        return nil
    end
    return character
end
function phowg:is_sticky_aim_source(plr, source)
    if source == 'StickyAim' then
        return true
    end
    if source ~= 'SilentAim' or not (Toggles.sticky_aim_enabled and Toggles.sticky_aim_enabled.Value) then
        return false
    end
    return plr ~= nil
        and (Data.StickyTarget == plr or (Data.SilentAimStickyTargets and Data.SilentAimStickyTargets[plr] == true))
end
function phowg:sticky_shoot_allowed(plr)
    local character = plr and plr.Character
    if not character or not character.Parent then
        return false
    end
    if not (Toggles.sticky_aim_checks_enabled and Toggles.sticky_aim_checks_enabled.Value) then
        return true
    end
    local selected = Options.sticky_aim_shoot_if and Options.sticky_aim_shoot_if.Value
    if type(selected) ~= 'table' then
        selected = { ['not knocked'] = true, ['not stomped'] = true, ['not protected'] = true }
    end
    local checks = Options.sticky_aim_check_types and Options.sticky_aim_check_types.Value
    if phowg:is_zombie_target(plr) and (selected['not zombie'] or type(checks) == 'table' and checks['not zombie']) then
        return false
    end
    local allowKnocked = Toggles.sticky_allow_knocked and Toggles.sticky_allow_knocked.Value
    if not allowKnocked and isknocked(plr) then
        return false
    end
    if selected['not stomped'] and (isstomped(plr) or isdead(plr)) then
        return false
    end
    if
        (selected['not protected'] or Toggles.sticky_ignore_protected and Toggles.sticky_ignore_protected.Value)
        and character:FindFirstChildOfClass('ForceField')
    then
        return false
    end
    return true
end
function phowg:current_sticky_shot(target, source)
    if not (Toggles.sticky_aim_enabled and Toggles.sticky_aim_enabled.Value) then
        return nil
    end
    if not source and phowg.get_gun_shot_target then
        local resolved, _, _, owner = phowg:get_gun_shot_target()
        if target and resolved ~= target then
            return nil
        end
        target, source = resolved, owner
    end
    if target and phowg:is_sticky_aim_source(target, source) then
        return target
    end
    return nil
end
function phowg:sticky_shot_blocked(target, source)
    local sticky = phowg:current_sticky_shot(target, source)
    return sticky ~= nil and (not phowg:sticky_checks_pass(sticky) or not phowg:sticky_shoot_allowed(sticky))
end
function phowg:randomize_sticky_bullet(point, target, source)
    if not (Toggles.randomize_bullets and Toggles.randomize_bullets.Value) or not phowg:perfect_hit_vector(point) then
        return point
    end
    local sticky = phowg:current_sticky_shot(target, source)
    local character = sticky and sticky.Character
    if not character or not character.Parent then
        return point
    end
    local part = character:FindFirstChild('Head') or character:FindFirstChild('HumanoidRootPart')
    local solution = part and phowg.perfect_hit_solution and phowg:perfect_hit_solution(sticky, nil, part)
    local center = solution and phowg:perfect_hit_vector(solution.Point) and solution.Point or point
    return center
        + Vector3.new((math.random() * 2 - 1) * 10, (math.random() * 2 - 1) * 10, (math.random() * 2 - 1) * 10)
end
function is_sticky_valid(plr)
