function clear_sticky_target(_reason)
    local old = Data['StickyTarget']
    if Data.MeleeReplicationRoot and Data.MeleeReplicationRoot.Target == old then
        phowg:clear_melee_replication_root()
    end
    Data['StickyTarget'] = nil
    Data['StickyTargetUid'] = nil
    Data['StickyLockAt'] = nil
    Data['StickyChar'] = nil
    local toWipe = {}
    if type(old) == 'table' and old.ZombieModel then
        if Data.SilentAimTarget == old then
            Data.SilentAimTarget, Data.SilentAimPos, Data.SilentAimHitPart = nil, nil, nil
        end
        if Data.SilentAimStickyTarget == old then
            Data.SilentAimStickyTarget = nil
