    if Data['SilentAimStickyTargets'] then
        for plr, _ in pairs(Data['SilentAimStickyTargets']) do
            toWipe[plr] = true
        end
        Data['SilentAimStickyTargets'] = {}
    end
    if Data['SingleLockedTarget'] and typeof(Data['SingleLockedTarget']) == 'Instance' then
        toWipe[Data['SingleLockedTarget']] = true
    end
    for plr, _ in pairs(toWipe) do
        if plr and typeof(plr) == 'Instance' then
            if Data['LockedTargets'] then
                Data['LockedTargets'][plr] = nil
            end
            if Data['DropdownTargets'] then
                Data['DropdownTargets'][plr] = nil
