            end
            if Data['SingleLockedTarget'] == plr then
                Data['SingleLockedTarget'] = nil
            end
            if Data['CurrentMainTarget'] == plr then
                Data['CurrentMainTarget'] = nil
            end
            if Data['CurrentActionTarget'] == plr then
                Data['CurrentActionTarget'] = nil
            end
            if Data['SilentAimStickyTarget'] == plr then
                Data['SilentAimStickyTarget'] = nil
            end
            if Data['StickyIncludeTarget'] == plr then
                Data['StickyIncludeTarget'] = nil
            end
            if Data['StickyMainTarget'] == plr then
                Data['StickyMainTarget'] = nil
            end
            if Data['RifleTarget'] == plr then
                Data['RifleTarget'] = nil
            end
            if Data['RifleVoidTarget'] == plr then
                Data['RifleVoid'] = nil
                Data['RifleVoidFF'] = nil
                Data['RifleVoidWait'] = nil
                Data['RifleVoidTarget'] = nil
            end
            if Data['GunAimTarget'] == plr then
                Data['GunAimTarget'] = nil
            end
            if Data['GunFocusTarget'] == plr then
                Data['GunFocusTarget'] = nil
            end
            if Data['GunAimTarget'] == nil then
                Data['GunAimAt'] = nil
            end
            if Data['GunFocusTarget'] == nil then
                Data['GunFocusAt'] = nil
            end
            if Data['FrozenRoots'] and Data['FrozenRoots'][plr] then
                local _r = Data['FrozenRoots'][plr]
                if _r and _r.Parent then
                    pcall(function()
                        _r.Anchored = false
                    end)
                end
                Data['FrozenRoots'][plr] = nil
            end
            if Data['FrozenAt'] then
                Data['FrozenAt'][plr] = nil
            end
            if Data['StompWatch'] then
                Data['StompWatch'][plr] = nil
            end
            if Data['ArrestWatch'] then
                Data['ArrestWatch'][plr] = nil
            end
        end
    end
    Data['StickyRepTarget'] = nil
    Data['SilentAimStickyLocked'] = nil
    Data['TargetListCache'] = nil
end
function set_sticky_target(plr)
    if not is_sticky_valid(plr) then
        return false
    end
    local cur = Data['StickyTarget']
    if cur == plr then
        return true
    end
    if not phowg:sticky_checks_pass(plr) or not phowg:sticky_character(plr) then
        return false
    end
    if cur then
        clear_sticky_target('switch')
    end
    if phowg:is_zombie_target(plr) then
        Data.StickyTarget, Data.StickyChar, Data.StickyLockAt = plr, plr.Character, tick()
        Data.SilentAimStickyTargets, Data.SilentAimStickyTarget = { [plr] = true }, plr
        Data.StickyRepTarget, Data.TargetListCache = nil, nil
        return true
    end
    if Data['SilentAimStickyTargets'] == nil then
        Data['SilentAimStickyTargets'] = {}
    end
    Data['SilentAimStickyTargets'] = {}
    Data['SilentAimStickyTargets'][plr] = true
    if Data['LockedTargets'] == nil then
        Data['LockedTargets'] = {}
    end
    Data['LockedTargets'][plr] = true
    if Data['TargetWatchlist'] == nil then
        Data['TargetWatchlist'] = {}
    end
    Data['TargetWatchlist'][plr.UserId] = true
    Data['TargetWatchlist'][plr.Name] = true
    if Data['StickyAimWatchlist'] == nil then
        Data['StickyAimWatchlist'] = {}
    end
    Data['StickyAimWatchlist'][plr.UserId] = true
    Data['StickyAimWatchlist'][plr.Name] = true
    Data['SingleLockedTarget'] = plr
    Data['SilentAimStickyTarget'] = plr
    Data['CurrentMainTarget'] = plr
    Data['StickyTarget'] = plr
    Data['StickyTargetUid'] = plr.UserId
    Data['StickyLockAt'] = tick()
    Data['StickyChar'] = plr.Character
    Data['StickyRepTarget'] = nil
    Data['TargetListCache'] = nil
    return true
end

function phowg:refresh_sticky_checks()
    Data.TargetListCache, Data.ActiveTarget, Data.ActiveTargetAt = nil, nil, nil
    local cur = Data.StickyTarget
    if not cur then
        return
    end
    if not is_sticky_valid(cur) or not phowg:sticky_checks_pass(cur) then
        clear_sticky_target('checks')
        return
    end
    if phowg:is_zombie_target(cur) then
        if not phowg:sticky_checks_pass(cur) then
            clear_sticky_target('checks')
        end
        return
    end
    Data.SilentAimStickyTargets = Data.SilentAimStickyTargets or {}
    Data.SilentAimStickyTargets[cur] = true
    Data.SilentAimStickyTarget = cur
    Data.LockedTargets = Data.LockedTargets or {}
    Data.LockedTargets[cur] = true
    Data.SingleLockedTarget = cur
    Data.TargetWatchlist = Data.TargetWatchlist or {}
    Data.TargetWatchlist[cur.UserId], Data.TargetWatchlist[cur.Name] = true, true
end
function getselectedtarget()
    do
        local _st = get_sticky_target()
        if
            _st
            and _st.Parent
            and _st ~= LocalPlayer
            and intelligence:get_character_cache(_st)
            and not isstomped(_st)
        then
            Data['CurrentMainTarget'] = _st
            return _st
        end
    end
    if haslockedsources() then
        if
            Data['CurrentMainTarget']
            and Data['CurrentMainTarget'].Parent
            and Data['LockedTargets'][Data['CurrentMainTarget']]
            and not isstomped(Data['CurrentMainTarget'])
        then
            return Data['CurrentMainTarget']
        end
        local prev = Data['PrevMainTarget']
        if
            prev
            and prev.Parent
            and prev ~= LocalPlayer
            and Data['LockedTargets'][prev]
            and intelligence:get_character_cache(prev)
            and not isstomped(prev)
        then
            Data['CurrentMainTarget'] = prev
            return prev
        end
        local cur = Data['CurrentMainTarget']
        if cur and cur.Parent and Data['LockedTargets'][cur] then
            Data['PrevMainTarget'] = cur
        end
        local BestPlr = nil
        local BestDist = math.huge
        for Plr, _ in pairs(Data['LockedTargets']) do
            if Plr and Plr.Parent and Plr ~= LocalPlayer and intelligence:get_character_cache(Plr) then
                local Dist = getdistancetoplayer(Plr)
                if Dist < BestDist then
                    BestDist = Dist
                    BestPlr = Plr
                end
            end
        end
        Data['CurrentMainTarget'] = BestPlr
        return BestPlr
    end
    if Toggles.target_all and Toggles.target_all.Value then
        if
            Data['CurrentMainTarget']
            and Data['CurrentMainTarget'].Parent
            and Data['CurrentMainTarget'] ~= LocalPlayer
            and not isstomped(Data['CurrentMainTarget'])
        then
            return Data['CurrentMainTarget']
        end
        local prev = Data['PrevMainTarget']
        if
            prev
            and prev.Parent
            and prev ~= LocalPlayer
            and intelligence:get_character_cache(prev)
            and not isstomped(prev)
        then
            Data['CurrentMainTarget'] = prev
            return prev
        end
        local cur = Data['CurrentMainTarget']
        if cur and cur.Parent and cur ~= LocalPlayer then
            Data['PrevMainTarget'] = cur
        end
        local BestPlr = nil
        local BestDist = math.huge
        for _, Plr in ipairs(Players:GetPlayers()) do
            if Plr ~= LocalPlayer and intelligence:get_character_cache(Plr) then
                local Dist = getdistancetoplayer(Plr)
                if Dist < BestDist then
                    BestDist = Dist
                    BestPlr = Plr
                end
            end
        end
        Data['CurrentMainTarget'] = BestPlr
        return BestPlr
    end
    if
        Data['SingleLockedTarget']
        and Data['SingleLockedTarget'].Parent
        and not isstomped(Data['SingleLockedTarget'])
    then
        Data['CurrentMainTarget'] = Data['SingleLockedTarget']
        return Data['SingleLockedTarget']
    end
    local Selected = Options.target_select and Options.target_select.Value
    if typeof(Selected) == 'Instance' and Selected:IsA('Player') and not isstomped(Selected) then
        Data['CurrentMainTarget'] = Selected
        return Selected
    elseif typeof(Selected) == 'string' and #Selected > 0 then
        local Plr = Players:FindFirstChild(Selected)
        if Plr and not isstomped(Plr) then
            Data['CurrentMainTarget'] = Plr
            return Plr
        end
    end
    Data['CurrentMainTarget'] = nil
    return nil
end
function isplayerloadedin(plr)
    if not plr then
        return false
    end
    if Data['PlayerJoinAt'] == nil then
        Data['PlayerJoinAt'] = {}
    end
    local at = Data['PlayerJoinAt'][plr]
    if not at then
        return true
    end
    return tick() - at >= 10
end
do
    local function disconnect(connections)
        for _, connection in ipairs(connections) do
            connection:Disconnect()
        end
        table.clear(connections)
    end
    function phowg:bounty_amount(value)
        if type(value) == 'string' then
            local number, suffix = value:gsub('<[^>]->', ''):match('(%d[%d,%s%.]*)%s*([%a]*)')
            value = number and tonumber((number:gsub('[,%s]', '')))
            local scale = ({ k = 1000, m = 1000000, b = 1000000000 })[string.lower(suffix or '')] or 1
            value = value and value * scale
        end
        return type(value) == 'number' and value == value and value > 0 and value < math.huge and value or 0
    end
    function phowg:auto_bounty_target_allowed(player)
        local state = Data.AutoBounty
        if not phowg:auto_bounty_enabled() or not player or player == LocalPlayer or player.Parent ~= Players then
            return false
        end
        local name = string.lower(player.Name)
        local amount = state.Amounts[name] or 0
        local minimum = Toggles.auto_bounty_high_only and Toggles.auto_bounty_high_only.Value and 1000000 or 1
        return amount >= minimum
            and state.Completed[name] ~= state.Revisions[name]
            and not iswhitelistedplayer(player)
            and not iscrewwhitelisted(player)
            and not (Data.RageWhitelist and Data.RageWhitelist[player])
    end
    function phowg:invalidate_auto_bounty(force)
        Data.TargetListCache, Data._ActionableAt = nil, nil
        local state = Data.AutoBounty
        local target = Data.CurrentActionTarget or Data.GunFocusTarget
        if
            not state
            or Data.PunishmentGunActive
            or not force and (not target or not state.Selected[target] or phowg:auto_bounty_target_allowed(target))
        then
            return
        end
        phowg:stop_gun_fire('Ragebot')
        if phowg.china_release_extra then
            phowg:china_release_extra()
        end
        phowg:clear_ragebot_idle()
        phowg:clear_rifle_void()
        phowg:clear_ragebot_void_spam()
        if target then
            phowg:release_stomp_target(target)
        end
        releasefrozenexcept(nil)
        phowg:cancel_c_frame_movement({ Combat = true, Stomp = true, RagebotIdle = true })
        Data.CurrentActionTarget, Data.CurrentMainTarget, Data.GunFocusTarget, Data.GunAimTarget = nil, nil, nil, nil
        Data.RagebotArrival, Data.RagebotMoveIntent = nil, nil
        Data.CurrentStatus = 'Idle'
    end
    function phowg:auto_bounty_targets()
        local state = Data.AutoBounty
        local targets = {}
        if not state then
            return targets
        end
        for name in pairs(state.Amounts) do
            local player = state.Players[name]
            if player and player ~= LocalPlayer and isstomped(player) then
                state.Completed[name] = state.Revisions[name]
                state.Events[name] = nil
            end
            if
                phowg:auto_bounty_target_allowed(player)
                and player.Character
                and getroot(player.Character)
                and not isdead(player)
                and not isstomped(player)
            then
                targets[#targets + 1] = player
                state.Selected[player] = true
            end
        end
        return targets
    end
    function phowg:refresh_auto_bounties(state)
        if Data.AutoBounty ~= state then
            return
        end
        state.Pending = false
        local amounts = {}
        for poster, entry in pairs(state.Posters) do
            local texts = poster:FindFirstChild('Texts')
            local function label(partName)
                local part = texts and texts:FindFirstChild(partName)
                local surface = part and part:FindFirstChild('SurfaceGui')
                local text = surface and surface:FindFirstChild('TextLabel')
                return text and text:IsA('TextLabel') and text or nil
            end
            local nameLabel, amountLabel = label('PlayerName'), label('Bounty')
            for key, object in pairs({ NameLabel = nameLabel or false, AmountLabel = amountLabel or false }) do
                if entry[key] ~= object then
                    if entry[key .. 'Connection'] then
                        entry[key .. 'Connection']:Disconnect()
                    end
                    entry[key] = object
                    entry[key .. 'Connection'] = object and object:GetPropertyChangedSignal('Text'):Connect(function()
                        phowg:queue_auto_bounties(state)
                    end) or nil
                end
            end
            local text = nameLabel and nameLabel.Text:gsub('<[^>]->', '') or ''
            local name = text:match('@([%w_]+)') or text:match('^%s*([%w_]+)%s*$')
            name = name and string.lower(name)
            local amount = phowg:bounty_amount(amountLabel and amountLabel.Text)
            if entry.Name and (entry.Name ~= name or amount == 0) then
                state.Events[entry.Name] = nil
            end
            entry.Name = name
            if name and amount > 0 then
                amounts[name] = math.max(amounts[name] or 0, amount)
                state.Events[name] = nil
            end
        end
        for name, amount in pairs(state.Events) do
            amounts[name] = amounts[name] or amount
        end
        for name, amount in pairs(amounts) do
            if state.Amounts[name] ~= amount then
                state.Revisions[name] = (state.Revisions[name] or 0) + 1
            end
        end
        for name in pairs(state.Amounts) do
            if not amounts[name] then
                state.Revisions[name] = (state.Revisions[name] or 0) + 1
            end
        end
        state.Amounts = amounts
        phowg:invalidate_auto_bounty(false)
    end
    function phowg:queue_auto_bounties(state)
        if Data.AutoBounty ~= state or state.Pending then
            return
        end
        state.Pending = true
        task.defer(phowg_callbacks.refresh_auto_bounties, state)
    end
    local function remove_poster(state, poster)
        local entry = state.Posters[poster]
        if not entry then
            return
        end
        disconnect(entry.Connections)
        for _, key in ipairs({ 'NameLabelConnection', 'AmountLabelConnection' }) do
            if entry[key] then
                entry[key]:Disconnect()
            end
        end
        if entry.Name then
            state.Events[entry.Name] = nil
        end
        state.Posters[poster] = nil
        phowg:queue_auto_bounties(state)
    end
    local function bind_folder(state, folder)
        if state.Folder == folder then
            return
        end
        disconnect(state.FolderConnections)
        for poster in pairs(table.clone(state.Posters)) do
            remove_poster(state, poster)
        end
        state.Folder = folder
        if not folder then
            phowg:queue_auto_bounties(state)
            return
        end
        local function add(poster)
            if state.Posters[poster] or not poster:IsA('Model') then
                return
            end
            local entry = { Connections = {} }
            state.Posters[poster] = entry
            entry.Connections[1] = poster.DescendantAdded:Connect(function()
                phowg:queue_auto_bounties(state)
            end)
            entry.Connections[2] = poster.DescendantRemoving:Connect(function()
                phowg:queue_auto_bounties(state)
            end)
            phowg:queue_auto_bounties(state)
        end
        state.FolderConnections[1] = folder.ChildAdded:Connect(add)
        state.FolderConnections[2] = folder.ChildRemoved:Connect(function(poster)
            remove_poster(state, poster)
        end)
        for _, poster in ipairs(folder:GetChildren()) do
            add(poster)
        end
    end
    local function bind_map(state, map)
        if state.Map == map then
            return
        end
        disconnect(state.MapConnections)
        state.Map = map
        bind_folder(state, map and map:FindFirstChild('BountyPosters'))
        if map then
            state.MapConnections[1] = map.ChildAdded:Connect(function(child)
                if child.Name == 'BountyPosters' then
                    bind_folder(state, child)
                end
            end)
            state.MapConnections[2] = map.ChildRemoved:Connect(function(child)
                if child == state.Folder then
                    bind_folder(state, nil)
                end
            end)
        end
    end
    function phowg:stop_auto_bounty()
        local state = Data.AutoBounty
        if not state then
            return
        end
        phowg:invalidate_auto_bounty(true)
        Data.AutoBounty = nil
        disconnect(state.Connections)
        disconnect(state.MapConnections)
        disconnect(state.FolderConnections)
        for poster in pairs(table.clone(state.Posters)) do
            remove_poster(state, poster)
        end
        Data.TargetListCache, Data._ActionableAt = nil, nil
    end
    function phowg:start_auto_bounty()
        if Data.AutoBounty or Library.Unloaded or Data.SafeMode then
            return
        end
        local state: { [string]: any } = {
            Amounts = {}, Events = {}, Revisions = {}, Completed = {}, Players = {}, Selected = {},
            Posters = {}, Connections = {}, MapConnections = {}, FolderConnections = {},
        }
        Data.AutoBounty = state
        phowg:invalidate_auto_bounty(true)
        for _, player in ipairs(Players:GetPlayers()) do
            state.Players[string.lower(player.Name)] = player
        end
        state.Connections[1] = Players.PlayerAdded:Connect(function(player)
            state.Players[string.lower(player.Name)] = player
        end)
        state.Connections[2] = Players.PlayerRemoving:Connect(function(player)
            local name = string.lower(player.Name)
            state.Players[name], state.Events[name], state.Selected[player] = nil, nil, nil
            phowg:queue_auto_bounties(state)
        end)
        state.Connections[3] = Workspace.ChildAdded:Connect(function(child)
            if child.Name == 'MAP' then
                bind_map(state, child)
            end
        end)
        state.Connections[4] = Workspace.ChildRemoved:Connect(function(child)
            if child == state.Map then
                bind_map(state, nil)
            end
        end)
        if MainEvent then
            state.Connections[5] = MainEvent.OnClientEvent:Connect(function(kind, player, amount)
                if
                    kind ~= 'HighBounty'
                    or typeof(player) ~= 'Instance'
                    or not player:IsA('Player')
                    or player == LocalPlayer
                    or player.Parent ~= Players
                then
                    return
                end
                amount = phowg:bounty_amount(amount)
                if amount == 0 then
                    return
                end
                local name = string.lower(player.Name)
                state.Events[name] = amount
                state.Completed[name] = nil
                phowg:queue_auto_bounties(state)
            end)
        end
        bind_map(state, Workspace:FindFirstChild('MAP'))
        phowg:refresh_auto_bounties(state)
        ragebot_on()
    end
    phowg:register_cleanup('auto bounty', function(_, reason)
        if reason == 'unload' then
            phowg:stop_auto_bounty()
        end
    end)
end
function gettargetlist()
    if phowg:target_search_active() then
        return phowg:target_search_engaged() and { Data.TargetSearch.Target } or {}
    end
    if phowg:auto_bounty_enabled() and not Data.PunishmentGunActive then
        return phowg:auto_bounty_targets()
    end
    for player, character in pairs(Data.SupportCompletedCharacters or {}) do
        if not player.Parent or player.Character and player.Character ~= character then
            Data.SupportCompletedCharacters[player] = nil
            if Data.SupportCompletedTargets then
                Data.SupportCompletedTargets[player] = nil
            end
            Data.TargetListCache = nil
        end
    end
    local Targets = {}
    if not LocalPlayer.Character then
        return Targets
    end
    local TargetAll = (Toggles.target_all and Toggles.target_all.Value) or false
    local useMulti = haslockedsources()
    local selVal = Options.target_select and Options.target_select.Value or nil
    local selKey = (typeof(selVal) == 'Instance' and selVal:GetFullName()) or tostring(selVal)
    local now = tick()
    local cache = Data['TargetListCache']
    local _stickySingle = Data['StickyTarget']
    if
        cache
        and now - cache.at < 0.15
        and cache.all == TargetAll
        and cache.multi == useMulti
        and cache.single == Data['SingleLockedTarget']
        and cache.sel == selKey
        and cache.sticky == Data['StickyIncludeTarget']
        and cache.stickySingle == _stickySingle
    then
        return phowg:ready_support_targets(cache.list)
    end
    if TargetAll then
        for _, Plr in ipairs(Players:GetPlayers()) do
            if
                Plr ~= LocalPlayer
                and intelligence:get_character_cache(Plr)
                and not iswhitelistedplayer(Plr)
                and not (Data['RageWhitelist'] and Data['RageWhitelist'][Plr])
            then
                local crewId = getplayercrewid(Plr)
                if crewId and Data['WhitelistedCrews'][tostring(crewId)] then
                else
                    local TargetRoot = getroot(Plr.Character)
                    if TargetRoot then
                        table.insert(Targets, Plr)
                    end
                end
            end
        end
    elseif useMulti then
        local function push_multi(Plr)
            if not Plr or not Plr.Parent or Plr == LocalPlayer then
                return
            end
            if not intelligence:get_character_cache(Plr) then
                return
            end
            if iswhitelistedplayer(Plr) then
                return
            end
            if Data['RageWhitelist'] and Data['RageWhitelist'][Plr] then
                return
            end
            if iscrewwhitelisted(Plr) then
                return
            end
            for _, p in ipairs(Targets) do
                if p == Plr then
                    return
                end
            end
            table.insert(Targets, Plr)
        end
        for Plr, _ in pairs(Data['DropdownTargets'] or {}) do
            push_multi(Plr)
        end
        for Plr, _ in pairs(Data['LockedTargets'] or {}) do
            push_multi(Plr)
        end
        if Data['SingleLockedTarget'] and Data['SingleLockedTarget'].Parent then
            push_multi(Data['SingleLockedTarget'])
        end
        for Plr, _ in pairs(Data['PunishmentTargets'] or {}) do
            push_multi(Plr)
        end
    else
        local TargetPlr = nil
        if
            Data['SingleLockedTarget']
            and Data['SingleLockedTarget'].Parent
            and not isstomped(Data['SingleLockedTarget'])
        then
            TargetPlr = Data['SingleLockedTarget']
        else
            local Selected = Options.target_select and Options.target_select.Value
            if typeof(Selected) == 'Instance' and Selected:IsA('Player') and not isstomped(Selected) then
                TargetPlr = Selected
            elseif typeof(Selected) == 'string' and #Selected > 0 then
                local Plr = Players:FindFirstChild(Selected)
                if Plr and not isstomped(Plr) then
                    TargetPlr = Plr
                end
            end
        end
        if
            TargetPlr
            and TargetPlr ~= LocalPlayer
            and intelligence:get_character_cache(TargetPlr)
            and not iswhitelistedplayer(TargetPlr)
            and not (Data['RageWhitelist'] and Data['RageWhitelist'][TargetPlr])
            and not iscrewwhitelisted(TargetPlr)
        then
            local TargetRoot = getroot(TargetPlr.Character)
            if TargetRoot then
                table.insert(Targets, TargetPlr)
            end
        end
    end
    if Data['Settings'].IncludeTarget then
        local st = Data['SilentAimStickyTarget']
        if
            st
            and st ~= LocalPlayer
            and st.Parent
            and intelligence:get_character_cache(st)
            and not iswhitelistedplayer(st)
            and not (Data['RageWhitelist'] and Data['RageWhitelist'][st])
            and not iscrewwhitelisted(st)
        then
            local dup = false
            for _, p in ipairs(Targets) do
                if p == st then
                    dup = true
                    break
                end
            end
            if not dup then
                table.insert(Targets, st)
            end
        end
        Data['StickyIncludeTarget'] = st
    else
        Data['StickyIncludeTarget'] = nil
    end
    local SortDist = {}
    for _, Plr in ipairs(Targets) do
        SortDist[Plr] = getdistancetoplayer(Plr)
    end
    table.sort(Targets, function(A, B)
        return (SortDist[A] or math.huge) < (SortDist[B] or math.huge)
    end)
    local ReadyTargets = {}
    for _, Plr in ipairs(Targets) do
        if isplayerloadedin(Plr) then
            table.insert(ReadyTargets, Plr)
        end
    end
    local NowT = tick()
    local FreshRet = Data['PunishmentTargets'] and next(Data['PunishmentTargets']) ~= nil or false
    if not FreshRet and #ReadyTargets > 1 then
        local Cur = Data['StickyMainTarget']
        local ValidCur = false
        if Cur and Cur.Parent and Cur ~= LocalPlayer and intelligence:get_character_cache(Cur) then
            for _, p in ipairs(ReadyTargets) do
                if p == Cur then
                    ValidCur = true
                    break
                end
            end
        end
        if ValidCur and ReadyTargets[1] ~= Cur and NowT - (Data['TargetSwitchAt'] or 0) < 1.5 then
            for i, p in ipairs(ReadyTargets) do
                if p == Cur then
                    table.remove(ReadyTargets, i)
                    break
                end
            end
            table.insert(ReadyTargets, 1, Cur)
        else
            if ReadyTargets[1] ~= Cur then
                Data['TargetSwitchAt'] = NowT
            end
            Data['StickyMainTarget'] = ReadyTargets[1]
        end
    elseif #ReadyTargets > 0 then
        if ReadyTargets[1] ~= Data['StickyMainTarget'] then
            Data['TargetSwitchAt'] = NowT
        end
        Data['StickyMainTarget'] = ReadyTargets[1]
    else
        Data['StickyMainTarget'] = nil
    end
    do
        local _sbt = get_sticky_target()
        if
            _sbt
            and _sbt.Parent
            and _sbt ~= LocalPlayer
            and intelligence:get_character_cache(_sbt)
            and not isstomped(_sbt)
            and isplayerloadedin(_sbt)
        then
            local _found = false
            for _, _p in ipairs(ReadyTargets) do
                if _p == _sbt then
                    _found = true
                    break
                end
            end
            if not _found then
                local _r = getroot(_sbt.Character)
                if _r then
                    table.insert(ReadyTargets, _sbt)
                end
            end
            for _i, _p in ipairs(ReadyTargets) do
                if _p == _sbt then
                    table.remove(ReadyTargets, _i)
                    break
                end
            end
            table.insert(ReadyTargets, 1, _sbt)
            Data['StickyMainTarget'] = _sbt
        end
    end
    for index = #ReadyTargets, 1, -1 do
        if Data['SupportCompletedTargets'] and Data['SupportCompletedTargets'][ReadyTargets[index]] then
            table.remove(ReadyTargets, index)
        end
    end
    Data['TargetListCache'] = {
        at = tick(),
        all = TargetAll,
        multi = useMulti,
        single = Data['SingleLockedTarget'],
        sel = selKey,
        sticky = Data['StickyIncludeTarget'],
        stickySingle = Data['StickyTarget'],
        list = ReadyTargets,
    }
    return phowg:ready_support_targets(ReadyTargets)
end
function resetspectate()
