function getspectatetarget()
    local sticky = get_sticky_target()
    if sticky and sticky.Parent and sticky.Character and sticky.Character.Parent then
        return sticky
    end
    local record = phowg.get_active_target and phowg:get_active_target()
    if record then
        return record.Player
    end
    local function spectatable(Plr)
        if not Plr or not Plr.Parent or Plr == LocalPlayer then
            return false
        end
        local ch = Plr.Character
        if not ch or not ch.Parent then
            return false
        end
        return true
    end
    if spectatable(Data['CurrentActionTarget']) then
        return Data['CurrentActionTarget']
    end
    do
        local _sst = get_sticky_target()
        if spectatable(_sst) then
            Data['CurrentMainTarget'] = _sst
            return _sst
        end
    end
    local stickySpec = Data['SilentAimStickyTarget']
    if spectatable(stickySpec) then
        Data['CurrentMainTarget'] = stickySpec
        return stickySpec
    end
    if spectatable(Data['CurrentMainTarget']) then
        return Data['CurrentMainTarget']
    end
    if spectatable(Data['SingleLockedTarget']) then
        Data['CurrentMainTarget'] = Data['SingleLockedTarget']
        return Data['SingleLockedTarget']
    end
    local Selected = Options.target_select and Options.target_select.Value
    if typeof(Selected) == 'Instance' and Selected:IsA('Player') then
        if spectatable(Selected) then
            Data['CurrentMainTarget'] = Selected
            return Selected
        end
    elseif typeof(Selected) == 'string' and #Selected > 0 then
        local Plr = Players:FindFirstChild(Selected)
        if spectatable(Plr) then
            Data['CurrentMainTarget'] = Plr
            return Plr
        end
    elseif type(Selected) == 'table' then
        for k, on in pairs(Selected) do
            local cand = nil
            if on then
                if typeof(k) == 'Instance' and k:IsA('Player') then
                    cand = k
                end
            end
            if cand and spectatable(cand) then
                Data['CurrentMainTarget'] = cand
                return cand
            end
        end
        for _, v in ipairs(Selected) do
            local cand = nil
            if typeof(v) == 'Instance' and v:IsA('Player') then
                cand = v
            elseif type(v) == 'string' and #v > 0 then
                cand = Players:FindFirstChild(v)
            end
            if cand and spectatable(cand) then
                Data['CurrentMainTarget'] = cand
                return cand
            end
        end
    end
    if haslockedsources() then
        local BestPlr = nil
        local BestDist = math.huge
        for Plr, _ in pairs(Data['LockedTargets']) do
            if spectatable(Plr) then
                local Dist = getdistancetoplayer(Plr)
                if Dist < BestDist then
                    BestDist = Dist
                    BestPlr = Plr
                end
            end
        end
        if BestPlr then
            Data['CurrentMainTarget'] = BestPlr
            return BestPlr
        end
    end
    if Toggles.target_all and Toggles.target_all.Value then
        local BestPlr = nil
        local BestDist = math.huge
        for _, Plr in ipairs(Players:GetPlayers()) do
            if spectatable(Plr) then
                local Dist = getdistancetoplayer(Plr)
                if Dist < BestDist then
                    BestDist = Dist
                    BestPlr = Plr
                end
            end
        end
        if BestPlr then
            Data['CurrentMainTarget'] = BestPlr
            return BestPlr
        end
    end
    return nil
end
function updatespectate()
    if Data['IsRespawning'] then
        lockcameratolocal()
        return
    end
    if not (Toggles.spectate and Toggles.spectate.Value and Data['SpectateActive']) then
        resetspectate()
        return
    end
    local TargetPlr = getspectatetarget()
    local Camera = Workspace.CurrentCamera
    local ch = TargetPlr and TargetPlr.Character or nil
    if Camera and ch and ch.Parent then
        local subj = ch:FindFirstChild('UpperTorso')
            or ch:FindFirstChild('Torso')
            or ch:FindFirstChild('Head')
            or ch:FindFirstChild('HumanoidRootPart')
            or ch:FindFirstChildOfClass('Humanoid')
        if subj then
            Camera.CameraSubject = subj
            return
        end
    end
    resetspectate()
end
function spectateloop()
    while Toggles.spectate and Toggles.spectate.Value and Data['SpectateActive'] do
        updatespectate()
        task.wait(0.25)
    end
    resetspectate()
end
function startvelocity()
    if localactionblocked() then
        return
    end
    if Data['Flying'] then
        return
    end
    if Data['WallWalking'] then
        return
    end
    Data['VelocityActive'] = true
    if Data['VelocityConnection'] then
        Data['VelocityConnection']:Disconnect()
    end
    Data['VelocityConnection'] = connectshared(RunService.Heartbeat, function()
        if localactionblocked() then
            return
        end
        if
            not Data['VelocityActive']
            or Data['Flying']
            or not (Toggles.speed_velocity and Toggles.speed_velocity.Value)
        then
            return
        end
        local char = LocalPlayer.Character
        if not char then
            return
        end
        local Root = getroot(char)
        local Hum = gethumanoid(char)
        local SpeedVal = (Options.speed_velocity_value and Options.speed_velocity_value.Value) or 150
        if Root and Hum then
            local MoveDir = Hum.MoveDirection
            if MoveDir.Magnitude > 0 then
                local yVel = Root.AssemblyLinearVelocity.Y
                local hv = Root.Velocity
                if math.abs(hv.Y) > math.abs(yVel) then
                    yVel = hv.Y
                end
                local newVel = Vector3.new(MoveDir.X * SpeedVal, yVel, MoveDir.Z * SpeedVal)
                Root.AssemblyLinearVelocity = newVel
                Root.Velocity = newVel
            end
        end
    end, RunService, 'frame/velocity', 0, 'event/Heartbeat', RunService)
end
function stopvelocity()
