function stopsilentanimations()
    local state = Data.SilentAnimState
    if state then
        for _, connection in ipairs(state.Connections) do
            connection:Disconnect()
        end
        for track, priority in pairs(state.Priorities) do
            pcall(function()
                track.Priority = priority
            end)
        end
    elseif Data.SilentAnimConnection then
        Data.SilentAnimConnection:Disconnect()
    end
    Data.SilentAnimState, Data.SilentAnimConnection = nil, nil
end
function startsilentanimations()
    stopsilentanimations()
    local character = LocalPlayer.Character
    if not character or not (Toggles.silent_animations and Toggles.silent_animations.Value) then
        return
    end
    local state: { [string]: any } =
        { Character = character, Connections = {}, Priorities = setmetatable({}, { __mode = 'k' }) }
    Data.SilentAnimState = state
    local function ignored(track)
        local id = track.Animation and track.Animation.AnimationId
        if not id then
            return false
        end
        if id == Data.AnimPlayerId then
            return true
        end
        local function matches(value)
            local raw = tostring(value or '')
            local number = raw:match('(%d+)')
            if not number then
                return false
            end
            local resolved = raw:find('rbxasset', 1, true) and ('rbxassetid://' .. number)
                or Data.AnimResolveCache and Data.AnimResolveCache[number]
            return resolved == id
        end
        if matches(Options.anim_player_custom_id and Options.anim_player_custom_id.Value) then
            return true
        end
        for _, value in pairs(Data.AnimPlayerList or {}) do
            if matches(value) then
                return true
            end
        end
        return false
    end
    local function apply(track)
        if Data.SilentAnimState ~= state or ignored(track) then
            return
        end
        local id = track.Animation and track.Animation.AnimationId
        local name, priority = track.Name, nil
        if id == 'rbxassetid://15609995579' or id == 'rbxassetid://10370351535' or id == 'rbxassetid://18665811005' then
            priority = Enum.AnimationPriority.Action3
        elseif
            name == 'FallAnim'
            or name == 'Animation1'
            or name == 'Animation2'
            or name == 'JumpAnim'
            or name == 'WalkAnim'
            or name == 'RunAnim'
        then
            priority = Enum.AnimationPriority.Action2
        elseif name == 'ToolNoneAnim' or name == 'ToolLungeAnim' or name == 'ToolSlashAnim' then
            priority = Enum.AnimationPriority.Action3
        end
        if priority and track.Priority ~= priority then
            if state.Priorities[track] == nil then
                state.Priorities[track] = track.Priority
            end
            track.Priority = priority
        end
    end
    local function bind(animator)
        if
            state.Animator == animator
            or not animator:IsA('Animator')
            or animator.Parent ~= character:FindFirstChildOfClass('Humanoid')
        then
            return
        end
        if state.Played then
            state.Played:Disconnect()
        end
        state.Animator = animator
        state.Played = connectshared(
            animator.AnimationPlayed,
            apply,
            character,
            'silent animation played',
            0,
            'event/AnimationPlayed',
            animator
        )
        state.Connections[#state.Connections + 1] = state.Played
        for _, track in ipairs(animator:GetPlayingAnimationTracks()) do
            apply(track)
        end
    end
    Data.SilentAnimConnection = connectshared(
        character.DescendantAdded,
        bind,
        character,
        'silent animator added',
        0,
        'event/DescendantAdded',
        character
    )
    state.Connections[#state.Connections + 1] = Data.SilentAnimConnection
    local humanoid = character:FindFirstChildOfClass('Humanoid')
    local animator = humanoid and humanoid:FindFirstChildOfClass('Animator')
    if animator then
        bind(animator)
    end
end
local function createflycore(root)
    local core = Instance.new('Part')
    core.Name = 'Core'
    core.Size = Vector3.new(0.05, 0.05, 0.05)
    core.CFrame = root.CFrame
    core.CanCollide = false
    core.CanQuery = false
    core.CanTouch = false
    core.Massless = true
    core.Transparency = 1
    core.Parent = Workspace
    local weld = Instance.new('Weld')
    weld.Part0 = core
    weld.Part1 = root
    weld.C0 = CFrame.new()
    weld.C1 = CFrame.new()
    weld.Parent = core
    return core
end
phowg.create_fly_core = createflycore
function phowg:get_fly_vehicle()
    local folder = Workspace:FindFirstChild('Vehicles')
    local owner = folder and folder:FindFirstChild(LocalPlayer.Name)
    if not owner then
        return nil, nil
    end
    local part
    if owner:IsA('BasePart') then
        part = owner
    elseif owner:IsA('Model') then
        local state = Data['FlyVehicle']
        part = owner.PrimaryPart
            or (state and state.Owner == owner and state.Part:IsDescendantOf(owner) and state.Part)
            or owner:FindFirstChildWhichIsA('BasePart', true)
    end
    if part and not part:IsDescendantOf(LocalPlayer.Character) then
        return part, owner
    end
    return nil, nil
end
function phowg:clear_fly_controllers()
    for _, key in ipairs({ 'FlyBodyVelocity', 'FlyBodyGyro' }) do
        local mover = Data[key]
        Data[key] = nil
        if mover then
            mover:Destroy()
        end
    end
    local core = Data['FlyCore']
    Data['FlyCore'] = nil
    if core then
        core:Destroy()
    end
    local state = Data['FlyVehicle']
    Data['FlyVehicle'] = nil
    if state then
        if state.Connection then
            state.Connection:Disconnect()
        end
        for force, enabled in pairs(state.NativeForces) do
            if force.Parent and force.Enabled == false then
                force.Enabled = enabled
            end
        end
        if state.Part.Parent and state.Part.Anchored == false then
            state.Part.Anchored = state.Anchored
        end
    end
    Data['FlyIdleAt'] = nil
end
function phowg:restore_fly_humanoid(humanoid)
    if not Data['FlyHumanoidActive'] then
        return
    end
    Data['FlyHumanoidActive'] = nil
    if humanoid and humanoid.Parent then
        humanoid.PlatformStand = Data['FlyPlatformStand'] == true
        local spin = Data['SpinbotRotation']
        humanoid.AutoRotate = not (spin and spin.Humanoid == humanoid) and Data['FlyAutoRotate'] ~= false
        humanoid:SetStateEnabled(Enum.HumanoidStateType.FallingDown, Data['FlyFallingDown'] ~= false)
        humanoid:SetStateEnabled(Enum.HumanoidStateType.Freefall, Data['FlyFreefall'] ~= false)
    end
end
function phowg:set_fly_target(root, humanoid, vehicle, owner)
    local state = Data['FlyVehicle']
    local core = vehicle or Data['FlyCore']
    local bodyVelocity, bodyGyro = Data['FlyBodyVelocity'], Data['FlyBodyGyro']
    if
        (
            vehicle and state and state.Part == vehicle and state.Owner == owner
            or not vehicle and not state and core and core.Parent == Workspace
        )
        and bodyVelocity
        and bodyVelocity.Parent == core
        and bodyGyro
        and bodyGyro.Parent == core
    then
        return
    end
    phowg:clear_fly_controllers()
    phowg:restore_fly_humanoid(humanoid)
    if vehicle then
        state = { Part = vehicle, Owner = owner, Anchored = vehicle.Anchored, NativeForces = {} }
        Data['FlyVehicle'] = state
        local function suspend(force)
            if Data['FlyVehicle'] ~= state or force.Parent ~= vehicle or not force:IsA('VectorForce') then
                return
            end
            if state.NativeForces[force] == nil then
                state.NativeForces[force] = force.Enabled
            end
            force.Enabled = false
        end
        state.Connection = connectshared(
            vehicle.ChildAdded,
            suspend,
            vehicle,
            'fly/vehicle force added',
            0,
            'event/ChildAdded',
            vehicle
        )
        for _, child in ipairs(vehicle:GetChildren()) do
            suspend(child)
        end
        core = vehicle
        Data['FlyFacing'] = vehicle.CFrame.Rotation
    else
        local method = (Options.fly_method and Options.fly_method.Value) or 'body'
        Data['FlyHumanoidActive'] = true
        humanoid.AutoRotate = false
        humanoid.PlatformStand = method ~= 'velocity'
        humanoid:SetStateEnabled(Enum.HumanoidStateType.FallingDown, false)
        humanoid:SetStateEnabled(Enum.HumanoidStateType.Freefall, false)
        core = createflycore(root)
        Data['FlyCore'] = core
        local clientCF = Data['CSyncTable'][2] and Data['CSyncTable'][1] or root.CFrame
        Data['FlyFacing'] = clientCF.Rotation
    end
    for _, name in ipairs({ 'PhowgFlyVelocity', 'PhowgFlyOrientation' }) do
        local oldController = core:FindFirstChild(name)
        if oldController and oldController:IsA('BodyMover') then
            oldController:Destroy()
        end
    end
    bodyVelocity = createbodymover('BodyVelocity', core)
    bodyVelocity.Name = 'PhowgFlyVelocity'
    bodyVelocity.MaxForce = Vector3.new(9e9, 9e9, 9e9)
    bodyVelocity.P = 100000
    bodyVelocity.Velocity = Vector3.zero
    Data['FlyBodyVelocity'] = bodyVelocity
    bodyGyro = createbodymover('BodyGyro', core)
    bodyGyro.Name = 'PhowgFlyOrientation'
    bodyGyro.MaxTorque = Vector3.new(9e9, 9e9, 9e9)
    bodyGyro.P = 90000
    bodyGyro.D = 1000
    bodyGyro.CFrame = Data['FlyFacing']
    Data['FlyBodyGyro'] = bodyGyro
end
function startfly()
    if localactionblocked() or Data['Flying'] then
        return
    end
    local character = LocalPlayer.Character
    local humanoid = character and character:FindFirstChildOfClass('Humanoid')
    local root = character and character:FindFirstChild('HumanoidRootPart')
    if not humanoid or not root then
        return
    end
    if Data['WallWalking'] then
        stopwallwalk()
    end
    Data['Flying'] = true
    Data['FlyCharacter'] = character
    local spin = Data['SpinbotRotation']
    Data['FlyAutoRotate'] = spin and spin.Humanoid == humanoid and spin.AutoRotate or humanoid.AutoRotate
    if spin then
        spin.Angle = 0
        Data['SpinbotAt'] = tick()
    end
    Data['FlyPlatformStand'] = humanoid.PlatformStand
    Data['FlyFallingDown'] = humanoid:GetStateEnabled(Enum.HumanoidStateType.FallingDown)
    Data['FlyFreefall'] = humanoid:GetStateEnabled(Enum.HumanoidStateType.Freefall)
    if Data['VelocityActive'] then
        Data['VelocityPausedByFly'] = true
        stopvelocity()
    end
    if Data['FlyNoclipConn'] then
        Data['FlyNoclipConn']:Disconnect()
    end
    Data['FlyNoclipConn'] = connectshared(RunService.Stepped, function()
        if not Data['Flying'] or LocalPlayer.Character ~= character or Data['FlyVehicle'] or localactionblocked() then
            return
        end
        local now = tick()
        if now - (Data['FlyNoclipAt'] or 0) < 0.2 then
            return
        end
        Data['FlyNoclipAt'] = now
        for _, part in ipairs(character:GetDescendants()) do
            if part:IsA('BasePart') then
                part.CanCollide = false
            end
        end
    end, RunService, 'frame/fly noclip', 0, 'event/Stepped', RunService)
    if Data['FlyConnection'] then
        Data['FlyConnection']:Disconnect()
    end
    for _, name in ipairs({ 'PhowgFlyVelocity', 'PhowgFlyOrientation', 'PhowgFlyAttachment' }) do
        local oldController = root:FindFirstChild(name)
        if
            oldController
            and (
                oldController:IsA('BodyMover')
                or oldController:IsA('LinearVelocity')
                or oldController:IsA('AlignOrientation')
                or oldController:IsA('Attachment')
            )
        then
            oldController:Destroy()
        end
    end
    local vehicle, owner = phowg:get_fly_vehicle()
    phowg:set_fly_target(root, humanoid, vehicle, owner)
    applyflyvelocity(root)
    local binding = 'PhowgFlight_' .. tostring(LocalPlayer.UserId)
    local connection = { Connected = true }
    function connection:Disconnect()
        if not self.Connected then
            return
        end
        self.Connected = false
        RunService:UnbindFromRenderStep(binding)
    end
    Data['FlyConnection'] = connection
    RunService:BindToRenderStep(binding, Enum.RenderPriority.Camera.Value + 1, function()
        if not Data['Flying'] or LocalPlayer.Character ~= character or not root.Parent or not humanoid.Parent then
            stopfly()
            return
        end
        if localactionblocked() then
            updatesuspension()
            return
        end
        local activeVehicle, activeOwner = phowg:get_fly_vehicle()
        phowg:set_fly_target(root, humanoid, activeVehicle, activeOwner)
        if not activeVehicle then
            local method = (Options.fly_method and Options.fly_method.Value) or 'body'
            humanoid.AutoRotate = false
            humanoid.PlatformStand = method ~= 'velocity'
            if method == 'velocity' and not Data['Flinging'] then
                humanoid:ChangeState(Enum.HumanoidStateType.Running)
            end
        end
        applyflyvelocity(root)
    end)
end
function stopfly()
    if not Data['Flying'] and not Data['FlyCharacter'] and not Data['FlyCore'] and not Data['FlyVehicle'] then
        return
    end
    Data['Flying'] = false
    if Data['FlyNoclipConn'] then
        Data['FlyNoclipConn']:Disconnect()
    end
    Data['FlyNoclipConn'] = nil
    if Data['FlyConnection'] then
        Data['FlyConnection']:Disconnect()
    end
