        root.AssemblyLinearVelocity = Vector3.zero
        root.AssemblyAngularVelocity = Vector3.zero
        root.Velocity = Vector3.zero
        root.RotVelocity = Vector3.zero
    end
    phowg:clear_fly_controllers()
    phowg:restore_fly_humanoid(humanoid)
    Data['FlyFacing'] = nil
    Data['FlyVelocity'] = nil
    Data['FlyCharacter'] = nil
    if Data['VelocityPausedByFly'] then
        Data['VelocityPausedByFly'] = nil
        if Toggles.speed_velocity and Toggles.speed_velocity.Value and not localactionblocked() then
            startvelocity()
        end
    end
