end)
function wallwalk_blocked(char, hum)
    if not char or not hum then
        return true
    end
    local st = hum:GetState()
    if
        hum.Health <= 0
        or hum.Sit
        or hum.SeatPart
        or hum.PlatformStand
        or st == Enum.HumanoidStateType.Dead
        or st == Enum.HumanoidStateType.Ragdoll
        or char:HasTag('__Ragdoll_Active')
        or char:GetAttribute('Carried')
        or char:GetAttribute('PassengerOf')
        or char:GetAttribute('BatmanFlight')
        or char:FindFirstChild('BatmanGrapple')
        or char:FindFirstChild('GRABBING_CONSTRAINT')
        or char:FindFirstChild('[CarHitBox]')
    then
        return true
    end
    local be = char:FindFirstChild('BodyEffects')
    if be then
        for _, n in ipairs({ 'K.O', 'Dead', 'SDeath', 'Cuff', 'Grabbed' }) do
            local v = be:FindFirstChild(n)
            if v and v.Value then
                return true
            end
        end
    end
    return false
end
function wallwalk_params(char)
    local p = RaycastParams.new()
    p.FilterType = Enum.RaycastFilterType.Exclude
    p.FilterDescendantsInstances = { char }
    p.RespectCanCollide = true
    p.IgnoreWater = true
    return p
end
function wallwalk_cast(origin, dir, params)
    local hit = workspace:Raycast(origin, dir, params)
    if not hit or not hit.Instance.CanCollide then
        return nil
    end
    local inst = hit.Instance
    if not inst.Anchored and not (inst.AssemblyRootPart and inst.AssemblyRootPart.Anchored) then
        return nil
    end
    local par = inst.Parent
    while par and par ~= workspace do
        if par:FindFirstChildOfClass('Humanoid') then
            return nil
        end
        par = par.Parent
    end
    return hit
end
function wallwalk_nearby(hrp, dist, params)
    local dirs = {
        -hrp.CFrame.UpVector,
        hrp.CFrame.LookVector,
        -hrp.CFrame.LookVector,
        hrp.CFrame.RightVector,
        -hrp.CFrame.RightVector,
        Vector3.new(0, 1, 0),
        Vector3.new(0, -1, 0),
    }
    for _, d in ipairs(dirs) do
        local hit = wallwalk_cast(hrp.Position, d * dist, params)
        if hit then
            return hit
        end
    end
    return nil
end
function wallwalk_find(hrp, up, moveDir, height, params)
    local pos = hrp.Position
    local flat = moveDir - up * moveDir:Dot(up)
    local downHit = wallwalk_cast(pos, -up * (height + 2.5), params)
    if not downHit and flat.Magnitude <= 0.05 then
        flat = hrp.CFrame.LookVector - up * hrp.CFrame.LookVector:Dot(up)
    end
    local stepHit = nil
    if flat.Magnitude > 0.05 then
        local unit = flat.Unit
        local side = math.clamp(hrp.Size.X * 0.5, 0.6, 1.2) + 0.2
        local tvel = hrp.AssemblyLinearVelocity - up * hrp.AssemblyLinearVelocity:Dot(up)
        local reach = math.clamp(hrp.Size.X * 0.5 + 1.5 + tvel.Magnitude * 0.12, 2, 6)
        local baseD = nil
        if downHit then
            baseD = (pos - downHit.Position):Dot(up)
        else
            baseD = height
        end
        local fwdHit = wallwalk_cast(pos - up * (baseD - 0.1), unit * reach, params)
        local fwdDist = nil
        if fwdHit then
            fwdDist = fwdHit.Distance + 0.35
        else
            fwdDist = reach
        end
        local sideUnit = unit:Cross(up).Unit
        local best = 0.05
        local bestHit = nil
        local offs = {
            -unit * side,
            Vector3.new(0, 0, 0),
            sideUnit * side,
            -sideUnit * side,
            unit * fwdDist,
            unit * reach,
            unit * fwdDist + sideUnit * side,
            unit * fwdDist - sideUnit * side,
        }
        for _, off in ipairs(offs) do
            local h = wallwalk_cast(pos + off + up * 4, -up * (height + 6.5), params)
            if h and h.Normal:Dot(up) > 0.35 then
                local base = nil
                if downHit then
                    base = downHit.Position
                else
                    base = pos - up * height
                end
                local d = (h.Position - base):Dot(up)
                if best < d and d <= 3.5 then
                    best = d
                    bestHit = h
                end
            end
        end
        if bestHit then
            return { Position = bestHit.Position, Normal = up, Instance = bestHit.Instance }
        end
        stepHit = wallwalk_cast(pos + unit * fwdDist + up * 2.5, -up * (height + 5), params)
        local wallHit = wallwalk_cast(pos, unit * (height + 0.7), params)
        if wallHit and wallHit.Normal:Dot(up) < 0.7 then
            return wallHit
        end
        if fwdHit and fwdHit.Normal:Dot(up) < 0.7 then
            return fwdHit
        end
    end
    if downHit then
        return downHit
    end
    if flat.Magnitude > 0.05 then
        local unit = flat.Unit
        for _, d in ipairs({ 0.5, 1.5, 2.5 }) do
            local h = wallwalk_cast(pos + unit * 2.5 - up * (height + d), -unit * (height + 4), params)
            if h and h.Normal:Dot(unit) > 0.1 then
                return h
            end
        end
    end
    if stepHit and stepHit.Normal:Dot(up) > 0.7 and (pos - stepHit.Position):Dot(up) >= height - 2.5 then
        return stepHit
    end
    local lk = hrp.CFrame.LookVector - up * hrp.CFrame.LookVector:Dot(up)
    if lk.Magnitude < 0.05 then
        lk = hrp.CFrame.RightVector - up * hrp.CFrame.RightVector:Dot(up)
    end
    local u1 = lk.Unit
    local u2 = u1:Cross(up).Unit
    for _, d in ipairs({ u1, -u1, u2, -u2 }) do
        local h = wallwalk_cast(pos + d * 2.5 + up * 2.5, -up * (height + 5), params)
        if h and h.Normal:Dot(up) > 0.7 and (pos - h.Position):Dot(up) >= height - 2.5 then
            return h
        end
    end
    return nil
end
function wallwalk_sample_up(hrp, upVec, lookVec, params, height)
    local origin = hrp.Position
    local radial = lookVec:Cross(upVec)
    if radial.Magnitude < 0.05 then
        radial = hrp.CFrame.RightVector:Cross(upVec)
    end
    if radial.Magnitude < 0.05 then
        return nil
    end
    radial = radial.Unit
    local sum = Vector3.zero
    local count = 0
    local gap = nil
    local center = wallwalk_cast(origin, -upVec * (height + 4), params)
    if center then
        sum = sum + center.Normal
        count = count + 1
        gap = center.Distance
    end
    for i = 1, 8 do
        local dtheta = math.pi * 2 * ((i - 1) / 8)
        local w = 0.25 + 0.75 * math.abs(math.cos(dtheta))
        local offset = CFrame.fromAxisAngle(upVec, dtheta) * radial
        local dir = (-upVec * 3 + offset * 1.5).Unit
        local h = wallwalk_cast(origin + offset * 2, dir * (height + 6), params)
        if h then
            sum = sum + w * h.Normal
            count = count + 1
        end
    end
    for i = 1, 4 do
        local dtheta = math.pi * 2 * ((i - 1) / 4) + math.pi / 4
        local w = 0.25 + 0.75 * math.abs(math.cos(dtheta))
        local offset = CFrame.fromAxisAngle(upVec, dtheta) * radial
        local dir = (offset * 2 - upVec * 2).Unit
        local h = wallwalk_cast(origin + upVec * 1 + dir * 1.5, dir * 3, params)
        if h then
            sum = sum + 2 * w * h.Normal
            count = count + 1
        end
    end
    if count > 0 and sum.Magnitude > 0.001 then
        return sum.Unit, gap
    end
    return nil
end
function wallwalk_catalog_anim(catalogId)
    local cacheKey = 'WallWalkAnim_' .. tostring(catalogId)
    if Data[cacheKey] then
        return Data[cacheKey]
    end
    if Data[cacheKey .. '_Miss'] then
        return nil
    end
    local ok, objs = pcall(function()
        return game:GetObjects('rbxassetid://' .. tostring(catalogId))
    end)
    if ok and objs then
        for _, o in ipairs(objs) do
            if o:IsA('Animation') and o.AnimationId and o.AnimationId ~= '' then
                Data[cacheKey] = o.AnimationId
                return o.AnimationId
            end
            for _, d in ipairs(o:GetDescendants()) do
                if d:IsA('Animation') and d.AnimationId and d.AnimationId ~= '' then
                    Data[cacheKey] = d.AnimationId
                    return d.AnimationId
                end
            end
        end
    end
    Data[cacheKey .. '_Miss'] = true
    return nil
end
function wallwalk_load_track(animator, animId)
    if not animator or not animId then
        return nil
    end
    local okA, anim = pcall(function()
        local a = Instance.new('Animation')
        a.AnimationId = animId
        return a
    end)
    if not okA or not anim then
        return nil
    end
    local okT, track = pcall(function()
        return animator:LoadAnimation(anim)
    end)
    if not okT or not track then
        return nil
    end
    track.Priority = Enum.AnimationPriority.Action
    track.Looped = true
    return track
end
function wallwalk_anim(moving, speed)
    local idleT = Data['WallWalkIdleTrack']
    local moveT = Data['WallWalkMoveTrack']
    if not idleT and not moveT then
        return
    end
    local wantMove = moving and moveT
    if wantMove then
        if not moveT.IsPlaying then
            pcall(function()
                moveT:Play(0.15, 1, 1)
            end)
        end
        local adj = 0
        if speed > 0.15 then
            adj = math.clamp(speed / 8, 0.2, 6)
        end
        pcall(function()
            moveT:AdjustSpeed(adj)
        end)
    elseif moveT and moveT.IsPlaying then
        pcall(function()
            moveT:Stop(0.15)
        end)
    end
    if idleT then
        if wantMove then
            if idleT.IsPlaying then
                pcall(function()
                    idleT:Stop(0.15)
                end)
            end
        elseif not idleT.IsPlaying then
            pcall(function()
                idleT:Play(0.15, 1, 1)
            end)
        end
    end
end
function startwallwalk()
    if localactionblocked() then
        return
    end
    if Data['WallWalking'] then
        return
    end
    local char = LocalPlayer.Character
    local hum = char and gethumanoid(char) or nil
    local hrp = char and getroot(char) or nil
    if not char or not hum or not hrp or not hrp.Parent then
        return
    end
    if wallwalk_blocked(char, hum) then
        return
    end
    local probeHeight = (Options.wallwalk_height and Options.wallwalk_height.Value) or 3.5
    local probeParams = wallwalk_params(char)
    local probe = wallwalk_find(hrp, hrp.CFrame.UpVector, hrp.CFrame.LookVector, probeHeight, probeParams)
        or wallwalk_nearby(hrp, probeHeight + 2.5, probeParams)
    if not probe or math.abs(probe.Normal.Y) > 0.75 then
        return
    end
    if stopspinbot then
        stopspinbot()
    end
    if Data['Flying'] then
        stopfly()
    end
    if Data['VelocityActive'] then
        Data['VelocityPausedByWallwalk'] = true
        stopvelocity()
    end
    if Workspace:FindFirstChild('CoreWall') then
        Workspace.CoreWall:Destroy()
    end
    local core = Instance.new('Part')
    core.Name = 'CoreWall'
    core.Size = Vector3.new(0.05, 0.05, 0.05)
    core.CanCollide = false
    core.Transparency = 1
    core.Parent = Workspace
    local weld = Instance.new('Weld', core)
    weld.Part0 = core
    weld.Part1 = hrp
    weld.C0 = CFrame.new(0, 0, 0)
    local bv = createbodymover('BodyVelocity', core)
    bv.MaxForce = Vector3.new(9e9, 9e9, 9e9)
    bv.Velocity = Vector3.zero
    local bg = createbodymover('BodyGyro', core)
    bg.MaxTorque = Vector3.new(9e9, 9e9, 9e9)
    bg.P = 9e4
    bg.CFrame = hrp.CFrame
    Data['WallWalkCore'] = core
    Data['WallWalkBV'] = bv
    Data['WallWalkBG'] = bg
    Data['WallWalking'] = true
    Data['WallWalkFocused'] = true
    Data['WallWalkConns'] = {}
    local up = hrp.CFrame.UpVector
    local look = hrp.CFrame.LookVector
    local anchor = hrp.Position
    local flatCount = 0
    local sampleFlip = false
    local cachedN = nil
    local cachedGap = nil
    Data['WallWalkUp'] = up
    Data['WallWalkParams'] = wallwalk_params(char)
    hum:SetStateEnabled(Enum.HumanoidStateType.FallingDown, false)
    hum:SetStateEnabled(Enum.HumanoidStateType.Freefall, false)
    hum:ChangeState(Enum.HumanoidStateType.Physics)
    Data['WallWalkIdleTrack'] = nil
    Data['WallWalkMoveTrack'] = nil
    local wAnimator = hum:FindFirstChildOfClass('Animator')
    if wAnimator then
        Data['WallWalkIdleTrack'] = wallwalk_load_track(wAnimator, wallwalk_catalog_anim('138917579889432'))
        Data['WallWalkMoveTrack'] = wallwalk_load_track(wAnimator, wallwalk_catalog_anim('130349209708136'))
        if (not Data['WallWalkIdleTrack'] or not Data['WallWalkMoveTrack']) and not Data['WallWalkAnimWarned'] then
            Data['WallWalkAnimWarned'] = true
            pcall(function()
                Library:Notify('wall walk: a wall animation failed to load', Library.NotifyDuration or 4)
            end)
        end
    end
    Data['WallWalkAutoRotate'] = hum.AutoRotate
    hum.AutoRotate = false
    table.insert(
        Data['WallWalkConns'],
        connectshared(
            UserInputService.WindowFocusReleased,
            function()
                Data['WallWalkFocused'] = false
            end,
            UserInputService,
            'event/UserInputService.WindowFocusReleased',
            0,
            'event/WindowFocusReleased',
            UserInputService
        )
    )
    table.insert(
        Data['WallWalkConns'],
        connectshared(UserInputService.WindowFocused, function()
            Data['WallWalkFocused'] = true
        end, UserInputService, 'event/UserInputService.WindowFocused', 0, 'event/WindowFocused', UserInputService)
    )
    local function foreign_mover(d)
        if
            Data['WallWalking']
            and not d:IsDescendantOf(core)
            and d.Enabled
            and (
                d:IsA('BodyMover')
                or d:IsA('BodyVelocity')
                or d:IsA('BodyPosition')
                or d:IsA('BodyGyro')
                or d:IsA('BodyAngularVelocity')
                or d:IsA('BodyThrust')
                or d:IsA('BodyForce')
                or d:IsA('LinearVelocity')
                or d:IsA('AngularVelocity')
                or d:IsA('AlignPosition')
                or d:IsA('AlignOrientation')
                or d:IsA('VectorForce')
            )
        then
            stopwallwalk()
        end
    end
    table.insert(
        Data['WallWalkConns'],
        connectshared(
            char.DescendantAdded,
            foreign_mover,
            char,
            'event/char.DescendantAdded',
            0,
            'event/DescendantAdded',
            char
        )
    )
    for _, d in ipairs(char:GetDescendants()) do
        if
            d:IsA('BodyMover')
            or d:IsA('BodyVelocity')
            or d:IsA('BodyPosition')
            or d:IsA('BodyGyro')
            or d:IsA('BodyAngularVelocity')
            or d:IsA('BodyThrust')
            or d:IsA('BodyForce')
            or d:IsA('LinearVelocity')
            or d:IsA('AngularVelocity')
            or d:IsA('AlignPosition')
            or d:IsA('AlignOrientation')
            or d:IsA('VectorForce')
        then
            if not d:IsDescendantOf(core) and d.Enabled then
                stopwallwalk()
                return
            end
        end
    end
    table.insert(
        Data['WallWalkConns'],
        connectshared(RunService.PreSimulation, function()
            if localactionblocked() then
                return
            end
            if not Data['WallWalking'] then
                return
            end
            local c = LocalPlayer.Character
            local h = c and gethumanoid(c) or nil
            local r = c and getroot(c) or nil
            local coreL = Data['WallWalkCore']
            local bvL = Data['WallWalkBV']
            local bgL = Data['WallWalkBG']
            if
                not c
                or c ~= char
                or not h
                or not r
                or not r.Parent
                or not coreL
                or not coreL.Parent
                or not bvL
                or not bgL
            then
                stopwallwalk()
                return
            end
            if r.Anchored or wallwalk_blocked(c, h) then
                stopwallwalk()
                return
            end
            if h:GetState() ~= Enum.HumanoidStateType.Physics then
                h:ChangeState(Enum.HumanoidStateType.Physics)
            end
            if h.AutoRotate then
                h.AutoRotate = false
            end
            local cam = workspace.CurrentCamera
            local typing = UserInputService:GetFocusedTextBox() ~= nil
            if TextChatService.ChatInputBarConfiguration and TextChatService.ChatInputBarConfiguration.IsFocused then
                typing = true
            end
            local mv = Vector3.zero
            if Data['WallWalkFocused'] and not typing then
                local ix = 0
                local iz = 0
                if UserInputService:IsKeyDown(Enum.KeyCode.D) then
                    ix = ix + 1
                end
                if UserInputService:IsKeyDown(Enum.KeyCode.A) then
                    ix = ix - 1
                end
                if UserInputService:IsKeyDown(Enum.KeyCode.S) then
                    iz = iz + 1
                end
                if UserInputService:IsKeyDown(Enum.KeyCode.W) then
                    iz = iz - 1
                end
                mv = Vector3.new(ix, 0, iz)
            end
            local camLook = nil
            if cam then
                camLook = cam.CFrame.LookVector
            else
                camLook = look
            end
            if math.abs(camLook:Dot(up)) > 0.8 and cam then
                camLook = cam.CFrame.UpVector
            end
            local proj = camLook - up * camLook:Dot(up)
            if proj.Magnitude < 0.05 then
                proj = look - up * look:Dot(up)
            end
            if proj.Magnitude < 0.05 then
                proj = up:Cross(Vector3.new(1, 0, 0))
            end
            if proj.Magnitude < 0.05 then
                proj = up:Cross(Vector3.new(0, 0, 1))
            end
            local unit = proj.Unit
            local wish = unit * -mv.Z + unit:Cross(up).Unit * mv.X
            if wish.Magnitude > 1 then
                wish = wish.Unit
            end
            local height = (Options.wallwalk_height and Options.wallwalk_height.Value) or 3.5
            local stickHeight = height
            if wish.Magnitude <= 0.05 then
                stickHeight = -3
            end
            local speedOpt = (Options.wallwalk_speed and Options.wallwalk_speed.Value)
                or math.clamp(h.WalkSpeed, 0, 120)
            local params = Data['WallWalkParams'] or wallwalk_params(c)
            sampleFlip = not sampleFlip
            local sampled, gap = cachedN, cachedGap
            if sampleFlip or not sampled then
                sampled, gap = wallwalk_sample_up(r, up, look, params, height)
                cachedN, cachedGap = sampled, gap
            end
            local rawN = sampled
            if not sampled then
                local near = wallwalk_nearby(r, height + 2.5, params)
                if near then
                    rawN = near.Normal
                end
            end
            if not rawN then
                local pull = (anchor - r.Position) * 14
                if pull.Magnitude > 18 then
                    pull = pull.Unit * 18
                end
                bvL.Velocity = bvL.Velocity:Lerp(pull, 0.45)
                wallwalk_anim(false, 0)
                return
            end
            anchor = r.Position
            if math.abs(rawN.Y) > 0.75 then
                flatCount = flatCount + 1
            else
                flatCount = 0
            end
            if flatCount >= 6 then
                stopwallwalk()
                return
            end
            if sampled then
                local sax = up:Cross(sampled)
                local sdot = math.clamp(up:Dot(sampled), -1, 1)
                if sax.Magnitude > 0.001 then
                    local sang = math.acos(sdot)
                    if sang > 0.008 then
                        local step = CFrame.fromAxisAngle(sax.Unit, sang * 0.25)
                        up = step:VectorToWorldSpace(up)
                        look = step:VectorToWorldSpace(look)
                    end
                elseif sdot < 0 then
                    up = sampled
                end
            else
                up = rawN
            end
            Data['WallWalkUp'] = up
            if wish.Magnitude > 0.05 then
                local want = wish.Unit
                local lax = look:Cross(want)
                local ldot = math.clamp(look:Dot(want), -1, 1)
                if lax.Magnitude > 0.001 then
                    look = CFrame.fromAxisAngle(lax.Unit, math.acos(ldot) * 0.5):VectorToWorldSpace(look)
                elseif ldot < 0 then
                    look = want
                end
            end
            look = look - up * look:Dot(up)
            if look.Magnitude < 0.05 then
                look = unit - up * unit:Dot(up)
            end
            if look.Magnitude < 0.05 then
                look = up:Cross(Vector3.new(1, 0, 0))
            end
            if look.Magnitude < 0.05 then
                look = up:Cross(Vector3.new(0, 0, 1))
            end
            look = look.Unit
            local gyroTarget = CFrame.lookAlong(Vector3.new(0, 0, 0), look, up)
            bgL.CFrame = bgL.CFrame:Lerp(gyroTarget, 0.5)
            local stick = 0
            local fade = 1
            if gap then
                stick = math.clamp((stickHeight - gap) * 14, -35, 35)
                if math.abs(stick) < 0.5 then
                    stick = 0
                end
                fade = 1 - math.max(0, gap - stickHeight - 0.5) / 2
                fade = math.clamp(fade, 0, 1)
            end
            local velTarget = wish * speedOpt * fade + up * stick
            bvL.Velocity = bvL.Velocity:Lerp(velTarget, 0.45)
            local wallTvel = r.AssemblyLinearVelocity - up * r.AssemblyLinearVelocity:Dot(up)
            wallwalk_anim(wish.Magnitude > 0.05, wallTvel.Magnitude)
        end, RunService, 'frame/wallwalk', 0, 'event/PreSimulation', RunService)
    )
end
function stopwallwalk()
    if not Data['WallWalking'] then
        return
    end
    Data['WallWalking'] = false
    if Data['WallWalkConns'] then
        for _, cn in ipairs(Data['WallWalkConns']) do
            pcall(function()
                cn:Disconnect()
            end)
        end
        Data['WallWalkConns'] = nil
    end
    if Data['WallWalkCore'] then
        pcall(function()
            Data['WallWalkCore']:Destroy()
        end)
        Data['WallWalkCore'] = nil
    end
    Data['WallWalkBV'] = nil
    Data['WallWalkBG'] = nil
    Data['WallWalkParams'] = nil
    local wI = Data['WallWalkIdleTrack']
    if wI then
        pcall(function()
            wI:Stop(0.1)
        end)
        pcall(function()
            wI:Destroy()
        end)
    end
    Data['WallWalkIdleTrack'] = nil
    local wM = Data['WallWalkMoveTrack']
    if wM then
        pcall(function()
            wM:Stop(0.1)
        end)
        pcall(function()
            wM:Destroy()
        end)
    end
    Data['WallWalkMoveTrack'] = nil
    if Data['VelocityPausedByWallwalk'] then
        Data['VelocityPausedByWallwalk'] = nil
        if Toggles.speed_velocity and Toggles.speed_velocity.Value then
            startvelocity()
        end
    end
    local c = LocalPlayer.Character
    local h = c and gethumanoid(c) or nil
    local r = c and getroot(c) or nil
    if r and r.Parent and not localactionblocked() then
        local lv = r.CFrame.LookVector - Vector3.yAxis * r.CFrame.LookVector:Dot(Vector3.yAxis)
        if lv.Magnitude < 0.05 then
            lv = Vector3.new(0, 0, 1)
        end
        r.CFrame = CFrame.lookAlong(r.Position, lv.Unit, Vector3.yAxis)
        r.AssemblyLinearVelocity = Vector3.zero
        r.AssemblyAngularVelocity = Vector3.zero
    end
    if h and h.Parent then
        local ar = Data['WallWalkAutoRotate']
        if ar == nil then
            ar = true
        end
        Data['WallWalkAutoRotate'] = nil
        h.AutoRotate = ar
        h:SetStateEnabled(Enum.HumanoidStateType.FallingDown, true)
        h:SetStateEnabled(Enum.HumanoidStateType.Freefall, true)
        h:ChangeState(Enum.HumanoidStateType.GettingUp)
        h:ChangeState(Enum.HumanoidStateType.Running)
    end
end
function stopspinbot()
    local state = Data['SpinbotRotation']
    Data['SpinbotRotation'] = nil
    Data['SpinbotAt'] = nil
    if state and state.Humanoid.Parent then
        local flying = Data['Flying'] and Data['FlyCharacter'] == state.Character
        if flying and typeof(Data['FlyFacing']) == 'CFrame' then
            Data['FlyFacing'] = CFrame.Angles(0, state.Angle or 0, 0) * Data['FlyFacing']
        end
        state.Humanoid.AutoRotate = not (flying and Data['FlyHumanoidActive']) and state.AutoRotate
    end
end
function spinbotloop()
    local enabled = Toggles.spinbot and Toggles.spinbot.Value and Data['SpinbotActive']
    if Options.spinbot_keybind then
        enabled = Toggles.spinbot and Toggles.spinbot.Value and Options.spinbot_keybind:GetState()
    end
    if not enabled or localactionblocked() or Data['WallWalking'] or Data['Flinging'] or Data['IsRespawning'] then
        stopspinbot()
        return
    end
    local char = LocalPlayer.Character
    if not char then
        stopspinbot()
        return
    end
    local hum = gethumanoid(char)
    if not hum or hum.Health <= 0 then
        stopspinbot()
        return
    end
    local root = getroot(char)
    if not root or not root.Parent or root.Anchored then
        stopspinbot()
        return
    end
    local state = Data['SpinbotRotation']
    if not state or state.Humanoid ~= hum then
        stopspinbot()
        local original = hum.AutoRotate
        if Data['Flying'] and Data['FlyHumanoidActive'] then
            original = Data['FlyAutoRotate']
        end
        state = { Character = char, Humanoid = hum, AutoRotate = original, Angle = 0 }
        Data['SpinbotRotation'] = state
    end
    hum.AutoRotate = false
    local now = tick()
    local dt = math.min(now - (Data['SpinbotAt'] or now), 0.1)
    Data['SpinbotAt'] = now
    local speed = (Options.spinbot_speed and Options.spinbot_speed.Value) or 100
    local delta = math.rad(speed * dt)
    state.Angle = ((state.Angle or 0) + delta) % (math.pi * 2)
    if not Data['Flying'] then
        root.CFrame = root.CFrame * CFrame.Angles(0, delta, 0)
    end
end
phowg:register_cleanup('spinbot rotation', function(scope)
    local state = Data['SpinbotRotation']
    if not scope or state and state.Character == scope then
        stopspinbot()
    end
end)
function thawcharacter()
    local char = LocalPlayer.Character
    if not char then
        return
    end
    local hum = char:FindFirstChildOfClass('Humanoid')
    if hum then
        hum.PlatformStand = false
        hum:ChangeState(Enum.HumanoidStateType.GettingUp)
        hum:ChangeState(Enum.HumanoidStateType.Running);
        (function()
            for _, tr in ipairs(hum:GetPlayingAnimationTracks()) do
                if tr.IsPlaying and tr.Speed == 0 then
                    tr:AdjustSpeed(1)
                end
            end
        end)()
    end
    local hrp = char:FindFirstChild('HumanoidRootPart')
    if hrp then
        hrp.AssemblyLinearVelocity = Vector3.zero
        hrp.AssemblyAngularVelocity = Vector3.zero
    end
end
function reapply_character_mods(Char)
    Char = Char or LocalPlayer.Character
    if not Char then
        return
    end
    Data['RespawnedAt'] = tick()
    task.spawn(function()
        local t0 = tick()
        local hum = nil
        while tick() - t0 < 15 do
            if LocalPlayer.Character ~= Char or not Char.Parent then
                return
            end
            hum = Char:FindFirstChildOfClass('Humanoid')
            if hum and hum.Health > 0 then
                break
            end
            task.wait(0.25)
        end
        if LocalPlayer.Character ~= Char or not Char.Parent then
            return
        end
        hum = Char:FindFirstChildOfClass('Humanoid')
        if not hum or hum.Health <= 0 then
            return
        end
        if Toggles.walkspeed_enabled and Toggles.walkspeed_enabled.Value then
            pcall(starthumanoidwalkspeed)
        end
        if Toggles.jumppower_enabled and Toggles.jumppower_enabled.Value then
            pcall(starthumanoidjumppower)
        end
        if Toggles.remove_slowdowns and Toggles.remove_slowdowns.Value then
            pcall(startremoveslowdowns)
        end
        if Toggles.remove_jump_cooldown and Toggles.remove_jump_cooldown.Value then
            pcall(startremovejumpcooldown)
        end
        if Toggles.disable_states and Toggles.disable_states.Value then
            apply_disable_states()
        end
        for _ = 1, 3 do
            task.wait(0.5)
            if LocalPlayer.Character ~= Char then
                return
            end
            local h = Char:FindFirstChildOfClass('Humanoid')
            if not h or h.Health <= 0 then
                return
            end
            if Toggles.walkspeed_enabled and Toggles.walkspeed_enabled.Value then
                local want = (Options.walkspeed_value and Options.walkspeed_value.Value) or 16
                if h.WalkSpeed ~= want then
                    pcall(function()
                        h.WalkSpeed = want
                    end)
                end
            end
            if Toggles.jumppower_enabled and Toggles.jumppower_enabled.Value then
                local wantJ = (Options.jumppower_value and Options.jumppower_value.Value) or 50
                pcall(function()
                    h.UseJumpPower = true
                end)
                if h.JumpPower ~= wantJ then
                    pcall(function()
                        h.JumpPower = wantJ
                    end)
                end
            end
        end
        if LocalPlayer.Character ~= Char then
            return
        end
        if Toggles.auto_block and Toggles.auto_block.Value then
            pcall(function()
                phowg:start_loop('AutoBlock', autoblockloop)
            end)
        end
        if Toggles.auto_armor and Toggles.auto_armor.Value then
            phowg:queue_auto_armor('Armor')
        end
        if Toggles.auto_fire_armor and Toggles.auto_fire_armor.Value then
            phowg:queue_auto_armor('FireArmor')
        end
        if Toggles.auto_mask and Toggles.auto_mask.Value then
            pcall(function()
                phowg:queue_auto_demand('Mask')
            end)
        end
        if Data['DesyncActive'] and Toggles.desync_rotation and Toggles.desync_rotation.Value then
            pcall(function()
                phowg:start_loop('UnifiedCharacter', unified_character_loop)
            end)
        end
        if Data['UndergroundActive'] then
            pcall(function()
                phowg:start_loop('Underground', undergroundloop)
            end)
        end
        if Data['VoidActive'] then
            pcall(function()
                phowg:start_loop('VoidHide', voidhideloop)
            end)
        end
    end)
end
local function restoreflashback(character)
    if not (Toggles.flashback_enabled and Toggles.flashback_enabled.Value) then
        return false
    end
    local destination = Data['FlashbackDeathPos']
    if not destination or Data['FlashbackDeathCharacter'] == character or LocalPlayer.Character ~= character then
        return false
    end
    local root = character:FindFirstChild('HumanoidRootPart')
    local humanoid = character:FindFirstChildOfClass('Humanoid')
    if not root or not root.Parent or not humanoid or humanoid.Health <= 0 or Data['MoveToInFlight'] == root then
        return false
    end
    local effects = character:FindFirstChild('BodyEffects')
    if effects then
        for _, name in ipairs({ 'SDeath', 'SDead', 'Dead', 'K.O', 'KO' }) do
            local value = effects:FindFirstChild(name)
            if value and value.Value == true then
                return false
            end
        end
    end
    destination += Vector3.new(0, 5, 0)
    root.CFrame = destination
    root.AssemblyLinearVelocity = Vector3.zero
    root.AssemblyAngularVelocity = Vector3.zero
    Data['CSyncTable'][1] = destination
    Data['CSyncTable'][2] = false
    Data['LastServerCF'] = destination
    Data['AppliedServerCF'] = nil
    Data['AppliedServerAt'] = nil
    Data['AppliedServerTag'] = nil
    Data['MoveToActive'] = false
    Data['MoveToTargetCF'] = nil
    Data['DisplayCF'] = nil
    Data['LastMoveToAt'] = tick()
    table.clear(Data['CSync'].Queue)
    Data['CSync'].PendingCF = nil
    Local_Data['ClientPos'] = destination
    getgenv().PhowgClientPos = destination
    Data['FlashbackDeathPos'] = nil
    Data['FlashbackDeathCharacter'] = nil
    return true
end
function handlecharacterrespawn(Char)
    if LocalPlayer.Character ~= Char or not Char.Parent then
        return
    end
    Data['IsRespawning'] = true
    Char:WaitForChild('FULLY_LOADED_CHAR', 10)
    if LocalPlayer.Character ~= Char or not Char.Parent then
        return
    end
    Data['_CSyncResetGen'] = Data['_CSyncResetGen'] + 1
    Data['CSyncTable'][2] = false
    Data['CSyncTable'][1] = CFrame.new()
    Data['CSync'].Queue = {}
    Data['CSync'].PendingCF = nil
    Data['LastServerCF'] = nil
    Data['DisplayCF'] = nil
    Data['Buying'] = false
    Data['ReloadedAwait'] = {}
    Data['GrippedTools'] = {}
    Data['AntiStompTriggered'] = false
    Data['CurrentStatus'] = 'Idle'
    Data['CurrentActionTarget'] = nil
    hidevisualizer()
    local earlyHrp = Char and Char:FindFirstChild('HumanoidRootPart') or nil
    if earlyHrp then
        buildvisualizer()
    end
    local shouldSilent = Toggles.silent_animations and Toggles.silent_animations.Value
    if Data['Flying'] then
        stopfly()
    end
    if Data['VelocityActive'] then
        stopvelocity()
    end
    if Data['WallWalking'] then
        stopwallwalk()
    end
    if shouldSilent then
        stopsilentanimations()
    end
    Char:SetAttribute('ShouldSilent', shouldSilent)
    task.spawn(function()
        local at0 = tick()
        while Data['IsRespawning'] and tick() - at0 < 10 do
            task.wait(0.1)
        end
        if LocalPlayer.Character ~= Char then
            return
        end
        for Index in pairs(Data['ActiveAccessories']) do
            local Dropdown = Options.accessories_dropdown
            if Dropdown and Dropdown.Value and Dropdown.Value[Index] then
                local Id = nil
                if Index == 'valk' then
                    Id = 1402432199
                elseif Index == 'emerald valk' then
                    Id = 2830437685
                elseif Index == 'void star' then
                    Id = 1125510
                elseif Index == 'ice valk' then
                    Id = 4390891467
                elseif Index == 'sparkle time fedora' then
                    Id = 1285307
                elseif Index == 'purple sparkle time fedora' then
                    Id = 63043890
                elseif Index == 'red sparkle time fedora' then
                    Id = 72082328
                elseif Index == 'white sparkle time fedora' then
                    Id = 1016143686
                elseif Index == 'toxic horns' then
                    Id = 1744060292
                elseif Index == 'fiery horns' then
                    Id = 215718515
                elseif Index == 'frozen horns' then
                    Id = 74891470
                elseif Index == 'dominus astra' then
                    Id = 162067148
                elseif Index == 'dominus frigidus' then
                    Id = 48545806
                elseif Index == 'dominus infernus' then
                    Id = 31101391
                elseif Index == 'dominus empyreus' then
                    Id = 21070012
                end
                if Id then
                    createattachment(Id, Index)
                end
            end
        end
    end)
    task.spawn(function()
        local flowGen = Data['_CSyncResetGen']
        local function alive()
            return flowGen == Data['_CSyncResetGen'] and LocalPlayer.Character == Char and Char.Parent ~= nil
        end
        local function deadflow()
            if flowGen == Data['_CSyncResetGen'] then
                Data['IsRespawning'] = false
            end
        end
        task.delay(30, function()
            if Data['IsRespawning'] and flowGen == Data['_CSyncResetGen'] then
                local c = LocalPlayer.Character
                local h = c and c:FindFirstChildOfClass('Humanoid')
                if c and c.Parent and h and h.Health > 0 and c:FindFirstChild('HumanoidRootPart') then
                    Data['IsRespawning'] = false
                end
            end
        end)
        local hrp = Char:WaitForChild('HumanoidRootPart', 5)
        local hum = Char:WaitForChild('Humanoid', 5)
        if not alive() then
            deadflow()
            return
        end
        if not hrp or not hum or hum.Health <= 0 then
            Data['IsRespawning'] = false
            return
        end
        local fullyLoaded = Char:FindFirstChild('FULLY_LOADED_CHAR')
        if not fullyLoaded then
            fullyLoaded = Char:WaitForChild('FULLY_LOADED_CHAR', 5)
        end
        if not alive() then
            deadflow()
            return
        end
        if fullyLoaded and fullyLoaded:IsA('ValueBase') then
            local t0 = tick()
            repeat
                task.wait(0.05)
            until (fullyLoaded.Value == true or fullyLoaded.Value == 'true') or tick() - t0 > 5 or not alive()
        elseif fullyLoaded then
            task.wait(0.1)
        end
        if not alive() then
            deadflow()
            return
        end
        Char:WaitForChild('BodyEffects', 2)
        if not alive() then
            deadflow()
            return
        end
        Data['FlashbackReadyCharacter'] = Char
        restoreflashback(Char)
        task.wait(0.25)
        if not alive() then
            deadflow()
            return
        end
        hrp = Char:FindFirstChild('HumanoidRootPart')
        hum = Char:FindFirstChildOfClass('Humanoid')
        if not hrp or not hum or hum.Health <= 0 then
            Data['IsRespawning'] = false
            return
        end
        Data['CSyncTable'][1] = hrp.CFrame
        Data['LastServerCF'] = hrp.CFrame
        Data['LastMoveToAt'] = tick()
        Data['CSync'].Queue = {}
        Data['CSync'].PendingCF = nil
        hidevisualizer()
        buildvisualizer()
        task.wait(0.05)
        if
            Toggles.spectate
            and Toggles.spectate.Value
            and Data['SpectateActive']
            and (
                Data['CurrentActionTarget']
                or Data['CurrentMainTarget']
                or Data['SingleLockedTarget']
                or next(Data['LockedTargets'])
            )
        then
            updatespectate()
        else
            resetspectate()
            lockcameratolocal()
        end
        if Data['VoidActive'] and not Data['LoopTokens']['VoidHide'] then
            Data['CurrentStatus'] = 'ragebot: voiding'
            phowg:start_loop('VoidHide', voidhideloop)
        end
        if Data['UndergroundActive'] and not Data['LoopTokens']['Underground'] then
            phowg:start_loop('Underground', undergroundloop)
        end
        if
            Data['DesyncActive']
            and Toggles.desync_rotation
            and Toggles.desync_rotation.Value
            and not Data['LoopTokens']['UnifiedCharacter']
        then
            phowg:start_loop('UnifiedCharacter', unified_character_loop)
        end
        if
            phowg:ragebot_action_enabled('auto_kill')
            or phowg:ragebot_action_enabled('auto_stomp')
            or Toggles.auto_arrest and Toggles.auto_arrest.Value
        then
            ragebot_on()
        end
        Data['CSyncTable'][1] = hrp.CFrame
        Data['LastServerCF'] = hrp.CFrame
        Data['LastMoveToAt'] = tick()
        Data['CSync'].Queue = {}
        local shouldSilent = Char:GetAttribute('ShouldSilent')
        if
            shouldSilent
            and Toggles.silent_animations
            and Toggles.silent_animations.Value
            and not Data['SilentAnimConnection']
        then
            startsilentanimations()
        end
        Data['IsRespawning'] = false
        thawcharacter()
        reapply_character_mods(Char)
        task.spawn(function()
            if LocalPlayer.Character ~= Char then
                return
            end
            buildvisualizer()
            if LocalPlayer.Character ~= Char then
                return
            end
            if Data['AvatarSpoof'] and Data['AvatarSpoof'].Desc then
                capturemyavatar(Char)
                if LocalPlayer.Character ~= Char then
                    return
                end
                applyavatarspooftochar(Char, false)
                buildvisualizer()
            elseif Data['AvatarSpoof'] then
                applyavatarspooftochar(Char, false)
            end
            if Toggles.auto_buy_on_respawn and Toggles.auto_buy_on_respawn.Value then
                task.spawn(function()
                    local loadChar = Char
                    local t0 = tick()
                    while not loadChar:FindFirstChild('HumanoidRootPart') and tick() - t0 < 10 do
                        task.wait(0.1)
                        if LocalPlayer.Character ~= loadChar then
                            return
                        end
                    end
                    if LocalPlayer.Character ~= loadChar then
                        return
                    end
                    if not loadChar:FindFirstChild('HumanoidRootPart') then
                        return
                    end
                    executeautobuyitems()
                end)
            end
            if LocalPlayer.Character ~= Char then
                return
            end
            if Toggles.auto_mask and Toggles.auto_mask.Value then
                phowg:queue_auto_demand('Mask')
            end
            if Toggles.custom_shoot_sound and Toggles.custom_shoot_sound.Value then
                hookshootsound()
            end
        end)
        if Data['Settings'].AbuseSpawn then
            task.spawn(function()
                local ff = Char:WaitForChild('ForceField', 10)
                if ff then
                    ff:GetPropertyChangedSignal('Parent'):Wait()
                    if Data['Settings'].AbuseSpawn then
                        local humanoid = Char:FindFirstChildOfClass('Humanoid')
                        if humanoid then
                            humanoid.Health = 0
                        end
                    end
                end
            end)
        end
    end)
end
function istoolvalid(Tool)
    return Tool
        and Tool.Parent
        and (Tool.Parent == LocalPlayer:FindFirstChild('Backpack') or Tool.Parent == LocalPlayer.Character)
end
function findtoolbypattern(Pattern)
    if LocalPlayer:FindFirstChild('Backpack') then
        for _, Tool in ipairs(LocalPlayer:FindFirstChild('Backpack'):GetChildren()) do
            if Tool:IsA('Tool') and Tool.Name:lower():match(Pattern) then
                return Tool
            end
        end
    end
    local Character = LocalPlayer.Character
    if Character then
        for _, Tool in ipairs(Character:GetChildren()) do
            if Tool:IsA('Tool') and Tool.Name:lower():match(Pattern) then
                return Tool
            end
        end
    end
    return nil
end
function findtoolbyexactname(Name)
    if LocalPlayer:FindFirstChild('Backpack') then
        local Tool = LocalPlayer:FindFirstChild('Backpack'):FindFirstChild(Name)
        if Tool and Tool:IsA('Tool') then
            return Tool
        end
    end
    local Character = LocalPlayer.Character
    if Character then
        local Tool = Character:FindFirstChild(Name)
        if Tool and Tool:IsA('Tool') then
            return Tool
        end
    end
    return nil
end
function phowg:cancel_backpack_reload()
    local job = Data.LoadoutReloadJob
    if not job then
        return
    end
    Data.LoadoutReloadJob, Data.LoadoutBusy = nil, nil
    if job.Hold then
        job.Hold:Stop()
        job.Hold = nil
        phowg:resume_active_movement(job.ReturnMovement)
        if
            (
                not job.ReturnMovement
                or job.ReturnMovement.Tag == 'RagebotVoid'
                    and not phowg:ragebot_void_move_valid(job.ReturnMovement.SourceVoidState)
            )
            and not Data.VoidActive
            and not reloadvoidactive()
            and not localactionblocked()
        then
            local client = Local_Data.ClientPos or getgenv().PhowgClientPos
            if typeof(client) == 'CFrame' then
                set_server_cframe(client, nil, Data.PRIO.LOADOUT, 'LoadoutReloadReturn')
            end
        end
    end
end
function phowg:invalidate_tool_restores()
    Data.ToolEquipRevision = (Data.ToolEquipRevision or 0) + 1
    Data.ToolCleanupUntil = tick() + 0.5
    Data.InventoryEquip, Data.PurchasedKnifeEquip = nil, nil
    phowg:cancel_backpack_reload()
end
function unequipall()
    if not LocalPlayer or not LocalPlayer.Character or not LocalPlayer:FindFirstChild('Backpack') then
        return
    end
    phowg:invalidate_tool_restores()
    local state = Data.ChinaHackState
    if state then
        state.Suspended = true
        state.MultiTarget, state.MultiCharacter = nil, nil
        table.clear(state.Equipped)
    end
    phowg:stop_gun_fire()
    local Character = LocalPlayer.Character
    local Tools = {}
    for _, Tool in ipairs(Character:GetChildren()) do
        if Tool:IsA('Tool') then
            table.insert(Tools, Tool)
        end
    end
    for _, Tool in ipairs(Tools) do
        if Tool and Tool.Parent == Character then
            Tool.Parent = LocalPlayer:FindFirstChild('Backpack')
        end
    end
end
function phowg:custom_reload_owned()
    if Library.Unloaded or Data.SharedSignalsClosed then
        return false
    end
    if Toggles.native_reload_coordination and not Toggles.native_reload_coordination.Value then
        return false
    end
    return Toggles.auto_reload and Toggles.auto_reload.Value
        or Toggles.loadout_manager and Toggles.loadout_manager.Value and Toggles.loadout_reload_backpack and Toggles.loadout_reload_backpack.Value
        or Data.RagebotIdle ~= nil
        or Data.LoadoutReloadJob ~= nil
        or Data.PunishmentGunActive
        or phowg.china_pair_selected and phowg:china_pair_selected() and rageboton() and phowg:ragebot_action_enabled('auto_kill')
        or tick() < (Data.ReloadOwnerUntil or 0)
end
function phowg:release_native_reload_owner()
    local state = Data.NativeReloadOwner
    Data.NativeReloadOwner = nil
    if not state then
        return
    end
    if state.Connection then
        state.Connection:Disconnect()
    end
    if state.Written and LocalPlayer:GetAttribute('AutoReload') == false then
        pcall(LocalPlayer.SetAttribute, LocalPlayer, 'AutoReload', state.Original)
    end
end
function phowg:sync_native_reload_owner(transaction)
    if transaction == true then
        Data.ReloadOwnerUntil = tick() + 1
    end
    if not phowg:custom_reload_owned() then
        phowg:release_native_reload_owner()
        return
    end
    local state = Data.NativeReloadOwner
    if not state then
        state = { Original = LocalPlayer:GetAttribute('AutoReload'), Writing = false, Written = false }
        Data.NativeReloadOwner = state
        state.Connection = connectshared(LocalPlayer:GetAttributeChangedSignal('AutoReload'), function()
            if Data.NativeReloadOwner ~= state or state.Writing then
                return
            end
            local value = LocalPlayer:GetAttribute('AutoReload')
            if value == false then
                return
            end
            state.Original = value
            if phowg:custom_reload_owned() then
                phowg:sync_native_reload_owner()
            end
        end, LocalPlayer, 'native reload ownership', 0, 'attribute/AutoReload', LocalPlayer)
    end
    if LocalPlayer:GetAttribute('AutoReload') ~= false then
        state.Writing = true
        local ok, err = pcall(LocalPlayer.SetAttribute, LocalPlayer, 'AutoReload', false)
        state.Writing = false
        if ok then
            state.Written = true
            state.Error = nil
        else
            state.Error = tostring(err)
        end
    end
end
registerheartbeat(
    'NativeReloadOwner',
    function()
        phowg:sync_native_reload_owner()
    end,
    0.1,
    function()
        return Data.NativeReloadOwner ~= nil or phowg:custom_reload_owned()
    end
)
phowg:register_cleanup('native reload owner', function(_, reason)
    if reason == 'unload' then
        Data.ReloadOwnerUntil = nil
        phowg:release_native_reload_owner()
    end
end)

function phowg:reload_pending(character)
    local pending = Data.GunReloadPending
    if not pending then
        return false
    end
    local ammo = pending.Tool and pending.Tool:FindFirstChild('Ammo')
    if
        pending.Character ~= character
        or tick() >= pending.Until
        or ammo and pending.Before ~= nil and type(ammo.Value) == 'number' and ammo.Value > pending.Before
    then
        Data.GunReloadPending = nil
        return false
    end
    return true
end
function phowg:local_gun_reloading(character)
    if isreloading() then
        return true
    end
    if not character then
        return false
    end
    for _, tool in ipairs(character:GetChildren()) do
        if tool:IsA('Tool') then
            local value = tool:FindFirstChild('Reloading') or tool:FindFirstChild('Reload')
            if value and value:IsA('BoolValue') and value.Value then
                return true
            end
        end
    end
    return false
end
function phowg:tool_equip_ready(tool)
    if not tool then
        return false
    end
    if not phowg:is_gun_weapon(tool.Name) then
        return true
    end
    return tool:FindFirstChild('Handle') ~= nil
        and tool:FindFirstChild('Ammo') ~= nil
        and tool:FindFirstChild('MaxAmmo') ~= nil
end
function phowg:request_gun_reload(tool, remote, reloadJob, preparation)
    local character = LocalPlayer.Character
    local backpack = LocalPlayer:FindFirstChild('Backpack')
    if
        Data.GunReloadSelection
        or not character
        or not backpack
        or not remote
        or localactionblocked()
        or Data.Buying
        or Data.Sorting
    then
        return false
    end
    if not tool or (tool.Parent ~= character and tool.Parent ~= backpack) then
        return false
    end
    if
        phowg.ragebot_weapons_paused
        and phowg:ragebot_weapons_paused(tool)
        and not (
            preparation
            and Data.RagebotIdle == preparation
            and phowg:ragebot_idle_valid(preparation)
            and phowg:is_ragebot_gun_selected(tool)
        )
    then
        return false
    end
    if not phowg:tool_equip_ready(tool) then
        return false
    end
    local reload = tool:FindFirstChild('Reloading') or tool:FindFirstChild('Reload')
    if
        phowg:local_gun_reloading(character)
        or reload and reload:IsA('BoolValue') and reload.Value
        or phowg:reload_pending(character)
    then
        return false
    end
    if reloadJob and Data.LoadoutReloadJob ~= reloadJob or not reloadJob and Data.LoadoutReloadJob then
        return false
    end
    local ammoBefore = tool:FindFirstChild('Ammo')
    local before = ammoBefore and ammoBefore.Value
    if phowg.sync_native_reload_owner then
        phowg:sync_native_reload_owner(true)
    end
    local selection = { Tool = tool, Character = character }
    Data.GunReloadSelection = selection
    local ok, sent = pcall(function()
        if not phowg:request_equipment('reload', tool, 'last', reloadJob) then
            return false
        end
        if tool.Parent ~= character or LocalPlayer.Character ~= character then
            return false
        end
        remote:FireServer('Reload', tool)
        Data.GunReloadPending = { Tool = tool, Character = character, Before = before, Until = tick() + 0.75 }
        if phowg.loadout_ammo_purchase_allowed then
            phowg:loadout_ammo_purchase_allowed()
        end
        if phowg.queue_loadout_ammo_check then
            phowg:queue_loadout_ammo_check(character)
        end
        if phowg.queue_auto_demand then
            phowg:queue_auto_demand('Ammo')
        end
        return true
    end)
    if Data.GunReloadSelection == selection then
        Data.GunReloadSelection = nil
    end
    if not ok or sent ~= true then
        phowg:release_equipment('reload', tool)
    end
    return ok and sent == true
end
function equip(Tool, reloadJob)
    if localactionblocked() then
        return
    end
    if not Tool or not istoolvalid(Tool) or not LocalPlayer.Character then
        return false
    end
    if phowg.ragebot_weapons_paused and phowg:ragebot_weapons_paused(Tool) then
        return false
    end
    if not phowg:tool_equip_ready(Tool) then
        return false
    end
    if reloadJob and Data.LoadoutReloadJob ~= reloadJob then
        return false
    end
    if not reloadJob and Data.LoadoutReloadJob then
        return false
    end
    if Tool.Parent == LocalPlayer.Character then
        return false
    end
    local preserve = phowg.china_hack_mode and phowg:china_hack_mode() and phowg:is_gun_weapon(Tool.Name)
        or phowg:is_ragebot_gun_selected(Tool)
            and phowg.support_multi_selected
            and phowg:support_multi_selected(Data.CurrentActionTarget)
    local ok =
        phowg:request_equipment(reloadJob and 'loadout' or 'equip', Tool, preserve and 'equip' or 'exclusive', reloadJob)
    if ok then
        phowg:stop_gun_fire()
    end
    return ok
end
function equiptoolgentle(Tool)
    if not Tool or not istoolvalid(Tool) or not LocalPlayer.Character then
        return false
    end
    if phowg.ragebot_weapons_paused and phowg:ragebot_weapons_paused(Tool) then
        return false
    end
    if Tool.Parent == LocalPlayer.Character then
        return true
    end
    return phowg:request_equipment('equip', Tool, 'equip')
end
function removemyhead()
    if not LocalPlayer.Character then
        return
    end
    local Head = LocalPlayer.Character:FindFirstChild('Head')
    if Head then
        Head:Destroy()
    end
end
function getweapontool(WeaponType)
    WeaponType = WeaponType or 'knife'
    local wt = normalizeweaponname(WeaponType)
    if Data.GunWeaponKeys[wt] then
        for _, container in pairs({ LocalPlayer.Character, LocalPlayer:FindFirstChild('Backpack') }) do
            for _, tool in ipairs(container:GetChildren()) do
                if tool:IsA('Tool') and normalizeweaponname(tool.Name) == wt then
                    return tool
                end
            end
        end
        return nil
    end
    if wt == 'combat' or wt == 'knife' then
        local character = LocalPlayer.Character
        for _, tool in ipairs(character and character:GetChildren() or {}) do
            if tool:IsA('Tool') and (wt == 'combat' and tool.Name == 'Combat' or wt == 'knife' and tool.Name:lower():match('knife')) then
                return tool
            end
        end
    end
    if wt == 'combat' then
        return findtoolbyexactname('Combat')
    elseif wt == 'knife' then
        return findtoolbypattern('knife')
    elseif wt == 'bat' then
        return findtoolbypattern('bat')
    elseif wt == 'flamethrower' then
        return findtoolbypattern('flamethrower')
    end
    return findtoolbypattern('knife')
end
function shopitemprice(Item)
    local price = nil
    (function()
        local raw = tostring(Item.Name):match('%$([%d,]+)')
        if raw then
            local digits = string.gsub(raw, ',', '')
            price = tonumber(digits)
        end
    end)()
    return price
end
do
    local index
    local function disconnect(connections)
        for _, connection in pairs(connections) do
            connection:Disconnect()
        end
        table.clear(connections)
    end
    local function key(value)
        local text = tostring(value or '')
        text = text:match('%[([^%]]+)%]') or text
        return normalizeweaponname(text:gsub('%$[%d,%.]+', ''))
    end
    local function invalidate(record)
        table.clear(index.Results)
        local bucket = record and index.Buckets[record.Key]
        if bucket then
            bucket.Dirty = true
        end
    end
    local function refresh(record, excluded)
        local item = record.Item
        local name = key(item.Name)
        if record.Key ~= name then
            local previous = index.Buckets[record.Key]
            if previous then
                previous.Items[record] = nil
                previous.Dirty = true
                if not next(previous.Items) then
                    index.Buckets[record.Key] = nil
                end
            end
            record.Key = name
            local bucket = index.Buckets[name]
            if not bucket then
                bucket = { Items = {}, Dirty = true }
                index.Buckets[name] = bucket
            end
            bucket.Items[record] = true
        end
        local head = item:FindFirstChild('Head')
        if head == excluded then
            head = nil
        end
        local detector = item:FindFirstChildOfClass('ClickDetector') or item:FindFirstChild('ClickDetector')
        if detector == excluded then
            detector = nil
        end
        if not head or not detector then
            for _, child in ipairs(item:GetChildren()) do
                if child ~= excluded then
                    if not head and child:IsA('BasePart') then
                        head = child
                    end
                    if not detector and (child:IsA('ClickDetector') or child.Name == 'ClickDetector') then
                        detector = child
                    end
                end
            end
        end
        record.Head, record.Detector, record.Price = head, detector, shopitemprice(item) or math.huge
        record.Ammo = name:find('ammo', 1, true) ~= nil
        invalidate(record)
    end
    local function watch_child(record, child)
        if
            record.Children[child]
            or not (
                child:IsA('BasePart')
                or child:IsA('ClickDetector')
                or child.Name == 'Head'
                or child.Name == 'ClickDetector'
            )
        then
            return
        end
        record.Children[child] = connectshared(child:GetPropertyChangedSignal('Name'), function()
            refresh(record)
        end, child, 'shop index/part name', 0, 'property/Name', child)
    end
    local function remove(record)
        disconnect(record.Connections)
        disconnect(record.Children)
        local bucket = index.Buckets[record.Key]
        if bucket then
            bucket.Items[record] = nil
            bucket.Dirty = true
            if not next(bucket.Items) then
                index.Buckets[record.Key] = nil
            end
        end
        index.Items[record.Item] = nil
        invalidate(record)
    end
    local function observe(item)
        if index.Items[item] then
            return
        end
        index.Sequence += 1
        local record = { Item = item, Key = '', Connections = {}, Children = {}, Sequence = index.Sequence }
        index.Items[item] = record
        record.Connections.Name = connectshared(item:GetPropertyChangedSignal('Name'), function()
            refresh(record)
        end, item, 'shop index/item name', 0, 'property/Name', item)
        for _, child in ipairs(item:GetChildren()) do
            watch_child(record, child)
        end
        refresh(record)
    end
    function phowg:clear_shop_index()
        if not index then
            return
        end
        disconnect(index.Connections)
        for _, record in pairs(index.Items) do
            disconnect(record.Connections)
            disconnect(record.Children)
        end
        index = nil
        Data.ShopIndex = nil
    end
    local function resolve()
        local ignored = Workspace:FindFirstChild('Ignored')
        local shop = ignored and ignored:FindFirstChild('Shop')
        if index and index.Shop == shop then
            return index
        end
        phowg:clear_shop_index()
        if not shop then
            return
        end
        index = { Shop = shop, Items = {}, Buckets = {}, Results = {}, Connections = {}, Sequence = 0 }
        Data.ShopIndex = index
        index.Connections.Added = connectshared(shop.DescendantAdded, function(object)
            if object.Parent == shop then
                observe(object)
            else
                local record = index.Items[object.Parent]
                if record then
                    watch_child(record, object)
                    refresh(record)
                end
            end
        end, shop, 'shop index/added', 0, 'event/DescendantAdded', shop)
        index.Connections.Removing = connectshared(shop.DescendantRemoving, function(object)
            local record = index.Items[object]
            if record then
                remove(record)
            else
                record = index.Items[object.Parent]
                if record then
                    local connection = record.Children[object]
                    if connection then
                        connection:Disconnect()
                        record.Children[object] = nil
                    end
                    refresh(record, object)
                end
            end
        end, shop, 'shop index/removing', 0, 'event/DescendantRemoving', shop)
        for _, item in ipairs(shop:GetChildren()) do
            observe(item)
        end
        return index
    end
    local function valid(record)
        return record
            and record.Item.Parent == index.Shop
            and record.Head
            and record.Head.Parent == record.Item
            and record.Detector
            and record.Detector.Parent == record.Item
    end
    local function cheapest(bucket)
        if not bucket then
            return
        end
        if not bucket.Dirty and valid(bucket.Best) then
            return bucket.Best
        end
        local best
        for record in pairs(bucket.Items) do
            if
                valid(record)
                and (
                    not best
                    or record.Price < best.Price
                    or record.Price == best.Price and record.Sequence < best.Sequence
                )
            then
                best = record
            end
        end
        bucket.Best, bucket.Dirty = best, false
        return best
    end
    function phowg:cheapest_shop_item(query, ammoOnly)
        if not resolve() then
            return nil
        end
        local wanted = key(query)
        if wanted == '' then
            return nil
        end
        local wantAmmo = ammoOnly or wanted:find('ammo', 1, true) ~= nil
        if ammoOnly and not wanted:find('ammo', 1, true) then
            wanted ..= 'ammo'
        end
        local resultKey = wanted .. (wantAmmo and ':ammo' or ':item')
        local best = index.Results[resultKey]
        if best ~= nil then
            if best == false then
                return nil
            end
            if valid(best) then
                return best.Item, best.Head, best.Detector
            end
            index.Results[resultKey] = nil
        end
        best = cheapest(index.Buckets[wanted])
        if best and best.Ammo ~= wantAmmo then
            best = nil
        end
        if not best then
            for name, bucket in pairs(index.Buckets) do
                if name:find(wanted, 1, true) and (name:find('ammo', 1, true) ~= nil) == wantAmmo then
                    local candidate = cheapest(bucket)
                    if
                        candidate
                        and (
                            not best
                            or candidate.Price < best.Price
                            or candidate.Price == best.Price and candidate.Sequence < best.Sequence
                        )
                    then
                        best = candidate
                    end
                end
            end
        end
        index.Results[resultKey] = best or false
        if best then
            return best.Item, best.Head, best.Detector
        end
        return nil
    end
    phowg:register_cleanup('shop index', function(scope)
        if not scope then
            phowg:clear_shop_index()
        end
    end)
    resolve()
end
function findshopitem(Query)
    return phowg:cheapest_shop_item(Query, false)
end
function getshopiteminfo(ShopItem)
    if not ShopItem then
        return 'Item', ''
    end
    local Name = ShopItem.Name
    local Price = ''
    for _, Desc in ipairs(ShopItem:GetDescendants()) do
        if Desc:IsA('TextLabel') and Desc.Text and Desc.Text:find('%$') then
            local p = Desc.Text:match('%$%d+')
            if p then
                Price = p
                break
            end
        end
    end
    if #Price == 0 then
        local FoundPrice = Name:match('%$%d+')
        if FoundPrice then
            Price = FoundPrice
        end
    end
    Name = Name:gsub('%[', ''):gsub('%]', '')
    Name = Name:gsub('%s*%-%s*%$%d+', ''):gsub('%s*%$%d+', '')
    Name = Name:match('^%s*(.-)%s*$') or Name
    if #Name == 0 then
        Name = 'Item'
    end
    return Name, Price
end
function counttoolsbypattern(Pattern)
    local n = 0
    local pl = string.gsub(string.lower(tostring(Pattern or '')), '[%[%]%s%-]', '')
    local bp = LocalPlayer:FindFirstChild('Backpack')
    if bp then
        for _, Tool in ipairs(bp:GetChildren()) do
            if
                Tool:IsA('Tool') and string.find(string.gsub(string.lower(Tool.Name), '[%[%]%s%-]', ''), pl, 1, true)
            then
                n = n + 1
            end
        end
    end
    local Character = LocalPlayer.Character
    if Character then
        for _, Tool in ipairs(Character:GetChildren()) do
            if
                Tool:IsA('Tool') and string.find(string.gsub(string.lower(Tool.Name), '[%[%]%s%-]', ''), pl, 1, true)
            then
                n = n + 1
            end
        end
    end
    return n
end
function hookmoneywatch()
    if Data['MoneyConns'] then
        for _, c in pairs(Data['MoneyConns']) do
            c:Disconnect()
        end
    end
    Data['MoneyConns'] = {}
    local function hookcurrency(cur)
        Data['money'] = cur.Value
        local c = connectshared(cur:GetPropertyChangedSignal('Value'), function()
            local before = Data['money'] or 0
            local now = cur.Value
            Data['money'] = now
            if now < before and Data['CustomMoneyLock'] then
                applymoneylock()
                applywalletmoneytext()
            end
        end, cur, 'event/cur:GetPropertyChangedSignal(Value)', 0, 'property/Value', cur)
        table.insert(Data['MoneyConns'], c)
    end
    local function hookfolder(df)
        if not df then
            return
        end
        local cur = df:FindFirstChild('Currency')
        if cur then
            hookcurrency(cur)
        end
        local c2 = connectshared(df.ChildAdded, function(ch)
            if ch.Name == 'Currency' then
                hookcurrency(ch)
            end
        end, df, 'event/df.ChildAdded', 0, 'event/ChildAdded', df)
        table.insert(Data['MoneyConns'], c2)
    end
    local df0 = LocalPlayer:FindFirstChild('DataFolder')
    if df0 then
        hookfolder(df0)
    else
        task.spawn(function()
            local df = LocalPlayer:WaitForChild('DataFolder', 15)
            if df then
                hookfolder(df)
            end
        end)
    end
    local c3 = connectshared(LocalPlayer.ChildAdded, function(ch)
        if ch.Name == 'DataFolder' then
            hookfolder(ch)
        end
    end, LocalPlayer, 'event/LocalPlayer.ChildAdded', 0, 'event/ChildAdded', LocalPlayer)
    table.insert(Data['MoneyConns'], c3)
end
Data.PromoCodeList = { 'ETERNAL', 'MACRO!', 'HALLOWEEN26' }
function phowg:used_promo_codes()
    local folder = LocalPlayer:FindFirstChild('DataFolder')
    local information = folder and folder:FindFirstChild('Information')
    if not information then
        return nil, 'player data is still loading', true
    end
    local value = information and information:FindFirstChild('Codes')
    if not value then
        Data.UsedPromoCodeCache = nil
        return {}
    end
    if not value:IsA('StringValue') then
        return nil, 'saved code history has an unsupported format'
    end
    local raw = value.Value
    local cached = Data.UsedPromoCodeCache
    if cached and cached.Value == value and cached.Raw == raw then
        return cached.Used
    end
    local ok, decoded = true, {}
    if raw:find('%S') then
        ok, decoded = pcall(HttpService.JSONDecode, HttpService, raw)
    end
    if not ok or type(decoded) ~= 'table' then
        return nil, 'saved code data could not be read'
    end
    local used = {}
    for key, flag in pairs(decoded) do
        local code = type(key) == 'string' and (flag == true or flag == 1) and key
            or type(key) == 'number' and type(flag) == 'string' and flag
        if code then
            used[code:upper():match('^%s*(.-)%s*$')] = true
        end
    end
    Data.UsedPromoCodeCache = { Value = value, Raw = raw, Used = used }
    return used
end
function phowg:code_redeem_balance()
    local folder = LocalPlayer:FindFirstChild('DataFolder')
    local currency = folder and folder:FindFirstChild('Currency')
    return tonumber(currency and currency.Value) or 0
end
function phowg:code_redeem_notice(message, automatic)
    Data.CodeRedeemNotices = Data.CodeRedeemNotices or {}
    local last = Data.CodeRedeemNotices[message]
    if automatic and last and tick() - last < 30 then
        return
    end
    Data.CodeRedeemNotices[message] = tick()
    if not Library.Unloaded then
        Library:Notify(message, Library.NotifyDuration or 4)
    end
end
function redeemcodes(stopEarly, automatic, requiredBalance)
    if Data.RedeemingCodes then
        if not automatic then
            phowg:code_redeem_notice('Code redemption is already running.', false)
        end
        return
    end
    local session: { [string]: any } =
        { Confirmed = 0, Unconfirmed = 0, Skipped = 0, Processed = 0, RequiredBalance = requiredBalance }
    Data.CodeRedeemSession, Data.RedeemingCodes = session, true
    local function progress(message, fraction)
        if session.Progress then
            session.Progress:Update(message, fraction)
        else
            phowg:code_redeem_notice(message, automatic)
        end
    end
    task.spawn(function()
        local completed, issue = pcall(function()
            local used, problem, loading = phowg:used_promo_codes()
            if not used and loading then
                phowg:code_redeem_notice('Waiting for player data before redeeming codes.', automatic)
                local deadline = tick() + 5
                repeat
                    if Data.CodeRedeemSession ~= session or Library.Unloaded then
                        return
                    end
                    task.wait(0.1)
                    used, problem, loading = phowg:used_promo_codes()
                until used or not loading or tick() >= deadline
            end
            if Data.CodeRedeemSession ~= session or Library.Unloaded then
                return
            end
            if not used then
                error(problem, 0)
            end
            local pending, cooling = {}, 0
            Data.PromoCodeRetry = Data.PromoCodeRetry or {}
            for _, code in ipairs(Data.PromoCodeList) do
                if used[code] then
                    session.Skipped += 1
                elseif automatic and tick() < (Data.PromoCodeRetry[code] or 0) then
                    cooling += 1
                else
                    pending[#pending + 1] = code
                end
            end
            Data.PromoCodesSpent = session.Skipped == #Data.PromoCodeList
            if #pending == 0 then
                session.Summary = cooling > 0
                        and 'No more available codes to try right now; previous attempts are awaiting confirmation or retry.'
                    or 'No more available codes: all listed codes are already used.'
                return
            end
            session.StartMoney = phowg:code_redeem_balance()
            local ok, handle = pcall(function()
                return Library:NotifyProgress(
                    string.format('Redeeming %d unused codes; skipping %d already used.', #pending, session.Skipped),
                    0,
                    false
                )
            end)
            if ok then
                session.Progress = handle
            end
            for index, code in ipairs(pending) do
                while tick() < (Data.PromoCodeNextSendAt or 0) do
                    if Data.CodeRedeemSession ~= session or Library.Unloaded then
                        return
                    end
                    task.wait(math.min(0.1, Data.PromoCodeNextSendAt - tick()))
                end
                if Data.CodeRedeemSession ~= session or Library.Unloaded then
                    return
                end
                local latest, readProblem = phowg:used_promo_codes()
                if not latest then
                    error(readProblem, 0)
                end
                if latest[code] then
                    session.Skipped += 1
                else
                    progress(
                        string.format(
                            'Using code %s (%d / %d); %d already used.',
                            code,
                            index,
                            #pending,
                            session.Skipped
                        ),
                        (index - 1) / #pending
                    )
                    local before = phowg:code_redeem_balance()
                    local remote = MainEvent
                    if not remote or not remote.Parent then
                        remote = ReplicatedStorage:FindFirstChild('MainEvent')
                        MainEvent = remote
                    end
                    Data.PromoCodeRetry[code] = tick() + 60
                    Data.PromoCodeNextSendAt = tick() + 4.9
                    local sent = remote and pcall(remote.FireServer, remote, 'EnterPromoCode', code)
                    local confirmed = false
                    if sent then
                        local deadline = tick() + 4
                        repeat
                            local current = phowg:used_promo_codes()
                            confirmed = current and current[code] == true or false
                            if confirmed or Data.CodeRedeemSession ~= session or Library.Unloaded then
                                break
                            end
                            task.wait(0.15)
                        until tick() >= deadline
                    end
                    if Data.CodeRedeemSession ~= session or Library.Unloaded then
                        return
                    end
                    if confirmed then
                        session.Confirmed += 1
                        Data.PromoCodeRetry[code] = nil
                        local gain = math.max(0, phowg:code_redeem_balance() - before)
                        phowg:code_redeem_notice(
                            'Redeemed ' .. code .. (gain > 0 and ' (+$' .. tostring(math.floor(gain)) .. ').' or '.'),
                            false
                        )
                    else
                        session.Unconfirmed += 1
                        phowg:code_redeem_notice(
                            sent and 'Code ' .. code .. ' was sent, but redemption was not confirmed.'
                                or 'Could not send code ' .. code .. '.',
                            automatic
                        )
                    end
                end
                session.Processed = index
                progress(
                    string.format(
                        'Codes: %d / %d checked; %d redeemed, %d skipped.',
                        index,
                        #pending,
                        session.Confirmed,
                        session.Skipped
                    ),
                    index / #pending
                )
                if
                    stopEarly
                    and (
                        session.RequiredBalance and phowg:code_redeem_balance() >= session.RequiredBalance
                        or not session.RequiredBalance and phowg:code_redeem_balance() > session.StartMoney
                    )
                then
                    session.StoppedEarly = index < #pending
                    break
                end
            end
        end)
        if Data.CodeRedeemSession ~= session then
            return
        end
        Data.CodeRedeemSession, Data.RedeemingCodes = nil, false
        local latest = phowg:used_promo_codes()
        local remaining = 0
        for _, code in ipairs(Data.PromoCodeList) do
            if not latest or not latest[code] then
                remaining += 1
            end
        end
        Data.PromoCodesSpent = remaining == 0
        local summary
        if not completed then
            summary = 'Code redemption stopped: ' .. tostring(issue)
        elseif session.Summary then
            summary = session.Summary
        elseif remaining == 0 then
            summary = string.format(
                'No more available codes. %d redeemed; %d already used.',
                session.Confirmed,
                session.Skipped
            )
        elseif session.StoppedEarly then
            summary = string.format(
                'Balance increased; %d codes confirmed. %d codes not marked used remain.',
                session.Confirmed,
                remaining
            )
        else
            summary = string.format(
                'Codes finished: %d redeemed, %d skipped, %d unconfirmed; %d not marked used.',
                session.Confirmed,
                session.Skipped,
                session.Unconfirmed,
                remaining
            )
        end
        progress(summary, 1)
        if session.Progress then
            task.delay(4.8, function()
                session.Progress:Complete()
            end)
        end
    end)
end
function trycodesforpurchase(requiredBalance)
    if Data.RedeemingCodes then
        local session = Data.CodeRedeemSession
        if session and requiredBalance then
            session.RequiredBalance = math.max(session.RequiredBalance or 0, requiredBalance)
        end
        return
    end
    if not Data.PromoCodesSpent then
        redeemcodes(true, true, requiredBalance)
    end
end
phowg:register_cleanup('code redemption', function(scope)
    if scope then
        return
    end
    local session = Data.CodeRedeemSession
    Data.CodeRedeemSession, Data.RedeemingCodes = nil, false
    if session and session.Progress then
        session.Progress:Complete()
    end
end)
function canafford(PriceStr, Count)
    local price = tonumber(string.match(tostring(PriceStr or ''), '%d+'))
    if not price then
        return true
    end
    local n = (type(Count) == 'number' and Count >= 1) and math.floor(Count) or 1
    local folder = LocalPlayer:FindFirstChild('DataFolder')
    local currency = folder and folder:FindFirstChild('Currency')
    local balance = tonumber(currency and currency.Value) or Data.money or 0
    return balance >= price * n
end
function setbuyingstatus(label)
    Data['BuyingItem'] = tostring(label or 'item'):gsub('[%[%]{}]', '')
    Data.BuyingArmor = phowg:is_armor_purchase(label)
    if not (rageboton() or punishmentactive()) then
        return
    end
    Data['CurrentStatus'] = 'ragebot: buying ' .. tostring(label or 'item')
end
function clearbuyingstatus(label)
    if Data['BuyingItem'] == tostring(label or ''):gsub('[%[%]{}]', '') then
        Data['BuyingItem'], Data.BuyingArmor = nil, nil
    end
    if Data['CurrentStatus'] == 'ragebot: buying ' .. tostring(label or '') then
        Data['CurrentStatus'] = 'Idle'
    end
end
function phowg:try_equip_purchased_knife(tool)
    local pending = Data.PurchasedKnifeEquip
    if not pending then
        return
    end
    local batch = pending.Batch
    if
        Library.Unloaded
        or Data.IsRespawning
        or LocalPlayer.Character ~= pending.Character
        or batch.Cancelled
        or not (Toggles.loadout_equip_knife and Toggles.loadout_equip_knife.Value)
        or batch.Done and tick() > (pending.Deadline or 0)
    then
        Data.PurchasedKnifeEquip = nil
        return
    end
    if
        tool
        and tool:IsA('Tool')
        and normalizeweaponname(tool.Name) == 'knife'
        and tool ~= pending.Before
        and istoolvalid(tool)
    then
        pending.Tool = tool
    end
    local knife = pending.Tool
    if
        not batch.Done
        or Data.Buying
        or Data.Sorting
        or Data.LoadoutReloadJob
        or localactionblocked()
        or not knife
        or not istoolvalid(knife)
    then
        return
    end
    if knife.Parent ~= pending.Character then
        equip(knife)
    end
    if knife.Parent == pending.Character then
        Data.PurchasedKnifeEquip = nil
        Data.InventoryEquip = nil
    end
end
function phowg:purchase_void_return_valid(state)
    return state ~= nil
        and Data.PurchaseVoidReturn == state
        and state.Character == LocalPlayer.Character
        and not Library.Unloaded
        and not Data.IsRespawning
        and not Data.Buying
        and not localactionblocked()
        and tick() < state.Until
        and (not state.Manual or Data.ManualVoid == true and Data.VoidActive == true)
        and (not state.SourceVoidState or phowg:ragebot_void_move_valid(state.SourceVoidState))
        and (not state.PurchaseHiding or Data.VoidActive == true)
end
function phowg:void_spam_out_active()
    local state = Data.ManualVoidSpam
    return state ~= nil and state.Character == LocalPlayer.Character and not state.Void
        and Data.ManualVoid == true and Data.VoidActive == true
        and Toggles.void_spam ~= nil and Toggles.void_spam.Value == true
end
function phowg:manual_void_phase()
    if not Data.ManualVoid or not (Toggles.void_spam and Toggles.void_spam.Value) then
        Data.ManualVoidSpam = nil
        return true
    end
    local now = tick()
    local state = Data.ManualVoidSpam
    if not state or state.Character ~= LocalPlayer.Character then
        state = { Character = LocalPlayer.Character, Void = true,
            Until = now + phowg:visual_number('void_spam_in_time', 0.5, 0.02, 5) }
        Data.ManualVoidSpam = state
    elseif now >= state.Until then
        state.Void = not state.Void
        state.Until = now + phowg:visual_number(state.Void and 'void_spam_in_time' or 'void_spam_out_time',
            state.Void and 0.5 or 0.2, 0.02, 5)
        releasemovement(state.Void and 'VoidSpamOut' or 'Void')
    end
    return state.Void
end
function phowg:pending_server_movement()
    local best, now = nil, tick()
    for _, entry in ipairs(Data.CSync.Queue) do
        if entry.character == LocalPlayer.Character and now - entry.t >= 0 and now - entry.t <= 0.3
            and validmovetohold(entry.hold)
            and phowg.explosive_movement_active and phowg:explosive_movement_active(entry.tag)
            and (not best or entry.prio < best.prio) then
            best = entry
        end
    end
    return best
end
function phowg:clear_void_presentation()
    local tag = Data.AppliedServerTag
    phowg:cancel_c_frame_movement({ Void = true, VoidTwitch = true, VoidSpamOut = true, PurchaseVoidReturn = true, VoidExit = true })
    Data.VoidExitRevision = (Data.VoidExitRevision or 0) + 1
    Data.PurchaseVoidReturn, Data.ManualVoidSpam = nil, nil
    releasemovement('VoidSpamOut')
    releasemovement('Void')
    releasemovement('VoidTwitch')
    releasemovement('PurchaseVoidReturn')
    if tag == 'Void' or tag == 'VoidTwitch' or tag == 'PurchaseVoidReturn' or tag == 'Buy' and not Data.Buying then
        Data.AppliedServerCF, Data.AppliedServerAt, Data.AppliedServerTag, Data.AppliedServerCharacter =
            nil, nil, nil, nil
        Data.MoveToActive, Data.MoveToTargetCF, Data.DisplayCF = false, nil, nil
        hidevisualizer()
    end
end
function phowg:purchase_hiding_return(saved)
    return saved ~= nil
        and saved.VoidHiding == true
        and saved.Character == LocalPlayer.Character
        and Data.VoidActive == true
        and (not saved.ManualVoid or Data.ManualVoid == true)
end
function phowg:resume_active_movement(saved, purchaseReturn)
    if Data.IsRespawning or Library.Unloaded or localactionblocked() or Data.RPGMoveActive or Data.Buying then
        return
    end
    local idle = phowg:ragebot_idle_hiding(Data.RagebotIdle)
    local voidPriority = idle or Data.HideVoid and not Data.ManualVoid
    voidPriority = voidPriority and Data.PRIO.KNIFE or Data.PRIO.IDLE
    local ceiling = (idle or Data.VoidActive) and voidPriority or math.huge
    local nextMovement = phowg:pending_server_movement()
    for _, hold in pairs(Data.MoveToHolds or {}) do
        if hold.Tag ~= 'Hold:LoadoutShop' and (not purchaseReturn or hold.Tag ~= 'Hold:LoadoutReload')
            and validmovetohold(hold) and (not nextMovement or hold.Priority < nextMovement.prio) then
            nextMovement = { cf = hold.CFrame, prio = hold.Priority, tag = hold.Tag, hold = hold, arrive = hold.Arrive }
        end
    end
    if nextMovement and nextMovement.tag ~= 'Buy' and nextMovement.prio < ceiling then
        set_server_cframe(nextMovement.cf, nil, nextMovement.prio, nextMovement.tag, false, nextMovement.hold, nextMovement.arrive)
        return
    end
    if idle then
        set_server_cframe(getvoidcframe(), nil, Data.PRIO.KNIFE, 'RagebotIdle')
        return
    end
    local returnVoid = purchaseReturn and phowg:purchase_hiding_return(saved)
        or purchaseReturn and saved and saved.SourceVoidState and phowg:ragebot_void_move_valid(saved.SourceVoidState)
        or not purchaseReturn
            and saved
            and saved.ReturnVoid
            and (saved.Tag ~= 'RagebotVoid' or phowg:ragebot_void_move_valid(saved.SourceVoidState))
            and saved.Character == LocalPlayer.Character
            and (not saved.ManualVoid or Data.VoidActive and Data.ManualVoid)
    if returnVoid or Data.VoidActive then
        local destination = returnVoid and saved.CFrame or getvoidcframe()
        local tag, priority = 'Void', voidPriority
        if returnVoid and saved.SourceVoidState and phowg:ragebot_void_move_valid(saved.SourceVoidState) then
            tag, priority = 'RagebotVoid', Data.PRIO.KNIFE
        elseif phowg:void_spam_out_active() then
            tag = 'VoidSpamOut'
            destination = Local_Data.ClientPos or Data.CSyncTable[1]
        end
        Data.PurchaseVoidReturn = nil
        releasemovement('PurchaseVoidReturn')
        set_server_cframe(destination, nil, priority, tag)
        return
    end
    local best
    for _, hold in pairs(Data.MoveToHolds or {}) do
        if
            (not purchaseReturn or hold.Tag ~= 'Hold:LoadoutReload')
            and validmovetohold(hold)
            and (not best or hold.Priority < best.Priority)
        then
            best = hold
        end
    end
    if best then
        set_server_cframe(best.CFrame, nil, best.Priority, best.Tag, false, best, best.Arrive)
    elseif
        saved
        and saved.Character == LocalPlayer.Character
        and saved.Tag ~= 'Buy'
        and saved.Tag ~= 'DeflectRPG'
        and saved.Tag ~= 'DeflectRPGReturn'
        and saved.Tag ~= 'Hold:LoadoutShop'
        and (not purchaseReturn or saved.Tag ~= 'Void' and saved.Tag ~= 'VoidTwitch' and saved.Tag ~= 'RagebotVoid' and saved.Tag ~= 'ReloadVoid' and saved.Tag ~= 'PurchaseVoidReturn' and saved.Tag ~= 'Hold:LoadoutReload')
        and typeof(saved.CFrame) == 'CFrame'
        and phowg.explosive_movement_active
        and phowg:explosive_movement_active(saved.Tag)
    then
        set_server_cframe(saved.CFrame, nil, saved.Priority or Data.PRIO.DESYNC, saved.Tag)
    end
end
function phowg:capture_active_movement()
    if Data.VoidActive then
        local cf = (
            Data.AppliedServerCharacter == LocalPlayer.Character
            and (Data.AppliedServerTag == 'Void' or Data.AppliedServerTag == 'VoidTwitch')
            and Data.AppliedServerCF
        ) or getvoidcframe()
        return {
            Character = LocalPlayer.Character,
            CFrame = cf,
            Tag = 'Void',
            Priority = Data.PRIO.IDLE,
            ReturnVoid = true,
            VoidHiding = true,
            ManualVoid = Data.ManualVoid == true,
        }
    end
    if Data.AppliedServerCharacter ~= LocalPlayer.Character then
        return nil
    end
    local tag = Data.AppliedServerTag
    local override = Data.MovementOverrides and Data.MovementOverrides[tag]
    return {
        Character = LocalPlayer.Character,
        CFrame = Data.AppliedServerCF,
        Tag = tag,
        Priority = override and override.prio
            or (tag == 'Desync' and Data.PRIO.DESYNC or tag == 'Underground' and Data.PRIO.IDLE or Data.PRIO.KNIFE),
        ReturnVoid = tag == 'RagebotVoid' and phowg:ragebot_void_move_valid(Data.RagebotVoidSpam)
            or tag == 'ReloadVoid' and reloadvoidactive()
            or tag == 'PurchaseVoidReturn' and phowg:purchase_void_return_valid(Data.PurchaseVoidReturn),
        ManualVoid = Data.ManualVoid == true,
        SourceVoidState = tag == 'RagebotVoid' and Data.RagebotVoidSpam
            or tag == 'PurchaseVoidReturn' and Data.PurchaseVoidReturn and Data.PurchaseVoidReturn.SourceVoidState
            or nil,
    }
end
function phowg:finish_purchases(batch, cancelled)
    if not batch then
        return
    end
    batch.Cancelled = cancelled == true
    batch.Done = true
    for _, pendingRequest in pairs(batch.Requests) do
        if not pendingRequest.Done then
            pendingRequest.Done, pendingRequest.Success = true, false
        end
    end
    if Data.PurchaseBatch ~= batch then
        return
    end
    Data.PurchaseBatch = nil
    Data.Buying, Data.BuyingArmor, Data.BuyingItem, Data.BuyingSupportTarget = false, nil, nil, nil
    Data.BuyTargetCF, Data.BuyPriority = nil, nil
    releasemovement('Buy')
    if Data.CSync and Data.CSync.Queue then
        for index = #Data.CSync.Queue, 1, -1 do
            if Data.CSync.Queue[index].tag == 'Buy' then
                table.remove(Data.CSync.Queue, index)
            end
        end
        if not Data.RPGMoveActive then
            Data.CSync.PendingCF = nil
        end
    end
    stopmovetohold('LoadoutShop')
    if not batch.Cancelled then
        for _, pendingRequest in pairs(batch.Requests) do
            if pendingRequest.Success and phowg:is_armor_purchase(pendingRequest.Query) then
                Data.LastArmorPurchaseAt = tick()
                break
            end
        end
    end
    phowg:resume_active_movement(batch.ReturnMovement, true)
    if not phowg:pending_server_movement()
        and (Data.AppliedServerTag == 'Buy' or Data.AppliedServerTag == 'Hold:LoadoutShop') then
        Data.AppliedServerCF, Data.AppliedServerAt, Data.AppliedServerTag, Data.AppliedServerCharacter, Data.AppliedServerHold =
            nil, nil, nil, nil, nil
        Data.MoveToActive, Data.MoveToTargetCF, Data.DisplayCF, Data.DisplayAt = false, nil, nil, nil
        hidevisualizer()
    end

    if Data.CurrentStatus and Data.CurrentStatus:sub(1, 16) == 'ragebot: buying ' then
        Data.CurrentStatus = 'Idle'
    end
    local pending = Data.PurchasedKnifeEquip
    if pending and pending.Batch == batch then
        pending.Deadline = tick() + 5
        phowg:try_equip_purchased_knife()
    end
end
function phowg:explosive_purchase_limit(query)
    local name = tostring(query or ''):lower():gsub('[%[%]%s%-]', ''):gsub('%$%d+', '')
    if name:find('ammo', 1, true) or name:find('launcher', 1, true) then
        return nil
    end
    if name:find('molotov', 1, true) then
        return 'molotov', 3
    end
    if name:find('grenade', 1, true) then
        return 'grenade', 10
    end
    return nil
end
function phowg:explosive_purchase_remaining(query)
    local name, limit = phowg:explosive_purchase_limit(query)
    if not name then
        return nil
    end
    local count, seen = 0, {}
    for _, container in pairs({ LocalPlayer.Character, LocalPlayer:FindFirstChildOfClass('Backpack') }) do
        if container then
            for _, tool in ipairs(container:GetChildren()) do
                if tool:IsA('Tool') and not seen[tool] and normalizeweaponname(tool.Name) == name then
                    count += 1
                    seen[tool] = true
                end
            end
        end
    end
    return math.max(0, limit - count), count, limit
end

function phowg:queue_purchase(batch, item)
    if type(item) ~= 'table' or type(item.Query) ~= 'string' or item.Query == '' then
        return nil
    end
    local remaining = phowg:explosive_purchase_remaining(item.Query)
    if remaining and remaining <= 0 then
        return nil
    end
    if remaining then
        item = table.clone(item)
        item.Count = math.min(math.max(1, tonumber(item.Count) or 1), remaining)
    end
    local key = item.Query:lower():gsub('[%[%]%s%-]', '') .. ':' .. tostring(item.SupportTarget or '')
    local pending = batch.Requests[key]
    if pending and not pending.Done then
        if not pending.Started then
            pending.Count = math.max(tonumber(pending.Count) or 1, tonumber(item.Count) or 1)
        end
        return pending
    end
    local pendingRequest: { [string]: any } = table.clone(item)
    pendingRequest.Key, pendingRequest.Done, pendingRequest.Success = key, false, false
    batch.Requests[key] = pendingRequest
    batch.Queue[#batch.Queue + 1] = pendingRequest
    return pendingRequest
end
function phowg:purchase_items(items, continuation)
    if Data.SafeMode then
        return false
    end
    local batch = Data.PurchaseBatch
    if batch and (batch.Done or batch.Cancelled or batch.Character ~= LocalPlayer.Character) then
        phowg:finish_purchases(batch, true)
        batch = nil
    end
    local owner = not batch
    if owner then
        if Data.Buying or Data.IsRespawning or not LocalPlayer.Character or localactionblocked() then
            return false
        end
        local returnMovement = phowg:capture_active_movement()
        Data.PurchaseVoidReturn = nil
        releasemovement('PurchaseVoidReturn')
        stopmovetohold('LoadoutShop')
        batch = {
            Character = LocalPlayer.Character,
            Owner = coroutine.running(),
            Queue = {},
            Requests = {},
            Producers = {},
            Done = false,
            Cancelled = false,
            ReturnMovement = returnMovement,
        }
        Data.PurchaseBatch = batch
    end
    local first
    for _, item in ipairs(items or {}) do
        local pendingRequest = phowg:queue_purchase(batch, item)
        if not first then
            first = pendingRequest
        end
    end
    if continuation then
        batch.Producers[#batch.Producers + 1] = continuation
    end
    if not owner then
        if batch.Owner == coroutine.running() then
            return false
        end
        repeat
            RunService.Heartbeat:Wait()
        until batch.Done or batch.Cancelled or LocalPlayer.Character ~= batch.Character or Library.Unloaded
        return first and first.Success == true or false
    end
    local ok, problem = pcall(function()
        while
            not batch.Cancelled
            and Data.PurchaseBatch == batch
            and LocalPlayer.Character == batch.Character
            and not Data.IsRespawning
            and not Library.Unloaded
        do
            if #batch.Queue == 0 then
                for index = #batch.Producers, 1, -1 do
                    local produced, item = pcall(batch.Producers[index])
                    if produced and item then
                        phowg:queue_purchase(batch, item)
                    else
                        table.remove(batch.Producers, index)
                        if not produced then
                            error(item)
                        end
                    end
                end
                if #batch.Queue == 0 then
                    break
                end
            end
            local best = 1
            for index = 2, #batch.Queue do
                if (batch.Queue[index].Prio or Data.PRIO.LOADOUT) < (batch.Queue[best].Prio or Data.PRIO.LOADOUT) then
                    best = index
                end
            end
            local pendingRequest = table.remove(batch.Queue, best)
            batch.ActiveRequest = pendingRequest
            pendingRequest.Started = true
            local knifePurchase = tostring(pendingRequest.Query):lower():gsub('[%[%]%s%-]', ''):gsub('%$%d+', '')
                == 'knife'
            if knifePurchase and Toggles.loadout_equip_knife and Toggles.loadout_equip_knife.Value then
                Data.PurchasedKnifeEquip =
                    { Batch = batch, Character = batch.Character, Before = phowg:loadout_tool('knife') }
            end
            pendingRequest.Success = phowg:perform_purchase(
                pendingRequest.Query,
                pendingRequest.Prio,
                pendingRequest.Count,
                pendingRequest.Quiet,
                pendingRequest.SupportTarget,
                pendingRequest.ShouldContinue,
                batch
            ) == true
            pendingRequest.Done = true
            batch.ActiveRequest = nil
            if knifePurchase and Data.PurchasedKnifeEquip and Data.PurchasedKnifeEquip.Batch == batch then
                phowg:try_equip_purchased_knife(phowg:loadout_tool('knife'))
            end
        end
    end)
    phowg:finish_purchases(
        batch,
        not ok
            or batch.Cancelled
            or LocalPlayer.Character ~= batch.Character
            or Data.IsRespawning == true
            or Library.Unloaded == true
    )
    if not ok then
        warn('[Phowg] purchase: ' .. tostring(problem))
    end
    return first and first.Success == true or false
end
function purchase_item(Query, Prio, Count, Quiet, SupportTarget, ShouldContinue)
    return phowg:purchase_items({
        {
            Query = Query,
            Prio = Prio,
            Count = Count,
            Quiet = Quiet,
            SupportTarget = SupportTarget,
            ShouldContinue = ShouldContinue,
        },
    })
end
function phowg:maintain_purchase_movement(batch)
    if
        not batch
        or Data.PurchaseBatch ~= batch
        or batch.Cancelled
        or batch.Done
        or batch.Character ~= LocalPlayer.Character
        or Data.IsRespawning
        or Library.Unloaded
        or localactionblocked()
        or Data.RPGMoveActive
        or not Data.Buying
    then
        return
    end
    if typeof(Data.BuyTargetCF) == 'CFrame' then
        set_server_cframe(Data.BuyTargetCF, nil, Data.BuyPriority or Data.PRIO.LOADOUT, 'Buy')
    end
end
function phowg:wait_for_purchase_funds(price, count, batch, supportTarget, shouldContinue)
    local function valid()
        return Data.PurchaseBatch == batch
            and not batch.Cancelled
            and not batch.Done
            and LocalPlayer.Character == batch.Character
            and not Data.IsRespawning
            and not Library.Unloaded
            and not Data.SharedSignalsClosed
            and not localactionblocked()
            and (not shouldContinue or shouldContinue())
            and (not supportTarget or Data.PunishmentTargets and Data.PunishmentTargets[supportTarget] ~= nil)
    end
    if not valid() then
        return false
    end
    local unit = tonumber(tostring(price or ''):match('%d+'))
    if not unit or canafford(price, count) then
        return true
    end
    trycodesforpurchase(unit * count)
    local settleUntil = tick() + 2
    repeat
        if not valid() then
            return false
        end
        if canafford(price, count) then
            return true
        end
        if Data.RedeemingCodes then
            settleUntil = tick() + 2
        end
        if not Data.RedeemingCodes and tick() >= settleUntil then
            break
        end
        task.wait(0.1)
    until false
    return false
end
function phowg:perform_purchase(Query, Prio, Count, Quiet, SupportTarget, ShouldContinue, batch)
    if Data.PurchaseBatch ~= batch or batch.Cancelled or LocalPlayer.Character ~= batch.Character then
        return false
    end
    if phowg:is_armor_purchase(Query) then
        if phowg:support_combat_pending() then
            return false
        end
        local requested = ShouldContinue
        ShouldContinue = function()
            return not phowg:support_combat_pending() and (not requested or requested())
        end
    end
    if ShouldContinue and not ShouldContinue() then
        return false
    end
    if SupportTarget and not (Data['PunishmentTargets'] and Data['PunishmentTargets'][SupportTarget]) then
        return
    end
    do
        local failKey = string.lower(tostring(Query or ''))
        local lastFail = Data['BuyFailAt'] and Data['BuyFailAt'][failKey] or 0
        if tick() - lastFail < 3 then
            return
        end
    end
    if
        punishmentactive()
        and Prio ~= Data['PRIO'].ARMOR
        and Prio ~= Data['PRIO'].FIREARMOR
        and Prio ~= Data['PRIO'].KNIFE
        and Prio ~= Data['PRIO'].PUNISH
        and Prio ~= Data['PRIO'].STOMP
        and Prio ~= Data['PRIO'].ARREST
        and Prio ~= Data['PRIO'].AMMO
    then
        return
    end
    do
        local ql0 = string.lower(tostring(Query or ''))
        local isHealBuy = (Prio == Data['PRIO'].HEAL) or (string.find(ql0, 'burger', 1, true) ~= nil)
        if isHealBuy then
            if punishmentactive() then
                return
            end
            if Data['CSync'] and Data['CSync'].Queue then
                for _, e in ipairs(Data['CSync'].Queue) do
                    if e.tag == 'Combat' then
                        return
                    end
                end
            end
            if tick() - (Data['LastCombatMoveAt'] or 0) < 1.0 then
                return
            end
            if rageboton() and Data['CurrentActionTarget'] ~= nil then
                return
            end
            local okAct, hasAct = pcall(function()
                return hasactionabletargetuncached(true)
            end)
            if okAct and hasAct and rageboton() then
                return
            end
        end
    end
    local cappedRemaining = phowg:explosive_purchase_remaining(Query)
    if cappedRemaining and cappedRemaining <= 0 then
        return true
    end
    local rawCount = Count
    Count = (type(Count) == 'number' and Count >= 1) and math.floor(Count) or 1
    if cappedRemaining then
        Count = math.min(Count, cappedRemaining)
    end
    local waitStart = tick()
    while Data['IsRespawning'] and tick() - waitStart < 4 do
        RunService.Heartbeat:Wait()
    end
    if Data['IsRespawning'] then
        return
    end
    local _char0 = LocalPlayer.Character
    if _char0 then
        _char0:WaitForChild('FULLY_LOADED_CHAR', 3)
        _char0:WaitForChild('HumanoidRootPart', 5)
        _char0:WaitForChild('Humanoid', 5)
    end
    local char = LocalPlayer.Character
    if not char or char ~= batch.Character or Data.PurchaseBatch ~= batch or batch.Cancelled then
        return false
    end
    local hrp = char:FindFirstChild('HumanoidRootPart')
    local hum = char:FindFirstChildOfClass('Humanoid')
    if not hrp or not hum or hum.Health <= 0 then
        local t0 = tick()
        repeat
            RunService.Heartbeat:Wait()
            hrp = char:FindFirstChild('HumanoidRootPart')
            hum = char:FindFirstChildOfClass('Humanoid')
        until (hrp and hum and hum.Health > 0) or tick() - t0 > 1.5
        if not hrp or not hum or hum.Health <= 0 then
            return
        end
    end
    local ShopItem, Head, ClickDetector = nil, nil, nil
    ShopItem, Head, ClickDetector = phowg:cheapest_shop_item(Query, false)
    if not ShopItem or not Head or not ClickDetector then
        return
    end
    if SupportTarget and not (Data['PunishmentTargets'] and Data['PunishmentTargets'][SupportTarget]) then
        return
    end
    local ItemName, ItemPrice = getshopiteminfo(ShopItem)
    local isAmmo = string.find(string.lower(ItemName .. ' ' .. Query), 'ammo', 1, true) ~= nil
    local availableSlots = phowg:explosive_purchase_remaining(Query)
    if availableSlots and availableSlots <= 0 then
        return true
    end
    if availableSlots then
        Count = math.min(Count, availableSlots)
    end
    if isAmmo and SupportTarget then
        local price = tonumber(ItemPrice:match('%d+'))
        if price and price > 0 then
            Count = math.min(Count, math.max(1, math.floor((Data['money'] or 0) / price)))
        end
    end
    if not canafford(ItemPrice, Count) then
        if not Quiet then
            Library:Notify('you do not have enough money to buy this', Library.NotifyDuration or 3)
        end
        if not phowg:wait_for_purchase_funds(ItemPrice, Count, batch, SupportTarget, ShouldContinue) then
            return false
        end
    end
    if (rawCount == nil or (type(rawCount) == 'number' and rawCount < 1)) and not isAmmo then
        if counttoolsbypattern(Query) > 0 then
            return
        end
    end
    if not phowg:is_armor_purchase(ItemName) then
        phowg:stop_gun_fire()
    end
    setbuyingstatus(ItemName)
    if not Data.RPGMoveActive then
        Data['CSync'].PendingCF = nil
    end
    Data['Buying'] = true
    Data['BuyingSupportTarget'] = SupportTarget
    Data['BuyingSince'] = tick()
    local dataFolder = LocalPlayer:FindFirstChild('DataFolder')
        or (LocalPlayer:WaitForChild('DataFolder', 5) and LocalPlayer:FindFirstChild('DataFolder'))
    local currency = dataFolder and dataFolder:FindFirstChild('Currency')
    local initialCurrency = currency and currency.Value or nil
    local bought = 0
    local currencyDropped = false
    local lastCurrency = initialCurrency
    local initialTools = isAmmo and 0 or counttoolsbypattern(Query)
    local isNadeBuy = type(Query) == 'string' and string.find(string.lower(Query), 'grenade', 1, true) ~= nil
    local StartTime = tick()
    local lastStep = StartTime
    local cappedClickAt, cappedBefore = 0, nil
    local pingSec = 0.08
    pcall(function()
        local p = LocalPlayer:GetNetworkPing()
        if type(p) == 'number' and p == p and p > 0 and p < 10 then
            pingSec = p
        end
    end)
    local pingBonus = math.clamp(pingSec * 4, 0, 5)
    local timeLimit = ((Count > 1 or isNadeBuy) and (2 + Count * 1.2) or 2) + pingBonus
    repeat
        RunService.Heartbeat:Wait()
        if Data.PurchaseBatch ~= batch or batch.Cancelled then
            break
        end
        local remaining, current = phowg:explosive_purchase_remaining(Query)
        if remaining and remaining <= 0 then
            bought = math.min(Count, math.max(0, current - initialTools))
            break
        end
        local now = tick()
        if Data.RPGMoveActive then
            StartTime = StartTime + now - lastStep
        end
        lastStep = now
        Data.BuyingSince = now
        if not Head.Parent or not ClickDetector.Parent then
            break
        end
        if ShouldContinue and not ShouldContinue() then
            break
        end
        if localactionblocked() or LocalPlayer.Character ~= char then
            break
        end
        if SupportTarget and not (Data['PunishmentTargets'] and Data['PunishmentTargets'][SupportTarget]) then
            break
        end
        if Data['IsRespawning'] then
            break
        end
        if not (LocalPlayer.Character and LocalPlayer.Character:FindFirstChild('HumanoidRootPart')) then
            break
        end
        if
            punishmentactive()
            and Prio ~= Data['PRIO'].ARMOR
            and Prio ~= Data['PRIO'].FIREARMOR
            and Prio ~= Data['PRIO'].KNIFE
            and Prio ~= Data['PRIO'].PUNISH
            and Prio ~= Data['PRIO'].STOMP
            and Prio ~= Data['PRIO'].ARREST
            and Prio ~= Data['PRIO'].AMMO
        then
            break
        end
        local styleNow = 'hosted rage'
        if Options.teleport_style and Options.teleport_style.Value then
            styleNow = Options.teleport_style.Value
        end
        local padCF = nil
        if styleNow == 'normal' then
            padCF = CFrame.new(Head.Position)
        else
            padCF = CFrame.new(Head.Position - Vector3.new(0, 10, 0)) * CFrame.Angles(0, 0, math.rad(180))
        end
        Data.BuyTargetCF = padCF
        Data.BuyPriority = Prio or Data.PRIO.LOADOUT
        if not Data.RPGMoveActive then
            phowg:maintain_purchase_movement(batch)
            local canClick = not cappedRemaining
                or not cappedBefore
                or current > cappedBefore
                or now - cappedClickAt >= math.max(0.35, pingSec * 3)
            if fireclickdetector and not localactionblocked() and canClick then
                local slots = phowg:explosive_purchase_remaining(Query)
                if not slots or slots > 0 then
                    fireclickdetector(ClickDetector)
                    cappedBefore, cappedClickAt = current, now
                end
            end
        end
        if currency and lastCurrency and currency.Value < lastCurrency then
            currencyDropped = true
            if isAmmo then
                bought = bought + 1
            end
            lastCurrency = currency.Value
        end
        if not isAmmo then
            if counttoolsbypattern(Query) >= initialTools + Count then
                bought = Count
            elseif Count == 1 and currencyDropped then
                local settle0 = tick()
                while tick() - settle0 < 0.6 do
                    RunService.Heartbeat:Wait()
                    if
                        Data['IsRespawning']
                        or batch.Cancelled
                        or Data.PurchaseBatch ~= batch
                        or LocalPlayer.Character ~= char
                    then
                        break
                    end
                    Data.BuyingSince = tick()
                    phowg:maintain_purchase_movement(batch)
                    if counttoolsbypattern(Query) >= initialTools + Count then
                        break
                    end
                end
                bought = Count
            elseif isNadeBuy then
                bought = math.max(0, counttoolsbypattern(Query) - initialTools)
                if bought >= 1 then
                    lastCurrency = currency and currency.Value or lastCurrency
                end
            elseif Count > 1 and counttoolsbypattern(Query) > initialTools then
                local seen0 = counttoolsbypattern(Query)
                local settle1 = tick()
                while tick() - settle1 < 0.8 do
                    RunService.Heartbeat:Wait()
                    if
                        Data['IsRespawning']
                        or batch.Cancelled
                        or Data.PurchaseBatch ~= batch
                        or LocalPlayer.Character ~= char
                    then
                        break
                    end
                    Data.BuyingSince = tick()
                    phowg:maintain_purchase_movement(batch)
                    if counttoolsbypattern(Query) ~= seen0 then
                        seen0 = counttoolsbypattern(Query)
                        settle1 = tick()
                    end
                end
                bought = math.min(counttoolsbypattern(Query) - initialTools, Count)
            end
        end
    until bought >= Count or tick() - StartTime > timeLimit
    local supportCancelled = SupportTarget
        and not (Data['PunishmentTargets'] and Data['PunishmentTargets'][SupportTarget])
    if bought < Count and not currencyDropped and not supportCancelled then
        Data['BuyFailAt'] = Data['BuyFailAt'] or {}
        Data['BuyFailAt'][string.lower(tostring(Query or ''))] = tick()
    end
    if
        not Quiet
        and not phowg:is_armor_purchase(Query)
        and (bought >= Count or (Count == 1 and (findtoolbypattern(Query:lower()) ~= nil or currencyDropped)))
    then
        (function()
            local PriceStr = ''
            if #ItemPrice > 0 then
                local unit = tonumber(string.match(ItemPrice, '%d+'))
                local n = (Count > 1) and math.min(bought, Count) or 1
                if unit and n > 1 then
                    PriceStr = ' for $' .. tostring(unit * n)
                else
                    PriceStr = ' for ' .. ItemPrice
                end
            end
            local CountStr = (Count > 1 and (tostring(math.min(bought, Count)) .. 'x ')) or ''
            Library:Notify('Purchased ' .. CountStr .. ItemName .. PriceStr, Library.NotifyDuration or 3)
        end)()
    end
    if Data.PurchaseBatch ~= batch or batch.Cancelled then
        return false
    end
    clearbuyingstatus(ItemName)
    Data.BuyingSupportTarget = nil
    if bought >= Count or currencyDropped then
        local nm = string.lower(tostring(ItemName or ''))
        if not string.find(nm, 'armor', 1, true) then
            aftershopbuy()
        end
    end
    return bought >= Count or currencyDropped
end
function buyarmor()
    if phowg:support_combat_pending() then
        return
    end
    if localactionblocked() then
        return
    end
    local char = Local_Parts['Character']
    if not char or char ~= LocalPlayer.Character then
        return
    end
    if Data['IsRespawning'] then
        return
    end
    if tick() - (Data['ArmorLastFire'] or 0) < 1 then
        return
    end
    if not (Toggles and Toggles.auto_armor and Toggles.auto_armor.Value) then
        return
    end
    local val = getarmorvalue()
    if val == nil then
        return
    end
    if Toggles.armor_buy_on_damage and Toggles.armor_buy_on_damage.Value then
        if val > 0 then
            return
        end
    else
        if val >= 100 then
            return
        end
    end
    if Data['Buying'] then
        return
    end
    Data['ArmorLastFire'] = tick()
    return purchase_item('high-medium', Data['PRIO'].ARMOR)
end
function prunenotifytable(Tbl)
    local count = 0
    for _ in pairs(Tbl) do
        count = count + 1
    end
    if count > 50 then
        for k in pairs(Tbl) do
            Tbl[k] = nil
        end
    end
end
function notifystomping(Target)
    if not Target or not Target.Parent then
        return
    end
    local last = Data['StompNotifyAt'][Target]
    if last and tick() - last < 15 then
        return
    end
    Data['StompNotifyAt'][Target] = tick()
    prunenotifytable(Data['StompNotifyAt'])
    Library:Notify('Stomping ' .. Library:PlayerDisplayName(Target), Library.NotifyDuration or 3)
end
function notifystomped(Target)
    if not Target then
        return
    end
    Library:Notify('Stomped ' .. Library:PlayerDisplayName(Target), Library.NotifyDuration or 3)
end
function notifyknocked(Target)
    if not Target then
        return
    end
    Library:Notify('Knocked ' .. Library:PlayerDisplayName(Target), Library.NotifyDuration or 3)
