function phowg:hide_after_stomp(target)
    Data._ActionableAt, Data.TargetListCache = nil, nil
    if not target or not isstomped(target) then
        return false
    end
    if phowg.record_ragebot_kill then
        phowg:record_ragebot_kill(target)
    end
    if Data.StompWatch and Data.StompWatch[target] then
        Data.StompWatch[target] = nil
        notifystomped(target)
    end
    if not (rageboton() or punishmentactive()) or not (Data.Settings and Data.Settings.Hide) then
        return false
    end
    local current = Data.CurrentActionTarget
        or Data.CurrentMainTarget
        or Data.SingleLockedTarget
        or Data.StompHideTarget
    if current ~= target then
        return false
    end
    if Data.StompHideTarget == target and Data.StompHideCharacter == target.Character and Data.HideVoid then
        return true
    end
    phowg:stop_gun_fire('Ragebot')
    releasefrozenexcept(nil)
    Data.StompHideTarget, Data.StompHideCharacter = target, target.Character
    Data.CurrentActionTarget = target
    Data.CombatArrivalAt, Data.CombatArrivalLastAt, Data.GunFocusTarget, Data.GunFocusAt = nil, nil, nil, nil
    Data.RifleTarget, Data.RifleVoid, Data.RifleVoidFF, Data.RifleVoidWait, Data.RifleVoidTarget =
        nil, nil, nil, nil, nil
    Data.HideVoid, Data.VoidActive, Data.HideStatus = true, true, 'hide'
    Data.CurrentStatus = 'ragebot: hiding...'
    if Data.RPGMoveActive then
        stoprpgmove(false)
    end
    local tags = { Combat = true, Stomp = true, Saving = true, ReloadVoid = true }
    if Data.TargetStrafeTarget == target then
        tags.TargetStrafe = true
    end
    for tag in pairs(tags) do
        releasemovement(tag)
    end
    for index = #Data.CSync.Queue, 1, -1 do
        if tags[Data.CSync.Queue[index].tag] then
            table.remove(Data.CSync.Queue, index)
        end
    end
    if not Data.Buying and not localactionblocked() then
        set_server_cframe(getvoidcframe(), nil, Data.PRIO.IDLE, 'Void')
    end
    phowg:start_loop('VoidHide', voidhideloop)
    return true
end
function phowg:release_stomp_target(target)
    if Data.StompWatch then
        Data.StompWatch[target] = nil
    end
    local character = Data.StompWatchCharacters and Data.StompWatchCharacters[target] or target.Character
    if Data.StompWatchCharacters then
        Data.StompWatchCharacters[target] = nil
    end
    local frozen = Data.FrozenRoots and Data.FrozenRoots[target]
    if frozen and frozen.Parent then
        frozen.Anchored = false
    end
    if Data.FrozenRoots then
        Data.FrozenRoots[target] = nil
    end
    if Data.FrozenAt then
        Data.FrozenAt[target] = nil
    end
    if Data.ResolvedMotion and character then
        Data.ResolvedMotion[character] = nil
    end
    if Data.SmartStrafeCache then
        Data.SmartStrafeCache[target] = nil
    end
    if Data.SmartAttackSamples then
        Data.SmartAttackSamples[target] = nil
    end
    if Data.StompContactCache and character then
        Data.StompContactCache[character] = nil
    end
    if Data.RagebotIdle and Data.RagebotIdle.StompCharacter == character then
        phowg:clear_ragebot_idle()
    end
    if Data.CurrentActionTarget == target then
        releasemovement('Stomp')
        for index = #Data.CSync.Queue, 1, -1 do
            if Data.CSync.Queue[index].tag == 'Stomp' then
                table.remove(Data.CSync.Queue, index)
            end
        end
        Data.RagebotArrival, Data.RagebotMoveIntent, Data.GunFocusTarget, Data.GunAimTarget = nil, nil, nil, nil
        Data.CombatArrivalAt, Data.CombatArrivalLastAt = nil, nil
        Data.TargetListCache, Data._ActionableAt = nil, nil
    end
end
function checkstompwatch()
    for target in pairs(Data.StompWatch or {}) do
        local character = Data.StompWatchCharacters and Data.StompWatchCharacters[target]
        if not target.Parent or character and target.Character ~= character then
            phowg:release_stomp_target(target)
        elseif isstomped(target) then
            phowg:hide_after_stomp(target)
            phowg:release_stomp_target(target)
        elseif not isknocked(target) then
            phowg:release_stomp_target(target)
        end
    end
end
function checktargetwatch()
    if not rageboton() then
        return
    end
    Data['TargetStates'] = Data['TargetStates'] or {}
    local active = {}
    local main = Data['CurrentActionTarget'] or Data['CurrentMainTarget'] or Data['SingleLockedTarget']
    if main and main.Parent then
        active[main] = true
    end
    for p, _ in pairs(Data['LockedTargets'] or {}) do
        if p and p.Parent then
            active[p] = true
        end
    end
    for _, p in ipairs(gettargetlist()) do
        if p and p.Parent then
            active[p] = true
        end
    end
    local sel = Options.target_select and Options.target_select.Value
    if typeof(sel) == 'Instance' and sel:IsA('Player') and sel.Parent then
        active[sel] = true
    elseif typeof(sel) == 'string' then
        local p = Players:FindFirstChild(sel)
        if p and p.Parent then
            active[p] = true
        end
    end
    for p, _ in pairs(active) do
        local st = Data['TargetStates'][p]
        local knocked = isknocked(p)
        local dead = isdead(p)
        local hasBody = p.Character
            and p.Character.Parent
            and p.Character:FindFirstChild('HumanoidRootPart')
            and p.Character:FindFirstChildOfClass('Humanoid')
        if not st then
            Data['TargetStates'][p] = { knocked = knocked, dead = (dead or not hasBody) }
        else
            if knocked and not st.knocked and not dead and hasBody then
                st.knocked = true
                notifyknocked(p)
            elseif not knocked and st.knocked then
                st.knocked = false
            end
            if dead or not hasBody then
                st.dead = true
            elseif hasBody and not dead and st.dead then
                st.dead = false
                st.knocked = false
                notifyrespawn(p)
            end
        end
    end
    for p, _ in pairs(Data['TargetStates']) do
        if not p.Parent or not active[p] then
            Data['TargetStates'][p] = nil
        end
    end
end
function hooktargetrespawn(plr)
    if not plr or plr == LocalPlayer then
        return
    end
    if Data['TargetRespawnConns'] == nil then
        Data['TargetRespawnConns'] = {}
    end
    local old = Data['TargetRespawnConns'][plr]
    if old then
        pcall(function()
            old:Disconnect()
        end)
    end
    local conn = connectshared(plr.CharacterAdded, function(ch)
        task.spawn(function()
            if not ch then
                return
            end
            ch:WaitForChild('HumanoidRootPart', 8)
            task.wait(0.5)
            if not plr.Parent then
                return
            end
            if ch ~= plr.Character then
                return
            end
            if LocalPlayer.Character == nil then
                return
            end
            local wasLocked = (
                Data['TargetWatchlist'] and (Data['TargetWatchlist'][plr.UserId] or Data['TargetWatchlist'][plr.Name])
            )
                or (Data['DropdownTargets'] and Data['DropdownTargets'][plr])
                or (Data['SingleLockedTarget'] == plr)
            if Data['StompWatch'] then
                Data['StompWatch'][plr] = nil
            end
            if Data['ArrestWatch'] then
                Data['ArrestWatch'][plr] = nil
            end
            if Data['FlameUntargetable'] then
                Data['FlameUntargetable'][plr] = nil
            end
            if Data['KillCharSeen'] then
                Data['KillCharSeen'][plr] = nil
            end
            if Data['TargetStates'] then
                Data['TargetStates'][plr] = nil
            end
            if Data['GunFocusTarget'] == plr then
                Data['GunFocusTarget'] = nil
                Data['GunFocusAt'] = nil
            end
            if Data['GunAimTarget'] == plr then
                Data['GunAimTarget'] = nil
                Data['GunAimAt'] = nil
            end
            if Data['RifleTarget'] == plr then
                Data['RifleTarget'] = nil
            end
            if Data['RifleVoidTarget'] == plr then
                Data['RifleVoid'] = nil
                Data['RifleVoidFF'] = nil
                Data['RifleVoidWait'] = nil
                Data['RifleVoidTarget'] = nil
                if not Data['ManualVoid'] and not Data.HideVoid then
                    Data['VoidActive'] = false
                end
            end
            if wasLocked then
                if Data['LockedTargets'] == nil then
                    Data['LockedTargets'] = {}
                end
                Data['LockedTargets'][plr] = true
                if Data['DropdownTargets'] == nil then
                    Data['DropdownTargets'] = {}
                end
                Data['DropdownTargets'][plr] = true
                Data['TargetListCache'] = nil
                pcall(function()
                    updatetracers()
                end)
                pcall(function()
                    updatetargetlabel()
                end)
            end
        end)
    end, plr, 'event/plr.CharacterAdded', 0, 'event/CharacterAdded', plr)
    Data['TargetRespawnConns'][plr] = conn
end
do
    local rs = RunService
    function physic_rep(root, targetPart)
        return task.spawn(function()
            if sethiddenproperty then
                rs.Heartbeat:Wait()
                sethiddenproperty(root, 'PhysicsRepRootRef', InstanceHandle.new(targetPart))
                rs.RenderStepped:Wait()
                sethiddenproperty(root, 'PhysicsRepRootRef', InstanceHandle.new(nill))
            end
        end)
    end
end
function phowg:cancel_physics_rep(root)
    local requests = Data.PhysicsRepRequests
    local request = requests and requests[root]
    if not request then
        return
    end
    requests[root] = nil
    if request.Thread and coroutine.status(request.Thread) ~= 'dead' then
        pcall(task.cancel, request.Thread)
    end
    pcall(function()
        sethiddenproperty(root, 'PhysicsRepRootRef', InstanceHandle.new(nil))
    end)
end
function phowg:request_physics_rep(root, targetPart)
    if not root or not sethiddenproperty then
        return false
    end
    if targetPart == nil then
        phowg:cancel_physics_rep(root)
        return false
    end
    Data.PhysicsRepRequests = Data.PhysicsRepRequests or {}
    local request = Data.PhysicsRepRequests[root]
    if request and request.TargetPart ~= targetPart then
        phowg:cancel_physics_rep(root)
        request = nil
    end
    if not request then
        request = { Root = root, TargetPart = targetPart }
        Data.PhysicsRepRequests[root] = request
    end
    request.Until = tick() + 0.15
    return true
end
create_connection('PhysicsRepStepped', RunService.Stepped:Connect(function()
    for root, request in pairs(Data.PhysicsRepRequests or {}) do
        if Library.Unloaded or Data.SharedSignalsClosed or Data.SafeMode or localactionblocked()
            or not root.Parent or not request.TargetPart.Parent or tick() > request.Until then
            phowg:cancel_physics_rep(root)
        elseif not request.Thread or coroutine.status(request.Thread) == 'dead' then
            request.Thread = physic_rep(root, request.TargetPart)
        end
    end
end))
phowg:register_cleanup('physics replication pulses', function(scope)
    for root, request in pairs(Data.PhysicsRepRequests or {}) do
        if not scope or scope == root or scope == root.Parent or scope == request.TargetPart or scope == request.TargetPart.Parent then
            phowg:cancel_physics_rep(root)
        end
    end
end)
function phowg:clear_melee_charge()
    local state = Data.MeleeCharge
    Data.MeleeCharge = nil
    Data.KnifeCharging, Data.KnifeChargingAt, Data.KnifeChargeTarget, Data.KnifeChargeAt = nil, nil, nil, nil
    if state then
        Data.MeleeChargeRetryAt = tick() + 0.1
        pcall(phowg_callbacks.deactivate_tool, state.Tool)
    end
end
function phowg:update_melee_knife_charge(tool, target)
    local now = tick()
    local state: { [string]: any }? = Data.MeleeCharge
    if
        state
        and (
            state.Tool ~= tool
            or state.Target ~= target
            or state.Character ~= LocalPlayer.Character
            or state.TargetCharacter ~= target.Character
        )
    then
        phowg:clear_melee_charge()
        state = nil
    end
    if not state then
        if now < (Data.MeleeChargeRetryAt or 0) then
            return false
        end
        state = {
            Tool = tool,
            Target = target,
            Character = LocalPlayer.Character,
            TargetCharacter = target.Character,
            StartedAt = now,
            ReadyAt = now + 0.6,
        }
        Data.MeleeCharge = state
        if not pcall(tool.Activate, tool) then
            phowg:clear_melee_charge()
            return false
        end
        Data.KnifeCharging, Data.KnifeChargingAt = target, now
        Data.KnifeChargeTarget, Data.KnifeChargeAt = target, now
        return false
    end
    if state.FiredAt then
        local effects = state.Character:FindFirstChild('BodyEffects')
        local attacking = effects and effects:FindFirstChild('Attacking')
        if now - state.FiredAt >= 1 or now - state.FiredAt >= 0.1 and not (attacking and attacking.Value) then
            phowg:clear_melee_charge()
        end
        return false
    end
    if now < state.ReadyAt then
        return false
    end
    state.FiredAt = now
    Data.KnifeCharging, Data.KnifeChargingAt = nil, nil
    Data.KnifeFiredAt = now
    if not pcall(tool.Activate, tool) then
        phowg:clear_melee_charge()
        return false
    end
    return true
end
function phowg:ragebot_owns_melee_position()
    return (rageboton() or punishmentactive())
        and phowg:ragebot_action_enabled('auto_kill')
        and Data.CurrentActionTarget ~= nil
        and phowg:ragebot_melee_weapon(Options.auto_kill_weapon and Options.auto_kill_weapon.Value) ~= nil
end

function phowg:sync_melee_freeze(state, root, enabled)
    if state.FrozenRoot and (not enabled or state.FrozenRoot ~= root) then
        pcall(function()
            state.FrozenRoot.Anchored = state.OriginalAnchored
        end)
        state.FrozenRoot = nil
    end
    if enabled and root then
        if not state.FrozenRoot then
            state.FrozenRoot, state.OriginalAnchored = root, root.Anchored
        end
        if not root.Anchored then
            root.Anchored = true
        end
    end
end
function phowg:clear_melee_replication_root()
    phowg:clear_melee_charge()
    local state = Data.MeleeReplicationRoot
    if not state then
        return
    end
    Data.MeleeReplicationRoot = nil
    phowg:sync_melee_freeze(state, nil, false)
    if Data.StickyRepTarget == state.TargetPart then
        Data.StickyRepTarget = nil
    end
    phowg:cancel_physics_rep(state.Root)
    releasemovement('Combat')
    phowg:cancel_c_frame_movement({ Combat = true })
end
function phowg:bind_melee_replication_root(root, targetPart, target)
    if
        type(sethiddenproperty) ~= 'function'
        or not root
        or not targetPart
        or not target
        or not target.Character
        or not root.Parent
        or not targetPart.Parent
        or Library.Unloaded
        or Data.SharedSignalsClosed
        or root.Parent ~= LocalPlayer.Character
        or targetPart.Parent ~= target.Character
        or Data.SafeMode
        or localactionblocked()
    then
        phowg:clear_melee_replication_root()
        return false
    end
    local state: { [string]: any }? = Data.MeleeReplicationRoot
    if state and (state.Root ~= root or state.TargetPart ~= targetPart) then
        phowg:clear_melee_replication_root()
        state = nil
    end
    if not state then
        local initial: { [string]: any } = { Root = root, Character = LocalPlayer.Character }
        state = initial
    end
    state.Target, state.TargetPart, state.TargetCharacter = target, targetPart, targetPart.Parent
    Data.MeleeReplicationRoot = state
    return phowg:request_physics_rep(root, targetPart)
end
phowg:register_cleanup('melee replication root', function(scope)
    local state = Data.MeleeReplicationRoot
    if
        not scope
        or state
            and (scope == state.Character or scope == state.Root or scope == state.Target or scope == state.TargetCharacter or scope == state.TargetPart)
