function phowg:stomp_protected(player)
    if Data.TargetSearch and Data.TargetSearch.Active and player and player.UserId == Data.TargetSearch.UserId then
        return true
    end
    return not player
        or player == LocalPlayer
        or not player.Parent
        or Data.IsraelWhitelist and Data.IsraelWhitelist[player] == true
        or Data.RageWhitelist and Data.RageWhitelist[player] == true
        or iswhitelistedplayer(player)
        or isfullywhitelisted(player)
        or iscrewwhitelisted(player)
end
function isvalidstomptarget(Target)
    if phowg:stomp_protected(Target) then
        return false
    end
    if Target and Target.Character and Target.Character:FindFirstChild('GRABBING_CONSTRAINT') then
        return false
    end
    if Data['PunishmentTargets'] and Data['PunishmentTargets'][Target] == 'knock target' then
        return false
    end
    if Data['SupportCompletedTargets'] and Data['SupportCompletedTargets'][Target] then
        return false
    end
    if Data['RPGMoveActive'] then
        return false
    end
    if not intelligence:get_character_cache(Target) then
        return false
    end
    if not isknocked(Target) then
        return false
    end
    if isstomped(Target) then
        return false
    end
    if Data['Settings'].SafeStomp then
        local root = Target.Character and getroot(Target.Character) or nil
        if not root then
            return false
        end
        if root.Position.Magnitude > 2500 then
            return false
        end
    end
    return true
end
function stompallowed(Targets)
    if Data['Settings'].StompWhenUnsafe ~= false then
        return true
    end
    for _, plr in ipairs(Targets or {}) do
        if intelligence:get_character_cache(plr) and not isdead(plr) and not isknocked(plr) then
            return false
        end
    end
    return true
end
function sendstomp(target, origin)
    if isreloading() or phowg:reload_pending(LocalPlayer.Character) then
        return
    end
    if phowg:stomp_protected(target) or not isvalidstomptarget(target) or typeof(origin) ~= 'Vector3' then
        return
    end
    local closest, nearest
    for _, player in ipairs(Players:GetPlayers()) do
        local torso = player.Character and getreppart(player.Character)
        if player ~= LocalPlayer and torso and isknocked(player) and not isstomped(player) then
            local distance = (torso.Position - origin).Magnitude
            if
                distance <= 15
                and (not nearest or distance < nearest or distance == nearest and phowg:stomp_protected(player))
            then
                closest, nearest = player, distance
            end
        end
    end
    if closest ~= target or phowg:stomp_protected(closest) then
        return
    end
    if MainEvent and not localactionblocked() and tick() - (Data['lastStompRemoteTick'] or 0) > 0.05 then
        Data['lastStompRemoteTick'] = tick()
        MainEvent:FireServer('Stomp')
        Data['RecentlyShotAt'] = tick()
    end
end
function phowg:target_touches_granite(target)
    local character = target and target.Character
    if not character or not character.Parent then
        return false
    end
    Data.StompContactCache = Data.StompContactCache or setmetatable({}, { __mode = 'k' })
    local now = tick()
    local cached = Data.StompContactCache[character]
    if cached and now - cached.At < 0.08 then
        return cached.Granite
    end
    local params = OverlapParams.new()
    params.FilterType = Enum.RaycastFilterType.Exclude
    params.FilterDescendantsInstances = { character, LocalPlayer.Character }
    params.RespectCanCollide = true
    local granite = false
    for _, part in ipairs(character:GetChildren()) do
        if part:IsA('BasePart') then
            local touching =
                Workspace:GetPartBoundsInBox(part.CFrame, part.Size + Vector3.new(0.12, 0.12, 0.12), params)
            for _, surface in ipairs(touching) do
                if
                    surface.CanCollide
                    and (surface.Material == Enum.Material.Granite or surface.Name:lower() == 'granite')
                then
                    granite = true
                    break
                end
            end
            if granite then
                break
            end
        end
    end
    Data.StompContactCache[character] = { At = now, Granite = granite }
    return granite
end
function performstomp(RageBotTarget, owner)
    if localactionblocked() or isreloading() or phowg:reload_pending(LocalPlayer.Character) then
        return
    end
    if not isvalidstomptarget(RageBotTarget) then
        return
    end
    local targetCharacter = RageBotTarget.Character
    Data.StompWatchCharacters = Data.StompWatchCharacters or setmetatable({}, { __mode = 'k' })
    Data.StompWatchCharacters[RageBotTarget] = targetCharacter
    local RageBotTorso = getreppart(targetCharacter)
    if not RageBotTorso then
        return
    end
    if owner ~= 'AssistStomp' then
        phowg:stop_gun_fire()
        phowg:clear_ragebot_void_spam()
        phowg:clear_ragebot_idle()
        local staleTags = {
            Combat = true,
            TargetStrafe = true,
            RagebotVoid = true,
            RagebotVoidReturn = true,
            ReloadVoid = true,
            RagebotIdle = true,
        }
        for tag in pairs(staleTags) do
            releasemovement(tag)
        end
        for index = #Data.CSync.Queue, 1, -1 do
            if staleTags[Data.CSync.Queue[index].tag] then
                table.remove(Data.CSync.Queue, index)
            end
        end
        Data['CurrentStatus'] = 'ragebot: stomping ' .. RageBotTarget.DisplayName .. ' | ' .. RageBotTarget.Name
        Data['CurrentActionTarget'] = RageBotTarget
        Data['CombatActAt'] = tick()
    end
    local MyRoot = LocalPlayer.Character and getreppart(LocalPlayer.Character)
    phowg:request_physics_rep(MyRoot, RageBotTorso)
    local holdingTool = false
    if LocalPlayer.Character then
        for _, t in ipairs(LocalPlayer.Character:GetChildren()) do
            if t:IsA('Tool') then
                holdingTool = true
                break
            end
        end
    end
    if holdingTool then
        unequipall()
    end
    local height = (Options['ragebot_stomp_height_offset'] and Options['ragebot_stomp_height_offset'].Value) or 6
    if phowg:target_touches_granite(RageBotTarget) then
        height = 0
    end
    local standPos = RageBotTorso.Position + Vector3.new(0, height, 0)
    local randAmt = (Options['ragebot_stomp_random_offset'] and Options['ragebot_stomp_random_offset'].Value) or 0
    local zAmt = (Options['ragebot_stomp_z'] and Options['ragebot_stomp_z'].Value) or 0
    if randAmt > 0 then
        standPos = standPos + Vector3.new((math.random() - 0.5) * 2 * randAmt, 0, (math.random() - 0.5) * 2 * randAmt)
    end
    if zAmt > 0 then
        standPos = standPos + Vector3.new(0, 0, (math.random() - 0.5) * 2 * zAmt)
    end
    local offset = standPos - RageBotTorso.Position
    if offset.Magnitude > 10 then
        standPos = RageBotTorso.Position + offset.Unit * 10
    end
    local StompCFrame = CFrame.new(standPos)
    if Data['Settings'].RagebotSilentStomp then
        StompCFrame = CFrame.new(standPos) * CFrame.Angles(0, 0, math.rad(180))
    end
    set_server_cframe(
        StompCFrame,
        nil,
        (punishmentactive() and Data['PRIO'].PUNISH or Data['PRIO'].STOMP),
        owner or 'Stomp',
        false,
        nil,
        function(root)
            local torso = RageBotTarget.Character and getreppart(RageBotTarget.Character)
            if
                (
                    owner ~= 'AssistStomp'
                    or phowg:assist_stomp_enabled() and Data.AssistStompTarget == RageBotTarget and not Data.Saving
                )
                and RageBotTarget.Character == targetCharacter
                and isvalidstomptarget(RageBotTarget)
                and torso
                and (torso.Position - root.Position).Magnitude <= 15
            then
                sendstomp(RageBotTarget, StompCFrame.Position)
            end
        end
    )
    Data['FrozenRoots'] = Data['FrozenRoots'] or {}
    local stompRoot = RageBotTarget.Character and RageBotTarget.Character:FindFirstChild('HumanoidRootPart') or nil
    if stompRoot and freezetargetenabled() then
        Data['FrozenRoots'][RageBotTarget] = stompRoot
        stompRoot.Anchored = true
        stompRoot.AssemblyLinearVelocity = Vector3.zero
    end
    phowg:request_physics_rep(MyRoot, RageBotTorso)
end
function phowg:sticky_stomp_valid(target, targetCharacter)
    if
        Library.Unloaded
        or Data.Unloading
        or localactionblocked()
        or Data.Buying
        or Data.Sorting
        or Data.LoadoutReloadJob
    then
        return false
    end
    if not phowg:toggle_enabled('sticky_stomp_target') or not phowg:toggle_enabled('sticky_aim_enabled') then
        return false
    end
    if
        not target
        or phowg:is_zombie_target(target)
        or target ~= get_sticky_target()
        or target.Character ~= targetCharacter
    then
        return false
    end
    return targetCharacter ~= nil
        and targetCharacter.Parent ~= nil
        and not isdead(target)
        and phowg:sticky_checks_pass(target)
        and isvalidstomptarget(target)
        and not isreloading()
        and not phowg:reload_pending(LocalPlayer.Character)
end
function phowg:clear_sticky_stomp()
    local state: { [string]: any }? = Data.StickyStomp
    Data.StickyStomp = nil
    if state and state.Hold then
        state.Hold:Stop()
    end
end
function phowg:update_sticky_stomp()
    local target = get_sticky_target()
    local character = target and target.Character
    if not phowg:sticky_stomp_valid(target, character) then
        phowg:clear_sticky_stomp()
        return
    end
    local torso = getreppart(character)
    if not torso then
        phowg:clear_sticky_stomp()
        return
    end
    local height = phowg:target_touches_granite(target) and 0
        or math.clamp(
            tonumber(Options.ragebot_stomp_height_offset and Options.ragebot_stomp_height_offset.Value) or 6,
            0,
            10
        )
    local destination = CFrame.new(torso.Position + Vector3.new(0, height, 0))
    local state: { [string]: any }? = Data.StickyStomp
    if
        state
        and (
            state.Target ~= target
            or state.TargetCharacter ~= character
            or state.Character ~= LocalPlayer.Character
            or not state.Hold
            or state.Hold.Stopped
            or not Data.MoveToHolds
            or Data.MoveToHolds.StickyStomp ~= state.Hold
        )
    then
        phowg:clear_sticky_stomp()
        state = nil
    end
    if LocalPlayer.Character:FindFirstChildOfClass('Tool') then
        unequipall()
    end
    if not state then
        local newState: { [string]: any } = {
            Target = target,
            TargetCharacter = character,
            Character = LocalPlayer.Character,
        }
        Data.StickyStomp = newState
        releasemovement('TargetStrafe')
        newState.Hold = startmovetohold('StickyStomp', destination, Data.PRIO.STOMP, function()
            return Data.StickyStomp == newState and phowg:sticky_stomp_valid(target, character)
        end, function(root)
            local currentTorso = getreppart(character)
            if
                Data.StickyStomp == newState
                and phowg:sticky_stomp_valid(target, character)
                and currentTorso
                and (currentTorso.Position - root.Position).Magnitude <= 15
            then
                sendstomp(target, root.Position)
            end
        end)
    else
        state.Hold:Update(destination)
    end
end
registerheartbeat('StickyTargetStomp', phowg.update_sticky_stomp, nil, function()
    return Data.StickyStomp ~= nil or phowg:toggle_enabled('sticky_stomp_target')
end)
phowg:register_cleanup('sticky target stomp', function(scope)
    local state: { [string]: any }? = Data.StickyStomp
    if not scope or state and (scope == state.Character or scope == state.TargetCharacter or scope == state.Target) then
        phowg:clear_sticky_stomp()
    end
end)
function getcufftool()
    return findtoolbyexactname('Cuff') or findtoolbypattern('^cuff$') or findtoolbypattern('cuff')
end
function isvalidarresttarget(Target)
    if phowg:target_search_active() and Target and Target.UserId == Data.TargetSearch.UserId then return false end
    if Data['PunishmentTargets'] and Data['PunishmentTargets'][Target] == 'knock target' then
        return false
    end
    if Data['SupportCompletedTargets'] and Data['SupportCompletedTargets'][Target] then
        return false
    end
    if not Target or not Target.Parent then
        return false
    end
    if Target.Character and Target.Character:FindFirstChild('GRABBING_CONSTRAINT') then
        return false
    end
    if not intelligence:get_character_cache(Target) then
        return false
    end
    if not isknocked(Target) then
        return false
    end
    if isdead(Target) then
        return false
    end
    local ch = Target.Character
    if not ch then
        return false
    end
    local be = ch:FindFirstChild('BodyEffects')
    if be then
        local arrested = be:FindFirstChild('Arrested') or be:FindFirstChild('Cuffed')
        if arrested and arrested.Value == true then
            return false
        end
    end
    if Data['Settings'].SafeStomp then
        local root = ch and getroot(ch) or nil
        if not root then
            return false
        end
        if root.Position.Magnitude > 2500 then
            return false
        end
    end
    return true
end
function notifyarresting(Target)
    if not Target or not Target.Parent then
        return
    end
    Data['ArrestNotifyAt'] = Data['ArrestNotifyAt'] or {}
    local last = Data['ArrestNotifyAt'][Target]
    if last and tick() - last < 15 then
        return
    end
    Data['ArrestNotifyAt'][Target] = tick()
    prunenotifytable(Data['ArrestNotifyAt'])
    Library:Notify('Arresting ' .. Library:PlayerDisplayName(Target), Library.NotifyDuration or 3)
end
function checkarrestwatch()
    Data['ArrestWatch'] = Data['ArrestWatch'] or {}
    for plr, _ in pairs(Data['ArrestWatch']) do
        if not plr.Parent then
            Data['ArrestWatch'][plr] = nil
        elseif isdead(plr) then
            Data['ArrestWatch'][plr] = nil
        elseif not (intelligence:get_character_cache(plr) and isknocked(plr)) then
            Data['ArrestWatch'][plr] = nil
        end
    end
end
function performarrest(RageBotTarget, owner)
    if localactionblocked() then
        return
    end
    if (owner == 'AssistStomp' and (not phowg:assist_stomp_enabled() or Data.AssistStompTarget ~= RageBotTarget or Data.Saving)) or not isvalidarresttarget(RageBotTarget) then
        return
    end
    local ch = RageBotTarget.Character
    if not ch then
        return
    end
    local RageBotTorso = getreppart(ch)
    if not RageBotTorso then
        return
    end
    if owner ~= 'AssistStomp' then
        Data['CurrentStatus'] = 'ragebot: arresting ' .. RageBotTarget.DisplayName .. ' | ' .. RageBotTarget.Name
        Data['CurrentActionTarget'] = RageBotTarget
        Data['CombatActAt'] = tick()
    end
    local MyRoot = LocalPlayer.Character and getreppart(LocalPlayer.Character) or nil
    phowg:request_physics_rep(MyRoot, RageBotTorso)
    local CuffTool = getcufftool()
    if not CuffTool then
        return
    end
    if CuffTool.Parent ~= LocalPlayer.Character then
        equip(CuffTool)
    end
    local standPos = RageBotTorso.Position + Vector3.new(0, 3, 0)
    local ArrestCFrame = CFrame.lookAt(standPos, RageBotTorso.Position)
        * CFrame.Angles(0, 0, tick() * 12 % (math.pi * 2))
    set_server_cframe(ArrestCFrame, nil, (punishmentactive() and Data['PRIO'].PUNISH or Data['PRIO'].ARREST), owner or 'Combat')
    Data['FrozenRoots'] = Data['FrozenRoots'] or {}
    local arrestRoot = ch:FindFirstChild('HumanoidRootPart')
    if arrestRoot and freezetargetenabled() then
        Data['FrozenRoots'][RageBotTarget] = arrestRoot
        arrestRoot.Anchored = true
        arrestRoot.AssemblyLinearVelocity = Vector3.zero
    end
    phowg:request_physics_rep(MyRoot, RageBotTorso)
    RunService.Heartbeat:Wait()
    if not isvalidarresttarget(RageBotTarget) then
        return
    end
    if tick() - (Data['LastArrestActivateAt'] or 0) >= 0.7 then
        local cur = RageBotTarget.Character
        local curTorso = cur and getreppart(cur) or nil
        if curTorso and (curTorso.Position - standPos).Magnitude <= 15 then
            local held = findtoolbyexactname('Cuff')
            if held and held.Parent == LocalPlayer.Character then
                if not localactionblocked() then
                    held:Activate()
                end
                Data['LastArrestActivateAt'] = tick()
                Data['RecentlyShotAt'] = tick()
            end
        end
    end
end
function isseated(Player)
    local hum = intelligence:get_character_cache(Player) and Player.Character:FindFirstChildOfClass('Humanoid')
    if not hum then
        return false
    end
    local seat = hum.SeatPart
    if seat and seat.Parent and (seat:IsA('Seat') or seat:IsA('VehicleSeat')) then
        return true
    end
    return false
end
function isdrivingvehicle(Player)
    if not Player then
        return false
    end
    local vehicles = Workspace:FindFirstChild('Vehicles')
    if not vehicles then
        return false
    end
    local uname = Player.Name
    for _, v in ipairs(vehicles:GetChildren()) do
        if v.Name == uname then
            return true
        end
    end
    return false
end
function flingclaim(owner)
    local t0 = tick()
    while Data['FlingOwner'] ~= nil and Data['FlingOwner'] ~= owner do
        if tick() - t0 > 0.5 then
            return false
        end
        RunService.Heartbeat:Wait()
    end
    Data['FlingOwner'] = owner
    return true
end
function flingrelease(owner)
    if Data['FlingOwner'] == owner then
        Data['FlingOwner'] = nil
    end
end
function stopflingstate()
    if Data['FrozenRoots'] then
        for P, R in pairs(Data['FrozenRoots']) do
            if R and R.Parent then
                pcall(function()
                    R.Anchored = false
                end)
            end
            Data['FrozenRoots'][P] = nil
        end
    end
    if Data['ProtectFrozen'] then
        for P, R in pairs(Data['ProtectFrozen']) do
            if R and R.Parent then
                pcall(function()
                    R.Anchored = false
                end)
            end
            Data['ProtectFrozen'][P] = nil
        end
    end
    if Data['ProtectHold'] then
        for P, _ in pairs(Data['ProtectHold']) do
            Data['ProtectHold'][P] = nil
        end
    end
    Data['Flinging'] = false
    Data['FlingOwner'] = nil
    Data['FlingFailCount'] = 0
    Data['CurrentStatus'] = 'Idle'
    Data['CurrentActionTarget'] = nil
end
function disableautofling()
    stopflingstate()
    if Toggles.auto_fling and Toggles.auto_fling.Value then
        if Toggles.auto_fling.SetValue then
            Toggles.auto_fling:SetValue(false)
        else
            Toggles.auto_fling.Value = false
        end
    end
    pcall(function()
        Library:Notify('auto fling disabled (self-fling detected)', Library.NotifyDuration or 4)
    end)
end
function flingpulse(hrp)
    if localactionblocked() then
        return
    end
    if not hrp or not hrp.Parent then
        return false
    end
    local origVel = hrp.AssemblyLinearVelocity
    if origVel.Magnitude > 1000 then
        origVel = Vector3.zero
    end
    hrp.Velocity = Vector3.new(0, -9e9, 0)
    hrp.AssemblyLinearVelocity = Vector3.new(0, -9e9, 0)
    RunService.RenderStepped:Wait()
    if not hrp.Parent then
        return false
    end
    hrp.Velocity = origVel
    hrp.AssemblyLinearVelocity = origVel
    RunService.Heartbeat:Wait()
    if not hrp.Parent then
        return false
    end
    if hrp.AssemblyLinearVelocity.Magnitude > 1000 or hrp.Velocity.Magnitude > 1000 then
        hrp.Velocity = Vector3.zero
        hrp.AssemblyLinearVelocity = Vector3.zero
        hrp.AssemblyAngularVelocity = Vector3.zero
        return false
    end
    return true
end
function flingnotefail()
    Data['FlingFailCount'] = (Data['FlingFailCount'] or 0) + 1
    if Data['FlingFailCount'] >= 3 then
        disableautofling()
        return true
    end
    return false
end
function autoflingloop()
    while Toggles.auto_fling and Toggles.auto_fling.Value and (rageboton() or punishmentactive()) do
        if localactionblocked() then
            task.wait(0.05)
            continue
        end
        local c = LocalPlayer.Character
        local hrp = c and getreppart(c)
        local Targets = gettargetlist()
        if hrp and #Targets > 0 then
            for _, Target in ipairs(Targets) do
                if not (Toggles.auto_fling and Toggles.auto_fling.Value) then
                    break
                end
                if
                    intelligence:get_character_cache(Target)
                    and not isseated(Target)
                    and not isdrivingvehicle(Target)
                then
                    local Torso = getreppart(Target.Character)
                    if Torso then
                        if Torso.Position.Magnitude > 10000 then
                            Data['CurrentStatus'] = 'Idle'
                        else
                            local FlingAnchorAt = tick()
                            while
                                Toggles.auto_fling
                                and Toggles.auto_fling.Value
                                and (rageboton() or punishmentactive())
                                and intelligence:get_character_cache(Target)
                                and not isseated(Target)
                                and not isdrivingvehicle(Target)
                            do
                                if phowg:support_armor_blocked(Target) then
                                    break
                                end
                                hrp = LocalPlayer.Character and getreppart(LocalPlayer.Character)
                                if not hrp or not hrp.Parent then
                                    break
                                end
                                Torso = getreppart(Target.Character)
                                if not Torso then
                                    break
                                end
                                if Torso.Position.Magnitude > 10000 then
                                    break
                                end
                                Data['CurrentStatus'] = 'ragebot: flinging '
                                    .. Target.DisplayName
                                    .. ' | '
                                    .. Target.Name
                                Data['CurrentActionTarget'] = Target
                                if not flingclaim('auto') then
                                    break
                                end
                                Data['Flinging'] = true
                                local TargetRoot = Target.Character:FindFirstChild('HumanoidRootPart') or Torso
                                Data['FrozenRoots'] = Data['FrozenRoots'] or {}
                                if freezetargetenabled() then
                                    Data['FrozenRoots'][Target] = TargetRoot
                                    TargetRoot.Anchored = true
                                    Data['FrozenAt'] = Data['FrozenAt'] or {}
                                    Data['FrozenAt'][Target] = tick()
                                end
                                phowg:request_physics_rep(hrp, Torso)
                                local faceOn = Data['Settings'] and Data['Settings'].RagebotFaceTarget or false
                                local flingPos = Torso.Position + Vector3.new(0, 0, 0)
                                if faceOn then
                                    set_server_cframe(
                                        CFrame.lookAt(flingPos, hrp.Position),
                                        nil,
                                        Data['PRIO'].IDLE,
                                        'Fling'
                                    )
                                else
                                    set_server_cframe(CFrame.new(flingPos), nil, Data['PRIO'].IDLE, 'Fling')
                                end
                                TargetRoot.Anchored = false
                                if flingpulse(hrp) then
                                    Data['FlingFailCount'] = 0
                                elseif flingnotefail() then
                                    flingrelease('auto')
                                    break
                                end
                                flingrelease('auto')
                                if isdead(Target) or isknocked(Target) then
                                    break
                                end
                                if tick() - FlingAnchorAt >= 2 then
                                    local fr = Data['FrozenRoots'] and Data['FrozenRoots'][Target] or nil
                                    if fr and fr.Parent then
                                        fr.Anchored = false
                                    end
                                    if Data['FrozenRoots'] then
                                        Data['FrozenRoots'][Target] = nil
                                    end
                                    Data['Flinging'] = false
                                    local tRoot = Target.Character
                                            and Target.Character:FindFirstChild('HumanoidRootPart')
                                        or nil
                                    if tRoot and tRoot.Position.Magnitude <= 2500 then
                                        FlingAnchorAt = tick()
                                    else
                                        break
                                    end
                                end
                            end
                            if Data['FrozenRoots'] then
                                local fr2 = Data['FrozenRoots'][Target]
                                if fr2 and fr2.Parent then
                                    fr2.Anchored = false
                                end
                                Data['FrozenRoots'][Target] = nil
                            end
                            Data['Flinging'] = false
                        end
                    end
                end
            end
        else
            Data['CurrentStatus'] = 'Idle'
        end
        RunService.Heartbeat:Wait()
    end
    if Data['FrozenRoots'] then
        for P, R in pairs(Data['FrozenRoots']) do
            if R and R.Parent then
                R.Anchored = false
            end
            Data['FrozenRoots'][P] = nil
        end
    end
    Data['Flinging'] = false
    Data['CurrentStatus'] = 'Idle'
end
function protectrelease(plr)
    if Data['ProtectHold'] then
        Data['ProtectHold'][plr] = nil
    end
    local owned = Data['ProtectFrozen'] and Data['ProtectFrozen'][plr] or nil
    if Data['ProtectFrozen'] then
        Data['ProtectFrozen'][plr] = nil
    end
    if owned then
        if owned.Parent then
            owned.Anchored = false
        end
        if Data['FrozenRoots'] and Data['FrozenRoots'][plr] == owned then
            Data['FrozenRoots'][plr] = nil
        end
    end
end
function protectfling(plr)
    if localactionblocked() then
        return
    end
    Data['ProtectHold'] = Data['ProtectHold'] or {}
    Data['ProtectFrozen'] = Data['ProtectFrozen'] or {}
    Data['ProtectCooldown'] = Data['ProtectCooldown'] or {}
    if Data['ProtectHold'][plr] then
        return
    end
    Data['ProtectHold'][plr] = true
    task.spawn(function()
        local t0 = tick()
        while
            tick() - t0 < 1
            and (Toggles.protect_key and Toggles.protect_key.Value)
            and plr.Parent
            and intelligence:get_character_cache(plr)
        do
            local c = LocalPlayer.Character
            local hrp = c and getreppart(c) or nil
            local ch = plr.Character
            local root = ch and ch:FindFirstChild('HumanoidRootPart') or nil
            if not hrp or not hrp.Parent or not root or not root.Parent then
                break
            end
            local torso = getreppart(ch) or root
            if freezetargetenabled() then
                Data['ProtectFrozen'][plr] = root
                Data['FrozenRoots'] = Data['FrozenRoots'] or {}
                Data['FrozenRoots'][plr] = root
                root.Anchored = true
                Data['FrozenAt'] = Data['FrozenAt'] or {}
                Data['FrozenAt'][plr] = tick()
                root.AssemblyLinearVelocity = Vector3.zero
            end
            if not flingclaim('protect') then
                break
            end
            phowg:request_physics_rep(hrp, torso)
            set_server_cframe(CFrame.new(torso.Position), nil, Data['PRIO'].KNIFE, 'Protect')
            root.Anchored = false
            if flingpulse(hrp) then
                Data['FlingFailCount'] = 0
            elseif flingnotefail() then
                flingrelease('protect')
                break
            end
            flingrelease('protect')
        end
        protectrelease(plr)
        Data['ProtectCooldown'] = Data['ProtectCooldown'] or {}
        Data['ProtectCooldown'][plr] = tick()
        local still = false
        if Data['ProtectHold'] then
            for _ in pairs(Data['ProtectHold']) do
                still = true
                break
            end
        end
        if not still then
            Data['Flinging'] = false
        end
    end)
end
function haskeytool(plr)
    if not plr or not plr.Parent then
        return false
    end
    local bp = plr:FindFirstChild('Backpack')
    if bp then
        for _, t in ipairs(bp:GetChildren()) do
            if t:IsA('Tool') and t.Name:lower():find('key', 1, true) then
                return true
            end
        end
    end
    local ch = plr.Character
    if ch then
        for _, t in ipairs(ch:GetChildren()) do
            if t:IsA('Tool') and t.Name:lower():find('key', 1, true) then
                return true
            end
        end
    end
    return false
end
function protecttick()
    Data['ProtectFrozen'] = Data['ProtectFrozen'] or {}
    Data['ProtectHold'] = Data['ProtectHold'] or {}
    Data['ProtectCooldown'] = Data['ProtectCooldown'] or {}
    if not (Toggles.protect_key and Toggles.protect_key.Value) then
        for plr, _ in pairs(Data['ProtectHold']) do
            protectrelease(plr)
        end
        for plr, _ in pairs(Data['ProtectFrozen']) do
            protectrelease(plr)
        end
        return
    end
    local guard = Vector3.new(-271, 22, -239)
    local jailedPositions = {}
    for _, plr in ipairs(Players:GetPlayers()) do
        if
            plr ~= LocalPlayer
            and plr.Parent
            and not Data['ProtectHold'][plr]
            and tick() - (Data['ProtectCooldown'][plr] or 0) >= 2
            and intelligence:get_character_cache(plr)
            and not isseated(plr)
            and not isdrivingvehicle(plr)
        then
            local dc = intelligence:get_data_cache(plr)
            if dc and dc.Jailed == true then
                local ch = plr.Character
                local root = ch and ch:FindFirstChild('HumanoidRootPart') or nil
                if root and root.Parent then
                    jailedPositions[#jailedPositions + 1] = root.Position
                    if (root.Position - guard).Magnitude <= 50 then
                        Data['Flinging'] = true
                        protectfling(plr)
                    end
                end
            end
        end
    end
    if #jailedPositions > 0 then
        for _, plr in ipairs(Players:GetPlayers()) do
            if
                plr ~= LocalPlayer
                and plr.Parent
                and not Data['ProtectHold'][plr]
                and tick() - (Data['ProtectCooldown'][plr] or 0) >= 2
                and intelligence:get_character_cache(plr)
                and not isseated(plr)
                and not isdrivingvehicle(plr)
            then
                local dc = intelligence:get_data_cache(plr)
                if dc and dc.Jailed ~= true and haskeytool(plr) then
                    local ch = plr.Character
                    local root = ch and ch:FindFirstChild('HumanoidRootPart') or nil
                    if root and root.Parent then
                        for _, jpos in ipairs(jailedPositions) do
                            if (root.Position - jpos).Magnitude <= 50 then
                                Data['Flinging'] = true
                                protectfling(plr)
                                break
                            end
                        end
                    end
                end
            end
        end
    end
end
function assiststomprelease(pat)
    if not pat then
        return
    end
    if Data['AssistStompTarget'] == pat then
        Data['AssistStompTarget'] = nil
        releasemovement('AssistStomp')
    end
    local pch = pat.Character
    local proot = pch and pch:FindFirstChild('HumanoidRootPart') or nil
    if Data['FrozenRoots'] and Data['FrozenRoots'][pat] then
        local fr = Data['FrozenRoots'][pat]
        if fr and (proot == nil or fr == proot) then
            if fr.Parent then
                fr.Anchored = false
            end
            Data['FrozenRoots'][pat] = nil
        end
    end
end
function phowg:assist_stomp_enabled()
    local toggle = Toggles.misc_auto_stomp
    local key = Options.misc_auto_stomp_key
    return not Library.Unloaded and not Data.SafeMode and toggle ~= nil and toggle.Value == true and (not key or key.Value == 'None' or key:GetState() == true)
end
function phowg:assist_stomp_snapshot()
    local cached = Data.AssistStompSnapshot
    if cached and tick() - cached.At < 0.05 then
        return cached
    end
    local root = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild('HumanoidRootPart')
    local client = Local_Data['ClientPos'] or getgenv().PhowgClientPos
    local origin = typeof(client) == 'CFrame' and client.Position or root and root.Position
    local mode = Options.misc_auto_stomp_mode and Options.misc_auto_stomp_mode.Value or 'normal'
    if type(mode) == 'table' then
        mode = (mode.assistance or mode[1] == 'assistance') and 'assistance' or 'normal'
    end
    if mode ~= 'assistance' then
        mode = 'normal'
    end
    local radius = Options.misc_auto_stomp_radius and Options.misc_auto_stomp_radius.Value or 25
    if mode == 'normal' then
        radius = math.min(radius, 10)
    end
    local enabled = Toggles.misc_auto_stomp and Toggles.misc_auto_stomp.Value
    local on = phowg:assist_stomp_enabled()
    local cuffs = mode == 'assistance' and getcufftool() ~= nil
    local crew = mode == 'assistance' and getplayercrewid(LocalPlayer)
    local snapshot = {
        At = tick(),
        Root = root,
        Origin = origin,
        Mode = mode,
        Radius = radius,
        On = on,
        Cuffs = cuffs,
        Candidates = {},
    }
    snapshot.Visible = enabled
        and Toggles.misc_auto_stomp_visualize
        and Toggles.misc_auto_stomp_visualize.Value
        and root ~= nil
        and root.Parent ~= nil
        and origin ~= nil
        and not localactionblocked()
    snapshot.Status = not on and 'KEYBIND OFF'
        or Data['Saving'] and 'SAVING'
        or isreloading() and 'RELOADING'
        or Data['RPGMoveActive'] and 'EVADING'
        or 'WAITING'
    if enabled and origin and not localactionblocked() then
        for _, player in ipairs(Players:GetPlayers()) do
            local character = player.Character
            local targetRoot = character and character:FindFirstChild('HumanoidRootPart')
            local distance = targetRoot and (targetRoot.Position - origin).Magnitude
            local valid = player ~= LocalPlayer
                and player.Parent
                and distance
                and distance <= radius
                and isknocked(player)
                and not isstomped(player)
                and intelligence:get_character_cache(player)
            if valid and mode == 'normal' then
                valid = isvalidstomptarget(player)
            end
            if valid and mode == 'assistance' then
                valid = not character:FindFirstChildOfClass('ForceField')
                    and not (crew and getplayercrewid(player) == crew)
                    and not (Data['IsraelWhitelist'] and Data['IsraelWhitelist'][player])
                    and not iswhitelistedplayer(player)
                    and not isfullywhitelisted(player)
                    and not (Data['RageWhitelist'] and Data['RageWhitelist'][player])
                    and not iscrewwhitelisted(player)
                if valid and cuffs then
                    local ok, playerData = pcall(function()
                        return intelligence:get_data_cache(player)
                    end)
                    local wanted = ok and playerData and playerData.Wanted
                    valid = wanted ~= nil and wanted ~= false and wanted ~= 0 and wanted ~= '' and wanted ~= '0'
                end
            end
            if valid then
                snapshot.Candidates[#snapshot.Candidates + 1] =
                    { Player = player, Root = targetRoot, Distance = distance }
            end
        end
        table.sort(snapshot.Candidates, function(a, b)
            return a.Distance < b.Distance
        end)
    end
    snapshot.Target = snapshot.Candidates[1]
    if snapshot.Target and snapshot.Status == 'WAITING' then
        snapshot.Status = cuffs and 'ARREST READY' or 'STOMP READY'
    end
    Data['AssistStompSnapshot'] = snapshot
    return snapshot
end
function phowg:clear_assist_stomp_visual()
    local visual = Data['AssistStompVisual']
    if visual then
        visual.Model:Destroy()
    end
    Data['AssistStompVisual'] = nil
    Data['AssistStompSnapshot'] = nil
end
function phowg:update_assist_stomp_visual()
    if
        not (
            Toggles.misc_auto_stomp
            and Toggles.misc_auto_stomp.Value
            and Toggles.misc_auto_stomp_visualize
            and Toggles.misc_auto_stomp_visualize.Value
        )
    then
        if Data.AssistStompVisual then
            phowg:clear_assist_stomp_visual()
        end
        return
    end
    local snapshot = Data['AssistStompSnapshot']
    if not snapshot or tick() - snapshot.At > 0.05 then
        snapshot = phowg:assist_stomp_snapshot()
    end
    local visual = Data['AssistStompVisual']
    local target = snapshot.Target
    local character = target and target.Player.Character
    local torso = character
        and (character:FindFirstChild('UpperTorso') or character:FindFirstChild('Torso') or target.Root)
    if not snapshot.Visible or not torso or not torso.Parent or Library.Unloaded or localactionblocked() then
        if visual then
            visual.Link.Transparency, visual.Glow.Transparency = 1, 1
        end
        return
    end
    if not visual or not visual.Model.Parent then
        phowg:clear_assist_stomp_visual()
        local model = Instance.new('Model')
        model.Name, model.Parent = 'PhowgAssistStompVisual', Workspace
        visual = { Model = model }
        for _, name in ipairs({ 'Link', 'Glow' }) do
            local part = Instance.new('Part')
            part.Name, part.Material = name, Enum.Material.Neon
            part.Anchored, part.CanCollide, part.CanTouch, part.CanQuery, part.CastShadow =
                true, false, false, false, false
            part.Parent = model
            visual[name] = part
        end
        Data['AssistStompVisual'] = visual
    end
    local a, b = snapshot.Origin, torso.Position
    local length = (b - a).Magnitude
    if length < 0.001 then
        visual.Link.Transparency, visual.Glow.Transparency = 1, 1
        return
    end
    local color = Options.misc_auto_stomp_visual_color and Options.misc_auto_stomp_visual_color.Value
        or Color3.fromRGB(90, 205, 255)
    local frame = CFrame.lookAt((a + b) * 0.5, b)
    visual.Link.Size, visual.Glow.Size = Vector3.new(0.065, 0.065, length), Vector3.new(0.14, 0.14, length)
    visual.Link.CFrame, visual.Glow.CFrame = frame, frame
    visual.Link.Color, visual.Glow.Color = color, color
    visual.Link.Transparency, visual.Glow.Transparency = snapshot.On and 0.05 or 0.45, 0.85
end
registerheartbeat('AssistStompVisual', phowg.update_assist_stomp_visual)
phowg:register_cleanup('assist stomp visual', function(scope)
    if not scope or scope == LocalPlayer.Character then
        assiststomprelease(Data.AssistStompTarget)
        phowg:clear_assist_stomp_visual()
    end
end)
function assiststomptick()
    if localactionblocked() or isreloading() or not phowg:assist_stomp_enabled() or Data.Saving then
        assiststomprelease(Data.AssistStompTarget)
        return
    end
    local snapshot = phowg:assist_stomp_snapshot()
    local candidate = snapshot.Target
    local target = candidate and candidate.Player
    if not snapshot.Root or not target then
        assiststomprelease(Data.AssistStompTarget)
        return
    end
    if movementblocked(snapshot.Cuffs and Data.PRIO.ARREST or Data.PRIO.STOMP, 'AssistStomp') then
        assiststomprelease(Data.AssistStompTarget)
        return
    end
    if Data.AssistStompTarget ~= target then
        assiststomprelease(Data.AssistStompTarget)
    end
    Data.AssistStompTarget = target
    if snapshot.Mode == 'normal' then
        local character = target.Character
        if LocalPlayer.Character:FindFirstChildOfClass('Tool') then
            unequipall()
        end
        set_server_cframe(CFrame.new(snapshot.Origin), nil, Data.PRIO.STOMP, 'AssistStomp', false, nil, function(root)
            local currentRoot = target.Character == character and getroot(character)
            if
                phowg:assist_stomp_enabled()
                and Data.AssistStompTarget == target
                and not localactionblocked()
                and not isreloading()
                and not Data.Saving
                and currentRoot == candidate.Root
                and isvalidstomptarget(target)
                and (currentRoot.Position - root.Position).Magnitude <= snapshot.Radius
            then
                sendstomp(target, root.Position)
            end
        end)
    elseif snapshot.Cuffs then
        performarrest(target, 'AssistStomp')
        notifyarresting(target)
        Data.ArrestWatch = Data.ArrestWatch or {}
        Data.ArrestWatch[target] = true
        checkarrestwatch()
    else
        performstomp(target, 'AssistStomp')
    end
end
function phowg:auto_save_enabled(target)
    return not Library.Unloaded
        and not Data.Unloading
        and phowg:other_protection_enabled()
        and phowg:toggle_enabled('auto_save')
        and (target == nil or target.Parent ~= nil and Data.IsraelWhitelist and Data.IsraelWhitelist[target] == true)
end
function phowg:auto_save_holding(character, target)
    local effects = character and character:FindFirstChild('BodyEffects')
    local grabbed = effects and effects:FindFirstChild('Grabbed')
    local carrying = grabbed and grabbed.Value
    Local_Data.carrying, Local_Data.Carrying = carrying, carrying
    local targetCharacter = target and target.Character
    return targetCharacter ~= nil
        and (
            carrying == targetCharacter
            or carrying == target
            or typeof(carrying) == 'Instance' and carrying:IsDescendantOf(targetCharacter)
            or type(carrying) == 'string' and carrying == target.Name
        ),
        carrying
end
function phowg:cancel_auto_save()
    Data.SaveRevision = (Data.SaveRevision or 0) + 1
    Data.AutoSaveSession = nil
    Data.Saving = false
    Data.CurrentSaveTarget = nil
    Data.SaveNotifyTarget, Data.SaveNotifyState, Data.SaveCarryNotified = nil, nil, nil
    Data.SaveOriginCF, Data.SaveGrabStartAt = nil, nil
    releasemovement('Saving')
end
function phowg:auto_save_session_valid(session)
    local character = LocalPlayer.Character
    local humanoid = character and character:FindFirstChildOfClass('Humanoid')
    return Data.AutoSaveSession == session
        and Data.Saving == true
        and phowg:auto_save_enabled(session.Target)
        and not localactionblocked()
        and not Data.IsRespawning
        and character == session.Character
        and humanoid ~= nil
        and humanoid.Health >= 1
        and character:FindFirstChild('HumanoidRootPart') == session.Root
        and session.Root.Parent == character
        and session.Target.Character == session.TargetCharacter
        and session.TargetCharacter.Parent ~= nil
        and not isdead(session.Target)
        and MainEvent ~= nil
end
function phowg:auto_save_client_frame(session)
    local frame = session.ClientCFrame
    local root = session.Root
    if not Data.Flying and not Data.CSyncTable[2] and Data.MoveToInFlight ~= root then
        local humanoid = session.Character:FindFirstChildOfClass('Humanoid')
        if humanoid and (humanoid.MoveDirection.Magnitude > 0.01 or humanoid.Jump) then
            local current = root.CFrame
            local distance = (current.Position - frame.Position).Magnitude
            local elapsed = math.clamp(tick() - session.ClientFrameAt, 0, 0.25)
            local speed = math.max(humanoid.WalkSpeed, humanoid.JumpPower, 16)
            if distance == distance and distance <= speed * elapsed * 2 + 4 then
                frame = current
            end
        end
    end
    session.ClientCFrame, session.ClientFrameAt = frame, tick()
    return frame
end
function phowg:suspend_auto_save_neckgrab()
    local toggle = Toggles.neckgrab_enabled
    if toggle and toggle.Value then
        toggle:SetValue(false)
    end
    if phowg.stop_neckgrab then
        phowg:stop_neckgrab()
    end
end
function phowg:auto_save_arrived(session, root)
    if not phowg:auto_save_session_valid(session) or root ~= session.Root then
        return
    end
    local now = tick()
    local holding, carrying = phowg:auto_save_holding(session.Character, session.Target)
    if session.Stage == 'grab' then
        if holding or carrying or not isknocked(session.Target) then
            return
        end
        local torso = getreppart(session.TargetCharacter)
        if torso and (root.Position - torso.Position).Magnitude <= 10 and now - session.LastGrabAt >= 0.3 then
            session.LastGrabAt = now
            Data.LastGrabFireAt = now
            MainEvent:FireServer('Grabbing', false)
        end
    elseif session.Stage == 'carry' then
        if not holding then
            return
        end
        if (root.Position - session.Destination.Position).Magnitude > 2 then
            session.ArrivedAt, session.LastArrivalAt = nil, nil
            return
        end
        if not session.LastArrivalAt or now - session.LastArrivalAt > 0.25 then
            session.ArrivedAt = now
        end
        session.LastArrivalAt = now
        if now - session.ArrivedAt >= 1 then
            session.Stage = 'release'
            session.DroppedAt = now
            MainEvent:FireServer('Grabbing', false)
        end
    end
end
function phowg:refresh_auto_save_movement()
    local session = Data.AutoSaveSession
    if not session or not phowg:auto_save_session_valid(session) then
        return
    end
    local destination = session.Destination
    if session.Stage == 'grab' then
        local torso = getreppart(session.TargetCharacter)
        if not torso then
            phowg:cancel_auto_save()
            return
        end
        destination = CFrame.new(torso.Position + Vector3.new(0, 3.5, 0))
    end
    session.MovementStage = session.Stage
    set_server_cframe(destination, nil, Data.PRIO.SAVING, 'Saving', false, nil, session.OnArrive)
end
phowg:register_cleanup('auto save', function(scope)
    local session = Data.AutoSaveSession
    if
        not scope
        or scope == LocalPlayer.Character
        or session and (scope == session.Character or scope == session.Target or scope == session.TargetCharacter)
    then
        phowg:cancel_auto_save()
    end
end)
function auto_save()
    local session = Data.AutoSaveSession
    if not phowg:auto_save_enabled() or localactionblocked() or Data.IsRespawning or not MainEvent then
        if session or Data.Saving then
            phowg:cancel_auto_save()
        end
        return
    end
    if not session then
        local character = LocalPlayer.Character
        local root = character and character:FindFirstChild('HumanoidRootPart')
        local humanoid = character and character:FindFirstChildOfClass('Humanoid')
        if not root or not humanoid or humanoid.Health < 1 then
            return
        end
        local origin = (Data.CSyncTable[2] or Data.MoveToInFlight == root) and Data.CSyncTable[1] or root.CFrame
        local mode = Options.save_location and Options.save_location.Value or 'client pos'
        if type(mode) == 'table' then
            mode = (mode.food or mode[1] == 'food') and 'food'
                or (mode.void or mode[1] == 'void') and 'void'
                or 'client pos'
        end
        local destination = origin
        if mode == 'food' then
            local ignored = Workspace:FindFirstChild('Ignored')
            local shop = ignored and ignored:FindFirstChild('Shop')
            if shop then
                for _, item in ipairs(shop:GetChildren()) do
                    local name = string.lower(item.Name)
                    for _, query in ipairs({
                        'donut',
                        'latte',
                        'starblox',
                        'pizza',
                        'taco',
                        'chicken',
                        'burger',
                        'lettuce',
                    }) do
                        if string.find(name, query, 1, true) then
                            local head = item:FindFirstChild('Head') or item:FindFirstChildWhichIsA('BasePart')
                            if head then
                                destination = CFrame.new(head.Position + Vector3.new(0, 3, 0))
                                break
                            end
                        end
                    end
                    if destination ~= origin then
                        break
                    end
                end
            end
            if destination == origin then
                destination = CFrame.new(-338, 24, -297)
            end
        elseif mode == 'void' then
            destination = CFrame.new(3305, -450, -265)
            if Options.teleport_style and Options.teleport_style.Value == 'hosted rage' then
                destination = CFrame.new(destination.Position - Vector3.new(0, 10, 0))
                    * CFrame.Angles(0, 0, math.rad(180))
            end
        end
        Data.SaveCooldown = Data.SaveCooldown or {}
        local minDistance = Options.save_min_distance and Options.save_min_distance.Value or 0
        local target, distance = nil, math.huge
        local now = tick()
        for player, whitelisted in pairs(Data.IsraelWhitelist or {}) do
            if
                whitelisted == true
                and player ~= LocalPlayer
                and player.Parent
                and now - (Data.SaveCooldown[player] or -math.huge) >= 2
                and isknocked(player)
                and not isdead(player)
            then
                local targetCharacter = player.Character
                local torso = targetCharacter and getreppart(targetCharacter)
                local holding, carrying = phowg:auto_save_holding(character, player)
                if
                    torso
                    and targetCharacter.Parent
                    and (not carrying or holding)
                    and (not targetCharacter:FindFirstChild('GRABBING_CONSTRAINT', true) or holding)
                then
                    local fromOrigin = (torso.Position - origin.Position).Magnitude
                    if
                        fromOrigin >= minDistance
                        and fromOrigin < distance
                        and (torso.Position - destination.Position).Magnitude >= 15
                    then
                        target, distance = player, fromOrigin
                    end
                end
            end
        end
        if not target then
            return
        end
        session = {
            Target = target,
            TargetCharacter = target.Character,
            Character = character,
            Root = root,
            Destination = destination,
            ClientCFrame = origin,
            ClientFrameAt = tick(),
            Stage = 'grab',
            LastGrabAt = -math.huge,
        }
        session.OnArrive = function(arrivedRoot)
            phowg:auto_save_arrived(session, arrivedRoot)
        end
        Data.AutoSaveSession, Data.Saving = session, true
        Data.CurrentSaveTarget, Data.SaveOriginCF = target, origin
        phowg:suspend_auto_save_neckgrab()
        unequipall()
        Library:Notify('saving ' .. Library:PlayerDisplayName(target), Library.NotifyDuration or 3)
    end
    if not phowg:auto_save_session_valid(session) then
        phowg:cancel_auto_save()
        return
    end
    phowg:suspend_auto_save_neckgrab()
    local holding, carrying = phowg:auto_save_holding(session.Character, session.Target)
    if session.Stage == 'grab' then
        if holding then
            session.Stage = 'carry'
        elseif carrying or not isknocked(session.Target) then
            phowg:cancel_auto_save()
            return
        end
    elseif session.Stage == 'carry' and not holding then
        phowg:cancel_auto_save()
        return
    elseif session.Stage == 'release' and tick() - session.DroppedAt >= 0.5 then
        Data.SaveCooldown[session.Target] = tick()
        local saved = not holding
        phowg:cancel_auto_save()
        if saved then
            Library:Notify('done.', Library.NotifyDuration or 3)
        end
        return
    end
    if session.MovementStage ~= session.Stage then
        phowg:refresh_auto_save_movement()
    end
end
function phowg:selected_grenade_type()
    local kind = Options.grenade_type and Options.grenade_type.Value
    return (kind == 'flashbang' or kind == 'teargas') and kind or 'grenade'
end
function phowg:grenade_target_allowed(target, kind)
    if not target or target == LocalPlayer or not target.Parent or iswhitelistedplayer(target) then
        return false
    end
    local character = target.Character
    local humanoid = character and character:FindFirstChildOfClass('Humanoid')
    if
        not character
        or not character.Parent
        or not humanoid
        or humanoid.Health <= 0
        or not character:FindFirstChild('HumanoidRootPart')
        or isknocked(target)
        or isdead(target)
        or isstomped(target)
    then
        return false
    end
    if kind ~= 'flashbang' then
        if character:FindFirstChildOfClass('ForceField') then
            return false
        end
        for _, name in ipairs({ 'Forcefield', 'ForceField', 'FORCEFIELD' }) do
            local value = character:FindFirstChild(name)
            if value and (not value:IsA('BoolValue') or value.Value ~= false) then
                return false
            end
        end
    end
    return true
end
function phowg:grenade_throw_target(kind)
    local sticky = get_sticky_target()
    if sticky then
        return phowg:grenade_target_allowed(sticky, kind) and sticky or nil
    end
    if not (rageboton() or punishmentactive()) then
        return nil
    end
    local current = Data.CurrentActionTarget
    if phowg:grenade_target_allowed(current, kind) then
        return current
    end
    for _, target in ipairs(gettargetlist()) do
        if phowg:grenade_target_allowed(target, kind) then
            return target
        end
    end
    return nil
end
function phowg:stop_auto_grenade_throw(job)
    local active = Data.AutoGrenadeThrowJob
    if not active or job and active ~= job then
        return
    end
    Data.AutoGrenadeThrowJob = nil
    phowg:release_equipment('grenade', active.Tool)
end
function phowg:auto_throw_grenade()
    if
        Data.AutoGrenadeThrowJob
        or Data.NukeGrenadeJob
        or Data.Buying
        or Data.Sorting
        or Data.BuildActive
        or Data.LoadoutReloadJob
        or phowg:equipment_owner()
        or localactionblocked()
    then
        return false
    end
    local kind = phowg:selected_grenade_type()
    local target = phowg:grenade_throw_target(kind)
    local character = LocalPlayer.Character
    local targetCharacter = target and target.Character
    local function valid()
        return Toggles.auto_throw_grenade
            and Toggles.auto_throw_grenade.Value
            and not Library.Unloaded
            and not Data.SharedSignalsClosed
            and not Data.IsRespawning
            and LocalPlayer.Character == character
            and character
            and character.Parent
            and not localactionblocked()
            and phowg:selected_grenade_type() == kind
            and target
            and target.Character == targetCharacter
            and phowg:grenade_throw_target(kind) == target
    end
    if not valid() then
        return false
    end
    local function find_tool()
        for _, container in ipairs({ character, LocalPlayer:FindFirstChild('Backpack') }) do
            for _, tool in ipairs(container:GetChildren()) do
                if tool:IsA('Tool') and normalizeweaponname(tool.Name) == kind then
                    return tool
                end
            end
        end
        return nil
    end
    local job, thrown
    local ok, problem = pcall(function()
        local tool = find_tool()
        if not tool then
            purchase_item(kind, Data.PRIO.AMMO, 1, true, nil, valid)
            if not valid() then
                return
            end
            tool = find_tool()
        end
        if not tool or not valid() then
            return
        end
        job = {
            Character = character,
            Target = target,
            TargetCharacter = targetCharacter,
            Tool = tool,
            StartedAt = tick(),
        }
        Data.AutoGrenadeThrowJob = job
        local accepted = phowg:request_equipment('grenade', tool, 'exclusive')
        if not accepted or tool.Parent ~= character then
            return
        end
        Data.EquipmentLease = { Owner = 'grenade', Tool = tool, Character = character, Until = tick() + 0.5 }
        phowg:stop_gun_fire()
        local function equipped()
            return Data.AutoGrenadeThrowJob == job and tool.Parent == character and valid()
        end
        task.wait(0.05)
        if not equipped() then
            return
        end
        tool:Activate()
        task.wait(0.05)
        if not equipped() then
            return
        end
        tool:Activate()
        Data.AutoGrenadeNextThrowAt = job.StartedAt + 1
        thrown = true
    end)
    if job then
        phowg:stop_auto_grenade_throw(job)
    end
    if not ok and not Library.Unloaded and tick() >= (Data.AutoGrenadeErrorAt or 0) then
        Data.AutoGrenadeErrorAt = tick() + 5
        warn('[Phowg] auto throw grenade: ' .. tostring(problem))
    end
    return thrown == true
end
function autothrowgrenadeloop()
    while
        Toggles.auto_throw_grenade
        and Toggles.auto_throw_grenade.Value
        and not Library.Unloaded
        and not Data.SharedSignalsClosed
    do
        if tick() >= (Data.AutoGrenadeNextThrowAt or 0) then
            phowg:auto_throw_grenade()
        end
        task.wait(math.clamp((Data.AutoGrenadeNextThrowAt or 0) - tick(), 0.1, 1))
    end
    phowg:stop_auto_grenade_throw()
end
phowg:register_cleanup('auto throw grenade', function(scope)
    local job = Data.AutoGrenadeThrowJob
    if not scope or job and (scope == job.Character or scope == job.TargetCharacter or scope == job.Tool) then
        phowg:stop_auto_grenade_throw(job)
    end
end)
function flashbangeveryoneloop()
    while Toggles.flashbang_everyone and Toggles.flashbang_everyone.Value and rageboton() do
        if localactionblocked() then
            task.wait(0.05)
            continue
        end
        if LocalPlayer.Character and getroot(LocalPlayer.Character) then
            local Targets = gettargetlist()
            if #Targets == 0 then
                for _, Plr in ipairs(Players:GetPlayers()) do
                    if Plr ~= LocalPlayer and intelligence:get_character_cache(Plr) and not isknocked(Plr) then
                        table.insert(Targets, Plr)
                    end
                end
            end
            for _, Target in ipairs(Targets) do
                if not (Toggles.flashbang_everyone and Toggles.flashbang_everyone.Value) then
                    break
                end
                if intelligence:get_character_cache(Target) and not isknocked(Target) then
                    Data['SingleLockedTarget'] = Target
                    local Tool = findtoolbypattern('flashbang')
                    if not Tool then
                        purchase_item('flashbang', Data['PRIO'].AMMO)
                        Tool = findtoolbypattern('flashbang')
                    end
                    if Tool then
                        equip(Tool)
                        task.wait(0.05)
                        if Tool.Parent == LocalPlayer.Character then
                            if not localactionblocked() then
                                Tool:Activate()
                            end
                            task.wait(0.05)
                            if not localactionblocked() then
                                Tool:Activate()
                            end
                        end
                    end
                    task.wait(1)
                end
            end
        end
        task.wait(0.5)
    end
end
function phowg:china_hack_mode()
    return not Library.Unloaded
        and not Data.SharedSignalsClosed
        and Options.gun_shoot_method
        and Options.gun_shoot_method.Value == 'china hack'
end
function phowg:china_remote_burst()
    local value = tonumber(Options.china_remote_burst and Options.china_remote_burst.Value) or 8
    if value ~= value then
        value = 8
    end
    if value == math.huge or value == -math.huge then
        value = 8
    end
    return math.max(1, math.floor(value))
end
function phowg:invalidate_china_gun_cache(tool)
    for _, other in pairs({ Data.SupportLoadout, Data.RapidFireState }) do
        if tool and other.Parts then
            other.Parts[tool] = nil
        end
    end
    local state = Data.ChinaHackState
    if not state then
        return
    end
    state.CacheDirty = true
    state.CacheRevision = (state.CacheRevision or 0) + 1
    if tool and state.Parts then
        state.Parts[tool] = nil
    end
end
function phowg:china_tool_parts(tool, state)
    if not tool or not tool:IsA('Tool') then
        return nil
    end
    state = state or Data.ChinaHackState
    if not state then
        return nil
    end
    state.Parts = state.Parts or setmetatable({}, { __mode = 'k' })
    local parts = state.Parts[tool]
    if
        parts
        and parts.Handle
        and parts.Ammo
        and parts.MaxAmmo
        and parts.Client
        and parts.Handle.Parent == tool
        and parts.Ammo.Parent == tool
        and parts.MaxAmmo.Parent == tool
        and parts.Client.Parent == tool
    then
        return parts
    end
    local handle, ammo, maximum =
        tool:FindFirstChild('Handle'), tool:FindFirstChild('Ammo'), tool:FindFirstChild('MaxAmmo')
    local client = tool:FindFirstChild('GunClient')
        or tool:FindFirstChild('GunClientAutomatic')
        or tool:FindFirstChild('GunClientShotgun')
        or tool:FindFirstChild('GunClientBurst')
        or tool:FindFirstChild('GunClientAutomaticShotgun')
    if not handle or not handle:IsA('BasePart') or not ammo or not maximum or not client then
        return nil
    end
    parts = {
        Handle = handle,
        Ammo = ammo,
        MaxAmmo = maximum,
        Client = client,
        Reload = tool:FindFirstChild('Reloading') or tool:FindFirstChild('Reload'),
    }
    state.Parts[tool] = parts
    return parts
end
function phowg:china_gun(tool)
    if Data.ChinaHackState then
        return phowg:china_tool_parts(tool) ~= nil
    end
    if not tool or not tool:IsA('Tool') or not phowg:tool_equip_ready(tool) or not tool:FindFirstChild('Ammo') then
        return false
    end
    return tool:FindFirstChild('GunClient') ~= nil
        or tool:FindFirstChild('GunClientAutomatic') ~= nil
        or tool:FindFirstChild('GunClientShotgun') ~= nil
        or tool:FindFirstChild('GunClientBurst') ~= nil
        or tool:FindFirstChild('GunClientAutomaticShotgun') ~= nil
end
function phowg:china_equipped_tools(state)
    if not state.CachedTools or state.CacheDirty or state.CachedCharacter ~= state.Character then
        state.CachedTools = {}
        state.CacheDirty = false
        state.CachedCharacter = state.Character
        for _, tool in ipairs(state.Character:GetChildren()) do
            if tool:IsA('Tool') then
                if hookammotool then
                    hookammotool(tool)
                end
                if phowg:china_tool_parts(tool, state) then
                    state.CachedTools[#state.CachedTools + 1] = tool
                end
            end
        end
        if phowg.combat_runtime then
            phowg:combat_runtime().CacheBuilds += 1
        end
    end
    return state.CachedTools
end
function phowg:china_pair_selected()
    return phowg:china_hack_mode() and not Data.PunishmentGunActive and #phowg:ragebot_gun_names() > 1
end
function phowg:china_multi_active(validatedTarget, validatedHead)
    local state = Data.ChinaHackState
    if not state then
        return false
    end
    local head
    if state.MultiTarget == validatedTarget then
        head = validatedHead
    else
        head = phowg:china_target_valid(state.MultiTarget)
    end
    return state
        and not state.Closed
        and state.Character == LocalPlayer.Character
        and phowg:china_hack_mode()
        and phowg:china_pair_selected()
        and not state.Suspended
        and state.MultiTarget
        and state.MultiTarget.Character == state.MultiCharacter
        and head
        and phowg:ragebot_action_enabled('auto_kill')
        and (rageboton() or Data.PunishmentGunActive)
end
function phowg:china_tools(state)
    local pack = LocalPlayer:FindFirstChildOfClass('Backpack')
    state.Guns = state.Guns or {}
    for _, name in ipairs(phowg:ragebot_gun_names()) do
        local record = state.Guns[name]
        local tool = record and record.Tool
        if
            not tool
            or (tool.Parent ~= state.Character and tool.Parent ~= pack)
            or normalizeweaponname(tool.Name) ~= name
            or not phowg:china_gun(tool)
        then
            tool = nil
            for _, container in pairs({ state.Character, pack }) do
                for _, candidate in ipairs(container:GetChildren()) do
                    if
                        candidate:IsA('Tool')
                        and normalizeweaponname(candidate.Name) == name
                        and phowg:china_gun(candidate)
                    then
                        tool = candidate
                        break
                    end
                end
                if tool then
                    break
                end
            end
            state.Guns[name] = { Tool = tool }
        end
    end
    for name in pairs(state.Guns) do
        local keep = false
        for _, selected in ipairs(phowg:ragebot_gun_names()) do
            if name == selected then
                keep = true
                break
            end
        end
        if not keep then
            state.Guns[name] = nil
        end
    end
    return state.Guns
end
function phowg:prune_ragebot_guns(character)
    if
        not character
        or character ~= LocalPlayer.Character
        or Data.GunReloadSelection
        or Data.LoadoutReloadJob
        or Data.Sorting
        or Data.Buying
        or Data.MaskBuying
    then
        return
    end
    local pack = LocalPlayer:FindFirstChild('Backpack')
    if not pack then
        return
    end
    local cache = phowg:china_hack_mode() and Data.ChinaHackState
    local revision = cache and (cache.CacheRevision or 0)
    if cache and cache.LastPruneRevision == revision then
        return
    end
    local meleeMode = phowg:ragebot_melee_weapon(Options.auto_kill_weapon and Options.auto_kill_weapon.Value)
    local meleeTool = meleeMode and getweapontool(meleeMode)
    local pending = false
    for _, tool in ipairs(character:GetChildren()) do
        local equippedGun = phowg:china_hack_mode()
            and tool:IsA('Tool')
            and tool:FindFirstChild('Ammo')
            and (phowg:is_gun_weapon(tool.Name) or phowg:china_gun(tool))
        if tool:IsA('Tool') and tool ~= meleeTool and not phowg:is_ragebot_gun_selected(tool) and not equippedGun then
            if not phowg:request_equipment('ragebot', tool, 'unequip') then
                pending = true
            end
        end
    end
    if cache and not pending then
        cache.LastPruneRevision = cache.CacheRevision or 0
    end
end
function phowg:queue_ragebot_tool_prune(character)
    if
        not character
        or character ~= LocalPlayer.Character
        or Data.RagebotPruneQueued == character
        or not rageboton()
        or not phowg:ragebot_action_enabled('auto_kill')
    then
        return
    end
    Data.RagebotPruneQueued = character
    task.defer(function()
        if Data.RagebotPruneQueued ~= character then
            return
        end
        Data.RagebotPruneQueued = nil
        if
            not Library.Unloaded
            and not Library.ConfigLoading
            and not Data.SharedSignalsClosed
            and character == LocalPlayer.Character
            and rageboton()
            and phowg:ragebot_action_enabled('auto_kill')
        then
            phowg:prune_ragebot_guns(character)
        end
    end)
end
function phowg:maintain_ragebot_void_tools(state)
    if
        not state
        or state.Closed
        or state.Character ~= LocalPlayer.Character
        or not phowg:china_pair_selected()
        or not rageboton()
        or not phowg:ragebot_action_enabled('auto_kill')
        or localshootblocked()
        or phowg:purchase_blocks_shooting()
        or Data.Sorting
        or Data.LoadoutReloadJob
        or Data.GunReloadSelection
    then
        return
    end
    if Data.RagebotIdle or not phowg:china_target_valid(state.MultiTarget) then
        return
    end
    phowg:prune_ragebot_guns(state.Character)
    for _, record in pairs(phowg:china_tools(state)) do
        local tool = record.Tool
        if tool then
            state.Equipped[tool] = true
            if Data.RagebotIdle then
                Data.RagebotIdle.Equipped[tool] = true
            end
            if tool.Parent ~= state.Character then
                tool.Parent = state.Character
            end
        end
    end
end
function phowg:china_maintain_tools(state, active)
    if active == nil then
        active = phowg:china_multi_active()
    end
    if
        state.Suspended
        or not active
        or phowg:purchase_blocks_shooting()
        or Data.Sorting
        or Data.LoadoutReloadJob
        or Data.GunReloadSelection
        or localshootblocked()
    then
        return
    end
    if Data.RagebotIdle or not phowg:china_target_valid(state.MultiTarget) then
        return
    end
    phowg:prune_ragebot_guns(state.Character)
    for _, record in pairs(phowg:china_tools(state)) do
        local tool = record.Tool
        if tool then
            state.Equipped[tool] = true
            if tool.Parent ~= state.Character then
                phowg:request_equipment('ragebot', tool, 'equip')
            end
        end
    end
end
function phowg:china_prepare_target(target)
    local state = Data.ChinaHackState
    if not state or phowg:gun_shoot_method('Ragebot', target) ~= 'china hack' or not phowg:china_target_valid(target) then
        return
    end
    if not phowg:china_pair_selected() then
        if state.MultiTarget then
            phowg:china_release_extra()
        end
        return
    end
    phowg:cancel_backpack_reload()
    state.Suspended = false
    state.PairFinished = nil
    state.MultiTarget, state.MultiCharacter = target, target.Character
    phowg:china_maintain_tools(state)
    local guns = phowg:china_tools(state)
    for _, name in ipairs(phowg:ragebot_gun_names()) do
        if not guns[name].Tool and not Data.Buying and phowg.queue_ragebot_purchase then
            phowg:queue_ragebot_purchase(name, Data.PRIO.KNIFE, nil, target)
            break
        end
    end
end
function phowg:china_release_extra()
    local state = Data.ChinaHackState
    local pack = LocalPlayer:FindFirstChild('Backpack')
    if not state or state.Releasing then
        return
    end
    local target = state.MultiTarget
    local hadTools = target ~= nil or next(state.Equipped) ~= nil
    state.Releasing = true
    state.Suspended = true
    if target and not phowg:china_target_valid(target) then
        state.PairFinished = true
    end
    state.MultiTarget, state.MultiCharacter = nil, nil
    local tools = {}
    if pack and state.Character == LocalPlayer.Character then
        for _, tool in ipairs(state.Character:GetChildren()) do
            if tool:IsA('Tool') and (state.Equipped[tool] or hadTools and phowg:china_gun(tool)) then
                tools[#tools + 1] = tool
            end
        end
    end
    if hadTools then
        phowg:invalidate_tool_restores()
        local held = Data.HeldGunFire
        if held and held.ChinaHack and held.Owner == 'Ragebot' then
            phowg:stop_gun_fire('Ragebot')
        end
    end
    for _, tool in ipairs(tools) do
        if tool.Parent == state.Character then
            tool.Parent = pack
        end
    end
    table.clear(state.Equipped)
    state.Releasing = nil
end
function phowg:china_target_valid(target)
    if target and phowg:current_sticky_shot(target) then
        if not phowg:sticky_shoot_allowed(target) or not phowg:sticky_character(target) then
            return false
        end
        local head = target.Character:FindFirstChild('Head')
        return head and head:IsA('BasePart') and phowg:perfect_hit_vector(head.Position) and head or false
    end
    if
        not target
        or target == LocalPlayer
        or not target.Parent
        or not target.Character
        or isdead(target)
        or isknocked(target)
    then
        return false
    end
    if
        iswhitelistedplayer(target)
        or iscrewwhitelisted(target)
        or Data.RageWhitelist and Data.RageWhitelist[target]
    then
        return false
    end
    if target.Character:FindFirstChildOfClass('ForceField') then
        return false
    end
    if target.Character:FindFirstChild('GRABBING_CONSTRAINT') then
        return false
    end
    local head = target.Character:FindFirstChild('Head')
    return head and head:IsA('BasePart') and phowg:perfect_hit_vector(head.Position) and head or false
end
function phowg:china_shot_context(target, validatedHead)
    if not phowg:smart_attack_ready(target, Data.HeldGunFire and Data.HeldGunFire.Owner) then
        return nil
    end
    local state = Data.ChinaHackState
    local character = LocalPlayer.Character
    if
        not state
        or state.Closed
        or state.Character ~= character
        or phowg:gun_shoot_method(Data.HeldGunFire and Data.HeldGunFire.Owner, target) ~= 'china hack'
    then
        return nil
    end
    if
        localshootblocked()
        or isreloading()
        or phowg:purchase_blocks_shooting()
        or phowg:support_armor_blocked(target)
        or Data.RPGMoveActive
    then
        return nil
    end
    local head = validatedHead or phowg:china_target_valid(target)
    if not head then
        return nil
    end
    local remote = MainEvent
    if not remote or not remote.Parent then
        remote = ReplicatedStorage:FindFirstChild('MainEvent')
        MainEvent = remote
    end
    if not remote then
        return nil
    end
    local solution = phowg.perfect_hit_solution and phowg:perfect_hit_solution(target, nil, head)
    local point = solution and solution.Point or predpos(head.Position, target.Character)
    if not phowg:perfect_hit_vector(point) then
        return nil
    end
    local source = Data.HeldGunFire and Data.HeldGunFire.Owner
    if not source and phowg.get_gun_shot_target then
        local _, _, _, owner = phowg:get_gun_shot_target()
        source = owner
    end
    return {
        State = state,
        Character = character,
        Target = target,
        TargetCharacter = target.Character,
        Head = head,
        Point = point,
        Remote = remote,
        Source = source,
    }
end
function phowg:china_shot_pellets(tool)
    local name = normalizeweaponname(tool.Name)
    if name ~= 'doublebarrelsg' and name ~= 'shotgun' and name ~= 'tacticalshotgun' and name ~= 'drumshotgun' then
        return 1, nil, nil
    end
    local stamp = Workspace:GetServerTimeNow()
    if type(Data.NativeShotgunSpread) == 'function' then
        local ok, offsets = pcall(Data.NativeShotgunSpread, tool.Name)
        if ok and type(offsets) == 'table' and #offsets == 5 then
            return 5, offsets, stamp
        end
    end
    local custom = Toggles.custom_spread and Toggles.custom_spread.Value
    local state = Data.GunModuleHooks and Data.GunModuleHooks.Spread
    local module = custom and state and state.Enabled and state.Module
    local seed = LocalPlayer:GetAttribute('ShotgunSpreadKey')
    if module and type(module.roll) == 'function' and type(seed) == 'number' then
        Data.ChinaSpreadSequence = (Data.ChinaSpreadSequence or 0) + 1
        local ok, offsets = pcall(module.roll, seed, Data.ChinaSpreadSequence, true, tool.Name)
        if ok and type(offsets) == 'table' and #offsets == 5 then
            return 5, offsets, stamp
        end
    end
    local percent = custom and tonumber(Options.custom_spread_amount and Options.custom_spread_amount.Value) or 100
    if not percent or percent ~= percent then
        percent = 100
    end
    local scale = math.clamp(percent, 0, 100) / 100 * (name == 'drumshotgun' and 0.756 or 1)
    local offsets = table.create(5)
    for index = 1, 5 do
        offsets[index] = scale == 0 and Vector3.zero
            or Vector3.new(
                    (math.random() * 2 - 1) * 0.05,
                    (math.random() * 2 - 1) * 0.1,
                    (math.random() * 2 - 1) * 0.05
                )
                * scale
    end
    return 5, offsets, stamp
end
function phowg:china_spread_point(_tool, origin, point, offset)
    if not phowg:perfect_hit_vector(offset) or offset.Magnitude == 0 or offset.Magnitude > 2 then
        return point
    end
    local delta = point - origin
    if delta.Magnitude < 0.001 then
        return point
    end
    return origin + (delta.Unit + offset) * delta.Magnitude
end
function phowg:restore_china_weapon_recoil(state)
    local joint = state.RecoilJoint
    if joint and joint.Parent and state.RecoilApplied and joint.C0 == state.RecoilApplied then
        joint.C0 = state.RecoilBase
    end
    state.RecoilJoint, state.RecoilBase, state.RecoilApplied, state.RecoilAngle, state.RecoilAt =
        nil, nil, nil, nil, nil
end
function phowg:china_weapon_kick(state, handle, now)
    if not handle or not phowg:tool_grip_allowed(handle.Parent) then
        return
    end
    local joint = state.RecoilJoint
    if not joint or not joint.Parent or joint.Part1 ~= handle then
        phowg:restore_china_weapon_recoil(state)
        local character = state.Character
        local hand = character:FindFirstChild('RightHand') or character:FindFirstChild('Right Arm')
        if not hand then
            return
        end
        for _, candidate in ipairs(hand:GetChildren()) do
            if candidate:IsA('JointInstance') and candidate.Part1 == handle then
                joint = candidate
                break
            end
        end
        if not joint or not joint.Parent or joint.Part1 ~= handle then
            return
        end
        state.RecoilJoint, state.RecoilBase = joint, joint.C0
    end
    local elapsed = now - (state.RecoilAt or now)
    local amount = (state.RecoilAngle or 0) * math.exp(-math.max(0, elapsed - 0.08) * 10)
    local automatic = handle.Parent:FindFirstChild('GunClientAutomatic')
        or handle.Parent:FindFirstChild('GunClientAutomaticShotgun')
    state.RecoilAngle = math.min(math.rad(14), amount + math.rad(automatic and 1.5 or 2.5))
    state.RecoilAt = now
end
function phowg:update_china_weapon_recoil(delta)
    if type(delta) == 'number' and delta > 0 and delta < 1 then
        Data.CombatFrameMs = (Data.CombatFrameMs or delta * 1000) * 0.9 + delta * 1000 * 0.1
    end
    local now = tick()
    for handle, state in pairs(Data.ChinaShotEffects or {}) do
        local joint = state.RecoilJoint
        if joint then
            if
                not joint.Parent
                or handle.Parent == nil
                or handle.Parent.Parent ~= LocalPlayer.Character
                or state.Character ~= LocalPlayer.Character
            then
                phowg:restore_china_weapon_recoil(state)
            else
                if state.RecoilApplied and joint.C0 ~= state.RecoilApplied then
                    state.RecoilBase = joint.C0
                end
                local age = math.max(0, now - (state.RecoilAt or now) - 0.08)
                local angle = (state.RecoilAngle or 0) * math.exp(-age * 10)
                if angle < 0.0001 then
                    phowg:restore_china_weapon_recoil(state)
                else
                    state.RecoilApplied = state.RecoilBase * CFrame.Angles(angle, 0, 0)
                    joint.C0 = state.RecoilApplied
                end
            end
        end
    end
end
phowg:register_render(phowg_callbacks.update_china_weapon_recoil, RunService, 'frame/china weapon recoil')
function phowg:clear_china_shot_effects(handle)
    local state = Data.ChinaShotEffects and Data.ChinaShotEffects[handle]
    if not state then
        return
    end
    Data.ChinaShotEffects[handle] = nil
    phowg:restore_china_weapon_recoil(state)
    for _, object in ipairs(state.Objects) do
        pcall(object.Destroy, object)
    end
    local flash = state.Flash
    if flash and flash.Parent then
        flash.Visible, flash.Size, flash.ImageTransparency =
            state.FlashVisible, state.FlashSize, state.FlashTransparency
    end
end
function phowg:china_shot_muzzle(state, handle, suppressed)
    local tool = handle.Parent
    local skin = handle:GetAttribute('SkinName')
    local assets = ReplicatedStorage:FindFirstChild('SkinAssets')
    local particles = assets and assets:FindFirstChild('GunSkinMuzzleParticle')
    local key = type(skin) == 'string' and skin ~= '' and skin or tool.Name
    local template = not suppressed and particles and particles:FindFirstChild(key)
    local default = tool:FindFirstChild('Default')
    local mesh = default and default:FindFirstChild('Mesh')
    local muzzle = mesh and mesh:FindFirstChild('Muzzle') or handle:FindFirstChild('Muzzle')
    if state.MuzzleTemplate ~= template or state.Muzzle ~= muzzle then
        for index = #state.Objects, 1, -1 do
            local object = state.Objects[index]
            if object:IsA('ParticleEmitter') then
                object:Destroy()
                table.remove(state.Objects, index)
            end
        end
        table.clear(state.Emitters)
        state.MuzzleTemplate, state.Muzzle = template, muzzle
        if template and muzzle then
            local source = template:FindFirstChild('Muzzle')
            local different = source and source:FindFirstChild('Different_GunMuzzle')
            if different then
                source = different:FindFirstChild(tool.Name)
            end
            local children = source and source:GetChildren() or template:GetChildren()
            if not source and #children > 0 then
                children = { children[math.random(#children)] }
            end
            for _, child in ipairs(children) do
                if child:IsA('ParticleEmitter') and #state.Emitters < 16 then
                    local clone = child:Clone()
                    clone.Enabled, clone.Parent = false, muzzle
                    state.Objects[#state.Objects + 1] = clone
                    state.Emitters[#state.Emitters + 1] = {
                        Object = clone,
                        Count = math.clamp(
                            tonumber(child:GetAttribute('EmitCount')) or (source and 1 or child.Rate),
                            0,
                            100
                        ),
                    }
                end
            end
        end
    end
    for _, emitter in ipairs(state.Emitters) do
        if emitter.Object.Parent and emitter.Count > 0 then
            emitter.Object:Emit(math.max(1, math.floor(emitter.Count * (Data.CosmeticQuality or 1))))
        end
    end
    if not state.Light then
        local light = Instance.new('PointLight')
        light.Name, light.Brightness, light.Range, light.Shadows = 'PhowgShotLight', 0.5, 0, false
        light.Color, light.Enabled, light.Parent = Color3.new(1, 1, 1), false, handle
        state.Light = light
        state.Objects[#state.Objects + 1] = light
    end
    state.Light.Enabled, state.Light.Range = not suppressed, suppressed and 0 or 15
    state.FlashActive = false
    local gui = handle:FindFirstChild('ShootBBGUI')
    local flash = gui and gui:FindFirstChild('Shoot')
    if flash and flash:IsA('ImageLabel') and not suppressed and #state.Emitters == 0 then
        if state.Flash ~= flash then
            state.Flash, state.FlashVisible, state.FlashSize, state.FlashTransparency =
                flash, flash.Visible, flash.Size, flash.ImageTransparency
        end
        state.FlashActive = true
        flash.Visible, flash.Size, flash.ImageTransparency = true, UDim2.fromScale(0, 0), 1
    end
end
function phowg:china_shot_sound(state, handle, suppressed)
    local now = tick()
    if now - (state.SoundAt or -math.huge) < 1 / phowg:visual_number('shot_sound_rate', 20, 5, 60) - 0.000001 then
        return
    end
    local source = handle:FindFirstChild('ShootSound')
    if not source or not source:IsA('Sound') then
        return
    end
    state.SoundAt = now
    local customId, customVolume = convertsound(source, handle.Parent)
    local id, speed = customId or source.SoundId, source.PlaybackSpeed
    if suppressed and not customId then
        id = source:GetAttribute('DefaultSoundId') or id
        speed = source:GetAttribute('DefaultPlaybackSpeed') or speed
    elseif not customId then
        local sequence = source:GetAttribute('SequenceSFX')
        if type(sequence) == 'string' then
            if state.Sequence ~= sequence then
                state.Sequence, state.SequenceIds = sequence, {}
                for value in sequence:gmatch('%d+') do
                    state.SequenceIds[#state.SequenceIds + 1] = value
                end
            end
            if #state.SequenceIds > 0 then
                local index = (tonumber(source:GetAttribute('CurrentSequence')) or 0) + 1
                source:SetAttribute('CurrentSequence', index)
                id = 'rbxassetid://' .. state.SequenceIds[index % #state.SequenceIds + 1]
            end
        end
    end
    local voices = math.floor(phowg:visual_number('shot_sound_voices', 4, 1, 8))
    while #state.Sounds > voices do
        local removed = table.remove(state.Sounds)
        removed:Stop()
        removed:Destroy()
        local index = table.find(state.Objects, removed)
        if index then
            table.remove(state.Objects, index)
        end
        state.NextSound = 0
    end
    local sound
    for _, candidate in ipairs(state.Sounds) do
        if candidate.Parent and not candidate.IsPlaying then
            sound = candidate
            break
        end
    end
    if not sound then
        if #state.Sounds < voices then
            sound = source:Clone()
            sound.Name, sound.Looped, sound.PlayOnRemove, sound.Parent = 'PhowgChinaShotSound', false, false, handle
            state.Sounds[#state.Sounds + 1] = sound
            state.Objects[#state.Objects + 1] = sound
        else
            state.NextSound = state.NextSound % #state.Sounds + 1
            sound = state.Sounds[state.NextSound]
        end
    end
    sound:Stop()
    sound.SoundId, sound.Volume, sound.PlaybackSpeed = id, customVolume or source.Volume, speed
    sound.TimePosition = 0
    sound:Play()
end
function phowg:play_china_shot_effects(handle)
    local character = LocalPlayer.Character
    if
        Library.Unloaded
        or Data.SharedSignalsClosed
        or not character
        or not handle
        or not handle.Parent
        or handle.Parent.Parent ~= character
    then
        return
    end
    Data.ChinaShotEffects = Data.ChinaShotEffects or {}
    local state, now = Data.ChinaShotEffects[handle], tick()
    if state and state.Character ~= character then
        phowg:clear_china_shot_effects(handle)
        state = nil
    end
    if not state then
        state = { Character = character, At = -math.huge, Objects = {}, Emitters = {}, Sounds = {}, NextSound = 0 }
        Data.ChinaShotEffects[handle] = state
    end
    if now - state.At < 1 / phowg:visual_number('shot_effect_rate', 20, 5, 60) - 0.000001 then
        return
    end
    state.At = now
    pcall(phowg_callbacks.china_weapon_kick, state, handle, now)
    local tool = handle.Parent
    tool:SetAttribute('LocalLastShotAt', os.clock())
    character:SetAttribute('LocalLastFiredGun', tool.Name)
    character:SetAttribute('LocalLastGunShotAt', os.clock())
    if now - (Data.ChinaShotAnimationAt or -math.huge) >= 0.05 - 0.000001 and type(shared.playerShot) == 'function' then
        Data.ChinaShotAnimationAt = now
        pcall(shared.playerShot, handle)
    end
    local suppressed = LocalPlayer:GetAttribute('GunFX') == true
    pcall(phowg_callbacks.china_shot_sound, state, handle, suppressed)
    pcall(phowg_callbacks.china_shot_muzzle, state, handle, suppressed)
end
registerheartbeat(
    'ChinaShotEffects',
    function()
        local effects = Data.ChinaShotEffects
        if Library.Unloaded or Data.SharedSignalsClosed or type(effects) ~= 'table' then
            return
        end
        local now = tick()
        for handle, state in pairs(effects) do
            local age = now - state.At
            if
                not handle.Parent
                or handle.Parent.Parent ~= LocalPlayer.Character
                or state.Character ~= LocalPlayer.Character
                or age > 5
            then
                phowg:clear_china_shot_effects(handle)
            else
                if state.Light then
                    state.Light.Range = math.max(0, 15 * (1 - age / 0.4))
                    if age >= 0.4 then
                        state.Light.Enabled = false
                    end
                end
                local flash = state.Flash
                if flash and flash.Parent then
                    if not state.FlashActive then
                        flash.Visible = false
                    elseif age < 0.4 then
                        local blend = Service.TweenService:GetValue(
                            math.clamp(age / 0.4, 0, 1),
                            Enum.EasingStyle.Bounce,
                            Enum.EasingDirection.In
                        )
                        flash.Size, flash.ImageTransparency = UDim2.fromScale(blend, blend), 1 - 0.6 * blend
                    elseif age < 0.6 then
                        flash.ImageTransparency = 0.4 + 0.6 * ((age - 0.4) / 0.2)
                    else
                        flash.Visible = false
                    end
                end
            end
        end
    end,
    1 / 30,
    function()
        return not Library.Unloaded
            and not Data.SharedSignalsClosed
            and type(Data.ChinaShotEffects) == 'table'
            and next(Data.ChinaShotEffects) ~= nil
    end,
    true
)
phowg:register_cleanup('china shot effects', function(scope, reason)
    for handle, state in pairs(Data.ChinaShotEffects or {}) do
        if
            reason == 'unload'
            or not scope
            or scope == state.Character
            or handle == scope
            or handle:IsDescendantOf(scope)
        then
            phowg:clear_china_shot_effects(handle)
        end
    end
    if reason == 'unload' then
        Data.ChinaShotEffects, Data.ChinaShotAnimationAt = nil, nil
    end
end)
function phowg:china_shoot(tool, target, context: any)
    if
        phowg.combat_can_fire
        and not phowg:combat_can_fire(Data.HeldGunFire and Data.HeldGunFire.Owner or 'china', tool, target)
    then
        return false
    end
    if phowg.combat_ammo_paused and phowg:combat_ammo_paused() then
        return false
    end
    context = context or phowg:china_shot_context(target)
    if
        not context
        or context.Target ~= target
        or not tool
        or tool.Parent ~= context.Character
        or Data.SupportGunReloads and Data.SupportGunReloads[tool]
    then
        return false
    end
    if context.TargetCharacter and (not target or target.Character ~= context.TargetCharacter) then
        return false
    end
    local state = context.State
    local parts = phowg:china_tool_parts(tool, state)
    if not parts then
        return false
    end
    if parts.Ammo.Value <= 0 or parts.Reload and parts.Reload.Value == true then
        if phowg.set_combat_state then
            phowg:set_combat_state(
                'reloading',
                tool.Name .. (parts.Ammo.Value <= 0 and ' needs ammo' or ' is reloading'),
                Data.HeldGunFire and Data.HeldGunFire.Owner or 'china',
                target
            )
        end
        return false
    end
    local handle, head, point = parts.Handle, context.Head, context.Point
    if phowg.perfect_bullet_allowed and not phowg:perfect_bullet_allowed(head) then
        return false
    end
    local origin = handle.Position
    if not phowg:perfect_hit_vector(origin) then
        return false
    end
    if phowg:around_wallbang_enabled(target, context.Source) then
        origin = gunshootorigin(handle, origin)
        origin = phowg:resolve_wallbang_origin(tool, target, origin, point, context.Source)
        if not origin then
            return false
        end
    end
    local count, offsets, stamp = phowg:china_shot_pellets(tool)
    local pendingShot = phowg.stage_gun_shot and phowg:stage_gun_shot(tool, target)
    local previousEmission = Data.ChinaRemoteEmission
    Data.ChinaRemoteEmission = tool
    local fired, visualPoint, sentCount = false, point, 0
    for index = 1, count do
        local pelletPoint = phowg:china_spread_point(tool, origin, point, offsets and offsets[index])
        if phowg.randomize_sticky_bullet then
            pelletPoint = phowg:randomize_sticky_bullet(
                pelletPoint,
                target,
                context.Source or Data.HeldGunFire and Data.HeldGunFire.Owner
            )
        end
        local sent
        if count > 1 then
            sent = pcall(
                context.Remote.FireServer,
                context.Remote,
                'ShootGun',
                handle,
                origin,
                pelletPoint,
                head,
                Vector3.new(0, 1, 0),
                stamp
            )
        else
            sent = pcall(
                context.Remote.FireServer,
                context.Remote,
                'ShootGun',
                handle,
                origin,
                pelletPoint,
                head,
                Vector3.new(0, 1, 0)
            )
        end
        if not sent then
            if phowg.combat_runtime then
                phowg:combat_runtime().Errors += 1
            end
            break
        end
        sentCount += 1
        if not fired then
            visualPoint = pelletPoint
        end
        fired = true
    end
    Data.ChinaRemoteEmission = previousEmission
    if not fired then
        if pendingShot then
            phowg:discard_gun_shot(tool, pendingShot)
        end
        return false
    end
    if phowg.record_combat_request then
        phowg:record_combat_request(tool, sentCount, true, target)
    end
    if phowg.set_combat_state then
        phowg:set_combat_state('firing', 'killing', Data.HeldGunFire and Data.HeldGunFire.Owner or 'china', target)
    end
    if not context.Visualized or not context.Visualized[tool] then
        if context.Visualized then
            context.Visualized[tool] = true
        end
        if phowg.capture_bullet_shot then
            pcall(phowg_callbacks.capture_bullet_shot, handle, origin, visualPoint, true)
        end
        if phowg.play_china_shot_effects then
            pcall(phowg_callbacks.play_china_shot_effects, handle)
        end
    end
    Data.RecentlyShotAt = tick()
    if Data.PunishmentTargets and Data.PunishmentTargets[target] then
        Data.SupportTargetSessions = Data.SupportTargetSessions or {}
        local session = Data.SupportTargetSessions[target] or {}
        Data.SupportTargetSessions[target] = session
        session.Tool, session.Character = tool, context.Character
    end
    return true
end
function phowg:support_multi_selected(target, owner)
    if not phowg:israel_support_enabled() then
        return false
    end
    return #phowg:ragebot_gun_names() > 1
            and (owner == 'Support' or Data.PunishmentGunActive == true or target and Data.PunishmentTargets and Data.PunishmentTargets[target] ~= nil)
        or false
end
function phowg:clear_support_loadout()
    local state = Data.SupportLoadout
    Data.SupportLoadout = nil
    if not state then
        return
    end
    local held = Data.HeldGunFire
    if held and held.SupportMulti then
        phowg:stop_gun_fire(held.Owner)
    end
    local pack = LocalPlayer:FindFirstChild('Backpack')
    if pack and state.Character == LocalPlayer.Character then
        for tool in pairs(state.Equipped) do
            if tool.Parent == state.Character then
                phowg:deactivate_tool(tool)
                tool.Parent = pack
            end
        end
    end
end
function phowg:prepare_support_loadout(target, owner)
    if
        not phowg:support_multi_selected(target, owner)
        or not phowg:china_target_valid(target)
        or localshootblocked()
        or phowg:purchase_blocks_shooting()
        or Data.Sorting
        or Data.LoadoutReloadJob
        or Data.GunReloadSelection
    then
        return nil
    end
    local character = LocalPlayer.Character
    local selection = table.concat(phowg:ragebot_gun_names(), '|')
    local state = Data.SupportLoadout
    if
        state
        and (
            state.Character ~= character
            or state.Target ~= target
            or state.TargetCharacter ~= target.Character
            or state.Selection ~= selection
        )
    then
        phowg:clear_support_loadout()
        state = nil
    end
    if not state then
        state = {
            Character = character,
            Target = target,
            TargetCharacter = target.Character,
            Selection = selection,
            Owner = owner,
            Equipped = {},
            Parts = setmetatable({}, { __mode = 'k' }),
            ShotAt = setmetatable({}, { __mode = 'k' }),
        }
        Data.SupportLoadout = state
    end
    local pack = LocalPlayer:FindFirstChild('Backpack')
    if not pack then
        return nil
    end
    for _, tool in ipairs(character:GetChildren()) do
        if tool:IsA('Tool') and not phowg:is_ragebot_gun_selected(tool) then
            phowg:request_equipment('support', tool, 'unequip')
        end
    end
    for _, name in ipairs(phowg:ragebot_gun_names()) do
        local tool = getweapontool(name)
        if tool and phowg:china_gun(tool) then
            state.Equipped[tool] = true
            if tool.Parent == pack then
                phowg:request_equipment('support', tool, 'equip')
            end
        elseif not tool and not Data.Buying and phowg.queue_ragebot_purchase then
            Data.CurrentActionTarget = target
            phowg:queue_ragebot_purchase(name, Data.PRIO.KNIFE, nil, target)
        end
    end
    return state
end
function phowg:fire_support_loadout(owner, target, interval)
    if
        not phowg:smart_attack_ready(target, owner)
        or isreloading()
        or phowg:support_armor_blocked(target)
        or Data.RPGMoveActive
    then
        return false
    end
    local state = phowg:prepare_support_loadout(target, owner)
    if not state then
        return false
    end
    local remote = MainEvent
    local head = phowg:china_target_valid(target)
    if not remote or not remote.Parent or not head then
        return false
    end
    local solution = phowg.perfect_hit_solution and phowg:perfect_hit_solution(target, nil, head)
    local point = solution and solution.Point or predpos(head.Position, target.Character)
    if not phowg:perfect_hit_vector(point) then
        return false
    end
    local fired = false
    local primary
    for _, name in ipairs(phowg:ragebot_gun_names()) do
        local tool = getweapontool(name)
        if tool and tool.Parent == state.Character then
            local ammo = tool:FindFirstChild('Ammo')
            if ammo and ammo.Value > 0 then
                primary = primary or tool
                if tick() - (state.ShotAt[tool] or -math.huge) >= math.max(0, interval or 0) then
                    local context = {
                        State = state,
                        Character = state.Character,
                        Target = target,
                        TargetCharacter = target.Character,
                        Head = head,
                        Point = point,
                        Remote = remote,
                        Source = owner,
                    }
                    if phowg:china_shoot(tool, target, context) then
                        state.ShotAt[tool] = tick()
                        fired = true
                        local session = Data.SupportTargetSessions and Data.SupportTargetSessions[target]
                        if session then
                            session.Multi = true
                            session.Tools = session.Tools or {}
                            session.Tools[tool] = true
                        end
                    end
                end
            elseif ammo and not phowg:reload_pending(state.Character) then
                phowg:request_gun_reload(tool, remote)
            end
        end
    end
    if primary then
        local held = Data.HeldGunFire
        if held and (held.Owner ~= owner or held.Target ~= target or not held.SupportMulti) then
            phowg:stop_gun_fire()
            held = nil
        end
        if not held then
            held = {
                Owner = owner,
                ShootMethod = 'perfect hit',
                SupportMulti = true,
                Character = state.Character,
                Target = target,
                TargetCharacter = target.Character,
                Guns = setmetatable({}, { __mode = 'k' }),
            }
            Data.HeldGunFire = held
        end
        held.Tool = primary
    end
    return fired or primary ~= nil
end
registerheartbeat(
    'SupportLoadout',
    function()
        local state = Data.SupportLoadout
        if
            state
            and (
                Library.Unloaded
                or Data.SharedSignalsClosed
                or state.Character ~= LocalPlayer.Character
                or not phowg:support_multi_selected(state.Target, state.Owner)
                or not phowg:china_target_valid(state.Target)
                or state.Target.Character ~= state.TargetCharacter
                or state.Selection ~= table.concat(phowg:ragebot_gun_names(), '|')
                or state.Owner == 'Ragebot' and not Data.PunishmentGunActive
                or state.Owner == 'Support'
                    and (not phowg:israel_support_enabled() or not (Toggles.full_rage and Toggles.full_rage.Value))
            )
        then
            phowg:clear_support_loadout()
        end
    end,
    0.05,
    function()
        return Data.SupportLoadout ~= nil
    end
)
phowg:register_cleanup('support shared loadout', function(scope, reason)
    local state = Data.SupportLoadout
    if state and (not scope or reason == 'unload' or scope == state.Character or scope == state.TargetCharacter) then
        phowg:clear_support_loadout()
    end
end)
function phowg:china_fire_gun(owner, tool, target)
    if owner ~= 'Ragebot' and owner ~= 'Support' and owner ~= 'KillAura' then
        return false
    end
    local state = Data.ChinaHackState
    if
        not state
        or state.Closed
        or state.Character ~= LocalPlayer.Character
        or phowg:gun_shoot_method(owner, target) ~= 'china hack'
        or not phowg:china_target_valid(target)
    then
        phowg:stop_gun_fire(owner)
        return false
    end
    if
        localshootblocked()
        or isreloading()
        or phowg:purchase_blocks_shooting()
        or phowg:support_armor_blocked(target)
        or Data.RPGMoveActive
    then
        phowg:stop_gun_fire(owner)
        return false
    end
    local held = Data.HeldGunFire
    local priorities = { Ragebot = 30, Support = 20, KillAura = 10, FullAuto = 0 }
    if held and (priorities[held.Owner] or 0) > (priorities[owner] or 0) then
        return false
    end
    if
        not held
        or not held.ChinaHack
        or held.Owner ~= owner
        or held.Tool ~= tool
        or held.Target ~= target
        or held.Character ~= state.Character
        or held.TargetCharacter ~= target.Character
    then
        phowg:stop_gun_fire()
        held = {
            Owner = owner,
            Tool = tool,
            Target = target,
            Character = state.Character,
            TargetCharacter = target.Character,
            ChinaHack = true,
            Guns = nil :: any,
        }
        Data.HeldGunFire = held
    end
    if owner == 'Ragebot' and phowg:china_pair_selected() then
        state.Suspended = false
        state.PairFinished = nil
        state.MultiTarget, state.MultiCharacter = target, target.Character
    end
    held.RequestedAt = tick()
    return true
end
function phowg:set_china_hack()
    phowg:stop_gun_fire()
    phowg:set_character_observer('china hack', phowg:china_hack_mode(), function(state, character)
        state.Equipped = {}
        Data.ChinaHackState = state
        local function repair(tool)
            phowg:invalidate_china_gun_cache(tool:IsA('Tool') and tool or nil)
            if state.RepairQueued or not tool:IsA('Tool') then
                return
            end
            state.RepairQueued = true
            task.defer(function()
                state.RepairQueued = nil
                if not state.Closed and Data.ChinaHackState == state then
                    phowg:china_maintain_tools(state)
                end
            end)
        end
        state.Connections.ToolsAdded = connectshared(
            character.ChildAdded,
            repair,
            character,
            'china hack/equip repair',
            0,
            'event/ChildAdded',
            character
        )
        state.Connections.ToolsRemoved = connectshared(
            character.ChildRemoved,
            repair,
            character,
            'china hack/unequip repair',
            0,
            'event/ChildRemoved',
            character
        )
        local pack = LocalPlayer:FindFirstChild('Backpack')
        if pack then
            state.Connections.BackpackAdded =
                connectshared(pack.ChildAdded, repair, pack, 'china hack/backpack repair', 0, 'event/ChildAdded', pack)
        end
        state.Restore = function()
            phowg:china_release_extra()
            state.MultiTarget, state.MultiCharacter = nil, nil
            Data.ChinaTracerTimes = nil
            for tool in pairs(state.Equipped) do
                if tool.Parent == character and pack and pack.Parent then
                    tool.Parent = pack
                end
            end
            table.clear(state.Equipped)
            if Data.ChinaHackState == state then
                Data.ChinaHackState = nil
            end
        end
    end)
    if phowg.set_full_auto then
        phowg:set_full_auto(Toggles.full_auto and Toggles.full_auto.Value)
    end
end
function phowg:change_shoot_method()
    phowg:sync_ragebot_weapon_mode()
    if phowg.clear_ragebot_idle then
        phowg:clear_ragebot_idle()
    end
    local held = Data.HeldGunFire
    local owner, target = held and held.Owner, held and held.Target
    local priorTool = held and held.Tool
    phowg:stop_gun_fire()
    Data.PerfectHitLastResult = nil
    Data.RedirectGunShots = setmetatable({}, { __mode = 'k' })
    Data.CombatArrivalAt, Data.CombatArrivalLastAt, Data.CombatArrivalTool = nil, nil, nil
    if phowg.set_china_hack then
        phowg:set_china_hack()
    end
    if phowg.update_bullet_capture then
        phowg:update_bullet_capture()
    end
    if
        target
        and target.Character
        and (owner == 'Ragebot' or owner == 'Support')
        and not Data.Buying
        and not Data.Sorting
        and not localactionblocked()
    then
        if phowg:china_hack_mode() then
            if owner == 'Ragebot' then
                phowg:china_prepare_target(target)
            end
        else
            local name = phowg:auto_kill_gun_mode()
            if held.ChinaHack and not phowg:is_gun_weapon(name) and priorTool then
                name = normalizeweaponname(priorTool.Name)
                local option = Options.auto_kill_weapon
                if option and option.SetValue then
                    option:SetValue(name)
                end
            end
            local tool = getweapontool(name)
            if tool and tool.Parent ~= LocalPlayer.Character then
                equip(tool)
            end
        end
    end
    if Toggles.rapid_fire and Toggles.rapid_fire.Value then
        stoprapidfire()
        rapidfire()
    end
end
function phowg:ragebot_weapons_changed()
    phowg:clear_melee_replication_root()
    phowg:sync_ragebot_weapon_mode()
    if Data.ChinaHackState then
        Data.ChinaHackState.LastPruneRevision = nil
    end
    if Library.ConfigLoading then
        return
    end
    phowg:stop_gun_fire('Ragebot')
    phowg:stop_gun_fire('Support')
    if phowg.clear_support_loadout then
        phowg:clear_support_loadout()
    end
    if phowg.clear_ragebot_idle then
        phowg:clear_ragebot_idle()
    end
    if phowg.china_release_extra then
        phowg:china_release_extra()
    end
    phowg:cancel_backpack_reload()
    if phowg.clear_ragebot_void_spam then
        phowg:clear_ragebot_void_spam()
    end
    Data.RagebotPurchase, Data.RagebotArrival, Data.RagebotBait, Data.RagebotBaitTargets = nil, nil, nil, nil
    Data.RagebotArrivalFireAt, Data.RagebotArrivalFireTarget = nil, nil
    Data.CombatArrivalAt, Data.CombatArrivalLastAt, Data.CombatArrivalTool = nil, nil, nil
    Data.CombatAmmoPause, Data.CombatAmmoRetryAt = nil, nil
    local pending = Data.GunReloadPending
    if pending and not phowg:is_ragebot_gun_selected(pending.Tool) then
        Data.GunReloadPending = nil
    end
    if rageboton() or punishmentactive() then
        ragebot_on()
    end
end
function phowg:china_reload_tool(tool, target)
    local state = Data.ChinaHackState
    if
        not state
        or state.Closed
        or tool.Parent ~= state.Character
        or localshootblocked()
        or Data.Buying
        or Data.Sorting
    then
        return
    end
    local ammo = tool:FindFirstChild('Ammo')
    local reload = tool:FindFirstChild('Reloading') or tool:FindFirstChild('Reload')
    if not ammo or ammo.Value > 0 or reload and reload.Value == true then
        return
    end
    state.ReloadAt = state.ReloadAt or setmetatable({}, { __mode = 'k' })
    if tick() - (state.ReloadAt[tool] or -math.huge) < 1 then
        return
    end
    if isreloading() or Data.GunReloadSelection or phowg:reload_pending(state.Character) then
        return
    end
    local reserve = getgunreserve(tool)
    if reserve ~= nil and reserve <= 0 then
        state.ReloadAt[tool] = tick()
        phowg:queue_ragebot_purchase(
            ammoshopname(tool.Name),
            Data.PRIO.AMMO,
            Options.ammo_buy_count and Options.ammo_buy_count.Value or 5,
            target
        )
    else
        local remote = MainEvent or ReplicatedStorage:FindFirstChild('MainEvent')
        if phowg:request_gun_reload(tool, remote) then
            state.ReloadAt[tool] = tick()
        end
    end
end
function phowg:update_china_fire()
    if Library.ConfigLoading then
        return
    end
    local state = Data.ChinaHackState
    if not state or state.Closed or state.Character ~= LocalPlayer.Character then
        return
    end
    if Data.RagebotIdle or Data.VoidActive or reloadvoidactive() then
        phowg:maintain_ragebot_void_tools(state)
        if Data.RagebotIdle then
            return
        end
    end
    local spam = Data.RagebotVoidSpam
    local spamOwnsTools = spam
        and Data.Settings.VoidSpam
        and spam.Target == state.MultiTarget
        and spam.Character == state.Character
        and tick() - (spam.LastAt or -math.huge) < 0.25
    if state.MultiTarget and spamOwnsTools and phowg:china_multi_active() then
        phowg:china_maintain_tools(state, true)
    end
    local held = Data.HeldGunFire
    if not held or not held.ChinaHack then
        if
            state.MultiTarget
            and phowg:china_multi_active()
            and (Data.CurrentActionTarget == state.MultiTarget or spamOwnsTools or isreloading())
        then
            phowg:china_maintain_tools(state)
        elseif state.MultiTarget then
            phowg:china_release_extra()
        end
        return
    end
    if phowg.combat_ammo_paused and phowg:combat_ammo_paused() then
        phowg:stop_gun_fire(held.Owner)
        return
    end
    local head = phowg:china_target_valid(held.Target)
    if
        not head
        or held.TargetCharacter ~= held.Target.Character
        or phowg:gun_shoot_method(held.Owner, held.Target) ~= 'china hack'
    then
        phowg:stop_gun_fire(held.Owner)
        phowg:china_release_extra()
        return
    end
    if tick() - (held.RequestedAt or 0) >= 0.3 then
        phowg:stop_gun_fire(held.Owner)
        if
            state.MultiTarget
            and phowg:china_multi_active()
            and rageboton()
            and Data.CurrentActionTarget == state.MultiTarget
        then
            phowg:china_maintain_tools(state)
        else
            phowg:china_release_extra()
        end
        return
    end
    local multi = held.Owner == 'Ragebot' and phowg:china_multi_active(held.Target, head)
    if multi then
        phowg:china_maintain_tools(state, multi)
    elseif state.MultiTarget then
        phowg:china_release_extra()
        return
    elseif held.Owner == 'Ragebot' then
        phowg:prune_ragebot_guns(state.Character)
    end
    local context: { [string]: any }? = phowg:china_shot_context(held.Target, head)
    if not context then
        phowg:stop_gun_fire(held.Owner)
        return
    end
    if not multi then
        local tool = held.Tool
        local backpack = LocalPlayer:FindFirstChild('Backpack')
        if
            tool
            and tool.Parent == backpack
            and phowg:tool_equip_ready(tool)
            and not Data.GunReloadSelection
            and not Data.Sorting
            and not Data.LoadoutReloadJob
        then
            phowg:request_equipment('combat', tool, 'equip')
        end
    end
    local tools, empty = {}, {}
    for _, tool in ipairs(phowg:china_equipped_tools(state)) do
        if tool:IsA('Tool') and (held.Owner ~= 'KillAura' or tool == held.Tool) and phowg:china_gun(tool) then
            local ammo = phowg:china_tool_parts(tool, state).Ammo
            if ammo and ammo.Value > 0 then
                tools[#tools + 1] = tool
            else
                empty[#empty + 1] = tool
            end
        end
    end
    context.Visualized = {}
    local maximum = phowg:china_remote_burst()
    local cursor = #tools > 0 and (state.FireCursor or 0) % #tools or 0
    for _round = 1, maximum do
        if
            Data.HeldGunFire ~= held
            or localshootblocked()
            or isreloading()
            or phowg:purchase_blocks_shooting()
            or Data.RPGMoveActive
        then
            break
        end
        for index = 1, #tools do
            local tool = tools[(cursor + index - 1) % #tools + 1]
            phowg:china_shoot(tool, held.Target, context)
        end
    end
    state.FireCursor = cursor + 1
    if Data.HeldGunFire == held and #empty > 0 then
        phowg:china_reload_tool(empty[1], held.Target)
    end
    if multi and not Data.Buying then
        local guns = phowg:china_tools(state)
        for _, name in ipairs(phowg:ragebot_gun_names()) do
            if not guns[name].Tool then
                phowg:queue_ragebot_purchase(name, Data.PRIO.KNIFE, nil, held.Target)
                break
            end
        end
    end
end
registerheartbeat('ChinaHack', phowg.update_china_fire, nil, phowg.china_hack_mode)

function phowg:simple_rapid_fire_mode()
    return phowg:china_hack_mode() and not Data.PunishmentGunActive and true or false
end
function phowg:simple_rapid_fire_active()
    local state = Data.RapidFireState
    return not Library.Unloaded
        and not Data.SharedSignalsClosed
        and state
        and state.Simple
        and state.Active
        and state.Character == LocalPlayer.Character
        and Toggles.rapid_fire
        and Toggles.rapid_fire.Value
        and phowg:simple_rapid_fire_mode()
end
function phowg:start_simple_rapid_fire()
    local character = LocalPlayer.Character
    local state: { [string]: any } =
        { Simple = true, Active = true, Character = character, Tools = {}, Connections = {}, Containers = {} }
    Data.RapidFireState = state
    local function owned(tool)
        return tool.Parent ~= nil
            and (tool.Parent == character or tool.Parent == LocalPlayer:FindFirstChild('Backpack'))
    end
    local function restore(tool, record)
        if record.Ready and tool.ManualActivationOnly == true then
            tool.ManualActivationOnly = record.ManualActivationOnly
        end
        record.Ready = false
    end
    local function bind_values(tool, record)
        local ammo = tool:FindFirstChild('Ammo')
        local reload = tool:FindFirstChild('Reloading') or tool:FindFirstChild('Reload')
        if record.Ammo == ammo and record.Reload == reload then
            return
        end
        for _, connection in ipairs(record.ValueConnections or {}) do
            connection:Disconnect()
        end
        record.ValueConnections = {}
        record.Ammo, record.Reload = ammo, reload
        local function changed()
            record.HasAmmo = ammo ~= nil and type(ammo.Value) == 'number' and ammo.Value > 0
            record.Reloading = reload ~= nil and reload.Value == true
        end
        for _, value in pairs({ Ammo = ammo, Reload = reload }) do
            record.ValueConnections[#record.ValueConnections + 1] = connectshared(
                value:GetPropertyChangedSignal('Value'),
                changed,
                value,
                'simple rapid/readiness',
                0,
                'property/Value',
                value
            )
        end
        changed()
    end
    local function prepare(tool, record)
        if phowg:china_gun(tool) then
            bind_values(tool, record)
            record.Automatic = tool:FindFirstChild('GunClientAutomatic') ~= nil
                or tool:FindFirstChild('GunClientAutomaticShotgun') ~= nil
            if not record.Ready then
                record.ManualActivationOnly = tool.ManualActivationOnly
                phowg:deactivate_tool(tool)
                tool.ManualActivationOnly = true
                record.Ready = true
            end
        else
            restore(tool, record)
        end
    end
    state.Release = function(tool)
        local record = state.Tools[tool]
        if not record then
            return
        end
        state.Tools[tool] = nil
        for _, connection in ipairs(record.Connections) do
            connection:Disconnect()
        end
        for _, connection in ipairs(record.ValueConnections or {}) do
            connection:Disconnect()
        end
        restore(tool, record)
    end
    local function track(tool)
        if not state.Active or Data.RapidFireState ~= state or not tool:IsA('Tool') or not owned(tool) then
            return
        end
        local record = state.Tools[tool]
        if not record then
            record = { Connections = {}, Ready = false }
            state.Tools[tool] = record
            local function changed(child)
                if
                    state.Active
                    and state.Tools[tool] == record
                    and (
                        child.Name == 'Ammo'
                        or child.Name == 'MaxAmmo'
                        or child.Name == 'Handle'
                        or child.Name == 'GunClient'
                        or child.Name == 'GunClientAutomatic'
                        or child.Name == 'GunClientShotgun'
                        or child.Name == 'GunClientBurst'
                        or child.Name == 'GunClientAutomaticShotgun'
                        or child.Name == 'Reloading'
                        or child.Name == 'Reload'
                    )
                then
                    prepare(tool, record)
                end
            end
            record.Connections[1] =
                connectshared(tool.ChildAdded, changed, tool, 'simple rapid/tool ready', 0, 'event/ChildAdded', tool)
            record.Connections[2] = connectshared(
                tool.ChildRemoved,
                changed,
                tool,
                'simple rapid/tool changed',
                0,
                'event/ChildRemoved',
                tool
            )
            record.Connections[3] = connectshared(tool.AncestryChanged, function()
                if state.Active and not owned(tool) then
                    state.Release(tool)
                end
            end, tool, 'simple rapid/tool released', 0, 'event/AncestryChanged', tool)
        end
        prepare(tool, record)
    end
    state.Refresh = function()
        if not state.Active or Data.RapidFireState ~= state or character ~= LocalPlayer.Character then
            return
        end
        if character then
            for _, tool in ipairs(character:GetChildren()) do
                if tool:IsA('Tool') and not state.Tools[tool] then
                    track(tool)
                end
            end
        end
        for tool, record in pairs(state.Tools) do
            if not owned(tool) then
                state.Release(tool)
            elseif not record.Ready then
                prepare(tool, record)
            end
        end
    end
    if character then
        state.Connections[1] = connectshared(
            character.ChildAdded,
            track,
            character,
            'simple rapid/equipped',
            0,
            'event/ChildAdded',
            character
        )
    end
    state.Connections[#state.Connections + 1] = connectshared(LocalPlayer.CharacterAdded, function(nextCharacter)
        if state.Active and nextCharacter ~= character then
            stoprapidfire()
            if Toggles.rapid_fire and Toggles.rapid_fire.Value then
                rapidfire()
            end
        end
    end, LocalPlayer, 'simple rapid/respawn', 0, 'event/CharacterAdded', LocalPlayer)
    state.Refresh()
end
function phowg:simple_rapid_shot_context(state, tool, remote)
    local handle, range = tool:FindFirstChild('Handle'), tool:FindFirstChild('Range')
    local camera = Workspace.CurrentCamera
    if not camera or not handle or not phowg:perfect_hit_vector(handle.Position) then
        return nil
    end
    local distance = phowg:redirect_range(range and tonumber(range.Value))
    local params = state.RaycastParams
    if not params then
        params = RaycastParams.new()
        params.FilterType, params.IgnoreWater = Enum.RaycastFilterType.Exclude, true
        state.RaycastParams = params
    end
    if not state.FrameFilterReady then
        local ignored = { state.Character }
        for _, name in ipairs({ 'Ignored', 'Vehicles' }) do
            local folder = Workspace:FindFirstChild(name)
            if folder then
                ignored[#ignored + 1] = folder
            end
        end
        for _, player in ipairs(Players:GetPlayers()) do
            local character = player.Character
            local flight = character and character:FindFirstChild('BatmanFlight')
            if
                character
                and (
                    character:GetAttribute('AdminInvisible') == true
                    or character:GetAttribute('BatmanFlight') == true
                        and flight
                        and flight:GetAttribute('HumanoidFlight') ~= true
                )
            then
                ignored[#ignored + 1] = character
            end
        end
        params.FilterDescendantsInstances = ignored
        state.FrameFilterReady = true
    end
    local origin, direction
    if _G.MobileShiftLock or _G.MobleAimingIn then
        origin, direction = camera.CFrame.Position, camera.CFrame.LookVector
    else
        state.Mouse = state.Mouse or LocalPlayer:GetMouse()
        local ray = camera:ScreenPointToRay(state.Mouse.X, state.Mouse.Y)
        origin, direction = ray.Origin, ray.Direction
    end
    local aimHit = Workspace:Raycast(origin, direction * distance, params)
    local point = aimHit and aimHit.Position or origin + direction * distance
    local delta = point - handle.Position
    if delta.Magnitude < 0.001 then
        return nil
    end
    local hit = Workspace:Raycast(handle.Position, delta.Unit * math.min(delta.Magnitude, distance), params)
    local part = hit and hit.Instance
    local model = part and part:FindFirstAncestorOfClass('Model')
    local target = model and Players:GetPlayerFromCharacter(model)
    return {
        State = state,
        Character = state.Character,
        Target = target,
        TargetCharacter = target and target.Character,
        Head = part,
        Point = hit and hit.Position or handle.Position + delta.Unit * math.min(delta.Magnitude, distance),
        Remote = remote,
        Source = 'Manual',
        Visualized = {},
    }
end
function phowg:update_simple_rapid_fire()
    if not phowg:simple_rapid_fire_active() or Library.ConfigLoading then
        return
    end
    local state = Data.RapidFireState
    if not UserInputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton1) then
        state.Clicked = false
        return
    end
    if
        UserInputService:GetFocusedTextBox()
        or localshootblocked()
        or isreloading()
        or phowg:purchase_blocks_shooting()
        or Data.HeldGunFire
        or Data.RPGMoveActive
        or Data.RagebotIdle
        or Data.PunishmentGunActive
        or rageboton() and phowg:ragebot_action_enabled('auto_kill')
        or phowg.combat_ammo_paused and phowg:combat_ammo_paused()
    then
        return
    end
    local remote = MainEvent
    if not remote or not remote.Parent then
        remote = ReplicatedStorage:FindFirstChild('MainEvent')
        MainEvent = remote
    end
    if not remote then
        return
    end
    local target = phowg.get_gun_shot_target and phowg:get_gun_shot_target()
    local context: any
    if target and phowg:china_target_valid(target) then
        local chance = tonumber(Options.silent_aim_hit_chance and Options.silent_aim_hit_chance.Value) or 100
        if math.random(1, 100) <= math.clamp(chance, 0, 100) then
            context = phowg:china_shot_context(target)
            if not context then
                return
            end
        end
    end
    state.FrameFilterReady = false
    if context then
        context.Visualized = {}
    end
    local fired = false
    for tool, record in pairs(state.Tools) do
        if
            record.Ready
            and tool.Parent == state.Character
            and record.Ammo
            and record.Ammo.Parent == tool
            and record.HasAmmo
            and not record.Reloading
            and tick() >= (record.NextShotAt or 0)
        then
            local shot = context or phowg:simple_rapid_shot_context(state, tool, remote)
            if shot then
                local cooldown = tool:FindFirstChild('ShootingCooldown')
                local baseline = cooldown and tonumber(cooldown.Value)
                    or normalizeweaponname(tool.Name) == 'rifle' and 1.3095 or 0
                record.NextShotAt = tick() + baseline * phowg:rapid_fire_factor()
                for _round = 1, phowg:china_remote_burst() do
                    if not phowg:china_shoot(tool, shot.Target, shot) then
                        break
                    end
                    fired = true
                end
            end
        end
    end
    if fired then
        state.Clicked = true
    end
end
registerheartbeat('SimpleRapidFire', phowg.update_simple_rapid_fire, nil, phowg.simple_rapid_fire_active)
function fullautoloop(tool, character, state, stop)
    local job = { Closed = false, Tool = tool }
    job.Thread = task.defer(function()
        pcall(function()
            while
                not job.Closed
                and not state.Closed
                and not Library.Unloaded
                and not Data.SharedSignalsClosed
                and Toggles.full_auto.Value
                and LocalPlayer.Character == character
                and tool.Parent == character
                and tool:FindFirstChild('Ammo')
                and not UserInputService:GetFocusedTextBox()
                and UserInputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton1)
            do
                tool:Activate()
                task.wait()
                if not job.Closed and tool.Parent == character then
                    tool:Deactivate()
                end
            end
        end)
        if not job.Closed then
            stop()
        end
    end)
    return job
end
function phowg:set_full_auto(enabled)
    phowg:set_character_observer('full auto', enabled, function(state, character)
        local tool, job
        local held = UserInputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton1)
        local function stop()
            local previous = job
            job = nil
            if not previous then
                return
            end
            previous.Closed = true
            if previous.Thread and previous.Thread ~= coroutine.running() then
                pcall(task.cancel, previous.Thread)
            end
            phowg:deactivate_tool(previous.Tool)
        end
        local refresh
        refresh = function()
            if state.Closed or state.Character ~= LocalPlayer.Character then
                stop()
                return
            end
            local current = character:FindFirstChildOfClass('Tool')
            if current ~= tool then
                stop()
                for _, key in ipairs({ 'ToolAdded', 'ToolRemoved' }) do
                    if state.Connections[key] then
                        state.Connections[key]:Disconnect()
                        state.Connections[key] = nil
                    end
                end
                tool = current
                if tool then
                    state.Connections.ToolAdded = connectshared(
                        tool.ChildAdded,
                        refresh,
                        tool,
                        'full auto/tool ready',
                        0,
                        'event/ChildAdded',
                        tool
                    )
                    state.Connections.ToolRemoved = connectshared(
                        tool.ChildRemoved,
                        refresh,
                        tool,
                        'full auto/tool changed',
                        0,
                        'event/ChildRemoved',
                        tool
                    )
                end
            end
            if
                not held
                or not Toggles.full_auto.Value
                or not tool
                or not tool:FindFirstChild('Ammo')
                or tool:FindFirstChild('GunClientAutomatic')
                or tool:FindFirstChild('GunClientAutomaticShotgun')
                or UserInputService:GetFocusedTextBox()
                or not UserInputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton1)
            then
                stop()
                return
            end
            if not job then
                job = fullautoloop(tool, character, state, stop)
            end
        end
        state.Connections.Added = connectshared(character.ChildAdded, function(child)
            if child:IsA('Tool') then
                refresh()
            end
        end, character, 'full auto/equipped', 0, 'event/ChildAdded', character)
        state.Connections.Removed = connectshared(character.ChildRemoved, function(child)
            if child == tool then
                refresh()
            end
        end, character, 'full auto/unequipped', 0, 'event/ChildRemoved', character)
        state.Connections.InputBegan = connectshared(UserInputService.InputBegan, function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1 then
                held = true
                refresh()
            end
        end, UserInputService, 'full auto/press', 0, 'event/InputBegan', UserInputService)
        state.Connections.InputEnded = connectshared(UserInputService.InputEnded, function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1 then
                held = false
                stop()
            end
        end, UserInputService, 'full auto/release', 0, 'event/InputEnded', UserInputService)
        state.Connections.FocusLost = connectshared(UserInputService.WindowFocusReleased, function()
            held = false
            stop()
        end, UserInputService, 'full auto/focus lost', 0, 'event/WindowFocusReleased', UserInputService)
        state.Connections.TextFocused = connectshared(
            UserInputService.TextBoxFocused,
            stop,
            UserInputService,
            'full auto/typing',
            0,
            'event/TextBoxFocused',
            UserInputService
        )
        state.Connections.TextReleased = connectshared(
            UserInputService.TextBoxFocusReleased,
            refresh,
            UserInputService,
            'full auto/typing ended',
            0,
            'event/TextBoxFocusReleased',
            UserInputService
        )
        state.Restore = stop
        refresh()
    end)
end
function phowg:rapid_fire_factor()
    local value = tonumber(Options.rapid_fire_percent and Options.rapid_fire_percent.Value)
    if not value then
        value = Toggles.rapid_fire and Toggles.rapid_fire.Value and 1 or 100
    end
    return math.clamp(value, 0, 100) / 100
end
function phowg:scale_rapid_fire_value(value, baseline)
    local scaled = baseline * phowg:rapid_fire_factor()
    return value:IsA('IntValue') and math.round(scaled) or scaled
end
local function rapidfiregetupvalue(callback, index)
    local result = table.pack(pcall(debug.getupvalue, callback, index))
    if not result[1] then
        return nil
    end
    if result.n >= 3 then
        return result[3]
    end
    return result[2]
end
local function rapidfireclient(tool, callback)
    if type(callback) ~= 'function' or type(getfenv) ~= 'function' then
        return nil
    end
    if type(iscclosure) == 'function' then
        local inspected, native = pcall(iscclosure, callback)
        if not inspected or native then
            return nil
        end
    end
    local ok, environment = pcall(getfenv, callback)
    if not ok or type(environment) ~= 'table' then
        return nil
    end
    local client = rawget(environment, 'script')
    if typeof(client) ~= 'Instance' or client.Parent ~= tool or not client:IsA('LocalScript') then
        return nil
    end
    local name = client.Name
    if
        name ~= 'GunClient'
        and name ~= 'GunClientAutomatic'
        and name ~= 'GunClientBurst'
        and name ~= 'GunClientShotgun'
        and name ~= 'GunClientAutomaticShotgun'
    then
        return nil
    end
    return client
end
local function rapidfirecooldownslots(tool, callback, client)
    local handle = tool:FindFirstChild('Handle')
    local range = tool:FindFirstChild('Range')
    if not handle or not range or type(rapidfiregetupvalue(callback, 1)) ~= 'number' then
        return nil
    end
    if
        client.Name == 'GunClient'
        and normalizeweaponname(tool.Name) == 'rifle'
        and type(rapidfiregetupvalue(callback, 3)) == 'table'
        and type(rapidfiregetupvalue(callback, 3).getCanShoot) == 'function'
        and rapidfiregetupvalue(callback, 4) == LocalPlayer.Character
        and rapidfiregetupvalue(callback, 6) == handle
        and typeof(rapidfiregetupvalue(callback, 7)) == 'CFrame'
        and rapidfiregetupvalue(callback, 8) == tool
        and rapidfiregetupvalue(callback, 9) == range
        and rapidfiregetupvalue(callback, 10) == ReplicatedStorage
    then
        return { { Index = 1, Name = 'LastShotAt', Timestamp = true, Duration = 1.3095 } }
    end
    local handler = rapidfiregetupvalue(callback, 2)
    if
        type(handler) == 'table'
        and type(handler.getCanShoot) == 'function'
        and rapidfiregetupvalue(callback, 3) == LocalPlayer.Character
    then
        if client.Name == 'GunClientAutomatic' then
            if
                type(rapidfiregetupvalue(callback, 5)) ~= 'number'
                or rapidfiregetupvalue(callback, 6) ~= tool
                or rapidfiregetupvalue(callback, 7) ~= handle
                or typeof(rapidfiregetupvalue(callback, 8)) ~= 'CFrame'
                or rapidfiregetupvalue(callback, 9) ~= range
                or rapidfiregetupvalue(callback, 10) ~= ReplicatedStorage
            then
                return nil
            end
            return { { Index = 5, Name = 'ShootingCooldown' } }
        end
        if
            client.Name == 'GunClient'
            and rapidfiregetupvalue(callback, 5) == handle
            and typeof(rapidfiregetupvalue(callback, 6)) == 'CFrame'
            and rapidfiregetupvalue(callback, 7) == tool
            and rapidfiregetupvalue(callback, 8) == range
            and rapidfiregetupvalue(callback, 9) == ReplicatedStorage
        then
            return {}
        end
        return nil
    end
    handler = rapidfiregetupvalue(callback, 3)
    if
        type(handler) ~= 'table'
        or type(handler.getCanShoot) ~= 'function'
        or rapidfiregetupvalue(callback, 4) ~= LocalPlayer.Character
        or type(rapidfiregetupvalue(callback, 2)) ~= 'number'
    then
        return nil
    end
    if client.Name == 'GunClientBurst' then
        if
            rapidfiregetupvalue(callback, 7) ~= handle
            or typeof(rapidfiregetupvalue(callback, 8)) ~= 'CFrame'
            or rapidfiregetupvalue(callback, 9) ~= tool
            or rapidfiregetupvalue(callback, 10) ~= range
            or rapidfiregetupvalue(callback, 11) ~= ReplicatedStorage
            or type(rapidfiregetupvalue(callback, 12)) ~= 'number'
        then
            return nil
        end
        return { { Index = 2, Name = 'ToleranceCooldown' }, { Index = 12, Name = 'ShootingCooldown' } }
    end
    if client.Name ~= 'GunClient' and client.Name ~= 'GunClientShotgun' then
        return nil
    end
    local toolIndex = client.Name == 'GunClientShotgun' and 5 or 8
    if
        rapidfiregetupvalue(callback, toolIndex) ~= tool
        or rapidfiregetupvalue(callback, 6) ~= handle
        or typeof(rapidfiregetupvalue(callback, 7)) ~= 'CFrame'
        or rapidfiregetupvalue(callback, 9) ~= range
        or rapidfiregetupvalue(callback, 10) ~= ReplicatedStorage
    then
        return nil
    end
    return { { Index = 2, Name = 'ShootingCooldown' } }
end
local function restorerapidfireupvalues(callback, slots)
    for index, state in pairs(slots) do
        if rapidfiregetupvalue(callback, index) == (state.Applied or 0) then
            pcall(debug.setupvalue, callback, index, state.Value)
        end
    end
end
local function patchrapidfireupvalues(tool, callback, slots)
    if #slots == 0 then
        return true
    end
    local applied = true
    local saved = Data['RapidFireUpvalues'][callback]
    if not saved then
        saved = {}
        Data['RapidFireUpvalues'][callback] = saved
    end
    for _, slot in ipairs(slots) do
        local value = rapidfiregetupvalue(callback, slot.Index)
        if type(value) == 'number' then
            local state = saved[slot.Index]
            if not state then
                local baseline = value
                local cooldown = tool:FindFirstChild(slot.Name)
                local originalValue = cooldown and Data['RapidFireValues'][cooldown]
                if originalValue and baseline == originalValue.Applied then
                    baseline = originalValue.Value
                end
                state = {
                    Value = baseline, Tool = tool, Name = slot.Name,
                    Timestamp = slot.Timestamp, Duration = slot.Duration,
                }
                saved[slot.Index] = state
            elseif value ~= state.Applied then
                state.Value = value
            end
            local factor = phowg:rapid_fire_factor()
            local replacement = state.Timestamp and state.Value - state.Duration * (1 - factor)
                or state.Value * factor
            if value ~= replacement then
                local updated = pcall(debug.setupvalue, callback, slot.Index, replacement)
                if updated then
                    state.Applied = replacement
                end
                if not updated then
                    applied = false
                end
                if not updated and not Data['RapidFireHookWarned'] then
                    Data['RapidFireHookWarned'] = true
                    Library:Notify('Rapid fire: cached cooldown hook failed', 5)
                end
            else
                state.Applied = replacement
            end
        else
            applied = false
        end
    end
    return applied
end
function phowg:refresh_rapid_fire_percent()
    local factor = phowg:rapid_fire_factor()
    for value, state in pairs(Data.RapidFireValues or {}) do
        state.Applied = phowg:scale_rapid_fire_value(value, state.Value)
        if value.Parent and value.Value ~= state.Applied then
            value.Value = state.Applied
        end
    end
    for callback, slots in pairs(Data.RapidFireUpvalues or {}) do
        for index, state in pairs(slots) do
            local current = rapidfiregetupvalue(callback, index)
            if type(current) == 'number' then
                if current ~= state.Applied then
                    state.Value = current
                end
                local replacement = state.Timestamp and state.Value - state.Duration * (1 - factor)
                    or state.Value * factor
                if pcall(debug.setupvalue, callback, index, replacement) then
                    state.Applied = replacement
                end
            end
        end
    end
end
local function rapidfiregeneric(tool, callback)
    local values, names = {}, {}
    for index = 1, 64 do
        local result = table.pack(pcall(debug.getupvalue, callback, index))
        if not result[1] then
            break
        end
        local value
        if result.n >= 3 then
            value = result[3]
        else
            value = result[2]
        end
        if value == nil then
            break
        end
        values[index] = value
        if result.n >= 3 and type(result[2]) == 'string' then
            names[index] = result[2]
        end
    end
    local hasTool, hasCharacter, hasHandler = false, false, false
    for _, value in pairs(values) do
        hasTool = hasTool or value == tool or value == tool:FindFirstChild('Handle')
        hasCharacter = hasCharacter or value == LocalPlayer.Character
        hasHandler = hasHandler or type(value) == 'table' and type(value.getCanShoot) == 'function'
    end
    if not (hasTool and hasCharacter and hasHandler) then
        return nil
    end
    local slots = {}
    for index, value in pairs(values) do
        if type(value) == 'number' then
            for _, key in ipairs({ 'ShootingCooldown', 'ToleranceCooldown' }) do
                local object = tool:FindFirstChild(key)
                local saved = object and Data.RapidFireValues[object]
                local baseline = saved and saved.Value or object and object.Value
                local named = names[index] and names[index]:lower():find('cooldown', 1, true)
                if named or type(baseline) == 'number' and baseline > 0 and value == baseline then
                    slots[#slots + 1] = { Index = index, Name = key }
                    break
                end
            end
        end
    end
    return slots
end
local function patchrapidfirecallbacks(tool, tracked)
    if not (getconnections and debug and debug.getupvalue and debug.setupvalue) then
        if not Data.RapidFireHookWarned then
            Data.RapidFireHookWarned = true
            Library:Notify('Rapid fire: executor cannot access cached gun cooldowns.', 5)
        end
        return false
    end
    local ok, connections = pcall(getconnections, tool.Activated)
    if not ok or type(connections) ~= 'table' then
        return false
    end
    local found, complete = false, true
    local function patch(callback)
        local client = rapidfireclient(tool, callback)
        if not client then
            return false
        end
        local record = tracked.Callbacks[callback]
        if record and record.Complete then
            return true
        end
        if not record then
            local slots = rapidfirecooldownslots(tool, callback, client)
            if not slots then
                slots = rapidfiregeneric(tool, callback)
            end
            if not slots then
                return false
            end
            record = { Slots = slots, Complete = false }
            tracked.Callbacks[callback] = record
        end
        if not record.UpvaluesApplied then
            record.UpvaluesApplied = patchrapidfireupvalues(tool, callback, record.Slots)
        end
        record.Complete = record.UpvaluesApplied
        return record.Complete
    end
    for _, connection in pairs(connections) do
        local callback = connection.Function
        if patch(callback) then
            found = true
        elseif tracked.Callbacks[callback] then
            complete = false
        end
    end
    return found and complete
end
function rapidfire()
    local simple = phowg:simple_rapid_fire_mode()
    local existing = Data['RapidFireState']
    if
        existing
        and (existing.Simple == true) == simple
        and existing.Active
        and existing.Refresh
        and existing.Character == LocalPlayer.Character
        and Toggles.rapid_fire
        and Toggles.rapid_fire.Value
        and not Library.Unloaded
    then
        existing.Refresh(true)
        return
    end
    stoprapidfire()
    if simple then
        phowg:start_simple_rapid_fire()
        return
    end
    Data['RapidFireValues'] = {}
    Data.RapidFireUpvalues = setmetatable({}, { __mode = 'k' })
    Data['RapidFireHookWarned'] = nil
    local context = { Active = true, Character = LocalPlayer.Character, Tools = {}, Containers = {}, Connections = {} }
    Data['RapidFireState'] = context
    local function active()
        return context.Active
            and Data['RapidFireState'] == context
            and Toggles.rapid_fire
            and Toggles.rapid_fire.Value
            and not Library.Unloaded
    end
    local function owned(tool)
        return tool.Parent ~= nil
            and (tool.Parent == LocalPlayer.Character or tool.Parent == LocalPlayer:FindFirstChild('Backpack'))
    end
    local function releasevalue(value)
        local state = Data['RapidFireValues'][value]
        if not state then
            return
        end
        state.Connection:Disconnect()
        Data['RapidFireValues'][value] = nil
        pcall(function()
            value.Value = state.Value
        end)
    end
    local function release(tool)
        local tracked = context.Tools[tool]
        if not tracked then
            return
        end
        context.Tools[tool] = nil
        tracked.Released = true
        phowg:deactivate_tool(tool)
        for _, connection in ipairs(tracked.Connections) do
            connection:Disconnect()
        end
        for _, connection in ipairs(tracked.PendingConnections) do
            connection:Disconnect()
        end
        for callback, slots in pairs(Data.RapidFireUpvalues or {}) do
            local matches = false
            for _, state in pairs(slots) do
                matches = state.Tool == tool
                break
            end
            if matches then
                restorerapidfireupvalues(callback, slots)
                Data.RapidFireUpvalues[callback] = nil
            end
        end
        for value in pairs(tracked.Values) do
            releasevalue(value)
        end
    end
    context.Release = release
    local function trackvalue(tool, tracked, value)
        if
            value.Parent ~= tool
            or (value.Name ~= 'ShootingCooldown' and value.Name ~= 'ToleranceCooldown')
            or not (value:IsA('NumberValue') or value:IsA('IntValue'))
            or Data['RapidFireValues'][value]
        then
            return
        end
        local state = { Value = value.Value, Tool = tool, Applied = phowg:scale_rapid_fire_value(value, value.Value) }
        Data['RapidFireValues'][value] = state
        tracked.Values[value] = true
        state.Connection = connectshared(value:GetPropertyChangedSignal('Value'), function()
            if
                active()
                and not tracked.Released
                and Data['RapidFireValues'][value] == state
                and value.Value ~= state.Applied
            then
                state.Value = value.Value
                state.Applied = phowg:scale_rapid_fire_value(value, state.Value)
                value.Value = state.Applied
            end
        end, value, 'event/value:GetPropertyChangedSignal(Value)', 0, 'property/Value', value)
        if value.Value ~= state.Applied then
            value.Value = state.Applied
        end
    end
    local function scan(tool, tracked)
        if not active() or tracked.Released or tracked.Scanning or Library.ConfigLoading then
            return
        end
        if tracked.Applied or tool.Parent ~= LocalPlayer.Character then
            return
        end
        if not owned(tool) then
            release(tool)
            return
        end
        if tick() < (tracked.ScanAfter or 0) then
            return
        end
        if
            not tool:FindFirstChild('Ammo')
            and not tool:FindFirstChild('ShootingCooldown')
            and not tool:FindFirstChild('ToleranceCooldown')
            and not tool:FindFirstChild('GunClient')
            and not tool:FindFirstChild('GunClientAutomatic')
            and not tool:FindFirstChild('GunClientBurst')
            and not tool:FindFirstChild('GunClientShotgun')
            and not tool:FindFirstChild('GunClientAutomaticShotgun')
        then
            tracked.ScanAfter = tick() + 5
            return
        end
        tracked.ScanAfter = tick() + (tracked.Applied and 2 or 0.25)
        for _, name in ipairs({ 'ShootingCooldown', 'ToleranceCooldown' }) do
            local value = tool:FindFirstChild(name)
            if value then
                trackvalue(tool, tracked, value)
            end
        end
        tracked.Scanning = true
        local patched, applied = pcall(patchrapidfirecallbacks, tool, tracked)
        tracked.Scanning = nil
        tracked.Applied = patched and applied == true
        if not patched and not Data.RapidFireHookWarned then
            Data.RapidFireHookWarned = true
            warn('[phowg] rapid fire callback patch: ' .. tostring(applied))
        end
        if not tracked.Applied then
            tracked.Attempts = (tracked.Attempts or 0) + 1
            tracked.ScanAfter = tick() + math.min(5, 0.25 * 2 ^ math.min(tracked.Attempts, 5))
        end
    end
    local function queuescan(tool, tracked, invalidate)
        if invalidate then
            table.clear(tracked.Callbacks)
            tracked.Applied = false
            tracked.Attempts = 0
        end
        if tracked.Applied then
            return
        end
        if tracked.Queued or tracked.Released or not active() then
            return
        end
        tracked.Queued = true
        tracked.ScanAfter = 0
        task.defer(function()
            tracked.Queued = false
            if active() and context.Tools[tool] == tracked then
                scan(tool, tracked)
            end
        end)
    end
    local function track(tool)
        if not active() or not tool:IsA('Tool') or not owned(tool) then
            return
        end
        if context.Tools[tool] then
            queuescan(tool, context.Tools[tool])
            return
        end
        local tracked: { [string]: any } = {
            Callbacks = setmetatable({}, { __mode = 'k' }),
            Values = {},
            Connections = {},
            PendingConnections = {},
            Released = false,
            Applied = false,
            Queued = false,
            ScanAfter = 0,
        }
        context.Tools[tool] = tracked
        table.insert(
            tracked.Connections,
            connectshared(tool.ChildAdded, function(child)
                if not active() or tracked.Released then
                    return
                end
                trackvalue(tool, tracked, child)
                if
                    child.Name == 'Ammo'
                    or child.Name == 'ShootingCooldown'
                    or child.Name == 'ToleranceCooldown'
                    or child.Name == 'GunClient'
                    or child.Name == 'GunClientAutomatic'
                    or child.Name == 'GunClientBurst'
                    or child.Name == 'GunClientShotgun'
                    or child.Name == 'GunClientAutomaticShotgun'
                    or child.Name == 'Handle'
                    or child.Name == 'Range'
                then
                    queuescan(tool, tracked, true)
                end
            end, tool, 'event/tool.ChildAdded', 0, 'event/ChildAdded', tool)
        )
        table.insert(
            tracked.Connections,
            connectshared(tool.ChildRemoved, function(child)
                if tracked.Released then
                    return
                end
                if tracked.Values[child] then
                    releasevalue(child)
                    tracked.Values[child] = nil
                end
                if
                    active()
                    and (
                        child.Name == 'Ammo'
                        or child.Name == 'ShootingCooldown'
                        or child.Name == 'ToleranceCooldown'
                        or child.Name == 'GunClient'
                        or child.Name == 'GunClientAutomatic'
                        or child.Name == 'GunClientBurst'
                        or child.Name == 'GunClientShotgun'
                        or child.Name == 'GunClientAutomaticShotgun'
                        or child.Name == 'Handle'
                        or child.Name == 'Range'
                    )
                then
                    queuescan(tool, tracked, true)
                end
            end, tool, 'event/tool.ChildRemoved', 0, 'event/ChildRemoved', tool)
        )
        table.insert(
            tracked.Connections,
            connectshared(tool.AncestryChanged, function()
                if not active() or tracked.Released then
                    return
                end
                if owned(tool) then
                    queuescan(tool, tracked)
                else
                    release(tool)
                end
            end, tool, 'event/tool.AncestryChanged', 0, 'event/AncestryChanged', tool)
        )
        table.insert(
            tracked.PendingConnections,
            connectshared(tool.Equipped, function()
                queuescan(tool, tracked)
            end, tool, 'event/tool.Equipped', 0, 'event/Equipped', tool)
        )
        for _, name in ipairs({ 'ShootingCooldown', 'ToleranceCooldown' }) do
            local value = tool:FindFirstChild(name)
            if value then
                trackvalue(tool, tracked, value)
            end
        end
        if normalizeweaponname(tool.Name) == 'rifle' then
            tracked.Connections[#tracked.Connections + 1] = connectshared(tool.Activated, function()
                task.defer(function()
                    if not active() or tracked.Released then
                        return
                    end
                    for callback, record in pairs(tracked.Callbacks) do
                        if record.Complete and record.Slots[1] and record.Slots[1].Timestamp then
                            patchrapidfireupvalues(tool, callback, record.Slots)
                        end
                    end
                end)
            end, tool, 'rapid fire/rifle timestamp', 0, 'event/Activated', tool)
        end
        queuescan(tool, tracked)
    end
    local function watch(container)
        if not container or context.Containers[container] then
            return
        end
        local connections = {}
        context.Containers[container] = connections
        table.insert(
            connections,
            connectshared(
                container.ChildAdded,
                track,
                container,
                'event/container.ChildAdded',
                0,
                'event/ChildAdded',
                container
            )
        )
        table.insert(
            connections,
            connectshared(container.ChildRemoved, function(tool)
                if active() and context.Tools[tool] and not owned(tool) then
                    release(tool)
                end
            end, container, 'event/container.ChildRemoved', 0, 'event/ChildRemoved', container)
        )
        for _, tool in ipairs(container:GetChildren()) do
            track(tool)
        end
    end
    table.insert(
        context.Connections,
        connectshared(LocalPlayer.CharacterAdded, function(character)
            if not active() or character == context.Character then
                return
            end
            stoprapidfire()
            if Toggles.rapid_fire and Toggles.rapid_fire.Value and not Library.Unloaded then
                rapidfire()
            end
        end, LocalPlayer, 'event/LocalPlayer.CharacterAdded', 0, 'event/CharacterAdded', LocalPlayer)
    )
    table.insert(
        context.Connections,
        connectshared(LocalPlayer.ChildAdded, function(child)
            if active() and child.Name == 'Backpack' then
                watch(child)
            end
        end, LocalPlayer, 'event/LocalPlayer.ChildAdded', 0, 'event/ChildAdded', LocalPlayer)
    )
    watch(LocalPlayer.Character)
    watch(LocalPlayer:FindFirstChild('Backpack'))
    context.ScanAt = tick()
    context.Refresh = function(force)
        if not active() or not force and tick() - context.ScanAt < 0.5 then
            return
        end
        context.ScanAt = tick()
        watch(LocalPlayer.Character)
        watch(LocalPlayer:FindFirstChild('Backpack'))
        for _, container in pairs({ LocalPlayer.Character, LocalPlayer:FindFirstChild('Backpack') }) do
            for _, tool in ipairs(container:GetChildren()) do
                if not context.Tools[tool] then
                    track(tool)
                end
            end
        end
        for tool, tracked in pairs(context.Tools) do
            if not owned(tool) then
                release(tool)
            elseif force or not tracked.Applied then
                scan(tool, tracked)
            end
        end
    end
end
function stoprapidfire()
    if Data['RapidFireConn'] then
        Data['RapidFireConn']:Disconnect()
        Data['RapidFireConn'] = nil
    end
    local context = Data['RapidFireState']
    if context then
        context.Active = false
        for _, connection in ipairs(context.Connections) do
            connection:Disconnect()
        end
        for _, connections in pairs(context.Containers) do
            for _, connection in ipairs(connections) do
                connection:Disconnect()
            end
        end
        for tool in pairs(context.Tools) do
            context.Release(tool)
        end
        Data['RapidFireState'] = nil
    end
    for callback, slots in pairs(Data.RapidFireUpvalues or {}) do
        restorerapidfireupvalues(callback, slots)
    end
    Data.RapidFireUpvalues = nil
    for value, state in pairs(Data['RapidFireValues'] or {}) do
        state.Connection:Disconnect()
        pcall(function()
            value.Value = state.Value
        end)
    end
    Data['RapidFireValues'] = nil
end
registerheartbeat('RapidFire', function()
    if Library.Unloaded or Library.ControlsReady == false or Library.ConfigLoading or Data.SharedSignalsClosed then
        return
    end
    local enabled = Toggles.rapid_fire and Toggles.rapid_fire.Value
    local context = Data['RapidFireState']
    if not enabled then
        if context then
            stoprapidfire()
        end
    elseif
        not context
        or not context.Active
        or not context.Refresh
        or context.Character ~= LocalPlayer.Character
        or (context.Simple == true) ~= phowg:simple_rapid_fire_mode()
    then
        rapidfire()
