end, 0.5)
local function gunmodactive(name)
    return not Library.Unloaded and not Data['RPGUnloading'] and Toggles[name] and Toggles[name].Value
end
local function loadgunmodule(name)
    local modules = ReplicatedStorage:FindFirstChild('Modules')
    local handler = modules and modules:FindFirstChild('GunHandler')
    local module = handler and handler:FindFirstChild(name)
    if not module or not module:IsA('ModuleScript') then
        return nil
    end
    local ok, result = pcall(require, module)
    if ok then
        return result
    end
    return nil
end
function stopgunmodulehook(name)
    local state = Data['GunModuleHooks'] and Data['GunModuleHooks'][name]
    if not state then
        return
    end
    state.Enabled = false
    if name == 'Spread' then
        local ok = pcall(function()
            state.Module.Ahead = state.Ahead
            for weapon, scale in pairs(state.Scales) do
                state.Scale[weapon] = scale
            end
            state.Module.roll = state.Original
        end)
        if ok then
            Data['GunModuleHooks'][name] = nil
        end
        return
    end
    local ok = pcall(hookfunction, state.Target, state.Original)
    if ok then
        Data['GunModuleHooks'][name] = nil
    end
end
function phowg:update_gun_spread(value)
    local state = Data['GunModuleHooks'] and Data['GunModuleHooks'].Spread
    if not state or not state.Enabled then
        return true
    end
    local percent = math.clamp(
        tonumber(value) or tonumber(Options.custom_spread_amount and Options.custom_spread_amount.Value) or 100,
        0,
        100
    )
    local factor = percent / 100
    local ok = pcall(function()
        state.Module.Ahead = percent == 0 and 0 or type(state.Ahead) == 'number' and state.Ahead * factor or state.Ahead
        for weapon, scale in pairs(state.Scales) do
            state.Scale[weapon] = percent == 0 and 0 or type(scale) == 'number' and scale * factor or scale
        end
        state.Module.roll = percent == 0 and state.ZeroRoll or state.Original
    end)
    if not ok then
        stopgunmodulehook('Spread')
        Library:Notify('Spread: module update failed', 5)
        if Toggles.custom_spread and Toggles.custom_spread.Value then
            Toggles.custom_spread:SetValue(false)
        end
    end
    return ok
end
function startgunmodulehook(name, toggle)
    if not gunmodactive(toggle) then
        return false
    end
    Data['GunModuleHooks'] = Data['GunModuleHooks'] or {}
    local existing = Data['GunModuleHooks'][name]
    if existing then
        if name ~= 'Spread' then
            existing.Enabled = true
            return true
        end
        if existing.Enabled then
            return phowg:update_gun_spread()
        end
        stopgunmodulehook(name)
        if Data['GunModuleHooks'][name] then
            return false
        end
    end
    if name ~= 'Spread' and not hookfunction then
        Library:Notify(name .. ': function hooks unavailable', 5)
        return false
    end
    local module = loadgunmodule(name)
    if not gunmodactive(toggle) then
        return false
    end
    if name == 'Spread' then
        if type(module) ~= 'table' or type(module.Scale) ~= 'table' or type(module.roll) ~= 'function' then
            Library:Notify('Spread: gun module unavailable', 5)
            return false
        end
        local state = {
            Module = module,
            Scale = module.Scale,
            Scales = table.clone(module.Scale),
            Ahead = module.Ahead,
            Original = module.roll,
            Enabled = true,
        }
        local replacement = function()
            return table.create(5, Vector3.zero)
        end
        if newcclosure then
            replacement = newcclosure(replacement)
        end
        state.ZeroRoll = replacement
        Data['GunModuleHooks'][name] = state
        return phowg:update_gun_spread()
    end
    local target = name == 'WallShot' and module or nil
    if type(target) ~= 'function' then
        Library:Notify(name .. ': gun module unavailable', 5)
        return false
    end
    local state = { Target = target, Enabled = true, Original = target }
    local replacement = LPH_NO_VIRTUALIZE(function(character, ...)
        if state.Enabled and gunmodactive(toggle) and character and character == LocalPlayer.Character then
            return nil
        end
        return state.Original(character, ...)
    end)
    local ok, original = pcall(hookfunction, target, replacement)
    if not ok or type(original) ~= 'function' then
        Library:Notify(name .. ': function hook failed', 5)
        return false
    end
    state.Original = original
    Data['GunModuleHooks'][name] = state
    return true
end
function hooksirenfx()
    if Data['SirenFxConn'] then
        Data['SirenFxConn']:Disconnect()
    end
    Data['SirenFxConn'] = nil
    if not (Toggles.rapid_fire and Toggles.rapid_fire.Value) then
        if Data['SirenFxOff'] then
            for inst, st in pairs(Data['SirenFxOff']) do
                (function()
                    if inst and inst.Parent then
                        inst.Enabled = st
                    end
                end)()
            end
            Data['SirenFxOff'] = {}
        end
        return
    end
    if Data['SirenFxOff'] == nil then
        Data['SirenFxOff'] = {}
    end
    setmetatable(Data['SirenFxOff'], { __mode = 'k' })
    local function killfx(d)
        local isLight, isEmit = false, false
        isLight = d:IsA('PointLight')
        if not isLight then
            isEmit = d:IsA('ParticleEmitter')
        end
        if not isLight and not isEmit then
            return
        end
        local inside = false
        local n = d
        while n do
            if n.Name == 'Radius' and n.Parent and n.Parent.Name == 'Siren' then
                inside = true
                break
            end
            n = n.Parent
        end
        if not inside then
            return
        end
        (function()
            if Data['SirenFxOff'][d] == nil then
                Data['SirenFxOff'][d] = d.Enabled
            end
            if d.Enabled then
                d.Enabled = false
            end
        end)()
    end
    local ign = Workspace:FindFirstChild('Ignored')
    if ign then
        for _, d in ipairs(ign:GetDescendants()) do
            killfx(d)
        end
        Data['SirenFxConn'] = connectshared(ign.DescendantAdded, function(d)
            killfx(d)
        end, ign, 'event/ign.DescendantAdded', 0, 'event/DescendantAdded', ign)
    else
        task.spawn(function()
            local w = Workspace:WaitForChild('Ignored', 10)
            if w and Toggles.rapid_fire and Toggles.rapid_fire.Value then
                hooksirenfx()
            end
        end)
    end
end
function enableextrapellet()
    if phowg.extrapelletold ~= nil then
        return
    end
    if not hookfunction or not getcallingscript or not checkcall then
        return
    end
    phowg.extrapelletold = hookfunction(
        math.random,
        LPH_NO_VIRTUALIZE(function(...)
            if localactionblocked() then
                return phowg.extrapelletold(...)
            end
            local count = select('#', ...)
            local minimum, maximum = ...
            if
                count ~= 0
                and (count ~= 2 or type(minimum) ~= 'number' or type(maximum) ~= 'number' or minimum > 0 or maximum < 0)
            then
                return phowg.extrapelletold(...)
            end
            local CallingScript = getcallingscript()
            if checkcall() then
                return phowg.extrapelletold(...)
            end
            local GetCalling = tostring(CallingScript):lower()
            if
                (GetCalling:find('gunclient') or GetCalling:find('shotgun'))
                and Toggles.extra_pellet
                and Toggles.extra_pellet.Value
            then
                return 0
            end
            return phowg.extrapelletold(...)
        end)
    )
end
function disableextrapellet()
    if phowg.extrapelletold ~= nil then
        local OldRandom = phowg.extrapelletold
        phowg.extrapelletold = nil
        hookfunction(math.random, OldRandom)
    end
end
function autoblockloop()
    while
        Toggles.auto_block
        and Toggles.auto_block.Value
        and not Data.Unloading
        and not Library.Unloaded
        and not Data.SharedSignalsClosed
    do
        if localactionblocked() then
            task.wait(0.05)
            continue
        end
        local char = LocalPlayer.Character
        if char then
            local be = char:FindFirstChild('BodyEffects')
            if be then
                local blk = be:FindFirstChild('Block')
                if blk then
                    blk:Destroy()
                end
            end
            local tool = char:FindFirstChildWhichIsA('Tool')
            if not MainEvent then
                RunService.Heartbeat:Wait()
            elseif tool and tool:FindFirstChild('Ammo') then
                MainEvent:FireServer('Block', false)
                RunService.Heartbeat:Wait()
            else
                if
                    not Data.Unloading
                    and not Library.Unloaded
                    and not Data.SharedSignalsClosed
                    and not localactionblocked()
                then
                    MainEvent:FireServer('Block', true)
                end
                task.wait()
                MainEvent:FireServer('Block', false)
                RunService.Heartbeat:Wait()
            end
        end
    end
end
local function ismolotovpart(part)
    if not part or not part:IsA('BasePart') or part:FindFirstAncestorOfClass('Tool') then
        return false
    end
    local character = LocalPlayer.Character
    if character and part:IsDescendantOf(character) then
        return false
    end
    if Service.CollectionService:HasTag(part, 'MolotovProjectile') then
        return part:IsDescendantOf(Workspace)
    end
    if part.Anchored then
        return false
    end
    local effects = Workspace:FindFirstChild('MolotovEffects')
    if not effects or not part:IsDescendantOf(effects) then
        return false
    end
    if part.Name == 'MolotovProjectile' then
        return true
    end
    local projectile = part:FindFirstAncestor('MolotovProjectile')
    if not projectile or not projectile:IsA('Model') then
        return false
    end
    return part == (projectile.PrimaryPart or projectile:FindFirstChildWhichIsA('BasePart', true))
end
local function grenadelauncherowner(part)
    local ignored = Workspace:FindFirstChild('Ignored')
    if not ignored or not part:IsDescendantOf(ignored) then
        return nil
    end
    local owner = part
    local found
    while owner and owner ~= ignored do
        if
            owner.Name == 'Shop'
            or owner.Name == 'Drop'
            or owner:IsA('Tool')
            or owner:FindFirstChildOfClass('Humanoid')
            or owner:FindFirstChild('HumanoidRootPart')
        then
            return nil
        end
        if owner.Name == 'GrenadeLauncherAmmo' then
            found = owner
        end
        owner = owner.Parent
    end
    return found
end
function isgrenadepart(Obj)
    if not Obj or not Obj:IsA('BasePart') then
        return false
    end
    local character = LocalPlayer.Character
    if character and Obj:IsDescendantOf(character) then
        return false
    end
    if grenadelauncherowner(Obj) then
        return true
    end
    if ismolotovpart(Obj) then
        return true
    end
    if Obj.Anchored then
        return false
    end
    if Obj.Name ~= 'Handle' and Obj.Name ~= 'GrenadeLauncherAmmo' and Obj.Name ~= 'Part' then
        return false
    end
    local Parent = Obj.Parent
    if not Parent then
        return false
    end
    if Parent.Name == 'Shop' or Parent.Name == 'Drop' then
        return false
    end
    if
        Parent:FindFirstChildOfClass('Humanoid')
        or Parent:FindFirstChild('HumanoidRootPart')
        or Parent:FindFirstChild('Head')
        or Parent:FindFirstChild('Torso')
        or Parent:FindFirstChild('UpperTorso')
        or Parent:FindFirstChild('LowerTorso')
    then
        return false
    end
    if Parent:IsA('Model') and Parent.PrimaryPart ~= nil then
        return false
    end
    if Obj:FindFirstAncestorOfClass('Tool') or Obj:FindFirstAncestorOfClass('Humanoid') then
        return false
    end
    local model = Obj:FindFirstAncestorOfClass('Model')
    if model and model ~= Workspace:FindFirstChild('Ignored') then
        if
            model:FindFirstChildOfClass('Humanoid')
            or model:FindFirstChild('HumanoidRootPart')
            or model:FindFirstChild('Head')
            or model:FindFirstChild('UpperTorso')
        then
            return false
        end
    end
    return true
end
local function releaseexplosivereflection(projectile)
    local orbit = Data['RPGOrbitProjectiles'] and Data['RPGOrbitProjectiles'][projectile]
    if orbit then
        for part, canTouch in pairs(orbit.Touches) do
            if part.Parent then
                pcall(function()
                    part.CanTouch = canTouch
                end)
            end
        end
        Data['RPGOrbitProjectiles'][projectile] = nil
    end
    local movers = Data['RPGReflectionMovers']
    if not movers then
        return
    end
    local function release(part)
        local mover = movers[part]
        if mover then
            pcall(function()
                mover:Destroy()
            end)
            movers[part] = nil
        end
        local properties = Data['RPGReflectionProperties'] and Data['RPGReflectionProperties'][part]
        if properties then
            if part.Parent then
                pcall(function()
                    part.CanTouch = properties.CanTouch
                    part.CanCollide = properties.CanCollide
                end)
            end
            Data['RPGReflectionProperties'][part] = nil
        end
    end
    if projectile:IsA('BasePart') then
        release(projectile)
    end
    for _, part in ipairs(projectile:GetDescendants()) do
        if part:IsA('BasePart') then
            release(part)
        end
    end
end
local function getgrenadetptarget()
    if localactionblocked() or not phowg:grenade_teleport_active() then
        return nil
    end
    local target = Toggles.auto_throw_grenade
            and Toggles.auto_throw_grenade.Value
            and phowg:grenade_throw_target(phowg:selected_grenade_type())
        or nil
    if not target and not (Toggles.auto_throw_grenade and Toggles.auto_throw_grenade.Value) then
        target = get_sticky_target()
    end
    if not target or target == LocalPlayer or not target.Parent or not intelligence:get_character_cache(target) then
        return nil
    end
    local character = target.Character
    local torso = character and (character:FindFirstChild('UpperTorso') or character:FindFirstChild('Torso'))
    local humanoid = character and character:FindFirstChildOfClass('Humanoid')
    local root = character and character:FindFirstChild('HumanoidRootPart')
    if not torso or not humanoid or not root then
        return nil
    end
    return target, torso, humanoid, root
end
local function releasegrenadepart(part, state)
    state.released = true
    if state.molotovConnection then
        state.molotovConnection:Disconnect()
        state.molotovConnection = nil
    end
    if state.position and state.position.Parent == part then
        state.position:Destroy()
    end
    if state.beam then
        state.beam:Destroy()
    end
    if state.attachment then
        state.attachment:Destroy()
    end
    if state.handAttachment then
        state.handAttachment:Destroy()
    end
    if part.Parent then
        if part.CFrame == state.molotovAppliedCFrame and typeof(state.molotovNativeCFrame) == 'CFrame' then
            part.CFrame = state.molotovNativeCFrame
        end
        part.CanCollide = state.canCollide
        part.CanQuery = state.canQuery
    end
end
function stopgrenadetp(keepMolotovTracking)
    if phowg.stop_grenade_scan_watch then
        phowg:stop_grenade_scan_watch()
    end
    if not keepMolotovTracking then
        for _, key in ipairs({ 'GrenadeMolotovAdded', 'GrenadeMolotovRemoved' }) do
            local connection = Data[key]
            if connection then
                connection:Disconnect()
                Data[key] = nil
            end
        end
        Data['GrenadeMolotovParts'] = nil
    end
    for part, state in pairs(Data['GrenadeControlledParts'] or {}) do
        releasegrenadepart(part, state)
    end
    Data['GrenadeControlledParts'] = nil
    Data['GrenadePartsCache'] = nil
    Data['GrenadePartsAt'] = nil
    Data['GrenadeIgnoredFolder'] = nil
    Data['GrenadeMolotovFolder'] = nil
    Data['GrenadeMotion'] = nil
    Data['GrenadePing'] = nil
    Data['GrenadePingAt'] = nil
    Data['GrenadeLauncherOffsets'] = nil
    Data['GrenadeTeleportTarget'] = nil
    Data['GrenadeTeleportCharacter'] = nil
end
phowg:register_cleanup('grenade teleport', function(scope)
    if not scope then
        Data.GrenadeNukeUntil = nil
    end
    if
        not scope
        or scope == LocalPlayer.Character
        or scope == Data.ManagedCharacter
        or scope == Data['GrenadeTeleportCharacter']
    then
        stopgrenadetp()
    end
end)
local function applymolotovposition(part, state)
    if
        state.released
        or state.molotovWriting
        or not state.molotovPosition
        or Data.SharedSignalsClosed
        or Library.Unloaded
    then
        return
    end
    if not phowg:grenade_teleport_active() or localactionblocked() then
        return
    end
    if
        not (
            Data['GrenadeControlledParts']
            and Data['GrenadeControlledParts'][part] == state
            and Data['GrenadeMolotovParts']
            and Data['GrenadeMolotovParts'][part]
        )
        or not part.Parent
        or not ismolotovpart(part)
    then
        return
    end
    local target = Data['GrenadeTeleportTarget']
    if not target or not target.Parent or target.Character ~= Data['GrenadeTeleportCharacter'] then
        return
    end
    local current = part.CFrame
    if current == state.molotovAppliedCFrame and current.Position == state.molotovPosition then
        return
    end
    if current ~= state.molotovAppliedCFrame then
        state.molotovNativeCFrame = current
    end
    local frame = CFrame.new(state.molotovPosition) * current.Rotation
    if current == frame then
        return
    end
    state.molotovAppliedCFrame = frame
    state.molotovWriting = true
    part.CFrame = frame
    state.molotovWriting = false
end
local function movegrenadepart(part, position, teleport, spinning)
    local character = LocalPlayer.Character
    if character and part:IsDescendantOf(character) then
        return
    end
    local launcher = grenadelauncherowner(part)
    releaseexplosivereflection(launcher or part)
    if launcher then
        part.Anchored = false
    end
    Data.GrenadeControlledParts = Data.GrenadeControlledParts or {}
    local state = Data.GrenadeControlledParts[part]
    if not state then
        state = { canCollide = part.CanCollide, canQuery = part.CanQuery }
        Data.GrenadeControlledParts[part] = state
    end
    part.CanCollide, part.CanQuery = false, false
    if Service.CollectionService:HasTag(part, 'MolotovProjectile') then
        state.molotovPosition = position
        if not state.molotovConnection then
            state.molotovConnection = part:GetPropertyChangedSignal('CFrame'):Connect(function()
                applymolotovposition(part, state)
            end)
        end
        applymolotovposition(part, state)
        return
    end
    part.AssemblyLinearVelocity = Vector3.new(0, 30, 0)
    part.AssemblyAngularVelocity = Vector3.zero
    local close = (part.Position - position).Magnitude < 30
    local usePosition = spinning or not teleport and not close
    for _, child in ipairs(part:GetChildren()) do
        if child:IsA('BodyPosition') then
            if not usePosition or child ~= state.position then
                child:Destroy()
            end
        elseif
            child:IsA('BodyGyro')
            or child:IsA('BodyVelocity')
            or child:IsA('AlignPosition')
            or child:IsA('AlignOrientation')
            or child:IsA('VectorForce')
        then
            child:Destroy()
        end
    end
    if usePosition then
        local mover = state.position
        if not mover or mover.Parent ~= part then
            mover = createbodymover('BodyPosition', part)
            state.position = mover
        end
        mover.Name = spinning and 'PhowgGrenadeSpin' or 'PHOWG'
        mover.MaxForce = Vector3.new(math.huge, math.huge, math.huge)
        mover.P, mover.D, mover.Position = 10000, 175, position
        if spinning and not state.spinPlaced then
            part.CFrame = CFrame.new(position)
            state.spinPlaced = true
        end
    else
        state.position = nil
        part.CFrame = CFrame.new(position)
    end
    if not spinning then
        state.spinPlaced = nil
    end
    local hand = character and (character:FindFirstChild('RightHand') or character:FindFirstChild('Right Arm'))
    local show = Toggles.grenade_tracer and Toggles.grenade_tracer.Value and hand
    if not show then
        if state.beam then
            state.beam:Destroy()
            state.beam = nil
        end
        if state.attachment then
            state.attachment:Destroy()
            state.attachment = nil
        end
        if state.handAttachment then
            state.handAttachment:Destroy()
            state.handAttachment = nil
        end
    else
        local grip = hand:FindFirstChild('RightGripAttachment')
        if not grip then
            if not state.handAttachment or state.handAttachment.Parent ~= hand then
                if state.handAttachment then
                    state.handAttachment:Destroy()
                end
                state.handAttachment = Instance.new('Attachment')
                state.handAttachment.Name = 'PhowgGrenadeGrip'
                state.handAttachment.Parent = hand
            end
            grip = state.handAttachment
        end
        if not state.attachment or state.attachment.Parent ~= part then
            state.attachment = Instance.new('Attachment')
            state.attachment.Name = 'PhowgGrenadeAttachment'
            state.attachment.Parent = part
        end
        if not state.beam or state.beam.Parent ~= state.attachment then
            local beam = Instance.new('Beam')
            beam.Name = 'PhowgGrenadeBeam'
            beam.Brightness, beam.LightEmission = 9e9, 1
            beam.Color = ColorSequence.new(Color3.fromRGB(146, 186, 255))
            beam.TextureMode, beam.TextureSpeed = Enum.TextureMode.Wrap, 0.1
            beam.Width0, beam.Width1, beam.FaceCamera = 0.1, 0.1, true
            beam.Parent = state.attachment
            state.beam = beam
        end
        state.beam.Attachment0, state.beam.Attachment1 = grip, state.attachment
    end
end

local function watchmolotovparts()
    if Data['GrenadeMolotovParts'] then
        return Data['GrenadeMolotovParts']
    end
    local collection = Service.CollectionService
    local parts = {}
    Data['GrenadeMolotovParts'] = parts
    local function added(part)
        if part:IsA('BasePart') then
            parts[part] = true
            Data['GrenadePartsCache'] = nil
        end
    end
    Data['GrenadeMolotovAdded'] = collection:GetInstanceAddedSignal('MolotovProjectile'):Connect(added)
    Data['GrenadeMolotovRemoved'] = collection:GetInstanceRemovedSignal('MolotovProjectile'):Connect(function(part)
        parts[part] = nil
        Data['GrenadePartsCache'] = nil
        local state = Data['GrenadeControlledParts'] and Data['GrenadeControlledParts'][part]
        if state and state.molotovConnection then
            releasegrenadepart(part, state)
            Data['GrenadeControlledParts'][part] = nil
        end
    end)
    for _, part in ipairs(collection:GetTagged('MolotovProjectile')) do
        added(part)
    end
    return parts
end
function phowg:stop_grenade_scan_watch()
    local state = Data.GrenadeScanWatch
    Data.GrenadeScanWatch = nil
    if state then
        for _, connection in ipairs(state.Connections) do
            connection:Disconnect()
        end
    end
    local stats = Data.GrenadeScanStats
    if stats then
        stats.Candidates, stats.Pending, stats.Parts = 0, 0, 0
    end
end
function phowg:watch_grenade_scan_folders(ignored, effects)
    local state = Data.GrenadeScanWatch
    if state and state.Ignored == ignored and state.Effects == effects then
        return state
    end
    phowg:stop_grenade_scan_watch()
    state = {
        Ignored = ignored,
        Effects = effects,
        Connections = {},
        Candidates = {},
        Parts = {},
        Pending = {},
        PendingIndex = 1,
        RecheckAt = tick() + 0.5,
    }
    Data.GrenadeScanWatch = state
    Data.GrenadePartsCache = nil
    local stats = Data.GrenadeScanStats
        or { Seeds = 0, Visits = 0, Rechecks = 0, Checks = 0, Candidates = 0, Parts = 0, Pending = 0 }
    Data.GrenadeScanStats = stats
    stats.Seeds += 1
    local function unqueue(record)
        local index = record.Index
        if not index then
            return
        end
        local last = table.remove(state.Pending)
        if last ~= record then
            state.Pending[index] = last
            last.Index = index
        end
        record.Index = nil
        stats.Pending = #state.Pending
    end
    local function remove(part)
        local record = state.Candidates[part]
        if record then
            unqueue(record)
            state.Candidates[part] = nil
            stats.Candidates -= 1
        end
        if state.Parts[part] then
            state.Parts[part] = nil
            Data.GrenadePartsCache = nil
        end
    end
    local function activate(part)
        local record = state.Candidates[part]
        if not record then
            record = { Part = part }
            state.Candidates[part] = record
            stats.Candidates += 1
            stats.Visits += 1
        end
        unqueue(record)
        if not state.Parts[part] then
            state.Parts[part] = true
            Data.GrenadePartsCache = nil
        end
    end
    state.Remove, state.Activate = remove, activate
    local function added(part, seeding)
        if Data.GrenadeScanWatch ~= state or not part:IsA('BasePart') then
            return
        end
        local inIgnored = ignored and part:IsDescendantOf(ignored)
        if inIgnored then
            local owner = part
            while owner.Parent and owner.Parent ~= ignored do
                owner = owner.Parent
            end
            if owner.Name == 'Shop' or owner.Name == 'Drop' then
                return
            end
        end
        if not (inIgnored or effects and part:IsDescendantOf(effects)) then
            return
        end
        local launcher = grenadelauncherowner(part)
        local molotov = ismolotovpart(part)
        if
            part.Name ~= 'Handle'
            and part.Name ~= 'Part'
            and part.Name ~= 'GrenadeLauncherAmmo'
            and not launcher
            and not molotov
        then
            return
        end
        if seeding and part.Anchored and not launcher and not molotov then
            return
        end
        stats.Checks = (stats.Checks or 0) + 1
        if isgrenadepart(part) and (inIgnored or molotov) then
            activate(part)
        elseif not seeding and not state.Candidates[part] then
            local record = { Part = part, Expires = tick() + 2, NextAt = tick() + 0.05, Index = #state.Pending + 1 }
            state.Candidates[part] = record
            state.Pending[record.Index] = record
            stats.Candidates, stats.Visits, stats.Pending = stats.Candidates + 1, stats.Visits + 1, #state.Pending
        end
    end
    local function removed(part)
        if Data.GrenadeScanWatch == state then
            remove(part)
        end
    end
    for _, folder in pairs({ ignored, effects }) do
        state.Connections[#state.Connections + 1] = connectshared(
            folder.DescendantAdded,
            added,
            folder,
            'grenades/scan added',
            0,
            'event/DescendantAdded',
            folder
        )
        state.Connections[#state.Connections + 1] = connectshared(
            folder.DescendantRemoving,
            removed,
            folder,
            'grenades/scan removed',
            0,
            'event/DescendantRemoving',
            folder
        )
        for _, child in ipairs(folder:GetChildren()) do
            if folder ~= ignored or child.Name ~= 'Shop' and child.Name ~= 'Drop' then
                added(child, true)
                for _, descendant in ipairs(child:GetDescendants()) do
                    added(descendant, true)
                end
            end
        end
    end
    return state
end
local function getgrenadeparts()
    local taggedMolotovs = watchmolotovparts()
    local ignored, effects = Workspace:FindFirstChild('Ignored'), Workspace:FindFirstChild('MolotovEffects')
    local state = phowg:watch_grenade_scan_folders(ignored, effects)
    local stats, now = Data.GrenadeScanStats, tick()
    local began = os.clock()
    for _ = 1, math.min(16, #state.Pending) do
        if #state.Pending == 0 or os.clock() - began >= 0.00035 then
            break
        end
        if state.PendingIndex > #state.Pending then
            state.PendingIndex = 1
        end
        local record = state.Pending[state.PendingIndex]
        local part = record.Part
        if now >= record.NextAt then
            record.NextAt = now + 0.05
            local inIgnored = part.Parent and ignored and part:IsDescendantOf(ignored)
            stats.Checks = (stats.Checks or 0) + 1
            if part.Parent and isgrenadepart(part) and (inIgnored or ismolotovpart(part)) then
                state.Activate(part)
            elseif not part.Parent or now >= record.Expires then
                state.Remove(part)
            else
                state.PendingIndex += 1
            end
        else
            state.PendingIndex += 1
        end
    end
    if now >= state.RecheckAt then
        state.RecheckAt = now + 0.5
        stats.Rechecks += 1
        for part in pairs(state.Parts) do
            stats.Checks = (stats.Checks or 0) + 1
            if
                not part.Parent
                or not isgrenadepart(part)
                or not (ignored and part:IsDescendantOf(ignored) or ismolotovpart(part))
            then
                state.Remove(part)
            end
        end
    end
    local parts = Data.GrenadePartsCache
    if not parts then
        parts = {}
        local present = {}
        for part in pairs(state.Parts) do
            if part.Parent then
                parts[#parts + 1] = part
                present[part] = true
            end
        end
        for part in pairs(taggedMolotovs) do
            if part.Parent and not present[part] and ismolotovpart(part) then
                parts[#parts + 1] = part
                present[part] = true
            end
        end
        Data.GrenadePartsCache, state.Present, stats.Parts = parts, present, #parts
    end
    for part, controlled in pairs(Data.GrenadeControlledParts or {}) do
        if not part.Parent or not state.Present[part] then
            releasegrenadepart(part, controlled)
            Data.GrenadeControlledParts[part] = nil
        end
    end
    return parts
end
local function grenadeprediction(target, torso, root)
    local kind = phowg:selected_grenade_type()
    local scale = (kind == 'flashbang' or kind == 'teargas') and 1.5 or 1
    if Toggles.grenade_auto_prediction and Toggles.grenade_auto_prediction.Value then
        local character = target and target.Character
        if character and root.Parent == character and torso.Parent == character then
            local predicted = predpos(torso.Position, character)
            if scale ~= 1 then
                predicted = Vector3.new(
                    torso.Position.X + (predicted.X - torso.Position.X) * scale,
                    predicted.Y,
                    torso.Position.Z + (predicted.Z - torso.Position.Z) * scale
                )
            end
            if phowg:perfect_hit_vector(predicted) then
                return Vector3.new(predicted.X, torso.Position.Y, predicted.Z)
            end
        end
        return torso.Position
    end
    local now = tick()
    local function finite(vector)
        return typeof(vector) == 'Vector3'
            and vector.X == vector.X
            and vector.Y == vector.Y
            and vector.Z == vector.Z
            and math.abs(vector.X) < 1e6
            and math.abs(vector.Y) < 1e6
            and math.abs(vector.Z) < 1e6
    end
    local position = root.Position
    local state = Data['GrenadeMotion']
    if
        not state
        or state.Target ~= target
        or state.Character ~= target.Character
        or state.Root ~= root
        or now < state.At
        or now - state.At > 0.5
    then
        state = {
            Target = target,
            Character = target.Character,
            Root = root,
            Position = position,
            PositionAt = now,
            At = now,
        }
        Data['GrenadeMotion'] = state
    end
    local velocity = root.AssemblyLinearVelocity
    local validVelocity = finite(velocity) and velocity.Magnitude <= 300
    if not validVelocity then
        velocity = Vector3.zero
    end
    local elapsed = now - state.PositionAt
    local delta = position - state.Position
    local discontinuity = not finite(delta) or delta.Magnitude > math.max(20, 300 * math.max(elapsed, 0))
    if discontinuity or root.Anchored then
        velocity = Vector3.zero
        state.ObservedVelocity = nil
        state.ObservedAt = nil
    elseif delta.Magnitude > 0.001 and elapsed >= 1 / 240 and elapsed <= 0.25 then
        local observed = delta / elapsed
        if finite(observed) and observed.Magnitude <= 300 then
            state.ObservedVelocity = observed
            state.ObservedAt = now
        else
            state.ObservedVelocity = nil
            state.ObservedAt = nil
        end
    end
    if
        not discontinuity
        and not root.Anchored
        and (not validVelocity or velocity.Magnitude < 0.1)
        and state.ObservedVelocity
        and now - state.ObservedAt <= 0.15
    then
        velocity = state.ObservedVelocity
    end
    if delta.Magnitude > 0.001 or discontinuity or elapsed > 0.25 then
        state.Position = position
        state.PositionAt = now
    end
    state.At = now
    local configured = tonumber(Options.grenade_prediction_time and Options.grenade_prediction_time.Value) or 0.34
    if configured ~= configured then
        configured = 0.34
    end
    configured = math.clamp(configured, 0, 1.5)
    if configured == 0 or root.Anchored or discontinuity then
        return torso.Position
    end
    if not Data['GrenadePingAt'] or now - Data['GrenadePingAt'] >= 0.5 then
        local ok, ping = pcall(function()
            return LocalPlayer:GetNetworkPing()
        end)
        Data['GrenadePing'] = ok and type(ping) == 'number' and ping == ping and math.clamp(ping * 0.5, 0, 0.25) or 0
        Data['GrenadePingAt'] = now
    end
    local lead = math.clamp(configured * scale + (Data['GrenadePing'] or 0), 0, 1.5 * scale + 0.25)
    local offset = Vector3.new(velocity.X * lead, 0, velocity.Z * lead)
    return torso.Position + offset
end
function phowg:grenade_teleport_active()
    return Toggles.grenade_tp and Toggles.grenade_tp.Value
        or Toggles.teleport_rockets and Toggles.teleport_rockets.Value
        or Toggles.auto_throw_grenade and Toggles.auto_throw_grenade.Value
        or tick() < (Data.GrenadeNukeUntil or 0)
end
function grenadetploop()
    if not phowg:grenade_teleport_active() then
        if Data.GrenadeControlledParts or Data.GrenadeMolotovParts then
            stopgrenadetp()
        end
        return
    end
    local parts = getgrenadeparts()
    if #parts == 0 then
        Data.GrenadeTeleportTarget, Data.GrenadeTeleportCharacter = nil, nil
        return
    end
    local target, torso, _humanoid, root = getgrenadetptarget()
    if not target then
        for part, controlled in pairs(Data.GrenadeControlledParts or {}) do
            releasegrenadepart(part, controlled)
        end
        Data.GrenadeControlledParts, Data.GrenadeLauncherOffsets = nil, nil
        Data.GrenadeTeleportTarget, Data.GrenadeTeleportCharacter = nil, nil
        return
    end
    Data.GrenadeTeleportTarget, Data.GrenadeTeleportCharacter = target, target.Character
    local predicted = grenadeprediction(target, torso, root)
    Data.GrenadeLauncherOffsets = Data.GrenadeLauncherOffsets or {}
    local now = tick()
    local ownerRoot = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild('HumanoidRootPart')
    local normal = Toggles.grenade_tp and Toggles.grenade_tp.Value
        or Toggles.auto_throw_grenade and Toggles.auto_throw_grenade.Value
        or now < (Data.GrenadeNukeUntil or 0)
    local seen, owners, members = {}, {}, {}
    for _, part in ipairs(parts) do
        local owner = grenadelauncherowner(part)
        owners[part] = owner
        if owner then
            if not members[owner] then
                members[owner] = {}
            end
            members[owner][#members[owner] + 1] = part
        end
    end
    for _, part in ipairs(parts) do
        local owner = owners[part]
        if owner and not seen[owner] then
            seen[owner] = true
            local primary = owner:IsA('BasePart') and owner
                or owner:FindFirstChild('Main', true)
                or owner:FindFirstChildWhichIsA('BasePart', true)
            if primary and primary:IsA('BasePart') then
                local state = Data.GrenadeLauncherOffsets[owner]
                if not state or state.Primary ~= primary then
                    state = { Primary = primary, Started = now, Offsets = {}, Sent = false }
                    Data.GrenadeLauncherOffsets[owner] = state
                end
                local present = {}
                for _, child in ipairs(members[owner]) do
                    present[child] = true
                    if not state.Offsets[child] then
                        state.Offsets[child] = child.Position - primary.Position
                    end
                end
                for child in pairs(state.Offsets) do
                    if not present[child] then
                        state.Offsets[child] = nil
                    end
                end
                local spinning = now - state.Started < 1 and ownerRoot ~= nil
                local destination = predicted
                if spinning then
                    local center = typeof(Local_Data.ClientPos) == 'CFrame' and Local_Data.ClientPos.Position
                        or ownerRoot.Position
                    local angle = (now - state.Started) * math.pi * 2
                    destination = center + Vector3.new(math.cos(angle) * 10, 2, math.sin(angle) * 10)
                end
                movegrenadepart(primary, destination, not spinning and not state.Sent, spinning)
                if not spinning then
                    state.Sent = true
                end
                for child, offset in pairs(state.Offsets) do
                    if child ~= primary and child.Parent then
                        movegrenadepart(child, primary.Position + offset, true, false)
                    end
                end
            end
        elseif not owner and normal and part.Parent and isgrenadepart(part) then
            movegrenadepart(part, predicted, true, false)
        end
    end
    for owner in pairs(Data.GrenadeLauncherOffsets) do
        if not owner.Parent or not seen[owner] then
            Data.GrenadeLauncherOffsets[owner] = nil
        end
    end
end
function phowg:nuke_grenades()
    if
        Data.NukeGrenadeJob
        or Data.Buying
        or Data.Sorting
        or Data.BuildActive
        or Data.LoadoutReloadJob
        or localactionblocked()
    then
        return
    end
    local character = LocalPlayer.Character
    local backpack = LocalPlayer:FindFirstChildOfClass('Backpack')
    if not character or not backpack then
        return
    end
    local target = get_sticky_target()
    if not target then
        Library:Notify('Select a sticky aim target first.', 3)
        return
    end
    local tools, seen = {}, {}
    for _, container in ipairs({ character, backpack }) do
        for _, tool in ipairs(container:GetChildren()) do
            if tool:IsA('Tool') and normalizeweaponname(tool.Name) == 'grenade' and not seen[tool] then
                tools[#tools + 1], seen[tool] = tool, true
            end
        end
    end
    if #tools == 0 then
        Library:Notify('No grenades in your inventory.', 3)
        return
    end
    local job = { Character = character }
    Data.NukeGrenadeJob, Data.BuildActive = job, true
    local failed, failure = 0, nil
    local function valid()
        return Data.NukeGrenadeJob == job
            and not Library.Unloaded
            and not Data.SharedSignalsClosed
            and LocalPlayer.Character == character
            and not localactionblocked()
    end
    local ok, problem = pcall(function()
        local deadline = tick() + 1.25
        local equipped = {}
        for _, tool in ipairs(tools) do
            if not valid() then
                return
            end
            local reason
            while tool.Parent == backpack and valid() do
                local accepted, blocked = phowg:request_equipment('nuke', tool, 'equip')
                reason = blocked
                if accepted and tool.Parent == character then
                    break
                end
                if tick() >= deadline then
                    break
                end
                RunService.Heartbeat:Wait()
            end
            if tool.Parent == character then
                equipped[#equipped + 1] = tool
            elseif tool.Parent == backpack then
                failed, failure = failed + 1, reason or 'tool unavailable'
            end
        end
        if not valid() or #equipped == 0 then
            return
        end
        Data.GrenadeNukeUntil = tick() + 8
        for pass = 1, 2 do
            if not valid() then
                break
            end
            for _, tool in ipairs(equipped) do
                if tool.Parent == character then
                    local activated, detail = pcall(tool.Activate, tool)
                    if not activated then
                        failed, failure = failed + 1, tostring(detail)
                    end
                end
            end
            if pass == 1 then
                RunService.Heartbeat:Wait()
            end
        end
    end)
    if Data.NukeGrenadeJob == job then
        Data.NukeGrenadeJob, Data.BuildActive = nil, nil
    end
    if not ok then
        Library:Notify('Grenade activation failed: ' .. tostring(problem), 4)
    elseif failed > 0 and not Library.Unloaded then
        Library:Notify('Could not activate every grenade: ' .. tostring(failure), 4)
    end
end

