    function phowg:neckgrab_character()
        local owner = LocalPlayer.Character
        if not owner or not owner.Parent then
            return nil
        end
        local effects = owner:FindFirstChild('BodyEffects')
        local grabbed = effects and effects:FindFirstChild('Grabbed')
        local target = grabbed and grabbed.Value
        if typeof(target) ~= 'Instance' then
            return nil
        end
        if target:IsA('Player') then
            target = target.Character
        end
        if target and target:IsA('BasePart') then
            target = target:FindFirstAncestorOfClass('Model')
        end
        local constraint = target and target:FindFirstChild('GRABBING_CONSTRAINT')
        if target and target:IsA('Model') and target ~= owner and target.Parent then
            return target, owner, grabbed, constraint
        end
        return nil
    end
    function phowg:clear_neckgrab_carry_silence()
        local state = Data.NeckgrabCarrySilence
        if not state then
            return
        end
        Data.NeckgrabCarrySilence = nil
        if state.Expiry and state.Expiry ~= coroutine.running() then
            pcall(task.cancel, state.Expiry)
        end
        if state.Played then
            state.Played:Disconnect()
        end
        for _, connection in ipairs(state.Connections) do
            connection:Disconnect()
        end
    end
    function phowg:sync_neckgrab_carry_silence(target, owner, constraint, enabled)
        local state = Data.NeckgrabCarrySilence
        if state and (Library.Unloaded or Data.SharedSignalsClosed or state.Owner ~= LocalPlayer.Character) then
            phowg:clear_neckgrab_carry_silence()
            state = nil
        end
        if Library.Unloaded or Data.SharedSignalsClosed then
            return
        end
        local carrying = target ~= nil and owner == LocalPlayer.Character
            and (enabled or state ~= nil)
            and not (Data.NeckgrabReleasedTarget == target and Data.NeckgrabReleasedConstraint == constraint)
        if not state and not carrying then
            return
        end
        if not state then
            state = { Owner = owner, Connections = {}, Carrying = true, Until = 0 }
            Data.NeckgrabCarrySilence = state
            local function silence(track)
                if Data.NeckgrabCarrySilence ~= state or state.Owner ~= LocalPlayer.Character
                    or not (state.Carrying or tick() < state.Until) then
                    return
                end
                local animation = track.Animation
                if animation and tostring(animation.AnimationId):match('%d+') == '4798175381' then
                    pcall(track.Stop, track, 0)
                end
            end
            local function bind()
                local humanoid = owner:FindFirstChildOfClass('Humanoid')
                local animator = humanoid and humanoid:FindFirstChildOfClass('Animator')
                if not animator or state.Animator == animator then
                    return
                end
                if state.Played then
                    state.Played:Disconnect()
                end
                state.Animator = animator
                state.Played = animator.AnimationPlayed:Connect(silence)
                for _, track in ipairs(animator:GetPlayingAnimationTracks()) do
                    silence(track)
                end
            end
            state.Connections[1] = owner.DescendantAdded:Connect(function(object)
                if object:IsA('Animator') then
                    bind()
                end
            end)
            state.Connections[2] = LocalPlayer.CharacterAdded:Connect(function(character)
                if character ~= owner and Data.NeckgrabCarrySilence == state then
                    phowg:clear_neckgrab_carry_silence()
                end
            end)
            bind()
        end
        if carrying then
            state.Carrying = true
            if state.Expiry then
                pcall(task.cancel, state.Expiry)
                state.Expiry = nil
            end
        elseif state.Carrying then
            state.Carrying, state.Until = false, tick() + 1
            state.Expiry = task.delay(1, function()
                if Data.NeckgrabCarrySilence == state and not state.Carrying then
                    phowg:clear_neckgrab_carry_silence()
                end
            end)
        end
    end
    phowg:register_cleanup('neckgrab carry animation', function(scope, reason)
        local state = Data.NeckgrabCarrySilence
        if state and (not scope or reason == 'unload' or scope == state.Owner or scope == state.Animator) then
            phowg:clear_neckgrab_carry_silence()
        end
    end)
    local function clear_raise_nazi_tools(session)
        if not session or session.Mode ~= 'raise' or not session.RaiseNaziEquipped or session.RaiseNaziCleaned then
            return
        end
        session.RaiseNaziCleaned = true
        local backpack = LocalPlayer and LocalPlayer:FindFirstChild('Backpack')
        local character = LocalPlayer and LocalPlayer.Character
        if not backpack then
            return
        end
        local names = {}
        for _, entry in ipairs(Data.NaziPlan or {}) do
            if entry and entry.name then
                names[entry.name] = true
            end
        end
        for tool in pairs(Data.GrippedTools or {}) do
            if tool and tool.Parent and names[tool.Name] then
                pcall(function()
                    tool.Parent = backpack
                end)
            end
        end
        if character then
            for _, tool in ipairs(character:GetChildren()) do
                if tool:IsA('Tool') and names[tool.Name] then
                    pcall(function()
                        tool.Parent = backpack
                    end)
                end
            end
        end
        Data.GrippedTools = {}
    end
    function phowg:stop_neckgrab(expected)
        local session = Data.NeckgrabSession
        if not session or expected and session ~= expected then
            return
        end
        clear_raise_nazi_tools(session)
        Data.NeckgrabSession = nil
        session.Closed = true
        for _, connection in ipairs(session.Connections) do
            pcall(connection.Disconnect, connection)
        end
        if session.Tween then
            pcall(session.Tween.Cancel, session.Tween)
        end
        for _, mover in ipairs(session.Movers) do
            pcall(mover.Destroy, mover)
        end
        for _, track in pairs(session.Tracks) do
            pcall(track.Stop, track, 0)
            pcall(track.Destroy, track)
        end
        local ownerActive = LocalPlayer.Character == session.Owner
            and session.Root.Parent == session.Owner
            and session.Owner:FindFirstChild('HumanoidRootPart') == session.Root
        local camera = Workspace.CurrentCamera
        if session.Clone then
            if camera and camera.CameraSubject == session.CloneHumanoid then
                local current = LocalPlayer.Character
                camera.CameraSubject = session.CameraSubject and session.CameraSubject.Parent and session.CameraSubject
                    or current and current:FindFirstChildOfClass('Humanoid')
            end
            session.Clone:Destroy()
        end
        for object, properties in pairs(session.Originals) do
            for key, original in pairs(properties) do
                if key ~= 'Parent' or object.Parent then
                    pcall(function()
                        local writes = session.Writes[object]
                        if not writes or writes[key] == nil or object[key] == writes[key] then
                            object[key] = original
                        end
                    end)
                end
            end
        end
        local humanoidOriginals = session.Originals[session.Humanoid]
        if humanoidOriginals and humanoidOriginals.HipHeight ~= nil then
            pcall(function()
                session.Humanoid.HipHeight = humanoidOriginals.HipHeight
            end)
        end
        if ownerActive and not Data.SpinbotActive then
            session.Root.AssemblyAngularVelocity = Vector3.zero
        end
    end
    local function remember(session, object, property, replacement)
        if not object or session.Closed then
            return
        end
        local originals = session.Originals[object]
        if not originals then
            originals = {}
            session.Originals[object] = originals
        end
        if originals[property] == nil then
            originals[property] = object[property]
        end
        local writes = session.Writes[object]
        if not writes then
            writes = {}
            session.Writes[object] = writes
        end
        writes[property] = replacement
        object[property] = replacement
    end
    local airBodyParts = {
        Head = true,
        UpperTorso = true,
        LowerTorso = true,
        LeftUpperArm = true,
        LeftLowerArm = true,
        LeftHand = true,
        RightUpperArm = true,
        RightLowerArm = true,
        RightHand = true,
        LeftUpperLeg = true,
        LeftLowerLeg = true,
        LeftFoot = true,
        RightUpperLeg = true,
        RightLowerLeg = true,
        RightFoot = true,
    }
    local function build_rig(session)
        session.Parts, session.RaiseJoints = {}, {}
        session.AirConstraints = {}
        for _, object in ipairs(session.Target:GetDescendants()) do
            if object:IsA('BasePart') then
                if object.Parent == session.Target then
                    session.Parts[object.Name] = object
                end
                remember(session, object, 'CanCollide', false)
            elseif object:IsA('Motor6D') then
                local first, second = object.Part0, object.Part1
                local raised = session.Mode == 'raise'
                    and first
                    and second
                    and first.Parent == session.Target
                    and second.Parent == session.Target
                    and (
                        first.Name == 'UpperTorso' and second.Name == 'RightUpperArm'
                        or first.Name == 'RightUpperArm' and second.Name == 'RightLowerArm'
                    )
                if raised then
                    session.RaiseJoints[second.Name] = object
                end
                if raised or session.Mode == 'Possession' or poses[session.Mode] or session.Mode == 'Orbit' then
                    remember(session, object, 'Enabled', false)
                end
            elseif object:IsA('BallSocketConstraint') or object:IsA('HingeConstraint') then
                local first, second = object.Attachment0, object.Attachment1
                first, second = first and first.Parent, second and second.Parent
                if first and second and first.Parent == session.Target and second.Parent == session.Target then
                    if airBodyParts[first.Name] and airBodyParts[second.Name] then
                        session.AirConstraints[#session.AirConstraints + 1] = object
                    end
                    local shoulder = first.Name == 'UpperTorso' and second.Name == 'RightUpperArm'
                        or second.Name == 'UpperTorso' and first.Name == 'RightUpperArm'
                    local elbow = first.Name == 'RightUpperArm' and second.Name == 'RightLowerArm'
                        or second.Name == 'RightUpperArm' and first.Name == 'RightLowerArm'
                    if session.Mode == 'raise' and (shoulder or elbow) then
                        remember(session, object, 'Enabled', false)
                    end
                end
            end
        end
        local rope = session.Constraint and session.Constraint:FindFirstChildWhichIsA('RopeConstraint', true)
        if rope then
            remember(session, rope, 'Length', math.huge)
        end
        session.Anchor, session.RigDirty = session.Parts.UpperTorso, false
        return session.Anchor ~= nil
    end
    local function stabilize_air(session, enabled, now)
        if not enabled then
            if not session.AirStabilized then
                return
            end
            for _, object in ipairs(session.AirConstraints) do
                local original = session.Originals[object]
                if object.Parent and original then
                    for property, value in pairs(original) do
                        remember(session, object, property, value)
                    end
                end
            end
            session.AirStabilized = false
            return
        end
        if
            not session.Constraint
            or not session.Constraint.Parent
            or not session.CarryConfirmedAt
            or now - session.CarryConfirmedAt < 1
        then
            return
        end
        for _, constraint in ipairs(session.AirConstraints) do
            if constraint.Parent and constraint.Enabled then
                remember(session, constraint, 'LimitsEnabled', true)
                remember(session, constraint, 'Restitution', 0)
                if constraint:IsA('BallSocketConstraint') then
                    remember(session, constraint, 'UpperAngle', 2)
                    remember(session, constraint, 'MaxFrictionTorque', 100)
                    remember(session, constraint, 'TwistLimitsEnabled', true)
                    remember(session, constraint, 'TwistLowerAngle', -1)
                    remember(session, constraint, 'TwistUpperAngle', 1)
                elseif constraint:IsA('HingeConstraint') then
                    remember(session, constraint, 'LowerAngle', -1)
                    remember(session, constraint, 'UpperAngle', 1)
                end
            end
        end
        session.AirStabilized = true
    end
    local function move_part(session, part, cf, power, damping)
        if session.Closed or Data.NeckgrabSession ~= session or not part or part.Parent ~= session.Target then
            return
        end
        local movers = session.Aligned[part]
        if not movers then
            local position = createbodymover('BodyPosition', part)
            position.Name, position.MaxForce = 'PhowgNeckPosition', Vector3.new(math.huge, math.huge, math.huge)
            local gyro = createbodymover('BodyGyro', part)
            gyro.Name, gyro.MaxTorque, gyro.P = 'PhowgNeckRotation', Vector3.new(9e9, 9e9, 9e9), 10000
            movers = { Position = position, Gyro = gyro }
            session.Aligned[part] = movers
            session.Movers[#session.Movers + 1], session.Movers[#session.Movers + 2] = position, gyro
        end
        movers.Position.Position = cf.Position
        movers.Position.P, movers.Position.D = power or 10000, damping or 175
        movers.Gyro.CFrame = cf
    end
    local function align(session, name, reference, offset, rotation, power, damping)
        if session.Closed or Data.NeckgrabSession ~= session then
            return
        end
        local part = session.Parts[name]
        local anchor = session.Owner:FindFirstChild(reference)
        if not part or not part.Parent or not anchor then
            return
        end
        session.Aligned = session.Aligned or {}
        local movers = session.Aligned[part]
        if not movers then
            local position = createbodymover('BodyPosition', part)
            position.Name, position.MaxForce = 'PhowgNeckPosition', Vector3.new(math.huge, math.huge, math.huge)
            local gyro = createbodymover('BodyGyro', part)
            gyro.Name, gyro.MaxTorque, gyro.P = 'PhowgNeckRotation', Vector3.new(9e9, 9e9, 9e9), 10000
            movers = { Position = position, Gyro = gyro }
            session.Aligned[part] = movers
            session.Movers[#session.Movers + 1], session.Movers[#session.Movers + 2] = position, gyro
        end
        movers.Position.Position = anchor.CFrame * offset.Position
        movers.Position.P, movers.Position.D = power or 10000, damping or 175
        movers.Gyro.CFrame = anchor.CFrame * rotation
    end
    local function raise_arm(session)
        local torso, upper, lower = session.Parts.UpperTorso, session.Parts.RightUpperArm, session.Parts.RightLowerArm
        local shoulder, elbow = session.RaiseJoints.RightUpperArm, session.RaiseJoints.RightLowerArm
        if
            not torso
            or torso.Parent ~= session.Target
            or not upper
            or upper.Parent ~= session.Target
            or not shoulder
            or shoulder.Parent == nil
        then
            return
        end
        local cf = torso.CFrame
            * CFrame.new(shoulder.C0.Position)
            * CFrame.Angles(math.rad(130), 0, 0)
            * shoulder.C0.Rotation
            * shoulder.C1:Inverse()
        move_part(session, upper, cf)
        upper.CFrame = cf
        if lower and lower.Parent == session.Target and elbow and elbow.Parent then
            cf = cf * elbow.C0 * elbow.C1:Inverse()
            move_part(session, lower, cf)
            lower.CFrame = cf
        end
    end
    local function play(session, id, speed, time, humanoid)
        if session.Closed or Data.NeckgrabSession ~= session then
            return nil
        end
        humanoid = humanoid or session.Humanoid
        local key = tostring(id) .. ':' .. (humanoid == session.Humanoid and 'owner' or 'clone')
        local track = session.Tracks[key]
        if not track then
            local animator = humanoid:FindFirstChildOfClass('Animator')
            if not animator then
                return nil
            end
            local animation = Instance.new('Animation')
            animation.AnimationId = 'rbxassetid://' .. id
            local ok, result = pcall(animator.LoadAnimation, animator, animation)
            animation:Destroy()
            if not ok then
                return nil
            end
            if session.Closed or Data.NeckgrabSession ~= session then
                result:Destroy()
                return nil
            end
            track = result
            track.Priority = Enum.AnimationPriority.Action4
            track:Play(0.1)
            session.Tracks[key] = track
        end
        if speed then
            track:AdjustSpeed(speed)
        end
        if time then
            track.TimePosition = time
        end
        return track
    end
    local function equip_prop(session, name, grip)
        local backpack = LocalPlayer:FindFirstChildOfClass('Backpack')
        local tool = session.Owner:FindFirstChild(name) or backpack and backpack:FindFirstChild(name)
        if not tool or not tool:IsA('Tool') or not phowg:tool_grip_allowed(tool) then
            return
        end
        local parent = tool.Parent
        if phowg:request_equipment('equip', tool, 'equip') and not session.Closed and Data.NeckgrabSession == session then
            remember(session, tool, 'Grip', grip)
            session.Originals[tool].Parent = parent
        end
    end
    local function carry_idle(session, enabled, now)
        if not enabled then
            if session.CarryIdleTrack then
                session.CarryIdleTrack:Stop(0.15)
                session.CarryIdleTrack = nil
            end
            return
        end
        if now < (session.CarryIdleCheckAt or 0) then
            return
        end
        session.CarryIdleCheckAt = now + 0.5
        local animate = session.Owner:FindFirstChild('Animate')
        local idle = animate and animate:FindFirstChild('idle')
        local selected, weight = nil, -1
        if idle then
            for _, animation in ipairs(idle:GetChildren()) do
                if animation:IsA('Animation') and animation.AnimationId ~= '' then
                    local value = animation:FindFirstChild('Weight')
                    local current = value and tonumber(value.Value) or 1
                    if current > weight then
                        selected, weight = animation, current
                    end
                end
            end
        end
        local id = selected and tonumber(selected.AnimationId:match('%d+'))
        local humanoid = session.Target:FindFirstChildOfClass('Humanoid')
        if not id or not humanoid then
            return
        end
        if session.CarryIdleId == id and session.CarryIdleTrack and session.CarryIdleTrack.IsPlaying then
            return
        end
        if session.CarryIdleTrack then
            session.CarryIdleTrack:Stop(0.15)
        end
        local track = play(session, id, 1, nil, humanoid)
        session.CarryIdleId, session.CarryIdleTrack = id, track
        if track then
            track.Looped = true
            if not track.IsPlaying then
                track:Play(0.15)
            end
        end
    end
    local function carry_facing(session, cf)
        local look = cf.LookVector
        local forward = Vector3.new(look.X, 0, look.Z)
        if forward.Magnitude < 0.0001 then
            forward = session.CarryForward or Vector3.new(0, 0, -1)
        end
        forward = forward.Unit
        session.CarryForward = forward
        return CFrame.lookAt(Vector3.zero, forward)
    end
    function phowg:return_neckgrab_to_air(expected)
        local session = Data.NeckgrabSession
        if not session or session.Mode ~= 'raise' or expected and session ~= expected then
            return false
        end
        local torso = session.Parts.UpperTorso
        local from = torso and torso.Parent == session.Target and torso.CFrame
        phowg:stop_neckgrab(session)
        if not from or not phowg:start_neckgrab('Holding') then
            return false
        end
        local current = Data.NeckgrabSession
        current.ReturnFrom, current.ReturnStarted = from, tick()
        if current.Constraint == session.Constraint then
            current.CarryConfirmedAt = session.CarryConfirmedAt
        end
        if Options.neckgrab_animation and Options.neckgrab_animation.Value ~= 'air' then
            Options.neckgrab_animation:SetValue('air')
        end
        move_part(current, current.Parts.UpperTorso, from)
        return true
    end
    function phowg:start_neckgrab(mode)
        if Data.Saving then
            return false
        end
        local target, owner, grabbed, constraint = phowg:neckgrab_character()
        if not target or localactionblocked() then
            return false
        end
        local humanoid = owner:FindFirstChildOfClass('Humanoid')
        local root = owner:FindFirstChild('HumanoidRootPart')
        if not humanoid or humanoid.Health <= 0 or not root then
            return false
        end
        if not target:FindFirstChild('UpperTorso') then
            if Data.NeckgrabUnsupportedTarget ~= target then
                Library:Notify('Neckgrab requires an R15 character.', 3)
                Data.NeckgrabUnsupportedTarget = target
            end
            return false
        end
        local previous = Data.NeckgrabSession
        if
            mode == 'raise'
            and previous
            and previous.Mode == mode
            and previous.Target == target
            and previous.Owner == owner
        then
            return phowg:return_neckgrab_to_air(previous)
        end
        local carryConfirmedAt = previous
            and previous.Target == target
            and previous.Owner == owner
            and previous.Constraint == constraint
            and previous.CarryConfirmedAt
        Data.NeckgrabUnsupportedTarget, Data.NeckgrabReleasedTarget, Data.NeckgrabReleasedConstraint = nil, nil, nil
        phowg:stop_neckgrab()
        local session: { [string]: any } = {
            Target = target,
            Owner = owner,
            Humanoid = humanoid,
            Root = root,
            Mode = mode or 'Holding',
            Started = tick(),
            LastAt = tick(),
            Parts = {},
            Originals = {},
            Writes = {},
            Movers = {},
            Aligned = {},
            Tracks = {},
            Connections = {},
            Stage = 0,
            Closed = false,
        }
        Data.NeckgrabSession = session
        session.Constraint = constraint
        session.CarryConfirmedAt = constraint and (carryConfirmedAt or tick()) or nil
        local targetRoot = target:FindFirstChild('HumanoidRootPart')
        if not targetRoot or not build_rig(session) then
            phowg:stop_neckgrab(session)
            return false
        end
        phowg:sync_neckgrab_carry_silence(target, owner, constraint, true)
        if session.Mode == 'raise' then
            session.RaiseFrom, session.RaiseStarted = session.Parts.UpperTorso.CFrame, tick()
            session.RaiseEquipAt, session.RaiseNaziEquipped = tick() + 1.5, false
            move_part(session, session.Parts.UpperTorso, session.RaiseFrom)
        end
        local function listen(signal, callback, label)
            session.Connections[#session.Connections + 1] = connectshared(signal, callback, owner, 'neckgrab/' .. label)
        end
        local function lost()
            if Data.NeckgrabSession ~= session then
                return
            end
            local current, currentOwner, currentValue = phowg:neckgrab_character()
            if current ~= target or currentOwner ~= owner or currentValue ~= grabbed then
                phowg:stop_neckgrab(session)
            end
        end
        local function constraint_lost()
            if Data.NeckgrabSession ~= session then
                return
            end
            phowg:stop_neckgrab(session)
            Data.NeckgrabReleasedTarget, Data.NeckgrabReleasedConstraint = target, nil
        end
        listen(grabbed:GetPropertyChangedSignal('Value'), lost, 'grab changed')
        if constraint then
            listen(constraint.Destroying, constraint_lost, 'constraint destroyed')
        end
        listen(target.ChildRemoved, function(child)
            if child == constraint then
                constraint_lost()
            elseif child == session.Anchor or child == targetRoot then
                phowg:stop_neckgrab(session)
            end
        end, 'target removed')
        listen(target.AncestryChanged, lost, 'target ancestry')
        listen(owner.AncestryChanged, lost, 'owner ancestry')
        listen(LocalPlayer:GetPropertyChangedSignal('Character'), lost, 'owner changed')
        listen(owner.DescendantRemoving, function(object)
            if object == grabbed or object == root then
                phowg:stop_neckgrab(session)
            end
        end, 'owner removed')
        local function rig_changed(object)
            if
                object:IsA('Motor6D')
                or object:IsA('Constraint')
                or object:IsA('BasePart') and object.Parent == target
            then
                session.RigDirty = true
            end
        end
        listen(target.DescendantAdded, rig_changed, 'rig added')
        listen(target.DescendantRemoving, rig_changed, 'rig removed')
        lost()
        if session.Closed then
            return false
        end
        for _, track in ipairs(humanoid:GetPlayingAnimationTracks()) do
            if track.Animation and track.Animation.AnimationId:find('11075367458', 1, true) then
                track:Stop()
            end
        end
        if poses[mode] then
            remember(
                session,
                humanoid,
                'HipHeight',
                mode == 'Minecraft Pig' and 2.4 or mode == 'Airplane' and 5.4 or 0.6
            )
            remember(session, owner:FindFirstChild('Animate'), 'Enabled', false)
            play(session, 12520993168)
            if mode == 'Minecraft Pig' then
                equip_prop(session, '[Pitchfork]', CFrame.new(1.5, 2.3, 0) * CFrame.Angles(-math.pi / 2, 0, 0))
                equip_prop(session, '[Chicken]', CFrame.new(1.5, 0, -4.4) * CFrame.Angles(math.pi, 0, 0))
            end
        elseif mode == 'Orbit' then
            local track = play(session, 11394033602)
            if track then
                track.Looped = true
            end
        elseif mode == 'Possession' then
            local archivable = target.Archivable
            target.Archivable = true
            local ok, clone = pcall(target.Clone, target)
            target.Archivable = archivable
            if not ok or not clone then
                phowg:stop_neckgrab(session)
                return false
            end
            session.Clone = clone
            for _, object in ipairs(clone:GetDescendants()) do
                if object:IsA('BasePart') then
                    object.Transparency, object.CanCollide, object.Anchored = 1, false, false
                elseif object:IsA('Decal') then
                    object.Transparency = 1
                elseif object:IsA('Motor6D') then
                    object.Enabled = true
                elseif
                    object:IsA('LuaSourceContainer')
                    or object:IsA('BodyMover')
                    or object:IsA('Constraint')
                    or object:IsA('Beam')
                    or object:IsA('Highlight')
                then
                    object:Destroy()
                end
            end
            for _, name in ipairs({ 'GRABBING_CONSTRAINT', 'BodyEffects', 'RagdollConstraints' }) do
                local object = clone:FindFirstChild(name)
                if object then
                    object:Destroy()
                end
            end
            local clonedHumanoid, clonedRoot =
                clone:FindFirstChildOfClass('Humanoid'), clone:FindFirstChild('HumanoidRootPart')
            if not clonedHumanoid or not clonedRoot then
                phowg:stop_neckgrab(session)
                return false
            end
            session.CloneHumanoid, session.CloneRoot = clonedHumanoid, clonedRoot
            clone.Name = 'PhowgNeckgrabControl'
            clone.Parent = owner
            clone:PivotTo(root.CFrame)
            local camera = Workspace.CurrentCamera
            if camera then
                session.CameraSubject = camera.CameraSubject
                camera.CameraSubject = clonedHumanoid
            end
        elseif mode == 'Dog' then
            equip_prop(session, '[Pitchfork]', CFrame.new(0, 2.3, 0) * CFrame.Angles(-math.pi * 0.45, 0, 0))
        end
        return not session.Closed and Data.NeckgrabSession == session
    end
    function phowg:dismember_grabbed(parts, height, expected)
        if expected and (expected.Closed or Data.NeckgrabSession ~= expected) then
            return
        end
        local target = phowg:neckgrab_character()
        if not target then
            return
        end
        for _, name in ipairs(parts) do
            local part = target:FindFirstChild(name)
            if part and part:IsA('BasePart') then
                part.CFrame = CFrame.new(0, height or -600, 0)
            end
        end
    end
    local function release(session)
        if session.Closed or Data.NeckgrabSession ~= session or session.Released then
            return
        end
        session.Released = true
        phowg:sync_neckgrab_carry_silence(nil, session.Owner, nil, false)
        if MainEvent then
            MainEvent:FireServer('Grabbing')
        end
        phowg:stop_neckgrab(session)
        Data.NeckgrabReleasedTarget, Data.NeckgrabReleasedConstraint = session.Target, session.Constraint
    end
    local function advance_attack(session, elapsed)
        if session.Closed or Data.NeckgrabSession ~= session then
            return
        end
        local mode = session.Mode
        local launchAt = mode == 'Archer Slingshot' and 2.7
            or mode == 'Praise Push' and 5.2
            or mode == 'Combo' and 9.1
            or 0.9
        if mode == 'Nugget Slingshot' and elapsed >= 0.6 and session.Stage == 0 then
            play(session, 2788292075, 1.4)
            session.Stage = 1
        end
        if mode == 'Nugget Slingshot' and elapsed >= 0.8 and session.Stage == 1 then
            session.Tween =
                game:GetService('TweenService')
                    :Create(session.Root, TweenInfo.new(0.1), { CFrame = session.Root.CFrame * CFrame.new(0, 0, -20) })
            session.Tween:Play()
            session.Stage = 2
        elseif mode == 'Archer Slingshot' and session.Stage == 0 then
            play(session, 13823324057)
            session.Stage = 1
        elseif mode == 'Praise Push' then
            if elapsed >= 0.6 and session.Stage == 0 then
                play(session, 10714164866, 1.1)
                session.Stage = 1
            end
            if elapsed >= 0.6 and elapsed < 2.6 then
                session.Root.AssemblyLinearVelocity = Vector3.new(0, 15, 0)
            end
            if elapsed >= 2.6 and session.Stage == 1 then
                play(session, 10714164866, 0, 1.7)
                session.Stage = 2
            end
        elseif mode == 'Combo' and elapsed >= 1.8 and elapsed < 9 then
            if session.Stage == 0 then
                session.Root.CFrame *= CFrame.new(0, 0, -10)
                session.Stage = 1
            end
            local phase = math.floor((elapsed - 1.8) / 0.03)
            if phase ~= session.ComboPhase then
                session.ComboPhase = phase
                local shifts = {
                    CFrame.new(0, 0, -4),
                    CFrame.new(0, 0, 8),
                    CFrame.new(0, 0, -4),
                    CFrame.new(-4, 0, 0),
                    CFrame.new(8, 0, 0),
                    CFrame.new(-4, 0, 0),
                }
                session.Root.CFrame *= shifts[phase % 6 + 1]
                play(session, 2788292075, 1.4)
            end
        end
        local offset = elapsed >= launchAt
                and (mode == 'Praise Push' and CFrame.new(0, 0, -200) or mode == 'Combo' and CFrame.new(0, 30, -150) or CFrame.new(
                    0,
                    100,
                    -270
                ))
            or CFrame.new(0, 0, -10)
        local rotation = elapsed >= launchAt and CFrame.Angles(-math.pi * 0.2, math.pi, 0)
            or CFrame.Angles(0, math.pi, 0)
        align(session, 'UpperTorso', 'HumanoidRootPart', offset, rotation, 8000, 800)
        if elapsed >= launchAt + 0.2 and not session.Dismembered then
            session.Dismembered = true
            phowg:dismember_grabbed({ 'RightUpperArm', 'LeftUpperArm', 'RightUpperLeg', 'LeftUpperLeg' }, -1200, session)
        end
        if elapsed >= launchAt + 0.5 then
            release(session)
        end
    end
    function phowg:update_neckgrab()
        local enabled = not Data.Saving and Toggles.neckgrab_enabled and Toggles.neckgrab_enabled.Value
        local target, owner, _grabbed, constraint = phowg:neckgrab_character()
        phowg:sync_neckgrab_carry_silence(target, owner, constraint, enabled)
        local session = Data.NeckgrabSession
        if not enabled or not target or localactionblocked() or Library.Unloaded or Data.SharedSignalsClosed then
            phowg:stop_neckgrab()
            if not target then
                Data.NeckgrabReleasedTarget, Data.NeckgrabReleasedConstraint, Data.NeckgrabUnsupportedTarget =
                    nil, nil, nil
            end
            return
        end
        if Data.NeckgrabReleasedTarget == target and Data.NeckgrabReleasedConstraint == constraint then
            return
        end
        Data.NeckgrabReleasedTarget, Data.NeckgrabReleasedConstraint = nil, nil
        if session and (session.Target ~= target or session.Owner ~= owner) then
            phowg:stop_neckgrab(session)
            session = nil
        elseif session and session.Constraint ~= constraint then
            local mode, from, started = session.Mode, session.ReturnFrom, session.ReturnStarted
            local raiseFrom, raiseStarted = session.RaiseFrom, session.RaiseStarted
            phowg:stop_neckgrab(session)
            if not phowg:start_neckgrab(mode) then
                return
            end
            session = Data.NeckgrabSession
            if session then
                session.ReturnFrom, session.ReturnStarted = from, started
                session.RaiseFrom, session.RaiseStarted = raiseFrom, raiseStarted
            end
        end
        if not session then
            if not phowg:start_neckgrab('Holding') then
                return
            end
            session = Data.NeckgrabSession
        end
        if not session or session.Closed or session.Humanoid.Health <= 0 or not session.Root.Parent then
            phowg:stop_neckgrab()
            return
        end
        local now = tick()
        local dt = math.clamp(now - session.LastAt, 0, 0.1)
        session.LastAt = now
        local elapsed = now - session.Started
        if elapsed < 1 then
            for _, track in ipairs(session.Humanoid:GetPlayingAnimationTracks()) do
                if track.Animation and track.Animation.AnimationId:find('11075367458', 1, true) then
                    track:Stop()
                end
            end
        end
        if session.RigDirty and not build_rig(session) then
            phowg:stop_neckgrab(session)
            return
        end
        for _, part in pairs(session.Parts) do
            if part.Parent then
                part.AssemblyLinearVelocity, part.AssemblyAngularVelocity, part.CanCollide =
                    Vector3.zero, Vector3.zero, false
            end
        end
        local mode = session.Mode
        if poses[mode] then
            local torso = owner:FindFirstChild('LowerTorso')
            if torso then
                for name, offset in pairs(poses[mode]) do
                    local part = session.Parts[name]
                    if part and part.Parent then
                        part.CFrame = torso.CFrame * offset
                    end
                end
            end
        elseif mode == 'Orbit' then
            local radius = 10 + math.sin(elapsed * 2) * 3
            for name, parameters in pairs(orbit) do
                local part = session.Parts[name]
                if part and part.Parent then
                    part.CFrame = CFrame.Angles(
                        math.pi * parameters[1],
                        parameters[2] * math.pi * parameters[3] * elapsed,
                        0
                    ) * CFrame.new(radius, parameters[4], radius + parameters[5]) + session.Root.Position
                end
            end
        elseif mode == 'Dog' then
            align(session, 'UpperTorso', 'RightUpperArm', CFrame.new(0, -5.6, 0.5), CFrame.Angles(-math.pi / 2, 0, 0))
        elseif mode == 'Instant Void' then
            for _, part in pairs(session.Parts) do
                if part.Parent then
                    part.Anchored = false
                    part.CFrame = CFrame.new(0, -1e6, 0)
                end
            end
            release(session)
        elseif mode == 'Possession' then
            if not session.Clone or not session.Clone.Parent or session.CloneHumanoid.Health <= 0 then
                phowg:stop_neckgrab()
                return
            end
            session.Root.CFrame = session.CloneRoot.CFrame * CFrame.new(0, -20, 0) * CFrame.Angles(math.pi / 2, 0, 0)
            for name, part in pairs(session.Parts) do
                local copy = session.Clone:FindFirstChild(name)
                if part.Parent and copy and copy:IsA('BasePart') then
                    part.CFrame = copy.CFrame
                end
            end
            session.CloneHumanoid.Jump = session.Humanoid.Jump
            session.CloneHumanoid:Move(session.Humanoid.MoveDirection, false)
            for _, track in ipairs(session.Humanoid:GetPlayingAnimationTracks()) do
                local id = track.Animation and track.Animation.AnimationId:match('%d+')
                if id and transfer[id] then
                    track:Stop()
                    play(session, tonumber(id), 1, nil, session.CloneHumanoid)
                end
            end
        elseif mode == 'raise' then
            if not session.RaiseNaziEquipped and now >= (session.RaiseEquipAt or math.huge) then
                session.RaiseNaziEquipped = true
                task.spawn(equipnazi)
            end
            local look = session.Root.CFrame.LookVector
            local forward = Vector3.new(look.X, 0, look.Z)
            if forward.Magnitude < 0.0001 then
                local right = session.Root.CFrame.RightVector
                forward = session.RaiseForward or Vector3.new(right.Z, 0, -right.X)
                if forward.Magnitude < 0.0001 then
                    forward = Vector3.new(0, 0, -1)
                end
            end
            forward = forward.Unit
            session.RaiseForward = forward
            local position = session.Root.Position + forward * 10 + Vector3.new(0, 6, 0)
            local facing = Vector3.new(session.Root.Position.X, position.Y, session.Root.Position.Z)
            local goal = CFrame.lookAt(position, facing)
            if session.RaiseFrom then
                local alpha = math.clamp((now - session.RaiseStarted) / 0.9, 0, 1)
                goal = session.RaiseFrom:Lerp(goal, alpha * alpha * (3 - 2 * alpha))
                if alpha >= 1 then
                    session.RaiseFrom, session.RaiseStarted = nil, nil
                end
            end
            move_part(session, session.Parts.UpperTorso, goal)
            raise_arm(session)
            stabilize_air(session, true, now)
            carry_idle(session, true, now)
        elseif mode ~= 'Holding' then
            advance_attack(session, elapsed)
        else
            local rotation = CFrame.Angles(0, math.rad(value('facing_angle', 0)), 0)
            local air = not Options.neckgrab_animation or Options.neckgrab_animation.Value == 'air'
            local offset = CFrame.new(
                value('offset_x', 0),
                value('offset_y', 0) + (air and 5 or 0),
                value('offset_z', 0) + (air and 5 or 0)
            )
            if Toggles.neckgrab_circle and Toggles.neckgrab_circle.Value then
                session.Angle = (session.Angle or 0) + dt * 3 * value('circle_speed', 1)
                offset = CFrame.new(
                    math.cos(session.Angle) * value('circle_radius', 5),
                    value('circle_height', 0) + (air and 5 or 0),
                    math.sin(session.Angle) * value('circle_radius', 5)
                )
                local point = session.Root.Position + offset.Position
                if (point - session.Root.Position).Magnitude > 0.001 then
                    rotation = CFrame.lookAt(point, session.Root.Position).Rotation
                end
            end
            if session.ReturnFrom then
                local alpha = math.clamp((now - session.ReturnStarted) / 0.9, 0, 1)
                local facing = session.Root.CFrame.Rotation * rotation
                if air then
                    facing = carry_facing(session, facing)
                end
                local goal = CFrame.new(session.Root.CFrame * offset.Position) * facing
                move_part(
                    session,
                    session.Parts.UpperTorso,
                    session.ReturnFrom:Lerp(goal, alpha * alpha * (3 - 2 * alpha))
                )
                if alpha >= 1 then
                    session.ReturnFrom, session.ReturnStarted = nil, nil
                end
            else
                align(session, 'UpperTorso', 'HumanoidRootPart', offset, rotation)
                if air then
                    session.Aligned[session.Parts.UpperTorso].Gyro.CFrame =
                        carry_facing(session, session.Root.CFrame.Rotation * rotation)
                end
            end
            stabilize_air(session, air, now)
            carry_idle(session, air, now)
        end
    end
    function phowg:sync_neckgrab_tools()
        Data.NeckgrabTools = Data.NeckgrabTools or {}
        local character = LocalPlayer.Character
        local backpack = LocalPlayer:FindFirstChildOfClass('Backpack')
        for index, name in ipairs(modes) do
            local record = Data.NeckgrabTools[name]
            local toggle = Toggles['neckgrab_tool_' .. index]
            local wanted = toggle
                and toggle.Value
                and character
                and backpack
                and not Library.Unloaded
                and not Data.SharedSignalsClosed
            if record and (not wanted or record.Tool.Parent ~= character and record.Tool.Parent ~= backpack) then
                record.Connection:Disconnect()
                record.Tool:Destroy()
                Data.NeckgrabTools[name] = nil
                record = nil
            end
            if wanted and not record then
                local tool = Instance.new('Tool')
                tool.Name, tool.RequiresHandle, tool.CanBeDropped = name, false, false
                tool.Parent = backpack
                local connection = connectshared(tool.Activated, function()
                    if not Toggles.neckgrab_enabled.Value then
                        Toggles.neckgrab_enabled:SetValue(true)
                    end
                    if name ~= 'raise' and tool.Parent == LocalPlayer.Character then
                        tool.Parent = backpack
                    end
                    if not phowg:start_neckgrab(name) then
                        Library:Notify('Grab an R15 player first.', 3)
                    end
                end, tool, 'neckgrab/tool activation', 0, 'event/Activated', tool)
                Data.NeckgrabTools[name] = { Tool = tool, Connection = connection }
            end
        end
    end
