        activation:AddToggle('neckgrab_enabled', {
            Text = 'enable neckgrabs',
            Default = false,
            Callback = function(enabled)
                if not enabled then
                    phowg:stop_neckgrab()
                    Data.NeckgrabReleasedTarget, Data.NeckgrabReleasedConstraint = nil, nil
                end
            end,
        })
        activation:AddDropdown(
            'neckgrab_animation',
            { Text = 'grab animation', Values = { 'air', 'posses' }, Default = 'air', Multi = false }
        )
        activation
            :AddButton('stop current pose', function()
                if Data.NeckgrabSession and Data.NeckgrabSession.Mode == 'raise' then
                    phowg:return_neckgrab_to_air(Data.NeckgrabSession)
                else
                    phowg:stop_neckgrab()
                end
            end)
            :AddButton('release', function()
                local session = Data.NeckgrabSession
                if session then
                    release(session)
                elseif MainEvent and phowg:neckgrab_character() then
                    MainEvent:FireServer('Grabbing')
                end
            end)
        local tools = tab:AddLeftGroupbox('neckgrabs')
