        )
        for _, axis in ipairs({ 'x', 'y', 'z' }) do
            position:AddSlider(
                'neckgrab_offset_' .. axis,
                { Text = axis, Default = 0, Min = -40, Max = 40, Rounding = 0, Compact = true }
            )
        end
        position:AddToggle('neckgrab_circle', { Text = 'orbit', Default = false })
        position:AddSlider(
            'neckgrab_circle_speed',
            { Text = 'orbit speed', Default = 1, Min = -10, Max = 10, Rounding = 1, Compact = true }
        )
        position:AddSlider(
            'neckgrab_circle_radius',
            { Text = 'orbit distance', Default = 5, Min = 1, Max = 20, Rounding = 1, Suffix = ' studs', Compact = true }
        )
        position:AddSlider(
            'neckgrab_circle_height',
            { Text = 'orbit height', Default = 0, Min = -30, Max = 40, Rounding = 1, Suffix = ' studs', Compact = true }
        )
        local dismember = tab:AddRightGroupbox('dismember')
        local entries = {
            { 'both arms', { 'LeftUpperArm', 'RightUpperArm' } },
            { 'both legs', { 'LeftUpperLeg', 'RightUpperLeg' } },
            { 'nugget', { 'LeftUpperLeg', 'RightUpperLeg', 'LeftUpperArm', 'RightUpperArm' } },
            { 'left arm', { 'LeftUpperArm' } },
            { 'right arm', { 'RightUpperArm' } },
            { 'left leg', { 'LeftUpperLeg' } },
            { 'right leg', { 'RightUpperLeg' } },
            { 'left hand', { 'LeftLowerArm' } },
            { 'right hand', { 'RightLowerArm' } },
            { 'left foot', { 'LeftLowerLeg' } },
            { 'right foot', { 'RightLowerLeg' } },
            { 'spine', { 'LowerTorso' } },
        }
        for _, entry in ipairs(entries) do
            dismember:AddButton(entry[1], function()
                phowg:dismember_grabbed(entry[2])
            end)
        end
        registerheartbeat('Neckgrab', phowg.update_neckgrab, 0, function()
            return Data.NeckgrabSession ~= nil or Data.NeckgrabCarrySilence ~= nil or Toggles.neckgrab_enabled.Value
        end)
        registerheartbeat('NeckgrabTools', phowg.sync_neckgrab_tools, 0.2, function()
            if next(Data.NeckgrabTools or {}) then
                return true
            end
            for index in ipairs(modes) do
                if Toggles['neckgrab_tool_' .. index].Value then
                    return true
                end
            end
            return false
        end)
    end
    phowg:register_cleanup('neckgrab', function(scope)
        local session = Data.NeckgrabSession
        if
            not scope
            or scope == LocalPlayer.Character
            or session and (scope == session.Owner or scope == session.Target)
        then
            phowg:stop_neckgrab()
            Data.NeckgrabReleasedTarget, Data.NeckgrabReleasedConstraint = nil, nil
            for name, record in pairs(Data.NeckgrabTools or {}) do
                record.Connection:Disconnect()
                record.Tool:Destroy()
                Data.NeckgrabTools[name] = nil
            end
        end
    end)
end

local function getrockettptarget()
    if not (Toggles.teleport_rockets and Toggles.teleport_rockets.Value) or localactionblocked() then
        return nil
    end
    local character = LocalPlayer.Character
    local root = character and character:FindFirstChild('HumanoidRootPart')
    if not root then
        return nil
    end
    local candidates = {
        Data['CurrentActionTarget'],
        Data['CurrentMainTarget'],
        Data['SingleLockedTarget'],
        Data['AssistLockedTarget'],
        Data['SilentAimTarget'],
        getselectedtarget(),
    }
    for index = 1, 6 do
        local target = candidates[index]
        if
            target
            and target ~= LocalPlayer
            and target.Parent
            and intelligence:get_character_cache(target)
            and target.Character
        then
            if
                not iswhitelistedplayer(target)
                and not iscrewwhitelisted(target)
                and not (Data['RageWhitelist'] and Data['RageWhitelist'][target])
                and not (Data['SupportCompletedTargets'] and Data['SupportCompletedTargets'][target])
            then
                local aim = target.Character:FindFirstChild('UpperTorso')
                    or target.Character:FindFirstChild('Torso')
                    or target.Character:FindFirstChild('HumanoidRootPart')
                if aim then
                    return target, aim
                end
            end
        end
    end
    return nil
end
local function isrocketpart(part)
    local ignored = Workspace:FindFirstChild('Ignored')
    if
        not ignored
        or not part:IsA('BasePart')
        or part.Name ~= 'Launcher'
        or not part:IsDescendantOf(ignored)
        or grenadelauncherowner(part)
    then
        return false
    end
    local ancestor = part.Parent
    while ancestor and ancestor ~= ignored do
        if
            ancestor:IsA('Tool')
            or ancestor.Name == 'Shop'
            or ancestor.Name == 'Drop'
            or ancestor:FindFirstChildOfClass('Humanoid')
        then
            return false
        end
        ancestor = ancestor.Parent
    end
    return true
end
local function releaserockettp(object)
    local state = Data.RocketTPParts and Data.RocketTPParts[object]
    if not state then
        return
    end
    Data.RocketTPParts[object] = nil
    state.Released = true
    if state.Follow then
        state.Follow:Disconnect()
    end
    if state.Destroy then
        state.Destroy:Disconnect()
    end
end
local function stoprockettp()
    local connection = Connections.RocketTPAdded
    if connection then
        connection:Disconnect()
        Connections.RocketTPAdded = nil
    end
    local parts = Data.RocketTPParts
    if parts then
        local pending = {}
        for object in pairs(parts) do
            pending[#pending + 1] = object
        end
        for _, object in ipairs(pending) do
            releaserockettp(object)
        end
    end
    Data.RocketTPFolder, Data.RocketTPParts = nil, nil
end
local function trackrockettp(object)
    local ignored = Data.RocketTPFolder
    if
        not ignored
        or object.Parent ~= ignored
        or object.Name ~= 'Model'
        or not getrockettptarget()
        or Data.RocketTPParts[object]
    then
        return
    end
    local state = { Released = false }
    Data.RocketTPParts[object] = state
    state.Destroy = connectshared(object.Destroying, function()
        releaserockettp(object)
    end, object, 'rocket teleport/destroy', 0, 'event/Destroying', object)
    task.spawn(function()
        local part = object:WaitForChild('Launcher', 5)
        if state.Released or Data.RocketTPFolder ~= ignored or object.Parent ~= ignored then
            return
        end
        if not part or not part:IsA('BasePart') then
            releaserockettp(object)
            return
        end
        part.CFrame = CFrame.new(1, 1, 1)
        local velocity = part:FindFirstChild('BodyVelocity')
        local touch = part:FindFirstChild('TouchInterest')
        if velocity then
            velocity:Destroy()
        end
        if touch then
            touch:Destroy()
        end
        state.Follow = connectshared(RunService.PostSimulation, function()
            if
                Library.Unloaded
                or state.Released
                or not (Toggles.teleport_rockets and Toggles.teleport_rockets.Value)
                or object.Parent ~= ignored
                or not part:IsDescendantOf(object)
            then
                releaserockettp(object)
                return
            end
            local target = getrockettptarget()
            local root = target and target.Character and target.Character:FindFirstChild('HumanoidRootPart')
            if root then
                part.CFrame = root.CFrame
                part.Velocity = Vector3.new(0, 0.001, 0)
            end
        end, object, 'rocket teleport/post simulation', 0, 'event/PostSimulation', RunService)
    end)
end
local function teleportrocketsloop()
    if not (Toggles.teleport_rockets and Toggles.teleport_rockets.Value) then
        stoprockettp()
        return
    end
    local ignored = Workspace:FindFirstChild('Ignored')
    if Data.RocketTPFolder ~= ignored then
        stoprockettp()
        if ignored then
            Data.RocketTPFolder, Data.RocketTPParts = ignored, {}
            create_connection(
                'RocketTPAdded',
                connectshared(
                    ignored.ChildAdded,
                    trackrockettp,
                    ignored,
                    'rocket teleport/child added',
                    0,
                    'event/ChildAdded',
                    ignored
                )
            )
        end
    end
end
phowg:register_cleanup('rocket teleport', function(scope)
    if not scope then
        stoprockettp()
    end
end)
function flingpartlog(msg)
    print('[FlingPart] ' .. tostring(msg))
end
function getflingsubject()
    local sel = getselectedtarget()
    if intelligence:get_character_cache(sel) then
        return sel
    end
    local cam = Workspace.CurrentCamera
    if not cam then
        return nil
    end
    local mousePos = UserInputService:GetMouseLocation()
    local best = nil
    local bestDist = 300
    for _, plr in ipairs(Players:GetPlayers()) do
        if plr ~= LocalPlayer and intelligence:get_character_cache(plr) then
            local head = plr.Character:FindFirstChild('Head') or getroot(plr.Character)
            if head then
                local sp, on = cam:WorldToViewportPoint(head.Position)
                if on then
                    local d = (Vector2.new(sp.X, sp.Y) - mousePos).Magnitude
                    if d < bestDist then
                        bestDist = d
                        best = plr
                    end
                end
            end
        end
    end
    return best
end
function isflingbuildpart(v)
    if not v:IsA('BasePart') then
        return false
    end
    local character = LocalPlayer.Character
    if character and v:IsDescendantOf(character) then
        return false
    end
    if v.Name ~= 'Part' then
        return false
    end
    if v.Anchored then
        return false
    end
    local s = v.Size
    if math.abs(s.X - 4) > 0.01 or math.abs(s.Y - 1) > 0.01 or math.abs(s.Z - 2) > 0.01 then
        return false
    end
    local massOk = false
    (function()
        if math.abs(v:GetMass() - 5.6) < 0.2 then
            massOk = true
        end
    end)()
    if not massOk then
        return false
    end
    if v:GetAttribute('BuildUID') ~= nil then
        return true
    end
    if v:GetAttribute('BuildRootUID') ~= nil then
        return true
    end
    if v:GetAttribute('BuildTemplateId') ~= nil then
        return true
    end
    return false
end
function findflingpart()
    local named = 0
    local loose = 0
    local mapFolder = Workspace:FindFirstChild('MAP')
    if mapFolder then
        for _, v in ipairs(mapFolder:GetDescendants()) do
            if v:IsA('BasePart') and v.Name == 'Part' then
                if isflingbuildpart(v) then
                    Data['FlingPartDebug'] = 'found-in-map'
                    return v
                end
            end
        end
    end
    for _, v in ipairs(Workspace:GetDescendants()) do
        if v:IsA('BasePart') and v.Name == 'Part' and not (mapFolder and v:IsDescendantOf(mapFolder)) then
            named = named + 1
            if not v.Anchored then
                loose = loose + 1
            end
            if isflingbuildpart(v) then
                local p = v.Parent
                if p and p.Name ~= 'Ignored' and p.Name ~= 'Shop' and p.Name ~= 'Drop' then
                    if
                        not v:FindFirstAncestorOfClass('Tool')
                        and not v:FindFirstAncestorOfClass('Humanoid')
                        and not v:IsDescendantOf(LocalPlayer.Character)
                    then
                        Data['FlingPartDebug'] = 'found-in-workspace'
                        return v
                    end
                end
            end
        end
    end
    Data['FlingPartDebug'] = 'map='
        .. tostring(mapFolder ~= nil)
        .. ' named='
        .. tostring(named)
        .. ' unanchored='
        .. tostring(loose)
    return nil
end
function restoreflingpart()
    local p = Data['FlingPart']
    if p and p.Parent and Data['FlingPartPhysOrig'] then
        p.CustomPhysicalProperties = Data['FlingPartPhysOrig']
    end
    Data['FlingPartPhysOrig'] = nil
end
function flingpartloop()
    if localactionblocked() then
        return
    end
    if not (Toggles.fling_part and Toggles.fling_part.Value) then
        if Data['FlingPartHighlight'] then
            Data['FlingPartHighlight']:Destroy()
            Data['FlingPartHighlight'] = nil
        end
        if Data['FlingPart'] and Data['FlingPart'].Parent and Data['FlingPartVisOrig'] ~= nil then
            Data['FlingPart'].Transparency = Data['FlingPartVisOrig']
        end
        restoreflingpart()
        Data['FlingPartVisOrig'] = nil
        Data['FlingPart'] = nil
        Data['FlingPartSpin'] = false
        Data['FlingPartFound'] = false
        Data['FlingPartRep'] = nil
        Data['FlingPartBoard'] = nil
        return
    end
    local char = LocalPlayer.Character
    local myHRP = char and char:FindFirstChild('HumanoidRootPart')
    if not myHRP then
        return
    end
    local now = tick()
    local part = Data['FlingPart']
    if not part or not part.Parent then
        if Data['FlingPartHighlight'] then
            Data['FlingPartHighlight']:Destroy()
            Data['FlingPartHighlight'] = nil
        end
        restoreflingpart()
        Data['FlingPartVisOrig'] = nil
        Data['FlingPart'] = nil
        Data['FlingPartRep'] = nil
        part = nil
        if Data['FlingPartFound'] then
            Data['FlingPartDebug'] = 'lost'
        elseif now - (Data['FlingPartScanAt'] or 0) >= 2 then
            Data['FlingPartScanAt'] = now
            part = findflingpart()
            if part then
                Data['FlingPart'] = part
                Data['FlingPartFound'] = true
                Data['FlingPartVisOrig'] = part.Transparency
                part.Transparency = 0
                if Data['FlingPartPhysOrig'] == nil then
                    Data['FlingPartPhysOrig'] = part.CustomPhysicalProperties
                end
                Data['FlingPartOwnerAt'] = 0
            end
        end
    end
    if now - (Data['FlingPartLogAt'] or 0) >= 5 then
        Data['FlingPartLogAt'] = now
        if part and part.Parent then
            local dist = math.floor((part.Position - myHRP.Position).Magnitude)
            local owner = '?'
            (function()
                local o = part:GetNetworkOwner()
                owner = o and o.Name or 'server'
            end)()
            local fmode = (Options.fling_part_mode and Options.fling_part_mode.Value) or 'fling'
            local mode = 'hover'
            if fmode == 'hoverboard' then
                mode = 'board'
                local t = getselectedtarget()
                if intelligence:get_character_cache(t) then
                    mode = 'board:' .. t.Name
                end
            elseif Data['FlingPartSpin'] then
                mode = 'spin'
                local t = getflingsubject()
                if intelligence:get_character_cache(t) then
                    mode = 'fling:' .. t.Name
                end
            end
            flingpartlog(
                'toggle=on part='
                    .. part:GetFullName()
                    .. ' dist='
                    .. tostring(dist)
                    .. ' mode='
                    .. mode
                    .. ' owner='
                    .. owner
            )
        else
            flingpartlog('toggle=on part=NONE ' .. tostring(Data['FlingPartDebug']))
        end
    end
    if not part or part:IsDescendantOf(char) then
        return
    end
    local props = part.CustomPhysicalProperties
    if not props or props.Density ~= 100 then
        part.CustomPhysicalProperties = PhysicalProperties.new(100, 0.3, 0.5)
    end
    if now - (Data['FlingPartOwnerAt'] or 0) > 1 then
        Data['FlingPartOwnerAt'] = now
        part:SetNetworkOwner(LocalPlayer)
    end
    if not Data['FlingPartHighlight'] or not Data['FlingPartHighlight'].Parent then
        local hl = Instance.new('Highlight')
        hl.Name = 'FlingPartHighlight'
        hl.FillColor = Color3.fromRGB(0, 0, 0)
        hl.FillTransparency = 0.5
        hl.OutlineColor = Color3.fromRGB(0, 150, 255)
        hl.OutlineTransparency = 0
        hl.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
        hl.Adornee = part
        hl.Parent = part
        Data['FlingPartHighlight'] = hl
    elseif Data['FlingPartHighlight'].Adornee ~= part then
        Data['FlingPartHighlight'].Adornee = part
    end
    local head = char:FindFirstChild('Head')
    local hoverPos = ((head and head.Position) or myHRP.Position) + Vector3.new(0, 5, 0)
    if part.Position.Y < -50 or (part.Position - hoverPos).Magnitude > 500 then
        part.CFrame = CFrame.new(hoverPos)
        part.AssemblyLinearVelocity = Vector3.zero
        part.AssemblyAngularVelocity = Vector3.zero
    end
    local fmode = (Options.fling_part_mode and Options.fling_part_mode.Value) or 'fling'
    local torso = nil
    if Data['FlingPartSpin'] and fmode == 'fling' then
        local ft = getflingsubject()
        if intelligence:get_character_cache(ft) then
            torso = ft.Character:FindFirstChild('UpperTorso') or ft.Character:FindFirstChild('Torso')
        end
    end
    local boardHRP = nil
    local boardPlr = nil
    if fmode == 'hoverboard' and not torso then
        local bt = getselectedtarget()
        if intelligence:get_character_cache(bt) then
            boardHRP = bt.Character:FindFirstChild('HumanoidRootPart')
            if boardHRP then
                boardPlr = bt
            end
        end
    end
    if torso then
        local targetHum = intelligence:get_character_cache(flingTarget)
            and flingTarget.Character:FindFirstChildOfClass('Humanoid')
        local md = targetHum and targetHum.MoveDirection or Vector3.zero
        local ws = targetHum and targetHum.WalkSpeed or 16
        local aimPos = torso.Position + md * ws * 0.2
        part.CanCollide = true
        part.CFrame = CFrame.new(aimPos) * (torso.CFrame - torso.CFrame.Position)
        part.AssemblyLinearVelocity = torso.AssemblyLinearVelocity
        part.AssemblyAngularVelocity = Vector3.new(0, 1500, 0)
        local bp = part:FindFirstChildWhichIsA('BodyPosition')
        if not bp then
            bp = createbodymover('BodyPosition', part)
        end
        bp.MaxForce = Vector3.new(math.huge, math.huge, math.huge)
        bp.Position = aimPos
        bp.P = 10000
        bp.D = 175
    elseif boardHRP then
        local bVel = boardHRP.AssemblyLinearVelocity
        if bVel.Magnitude < 1 then
            local bHum = boardHRP.Parent and boardHRP.Parent:FindFirstChildOfClass('Humanoid')
            if bHum then
                bVel = bHum.MoveDirection * bHum.WalkSpeed
            end
        end
        bVel = Vector3.new(bVel.X, 0, bVel.Z)
        local underPos = boardHRP.Position + bVel * 0.15 + Vector3.new(0, -3.5, 0)
        local bTorso = boardHRP.Parent
            and (boardHRP.Parent:FindFirstChild('UpperTorso') or boardHRP.Parent:FindFirstChild('Torso'))
        local yaw = 0
        if bTorso then
            local _rx, ry, _rz = bTorso.CFrame:ToOrientation()
            yaw = ry
        end
        part.CanCollide = true
        part.CFrame = CFrame.new(underPos) * CFrame.Angles(0, yaw, 0)
        part.AssemblyLinearVelocity = boardHRP.AssemblyLinearVelocity
        part.AssemblyAngularVelocity = Vector3.zero
        local bp = part:FindFirstChildWhichIsA('BodyPosition')
        if not bp then
            bp = createbodymover('BodyPosition', part)
        end
        bp.MaxForce = Vector3.new(math.huge, math.huge, math.huge)
        bp.Position = underPos
        bp.P = 10000
        bp.D = 175
    else
        part.CanCollide = false
        part.AssemblyAngularVelocity = Vector3.new(1.5, 2, 1)
        local bp = part:FindFirstChildWhichIsA('BodyPosition')
        if not bp then
            bp = createbodymover('BodyPosition', part)
        end
        bp.MaxForce = Vector3.new(math.huge, math.huge, math.huge)
        bp.Position = hoverPos
        bp.P = 50000
        bp.D = 1000
    end
    if boardPlr then
        Data['FlingPartBoard'] = boardPlr
    elseif Data['FlingPartBoard'] ~= nil then
        Data['FlingPartBoard'] = nil
        local bp0 = part:FindFirstChildWhichIsA('BodyPosition')
        if bp0 then
            bp0:Destroy()
        end
        part.CFrame = CFrame.new(hoverPos)
        part.AssemblyLinearVelocity = Vector3.zero
        part.AssemblyAngularVelocity = Vector3.zero
    end
end
function phowg:stop_character_observer(name)
    local state = Data.CharacterObservers and Data.CharacterObservers[name]
    if not state then
        return
    end
    Data.CharacterObservers[name] = nil
    state.Closed = true
    if state.Spawn then
        state.Spawn:Disconnect()
    end
    for _, connection in pairs(state.Connections) do
        connection:Disconnect()
    end
    if state.Pending and state.Pending ~= coroutine.running() then
        local batch = Data.PurchaseBatch
        if batch and batch.Owner == state.Pending then
            phowg:finish_purchases(batch, true)
        end
        pcall(task.cancel, state.Pending)
    end
    if state.Restore then
        state.Restore()
    end
end
function phowg:cancel_observer_work(state)
    if state.Pending and state.Pending ~= coroutine.running() then
        local batch = Data.PurchaseBatch
        if batch and batch.Owner == state.Pending then
            phowg:finish_purchases(batch, true)
        end
        pcall(task.cancel, state.Pending)
    end
    state.Pending = nil
end
function phowg:set_character_observer(name, enabled, setup)
    phowg:stop_character_observer(name)
    if not enabled or Data.SharedSignalsClosed then
        return
    end
    Data.CharacterObservers = Data.CharacterObservers or {}
    local state: {
        Connections: { [string]: any },
        Closed: boolean,
        Character: any,
        Pending: thread?,
        Restore: (() -> ())?,
        Spawn: any,
    } =
        { Connections = {}, Closed = false }
    Data.CharacterObservers[name] = state
    local function bind(character)
        for _, connection in pairs(state.Connections) do
            connection:Disconnect()
        end
        table.clear(state.Connections)
        phowg:cancel_observer_work(state)
        if state.Restore then
            state.Restore()
            state.Restore = nil
        end
        state.Character = character
        if character and not state.Closed and character == LocalPlayer.Character then
            setup(state, character)
        end
    end
    state.Spawn = connectshared(LocalPlayer.CharacterAdded, bind, LocalPlayer, name .. '/respawn')
    bind(LocalPlayer.Character)
end
function phowg:observe_character_values(state, character, names, check)
    local effects
    local function listen(key, signal, callback, owner)
        if state.Connections[key] then
            state.Connections[key]:Disconnect()
        end
        state.Connections[key] = connectshared(signal, callback, owner, 'character observer/' .. key)
    end
    local function observe(value)
        if not names[value.Name] or not value:IsA('ValueBase') then
            return
        end
        listen('value/' .. value.Name, value:GetPropertyChangedSignal('Value'), check, value)
    end
    local function bind_effects(folder)
        for key, connection in pairs(state.Connections) do
            if key:sub(1, 6) == 'value/' or key == 'effects added' or key == 'effects removed' then
                connection:Disconnect()
                state.Connections[key] = nil
            end
        end
        effects = folder
        if folder then
            listen('effects added', folder.ChildAdded, function(value)
                observe(value)
                check()
            end, folder)
            listen('effects removed', folder.ChildRemoved, function(value)
                if not names[value.Name] then
                    return
                end
                local key = 'value/' .. value.Name
                if state.Connections[key] then
                    state.Connections[key]:Disconnect()
                    state.Connections[key] = nil
                end
                local replacement = folder:FindFirstChild(value.Name)
                if replacement then
                    observe(replacement)
                end
                check()
            end, folder)
            for _, value in ipairs(folder:GetChildren()) do
                observe(value)
            end
        end
        check()
    end
    listen('character added', character.ChildAdded, function(child)
        if child.Name == 'BodyEffects' then
            bind_effects(child)
        else
            check()
        end
    end, character)
    listen('character removed', character.ChildRemoved, function(child)
        if child == effects then
            bind_effects(nil)
        else
            check()
        end
    end, character)
    bind_effects(character:FindFirstChild('BodyEffects'))
end
function phowg:restore_animated_grip_checks(connections)
    for _, connection in ipairs(connections or {}) do
        pcall(connection.Enable, connection)
    end
end
function phowg:suspend_animated_grip_checks(tool, cache)
    local constants = getconstants or debug and debug.getconstants
    if type(getconnections) ~= 'function' or type(constants) ~= 'function' then
        return nil
    end
    cache = cache or {}
    cache.GripSignals = cache.GripSignals or {}
    cache.GripConstants = cache.GripConstants or setmetatable({}, { __mode = 'k' })
    Data.AnimatedGripProperties = Data.AnimatedGripProperties
        or { 'Grip', 'GripPos', 'GripForward', 'GripRight', 'GripUp' }
    local suspended, seen = {}, {}
    for _, property in ipairs(Data.AnimatedGripProperties) do
        local ok, connections = pcall(function()
            local signal = cache.GripSignals[property]
            if not signal then
                signal = tool:GetPropertyChangedSignal(property)
                cache.GripSignals[property] = signal
            end
            return getconnections(signal)
        end)
        if not ok or type(connections) ~= 'table' then
            phowg:restore_animated_grip_checks(suspended)
            return nil
        end
        for _, connection in ipairs(connections) do
            if not seen[connection] and connection.Enabled then
                seen[connection] = true
                local callback = connection.Function
                if type(callback) == 'function' then
                    local marked = cache.GripConstants[callback]
                    if marked == nil then
                        local readable, values = pcall(constants, callback)
                        if not readable or type(values) ~= 'table' then
                            phowg:restore_animated_grip_checks(suspended)
                            return nil
                        end
                        marked = table.find(values, 'CHECKER_4') ~= nil
                        cache.GripConstants[callback] = marked
                    end
                    if marked then
                        if type(connection.Disable) ~= 'function' or type(connection.Enable) ~= 'function' then
                            phowg:restore_animated_grip_checks(suspended)
                            return nil
                        end
                        suspended[#suspended + 1] = connection
                        local disabled = pcall(connection.Disable, connection)
                        if not disabled or connection.Enabled then
                            phowg:restore_animated_grip_checks(suspended)
                            return nil
                        end
                    end
                end
            end
        end
    end
    return suspended
end
function phowg:grip_wall_exit(wall, origin, point)
    if not wall or not wall.Parent or not wall:IsA('BasePart') then
        return nil
    end
    local delta = point - origin
    if delta.Magnitude < 0.1 then
        return nil
    end
    local direction = delta.Unit
    local reverseParams = Data.GripWallExitParams
    if not reverseParams then
        reverseParams = RaycastParams.new()
        reverseParams.FilterType, reverseParams.IgnoreWater = Enum.RaycastFilterType.Include, true
        Data.GripWallExitParams = reverseParams
    end
    reverseParams.FilterDescendantsInstances = { wall }
    local reverse = Workspace:Raycast(point, -delta, reverseParams)
    if reverse and reverse.Instance == wall then
        local distance = (reverse.Position - origin):Dot(direction)
        local remaining = delta.Magnitude - distance
        if distance >= 0 and remaining > 0.001 then
            return origin + direction * (distance + math.min(0.25, remaining * 0.5))
        end
    end
    local position = wall.CFrame:PointToObjectSpace(origin)
    local ray = wall.CFrame:VectorToObjectSpace(direction)
    local half = wall.Size * 0.5
    local enter, leave = -math.huge, math.huge
    for _, axis in ipairs({ 'X', 'Y', 'Z' }) do
        if math.abs(ray[axis]) < 0.00001 then
            if math.abs(position[axis]) > half[axis] then
                return nil
            end
        else
            local first = (-half[axis] - position[axis]) / ray[axis]
            local last = (half[axis] - position[axis]) / ray[axis]
            enter, leave = math.max(enter, math.min(first, last)), math.min(leave, math.max(first, last))
        end
    end
    if enter > leave or leave < 0 or leave + 0.001 >= delta.Magnitude then
        return nil
    end
    return origin + direction * (leave + math.min(0.25, (delta.Magnitude - leave) * 0.5))
end
function phowg:find_grip_wall_exit(origin, point, params, hit)
    local cursor = origin
    for _ = 1, 8 do
        local exit = hit and phowg:grip_wall_exit(hit.Instance, cursor, point)
        if not exit or (exit - origin).Magnitude > 250 or (exit - cursor).Magnitude < 0.001 then
            return nil
        end
        local clear, _, obstruction = phowg:strafe_shot_clear(exit, point, params)
        if clear then
            return exit
        end
        cursor, hit = exit, obstruction
    end
    return nil
end
function phowg:grip_wallbang_path_clear(origin, point, params, character, rootCF, worldCF)
    if not phowg:strafe_shot_clear(origin, point, params) then
        return false
    end
    if Players:GetAttribute('RankedWallShotsBanned') then
        local map = Workspace:FindFirstChild('MAP')
        local head = character:FindFirstChild('Head')
        if not map or not head then
            return false
        end
        local headParams = Data.GripWallbangHeadParams
        if not headParams then
            headParams = RaycastParams.new()
            headParams.FilterType, headParams.RespectCanCollide = Enum.RaycastFilterType.Include, true
            Data.GripWallbangHeadParams = headParams
        end
        headParams.FilterDescendantsInstances = { map }
        local position = worldCF:PointToWorldSpace(rootCF:PointToObjectSpace(head.Position))
        if Workspace:Raycast(position, origin - position, headParams) then
            return false
        end
    end
    return true
end
function phowg:around_wallbang_enabled(target, source)
    if
        Library.Unloaded
        or Data.Unloading
        or Data.SharedSignalsClosed
        or Data.SafeMode
        or not (Toggles.wallbang and Toggles.wallbang.Value)
    then
        return false
    end
    local method = phowg:gun_shoot_method(source, target)
    return method == 'perfect hit' or method == 'china hack'
end
function phowg:resolve_wallbang_origin(tool, target, origin, point, source)
    if not phowg:around_wallbang_enabled(target, source) then
        return origin, false
    end
    local character = LocalPlayer.Character
    local targetCharacter = target and target.Character
    if
        not character
        or not targetCharacter
        or not targetCharacter.Parent
        or not tool
        or tool.Parent ~= character
        or not phowg:perfect_hit_vector(origin)
        or not phowg:perfect_hit_vector(point)
    then
        return nil, false
    end
    local grip = Data.GripWallbang
    if grip and grip.Tool == tool then
        origin = grip.BaseOrigin
        phowg:clear_grip_wallbang()
    end
    if (point - origin).Magnitude > 250 then
        return nil, false
    end
    local method = phowg:gun_shoot_method(source, target)
    local ranked = Players:GetAttribute('RankedWallShotsBanned')
    local cache: { [string]: any }? = Data.AroundWallbangCache
    if
        not cache
        or cache.Tool ~= tool
        or cache.Target ~= target
        or cache.Character ~= character
        or cache.TargetCharacter ~= targetCharacter
        or cache.Source ~= source
        or cache.Method ~= method
        or cache.Ranked ~= ranked
        or cache.Revision ~= (Data.StrafeFilterRevision or 0)
    then
        cache = {
            Tool = tool,
            Target = target,
            Character = character,
            TargetCharacter = targetCharacter,
            Source = source,
            Method = method,
            Ranked = ranked,
            Revision = Data.StrafeFilterRevision or 0,
            Params = phowg:strafe_shot_params(character, targetCharacter),
            NextAt = 0,
        }
        Data.AroundWallbangCache = cache
    end
    local params = cache.Params
    if
        cache.LastOrigin
        and cache.LastPoint
        and (origin - cache.LastOrigin).Magnitude <= 0.1
        and (point - cache.LastPoint).Magnitude <= 0.1
        and tick() < (cache.ValidUntil or 0)
        and (
            not cache.Wall
            or cache.Wall.Parent and cache.WallCF == cache.Wall.CFrame and cache.WallSize == cache.Wall.Size
        )
    then
        return cache.Candidate or cache.Direct and origin or nil, cache.Candidate ~= nil
    end
    cache.LastOrigin, cache.LastPoint = origin, point
    local root = character:FindFirstChild('HumanoidRootPart')
    if not root then
        return nil, false
    end
    local rootCF = root:GetPivot() * root.PivotOffset:Inverse()
    local worldCF = rootCF
    if
        Data.AppliedServerCharacter == character
        and typeof(Data.AppliedServerCF) == 'CFrame'
        and tick() - (Data.AppliedServerAt or -math.huge) >= 0
        and tick() - (Data.AppliedServerAt or -math.huge) <= 0.15
        and (
            Data.AppliedServerTag == 'Combat'
            or Data.AppliedServerTag == 'TargetStrafe'
            or Data.AppliedServerTag == 'Desync'
        )
    then
        worldCF = Data.AppliedServerCF
    end
    local clear, _, hit = phowg:strafe_shot_clear(origin, point, params)
    if clear then
        if ranked and not phowg:grip_wallbang_path_clear(origin, point, params, character, rootCF, worldCF) then
            cache.Candidate, cache.Wall, cache.Direct, cache.ValidUntil = nil, nil, false, tick() + 0.05
            return nil, false
        end
        cache.Candidate, cache.Wall = nil, nil
        cache.Direct, cache.ValidUntil = true, tick() + 0.05
        return origin, false
    end
    cache.Direct = false
    local wall = hit and hit.Instance
    if not wall or not wall:IsA('BasePart') then
        cache.Candidate = nil
        return nil, false
    end
    local function valid(candidate)
        return (candidate - origin).Magnitude <= 250
            and (point - candidate).Magnitude <= 250
            and phowg:strafe_shot_clear(origin, candidate, params)
            and phowg:grip_wallbang_path_clear(candidate, point, params, character, rootCF, worldCF)
    end
    if
        cache.Candidate
        and cache.Wall == wall
        and cache.WallCF == wall.CFrame
        and cache.WallSize == wall.Size
        and valid(cache.Candidate)
    then
        cache.ValidUntil = tick() + 0.05
        return cache.Candidate, true
    end
    cache.Candidate = nil
    if tick() < cache.NextAt and cache.Wall == wall and cache.WallCF == wall.CFrame and cache.WallSize == wall.Size then
        return nil, false
    end
    cache.NextAt, cache.Wall, cache.WallCF, cache.WallSize = tick() + 0.05, wall, wall.CFrame, wall.Size
    cache.ValidUntil = cache.NextAt
    local forward = point - origin
    local side = forward:Cross(Vector3.yAxis)
    side = side.Magnitude > 0.001 and side.Unit or Vector3.xAxis
    local half = wall.Size * 0.5
    for _, direction in ipairs({ Vector3.yAxis, side, -side }) do
        local extent = math.abs(direction:Dot(wall.CFrame.RightVector)) * half.X
            + math.abs(direction:Dot(wall.CFrame.UpVector)) * half.Y
            + math.abs(direction:Dot(wall.CFrame.LookVector)) * half.Z
        local edge = (wall.Position - hit.Position):Dot(direction) + extent
        for _, clearance in ipairs({ 0.5, 2, 6, 12 }) do
            local candidate = hit.Position + direction * (edge + clearance) + (hit.Normal or -forward.Unit) * 0.25
            if valid(candidate) then
                cache.Candidate = candidate
                return candidate, true
            end
        end
    end
    return nil, false
end
phowg:register_cleanup('around wallbang', function(scope)
    local cache = Data.AroundWallbangCache
    if
        not scope
        or cache
            and (scope == cache.Character or scope == cache.Target or scope == cache.TargetCharacter or scope == cache.Tool)
    then
        Data.AroundWallbangCache = nil
    end
end)
function phowg:clear_grip_wallbang()
    local state = Data.GripWallbang
    if not state then
        return
    end
    Data.GripWallbang = nil
    local tool = state.Tool
    local animated = Data.AnimatedToolStates and Data.AnimatedToolStates[tool]
    local checks = phowg:suspend_animated_grip_checks(tool, state)
    for _, connection in ipairs(checks or {}) do
        state.GripChecks[#state.GripChecks + 1] = connection
    end
    pcall(function()
        if checks and state.Applied and tool.Grip == state.Applied then
            tool.Grip = animated and animated.Applied or state.ReturnGrip
        end
    end)
    if animated then
        for _, connection in ipairs(state.GripChecks) do
            animated.GripChecks[#animated.GripChecks + 1] = connection
        end
    else
        phowg:restore_animated_grip_checks(state.GripChecks)
    end
end
function phowg:grip_wallbang_context()
    if
        Library.Unloaded
        or Data.Unloading
        or Data.SafeMode
        or not (Toggles.wallbang and Toggles.wallbang.Value)
        or not (Toggles.sticky_aim_enabled and Toggles.sticky_aim_enabled.Value)
        or localshootblocked()
        or isreloading()
        or phowg:purchase_blocks_shooting()
    then
        return nil
    end
    local target, position, part, owner = phowg:get_gun_shot_target()
    if
        not target
        or target ~= Data.StickyTarget
        or owner ~= 'StickyAim'
        or isdead(target)
        or phowg:gun_shoot_method(owner, target) ~= 'shoot redirect'
    then
        return nil
    end
    local character, targetCharacter = LocalPlayer.Character, target.Character
    local tool = getequippedguntool()
    local root = character and character:FindFirstChild('HumanoidRootPart')
    local handle = tool and tool:FindFirstChild('Handle')
    local ammo = tool and tool:FindFirstChild('Ammo')
    local range = 250
    if
        not root
        or not handle
        or not handle:IsA('BasePart')
        or tool.Parent ~= character
        or not ammo
        or ammo.Value < 1
        or not targetCharacter
        or targetCharacter:FindFirstChildOfClass('ForceField')
        or phowg:sticky_shot_blocked(target, owner)
    then
        return nil
    end
    part = part and part.Parent and part:IsDescendantOf(targetCharacter) and part or phowg:strafe_aim_part(target)
    if not part then
        return nil
    end
    local cf = root:GetPivot() * root.PivotOffset:Inverse()
    local tag = Data.AppliedServerTag
    if tag == 'Void' or tag == 'VoidTwitch' or tag == 'VoidSpamOut' or tag == 'RagebotVoid' or tag == 'RagebotIdle' then
        return nil
    end
    local world = cf
    if
        Data.AppliedServerCharacter == character
        and typeof(Data.AppliedServerCF) == 'CFrame'
        and tick() - (Data.AppliedServerAt or -math.huge) <= 0.15
        and (tag == 'Combat' or tag == 'TargetStrafe' or tag == 'Desync')
    then
        world = Data.AppliedServerCF
    end
    local point = typeof(position) == 'CFrame' and position.Position
        or typeof(position) == 'Vector3' and position
        or part.Position
    return tool, target, point, handle, cf, world, range
end
function phowg:update_grip_wallbang()
    if not Data.GripWallbangPressedTool and not Data.HeldGunFire and not Data.GripWallbangMouseDown then
        phowg:clear_grip_wallbang()
        return
    end
    local tool, target, point, handle, rootCF, worldCF, range = phowg:grip_wallbang_context()
    local held = Data.HeldGunFire
    local firing = tool
        and (
            Data.GripWallbangPressedTool == tool
            or Data.GripWallbangMouseDown
            or held and held.Tool == tool and held.Target == target
        )
    if not firing then
        phowg:clear_grip_wallbang()
        return
    end
    local state = Data.GripWallbang
    if
        state
        and (
            state.Tool ~= tool
            or state.Target ~= target
            or state.Character ~= LocalPlayer.Character
            or state.TargetCharacter ~= target.Character
        )
    then
        phowg:clear_grip_wallbang()
        state = nil
    end
    if state and tick() < state.NextProbeAt then
        return
    end
    local animated = Data.AnimatedToolStates and Data.AnimatedToolStates[tool]
    local baseGrip = state and state.BaseGrip or animated and animated.Original or tool.Grip
    local baseHandle = handle.CFrame * tool.Grip * baseGrip:Inverse()
    local offset = gettoolhandleoffset(LocalPlayer.Character, tool)
    if not offset then
        phowg:clear_grip_wallbang()
        return
    end
    local muzzle = handle.CFrame:PointToObjectSpace(rootCF:PointToWorldSpace(offset))
    baseHandle = worldCF * rootCF:Inverse() * baseHandle
    local origin = baseHandle:PointToWorldSpace(muzzle)
    if (point - origin).Magnitude > range then
        phowg:clear_grip_wallbang()
        return
    end
    local params = state and state.Params or phowg:strafe_shot_params(LocalPlayer.Character, target.Character)
    local clear, _, hit = phowg:strafe_shot_clear(origin, point, params)
    if clear then
        phowg:clear_grip_wallbang()
        return
    end
    local exit = phowg:find_grip_wall_exit(origin, point, params, hit)
    if
        not exit
        or (exit - origin).Magnitude > range
        or (point - exit).Magnitude > range
        or not phowg:grip_wallbang_path_clear(exit, point, params, LocalPlayer.Character, rootCF, worldCF)
    then
        phowg:clear_grip_wallbang()
        return
    end
    if not state then
        state = {
            Tool = tool,
            Target = target,
            Character = LocalPlayer.Character,
            TargetCharacter = target.Character,
            BaseGrip = baseGrip,
            ReturnGrip = tool.Grip,
            GripChecks = {},
            Params = params,
        }
    end
    local checks = phowg:suspend_animated_grip_checks(tool, state)
    if not checks then
        phowg:clear_grip_wallbang()
        return
    end
    for _, connection in ipairs(checks) do
        state.GripChecks[#state.GripChecks + 1] = connection
    end
    state.Applied = CFrame.new(-baseHandle:VectorToObjectSpace(exit - origin)) * baseGrip
    state.Point, state.Origin, state.BaseOrigin, state.NextProbeAt = point, exit, origin, tick() + 0.05
    Data.GripWallbang = state
    if tool.Grip ~= state.Applied then
        tool.Grip = state.Applied
    end
end
function phowg:set_grip_wallbang_observer(enabled)
    phowg:clear_grip_wallbang()
    Data.GripWallbangPressedTool, Data.GripWallbangMouseDown = nil, nil
    phowg:set_character_observer('grip wallbang', enabled, function(state, character)
        local hooks = {}
        local function remove(tool)
            for _, connection in ipairs(hooks[tool] or {}) do
                connection:Disconnect()
            end
            hooks[tool] = nil
            if Data.GripWallbangPressedTool == tool then
                Data.GripWallbangPressedTool = nil
            end
            if Data.GripWallbang and Data.GripWallbang.Tool == tool then
                phowg:clear_grip_wallbang()
            end
        end
        local function added(tool)
            if tool:IsA('Tool') and not hooks[tool] then
                hooks[tool] = {
                    connectshared(tool.Activated, function()
                        Data.GripWallbangPressedTool = tool
                        phowg:update_grip_wallbang()
                    end, tool, 'grip wallbang/activated'),
                    connectshared(tool.Deactivated, function()
                        Data.GripWallbangPressedTool = nil
                        if not Data.GripWallbangMouseDown then
                            phowg:clear_grip_wallbang()
                        end
                    end, tool, 'grip wallbang/deactivated'),
                }
            end
        end
        state.Connections.Added = connectshared(character.ChildAdded, added, character, 'grip wallbang/equipped')
        state.Connections.Removed = connectshared(character.ChildRemoved, remove, character, 'grip wallbang/unequipped')
        state.Connections.Input = connectshared(UserInputService.InputBegan, function(input, processed)
            if not processed and input.UserInputType == Enum.UserInputType.MouseButton1 then
                Data.GripWallbangMouseDown = true
                phowg:update_grip_wallbang()
            end
        end, UserInputService, 'grip wallbang/input')
        state.Connections.InputEnded = connectshared(UserInputService.InputEnded, function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1 then
                Data.GripWallbangMouseDown = nil
                phowg:update_grip_wallbang()
            end
        end, UserInputService, 'grip wallbang/input ended')
        for _, tool in ipairs(character:GetChildren()) do
            added(tool)
        end
        state.Restore = function()
            Data.GripWallbangMouseDown = nil
            for tool in pairs(hooks) do
                remove(tool)
            end
            phowg:clear_grip_wallbang()
        end
    end)
end
phowg:register_cleanup('grip wallbang', function(scope)
    local state = Data.GripWallbang
    if not scope or state and (scope == state.Character or scope == state.TargetCharacter or scope == state.Tool) then
        phowg:clear_grip_wallbang()
    end
end)
function phowg:clear_animated_tool(tool)
    local states = Data.AnimatedToolStates
    local state = states and states[tool]
    if not state then
        return
    end
    states[tool] = nil
    local wallbang = Data.GripWallbang
    if wallbang and wallbang.Tool == tool then
        wallbang.ReturnGrip = state.Original
        for _, connection in ipairs(state.GripChecks) do
            wallbang.GripChecks[#wallbang.GripChecks + 1] = connection
        end
        return
    end
    local checks = phowg:suspend_animated_grip_checks(tool, state)
    if checks then
        for _, connection in ipairs(checks) do
            state.GripChecks[#state.GripChecks + 1] = connection
        end
    end
    pcall(function()
        if checks and state.Applied and tool.Grip == state.Applied then
            tool.Grip = state.Original
        end
    end)
    phowg:restore_animated_grip_checks(state.GripChecks)
end
function phowg:set_animated_tools(enabled)
    phowg:set_character_observer('animated tools', enabled, function(state, character)
        Data.AnimatedToolStates = Data.AnimatedToolStates or setmetatable({}, { __mode = 'k' })
        local function added(tool)
            if typeof(tool) == 'Instance' and tool:IsA('Tool') and not Data.AnimatedToolStates[tool] then
                local record: { [string]: any } = {
                    Character = character,
                    Original = tool.Grip,
                    At = tick(),
                }
                local checks = phowg:suspend_animated_grip_checks(tool, record)
                if not checks then
                    return
                end
                record.GripChecks = checks
                local wallbang = Data.GripWallbang
                if wallbang and wallbang.Tool == tool then
                    record.Original, record.Applied = wallbang.BaseGrip, wallbang.ReturnGrip
                end
                Data.AnimatedToolStates[tool] = record
            end
        end
        state.Connections.Added = connectshared(character.ChildAdded, added, character, 'animated tools/equipped')
        state.Connections.Removed =
            connectshared(character.ChildRemoved, phowg_callbacks.clear_animated_tool, character, 'animated tools/unequipped')
        for _, tool in ipairs(character:GetChildren()) do
            added(tool)
        end
        state.Restore = function()
            for tool, record in pairs(Data.AnimatedToolStates or {}) do
                if record.Character == character then
                    phowg:clear_animated_tool(tool)
                end
            end
        end
    end)
end
function phowg:animated_tool_angle(mode, elapsed, speed)
    if not mode or mode == 'Off' then
        return 0
    end
    local phase = elapsed * speed
    if mode == 'Spin' then
        return phase
    end
    if mode == 'Sway' then
        return math.sin(phase) * math.rad(25)
    end
    return math.sin(phase) * math.pi
end
function phowg:update_animated_tools()
    phowg:update_grip_wallbang()
    for tool, state in pairs(Data.AnimatedToolStates or {}) do
        if
            Library.Unloaded
            or not Toggles.animated_tools.Value
            or tool.Parent ~= LocalPlayer.Character
            or not tool:IsA('Tool')
        then
            phowg:clear_animated_tool(tool)
        elseif Data.GripWallbang and Data.GripWallbang.Tool == tool then
            continue
        else
            local checks = phowg:suspend_animated_grip_checks(tool, state)
            if not checks then
                phowg:clear_animated_tool(tool)
                continue
            end
            for _, connection in ipairs(checks) do
                state.GripChecks[#state.GripChecks + 1] = connection
            end
            local current = tool.Grip
            if state.Applied and current ~= state.Applied then
                state.Original = current
            end
            local elapsed = tick() - state.At
            local horizontal = phowg:animated_tool_angle(
                Options.animated_tools_horizontal.Value,
                elapsed,
                Options.animated_tools_horizontal_speed.Value
            )
            local vertical = phowg:animated_tool_angle(
                Options.animated_tools_vertical.Value,
                elapsed,
                Options.animated_tools_vertical_speed.Value
            )
            local x = tonumber(Options.animated_tools_position_x and Options.animated_tools_position_x.Value) or 0
            local y = tonumber(Options.animated_tools_position_y and Options.animated_tools_position_y.Value) or 0
            local z = tonumber(Options.animated_tools_position_z and Options.animated_tools_position_z.Value) or 0
            state.Applied = state.Original * CFrame.new(x, y, z) * CFrame.Angles(vertical, horizontal, 0)
            if tool.Grip ~= state.Applied then
                tool.Grip = state.Applied
            end
        end
    end
end
registerheartbeat('AnimatedTools', phowg.update_animated_tools, 1 / 60, function()
    return Toggles.wallbang and Toggles.wallbang.Value
        or Toggles.animated_tools and Toggles.animated_tools.Value and Data.AnimatedToolStates ~= nil
end)
phowg:register_cleanup('animated tools', function(scope)
    for tool, state in pairs(Data.AnimatedToolStates or {}) do
        if not scope or scope == tool or scope == state.Character then
            phowg:clear_animated_tool(tool)
        end
    end
end)
function phowg:set_anti_stomp(enabled)
    Data.AntiStompTriggered = false
    phowg:set_character_observer('anti stomp', enabled, function(state, character)
        local function check()
            if state.Closed or character ~= LocalPlayer.Character then
                return
            end
            local effects = character:FindFirstChild('BodyEffects')
            local ko = effects and (effects:FindFirstChild('K.O') or effects:FindFirstChild('KO'))
            local knocked = ko and ko.Value == true
            if not knocked then
                Data.AntiStompTriggered = false
                return
            end
            if not Data.AntiStompTriggered then
                if not character:FindFirstChild('Head') then
                    return
                end
                Data.AntiStompTriggered = true
                removemyhead()
            end
        end
        Data.AntiStompTriggered = false
        phowg:observe_character_values(state, character, { ['K.O'] = true, KO = true }, check)
    end)
end
function phowg:set_anti_trip(enabled)
    phowg:set_character_observer('anti trip', enabled, function(state, character)
        local humanoid
        local function bind(hum)
            if humanoid == hum then
                return
            end
            if state.Connections.State then
                state.Connections.State:Disconnect()
            end
            if state.Restore then
                state.Restore()
                state.Restore = nil
            end
            humanoid = hum
            if not hum then
                return
            end
            local falling = hum:GetStateEnabled(Enum.HumanoidStateType.FallingDown)
            local ragdoll = hum:GetStateEnabled(Enum.HumanoidStateType.Ragdoll)
            state.Restore = function()
                if hum.Parent then
                    hum:SetStateEnabled(Enum.HumanoidStateType.FallingDown, falling)
                    hum:SetStateEnabled(Enum.HumanoidStateType.Ragdoll, ragdoll)
                end
            end
            hum:SetStateEnabled(Enum.HumanoidStateType.FallingDown, false)
            hum:SetStateEnabled(Enum.HumanoidStateType.Ragdoll, false)
            local function check(_, nextState)
                if
                    state.Closed
                    or character ~= LocalPlayer.Character
                    or Data.Flying
                    or Data.WallWalking
                    or localactionblocked()
                then
                    return
                end
                local current = nextState or hum:GetState()
                if current == Enum.HumanoidStateType.FallingDown or current == Enum.HumanoidStateType.Ragdoll then
                    hum:ChangeState(Enum.HumanoidStateType.GettingUp)
                end
            end
            state.Connections.State =
                connectshared(hum.StateChanged, check, hum, 'anti trip/state', 0, 'event/StateChanged', hum)
            check()
        end
        state.Connections.Added = connectshared(character.ChildAdded, function(child)
            if child:IsA('Humanoid') then
                bind(child)
            end
        end, character, 'anti trip/humanoid added', 0, 'event/ChildAdded', character)
        state.Connections.Removed = connectshared(character.ChildRemoved, function(child)
            if child == humanoid then
                bind(nil)
            end
        end, character, 'anti trip/humanoid removed', 0, 'event/ChildRemoved', character)
        bind(character:FindFirstChildOfClass('Humanoid'))
    end)
end
phowg:register_cleanup('character observers', function(scope)
    for name, state in pairs(Data.CharacterObservers or {}) do
        if not scope then
            phowg:stop_character_observer(name)
        elseif state.Character == scope then
            for _, connection in pairs(state.Connections) do
                connection:Disconnect()
            end
            table.clear(state.Connections)
            phowg:cancel_observer_work(state)
            state.Character = nil
            if state.Restore then
                state.Restore()
                state.Restore = nil
            end
        end
    end
end)
function stopnoclip()
    local state = Data['NoclipState']
    Data['NoclipState'] = nil
    if not state then
        return
    end
    for _, connection in ipairs(state.Connections) do
        connection:Disconnect()
    end
    for part, canCollide in pairs(state.Parts) do
        if part.Parent then
            part.CanCollide = canCollide
        end
    end
end
function startnoclip()
    local char = LocalPlayer.Character
    if not char or localactionblocked() then
        stopnoclip()
        return
    end
    local state = Data['NoclipState']
    if not state or state.Character ~= char then
        stopnoclip()
        state = { Character = char, Parts = {}, Connections = {} }
        Data['NoclipState'] = state
        local function track(part)
            if part:IsA('BasePart') and part:IsDescendantOf(char) and Data['NoclipState'] == state then
                if state.Parts[part] == nil then
                    state.Parts[part] = part.CanCollide
                end
                part.CanCollide = false
            end
        end
        table.insert(
            state.Connections,
            connectshared(char.DescendantAdded, track, char, 'noclip/part added', 0, 'event/DescendantAdded', char)
        )
        table.insert(
            state.Connections,
            connectshared(char.DescendantRemoving, function(part)
                local original = state.Parts[part]
                if original ~= nil then
                    state.Parts[part] = nil
                    part.CanCollide = original
                end
            end, char, 'noclip/part removed', 0, 'event/DescendantRemoving', char)
        )
        for _, part in ipairs(char:GetDescendants()) do
            track(part)
        end
    end
    for part in pairs(state.Parts) do
        if not part.Parent or not part:IsDescendantOf(char) then
            state.Parts[part] = nil
        elseif part.CanCollide then
            part.CanCollide = false
        end
    end
end
function nocliptick()
    local enabled = Toggles.noclip and Toggles.noclip.Value
    local key = Options.noclip_keybind
    if enabled and key and key.Value ~= 'None' then
        enabled = key:GetState()
    end
    Data['NoclipActive'] = enabled == true
    if enabled and not localactionblocked() then
        startnoclip()
    else
        stopnoclip()
    end
end
create_connection(
    'NoclipSimulation',
    connectshared(
        RunService.PreSimulation,
        nocliptick,
        RunService,
        'frame/noclip simulation',
        0,
        'event/PreSimulation',
        RunService
    )
)
phowg:register_cleanup('noclip state', function(scope)
    local state = Data['NoclipState']
    if not scope or state and state.Character == scope then
        stopnoclip()
    end
end)
function antiflingtrack(d)
    if not d or not d:IsA('BasePart') then
        return
    end
    if Data['AntiFlingParts'] == nil then
        Data['AntiFlingParts'] = {}
    end
    Data['AntiFlingParts'][d] = true
    if d.CanCollide then
        d.CanCollide = false
    end
end
function antiflingwatchchar(plr, char)
    if not char then
        return
    end
    for _, d in ipairs(char:GetDescendants()) do
        antiflingtrack(d)
    end
    local e = Data['AntiFlingConns'] and Data['AntiFlingConns'][plr] or nil
    if e then
        if e.desc then
            e.desc:Disconnect()
            e.desc = nil
        end
        e.desc = connectshared(char.DescendantAdded, function(d)
            antiflingtrack(d)
        end, char, 'event/char.DescendantAdded', 0, 'event/DescendantAdded', char)
    end
end
function unhookantiflingplayer(plr)
    local e = Data['AntiFlingConns'] and Data['AntiFlingConns'][plr] or nil
    if e then
        if e.desc then
            e.desc:Disconnect()
        end
        if e.added then
            e.added:Disconnect()
        end
        Data['AntiFlingConns'][plr] = nil
    end
end
function hookantiflingplayer(plr)
    if not plr or plr == LocalPlayer then
        return
    end
    if Data['AntiFlingConns'] == nil then
        Data['AntiFlingConns'] = {}
    end
    unhookantiflingplayer(plr)
    Data['AntiFlingConns'][plr] = {}
    if plr.Character then
        antiflingwatchchar(plr, plr.Character)
    end
    Data['AntiFlingConns'][plr].added = connectshared(plr.CharacterAdded, function(c)
        antiflingwatchchar(plr, c)
    end, plr, 'event/plr.CharacterAdded', 0, 'event/CharacterAdded', plr)
end
function startantiflinghooks()
    if Data['AntiFlingConns'] == nil then
        Data['AntiFlingConns'] = {}
    end
    for _, plr in ipairs(Players:GetPlayers()) do
        hookantiflingplayer(plr)
    end
    if not Data['AntiFlingPlayerAdded'] then
        Data['AntiFlingPlayerAdded'] = connectshared(Players.PlayerAdded, function(plr)
            hookantiflingplayer(plr)
        end, Players, 'event/Players.PlayerAdded', 0, 'event/PlayerAdded', Players)
    end
    if not Data['AntiFlingPlayerRemoving'] then
        Data['AntiFlingPlayerRemoving'] = connectshared(Players.PlayerRemoving, function(plr)
            unhookantiflingplayer(plr)
        end, Players, 'event/Players.PlayerRemoving', 0, 'event/PlayerRemoving', Players)
    end
end
function stopantiflinghooks()
    if Data['AntiFlingConns'] then
        for plr, _ in pairs(Data['AntiFlingConns']) do
            unhookantiflingplayer(plr)
        end
        Data['AntiFlingConns'] = nil
    end
    if Data['AntiFlingPlayerAdded'] then
        Data['AntiFlingPlayerAdded']:Disconnect()
        Data['AntiFlingPlayerAdded'] = nil
    end
    if Data['AntiFlingPlayerRemoving'] then
        Data['AntiFlingPlayerRemoving']:Disconnect()
        Data['AntiFlingPlayerRemoving'] = nil
    end
    Data['AntiFlingParts'] = nil
end
function antiflingloop()
    if localactionblocked(true) then
        return
    end
    if not (Toggles.anti_fling and Toggles.anti_fling.Value) or not LocalPlayer.Character then
        return
    end
    local Root = getroot(LocalPlayer.Character)
    if Root then
        if Root.AssemblyAngularVelocity.Magnitude > 80 then
            Root.AssemblyAngularVelocity = Vector3.zero
        end
        if
            Root.AssemblyLinearVelocity.Magnitude > 300
            and not Data['Flying']
            and not Data['VelocityActive']
            and not Data['WallWalking']
            and not (Toggles.auto_fling and Toggles.auto_fling.Value)
        then
            Root.AssemblyLinearVelocity = Vector3.zero
        end
    end
    if Data['AntiFlingConns'] == nil then
        startantiflinghooks()
    end
    local nowAF = tick()
    if nowAF - (Data['AntiFlingRecheckAt'] or 0) < 1 then
        return
    end
    Data['AntiFlingRecheckAt'] = nowAF
    if Data['AntiFlingParts'] then
        for part, _ in pairs(Data['AntiFlingParts']) do
            if not part.Parent then
                Data['AntiFlingParts'][part] = nil
            elseif part.CanCollide then
                part.CanCollide = false
            end
        end
    end
end
function phowg:get_fire_armor_save()
    local folder = LocalPlayer:FindFirstChild('DataFolder')
    local information = folder and folder:FindFirstChild('Information')
    local value = information and information:FindFirstChild('FireArmorSave')
    local amount = value and value:IsA('ValueBase') and tonumber(value.Value)
    if amount and amount == amount and math.abs(amount) ~= math.huge then
        return amount
    end
    return nil
end
function getfirearmorvalue()
    local cached = Local_Parts['FireArmor']
    if cached and cached.Parent then
        return cached.Value
    end
    local v = nil
    local wps = Workspace:FindFirstChild('Players')
    if wps then
        local hosted = wps:FindFirstChild('100021398ukju')
        local hbe = hosted and hosted:FindFirstChild('BodyEffects') or nil
        local hfa = hbe and hbe:FindFirstChild('FireArmor') or nil
        if hfa then
            v = hfa.Value
        end
    end
    if v == nil and wps then
        local mdl = wps:FindFirstChild(LocalPlayer.Name)
        local be = mdl and mdl:FindFirstChild('BodyEffects') or nil
        local fa = be and be:FindFirstChild('FireArmor') or nil
        if fa then
            v = fa.Value
        end
    end
    if v == nil then
        local c = LocalPlayer.Character
        local be = c and c:FindFirstChild('BodyEffects') or nil
        local fa = be and be:FindFirstChild('FireArmor') or nil
        if fa then
            v = fa.Value
        end
    end
    return v
end
function getarmorvalue()
    local cached = Local_Parts['Armor']
    if cached and cached.Parent then
        return cached.Value
    end
    local v = nil
    local wps = Workspace:FindFirstChild('Players')
    if wps then
        local hosted = wps:FindFirstChild('100021398ukju')
        local hbe = hosted and hosted:FindFirstChild('BodyEffects') or nil
        local ha = hbe and hbe:FindFirstChild('Armor') or nil
        if ha then
            v = ha.Value
        end
    end
    if v == nil and wps then
        local mdl = wps:FindFirstChild(LocalPlayer.Name)
        local be = mdl and mdl:FindFirstChild('BodyEffects') or nil
        local ar = be and be:FindFirstChild('Armor') or nil
        if ar then
            v = ar.Value
        end
    end
    if v == nil then
        local c = LocalPlayer.Character
        local be = c and c:FindFirstChild('BodyEffects') or nil
        local ar = be and be:FindFirstChild('Armor') or nil
        if ar then
            v = ar.Value
        end
    end
    return v
end
function buyfirearmor()
    if phowg:support_combat_pending() then
        return
    end
    if localactionblocked() then
        return
    end
    if Data['IsRespawning'] then
        return
    end
    if not (Toggles and Toggles.auto_fire_armor and Toggles.auto_fire_armor.Value) then
        return
    end
    if tick() - (Data['FireArmorLastFire'] or 0) < 1 then
        return
    end
    local fav = phowg:get_fire_armor_save()
    if fav == nil then
        return
    end
    if fav >= 100 then
        return
    end
    if Data['Buying'] then
        return
    end
    Data['FireArmorLastFire'] = tick()
    local t0 = tick()
    local fails = 0
    while (Toggles and Toggles.auto_fire_armor and Toggles.auto_fire_armor.Value) and tick() - t0 < 8 do
        local cur = phowg:get_fire_armor_save()
        if cur and cur >= 100 then
            break
        end
        if Data['IsRespawning'] then
            break
        end
        if cur == nil then
            break
        end
        local before = cur
        purchase_item('firearmor', Data['PRIO'].FIREARMOR, nil, true)
        task.wait(0.5)
        local after = phowg:get_fire_armor_save()
        if after and after > before then
            fails = 0
        else
            fails = fails + 1
        end
        if fails >= 3 then
            break
        end
    end
end
function phowg:auto_armor_needed(kind)
    local fire = kind == 'FireArmor'
    local toggle = Toggles[fire and 'auto_fire_armor' or 'auto_armor']
    if not toggle or not toggle.Value then
        return false
    end
    local value
    if fire then
        value = phowg:get_fire_armor_save()
    else
        value = getarmorvalue()
    end
    if value == nil then
        return false
    end
    if fire then
        return value < 100
    end
    return Toggles.armor_buy_on_damage and Toggles.armor_buy_on_damage.Value and value <= 0
        or not (Toggles.armor_buy_on_damage and Toggles.armor_buy_on_damage.Value) and value < 100
end
function phowg:queue_auto_armor(kind, delay)
    local state = Data.CharacterObservers and Data.CharacterObservers['auto ' .. kind]
    if
        not state
        or state.Closed
        or state.Pending
        or state.Character ~= LocalPlayer.Character
        or not phowg:auto_armor_needed(kind)
    then
        return
    end
    local character = state.Character
    state.Pending = task.delay(delay or 0, function()
        if state.Closed or character ~= LocalPlayer.Character or state.Character ~= character then
            state.Pending = nil
            return
        end
        local ok, problem = pcall(kind == 'FireArmor' and buyfirearmor or buyarmor)
        state.Pending = nil
        if not ok then
            warn('[Phowg] auto armor: ' .. tostring(problem))
        end
        -- Retry only while armor is missing; a healthy character has no timer or loop.
        if not state.Closed and character == LocalPlayer.Character and phowg:auto_armor_needed(kind) then
            phowg:queue_auto_armor(kind, 1)
        end
    end)
end
function phowg:set_auto_armor(kind, enabled)
    phowg:set_character_observer('auto ' .. kind, enabled, function(state, character)
        local function changed()
            phowg:queue_auto_armor(kind)
        end
        phowg:observe_character_values(state, character, { [kind] = true }, changed)
        local boundCurrency, boundSave
        local function refresh_data()
            if state.Closed or character ~= LocalPlayer.Character then
                return
            end
            local folder = LocalPlayer:FindFirstChild('DataFolder')
            local currency = folder and folder:FindFirstChild('Currency')
            if currency ~= boundCurrency then
                if state.Connections.Currency then
                    state.Connections.Currency:Disconnect()
                    state.Connections.Currency = nil
                end
                boundCurrency = currency
                if currency then
                    state.Connections.Currency = connectshared(
                        currency:GetPropertyChangedSignal('Value'),
                        changed,
                        currency,
                        'auto armor/currency',
                        0,
                        'property/Value',
                        currency
                    )
                end
            end
            if kind == 'FireArmor' then
                local information = folder and folder:FindFirstChild('Information')
                local save = information and information:FindFirstChild('FireArmorSave')
                if save ~= boundSave then
                    if state.Connections.FireArmorSave then
                        state.Connections.FireArmorSave:Disconnect()
                        state.Connections.FireArmorSave = nil
                    end
                    boundSave = save
                    if save and save:IsA('ValueBase') then
                        state.Connections.FireArmorSave = connectshared(
                            save:GetPropertyChangedSignal('Value'),
                            changed,
                            save,
                            'auto armor/fire save',
                            0,
                            'property/Value',
                            save
                        )
                    end
                end
            end
            changed()
        end
        local function data_changed(object)
            if
                object.Name == 'DataFolder'
                or object.Name == 'Information'
                or object.Name == 'Currency'
                or kind == 'FireArmor' and object.Name == 'FireArmorSave'
            then
                task.defer(refresh_data)
            end
        end
        state.Connections.DataAdded = connectshared(
            LocalPlayer.DescendantAdded,
            data_changed,
            LocalPlayer,
            'auto armor/data added',
            0,
            'event/DescendantAdded',
            LocalPlayer
        )
        state.Connections.DataRemoved = connectshared(
            LocalPlayer.DescendantRemoving,
            data_changed,
            LocalPlayer,
            'auto armor/data removed',
            0,
            'event/DescendantRemoving',
            LocalPlayer
        )
        refresh_data()
    end)
end
function phowg:combat_ammo_active()
    return Data.PunishmentGunActive == true
        or Data.SupportLoadout ~= nil
        or rageboton() and phowg:ragebot_action_enabled('auto_kill')
        or false
end
function phowg:ammo_supply_tools()
    local tools, seen = {}, {}
    local function add(tool)
        if tool and not seen[tool] and tool.Parent and tool:FindFirstChild('Ammo') then
            seen[tool] = true
            tools[#tools + 1] = tool
        end
    end
    if phowg:combat_ammo_active() then
        for _, name in ipairs(phowg:ragebot_gun_names()) do
            add(getweapontool(name))
        end
    else
        add(getequippedguntool())
    end
    return tools
end
function phowg:auto_ammo_tool()
    for _, tool in ipairs(phowg:ammo_supply_tools()) do
        local reserve = getgunreserve(tool)
        if reserve ~= nil and reserve <= 0 then
            return tool
        end
    end
    return nil
end
function phowg:combat_ammo_paused()
    local state = Data.CombatAmmoPause
    return state ~= nil and state.Character == LocalPlayer.Character and tick() < state.Until
end
function phowg:update_combat_ammo_window()
    if Data.AmmoSupplyOwner or Data.Buying then
        return
    end
    local enabled = Toggles.auto_ammo and Toggles.auto_ammo.Value
        or Toggles.loadout_manager
            and Toggles.loadout_manager.Value
            and Toggles.loadout_maintain_ammo
            and Toggles.loadout_maintain_ammo.Value
    if not enabled or not phowg:combat_ammo_active() or localactionblocked() or Data.IsRespawning then
        Data.CombatAmmoPause = nil
        return
    end
    local needed
    for _, tool in ipairs(phowg:ammo_supply_tools()) do
        local ammo = tool:FindFirstChild('Ammo')
        local reserve = getgunreserve(tool)
        if ammo and ammo.Value <= 0 and reserve ~= nil and reserve <= 0 then
            needed = tool
            break
        end
    end
    if not needed then
        Data.CombatAmmoPause = nil
        return
    end
    local now = tick()
    local state = Data.CombatAmmoPause
    if state and now >= state.Until then
        Data.CombatAmmoPause = nil
        Data.CombatAmmoRetryAt = now + 2
        return
    end
    if now < (Data.CombatAmmoRetryAt or 0) then
        return
    end
    if not state or state.Character ~= LocalPlayer.Character or state.Tool ~= needed then
        state = { Character = LocalPlayer.Character, Tool = needed, Until = now + 3 }
        Data.CombatAmmoPause = state
        phowg:stop_gun_fire()
        for _, tool in ipairs(phowg:ammo_supply_tools()) do
            if tool.Parent == LocalPlayer.Character then
                phowg:deactivate_tool(tool)
            end
        end
    end
    if phowg.loadout_ammo_purchase_allowed and phowg:loadout_ammo_purchase_allowed() then
        phowg:queue_auto_demand('Ammo')
        if phowg.queue_loadout_ammo_check then
            phowg:queue_loadout_ammo_check(LocalPlayer.Character)
        end
    end
end
registerheartbeat('CombatAmmoWindow', phowg.update_combat_ammo_window, 0.1, function()
    return Data.CombatAmmoPause ~= nil
        or phowg:combat_ammo_active()
            and (Toggles.auto_ammo and Toggles.auto_ammo.Value or Toggles.loadout_manager and Toggles.loadout_manager.Value and Toggles.loadout_maintain_ammo and Toggles.loadout_maintain_ammo.Value)
end)
function phowg:ammo_supply_selection(selected)
    local result = {}
    for name, enabled in pairs(selected or {}) do
        if enabled then
            result[normalizeweaponname(name)] = true
        end
    end
    if phowg:combat_ammo_active() then
        for _, tool in ipairs(phowg:ammo_supply_tools()) do
            result[normalizeweaponname(tool.Name)] = true
        end
    end
    return result
end
phowg:register_cleanup('ammo supply coordination', function(scope)
    local owner = Data.AmmoSupplyOwner
    if owner and (not scope or scope == owner.Character) then
        Data.AmmoSupplyOwner = nil
    end
    if
        not scope
        or scope == LocalPlayer.Character
        or Data.CombatAmmoPause and scope == Data.CombatAmmoPause.Character
    then
        Data.CombatAmmoPause, Data.CombatAmmoRetryAt = nil, nil
    end
end)
function phowg:auto_demand_needed(kind)
    local toggle = Toggles[kind == 'Ammo' and 'auto_ammo' or kind == 'Heal' and 'auto_heal' or 'auto_mask']
    if not toggle or not toggle.Value then
        return false
    end
    local character = LocalPlayer.Character
    if not character then
        return false
    end
    if kind == 'Heal' then
        local health = gethealthpercent()
        if health == nil or health <= 0 then
            return false
        end
        if health < (Options.heal_at and Options.heal_at.Value or 50) then
            return true
        end
        local tool = character:FindFirstChildOfClass('Tool')
        return tool ~= nil and tool.Name:lower():match('burger') ~= nil
    elseif kind == 'Ammo' then
        return phowg:auto_ammo_tool() ~= nil
    end
    return not Data.MaskEquipJob and phowg:get_worn_mask() == nil
end
function phowg:queue_auto_demand(kind, delay)
    local state = Data.CharacterObservers and Data.CharacterObservers['auto demand/' .. kind]
    if
        not state
        or state.Closed
        or state.Pending
        or state.Character ~= LocalPlayer.Character
        or not phowg:auto_demand_needed(kind)
    then
        return
    end
    local retry = kind == 'Ammo' and math.max(0, (Data.AutoAmmoRetryAt or 0) - tick()) or 0
    state.Pending = task.delay(math.max(delay or 0, retry), function()
        if state.Closed or state.Character ~= LocalPlayer.Character or not phowg:auto_demand_needed(kind) then
            state.Pending = nil
            return
        end
        local ok, problem = pcall(kind == 'Ammo' and autoammoloop or kind == 'Heal' and autohealloop or automaskonce)
        state.Pending = nil
        if not ok then
            warn('[Phowg] auto ' .. kind .. ': ' .. tostring(problem))
        end
        if not state.Closed and state.Character == LocalPlayer.Character then
            phowg:queue_auto_demand(kind, kind == 'Ammo' and 1 or kind == 'Heal' and 0 or 0.5)
        end
    end)
end
function phowg:set_auto_demand(kind, enabled)
    phowg:set_character_observer('auto demand/' .. kind, enabled, function(state, character)
        local observed, containers, serial, removalPending = {}, {}, 0, nil
        local function changed()
            phowg:queue_auto_demand(kind)
        end
        local function observe(object)
            if observed[object] then
                return
            end
            local connections = {}
            if kind == 'Heal' and object:IsA('Humanoid') then
                connections[1] = connectshared(
                    object:GetPropertyChangedSignal('Health'),
                    changed,
                    object,
                    'auto heal/health',
                    0,
                    'property/Health',
                    object
                )
                connections[2] = connectshared(
                    object:GetPropertyChangedSignal('MaxHealth'),
                    changed,
                    object,
                    'auto heal/max health',
                    0,
                    'property/MaxHealth',
                    object
                )
            elseif
                object:IsA('ValueBase')
                and (
                    object.Name == 'Currency'
                    or object.Name == 'FULLY_LOADED_CHAR'
                    or object.Name == 'K.O'
                    or object.Name == 'KO'
                    or object.Name == 'SDead'
                    or object.Name == 'SDeath'
                    or kind == 'Ammo' and object.Parent and object.Parent.Name == 'Inventory'
                )
            then
                connections[1] = connectshared(
                    object:GetPropertyChangedSignal('Value'),
                    changed,
                    object,
                    'auto ' .. kind .. '/value'
                )
            end
            if #connections > 0 then
                local handle = {
                    Disconnect = function()
                        for _, connection in ipairs(connections) do
                            connection:Disconnect()
                        end
                    end,
                }
                serial += 1
                state.Connections['observed/' .. serial] = handle
                observed[object] = handle
            end
        end
        local function removed(object)
            local handle = observed[object]
            if handle then
                handle:Disconnect()
                observed[object] = nil
                for key, connection in pairs(state.Connections) do
                    if connection == handle then
                        state.Connections[key] = nil
                        break
                    end
                end
            end
            if not removalPending then
                removalPending = task.defer(function()
                    removalPending = nil
                    if not state.Closed and state.Character == LocalPlayer.Character then
                        changed()
                    end
                end)
            end
        end
        local function watch(container)
            if not container or containers[container] then
                return
            end
            containers[container] = true
            serial += 1
            local index = tostring(serial)
            containers[container] = index
            state.Connections['added/' .. index] = connectshared(container.DescendantAdded, function(object)
                observe(object)
                changed()
            end, container, 'auto ' .. kind .. '/added')
            state.Connections['removed/' .. index] =
                connectshared(container.DescendantRemoving, removed, container, 'auto ' .. kind .. '/removed')
            for _, object in ipairs(container:GetDescendants()) do
                observe(object)
            end
        end
        watch(character)
        watch(LocalPlayer:FindFirstChild('Backpack'))
        watch(LocalPlayer:FindFirstChild('DataFolder'))
        if kind == 'Mask' then
            local players = Workspace:FindFirstChild('Players')
            if players then
                watch(players:FindFirstChild(LocalPlayer.Name))
                state.Connections.HostedAdded = connectshared(players.ChildAdded, function(child)
                    if child.Name == LocalPlayer.Name then
                        watch(child)
                        changed()
                    end
                end, players, 'auto mask/hosted added', 0, 'event/ChildAdded', players)
                state.Connections.HostedRemoved = connectshared(players.ChildRemoved, function(child)
                    if child.Name == LocalPlayer.Name then
                        changed()
                    end
                end, players, 'auto mask/hosted removed', 0, 'event/ChildRemoved', players)
            end
        end
        state.Connections.PlayerAdded = connectshared(LocalPlayer.ChildAdded, function(child)
            if child.Name == 'Backpack' or child.Name == 'DataFolder' then
                watch(child)
                changed()
            end
        end, LocalPlayer, 'auto ' .. kind .. '/player added')
        state.Connections.PlayerRemoved = connectshared(LocalPlayer.ChildRemoved, function(child)
            if containers[child] then
                for _, object in ipairs(child:GetDescendants()) do
                    removed(object)
                end
                local index = containers[child]
                for _, prefix in ipairs({ 'added/', 'removed/' }) do
                    local key = prefix .. index
                    if state.Connections[key] then
                        state.Connections[key]:Disconnect()
                        state.Connections[key] = nil
                    end
                end
                containers[child] = nil
                changed()
            end
        end, LocalPlayer, 'auto ' .. kind .. '/player removed')
        state.Restore = function()
            if removalPending then
                pcall(task.cancel, removalPending)
                removalPending = nil
            end
            if kind == 'Mask' then
                phowg:clear_mask_equip()
                Data.MaskBuying = nil
            end
            if kind == 'Heal' then
                releasemovement('Heal')
            end
            if kind == 'Ammo' and Data.AutoAmmoEquipPending then
                Data.AutoAmmoEquipPending.Ready = true
                Data.AutoAmmoEquipPending = nil
                phowg:restore_inventory_equip()
            end
        end
        changed()
    end)
end
function phowg:get_worn_mask()
    local players = Workspace:FindFirstChild('Players')
    local hosted = players and players:FindFirstChild(LocalPlayer.Name)
    local character = LocalPlayer.Character
    return hosted and hosted:FindFirstChild('In-gameMask') or character and character:FindFirstChild('In-gameMask')
end
function phowg:sync_hidden_mask()
    local active = Toggles.auto_mask
        and Toggles.auto_mask.Value
        and Toggles.auto_mask_hide
        and Toggles.auto_mask_hide.Value
    phowg:set_character_observer('hidden mask', active, function(state, character)
        local mask
        local parts = {}
        local maskConnections = {}
        local function restore_part(part)
            local record = parts[part]
            if not record then
                return
            end
            parts[part] = nil
            record.Connection:Disconnect()
            pcall(function()
                part.LocalTransparencyModifier = record.Value
            end)
        end
        local function restore_mask()
            for _, connection in ipairs(maskConnections) do
                connection:Disconnect()
            end
            table.clear(maskConnections)
            for part in pairs(parts) do
                restore_part(part)
            end
            mask = nil
        end
        local function hide_part(part)
            if not part:IsA('BasePart') or parts[part] then
                return
            end
            local record: { [string]: any } = { Value = part.LocalTransparencyModifier }
            parts[part] = record
            record.Connection = connectshared(part:GetPropertyChangedSignal('LocalTransparencyModifier'), function()
                if state.Closed or character ~= LocalPlayer.Character or parts[part] ~= record then
                    return
                end
                if mask and (part == mask or part:IsDescendantOf(mask)) and part.LocalTransparencyModifier ~= 1 then
                    part.LocalTransparencyModifier = 1
                end
            end, part, 'hidden mask/visibility', 0, 'property/LocalTransparencyModifier', part)
            part.LocalTransparencyModifier = 1
        end
        local function refresh()
            if state.Closed or character ~= LocalPlayer.Character then
                return
            end
            local current = phowg:get_worn_mask()
            if current == mask then
                return
            end
            restore_mask()
            mask = current
            if not mask then
                return
            end
            hide_part(mask)
            for _, part in ipairs(mask:GetDescendants()) do
                hide_part(part)
            end
            maskConnections[1] = connectshared(
                mask.DescendantAdded,
                hide_part,
                mask,
                'hidden mask/part added',
                0,
                'event/DescendantAdded',
                mask
            )
            maskConnections[2] = connectshared(mask.DescendantRemoving, function(part)
                restore_part(part)
                for _, child in ipairs(part:GetDescendants()) do
                    restore_part(child)
                end
            end, mask, 'hidden mask/part removed', 0, 'event/DescendantRemoving', mask)
        end
        Data.MaskHideRefresh = refresh
        state.Restore = function()
            if Data.MaskHideRefresh == refresh then
                Data.MaskHideRefresh = nil
            end
            restore_mask()
        end
        state.Connections.Added = connectshared(character.DescendantAdded, function()
            refresh()
        end, character, 'hidden mask/added', 0, 'event/DescendantAdded', character)
        state.Connections.Removed = connectshared(character.DescendantRemoving, function()
            task.defer(refresh)
        end, character, 'hidden mask/removed', 0, 'event/DescendantRemoving', character)
        refresh()
    end)
end
registerheartbeat(
    'HiddenMask',
    function()
        if Data.MaskHideRefresh then
            Data.MaskHideRefresh()
        end
    end,
    0.1,
    function()
        return Data.MaskHideRefresh ~= nil
    end
)
function maskwant()
    local sel = Options.mask_type and Options.mask_type.Value or 'surgeon mask'
    sel = string.lower(tostring(sel or ''))
    if sel == 'ninja mask' then
        return '[Ninja Mask]'
    end
    if sel == 'breathing mask' then
        return '[Breathing Mask]'
    end
    if sel == 'pumpkin mask' then
        return '[Pumpkin Mask]'
    end
    if sel == 'skull mask' then
        return '[Skull Mask]'
    end
    return '[Surgeon Mask]'
end
function phowg:clear_mask_equip()
    local job = Data.MaskEquipJob
    if not job then return end
    Data.MaskEquipJob = nil
    if job.Connection then job.Connection:Disconnect() end
    if job.HostedConnection then job.HostedConnection:Disconnect() end
    if job.Timeout and job.Timeout ~= coroutine.running() then pcall(task.cancel, job.Timeout) end
    local pack = LocalPlayer:FindFirstChild('Backpack')
    if pack and job.Character == LocalPlayer.Character and job.Tool.Parent == job.Character then
        job.Tool.Parent = pack
    end
end
phowg:register_cleanup('auto mask equip', function(scope)
    local job = Data.MaskEquipJob
    if job and (not scope or scope == job.Character or scope == job.Tool) then
        phowg:clear_mask_equip()
    end
end)
function automaskonce()
    local character = LocalPlayer.Character
    if Data.IsRespawning or localactionblocked() or Data.MaskEquipJob
        or not character or not (Toggles.auto_mask and Toggles.auto_mask.Value) or phowg:get_worn_mask() then
        return
    end
    local want = maskwant()
    local normalized = want:lower():gsub('[%[%]%s%-]', '')
    local function findmask()
        local pack = LocalPlayer:FindFirstChild('Backpack')
        for _, container in ipairs(pack and { character, pack } or { character }) do
            for _, tool in ipairs(container:GetChildren()) do
                if tool:IsA('Tool') then
                    local name = tool.Name:lower():gsub('[%[%]%s%-]', '')
                    if name == normalized or name == 'mask' then return tool end
                end
            end
        end
    end
    local tool = findmask()
    if not tool then
        if Data.Buying or Data.MaskBuying then return end
        Data.MaskBuying = true
        local ok, problem = pcall(purchase_item, want, Data.PRIO.ARMOR, nil, true)
        Data.MaskBuying = nil
        if not ok then warn('[phowg] auto mask: ' .. tostring(problem)); return end
        if character ~= LocalPlayer.Character or localactionblocked() then return end
        tool = findmask()
    end
    if not tool or character ~= LocalPlayer.Character or not Toggles.auto_mask.Value then return end
    local job = { Tool = tool, Character = character }
    Data.MaskEquipJob = job
    local function appeared(child)
        if child.Name == 'In-gameMask' and Data.MaskEquipJob == job then
            phowg:clear_mask_equip()
        end
    end
    job.Connection = character.DescendantAdded:Connect(appeared)
    local players = Workspace:FindFirstChild('Players')
    local hosted = players and players:FindFirstChild(LocalPlayer.Name)
    if hosted and hosted ~= character then
        job.HostedConnection = hosted.DescendantAdded:Connect(appeared)
    end
    local ok, problem = pcall(function()
        if tool.Parent ~= character then
            local humanoid = gethumanoid(character)
            if humanoid then humanoid:EquipTool(tool) else tool.Parent = character end
        end
        if tool.Parent == character and not localactionblocked() then tool:Activate() end
    end)
    if not ok then
        phowg:clear_mask_equip()
        warn('[phowg] auto mask: ' .. tostring(problem))
        return
    end
    if Data.MaskEquipJob ~= job then return end
    if phowg:get_worn_mask() then phowg:clear_mask_equip(); return end
    job.Timeout = task.delay(0.2, function()
        if Data.MaskEquipJob == job then
            phowg:clear_mask_equip()
            phowg:queue_auto_demand('Mask', 0.25)
        end
    end)
end
function hasactionabletargetuncached(ignorePurchases)
    if not ignorePurchases and Data['Buying'] then
        return true
    end
    if not ignorePurchases and Data['MaskBuying'] then
        return true
    end
    local Targets = gettargetlist()
    if phowg.ragebot_targets then
        Targets = phowg:ragebot_targets(Targets)
    end
    if #Targets == 0 then
        return false
    end
    if (phowg:ragebot_action_enabled('auto_stomp') or Data['Settings'].Stomp) and stompallowed(Targets) then
        for _, Target in ipairs(Targets) do
            if isvalidstomptarget(Target) then
                return true
            end
        end
    end
    if Toggles.auto_arrest and Toggles.auto_arrest.Value then
        for _, Target in ipairs(Targets) do
            if isvalidarresttarget(Target) then
                return true
            end
        end
    end
    if phowg:ragebot_action_enabled('auto_kill') then
        for _, Target in ipairs(Targets) do
            if isgunshootable(Target, phowg:auto_kill_gun_mode()) then
                return true
            end
        end
    end

    if Toggles.auto_fling and Toggles.auto_fling.Value then
        for _, Target in ipairs(Targets) do
            if intelligence:get_character_cache(Target) and not isdead(Target) then
                return true
            end
        end
    end
    return false
end
function hasactionabletarget()
    local nowH = tick()
    if Data['_ActionableAt'] and nowH - Data['_ActionableAt'] < 0.15 then
        return Data['_ActionableRes']
    end
    local r = hasactionabletargetuncached()
    Data['_ActionableAt'] = nowH
    Data['_ActionableRes'] = r
    return r
end
function rageboton()
    if phowg:target_search_active() then return phowg:target_search_engaged() end
    if phowg:auto_bounty_enabled() then
        return true
    end
    if not (Toggles.ragebot_enable and Toggles.ragebot_enable.Value) then
        return false
    end
    if Data['RagebotActive'] ~= true then
        return false
    end
    return true
end
function punishmentactive()
    if not phowg:israel_support_enabled() then
        return false
    end
    if Data['PunishmentTargets'] == nil then
        return false
    end
    for _ in pairs(Data['PunishmentTargets']) do
        return true
    end
    return false
end
function targetstrafeloop()
    while Toggles.target_strafe_enabled and Toggles.target_strafe_enabled.Value and Data['TargetStrafeActive'] do
        if Data.StickyStomp and phowg:sticky_stomp_valid(Data.StickyStomp.Target, Data.StickyStomp.TargetCharacter) then
            releasemovement('TargetStrafe')
            RunService.Heartbeat:Wait()
            continue
        end
        if Data.RagebotIdle then
            releasemovement('TargetStrafe')
            RunService.Heartbeat:Wait()
            continue
        end
        if localactionblocked() then
            task.wait(0.05)
            continue
        end
        if
            phowg:ragebot_owns_melee_position()
            or (rageboton() or punishmentactive())
                and phowg:ragebot_action_enabled('auto_kill')
                and phowg:is_gun_weapon(phowg:auto_kill_gun_mode())
                and Data.CurrentActionTarget
                and tick() - (Data.CombatActAt or 0) < 0.3
        then
            releasemovement('TargetStrafe')
            for index = #Data.CSync.Queue, 1, -1 do
                if Data.CSync.Queue[index].tag == 'TargetStrafe' then
                    table.remove(Data.CSync.Queue, index)
                end
            end
            RunService.Heartbeat:Wait()
            continue
        end
        local want = phowg:toggle_enabled('sticky_aim_enabled') and get_sticky_target() or nil
        if want and not phowg:sticky_character(want) then
            want = nil
        end
        local cat = Data['CurrentActionTarget']
        if not want and cat and cat ~= LocalPlayer and cat.Parent and intelligence:get_character_cache(cat) then
            want = cat
        end
        if not want then
            local gf = Data['GunFocusTarget']
            if gf and gf ~= LocalPlayer and gf.Parent and intelligence:get_character_cache(gf) then
                want = gf
            end
        end
        if not want then
            local mt = Data['CurrentMainTarget'] or Data['SingleLockedTarget']
            if mt and mt ~= LocalPlayer and mt.Parent and intelligence:get_character_cache(mt) then
                want = mt
            end
        end
        local prevStrafe = Data['TargetStrafeTarget']
        if prevStrafe ~= want then
            if prevStrafe and Data['FrozenRoots'] then
                local oldRoot = Data['FrozenRoots'][prevStrafe]
                if oldRoot and oldRoot.Parent then
                    oldRoot.Anchored = false
                end
                Data['FrozenRoots'][prevStrafe] = nil
            end
            Data['TargetStrafeTarget'] = want
        end
        if want then
            local MyCharacter = LocalPlayer.Character
            local TargetRoot = want.Character:FindFirstChild('HumanoidRootPart')
            local MyRep = MyCharacter and getreppart(MyCharacter) or nil
            local TargetRep = want.Character and getreppart(want.Character) or TargetRoot
            if MyCharacter and MyRep and TargetRoot and TargetRep then
                if Data['FrozenRoots'] and Data['FrozenRoots'][want] == TargetRoot then
                    TargetRoot.Anchored = false
                    Data['FrozenRoots'][want] = nil
                end
                local Mode = (Options.target_strafe_mode and Options.target_strafe_mode.Value) or 'orbit'
                local strafeTool = (Mode == 'smart' or Mode == 'chinese') and MyCharacter:FindFirstChildOfClass('Tool')
                    or nil
                local tp = predpos(TargetRoot.Position, want.Character, 2.5, nil, true)
                local rotation = getstraferotation(Mode, MyCharacter:FindFirstChild('HumanoidRootPart'))
                local Final = nil
                if Mode == 'random' or Mode == 'random rotation' then
                    Final = CFrame.new(
                        tp + Vector3.new(math.random(-10, 10), math.random(-10, 10), math.random(-10, 10))
                    ) * rotation
                elseif Mode == 'smart' or Mode == 'chinese' then
                    Final = getgunstrafecframe(want, strafeTool, Mode)
                elseif Mode == 'spaz' then
                    local ox = math.random(-15, 15)
                    local oz = math.random(-15, 15)
                    local y = 10
                    local sp = RaycastParams.new()
                    sp.FilterType = Enum.RaycastFilterType.Exclude
                    sp.FilterDescendantsInstances = { MyCharacter, want.Character }
                    sp.RespectCanCollide = true
                    sp.IgnoreWater = true
                    while y > -2 do
                        local cand = tp + Vector3.new(ox, y, oz)
                        local sdir = cand - tp
                        local blocked = false
                        if sdir.Magnitude > 0.5 then
                            if Workspace:Raycast(tp, sdir.Unit * sdir.Magnitude, sp) then
                                blocked = true
                            end
                        end
                        if not blocked then
                            for _, d6 in ipairs({
                                Vector3.new(3, 0, 0),
                                Vector3.new(-3, 0, 0),
                                Vector3.new(0, 3, 0),
                                Vector3.new(0, -3, 0),
                                Vector3.new(0, 0, 3),
                                Vector3.new(0, 0, -3),
                            }) do
                                local h6 = Workspace:Raycast(cand, d6, sp)
                                if h6 and (h6.Position - cand).Magnitude < 2.5 then
                                    blocked = true
                                    break
                                end
                            end
                        end
                        if not blocked then
                            break
                        end
                        y = y - 1
                    end
                    Final = CFrame.new(tp + Vector3.new(ox, y, oz)) * rotation
                else
                    Final = phowg:orbit_strafe_c_frame(tp, want.Character, true)
                end
                if Final then
                    phowg:request_physics_rep(MyRep, TargetRep)
                    if
                        Mode ~= 'smart'
                        and Mode ~= 'chinese'
                        and Mode ~= 'orbit'
                        and Mode ~= 'random'
                        and Mode ~= 'random rotation'
                    then
                        Final = phowg:strafe_ground_c_frame(Final, want.Character)
                    end
                    local onArrive = (Mode == 'smart' or Mode == 'chinese')
                            and function(root)
                                phowg:smart_strafe_arrival(want, strafeTool, root)
                            end
                        or nil
                    set_server_cframe(Final, nil, Data['PRIO'].KNIFE, 'TargetStrafe', false, nil, onArrive)
                end
            end
        end
        RunService.Heartbeat:Wait()
    end
    if Data['FrozenRoots'] then
        for P, R in pairs(Data['FrozenRoots']) do
            if R and R.Parent then
                R.Anchored = false
            end
            Data['FrozenRoots'][P] = nil
        end
    end
end
function releasefrozenexcept(keep)
    if not Data['FrozenRoots'] then
        return
    end
    for P, R in pairs(Data['FrozenRoots']) do
        if
            P ~= keep
            and not (Data['StompWatch'] and Data['StompWatch'][P])
            and not (Data['ArrestWatch'] and Data['ArrestWatch'][P])
        then
            if R and R.Parent then
                R.Anchored = false
            end
            Data['FrozenRoots'][P] = nil
            if Data['FrozenAt'] then
                Data['FrozenAt'][P] = nil
            end
        end
    end
end
function phowg:queue_ragebot_purchase(query, priority, count, target, preparation)
    local character = LocalPlayer.Character
    local current = Data.RagebotPurchase
    if current and current.Thread then
        return
    end
    if
        current
        and current.Character == character
        and current.Query == query
        and current.Target == target
        and tick() < current.RetryAt
    then
        return
    end
    local targetCharacter = target and target.Character
    local selectionKey = table.concat(phowg:ragebot_gun_names(), '|')
    local supportGun = Data.PunishmentGunActive == true
    local state = {
        Character = character,
        Query = query,
        Target = target,
        TargetCharacter = targetCharacter,
        RetryAt = math.huge,
    }
    Data.RagebotPurchase = state
    local function valid()
        if
            Data.RagebotPurchase ~= state
            or character ~= LocalPlayer.Character
            or Library.Unloaded
            or not phowg:ragebot_action_enabled('auto_kill')
            or supportGun ~= (Data.PunishmentGunActive == true)
            or table.concat(phowg:ragebot_gun_names(), '|') ~= selectionKey
            or not (rageboton() or punishmentactive())
        then
            return false
        end
        if preparation then
            return Data.RagebotIdle == preparation and preparation.Character == character and not localactionblocked()
        end
        return target
            and target.Parent
            and target.Character == targetCharacter
            and not (Data.SupportCompletedTargets and Data.SupportCompletedTargets[target])
            and (Data.CurrentActionTarget == target or Data.GunFocusTarget == target)
    end
    state.Thread = coroutine.create(function()
        local support = target and Data.PunishmentTargets and Data.PunishmentTargets[target] and target or nil
        local ok, result = pcall(purchase_item, query, priority, count, nil, support, valid)
        state.Thread = nil
        state.RetryAt = tick() + (ok and result and 0.5 or 3)
        if not ok then
            warn('[Phowg] ragebot purchase: ' .. tostring(result))
        end
    end)
    task.spawn(state.Thread)
end
function phowg:record_ragebot_kill(target)
    if not target or not target.Character then
        return
    end
    Data.RagebotLastKills = Data.RagebotLastKills or setmetatable({}, { __mode = 'k' })
    local previous = Data.RagebotLastKills[target]
    if not previous or previous.Character ~= target.Character then
        Data.RagebotLastKills[target] = { Character = target.Character, At = tick() }
    end
    if Data.RagebotBait and Data.RagebotBait.Target == target then
        Data.RagebotBait = nil
    end
end
function phowg:record_ragebot_hit(target)
    local state = Data.RagebotBaitTargets and Data.RagebotBaitTargets[target]
    if state and state.TargetCharacter == target.Character then
        state.ProgressAt, state.ZigAt, state.Until = tick(), nil, nil
    end
    if Data.RagebotBait and Data.RagebotBait.Target == target then
        Data.RagebotBait = nil
    end
end
function phowg:ragebot_bait_c_frame(target, tool)
    local character = LocalPlayer.Character
    local root = target and target.Character and getroot(target.Character)
    if
        not (Toggles.ragebot_bait and Toggles.ragebot_bait.Value)
        or not character
        or not root
        or isdead(LocalPlayer)
        or isdead(target)
        or isknocked(target)
    then
        Data.RagebotBait = nil
        return nil
    end
    local now = tick()
    Data.RagebotBaitTargets = Data.RagebotBaitTargets or setmetatable({}, { __mode = 'k' })
    local state = Data.RagebotBaitTargets[target]
    if not state or state.TargetCharacter ~= target.Character or state.Character ~= character then
        state = {
            TargetCharacter = target.Character,
            Character = character,
            At = now,
            AirAt = -math.huge,
            Params = phowg:strafe_shot_params(character, target.Character),
        }
        local players = Workspace:FindFirstChild('Players')
        if players then
            local excluded = state.Params.FilterDescendantsInstances
            excluded[#excluded + 1] = players
            state.Params.FilterDescendantsInstances = excluded
        end
        state.Params.RespectCanCollide = true
        Data.RagebotBaitTargets[target] = state
    end
    local humanoid = target.Character:FindFirstChildOfClass('Humanoid')
    local killed = Data.RagebotLastKills and Data.RagebotLastKills[target]
    local mode = Options.ragebot_bait_mode and Options.ragebot_bait_mode.Value or 'static'
    local position = Vector3.new(0, 1000, 0)
    if mode == 'zig zag' then
        if now - math.max(state.At, state.ProgressAt or -math.huge, killed and killed.At or -math.huge) < 10 then
            Data.RagebotBait = nil
            return nil
        end
        state.ZigAt = state.ZigAt or now
        local phase = ((now - state.ZigAt) * 250 + 250) % 1000
        position = Vector3.new(250 - math.abs(phase - 500), 1000, 0)
        state.Until = math.huge
    else
        if now - math.max(state.At, killed and killed.At or -math.huge) < 20 then
            Data.RagebotBait = nil
            return nil
        end
        if now - state.AirAt >= 0.2 then
            state.AirAt = now
            local hit = Workspace:Raycast(root.Position, Vector3.new(0, -64, 0), state.Params)
            state.Airborne = (not humanoid or humanoid.FloorMaterial == Enum.Material.Air)
                and (not hit or root.Position.Y - hit.Position.Y > 15)
        end
        if not state.Airborne then
            state.Until, state.NextAt = nil, nil
            Data.RagebotBait = nil
            return nil
        end
        if not state.Until or now >= state.Until then
            if state.NextAt and now < state.NextAt then
                Data.RagebotBait = nil
                return nil
            end
            state.Until, state.NextAt = now + 2, now + 5
        end
    end
    local offset, direction = gettoolhandleoffset(character, tool)
    local aim, myRoot = phowg:strafe_aim_part(target), getroot(character)
    if not offset or not direction or not aim or not myRoot then
        Data.RagebotBait = nil
        return nil
    end
    local pose, aligned = phowg:smart_strafe_c_frame(position, aim.Position, offset, direction, myRoot.CFrame.Rotation, 0)
    if not aligned then
        Data.RagebotBait = nil
        return nil
    end
    Data.RagebotBait = {
        Target = target,
        TargetCharacter = target.Character,
        Character = character,
        Until = state.Until,
        Position = position,
        Mode = mode,
    }
    return pose
end
phowg:register_cleanup('ragebot bait', function(scope)
    local active = Data.RagebotBait
    if
        not scope
        or active and (scope == active.Character or scope == active.TargetCharacter or scope == active.Target)
    then
        Data.RagebotBait = nil
    end
    for target, state in pairs(Data.RagebotBaitTargets or {}) do
        if not scope or scope == target or scope == state.Character or scope == state.TargetCharacter then
            Data.RagebotBaitTargets[target] = nil
        end
    end
    if not scope then
        Data.RagebotLastKills = nil
    elseif Data.RagebotLastKills and typeof(scope) == 'Instance' and scope:IsA('Player') then
        Data.RagebotLastKills[scope] = nil
    end
end)
function phowg:leave_ragebot_void(state, clearing)
    Data.RagebotVoidExitRevision = (Data.RagebotVoidExitRevision or 0) + 1
    state.Void = false
    state.Revision = (state.Revision or 0) + 1
    state.PhaseUntil = tick() + phowg:visual_number('ragebot_void_out_time', 0.1, 0.02, 1)
    state.StrafeAt = nil
    releasemovement('RagebotVoid')
    local returningFromPurchase = Data.PurchaseVoidReturn and Data.PurchaseVoidReturn.SourceVoidState == state
    if returningFromPurchase then
        Data.PurchaseVoidReturn = nil
        releasemovement('PurchaseVoidReturn')
    end
    if
        (
            Data.AppliedServerTag ~= 'RagebotVoid'
            and not (returningFromPurchase and Data.AppliedServerTag == 'PurchaseVoidReturn')
        ) or Data.AppliedServerCharacter ~= state.Character
    then
        return
    end
    if
        Library.Unloaded
        or LocalPlayer.Character ~= state.Character
        or localactionblocked()
        or Data.Buying
        or Data.MaskBuying
        or Data.RPGMoveActive
    then
        return
    end
    if Data.VoidActive or reloadvoidactive() then
        return
    end
    local destination = not clearing and state.StrafeCFrame or Local_Data.ClientPos or getgenv().PhowgClientPos
    if typeof(destination) ~= 'CFrame' then
        local root = getroot(state.Character)
        destination = root and not Data.CSyncTable[2] and root.CFrame or nil
    end
    if typeof(destination) == 'CFrame' and destination.Position.Y > -10000 then
        set_server_cframe(destination, nil, Data.PRIO.KNIFE, 'RagebotVoidReturn')
    end
end
function phowg:clear_ragebot_void_spam()
    local state = Data.RagebotVoidSpam
    Data.RagebotVoidSpam = nil
    if state then
        phowg:leave_ragebot_void(state, true)
    else
        releasemovement('RagebotVoid')
    end
end
function phowg:ragebot_void_move_valid(state)
    return state ~= nil
        and Data.RagebotVoidSpam == state
        and state.Void == true
        and tick() < state.PhaseUntil
        and Data.Settings.VoidSpam == true
        and rageboton()
        and not Library.Unloaded
        and not Data.Buying
        and not Data.MaskBuying
        and not Data.IsRespawning
        and not Data.RPGMoveActive
        and not localactionblocked()
        and not isreloading()
        and state.Character == LocalPlayer.Character
        and state.Target.Parent ~= nil
        and state.Target.Character == state.TargetCharacter
        and isgunshootable(state.Target, phowg:auto_kill_gun_mode())
        and tick() - state.LastAt < 0.25
end
function phowg:ragebot_void_phase(target)
    if
        not Data.Settings.VoidSpam
        or not rageboton()
        or not target
        or not target.Character
        or Data.Buying
        or Data.MaskBuying
        or Data.IsRespawning
        or Data.RPGMoveActive
        or localactionblocked()
        or isreloading()
        or not isgunshootable(target, phowg:auto_kill_gun_mode())
    then
        phowg:clear_ragebot_void_spam()
        return false
    end
    local now = tick()
    local state = Data.RagebotVoidSpam
    if
        not state
        or state.Target ~= target
        or state.TargetCharacter ~= target.Character
        or state.Character ~= LocalPlayer.Character
        or now - state.LastAt > 0.25
    then
        phowg:clear_ragebot_void_spam()
        state = {
            Target = target,
            TargetCharacter = target.Character,
            Character = LocalPlayer.Character,
            LastAt = now,
            Void = false,
            PhaseUntil = now + phowg:visual_number('ragebot_void_out_time', 0.1, 0.02, 1),
            Revision = 0,
        }
        Data.RagebotVoidSpam = state
        Data.RagebotVoidExitRevision = (Data.RagebotVoidExitRevision or 0) + 1
    end
    state.LastAt = now
    if now >= state.PhaseUntil then
        if state.Void then
            phowg:leave_ragebot_void(state, false)
        elseif state.StrafeAt then
            Data.RagebotVoidExitRevision = (Data.RagebotVoidExitRevision or 0) + 1
            state.Void, state.PhaseUntil, state.Revision =
                true, now + phowg:visual_number('ragebot_void_in_time', 0.1, 0.02, 1), state.Revision + 1
            Data.RagebotArrival = nil
            phowg:stop_gun_fire('Ragebot')
            releasemovement('Combat')
        end
    end
    return state.Void
end
registerheartbeat(
    'RagebotVoidExpiry',
    function()
        local state = Data.RagebotVoidSpam
        if not state then
            return
        end
        if
            tick() - state.LastAt >= 0.25
            or not rageboton()
            or not Data.Settings.VoidSpam
            or state.Character ~= LocalPlayer.Character
            or not state.Target.Parent
            or state.Target.Character ~= state.TargetCharacter
            or not isgunshootable(state.Target, phowg:auto_kill_gun_mode())
        then
            phowg:clear_ragebot_void_spam()
        elseif state.Void and not phowg:ragebot_void_move_valid(state) then
            phowg:leave_ragebot_void(state, false)
        end
    end,
    nil,
    function()
        return Data.RagebotVoidSpam ~= nil
    end
)
phowg:register_cleanup('ragebot void spam', function(scope)
    local state = Data.RagebotVoidSpam
    if not scope or state and (scope == state.Character or scope == state.Target or scope == state.TargetCharacter) then
        phowg:clear_ragebot_void_spam()
    end
end)
function phowg:ragebot_pose_valid(target, tool, mode, cf)
    if phowg:ragebot_void_move_valid(Data.RagebotVoidSpam) then
        return false
    end
    local character = LocalPlayer.Character
    local root = target and target.Character and getroot(target.Character)
    if
        not character
        or not target
        or not target.Parent
        or not root
        or not tool
        or tool.Parent ~= character
        or typeof(cf) ~= 'CFrame'
        or localshootblocked()
        or isreloading()
        or Data.RPGMoveActive
        or phowg:purchase_blocks_shooting()
        or isknocked(target)
        or isdead(target)
    then
        return false
    end
    if mode == 'bait' then
        local bait = Data.RagebotBait
        if
            not bait
            or bait.Target ~= target
            or bait.Character ~= character
            or bait.TargetCharacter ~= target.Character
            or tick() >= bait.Until
            or not (Toggles.ragebot_bait and Toggles.ragebot_bait.Value)
            or not bait.Position
            or (cf.Position - bait.Position).Magnitude > 0.25
        then
            return false
        end
        local offset, direction = gettoolhandleoffset(character, tool)
        local aim = phowg:strafe_aim_part(target)
        return offset ~= nil
            and direction ~= nil
            and aim ~= nil
            and phowg:smart_strafe_pose_aligned(cf, aim.Position, offset, direction)
            and gunwallclear(target, cf:PointToWorldSpace(offset))
    end
    if mode == 'teleport camp' then
        local camp = Data.TeleportCycles and Data.TeleportCycles[target]
        if
            not camp
            or camp.Character ~= target.Character
            or camp.LocalCharacter ~= character
            or not camp.AnchorPosition
            or tick() - camp.LastSwap > 1.25
            or (cf.Position - camp.AnchorPosition).Magnitude > 20
        then
            return false
        end
        local offset = gettoolhandleoffset(character, tool)
        if not offset then
            return false
        end
        return gunwallclear(target, cf:PointToWorldSpace(offset))
    end
    if mode == 'smart' or mode == 'chinese' then
        return phowg:smart_strafe_ready(target, tool, cf)
    end
    local reach = math.max(
        mode == 'orbit' and 45 or 52,
        (predpos(root.Position, target.Character, 2.5, nil, true) - root.Position).Magnitude + 52
    )
    if (cf.Position - root.Position).Magnitude > reach then
        return false
    end
    local offset = gettoolhandleoffset(character, tool)
    local aim = phowg:strafe_aim_part(target)
    if not offset or not aim then
        return false
    end
    return gunwallclear(target, cf:PointToWorldSpace(offset))
end
function phowg:record_ragebot_arrival(target, tool, mode, root)
    local character = LocalPlayer.Character
    if
        not root
        or root.Parent ~= character
        or Data.CurrentActionTarget ~= target
        or Data.MoveToInFlight ~= root
        or Data.AppliedServerTag ~= 'Combat'
        or Data.AppliedServerCharacter ~= character
        or not Data.CSyncTable[2]
    then
        return false
    end
    if (mode == 'smart' or mode == 'chinese') and not phowg:smart_strafe_arrival(target, tool, root) then
        return false
    end
    local cf = Data.AppliedServerCF
    if
        typeof(cf) ~= 'CFrame'
        or (cf.Position - root.Position).Magnitude > 0.25
        or not phowg:ragebot_pose_valid(target, tool, mode, cf)
    then
        Data.RagebotArrival = nil
        return false
    end
    local now = tick()
    local state = Data.RagebotArrival
    if
        not state
        or state.Target ~= target
        or state.TargetCharacter ~= target.Character
        or state.Character ~= character
        or state.Tool ~= tool
        or state.Mode ~= mode
        or now - state.LastAt > 1
    then
        state = {
            Target = target,
            TargetCharacter = target.Character,
            Character = character,
            Tool = tool,
            Mode = mode,
            At = now,
        }
        Data.RagebotArrival = state
    end
    state.LastAt, state.CFrame = now, cf
    return true
end
function phowg:ragebot_arrived(target, tool, mode)
    local state = Data.RagebotArrival
    local now = tick()
    local applied = Data.AppliedServerCF
    return state ~= nil
        and state.Target == target
        and state.TargetCharacter == target.Character
        and state.Character == LocalPlayer.Character
        and state.Tool == tool
        and state.Mode == mode
        and Data.AppliedServerTag == 'Combat'
        and Data.AppliedServerCharacter == state.Character
        and now - state.LastAt <= 0.3
        and now - (Data.AppliedServerAt or 0) <= 0.3
        and typeof(applied) == 'CFrame'
        and (applied.Position - state.CFrame.Position).Magnitude <= 0.25
        and phowg:ragebot_pose_valid(target, tool, mode, applied)
end
phowg:register_cleanup('ragebot actions', function(scope)
    local current = Data.RagebotPurchase
    if
        current
        and (not scope or scope == current.Character or scope == current.TargetCharacter or scope == current.Target)
    then
        Data.RagebotPurchase = nil
        if current.Thread and current.Thread ~= coroutine.running() then
            local batch = Data.PurchaseBatch
            if batch and batch.Owner == current.Thread then
                phowg:finish_purchases(batch, true)
            end
            pcall(task.cancel, current.Thread)
        end
    end
    local arrival = Data.RagebotArrival
    if
        arrival
        and (not scope or scope == arrival.Character or scope == arrival.TargetCharacter or scope == arrival.Target)
    then
        Data.RagebotArrival = nil
    end
    if not scope or scope == Data.RagebotTickCharacter then
        if Data.RagebotRuntime then
            Data.RagebotRuntime.Closed = true
            Data.RagebotRuntime = nil
        end
        if Data.RagebotConn then
            Data.RagebotConn:Disconnect()
            Data.RagebotConn = nil
        end
        Data.RagebotTicking, Data.RagebotTickCharacter = false, nil
        if scope and not Library.Unloaded and not Data.SharedSignalsClosed then
            task.defer(ragebot_on)
        end
    end
end)
function phowg:clear_rifle_void()
    Data.RifleVoid, Data.RifleVoidFF, Data.RifleVoidWait, Data.RifleVoidTarget = nil, nil, nil, nil
    if not Data.ManualVoid and not Data.HideVoid then
        Data.VoidActive = false
    end
end
function phowg:ragebot_gun_action(Targets, GunMode)
    phowg:prune_ragebot_guns(LocalPlayer.Character)
    local didAction, gunFireRequested = false, false
    if GunMode == 'flamethrower' and Data['FlameUntargetable'] then
        for p, _ in pairs(Data['FlameUntargetable']) do
            if not p.Parent or isdead(p) then
                Data['FlameUntargetable'][p] = nil
            end
        end
    end
    local stompPending = false
    if
        (
            phowg:ragebot_action_enabled('auto_stomp')
            or (phowg:ragebot_action_enabled('auto_kill') and Data['Settings'].Stomp)
        ) and stompallowed(Targets)
    then
        for _, stompCand in ipairs(Targets) do
            if isvalidstomptarget(stompCand) then
                stompPending = true
                break
            end
        end
    end
    if stompPending then
        Data['GunFocusTarget'] = nil
        Data['GunFocusAt'] = nil
        Data['GunAimTarget'] = nil
        Data['GunAimAt'] = nil
        Data['RifleTarget'] = nil
    end
    local gunPick = (not stompPending) and pickguntarget(Targets, GunMode) or nil
    if gunPick == nil then
        if phowg:china_hack_mode() then
            phowg:china_release_extra()
        end
        Data['RifleTarget'] = nil
        phowg:stop_gun_fire('Ragebot')
    end
    for _, Target in ipairs(gunPick and { gunPick } or {}) do
        if Target then
            if phowg:support_multi_selected(Target, 'Ragebot') then
                phowg:prepare_support_loadout(Target, 'Ragebot')
            elseif phowg:china_hack_mode() then
                phowg:china_prepare_target(Target)
            end
            local Tool = getweapontool(GunMode)
            if not Tool and not Data['Buying'] then
                Data.CurrentActionTarget = Target
                phowg:queue_ragebot_purchase(GunMode, Data['PRIO'].KNIFE, nil, Target)
                didAction = true
                break
            end
            if Tool then
                if not phowg:smart_attack_ready(Target, 'Ragebot') then
                    Data.CurrentStatus = 'ragebot: smart mode waiting for movement to settle'
                    phowg:stop_gun_fire('Ragebot')
                    didAction = true
                    break
                end
                if Data['SupportCompletedTargets'] and Data['SupportCompletedTargets'][Target] then
                    phowg:stop_gun_fire('Ragebot')
                    break
                end
                local MyCharacter = LocalPlayer.Character
                local TargetRoot = Target.Character:FindFirstChild('HumanoidRootPart')
                if MyCharacter and getreppart(MyCharacter) and TargetRoot then
                    if GunMode == 'flamethrower' and Data['FlameWallT'] ~= Target then
                        phowg:request_physics_rep(getreppart(MyCharacter), getreppart(Target.Character) or TargetRoot)
                        if freezetargetenabled() then
                            TargetRoot.CFrame = CFrame.new(-200, 250, 0)
                            TargetRoot.Anchored = true
                            TargetRoot.AssemblyLinearVelocity = Vector3.zero
                            Data['FlameFrozenTarget'] = Target
                        end
                    end
                    if Tool.Parent ~= MyCharacter then
                        equip(Tool)
                    end
                    if Tool.Parent ~= MyCharacter then
                        didAction = true
                        break
                    end
                    local res = getgunreserve(Tool)
                    local ammo = Tool:FindFirstChild('Ammo')
                    if ammo and ammo.Value <= 0 then
                        Data.CurrentActionTarget = Target
                        if res ~= nil and res <= 0 and not Data['Buying'] then
                            local count = Options.ammo_buy_count and Options.ammo_buy_count.Value or 5
                            phowg:queue_ragebot_purchase(ammoshopname(Tool.Name), Data['PRIO'].AMMO, count, Target)
                        else
                            preparevoidreload(Tool)
                        end
                        Data.RagebotArrival = nil
                        phowg:stop_gun_fire('Ragebot')
                        didAction = true
                        break
                    end
                    if GunMode == 'flamethrower' then
                        if Data['FlameWallT'] == Target and tick() - (Data['FlameWallAt'] or 0) < 1 then
                            local myHrp = MyCharacter:FindFirstChild('HumanoidRootPart')
                            if myHrp then
                                local ov = myHrp.AssemblyLinearVelocity
                                if ov.Magnitude > 1000 then
                                    ov = Vector3.zero
                                end
                                myHrp.Velocity = Vector3.new(0, -9e9, 0)
                                myHrp.AssemblyLinearVelocity = Vector3.new(0, -9e9, 0)
                                RunService.RenderStepped:Once(function()
                                    if myHrp.Parent and LocalPlayer.Character == MyCharacter then
                                        myHrp.Velocity = ov
                                        myHrp.AssemblyLinearVelocity = ov
                                    end
                                end)
                            end
                            didAction = true
                            break
                        end
                        local stuckCount = 0
                        local stdirs = {
                            Vector3.new(6, 0, 0),
                            Vector3.new(-6, 0, 0),
                            Vector3.new(0, 6, 0),
                            Vector3.new(0, -6, 0),
                            Vector3.new(0, 0, 6),
                            Vector3.new(0, 0, -6),
                        }
                        for _, sd in ipairs(stdirs) do
                            local swp = RaycastParams.new()
                            swp.FilterType = Enum.RaycastFilterType.Exclude
                            swp.FilterDescendantsInstances = { MyCharacter, Target.Character }
                            swp.RespectCanCollide = true
                            swp.IgnoreWater = true
                            if Workspace:Raycast(TargetRoot.Position + sd, -sd, swp) then
                                stuckCount = stuckCount + 1
                            end
                        end
                        if stuckCount >= 5 then
                            TargetRoot.Anchored = false
                            Data['FlameFrozenTarget'] = nil
                            set_server_cframe(TargetRoot.Position, nil, Data['PRIO'].KNIFE, 'Combat')
                            if Data['FlameWallT'] == Target and tick() - (Data['FlameWallAt'] or 0) >= 1 then
                                Data['FlameUntargetable'] = Data['FlameUntargetable'] or {}
                                Data['FlameUntargetable'][Target] = true
                                Data['FlameWallT'] = nil
                                didAction = true
                                break
                            end
                            Data['FlameWallT'] = Target
                            Data['FlameWallAt'] = tick()
                            didAction = true
                            break
                        elseif Data['FlameWallT'] == Target then
                            Data['FlameWallT'] = nil
                        end
                    end
                    Data['RifleTarget'] = Target
                    Data['CurrentStatus'] = 'ragebot: shooting ' .. Target.DisplayName .. ' | ' .. Target.Name
                    Data['CurrentActionTarget'] = Target
                    Data['CombatActAt'] = tick()
                    releasefrozenexcept(Target)
                    if GunMode ~= 'flamethrower' and isreloading() then
                        Data['CurrentStatus'] = 'ragebot: reloading'
                        if reloadvoidactive() then
                            set_server_cframe(getvoidcframe(), nil, Data['PRIO'].IDLE, 'ReloadVoid')
                        end
                        didAction = true
                        break
                    end
                    local strafeType = Options.target_strafe_mode and Options.target_strafe_mode.Value or 'orbit'
                    local supportMode = Data['PunishmentTargets'] and Data['PunishmentTargets'][Target]
                    if
                        (Data['SupportCompletedTargets'] and Data['SupportCompletedTargets'][Target])
                        or (supportMode and supporttargetfinished(Target, supportMode))
                    then
                        if supportMode then
                            punishmentcleartarget(Target, nil, true)
                        end
                        phowg:stop_gun_fire('Ragebot')
                        didAction = true
                        break
                    end
                    local continuousChina = phowg:gun_shoot_method('Ragebot', Target) == 'china hack'
                        and phowg:china_target_valid(Target)
                    if continuousChina then
                        gunFireRequested = phowg:fire_gun('Ragebot', Tool, Target, 0)
                    end
                    if phowg:ragebot_void_phase(Target) then
                        set_server_cframe(
                            getvoidcframe(),
                            nil,
                            (punishmentactive() and Data.PRIO.PUNISH or Data.PRIO.KNIFE),
                            'RagebotVoid'
                        )
                        didAction = true
                        break
                    end
                    local strafeCF = phowg:ragebot_bait_c_frame(Target, Tool)
                    if strafeCF then
                        strafeType = 'bait'
                    else
                        strafeCF = phowg:teleport_camp_c_frame(Target, Tool)
                        if strafeCF then
                            strafeType = 'teleport camp'
                        else
                            strafeCF = getgunstrafecframe(Target, Tool, strafeType)
                        end
                    end
                    if not strafeCF then
                        Data.CurrentStatus = continuousChina and 'ragebot: killing'
                            or 'ragebot: finding a strafe position'
                        if not continuousChina then
                            phowg:stop_gun_fire('Ragebot')
                        end
                        didAction = true
                        break
                    end
                    local targetCharacter = Target.Character
                    local intent = Data.RagebotMoveIntent
                    if
                        not intent
                        or intent.Target ~= Target
                        or intent.Tool ~= Tool
                        or intent.Mode ~= strafeType
                        or intent.Character ~= targetCharacter
                        or intent.LocalCharacter ~= MyCharacter
                    then
                        intent = {
                            Target = Target,
                            Tool = Tool,
                            Mode = strafeType,
                            Character = targetCharacter,
                            LocalCharacter = MyCharacter,
                        }
                        Data.RagebotMoveIntent = intent
                    end
                    local onArrive = function(root)
                        if
                            Data.RagebotMoveIntent ~= intent
                            or Data.CurrentActionTarget ~= Target
                            or Target.Character ~= targetCharacter
                            or not (rageboton() or punishmentactive())
                        then
                            return
                        end
                        if phowg:record_ragebot_arrival(Target, Tool, strafeType, root) then
                            if phowg:fire_gun('Ragebot', Tool, Target, 0) then
                                Data.RagebotArrivalFireAt, Data.RagebotArrivalFireTarget = tick(), Target
                            end
                        elseif not continuousChina then
                            phowg:stop_gun_fire('Ragebot')
                        end
                    end
                    set_server_cframe(
                        strafeCF,
                        nil,
                        (punishmentactive() and Data['PRIO'].PUNISH or Data['PRIO'].KNIFE),
                        'Combat',
                        false,
                        nil,
                        onArrive
                    )
                    if Data['GunAimTarget'] ~= Target then
                        Data['GunAimTarget'] = Target
                        Data['GunAimAt'] = tick()
                    end
                    local arrived = phowg:ragebot_arrived(Target, Tool, strafeType)
                    if (arrived or continuousChina) and not Data['RPGMoveActive'] and not isreloading() then
                        gunFireRequested = phowg:fire_gun('Ragebot', Tool, Target, 0)
                    else
                        Data.CurrentStatus = 'ragebot: killing'
                        phowg:stop_gun_fire('Ragebot')
                    end
                end
            end
            didAction = true
            break
        end
    end
    return didAction, gunFireRequested
end
function phowg:ragebot_melee_action(Targets, GunMode)
    if GunMode ~= 'knife' and GunMode ~= 'combat' then
        phowg:clear_melee_replication_root()
        return false
    end
    local didAction = false
    for _, Target in ipairs(Targets) do
        if
            intelligence:get_character_cache(Target)
            and not isknocked(Target)
            and not isdead(Target)
            and not Target.Character:FindFirstChildOfClass('ForceField')
            and phowg:smart_attack_ready(Target, 'Ragebot')
        then
            local tch = Target.Character
            local seen = Data['KillCharSeen'] and Data['KillCharSeen'][Target] or nil
            if not seen or seen.char ~= tch then
                if Data['KillCharSeen'] == nil then
                    Data['KillCharSeen'] = {}
                end
                local scount = 0
                for _ in pairs(Data['KillCharSeen']) do
                    scount = scount + 1
                end
                if scount > 50 then
                    Data['KillCharSeen'] = {}
                end
                Data['KillCharSeen'][Target] = { char = tch, at = tick() }
                Data['CurrentActionTarget'] = Target
                didAction = true
                break
            elseif tick() - seen.at < 0.1 then
                Data['CurrentActionTarget'] = Target
                didAction = true
                break
            end
            local WeaponType = GunMode
            local Tool = getweapontool(WeaponType)
            if not Tool then
                phowg:clear_melee_replication_root()
                Data.CurrentActionTarget = Target
                if WeaponType == 'knife' and not Data.Buying then
                    phowg:queue_ragebot_purchase('knife', Data.PRIO.KNIFE, nil, Target)
                elseif WeaponType == 'combat' then
                    Data.CurrentStatus = 'ragebot: waiting for combat'
                end
                didAction = true
                break
            end
            if Tool then
                local MyCharacter = LocalPlayer.Character
                local TargetRoot = Target.Character:FindFirstChild('HumanoidRootPart')
                if MyCharacter and getreppart(MyCharacter) and TargetRoot then
                    Data['CurrentStatus'] = 'ragebot: killing ' .. Target.DisplayName .. ' | ' .. Target.Name
                    Data['CurrentActionTarget'] = Target
                    Data['CombatActAt'] = tick()
                    if phowg:ragebot_void_phase(Target) then
                        phowg:clear_melee_replication_root()
                        phowg:deactivate_tool(Tool)
                        set_server_cframe(
                            getvoidcframe(),
                            nil,
                            (punishmentactive() and Data.PRIO.PUNISH or Data.PRIO.KNIFE),
                            'RagebotVoid'
                        )
                        didAction = true
                        break
                    end
                    if Tool.Parent ~= MyCharacter then
                        local pending = Data.MeleeEquipRequest
                        local now = tick()
                        if not pending or pending.Tool ~= Tool or pending.Character ~= MyCharacter or now >= pending.RetryAt then
                            Data.MeleeEquipRequest = { Tool = Tool, Character = MyCharacter, RetryAt = now + 1 }
                            equip(Tool)
                        end
                        if Tool.Parent ~= MyCharacter then
                            didAction = true
                            break
                        end
                    end
                    local Torso = getreppart(Target.Character) or TargetRoot
                    if Data.ChineseHolding then
                        phowg:cancel_chinese_strafe()
                    end
                    if not phowg:bind_melee_replication_root(getreppart(MyCharacter), Torso, Target) then
                        phowg:deactivate_tool(Tool)
                        didAction = true
                        break
                    end
                    Data.StickyRepTarget = Torso
                    set_server_cframe(
                        TargetRoot.CFrame * CFrame.new(0, 0, 2),
                        nil,
                        (punishmentactive() and Data.PRIO.PUNISH or Data.PRIO.KNIFE),
                        'Combat'
                    )
                    releasefrozenexcept(Target)
                    local melee = Data.MeleeReplicationRoot
                    if melee and melee.Target == Target then
                        phowg:sync_melee_freeze(melee, TargetRoot, freezetargetenabled())
                    end
                    if Tool.Parent == MyCharacter then
                        local rapid = WeaponType == 'combat' or Data.Settings.Rapid == true
                        if rapid then
                            phowg:clear_melee_charge()
                            if not localactionblocked() then
                                Tool:Activate()
                            end
                            phowg:deactivate_tool(Tool)
                            Data.RecentlyShotAt = tick()
                        elseif phowg:update_melee_knife_charge(Tool, Target) then
                            Data.RecentlyShotAt = tick()
                        end
                    end
                end
                didAction = true
                break
            end
        end
    end
    if not didAction then
        phowg:clear_melee_replication_root()
    end
    return didAction
end
function phowg:ragebot_carrier_allowed(player)
    return player
        and player ~= LocalPlayer
        and player.Parent
        and player.Character
        and not iswhitelistedplayer(player)
        and not iscrewwhitelisted(player)
        and not (Data.RageWhitelist and Data.RageWhitelist[player])
        and not (Data.FullWhitelist and Data.FullWhitelist[player])
end
function phowg:target_carrier(target)
    local character = target and target.Character
    local constraint = character and character:FindFirstChild('GRABBING_CONSTRAINT')
    if not constraint then
        return nil
    end
    for _, player in ipairs(Players:GetPlayers()) do
        local body = player.Character and player.Character:FindFirstChild('BodyEffects')
        if player ~= target and body then
            for _, name in ipairs({ 'Grabbed', 'Grabbing' }) do
                local reference = body:FindFirstChild(name)
                if
                    reference
                    and reference:IsA('ObjectValue')
                    and (reference.Value == character or reference.Value == target)
                then
                    return player
                end
            end
        end
    end
    local joints = { constraint }
    for _, object in ipairs(constraint:GetDescendants()) do
        joints[#joints + 1] = object
    end
    for _, joint in ipairs(joints) do
        if joint:IsA('JointInstance') or joint:IsA('WeldConstraint') then
            for _, part in pairs({ joint.Part0, joint.Part1 }) do
                local current = part
                while current and current ~= Workspace do
                    if current:IsA('Model') then
                        local player = Players:GetPlayerFromCharacter(current)
                        if player and player ~= target then
                            return player
                        end
                    end
                    current = current.Parent
                end
            end
        end
    end
    return nil
end
function phowg:ragebot_targets(targets)
    targets = targets or gettargetlist()
    if phowg:target_search_active() then
        Data.RagebotCarriers = nil
        return phowg:target_search_engaged() and { Data.TargetSearch.Target } or {}
    end
    if phowg:auto_bounty_enabled() and not Data.PunishmentGunActive then
        Data.RagebotCarriers = nil
        return targets
    end
    if not rageboton() or Data.PunishmentGunActive then
        Data.RagebotCarriers = nil
        return targets
    end
    local tracking = Data.RagebotCarriers or {}
    Data.RagebotCarriers = tracking
    local selected, seen, carriers, remaining = {}, {}, {}, {}
    local finishKnocked = phowg:ragebot_action_enabled('auto_stomp') or Data.Settings.Stomp
    for _, target in ipairs(targets) do
        selected[target] = true
        local character = target.Character
        local entry = tracking[target]
        if
            entry
            and (
                entry.Character ~= character
                or not phowg:ragebot_carrier_allowed(entry.Carrier)
                or entry.Carrier.Character ~= entry.CarrierCharacter
                or isdead(entry.Carrier)
                or isknocked(entry.Carrier) and not finishKnocked
            )
        then
            tracking[target] = nil
            entry = nil
        end
        if not character or isdead(target) then
            tracking[target] = nil
            continue
        end
        local carried = character:FindFirstChild('GRABBING_CONSTRAINT') ~= nil
        if carried then
            local carrier = phowg:target_carrier(target)
            if
                phowg:ragebot_carrier_allowed(carrier)
                and not isdead(carrier)
                and (finishKnocked or not isknocked(carrier))
            then
                if not entry or entry.Carrier ~= carrier or entry.CarrierCharacter ~= carrier.Character then
                    entry = { Character = character, Carrier = carrier, CarrierCharacter = carrier.Character }
                    tracking[target] = entry
                end
            elseif carrier and not phowg:ragebot_carrier_allowed(carrier) then
                tracking[target] = nil
                entry = nil
            end
        end
        if entry then
            if not seen[entry.Carrier] then
                seen[entry.Carrier] = true
                carriers[#carriers + 1] = entry.Carrier
            end
        elseif not carried and not seen[target] then
            seen[target] = true
            remaining[#remaining + 1] = target
        end
    end
    for target in pairs(tracking) do
        if not selected[target] then
            tracking[target] = nil
        end
    end
    if #carriers > 0 then
        return carriers
    end
    return remaining
end
function phowg:ragebot_has_shootable_target(targets)
    local mode = phowg:auto_kill_gun_mode()
    for _, target in ipairs(targets or phowg:ragebot_targets()) do
        if isgunshootable(target, mode) then
            return true
        end
    end
    return false
end
function phowg:ragebot_weapons_paused(tool)
    if
        Data.PunishmentGunActive
        or not rageboton()
        or not phowg:ragebot_action_enabled('auto_kill')
        or not phowg:is_ragebot_gun_selected(tool)
    then
        return false
    end
    return not phowg:ragebot_has_shootable_target()
end
function phowg:suspend_ragebot_weapons()
    phowg:stop_gun_fire('Ragebot')
    phowg:china_release_extra()
    phowg:cancel_backpack_reload()
    local character = LocalPlayer.Character
    local pack = LocalPlayer:FindFirstChild('Backpack')
    if character and pack then
        for _, tool in ipairs(character:GetChildren()) do
            if tool:IsA('Tool') and phowg:is_ragebot_gun_selected(tool) then
                phowg:deactivate_tool(tool)
                if tool.Parent == character then
                    tool.Parent = pack
                end
            end
        end
    end
end
phowg:register_cleanup('ragebot carriers', function(scope, reason)
    if not scope or reason == 'unload' or scope == LocalPlayer.Character then
        Data.RagebotCarriers = nil
    end
end)
function phowg:ragebot_idle_valid(state)
    return state ~= nil
        and Data.RagebotIdle == state
        and state.Character == LocalPlayer.Character
        and not Library.Unloaded
        and not Data.SharedSignalsClosed
        and not Data.IsRespawning
        and not Data.PunishmentGunActive
        and not Data.Buying
        and not Data.MaskBuying
        and rageboton()
        and phowg:ragebot_action_enabled('auto_kill')
        and not localactionblocked()
end
function phowg:ragebot_idle_hiding(state)
    return Data.Settings.Hide == true and phowg:ragebot_idle_valid(state)
end
function phowg:clear_ragebot_idle()
    local state = Data.RagebotIdle
    if not state then
        return
    end
    Data.RagebotIdle = nil
    releasemovement('RagebotIdle')
    for index = #(Data.CSync and Data.CSync.Queue or {}), 1, -1 do
        if Data.CSync.Queue[index].tag == 'RagebotIdle' then
            table.remove(Data.CSync.Queue, index)
        end
    end
    local pack = LocalPlayer:FindFirstChild('Backpack')
    if state.Character == LocalPlayer.Character and pack then
        for tool in pairs(state.Equipped) do
            if tool.Parent == state.Character then
                tool.Parent = pack
            end
        end
    end
    if Data.AppliedServerTag == 'RagebotIdle' and Data.AppliedServerCharacter == state.Character then
        Data.AppliedServerCF, Data.AppliedServerAt, Data.AppliedServerTag, Data.AppliedServerCharacter =
            nil, nil, nil, nil
        Data.MoveToActive, Data.MoveToTargetCF = false, nil
        hidevisualizer()
    end
end
function phowg:ragebot_idle_reload(state)
    if not phowg:ragebot_idle_valid(state) or Data.Buying or Data.Sorting or Data.LoadoutReloadJob then
        return false
    end
    local now = tick()
    local pack = LocalPlayer:FindFirstChild('Backpack')
    if not pack then
        return false
    end
    local job = state.Reload
    if job then
        local ammo = job.Tool:FindFirstChild('Ammo')
        local active = phowg:local_gun_reloading(state.Character) or phowg:reload_pending(state.Character)
        if active then
            job.Started = true
        end
        if
            job.Tool.Parent ~= state.Character
            or not ammo
            or now >= job.Deadline
            or not active and (job.Started or ammo.Value > job.Before)
        then
            state.Reload = nil
            if job.Tool.Parent == state.Character then
                job.Tool.Parent = pack
            end
            state.Equipped[job.Tool] = nil
            state.RetryAt[job.Name] = now + 0.75
        end
        return false
    end
    if phowg:local_gun_reloading(state.Character) or Data.GunReloadSelection or phowg:reload_pending(state.Character) then
        return false
    end
    for _, name in ipairs(phowg:ragebot_gun_names()) do
        local tool = getweapontool(name)
        if not tool then
            Data.CurrentStatus = 'ragebot: preparing / buying ' .. name
            phowg:queue_ragebot_purchase(name, Data.PRIO.KNIFE, nil, nil, state)
            return false
        end
        local ammo = tool:FindFirstChild('Ammo')
        local maximum = tool:FindFirstChild('MaxAmmo')
        local capacity = tonumber(maximum and maximum.Value or tool:GetAttribute('MaxAmmo'))
        local reserve = getgunreserve(tool)
        if
            ammo
            and type(ammo.Value) == 'number'
            and (capacity and capacity > 0 and ammo.Value < capacity or not capacity and ammo.Value <= 0)
        then
            if now < (state.RetryAt[name] or 0) then
                return false
            end
            if reserve ~= nil and reserve <= 0 then
                Data.CurrentStatus = 'ragebot: preparing / buying ammo for ' .. name
                phowg:queue_ragebot_purchase(
                    ammoshopname(tool.Name),
                    Data.PRIO.AMMO,
                    Options.ammo_buy_count and Options.ammo_buy_count.Value or 5,
                    nil,
                    state
                )
                return false
            end
            local remote = MainEvent or ReplicatedStorage:FindFirstChild('MainEvent')
            local before = ammo.Value
            state.Equipped[tool] = true
            if phowg:request_gun_reload(tool, remote, nil, state) then
                state.Reload = { Tool = tool, Name = name, Before = before, Started = false, Deadline = now + 8 }
                Data.CurrentStatus = 'ragebot: preparing / reloading ' .. name
            else
                if tool.Parent == state.Character then
                    tool.Parent = pack
                end
                state.Equipped[tool] = nil
                state.RetryAt[name] = now + 0.75
            end
            return false
        end
    end
    Data.CurrentStatus = Data.Settings.Hide and 'ragebot: idle in void / selected guns ready'
        or 'ragebot: waiting / selected guns ready'
    return true
end
function phowg:ragebot_idle_step()
    if
        not rageboton()
        or not phowg:ragebot_action_enabled('auto_kill')
        or punishmentactive()
        or Library.Unloaded
        or Data.IsRespawning
        or localactionblocked()
        or not getroot(LocalPlayer.Character)
    then
        phowg:clear_ragebot_idle()
        return false
    end
    if Data.Buying or Data.MaskBuying then
        return false
    end
    local mode = phowg:auto_kill_gun_mode()
    if not phowg:is_gun_weapon(mode) then
        phowg:clear_ragebot_idle()
        return false
    end
    local targets = phowg:ragebot_targets()
    local stompTarget, actionable
    for _, target in ipairs(targets) do
        if
            isgunshootable(target, mode) and target.Character:FindFirstChild('Head')
            or Toggles.auto_arrest and Toggles.auto_arrest.Value and isvalidarresttarget(target)
        then
            actionable = true
        end
        if
            (phowg:ragebot_action_enabled('auto_stomp') or Data.Settings.Stomp)
            and stompallowed(targets)
            and isvalidstomptarget(target)
        then
            stompTarget = stompTarget or target
        end
    end
    if
        (stompTarget and not (Toggles.ragebot_reload_before_stomp and Toggles.ragebot_reload_before_stomp.Value))
        or not stompTarget and actionable
    then
        phowg:clear_ragebot_idle()
        return false
    end
    local state = Data.RagebotIdle
    if state and state.Character ~= LocalPlayer.Character then
        phowg:clear_ragebot_idle()
        state = nil
    end
    if not state then
        phowg:clear_ragebot_void_spam()
        phowg:suspend_ragebot_weapons()
        state = {
            Character = LocalPlayer.Character,
            Equipped = {},
            RetryAt = {},
            Reload = nil :: any,
            MoveAt = -math.huge,
            StartedAt = tick(),
        }
        Data.RagebotIdle = state
        local pack = LocalPlayer:FindFirstChild('Backpack')
        if pack then
            for _, tool in ipairs(state.Character:GetChildren()) do
                if tool:IsA('Tool') and phowg:is_ragebot_gun_selected(tool) then
                    tool.Parent = pack
                end
            end
        end
        for _, tag in ipairs({ 'Combat', 'TargetStrafe', 'ReloadVoid' }) do
            releasemovement(tag)
        end
        for index = #Data.CSync.Queue, 1, -1 do
            local tag = Data.CSync.Queue[index].tag
            if tag == 'Combat' or tag == 'TargetStrafe' or tag == 'ReloadVoid' then
                table.remove(Data.CSync.Queue, index)
            end
        end
    end
    if stompTarget then
        if state.StompCharacter ~= stompTarget.Character then
            state.StompCharacter = stompTarget.Character
            state.StompStartedAt = tick()
        end
        if tick() - (state.StompStartedAt or state.StartedAt) >= 12 then
            phowg:clear_ragebot_idle()
            return false
        end
    else
        state.StompCharacter, state.StompStartedAt = nil, nil
    end
    Data.CurrentActionTarget, Data.StickyRepTarget = nil, nil
    Data.CurrentStatus = Data.Settings.Hide and 'ragebot: idle in void' or 'ragebot: waiting'
    releasefrozenexcept(nil)
    if phowg:ragebot_idle_hiding(state) and tick() - state.MoveAt >= 0.05 then
        state.MoveAt = tick()
        set_server_cframe(getvoidcframe(), nil, Data.PRIO.KNIFE, 'RagebotIdle')
    end
    local ready = phowg:ragebot_idle_reload(state)
    if stompTarget and ready then
        phowg:clear_ragebot_idle()
        return false
    end
    return true
end
phowg:register_cleanup('ragebot idle', function(scope, reason)
    local state = Data.RagebotIdle
    if state and (not scope or reason == 'unload' or scope == state.Character) then
        phowg:clear_ragebot_idle()
    end
end)
function phowg:ragebot_step()
    if Library.ConfigLoading then
        phowg:clear_ragebot_idle()
        return false
    end
    local pair = Data.ChinaHackState
    if pair and pair.MultiTarget and not phowg:china_target_valid(pair.MultiTarget) then
        phowg:china_release_extra()
    end
    local gunFireRequested = false
    checkstompwatch()
    if phowg:ragebot_idle_step() then
        return false
    end
    local completedTarget = Data.CurrentActionTarget or Data.CurrentMainTarget or Data.SingleLockedTarget
    if completedTarget and isstomped(completedTarget) then
        phowg:hide_after_stomp(completedTarget)
    end
    for player, mode in pairs(Data['PunishmentTargets'] or {}) do
        if supporttargetfinished(player, mode) then
            punishmentcleartarget(player, nil, true)
        end
    end
    if
        not (rageboton() or punishmentactive())
        or not (
            phowg:ragebot_action_enabled('auto_kill')
            or phowg:ragebot_action_enabled('auto_stomp')
            or (Toggles.auto_arrest and Toggles.auto_arrest.Value)
        )
    then
        Data['CurrentStatus'] = 'Idle'
        Data['CurrentActionTarget'] = nil
        Data['StickyRepTarget'] = nil
        syncvisualizer()
        if not Data['Flinging'] then
            if Data['FrozenRoots'] then
                for P, R in pairs(Data['FrozenRoots']) do
                    if R and R.Parent then
                        R.Anchored = false
                    end
                    Data['FrozenRoots'][P] = nil
                end
            end
        end
    elseif localactionblocked() or not getroot(LocalPlayer.Character) then
        Data.CurrentStatus = Data.IsRespawning and 'ragebot: respawning'
            or 'ragebot: local character unavailable or knocked'
    elseif isreloading() or reloadvoidactive() then
        Data['CurrentStatus'] = 'ragebot: reloading'
        Data['CombatArrivalAt'] = nil
        Data['CombatArrivalLastAt'] = nil
        releasefrozenexcept(nil)
        for index = #Data['CSync'].Queue, 1, -1 do
            local queued = Data['CSync'].Queue[index]
            if queued.tag == 'Combat' then
                table.remove(Data['CSync'].Queue, index)
            end
        end
        if reloadvoidactive() then
            set_server_cframe(getvoidcframe(), nil, Data['PRIO'].PUNISH, 'ReloadVoid')
        end
    elseif Data['Buying'] then
        Data.CurrentStatus = 'ragebot: buying supplies'
        if Data.BuyingArmor and phowg:ragebot_action_enabled('auto_kill') and not localshootblocked() then
            local mode = phowg:auto_kill_gun_mode()
            if phowg:is_gun_weapon(mode) then
                local target = pickguntarget(phowg:ragebot_targets(), mode)
                local tool = target and getweapontool(mode)
                if tool then
                    if tool.Parent ~= LocalPlayer.Character then
                        equip(tool)
                    end
                    Data.CurrentActionTarget, Data.CombatActAt = target, tick()
                    if Data.GunAimTarget ~= target then
                        Data.GunAimTarget, Data.GunAimAt = target, tick()
                    end
                    gunFireRequested = phowg:fire_gun('Ragebot', tool, target, 0)
                end
            end
        end
    elseif Data['MaskBuying'] then
        Data.CurrentStatus = 'ragebot: buying mask'
    else
        for index = #Data['CSync'].Queue, 1, -1 do
            if Data['CSync'].Queue[index].tag == 'ReloadVoid' then
                table.remove(Data['CSync'].Queue, index)
            end
        end
        Data['StickyRepTarget'] = nil
        local Targets = phowg:ragebot_targets()
        do
            local jt = Data['CurrentMainTarget'] or Data['CurrentActionTarget'] or Data['SingleLockedTarget']
            if jt and jt.Parent and jt ~= LocalPlayer then
                local okj, dcj = pcall(function()
                    return intelligence:get_data_cache(jt)
                end)
                if okj and dcj and dcj.Jailed == true then
                    Data['RageJailedNotified'] = Data['RageJailedNotified'] or {}
                    local lastJ = Data['RageJailedNotified'][jt] or 0
                    if tick() - lastJ > 5 then
                        Data['RageJailedNotified'][jt] = tick()
                        pcall(function()
                            Library:Notify(
                                'target ' .. tostring(jt.DisplayName) .. ' @' .. tostring(jt.Name) .. ' has been jailed',
                                3
                            )
                        end)
                    end
                end
            end
        end
        local didAction = false
        if Data['FrozenRoots'] then
            for P, R in pairs(Data['FrozenRoots']) do
                if
                    not (P and P.Parent)
                    or isdead(P)
                    or (
                        isknocked(P)
                        and not (Data['StompWatch'] and Data['StompWatch'][P])
                        and not (Data['ArrestWatch'] and Data['ArrestWatch'][P])
                    )
                then
                    if R and R.Parent then
                        R.Anchored = false
                    end
                    Data['FrozenRoots'][P] = nil
                end
            end
        end
        if
            not didAction
            and (phowg:ragebot_action_enabled('auto_stomp') or (phowg:ragebot_action_enabled('auto_kill') and Data['Settings'].Stomp))
            and stompallowed(Targets)
        then
            for _, Target in ipairs(Targets) do
                if isvalidstomptarget(Target) then
                    performstomp(Target)
                    notifystomping(Target)
                    Data['StompWatch'][Target] = true
                    releasefrozenexcept(Target)
                    Data['RifleTarget'] = nil
                    Data['GunFocusTarget'] = nil
                    Data['GunFocusAt'] = nil
                    didAction = true
                    break
                end
            end
            checkstompwatch()
        end
        if not didAction and Toggles.auto_arrest and Toggles.auto_arrest.Value then
            for _, Target in ipairs(Targets) do
                if isvalidarresttarget(Target) then
                    performarrest(Target)
                    notifyarresting(Target)
                    Data['ArrestWatch'] = Data['ArrestWatch'] or {}
                    Data['ArrestWatch'][Target] = true
                    releasefrozenexcept(Target)
                    didAction = true
                    break
                end
            end
            checkarrestwatch()
        end
        local GunMode = phowg:auto_kill_gun_mode()
        local IsGun = phowg:is_gun_weapon(GunMode)
        if not didAction and phowg:ragebot_action_enabled('auto_kill') and IsGun then
            didAction, gunFireRequested = phowg:ragebot_gun_action(Targets, GunMode)
        end
        if not didAction and not IsGun and phowg:ragebot_action_enabled('auto_kill') then
            didAction = phowg:ragebot_melee_action(Targets, GunMode)
        end
        if phowg:ragebot_action_enabled('auto_kill') and IsGun then
            if Data['RifleVoid'] then
                local rt = Data['RifleVoidTarget']
                local rc = rt and rt.Parent and rt.Character or nil
                if rt == nil or not rt.Parent then
                    phowg:clear_rifle_void()
                else
                    local rff = rc and rc:FindFirstChildOfClass('ForceField') or nil
                    if rff then
                        Data['RifleVoidFF'] = true
                    elseif rc and not isknocked(rt) and not isdead(rt) then
                        phowg:clear_rifle_void()
                    elseif Data['RifleVoidFF'] then
                        phowg:clear_rifle_void()
                        if Data['CurrentStatus'] == 'ragebot: voiding' then
                            Data['CurrentStatus'] = 'Idle'
                        end
                    elseif not rc then
                        phowg:clear_rifle_void()
                    end
                end
            else
                local rkt = Data['RifleTarget']
                if rkt ~= nil then
                    local gone = not rkt.Parent
                    local dead = not gone and isdead(rkt)
                    local knocked = not gone and not dead and isknocked(rkt)
                    if
                        Data.Settings.Hide
                        and not didAction
                        and phowg:ragebot_action_enabled('auto_stomp')
                        and (gone or dead or (knocked and isvalidstomptarget(rkt)))
                    then
                        Data['RifleVoid'] = true
                        Data['RifleVoidFF'] = false
                        Data['RifleVoidWait'] = true
                        Data['RifleVoidTarget'] = rkt
                        if not Data['VoidActive'] then
                            Data['VoidActive'] = true
                            phowg:start_loop('VoidHide', voidhideloop)
                        end
                    elseif Data['Settings'] and Data['Settings'].Hide and knocked then
                        Data['RifleVoid'] = true
                        Data['RifleVoidFF'] = false
                        Data['RifleVoidWait'] = nil
                        Data['RifleVoidTarget'] = rkt
                        if not Data['VoidActive'] then
                            Data['VoidActive'] = true
                            phowg:start_loop('VoidHide', voidhideloop)
                        end
                    else
                        Data['RifleTarget'] = nil
                    end
                end
            end
        elseif Data['RifleVoid'] then
            phowg:clear_rifle_void()
        end
        if Data['FlameFrozenTarget'] ~= nil then
            local fm = Data['FlameFrozenTarget']
            local fch = fm and fm.Parent and fm.Character or nil
            local stillFlaming = phowg:ragebot_action_enabled('auto_kill')
                and IsGun
                and GunMode == 'flamethrower'
                and fch
                and not isdead(fm)
                and not isknocked(fm)
            if not stillFlaming then
                local holdStomp = fch and phowg:ragebot_action_enabled('auto_stomp') and isvalidstomptarget(fm)
                if not holdStomp then
                    local frt = fch and fch:FindFirstChild('HumanoidRootPart') or nil
                    if frt and frt.Parent then
                        frt.Anchored = false
                    end
                    if Data['FrozenRoots'] then
                        Data['FrozenRoots'][fm] = nil
                    end
                    Data['FlameFrozenTarget'] = nil
                end
            end
        end
        if not didAction then
            if not Data['HideVoid'] then
                Data.CurrentStatus = #Targets == 0 and 'ragebot: no eligible targets'
                    or 'ragebot: target knocked, protected or unavailable'
                Data['CurrentActionTarget'] = nil
                syncvisualizer()
            end
            if not Data['Flinging'] then
                if Data['FrozenRoots'] then
                    for P, R in pairs(Data['FrozenRoots']) do
                        if R and R.Parent then
                            R.Anchored = false
                        end
                        Data['FrozenRoots'][P] = nil
                    end
                end
            end
            if Data['Settings'].Hide and (rageboton() or Data['Settings'].SafeIdle or Data['VoidActive']) then
                set_server_cframe(getvoidcframe(), nil, Data['PRIO'].IDLE, 'Combat')
            end
        end
    end
    return gunFireRequested
end
function ragebot_on()
    if phowg.sync_target_data_observers then
        phowg:sync_target_data_observers()
    end
    phowg:queue_ragebot_tool_prune(LocalPlayer.Character)
    if Library.Unloaded or Data.SharedSignalsClosed or Data.RagebotConn and Data.RagebotConn.Connected then
        return
    end
    local runtime: { [string]: any } = { Busy = false, Closed = false }
    Data.RagebotRuntime = runtime
    Data.RagebotConn = connectshared(RunService.Heartbeat, function()
        if
            runtime.Closed
            or Data.RagebotRuntime ~= runtime
            or runtime.Busy
            or Library.Unloaded
            or Data.SharedSignalsClosed
        then
            return
        end
        runtime.Busy = true
        Data.RagebotTicking, Data.RagebotTickCharacter, Data.RagebotTickStartAt = true, LocalPlayer.Character, tick()
        local ok, requested = pcall(function()
            local spam = Data.RagebotVoidSpam
            if
                spam
                and (
                    not rageboton()
                    or Data.Buying
                    or Data.MaskBuying
                    or Data.IsRespawning
                    or isreloading()
                    or localactionblocked()
                    or tick() - spam.LastAt > 0.25
                )
            then
                phowg:clear_ragebot_void_spam()
            end
            return phowg:ragebot_step()
        end)
        runtime.Busy = false
        if runtime.Closed or Data.RagebotRuntime ~= runtime then
            return
        end
        Data.RagebotTicking = false
        local arrivalFire = Data.HeldGunFire
            and Data.HeldGunFire.Owner == 'Ragebot'
            and Data.HeldGunFire.Target == Data.CurrentActionTarget
            and Data.RagebotArrivalFireTarget == Data.CurrentActionTarget
            and tick() - (Data.RagebotArrivalFireAt or -math.huge) < 0.12
        if not ok or not requested and not arrivalFire then
            phowg:stop_gun_fire('Ragebot')
        end
        if not ok then
            Data.RagebotArrival = nil
            phowg:clear_ragebot_void_spam()
            Data.RagebotLastError, Data.RagebotTickErrAt = tostring(requested), tick()
            if tick() - (Data.RagebotErrorWarnAt or -math.huge) >= 5 then
                Data.RagebotErrorWarnAt = tick()
                warn('[Phowg] ragebot: ' .. Data.RagebotLastError)
                pcall(Library.Notify, Library, 'Ragebot error: ' .. Data.RagebotLastError:sub(1, 240), 5)
            end
        end
    end, RunService, 'frame/ragebot', 0, 'event/Heartbeat', RunService)
end
function prime_session_moveto(tag)
    if Data['CSync'] and Data['CSync'].Queue then
        for i = #Data['CSync'].Queue, 1, -1 do
            if Data['CSync'].Queue[i].tag == tag then
                table.remove(Data['CSync'].Queue, i)
            end
        end
    end
    if Data['Buying'] and tick() - (Data['BuyingSince'] or 0) > 8 then
        Data['Buying'] = false
    end
end
function undergroundloop()
    while Data['UndergroundActive'] do
        if localactionblocked() then
            task.wait(0.05)
            continue
        end
        if movementblocked(Data['PRIO'].IDLE, 'Underground') then
            RunService.Heartbeat:Wait()
            continue
        end
        if Data['VoidActive'] then
            RunService.Heartbeat:Wait()
        else
            if Data['CSyncTable'][2] and tick() - (Data['LastMoveToAt'] or 0) > 1.2 then
                Data['CSyncTable'][2] = false
            end
            if not Data['IsRespawning'] and not Data['Buying'] then
                local char = LocalPlayer.Character
                local hrp = char and char:FindFirstChild('HumanoidRootPart') or nil
                if hrp and hrp.Parent then
                    if tick() - (Data['UndergroundNoclipAt'] or 0) > 0.25 then
                        Data['UndergroundNoclipAt'] = tick()
                        for _, p in ipairs(char:GetDescendants()) do
                            if p:IsA('BasePart') then
                                p.CanCollide = false
                            end
                        end
                    end
                    local baseCF = Data['CSyncTable'][2] and Data['CSyncTable'][1] or hrp.CFrame
                    local depth = (Options.underground_depth and Options.underground_depth.Value) or 4.5
                    local upV = hrp.AssemblyLinearVelocity.Y
                    if upV > 5 then
                        depth = depth + math.min((upV - 5) * 0.15, 10)
                    end
                    local params = RaycastParams.new()
                    params.FilterType = Enum.RaycastFilterType.Exclude
                    local ign = {}
                    for _, plr in ipairs(Players:GetPlayers()) do
                        if plr.Character then
                            ign[#ign + 1] = plr.Character
                        end
                    end
                    params.FilterDescendantsInstances = ign
                    params.RespectCanCollide = true
                    params.IgnoreWater = true
                    local hit =
                        workspace:Raycast(baseCF.Position + Vector3.new(0, 10, 0), Vector3.new(0, -510, 0), params)
                    if hit and hit.Position then
                        local tp = hit.Position - Vector3.new(0, depth + 3, 0)
                        set_server_cframe(
                            CFrame.new(tp) * (baseCF - baseCF.Position),
                            nil,
                            Data['PRIO'].IDLE,
                            'Underground'
                        )
                    end
                end
            end
            RunService.Heartbeat:Wait()
        end
    end
    local char = LocalPlayer.Character
    local hrp = char and getroot(char) or nil
    if hrp and hrp.Parent then
        hrp.AssemblyLinearVelocity = Vector3.zero
        hrp.AssemblyAngularVelocity = Vector3.zero
        hrp.Velocity = Vector3.zero
    end
    for i = #Data['CSync'].Queue, 1, -1 do
        if Data['CSync'].Queue[i].tag == 'Underground' then
            table.remove(Data['CSync'].Queue, i)
        end
    end
end
function phowg:ragebot_hide_required()
    if
        not (Data.Settings and Data.Settings.Hide)
        or not (rageboton() or punishmentactive())
        or Library.Unloaded
        or Data.SharedSignalsClosed
        or Data.IsRespawning
        or localactionblocked()
    then
        return false
    end
    if isreloading() or Data.GunReloadSelection or phowg:reload_pending(LocalPlayer.Character) then
        return true
    end
    if phowg:ragebot_idle_hiding(Data.RagebotIdle) then
        return true
    end
    return not hasactionabletargetuncached(true)
end
function phowg:refresh_void_ownership()
    if Data.ManualVoid then
        return
    end
    if phowg:ragebot_hide_required() then
        local entering = not Data.HideVoid
        local running = Data.VoidActive
        Data.HideVoid, Data.VoidActive, Data.HideStatus = true, true, 'hide'
        if entering then
            phowg:clear_ragebot_void_spam()
            local staleTags = { Combat = true, TargetStrafe = true, RagebotVoidReturn = true, ReloadVoid = true }
            for tag in pairs(staleTags) do
                releasemovement(tag)
            end
            for index = #Data.CSync.Queue, 1, -1 do
                if staleTags[Data.CSync.Queue[index].tag] then
                    table.remove(Data.CSync.Queue, index)
                end
            end
        end
        if not Data.Buying and not Data.MaskBuying then
            Data.CurrentStatus = isreloading() and 'ragebot: reloading in void' or 'ragebot: hiding...'
        end
        if not running then
            phowg:start_loop('VoidHide', voidhideloop)
        end
        return
    end
    if not Data.VoidActive and not Data.HideVoid then
        return
    end
    Data.VoidActive, Data.HideVoid, Data.HideStatus = false, nil, nil
    Data.RifleVoid, Data.RifleVoidFF, Data.RifleVoidWait, Data.RifleVoidTarget = nil, nil, nil, nil
    Data.StompHideTarget, Data.StompHideCharacter = nil, nil
    phowg:clear_void_presentation()
end
registerheartbeat('AutomaticVoidOwner', phowg.refresh_void_ownership, 0.05, function()
