function voidhideloop()
    while Data['VoidActive'] do
        phowg:refresh_void_ownership()
        if not Data.VoidActive then
            break
        end
        if localactionblocked() then
            task.wait(0.05)
            continue
        end
        local voidPriority = Data.HideVoid and not Data.ManualVoid and Data.PRIO.KNIFE or Data.PRIO.IDLE
        if movementblocked(voidPriority, 'Void') then
            RunService.Heartbeat:Wait()
            continue
        end
        if Data['CSyncTable'][2] and tick() - (Data['LastMoveToAt'] or 0) > 1.2 then
            Data['CSyncTable'][2] = false
        end
        if
            not Data['IsRespawning']
            and not Data['Buying']
            and LocalPlayer.Character
            and LocalPlayer.Character:FindFirstChild('HumanoidRootPart')
        then
            if
                Data['CurrentStatus'] ~= 'ragebot: hiding...'
                and Data['CurrentStatus'] ~= 'ragebot: hiding and waiting for forcefield..'
                and Data['CurrentStatus'] ~= 'ragebot: hiding and waiting for forcefield...'
                and Data['CurrentStatus'] ~= "ragebot: hiding and waiting for player's forcefield"
            then
                Data['CurrentStatus'] = 'ragebot: voiding'
            end
            if not phowg:manual_void_phase() then
                local client = Local_Data.ClientPos or Data.CSyncTable[1]
                if typeof(client) == 'CFrame' then
                    set_server_cframe(client, nil, voidPriority, 'VoidSpamOut')
                end
                RunService.Heartbeat:Wait()
                continue
            end
            local voidMode = (Options.void_mode and Options.void_mode.Value) or 'unkillable'
            if Data.HideVoid and not Data.ManualVoid then
                set_server_cframe(getvoidcframe(), nil, Data.PRIO.KNIFE, 'Void')
            elseif voidMode == 'anti matrix' then
                set_server_cframe(getvoidcframe(), nil, Data['PRIO'].IDLE, 'Void')
            elseif voidMode == 'random' then
                set_server_cframe(getvoidcframe(), nil, Data['PRIO'].IDLE, 'VoidTwitch')
            elseif Toggles.twitch_void and Toggles.twitch_void.Value then
                local useVoid = math.random() < 0.2
                local cf
                if useVoid then
                    cf = getvoidcframe()
                        * CFrame.Angles(
                            math.rad(math.random(-180, 180)),
                            math.rad(math.random(-180, 180)),
                            math.rad(math.random(-180, 180))
                        )
                else
                    local x = math.random(-10000, 10000)
                    local yChoices = { 20000, 6000, 10000 }
                    local y = yChoices[math.random(1, #yChoices)] + math.random(-5000, 5000)
                    local z = math.random(-100000, 10000)
                    cf = CFrame.new(x, y, z)
                        * CFrame.Angles(
                            math.rad(math.random(-180, 180)),
                            math.rad(math.random(-180, 180)),
                            math.rad(math.random(-180, 180))
                        )
                end
                set_server_cframe(cf, nil, Data['PRIO'].IDLE, 'VoidTwitch')
            else
                set_server_cframe(getvoidcframe(), nil, Data['PRIO'].IDLE, 'Void')
            end
        end
        RunService.Heartbeat:Wait()
    end
    Data['CurrentStatus'] = 'Idle'
    if LocalPlayer.Character then
        local hum = LocalPlayer.Character:FindFirstChildOfClass('Humanoid')
        if hum then
            hum.PlatformStand = false
            hum:ChangeState(Enum.HumanoidStateType.GettingUp)
            hum:ChangeState(Enum.HumanoidStateType.Running)
        end
        local hrp = getroot(LocalPlayer.Character)
        if hrp then
            hrp.AssemblyLinearVelocity = Vector3.zero
            hrp.AssemblyAngularVelocity = Vector3.zero
            hrp.Velocity = Vector3.zero
        end
    end
    phowg:clear_void_presentation()
end
