function phowg:restore_velocity_desync()
    local pending = Data.VelocityDesyncPending
    Data.VelocityDesyncPending = nil
    if pending and pending.Root.Parent then
        pending.Root.Velocity = pending.Velocity
    end
end
function phowg:velocity_desync_tick()
    phowg:restore_velocity_desync()
    if
        Library.Unloaded
        or Data.SharedSignalsClosed
        or not (Toggles.velocity_desync and Toggles.velocity_desync.Value)
    then
        return
    end
    local key = Options.velocity_desync_key
    if key and key.Value ~= 'None' and not key:GetState() then
        return
    end
    local character = LocalPlayer.Character
    local root = character and character:FindFirstChild('HumanoidRootPart')
    if not root or not root.Parent or localactionblocked() then
        return
    end
    local old = root.Velocity
    local mode = Options.velocity_desync_value and Options.velocity_desync_value.Value or 'zero'
    local randomValue = math.floor((Options.velocity_desync_random and Options.velocity_desync_random.Value or 5) * 5.5)
    local velocity = mode == 'zero' and Vector3.zero
        or mode == 'max' and Vector3.new(63536, 63536, 63536)
        or mode == 'sky' and Vector3.new(0, 10000, 0)
        or mode == 'multiplier' and old * (Options.velocity_desync_mult and Options.velocity_desync_mult.Value or 0.2)
        or mode == 'underground' and Vector3.new(0, -10000, 0)
        or mode == 'random'
            and Vector3.new(
                math.random(-randomValue, randomValue),
                math.random(-randomValue, randomValue),
                math.random(-randomValue, randomValue)
            )
    if not velocity then
        return
    end
    Data.VelocityDesyncPending = { Root = root, Velocity = old, Character = character }
    root.Velocity = velocity
end
function phowg:set_velocity_desync(enabled)
    for _, key in ipairs({ 'VelocityDesyncHeartbeat', 'VelocityDesyncRender' }) do
        if Data[key] then
            Data[key]:Disconnect()
            Data[key] = nil
        end
    end
    phowg:restore_velocity_desync()
    if not enabled then
        return
    end
    Data.VelocityDesyncHeartbeat = connectshared(
        RunService.Heartbeat,
        phowg.velocity_desync_tick,
        RunService,
        'heartbeat/velocity desynchronization',
        100,
        'event/Heartbeat',
        RunService
    )
    Data.VelocityDesyncRender = connectshared(
        RunService.RenderStepped,
        phowg.restore_velocity_desync,
        RunService,
        'frame/velocity desynchronization restore',
        -100,
        'event/RenderStepped',
        RunService
    )
end
phowg:register_cleanup('velocity desynchronization', function(scope, reason)
    if reason == 'unload' then
        phowg:set_velocity_desync(false)
    elseif Data.VelocityDesyncPending and Data.VelocityDesyncPending.Character == scope then
        phowg:restore_velocity_desync()
    end
end)

function phowg:clear_fake_position_visuals()
    for _, object in pairs(Data.FakePositionDrawings or {}) do
        pcall(function()
            object:Remove()
        end)
    end
    Data.FakePositionDrawings, Data.FakePositionScreen, Data.FakePositionFade = nil, nil, nil
end
function phowg:release_fake_position_root(state)
    local root = state and state.Root
    if root and root.Parent and state.Applied and type(sethiddenproperty) == 'function' then
        pcall(sethiddenproperty, root, 'PhysicsRepRootPart', state.Original)
    end
    if state then
        state.Root, state.Character, state.Applied, state.Position = nil, nil, nil, nil
        state.ReleaseUntil, state.CapturePosition, state.Cycles = nil, nil, 0
    end
end
function phowg:set_fake_position(value)
    local previous = Data.FakePosition
    Data.FakePosition = nil
    if previous and previous.Render then
        previous.Render:Disconnect()
    end
    phowg:release_fake_position_root(previous)
    if previous and previous.SenderRate ~= nil and type(setfflag) == 'function' then
        local restore = true
        if type(getfflag) == 'function' then
            local ok, current = pcall(getfflag, 'S2PhysicsSenderRate')
            restore = ok and tostring(current) == '1000'
        end
        if restore then
            pcall(setfflag, 'S2PhysicsSenderRate', previous.SenderRate)
        end
    end
    phowg:clear_fake_position_visuals()
    if Data.FakePositionVisualized then
        Data.FakePositionVisualized = nil
        hidevisualizer()
    end
    if not value then
        return true
    end
    if type(sethiddenproperty) ~= 'function' then
        Library:Notify('Your executor does not support fake position.', 4)
        return false
    end
    local state: { [string]: any } = { Cycles = 0, Paused = true }
    if type(getfflag) == 'function' and type(setfflag) == 'function' then
        local ok, original = pcall(getfflag, 'S2PhysicsSenderRate')
        if ok and original ~= nil and pcall(setfflag, 'S2PhysicsSenderRate', '1000') then
            state.SenderRate = original
        end
    end
    Data.FakePosition = state
    if phowg.fake_position_visual_tick then
        state.Render = phowg:register_render(phowg_callbacks.fake_position_visual_tick, LocalPlayer, 'visuals/fake position')
    end
    return true
end
function phowg:fake_position_blocked()
    return Library.Unloaded
        or Data.SharedSignalsClosed
        or Data.IsRespawning
        or Data.RPGUnloading
        or Data.Buying
        or Data.MoveToActive
        or Data.MoveToInFlight ~= nil
        or Data.CSyncTable and Data.CSyncTable[2] == true
        or Data.VoidActive
        or Data.DesyncActive
        or Data.UndergroundActive
        or Data.RPGMoveActive
end
function phowg:fake_position_tick()
    local state = Data.FakePosition
    if not state then
        return
    end
    local character = LocalPlayer.Character
    local root = character and character:FindFirstChild('HumanoidRootPart')
    local humanoid = character and character:FindFirstChildOfClass('Humanoid')
    if phowg:fake_position_blocked() or not root or not humanoid or humanoid.Health <= 0 then
        if state.Root then
            phowg:release_fake_position_root(state)
        end
        state.Paused = true
        return
    end
    if state.Root ~= root or state.Character ~= character then
        phowg:release_fake_position_root(state)
        state.Root, state.Character, state.Original = root, character, root
        if type(gethiddenproperty) == 'function' then
            local ok, original = pcall(gethiddenproperty, root, 'PhysicsRepRootPart')
            if ok and (original == nil or typeof(original) == 'Instance') then
                state.Original = original
            end
        end
        state.Position, state.At, state.Cycles = root.Position, tick(), 0
    end
    state.Paused = false
    local now, value = tick(), root
    if state.ReleaseUntil then
        if now < state.ReleaseUntil then
            return
        end
        if (root.Position - state.CapturePosition).Magnitude > 10 then
            state.Position, state.At = root.Position, now
        end
        state.ReleaseUntil, state.CapturePosition, state.Cycles = nil, nil, 20
    elseif state.Cycles <= 0 then
        state.CapturePosition, state.ReleaseUntil = root.Position, now + 0.1
        value = nil
    else
        state.Cycles -= 1
    end
    local ok, problem = pcall(sethiddenproperty, root, 'PhysicsRepRootPart', value)
    if ok then
        state.Applied = true
        return
    end
    phowg:set_fake_position(false)
    if Toggles.fake_position and Toggles.fake_position.Value then
        Toggles.fake_position:SetValue(false)
    end
    Library:Notify('Fake position could not set PhysicsRepRootPart: ' .. tostring(problem), 5)
end
function phowg:fake_position_snapshot(character, root)
    local state = Data.FakePosition
    if
        not state
        or state.Paused
        or state.Character ~= character
        or state.Root ~= root
        or not root.Parent
        or not state.Position
        or phowg:fake_position_blocked()
    then
        return nil
    end
    return CFrame.new(state.Position) * root.CFrame.Rotation, math.max(0, tick() - (state.At or tick()))
end
Data.FakePositionImages = {
    Icon = '',
}
function phowg:decode_fake_position_image(encoded)
    local alphabet, bytes = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/', {}
    for index = 1, #encoded, 4 do
        local function digit(offset)
            local value = alphabet:find(encoded:sub(index + offset, index + offset), 1, true)
            return value and value - 1 or 0
        end
        local value = digit(0) * 262144 + digit(1) * 4096 + digit(2) * 64 + digit(3)
        bytes[#bytes + 1] = string.char(math.floor(value / 65536) % 256)
        if encoded:sub(index + 2, index + 2) ~= '=' then
            bytes[#bytes + 1] = string.char(math.floor(value / 256) % 256)
        end
        if encoded:sub(index + 3, index + 3) ~= '=' then
            bytes[#bytes + 1] = string.char(value % 256)
        end
    end
    return table.concat(bytes)
end
function phowg:get_fake_position_drawings(storage)
    storage = storage or 'FakePositionDrawings'
    if Data[storage] then
        return Data[storage]
    end
    if not Drawing or type(Drawing.new) ~= 'function' or Data.FakePositionDrawingUnsupported then
        return nil
    end
    local drawings = {}
    local ok, problem = pcall(function()
        local function create(key, kind, properties)
            local object = Drawing.new(kind)
            drawings[key] = object
            object.Visible = false
            for name, value in pairs(properties) do
                object[name] = value
            end
            return object
        end
        create('Tracer', 'Line', { Thickness = 1.5, Transparency = 1, ZIndex = 51 })
        if storage ~= 'FakePositionDrawings' then
            create('GlowSoft', 'Circle', { Filled = true, NumSides = 48, Color = Color3.new(0, 0, 0), ZIndex = 50 })
            create('Glow', 'Circle', { Filled = true, NumSides = 48, Color = Color3.new(0, 0, 0), ZIndex = 51 })
            create('Outline', 'Circle', { Filled = true, NumSides = 48, Color = Color3.new(0, 0, 0), ZIndex = 52 })
            create('Fill', 'Circle', { Filled = true, NumSides = 48, ZIndex = 53 })
            create('Icon', 'Image', {
                Data = phowg:decode_fake_position_image(Data.FakePositionImages.Icon),
                Color = Color3.new(1, 1, 1),
                ZIndex = 54,
            })
        end
    end)
    if not ok then
        for _, object in pairs(drawings) do
            pcall(function()
                object:Remove()
            end)
        end
        Data.FakePositionDrawingUnsupported = true
        Library:Notify('Fake position visuals are unavailable: ' .. tostring(problem), 4)
        return nil
    end
    Data[storage] = drawings
    return drawings
end
function phowg:fake_position_visual_tick(delta)
    local tracerOn, indicatorOn = phowg:toggle_enabled('fake_position_tracer'), false
    local drawings = Data.FakePositionDrawings
    if not (tracerOn or indicatorOn) then
        if drawings then
            for _, object in pairs(drawings) do
                object.Visible = false
            end
        end
        Data.FakePositionScreen, Data.FakePositionFade = nil, nil
        return
    end
    local character = LocalPlayer.Character
    local root = character and character:FindFirstChild('HumanoidRootPart')
    local frame = root and phowg:fake_position_snapshot(character, root)
    local camera = Workspace.CurrentCamera
    if not frame or not camera then
        if drawings then
            for _, object in pairs(drawings) do
                object.Visible = false
            end
        end
        Data.FakePositionScreen, Data.FakePositionFade = nil, nil
        return
    end
    local point, visible = camera:WorldToViewportPoint(frame.Position)
    if not visible or point.Z <= 0 then
        if drawings then
            for _, object in pairs(drawings) do
                object.Visible = false
            end
        end
        Data.FakePositionScreen, Data.FakePositionFade = nil, nil
        return
    end
    drawings = drawings or phowg:get_fake_position_drawings()
    if not drawings then
        return
    end
    local destination = Vector2.new(point.X, point.Y)
    local tracerColor = Options.fake_position_tracer_color and Options.fake_position_tracer_color.Value
        or Color3.fromRGB(255, 100, 0)
    if tracerOn then
        local mode = Options.fake_position_tracer_origin and Options.fake_position_tracer_origin.Value or 'center'
        local origin = camera.ViewportSize / 2
        if mode == 'mouse' then
            origin = UserInputService:GetMouseLocation()
        elseif mode == 'guns tip' then
            local tool = character:FindFirstChildOfClass('Tool')
            local offset = tool and gettoolhandleoffset(character, tool)
            local head = character:FindFirstChild('Head')
            local position = offset and root.CFrame:PointToWorldSpace(offset) or head and head.Position
            if position then
                local muzzle, muzzleVisible = camera:WorldToViewportPoint(position)
                if muzzleVisible and muzzle.Z > 0 then
                    origin = Vector2.new(muzzle.X, muzzle.Y)
                else
                    origin = UserInputService:GetMouseLocation()
                end
            else
                origin = UserInputService:GetMouseLocation()
            end
        end
        drawings.Tracer.From, drawings.Tracer.To = origin, destination
        drawings.Tracer.Color, drawings.Tracer.Thickness =
            tracerColor, phowg:visual_number('fake_position_tracer_thickness', 1.5, 0.5, 5)
    end
    drawings.Tracer.Visible = tracerOn
end
registerheartbeat('FakePosition', phowg.fake_position_tick, 1 / 240, function()
    return Data.FakePosition ~= nil
end)
phowg:register_cleanup('fake position', function(scope, reason)
