end)
function unified_character_loop()
    while Data['DesyncActive'] or phowg:israel_support_enabled() do
        for player, mode in pairs(Data['PunishmentTargets'] or {}) do
            if supporttargetfinished(player, mode) then
                punishmentcleartarget(player, nil, true)
            end
        end
        if localactionblocked() then
            task.wait(0.05)
            continue
        end
        if Data['VoidActive'] then
            for i = #Data['CSync'].Queue, 1, -1 do
                if Data['CSync'].Queue[i].tag == 'Desync' then
                    table.remove(Data['CSync'].Queue, i)
                end
            end
            Data['DesyncBaseY'] = nil
        end
        if not (Data['DesyncActive'] and Toggles.desync_rotation and Toggles.desync_rotation.Value) then
            for i = #Data['CSync'].Queue, 1, -1 do
                if Data['CSync'].Queue[i].tag == 'Desync' then
                    table.remove(Data['CSync'].Queue, i)
                end
            end
            Data['DesyncBaseY'] = nil
        end
        if
            Data['DesyncActive']
            and Toggles.desync_rotation
            and Toggles.desync_rotation.Value
            and not movementblocked(Data['PRIO'].DESYNC, 'Desync')
        then
            local CharU = LocalPlayer.Character
            local RootU = CharU and CharU:FindFirstChild('HumanoidRootPart')
            if RootU then
                local RealCFU = (Data['CSyncTable'][2] and Data['CSyncTable'][1]) or RootU.CFrame
                local RootPosU = RealCFU.Position
                if
                    RootPosU.Magnitude > 1
                    and not Data['IsRespawning']
                    and not Data['Buying']
                    and not Data['VoidActive']
                    and RootU:IsDescendantOf(Workspace)
                then
                    local LookU = RealCFU.LookVector
                    LookU = Vector3.new(LookU.X, 0, LookU.Z)
                    if LookU.Magnitude < 0.05 then
                        LookU = Vector3.new(0, 0, -1)
                    end
                    LookU = LookU.Unit
                    local FacingU = CFrame.lookAt(Vector3.zero, LookU)
                    local PitchU = (Options.desync_pitch and Options.desync_pitch.Value) or 0
                    local YawU = (Options.desync_yaw and Options.desync_yaw.Value) or 0
                    local RollU = (Options.desync_roll and Options.desync_roll.Value) or 0
                    local JitXU, JitYU, JitZU = 0, 0, 0
                    if Toggles.desync_random_angle and Toggles.desync_random_angle.Value then
                        local XMinU = (Options.desync_x_min and Options.desync_x_min.Value) or -10
                        local XMaxU = (Options.desync_x_max and Options.desync_x_max.Value) or 10
                        local YMinU = (Options.desync_y_min and Options.desync_y_min.Value) or -10
                        local YMaxU = (Options.desync_y_max and Options.desync_y_max.Value) or 10
                        local ZMinU = (Options.desync_z_min and Options.desync_z_min.Value) or -10
                        local ZMaxU = (Options.desync_z_max and Options.desync_z_max.Value) or 10
                        if XMaxU < XMinU then
                            XMinU, XMaxU = XMaxU, XMinU
                        end
                        if YMaxU < YMinU then
                            YMinU, YMaxU = YMaxU, YMinU
                        end
                        if ZMaxU < ZMinU then
                            ZMinU, ZMaxU = ZMaxU, ZMinU
                        end
                        JitXU = XMinU + math.random() * (XMaxU - XMinU)
                        JitYU = YMinU + math.random() * (YMaxU - YMinU)
                        JitZU = ZMinU + math.random() * (ZMaxU - ZMinU)
                    end
                    local SpinModeU = Options.desync_spin_axis and Options.desync_spin_axis.Value or nil
                    if SpinModeU and SpinModeU ~= 'Off' then
                        local SpinT0U = Data['DesyncSpinT0'] or tick()
                        Data['DesyncSpinT0'] = SpinT0U
                        local SpinPhU = ((tick() - SpinT0U) % 16) / 16
                        local SpinTriU = SpinPhU < 0.5 and (SpinPhU * 2) or (2 - SpinPhU * 2)
                        local SpinAngU = -180 + 360 * SpinTriU
                        if SpinModeU == 'random pitch' then
                            PitchU = SpinAngU
                        elseif SpinModeU == 'random yaw' then
                            YawU = SpinAngU
                        else
                            RollU = SpinAngU
                        end
                    end
                    local DesyncCFU = CFrame.new(RootPosU.X + JitXU, RootPosU.Y + 5 + JitYU, RootPosU.Z + JitZU)
                        * FacingU
                        * CFrame.Angles(math.rad(PitchU), math.rad(YawU), math.rad(RollU))
                    set_server_cframe(DesyncCFU, nil, Data['PRIO'].DESYNC, 'Desync')
                end
            end
        end
        if Data['CSyncTable'][2] and tick() - (Data['LastMoveToAt'] or 0) > 1.5 then
            Data['CSyncTable'][2] = false
            for i = #Data['CSync'].Queue, 1, -1 do
                if Data['CSync'].Queue[i].tag == 'Desync' then
                    table.remove(Data['CSync'].Queue, i)
                end
            end
        end
        RunService.Heartbeat:Wait()
    end
end
function updatetracers()
    if not Drawing or not Drawing.new then
        return
    end
    if
        not (Toggles.grenade_tp and Toggles.grenade_tp.Value)
        or not (Toggles.grenade_tracer and Toggles.grenade_tracer.Value)
    then
        for _, Line in pairs(Data['GrenadeTracerPool']) do
            Line.Visible = false
        end
    else
        local Camera = Workspace.CurrentCamera
        if not Camera then
            for _, Line in pairs(Data['GrenadeTracerPool']) do
                Line.Visible = false
            end
        else
            local MousePos = UserInputService:GetMouseLocation()
            local ActiveGIndex = 0
            for _, Child in ipairs(getgrenadeparts()) do
                local owner = Child and Child.Parent and grenadelauncherowner(Child)
                if
                    Child
                    and Child.Parent
                    and ismolotovpart(Child)
                    and (not owner or Child == owner:FindFirstChild('Main', true))
                then
                    local ScreenPos, OnScreen = Camera:WorldToViewportPoint(Child.Position)
                    if OnScreen then
                        ActiveGIndex = ActiveGIndex + 1
                        local GLine = getorcreategrenadetracer(ActiveGIndex)
                        if GLine then
                            GLine.From = MousePos
                            GLine.To = Vector2.new(ScreenPos.X, ScreenPos.Y)
                            GLine.Transparency = 1
                            GLine.Visible = true
                        end
                    end
                end
            end
            for I = ActiveGIndex + 1, #Data['GrenadeTracerPool'] do
                if Data['GrenadeTracerPool'][I] then
                    Data['GrenadeTracerPool'][I].Visible = false
                end
            end
        end
    end
end
function phowg:display_status()
