            or tag == 'RagebotVoid'
            or tag == 'RagebotIdle'
        )
    then
        return 'void'
    end
    return tostring(Data.CurrentStatus or 'idle')
end
function updatestatusdisplay()
    if not Data['StatusText'] then
        return
    end
    if phowg:display_status() == 'void' then
        if Data.StatusShown ~= 'void' then
            Data.StatusShown, Data.StatusText.Text = 'void', 'void'
        end
        Data.StatusText.Visible = true
        return
    end
    if not rageboton() then
        Data['CurrentStatus'] = 'Idle'
        Data['CurrentActionTarget'] = nil
        if Data['StatusShown'] ~= nil then
            Data['StatusShown'] = nil
            Data['StatusText'].Text = ''
            Data['StatusText'].Visible = false
        end
        return
    end
    if checktargetwatch then
        checktargetwatch()
    end
    if
        Data['CurrentStatus']
        and Data['CurrentStatus'] ~= 'Idle'
        and Data['CurrentStatus'] ~= 'ragebot: voiding'
        and Data['CurrentStatus'] ~= 'target is in void respawning..'
    then
        if not Data['Buying'] and not Data['VoidActive'] and not Data['HideVoid'] and not hasactionabletarget() then
            Data['CurrentStatus'] = 'Idle'
            Data['CurrentActionTarget'] = nil
        end
    end
    if Data['CurrentStatus'] == 'Idle' then
        Data['CurrentActionTarget'] = nil
    end
    local plr = Data['CurrentActionTarget'] or Data['CurrentMainTarget'] or Data['SingleLockedTarget']
    if not plr or not plr.Parent then
        for p, _ in pairs(Data['LockedTargets'] or {}) do
            plr = p
            break
        end
    end
    if not plr or not plr.Parent then
        local sel = Options.target_select and Options.target_select.Value
        if typeof(sel) == 'Instance' and sel:IsA('Player') and sel.Parent then
            plr = sel
        elseif typeof(sel) == 'string' then
            local p = Players:FindFirstChild(sel)
            if p and p.Parent then
                plr = p
            end
        end
    end
    local namePart = 'no target'
    if plr and plr.Parent then
        local disp = plr.DisplayName or plr.Name
        namePart = '@' .. plr.Name .. '|' .. disp
    end
    local bodyExists = plr
        and plr.Character
        and plr.Character.Parent
        and plr.Character:FindFirstChild('HumanoidRootPart')
        and plr.Character:FindFirstChildOfClass('Humanoid')
    local state = 'waiting'
    local s = string.lower(phowg:display_status())
    if plr and not bodyExists then
        state = 'target is in void respawning..'
    elseif s:find('killing', 1, true) then
        state = 'killing'
    elseif s:find('stomping', 1, true) then
        state = 'stomping'
    elseif s:find('shooting', 1, true) or s:find('strafe position', 1, true) then
        state = 'killing'
    elseif s:find('reloading', 1, true) then
        state = 'reloading'
    elseif s:find('arresting', 1, true) then
        state = 'arresting'
    elseif s:find('buying', 1, true) then
        state = 'buying'
    elseif s:find('charging', 1, true) then
        state = 'charging'
    elseif s:find('flinging', 1, true) then
        state = 'killing'
    elseif s:find('predicting', 1, true) then
        state = 'waiting'
    elseif s:find('hiding', 1, true) or s:find('voiding', 1, true) or Data['VoidActive'] or Data['HideVoid'] then
        state = 'hiding'
    elseif s == 'idle' then
        state = 'waiting'
    elseif s:sub(1, 9) == 'ragebot: ' then
        state = tostring(Data.CurrentStatus):sub(10)
    end
    local showText = '> ' .. state .. " '" .. namePart .. "'"
    if showText ~= Data['StatusShown'] then
        Data['StatusShown'] = showText
        Data['StatusText'].Text = showText
        Data['StatusText'].Visible = true
    end
end
function gotoflingpart()
    if localactionblocked() then
        return
    end
    local part = Data['FlingPart']
    local char = LocalPlayer.Character
    local myHRP = char and char:FindFirstChild('HumanoidRootPart')
    if part and part.Parent and myHRP then
        myHRP.CFrame = part.CFrame + Vector3.new(0, 5, 0)
    end
end
function getequippedguntool()
    local char = LocalPlayer.Character
    if char then
        for _, tool in ipairs(char:GetChildren()) do
            if phowg:inventory_is_gun(tool) then
                return tool
            end
        end
    end
    return nil
end
function getgunreserve(tool)
    local v = nil
    (function()
        local df = LocalPlayer:FindFirstChild('DataFolder')
        local inv = df and df:FindFirstChild('Inventory')
        local item = inv
            and tool
            and (inv:FindFirstChild(tool.Name) or inv:FindFirstChild(tool.Name:match('^%[(.-)%]$') or tool.Name))
        if item and item.Value ~= nil then
            v = tonumber(item.Value)
        end
    end)()
    return v
end
function ammoshopname(toolName)
    local n = tostring(toolName or '')
    if n:sub(-1) == ']' then
        return n:sub(1, -2) .. ' Ammo]'
    end
    return n .. ' Ammo'
end
function autoammoloop()
    if Toggles.auto_ammo and Toggles.auto_ammo.Value then
        if localactionblocked() then
            task.wait(0.05)
        elseif
            Data['IsRespawning']
            or Data['Buying']
            or Data.Sorting
            or Data.InventoryEquip
            or Data.AmmoSupplyOwner
            or Data.LoadoutBusy
        then
            RunService.Heartbeat:Wait()
        else
            local tool = phowg:auto_ammo_tool()
            local reserve = tool and getgunreserve(tool) or nil
            if
                tool
                and reserve ~= nil
                and reserve <= 0
                and phowg:loadout_ammo_purchase_allowed()
                and tick() >= (Data.AutoAmmoRetryAt or 0)
            then
                local count = (Options.ammo_buy_count and Options.ammo_buy_count.Value) or 5
                local cashBefore = nil
                (function()
                    local df = LocalPlayer:FindFirstChild('DataFolder')
                    local cur = df and df:FindFirstChild('Currency')
                    if cur then
                        cashBefore = cur.Value
                    end
                end)()
                local CharNow = LocalPlayer.Character
                local PackNow = LocalPlayer:FindFirstChild('Backpack')
                local currentTarget = Data['CurrentActionTarget'] or Data['SingleLockedTarget']
                local supportTarget = Data['PunishmentTargets']
                        and Data['PunishmentTargets'][currentTarget]
                        and currentTarget
                    or nil
                local pending = nil
                if not phowg:combat_ammo_active() and CharNow and PackNow and tool.Parent == CharNow then
                    phowg:stop_gun_fire(nil, tool)
                    pending = phowg:queue_inventory_equip(tool, CharNow, PackNow, supportTarget)
                    pending.Ready = false
                    Data.AutoAmmoEquipPending = pending
                    tool.Parent = PackNow
                end
                local owner = { Character = CharNow, Tool = tool }
                Data.AmmoSupplyOwner = owner
                local function valid()
                    return Data.AmmoSupplyOwner == owner
                        and CharNow == LocalPlayer.Character
                        and not Library.Unloaded
                        and Toggles.auto_ammo
                        and Toggles.auto_ammo.Value
                        and not localactionblocked()
                        and not Data.IsRespawning
                        and tool.Parent ~= nil
                        and (tool.Parent == CharNow or tool.Parent == PackNow)
                        and phowg:loadout_ammo_purchase_allowed()
                        and (not phowg:combat_ammo_active() or phowg:is_ragebot_gun_selected(tool))
                end
                local bought, buyResult =
                    pcall(purchase_item, ammoshopname(tool.Name), Data['PRIO'].AMMO, count, nil, supportTarget, valid)
                if Data.AmmoSupplyOwner == owner then
                    Data.AmmoSupplyOwner = nil
                end
                if not bought or not buyResult then
                    Data.AutoAmmoRetryAt = tick() + 5
                end
                if pending then
                    pending.Ready = true
                end
                Data.AutoAmmoEquipPending = nil
                phowg:restore_inventory_equip()
                if not bought then
                    warn('[Phowg] auto ammo: ' .. tostring(buyResult))
                end
                local cashAfter = nil
                (function()
                    local df = LocalPlayer:FindFirstChild('DataFolder')
                    local cur = df and df:FindFirstChild('Currency')
                    if cur then
                        cashAfter = cur.Value
                    end
                end)()
                if cashBefore ~= nil and cashAfter ~= nil and cashAfter >= cashBefore then
                    Data.AutoAmmoRetryAt = tick() + 5
                end
            end
            RunService.Heartbeat:Wait()
        end
    end
end
function getammolabel()
    local label = Data['AmmoLabel']
    if label and label.Parent then
        return label
    end
    local playerGui = LocalPlayer:FindFirstChildOfClass('PlayerGui')
    local oldGui = CoreGui:FindFirstChild('PhowgAmmoHud') or playerGui and playerGui:FindFirstChild('PhowgAmmoHud')
    if oldGui then
        oldGui:Destroy()
    end
    local gui = Instance.new('ScreenGui')
    gui.Name = 'PhowgAmmoHud'
    gui.IgnoreGuiInset = true
    gui.ResetOnSpawn = false
    gui.DisplayOrder = 2147483647
    local text = Instance.new('TextLabel')
    text.Name = 'Text'
    text.AnchorPoint = Vector2.new(0.5, 0)
    text.RichText = true
    text.TextXAlignment = Enum.TextXAlignment.Center
    text.TextYAlignment = Enum.TextYAlignment.Top
    text.AutomaticSize = Enum.AutomaticSize.XY
    text.BackgroundTransparency = 1
    text.BorderSizePixel = 0
    text.Font = Enum.Font.GothamBold
    text.Size = UDim2.fromOffset(0, 0)
    text.TextColor3 = Color3.fromRGB(255, 255, 255)
    text.TextSize = 16
    text.TextStrokeTransparency = 0
    text.Visible = false
    text.Parent = gui
    gui.Parent = CoreGui
    if not gui.Parent then
        gui.Parent = LocalPlayer:FindFirstChildOfClass('PlayerGui')
    end
    Data['AmmoGui'] = gui
    Data['AmmoLabel'] = text
    return text
end
function isreloading()
    local char = LocalPlayer and LocalPlayer.Character or nil
    if not char then
        return false
    end
    local bodyEffects = char:FindFirstChild('BodyEffects')
    local reload = bodyEffects and bodyEffects:FindFirstChild('Reload')
    local reloading = bodyEffects and bodyEffects:FindFirstChild('Reloading')
    return reload and reload:IsA('BoolValue') and reload.Value
        or reloading and reloading:IsA('BoolValue') and reloading.Value
        or false
end
function preparevoidreload(tool)
    if not tool or Data.RagebotIdle or localactionblocked() or Data.Buying or Data.IsRespawning then
        return false
    end
    local character = LocalPlayer.Character
    local backpack = LocalPlayer:FindFirstChild('Backpack')
    if not character or (tool.Parent ~= character and tool.Parent ~= backpack) then
        return false
    end
    local ammo = tool:FindFirstChild('Ammo')
    if not ammo or type(ammo.Value) ~= 'number' or ammo.Value > 0 then
        return false
    end
    local reserve = getgunreserve(tool)
    if reserve ~= nil and reserve <= 0 then
        return false
    end
    return phowg:request_gun_reload(tool, MainEvent or ReplicatedStorage:FindFirstChild('MainEvent'))
end
function phowg:manipulation_ready(record)
    local target = record and record.Player
    local character = LocalPlayer.Character
    local targetCharacter = target and target.Character
    local root = character and character:FindFirstChild('HumanoidRootPart')
    local humanoid = targetCharacter and targetCharacter:FindFirstChildOfClass('Humanoid')
    if
        not root
        or not targetCharacter
        or not targetCharacter.Parent
        or not humanoid
        or humanoid.Health < 1
        or targetCharacter:FindFirstChildOfClass('ForceField')
        or localshootblocked()
        or isreloading()
        or phowg:purchase_blocks_shooting()
        or Data.RPGMoveActive
    then
        return false
    end
    local tool = getequippedguntool()
    local ammo = tool and tool:FindFirstChild('Ammo')
    local ammoCount = ammo and tonumber(ammo.Value)
    local handle = tool and tool:FindFirstChild('Handle')
    local rangeValue = tool and tool:FindFirstChild('Range')
    local grip = Data.GripWallbang
    local gripActive = grip and grip.Tool == tool and grip.Target == target and tool.Grip == grip.Applied
    local around = phowg:around_wallbang_enabled(target, record and record.Owner)
    local range = (gripActive or around) and 250
        or rangeValue and tonumber(rangeValue.Value)
        or tool and tonumber(tool:GetAttribute('Range'))
    if
        not tool
        or tool.Parent ~= character
        or not ammoCount
        or ammoCount < 1
        or not handle
        or not handle:IsA('BasePart')
        or not range
        or range ~= range
        or range <= 0
        or range == math.huge
    then
        return false
    end
    local reload = tool:FindFirstChild('Reloading') or tool:FindFirstChild('Reload')
    if reload and reload.Value == true then
        return false
    end
    local shotTarget, position, part, source
    if phowg.get_gun_shot_target then
        shotTarget, position, part, source = phowg:get_gun_shot_target()
    end
    if shotTarget and shotTarget ~= target then
        return false
    end
    source = source or record.Owner
    if phowg.sticky_shot_blocked and phowg:sticky_shot_blocked(target, source) then
        return false
    end
    if not part or not part.Parent or not part:IsDescendantOf(targetCharacter) then
        part = phowg:strafe_aim_part(target)
    end
    if not part then
        return false
    end
    local point = part.Position
    local method = phowg:gun_shoot_method(source, target)
    if method == 'perfect hit' or method == 'china hack' then
        local solution = phowg.perfect_hit_solution and phowg:perfect_hit_solution(target, position, part)
        if not solution then
            return false
        end
        point = solution.Point
    end
    if not phowg:perfect_hit_vector(point) then
        return false
    end
    local offset = gettoolhandleoffset(character, tool)
    if not offset then
        return false
    end
    local cf = root:GetPivot() * root.PivotOffset:Inverse()
    local tag, applied = Data.AppliedServerTag, Data.AppliedServerCF
    local age = tick() - (Data.AppliedServerAt or -math.huge)
    if
        Data.AppliedServerCharacter == character
        and typeof(applied) == 'CFrame'
        and age >= 0
        and age <= 0.15
        and (tag == 'Combat' or tag == 'KillAura' or tag == 'TargetStrafe' or tag == 'Desync')
    then
        cf = applied
    elseif
        tag == 'Void'
        or tag == 'VoidTwitch'
        or tag == 'VoidSpamOut'
        or tag == 'RagebotVoid'
        or tag == 'RagebotIdle'
    then
        return false
    end
    local cached = Data.SmartStrafeCache and Data.SmartStrafeCache[target]
    if cached and cached.mode == 'chinese' and (cached.VoidFallback or cached.Travel) then
        return false
    end
    local origin = cf:PointToWorldSpace(offset)
    if not phowg:perfect_hit_vector(origin) or math.abs(cf.Position.Y) > 5000 or (point - origin).Magnitude > range then
        return false
    end
    local state = Data.ManipulationProbe
    if not state or state.Character ~= character or state.Target ~= targetCharacter or state.Tool ~= tool then
        local params = phowg:strafe_shot_params(character, targetCharacter)
        local overlap = OverlapParams.new()
        overlap.FilterType, overlap.RespectCanCollide, overlap.MaxParts = Enum.RaycastFilterType.Exclude, true, 16
        overlap.FilterDescendantsInstances = params.FilterDescendantsInstances
        state = { Character = character, Target = targetCharacter, Tool = tool, Params = params, Overlap = overlap }
        Data.ManipulationProbe = state
    end
    if around then
        return phowg:resolve_wallbang_origin(tool, target, origin, point, source) ~= nil
    end
    if gripActive then
        return (point - grip.BaseOrigin).Magnitude <= 250
            and (origin - grip.Origin).Magnitude <= 0.75
            and phowg:grip_wallbang_path_clear(
                origin,
                point,
                state.Params,
                character,
                root:GetPivot() * root.PivotOffset:Inverse(),
                cf
            )
    end
    local wall
    if
        cached
        and cached.localCharacter == character
        and cached.character == targetCharacter
        and cached.tool == tool
        and cached.wall
        and cached.wall.Parent
        and ispointinsidepart(cached.wall, origin)
    then
        wall = cached.wall
    else
        for _, candidate in ipairs(Workspace:GetPartBoundsInRadius(origin, 0.05, state.Overlap)) do
            if candidate:IsA('BasePart') and candidate.CanCollide and ispointinsidepart(candidate, origin) then
                wall = candidate
                break
            end
        end
    end
    if wall then
        local hull = phowg:chinese_character_hull(character, tool)
        if not hull then
            return false
        end
        state.wall, state.params = wall, state.Params
        return phowg:chinese_shot_clear(origin, point, state, cf, hull)
    end
    return phowg:strafe_shot_clear(origin, point, state.Params)
end
phowg:register_cleanup('manipulation indicator', function(scope)
    local state = Data.ManipulationProbe
    if not scope or state and (scope == state.Character or scope == state.Target or scope == state.Tool) then
        Data.ManipulationProbe = nil
    end
end)
function updateammodisplay()
    local label = getammolabel()
    local wantAmmo = Toggles.visualize_ammo and Toggles.visualize_ammo.Value or false
    if not wantAmmo then
        if label.Visible then
            label.Visible = false
        end
        Data['AmmoText'] = nil
        return
    end
    local nowM = tick()
    if nowM - (Data['AmmoTextAt'] or 0) >= 0.1 then
        Data['AmmoTextAt'] = nowM
        local sel = Options.indicator_sources and Options.indicator_sources.Value or {}
        local function sel_has(name)
            if type(sel) ~= 'table' then
                return sel == name
            end
            if sel[name] then
                return true
            end
            for _, v in ipairs(sel) do
                if v == name then
                    return true
                end
            end
            return false
        end
        local lines = {}
        local char = LocalPlayer.Character
        local record = phowg:get_active_target()
        local function escape(value)
            return tostring(value or ''):gsub('&', '&amp;'):gsub('<', '&lt;'):gsub('>', '&gt;'):gsub('"', '&quot;')
        end
        local accent = Options.indicator_color and Options.indicator_color.Value or Color3.fromRGB(231, 48, 91)
        local color = ('rgb(%d,%d,%d)'):format(
            math.round(accent.R * 255),
            math.round(accent.G * 255),
            math.round(accent.B * 255)
        )
        local titleOption = record and Options.indicator_active_title or Options.indicator_title
        local heading = titleOption and titleOption.Value or 'phowg host'
        if heading ~= '' then
            lines[#lines + 1] = '<font color="'
                .. (record and color or 'rgb(255,255,255)')
                .. '">'
                .. escape(heading)
                .. '</font>'
        end
        local function feature(name, enabled, target)
            if not sel_has(name) then
                return
            end
            local line = '<font color="'
                .. (enabled and 'rgb(255,255,255)' or 'rgb(160,160,160)')
                .. '">'
                .. name
                .. '</font>'
            if enabled and target and target.Parent then
                line ..= ' <font color="' .. color .. '">' .. escape(target.DisplayName or target.Name) .. '</font>'
            end
            lines[#lines + 1] = line
        end
        feature('silent aim', Toggles.silent_aim_enabled and Toggles.silent_aim_enabled.Value, Data.SilentAimTarget)
        feature('sticky aim', Toggles.sticky_aim_enabled and Toggles.sticky_aim_enabled.Value, get_sticky_target())
        feature('aim assist', Toggles.aim_assist_enabled and Toggles.aim_assist_enabled.Value, Data.AssistLockedTarget)
        feature(
            'speed',
            Toggles.speed_velocity and Toggles.speed_velocity.Value
                or Toggles.walkspeed_enabled and Toggles.walkspeed_enabled.Value
        )
        feature('fly', Toggles.fly and Toggles.fly.Value)
        feature(
            'esp',
            Toggles.name_esp and Toggles.name_esp.Value
                or Toggles.box_esp and Toggles.box_esp.Value
                or Toggles.health_esp and Toggles.health_esp.Value
        )
        if sel_has('manipulation') and phowg:manipulation_ready(record) then
            lines[#lines + 1] = '<font color="' .. color .. '">manipulated</font>'
        end
        local reloading = char and char.Parent and isreloading() or false
        if sel_has('ammo') and char and char.Parent and not reloading then
            local tool = getequippedguntool()
            if tool and tool.Parent then
                local a = tool:FindFirstChild('Ammo')
                local m = tool:FindFirstChild('MaxAmmo')
                local mag = a and a.Value or nil
                local mx = m and m.Value or nil
                if mag == nil and tool == Local_Data['Current_Gun'] then
                    mag = Local_Data['Ammo']
                end
                if mx == nil and tool == Local_Data['Current_Gun'] then
                    mx = Local_Data['MaxAmmo']
                end
                Local_Data['Current_Gun'] = tool
                Local_Data['Ammo'] = mag
                Local_Data['MaxAmmo'] = mx
                if mag ~= nil and mx ~= nil then
                    lines[#lines + 1] = tostring(mag) .. '/' .. tostring(mx)
                elseif mag ~= nil then
                    lines[#lines + 1] = tostring(mag)
                end
            end
        end
        if sel_has('reloading') and reloading then
            lines[#lines + 1] = 'reloading'
        end
        if sel_has('buying item') and Data['Buying'] then
            local item = Data['BuyingItem'] or 'item'
            lines[#lines + 1] = 'buying ' .. item
        end
        if sel_has('respawning') and Data['IsRespawning'] then
            lines[#lines + 1] = 'respawning'
        end
        if record then
            local vitals = {}
            if sel_has('health') then
                vitals[#vitals + 1] = 'H: ' .. math.round(record.Health)
            end
            if sel_has('armor') then
                vitals[#vitals + 1] = 'A: ' .. math.round(record.Armor)
            end
            if #vitals > 0 then
                lines[#lines + 1] = table.concat(vitals, ' | ')
            end
            if sel_has('country') then
                lines[#lines + 1] = 'country: ' .. escape(phowg:player_country(record.Player))
            end
            if sel_has('fire armor') then
                lines[#lines + 1] = 'fire armor: ' .. math.ceil(record.FireArmor)
            end
            if sel_has('target weapon') and record.Tool then
                lines[#lines + 1] = record.Tool.Name
            end
            if sel_has('target reloading') and record.Reload then
                lines[#lines + 1] = 'target reloading'
            end
            if sel_has('target distance') then
                lines[#lines + 1] = ('target: %dm'):format(
                    (record.Root.Position - Workspace.CurrentCamera.CFrame.Position).Magnitude
                )
            end
            if sel_has('spawn protection') and record.ForceField then
                lines[#lines + 1] = 'spawn protection'
            end
        end
        local humanoid = char and char:FindFirstChildOfClass('Humanoid')
        if sel_has('self health') and humanoid then
            lines[#lines + 1] = ('self health: %d/%d'):format(math.ceil(humanoid.Health), math.ceil(humanoid.MaxHealth))
        end
        local body = char and char:FindFirstChild('BodyEffects')
        local armor = body and body:FindFirstChild('Armor')
        if sel_has('self armor') and armor then
            lines[#lines + 1] = 'self armor: ' .. tostring(armor.Value)
        end
        if sel_has('self fire armor') then
            local value = getfirearmorvalue()
            if value ~= nil then
                lines[#lines + 1] = 'self fire armor: ' .. tostring(value)
            end
        end
        if sel_has('ping') then
            local ok, ping = pcall(function()
                return LocalPlayer:GetNetworkPing()
            end)
            if ok and typeof(ping) == 'number' then
                lines[#lines + 1] = ('ping: %d ms'):format(math.floor(ping * 1000 + 0.5))
            end
        end
        local target = record and record.Player
        if sel_has('target') and target and target.Parent then
            lines[#lines + 1] = 'target: ' .. target.DisplayName
        end
        if sel_has('ragebot') and (rageboton() or punishmentactive()) then
            lines[#lines + 1] = phowg:display_status()
        end
        if sel_has('strafe') and (rageboton() or punishmentactive()) then
            lines[#lines + 1] = 'strafe: '
                .. tostring(Options.target_strafe_mode and Options.target_strafe_mode.Value or 'orbit')
        end
        if sel_has('shot delay') and target and Data['CombatArrivalTarget'] == target and Data['CombatArrivalAt'] then
            local remaining = math.max(0, 0.4 - (tick() - Data['CombatArrivalAt']))
            lines[#lines + 1] = remaining > 0 and ('shot: %.2fs'):format(remaining) or 'shot ready'
        end
        if (sel_has('evade explosives') or sel_has('rpg dodge')) and Data['RPGMoveActive'] then
            lines[#lines + 1] = 'evading explosives'
        end
        if sel_has('reserve ammo') then
            local tool = getequippedguntool()
            local reserve = tool and getgunreserve(tool)
            if reserve ~= nil then
                lines[#lines + 1] = 'reserve: ' .. tostring(reserve)
            end
        end
        if sel_has('void') and (Data['VoidActive'] or Data['HideVoid'] or Data['RifleVoid'] or reloadvoidactive()) then
            lines[#lines + 1] = 'void waiting'
        end
        Data['AmmoText'] = #lines > 0 and table.concat(lines, '\n') or nil
    end
    local txt = Data['AmmoText']
    if txt then
        local scale, opacity = phowg:hud_settings()
        local size, transparency, stroke = math.round(12 * scale), 1 - opacity, math.max(0.25, 1 - opacity)
        if label.TextSize ~= size then
            label.TextSize = size
        end
        if label.TextTransparency ~= transparency then
            label.TextTransparency = transparency
        end
        if label.TextStrokeTransparency ~= stroke then
            label.TextStrokeTransparency = stroke
        end
        local position = UDim2.new(0.5, 0, 1, -175)
        if label.Position ~= position then
            label.Position = position
        end
        if label.Text ~= txt then
            label.Text = txt
        end
        if not label.Visible then
            label.Visible = true
        end
    else
        if label.Visible then
            label.Visible = false
        end
    end
end
function gettargetvisualtarget(sources)
    local record = phowg.get_active_target and phowg:get_active_target(sources)
    return record and record.Player or nil
end

do
    local sourceEntries = {
        { 'ragebot', 'Ragebot', { 'RifleTarget', 'GunFocusTarget', 'CurrentActionTarget', 'CurrentMainTarget' } },
        { 'support', 'Support', { 'RapeTarget' } },
        { 'kill aura', 'KillAura', { 'KillAuraTarget' } },
        { 'silent aim', 'SilentAim', { 'SilentAimTarget' } },
        { 'aim assist', 'AimAssist', { 'AssistLockedTarget' } },
        { 'sticky aim', 'StickyAim', { 'StickyTarget' } },
        { 'target strafe', 'TargetStrafe', { 'TargetStrafeTarget' } },
    }
    local function enabled(name)
        return Toggles[name] and Toggles[name].Value == true
    end
    local function selected(values, name)
        return type(values) == 'table' and (values[name] == true or table.find(values, name) ~= nil) or values == name
    end
    local function number(name, fallback, minimum, maximum)
        local value = tonumber(Options[name] and Options[name].Value)
        if not value or value ~= value or math.abs(value) == math.huge then
            return fallback
        end
        return math.clamp(value, minimum, maximum)
    end
    local function key_active(name)
        local key = Options[name]
        return key and key.GetState and key:GetState() == true
    end
    local function active(owner)
        if owner == 'Ragebot' then
            return Data.PunishmentGunActive == true
                or phowg:target_search_engaged()
                or phowg:auto_bounty_enabled()
                or (enabled('ragebot_enable') and Data.RagebotActive == true and key_active('ragebot_enable_key'))
        end
        if owner == 'Support' then
            return phowg:israel_support_enabled() and enabled('full_rage') and not Data.PunishmentGunActive
        end
        if owner == 'KillAura' then
            return enabled('kill_aura_enabled') and key_active('kill_aura_keybind')
        end
        if owner == 'SilentAim' then
            return enabled('silent_aim_enabled') and key_active('silent_aim_keybind')
        end
        if owner == 'AimAssist' then
            return enabled('aim_assist_enabled') and key_active('aim_assist_key')
        end
        if owner == 'StickyAim' then
            return enabled('sticky_aim_enabled')
        end
        if owner == 'TargetStrafe' then
            return enabled('target_strafe_enabled')
                and Data.TargetStrafeActive == true
                and key_active('target_strafe_key')
        end
        return false
    end
    local function valid(player, owner)
        if not player or player == LocalPlayer or not player.Parent then
            return false
        end
        if owner == 'Support' and Data.SupportCompletedTargets and Data.SupportCompletedTargets[player] then
            return false
        end
        local character = player.Character
        local humanoid = character and character:FindFirstChildOfClass('Humanoid')
        return character
            and character.Parent
            and humanoid
            and humanoid.Health > 0
            and character:FindFirstChild('HumanoidRootPart') ~= nil
    end
    function phowg:get_active_target(sources)
        local function allowed(source)
            return sources == nil or selected(sources, source)
        end
        local now, record = tick(), sources == nil and Data.ActiveTarget or nil
        if
            record
            and now < (Data.ActiveTargetAt or 0)
            and active(record.Owner)
            and valid(record.Player, record.Owner)
            and record.Character == record.Player.Character
        then
            return record
        end
        local player, source, owner
        local held = Data.HeldGunFire
        if
            held
            and held.Character == LocalPlayer.Character
            and held.Tool
            and held.Tool.Parent == held.Character
            and active(held.Owner)
            and valid(held.Target, held.Owner)
        then
            for _, entry in ipairs(sourceEntries) do
                if entry[2] == held.Owner and allowed(entry[1]) then
                    player, source, owner = held.Target, entry[1], entry[2]
                    break
                end
            end
        end
        if not player then
            for _, entry in ipairs(sourceEntries) do
                if allowed(entry[1]) and active(entry[2]) then
                    for _, name in ipairs(entry[3]) do
                        if valid(Data[name], entry[2]) then
                            player, source, owner = Data[name], entry[1], entry[2]
                            break
                        end
                    end
                    if player then
                        break
                    end
                end
            end
        end
        if sources == nil then
            Data.ActiveTargetAt = now + 1 / 120
        end
        if not player then
            if sources == nil then
                Data.ActiveTarget = nil
            end
            return nil
        end
        local character = player.Character
        local body = character:FindFirstChild('BodyEffects')
        local humanoid = character:FindFirstChildOfClass('Humanoid')
        local function stat(name)
            local value = body and body:FindFirstChild(name)
            if not value then
                local effects = humanoid and humanoid:FindFirstChild('BodyEffects')
                value = effects and effects:FindFirstChild(name)
            end
            local number = value and tonumber(value.Value) or 0
            return number and number == number and math.abs(number) < math.huge and math.max(0, number) or 0
        end
        record = record or {}
        record.Player, record.Character, record.Root, record.Humanoid =
            player, character, character:FindFirstChild('HumanoidRootPart'), humanoid
        record.Source, record.Owner = source, owner
        record.Health, record.MaxHealth, record.Armor, record.FireArmor =
            math.max(0, humanoid.Health), math.max(1, humanoid.MaxHealth), stat('Armor'), stat('FireArmor')
        record.Tool = character:FindFirstChildOfClass('Tool')
        local reload = body and body:FindFirstChild('Reload')
        record.Reload = reload and reload.Value == true or false
        local esp = getgenv().ESP
        if esp and esp.HasForceField then
            record.ForceField = esp:HasForceField(character)
        else
            local flag = character:FindFirstChildOfClass('ForceField')
                or character:FindFirstChild('FORCEFIELD')
                or character:FindFirstChild('Forcefield')
                or character:FindFirstChild('ForceField')
            record.ForceField = flag ~= nil and (not flag:IsA('BoolValue') or flag.Value ~= false)
        end
        if sources == nil then
            Data.ActiveTarget = record
        end
        return record
    end
    function phowg:get_presentation_target()
        local values = Options.target_hud_sources and Options.target_hud_sources.Value
        local record = phowg:get_active_target(values)
        return record and record.Player or nil
    end
