    function phowg:player_country(player)
        local value = player and player:GetAttribute('Country')
        local code = type(value) == 'string' and value:upper():match('^%s*([A-Z][A-Z])%s*$') or nil
        return code and (Data.NotificationCountries[code] or code) or 'Unknown', code or 'Unknown'
    end
    function phowg:combat_notification(kind, player, damage, weapon, action, fallback)
        if not enabled('custom_combat_notifications') then
            return fallback
        end
        local option = Options[kind .. '_notification_template']
        local template = option and option.Value
        if type(template) ~= 'string' or not template:find('%S') then
            return fallback
        end
        local country, code = phowg:player_country(player)
        local character = player and player.Character
        local humanoid = character and character:FindFirstChildOfClass('Humanoid')
        local root = character and getroot(character)
        local localRoot = LocalPlayer.Character and getroot(LocalPlayer.Character)
        local client = Local_Data.ClientPos
        local origin = typeof(client) == 'CFrame' and client.Position or localRoot and localRoot.Position
        local function amount(value, rounded)
            value = tonumber(value) or 0
            if value ~= value or math.abs(value) == math.huge then
                value = 0
            end
            if rounded then
                return tostring(math.round(value))
            end
            return string.format('%.1f', value):gsub('%.0$', '')
        end
        local aliases = {
            name = player and (player.DisplayName or player.Name) or 'Unknown',
            display = player and (player.DisplayName or player.Name) or 'Unknown',
            username = player and player.Name or 'Unknown',
            userid = player and tostring(player.UserId) or 'Unknown',
            damage = amount(damage, true),
            country = country,
            country_code = code,
            weapon = tostring(weapon or 'unknown'),
            action = tostring(action or 'hit'),
            health = amount(humanoid and humanoid.Health),
            max_health = amount(humanoid and humanoid.MaxHealth),
            distance = root and origin and amount((root.Position - origin).Magnitude) or 'Unknown',
        }
        return (
            template:gsub('{([%w_]+)}', function(key)
                return aliases[key:lower()] or '{' .. key .. '}'
            end)
        )
    end
    function phowg:clear_target_hud()
        for _, connection in ipairs(Data.TargetHUDConnections or {}) do
            connection:Disconnect()
        end
        if Data.TargetHUDGui then
            pcall(function()
                Data.TargetHUDGui:Destroy()
            end)
        end
        Data.TargetHUDGui, Data.TargetHUDWidgets, Data.TargetHUDConnections = nil, nil, nil
        Data.TargetHUDTarget, Data.TargetHUDCharacter, Data.TargetHUDDrag, Data.TargetHUDStatsAt = nil, nil, nil, nil
    end
    local function make_ui(class, parent, properties)
        local object = Instance.new(class)
        for key, value in pairs(properties) do
            object[key] = value
        end
        object.Parent = parent
        return object
    end
    function phowg:get_target_hud()
        if
            Data.TargetHUDGui
            and Data.TargetHUDGui.Parent
            and Data.TargetHUDWidgets
            and Data.TargetHUDWidgets.Panel.Parent == Data.TargetHUDGui
        then
            return Data.TargetHUDWidgets
        end
        if tick() < (Data.TargetHUDRetryAt or 0) then
            return nil
        end
        phowg:clear_target_hud()
        local gui, widgets
        local ok = pcall(function()
            gui = Instance.new('ScreenGui')
            gui.Name, gui.IgnoreGuiInset, gui.ResetOnSpawn = 'PhowgTargetHUD', true, false
            gui.DisplayOrder, gui.ZIndexBehavior, gui.Enabled = 9900, Enum.ZIndexBehavior.Sibling, false
            local parent = CoreGui
            if gethui then
                local got, hidden = pcall(gethui)
                if got and typeof(hidden) == 'Instance' then
                    parent = hidden
                end
            end
            local attached = pcall(function()
                gui.Parent = parent
            end)
            if not attached or not gui.Parent then
                gui.Parent = LocalPlayer:FindFirstChildOfClass('PlayerGui')
            end
            if not gui.Parent then
                error('target HUD parent is unavailable')
            end
            local panel = make_ui('CanvasGroup', gui, {
                Name = 'Target',
