            local username = label(body, 'Username', 86, 33, 132, '', 13, 20)
            username.TextColor3 = Color3.fromRGB(145, 145, 155)
            local badge = make_ui('Frame', body, {
                Name = 'StatusBadge',
                Position = UDim2.fromOffset(226, 33),
