            local status = label(badge, 'Status', 0, 0, 104, '', 13, 20)
            status.TextXAlignment = Enum.TextXAlignment.Center
            local weapon = label(body, 'Weapon', 86, 56, 150, '', 13, 20)
            local function bar(name, y)
                local track = make_ui('Frame', body, {
                    Name = name,
                    Position = UDim2.fromOffset(86, y),
                    Size = UDim2.fromOffset(244, 16),
                    BorderColor3 = Color3.fromRGB(39, 39, 48),
                    BorderSizePixel = 1,
