            local healthBar, healthValue = bar('HealthBar', 81)
            local armorBar, armorValue = bar('ArmorBar', 104)
            widgets = {
                Panel = panel,
                Scale = scale,
                Width = 360,
                Height = 176,
                Avatar = avatar,
                Name = name,
                Username = username,
                Country = country,
                Status = status,
                Distance = distance,
                Weapon = weapon,
                HealthValue = healthValue,
                ArmorValue = armorValue,
                HealthBar = healthBar,
                ArmorBar = armorBar,
            }
        end)
        if not ok then
            if gui then
                pcall(function()
                    gui:Destroy()
                end)
            end
            Data.TargetHUDRetryAt = tick() + 0.5
            return nil
        end
        Data.TargetHUDGui, Data.TargetHUDWidgets, Data.TargetHUDConnections = gui, widgets, {}
        Data.TargetHUDRetryAt = nil
        local connections = Data.TargetHUDConnections
        connections[#connections + 1] = connectshared(widgets.Panel.InputBegan, function(input)
            if
                not enabled('target_hud')
                or (Options.target_hud_mode and Options.target_hud_mode.Value == 'follow target')
            then
                return
            end
            if
                input.UserInputType ~= Enum.UserInputType.MouseButton1
                and input.UserInputType ~= Enum.UserInputType.Touch
            then
                return
            end
            Data.TargetHUDDrag = {
                Input = input,
                Mouse = Vector2.new(input.Position.X, input.Position.Y),
                Position = widgets.Panel.AbsolutePosition,
            }
        end, gui, 'visuals/target HUD drag')
        connections[#connections + 1] = connectshared(UserInputService.InputChanged, function(input)
            local drag, camera = Data.TargetHUDDrag, Workspace.CurrentCamera
            if not drag or not camera then
                return
            end
            if input.UserInputType ~= Enum.UserInputType.MouseMovement and input ~= drag.Input then
                return
            end
            if
                not enabled('target_hud')
                or (Options.target_hud_mode and Options.target_hud_mode.Value == 'follow target')
            then
                Data.TargetHUDDrag = nil
                return
            end
            local position = drag.Position + Vector2.new(input.Position.X, input.Position.Y) - drag.Mouse
            local bounds = camera.ViewportSize - widgets.Panel.AbsoluteSize
            widgets.Panel.Position = UDim2.fromOffset(
                math.clamp(position.X, 0, math.max(0, bounds.X)),
                math.clamp(position.Y, 0, math.max(0, bounds.Y))
            )
        end, gui, 'visuals/target HUD drag update', 0, 'event/InputChanged', UserInputService)
        connections[#connections + 1] = connectshared(UserInputService.InputEnded, function(input)
            local drag, camera = Data.TargetHUDDrag, Workspace.CurrentCamera
            if not drag or input ~= drag.Input then
                return
            end
            Data.TargetHUDDrag = nil
            if not camera then
                return
            end
            local bounds = camera.ViewportSize - widgets.Panel.AbsoluteSize
            local position = widgets.Panel.AbsolutePosition
            if Options.target_hud_x then
                Options.target_hud_x:SetValue(math.clamp(position.X / math.max(1, bounds.X) * 100, 0, 100))
            end
            if Options.target_hud_y then
                Options.target_hud_y:SetValue(math.clamp(position.Y / math.max(1, bounds.Y) * 100, 0, 100))
            end
        end, gui, 'visuals/target HUD drag end', 0, 'event/InputEnded', UserInputService)
        return widgets
    end
    function phowg:smooth_target_hud_bars(widgets)
        if not widgets.HealthRatio then
            return
        end
        local now = tick()
        local alpha = 1 - math.exp(-18 * math.clamp(now - (widgets.SmoothAt or now), 0, 0.2))
        widgets.SmoothAt = now
        widgets.HealthDisplayed = widgets.HealthDisplayed
                and (widgets.HealthDisplayed + (widgets.HealthRatio - widgets.HealthDisplayed) * alpha)
            or widgets.HealthRatio
        widgets.ArmorDisplayed = widgets.ArmorDisplayed
                and (widgets.ArmorDisplayed + (widgets.ArmorRatio - widgets.ArmorDisplayed) * alpha)
            or widgets.ArmorRatio
        local healthWidth = math.abs(widgets.HealthDisplayed - widgets.HealthRatio) < 0.001 and widgets.HealthRatio
            or widgets.HealthDisplayed
        local armorWidth = math.abs(widgets.ArmorDisplayed - widgets.ArmorRatio) < 0.001 and widgets.ArmorRatio
            or widgets.ArmorDisplayed
        if widgets.HealthBar.Size.X.Scale ~= healthWidth then
            widgets.HealthBar.Size = UDim2.fromScale(healthWidth, 1)
        end
        if widgets.ArmorBar.Size.X.Scale ~= armorWidth then
            widgets.ArmorBar.Size = UDim2.fromScale(armorWidth, 1)
        end
    end
    function phowg:target_hud_visibility(widgets, visible)
        local now = tick()
        local elapsed = math.clamp(now - (widgets.FadeAt or now - 1 / 60), 0, 0.1)
        widgets.FadeAt = now
        local goal = visible and 1 or 0
        widgets.Visibility = Library.ReducedMotion and goal
            or (widgets.Visibility or 0) + (goal - (widgets.Visibility or 0)) * (1 - math.exp(-22 * elapsed))
        if math.abs(widgets.Visibility - goal) < 0.01 then
            widgets.Visibility = goal
        end
        local _, opacity = phowg:hud_settings()
        widgets.Panel.GroupTransparency = 1 - opacity * widgets.Visibility
        Data.TargetHUDGui.Enabled = visible or widgets.Visibility > 0.01
    end
    function phowg:hide_target_hud()
        Data.TargetHUDDrag = nil
        local widgets = Data.TargetHUDWidgets
        if widgets and Data.TargetHUDGui then
            phowg:target_hud_visibility(widgets, false)
            if not Data.TargetHUDGui.Enabled then
                Data.TargetHUDTarget = nil
            end
        end
    end
    function phowg:clear_prediction_visualization()
        local state = Data.PredictionGhost
        Data.PredictionGhost = nil
        if state then
            for _, connection in ipairs(state.Connections) do
                connection:Disconnect()
            end
            state.Model:Destroy()
        end
        for _, object in pairs(Data.PredictionDrawings or {}) do
            pcall(function()
                object:Remove()
            end)
        end
        Data.PredictionDrawings = nil
        Data.PredictionDrawingTarget, Data.PredictionDrawingCharacter = nil, nil
    end
    function phowg:prediction_target(presentation)
        local function valid(player)
            return player
                and player ~= LocalPlayer
                and player.Parent
                and player.Character
                and getroot(player.Character)
                and not isdead(player)
        end
        local held = Data.HeldGunFire
        if held and (held.Owner == 'Ragebot' or held.Owner == 'Support') and valid(held.Target) then
            return held.Target
        end
        if (rageboton() or punishmentactive()) and valid(Data.CurrentActionTarget) then
            return Data.CurrentActionTarget
        end
        if valid(presentation) then
            return presentation
        end
        if Data.TargetStrafeActive and valid(Data.TargetStrafeTarget) then
            return Data.TargetStrafeTarget
        end
        if valid(Data.RapeTarget) then
            return Data.RapeTarget
        end
        if valid(Data.StickyTarget) then
            return Data.StickyTarget
        end
        return nil
    end
    function phowg:update_prediction_markers(target, character, root, predicted)
        local camera = Workspace.CurrentCamera
        local drawings = Data.PredictionDrawings
        if not camera then
            for _, object in pairs(drawings or {}) do
                object.Visible = false
            end
            return
        end
        if not drawings then
            if not Drawing or not Drawing.new then
                return
            end
            drawings = {}
            Data.PredictionDrawings = drawings
            local ok = pcall(function()
                drawings.Actual = Drawing.new('Circle')
                drawings.Predicted = Drawing.new('Circle')
                drawings.Link = Drawing.new('Line')
                for _, object in pairs(drawings) do
                    object.Thickness = 1.5
                    object.Transparency = 1
                    object.ZIndex = 50
                end
                drawings.Actual.Radius, drawings.Predicted.Radius = 3, 6
                drawings.Actual.Filled, drawings.Predicted.Filled = false, false
            end)
            if not ok then
                phowg:clear_prediction_visualization()
                return
            end
        end
        Data.PredictionDrawingTarget, Data.PredictionDrawingCharacter = target, character
        predicted = predicted or predpos(root.Position, character, 2.5)
        local actualPoint, actualVisible = camera:WorldToViewportPoint(root.Position)
        local predictedPoint, predictedVisible = camera:WorldToViewportPoint(predicted)
        local color = Options.prediction_visualization_color and Options.prediction_visualization_color.Value
            or Library.AccentColor
        drawings.Actual.Color = Color3.fromRGB(180, 180, 180)
        drawings.Predicted.Color, drawings.Link.Color = color, color
        drawings.Actual.Position = Vector2.new(actualPoint.X, actualPoint.Y)
        drawings.Predicted.Position = Vector2.new(predictedPoint.X, predictedPoint.Y)
        drawings.Link.From, drawings.Link.To = drawings.Actual.Position, drawings.Predicted.Position
        drawings.Actual.Visible, drawings.Predicted.Visible = actualVisible, predictedVisible
        drawings.Link.Visible = actualVisible and predictedVisible and (predicted - root.Position).Magnitude > 0.01
    end
    function phowg:hide_prediction_visualization()
        if Data.PredictionGhost then
            Data.PredictionGhost.Model.Parent = nil
        end
        for _, object in pairs(Data.PredictionDrawings or {}) do
            object.Visible = false
        end
    end
    function phowg:update_prediction_visualization(target)
        if not enabled('prediction_visualization') then
            phowg:clear_prediction_visualization()
            return
        end
        local character = target and target.Parent and target.Character
        local root = character and character:FindFirstChild('HumanoidRootPart')
        if not root or isdead(target) then
            phowg:clear_prediction_visualization()
            return
        end
        local stateMotion = Data.PredictionVisualMotion
        local now = tick()
        if not stateMotion or stateMotion.Character ~= character then
            phowg:clear_prediction_visualization()
            stateMotion = { Character = character, Position = root.Position, MovingAt = -math.huge }
            Data.PredictionVisualMotion = stateMotion
        end
        local rate = phowg:resolve_target_motion(character, root)
        if (root.Position - stateMotion.Position).Magnitude > 0.03 or rate.Magnitude > 1 then
            stateMotion.MovingAt = now
        end
        stateMotion.Position = root.Position
        if now - stateMotion.MovingAt > 0.12 then
            phowg:hide_prediction_visualization()
            return
        end
        local predicted = predpos(root.Position, character, 2.5)
        if (predicted - root.Position).Magnitude < 0.05 then
            phowg:hide_prediction_visualization()
            return
        end
        if
            now - (stateMotion.RenderAt or -math.huge)
            < 1 / phowg:visual_number('prediction_preview_rate', 30, 10, 60)
        then
            return
        end
        stateMotion.RenderAt = now
        local style = Options.prediction_visualization_style and Options.prediction_visualization_style.Value
            or 'realistic'
        if style == 'circle + line' then
            if Data.PredictionGhost then
                phowg:clear_prediction_visualization()
            end
            phowg:update_prediction_markers(target, character, root, predicted)
            return
        end
        if Data.PredictionDrawings then
            phowg:clear_prediction_visualization()
        end
        local state = Data.PredictionGhost
        if not state or state.Character ~= character then
            phowg:clear_prediction_visualization()
            local model = Instance.new('Model')
            model.Name = 'PhowgPredictionGhost'
            state = { Character = character, Model = model, Parts = {}, Connections = {}, Dirty = true }
            Data.PredictionGhost = state
            local function dirty(part)
                if part:IsA('BasePart') or part:IsA('Accessory') or part:IsA('Tool') or part:IsA('SpecialMesh') then
                    state.Dirty = true
                end
            end
            state.Connections[1] = connectshared(
                character.DescendantAdded,
                dirty,
                character,
                'prediction ghost/parts added',
                0,
                'event/DescendantAdded',
                character
            )
            state.Connections[2] = connectshared(
                character.DescendantRemoving,
                dirty,
                character,
                'prediction ghost/parts removed',
                0,
                'event/DescendantRemoving',
                character
            )
        end
        if state.Quality ~= Data.CosmeticQuality then
            state.Dirty = true
            state.Quality = Data.CosmeticQuality
        end
        if state.Dirty then
            local present = {}
            local count = 0
            local limit = math.max(8, math.floor(48 * (Data.CosmeticQuality or 1)))
            for _, part in ipairs(character:GetDescendants()) do
                if part:IsA('BasePart') and part ~= root and part.Transparency < 1 and count < limit then
                    count += 1
                    present[part] = true
                    if not state.Parts[part] then
                        local archivable = part.Archivable
                        part.Archivable = true
                        local ok, ghost = pcall(part.Clone, part)
                        part.Archivable = archivable
                        if ok and ghost then
                            for _, child in ipairs(ghost:GetChildren()) do
                                if child:IsA('SpecialMesh') then
                                    child.TextureId = ''
                                    for _, nested in ipairs(child:GetChildren()) do
                                        nested:Destroy()
                                    end
                                else
                                    child:Destroy()
                                end
                            end
                            if ghost:IsA('MeshPart') then
                                ghost.TextureID = ''
                            end
                            ghost.Anchored, ghost.CanCollide, ghost.CanTouch, ghost.CanQuery = true, false, false, false
                            ghost.CastShadow, ghost.Massless, ghost.LocalTransparencyModifier = false, true, 0
                            ghost.Material = Enum.Material.ForceField
                            ghost.Parent = state.Model
                            state.Parts[part] = ghost
                        end
                    end
                end
            end
            for part, ghost in pairs(state.Parts) do
                if not present[part] then
                    ghost:Destroy()
                    state.Parts[part] = nil
                end
            end
            state.Dirty = false
        end
        local position = predicted
        local lead = position - root.Position
        local color = Options.prediction_visualization_color and Options.prediction_visualization_color.Value
            or Library.AccentColor
        for part, ghost in pairs(state.Parts) do
            if part.Parent and part:IsDescendantOf(character) and part.Transparency < 1 then
                ghost.CFrame = part.CFrame + lead
                ghost.Size, ghost.Color, ghost.Transparency = part.Size, color, 0.6
            else
                ghost.Transparency = 1
            end
        end
        state.Model.Parent = Workspace:FindFirstChild('Ignored') or Workspace
        state.Target, state.Position = target, position
    end
    phowg:register_cleanup('prediction visualization', function(scope)
        local state = Data.PredictionGhost
        if
            not scope
            or state and (scope == state.Character or scope == state.Target)
            or scope == Data.PredictionDrawingTarget
            or scope == Data.PredictionDrawingCharacter
        then
            phowg:clear_prediction_visualization()
        end
        Data.SmartAttackSamples = nil
    end)
    function phowg:update_target_hud(target)
        if not enabled('target_hud') or not target or Data.IsRespawning then
            phowg:hide_target_hud()
            return
        end
        local camera, character = Workspace.CurrentCamera, target.Character
        local root = character and character:FindFirstChild('HumanoidRootPart')
        local humanoid = character and character:FindFirstChildOfClass('Humanoid')
        if not camera or not root or not humanoid then
            phowg:hide_target_hud()
            return
        end
        local widgets = phowg:get_target_hud()
        if not widgets then
            return
        end
        if Data.TargetHUDTarget and (Data.TargetHUDTarget ~= target or Data.TargetHUDCharacter ~= character) then
            phowg:target_hud_visibility(widgets, false)
            if widgets.Visibility > 0.03 then
                return
            end
        end
        local viewport = camera.ViewportSize
        local scale = phowg:hud_settings()
        local follow = Options.target_hud_mode and Options.target_hud_mode.Value == 'follow target'
        if follow then
            scale = scale * 0.8
        end
        scale =
            math.min(scale, math.max(1, viewport.X - 8) / widgets.Width, math.max(1, viewport.Y - 8) / widgets.Height)
        widgets.Scale.Scale = scale
        local bounds = Vector2.new(
            math.max(0, viewport.X - widgets.Width * scale),
            math.max(0, viewport.Y - widgets.Height * scale)
        )
        if follow then
            Data.TargetHUDDrag = nil
            local feet = root.Position - Vector3.new(0, math.max(3, (humanoid.HipHeight or 0) + root.Size.Y * 0.5), 0)
            local point, visible = camera:WorldToViewportPoint(feet)
            if not visible then
                phowg:hide_target_hud()
                return
            end
            widgets.Panel.Position = UDim2.fromOffset(
                math.clamp(point.X - widgets.Width * scale * 0.5, 0, bounds.X),
                math.clamp(point.Y + 12, 0, bounds.Y)
            )
        elseif not Data.TargetHUDDrag then
            widgets.Panel.Position = UDim2.fromOffset(
                bounds.X * number('target_hud_x', 50, 0, 100) / 100,
                bounds.Y * number('target_hud_y', 70, 0, 100) / 100
            )
        end
        phowg:target_hud_visibility(widgets, true)
        if Data.TargetHUDTarget ~= target or Data.TargetHUDCharacter ~= character then
            Data.TargetHUDTarget, Data.TargetHUDCharacter = target, character
            widgets.ArmorMaximum = nil
            widgets.Avatar.Image = phowg:is_zombie_target(target) and ''
                or 'rbxthumb://type=AvatarHeadShot&id=' .. tostring(target.UserId) .. '&w=150&h=150'
            Data.TargetHUDStatsAt = nil
            widgets.HealthRatio, widgets.ArmorRatio = nil, nil
            widgets.HealthDisplayed, widgets.ArmorDisplayed, widgets.SmoothAt = nil, nil, nil
        end
        if tick() < (Data.TargetHUDStatsAt or 0) then
            phowg:smooth_target_hud_bars(widgets)
            return
        end
        Data.TargetHUDStatsAt = tick() + 0.1
        local maximum = math.max(1, humanoid.MaxHealth)
        local health = math.clamp(humanoid.Health, 0, maximum)
        local effects = character:FindFirstChild('BodyEffects')
        local armorValue = effects and effects:FindFirstChild('Armor')
        local armor = tonumber(armorValue and armorValue.Value) or 0
        if armor ~= armor or math.abs(armor) == math.huge then
            armor = 0
        end
        armor = math.max(0, armor)
        widgets.Name.Text = target.DisplayName or target.Name
        widgets.Username.Text = '@' .. target.Name
        local country = phowg:player_country(target)
        widgets.Country.Text = country
        widgets.HealthValue.Text = string.format('HP %d / %d', math.round(health), math.round(maximum))
        local armorMaximum = math.max(widgets.ArmorMaximum or 100, armor > 100 and 130 or 100)
        widgets.ArmorMaximum = armorMaximum
        widgets.ArmorValue.Text = string.format('AP %d / %d', math.round(armor), armorMaximum)
        local localRoot = LocalPlayer.Character and getroot(LocalPlayer.Character)
        local clientCF = Data.CSyncTable and Data.CSyncTable[2] and Data.CSyncTable[1] or Local_Data.ClientPos
        local origin = typeof(clientCF) == 'CFrame' and clientCF.Position
            or localRoot and localRoot.Position
            or camera.CFrame.Position
        local distance = (root.Position - origin).Magnitude
        widgets.Distance.Text = string.format('%d studs', math.floor(distance))
        local dead = humanoid.Health <= 0
        local downed = not dead and isknocked(target)
        local protected = not dead and not downed and character:FindFirstChildOfClass('ForceField') ~= nil
        widgets.Status.Text = dead and 'DEAD' or downed and 'DOWNED' or protected and 'PROTECTED' or 'ALIVE'
        widgets.Status.TextColor3 = dead and Color3.fromRGB(150, 150, 160)
            or downed and Color3.fromRGB(245, 184, 95)
            or protected and Color3.fromRGB(144, 187, 245)
            or Color3.fromRGB(113, 221, 151)
        local tool = character:FindFirstChildOfClass('Tool')
        widgets.Weapon.Text = tool and tool.Name or 'Unarmed'
        local healthColor = Color3.fromRGB(245, 80, 90):Lerp(Color3.fromRGB(80, 225, 130), health / maximum)
        local armorColor = Options.target_hud_color and Options.target_hud_color.Value
            or Library.AccentColor
            or Color3.fromRGB(100, 170, 255)
        widgets.HealthBar.BackgroundColor3 = healthColor
        widgets.ArmorBar.BackgroundColor3 = armorColor
        widgets.HealthRatio, widgets.ArmorRatio = health / maximum, math.clamp(armor / armorMaximum, 0, 1)
        phowg:smooth_target_hud_bars(widgets)
    end
    function phowg:release_afterimage_slot(slot)
        if not slot then
            return
        end
        if slot.Active then
            Data.AfterimageActiveCount = math.max(0, (Data.AfterimageActiveCount or 0) - 1)
            slot.Active = nil
        end
        phowg:release_visual(slot)
    end
    function phowg:trim_afterimage_limit(reserve, exclude)
        local limit = math.floor(number('afterimages_total_limit', 48, 4, 128)) - (reserve or 0)
        while (Data.AfterimageActiveCount or 0) > limit do
            local oldest
            for _, state in pairs(Data.AfterimageStates or {}) do
                for _, slot in ipairs(state.Slots) do
                    if slot.Active and slot ~= exclude and (not oldest or (slot.At or 0) < (oldest.At or 0)) then
                        oldest = slot
                    end
                end
            end
            if not oldest then
                break
            end
            oldest.Model.Parent, oldest.Dormant = nil, true
            phowg:release_afterimage_slot(oldest)
        end
    end
    function phowg:afterimage_part_key(part)
        local mesh = part:FindFirstChildOfClass('SpecialMesh')
        return part.ClassName
            .. '|'
            .. (part:IsA('MeshPart') and tostring(part.MeshId) or '')
            .. '|'
            .. (mesh and tostring(mesh.MeshId) .. '/' .. tostring(mesh.MeshType) .. '/' .. tostring(mesh.Scale) or '')
    end
    function phowg:recycle_afterimage_part(slot, part, ghost)
        slot.Spares = slot.Spares or {}
        if ghost.Parent == slot.Model and #slot.Spares < 16 then
            ghost.Transparency = 1
            slot.Spares[#slot.Spares + 1] = { Key = slot.PartKeys and slot.PartKeys[part], Part = ghost }
        else
            ghost:Destroy()
        end
        slot.Parts[part] = nil
        if slot.PartKeys then
            slot.PartKeys[part] = nil
        end
    end
    function phowg:clear_afterimages(role)
        local states = Data.AfterimageStates
        if states then
            for name, state in pairs(states) do
                if not role or name == role then
                    states[name] = nil
                    state.Released = true
                    for _, connection in pairs(state.Connections or {}) do
                        connection:Disconnect()
                    end
                    for _, connection in pairs(state.CharacterConnections or {}) do
                        connection:Disconnect()
                    end
                    for _, slot in pairs(state.Slots or {}) do
                        phowg:release_afterimage_slot(slot)
                        if slot.Model then
                            pcall(function()
                                slot.Model:Destroy()
                            end)
                        end
                    end
                    state.Connections, state.CharacterConnections, state.Slots = {}, {}, {}
                    state.Parts, state.CaptureParts, state.HatIndices, state.Root = {}, {}, {}, nil
                end
            end
        end
        if not role then
            Data.AfterimageStates, Data.AfterimageElapsed, Data.AfterimageSourcesAt, Data.AfterimageSourceKey =
                nil, nil, nil, nil
            Data.AfterimageActiveCount = 0
            Data.AfterimageTargetCharacter, Data.AfterimageLocalCharacter, Data.AfterimageCloneBudget = nil, nil, nil
            Data.AfterimageSources, Data.AfterimageOrder, Data.AfterimageRoster, Data.AfterimageRosterAt, Data.AfterimageCursor =
                nil, nil, nil, nil, nil
        end
    end
    local function afterimage_state(role, character)
        Data.AfterimageStates = Data.AfterimageStates or {}
        local state = Data.AfterimageStates[role]
        if state and state.Character == character then
            return state
        end
        phowg:clear_afterimages(role)
        state = {
            Character = character,
            Slots = {},
            Connections = {},
            CharacterConnections = {},
            Parts = {},
            CaptureParts = {},
            HatIndices = {},
            Released = false,
            Dirty = true,
            RefsDirty = true,
            Next = 1,
            At = 0,
        }
        Data.AfterimageStates[role] = state
        local function dirty(object)
            if
                not state.Released
                and (
                    object:IsA('BasePart')
                    or object:IsA('Humanoid')
                    or object:IsA('SpecialMesh')
                    or object:IsA('Accessory')
                    or object:IsA('Tool')
                )
            then
                state.Dirty, state.RefsDirty = true, true
            end
        end
        state.Connections[1] = connectshared(
            character.DescendantAdded,
            dirty,
            character,
            'visuals/afterimage parts added',
            0,
            'event/DescendantAdded',
            character
        )
        state.Connections[2] = connectshared(
            character.DescendantRemoving,
            dirty,
            character,
            'visuals/afterimage parts removed',
            0,
            'event/DescendantRemoving',
            character
        )
        return state
    end
    local function capture_afterimage(state, root, now, count, lifetime, color, transparency, material)
        if state.Released or not enabled('character_afterimages') then
            return false
        end
        if state.Dirty then
            table.clear(state.Parts)
            for _, part in ipairs(state.Character:GetChildren()) do
                if part:IsA('BasePart') and part ~= root and #state.Parts < 20 then
                    state.Parts[#state.Parts + 1] = part
                end
            end
            local extra = 0
            local limit = math.floor(number('afterimages_extra_budget', 8, 0, 24) * Data.CosmeticQuality)
            for _, container in ipairs(state.Character:GetChildren()) do
                local capture = (container:IsA('Accessory') and enabled('afterimages_accessories'))
                    or (container:IsA('Tool') and enabled('afterimages_weapons'))
                if capture and extra < limit then
                    for _, part in ipairs(container:GetDescendants()) do
                        if part:IsA('BasePart') and extra < limit then
                            state.Parts[#state.Parts + 1] = part
                            extra += 1
                        end
                    end
                end
            end
            state.Dirty = false
        end
        if #state.Parts == 0 then
            return
        end
        local rootCF = root.CFrame
        local clientCF = rootCF
        if
            state.Character == LocalPlayer.Character
            and (Data.CSyncTable[2] or Data.MoveToInFlight == root)
            and typeof(Data.CSyncTable[1]) == 'CFrame'
        then
            clientCF = Data.CSyncTable[1]
        end
        local position = clientCF.Position
        if
            position.X ~= position.X
            or position.Y ~= position.Y
            or position.Z ~= position.Z
            or position.Magnitude >= 1e8
        then
            return
        end
        if
            enabled('afterimages_movement_only')
            and state.LastCF
            and (position - state.LastCF.Position).Magnitude < number('afterimages_spacing', 0.1, 0.05, 12)
            and clientCF.LookVector:Dot(state.LastCF.LookVector) > 0.999
        then
            return
        end
        state.Next = (state.Next - 1) % count + 1
        local slot = state.Slots[state.Next]
        if slot and not slot.Model.Parent and not slot.Dormant then
            phowg:release_afterimage_slot(slot)
            slot.Model:Destroy()
            state.Slots[state.Next] = nil
            slot = nil
        end
        if not slot then
            local model = Instance.new('Model')
            model.Name = 'PhowgAfterimage'
            slot = { Model = model, Parts = {}, PartKeys = {}, Spares = {}, Present = {}, Dormant = true }
            state.Slots[state.Next] = slot
        end
        phowg:trim_afterimage_limit(slot.Active and 0 or 1, slot)
        local present, captureParts, hatIndices = slot.Present, state.CaptureParts, state.HatIndices
        table.clear(present)
        table.clear(captureParts)
        table.clear(hatIndices)
        slot.HatParts = slot.HatParts or {}
        table.clear(slot.HatParts)
        for _, part in ipairs(state.Parts) do
            captureParts[#captureParts + 1] = part
        end
        local head = state.Head
        local hat = state.Character == LocalPlayer.Character and head and Data.ChinaHats and Data.ChinaHats[head]
        local hatParts = enabled('china_hat') and hat and hat.parts or nil
        local hatSettings = hatParts and phowg:china_hat_settings()
        local hatMode = Options.china_hat_mode and Options.china_hat_mode.Value or 'self'
        if hatMode == 'others' then
            hatParts = nil
        end
        if hatParts then
            state.HadHat = true
            for index, part in ipairs(hatParts) do
                if part.Parent and #captureParts < #state.Parts + #hatParts then
                    hatIndices[part] = index
                    captureParts[#captureParts + 1] = part
                end
            end
        end
        local headCF = head and clientCF * rootCF:ToObjectSpace(head.CFrame)
        local cap = math.max(1, math.floor(24 * Data.CosmeticQuality))
        if #captureParts > 20 + cap + 40 then
            return false
        end
        for _, part in ipairs(captureParts) do
            local previous = slot.Parts[part]
            if previous and previous.Parent ~= slot.Model then
                previous:Destroy()
                slot.Parts[part] = nil
            end
            if part.Parent and part.Transparency < 1 and not slot.Parts[part] then
                local key, ghost = phowg:afterimage_part_key(part)
                for index = #slot.Spares, 1, -1 do
                    local spare = slot.Spares[index]
                    if spare.Key == key and spare.Part.Parent == slot.Model then
                        ghost = spare.Part
                        table.remove(slot.Spares, index)
                        break
                    end
                end
                local ok = ghost ~= nil
                if not ghost then
                    if (Data.AfterimageCloneBudget or 0) <= 0 then
                        return false
                    end
                    Data.AfterimageCloneBudget -= 1
                    local archivable = part.Archivable
                    part.Archivable = true
                    ok, ghost = pcall(part.Clone, part)
                    part.Archivable = archivable
                end
                if ok and ghost then
                    slot.PartKeys[part] = key
                    for _, child in ipairs(ghost:GetChildren()) do
                        if child:IsA('SpecialMesh') then
                            child.TextureId = ''
                            for _, nested in ipairs(child:GetChildren()) do
                                nested:Destroy()
                            end
                        else
                            child:Destroy()
                        end
                    end
                    if ghost:IsA('MeshPart') then
                        ghost.TextureID = ''
                    end
                    ghost.Anchored, ghost.CanCollide, ghost.CanTouch, ghost.CanQuery = true, false, false, false
                    ghost.CastShadow, ghost.Massless, ghost.LocalTransparencyModifier = false, true, 0
                    ghost.Transparency = 1
                    ghost.Parent = slot.Model
                    slot.Parts[part] = ghost
                end
            end
        end
        if not phowg:acquire_visual(slot, #captureParts, 'afterimages') then
            return false
        end
        if not slot.Active then
            slot.Active = true
            Data.AfterimageActiveCount = (Data.AfterimageActiveCount or 0) + 1
        end
        if state.Released or not enabled('character_afterimages') then
            phowg:release_afterimage_slot(slot)
            return false
        end
        slot.Model.Parent, slot.Dormant = Workspace:FindFirstChild('Ignored') or Workspace, false
        state.LastCF = clientCF
        local transform = clientCF * rootCF:Inverse()
        for _, part in ipairs(captureParts) do
            local hatIndex = hatIndices[part]
            if (part:IsDescendantOf(state.Character) or hatIndex) and part.Parent and part.Transparency < 1 then
                present[part] = true
                local ghost = slot.Parts[part]
                if ghost and ghost.Parent ~= slot.Model then
                    pcall(function()
                        ghost:Destroy()
                    end)
                    ghost = nil
                    slot.Parts[part] = nil
                end
                if ghost then
                    if ghost.Size ~= part.Size then
                        ghost.Size = part.Size
                    end
                    if ghost.Color ~= color then
                        ghost.Color = color
                    end
                    if ghost.Material ~= material then
                        ghost.Material = material
                    end
                    ghost.CFrame = hatIndex
                            and phowg:china_hat_part_c_frame(headCF, head.Size.Y, hatIndex, #hatParts, hatSettings)
                        or transform * part.CFrame
                    ghost.Transparency = transparency
                    if hatIndex then
                        ghost.LocalTransparencyModifier = Data.ChinaHatFirstPerson and 1 or 0
                        slot.HatParts[#slot.HatParts + 1] = ghost
                    end
                end
            end
        end
        for part, ghost in pairs(slot.Parts) do
            if not present[part] then
                phowg:recycle_afterimage_part(slot, part, ghost)
            end
        end
        slot.At, slot.Lifetime, slot.Transparency, slot.Fade = now, lifetime, transparency, transparency
        slot.HatHidden = Data.ChinaHatFirstPerson == true
        state.Next = state.Next % count + 1
        return true
    end
    function phowg:update_afterimages(target, delta)
        if not enabled('character_afterimages') or Data.IsRespawning then
            if Data.AfterimageStates then
                phowg:clear_afterimages()
            end
            return
        end
        local elapsed = (Data.AfterimageElapsed or 0) + (tonumber(delta) or 1 / 60)
        if elapsed < 1 / 30 then
            Data.AfterimageElapsed = elapsed
            return
        end
        Data.AfterimageElapsed = elapsed % (1 / 30)
        local values = Options.afterimages_sources and Options.afterimages_sources.Value or { 'local player' }
        local now = tick()
        local sources = Data.AfterimageSources or {}
        local order = Data.AfterimageOrder or {}
        Data.AfterimageSources, Data.AfterimageOrder = sources, order
        Data.AfterimageCloneBudget = 24
        phowg:trim_afterimage_limit()
        local everyone = selected(values, 'everyone')
        local selfOn = everyone or selected(values, 'local player') or selected(values, 'self only')
        local targetOn = not everyone and selected(values, 'current target')
        local targetCharacter = targetOn and target and target.Character or nil
        local localCharacter = LocalPlayer.Character
        local sourceKey = tostring(everyone) .. tostring(selfOn) .. tostring(targetOn)
        if
            now >= (Data.AfterimageSourcesAt or 0)
            or Data.AfterimageSourceKey ~= sourceKey
            or Data.AfterimageTargetCharacter ~= targetCharacter
            or Data.AfterimageLocalCharacter ~= localCharacter
        then
            Data.AfterimageSourcesAt, Data.AfterimageSourceKey = now + 0.2, sourceKey
            Data.AfterimageTargetCharacter, Data.AfterimageLocalCharacter = targetCharacter, localCharacter
            table.clear(sources)
            table.clear(order)
            local function add(role, character)
                if character and character.Parent then
                    sources[role] = character
                    order[#order + 1] = role
                end
            end
            if selfOn then
                add('local player', localCharacter)
            end
            if everyone then
                if not Data.AfterimageRoster or now >= (Data.AfterimageRosterAt or 0) then
                    Data.AfterimageRoster = Players:GetPlayers()
                    Data.AfterimageRosterAt = now + 0.5
                end
                for _, player in ipairs(Data.AfterimageRoster) do
                    if player ~= LocalPlayer and player.Parent then
                        add(player, player.Character)
                    end
                end
            elseif targetCharacter then
                add('current target', targetCharacter)
            end
        end
        local count = math.floor(number('afterimages_count', 8, 1, 12))
        local interval = number('afterimages_interval', 0.12, 0.05, 1) / Data.CosmeticQuality
        local lifetime = number('afterimages_lifetime', 0.8, 0.1, 3)
        local transparency = number('afterimages_transparency', 0.6, 0, 1)
        local color = Options.afterimages_color and Options.afterimages_color.Value or Color3.fromRGB(100, 170, 255)
        local material = Options.afterimages_material
                and Options.afterimages_material.Value == 'forcefield'
                and Enum.Material.ForceField
            or Enum.Material.Neon
        for role, state in pairs(Data.AfterimageStates or {}) do
            if sources[role] ~= state.Character then
                phowg:clear_afterimages(role)
            end
        end
        for _, role in ipairs(order) do
            local character = sources[role]
            local state = afterimage_state(role, character)
            if state.RefsDirty then
                state.Root, state.Head, state.Humanoid =
                    character:FindFirstChild('HumanoidRootPart'),
                    character:FindFirstChild('Head'),
                    character:FindFirstChildOfClass('Humanoid')
                state.RefsDirty = false
            end
            local root, humanoid = state.Root, state.Humanoid
            state.Ready = character.Parent
                and root
                and root.Parent
                and humanoid
                and humanoid.Parent
                and humanoid.Health > 0
            if state.Ready then
                for index = #state.Slots, count + 1, -1 do
                    phowg:release_afterimage_slot(state.Slots[index])
                    state.Slots[index].Model:Destroy()
                    state.Slots[index] = nil
                end
                for _, slot in ipairs(state.Slots) do
                    if slot.At and not slot.Dormant then
                        local fade = math.clamp((now - slot.At) / slot.Lifetime, 0, 1)
                        if fade >= 1 then
                            slot.Model.Parent, slot.Dormant, slot.Fade = nil, true, 1
                            phowg:release_afterimage_slot(slot)
                        else
                            local alpha = math.floor((slot.Transparency + (1 - slot.Transparency) * fade) * 100 + 0.5)
                                / 100
                            if slot.Fade ~= alpha then
                                for _, ghost in pairs(slot.Parts) do
                                    if ghost.Parent then
                                        ghost.Transparency = alpha
                                    end
                                end
                                slot.Fade = alpha
                            end
                        end
                    end
                end
            elseif not character.Parent then
                phowg:clear_afterimages(role)
            else
                state.LastCF = nil
                for _, slot in ipairs(state.Slots) do
                    if not slot.Dormant then
                        slot.Model.Parent, slot.Dormant = nil, true
                        phowg:release_afterimage_slot(slot)
                    end
                end
            end
        end
        local captured = 0
        for _ = 1, #order do
            local index = ((Data.AfterimageCursor or 1) - 1) % #order + 1
            Data.AfterimageCursor = index % #order + 1
            local state = Data.AfterimageStates and Data.AfterimageStates[order[index]]
            if state and state.Ready and now >= state.At then
                state.At = now + interval
                if capture_afterimage(state, state.Root, now, count, lifetime, color, transparency, material) then
                    captured += 1
                elseif (Data.AfterimageCloneBudget or 0) <= 0 then
                    state.At = now
                end
                if captured >= 4 or (Data.AfterimageCloneBudget or 0) <= 0 then
                    break
                end
            end
        end
    end
    function phowg:update_target_presentation(delta)
        if Data.SharedSignalsClosed or Library.Unloaded then
            return
        end
        phowg:update_china_hat_visibility()
        local needsTarget = enabled('prediction_visualization') or enabled('character_afterimages')
        local record = needsTarget and phowg:get_active_target()
        local target = record and record.Player
        local hudTarget = enabled('target_hud') and phowg:get_presentation_target() or nil
        phowg:update_target_hud(hudTarget)
        phowg:update_prediction_visualization(phowg:prediction_target(target))
        phowg:update_afterimages(target, delta)
    end
    phowg:register_cleanup('target presentation', function(scope, reason)
        Data.ActiveTarget, Data.ActiveTargetAt = nil, nil
        if reason == 'unload' or not scope then
            phowg:clear_target_hud()
            phowg:clear_afterimages()
            return
        end
        if scope == LocalPlayer.Character or scope == Data.ManagedCharacter then
            if Data.TargetHUDGui then
                Data.TargetHUDGui.Enabled = false
            end
            Data.TargetHUDTarget, Data.TargetHUDDrag = nil, nil
            phowg:clear_afterimages()
        else
            for role, state in pairs(Data.AfterimageStates or {}) do
                if state.Character == scope then
                    phowg:clear_afterimages(role)
                end
            end
            if Data.TargetHUDTarget and Data.TargetHUDTarget.Character == scope then
                Data.TargetHUDTarget, Data.TargetHUDDrag = nil, nil
                if Data.TargetHUDGui then
                    Data.TargetHUDGui.Enabled = false
                end
            end
        end
    end)
end
function gettargetvisualring()
    local ring = Data['TargetVisualRing']
    if ring and ring.Parent then
        return ring
    end
    local oldRing = Workspace:FindFirstChild('PhowgTargetVisualRing')
    if oldRing then
        oldRing:Destroy()
    end
    ring = Instance.new('Model')
    phowg:acquire_visual(ring, 48, 'target ring')
    ring.Name = 'PhowgTargetVisualRing'
    ring.Parent = Workspace
    Data['TargetVisualRing'] = ring
    Data['TargetVisualRingParts'] = {}
    for index = 1, 48 do
        local part = Instance.new('Part')
        part.Anchored = true
        part.CanCollide = false
        part.CanQuery = false
        part.CanTouch = false
        part.CastShadow = false
        part.Material = Enum.Material.Neon
        part.Shape = Enum.PartType.Ball
        part.Size = Vector3.new(0.18, 0.18, 0.18)
        part.Transparency = 1
        part.Parent = ring
        Data['TargetVisualRingParts'][index] = part
    end
    return ring
end
function phowg:target_visual_aura_style()
    local style = Options.target_visual_aura and Options.target_visual_aura.Value
    if
        style == 'wavy circle'
        or style == 'full circle'
        or style == 'twin ring'
        or style == 'pulse ring'
        or style == 'swirl'
        or style == 'bubble'
        or style == 'rain'
        or style == 'air'
    then
        return style
    end
    return nil
end
function phowg:get_target_visual_highlight()
    local highlight = Data.TargetVisualHighlight
    if highlight and highlight.Parent then
        return highlight
    end
    if highlight then
        pcall(highlight.Destroy, highlight)
    end
    local container = Data.TargetVisualHighlightContainer
    if not container or not container.Parent then
        container = Instance.new('Folder')
        container.Name = 'PhowgTargetVisuals'
        container.Parent = Workspace
        Data.TargetVisualHighlightContainer = container
    end
    highlight = Instance.new('Highlight')
    highlight.Name = 'PhowgTargetHighlight'
    highlight.Enabled = false
    highlight.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
    highlight.FillTransparency = 0.5
    highlight.OutlineTransparency = 0
    highlight.Parent = container
    Data.TargetVisualHighlight = highlight
    return highlight
end
function phowg:hide_target_visual_highlight()
    local highlight = Data.TargetVisualHighlight
    if highlight then
        if highlight.Enabled then
            highlight.Enabled = false
        end
        if highlight.Adornee and not highlight.Adornee.Parent then
            highlight.Adornee = nil
        end
    end
end
function phowg:prepare_target_visuals()
    if
        Library.Unloaded
        or Data.Unloading
        or Data.SharedSignalsClosed
        or not (Toggles.target_visuals and Toggles.target_visuals.Value)
    then
        return
    end
    if Toggles.target_visual_highlight and Toggles.target_visual_highlight.Value then
        phowg:get_target_visual_highlight()
    end
    local style = phowg:target_visual_aura_style()
    if style == 'wavy circle' or style == 'full circle' or style == 'twin ring' or style == 'pulse ring' then
        gettargetvisualring()
    end
end
function phowg:apply_target_visual_highlight(character, color)
    local highlight = phowg:get_target_visual_highlight()
    local fill = Options.target_visual_highlight_fill and Options.target_visual_highlight_fill.Value or color
    local outline = Options.target_visual_highlight_outline and Options.target_visual_highlight_outline.Value
        or Color3.new(1, 1, 1)
    if highlight.Adornee ~= character then
        highlight.Adornee = character
    end
    if highlight.FillColor ~= fill then
        highlight.FillColor = fill
    end
    if highlight.OutlineColor ~= outline then
        highlight.OutlineColor = outline
    end
    if highlight.FillTransparency ~= 0.5 then
        highlight.FillTransparency = 0.5
    end
    if highlight.OutlineTransparency ~= 0 then
        highlight.OutlineTransparency = 0
    end
    if not highlight.Enabled then
        highlight.Enabled = true
    end
end
function hidetargetvisuals()
    local line = Data['TargetVisualTracer']
    if line then
        line.Visible = false
    end
    for _, part in ipairs(Data['TargetVisualRingParts'] or {}) do
        if part and part.Parent then
            part.Transparency = 1
        end
    end
    local tap = Data['TargetAuraPart']
    if tap then
        phowg:release_visual(tap)
        pcall(function()
            tap:Destroy()
        end)
    end
    Data['TargetAuraPart'] = nil
    Data['TargetAuraKey'] = nil
    phowg:hide_target_visual_highlight()
end
function update_target_aura(target, character, torso, auraStyle, color)
    local map = { swirl = 'Swirl', bubble = 'Bubble', rain = 'Rain', air = 'Air' }
    local tkey = map[auraStyle]
    local wantKey = tostring(target and target.UserId or 0) .. '|' .. tostring(auraStyle)
    local ap = Data['TargetAuraPart']
    if torso and not phowg:cosmetic_visible(torso.Position) then
        if ap then
            ap:Destroy()
            phowg:release_visual(ap)
            Data.TargetAuraPart = nil
        end
        return
    end
    if Data['TargetAuraKey'] ~= wantKey or not ap or not ap.Parent then
        if ap then
            phowg:release_visual(ap)
            pcall(function()
                ap:Destroy()
            end)
        end
        Data['TargetAuraPart'] = nil
        Data['TargetAuraKey'] = wantKey
        if not (target and character and torso and torso.Parent and tkey) then
            return
        end
        local tmpl = Data['AuraTemplates'] and Data['AuraTemplates'][tkey] or nil
        if not tmpl then
            return
        end
        ap = Instance.new('Part')
        phowg:acquire_visual(ap, #tmpl * 15, 'target particles')
        ap.Name = 'PhowgTargetAura'
        ap.Size = Vector3.new(0.01, 0.01, 0.01)
        ap.Transparency = 1
        ap.Anchored = true
        ap.CanCollide = false
        ap.CanQuery = false
        ap.CanTouch = false
        ap.CastShadow = false
        ap.CFrame = torso.CFrame
        ap.Parent = Workspace
        Data['TargetAuraPart'] = ap
        for _, props in ipairs(tmpl) do
            local e = Instance.new('ParticleEmitter')
            for k, v in pairs(props) do
                e[k] = v
            end
            e.Color = ColorSequence.new(color)
            e.Rate = e.Rate * Data.CosmeticQuality
            e.Enabled = true
            e.Parent = ap
        end
    end
    if ap and ap.Parent and torso and torso.Parent then
        ap.CFrame = torso.CFrame
    end
end
function updatetargetvisuals()
    if not (Toggles.target_visuals and Toggles.target_visuals.Value) then
        hidetargetvisuals()
        return
    end
    local tracerTarget =
        gettargetvisualtarget(Options.target_visual_tracer_sources and Options.target_visual_tracer_sources.Value)
    local tracerChar = tracerTarget and tracerTarget.Character
    local tracerTorso = tracerChar
        and (
            tracerChar:FindFirstChild('UpperTorso')
            or tracerChar:FindFirstChild('Torso')
            or tracerChar:FindFirstChild('HumanoidRootPart')
            or tracerChar:FindFirstChild('Head')
        )
    local color = Options.target_visual_color and Options.target_visual_color.Value or Color3.fromRGB(255, 70, 70)
    if
        Toggles.target_visual_tracer
        and Toggles.target_visual_tracer.Value
        and tracerTorso
        and tracerTorso:IsA('BasePart')
    then
        local line = Data['TargetVisualTracer']
        if not alivedrawing(line) then
            line = newdrawingline(color, 1.5, 10)
            Data['TargetVisualTracer'] = line
        end
        local camera = Workspace.CurrentCamera
        if line and camera then
            local point, onScreen = camera:WorldToViewportPoint(tracerTorso.Position)
            if onScreen then
                line.From = UserInputService:GetMouseLocation()
                line.To = Vector2.new(point.X, point.Y)
                line.Color = Options.target_visual_tracer_color and Options.target_visual_tracer_color.Value or color
                line.Transparency = 1
                line.Visible = true
            else
                line.Visible = false
            end
        end
    elseif Data['TargetVisualTracer'] then
        Data['TargetVisualTracer'].Visible = false
    end
    local target = gettargetvisualtarget(Options.target_visual_sources and Options.target_visual_sources.Value)
    local root = target and target.Character and target.Character:FindFirstChild('HumanoidRootPart')
    if root and not phowg:cosmetic_visible(root.Position) then
        target = nil
    end
    local character = target and target.Character
    local highlightTarget = gettargetvisualtarget()
    local highlightCharacter = highlightTarget and highlightTarget.Character
    local highlightRoot = highlightCharacter and highlightCharacter:FindFirstChild('HumanoidRootPart')
    local wantHl = Toggles.target_visual_highlight
        and Toggles.target_visual_highlight.Value
        and highlightRoot ~= nil
        and phowg:cosmetic_visible(highlightRoot.Position)
    if wantHl then
        phowg:apply_target_visual_highlight(highlightCharacter, color)
    else
        phowg:hide_target_visual_highlight()
    end
    local torso = character and (character:FindFirstChild('UpperTorso') or character:FindFirstChild('Torso'))
    local auraStyle = phowg:target_visual_aura_style()
    if not auraStyle or not torso or not torso:IsA('BasePart') then
        for _, part in ipairs(Data['TargetVisualRingParts'] or {}) do
            if part and part.Parent then
                part.Transparency = 1
            end
        end
        local tap0 = Data['TargetAuraPart']
        if tap0 then
            phowg:release_visual(tap0)
            pcall(function()
                tap0:Destroy()
            end)
        end
        Data['TargetAuraPart'] = nil
        Data['TargetAuraKey'] = nil
        return
    end
    local isParticle = auraStyle == 'swirl' or auraStyle == 'bubble' or auraStyle == 'rain' or auraStyle == 'air'
    if isParticle then
        for _, part in ipairs(Data['TargetVisualRingParts'] or {}) do
            if part and part.Parent then
                part.Transparency = 1
            end
        end
        update_target_aura(target, character, torso, auraStyle, color)
        return
    end
    if Data['TargetAuraPart'] then
        pcall(function()
            Data['TargetAuraPart']:Destroy()
        end)
        Data['TargetAuraPart'] = nil
        Data['TargetAuraKey'] = nil
    end
    if not gettargetvisualring() then
        return
    end
    local parts = Data['TargetVisualRingParts']
    local center = torso.Position
    local now = tick()
    local n = #parts
    if auraStyle == 'full circle' then
        local spin = now * 2
        for index, part in ipairs(parts) do
            if part and part.Parent then
                part.Size = Vector3.new(0.18, 0.18, 0.18)
                part.Color = color
                part.Transparency = 0
                local angle = spin + (index - 1) * math.pi * 2 / n
                part.CFrame = CFrame.new(center + Vector3.new(math.cos(angle) * 3, 0, math.sin(angle) * 3))
            end
        end
    elseif auraStyle == 'twin ring' then
        local spin = now * 4
        for index, part in ipairs(parts) do
            if part and part.Parent then
                part.Size = Vector3.new(0.16, 0.16, 0.16)
                part.Color = color
                part.Transparency = 0
                local angle, radius
                if index <= 24 then
                    angle = spin + (index - 1) * math.pi * 2 / 24
                    radius = 2.2
                else
                    angle = -spin + (index - 25) * math.pi * 2 / 24
                    radius = 3.8
                end
                part.CFrame = CFrame.new(center + Vector3.new(math.cos(angle) * radius, 0, math.sin(angle) * radius))
            end
        end
    elseif auraStyle == 'pulse ring' then
        local pulse = 0.5 + 0.5 * math.sin(now * 3)
        local radius = 2 + pulse * 2.5
        local s = 0.14 + 0.08 * pulse
        local spin = now * 1.5
        for index, part in ipairs(parts) do
            if part and part.Parent then
                part.Size = Vector3.new(s, s, s)
                part.Color = color
                part.Transparency = 0
                local angle = spin + (index - 1) * math.pi * 2 / n
                part.CFrame = CFrame.new(center + Vector3.new(math.cos(angle) * radius, 0, math.sin(angle) * radius))
            end
        end
    else
        local spin = now * 5
        local bob = math.sin(now * 3) * 0.7
        local radius = 3 + math.sin(now * 2.2) * 0.3
        for index, part in ipairs(parts) do
            if part and part.Parent then
                local s = 0.16 + 0.06 * math.sin(now * 6 + index * 0.7)
                part.Size = Vector3.new(s, s, s)
                part.Color = color
                part.Transparency = 0
                local angle = spin + (index - 1) * math.pi * 2 / n
                local y = bob + 0.25 * math.sin(now * 4 + index * 0.9)
                part.CFrame = CFrame.new(center + Vector3.new(math.cos(angle) * radius, y, math.sin(angle) * radius))
            end
        end
    end
end
function enablenorecoil()
    if Data['NoRecoilHooked'] then
        return
    end
    (function()
        local Wrap = function(f)
            return f
        end
        if newcclosure then
            Wrap = newcclosure
        end
        local norecoilorig
        norecoilorig = hookmm(
            game,
            '__newindex',
            Wrap(function(Self, Property, Value)
                if Property ~= 'CFrame' or Self ~= Workspace.CurrentCamera or checkcall() then
                    return norecoilorig(Self, Property, Value)
                end
                if localactionblocked() then
                    return norecoilorig(Self, Property, Value)
                end
                local Enabled = Toggles.no_recoil and Toggles.no_recoil.Value or false
                if Enabled and not checkcall() then
                    local CallingScript = nil
                    CallingScript = getcallingscript()
                    local Cam = Workspace.CurrentCamera
                    if CallingScript and (CallingScript.Name == 'Framework' or CallingScript.Name == 'F') then
                        if Cam and Self == Cam and Property == 'CFrame' then
                            local percent = tonumber(Options.recoil_percent and Options.recoil_percent.Value) or 0
                            local Modified = Cam.CFrame:Lerp(Value, math.clamp(percent, 0, 100) / 100)
                            return norecoilorig(Self, Property, Modified)
                        end
                    end
                end
                return norecoilorig(Self, Property, Value)
            end)
        )
        Data['NoRecoilOriginal'] = norecoilorig
        Data['NoRecoilHooked'] = true
    end)()
end
function punishmentcleantoolname(name)
    local n = tostring(name or '')
    n = n:gsub('%[', ''):gsub('%]', '')
    n = n:match('^%s*(.-)%s*$') or n
    if n == '' then
        n = 'unknown gun'
    end
    return n
end
function punishmentdescribeattack(plr, victim)
    local who = 'you'
    if typeof(victim) == 'Instance' and victim:IsA('Player') and victim ~= LocalPlayer then
        who = Library:PlayerDisplayName(victim)
    end
    if not plr then
        return 'damaged ' .. who
    end
    if Data['PunishmentHitWeapon'] then
        local snap = Data['PunishmentHitWeapon'][plr]
        if snap and snap.name and tick() - (snap.at or 0) < 5 then
            if snap.ammo then
                return 'shot ' .. who .. ' with ' .. punishmentcleantoolname(snap.name)
            end
            if string.lower(snap.name):find('knife', 1, true) then
                return 'knifed ' .. who
            end
            if string.lower(snap.name):find('combat', 1, true) then
                return 'punched ' .. who
            end
            return 'hit ' .. who .. ' with ' .. punishmentcleantoolname(snap.name)
        end
    end
    local chartools = {}
    local char = plr.Character
    if char then
        for _, t in ipairs(char:GetChildren()) do
            if t:IsA('Tool') then
                table.insert(chartools, t)
            end
        end
    end
    local function pick(list)
        for _, t in ipairs(list) do
            local hasAmmo = false
            hasAmmo = t:FindFirstChild('Ammo', true) ~= nil
            if hasAmmo then
                return 'shot ' .. who .. ' with ' .. punishmentcleantoolname(t.Name)
            end
        end
        for _, t in ipairs(list) do
            if string.lower(t.Name):find('knife', 1, true) then
                return 'knifed ' .. who
            end
        end
        for _, t in ipairs(list) do
            if string.lower(t.Name):find('combat', 1, true) then
                return 'punched ' .. who
            end
        end
        if #list > 0 then
            return 'hit ' .. who .. ' with ' .. punishmentcleantoolname(list[1].Name)
        end
        return nil
    end
    local desc = pick(chartools)
    if desc then
        return desc
    end
    local bptools = {}
    local bp = plr:FindFirstChild('Backpack')
    if bp then
        for _, t in ipairs(bp:GetChildren()) do
            if t:IsA('Tool') then
                table.insert(bptools, t)
            end
        end
    end
    desc = pick(bptools)
    if desc then
        return desc
    end
    return 'damaged ' .. who
end
function phowg:support_completion_gun(player, completed)
    if not completed or not player or not player.Parent then
        return nil
    end
    local mode = Data.PunishmentTargets and Data.PunishmentTargets[player]
    if
        not (
            mode == 'knock target' and (isknocked(player) or isstomped(player))
            or mode == 'stomp target' and isstomped(player)
        )
    then
        return nil
    end
    if
        iswhitelistedplayer(player)
        or iscrewwhitelisted(player)
        or Data.RageWhitelist and Data.RageWhitelist[player]
    then
        return nil
    end
    if Data.SupportTargetCharacters and Data.SupportTargetCharacters[player] ~= player.Character then
        return nil
    end
    local session = Data.SupportTargetSessions and Data.SupportTargetSessions[player]
    if session and session.Character == LocalPlayer.Character then
        return session.Tool
    end
    return nil
end
function phowg:finish_support_gun_reload(job, unequip)
    if not job or not Data.SupportGunReloads or Data.SupportGunReloads[job.Tool] ~= job then
        return
    end
    Data.SupportGunReloads[job.Tool] = nil
    for _, connection in ipairs(job.Connections) do
        connection:Disconnect()
    end
    table.clear(job.Connections)
    if job.Timer and job.Timer ~= coroutine.running() then
        pcall(task.cancel, job.Timer)
    end
    job.Timer = nil
    if
        unequip
        and LocalPlayer.Character == job.Character
        and job.Tool.Parent == job.Character
        and job.Backpack.Parent == LocalPlayer
    then
        phowg:stop_gun_fire(nil, job.Tool)
        pcall(function()
            phowg:deactivate_tool(job.Tool)
        end)
        local pending = Data.InventoryEquip
        if
            pending
            and pending.Tool == job.Tool
            and (not pending.SupportTarget or pending.SupportTarget == job.Target)
        then
            Data.InventoryEquip = nil
        end
        job.Tool.Parent = job.Backpack
    end
end
function phowg:reload_completed_support_gun(tool, target)
    if not tool or not tool:IsA('Tool') then
        return
    end
    local character, backpack = LocalPlayer.Character, LocalPlayer:FindFirstChild('Backpack')
    if not character or not backpack or not backpack.Parent or Library.Unloaded or localactionblocked() then
        return
    end
    if tool.Parent ~= character and tool.Parent ~= backpack then
        return
    end
    Data.SupportGunReloads = Data.SupportGunReloads or {}
    if Data.SupportGunReloads[tool] then
        return
    end
    phowg:stop_gun_fire(nil, tool)
    pcall(function()
        phowg:deactivate_tool(tool)
    end)
    local current = character:FindFirstChildOfClass('Tool')
    if tool.Parent == backpack then
        if current and current ~= tool or Data.Buying or Data.Sorting or Data.LoadoutReloadJob then
            return
        end
        equip(tool)
        if tool.Parent ~= character then
            return
        end
    end
    local remote = MainEvent or ReplicatedStorage:FindFirstChild('MainEvent')
    local ammo, maximum = tool:FindFirstChild('Ammo'), tool:FindFirstChild('MaxAmmo')
    local body = character:FindFirstChild('BodyEffects')
    local reload = body and body:FindFirstChild('Reload')
    local before = ammo and ammo.Value
    local job = {
        Tool = tool,
        Target = target,
        Character = character,
        Backpack = backpack,
        Connections = {},
        Started = reload and reload.Value == true,
        Timer = nil :: any,
    }
    Data.SupportGunReloads[tool] = job
    local function changed()
        if Data.SupportGunReloads[tool] ~= job then
            return
        end
        if
            Data.GunReloadSelection
            and Data.GunReloadSelection.Tool == tool
            and Data.GunReloadSelection.Character == character
        then
            return
        end
        if
            Library.Unloaded
            or LocalPlayer.Character ~= character
            or tool.Parent ~= character
            or localactionblocked()
        then
            phowg:finish_support_gun_reload(job, false)
            return
        end
        local active = reload and reload.Parent == body and reload.Value == true
        if active then
            job.Started = true
        end
        if not active and (job.Started or ammo and before ~= nil and ammo.Value > before) then
            phowg:finish_support_gun_reload(job, true)
        end
    end
    local function listen(signal, label)
        job.Connections[#job.Connections + 1] = connectshared(signal, changed, character, label)
    end
    if ammo then
        listen(ammo:GetPropertyChangedSignal('Value'), 'support reload/ammo')
    end
    if reload then
        listen(reload:GetPropertyChangedSignal('Value'), 'support reload/state')
    end
    listen(tool:GetPropertyChangedSignal('Parent'), 'support reload/tool')
    listen(LocalPlayer:GetPropertyChangedSignal('Character'), 'support reload/character')
    job.Timer = task.delay(8, function()
        phowg:finish_support_gun_reload(job, true)
    end)
    local ok = phowg:request_gun_reload(tool, remote)
    local capacity = maximum and maximum.Value or tool:GetAttribute('MaxAmmo')
    local reserve = getgunreserve(tool)
    if not ok or before ~= nil and capacity ~= nil and before >= capacity or reserve ~= nil and reserve <= 0 then
        phowg:finish_support_gun_reload(job, true)
    else
        changed()
    end
end
phowg:register_cleanup('support gun reload', function(scope)
    for _, job in pairs(table.clone(Data.SupportGunReloads or {})) do
        if not scope or scope == job.Character or phowg:scope_contains(scope, job.Tool) then
            phowg:finish_support_gun_reload(job, false)
        end
    end
end)
function punishmentcleartarget(plr, skipRestore, completed)
    if not plr then
        return
    end
    local completedGun = phowg:support_completion_gun(plr, completed)
    local multiSession = Data.SupportTargetSessions and Data.SupportTargetSessions[plr]
    if multiSession and multiSession.Multi then
        completedGun = nil
    end
    if Data.SupportLoadout and Data.SupportLoadout.Target == plr then
        phowg:clear_support_loadout()
    end
    phowg:cancel_pending_support(plr)
    local wasActionTarget = Data['CurrentActionTarget'] == plr
        or Data['CurrentMainTarget'] == plr
        or Data['SingleLockedTarget'] == plr
        or Data['RifleTarget'] == plr
        or Data['RapeTarget'] == plr
    if completed then
        Data['SupportCompletedTargets'] = Data['SupportCompletedTargets'] or {}
        Data['SupportCompletedTargets'][plr] = true
        Data.SupportCompletedCharacters = Data.SupportCompletedCharacters or {}
        Data.SupportCompletedCharacters[plr] = plr.Character
        Data.SupportCompletedAt = Data.SupportCompletedAt or {}
        Data.SupportCompletedAt[plr] = tick()
    end
    if Data['SupportTargetCharacters'] then
        Data['SupportTargetCharacters'][plr] = nil
    end
    if Data['SupportTargetSessions'] then
        Data['SupportTargetSessions'][plr] = nil
    end
    local FrozenRoot = Data['FrozenRoots'] and Data['FrozenRoots'][plr] or nil
    if FrozenRoot and FrozenRoot.Parent then
        FrozenRoot.Anchored = false
    end
    if Data['FrozenRoots'] then
        Data['FrozenRoots'][plr] = nil
    end
    Data['PunishmentTargets'][plr] = nil
    Data['TargetListCache'] = nil
    if Data['StompWatch'] then
        Data['StompWatch'][plr] = nil
    end
    if Data['ArrestWatch'] then
        Data['ArrestWatch'][plr] = nil
    end
    if Data['SmartStrafe'] and Data['SmartStrafe'].target == plr then
        Data['SmartStrafe'] = nil
    end
    if Data['SmartStrafeCache'] then
        Data['SmartStrafeCache'][plr] = nil
    end
    if Data['GunFocusTarget'] == plr then
        Data['GunFocusTarget'] = nil
        Data['GunFocusAt'] = nil
    end
    if Data['GunAimTarget'] == plr then
        Data['GunAimTarget'] = nil
        Data['GunAimAt'] = nil
    end
    if Data['RifleTarget'] == plr then
        Data['RifleTarget'] = nil
    end
    if Data['RifleVoidTarget'] == plr then
        Data['RifleVoidTarget'] = nil
        Data['RifleVoid'] = nil
        Data['RifleVoidFF'] = nil
        Data['RifleVoidWait'] = nil
        if not Data['ManualVoid'] and not Data.HideVoid then
            Data['VoidActive'] = false
        end
    end
    if Data['StickyMainTarget'] == plr then
        Data['StickyMainTarget'] = nil
    end
    if Data['CombatArrivalTarget'] == plr then
        Data['CombatArrivalAt'] = nil
        Data['CombatArrivalLastAt'] = nil
        Data['CombatArrivalTarget'] = nil
        Data['CombatArrivalCharacter'] = nil
        Data['CombatArrivalTool'] = nil
    end
    if Data['RapeTarget'] == plr then
        rapestopfiring()
    end
    if Data['CSync'] and Data['CSync'].Queue then
        for index = #Data['CSync'].Queue, 1, -1 do
            local tag = Data['CSync'].Queue[index].tag
            if (wasActionTarget and tag == 'Combat') or (Data['BuyingSupportTarget'] == plr and tag == 'Buy') then
                table.remove(Data['CSync'].Queue, index)
            end
        end
    end
    if wasActionTarget then
        phowg:stop_gun_fire()
        Data['MoveToActive'] = false
        Data['MoveToTargetCF'] = nil
        Data['CurrentStatus'] = 'Idle'
        local character = LocalPlayer.Character
        local tool = character and character:FindFirstChildOfClass('Tool')
        if tool then
            phowg:deactivate_tool(tool)
        end
        phowg:request_physics_rep(getreppart(character), nil)
    end
    if Data['PunishmentHitWeapon'] then
        Data['PunishmentHitWeapon'][plr] = nil
    end
    local stickyKept = Data['SilentAimStickyTargets'] and Data['SilentAimStickyTargets'][plr] or false
    if not stickyKept then
        Data['LockedTargets'][plr] = nil
        if Data['TargetWatchlist'] then
            Data['TargetWatchlist'][plr.UserId] = nil
            Data['TargetWatchlist'][plr.Name] = nil
        end
        if Data['SingleLockedTarget'] == plr then
            local nextSingle = nil
            nextSingle = phowg:next_support_target()
            if not nextSingle then
                for p, _ in pairs(Data['LockedTargets']) do
                    nextSingle = p
                    break
                end
            end
            Data['SingleLockedTarget'] = nextSingle
        end
    end
    if Data['CurrentActionTarget'] == plr then
        Data['CurrentActionTarget'] = nil
    end
    if Data['CurrentMainTarget'] == plr then
        Data['CurrentMainTarget'] = nil
    end
    phowg:select_support_head()
    applypunishmentmodes()
    if not skipRestore then
        phowg:restore_support_settings(plr)
    end
    if completedGun then
        phowg:reload_completed_support_gun(completedGun, plr)
    end
end
function phowg:restore_support_settings(plr)
    if next(Data.PunishmentTargets or {}) or next(Data.PendingSupport or {}) then
        return
    end
    if Data['PunishmentSavedToggles'] then
        local sv = Data['PunishmentSavedToggles']
        Data['PunishmentSavedToggles'] = nil
        Data['PunishmentAutoFling'] = nil

        if Toggles.auto_kill and Toggles.auto_kill.SetValue then
            Toggles.auto_kill:SetValue(sv.AutoKill and true or false)
        end
        if Toggles.auto_stomp and Toggles.auto_stomp.SetValue then
            Toggles.auto_stomp:SetValue(sv.AutoStomp and true or false)
        end
        if Toggles.auto_fling and Toggles.auto_fling.SetValue then
            Toggles.auto_fling:SetValue(sv.AutoFling and true or false)
        end
        if sv.AutoKill or sv.AutoStomp then
            ragebot_on()
        end
    end
    if Data['PunishmentPrev'] then
        local prev = Data['PunishmentPrev']
        Data['PunishmentPrev'] = nil
        local back = prev.single ~= plr and prev.single or nil
        if
            intelligence:get_character_cache(back)
            and not (Data.SupportCompletedTargets and Data.SupportCompletedTargets[back])
        then
            Data['LockedTargets'][back] = true
            if Data['TargetWatchlist'] then
                Data['TargetWatchlist'][back.UserId] = true
                Data['TargetWatchlist'][back.Name] = true
            end
            if Data['SingleLockedTarget'] == nil then
                Data['SingleLockedTarget'] = back
            end
            if Data['CurrentMainTarget'] == nil then
                Data['CurrentMainTarget'] = back
            end
            if Data['CurrentActionTarget'] == nil then
                Data['CurrentActionTarget'] = back
            end
        end
    end
end
function isfullywhitelisted(p)
    if not p then
        return false
    end
    if Data['FullWhitelist'] and Data['FullWhitelist'][p] then
        return true
    end
    if Data['RageWhitelist'] and Data['RageWhitelist'][p] then
        return true
    end
    if Data['IsraelWhitelist'] and Data['IsraelWhitelist'][p] then
        return true
    end
    if Library.SilentWhitelist and Library.SilentWhitelist[p] then
        return true
    end
    if Library.StickyWhitelist and Library.StickyWhitelist[p] then
        return true
    end
    if Library.IsraelWhitelist and Library.IsraelWhitelist[p] then
        return true
    end
    if iscrewwhitelisted(p) then
        return true
    end
    return false
end
function iswhitelistedplayer(p)
    if isfullywhitelisted(p) then
        return true
    end
    if Data['IsraelWhitelist'] == nil then
        return false
    end
    return Data['IsraelWhitelist'][p] == true
end
function whitelistfully(plr)
    if not plr then
        return
    end
    Data['FullWhitelist'] = Data['FullWhitelist'] or {}
    Data['FullWhitelist'][plr] = true
    Data['RageWhitelist'] = Data['RageWhitelist'] or {}
    Data['RageWhitelist'][plr] = true
    Data['IsraelWhitelist'] = Data['IsraelWhitelist'] or {}
    Data['IsraelWhitelist'][plr] = true
    Library.SilentWhitelist = Library.SilentWhitelist or {}
    Library.SilentWhitelist[plr] = true
    Library.StickyWhitelist = Library.StickyWhitelist or {}
    Library.StickyWhitelist[plr] = true
    Library.IsraelWhitelist = Library.IsraelWhitelist or {}
    Library.IsraelWhitelist[plr] = true
    if Data['SilentAimStickyTargets'] then
        Data['SilentAimStickyTargets'][plr] = nil
    end
    if Data['SilentAimStickyTarget'] == plr then
        Data['SilentAimStickyTarget'] = nil
    end
    if Data['SilentAimTarget'] == plr then
        Data['SilentAimTarget'] = nil
        Data['SilentAimPos'] = nil
        Data['SilentAimHitPart'] = nil
    end
    if Data['LockedTargets'] then
        Data['LockedTargets'][plr] = nil
    end
    if Data['DropdownTargets'] then
        Data['DropdownTargets'][plr] = nil
    end
    if Data['AssistLockedTarget'] == plr then
        Data['AssistLockedTarget'] = nil
        Data['AssistAimPos'] = nil
        Data['AssistAimPart'] = nil
    end
    if Data['CurrentMainTarget'] == plr then
        Data['CurrentMainTarget'] = nil
    end
    if Data['CurrentActionTarget'] == plr then
        Data['CurrentActionTarget'] = nil
    end
    pcall(function()
        purgesilentwhitelisted()
    end)
    if phowg.sync_israel_protection then
        phowg:sync_israel_protection()
    end
    pcall(function()
        Library:Notify('whitelisted fully ' .. tostring(plr.DisplayName) .. ' @' .. tostring(plr.Name), 2)
    end)
end
function unwhitelistfully(plr)
