    if Library and Library.SilentWhitelist then
        Library.SilentWhitelist[plr] = nil
    end
    if Library and Library.StickyWhitelist then
        Library.StickyWhitelist[plr] = nil
    end
    if Library and Library.IsraelWhitelist then
