    if phowg.sync_israel_protection then
        phowg:sync_israel_protection()
    end
    pcall(function()
        Library:Notify('unwhitelisted ' .. tostring(plr.DisplayName) .. ' @' .. tostring(plr.Name), 2)
    end)
end
function applypunishmentmodes()
    if not phowg:israel_support_enabled() then
        Data.PunishmentGunActive, Data.PunishmentAutoFling = nil, nil
        return
    end
    local anyFlingP = false
    local anyKnockP = false
    local anyRapeP = false
    for _, m in pairs(Data['PunishmentTargets'] or {}) do
        if m == 'fling target' then
            anyFlingP = true
        end
        if m == 'knock target' then
            anyKnockP = true
        end
        if m == 'stomp target' then
            anyRapeP = true
        end
    end
    local anyGunP = anyKnockP or anyRapeP
    Data['PunishmentGunActive'] = anyGunP and true or nil
    Data['PunishmentAutoFling'] = anyFlingP and not anyGunP and true or nil
    if not next(Data['PunishmentTargets'] or {}) then
        return
    end
    if anyGunP then
        if Toggles.auto_kill and Toggles.auto_kill.SetValue and not Toggles.auto_kill.Value then
            Toggles.auto_kill:SetValue(true)
        end
    else
        if Toggles.auto_kill and Toggles.auto_kill.Value then
            Toggles.auto_kill:SetValue(false)
        end
    end
    if Toggles.auto_stomp and Toggles.auto_stomp.SetValue and Toggles.auto_stomp.Value ~= anyRapeP then
        Toggles.auto_stomp:SetValue(anyRapeP)
    end

    if anyFlingP and not anyGunP then
        if Toggles.auto_fling and Toggles.auto_fling.SetValue and not Toggles.auto_fling.Value then
            Toggles.auto_fling:SetValue(true)
        end
    else
        if Toggles.auto_fling and Toggles.auto_fling.Value then
            Toggles.auto_fling:SetValue(false)
        end
    end
end
function phowg:cancel_pending_support(target)
    for player, pending in pairs(Data.PendingSupport or {}) do
        if not target or player == target then
            Data.PendingSupport[player] = nil
            if pending.Thread and pending.Thread ~= coroutine.running() then
                local batch = Data.PurchaseBatch
                if batch and batch.Owner == pending.Thread then
                    phowg:finish_purchases(batch, true)
                end
                pcall(task.cancel, pending.Thread)
            end
        end
    end
    if not Library.Unloaded then
        phowg:select_support_head()
        phowg:restore_support_settings()
    end
end
function punish(Damager, Damage, ForceMode, Victim, Reason)
    ForceMode = phowg:protect_player_mode()
    if not Damager or Damager == LocalPlayer or not Damager.Parent or iswhitelistedplayer(Damager) then
        return
    end
    if not phowg:support_request_allowed(Victim, Reason) then
        return
    end
    local israel = Data.IsIsraelPunish == true
    if Data.RageWhitelist and Data.RageWhitelist[Damager] and not israel then
        return
    end
    local activeMode = Data.PunishmentTargets and Data.PunishmentTargets[Damager]
    local activeSession = Data.SupportTargetSessions and Data.SupportTargetSessions[Damager]
    if
        activeMode
        and activeSession
        and activeSession.ArmorCharacter == LocalPlayer.Character
        and Data.SupportTargetCharacters
        and Data.SupportTargetCharacters[Damager] == Damager.Character
        and not supporttargetfinished(Damager, activeMode)
    then
        if activeSession.Reason == 'report' and Reason ~= 'report' then
            activeSession.Reason, activeSession.Victim = Reason, Victim
        end
        if Victim and (not activeSession.Victim or activeSession.Victim == LocalPlayer) then
            activeSession.Victim = Victim
        end
        if
            ForceMode
            and ForceMode ~= activeMode
            and not (activeMode == 'stomp target' and ForceMode == 'knock target')
            and (ForceMode == 'knock target' or ForceMode == 'stomp target' or ForceMode == 'fling target')
        then
            Data.PunishmentTargets[Damager] = ForceMode
            Data.TargetListCache = nil
            applypunishmentmodes()
        end
        return
    end
    Data.PendingSupport = Data.PendingSupport or {}
    local pending = Data.PendingSupport[Damager]
    if pending then
        if pending.Reason == 'report' and Reason ~= 'report' then
            pending.Reason, pending.Victim = Reason, Victim
        end
        pending.Damage = math.max(tonumber(pending.Damage) or 0, tonumber(Damage) or 0)
        if ForceMode and not (pending.Mode == 'stomp target' and ForceMode == 'knock target') then
            pending.Mode = ForceMode
        end
        if Victim and (not pending.Victim or pending.Victim == LocalPlayer) then
            pending.Victim = Victim
        end
        pending.Israel = israel or pending.Israel
        return
    end
    Data.SupportSequence = (Data.SupportSequence or 0) + 1
    pending = { Damage = Damage, Mode = ForceMode, Victim = Victim, Israel = israel, Order = Data.SupportSequence, Reason = Reason }
    if Data.PunishmentPrev == nil then
        Data.PunishmentPrev = { damager = Damager, single = Data.SingleLockedTarget }
    end
    Data.PendingSupport[Damager] = pending
    local batch = Data.PurchaseBatch
    if batch and (Data.BuyingArmor or batch.ActiveRequest and phowg:is_armor_purchase(batch.ActiveRequest.Query)) then
        phowg:finish_purchases(batch, true)
    end
    if Data.HeldGunFire and Data.HeldGunFire.Target == Damager then
        phowg:stop_gun_fire()
    end
    pending.Thread = coroutine.create(function()
        local ok, problem = pcall(function()
            local deadline = tick() + 20
            while
                Data.PendingSupport[Damager] == pending
                and Damager.Parent
                and not Library.Unloaded
                and tick() < deadline
            do
                if
                    not phowg:support_request_allowed(pending.Victim, pending.Reason)
                    or iswhitelistedplayer(Damager)
                then
                    return
                end
                local character = LocalPlayer.Character
                if character and not localactionblocked() and isplayerloadedin(Damager) then
                    if
                        not Data.Buying
                        and not Data.PurchaseBatch
                        and character == LocalPlayer.Character
                        and not localactionblocked()
                    then
                        Data.PendingSupport[Damager] = nil
                        phowg:start_punishment(
                            Damager,
                            pending.Damage,
                            pending.Mode,
                            pending.Victim,
                            pending.Israel,
                            pending.Order,
                            pending.Reason
                        )
                        return
                    end
                end
                task.wait(0.1)
            end
        end)
        if Data.PendingSupport[Damager] == pending then
            Data.PendingSupport[Damager] = nil
        end
        phowg:select_support_head()
        phowg:restore_support_settings()
        if not ok and not Library.Unloaded then
            warn('[Phowg] support preparation: ' .. tostring(problem))
        end
    end)
    task.spawn(pending.Thread)
end
phowg:register_cleanup('pending support', function(scope)
    if not scope then
        phowg:cancel_pending_support()
    elseif typeof(scope) == 'Instance' and scope:IsA('Player') then
        phowg:cancel_pending_support(scope)
    end
end)
function phowg:disable_israel_support()
    phowg:cancel_pending_support()
    local watch = Data.PunishmentDamageWatch
    if watch then
        watch.SignalSource, watch.SignalAt = nil, -math.huge
        for _, event in ipairs(watch.Events or {}) do
            event.Support = false
        end
    end
    local targets = {}
    for target in pairs(Data.PunishmentTargets or {}) do
        targets[#targets + 1] = target
    end
    for _, target in ipairs(targets) do
        punishmentcleartarget(target, true)
    end
    rapestopfiring()
    phowg:clear_support_loadout()
    Data.PunishmentGunActive, Data.PunishmentAutoFling, Data.SupportHead = nil, nil, nil
    phowg:restore_support_settings()
    phowg:update_protect_spectate()
end
function phowg:prune_support_requests()
    for target, pending in pairs(table.clone(Data.PendingSupport or {})) do
        if not phowg:support_request_allowed(pending.Victim, pending.Reason) then
            phowg:cancel_pending_support(target)
        end
    end
    for target, session in pairs(table.clone(Data.SupportTargetSessions or {})) do
        if not phowg:support_request_allowed(session.Victim, session.Reason) then
            punishmentcleartarget(target, true)
        end
    end
    if not phowg:israel_support_enabled() then
        phowg:disable_israel_support()
    else
        phowg:select_support_head()
        phowg:restore_support_settings()
        phowg:update_protect_spectate()
    end
end
function phowg:disable_self_protect()
    local watch = Data.PunishmentDamageWatch
    for _, event in ipairs(watch and watch.Events or {}) do
        event.Support = false
    end
    for target, pending in pairs(table.clone(Data.PendingSupport or {})) do
        if pending.Victim == LocalPlayer then
            phowg:cancel_pending_support(target)
        end
    end
    for target, session in pairs(table.clone(Data.SupportTargetSessions or {})) do
        if session.Victim == LocalPlayer and not (Data.PendingSupport and Data.PendingSupport[target]) then
            punishmentcleartarget(target, true)
        end
    end
    phowg:update_protect_spectate()
end
function phowg:protect_player_mode()
    return Toggles.protect_player_stomp and Toggles.protect_player_stomp.Value and 'stomp target' or 'knock target'
end
function phowg:sync_protect_player_mode()
    local mode = phowg:protect_player_mode()
    for target in pairs(Data.PunishmentTargets or {}) do
        Data.PunishmentTargets[target] = mode
    end
    for _, pending in pairs(Data.PendingSupport or {}) do
        pending.Mode = mode
    end
    Data.TargetListCache = nil
    if next(Data.PunishmentTargets or {}) then
        applypunishmentmodes()
    end
end
function phowg:update_protect_spectate()
    local previous = Data.ProtectSpectate
    local camera = Workspace.CurrentCamera
    local manual = Data.SpectateActive and Toggles.spectate and Toggles.spectate.Value
    local enabled = phowg:israel_support_enabled()
        and Toggles.protect_player_spectate
        and Toggles.protect_player_spectate.Value
    local target = enabled and not manual and not Data.IsRespawning and Data.SupportHead
    local character = target and target.Parent and target.Character
    local subject = character
        and character.Parent
        and (character:FindFirstChildOfClass('Humanoid') or character:FindFirstChild('HumanoidRootPart'))
    if previous and (previous.Camera ~= camera or not subject) then
        if
            not manual
            and previous.Camera
            and previous.Camera.Parent
            and previous.Camera.CameraSubject == previous.Subject
        then
            local restore = previous.Previous
            if not restore or not restore.Parent then
                restore = LocalPlayer.Character and LocalPlayer.Character:FindFirstChildOfClass('Humanoid')
            end
            if restore then
                previous.Camera.CameraSubject = restore
            end
        end
        Data.ProtectSpectate, previous = nil, nil
    end
    if not camera or not subject then
        return
    end
    if not previous then
        previous = { Camera = camera, Previous = camera.CameraSubject }
        Data.ProtectSpectate = previous
    end
    previous.Subject = subject
    if camera.CameraSubject ~= subject then
        camera.CameraSubject = subject
    end
end
registerheartbeat('ProtectSpectate', phowg.update_protect_spectate, 0.1, function()
    return Data.ProtectSpectate ~= nil
        or phowg:israel_support_enabled() and Toggles.protect_player_spectate and Toggles.protect_player_spectate.Value
end)
phowg:register_cleanup('protect spectate', function()
    local state = Data.ProtectSpectate
    Data.ProtectSpectate = nil
    if state and state.Camera and state.Camera.Parent and state.Camera.CameraSubject == state.Subject then
        local restore = state.Previous
        if not restore or not restore.Parent then
            restore = LocalPlayer.Character and LocalPlayer.Character:FindFirstChildOfClass('Humanoid')
        end
        if restore then
            state.Camera.CameraSubject = restore
        end
    end
end)
function phowg:start_punishment(Damager, Damage, ForceMode, Victim, IsraelPunish, Order, Reason)
    if not Damager or Damager == LocalPlayer then
        return
    end
    if localactionblocked() or Data.Buying or Data.PurchaseBatch then
        return
    end
    if iswhitelistedplayer(Damager) then
        return
    end
    if Data['RageWhitelist'] and Data['RageWhitelist'][Damager] and not IsraelPunish then
        return
    end
    if not phowg:support_request_allowed(Victim, Reason) then
        return
    end
    if not isplayerloadedin(Damager) then
        task.spawn(function()
            local t0 = tick()
            while not isplayerloadedin(Damager) and tick() - t0 < 15 do
                task.wait(0.5)
            end
            if isplayerloadedin(Damager) and Damager.Parent and not isdead(Damager) then
                punish(Damager, Damage, ForceMode, Victim, Reason)
            end
        end)
        return
    end
    if Data['PunishmentSavedToggles'] == nil then
        Data['PunishmentSavedToggles'] = {
            AutoKill = Toggles.auto_kill and Toggles.auto_kill.Value or false,
            AutoStomp = Toggles.auto_stomp and Toggles.auto_stomp.Value or false,
            AutoFling = Toggles.auto_fling and Toggles.auto_fling.Value or false,
        }
    end
    if Data['PunishmentPrev'] == nil then
        Data['PunishmentPrev'] = { damager = Damager, single = Data['SingleLockedTarget'] }
    end
    Data['LockedTargets'][Damager] = true
    Data['TargetWatchlist'][Damager.UserId] = true
    Data['TargetWatchlist'][Damager.Name] = true
    local mode = phowg:protect_player_mode()
    if mode ~= 'knock target' and mode ~= 'stomp target' and mode ~= 'fling target' then
        mode = 'knock target'
    end
    Data['SupportCompletedTargets'] = Data['SupportCompletedTargets'] or {}
    Data['SupportCompletedTargets'][Damager] = nil
    Data['SupportTargetCharacters'] = Data['SupportTargetCharacters'] or {}
    Data['SupportTargetCharacters'][Damager] = Damager.Character
    Data['PunishmentTargets'][Damager] = mode
    Data['SupportTargetSessions'] = Data['SupportTargetSessions'] or {}
    if not Data['SupportTargetSessions'][Damager] then
        Data['SupportTargetSessions'][Damager] = { ArmorCharacter = LocalPlayer.Character, Victim = Victim, Reason = Reason }
    end
    local session = Data['SupportTargetSessions'][Damager]
    if not session.Order then
        if not Order then
            Data.SupportSequence = (Data.SupportSequence or 0) + 1
            Order = Data.SupportSequence
        end
        session.Order = Order
    end
    phowg:select_support_head()
    Data['TargetListCache'] = nil
    applypunishmentmodes()
    phowg:start_loop('UnifiedCharacter', unified_character_loop)
    ragebot_on()
    if mode == 'fling target' then
        phowg:start_loop('AutoFling', autoflingloop)
    end
    task.defer(function()
        local desc = punishmentdescribeattack(Damager, Victim)
        Library:Notify(
            Library:PlayerDisplayName(Damager) .. ' ' .. desc .. ' for ' .. tostring(math.floor((Damage or 0) + 0.5)),
            Library.NotifyDuration or 4
        )
    end)
end
function phowg:queue_israel_attacker(player, damage, mode, victim)
    if
        not phowg:support_request_allowed(victim)
        or not player
        or player == LocalPlayer
        or not player.Parent
        or player == victim
        or phowg:stomp_protected(player)
    then
        return
    end
    local previous = Data.IsIsraelPunish
    Data.IsIsraelPunish = true
    local ok, problem = pcall(punish, player, damage or 1, mode or phowg:protect_player_mode(), victim)
    Data.IsIsraelPunish = previous
    if not ok and not Library.Unloaded then
        warn('[Phowg] support protection: ' .. tostring(problem))
    end
end
function phowg:match_israel_stomp(state)
    if Data.IsraelProtectionWatch ~= state or state.Closed then
        return
    end
    local now = tick()
    for victim, stomp in pairs(state.Stomps) do
        if not victim.Parent or now - stomp.At > 1.5 then
            state.Stomps[victim] = nil
        end
    end
    for attacker, increase in pairs(state.Wanted) do
        if not attacker.Parent or now - increase.At > 1.5 then
            state.Wanted[attacker] = nil
        else
            local closest, distance
            for victim, stomp in pairs(state.Stomps) do
                local separation = (increase.Position - stomp.Position).Magnitude
                if
                    attacker ~= victim
                    and math.abs(increase.At - stomp.At) <= 1.5
                    and separation <= 25
                    and (not distance or separation < distance)
                then
                    closest, distance = victim, separation
                end
            end
            if closest then
                state.Wanted[attacker] = nil
                phowg:queue_israel_attacker(attacker, 1, 'stomp target', closest)
            end
        end
    end
end
function phowg:stop_israel_protection()
    local state = Data.IsraelProtectionWatch
    Data.IsraelProtectionWatch = nil
    if not state then
        return
    end
    state.Closed = true
    for _, connection in pairs(state.Connections) do
        connection:Disconnect()
    end
    for _, record in pairs(state.Records) do
        record.Closed = true
        for _, connection in pairs(record.Connections) do
            connection:Disconnect()
        end
    end
end
function phowg:bind_israel_protection_player(state, player)
    if state.Closed or state.Records[player] then
        return
    end
    local protected = player == LocalPlayer and state.WatchWanted
        or (state.WatchWanted or state.WatchDamage)
            and Data.IsraelWhitelist
            and Data.IsraelWhitelist[player] == true
    if not protected and not state.WatchWanted then
        return
    end
    local record: { [string]: any } =
        { Connections = {}, Values = {}, Damagers = {}, Protected = protected, Closed = false }
    state.Records[player] = record
    local function active()
        return not state.Closed and not record.Closed and Data.IsraelProtectionWatch == state and player.Parent ~= nil
    end
    local function listen(key, source, callback, owner)
        if record.Connections[key] then
            record.Connections[key]:Disconnect()
        end
        record.Connections[key] = connectshared(source, callback, owner, 'israel protection/' .. key)
    end
    local function bind_value(key, value, callback)
        if value and not value:IsA('ValueBase') then
            value = nil
        end
        if record.Values[key] == value then
            return
        end
        if record.Connections[key] then
            record.Connections[key]:Disconnect()
            record.Connections[key] = nil
        end
        record.Values[key] = value
        if value then
            listen(key, value:GetPropertyChangedSignal('Value'), function()
                if active() and record.Values[key] == value and value.Parent then
                    callback(value, false)
                end
            end, value)
            callback(value, true)
        end
    end
    local function damager()
        local value = record.Values.LastDamager
        local source = value and value.Value
        if typeof(source) ~= 'Instance' then
            return nil
        end
        return source:IsA('Player') and source or Players:GetPlayerFromCharacter(source)
    end
    local function remember_damage()
        local shooter = damager()
        if shooter and shooter ~= player then
            record.Damagers[shooter] = tick()
        end
        return shooter
    end
    local function damage_changed()
        if player == LocalPlayer or not state.WatchDamage then
            return
        end
        if not active() or player.Character ~= record.Character or not record.Humanoid then
            return
        end
        local health = record.Humanoid.Health
        local drop = (record.Health or health) - health
        record.Health = health
        if drop <= 0 then
            return
        end
        record.LastDamageAt, record.LastDamage = tick(), drop
        local damageAt = record.LastDamageAt
        local function resolve_damage()
            if not active() or record.LastDamageAt ~= damageAt or record.DamageResolvedAt == damageAt then
                return
            end
            local shooter = damager()
            if not shooter or shooter == player then
                return
            end
            if
                Data.SupportCompletedTargets
                and Data.SupportCompletedTargets[shooter]
                and (record.Damagers[shooter] or -math.huge)
                    <= (Data.SupportCompletedAt and Data.SupportCompletedAt[shooter] or math.huge)
            then
                return
            end
            record.DamageResolvedAt = damageAt
            phowg:queue_israel_attacker(shooter, drop, nil, player)
        end
        task.delay(0.12, resolve_damage)
    end
    local function stomp_changed()
        if not active() or player.Character ~= record.Character then
            return
        end
        local stomped = isstomped(player)
        local changed = stomped and record.Stomped == false
        record.Stomped = stomped
        if changed then
            local root = getroot(record.Character)
            if root then
                state.Stomps[player] = { At = tick(), Position = root.Position, Character = record.Character }
                phowg:match_israel_stomp(state)
            end
        end
    end
    local function refresh_character()
        if not active() or not record.Character or player.Character ~= record.Character then
            return
        end
        local effects = record.Character:FindFirstChild('BodyEffects')
        bind_value('LastDamager', effects and effects:FindFirstChild('LastDamager'), function(_, initial)
            if initial or player == LocalPlayer or not state.WatchDamage then
                return
            end
            local shooter = remember_damage()
            if
                shooter
                and record.LastDamageAt
                and tick() - record.LastDamageAt <= 0.35
                and record.DamageResolvedAt ~= record.LastDamageAt
            then
                record.DamageResolvedAt = record.LastDamageAt
                phowg:queue_israel_attacker(shooter, record.LastDamage, nil, player)
            end
        end)
        if state.WatchWanted then
            bind_value('SDeath', effects and effects:FindFirstChild('SDeath'), stomp_changed)
            bind_value('SDead', effects and effects:FindFirstChild('SDead'), stomp_changed)
        end
        local humanoid = record.Character:FindFirstChildOfClass('Humanoid')
        if humanoid ~= record.Humanoid then
            if record.Connections.Health then
                record.Connections.Health:Disconnect()
                record.Connections.Health = nil
            end
            record.Humanoid, record.Health = humanoid, humanoid and humanoid.Health
            if humanoid then
                listen('Health', humanoid:GetPropertyChangedSignal('Health'), damage_changed, humanoid)
            end
        end
    end
    function record.BindCharacter(character)
        for _, key in ipairs({ 'character added', 'character removed', 'Health', 'LastDamager', 'SDeath', 'SDead' }) do
            if record.Connections[key] then
                record.Connections[key]:Disconnect()
                record.Connections[key] = nil
            end
            record.Values[key] = nil
        end
        record.Character, record.Humanoid, record.Health, record.LastDamageAt = character, nil, nil, nil
        table.clear(record.Damagers)
        record.Stomped = character and isstomped(player) or false
        if not character or not active() then
            return
        end
        local function changed(child)
            if
                child.Name == 'BodyEffects'
                or child.Name == 'LastDamager'
                or child.Name == 'SDeath'
                or child.Name == 'SDead'
                or child:IsA('Humanoid')
            then
                task.defer(function()
                    if active() and record.Character == character then
                        refresh_character()
                    end
                end)
            end
        end
        listen('character added', character.DescendantAdded, changed, character)
        listen('character removed', character.DescendantRemoving, changed, character)
        refresh_character()
    end
    if protected then
        listen('spawn', player.CharacterAdded, record.BindCharacter, player)
        listen('despawn', player.CharacterRemoving, function(character)
            if record.Character == character then
                record.BindCharacter(nil)
            end
        end, player)
        record.BindCharacter(player.Character)
    end
    if state.WatchWanted and player ~= LocalPlayer then
        local function refresh_wanted()
            if not active() then
                return
            end
            local folder = player:FindFirstChild('DataFolder')
            local information = folder and folder:FindFirstChild('Information')
            local value = information and information:FindFirstChild('Wanted')
                or folder and folder:FindFirstChild('Wanted')
            bind_value('Wanted', value, function(source, initial)
                local wanted = tonumber(source.Value)
                local previous = record.Wanted
                record.Wanted = wanted
                if not initial and wanted and previous and wanted > previous then
                    local root = player.Character and getroot(player.Character)
                    if root then
                        state.Wanted[player] = { At = tick(), Position = root.Position }
                        phowg:match_israel_stomp(state)
                    end
                end
            end)
        end
        local function changed(child)
            if child.Name == 'Wanted' or child.Name == 'DataFolder' or child.Name == 'Information' then
                task.defer(refresh_wanted)
            end
        end
        listen('data added', player.DescendantAdded, changed, player)
        listen('data removed', player.DescendantRemoving, changed, player)
        refresh_wanted()
    end
end
function phowg:sync_israel_protection()
    local master = phowg:other_protection_enabled()
    local call = phowg:self_protect_enabled() and Toggles.israel_call_protection and Toggles.israel_call_protection.Value == true
    if Data.CallProtectionEnabled ~= call then
        Data.CallProtectionEnabled = call
        phowg:set_character_observer('call protection', call, function(state, character)
            local previous
            phowg:observe_character_values(state, character, { CallFrom = true }, function()
                if state.Closed or character ~= LocalPlayer.Character then
                    return
                end
                local effects = character:FindFirstChild('BodyEffects')
                local value = effects and effects:FindFirstChild('CallFrom')
                local name = value and type(value.Value) == 'string' and value.Value:match('^%s*(.-)%s*$') or ''
                if name == previous then
                    return
                end
                previous = name
                local caller = name ~= '' and Players:FindFirstChild(name)
                if caller and caller:IsA('Player') then
                    phowg:queue_israel_attacker(caller, 1, 'stomp target', LocalPlayer)
                end
            end)
        end)
    end
    local protected = master and Toggles.protect_whitelisted and Toggles.protect_whitelisted.Value == true
        and next(Data.IsraelWhitelist or {}) ~= nil
    local wanted = master and Toggles.israel_stomp_protection and Toggles.israel_stomp_protection.Value == true
    if not protected and not wanted then
        phowg:stop_israel_protection()
        return
    end
    local ids = {}
    for player, enabled in pairs(Data.IsraelWhitelist or {}) do
        if enabled and player.Parent then
            ids[#ids + 1] = tostring(player.UserId)
        end
    end
    table.sort(ids)
    local signature = tostring(protected) .. '/' .. tostring(wanted) .. '/' .. table.concat(ids, ',')
    if Data.IsraelProtectionWatch and Data.IsraelProtectionWatch.Signature == signature then
        return
    end
    phowg:stop_israel_protection()
    local state = {
        Connections = {},
        Records = {},
        Stomps = {},
        Wanted = {},
        WatchWanted = wanted,
        WatchDamage = protected,
        Signature = signature,
        Closed = false,
    }
    Data.IsraelProtectionWatch = state
    state.Connections.Added = connectshared(Players.PlayerAdded, function(player)
        phowg:bind_israel_protection_player(state, player)
    end, Players, 'israel protection/join', 0, 'event/PlayerAdded', Players)
    state.Connections.Removed = connectshared(Players.PlayerRemoving, function(player)
        local record = state.Records[player]
        if record then
            record.Closed = true
            for _, connection in pairs(record.Connections) do
                connection:Disconnect()
            end
            state.Records[player] = nil
        end
        state.Stomps[player], state.Wanted[player] = nil, nil
    end, Players, 'israel protection/leave', 0, 'event/PlayerRemoving', Players)
    for _, player in ipairs(Players:GetPlayers()) do
        phowg:bind_israel_protection_player(state, player)
    end
end
phowg:register_cleanup('israel protection', function(scope)
    if not scope then
        phowg:stop_israel_protection()
        phowg:stop_character_observer('call protection')
        Data.CallProtectionEnabled = nil
        return
    end
    local state = Data.IsraelProtectionWatch
    if state then
        for player, record in pairs(state.Records) do
            if scope == player then
                record.Closed = true
                for _, connection in pairs(record.Connections) do
                    connection:Disconnect()
                end
                state.Records[player], state.Wanted[player], state.Stomps[player] = nil, nil, nil
            elseif scope == record.Character then
                record.BindCharacter(nil)
            end
        end
    end
end)

function phowg:local_damage_source(source)
    if typeof(source) ~= 'Instance' then
        return nil
    end
    if source:IsA('Player') then
        return source ~= LocalPlayer and source.Parent and source or nil
    end
    local node = source
    while node and node ~= Workspace do
        if node:IsA('Model') then
            local player = Players:GetPlayerFromCharacter(node)
            if player then
                return player ~= LocalPlayer and player.Parent and player or nil
            end
        end
        node = node.Parent
    end
    return nil
end
function phowg:local_damage_attacker(state: any, event: any)
    local function identify(source, signalAt, shotAt, shotPosition)
        local attacker = phowg:local_damage_source(source)
        if not attacker or not attacker.Character then
            return nil
        end
        local evidence = -math.huge
        local root = getroot(attacker.Character)
        local shotFresh = shotPosition and shotAt >= event.At - 0.2 and shotAt <= event.Expires
        local shotMatches = root and shotFresh and (root.Position - shotPosition).Magnitude <= 25
        if signalAt >= event.At - 0.2 and signalAt <= event.Expires and (not shotFresh or shotMatches) then
            evidence = signalAt
        end
        if shotMatches then
            evidence = math.max(evidence, shotAt)
        end
        local effects = attacker.Character:FindFirstChild('BodyEffects')
        local attacking = effects and effects:FindFirstChild('Attacking')
        local myRoot = getroot(state.Character)
        if
            root
            and myRoot
            and attacking
            and attacking:IsA('BoolValue')
            and attacking.Value
            and (root.Position - myRoot.Position).Magnitude <= 18
        then
            evidence = math.max(evidence, tonumber(event.At) or -math.huge)
        end
        if evidence == -math.huge then
            return nil
        end
        return attacker, evidence
    end
    local attacker, evidence = identify(event.Source, event.SourceAt, event.ShotAt, event.ShotPosition)
    if attacker then
        return attacker, evidence
    end
    local value = state.Values.LastDamager
    local source = value and value.Parent and value.Value
    return identify(
        source,
        state.SignalSource == source and state.SignalAt or -math.huge,
        state.ShotAt,
        state.ShotPosition
    )
end
function phowg:notify_local_damage(event: any, attacker: any)
    if not event.Notify or not (Toggles.damage_notifications and Toggles.damage_notifications.Value) then
        return
    end
    if attacker and not phowg:on_hit_allowed(attacker) then
        return
    end
    if
        not attacker
        and (
            Toggles.on_hit_enabled and not Toggles.on_hit_enabled.Value
            or Toggles.on_hit_ignore_crew and Toggles.on_hit_ignore_crew.Value
        )
    then
        return
    end
    local damage = math.round(tonumber(event.Damage) or 0)
    if not attacker then
        Library:Notify('took ' .. tostring(damage) .. ' damage.', Library.NotifyDuration or 4)
        return
    end
    local desc = punishmentdescribeattack(attacker)
    local snapshot = Data.PunishmentHitWeapon and Data.PunishmentHitWeapon[attacker]
    local weapon = snapshot and tick() - (snapshot.at or 0) < 5 and snapshot.name
    if not weapon then
        local tool = attacker.Character and attacker.Character:FindFirstChildOfClass('Tool')
        weapon = tool and tool.Name
    end
    local fallback = Library:PlayerDisplayName(attacker) .. ' ' .. tostring(desc) .. ' for ' .. tostring(damage)
    Library:Notify(
        phowg:combat_notification(
            'damage',
            attacker,
            event.Damage,
            weapon and punishmentcleantoolname(weapon),
            desc,
            fallback
        ),
        Library.NotifyDuration or 4
    )
end
function phowg:stop_local_damage_watch()
    local state = Data.PunishmentDamageWatch
    if not state then
        return
    end
    state.Closed = true
    if state.Timer then
        pcall(task.cancel, state.Timer)
    end
    for _, connection in pairs(state.Connections) do
        connection:Disconnect()
    end
    table.clear(state.Connections)
    table.clear(state.Events)
    Data.PunishmentDamageWatch = nil
    Data.PunishmentConns = {}
    Data.DamageNotifyConns = {}
end
function watchpunishmentdamage(char)
    local previous = Data.PunishmentDamageWatch
    if previous and not previous.Closed and previous.Character == char then
        return
    end
    phowg:stop_local_damage_watch()
    if not char or char ~= LocalPlayer.Character or Library.Unloaded then
        return
    end
    local state: { [string]: any } = {
        Character = char,
        Events = {},
        Connections = {},
        Values = {},
        ValueConnections = {},
        Last = {},
        SignalAt = -math.huge,
        ShotAt = -math.huge,
        Closed = false,
    }
    Data.PunishmentDamageWatch, Data.PunishmentConns = state, state.Connections
    local function active()
        return not state.Closed
            and Data.PunishmentDamageWatch == state
            and LocalPlayer.Character == char
            and not Library.Unloaded
            and not Data.SharedSignalsClosed
    end
    local function keep(connection)
        state.Connections[connection] = connection
        return connection
    end
    local function release(connection)
        if connection then
            connection:Disconnect()
            state.Connections[connection] = nil
        end
    end
    local flush
    local function schedule(delay)
        if not active() then
            return
        end
        local due = tick() + delay
        if state.Timer and state.TimerAt <= due then
            return
        end
        if state.Timer then
            pcall(task.cancel, state.Timer)
        end
        state.TimerAt = due
        state.Timer = task.delay(delay, function()
            state.Timer = nil
            if active() then
                flush()
            end
        end)
    end
    flush = function()
        if not active() then
            return
        end
        local now, pending = tick(), state.Events
        state.Events = {}
        local nextAt = math.huge
        for _, event in ipairs(pending) do
            local attacker, evidence
            if now >= event.ReadyAt then
                attacker, evidence = phowg:local_damage_attacker(state, event)
            end
            if now < event.ReadyAt or not attacker and now < event.Expires then
                state.Events[#state.Events + 1] = event
                nextAt = math.min(nextAt, now < event.ReadyAt and event.ReadyAt or event.Expires)
            else
                if
                    attacker
                    and event.Support
                    and phowg:self_protect_enabled()
                    and not Data.IsRespawning
                then
                    local completed = Data.SupportCompletedTargets and Data.SupportCompletedTargets[attacker]
                    local completedAt = Data.SupportCompletedAt and Data.SupportCompletedAt[attacker] or math.huge
                    if not completed or evidence > completedAt then
                        Data.PunishmentLastDamageCharacter, Data.PunishmentLastDamageAt = char, now
                        Data.PunishmentCooldowns = Data.PunishmentCooldowns or {}
                        Data.PunishmentCooldowns[attacker] = now
                        punish(attacker, event.Damage, event.Mode, LocalPlayer)
                    end
                end
                phowg:notify_local_damage(event, attacker)
            end
        end
        if nextAt < math.huge then
            schedule(math.max(0, nextAt - tick()))
        end
    end
    local function loss(kind, current)
        current = tonumber(current)
        if not active() or not current or current ~= current or math.abs(current) == math.huge then
            return
        end
        local last = state.Last[kind]
        state.Last[kind] = current
        if kind == 'Health' then
            Data.PunishmentLastHealth, Data.DamageNotifyLastHealth = current, current
        end
        local amount = last and last - current or 0
        if amount <= 0 then
            return
        end
        local now = tick()
        Data.TookDamageAt = now
        local support = phowg:self_protect_enabled()
            and not Data.IsRespawning
        local notify = Toggles.damage_notifications and Toggles.damage_notifications.Value == true
        if not support and not notify then
            return
        end
        local value = state.Values.LastDamager
        local source = value and value.Parent and value.Value
        local previousEvent = state.Events[#state.Events]
        if
            previousEvent
            and now - previousEvent.At <= 1 / 60
            and not previousEvent.Kinds[kind]
            and previousEvent.Source == source
            and previousEvent.Support == support
            and previousEvent.Notify == notify
        then
            previousEvent.Damage += amount
            previousEvent.Kinds[kind] = true
            if kind == 'Health' and current <= 0 then
                previousEvent.Mode = phowg:protect_player_mode()
            end
        else
            local health = state.Humanoid and state.Humanoid.Health or 0
            local event = {
                At = now,
                ReadyAt = now + 0.08,
                Expires = now + 0.6,
                Damage = amount,
                Kinds = { [kind] = true },
                Source = source,
                Support = support,
                Notify = notify,
                SourceAt = state.SignalSource == source and state.SignalAt or -math.huge,
                ShotAt = state.ShotAt,
                ShotPosition = state.ShotPosition,
                Mode = health <= 0 and (phowg:protect_player_mode()) or nil,
            }
            state.Events[#state.Events + 1] = event
        end
        schedule(0.08)
    end
    local function bind_value(name, value)
        if state.Values[name] == value then
            return
        end
        release(state.ValueConnections[name])
        state.ValueConnections[name] = nil
        state.Values[name], state.Last[name] = value, nil
        if not value or not value:IsA('ValueBase') then
            return
        end
        if name ~= 'LastDamager' then
            state.Last[name] = tonumber(value.Value)
        end
        state.ValueConnections[name] = keep(connectshared(value:GetPropertyChangedSignal('Value'), function()
            if not active() or state.Values[name] ~= value or value.Parent ~= state.Effects then
                return
            end
            if name == 'LastDamager' then
                state.SignalSource, state.SignalAt = value.Value, tick()
                Data.PunishmentLastSignalAt = state.SignalAt
                if #state.Events > 0 then
                    schedule(0.01)
                end
            else
                loss(name, value.Value)
            end
        end, value, 'local damage/' .. name, 0, 'property/Value', value))
    end
    local function bind_effects(effects)
        if state.Effects == effects then
            return
        end
        release(state.EffectsAdded)
        release(state.EffectsRemoved)
        for _, name in ipairs({ 'LastDamager', 'Armor', 'FireArmor' }) do
            bind_value(name, nil)
        end
        state.Effects = effects
        state.SignalSource, state.SignalAt = nil, -math.huge
        if not effects then
            return
        end
        local function sync(value)
            if value.Name == 'LastDamager' or value.Name == 'Armor' or value.Name == 'FireArmor' then
                bind_value(value.Name, effects:FindFirstChild(value.Name))
            end
        end
        state.EffectsAdded = keep(
            connectshared(effects.ChildAdded, sync, effects, 'local damage/value added', 0, 'event/ChildAdded', effects)
        )
        state.EffectsRemoved = keep(
            connectshared(
                effects.ChildRemoved,
                sync,
                effects,
                'local damage/value removed',
                0,
                'event/ChildRemoved',
                effects
            )
        )
        for _, name in ipairs({ 'LastDamager', 'Armor', 'FireArmor' }) do
            bind_value(name, effects:FindFirstChild(name))
        end
    end
    local function bind_humanoid(humanoid)
        if state.Humanoid == humanoid then
            return
        end
        release(state.HealthConnection)
        state.Humanoid, state.Last.Health = humanoid, humanoid and humanoid.Health or nil
        if humanoid then
            state.HealthConnection = keep(connectshared(humanoid:GetPropertyChangedSignal('Health'), function()
                if active() and humanoid.Parent == char then
                    loss('Health', humanoid.Health)
                end
            end, humanoid, 'local damage/health', 0, 'property/Health', humanoid))
        end
    end
    local function sync_child(child)
        if not active() then
            return
        end
        if child.Name == 'BodyEffects' then
            bind_effects(char:FindFirstChild('BodyEffects'))
        elseif child:IsA('Humanoid') then
            bind_humanoid(char:FindFirstChildOfClass('Humanoid'))
        end
    end
    keep(connectshared(char.ChildAdded, sync_child, char, 'local damage/child added', 0, 'event/ChildAdded', char))
    keep(connectshared(char.ChildRemoved, sync_child, char, 'local damage/child removed', 0, 'event/ChildRemoved', char))
    bind_humanoid(char:FindFirstChildOfClass('Humanoid'))
    bind_effects(char:FindFirstChild('BodyEffects'))
    state.BindRemote = function(remote)
        if state.Remote == remote then
            return
        end
        release(state.RemoteConnection)
        state.Remote, state.ShotAt, state.ShotPosition = remote, -math.huge, nil
        if remote and remote:IsA('RemoteEvent') then
            state.RemoteConnection = keep(connectshared(remote.OnClientEvent, function(kind, position)
                if not active() or kind ~= 'ShotFrom' or typeof(position) ~= 'Vector3' then
                    return
                end
                state.ShotAt, state.ShotPosition = tick(), position
                if #state.Events > 0 then
                    schedule(0.01)
                end
            end, remote, 'local damage/shot from', 0, 'event/OnClientEvent', remote))
        end
    end
    state.BindRemote(MainEvent and MainEvent.Parent and MainEvent or ReplicatedStorage:FindFirstChild('MainEvent'))
end
function hookdamagenotifywatch(char)
    watchpunishmentdamage(char)
