function phowg:hit_sound_values()
    local values = {
        'minecraft',
        'gamesense',
        'neverlose',
        'bameware',
        'bubble',
        'rifk7',
        'rust',
        'cod',
        'mc bow',
        'tf2 crit',
        'osu',
        'villager',
        'goofy',
        'bloody',
    }
    local files = {}
    for name in pairs(Data.SymbolSoundFiles) do
        files[#files + 1] = name
    end
    table.sort(files)
    for _, name in ipairs(files) do
        values[#values + 1] = Data.SymbolSoundLabels[name]
    end
    values[#values + 1] = 'custom'
    return values
end
function phowg:asset_cache_path(category, file, legacy)
    local hosted = RuntimeAssets['assets/' .. category .. '/' .. file]
    if hosted then return hosted end
    local root = 'PhowgHosted/DaHood/cache'
    local folder = root .. '/' .. category
    local path = folder .. '/' .. file
    if type(makefolder) ~= 'function' or type(isfolder) ~= 'function' then
        return path
    end
    Data.AssetCacheFolders = Data.AssetCacheFolders or {}
    if not Data.AssetCacheFolders[folder] then
        for _, directory in ipairs({ 'PhowgHosted', 'PhowgHosted/DaHood', root, folder }) do
            if not isfolder(directory) then
                makefolder(directory)
            end
        end
        Data.AssetCacheFolders[folder] = true
    end
    if
        legacy
        and type(isfile) == 'function'
        and type(readfile) == 'function'
        and type(writefile) == 'function'
        and not isfile(path)
    then
        for _, candidate in ipairs(legacy) do
            if isfile(candidate) then
                local ok, bytes = pcall(readfile, candidate)
                if ok and type(bytes) == 'string' and #bytes > 0 then
                    writefile(path, bytes)
                    break
                end
            end
        end
    end
    return path
end
function phowg:resolve_symbol_sound(selection)
    local name = type(selection) == 'string'
        and (Data.SymbolSoundNames[selection] or selection:match('^symbol / (.+)$'))
    local file = name and Data.SymbolSoundFiles[name]
    if not file then
        return nil
    end
    Data.SymbolSoundAssets = Data.SymbolSoundAssets or {}
    local cached = Data.SymbolSoundAssets[name]
    if type(cached) == 'string' then
        return cached
    end
    if cached == false or tick() < ((Data.SymbolSoundRetry or {})[name] or 0) then
        return nil
    end
    local asset = getcustomasset or getsynasset
    if not asset or not isfile then
        return nil
    end
    local original = 'SymbolDogShit/Sounds/' .. file
    if makefolder and isfolder and writefile then
        local ok, path = pcall(phowg_callbacks.asset_cache_path, 'sounds', file, { original, 'PhowgAssets/Sounds/' .. file })
        if ok then
            original = path
        end
    end
    if isfile(original) then
        local ok, id = pcall(asset, original)
        if ok and type(id) == 'string' then
            Data.SymbolSoundAssets[name] = id
            return id
        end
    end
    if not (writefile and makefolder and isfolder) then
        return nil
    end
    Data.SymbolSoundAssets[name] = false
    phowg:queue_background('sound assets', name, function()
        if Library.Unloaded or Data.SharedSignalsClosed then
            Data.SymbolSoundAssets[name] = nil
            return
        end
        local ok, id = pcall(function()
            local path = phowg:asset_cache_path('sounds', file, { 'PhowgAssets/Sounds/' .. file })
            if not isfile(path) then
                local leaf = file:sub(1, 7) == 'Nebula_' and file:sub(8) or file
                local url = file:sub(1, 7) == 'Nebula_'
                        and 'https://raw.githubusercontent.com/f1nobe7650/Nebula/refs/heads/main/Sounds/'
                    or 'https://raw.githubusercontent.com/OnChangedCallback/sounds/refs/heads/main/main/'
                leaf = leaf:gsub('[^%w%-%._~]', function(char)
                    return string.format('%%%02X', string.byte(char))
                end)
                local bytes = game:HttpGet(url .. leaf)
                if type(bytes) ~= 'string' or #bytes == 0 then
                    error('Empty hit sound download')
                end
                writefile(path, bytes)
            end
            return asset(path)
        end)
        if ok and type(id) == 'string' then
            Data.SymbolSoundAssets[name] = id
            phowg:queue_assets({ id })
        else
            Data.SymbolSoundAssets[name] = nil
            Data.SymbolSoundRetry = Data.SymbolSoundRetry or {}
            Data.SymbolSoundRetry[name] = tick() + 10
        end
    end)
    return nil
end
function phowg:play_cached_hit_sound(id, volume, pitch)
    Data.SymbolSoundPool = Data.SymbolSoundPool or {}
    local selected
    for index = #Data.SymbolSoundPool, 1, -1 do
        if not Data.SymbolSoundPool[index].Sound.Parent then
            Data.SymbolSoundPool[index].Sound:Destroy()
            table.remove(Data.SymbolSoundPool, index)
        end
    end
    for _, entry in ipairs(Data.SymbolSoundPool) do
        if entry.Sound.Parent and not entry.Sound.IsPlaying then
            selected = entry
            break
        end
    end
    if not selected and #Data.SymbolSoundPool < 32 then
        local sound = Instance.new('Sound')
        sound.Name, sound.Parent = 'PhowgHitSound', Workspace
        selected = { Sound = sound, At = 0 }
        Data.SymbolSoundPool[#Data.SymbolSoundPool + 1] = selected
    end
    if not selected then
        selected = Data.SymbolSoundPool[1]
        for _, entry in ipairs(Data.SymbolSoundPool) do
            if entry.At < selected.At then
                selected = entry
            end
        end
    end
    local sound = selected.Sound
    sound:Stop()
    sound.SoundId, sound.Volume, sound.PlaybackSpeed, sound.TimePosition = id, volume, pitch, 0
    sound.Parent = Workspace
    sound:Play()
    selected.At, Data.SymbolSoundAt = tick(), tick()
end
function phowg:queue_assets(assets)
    if Library.Unloaded or Data.SharedSignalsClosed then
        return
    end
    Data.VisualAssets = Data.VisualAssets or {}
    Data.AssetRetries = Data.AssetRetries or {}
    local queue = Data.AssetPreloadQueue
    if not queue then
        queue = { Items = {}, Head = 1, Tail = 0 }
        Data.AssetPreloadQueue = queue
    end
    for _, asset in ipairs(assets) do
        if
            type(asset) == 'string'
            and asset ~= ''
            and not Data.VisualAssets[asset]
            and tick() >= (Data.AssetRetries[asset] or 0)
        then
            Data.VisualAssets[asset] = 'queued'
            Data.AssetLoadTotal = (Data.AssetLoadTotal or 0) + 1
            queue.Tail += 1
            queue.Items[queue.Tail] = asset
        end
    end
    if queue.Worker or queue.Head > queue.Tail then
        return
    end
    local worker = coroutine.create(function()
        local provider = game:GetService('ContentProvider')
        while queue.Head <= queue.Tail and not Library.Unloaded and not Data.SharedSignalsClosed do
            local batch, results = {}, {}
            for _ = 1, 16 do
                if queue.Head > queue.Tail then
                    break
                end
                local asset = queue.Items[queue.Head]
                queue.Items[queue.Head] = nil
                queue.Head += 1
                Data.VisualAssets[asset] = 'loading'
                batch[#batch + 1] = asset
            end
            local ok = pcall(function()
                provider:PreloadAsync(batch, function(asset, status)
                    local success = status == Enum.AssetFetchStatus.Success
                    results[asset] = success
                    local id = type(asset) == 'string' and asset:match('[?/=](%d+)')
                    if id then
                        results[id] = results[id] ~= false and success
                    end
                end)
            end)
            for _, asset in ipairs(batch) do
                local status = results[asset]
                if status == nil then
                    status = results[asset:match('[?/=](%d+)') or asset]
                end
                Data.VisualAssets[asset] = ok and status == true and 'loaded' or nil
                Data.AssetLoadCompleted = (Data.AssetLoadCompleted or 0) + 1
                if not Data.VisualAssets[asset] then
                    Data.AssetLoadFailed = (Data.AssetLoadFailed or 0) + 1
                end
                if not Data.VisualAssets[asset] then
                    Data.AssetRetries[asset] = tick() + 10
                end
            end
            if queue.Head <= queue.Tail then
                task.wait()
            end
        end
        table.clear(queue.Items)
        queue.Head, queue.Tail, queue.Worker = 1, 0, nil
    end)
    queue.Worker = worker
    task.spawn(worker)
end
function phowg:queue_asset_tree(root)
    if not root then
        return
    end
    local assets = {}
    local function add(object)
        if object:IsA('Animation') then
            assets[#assets + 1] = object.AnimationId
        elseif object:IsA('Sound') then
            assets[#assets + 1] = object.SoundId
        elseif
            object:IsA('ParticleEmitter')
            or object:IsA('Beam')
            or object:IsA('Trail')
            or object:IsA('Decal')
            or object:IsA('Texture')
        then
            assets[#assets + 1] = object.Texture
        elseif object:IsA('MeshPart') then
            assets[#assets + 1], assets[#assets + 2] = object.MeshId, object.TextureID
        elseif object:IsA('SpecialMesh') then
            assets[#assets + 1], assets[#assets + 2] = object.MeshId, object.TextureId
        elseif
            object:IsA('StringValue')
            and type(object.Value) == 'string'
            and object.Value:find('rbxasset', 1, true)
        then
            assets[#assets + 1] = object.Value
        elseif object:IsA('ImageLabel') or object:IsA('ImageButton') then
            assets[#assets + 1] = object.Image
        end
    end
    add(root)
    for index, object in ipairs(root:GetDescendants()) do
        add(object)
        if index % 128 == 0 then
            phowg:queue_assets(assets)
            table.clear(assets)
            if Library.Unloaded or Data.SharedSignalsClosed then
                return
            end
            task.wait()
        end
    end
    phowg:queue_assets(assets)
end
function phowg:preload_visual_assets(emitters)
    local assets = {}
    for _, emitter in ipairs(emitters) do
        assets[#assets + 1] = emitter.Texture
    end
    phowg:queue_assets(assets)
end
function phowg:preload_known_assets()
    local selectedAura = Options.local_particle_aura_value and Options.local_particle_aura_value.Value
    if phowg:toggle_enabled('local_particle_aura') and selectedAura and Data.LarpticAuraAssets[selectedAura] then
        phowg:larptic_aura_template(selectedAura, false)
    end
    if phowg:toggle_enabled('anim_player_enabled') then
        local selected = Options.anim_player_animation and Options.anim_player_animation.Value
        local raw = selected == 'custom' and Options.anim_player_custom_id and Options.anim_player_custom_id.Value
            or Data.AnimPlayerList and Data.AnimPlayerList[selected]
        if raw then
            phowg:queue_background('selected assets', 'animation', function()
                local id = resolveanimid(raw)
                if id then phowg:queue_assets({ id }) end
            end)
        end
    end
    if Toggles.hit_sound and Toggles.hit_sound.Value then
        phowg:queue_assets({ phowg:selected_hit_sound() })
    end
    phowg:warm_aura_caches()
    local assets = {}
    local function collect(value)
        if type(value) == 'string' and value:find('rbxasset', 1, true) then
            assets[#assets + 1] = value
        elseif type(value) == 'table' then
            for _, child in pairs(value) do
                collect(child)
            end
        end
    end
    for _, key in ipairs({ 'HitSounds', 'ShootSounds', 'SkinPullouts', 'SkinKnifeProfiles', 'AuraTemplates' }) do
        collect(Data[key])
    end
    phowg:queue_assets(assets)
    for name, value in pairs(Data.AnimPlayerList or {}) do
        local raw = value
        phowg:queue_background('animation assets', name, function()
            local id = resolveanimid(raw)
            if id then
                phowg:queue_assets({ id })
            end
        end, true)
    end
    for name in pairs(Data.SymbolSoundNames or {}) do
        local id = phowg:resolve_symbol_sound(name)
        if id then
            phowg:queue_assets({ id })
        end
    end
    for _, name in ipairs({ 'SkinAssets', 'SkinModules', 'Animations', 'ClientAnimations' }) do
        local root = ReplicatedStorage:FindFirstChild(name)
        if root then
            phowg:queue_background('asset discovery', name, function()
                phowg:queue_asset_tree(root)
            end, true)
        end
    end
    for _, name in pairs(Data.SymbolEffectNames or {}) do
        local effectAssets = Data.SymbolHitAssetIds and Data.SymbolHitAssetIds[name]
        if effectAssets then
            phowg:queue_assets(effectAssets)
        else
            phowg:queue_background('effect assets', name, function()
                phowg:queue_asset_tree(phowg:symbol_hit_template(name))
            end, true)
        end
    end
    phowg:queue_background('effect assets', 'native hit effects', function()
        phowg:queue_asset_tree(buildhitfx())
    end)
    if LocalPlayer.Character then
        phowg:queue_asset_tree(LocalPlayer.Character:FindFirstChild('Animate'))
    end
end
phowg:register_cleanup('asset preloading', function(_, reason)
    if reason ~= 'unload' then
        return
    end
    local queue = Data.AssetPreloadQueue
    if queue and queue.Worker and queue.Worker ~= coroutine.running() then
        pcall(task.cancel, queue.Worker)
    end
    Data.AssetPreloadQueue = nil
end)
function phowg:new_symbol_hit_entry(name)
    local ok, template = pcall(phowg_callbacks.symbol_hit_template, name)
    if not ok or not template then
        Data.HitTemplateErrors = Data.HitTemplateErrors or {}
        if not Data.HitTemplateErrors[name] then
            Data.HitTemplateErrors[name] = true
            warn('[Phowg] cannot build hit effect ' .. name .. ': ' .. tostring(template))
        end
        return nil
    end
    local carrier = Instance.new('Part')
    carrier.Name, carrier.Anchored, carrier.Transparency, carrier.CastShadow = 'PhowgHitEffect', true, 1, false
    carrier.CanCollide, carrier.CanTouch, carrier.CanQuery = false, false, false
    carrier.Size = name == 'Glitch' and Vector3.new(2.6, 5.52, 2.8) or Vector3.new(1, 1, 1)
    local attachment = template:Clone()
    attachment.Parent = carrier
    local entry = {
        Carrier = carrier,
        Attachment = attachment,
        Name = name,
        Emitters = {},
        Colors = {},
        Counts = {},
        BaseCounts = {},
        Duration = 0,
    }
    for _, child in ipairs(attachment:GetDescendants()) do
        if child:IsA('ParticleEmitter') then
            local amount = child:GetAttribute('EmitCount') or child.Rate
            if name == 'Glitch' then
                amount = 3
                child.Parent = carrier
            end
            entry.BaseCounts[#entry.BaseCounts + 1] = math.max(1, math.floor(tonumber(amount) or 1))
            entry.Duration = math.max(entry.Duration, child.Lifetime.Max / math.max(child.TimeScale, 0.05))
            child.Enabled, child.Rate = false, 0
            entry.Emitters[#entry.Emitters + 1] = child
        end
        if child:IsA('ParticleEmitter') or child:IsA('Beam') or child:IsA('Trail') then
            entry.Colors[#entry.Colors + 1] = child
        end
    end
    if #entry.Emitters == 0 then
        carrier:Destroy()
        return nil
    end
    phowg:preload_visual_assets(entry.Emitters)
    return entry
end
function phowg:prepare_hit_effects(selection)
    local presets, seen = {}, {}
    local function add(value)
        if type(value) ~= 'string' or value == '' then
            return
        end
        value = value:lower()
        if not seen[value] then
            seen[value] = true
            presets[#presets + 1] = value
        end
    end
    if type(selection) == 'table' then
        for key, value in pairs(selection) do
            if type(key) == 'string' and value then
                add(key)
            elseif type(key) == 'number' then
                add(value)
            end
        end
    else
        add(selection)
    end
    if #presets == 0 then
        presets[1] = 'sparks'
    end
    Data.HitEffectPresets = presets
    Data.HitEffectWarmQueue = {}
    if not (Toggles.hit_effect and Toggles.hit_effect.Value) then
        return
    end
    Data.SymbolEffectPools = Data.SymbolEffectPools or {}
    for _, preset in ipairs(presets) do
        local name = Data.SymbolEffectNames[preset]
        if name then
            local pool = Data.SymbolEffectPools[name]
            if not pool then
                pool = {}
                Data.SymbolEffectPools[name] = pool
            end
            if #pool == 0 then
                local entry = phowg:new_symbol_hit_entry(name)
                if entry then
                    pool[#pool + 1] = entry
                end
            end
            local total = #pool
            for _, entry in ipairs(Data.SymbolEffects or {}) do
                if entry.Name == name then
                    total = total + 1
                end
            end
            for _ = total + 1, 11 do
                Data.HitEffectWarmQueue[#Data.HitEffectWarmQueue + 1] = name
            end
        elseif preset == 'blood splatter' then
            phowg:queue_assets({ 'rbxassetid://16939835586' })
        else
            buildhitfx()
        end
    end
end
function phowg:clear_particle_hit_effects()
    local splatters = Data.EffectPools and Data.EffectPools.bloodsplatter
    if splatters then
        for index = #splatters.Active, 1, -1 do
            phowg:return_effect(splatters.Active[index])
        end
    end
    for _, entry in ipairs(Data.SymbolEffects or {}) do
        for _, emitter in ipairs(entry.Emitters) do
            emitter:Clear()
        end
        entry.Carrier.Parent = nil
        phowg:release_visual(entry)
        local pool = Data.SymbolEffectPools[entry.Name]
        pool[#pool + 1] = entry
    end
    Data.SymbolEffects, Data.NativeHitBursts, Data.HitEffectWarmQueue = {}, {}, {}
    if Data.HitFxPart then
        for _, emitter in pairs(Data.HitFxEmitters or {}) do
            emitter:Clear()
        end
        phowg:release_visual(Data.HitFxPart)
    end
end
function phowg:emit_symbol_hit_effect(name, root, color)
    local now = tick()
    Data.SymbolEffectTimes = Data.SymbolEffectTimes or {}
    Data.SymbolEffectPools, Data.SymbolEffects = Data.SymbolEffectPools or {}, Data.SymbolEffects or {}
    local pool = Data.SymbolEffectPools[name]
    if not pool then
        pool = {}
        Data.SymbolEffectPools[name] = pool
    end
    local entry = table.remove(pool) or phowg:new_symbol_hit_entry(name)
    if not entry then
        return
    end
    local quality = Data.CosmeticQuality or 1
    if entry.Quality ~= quality then
        local count = 0
        for index in ipairs(entry.Emitters) do
            local amount = math.max(1, math.floor(entry.BaseCounts[index] * quality))
            entry.Counts[index] = amount
            count = count + amount
        end
        entry.Quality, entry.Cost = quality, count
    end
    if not phowg:acquire_visual(entry, entry.Cost, 'particles') then
        pool[#pool + 1] = entry
        return
    end
    if entry.Color ~= color then
        local sequence = ColorSequence.new(color)
        for _, child in ipairs(entry.Colors) do
            child.Color = sequence
        end
        entry.Color = color
    end
    entry.Carrier.CFrame = root.CFrame
    entry.Carrier.Parent = Workspace:FindFirstChild('Ignored') or Workspace
    for index, emitter in ipairs(entry.Emitters) do
        emitter:Emit(entry.Counts[index])
    end
    entry.Until, Data.SymbolEffectTimes[name] = now + entry.Duration + 0.05, now
    Data.SymbolEffects[#Data.SymbolEffects + 1] = entry
end
registerheartbeat('SymbolHitEffects', function()
    local now = tick()
    local warm = Data.HitEffectWarmQueue
    if warm and #warm > 0 and Toggles.hit_effect and Toggles.hit_effect.Value then
        local name = table.remove(warm)
        local entry = phowg:new_symbol_hit_entry(name)
        if entry then
            local pool = Data.SymbolEffectPools[name]
            pool[#pool + 1] = entry
        end
    end
    local bursts, part = Data.NativeHitBursts, Data.HitFxPart
    if bursts and part then
        local changed, cost = false, 0
        for index = #bursts, 1, -1 do
            local burst = bursts[index]
            if now >= burst.Until then
                bursts[index] = bursts[#bursts]
                bursts[#bursts] = nil
                changed = true
            else
                cost = cost + burst.Cost
            end
        end
        if changed then
            if cost == 0 then
                phowg:release_visual(part)
            else
                phowg:acquire_visual(part, cost, 'particles')
            end
        end
    end
    local list = Data.SymbolEffects
    if not list then
        return
    end
    for index = #list, 1, -1 do
        local entry = list[index]
        if now >= entry.Until or not entry.Carrier.Parent or not entry.Carrier:IsDescendantOf(Workspace) then
            for _, emitter in ipairs(entry.Emitters) do
                emitter:Clear()
            end
            entry.Carrier.Parent = nil
            phowg:release_visual(entry)
            local pool = Data.SymbolEffectPools[entry.Name]
            pool[#pool + 1] = entry
            list[index] = list[#list]
            list[#list] = nil
        end
    end
end)
phowg:register_cleanup('particle hit effects', function(scope, reason)
    if reason == 'unload' or scope == LocalPlayer.Character then
        phowg:clear_particle_hit_effects()
    end
end)
phowg:register_cleanup('symbol integration', function(scope, reason)
