        for _, entry in ipairs(pool) do
            entry.Carrier:Destroy()
        end
    end
    for _, template in pairs(Data.SymbolHitTemplates or {}) do
        template:Destroy()
    end
    for _, entry in ipairs(Data.SymbolSoundPool or {}) do
        entry.Sound:Destroy()
    end
    Data.SymbolEffects, Data.SymbolEffectPools, Data.SymbolHitTemplates, Data.SymbolSoundPool = nil, nil, nil, nil
end)
Data.LarpticAuraAssets = {
    starlight = 'rbxassetid://134645216613107',
    heavenly = 'rbxassetid://139300897520961',
    ribbon = 'rbxassetid://132069507632161',
    sakura = 'rbxassetid://81755778619404',
    angel = 'rbxassetid://97658130917593',
