function phowg:larptic_aura_template(name, silent)
    Data.LarpticAuraTemplates = Data.LarpticAuraTemplates or {}
    Data.LarpticAuraLoads = Data.LarpticAuraLoads or {}
    if Data.LarpticAuraTemplates[name] then
        return Data.LarpticAuraTemplates[name]
    end
    local pending = Data.LarpticAuraLoads[name]
    if pending and not silent then
        pending.Silent = false
    end
    if pending and (pending.Loading or tick() < pending.RetryAt) then
        return nil
    end
    local asset = Data.LarpticAuraAssets[name]
    if not asset then
        return nil
    end
    local loadState =
        { Loading = true, RetryAt = 0, Notified = pending and pending.Notified or false, Silent = silent == true }
    Data.LarpticAuraLoads[name] = loadState
    phowg:queue_background('particle aura assets', name, function()
        local ok, objects = pcall(game.GetObjects, game, asset)
        local template = ok and type(objects) == 'table' and objects[1]
        if
            not Data.LarpticAuraLoads
            or Data.LarpticAuraLoads[name] ~= loadState
            or Library.Unloaded
            or Data.SharedSignalsClosed
        then
            if type(objects) == 'table' then
                for _, object in ipairs(objects) do
                    object:Destroy()
                end
            end
            return
        end
        if typeof(template) == 'Instance' then
            template.Archivable = true
            for _, object in ipairs(template:GetDescendants()) do
                if object:IsA('BaseScript') or object:IsA('ModuleScript') then
                    object:Destroy()
                else
                    object.Archivable = true
                end
            end
            template.Parent = nil
            Data.LarpticAuraTemplates[name] = template
            phowg:queue_asset_tree(template)
            for index = 2, #objects do
                objects[index]:Destroy()
            end
            loadState.Loading = false
        else
            loadState.Loading, loadState.RetryAt = false, tick() + 10
            if not loadState.Notified and not loadState.Silent then
                Library:Notify('Could not load particle aura: ' .. name, 4)
                loadState.Notified = true
            end
        end
    end, silent == true)
    return nil
end
function phowg:aura_body_part(character, name)
    local part = character:FindFirstChild(name)
    if part and part:IsA('BasePart') then
        return part
    end
    local aliases = {
        Torso = { 'UpperTorso', 'LowerTorso' },
        UpperTorso = { 'Torso' },
        LowerTorso = { 'Torso' },
        ['Left Arm'] = { 'LeftUpperArm', 'LeftLowerArm', 'LeftHand' },
        ['Right Arm'] = { 'RightUpperArm', 'RightLowerArm', 'RightHand' },
        ['Left Leg'] = { 'LeftUpperLeg', 'LeftLowerLeg', 'LeftFoot' },
        ['Right Leg'] = { 'RightUpperLeg', 'RightLowerLeg', 'RightFoot' },
        LeftUpperArm = { 'Left Arm' },
        LeftLowerArm = { 'Left Arm' },
        LeftHand = { 'Left Arm' },
        RightUpperArm = { 'Right Arm' },
        RightLowerArm = { 'Right Arm' },
        RightHand = { 'Right Arm' },
        LeftUpperLeg = { 'Left Leg' },
        LeftLowerLeg = { 'Left Leg' },
        LeftFoot = { 'Left Leg' },
        RightUpperLeg = { 'Right Leg' },
        RightLowerLeg = { 'Right Leg' },
        RightFoot = { 'Right Leg' },
    }
    for _, alias in ipairs(aliases[name] or {}) do
        part = character:FindFirstChild(alias)
        if part and part:IsA('BasePart') then
            return part
        end
    end
    return nil
end
function phowg:build_larptic_aura(state, name, cachedTemplate)
    if tick() < (state.RetryAt or 0) then
        return false
    end
    local template = cachedTemplate or phowg:larptic_aura_template(name)
    if not template then
        return false
    end
    local copy = template:Clone()
    local sources = copy:GetDescendants()
    if copy:IsA('BasePart') then
        sources[#sources + 1] = copy
    end
    for _, source in ipairs(sources) do
        if source:IsA('BasePart') then
            local target = phowg:aura_body_part(state.Character, source.Name)
            if target then
                for _, object in ipairs(source:GetChildren()) do
                    if
                        object:IsA('Attachment')
                        or object:IsA('ParticleEmitter')
                        or object:IsA('Beam')
                        or object:IsA('Trail')
                        or object:IsA('Light')
                    then
                        for _, nested in ipairs(object:GetDescendants()) do
                            local visual = nested:IsA('Attachment')
                                or nested:IsA('ParticleEmitter')
                                or nested:IsA('Beam')
                                or nested:IsA('Trail')
                                or nested:IsA('Light')
                                or nested:IsA('Folder')
                                or nested:IsA('ValueBase')
                            if not visual then
                                nested:Destroy()
                            end
                        end
                        object.Parent = target
                        state.Attachments[#state.Attachments + 1] = object
                    end
                end
            end
        end
    end
    for _, container in ipairs(state.Attachments) do
        local objects = container:GetDescendants()
        objects[#objects + 1] = container
        for _, object in ipairs(objects) do
            if object:IsA('ParticleEmitter') then
                state.Particles[#state.Particles + 1] = object
            elseif object:IsA('Beam') or object:IsA('Trail') then
                if
                    object.Attachment0
                    and object.Attachment1
                    and object.Attachment0:IsDescendantOf(state.Character)
                    and object.Attachment1:IsDescendantOf(state.Character)
                then
                    state.Decorations[#state.Decorations + 1] = object
                else
                    object:Destroy()
                end
            elseif object:IsA('Light') then
                state.Lights[#state.Lights + 1] = object
            end
        end
    end
    copy:Destroy()
    if #state.Particles + #state.Decorations + #state.Lights == 0 then
        for _, object in ipairs(state.Attachments) do
            object:Destroy()
        end
        table.clear(state.Attachments)
        state.RetryAt = tick() + 0.5
        return false
    end
    return true
end
