function phowg:warm_aura_caches()
    if phowg.warm_native_aura_caches then
        phowg:warm_native_aura_caches()
    end
    for name in pairs(Data.LarpticAuraAssets or {}) do
        phowg:larptic_aura_template(name, true)
    end
    for _, name in ipairs({ 'Angelic', 'Ambient', 'Nimb', 'Tornado' }) do
        phowg:queue_background('aura templates', name, function()
            if Data.SharedSignalsClosed or Library.Unloaded then
                return
            end
            Data.ProceduralAuraTemplates = Data.ProceduralAuraTemplates or {}
            if Data.ProceduralAuraTemplates[name] then
                return
            end
            local model = Instance.new('Model')
            model.Name = 'aura cache'
            for _, partName in ipairs({ 'Torso', 'Head', 'HumanoidRootPart' }) do
                local part = Instance.new('Part')
                part.Name = partName
                part.Anchored = true
                part.Transparency = 1
                part.Parent = model
            end
            local state = { Character = model, Attachments = {}, Particles = {}, Decorations = {}, Lights = {} }
            local ok, problem = pcall(phowg_callbacks.build_procedural_aura, state, name)
            if not ok or Library.Unloaded or Data.SharedSignalsClosed then
                model:Destroy()
                if not ok then
                    warn('[phowg] aura cache: ' .. tostring(problem))
                end
                return
            end
            for _, emitter in ipairs(state.Particles) do
                emitter.Enabled = false
            end
            Data.ProceduralAuraTemplates[name] = model
            phowg:queue_asset_tree(model)
        end)
    end
end
function phowg:build_symbol_aura(state, name)
    local template = Data.ProceduralAuraTemplates and Data.ProceduralAuraTemplates[name]
    if template then
        return phowg:build_larptic_aura(state, name, template)
    end
    return phowg:build_procedural_aura(state, name)
end
phowg:register_cleanup('aura caches', function(_, reason)
    if reason ~= 'unload' then
        return
    end
    for _, template in pairs(Data.ProceduralAuraTemplates or {}) do
        template:Destroy()
    end
    for _, template in pairs(Data.NativeAuraTemplates or {}) do
        template:Destroy()
    end
    Data.ProceduralAuraTemplates, Data.NativeAuraTemplates = nil, nil
end)

function phowg:clear_desync_aura()
    local state = Data.DesyncAuraState
    Data.DesyncAuraState = nil
    if not state then
        return
    end
    for _, object in ipairs(state.Attachments) do
        object:Destroy()
    end
    phowg:release_visual(state)
end
function phowg:sync_desync_aura()
    local model = Data.VisualizeModel
    if
        Library.Unloaded
        or Data.SharedSignalsClosed
        or Data.IsRespawning
        or not phowg:toggle_enabled('local_particle_aura')
        or not phowg:toggle_enabled('local_particle_aura_desync')
        or not Data.VisualShown
        or not model
        or not model.Parent
    then
        phowg:clear_desync_aura()
        return
    end
    local key = Options.local_particle_aura_value and Options.local_particle_aura_value.Value or 'swirl'
    local state = Data.DesyncAuraState
    if state and (state.Character ~= model or state.Key ~= key) then
        phowg:clear_desync_aura()
        state = nil
    end
    if not state then
        state = {
            Character = model,
            Key = key,
            Attachments = {},
            Particles = {},
            Decorations = {},
            Lights = {},
            Rates = {},
            Built = false,
            Enabled = false,
        }
        Data.DesyncAuraState = state
    end
    if not state.Built then
        if Data.SymbolAuraNames[key] then
            if not phowg:build_symbol_aura(state, key) then
                return
            end
        else
            local root = model:FindFirstChild('HumanoidRootPart')
            local name = tostring(key):sub(1, 1):upper() .. tostring(key):sub(2):lower()
            local template = phowg.native_aura_template and phowg:native_aura_template(name)
            if not root or not template then
                return
            end
            local attachment = Instance.new('Attachment')
            attachment.Name = 'PhowgDesyncAura'
            attachment.Position = name == 'Rain' and Vector3.new(0, 3.5, 0) or Vector3.zero
            attachment.Parent = root
            state.Attachments[#state.Attachments + 1] = attachment
            for _, source in ipairs(template:GetChildren()) do
                if source:IsA('ParticleEmitter') then
                    local emitter = source:Clone()
                    emitter.Parent = attachment
                    state.Particles[#state.Particles + 1] = emitter
                end
            end
        end
        state.Built = true
        for _, emitter in ipairs(state.Particles) do
            state.Rates[emitter] = emitter.Rate
            emitter.Enabled = false
        end
        phowg:preload_visual_assets(state.Particles)
    end
    local color = Options.local_particle_aura_color and Options.local_particle_aura_color.Value or Color3.new(1, 1, 1)
    local quality = math.clamp(Data.CosmeticQuality or 1, 0, 1)
    local budget = phowg:visual_number('cosmetic_budget', 2000, 100, 10000)
    if state.Color ~= color or state.Quality ~= quality or state.Budget ~= budget then
        local sequence, cost = ColorSequence.new(color), 0
        for _, emitter in ipairs(state.Particles) do
            emitter.Color, emitter.Rate = sequence, state.Rates[emitter] * quality
            cost += emitter.Rate * emitter.Lifetime.Max
        end
        local fixed = #state.Decorations + #state.Lights * 4
        local allowance = math.max(0, budget * 0.3 - fixed)
        if cost > allowance then
            local factor = allowance / cost
            for _, emitter in ipairs(state.Particles) do
                emitter.Rate *= factor
            end
            cost = allowance
        end
        for _, object in ipairs(state.Decorations) do
            object.Color = sequence
        end
        for _, object in ipairs(state.Lights) do
            object.Color = color
        end
        state.Color, state.Quality, state.Budget, state.Cost = color, quality, budget, cost + fixed
    end
    local enabled = phowg:acquire_visual(state, state.Cost or 0, 'desync aura')
    if not enabled then
        phowg:release_visual(state)
    end
    if state.Enabled ~= enabled then
        for _, object in ipairs(state.Particles) do
            object.Enabled = enabled
        end
        for _, object in ipairs(state.Decorations) do
            object.Enabled = enabled
        end
        for _, object in ipairs(state.Lights) do
            object.Enabled = enabled
        end
        state.Enabled = enabled
    end
end
phowg:register_cleanup('desync aura', function(scope)
    local state = Data.DesyncAuraState
    if not scope or state and scope == state.Character then
        phowg:clear_desync_aura()
    end
end)
function phowg:clear_symbol_auras()
    local state = Data.SymbolAuraState
    if not state then
        return
    end
    for _, connection in ipairs(state.Connections) do
        connection:Disconnect()
    end
    for _, attachment in ipairs(state.Attachments) do
        attachment:Destroy()
    end
    phowg:release_visual(state)
    Data.SymbolAuraState = nil
end
Data.SymbolAuraNames = { Angelic = true, Ambient = true, Nimb = true, Tornado = true }
for name in pairs(Data.LarpticAuraAssets) do
    Data.SymbolAuraNames[name] = true
end
function phowg:sync_local_symbol_auras()
    local character = LocalPlayer.Character
    if
        Library.Unloaded
        or Data.IsRespawning
        or not character
        or not character.Parent
        or not (Toggles.local_particle_aura and Toggles.local_particle_aura.Value)
    then
        phowg:clear_symbol_auras()
        return
    end
    local key = Options.local_particle_aura_value and Options.local_particle_aura_value.Value
    if not Data.SymbolAuraNames[key] then
        phowg:clear_symbol_auras()
        return
    end
    local state = Data.SymbolAuraState
    if state and (state.Character ~= character or state.Key ~= key or state.Dirty) then
        phowg:clear_symbol_auras()
        state = nil
    end
    if not state then
        state = {
            Character = character,
            Key = key,
            Attachments = {},
            Particles = {},
            Rates = {},
            Lights = {},
            Decorations = {},
            Connections = {},
            Dirty = false,
        }
        Data.SymbolAuraState = state
    end
    if not state.Built then
        if not phowg:build_symbol_aura(state, key) then
            return
        end
        state.Built = true
        for _, emitter in ipairs(state.Particles) do
            state.Rates[emitter] = emitter.Rate
            emitter.Enabled = false
        end
        for _, object in ipairs(state.Decorations) do
            object.Enabled = false
        end
        for _, object in ipairs(state.Lights) do
            object.Enabled = false
        end
        phowg:preload_visual_assets(state.Particles)
        local function dirty(part)
            local anchor = Data.LarpticAuraAssets[state.Key] and part:IsA('BasePart')
                or state.Key == 'Angelic' and (part.Name == 'Torso' or part.Name == 'UpperTorso')
                or state.Key == 'Nimb' and part.Name == 'Head'
                or (state.Key == 'Ambient' or state.Key == 'Tornado') and part.Name == 'HumanoidRootPart'
            if anchor then
                state.Dirty = true
            end
        end
        state.Connections[1] = connectshared(
            character.ChildAdded,
            dirty,
            character,
            'symbol aura parts added',
            0,
            'event/ChildAdded',
            character
        )
        state.Connections[2] = connectshared(
            character.ChildRemoved,
            dirty,
            character,
            'symbol aura parts removed',
            0,
            'event/ChildRemoved',
            character
        )
    end
    local color = Options.local_particle_aura_color and Options.local_particle_aura_color.Value
        or Color3.fromRGB(0, 255, 38)
    local quality = math.clamp(Data.CosmeticQuality or 1, 0, 1)
    local budget = phowg:visual_number('cosmetic_budget', 2000, 100, 10000)
    if state.Color ~= color or state.Quality ~= quality or state.Budget ~= budget then
        local sequence, cost = ColorSequence.new(color), 0
        for _, emitter in ipairs(state.Particles) do
            emitter.Color, emitter.Rate = sequence, state.Rates[emitter] * quality
            cost = cost + emitter.Rate * emitter.Lifetime.Max
        end
        local fixedCost = #state.Decorations + #state.Lights * 4
        local allowance = math.max(1, budget * 0.65 - fixedCost)
        if Data.LarpticAuraAssets[state.Key] and cost > allowance then
            local factor = allowance / cost
            for _, emitter in ipairs(state.Particles) do
                emitter.Rate *= factor
            end
            cost = allowance
        end
        for _, object in ipairs(state.Decorations) do
            object.Color = sequence
        end
        for _, object in ipairs(state.Lights) do
            object.Color = color
        end
        cost += fixedCost
        state.Color, state.Quality, state.Cost, state.Budget = color, quality, cost, budget
    end
    local allowed = state.Enabled
    if state.LeaseCost ~= state.Cost or not state.Enabled then
        allowed = phowg:acquire_visual(state, state.Cost or 0, 'particles')
        state.LeaseCost = state.Cost
    end
    if state.Enabled ~= allowed then
        for _, emitter in ipairs(state.Particles) do
            emitter.Enabled = allowed
        end
        for _, object in ipairs(state.Decorations) do
            object.Enabled = allowed
        end
        for _, object in ipairs(state.Lights) do
            object.Enabled = allowed
        end
        state.Enabled = allowed
        if not allowed then
            phowg:release_visual(state)
        end
    end
end
function phowg:sync_symbol_auras()
    if phowg:defer_config_effect('auras', phowg.sync_symbol_auras) then return end
    phowg:sync_local_symbol_auras()
    phowg:sync_desync_aura()
end
phowg:register_cleanup('symbol auras', function(scope, reason)
    local state = Data.SymbolAuraState
    if reason == 'unload' or state and scope == state.Character then
        phowg:clear_symbol_auras()
    end
    if reason == 'unload' then
        for _, template in pairs(Data.LarpticAuraTemplates or {}) do
            template:Destroy()
        end
        Data.LarpticAuraTemplates, Data.LarpticAuraLoads = {}, {}
    end
end)

