    ['Cosmic'] = function()
        local Part = Instance.new('Attachment')

        local Attachment = Instance.new('Attachment', Part)
        local colorSeq = ColorSequence.new(Color3.new(1, 1, 1))

        local function create_p(tex, size, life)
            local p = Instance.new('ParticleEmitter', Attachment)
            p.Color = colorSeq
            p.Texture = tex
            p.Size = size
            p.Lifetime = life
            p.Brightness = 5
            return p
        end
        create_p('rbxassetid://8708637750', NumberSequence.new(9, 16), NumberRange.new(0.16))
        create_p('rbxassetid://8196169974', NumberSequence.new(0, 11), NumberRange.new(0.3))

        for _, emitter in ipairs(Part:GetDescendants()) do
            if emitter:IsA('ParticleEmitter') then
                emitter.Enabled = false
                emitter.Rate = 1
            end
        end
        return Part
    end,
    ['CrescentSlash'] = function()
        local Part = Instance.new('Attachment')

