    blood.Acceleration, blood.Color = Vector3.new(0, -75, 0), ColorSequence.new(Color3.new(1, 1, 1))
    blood.Lifetime, blood.Orientation = NumberRange.new(0.25, 0.5), Enum.ParticleOrientation.VelocityParallel
    blood.Size = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0.125), NumberSequenceKeypoint.new(1, 0.25, 0.1) })
    blood.Speed, blood.SpreadAngle, blood.Texture =
        NumberRange.new(5, 15), Vector2.new(90, 90), 'rbxassetid://4509687978'
    blood.Transparency = NumberSequence.new({
        NumberSequenceKeypoint.new(0, 1),
        NumberSequenceKeypoint.new(0.25, 0),
        NumberSequenceKeypoint.new(1, 1),
    })
    blood.Enabled, blood.Rate, blood.Parent = false, 0, attachment
    blood:SetAttribute('EmitCount', 3)
    return attachment
end
