function phowg:symbol_hit_template(name)
    Data.SymbolHitTemplates = Data.SymbolHitTemplates or {}
    local templates = Data.SymbolHitTemplates
    if templates[name] then
        return templates[name]
    end
    local sample = Data.SampleHitBuilders[name]
    if sample then
        templates[name] = sample()
    else
        local factory = Data.SymbolHitBuilders[name]
        if factory then
            factory(templates)
        end
    end
    return templates[name]
end

