function phowg:selected_hit_sound()
    local sel = (Options.hit_sound_value and Options.hit_sound_value.Value) or 'gamesense'
    local id = nil
    if sel == 'custom' then
        id = Data['CustomHitSoundText'] or ''
        if id ~= '' and not string.find(id, 'rbxassetid') then
            id = 'rbxassetid://' .. id
        end
    elseif type(sel) == 'string' and (Data.SymbolSoundNames[sel] or sel:sub(1, 9) == 'symbol / ') then
        id = phowg:resolve_symbol_sound(sel)
    else
        id = Data['HitSounds'][sel] or Data['HitSounds'].gamesense
    end
    if not id or id == '' then
        return
    end
    return id
end
function playhitsound()
    local id = phowg:selected_hit_sound()
    if not id then
        return false
    end
    local vol = ((Options.hit_sound_volume and Options.hit_sound_volume.Value) or 20) / 20
    phowg:play_cached_hit_sound(id, vol, phowg:visual_number('hit_sound_pitch', 1, 0.1, 3))
    return true
end
function phowg:preview_hit_sound()
    local selected = Options.hit_sound_value and Options.hit_sound_value.Value
    local function play()
        if
            Library.Unloaded
            or Data.SharedSignalsClosed
            or Options.hit_sound_value and Options.hit_sound_value.Value ~= selected
        then
            return
        end
        local id = phowg:selected_hit_sound()
        if not id then
            return
        end
        phowg:queue_assets({ id })
        local sound = Data.HitSoundPreview
        if not sound or not sound.Parent then
            sound = Instance.new('Sound')
            sound.Name, sound.Parent, sound.PlayOnRemove, sound.Looped = 'PhowgHitSoundPreview', Workspace, false, false
            Data.HitSoundPreview = sound
        end
        sound:Stop()
        sound.SoundId, sound.Volume, sound.PlaybackSpeed, sound.TimePosition =
            id,
            ((Options.hit_sound_volume and Options.hit_sound_volume.Value) or 20) / 20,
            phowg:visual_number('hit_sound_pitch', 1, 0.1, 3),
            0
        sound:Play()
    end
    if phowg:selected_hit_sound() then
        play()
    else
        phowg:queue_background('sound assets', 'preview selected hitsound', play)
    end
end
phowg:register_cleanup('hitsound preview', function(_, reason)
    if reason ~= 'unload' then
        return
    end
    if Data.HitSoundPreview then
        Data.HitSoundPreview:Stop()
        Data.HitSoundPreview:Destroy()
        Data.HitSoundPreview = nil
    end
end)
function mkhitfxemitter(parent, name, props)
    local em = Instance.new('ParticleEmitter')
    em.Name = name
    for k, v in pairs(props) do
        em[k] = v
    end
    em.Enabled = false
    em.Rate = 0
    em.Parent = parent
    return em
end
