        FlipbookLayout = Enum.ParticleFlipbookLayout.Grid4x4,
        FlipbookMode = Enum.ParticleFlipbookMode.OneShot,
        Lifetime = NumberRange.new(0.67, 0.67),
        LightEmission = -5,
        RotSpeed = NumberRange.new(-10, 10),
        Rotation = NumberRange.new(-1000, 1000),
        Size = NumberSequence.new({ NumberSequenceKeypoint.new(0, 3), NumberSequenceKeypoint.new(1, 3) }),
        Speed = NumberRange.new(0, 0),
        SpreadAngle = Vector2.new(-1000, 1000),
        Texture = 'rbxassetid://11517935503',
        Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0), NumberSequenceKeypoint.new(1, 1) }),
    })
    mkhitfxemitter(part, 'splash', {
        Acceleration = Vector3.new(0, -25, 0),
        Color = ColorSequence.new({
            ColorSequenceKeypoint.new(0, Color3.new(0.2, 0.6, 1)),
            ColorSequenceKeypoint.new(1, Color3.new(0.1, 0.3, 1)),
        }),
        Lifetime = NumberRange.new(0.5, 0.5),
        LightEmission = 0.5,
        Size = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0.4), NumberSequenceKeypoint.new(1, 0) }),
        Speed = NumberRange.new(15, 15),
        SpreadAngle = Vector2.new(50, 50),
        Texture = 'rbxassetid://1084991215',
        Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0), NumberSequenceKeypoint.new(1, 1) }),
    })
    local holder = Workspace:FindFirstChild('Ignored') or Workspace
    part.Parent = holder
    Data['HitFxPart'] = part
    Data.HitFxEmitters = {}
    local emitters = part:GetChildren()
    for _, emitter in ipairs(emitters) do
        Data.HitFxEmitters[emitter.Name] = emitter
    end
    Data.HitFxColor = nil
    phowg:preload_visual_assets(emitters)
    return part
end
Data.NativeHitPresets = {
    bubble = { { 'bubble1', 'bubble2', 'bubble3' }, 1 },
    sparks = { { 'sparks' }, 30 },
    air = { { 'air', 'air2' }, 15 },
    splash = { { 'splash' }, 7 },
    bits = { { 'bits' }, 9 },
    flame = { { 'flame' }, 1 },
}
function hiteffect(plr)
    local char = plr.Character or intelligence:get_character_cache(plr)
    local hrp = char and char:FindFirstChild('HumanoidRootPart')
    if not hrp or not phowg:cosmetic_visible(hrp.Position) then
        return
    end
    if not Data.HitEffectPresets then
        phowg:prepare_hit_effects(Options.hit_effect_value and Options.hit_effect_value.Value)
    end
    local presets, map = Data.HitEffectPresets, Data.NativeHitPresets
    local quality, color =
        Data.CosmeticQuality or 1,
        Options.hit_effect_color and Options.hit_effect_color.Value or Color3.fromRGB(255, 255, 255)
    local count, lifetime = 0, 0
    local part
    for _, preset in ipairs(presets) do
        if preset ~= 'blood splatter' and not Data.SymbolEffectNames[preset] then
            part = part or buildhitfx()
            local effect = map[preset] or map.sparks
            for _, name in ipairs(effect[1]) do
                local emitter = Data.HitFxEmitters[name]
                count = count + math.max(1, math.floor(effect[2] * quality))
                lifetime = math.max(lifetime, emitter.Lifetime.Max)
            end
        end
    end
    if part then
        local previous = Data.VisualLeases[part]
        if phowg:acquire_visual(part, count + (previous and previous.Cost or 0), 'particles') then
            Data.NativeHitBursts = Data.NativeHitBursts or {}
            Data.NativeHitBursts[#Data.NativeHitBursts + 1] = { Cost = count, Until = tick() + lifetime }
            part.CFrame = hrp.CFrame
            if Data.HitFxColor ~= color then
                local sequence = ColorSequence.new(color)
                for _, emitter in pairs(Data.HitFxEmitters) do
                    emitter.Color = sequence
                end
                Data.HitFxColor = color
            end
        else
            part = nil
        end
    end
    for _, preset in ipairs(presets) do
        local symbol = Data.SymbolEffectNames[preset]
        if preset == 'blood splatter' then
            phowg:emit_blood_splatter(char, hrp, color)
        elseif symbol then
            phowg:run_hit_feedback('hit effect/' .. symbol, phowg_callbacks.emit_symbol_hit_effect, symbol, hrp, color)
        elseif part then
            local effect = map[preset] or map.sparks
            local amount = math.max(1, math.floor(effect[2] * quality))
            for _, name in ipairs(effect[1]) do
                Data.HitFxEmitters[name]:Emit(amount)
            end
        end
    end
end
function clearhitskeletons()
    if Data['HitSkeletons'] then
        for skel, _ in pairs(Data['HitSkeletons']) do
            for _, d in ipairs(skel.draw) do
                if d.Remove then
                    d:Remove()
                end
            end
            Data['HitSkeletons'][skel] = nil
        end
    end
end
function ensurehitskelconn()
    if Data['HitSkelConn'] then
        return
    end
    Data['HitSkelConn'] = phowg:register_render(function()
        local list = Data['HitSkeletons']
        if not list or next(list) == nil then
            if Data['HitSkelConn'] then
                Data['HitSkelConn']:Disconnect()
            end
            Data['HitSkelConn'] = nil
            return
        end
        local cam = Workspace.CurrentCamera
        if not cam then
            return
        end
        local now = tick()
        for skel, _ in pairs(list) do
            local age = now - skel.t0
            if age > skel.life then
                for _, d in ipairs(skel.draw) do
                    if d.Remove then
                        d:Remove()
                    end
                end
                list[skel] = nil
            else
                local alpha = 1
                if skel.fade then
                    alpha = 1 - (age / skel.life)
                end
                for _, s in ipairs(skel.segs) do
                    local a = s[1]
                    local b = s[2]
                    if a.Parent and b.Parent then
                        local pa, onA = cam:WorldToViewportPoint(a.Position)
                        local pb, onB = cam:WorldToViewportPoint(b.Position)
                        if onA and onB then
                            s[3].From = Vector2.new(pa.X, pa.Y)
                            s[3].To = Vector2.new(pb.X, pb.Y)
                            s[3].Transparency = 1 - alpha
                            s[3].Visible = true
                            s[4].From = Vector2.new(pa.X, pa.Y)
                            s[4].To = Vector2.new(pb.X, pb.Y)
                            s[4].Transparency = 1 - alpha
                            s[4].Visible = true
                        else
                            s[3].Visible = false
                            s[4].Visible = false
                        end
                    else
                        s[3].Visible = false
                        s[4].Visible = false
                    end
                end
            end
        end
    end, RunService, 'frame/hit skeletons')
end
function spawnhitskeleton(plr)
    if not (Drawing and Drawing.new) then
        return
    end
    local char = intelligence:get_character_cache(plr) or nil
    if not char then
        return
    end
    if Toggles.hit_skeleton_last_hit and Toggles.hit_skeleton_last_hit.Value then
        clearhitskeletons()
    end
    local col = (Options.hit_skeleton_color and Options.hit_skeleton_color.Value) or Color3.fromRGB(255, 255, 255)
    local life = (Options.hit_skeleton_life and Options.hit_skeleton_life.Value) or 1.5
    local fade = Toggles.hit_skeleton_fade and Toggles.hit_skeleton_fade.Value
    if not fade then
        fade = false
    end
    local function part(n)
        local p = char:FindFirstChild(n)
        if p and p:IsA('BasePart') then
            return p
        end
        return nil
    end
    local limbPairs = {}
    local head = part('Head')
    local upper = part('UpperTorso')
    local torso = part('Torso')
    local hub = upper or torso
    local lower = part('LowerTorso')
    local legHub = lower or hub
    local armL = part('LeftUpperArm') or part('Left Arm')
    local armR = part('RightUpperArm') or part('Right Arm')
    local legL = part('LeftUpperLeg') or part('Left Leg')
    local legR = part('RightUpperLeg') or part('Right Leg')
    if head and hub then
        table.insert(limbPairs, { head, hub })
    end
    if upper and lower then
        table.insert(limbPairs, { upper, lower })
    end
    if hub and armL then
        table.insert(limbPairs, { hub, armL })
    end
    if hub and armR then
        table.insert(limbPairs, { hub, armR })
    end
    if legHub and legL then
        table.insert(limbPairs, { legHub, legL })
    end
    if legHub and legR then
        table.insert(limbPairs, { legHub, legR })
    end
    if #limbPairs == 0 then
        return
    end
    local skel = { t0 = tick(), life = life, fade = fade, segs = {}, draw = {} }
    local ok = true
    (function()
        for _, pr in ipairs(limbPairs) do
            local out = Drawing.new('Line')
            out.Thickness = 4
            out.Color = Color3.new(0, 0, 0)
            out.Transparency = 1
            out.Visible = false
            out.ZIndex = 1
            local ln = Drawing.new('Line')
            ln.Thickness = 2
            ln.Color = col
            ln.Transparency = 1
            ln.Visible = false
            ln.ZIndex = 2
            table.insert(skel.draw, out)
            table.insert(skel.draw, ln)
            table.insert(skel.segs, { pr[1], pr[2], ln, out })
        end
    end)()
    if not ok or #skel.segs == 0 then
        for _, d in ipairs(skel.draw) do
            if d.Remove then
                d:Remove()
            end
        end
        return
    end
    if Data['HitSkeletons'] == nil then
        Data['HitSkeletons'] = {}
    end
    Data['HitSkeletons'][skel] = true
    ensurehitskelconn()
end
function hitmarker2d()
    if not (Drawing and Drawing.new) then
        return
    end
    local col = (Options.hit_marker_color and Options.hit_marker_color.Value) or Color3.fromRGB(255, 255, 255)
    local offs = { Vector2.new(1, 1), Vector2.new(-1, 1), Vector2.new(1, -1), Vector2.new(-1, -1) }
    local lines = {}
    local ok = true
    (function()
        for i = 1, 4 do
            local out = Drawing.new('Line')
            out.Thickness = 3
            out.ZIndex = 1
            out.Transparency = 1
            out.Visible = true
            out.Color = Color3.new(0, 0, 0)
            local ln = Drawing.new('Line')
            ln.Thickness = 1
            ln.ZIndex = 2
            ln.Transparency = 1
            ln.Visible = true
            ln.Color = col
            lines[i] = { out, ln }
        end
    end)()
    if not ok then
        return
    end
    task.spawn(function()
        local t0 = tick()
        while tick() - t0 < 0.73 do
            local dt = tick() - t0
            local tw = 0
            if dt > 0.6 then
                tw = math.clamp((dt - 0.6) / 0.12, 0, 1)
            end
            local mp = UserInputService:GetMouseLocation()
            for i = 1, 4 do
                local o = offs[i]
                local from = mp + o * 5
                local to = from + o * 4
                for _, ln in ipairs(lines[i]) do
                    ln.From = from
                    ln.To = to
                    ln.Transparency = 1 - tw
                    ln.Visible = true
                end
            end
            RunService.Heartbeat:Wait()
        end
        for _, pair in ipairs(lines) do
            for _, ln in ipairs(pair) do
                if ln.Remove then
                    ln:Remove()
                end
            end
        end
    end)
end
function hitmarker3d(plr)
    if not (Drawing and Drawing.new) then
        return
    end
    local char = intelligence:get_character_cache(plr) or nil
    local hrp = char and char:FindFirstChild('HumanoidRootPart') or nil
    if not hrp then
        return
    end
    local col = (Options.hit_marker_color and Options.hit_marker_color.Value) or Color3.fromRGB(255, 255, 255)
    local offs = { Vector2.new(1, 1), Vector2.new(-1, 1), Vector2.new(1, -1), Vector2.new(-1, -1) }
    local lines = {}
    local ok = true
    (function()
        for i = 1, 4 do
            local out = Drawing.new('Line')
            out.Thickness = 3
            out.ZIndex = 1
            out.Transparency = 1
            out.Color = Color3.new(0, 0, 0)
            local ln = Drawing.new('Line')
            ln.Thickness = 1
            ln.ZIndex = 2
            ln.Transparency = 1
            ln.Color = col
            lines[i] = { out, ln }
        end
    end)()
    if not ok then
        return
    end
    task.spawn(function()
        local t0 = tick()
        while tick() - t0 < 0.73 do
            local dt = tick() - t0
            local tw = 0
            if dt > 0.6 then
                tw = math.clamp((dt - 0.6) / 0.12, 0, 1)
            end
            local cam = Workspace.CurrentCamera
            if hrp.Parent and cam then
                local sp, on = cam:WorldToViewportPoint(hrp.Position)
                if on then
                    local mp = Vector2.new(sp.X, sp.Y)
                    for i = 1, 4 do
                        local o = offs[i]
                        local from = mp + o * 5
                        local to = from + o * 4
                        for _, ln in ipairs(lines[i]) do
                            ln.From = from
                            ln.To = to
                            ln.Transparency = 1 - tw
                            ln.Visible = true
                        end
                    end
                else
                    for _, pair in ipairs(lines) do
                        for _, ln in ipairs(pair) do
                            ln.Visible = false
                        end
                    end
                end
            else
                for _, pair in ipairs(lines) do
                    for _, ln in ipairs(pair) do
                        ln.Visible = false
                    end
                end
            end
            RunService.Heartbeat:Wait()
        end
        for _, pair in ipairs(lines) do
            for _, ln in ipairs(pair) do
                if ln.Remove then
                    ln:Remove()
                end
            end
        end
    end)
end
function phowg:get_effect(kind, cost, factory, capacity)
    Data.EffectPools = Data.EffectPools or {}
    local pool = Data.EffectPools[kind]
    if not pool then
        pool = { Free = {}, Active = {}, Count = 0, Capacity = capacity }
        Data.EffectPools[kind] = pool
    end
    local entry = table.remove(pool.Free)
    if not entry then
        if pool.Count >= pool.Capacity then
            return nil
        end
        local ok, result = pcall(factory)
        if not ok or not result then
            return nil
        end
        entry, pool.Count = result, pool.Count + 1
    end
    if not phowg:acquire_visual(entry, cost, kind) then
        pool.Free[#pool.Free + 1] = entry
        return nil
    end
    entry.At, entry.Pool, entry.Active = tick(), pool, true
    entry.ActiveIndex = #pool.Active + 1
    pool.Active[entry.ActiveIndex] = entry
    return entry
end
function phowg:return_effect(entry)
    if not entry.Active then
        return
    end
    entry.Active = false
    local active = entry.Pool.Active
    local index = entry.ActiveIndex
    if not index or active[index] ~= entry then
        index = table.find(active, entry)
    end
    if index then
        local last = table.remove(active)
        if index <= #active then
            active[index] = last
            last.ActiveIndex = index
        end
    end
    entry.ActiveIndex = nil
    phowg:release_visual(entry)
    if entry.Text then
        entry.Text.Visible = false
    end
    if entry.Model then
        entry.Model.Parent = nil
    end
    if entry.Part then
        entry.Part.Parent = nil
        for _, child in ipairs(entry.Part:GetChildren()) do
            if child:IsA('ParticleEmitter') then
                child:Clear()
            end
        end
    end
    entry.Pool.Free[#entry.Pool.Free + 1] = entry
end
function phowg:clear_effects(scope)
    for _, pool in pairs(Data.EffectPools or {}) do
        for _, entries in ipairs({ pool.Free, pool.Active }) do
            for index = #entries, 1, -1 do
                local entry = entries[index]
                if not scope or entry.Character == scope then
                    phowg:release_visual(entry)
                    if entry.Text then
                        pcall(function()
                            entry.Text:Remove()
                        end)
                    end
                    if entry.Model then
                        entry.Model:Destroy()
                    end
                    if entry.Part then
                        entry.Part:Destroy()
                    end
                    table.remove(entries, index)
                    if entries == pool.Active then
                        for remaining = index, #entries do entries[remaining].ActiveIndex = remaining end
                    end
                    entry.ActiveIndex = nil
                    pool.Count -= 1
                    if Data.HitChamEntry == entry then
                        Data.HitChamPrev, Data.HitChamEntry = nil, nil
                    end
                end
            end
        end
    end
    if not scope then
        Data.EffectPools, Data.HitChamPrev, Data.HitChamEntry = nil, nil, nil
    end
end
function phowg:update_effects()
    local now, camera = tick(), Workspace.CurrentCamera
    for kind, pool in pairs(Data.EffectPools or {}) do
        for index = #pool.Active, 1, -1 do
            local entry = pool.Active[index]
            local age = now - entry.At
            local toggle = (kind == 'damage' or kind == 'damage_fortnite') and 'damage_number'
                or kind == 'hitchams' and 'hit_chams'
                or kind == 'impact' and 'bullet_impacts'
                or kind == 'jumpcircle' and 'jump_circles'
                or kind == 'rainsplash' and 'world_weather'
                or 'hit_effect'
            if not entry.Active or age >= entry.Lifetime or not (Toggles[toggle] and Toggles[toggle].Value) then
                phowg:return_effect(entry)
            elseif entry.Update then
                local ok = pcall(entry.Update, entry, age, camera)
                if not ok then
                    phowg:return_effect(entry)
                end
            end
        end
    end
end
function phowg:new_jump_circle()
    local part = Instance.new('Part')
    part.Name, part.Anchored, part.Transparency, part.CastShadow = 'PhowgJumpCircle', true, 1, false
    part.CanCollide, part.CanTouch, part.CanQuery = false, false, false
    part.Size = Vector3.new(1, 0.02, 1)
    local surface = Instance.new('SurfaceGui')
    surface.Name, surface.Adornee, surface.Face = 'CircleSurface', part, Enum.NormalId.Top
    surface.SizingMode, surface.CanvasSize = Enum.SurfaceGuiSizingMode.FixedSize, Vector2.new(256, 256)
    surface.LightInfluence, surface.AlwaysOnTop, surface.Parent = 0, false, part
    local rings = {}
    for index = 1, 3 do
        local frame = Instance.new('Frame')
        frame.AnchorPoint, frame.Position = Vector2.new(0.5, 0.5), UDim2.fromScale(0.5, 0.5)
        frame.Size = UDim2.fromScale(index == 3 and 0.76 or 0.93, index == 3 and 0.76 or 0.93)
        frame.BackgroundTransparency, frame.BorderSizePixel, frame.Parent = 1, 0, surface
        local corner = Instance.new('UICorner')
        corner.CornerRadius, corner.Parent = UDim.new(0.5, 0), frame
        local stroke = Instance.new('UIStroke')
        stroke.ApplyStrokeMode, stroke.Thickness =
            Enum.ApplyStrokeMode.Border, index == 1 and 7 or index == 2 and 2 or 1
        stroke.Transparency, stroke.Parent = 1, frame
        rings[index] = { Frame = frame, Stroke = stroke }
    end
    return { Model = part, Surface = surface, Stroke = rings[2].Stroke, Rings = rings }
end
function phowg:set_ground_ring_color(entry, color)
    for _, ring in ipairs(entry.Rings) do
        ring.Stroke.Color = color
    end
end
function phowg:ground_ring_c_frame(hit)
    local normal = hit.Normal.Unit
    local tangent = math.abs(normal:Dot(Vector3.yAxis)) > 0.98 and Vector3.xAxis or Vector3.yAxis:Cross(normal).Unit
    return CFrame.fromMatrix(hit.Position + normal * 0.035, tangent, normal, tangent:Cross(normal).Unit)
end
function phowg:animate_jump_circle(entry, age)
    local progress = math.clamp(age / entry.Lifetime, 0, 1)
    local scale = Library.ReducedMotion and 1 or 0.25 + 0.75 * (1 - (1 - progress) ^ 3)
    local diameter = entry.Radius * 2 * scale
    entry.Model.Size = Vector3.new(diameter, 0.02, diameter)
    local visibility = math.min(1, age / 0.045) * (1 - progress) ^ 0.8
    entry.Rings[1].Stroke.Transparency = 1 - visibility * 0.16
    entry.Rings[2].Stroke.Transparency = 1 - visibility
    entry.Rings[3].Stroke.Transparency = 1 - visibility * 0.5
    local inner = Library.ReducedMotion and 0.76 or 0.58 + 0.23 * progress
    entry.Rings[3].Frame.Size = UDim2.fromScale(inner, inner)
end
function phowg:emit_jump_circle(player, character, humanoid)
    if
        Library.Unloaded
        or Data.SharedSignalsClosed
        or not phowg:toggle_enabled('jump_circles')
        or not character
        or not character.Parent
        or humanoid.Health < 1
    then
        return
    end
    local root = character:FindFirstChild('HumanoidRootPart')
    if not root then
        return
    end
    local position = root.Position
    if player == LocalPlayer then
        local getter = getgenv().PhowgGetClientCFrame
        local cf = type(getter) == 'function' and getter()
        if typeof(cf) == 'CFrame' then
            position = cf.Position
        end
    end
    if not phowg:cosmetic_visible(position) then
        return
    end
    local params = RaycastParams.new()
    params.FilterType, params.RespectCanCollide, params.IgnoreWater = Enum.RaycastFilterType.Exclude, true, true
    local excluded = { character }
    local players = Workspace:FindFirstChild('Players')
    local ignored = Workspace:FindFirstChild('Ignored')
    if players then
        excluded[#excluded + 1] = players
    end
    if ignored then
        excluded[#excluded + 1] = ignored
    end
    params.FilterDescendantsInstances = excluded
    local hit = Workspace:Raycast(position + Vector3.new(0, 1, 0), Vector3.new(0, -24, 0), params)
    if not hit or hit.Normal.Y <= 0.2 then
        return
    end
    local entry = phowg:get_effect('jumpcircle', 11, phowg.new_jump_circle, 64)
    if not entry then
        return
    end
    entry.Model.CFrame = phowg:ground_ring_c_frame(hit)
    entry.Character, entry.Radius = character, phowg:visual_number('jump_circle_radius', 3, 0.5, 8)
    entry.Lifetime = phowg:visual_number('jump_circle_lifetime', 1, 0.2, 5)
    phowg:set_ground_ring_color(entry, Options.jump_circle_color and Options.jump_circle_color.Value or Color3.new(1, 1, 1))
    entry.Surface.MaxDistance = phowg:visual_number('cosmetic_distance', 1000, 100, 5000)
    entry.Update = phowg_callbacks.animate_jump_circle
    phowg:animate_jump_circle(entry, 0)
    entry.Model.Parent = ignored or Workspace
end
function phowg:bind_jump_circle_character(state, record, character)
    if record.HumanoidConnection then
        record.HumanoidConnection:Disconnect()
    end
    if record.ChildConnection then
        record.ChildConnection:Disconnect()
    end
    record.Character, record.Humanoid = character, nil
    record.HumanoidConnection, record.ChildConnection = nil, nil
    record.LastJumpAt = -math.huge
    if not character then
        return
    end
    local function bind_humanoid(humanoid)
        if record.HumanoidConnection then
            record.HumanoidConnection:Disconnect()
        end
        record.Humanoid = humanoid
        record.HumanoidConnection = connectshared(humanoid.StateChanged, function(oldState, newState)
            if Data.JumpCircleState ~= state or record.Character ~= character then
                return
            end
            local root = character:FindFirstChild('HumanoidRootPart')
            local grounded = oldState == Enum.HumanoidStateType.Running
                or oldState == Enum.HumanoidStateType.Landed
                or oldState == Enum.HumanoidStateType.RunningNoPhysics
            local rising = root and root.AssemblyLinearVelocity.Y > 2
            if
                newState == Enum.HumanoidStateType.Jumping
                or newState == Enum.HumanoidStateType.Freefall and grounded and rising
            then
                local now = tick()
                if now - record.LastJumpAt >= 0.15 then
                    record.LastJumpAt = now
                    phowg:emit_jump_circle(record.Player, character, humanoid)
                end
            end
        end, character, 'jump circles/state')
    end
    record.ChildConnection = connectshared(character.ChildAdded, function(child)
        if Data.JumpCircleState == state and child:IsA('Humanoid') then
            bind_humanoid(child)
        end
    end, character, 'jump circles/humanoid')
    local humanoid = character:FindFirstChildOfClass('Humanoid')
    if humanoid then
        bind_humanoid(humanoid)
    end
end
function phowg:remove_jump_circle_player(state, player)
    local record = state.Players[player]
    if not record then
        return
    end
    state.Players[player] = nil
    phowg:bind_jump_circle_character(state, record, nil)
    for _, connection in ipairs(record.Connections) do
        connection:Disconnect()
    end
end
function phowg:add_jump_circle_player(state, player)
    if Data.JumpCircleState ~= state or state.Players[player] then
        return
    end
    local record = {
        Player = player,
        Character = player.Character,
        Connections = {},
        LastJumpAt = -math.huge,
    }
    state.Players[player] = record
    record.Connections[1] = connectshared(player.CharacterAdded, function(character)
        if Data.JumpCircleState == state then
            phowg:bind_jump_circle_character(state, record, character)
        end
    end, player, 'jump circles/character added')
    record.Connections[2] = connectshared(player.CharacterRemoving, function(character)
        if record.Character == character then
            phowg:bind_jump_circle_character(state, record, nil)
        end
    end, player, 'jump circles/character removed')
    phowg:bind_jump_circle_character(state, record, player.Character)
end
function phowg:clear_jump_circles()
    local state = Data.JumpCircleState
    Data.JumpCircleState = nil
    if state then
        for _, connection in ipairs(state.Connections) do
            connection:Disconnect()
        end
        local players = {}
        for player in pairs(state.Players) do
            players[#players + 1] = player
        end
        for _, player in ipairs(players) do
            phowg:remove_jump_circle_player(state, player)
        end
    end
    local pool = Data.EffectPools and Data.EffectPools.jumpcircle
    if pool then
        for index = #pool.Active, 1, -1 do
            phowg:return_effect(pool.Active[index])
        end
    end
end
function phowg:update_jump_circles()
    phowg:clear_jump_circles()
    if Library.Unloaded or Data.SharedSignalsClosed or not phowg:toggle_enabled('jump_circles') then
        return
    end
    local state = { Players = {}, Connections = {} }
    Data.JumpCircleState = state
    local everyone = Options.jump_circle_sources and Options.jump_circle_sources.Value == 'everyone'
    if everyone then
        state.Connections[1] = connectshared(Players.PlayerAdded, function(player)
            phowg:add_jump_circle_player(state, player)
        end, Players, 'jump circles/player joined')
        state.Connections[2] = connectshared(Players.PlayerRemoving, function(player)
            phowg:remove_jump_circle_player(state, player)
        end, Players, 'jump circles/player left')
        for _, player in ipairs(Players:GetPlayers()) do
            phowg:add_jump_circle_player(state, player)
        end
    else
        phowg:add_jump_circle_player(state, LocalPlayer)
    end
end
phowg:register_cleanup('jump circles', function(scope)
    if not scope then
        phowg:clear_jump_circles()
    end
end)
function phowg:new_blood_splatter()
    local model, drops = Instance.new('Model'), {}
    model.Name = 'PhowgBloodSplatter'
    for index = 1, 12 do
        local part = Instance.new('Part')
        part.Name, part.Anchored, part.CanCollide, part.CanTouch, part.CanQuery = 'Droplet', true, false, false, false
        part.CastShadow, part.Massless, part.Transparency = false, true, 1
        part.Size, part.Shape, part.Material = Vector3.new(0.12, 0.12, 0.12), Enum.PartType.Ball, Enum.Material.Neon
        part.Parent = model
        local top, bottom = Instance.new('Attachment'), Instance.new('Attachment')
        top.Position, bottom.Position = Vector3.new(0, 0.12, 0), Vector3.new(0, -0.12, 0)
        top.Parent, bottom.Parent = part, part
        local trail = Instance.new('Trail')
        trail.Attachment0, trail.Attachment1, trail.Lifetime, trail.FaceCamera, trail.Enabled =
            top, bottom, 0.25, true, false
        trail.WidthScale = NumberSequence.new({
            NumberSequenceKeypoint.new(0, 0.05),
            NumberSequenceKeypoint.new(0.25, 0.35),
            NumberSequenceKeypoint.new(0.8, 0.2),
            NumberSequenceKeypoint.new(1, 0),
        })
        trail.Parent = part
        local decal = Instance.new('Decal')
        decal.Texture, decal.Face, decal.Transparency = 'rbxassetid://16939835586', Enum.NormalId.Right, 1
        decal.Parent = part
        drops[index] = { Part = part, Trail = trail, Decal = decal, Position = Vector3.zero, Velocity = Vector3.zero }
    end
    local params = RaycastParams.new()
    params.FilterType, params.IgnoreWater = Enum.RaycastFilterType.Exclude, true
    return { Model = model, Drops = drops, Params = params }
end
function phowg:update_blood_splatter(entry, age)
    local elapsed = age - entry.LastStep
    if elapsed < 1 / 30 then
        return
    end
    entry.LastStep = age
    local delta, living = math.min(elapsed, 0.1), 0
    for index = 1, entry.Count do
        local drop = entry.Drops[index]
        if not drop.Done then
            if drop.SplatAt then
                local alpha = math.clamp((age - drop.SplatAt - entry.SplatLifetime) / 0.8, 0, 1)
                drop.Part.Transparency, drop.Decal.Transparency = 0.05 + 0.95 * alpha, 0.05 + 0.95 * alpha
                drop.Done = alpha >= 1
            elseif age >= 1.8 then
                drop.Trail.Enabled = false
                drop.Part.Transparency = math.clamp((age - 1.8) / 0.3, 0, 1)
                drop.Done = age >= 2.1
            else
                local acceleration = Vector3.new(0, -48, 0)
                local destination = drop.Position + drop.Velocity * delta + acceleration * (delta * delta * 0.5)
                local hit = Workspace:Raycast(drop.Position, destination - drop.Position, entry.Params)
                if hit then
                    local width = math.random(7, 12) / 10
                    drop.Part.Shape, drop.Part.Material = Enum.PartType.Cylinder, Enum.Material.SmoothPlastic
                    drop.Part.Size = Vector3.new(0.02, width, width * math.random(7, 9) / 10)
                    local position = hit.Position + hit.Normal * 0.012
                    drop.Part.CFrame = CFrame.lookAt(position, position + hit.Normal)
                        * CFrame.Angles(0, math.pi / 2, 0)
                        * CFrame.Angles(math.rad(math.random(0, 360)), 0, 0)
                    drop.Part.Transparency, drop.Decal.Transparency, drop.Trail.Enabled = 0.05, 0.05, false
                    drop.SplatAt = age
                else
                    drop.Position, drop.Velocity = destination, drop.Velocity + acceleration * delta
                    drop.Part.CFrame = drop.Velocity.Magnitude > 0.001
                            and CFrame.lookAt(destination, destination + drop.Velocity)
                        or CFrame.new(destination)
                end
            end
            if not drop.Done then
                living += 1
            end
        end
    end
    if living == 0 then
        phowg:return_effect(entry)
    end
end
function phowg:emit_blood_splatter(character, root, color)
    local now = tick()
    Data.BloodSplatterTimes = Data.BloodSplatterTimes or setmetatable({}, { __mode = 'k' })
    if now - (Data.BloodSplatterTimes[character] or -math.huge) < 0.15 then
        return
    end
    local quality = math.clamp(Data.CosmeticQuality or 1, 0, 1)
    if quality <= 0 then
        return
    end
    local count = math.max(1, math.floor(12 * quality))
    local entry = phowg:get_effect('bloodsplatter', count * 3, phowg.new_blood_splatter, 6)
    if not entry then
        return
    end
    Data.BloodSplatterTimes[character] = now
    color = color == Color3.new(1, 1, 1) and Color3.fromRGB(120, 10, 10) or color
    entry.Character, entry.Count, entry.LastStep = character, count, 0
    entry.SplatLifetime = phowg:visual_number('blood_splatter_life', 1.5, 0.2, 5)
    entry.Lifetime, entry.Update = 1.8 + entry.SplatLifetime + 0.8, phowg_callbacks.update_blood_splatter
    local filter = { character, entry.Model }
    if LocalPlayer.Character then
        filter[#filter + 1] = LocalPlayer.Character
    end
    if Workspace.CurrentCamera then
        filter[#filter + 1] = Workspace.CurrentCamera
    end
    entry.Params.FilterDescendantsInstances = filter
    local sequence = ColorSequence.new(color)
    for index, drop in ipairs(entry.Drops) do
        local active = index <= count
        drop.Trail.Enabled = false
        drop.Trail:Clear()
        drop.Trail.Color, drop.Decal.Color3, drop.Decal.Transparency = sequence, color, 1
        drop.Part.Shape, drop.Part.Material = Enum.PartType.Ball, Enum.Material.Neon
        drop.Part.Size, drop.Part.Color, drop.Part.Transparency =
            Vector3.new(0.12, 0.12, 0.12), color, active and 0 or 1
        drop.Part.CFrame = CFrame.new(root.Position)
        drop.Position, drop.SplatAt, drop.Done = root.Position, nil, not active
        local angle, elevation, speed =
            math.rad(math.random(0, 360)), math.rad(math.random(15, 75)), math.random(14, 28)
        drop.Velocity = Vector3.new(
            math.cos(angle) * math.cos(elevation),
            math.sin(elevation),
            math.sin(angle) * math.cos(elevation)
        ) * speed
        drop.Trail.Enabled = active
    end
    entry.Model.Parent = Workspace:FindFirstChild('Ignored') or Workspace
end
function phowg:fortnite_damage_number(plr, damage)
    local character = intelligence:get_character_cache(plr)
    local head = character and character:FindFirstChild('Head')
    if not head or not phowg:cosmetic_visible(head.Position) then
        return
    end
    local entry = phowg:get_effect('damage_fortnite', 7, function()
        local frame = Instance.new('Frame')
        frame.Name, frame.BackgroundTransparency, frame.BorderSizePixel = 'FortniteDamage', 1, 0
        frame.AnchorPoint, frame.Size, frame.ZIndex = Vector2.new(0.5, 0.5), UDim2.fromOffset(180, 80), 30
        local scale = Instance.new('UIScale')
        scale.Parent = frame
        local face = Font.fromEnum(Enum.Font.Bangers)
        local function label(name, color, offset, strokeSize)
            local text = Instance.new('TextLabel')
            text.Name, text.BackgroundTransparency, text.BorderSizePixel = name, 1, 0
            text.Size, text.Position = UDim2.fromScale(1, 1), offset
            text.FontFace, text.TextSize, text.TextColor3 = face, 48, color
            text.TextWrapped, text.RichText, text.ZIndex, text.Parent = false, false, 31, frame
            local stroke = Instance.new('UIStroke')
            stroke.Color, stroke.Thickness, stroke.Parent = Color3.new(0, 0, 0), strokeSize, text
            return text, stroke
        end
        local shadow, shadowStroke = label('Shadow', Color3.new(0, 0, 0), UDim2.fromOffset(2, 3), 3)
        local number, outline = label('Number', Color3.fromRGB(255, 235, 0), UDim2.fromOffset(0, 0), 2.5)
        number.ZIndex = 32
        local gradient = Instance.new('UIGradient')
        gradient.Color = ColorSequence.new(Color3.fromRGB(255, 255, 120), Color3.fromRGB(255, 220, 0))
        gradient.Rotation, gradient.Parent = 90, number
        return { Model = frame, Scale = scale, Number = number, Shadow = shadow, Outline = outline, ShadowStroke = shadowStroke }
    end, 24)
    if not entry then
        return
    end
    local text = tostring(math.round(math.max(0, tonumber(damage) or 0)))
    entry.Number.Text, entry.Shadow.Text = text, text
    entry.Character, entry.Anchor, entry.Position = character, head, head.Position
    entry.Duration = phowg:visual_number('damage_number_life', 0.6, 0.1, 5)
    entry.Lifetime = entry.Duration + 0.2
    entry.Scale.Scale = Library.ReducedMotion and 1 or 0.8
    entry.Model.Visible, entry.Model.Parent = false, Data.StatusGui
    entry.Update = function(e, age, camera)
        if not camera then
            e.Model.Visible = false
            return
        end
        local anchor = e.Anchor and e.Anchor.Parent and e.Anchor.Position or e.Position
        local point, visible = camera:WorldToViewportPoint(
            anchor + camera.CFrame.RightVector * 1.4 + Vector3.new(0, 0.6, 0)
        )
        local motion = Library.ReducedMotion and 0 or math.min(age / 0.35, 1)
        local pop = Library.ReducedMotion and 1
            or age < 0.06 and 0.8 + age / 0.06 * 0.45
            or age < 0.16 and 1.25 - (age - 0.06) / 0.1 * 0.25
            or 1
        local fade = math.clamp((age - e.Duration) / 0.2, 0, 1)
        e.Model.Position = UDim2.fromOffset(point.X + 18 + motion * 10, point.Y - 22 - motion * 14)
        e.Model.Rotation = -2
        e.Scale.Scale = pop
        e.Number.TextTransparency, e.Shadow.TextTransparency = fade, fade
        e.Outline.Transparency, e.ShadowStroke.Transparency = fade, fade
        e.Model.Visible = visible
    end
end
function damagenumber(plr, dmg)
    if Options.damage_number_value and Options.damage_number_value.Value == 'fortnite' then
        phowg:fortnite_damage_number(plr, dmg)
        return
    end
    if not (Drawing and Drawing.new) then
        return
    end
    local char = intelligence:get_character_cache(plr)
    local head = char and char:FindFirstChild('Head')
    if not head or not phowg:cosmetic_visible(head.Position) then
        return
    end
    local entry = phowg:get_effect('damage', 1, function()
        local text = Drawing.new('Text')
        text.Size, text.Font, text.Outline, text.Visible = 12, 2, true, false
        return { Text = text }
    end, 48)
    if not entry then
        return
    end
    entry.Text.Text = '-' .. tostring(math.floor((dmg or 0) + 0.5))
    entry.Text.Color = Options.damage_number_color and Options.damage_number_color.Value or Color3.new(1, 1, 1)
    entry.Character = char
    entry.Position, entry.Duration = head.Position, phowg:visual_number('damage_number_life', 0.6, 0.1, 5)
    entry.Lifetime, entry.Float =
        entry.Duration + 0.2, not Options.damage_number_value or Options.damage_number_value.Value == 'float'
    entry.Update = function(e, age, camera)
        if not camera then
            e.Text.Visible = false
            return
        end
        local movement = e.Float
                and (math.min(age, e.Duration) ^ 2 / e.Duration * 4.2 + math.max(0, age - e.Duration) * 8.4)
            or 0
        local point, visible = camera:WorldToViewportPoint(e.Position + Vector3.new(0, movement, 0))
        e.Text.Position = Vector2.new(point.X, point.Y - (Toggles.hit_marker and Toggles.hit_marker.Value and 11 or 0))
        e.Text.Visible, e.Text.Transparency = visible, 1 - math.clamp((age - e.Duration) / 0.2, 0, 1)
    end
end
function hitchams(plr)
    local char = intelligence:get_character_cache(plr)
    local root = char and char:FindFirstChild('HumanoidRootPart')
    if not root or not phowg:cosmetic_visible(root.Position) then
        return
    end
    if Toggles.hit_chams_last_hit and Toggles.hit_chams_last_hit.Value and Data.HitChamEntry then
        phowg:return_effect(Data.HitChamEntry)
    end
    local entry = phowg:get_effect('hitchams', 20, function()
        return { Model = Instance.new('Model'), Parts = {} }
    end, 8)
    if not entry then
        return
    end
    entry.Model.Name, entry.Model.Parent = 'PhowgHitChams', Workspace:FindFirstChild('Ignored') or Workspace
    if entry.Character ~= char then
        for _, ghost in pairs(entry.Parts) do
            ghost:Destroy()
        end
        table.clear(entry.Parts)
        entry.Character = char
    end
    local mode = Options.hit_chams_value and Options.hit_chams_value.Value or 'outline'
    local color = Options.hit_chams_color and Options.hit_chams_color.Value or Color3.new(1, 1, 1)
    local present, count = {}, 0
    for _, part in ipairs(char:GetChildren()) do
        if part:IsA('BasePart') and part ~= root and count < 20 then
            count += 1
            present[part] = true
            local ghost = entry.Parts[part]
            if not ghost then
                local previous = part.Archivable
                part.Archivable = true
                local ok, copy = pcall(function()
                    return part:Clone()
                end)
                part.Archivable = previous
                if ok and copy then
                    ghost = copy
                    for _, child in ipairs(ghost:GetChildren()) do
                        if not child:IsA('SpecialMesh') then
                            child:Destroy()
                        end
                    end
                    ghost.Anchored, ghost.CanCollide, ghost.CanTouch, ghost.CanQuery, ghost.CastShadow =
                        true, false, false, false, false
                    local box = Instance.new('SelectionBox')
                    box.Name, box.LineThickness, box.SurfaceTransparency, box.Adornee, box.Parent =
                        'Outline', 0.01, 1, ghost, ghost
                    ghost.Parent, entry.Parts[part] = entry.Model, ghost
                end
            end
            if ghost then
                ghost.CFrame, ghost.Size, ghost.Color = part.CFrame, part.Size, color
                ghost.Material = mode == 'forcefield' and Enum.Material.ForceField
                    or mode == 'neon' and Enum.Material.Neon
                    or Enum.Material.SmoothPlastic
                ghost.Transparency = mode == 'outline' and 1 or 0
                local box = ghost:FindFirstChild('Outline')
                box.Visible, box.Color3, box.Transparency = mode == 'outline', color, 0
            end
        end
    end
    for part, ghost in pairs(entry.Parts) do
        if not present[part] then
            ghost:Destroy()
            entry.Parts[part] = nil
        end
    end
    entry.Duration = phowg:visual_number('hit_chams_life', 1.5, 0.1, 5)
    entry.Fade = Toggles.hit_chams_fade and Toggles.hit_chams_fade.Value
    entry.Lifetime, entry.Mode = entry.Duration + (entry.Fade and 0.2 or 0), mode
    entry.Update = function(e, age)
        local alpha = e.Fade and math.clamp((age - e.Duration) / 0.2, 0, 1) or 0
        if alpha == e.Alpha then
            return
        end
        e.Alpha = alpha
        for _, ghost in pairs(e.Parts) do
            ghost.Transparency = e.Mode == 'outline' and 1 or alpha
            local box = ghost:FindFirstChild('Outline')
            if box then
                box.Transparency = alpha
            end
        end
    end
    entry.Alpha, Data.HitChamPrev, Data.HitChamEntry = nil, entry.Model, entry
end
phowg:register_cleanup('pooled hit effects', function(scope)
    if not scope or scope == LocalPlayer.Character or scope == Data.ManagedCharacter then
        phowg:clear_effects()
    else
        phowg:clear_effects(scope)
    end
end)
function phowg:skin_cosmetics_enabled()
    return (Toggles.skin_changer_enabled and Toggles.skin_changer_enabled.Value)
        or (Toggles.inventory_changer_enabled and Toggles.inventory_changer_enabled.Value)
        or false
end
function phowg:resolve_skin_shoot_sound(tool)
    if not phowg:skin_cosmetics_enabled() then
        return nil
    end
    local state = Data.SkinToolStates and Data.SkinToolStates[tool]
    if
        not state
        or state.Character ~= LocalPlayer.Character
        or state.Handle.Parent ~= tool
        or state.Skin ~= Data.SkinEquipped[tool.Name]
    then
        return nil
    end
    if Toggles.skin_shoot_sounds and not Toggles.skin_shoot_sounds.Value then
        return nil
    end
    local source = state.ShootSoundSource
    local assets = ReplicatedStorage:FindFirstChild('SkinAssets')
    local folder = assets and assets:FindFirstChild('GunShootSounds')
    if
        not source
        or not source:IsA('StringValue')
        or not source.Parent
        or source.Parent.Parent ~= folder
        or phowg:skin_asset_key(source.Parent.Name) ~= phowg:skin_asset_key(tool.Name)
        or phowg:skin_asset_key(source.Name) ~= phowg:skin_asset_key(state.Skin)
    then
        return nil
    end
    local value = source.Value
    if type(value) ~= 'string' then
        return nil
    end
    local id = value:match('^%s*(.-)%s*$')
    if id:match('^%d+$') then
        return tonumber(id) > 0 and 'rbxassetid://' .. id or nil
    end
    local asset = id:match('^rbxassetid://(%d+)$')
    if asset then
        return tonumber(asset) > 0 and id or nil
    end
    if id:match('^rbxasset://') or id:match('^https?://') then
        return id
    end
    return nil
end
function phowg:resolve_tool_shoot_sound(tool)
    if Library.Unloaded or Data.SharedSignalsClosed or not tool or tool.Parent ~= LocalPlayer.Character then
        return nil
    end
    if Data.RetiredScopes and (Data.RetiredScopes[tool] or Data.RetiredScopes[tool.Parent]) then
        return nil
    end
    local custom = Toggles.custom_shoot_sound and Toggles.custom_shoot_sound.Value
    local selection = custom and Options.custom_shoot_sound_value and Options.custom_shoot_sound_value.Value
    if custom and selection ~= 'default' then
        local id = selection == 'custom' and Data.CustomShootSoundText
            or Data.ShootSounds and Data.ShootSounds[selection or 'ssg-08']
        if type(id) == 'string' and id ~= '' then
            if selection == 'custom' and not id:find('rbxassetid', 1, true) then
                id = 'rbxassetid://' .. id
            end
            return id, Options.custom_shoot_sound_volume and Options.custom_shoot_sound_volume.Value or 1
        end
    end
    local id = phowg:resolve_skin_shoot_sound(tool)
    local state = phowg:skin_cosmetics_enabled() and Data.SkinToolStates and Data.SkinToolStates[tool]
    local skin = state
        and state.Character == LocalPlayer.Character
        and state.Handle.Parent == tool
        and state.Skin == Data.SkinEquipped[tool.Name]
    if custom and selection == 'default' or skin then
        local handle = tool:FindFirstChild('Handle')
        local sound = handle and handle:FindFirstChild('ShootSound')
        if not sound or not sound:IsA('Sound') then
            return nil
        end
        local original = Data.ShootSoundOrig and Data.ShootSoundOrig[sound]
        local skinVolume = id and phowg:visual_number('skin_shoot_volume', 1, 0, 3) or 1
        id = id or original and original.id or sound.SoundId
        if type(id) ~= 'string' or id == '' then
            return nil
        end
        local customVolume = custom
                and selection == 'default'
                and Options.custom_shoot_sound_volume
                and Options.custom_shoot_sound_volume.Value
            or 1
        return id, (original and original.vol or sound.Volume) * skinVolume * customVolume
    end
    return id
end
function phowg:restore_tool_sound(sound)
    local original = Data.ShootSoundOrig and Data.ShootSoundOrig[sound]
    if not original then
        return
    end
    if sound.Parent then
        sound.SoundId, sound.Volume = original.id, original.vol
    end
    Data.ShootSoundOrig[sound] = nil
end
function phowg:restore_tool_sounds(character)
    for sound in pairs(Data.ShootSoundOrig or {}) do
        if not character or not sound.Parent or sound:IsDescendantOf(character) then
            phowg:restore_tool_sound(sound)
        end
    end
end
function convertsound(sound, tool)
    if not sound or not sound:IsA('Sound') or sound.Name ~= 'ShootSound' then
        return nil
    end
    tool = tool or sound:FindFirstAncestorOfClass('Tool')
    local id, volume = phowg:resolve_tool_shoot_sound(tool)
    if not id then
        phowg:restore_tool_sound(sound)
        return nil
    end
    Data.ShootSoundOrig = Data.ShootSoundOrig or setmetatable({}, { __mode = 'k' })
    local original = Data.ShootSoundOrig[sound]
    if not original then
        original = { id = sound.SoundId, vol = sound.Volume }
        Data.ShootSoundOrig[sound] = original
    end
    volume = volume or original.vol
    if sound.SoundId ~= id then
        sound.SoundId = id
    end
    if sound.Volume ~= volume then
        sound.Volume = volume
    end
    return id, volume
end
function phowg:stop_tool_shoot_sounds(tool)
    local playback = Data.ToolShootPlayback and Data.ToolShootPlayback[tool]
    if not playback then
        return
    end
    if playback.Borrowed and playback.Source.Parent then
        playback.Source:Stop()
    end
    for _, sound in ipairs(playback.Sounds) do
        sound:Stop()
        sound:Destroy()
    end
    Data.ToolShootPlayback[tool] = nil
end
function phowg:play_tool_shoot_sound(handle, different)
    if typeof(handle) ~= 'Instance' or not handle:IsA('BasePart') then
        return false
    end
    local tool = handle.Parent
    if not tool or tool.Parent ~= LocalPlayer.Character or not tool:IsA('Tool') then
        return false
    end
    local source = handle:FindFirstChild('ShootSound')
    if not source or not source:IsA('Sound') then
        return false
    end
    local id, volume = convertsound(source, tool)
    if not id then
        phowg:stop_tool_shoot_sounds(tool)
        return false
    end
    Data.ToolShootPlayback = Data.ToolShootPlayback or setmetatable({}, { __mode = 'k' })
    local playback = Data.ToolShootPlayback[tool]
    if
        playback
        and (
            playback.Character ~= LocalPlayer.Character
            or playback.Source ~= source
            or playback.Id ~= id
            or playback.Volume ~= volume
        )
    then
        phowg:stop_tool_shoot_sounds(tool)
        playback = nil
    end
    if not playback then
        playback = {
            Character = LocalPlayer.Character,
            Source = source,
            Id = id,
            Volume = volume,
            Borrowed = false,
            Next = 1,
            Sounds = {},
        }
        Data.ToolShootPlayback[tool] = playback
    end
    local selected = source
    if different then
        selected = nil
        for index = #playback.Sounds, 1, -1 do
            local sound = playback.Sounds[index]
            if not sound.Parent then
                sound:Destroy()
                table.remove(playback.Sounds, index)
            elseif not sound.IsPlaying then
                selected = sound
                break
            end
        end
        if not selected then
            if #playback.Sounds < 16 then
                selected = source:Clone()
                selected:Stop()
                selected.Name = 'PhowgSkinShotSound'
                selected.PlayOnRemove, selected.Looped = false, false
                selected.Parent = handle
                playback.Sounds[#playback.Sounds + 1] = selected
            else
                selected = playback.Sounds[playback.Next]
                playback.Next = playback.Next % #playback.Sounds + 1
                selected:Stop()
            end
        end
        selected.SoundId, selected.Volume, selected.PlaybackSpeed = id, volume, source.PlaybackSpeed
    else
        playback.Borrowed = true
    end
    selected.TimePosition = 0
    selected:Play()
    return true
end
function phowg:install_shoot_sound_handler()
    if Data.NativeGunSound or Data.ShootSoundHookPending or Library.Unloaded or Data.SharedSignalsClosed then
        return
    end
    local module = ReplicatedStorage:FindFirstChild('GunSoundPlay')
    if not module or not module:IsA('ModuleScript') then
        return
    end
    local pending = {}
    Data.ShootSoundHookPending = pending
    task.defer(function()
        if Data.ShootSoundHookPending ~= pending then
            return
        end
        local ok, handler = pcall(require, module)
        if Data.ShootSoundHookPending ~= pending then
            return
        end
        Data.ShootSoundHookPending = nil
        if
            not ok
            or Library.Unloaded
            or Data.SharedSignalsClosed
            or type(handler) ~= 'table'
            or type(handler.SoundPlay) ~= 'function'
        then
            return
        end
        local original = handler.SoundPlay
        local replacement = LPH_NO_VIRTUALIZE(function(handle, different, ...)
            if not Library.Unloaded and not Data.SharedSignalsClosed and phowg:play_tool_shoot_sound(handle, different) then
                return
            end
            return original(handle, different, ...)
        end)
        Data.NativeGunSound = { Handler = handler, Original = original, Replacement = replacement }
        handler.SoundPlay = replacement
    end)
end
function hooktoolshootsound(tool)
    if not tool then
        return
    end
    local record = Data.ToolObservers and Data.ToolObservers[tool]
    local sounds = record and record.Sounds
    local active = Toggles.custom_shoot_sound and Toggles.custom_shoot_sound.Value or phowg:skin_cosmetics_enabled()
    if not active and not sounds then
        return
    end
    if active then
        phowg:install_shoot_sound_handler()
    end
    if not sounds then
        sounds = setmetatable({}, { __mode = 'k' })
        if record then
            record.Sounds = sounds
        end
        for _, sound in ipairs(tool:GetDescendants()) do
            if sound:IsA('Sound') and sound.Name == 'ShootSound' then
                sounds[sound] = true
            end
        end
    end
    for sound in pairs(sounds) do
        if sound:IsDescendantOf(tool) then
            convertsound(sound, tool)
        else
            sounds[sound] = nil
        end
    end
    if not phowg:resolve_tool_shoot_sound(tool) then
        phowg:stop_tool_shoot_sounds(tool)
    end
end
function hookshootsound()
    phowg:restore_tool_sounds()
    local character = LocalPlayer.Character
    if not character then
        return
    end
    hooklocaltools(character)
    for _, tool in ipairs(character:GetChildren()) do
        if tool:IsA('Tool') then
            hooktoolshootsound(tool)
        end
    end
end
phowg:register_cleanup('shoot sounds', function(scope, reason)
    for tool, playback in pairs(table.clone(Data.ToolShootPlayback or {})) do
        if not scope or tool == scope or playback.Character == scope or tool:IsDescendantOf(scope) then
            phowg:stop_tool_shoot_sounds(tool)
        end
    end
    if reason ~= 'unload' then
        return
    end
    phowg:restore_tool_sounds()
    local native = Data.NativeGunSound
    if native and native.Handler.SoundPlay == native.Replacement then
        native.Handler.SoundPlay = native.Original
    end
    Data.NativeGunSound, Data.ShootSoundHookPending = nil, nil
end)
function phowg:on_hit_allowed(player, confirmed)
    if Toggles.on_hit_enabled and not Toggles.on_hit_enabled.Value then
        return false
    end
    if not player or not player.Parent or not player.Character then
        return false
    end
    if
        not confirmed
        and Toggles.on_hit_not_knocked
        and Toggles.on_hit_not_knocked.Value
        and (isdead(player) or isknocked(player))
    then
        return false
    end
    if Toggles.on_hit_ignore_crew and Toggles.on_hit_ignore_crew.Value then
        local mine, theirs = getplayercrewid(LocalPlayer), getplayercrewid(player)
        if mine and theirs and tostring(mine) == tostring(theirs) then
            return false
        end
    end
    return true
end
function phowg:bullet_hit_feedback_enabled()
    if Toggles.on_hit_enabled and not Toggles.on_hit_enabled.Value then
        return false
    end
    for _, name in ipairs({
        'hit_sound',
        'hit_skeleton',
        'hit_effect',
        'hit_marker',
        'hit_chams',
        'damage_number',
        'hit_notifications',
    }) do
        if Toggles[name] and Toggles[name].Value then
            return true
        end
    end
    return false
end
function phowg:hit_confirmation_window()
    local now = tick()
    if now >= (Data.HitConfirmWindowAt or 0) then
        local ok, ping = pcall(LocalPlayer.GetNetworkPing, LocalPlayer)
        if not ok or type(ping) ~= 'number' or ping ~= ping or ping < 0 or ping == math.huge then
            ping = 0
        end
        Data.HitConfirmWindow = math.clamp(0.35 + ping * 4, 0.35, 1.5)
        Data.HitConfirmWindowAt = now + 1
    end
    return Data.HitConfirmWindow or 0.35
end
function phowg:prune_hit_shots(state)
    local shots, now = state.Shots, tick()
    while shots.Head <= shots.Tail do
        local shot = shots.Items[shots.Head]
        if shot and shot.Expires > now and shot.OwnerCharacter == LocalPlayer.Character then
            break
        end
        shots.Items[shots.Head] = nil
        shots.Head = shots.Head + 1
    end
    if shots.Head > shots.Tail then
        table.clear(shots.Items)
        shots.Head, shots.Tail = 1, 0
    end
end

function phowg:flush_confirmed_hits(player)
    local native = Data.NativeHitFeedback
    if native then
        native.Dirty = true
    end
end
function phowg:hit_marker_receipt_valid(receipt, player)
    return type(receipt) == 'table'
        and receipt.State == Data.NativeHitFeedback
        and receipt.Acknowledged == true
        and receipt.Character == LocalPlayer.Character
        and receipt.HasTarget == true
        and receipt.Player == player
        and player
        and player.Parent
        and receipt.TargetCharacter == player.Character
end
function phowg:resolve_hit_marker_feedback(native)
    if
        Data.NativeHitFeedback ~= native
        or native.Resolving
        or Library.Unloaded
        or Data.SharedSignalsClosed
        or #native.Events == 0
    then
        return
    end
    native.Resolving = true
    local now, character = tick(), LocalPlayer.Character
    local window = phowg:hit_confirmation_window()
    local candidates, states = {}, {}
    for player, state in pairs(Data.ConfirmedHitStates or {}) do
        if state.Closed or player.Character ~= state.Character or not player.Parent or not state.Humanoid.Parent then
            state:Disconnect()
        else
            phowg:prune_hit_shots(state)
            local losses, write = state.Losses, 1
            for _, loss in ipairs(losses) do
                if loss.OwnerCharacter == character and loss.Expires > now then
                    losses[write] = loss
                    write += 1
                end
            end
            for index = #losses, write, -1 do
                losses[index] = nil
            end
            if #losses > 0 and ismydamager(player) then
                states[#states + 1] = state
                local shots = {}
                for index = state.Shots.Head, state.Shots.Tail do
                    local shot = state.Shots.Items[index]
                    if shot and shot.OwnerCharacter == character then
                        shots[#shots + 1] = shot
                    end
                end
                table.sort(shots, function(a, b)
                    return a.At < b.At
                end)
                for _, loss in ipairs(losses) do
                    if now >= loss.ReadyAt then
                        local low, high = 1, #shots + 1
                        while low < high do
                            local middle = math.floor((low + high) * 0.5)
                            if shots[middle].At < loss.At then
                                low = middle + 1
                            else
                                high = middle
                            end
                        end
                        local left, right = low - 1, low
                        local bestShot, bestDistance = nil, math.huge
                        while left >= 1 or right <= #shots do
                            local ld = left >= 1 and math.abs(shots[left].At - loss.At) or math.huge
                            local rd = right <= #shots and math.abs(shots[right].At - loss.At) or math.huge
                            local distance = math.min(ld, rd)
                            if distance >= bestDistance or distance > 1.5 then
                                break
                            end
                            local shot
                            if ld <= rd then
                                shot = shots[left]
                                left -= 1
                            else
                                shot = shots[right]
                                right += 1
                            end
                            if shot.At <= loss.At + 0.15 and loss.At - shot.At <= shot.Window then
                                bestShot, bestDistance = shot, distance
                            end
                        end
                        if bestShot or loss.Method then
                            candidates[#candidates + 1] = {
                                State = state,
                                Loss = loss,
                                Shot = bestShot,
                                Score = bestShot and bestDistance * 0.1 or window,
                            }
                        end
                    end
                end
            end
        end
    end
    table.sort(candidates, function(a, b)
        return a.Loss.At < b.Loss.At
    end)
    local count = #candidates
    local following, preceding = {}, {}
    local function available(links, index)
        local first = index
        while index >= 1 and index <= count and links[index] do
            index = links[index]
        end
        while first >= 1 and first <= count and links[first] do
            local nextIndex = links[first]
            links[first] = index
            first = nextIndex
        end
        return index
    end
    local groups, ordered = {}, {}
    for _, receipt in ipairs(native.Events) do
        if not receipt.HasTarget and receipt.Character == character and now - receipt.At <= window + 0.25 then
            local low, high = 1, count + 1
            while low < high do
                local middle = math.floor((low + high) * 0.5)
                if candidates[middle].Loss.At < receipt.At then
                    low = middle + 1
                else
                    high = middle
                end
            end
            local left, right = available(preceding, low - 1), available(following, low)
            local best, bestIndex, bestScore = nil, nil, math.huge
            while left >= 1 or right <= count do
                local ld = left >= 1 and math.abs(candidates[left].Loss.At - receipt.At) or math.huge
                local rd = right <= count and math.abs(candidates[right].Loss.At - receipt.At) or math.huge
                local distance = math.min(ld, rd)
                if distance > window or distance >= bestScore then
                    break
                end
                local index
                if ld <= rd then
                    index = left
                    left = available(preceding, left - 1)
                else
                    index = right
                    right = available(following, right + 1)
                end
                local candidate = candidates[index]
                local score = distance + candidate.Score
                if score < bestScore then
                    best, bestIndex, bestScore = candidate, index, score
                end
            end
            if best then
                following[bestIndex] = available(following, bestIndex + 1)
                preceding[bestIndex] = available(preceding, bestIndex - 1)
                local state, loss, shot = best.State, best.Loss, best.Shot
                loss.Consumed = true
                receipt.HasTarget, receipt.Player, receipt.TargetCharacter = true, state.Player, state.Character
                receipt.Damage, receipt.Method, receipt.Weapon =
                    loss.Damage, shot and 'gun' or loss.Method, shot and shot.Weapon
                if phowg:hit_marker_receipt_valid(receipt, state.Player) then
                    if phowg.record_ragebot_hit then
                        phowg:record_ragebot_hit(state.Player)
                    end
                    if phowg.record_combat_hit and receipt.Method == 'gun' then
                        phowg:record_combat_hit(state.Player, receipt.Damage, receipt.Weapon)
                    end
                    local group = groups[state.Player]
                    if not group then
                        group = {
                            Receipt = receipt,
                            Damage = 0,
                            Weapon = receipt.Weapon,
                            Method = receipt.Method,
                            Sound = true,
                            Marker = true,
                        }
                        groups[state.Player] = group
                        ordered[#ordered + 1] = group
                    elseif group.Weapon ~= receipt.Weapon then
                        group.Weapon = 'multiple guns'
                    end
                    group.Damage += receipt.Damage
                    group.Sound = group.Sound and receipt.PlayedSound
                    group.Marker = group.Marker and receipt.PlayedMarker
                end
            end
        end
    end
    for _, state in ipairs(states) do
        local losses, write = state.Losses, 1
        for _, loss in ipairs(losses) do
            if not loss.Consumed then
                losses[write] = loss
                write += 1
            end
        end
        for index = #losses, write, -1 do
            losses[index] = nil
        end
    end
    native.Resolving = false
    for _, group in ipairs(ordered) do
        local receipt = group.Receipt
        receipt.PlayedSound, receipt.PlayedMarker = group.Sound, group.Marker
        phowg:run_hit_feedback('confirmed hit', tryhit, receipt.Player, group.Damage, group.Method, group.Weapon, receipt)
    end
end
function phowg:record_target_gun_shot(tool, player, shotAt)
    if
        Library.Unloaded
        or Data.SharedSignalsClosed
        or not phowg:native_hit_feedback_enabled()
        or not player
        or not player.Parent
    then
        return false
    end
    local character = LocalPlayer.Character
    local pack = LocalPlayer:FindFirstChild('Backpack')
    if not character or not tool or (tool.Parent ~= character and tool.Parent ~= pack) or not player.Character then
        return false
    end
    local state = Data.ConfirmedHitStates and Data.ConfirmedHitStates[player]
    if not state or state.Character ~= player.Character then
        hookhitwatch(player)
        state = Data.ConfirmedHitStates and Data.ConfirmedHitStates[player]
    end
    if not state or state.Closed or (state.Humanoid.Health <= 0 and #state.Losses == 0) then
        return false
    end
    phowg:prune_hit_shots(state)
    local now, window = tick(), phowg:hit_confirmation_window()
    state.Shots.Tail += 1
    state.Shots.Items[state.Shots.Tail] = {
        At = shotAt or now,
        Expires = now + window + 0.2,
        Window = window,
        OwnerCharacter = character,
        Weapon = tool.Name,
        Tool = tool,
        AmmoObserved = true,
    }
    phowg:flush_confirmed_hits(player)
    return true
end
function phowg:stage_gun_shot(tool, target)
    if not phowg:native_hit_feedback_enabled() or not target or not target.Parent or not target.Character then
        return nil
    end
    Data.PendingGunShots = Data.PendingGunShots or setmetatable({}, { __mode = 'k' })
    local queue = Data.PendingGunShots[tool]
    if not queue then
        queue = {}
        Data.PendingGunShots[tool] = queue
    end
    local hitState = Data.ConfirmedHitStates and Data.ConfirmedHitStates[target]
    if not hitState or hitState.Character ~= target.Character then
        hookhitwatch(target)
    end
    local now = tick()
    while
        #queue > 0
        and (now - queue[1].At > phowg:hit_confirmation_window() + 0.2 or queue[1].Character ~= LocalPlayer.Character)
    do
        table.remove(queue, 1)
    end
    if #queue >= 128 then
        table.remove(queue, 1)
    end
    local shot = { At = now, Character = LocalPlayer.Character, Target = target, TargetCharacter = target.Character }
    queue[#queue + 1] = shot
    return shot
end
function phowg:discard_gun_shot(tool, shot)
    local queue = Data.PendingGunShots and Data.PendingGunShots[tool]
    local index = queue and table.find(queue, shot)
    if index then
        table.remove(queue, index)
    end
end
function phowg:confirm_gun_ammo(tool, record, spent)
    local character = LocalPlayer.Character
    local pack = LocalPlayer:FindFirstChild('Backpack')
    if record.Character ~= character or (tool.Parent ~= character and tool.Parent ~= pack) then
        return
    end
    local queue = Data.PendingGunShots and Data.PendingGunShots[tool]
    local now = tick()
    if phowg.record_combat_ammo then
        phowg:record_combat_ammo(tool, spent)
    end
    local count = math.clamp(math.floor(tonumber(spent) or 0), 0, 128)
    for _ = 1, count do
        local shot
        while queue and #queue > 0 do
            local candidate = table.remove(queue, 1)
            if
                candidate.Character == character
                and candidate.Target.Parent
                and candidate.Target.Character == candidate.TargetCharacter
                and now - candidate.At <= phowg:hit_confirmation_window() + 0.2
            then
                shot = candidate
                break
            end
        end
        if not shot then
            break
        end
        phowg:record_target_gun_shot(tool, shot.Target, shot.At)
    end
    if queue and #queue == 0 then
        Data.PendingGunShots[tool] = nil
    end
end
function phowg:record_bullet_hit(handle, _origin, _point, hitPart)
    if Library.Unloaded or Data.SharedSignalsClosed or not phowg:native_hit_feedback_enabled() then
        return
    end
    local character = LocalPlayer.Character
    if
        not character
        or typeof(handle) ~= 'Instance'
        or not handle:IsA('BasePart')
        or not handle:IsDescendantOf(character)
        or typeof(hitPart) ~= 'Instance'
        or not hitPart:IsA('BasePart')
    then
        return
    end
    if Data.ChinaRemoteEmission == handle.Parent then
        return
    end
    local tool = handle.Parent
    if not tool or not tool:IsA('Tool') or tool.Parent ~= character then
        return
    end
    Data.BulletHitPlayers = Data.BulletHitPlayers or setmetatable({}, { __mode = 'k' })
    local cached = Data.BulletHitPlayers[hitPart]
    local player = cached and cached.Player
    if
        not player
        or not player.Parent
        or player.Character ~= cached.Character
        or not hitPart:IsDescendantOf(cached.Character)
    then
        player = nil
        local model = hitPart.Parent
        while model and model ~= Workspace do
            if model:IsA('Model') then
                player = Players:GetPlayerFromCharacter(model)
                if player then
                    break
                end
            end
            model = model.Parent
        end
        if
            not player
            or player == LocalPlayer
            or not player.Parent
            or not player.Character
            or not hitPart:IsDescendantOf(player.Character)
        then
            return
        end
        Data.BulletHitPlayers[hitPart] = { Player = player, Character = player.Character }
    end
    if player == LocalPlayer then
        return
    end
    local state = Data.ConfirmedHitStates and Data.ConfirmedHitStates[player]
    if not state or state.Character ~= player.Character then
        hookhitwatch(player)
        state = Data.ConfirmedHitStates and Data.ConfirmedHitStates[player]
    end
    if not state or state.Closed or (state.Humanoid.Health <= 0 and #state.Losses == 0) then
        return
    end
    phowg:prune_hit_shots(state)
    local now, window = tick(), phowg:hit_confirmation_window()
    state.Shots.Tail = state.Shots.Tail + 1
    state.Shots.Items[state.Shots.Tail] =
        { At = now, Expires = now + window + 0.2, Window = window, OwnerCharacter = character, Weapon = tool.Name }
    phowg:flush_confirmed_hits(player)
end
phowg:register_cleanup('bullet hit feedback', function(scope, reason)
    for player, state in pairs(table.clone(Data.ConfirmedHitStates or {})) do
        if not scope or scope == player or scope == state.Character or phowg:scope_contains(scope, state.Humanoid) then
            state:Disconnect()
        elseif scope == LocalPlayer.Character or scope == Data.ManagedCharacter then
            table.clear(state.Losses)
            table.clear(state.Shots.Items)
            state.Shots.Head, state.Shots.Tail = 1, 0
            if state.Timer then
                pcall(task.cancel, state.Timer)
                state.Timer = nil
            end
        end
    end
    if not scope or reason == 'unload' or scope == LocalPlayer.Character or scope == Data.ManagedCharacter then
        Data.BulletHitPlayers, Data.PendingGunShots = nil, nil
    end
end)
function isattacking()
    local value = Local_Parts.Attacking
    return value ~= nil and value.Parent == Local_Parts.BodyEffects and value.Value == true
end
function phowg:queue_observed_gun_reload(tool, record)
    if not (Toggles.auto_reload and Toggles.auto_reload.Value) then
        return
    end
    Data.AutoReloadQueue = Data.AutoReloadQueue or setmetatable({}, { __mode = 'k' })
    Data.AutoReloadQueue[tool] = { Character = record.Character, Tool = tool }
end
function phowg:update_auto_reload()
    if
        Library.Unloaded
        or Data.SharedSignalsClosed
        or Library.ConfigLoading
        or not (Toggles.auto_reload and Toggles.auto_reload.Value)
    then
        Data.AutoReloadQueue = nil
        return
    end
    local character = LocalPlayer.Character
    if not character then
        Data.AutoReloadQueue = nil
        return
    end
    local queue = Data.AutoReloadQueue or setmetatable({}, { __mode = 'k' })
    Data.AutoReloadQueue = queue
    local multi = phowg:china_multi_active()
    for _, tool in ipairs(character:GetChildren()) do
        local ammo = tool:IsA('Tool') and tool:FindFirstChild('Ammo')
        if ammo and type(ammo.Value) == 'number' and ammo.Value <= 0 and not queue[tool] then
            queue[tool] = { Character = character, Tool = tool }
        end
    end
    if multi then
        for _, name in ipairs(phowg:ragebot_gun_names()) do
            local tool = getweapontool(name)
            local ammo = tool and tool:FindFirstChild('Ammo')
            if ammo and type(ammo.Value) == 'number' and ammo.Value <= 0 and not queue[tool] then
                queue[tool] = { Character = character, Tool = tool }
            end
        end
    end
    local backpack = LocalPlayer:FindFirstChild('Backpack')
    for tool, pendingRequest in pairs(queue) do
        local ammo = tool:FindFirstChild('Ammo')
        if
            pendingRequest.Character ~= character
            or not ammo
            or type(ammo.Value) ~= 'number'
            or ammo.Value > 0
            or tool.Parent ~= character
                and not (multi and tool.Parent == backpack and phowg:is_ragebot_gun_selected(tool))
        then
            queue[tool] = nil
        end
    end
    if
        Data.RagebotIdle
        or Data.LoadoutReloadJob
        or Data.GunReloadSelection
        or Data.Buying
        or Data.Sorting
        or Data.IsRespawning
        or localactionblocked()
        or isreloading()
    then
        return
    end
    if phowg:reload_pending(character) then
        return
    end
    for tool in pairs(queue) do
        local reserve = getgunreserve(tool)
        if reserve == nil or reserve > 0 then
            if phowg:request_gun_reload(tool, MainEvent or ReplicatedStorage:FindFirstChild('MainEvent')) then
                return
            end
        end
    end
end
registerheartbeat('AutoReload', phowg.update_auto_reload, 0.08, function()
    return Toggles.auto_reload and Toggles.auto_reload.Value or Data.AutoReloadQueue ~= nil
end)
phowg:register_cleanup('automatic gun reload', function(scope, reason)
    if not scope or reason == 'unload' or scope == LocalPlayer.Character or scope == Data.ManagedCharacter then
        Data.AutoReloadQueue, Data.GunReloadPending = nil, nil
    end
end)
function phowg:sync_observed_tool(tool, record, reload)
    if tool.Parent ~= LocalPlayer.Character or record.Character ~= LocalPlayer.Character then
        return
    end
    local ammo = record.Ammo
    Local_Data.Current_Gun = ammo and tool or nil
    Local_Data.Ammo = ammo and ammo.Value or nil
    Local_Data.MaxAmmo = record.MaxAmmo and record.MaxAmmo.Value or nil
    if
        ammo
        and ammo.Value <= 0
        and not (Data.GunReloadSelection and Data.GunReloadSelection.Tool == tool)
        and not phowg:china_multi_active()
    then
        task.defer(function()
            if
                tool.Parent == LocalPlayer.Character
                and record.Character == LocalPlayer.Character
                and ammo.Parent == tool
                and ammo.Value <= 0
                and not phowg:china_multi_active()
            then
                phowg:stop_gun_fire(nil, tool)
            end
        end)
    end
    if
        reload
        and not Data.LoadoutReloadJob
        and ammo
        and ammo.Value == 0
        and Toggles.auto_reload
        and Toggles.auto_reload.Value
        and not localactionblocked()
    then
        phowg:queue_observed_gun_reload(tool, record)
    end
end
function hookammotool(tool)
    if not tool or not tool:IsA('Tool') then
        return nil
    end
    Data.ToolObservers = Data.ToolObservers or setmetatable({}, { __mode = 'k' })
    local character = LocalPlayer.Character
    local record = Data.ToolObservers[tool]
    if record and record.Character == character then
        return record, false
    end
    record = { Character = character, Connections = {}, ReloadQueued = nil :: any }
    Data.ToolObservers[tool] = record
    local function keep(connection)
        record.Connections[connection] = true
        table.insert(Data.LocalToolConns, connection)
        return connection
    end
    local function discard(connection)
        connection:Disconnect()
        record.Connections[connection] = nil
        local index = table.find(Data.LocalToolConns, connection)
        if index then
            table.remove(Data.LocalToolConns, index)
        end
    end
    local function observe(value)
        if
            phowg.invalidate_china_gun_cache
            and (
                value.Name == 'Ammo'
                or value.Name == 'MaxAmmo'
                or value.Name == 'Handle'
                or value.Name == 'Reload'
                or value.Name == 'Reloading'
                or value.Name:find('GunClient', 1, true)
            )
        then
            phowg:invalidate_china_gun_cache(tool)
        end
        if value.Name ~= 'Ammo' and value.Name ~= 'MaxAmmo' then
            return
        end
        if not value:IsA('ValueBase') then
            return
        end
        local key = value.Name
        if record[key] == value then
            return
        end
        if record[key .. 'Connection'] then
            discard(record[key .. 'Connection'])
        end
        record[key] = value
        local last = value.Value
        record[key .. 'Connection'] = keep(connectshared(value:GetPropertyChangedSignal('Value'), function()
            local current = value.Value
            if key == 'Ammo' and current < last then
                phowg:confirm_gun_ammo(tool, record, last - current)
            end
            if key == 'Ammo' and tool.Parent == character and current < last then
                Data.RecentlyShotAt = tick()
                Data.RecentlyShotTight = Data.RecentlyShotAt
                local held = Data.HeldGunFire
                if
                    held
                    and (held.Tool == tool or (held.ChinaHack or held.SupportMulti) and phowg:is_ragebot_gun_selected(tool))
                then
                    held.LastShotAt = Data.RecentlyShotAt
                    held.Guns = held.Guns or setmetatable({}, { __mode = 'k' })
                    held.Guns[tool] = { Ammo = current, LastShotAt = Data.RecentlyShotAt }
                    if held.Tool == tool then
                        held.Ammo = current
                    end
                end
            end
            last = current
            phowg:sync_observed_tool(tool, record, key == 'Ammo')
        end, character, 'inventory/' .. key))
        phowg:sync_observed_tool(tool, record, key == 'Ammo')
    end
    keep(connectshared(tool.Activated, function()
        if tool.Parent == character and character == LocalPlayer.Character then
            Data.RecentlyShotAt = tick()
            if not Local_Parts.Attacking and tool:GetAttribute('Attacking') == nil and phowg.play_skin_attack then
                phowg:play_skin_attack(tool)
            end
        end
    end, character, 'inventory/activated', 0, 'event/Activated', tool))
    if tool.Name == '[Knife]' then
        keep(connectshared(tool:GetAttributeChangedSignal('Attacking'), function()
            if tool:GetAttribute('Attacking') ~= true then
                local state = Data.SkinToolStates and Data.SkinToolStates[tool]
                if state then
                    state.AttributeAttackPlayed = nil
                end
            elseif tool.Parent == character and character == LocalPlayer.Character and phowg.play_skin_attack then
                phowg:play_skin_attack(tool)
            end
        end, character, 'inventory/knife attack', 0, 'attribute/Attacking', tool))
    end
    keep(connectshared(tool.ChildAdded, observe, character, 'inventory/value added', 0, 'event/ChildAdded', tool))
    keep(connectshared(tool.ChildRemoved, function(value)
        if phowg.invalidate_china_gun_cache then
            phowg:invalidate_china_gun_cache(tool)
        end
        local key = value.Name
        if record[key] ~= value then
            return
        end
        if record[key .. 'Connection'] then
            discard(record[key .. 'Connection'])
            record[key .. 'Connection'] = nil
        end
        record[key] = nil
        phowg:sync_observed_tool(tool, record, false)
    end, character, 'inventory/value removed', 0, 'event/ChildRemoved', tool))
    keep(connectshared(tool.AncestryChanged, function()
        if phowg.invalidate_china_gun_cache then
            phowg:invalidate_china_gun_cache(tool)
        end
        if tool.Parent ~= character then
            phowg:queue_removed_gun_stop(tool, character)
        end
        local backpack = LocalPlayer:FindFirstChild('Backpack')
        if tool:IsDescendantOf(character) or (backpack and tool:IsDescendantOf(backpack)) then
            return
        end
        for connection in pairs(record.Connections) do
            discard(connection)
        end
        Data.ToolObservers[tool] = nil
        if phowg.stop_skin_tool then
            phowg:stop_skin_tool(tool, true)
        end
        phowg:stop_tool_shoot_sounds(tool)
    end, character, 'inventory/tool released', 0, 'event/AncestryChanged', tool))
    for _, value in ipairs(tool:GetChildren()) do
        observe(value)
    end
    return record, true
end
function hooklocaltools(character)
    if not character or character ~= LocalPlayer.Character then
        return
    end
    if Data.ToolCharacter == character and Data.ToolAddedConnection and Data.ToolAddedConnection.Connected then
        return
    end
    if Data.ToolCharacter then
        phowg:restore_tool_sounds(Data.ToolCharacter)
        if phowg.clear_skin_tools then
            phowg:clear_skin_tools(Data.ToolCharacter)
        end
    end
    for _, connection in pairs(Data.LocalToolConns or {}) do
        connection:Disconnect()
    end
    Data.LocalToolConns = {}
    Data.ToolObservers = setmetatable({}, { __mode = 'k' })
    Data.ToolCharacter = character
    phowg:bind_local_data(character)
    if phowg.bind_local_materials then
        phowg:bind_local_materials(character)
    end
    local function added(tool)
        if character ~= LocalPlayer.Character or tool.Parent ~= character then
            return
        end
        if tool.Name == 'BodyEffects' then
            phowg:bind_local_data(character, tool)
        end
        if not tool:IsA('Tool') then
            return
        end
        if phowg.queue_ragebot_tool_prune then
            phowg:queue_ragebot_tool_prune(character)
        end
        local record, fresh = hookammotool(tool)
        if record and not fresh then
            phowg:sync_observed_tool(tool, record, true)
        end
        if phowg.inventory_tool_added then
            phowg:inventory_tool_added(tool)
        end
        if onskintooladded then
            onskintooladded(tool)
        end
        hooktoolshootsound(tool)
        if tool.Name == '[Wallet]' then
            task.delay(0.3, function()
                if LocalPlayer.Character == character and tool.Parent == character then
                    applywalletmoneytext()
                end
            end)
        end
    end
    Data.ToolAddedConnection = create_connection(
        'LocalCharacterToolAdded',
        connectshared(
            character.ChildAdded,
            added,
            character,
            'inventory/tool added',
            -100,
            'event/ChildAdded',
            character
        )
    )
    table.insert(Data.LocalToolConns, Data.ToolAddedConnection)
    table.insert(
        Data.LocalToolConns,
        create_connection(
            'LocalCharacterToolRemoved',
            connectshared(character.ChildRemoved, function(tool)
                if character ~= LocalPlayer.Character then
                    return
                end
                if tool.Name == 'BodyEffects' and Local_Parts.BodyEffects == tool then
                    phowg:bind_local_data(character, false)
                end
                if not tool:IsA('Tool') then
                    return
                end
                phowg:queue_removed_gun_stop(tool, character)
                if Local_Data.Current_Gun == tool then
                    Local_Data.Current_Gun, Local_Data.Ammo, Local_Data.MaxAmmo = nil, nil, nil
                end
                if phowg.inventory_tool_removed then
                    phowg:inventory_tool_removed(tool)
                end
                if phowg.stop_skin_tool then
                    phowg:stop_skin_tool(tool, false)
                end
                phowg:stop_tool_shoot_sounds(tool)
            end, character, 'inventory/tool removed', -100, 'event/ChildRemoved', character)
        )
    )
    table.insert(
        Data.LocalToolConns,
        create_connection(
            'LocalCharacterDescendantAdded',
            connectshared(character.DescendantAdded, function(part)
                if character ~= LocalPlayer.Character then
                    return
                end
                if phowg.local_material_added then
                    phowg:local_material_added(part)
                end
                if part.Name == 'ShootSound' and part:IsA('Sound') then
                    local tool = part:FindFirstAncestorOfClass('Tool')
                    if tool and tool.Parent == character then
                        local record = Data.ToolObservers[tool]
                        if record and record.Sounds then
                            record.Sounds[part] = true
                        end
                        convertsound(part, tool)
                    end
                elseif
                    (part.Name == 'Handle' or part.Name == 'Default')
                    and part.Parent
                    and part.Parent:IsA('Tool')
                    and part.Parent.Parent == character
                then
                    if onskintooladded then
                        onskintooladded(part.Parent)
                    end
                elseif part:IsA('JointInstance') or part:IsA('WeldConstraint') then
                    local parent, tool = part.Parent, nil
                    if part.Name == 'RightGrip' then
                        local target = part.Part1
                        tool = target and target:FindFirstAncestorOfClass('Tool')
                        if not tool then
                            target = part.Part0
                            tool = target and target:FindFirstAncestorOfClass('Tool')
                        end
                    elseif parent and parent:IsA('Tool') then
                        tool = parent
                    elseif
                        parent
                        and (parent.Name == 'Handle' or parent.Name == 'Default')
                        and parent.Parent
                        and parent.Parent:IsA('Tool')
                    then
                        tool = parent.Parent
                    end
                    if tool and tool.Name == '[Knife]' and tool.Parent == character then
                        local state = Data.SkinModelStates and Data.SkinModelStates[tool]
                        if state then
                            state.BindDirty = true
                        end
                        if onskintooladded then
                            onskintooladded(tool)
                        end
                    end
                end
            end, character, 'inventory/descendant added', -100, 'event/DescendantAdded', character)
        )
    )
    table.insert(
        Data.LocalToolConns,
        create_connection(
            'LocalCharacterDescendantRemoving',
            connectshared(character.DescendantRemoving, function(part)
                if phowg.local_material_removed then
                    phowg:local_material_removed(part)
                end
                if part:IsA('Sound') then
                    phowg:restore_tool_sound(part)
                end
            end, character, 'inventory/descendant removed', -100, 'event/DescendantRemoving', character)
        )
    )
    for _, tool in ipairs(character:GetChildren()) do
        added(tool)
    end
end
function phowg:native_hit_feedback_enabled()
    return phowg:bullet_hit_feedback_enabled() or rageboton() or punishmentactive()
end
function phowg:receive_hit_marker(headshot)
    local state = Data.NativeHitFeedback
    if
        not state
        or Library.Unloaded
        or Data.SharedSignalsClosed
        or not LocalPlayer.Character
        or type(headshot) ~= 'boolean'
    then
        return
    end
    local now = tick()
    local receipt = {
        State = state,
        At = now,
        DueAt = now + 0.2,
        Character = LocalPlayer.Character,
        Acknowledged = true,
        HasTarget = false,
        Headshot = headshot,
        PlayedSound = false,
        PlayedMarker = false,
        Delivered = false,
    }
    state.Events[#state.Events + 1] = receipt
    phowg:flush_confirmed_hits()
end
function phowg:update_native_hit_feedback()
    if phowg.sync_hit_watchers then
        phowg:sync_hit_watchers()
    end
    local state = Data.NativeHitFeedback
    if Library.Unloaded or Data.SharedSignalsClosed or not phowg:native_hit_feedback_enabled() then
        if state and state.Connection then
            state.Connection:Disconnect()
        end
        Data.NativeHitFeedback = nil
        if state and phowg.update_bullet_capture then
            phowg:update_bullet_capture()
        end
        return
    end
    if not state then
        state = { Events = {}, ConnectAt = -math.huge }
        Data.NativeHitFeedback = state
        if phowg.update_bullet_capture then
            phowg:update_bullet_capture()
        end
    end
    local now = tick()
    if now - state.ConnectAt >= 0.5 then
        state.ConnectAt = now
        local remote = MainEvent and MainEvent.Parent and MainEvent or ReplicatedStorage:FindFirstChild('MainEvent')
        if state.Remote ~= remote then
            if state.Connection then
                state.Connection:Disconnect()
                state.Connection = nil
            end
            table.clear(state.Events)
            state.Remote = remote
            if remote and remote:IsA('RemoteEvent') then
                state.Connection = connectshared(remote.OnClientEvent, function(kind, value)
                    if kind == 'HitMarker' and Data.NativeHitFeedback == state and phowg:native_hit_feedback_enabled() then
                        phowg:receive_hit_marker(value == true)
                    end
                end, remote, 'confirmed hit marker', 0, 'event/OnClientEvent', remote)
            end
        end
    end
    if now >= (state.PruneAt or 0) then
        state.PruneAt = now + 0.5
        for player, watch in pairs(Data.ConfirmedHitStates or {}) do
            if
                watch.Closed
                or not player.Parent
                or player.Character ~= watch.Character
                or not watch.Humanoid.Parent
            then
                watch:Disconnect()
            else
                phowg:prune_hit_shots(watch)
                local losses, write = watch.Losses, 1
                for _, loss in ipairs(losses) do
                    if loss.OwnerCharacter == LocalPlayer.Character and loss.Expires > now then
                        losses[write] = loss
                        write += 1
                    end
                end
                for index = #losses, write, -1 do
                    losses[index] = nil
                end
            end
        end
    end
    if #state.Events == 0 then
        return
    end
    phowg:resolve_hit_marker_feedback(state)
    state.Dirty = false
    local window = phowg:hit_confirmation_window() + 0.25
    local write, soundPlayed, markerPlayed = 1, false, false
    for _, receipt in ipairs(state.Events) do
        if not receipt.HasTarget and receipt.Character == LocalPlayer.Character and now - receipt.At <= window then
            state.Events[write] = receipt
            write += 1
            if now >= receipt.DueAt and phowg:bullet_hit_feedback_enabled() then
                local filtered = Toggles.on_hit_ignore_crew and Toggles.on_hit_ignore_crew.Value
                    or Toggles.on_hit_not_knocked and Toggles.on_hit_not_knocked.Value
                if not filtered then
                    if not receipt.PlayedSound and Toggles.hit_sound and Toggles.hit_sound.Value then
                        receipt.PlayedSound = true
                        if not soundPlayed then
                            phowg:run_hit_feedback('confirmed hit sound', playhitsound)
                            soundPlayed = true
                        end
                    end
                    if
                        not receipt.PlayedMarker
                        and Toggles.hit_marker
                        and Toggles.hit_marker.Value
                        and ((Options.hit_marker_value and Options.hit_marker_value.Value) or '2D') == '2D'
                    then
                        receipt.PlayedMarker = true
                        if not markerPlayed then
                            phowg:run_hit_feedback('confirmed hit marker', hitmarker2d)
                            markerPlayed = true
                        end
                    end
                end
            end
        end
    end
    for index = #state.Events, write, -1 do
        state.Events[index] = nil
    end
end
registerheartbeat('NativeHitFeedback', phowg.update_native_hit_feedback, 0.05, function()
    return Data.NativeHitFeedback ~= nil or phowg:native_hit_feedback_enabled()
end)
phowg:register_cleanup('native hit feedback', function(scope, reason)
    local state = Data.NativeHitFeedback
    if not state then
        return
    end
    if reason == 'unload' then
        if state.Connection then
            state.Connection:Disconnect()
        end
        Data.NativeHitFeedback = nil
    elseif not scope or scope == LocalPlayer.Character or scope == Data.ManagedCharacter then
        table.clear(state.Events)
    else
        for index = #state.Events, 1, -1 do
            local receipt = state.Events[index]
            if receipt.Player == scope or receipt.TargetCharacter == scope then
                table.remove(state.Events, index)
            end
        end
    end
end)

function phowg:run_hit_feedback(name, callback, ...)
    local ok, err = pcall(callback, ...)
    if not ok and tick() >= (Data.HitFeedbackErrorAt or 0) then
        Data.HitFeedbackErrorAt = tick() + 5
        warn('[Phowg] ' .. name .. ': ' .. tostring(err))
    end
    return ok, err
end
function onhit(plr, dmg, receipt)
    if not phowg:hit_marker_receipt_valid(receipt, plr) or not receipt.Delivering or not phowg:on_hit_allowed(plr, true) then
        return
    end
    if Toggles.hit_sound and Toggles.hit_sound.Value and not (receipt and receipt.PlayedSound) then
        local ok, result = phowg:run_hit_feedback('hit sound', playhitsound)
        if receipt then
            receipt.PlayedSound = ok and result ~= false
        end
    end
    if Toggles.damage_number and Toggles.damage_number.Value then
        phowg:run_hit_feedback('damage number', damagenumber, plr, dmg)
    end
    if Toggles.hit_skeleton and Toggles.hit_skeleton.Value then
        phowg:run_hit_feedback('hit skeleton', spawnhitskeleton, plr)
    end
    if Toggles.hit_effect and Toggles.hit_effect.Value then
        phowg:run_hit_feedback('hit effect', hiteffect, plr)
    end
    if Toggles.hit_marker and Toggles.hit_marker.Value then
        if ((Options.hit_marker_value and Options.hit_marker_value.Value) or '2D') == '3D' then
            phowg:run_hit_feedback('hit marker', hitmarker3d, plr)
        else
            if not (receipt and receipt.PlayedMarker) then
                local ok = phowg:run_hit_feedback('hit marker', hitmarker2d)
                if receipt then
                    receipt.PlayedMarker = ok
                end
            end
        end
    end
    if Toggles.hit_chams and Toggles.hit_chams.Value then
        phowg:run_hit_feedback('hit chams', hitchams, plr)
    end
end
function ismydamager(plr)
    local ok, mine = pcall(function()
        if not plr or not plr.Parent then
            return false
        end
        local char = plr.Character
        local myChar = LocalPlayer and LocalPlayer.Character
        if not char or not myChar then
            return false
        end
        local be = char:FindFirstChild('BodyEffects')
        local lastDmg = be and be:FindFirstChild('LastDamager')
        local value = lastDmg and lastDmg.Value
        if not value then
            return false
        end
        if value == myChar then
            return true
        end
        if typeof(value) ~= 'Instance' then
            return false
        end
        return value:IsDescendantOf(myChar) or Players:GetPlayerFromCharacter(value) == LocalPlayer
    end)
    return ok and mine == true
end
function phowg:target_data_observers_needed()
    if Library.Unloaded or Data.SharedSignalsClosed then
        return false
    end
    if phowg:bullet_hit_feedback_enabled() or rageboton() or punishmentactive() then
        return true
    end
    for _, name in ipairs({
        'silent_aim_enabled',
        'sticky_aim_enabled',
        'misc_auto_stomp',
        'kill_aura_enabled',
        'auto_save',
    }) do
        if Toggles[name] and Toggles[name].Value then
            return true
        end
    end
    return false
end
function phowg:clear_target_data_observer(player)
    local connections = Data.DamagerConns and Data.DamagerConns[player]
    if connections then
        if type(connections) == 'table' then
            for _, connection in pairs(connections) do
                connection:Disconnect()
            end
        else
            connections:Disconnect()
        end
        Data.DamagerConns[player] = nil
    end
    if Data.DamagerCharacters then
        Data.DamagerCharacters[player] = nil
    end
    if Data.TargetDamagerAt then
        Data.TargetDamagerAt[player] = nil
    end
end
function phowg:sync_target_data_observers()
    local needed = phowg:target_data_observers_needed()
    if Data.TargetDataObserversOn == needed then
        return
    end
    Data.TargetDataObserversOn = needed
    for _, player in ipairs(Players:GetPlayers()) do
        if needed then
            hooktargetdamagerwatch(player, player.Character)
        else
            phowg:clear_target_data_observer(player)
        end
    end
end
registerheartbeat('TargetDataObservers', phowg.sync_target_data_observers, 0.25)
function hooktargetdamagerwatch(plr, char)
    if not plr or plr == LocalPlayer or not char then
        return
    end
    if not phowg:target_data_observers_needed() then
        phowg:clear_target_data_observer(plr)
        return
    end
    Data.DamagerConns = Data.DamagerConns or {}
    Data.TargetDamagerAt = Data.TargetDamagerAt or {}
    local old = Data.DamagerConns[plr]
    Data.DamagerCharacters = Data.DamagerCharacters or setmetatable({}, { __mode = 'k' })
    if old and Data.DamagerCharacters[plr] == char and old[1] and old[1].Connected then
        return
    end
    if old then
        if type(old) == 'table' then
            for _, connection in pairs(old) do
                connection:Disconnect()
            end
        else
            old:Disconnect()
        end
    end
    local connections, values, valueConnections = {}, {}, {}
    Data.DamagerConns[plr] = connections
    Data.DamagerCharacters[plr] = char
    local bodyEffects, addedConnection
    local function keep(connection)
        connections[#connections + 1] = connection
        return connection
    end
    local function release(connection)
        if not connection then
            return
        end
        connection:Disconnect()
        local index = table.find(connections, connection)
        if index then
            table.remove(connections, index)
        end
    end
    local function observe(value)
        local name = value.Name
        if name ~= 'LastDamager' and name ~= 'SDeath' and name ~= 'SDead' then
            return
        end
        if not value:IsA('ValueBase') or values[name] == value then
            return
        end
        release(valueConnections[name])
        values[name] = value
        local function sync()
            if plr.Character ~= char or value.Parent ~= bodyEffects then
                return
            end
            if name == 'LastDamager' then
                if ismydamager(plr) then
                    Data.TargetDamagerAt[plr] = tick()
                end
                phowg:flush_confirmed_hits(plr)
            else
                Data._ActionableAt, Data.TargetListCache = nil, nil
                if value.Value == true then
                    phowg:hide_after_stomp(plr)
                end
            end
        end
        valueConnections[name] = keep(
            connectshared(
                value:GetPropertyChangedSignal('Value'),
                sync,
                value,
                'target data/value',
                0,
                'property/Value',
                value
            )
        )
        sync()
    end
    local function bind_effects(effects)
        if plr.Character ~= char or bodyEffects == effects then
            return
        end
        release(addedConnection)
        for _, connection in pairs(valueConnections) do
            release(connection)
        end
        table.clear(values)
        table.clear(valueConnections)
        bodyEffects = effects
        addedConnection = keep(
            connectshared(effects.ChildAdded, observe, effects, 'target data/added', 0, 'event/ChildAdded', effects)
        )
        for _, name in ipairs({ 'LastDamager', 'SDeath', 'SDead' }) do
            local value = effects:FindFirstChild(name)
            if value then
                observe(value)
            end
        end
    end
    local effects = char:FindFirstChild('BodyEffects')
    if effects then
        bind_effects(effects)
    end
    keep(connectshared(char.ChildAdded, function(child)
        if child.Name == 'BodyEffects' then
            bind_effects(child)
        end
    end, char, 'target data/character added', 0, 'event/ChildAdded', char))
end
function isgrenadetool(t)
    if not t then
        return false
    end
    local ok, isTool = true, (t:IsA('Tool'))
    if not ok or not isTool then
        return false
    end
    local ln = string.lower(t.Name)
    if string.find(ln, 'grenade', 1, true) then
        return true
    end
    return false
end
function hookgrenadewatch()
    if Data['NadeConns'] then
        for _, c in pairs(Data['NadeConns']) do
            c:Disconnect()
        end
    end
    Data['NadeConns'] = {}
    local function watch(cont)
        if not cont then
            return
        end
        local c = connectshared(cont.ChildRemoved, function(ch)
            local isNade = false
            isNade = isgrenadetool(ch)
            if not isNade then
                return
            end
            local myChar = LocalPlayer and LocalPlayer.Character
            if not myChar then
                return
            end
            if Data['IsRespawning'] then
                return
            end
            local dead = false
            dead = isdead(LocalPlayer)
            if dead then
                return
            end
            local hum = myChar:FindFirstChildOfClass('Humanoid')
            if hum and hum.Health <= 0 then
                return
            end
            Data['RecentlyNadedAt'] = tick()
            local cur = Data['CurrentActionTarget'] or Data['CurrentMainTarget'] or Data['SingleLockedTarget']
            if cur and cur.Parent then
                Data['NadeTarget'] = cur
            else
                local ok, list = true, (gettargetlist())
                if ok and list and list[1] then
                    Data['NadeTarget'] = list[1]
                end
            end
        end, cont, 'event/cont.ChildRemoved', 0, 'event/ChildRemoved', cont)
        table.insert(Data['NadeConns'], c)
    end
    (function()
        local char = LocalPlayer and LocalPlayer.Character
        if char then
            watch(char)
        end
    end)();
    (function()
        local bp = LocalPlayer and LocalPlayer:FindFirstChild('Backpack')
        if bp then
            watch(bp)
        end
    end)()
end
function isnademethod(plr)
    if not plr or not plr.Parent then
        return nil
    end
    if tick() - (Data['RecentlyNadedAt'] or 0) > 3.5 then
        return nil
    end
    local cur = Data['NadeTarget']
    if cur and cur.Parent and cur == plr then
        return 'nade'
    end
    if Data['CurrentActionTarget'] and Data['CurrentActionTarget'] == plr then
        return 'nade'
    end
    if Data['CurrentMainTarget'] and Data['CurrentMainTarget'] == plr then
        return 'nade'
    end
    return nil
end
function hasclosecombatool()
    local char = LocalPlayer and LocalPlayer.Character
    if not char then
        return false
    end
    local function check(t)
        if t:IsA('Tool') then
            if t:FindFirstChild('Ammo') then
                return true
            end
            local ln = string.lower(t.Name)
            if string.find(ln, 'combat', 1, true) or string.find(ln, 'knife', 1, true) then
                return true
            end
        end
        return false
    end
    for _, t in ipairs(char:GetChildren()) do
        if check(t) then
            return true
        end
    end
    return false
end
function isfisthit(plr)
    local now = tick()
    local punchRecent = now - (Data['RecentlyAttacked'] or 0) < 0.6
    local attackingNow = false
    attackingNow = isattacking()
    if punchRecent or attackingNow then
        local hasTool = false
        hasTool = hasclosecombatool()
        if not hasTool then
            return false
        end
        local d = getdistancetoplayer(plr)
        if d < 10 then
            return true
        end
        local spoof = Data['LastServerCF']
        if typeof(spoof) == 'CFrame' then
            local tr = plr.Character and plr.Character:FindFirstChild('HumanoidRootPart') or nil
            if tr then
                local sd = (spoof.Position - tr.CFrame.Position).Magnitude
                if sd < 10 then
                    return true
                end
            end
        end
    end
    return false
end
function tryhit(plr, drop, method, weapon, receipt)
    if not phowg:hit_marker_receipt_valid(receipt, plr) or receipt.Delivered or not phowg:on_hit_allowed(plr, true) then
        return
    end
    if type(drop) ~= 'number' or drop <= 0 or drop ~= drop or drop == math.huge then
        return
    end
    receipt.Delivered, receipt.Delivering = true, true
    local dmg = drop
    onhit(plr, dmg, receipt)
    receipt.Delivering = false
    if Toggles.hit_notifications and Toggles.hit_notifications.Value then
        local w = 'gun'
        (function()
            local m = tostring(method or '')
            if string.sub(m, 1, 6) == 'blood-' then
                m = string.sub(m, 7)
            end
            if m == 'nade' then
                w = 'grenade'
            else
                local found = weapon
                local ch = LocalPlayer and LocalPlayer.Character or nil
                if not found and ch then
                    for _, t in ipairs(ch:GetChildren()) do
                        if t:IsA('Tool') then
                            found = t.Name
                            break
                        end
                    end
                end
                if found then
                    if string.find(string.lower(tostring(found)), 'combat', 1, true) then
                        w = 'fists'
                    else
                        local okN, nm = true, (punishmentcleantoolname(found))
                        if okN and nm and nm ~= '' then
                            w = nm
                        end
                    end
                elseif m == 'fist' then
                    w = 'fists'
                end
            end
        end)();
        (function()
            local fallback = 'shot landed on '
                .. Library:PlayerDisplayName(plr)
                .. ' for '
                .. tostring(math.round(dmg))
                .. ' damage.'
            Library:Notify(phowg:combat_notification('hit', plr, dmg, w, 'hit', fallback), Library.NotifyDuration or 3)
        end)()
    end
end
function hookhitwatch(plr)
    if not plr or plr == LocalPlayer then
        return
    end
    local char = plr.Character
    if char then
        hooktargetdamagerwatch(plr, char)
    end
    if not phowg:native_hit_feedback_enabled() then
        local previous = Data.HitConns and Data.HitConns[plr]
        if previous then
            previous:Disconnect()
        end
        return
    end
    local hum = char and char:FindFirstChildOfClass('Humanoid')
    if not hum then
        return
    end
    Data.HitConns = Data.HitConns or {}
    Data.HitHealth = Data.HitHealth or {}
    Data.ConfirmedHitStates = Data.ConfirmedHitStates or setmetatable({}, { __mode = 'k' })
    local old = Data.HitConns[plr]
    local existing = Data.ConfirmedHitStates[plr]
    if existing and not existing.Closed and existing.Character == char and existing.Humanoid == hum then
        return
    end
    if old then
        old:Disconnect()
    end
    local state: { [string]: any } = {
        Player = plr,
        Character = char,
        Humanoid = hum,
        Health = hum.Health,
        Shots = { Items = {}, Head = 1, Tail = 0 },
        Losses = {},
        Connections = {},
        Closed = false,
        Flushing = false,
    }
    function state:Disconnect()
        if self.Closed then
            return
        end
        self.Closed = true
        if self.ArmorAdded then
            self.ArmorAdded:Disconnect()
            self.ArmorAdded = nil
        end
        if self.ArmorConnection then
            self.ArmorConnection:Disconnect()
            self.ArmorConnection = nil
        end
        if self.Timer then
            pcall(task.cancel, self.Timer)
            self.Timer = nil
        end
        for _, connection in ipairs(self.Connections) do
            connection:Disconnect()
        end
        table.clear(self.Connections)
        table.clear(self.Losses)
        table.clear(self.Shots.Items)
        if Data.ConfirmedHitStates[plr] == self then
            Data.ConfirmedHitStates[plr] = nil
        end
        if Data.HitConns[plr] == self then
            Data.HitConns[plr] = nil
        end
    end
    Data.ConfirmedHitStates[plr], Data.HitConns[plr], Data.HitHealth[plr] = state, state, hum.Health
    local function loss(amount, kind)
        if
            state.Closed
            or plr.Character ~= char
            or Library.Unloaded
            or Data.SharedSignalsClosed
            or amount <= 0
            or amount ~= amount
            or amount == math.huge
        then
            return
        end
        phowg:prune_hit_shots(state)
        local method = isfisthit(plr) and 'fist' or isnademethod(plr)
        local now = tick()
        local previous = state.Losses[#state.Losses]
        if
            previous
            and not previous[kind]
            and now - previous.At < 1 / 120
            and previous.OwnerCharacter == LocalPlayer.Character
        then
            previous[kind] = true
            previous.Damage = previous.Damage + amount
        else
            local event = {
                At = now,
                ReadyAt = now + 0.15,
                Expires = now + phowg:hit_confirmation_window() + 0.15,
                OwnerCharacter = LocalPlayer.Character,
                Damage = amount,
                Method = method,
            }
            event[kind] = true
            state.Losses[#state.Losses + 1] = event
        end
        phowg:flush_confirmed_hits(plr)
    end
    state.Connections[#state.Connections + 1] = connectshared(hum:GetPropertyChangedSignal('Health'), function()
        if state.Closed or plr.Character ~= char or not hum.Parent then
            return
        end
        local health = hum.Health
        local drop = state.Health - health
        state.Health, Data.HitHealth[plr] = health, health
        if drop > 0 then
            loss(drop, 'Health')
        end
    end, hum, 'hit confirmation/health', 0, 'property/Health', hum)
    local function bind_armor(armor)
        if
            not armor
            or armor.Name ~= 'Armor'
            or not (armor:IsA('NumberValue') or armor:IsA('IntValue'))
            or state.ArmorValue == armor
        then
            return
        end
        if state.ArmorConnection then
            state.ArmorConnection:Disconnect()
        end
        state.ArmorValue, state.Armor = armor, armor.Value
        state.ArmorConnection = connectshared(armor:GetPropertyChangedSignal('Value'), function()
            if state.Closed or plr.Character ~= char or armor.Parent ~= char:FindFirstChild('BodyEffects') then
                return
            end
            local value = armor.Value
            local drop = state.Armor - value
            state.Armor = value
            if drop > 0 then
                loss(drop, 'Armor')
            end
        end, armor, 'hit confirmation/armor', 0, 'property/Value', armor)
    end
    local effects
    local function bind_effects(folder)
        if folder.Name ~= 'BodyEffects' or effects == folder or state.Closed then
            return
        end
        if state.ArmorAdded then
            state.ArmorAdded:Disconnect()
        end
        if state.ArmorConnection then
            state.ArmorConnection:Disconnect()
            state.ArmorConnection = nil
        end
        state.ArmorValue, effects = nil, folder
        state.ArmorAdded = connectshared(
            folder.ChildAdded,
            bind_armor,
            folder,
            'hit confirmation/armor added',
            0,
            'event/ChildAdded',
            folder
        )
        bind_armor(folder:FindFirstChild('Armor'))
    end
    state.Connections[#state.Connections + 1] = connectshared(
        char.ChildAdded,
        bind_effects,
        char,
        'hit confirmation/body effects added',
        0,
        'event/ChildAdded',
        char
    )
    local bodyEffects = char:FindFirstChild('BodyEffects')
    if bodyEffects then
        bind_effects(bodyEffects)
    end
    hooktargetdamagerwatch(plr, char)
end
function phowg:sync_hit_watchers()
    local enabled = phowg:native_hit_feedback_enabled()
    if Data.HitWatchersEnabled == enabled then
        return
    end
    Data.HitWatchersEnabled = enabled
    for _, player in ipairs(Players:GetPlayers()) do
        hookhitwatch(player)
    end
end
function hookbloodsound()
    if Data['BloodSoundConn'] then
        Data['BloodSoundConn']:Disconnect()
    end
    Data['BloodSoundConn'] = nil
    local wps = Workspace:FindFirstChild('Players')
    if not wps then
        task.spawn(function()
            local w = Workspace:WaitForChild('Players', 10)
            if w then
                hookbloodsound()
            end
        end)
        return
    end
    Data['BloodSoundConn'] = connectshared(wps.DescendantAdded, function(d)
        if d.Name ~= 'BloodSplatter' then
            return
        end
        task.defer(function()
            (function()
                local okS, isSound = true, (d:IsA('Sound'))
                if not okS or not isSound then
                    return
                end
                if not (Toggles.hit_sound and Toggles.hit_sound.Value) then
                    return
                end
                local now = tick()
                local acting = false
                if now - (Data['RecentlyShotTight'] or 0) < 1.0 then
                    acting = true
                end
                if now - (Data['RecentlyAttacked'] or 0) < 1.0 then
                    acting = true
                end
                if now - (Data['RecentlyNadedAt'] or 0) < 4.0 then
                    acting = true
                end
                if not acting then
                    (function()
                        if isattacking() then
                            acting = true
                        end
                    end)()
                end
                if acting then
                    d.Volume = 0
                end
            end)()
        end)
    end, wps, 'event/wps.DescendantAdded', 0, 'event/DescendantAdded', wps)
end
function hookexplosionsound()
    if Data['ExplosionSoundConn'] then
        Data['ExplosionSoundConn']:Disconnect()
    end
    Data['ExplosionSoundConn'] = nil
    local ign = Workspace:FindFirstChild('Ignored')
    if not ign then
        task.spawn(function()
            local w = Workspace:WaitForChild('Ignored', 10)
            if w then
                hookexplosionsound()
            end
        end)
        return
    end
    Data['ExplosionSoundConn'] = connectshared(ign.DescendantAdded, function(d)
        if d.Name ~= 'Explosion' then
            return
        end
        local isSound = false
        isSound = d:IsA('Sound')
        if not isSound then
            return
        end
        local sid = ''
        sid = tostring(d.SoundId)
        if not string.find(string.lower(sid), 'collide', 1, true) then
            return
        end
        task.defer(function()
            (function()
                local now = tick()
                local acting = false
                if now - (Data['RecentlyShotTight'] or 0) < 0.5 then
                    acting = true
                end
                if now - (Data['RecentlyShotAt'] or 0) < 0.5 then
                    acting = true
                end
                if now - (Data['RecentlyAttacked'] or 0) < 0.8 then
                    acting = true
                end
                if now - (Data['RecentlyNadedAt'] or 0) < 3.5 then
                    acting = true
                end
                if not acting then
                    local atk = false
                    atk = isattacking()
                    if atk then
                        acting = true
                    end
                end
                if not acting then
                    return
                end
                local pos = nil
                (function()
                    local par = d.Parent
                    if par and par:IsA('BasePart') then
                        pos = par.Position
                    end
                end)()
                if pos then
                    local nearTarget = false
                    (function()
                        local tgts = {}
                        if Data['NadeTarget'] and Data['NadeTarget'].Parent then
                            table.insert(tgts, Data['NadeTarget'])
                        end
                        if Data['CurrentActionTarget'] and Data['CurrentActionTarget'].Parent then
                            table.insert(tgts, Data['CurrentActionTarget'])
                        end
                        if Data['CurrentMainTarget'] and Data['CurrentMainTarget'].Parent then
                            table.insert(tgts, Data['CurrentMainTarget'])
                        end
                        if #tgts == 0 then
                            return
                        end
                        for _, t in ipairs(tgts) do
                            local c = t.Character
                            local r = c and getroot(c) or nil
                            if r and (r.Position - pos).Magnitude < 60 then
                                nearTarget = true
                                break
                            end
                        end
                        if not nearTarget then
                            local myR = LocalPlayer.Character and getroot(LocalPlayer.Character) or nil
                            if myR and (myR.Position - pos).Magnitude < 60 then
                                nearTarget = true
                            end
                        end
                    end)()
                    if not nearTarget then
                        return
                    end
                end
                d.Volume = 0
            end)()
        end)
    end, ign, 'event/ign.DescendantAdded', 0, 'event/DescendantAdded', ign)
end
function phowg:update_ban_notification(state)
    if Data.ReportedCountWatch ~= state or Library.Unloaded or Data.SharedSignalsClosed then
        return
    end
    local value = state.BanValue
    local current = value and value.Parent == state.Folder and tonumber(value.Value) or nil
    local previous = state.LastLockFlagged
    state.LastLockFlagged = current
    if previous and previous > 0 and current == 0 and Toggles.notify_bans and Toggles.notify_bans.Value then
        Library:Notify('you have been reported and the game has banned you, you will get kicked in the next 3 seconds.', 6)
    end
end
function phowg:update_reported_count_label()
    local label = Data.ReportedCountLabel
    if not label or Library.Unloaded or Data.SharedSignalsClosed then
        return
    end
    local state = Data.ReportedCountWatch
    local value = state and state.Value
    local text = 'reported count: ' .. (value and value.Parent == state.Folder and tostring(value.Value) or 'loading')
    if Data.ReportedCountText ~= text then
        Data.ReportedCountText = text
        label:SetText(text)
    end
end
function phowg:clear_reported_count_watch()
    local state = Data.ReportedCountWatch
    Data.ReportedCountWatch = nil
    for _, connection in pairs(state and state.Connections or {}) do
        connection:Disconnect()
    end
end
function phowg:bind_reported_count_label()
    if Library.Unloaded or Data.SharedSignalsClosed then
        return
    end
    local state = Data.ReportedCountWatch
    if state and state.Player == LocalPlayer then
        phowg:update_reported_count_label()
        return
    end
    phowg:clear_reported_count_watch()
    state = { Player = LocalPlayer, Connections = {} }
    Data.ReportedCountWatch = state
    local function disconnect(name)
        local connection = state.Connections[name]
        if connection then
            connection:Disconnect()
            state.Connections[name] = nil
        end
    end
    local function refresh()
        if Data.ReportedCountWatch ~= state then
            return
        end
        local folder = LocalPlayer:FindFirstChild('DataFolder')
        if state.Folder ~= folder then
            disconnect('FolderAdded')
            disconnect('FolderRemoved')
            disconnect('Value')
            disconnect('BanValue')
            state.BanValue, state.LastLockFlagged = nil, nil
            state.Folder, state.Value = folder, nil
            if folder then
                state.Connections.FolderAdded = connectshared(folder.ChildAdded, function(child)
                    if child.Name == 'ReportedCount' or child.Name == 'LockFlagged' then
                        refresh()
                    end
                end, folder, 'reports/count added', 0, 'event/ChildAdded', folder)
                state.Connections.FolderRemoved = connectshared(folder.ChildRemoved, function(child)
                    if child == state.Value or child == state.BanValue then
                        refresh()
                    end
                end, folder, 'reports/count removed', 0, 'event/ChildRemoved', folder)
            end
        end
        local value = folder and folder:FindFirstChild('ReportedCount')
        if value and not value:IsA('ValueBase') then
            value = nil
        end
        if state.Value ~= value then
            disconnect('Value')
            state.Value = value
            if value then
                state.Connections.Value = connectshared(
                    value:GetPropertyChangedSignal('Value'),
                    phowg.update_reported_count_label,
                    value,
                    'reports/count changed',
                    0,
                    'property/Value',
                    value
                )
            end
        end
        local banValue = folder and folder:FindFirstChild('LockFlagged')
        if banValue and not (banValue:IsA('IntValue') or banValue:IsA('NumberValue')) then
            banValue = nil
        end
        if state.BanValue ~= banValue then
            disconnect('BanValue')
            state.BanValue, state.LastLockFlagged = banValue, nil
            if banValue then
                state.Connections.BanValue = connectshared(banValue:GetPropertyChangedSignal('Value'), function()
                    phowg:update_ban_notification(state)
                end, banValue, 'reports/ban flag changed', 0, 'property/Value', banValue)
            end
            phowg:update_ban_notification(state)
        end
        phowg:update_reported_count_label()
    end
    state.Connections.PlayerAdded = connectshared(LocalPlayer.ChildAdded, function(child)
        if child.Name == 'DataFolder' then
            refresh()
        end
    end, LocalPlayer, 'reports/data added', 0, 'event/ChildAdded', LocalPlayer)
    state.Connections.PlayerRemoved = connectshared(LocalPlayer.ChildRemoved, function(child)
        if child == state.Folder then
            refresh()
        end
    end, LocalPlayer, 'reports/data removed', 0, 'event/ChildRemoved', LocalPlayer)
    refresh()
end
phowg:register_cleanup('reported count', function(scope)
    if not scope or scope == LocalPlayer then
        phowg:clear_reported_count_watch()
    end
end)
function handlereporter(child)
    if not child then
        return
    end
    if not (Toggles.notify_reported and Toggles.notify_reported.Value) and not phowg:report_protection_enabled() then
        return
    end
    local uid = tonumber(child.Name)
    local username = tostring(child.Name)
    if child:IsA('StringValue') and child.Value ~= '' then
        username = tostring(child.Value)
    end
    task.spawn(function()
        if not uid then
            pcall(function()
                local id = Players:GetUserIdFromNameAsync(username)
                if id then
                    uid = id
                end
            end)
        end
        local disp, user = nil, username
        local target = nil
        pcall(function()
            if uid then
                target = Players:GetPlayerByUserId(uid)
            end
        end)
        if target then
            disp, user = target.DisplayName, target.Name
        end
        if not disp and uid then
            pcall(function()
                if game.HttpGet then
                    local raw = game:HttpGet('https://users.roblox.com/v1/users/' .. tostring(uid))
                    local info = nil
                    if type(raw) == 'string' and #raw > 2 and string.sub(raw, 1, 1) == '{' then
                        info = HttpService:JSONDecode(raw)
                    end
                    if info then
                        if info.displayName then
                            disp = tostring(info.displayName)
                        end
                        if info.name then
                            user = tostring(info.name)
                        end
                    end
                end
            end)
        end
        if not disp then
            disp = user
        end
        local repMode = phowg:protect_player_mode()
        local repName = (target and Library:PlayerDisplayName(target)) or (tostring(disp) .. ' | ' .. tostring(user))
        if Library.Unloaded or Data.SharedSignalsClosed then
            return
        end
        if Toggles.notify_reported and Toggles.notify_reported.Value then
            Library:Notify(repName .. ' has reported you.', Library.NotifyDuration or 5)
        end
        if phowg:report_protection_enabled() then
            if target and target ~= LocalPlayer then
                punish(target, 0, repMode, nil, 'report')
            elseif uid then
                Data.ReporterWatchlist = Data.ReporterWatchlist or {}
                Data.ReporterWatchlist[uid] = true
            end
        end
    end)
end
function watchreporters()
    if Data['ReportersWatched'] then
        return
    end
    task.spawn(function()
        local df = LocalPlayer:WaitForChild('DataFolder', 10)
        if not df then
            return
        end
        local rep = df:WaitForChild('Reporters', 10)
        if not rep then
            return
        end
        if Data['ReportersWatched'] then
            return
        end
        Data['ReportersWatched'] = true
        for _, c in ipairs(rep:GetChildren()) do
            handlereporter(c)
        end
        connectshared(rep.ChildAdded, function(c)
            handlereporter(c)
        end, rep, 'event/rep.ChildAdded', 0, 'event/ChildAdded', rep)
    end)
end
function gettargetlabelnames()
    local list = {}
    if Toggles.target_all and Toggles.target_all.Value then
        for _, p in ipairs(Players:GetPlayers()) do
            if p ~= LocalPlayer and p.Parent then
                list[#list + 1] = p.Name
            end
        end
    else
        local s = Data['SingleLockedTarget']
        if not (s and s.Parent) then
            local sel = Options.target_select and Options.target_select.Value or nil
            if typeof(sel) == 'Instance' and sel:IsA('Player') then
                s = sel
            elseif typeof(sel) == 'string' and #sel > 0 then
                s = Players:FindFirstChild(sel)
            else
                s = nil
            end
        end
        if s and s.Parent then
            list[#list + 1] = s.Name
        end
    end
    return list
end
function updatetargetlabel()
    if not Data['TargetListLabel'] then
        return
    end
    if not Data['TargetListLabel'].SetText then
        return
    end
    pcall(function()
        local list = gettargetlabelnames()
        table.sort(list)
        if #list == 0 then
            Data['TargetListLabel']:SetText('targets: none')
        else
            Data['TargetListLabel']:SetText('targets:\n' .. table.concat(list, '\n'))
        end
    end)
end
function prunetargettables()
    local function alive(p)
        return p and typeof(p) == 'Instance' and p:IsA('Player') and p.Parent and p ~= LocalPlayer
    end
    local function unwatch(p)
        if p and typeof(p) == 'Instance' and p:IsA('Player') then
            pcall(function()
                Data['TargetWatchlist'][p.UserId] = nil
            end)
            pcall(function()
                Data['TargetWatchlist'][p.Name] = nil
            end)
            if Data['StickyAimWatchlist'] then
                pcall(function()
                    Data['StickyAimWatchlist'][p.UserId] = nil
                end)
                pcall(function()
                    Data['StickyAimWatchlist'][p.Name] = nil
                end)
            end
        end
    end
    for p, _ in pairs(Data['LockedTargets']) do
        if not alive(p) then
            Data['LockedTargets'][p] = nil
            unwatch(p)
        end
    end
    for p, _ in pairs(Data['DropdownTargets'] or {}) do
        if not alive(p) then
            Data['DropdownTargets'][p] = nil
        end
    end
    for p, _ in pairs(Data['SilentAimStickyTargets'] or {}) do
        if not alive(p) then
            Data['SilentAimStickyTargets'][p] = nil
            unwatch(p)
        end
    end
    for p, _ in pairs(Data['RageWhitelist'] or {}) do
        if not alive(p) then
            Data['RageWhitelist'][p] = nil
        end
    end
