function apply_disable_states()
    if localactionblocked() then
        return
    end
    local char = LocalPlayer.Character
    local hum = char and gethumanoid(char) or nil
    if not hum or not hum.Parent then
        return
    end
    local sel = {}
    if Toggles.disable_states and Toggles.disable_states.Value then
        local raw = Options.disable_states_list and Options.disable_states_list.Value or {}
        if type(raw) == 'table' then
            for k, v in pairs(raw) do
                if type(k) == 'string' and v then
                    sel[string.lower(k)] = true
                end
                if type(v) == 'string' then
                    sel[string.lower(v)] = true
                end
            end
        end
    end
    for label, st in pairs(Data['DisableStateMap']) do
        if hum.Parent then
            hum:SetStateEnabled(st, not sel[label])
        end
    end
end
