function clearspoofaccessories(char)
    if not char then
        return
    end
    for _, c in ipairs(char:GetChildren()) do
        if (c:IsA('Accessory') or c:IsA('Tool')) and string.sub(c.Name, 1, 9) == 'spoofacc_' then
            c:Destroy()
        end
    end
end
function phowg:copy_spoof_body_part(dst, src)
    if dst:IsA('MeshPart') and src:IsA('MeshPart') then
        dst:ApplyMesh(src)
    end
    dst.Size = src.Size
    for _, child in ipairs(dst:GetChildren()) do
        if
            (child:IsA('FaceControls') or child:IsA('Bone') or child:IsA('SurfaceAppearance'))
            and not src:FindFirstChild(child.Name)
        then
            child:Destroy()
        end
    end
    for _, child in ipairs(src:GetChildren()) do
        if child:IsA('Attachment') then
            local attachment = dst:FindFirstChild(child.Name)
            if attachment and not attachment:IsA('Attachment') then
                attachment = nil
            end
            if not attachment then
                attachment = child:Clone()
                attachment.Parent = dst
            end
            attachment.CFrame = child.CFrame
            local position = child:FindFirstChild('OriginalPosition')
            if position then
                local old = attachment:FindFirstChild('OriginalPosition')
                if old then
                    old:Destroy()
                end
                position:Clone().Parent = attachment
            end
        elseif
            child.Name == 'OriginalSize'
            or child.Name == 'AvatarPartScaleType'
            or child:IsA('WrapTarget')
            or child:IsA('FaceControls')
            or child:IsA('SpecialMesh')
            or child:IsA('Bone')
            or child:IsA('SurfaceAppearance')
            or child:IsA('Decal')
        then
            local old = dst:FindFirstChild(child.Name)
            if old then
                old:Destroy()
            end
            child:Clone().Parent = dst
        end
    end
end
function phowg:apply_spoof_body_scales(humanoid, description)
    if not humanoid then
        return
    end
    for name, property in pairs({
        BodyWidthScale = 'WidthScale',
        BodyDepthScale = 'DepthScale',
        BodyHeightScale = 'HeightScale',
        HeadScale = 'HeadScale',
    }) do
        local scale, value = humanoid:FindFirstChild(name), tonumber(description[property])
        if scale and scale:IsA('NumberValue') and value and value > 0 and scale.Value ~= value then
            scale.Value = value
        end
    end
end
function phowg:spoof_reference_rig(char, allowFetch)
    local snapshot = Data.AvatarSpoof
    local humanoid = char:FindFirstChildOfClass('Humanoid')
    if not snapshot or not humanoid then
        return nil
    end
    if snapshot.ReferenceRig and snapshot.ReferenceRigType == humanoid.RigType then
        return snapshot.ReferenceRig
    end
    if not allowFetch or snapshot.ReferenceFailed then
        return nil
    end
    local ok, rig = pcall(function()
        return Players:CreateHumanoidModelFromDescriptionAsync(snapshot.Desc, humanoid.RigType)
    end)
    if Data.AvatarSpoof ~= snapshot or LocalPlayer.Character ~= char then
        if ok and rig then
            rig:Destroy()
        end
        return nil
    end
    if not ok or not rig then
        snapshot.ReferenceFailed = true
        return nil
    end
    phowg:apply_spoof_body_scales(rig:FindFirstChildOfClass('Humanoid'), snapshot.Desc)
    if snapshot.ReferenceRig then
        snapshot.ReferenceRig:Destroy()
    end
    snapshot.ReferenceRig, snapshot.ReferenceRigType = rig, humanoid.RigType
    phowg:queue_asset_tree(rig)
    return rig
end
function phowg:copy_spoof_rig_body(char, rig)
    local humanoid, sourceHumanoid = char:FindFirstChildOfClass('Humanoid'), rig:FindFirstChildOfClass('Humanoid')
    if humanoid and sourceHumanoid then
        for _, name in ipairs({
            'BodyWidthScale',
            'BodyDepthScale',
            'BodyHeightScale',
            'HeadScale',
            'BodyTypeScale',
            'BodyProportionScale',
        }) do
            local dst, src = humanoid:FindFirstChild(name), sourceHumanoid:FindFirstChild(name)
            if dst and src then
                dst.Value = src.Value
            end
        end
    end
    for _, src in ipairs(rig:GetChildren()) do
        local dst = char:FindFirstChild(src.Name)
        if src:IsA('BasePart') and src.Name ~= 'HumanoidRootPart' and dst and dst:IsA('BasePart') then
            phowg:copy_spoof_body_part(dst, src)
        end
    end
    for _, joint in ipairs(char:GetDescendants()) do
        if
            joint:IsA('Motor6D')
            and joint.Part0
            and joint.Part1
            and joint.Part0.Parent == char
            and joint.Part1.Parent == char
        then
            local sourcePart = rig:FindFirstChild(joint.Parent.Name)
            local source = sourcePart and sourcePart:FindFirstChild(joint.Name)
            if
                source
                and source:IsA('Motor6D')
                and source.Part0
                and source.Part1
                and source.Part0.Name == joint.Part0.Name
                and source.Part1.Name == joint.Part1.Name
            then
                joint.C0, joint.C1 = source.C0, source.C1
            end
        end
    end
end
function phowg:copy_spoof_rig_accessories(char, rig)
    for _, child in ipairs(char:GetChildren()) do
        if child:IsA('Accessory') then
            child:Destroy()
        end
    end
    for _, source in ipairs(rig:GetChildren()) do
        if source:IsA('Accessory') then
            local clone = source:Clone()
            clone.Name = 'spoofacc_' .. source.Name
            for _, descendant in ipairs(clone:GetDescendants()) do
                if descendant:IsA('BasePart') then
                    descendant.CanCollide, descendant.CanTouch, descendant.CanQuery, descendant.Massless =
                        false, false, false, true
                end
                if descendant:IsA('JointInstance') then
                    for _, property in ipairs({ 'Part0', 'Part1' }) do
                        local part = descendant[property]
                        if part and not part:IsDescendantOf(clone) then
                            descendant[property] = char:FindFirstChild(part.Name)
                        end
                    end
                end
            end
            local handle = clone:FindFirstChild('Handle')
            local attached = false
            if handle then
                for _, weld in ipairs(handle:GetChildren()) do
                    if
                        weld:IsA('JointInstance')
                        and (
                            weld.Part0 == handle and weld.Part1 and weld.Part1.Parent == char
                            or weld.Part1 == handle and weld.Part0 and weld.Part0.Parent == char
                        )
                    then
                        local body = weld.Part0 == handle and weld.Part1 or weld.Part0
                        handle.CFrame = weld.Part1 == handle and body.CFrame * weld.C0 * weld.C1:Inverse()
                            or body.CFrame * weld.C1 * weld.C0:Inverse()
                        handle.AssemblyLinearVelocity, handle.AssemblyAngularVelocity = Vector3.zero, Vector3.zero
                        attached = true
                        break
                    end
                end
            end
            if attached then
                clone.Parent = char
            elseif not phowg:attach_spoof_accessory(clone, char) then
                clone:Destroy()
            end
        end
    end
end
function phowg:copy_spoof_rig_appearance(char, rig)
    for _, child in ipairs(char:GetChildren()) do
        if child:IsA('Shirt') or child:IsA('Pants') or child:IsA('ShirtGraphic') or child:IsA('BodyColors') then
            child:Destroy()
        end
    end
    for _, child in ipairs(rig:GetChildren()) do
        if child:IsA('Shirt') or child:IsA('Pants') or child:IsA('ShirtGraphic') or child:IsA('BodyColors') then
            child:Clone().Parent = char
        end
    end
    phowg:copy_spoof_rig_accessories(char, rig)
end
function applyspoofbodyparts(char, desc, allowFetch, skipDescription)
    if not char or not desc then
        return false
    end
    if allowFetch == nil then
        allowFetch = true
    end
    local hum = char:FindFirstChildOfClass('Humanoid')
    if hum and not skipDescription then
        local ok = pcall(function()
            hum:ApplyDescription(desc)
        end)
        if ok then
            if Data['AvatarSpoof'] then
                Data['AvatarSpoof'].HeadSwapped = true
            end
            return true
        end
    end
    local rig = phowg:spoof_reference_rig(char, allowFetch)
    if rig then
        phowg:copy_spoof_rig_body(char, rig)
        Data.AvatarSpoof.HeadSwapped = true
        return true
    end
    Data['SpoofPartCache'] = Data['SpoofPartCache'] or {}
    Data['SpoofPartFail'] = Data['SpoofPartFail'] or {}
    local groups = {
        { prop = 'Head', parts = { 'Head' } },
        { prop = 'Torso', parts = { 'UpperTorso', 'LowerTorso', 'Torso' } },
        { prop = 'LeftArm', parts = { 'LeftUpperArm', 'LeftLowerArm', 'LeftHand', 'Left Arm' } },
        { prop = 'RightArm', parts = { 'RightUpperArm', 'RightLowerArm', 'RightHand', 'Right Arm' } },
        { prop = 'LeftLeg', parts = { 'LeftUpperLeg', 'LeftLowerLeg', 'LeftFoot', 'Left Leg' } },
        { prop = 'RightLeg', parts = { 'RightUpperLeg', 'RightLowerLeg', 'RightFoot', 'Right Leg' } },
    }
    local changed, headSwapped = false, false
    for _, g in ipairs(groups) do
        local pid = desc[g.prop]
        if pid and pid ~= 0 then
            local cached = Data['SpoofPartCache'][pid]
            local ok, objs = false, nil
            if cached then
                ok, objs = true, cached
            elseif not allowFetch then
                ok, objs = false, nil
            elseif Data['SpoofPartFail'][pid] then
                ok, objs = false, nil
            else
                ok, objs = pcall(function()
                    return game:GetObjects('rbxassetid://' .. tostring(pid))
                end)
                if ok and objs and #objs > 0 then
                    local srcParts = {}
                    for _, o in ipairs(objs) do
                        if o:IsA('BasePart') then
                            table.insert(srcParts, o)
                        end
                        for _, d in ipairs(o:GetDescendants()) do
                            if d:IsA('BasePart') then
                                table.insert(srcParts, d)
                            end
                        end
                    end
                    if #srcParts > 0 then
                        Data['SpoofPartCache'][pid] = objs
                    else
                        Data['SpoofPartFail'][pid] = true
                        ok = false
                    end
                else
                    Data['SpoofPartFail'][pid] = true
                end
            end
            if ok and objs and #objs > 0 then
                local srcParts = {}
                for _, o in ipairs(objs) do
                    if o:IsA('BasePart') then
                        table.insert(srcParts, o)
                    end
                    for _, d in ipairs(o:GetDescendants()) do
                        if d:IsA('BasePart') then
                            table.insert(srcParts, d)
                        end
                    end
                end
                for _, pname in ipairs(g.parts) do
                    local dst = char:FindFirstChild(pname)
                    if dst and dst:IsA('BasePart') and #srcParts > 0 then
                        local src = nil
                        for _, s in ipairs(srcParts) do
                            if s.Name == pname then
                                src = s
                                break
                            end
                        end
                        if not src then
                            continue
                        end
                        local didMesh = src:IsA('MeshPart') and dst:IsA('MeshPart')
                        phowg:copy_spoof_body_part(dst, src)
                        if didMesh then
                            changed = true
                            if pname == 'Head' then
                                headSwapped = true
                            end
                        end
                    end
                end
            end
        end
    end
    if Data['AvatarSpoof'] then
        Data['AvatarSpoof'].HeadSwapped = headSwapped
    end
    local hum2 = char:FindFirstChildOfClass('Humanoid')
    if hum2 and desc then
        pcall(function()
            if hum2:FindFirstChild('BodyHeightScale') then
                hum2.BodyHeightScale.Value = desc.HeightScale
            end
            if hum2:FindFirstChild('BodyWidthScale') then
                hum2.BodyWidthScale.Value = desc.WidthScale
            end
            if hum2:FindFirstChild('BodyDepthScale') then
                hum2.BodyDepthScale.Value = desc.DepthScale
            end
            if hum2:FindFirstChild('HeadScale') then
                hum2.HeadScale.Value = desc.HeadScale
            end
            if hum2:FindFirstChild('BodyTypeScale') then
                hum2.BodyTypeScale.Value = desc.BodyTypeScale
            end
            if hum2:FindFirstChild('BodyProportionScale') then
                hum2.BodyProportionScale.Value = desc.ProportionScale
            end
        end)
    end
    if hum2 and hum2.AutomaticScalingEnabled then
        local width = hum2:FindFirstChild('BodyWidthScale')
        if width then
            local value = width.Value
            width.Value = value + 0.0001
            width.Value = value
        end
    end
    for _, joint in ipairs(char:GetDescendants()) do
        if
            joint:IsA('Motor6D')
            and joint.Part0
            and joint.Part1
            and joint.Part0.Parent == char
            and joint.Part1.Parent == char
        then
            local name = joint.Name .. 'RigAttachment'
            local a0, a1 = joint.Part0:FindFirstChild(name), joint.Part1:FindFirstChild(name)
            if a0 and a1 and a0:IsA('Attachment') and a1:IsA('Attachment') then
                joint.C0, joint.C1 = a0.CFrame, a1.CFrame
            end
        end
    end
    return changed
end
function capturemyavatar(char)
    if not char then
        return
    end
    local hum = char:FindFirstChildOfClass('Humanoid')
    if not hum then
        return
    end
    if Data['AvatarSpoof'] and not Data['AvatarSpoof'].MyDesc then
        (function()
            Data['AvatarSpoof'].MyDesc = hum:GetAppliedDescription()
        end)()
    end
    local snapshot = Data.AvatarSpoof
    if snapshot and not snapshot.MyScales then
        snapshot.MyScales = {}
        for _, name in ipairs({
            'BodyWidthScale',
            'BodyDepthScale',
            'BodyHeightScale',
            'HeadScale',
            'BodyTypeScale',
            'BodyProportionScale',
        }) do
            local scale = hum:FindFirstChild(name)
            if scale and scale:IsA('NumberValue') then
                snapshot.MyScales[name] = scale.Value
            end
        end
    end
    if snapshot and not snapshot.MyAccessories then
        snapshot.MyAccessories = {}
        for _, child in ipairs(char:GetChildren()) do
            if child:IsA('Accessory') then
                local clone = child:Clone()
                if clone then
                    snapshot.MyAccessories[#snapshot.MyAccessories + 1] = clone
                end
            end
        end
    end
    if snapshot and not snapshot.My then
        local shirt, pants = char:FindFirstChildOfClass('Shirt'), char:FindFirstChildOfClass('Pants')
        local graphic = char:FindFirstChildOfClass('ShirtGraphic')
        local head = char:FindFirstChild('Head')
        local face = head and head:FindFirstChildOfClass('Decal')
        local colors = char:FindFirstChildOfClass('BodyColors')
        local saved = {
            ShirtX = shirt ~= nil,
            ShirtT = shirt and shirt.ShirtTemplate,
            PantsX = pants ~= nil,
            PantsT = pants and pants.PantsTemplate,
            GraphicX = graphic ~= nil,
            GraphicT = graphic and graphic.Graphic,
            FaceT = face and face.Texture,
            Colors = {},
        }
        if colors then
            for _, key in ipairs({
                'HeadColor3',
                'TorsoColor3',
                'LeftArmColor3',
                'RightArmColor3',
                'LeftLegColor3',
                'RightLegColor3',
            }) do
                saved.Colors[key] = colors[key]
            end
        end
        snapshot.My = saved
    end
    if snapshot and not snapshot.MyAnimations then
        snapshot.MyAnimations, snapshot.MyAnimationWeights = {}, {}
        local animate = char:FindFirstChild('Animate')
        local damping = animate and animate:FindFirstChild('ScaleDampeningPercent')
        snapshot.MyAnimationDamping = damping and damping.Value
        snapshot.MyAnimationDampingPresent = damping ~= nil
        if animate then
            for _, animation in ipairs(animate:GetDescendants()) do
                if animation:IsA('Animation') then
                    local key = animation.Parent.Name .. '/' .. animation.Name
                    snapshot.MyAnimations[key] = animation.AnimationId
                    local weight = animation:FindFirstChild('Weight')
                    if weight and weight:IsA('NumberValue') then
                        snapshot.MyAnimationWeights[key] = weight.Value
                    end
                end
            end
        end
    end
    if Data['AvatarSpoof'] and not Data['AvatarSpoof'].MyMeshes then
        local mm = {}
        (function()
            for _, pname in ipairs({
                'Head',
                'UpperTorso',
                'LowerTorso',
                'Torso',
                'LeftUpperArm',
                'LeftLowerArm',
                'LeftHand',
                'RightUpperArm',
                'RightLowerArm',
                'RightHand',
                'LeftUpperLeg',
                'LeftLowerLeg',
                'LeftFoot',
                'RightUpperLeg',
                'RightLowerLeg',
                'RightFoot',
                'Left Arm',
                'Right Arm',
                'Left Leg',
                'Right Leg',
            }) do
                local p = char:FindFirstChild(pname)
                if p and p:IsA('BasePart') then
                    local e = {}
                    e.Mesh = p:IsA('MeshPart') and p.MeshId or nil
                    e.Texture = p:IsA('MeshPart') and p.TextureID or nil
                    e.Size = p.Size
                    e.Part = p:Clone()
                    for _, child in ipairs(e.Part:GetChildren()) do
                        if
                            not (
                                child:IsA('Attachment')
                                or child.Name == 'OriginalSize'
                                or child.Name == 'AvatarPartScaleType'
                                or child:IsA('WrapTarget')
                                or child:IsA('FaceControls')
                                or child:IsA('SpecialMesh')
                                or child:IsA('Bone')
                                or child:IsA('SurfaceAppearance')
                                or child:IsA('Decal')
                            )
                        then
                            child:Destroy()
                        end
                    end
                    e.Part.Parent = nil
                    mm[pname] = e
                end
            end
        end)()
        Data['AvatarSpoof'].MyMeshes = mm
        snapshot.MyJoints = {}
        for _, joint in ipairs(char:GetDescendants()) do
            if
                joint:IsA('Motor6D')
                and joint.Part0
                and joint.Part1
                and joint.Part0.Parent == char
                and joint.Part1.Parent == char
            then
                snapshot.MyJoints[#snapshot.MyJoints + 1] = {
                    Parent = joint.Parent.Name,
                    Name = joint.Name,
                    Part0 = joint.Part0.Name,
                    Part1 = joint.Part1.Name,
                    C0 = joint.C0,
                    C1 = joint.C1,
                }
            end
        end
    end
end
function applyavatarspooffallback(char, allowFetch)
    local reference = Data.AvatarSpoof and Data.AvatarSpoof.ReferenceRig
    if reference and char and char.Parent then
        phowg:copy_spoof_rig_appearance(char, reference)
        return
    end
    if not char or not char.Parent or not Data['AvatarSpoof'] or not Data['AvatarSpoof'].Desc then
        return
    end
    if allowFetch == nil then
        allowFetch = true
    end
    Data['SpoofShirtCache'] = Data['SpoofShirtCache'] or {}
    Data['SpoofPantsCache'] = Data['SpoofPantsCache'] or {}
    Data['SpoofFaceCache'] = Data['SpoofFaceCache'] or {}
    Data['SpoofAccObjCache'] = Data['SpoofAccObjCache'] or {}
    Data['SpoofAccFail'] = Data['SpoofAccFail'] or {}
    local hum = char:FindFirstChildOfClass('Humanoid')
    if not char.Parent then
        return
    end
    for _, c in ipairs(char:GetChildren()) do
        if c:IsA('Accessory') then
            c:Destroy()
        end
    end
    local desc = Data['AvatarSpoof'].Desc
    local savedSnap = Data['AvatarSpoof']
    if desc.Shirt and desc.Shirt ~= 0 then
        local template = Data['SpoofShirtCache'][desc.Shirt] or savedSnap.ShirtT
        if not template and allowFetch then
            local ok, objs = pcall(function()
                return game:GetObjects('rbxassetid://' .. tostring(desc.Shirt))
            end)
            local s = ok and objs and objs[1] or nil
            if s and s:IsA('Shirt') and s.ShirtTemplate ~= '' then
                template = s.ShirtTemplate
                Data['SpoofShirtCache'][desc.Shirt] = template
                savedSnap.ShirtT = template
            end
        end
        if template and template ~= '' then
            local shirt = char:FindFirstChildOfClass('Shirt')
            if not shirt then
                shirt = Instance.new('Shirt')
                shirt.Parent = char
            end
            shirt.ShirtTemplate = template
        end
    else
        local shirt = char:FindFirstChildOfClass('Shirt')
        if shirt then
            shirt.ShirtTemplate = ''
        end
    end
    if desc.Pants and desc.Pants ~= 0 then
        local template = Data['SpoofPantsCache'][desc.Pants] or savedSnap.PantsT
        if not template and allowFetch then
            local ok, objs = pcall(function()
                return game:GetObjects('rbxassetid://' .. tostring(desc.Pants))
            end)
            local p = ok and objs and objs[1] or nil
            if p and p:IsA('Pants') and p.PantsTemplate ~= '' then
                template = p.PantsTemplate
                Data['SpoofPantsCache'][desc.Pants] = template
                savedSnap.PantsT = template
            end
        end
        if template and template ~= '' then
            local pants = char:FindFirstChildOfClass('Pants')
            if not pants then
                pants = Instance.new('Pants')
                pants.Parent = char
            end
            pants.PantsTemplate = template
        end
    else
        local pants = char:FindFirstChildOfClass('Pants')
        if pants then
            pants.PantsTemplate = ''
        end
    end
    local spoofHead = char:FindFirstChild('Head')
    if desc.Face and desc.Face ~= 0 and not (spoofHead and spoofHead:FindFirstChildOfClass('FaceControls')) then
        local texture = Data['SpoofFaceCache'][desc.Face] or savedSnap.FaceT
        if not texture and allowFetch then
            local ok, objs = pcall(function()
                return game:GetObjects('rbxassetid://' .. tostring(desc.Face))
            end)
            local f = ok and objs and objs[1] or nil
            if f and f:IsA('Decal') and f.Texture ~= '' then
                texture = f.Texture
                Data['SpoofFaceCache'][desc.Face] = texture
                savedSnap.FaceT = texture
            end
        end
        if texture and texture ~= '' then
            local head = char:FindFirstChild('Head')
            local face = head and head:FindFirstChildOfClass('Decal')
            if face then
                face.Texture = texture
            end
        end
    end
    local bc = char:FindFirstChildOfClass('BodyColors')
    if bc then
        bc.HeadColor3 = desc.HeadColor
        bc.TorsoColor3 = desc.TorsoColor
        bc.LeftArmColor3 = desc.LeftArmColor
        bc.RightArmColor3 = desc.RightArmColor
        bc.LeftLegColor3 = desc.LeftLegColor
        bc.RightLegColor3 = desc.RightLegColor
    end
    local accessoryReference = savedSnap.ReferenceRig
    if accessoryReference then
        phowg:copy_spoof_rig_accessories(char, accessoryReference)
        return
    end
    local accs, layered = savedSnap.AccList, savedSnap.LayeredList
    if not accs or not layered then
        accs, layered = {}, {}
        pcall(function()
            accs, layered = collectspoofaccs(desc)
        end)
        savedSnap.AccList = accs
        savedSnap.LayeredList = layered
    end
    for _, aid in ipairs(accs) do
        if not char.Parent then
            return
        end
        if not char:FindFirstChild('spoofacc_' .. tostring(aid)) then
            local numAid = tonumber(aid)
            if numAid then
                if Data['SpoofAccObjCache'][numAid] then
                    createattachment(numAid, 'spoofacc_' .. tostring(aid), char)
                elseif allowFetch then
                    createattachment(numAid, 'spoofacc_' .. tostring(aid), char)
                end
            end
        end
    end
    if not char.Parent then
        return
    end
    hum = char:FindFirstChildOfClass('Humanoid')
    if hum then
        for _, aid in ipairs(layered) do
            if not char:FindFirstChild('spoofacc_' .. tostring(aid)) then
                local numAid = tonumber(aid)
                local cachedAcc = numAid and Data['SpoofAccObjCache'][numAid] or nil
                if cachedAcc then
                    local clone = cachedAcc:Clone()
                    clone.Name = 'spoofacc_' .. tostring(aid)
                    if not phowg:attach_spoof_accessory(clone, char, true) then
                        clone:Destroy()
                    end
                elseif allowFetch and numAid and not Data['SpoofAccFail'][numAid] then
                    local ok, objs = pcall(function()
                        return game:GetObjects('rbxassetid://' .. tostring(aid))
                    end)
                    local acc = ok and objs and objs[1] or nil
                    if acc then
                        Data['SpoofAccObjCache'][numAid] = acc
                        local clone2 = acc:Clone()
                        clone2.Name = 'spoofacc_' .. tostring(aid)
                        if not phowg:attach_spoof_accessory(clone2, char, true) then
                            clone2:Destroy()
                        end
                    else
                        Data['SpoofAccFail'][numAid] = true
                    end
                end
            end
        end
    end
end
function phowg:avatar_presets()
    if Data.AvatarPresets then
        return Data.AvatarPresets
    end
    local archive = { Revision = 1, Presets = {} }
    if readfile and isfile then
        local ok, result = pcall(function()
            local path = 'PhowgHosted/DaHood/avatar-presets.json'
            if isfile(path) then
                return HttpService:JSONDecode(readfile(path))
            end
            return nil
        end)
        if ok and type(result) == 'table' and result.Revision == 1 and type(result.Presets) == 'table' then
            archive = result
        end
    end
    Data.AvatarPresets = archive
    return archive
end
function phowg:write_avatar_presets(archive)
    if not writefile or not makefolder or not isfolder then
        return false, 'Preset storage is unavailable'
    end
    local ok, err = pcall(function()
        if not isfolder('PhowgHosted') then
            makefolder('PhowgHosted')
        end
        if not isfolder('PhowgHosted/DaHood') then
            makefolder('PhowgHosted/DaHood')
        end
        writefile('PhowgHosted/DaHood/avatar-presets.json', HttpService:JSONEncode(archive))
    end)
    if ok then
        Data.AvatarPresets = archive
        return true, nil
    end
    return false, tostring(err)
end
function phowg:save_avatar_preset(name, editor)
    name = tostring(name or ''):match('^%s*(.-)%s*$')
    if name == '' or #name > 64 then
        return false, 'Enter a preset name (1Ã¢â‚¬â€œ64 characters)'
    end
    local snapshot = editor.Snapshot
    local source = snapshot.BaseDesc or snapshot.Desc
    local entry = {
        UserId = snapshot.UserId,
        Properties = {},
        Colors = {},
        Accessories = {},
        Details = table.clone(editor.Edits.Details),
        Edits = {},
    }
    for _, property in ipairs(phowg:avatar_description_properties()) do
        local ok, value = pcall(function()
            return source[property]
        end)
        if ok and (type(value) == 'number' or type(value) == 'string') then
            entry.Properties[property] = value
        end
    end
    for _, property in ipairs({
        'HeadColor',
        'TorsoColor',
        'LeftArmColor',
        'RightArmColor',
        'LeftLegColor',
        'RightLegColor',
    }) do
        local color = source[property]
        entry.Colors[property] = { color.R, color.G, color.B }
    end
    for _, accessory in ipairs(source:GetAccessories(true)) do
        entry.Accessories[#entry.Accessories + 1] = {
            AssetId = accessory.AssetId,
            AccessoryType = accessory.AccessoryType.Name,
            IsLayered = accessory.IsLayered,
            Order = accessory.Order,
            Puffiness = accessory.Puffiness,
        }
    end
    entry.Emotes, entry.EquippedEmotes = source:GetEmotes(), source:GetEquippedEmotes()
    for id, edit in pairs(editor.Edits.Accessories) do
        entry.Edits[id] = {
            Enabled = edit.Enabled,
            Position = { edit.Position.X, edit.Position.Y, edit.Position.Z },
            Rotation = { edit.Rotation.X, edit.Rotation.Y, edit.Rotation.Z },
            Scale = { edit.Scale.X, edit.Scale.Y, edit.Scale.Z },
        }
    end
    local archive = phowg:avatar_presets()
    local copy = { Revision = 1, Presets = table.clone(archive.Presets) }
    copy.Presets[name] = entry
    return phowg:write_avatar_presets(copy)
end
function phowg:decode_avatar_preset(entry)
    if type(entry) ~= 'table' or type(entry.Properties) ~= 'table' or type(entry.Accessories) ~= 'table' then
        return nil
    end
    local description = Instance.new('HumanoidDescription')
    local edits = { Details = {}, Accessories = {} }
    local ok = pcall(function()
        for _, property in ipairs(phowg:avatar_description_properties()) do
            local value = entry.Properties[property]
            if type(value) == 'number' or type(value) == 'string' then
                description[property] = value
            end
        end
        for _, property in ipairs({
            'HeadColor',
            'TorsoColor',
            'LeftArmColor',
            'RightArmColor',
            'LeftLegColor',
            'RightLegColor',
        }) do
            local color = entry.Colors[property]
            description[property] = Color3.new(color[1], color[2], color[3])
        end
        local accessories = {}
        for _, item in ipairs(entry.Accessories) do
            local kind = Enum.AccessoryType[item.AccessoryType]
            if not kind or type(item.AssetId) ~= 'number' or item.AssetId <= 0 then
                error('Invalid accessory')
            end
            accessories[#accessories + 1] = {
                AssetId = item.AssetId,
                AccessoryType = kind,
                IsLayered = item.IsLayered,
                Order = item.Order,
                Puffiness = item.Puffiness,
            }
        end
        description:SetAccessories(accessories, true)
        description:SetEmotes(entry.Emotes or {})
        description:SetEquippedEmotes(entry.EquippedEmotes or {})
        for property, value in pairs(entry.Details or {}) do
            if type(value) == 'boolean' then
                edits.Details[property] = value
            end
        end
        local function vector(values, min, max, fallback)
            if values == nil then
                return fallback
            end
            if type(values) ~= 'table' then
                error('Invalid adjustment')
            end
            local result = {}
            for i = 1, 3 do
                local v = values[i]
                if type(v) ~= 'number' or v ~= v or v < min or v > max then
                    error('Invalid adjustment')
                end
                result[i] = v
            end
            return Vector3.new(result[1], result[2], result[3])
        end
        for id, item in pairs(entry.Edits or {}) do
            edits.Accessories[id] = {
                Enabled = item.Enabled ~= false,
                Position = vector(item.Position, -5, 5, Vector3.zero),
                Rotation = vector(item.Rotation, -180, 180, Vector3.zero),
                Scale = vector(item.Scale, 0.1, 3, Vector3.one),
            }
        end
    end)
    if not ok then
        description:Destroy()
        return nil
    end
    return description, edits
end
function phowg:load_avatar_preset(name)
    if
        Data.SpoofBusy
        or Data.AvatarRestoreBusy
        or Data.AvatarApplyJobs and Data.AvatarApplyJobs[LocalPlayer.Character]
    then
        return false, 'Wait for the current avatar update'
    end
    local entry = phowg:avatar_presets().Presets[name]
    local description, edits = phowg:decode_avatar_preset(entry)
    if not description then
        return false, 'Preset is missing or invalid'
    end
    local old = Data.AvatarSpoof
    if not old or not Toggles.avatar_spoof_enabled.Value then
        description:Destroy()
        return false, 'Enable avatar spoof first'
    end
    phowg:close_avatar_editor()
    phowg:stop_avatar_mood(old)
    local snapshot = { Desc = description, UserId = entry.UserId, Source = 'saved preset', Customization = edits }
    for _, key in ipairs({
        'My',
        'MyDesc',
        'MyMeshes',
        'MyAnimations',
        'MyAnimationWeights',
        'MyScales',
        'MyJoints',
        'MyAccessories',
        'MyAnimationDamping',
        'MyAnimationDampingPresent',
    }) do
        snapshot[key] = old[key]
    end
    Data.AvatarSpoof = snapshot
    for _, key in ipairs({ 'ReferenceRig', 'BaseDesc', 'Desc' }) do
        if old[key] then
            old[key]:Destroy()
        end
    end
    phowg:resolve_avatar_identity(snapshot)
    task.spawn(function()
        applyavatarspooftochar(LocalPlayer.Character, true)
        if Data.AvatarSpoof == snapshot and not Library.Unloaded then
            phowg:open_avatar_editor()
        end
    end)
    return true
end
function phowg:avatar_preview_animation(editor)
    local humanoid = editor.Rig and editor.Rig:FindFirstChildOfClass('Humanoid')
    if not humanoid then
        return
    end
    local animator = humanoid:FindFirstChildOfClass('Animator')
    if not animator then
        animator = Instance.new('Animator')
        animator.Parent = humanoid
    end
    local source = editor.PreviewIdleAnimation or 0
    if editor.Animator == animator and editor.Track and editor.AnimationSource == source then
        return
    end
    if editor.Track then
        pcall(function()
            editor.Track:Stop(0)
            editor.Track:Destroy()
        end)
        editor.Track = nil
    end
    if editor.Animation then
        editor.Animation:Destroy()
    end
    local animation = Instance.new('Animation')
    animation.AnimationId = humanoid.RigType == Enum.HumanoidRigType.R15 and 'rbxassetid://507766666'
        or 'rbxassetid://180435571'
    if source > 0 then
        local ids = phowg:avatar_animation_ids(source)
        if editor.Closed then
            animation:Destroy()
            return
        end
        animation.AnimationId = ids.Animation1 or ids.Idle or ids.First or animation.AnimationId
    end
    editor.AnimationSource = source
    editor.Animation, editor.Animator = animation, animator
    local ok, track = pcall(animator.LoadAnimation, animator, animation)
    if ok and track then
        editor.Track = track
        track.Looped, track.Priority = true, Enum.AnimationPriority.Idle
        pcall(track.Play, track, 0.2)
    end
end

function phowg:avatar_editor_description(snapshot, edits)
    local source = snapshot.BaseDesc or snapshot.Desc
    local desc = source:Clone()
    local original = snapshot.MyDesc
    for property, enabled in pairs(edits.Details) do
        if not enabled and original then
            pcall(function()
                desc[property] = original[property]
            end)
        end
    end
    if edits.Details.Emotes == false and original then
        desc:SetEmotes(original:GetEmotes())
        desc:SetEquippedEmotes(original:GetEquippedEmotes())
    end
    local accessories = {}
    for _, item in ipairs(source:GetAccessories(true)) do
        local edit = edits.Accessories[tostring(item.AssetId)]
        if not edit or edit.Enabled ~= false then
            accessories[#accessories + 1] = table.clone(item)
        end
    end
    desc:SetAccessories(accessories, true)
    for _, child in ipairs(desc:GetChildren()) do
        if child:IsA('AccessoryDescription') then
            local edit = edits.Accessories[tostring(child.AssetId)]
            if edit and not child.IsLayered then
                child.Position = edit.Position
                child.Rotation = edit.Rotation
                child.Scale = edit.Scale
            end
        end
    end
    return desc
end
function phowg:close_avatar_editor()
    local editor = Data.AvatarEditor
    if not editor then
        return
    end
    Data.AvatarEditor = nil
    editor.Closed = true
    for _, connection in ipairs(editor.Connections) do
        connection:Disconnect()
    end
    if editor.Tween then
        editor.Tween:Cancel()
    end
    if editor.Track then
        pcall(function()
            editor.Track:Stop(0)
            editor.Track:Destroy()
        end)
    end
    if editor.Animation then
        editor.Animation:Destroy()
    end
    if editor.Draft then
        editor.Draft:Destroy()
    end
    if editor.PreviewTween then
        editor.PreviewTween:Cancel()
    end
    if editor.PreviewFrame then
        editor.PreviewFrame:Destroy()
    end
    if editor.Frame then
        editor.Frame:Destroy()
    end
end
function phowg:avatar_preview_fit(size, fieldOfView, aspect, angle, pitch)
    local tangent = math.tan(math.rad(math.clamp(fieldOfView, 20, 70)) * 0.5)
    local horizontal = (math.abs(math.cos(angle)) * size.X + math.abs(math.sin(angle)) * size.Z) * 0.5
    local depth = (math.abs(math.sin(angle)) * size.X + math.abs(math.cos(angle)) * size.Z) * 0.5
    local height = size.Y * 0.5
    local projectedHeight = height * math.abs(math.cos(pitch)) + depth * math.abs(math.sin(pitch))
    local projectedDepth = depth * math.abs(math.cos(pitch)) + height * math.abs(math.sin(pitch))
    return math.max(
        2,
        (math.max(projectedHeight / tangent, horizontal / (tangent * math.max(aspect, 0.2))) + projectedDepth) * 1.12
    )
end
function phowg:update_avatar_stage(editor, center, size)
    local stage = editor.Stage
    if not stage then
        stage = Instance.new('Part')
        stage.Name = 'PreviewStage'
        stage.Anchored, stage.CanCollide, stage.CanTouch, stage.CanQuery = true, false, false, false
        stage.Material = Enum.Material.SmoothPlastic
        stage.Color = Color3.fromRGB(37, 39, 46)
        stage.Parent = editor.World
        editor.Stage = stage
    end
    stage.Size = Vector3.new(math.max(4, size.X * 1.3), 0.08, math.max(4, size.Z * 1.3))
    stage.CFrame = CFrame.new(center.X, center.Y - size.Y * 0.5 - 0.06, center.Z)
end
function phowg:avatar_editor_preview(editor)
    if editor.Closed or Data.AvatarSpoof ~= editor.Snapshot then
        return
    end
    editor.Revision += 1
    if editor.Working then
        return
    end
    editor.Working = true
    task.spawn(function()
        while not editor.Closed and Data.AvatarSpoof == editor.Snapshot do
            local version = editor.Revision
            task.wait(0.2)
            if editor.Closed or Data.AvatarSpoof ~= editor.Snapshot then
                break
            end
            if version ~= editor.Revision then
                continue
            end
            local preview = table.clone(editor.Snapshot)
            preview.Desc, preview.ScalesPrepared, preview.Customization =
                (preview.BaseDesc or preview.Desc):Clone(), nil, editor.Edits
            phowg:prepare_avatar_spoof(preview)
            local description = preview.Desc
            local ok, result = pcall(function()
                if editor.Rig then
                    local humanoid = editor.Rig:FindFirstChildOfClass('Humanoid')
                    humanoid:ApplyDescriptionAsync(description)
                    return editor.Rig
                end
                local character = LocalPlayer.Character
                local humanoid = character and character:FindFirstChildOfClass('Humanoid')
                return Players:CreateHumanoidModelFromDescriptionAsync(
                    description,
                    humanoid and humanoid.RigType or Enum.HumanoidRigType.R6
                )
            end)
            editor.PreviewIdleAnimation = description.IdleAnimation
            description:Destroy()
            if editor.Closed or Data.AvatarSpoof ~= editor.Snapshot then
                if ok and result then
                    result:Destroy()
                end
                break
            end
            if ok and result then
                editor.Rig = result
                for _, descendant in ipairs(result:GetDescendants()) do
                    if descendant:IsA('BasePart') then
                        descendant.CanCollide = false
                    end
                    if descendant:IsA('Script') or descendant:IsA('LocalScript') then
                        descendant:Destroy()
                    end
                end
                local root = result:FindFirstChild('HumanoidRootPart')
                if root then
                    root.Anchored = true
                end
                result.Parent = editor.World
                result:PivotTo(CFrame.new())
                local center, size = Library:VisiblePreviewBounds(result)
                if not center then
                    local cf
                    cf, size = result:GetBoundingBox()
                    center = cf.Position
                end
                editor.Center, editor.BoundsSize = center, size
                local head = result:FindFirstChild('Head')
                editor.HeadCenter = head and head.Position or center + Vector3.new(0, size.Y * 0.3, 0)
                editor.HeadSize = head and head.Size or Vector3.new(2, 1, 1)
                phowg:update_avatar_stage(editor, center, size)
                editor.UpdateCamera()
                phowg:avatar_preview_animation(editor)
                editor.Status.Text = 'preview Ã‚Â· changes are staged until apply'
            else
                editor.Status.Text = 'preview unavailable Ã‚Â· you can still edit and apply'
            end
            if version == editor.Revision then
                break
            end
        end
        editor.Working = false
    end)
end
function phowg:open_avatar_editor()
    local snapshot = Data.AvatarSpoof
    if not snapshot or not snapshot.Desc then
        Library:Notify('Load a spoof avatar first', 3)
        return
    end
    phowg:close_avatar_editor()
    phowg:prepare_avatar_spoof(snapshot)
    local editor = {
        Snapshot = snapshot,
        Connections = {},
        Edits = { Details = {}, Accessories = {} },
        Closed = false,
        Working = false,
        Center = Vector3.zero,
        HeadCenter = Vector3.zero,
        HeadSize = Vector3.new(2, 1, 1),
        BoundsSize = Vector3.new(4, 6, 3),
        Distance = 12,
        Revision = 0,
        Angle = math.pi,
        Pitch = math.rad(4),
        Zoom = 1,
        View = 'body',
        AutoRotate = false,
        UpdateCamera = function() end,
    }
    Data.AvatarEditor = editor
    local source = snapshot.BaseDesc or snapshot.Desc
    local saved = snapshot.Customization
    for property, value in pairs(saved and saved.Details or {}) do
        editor.Edits.Details[property] = value
    end
    local entries = {}
    for _, item in ipairs(source:GetAccessories(true)) do
        local id = tostring(item.AssetId)
        local prior = saved and saved.Accessories[id]
        local edit = {
            Enabled = not prior or prior.Enabled ~= false,
            Position = Vector3.zero,
            Rotation = Vector3.zero,
            Scale = Vector3.one,
        }
        if prior then
            edit.Position, edit.Rotation, edit.Scale = prior.Position, prior.Rotation, prior.Scale
        else
            for _, child in ipairs(source:GetChildren()) do
                if child:IsA('AccessoryDescription') and child.AssetId == item.AssetId then
                    edit.Position, edit.Rotation, edit.Scale = child.Position, child.Rotation, child.Scale
                    break
                end
            end
        end
        editor.Edits.Accessories[id] = edit
        entries[#entries + 1] =
            { Id = id, Name = item.AccessoryType.Name .. ' Ã‚Â· ' .. id, Layered = item.IsLayered == true }
    end
    local function ui(class, parent, properties)
        properties.Parent = parent
        if class == 'TextButton' or class == 'TextLabel' or class == 'TextBox' then
            properties.Font = Library.Font
            properties.TextSize = properties.TextSize or 14
            properties.TextColor3 = Library.FontColor
        end
        local object = Library:Create(class, properties)
        if object:IsA('GuiObject') then
            object.ZIndex = 701
        end
        return object
    end
    local function on(signal, callback)
        local connection = connectshared(signal, function(...)
            if not editor.Closed then
                callback(...)
            end
        end, editor, 'avatar editor')
