    editor.UpdateCamera = function()
        local portrait = editor.View == 'portrait'
        local center = portrait and editor.HeadCenter or editor.Center or Vector3.zero
        local size = portrait and (editor.HeadSize or Vector3.new(2, 1, 1)) * Vector3.new(2.2, 2.8, 2.2)
            or editor.BoundsSize
            or Vector3.new(4, 6, 3)
        local pixels = viewport.AbsoluteSize
        local aspect = pixels.Y > 0 and pixels.X / pixels.Y or 392 / 500
        local pitch = editor.Pitch or 0
        local distance = phowg:avatar_preview_fit(size, camera.FieldOfView, aspect, editor.Angle, pitch) * editor.Zoom
        local direction = Vector3.new(
            math.sin(editor.Angle) * math.cos(pitch),
            math.sin(pitch),
            math.cos(editor.Angle) * math.cos(pitch)
        )
        camera.CFrame = CFrame.lookAt(center + direction * distance, center)
        editor.Distance = distance
    end
