    local fields: { any } = {}
    local updating
    local dragField: any = nil
    local function select_entry(entry)
        editor.Selected = entry
        selectedLabel.Text = entry.Name
            .. (entry.Layered and '\nLayered Ã‚Â· fitting stays automatic' or '\nRigid accessory')
        updating = true
        local edit = editor.Edits.Accessories[entry.Id]
        for _, field in ipairs(fields) do
            local value = field.Axis == 'All' and edit[field.Property].X or edit[field.Property][field.Axis]
            field.Box.Text = string.format(field.Property == 'Rotation' and '%.0f' or '%.2f', value)
            field.Box.TextEditable = not entry.Layered
            field.Box.TextTransparency = entry.Layered and 0.6 or 0
            local ratio = math.clamp((value - field.Min) / (field.Max - field.Min), 0, 1)
            field.Fill.Size = UDim2.fromScale(ratio, 1)
            field.Thumb.Position = UDim2.fromScale(ratio, 0.5)
            field.Fill.BackgroundTransparency = entry.Layered and 0.7 or 0
            field.Thumb.BackgroundTransparency = entry.Layered and 0.7 or 0
        end
        updating = nil
    end
    for _, group in ipairs({
        { Name = 'scale', Property = 'Scale', Min = 0.1, Max = 3, Step = 0.01 },
        { Name = 'move', Property = 'Position', Min = -5, Max = 5, Step = 0.01 },
        { Name = 'rotate', Property = 'Rotation', Min = -180, Max = 180, Step = 1 },
    }) do
        for _, axis in ipairs(group.Property == 'Scale' and { 'All' } or { 'X', 'Y', 'Z' }) do
            local y = 48 + #fields * 34
            ui('TextLabel', controls, {
                Text = axis == 'All' and group.Name or group.Name .. ' ' .. axis:lower(),
                Position = UDim2.fromOffset(8, y),
                Size = UDim2.fromOffset(140, 18),
                BackgroundTransparency = 1,
                TextXAlignment = Enum.TextXAlignment.Left,
            })
            local box = ui('TextBox', controls, {
                Text = '',
                Position = UDim2.fromOffset(176, y),
                Size = UDim2.fromOffset(48, 18),
                BackgroundTransparency = 1,
                BorderSizePixel = 0,
                ClearTextOnFocus = false,
