            })
            local track = ui('TextButton', controls, {
                Name = 'AvatarAdjustmentSlider',
                Text = '',
                Position = UDim2.fromOffset(8, y + 18),
                Size = UDim2.fromOffset(216, 14),
                BackgroundTransparency = 1,
                BorderSizePixel = 0,
                AutoButtonColor = false,
                Active = true,
            })
            local rail = ui('Frame', track, {
                Position = UDim2.fromOffset(0, 5),
                Size = UDim2.new(1, 0, 0, 4),
                BackgroundColor3 = Library.MainColor,
                BorderSizePixel = 0,
            })
            local fill = ui(
                'Frame',
                rail,
                { Size = UDim2.fromScale(0, 1), BackgroundColor3 = Library.AccentColor, BorderSizePixel = 0 }
            )
            local thumb = ui('Frame', rail, {
                AnchorPoint = Vector2.new(0.5, 0.5),
                Position = UDim2.fromScale(0, 0.5),
                Size = UDim2.fromOffset(10, 10),
                BackgroundColor3 = Library.FontColor,
                BorderSizePixel = 0,
            })
            Library:Create('UICorner', { CornerRadius = UDim.new(0, 0), Parent = rail })
            Library:Create('UICorner', { CornerRadius = UDim.new(0, 0), Parent = fill })
            Library:Create('UICorner', { CornerRadius = UDim.new(0, 0), Parent = thumb })
            local field = {
                Box = box,
                Property = group.Property,
                Axis = axis,
                Min = group.Min,
                Max = group.Max,
                Fill = fill,
                Thumb = thumb,
                Track = track,
            }
            fields[#fields + 1] = field
            local function change(value)
                local entry = editor.Selected
                if updating or not entry or entry.Layered then
                    return
                end
                value = value or tonumber(box.Text)
                if not value or value ~= value then
                    select_entry(entry)
                    return
                end
                value = math.clamp(value, group.Min, group.Max)
                local edit = editor.Edits.Accessories[entry.Id]
                local previous = edit[group.Property]
                edit[group.Property] = axis == 'All' and Vector3.new(value, value, value)
                    or Vector3.new(
                        axis == 'X' and value or previous.X,
                        axis == 'Y' and value or previous.Y,
                        axis == 'Z' and value or previous.Z
                    )
                select_entry(entry)
                phowg:avatar_editor_preview(editor)
            end
            field.Drag = function(x)
                local width = track.AbsoluteSize.X
                if width <= 0 then
                    return
                end
                local ratio = math.clamp((x - track.AbsolutePosition.X) / width, 0, 1)
                local value = group.Min + ratio * (group.Max - group.Min)
                value = group.Min + math.floor((value - group.Min) / group.Step + 0.5) * group.Step
                change(value)
            end
            on(box.FocusLost, function()
                change()
            end)
            on(track.InputBegan, function(input)
                if
                    editor.Selected
                    and not editor.Selected.Layered
                    and (
                        input.UserInputType == Enum.UserInputType.MouseButton1
                        or input.UserInputType == Enum.UserInputType.Touch
                    )
                then
                    dragField = field
                    field.Drag(input.Position.X)
                end
            end)
        end
    end
    on(UserInputService.InputChanged, function(input)
        if
