    local presetConnections = {}
    local function refresh_presets()
        for _, connection in ipairs(presetConnections) do
            connection:Disconnect()
            local index = table.find(editor.Connections, connection)
            if index then
                table.remove(editor.Connections, index)
            end
        end
        table.clear(presetConnections)
        for _, child in ipairs(presetList:GetChildren()) do
            if child:IsA('GuiObject') then
                child:Destroy()
            end
        end
        local names = {}
        for name in pairs(phowg:avatar_presets().Presets) do
            names[#names + 1] = name
        end
        table.sort(names)
        for index, name in ipairs(names) do
            local button = ui('TextButton', presetList, {
                Text = name,
                Size = UDim2.new(1, -4, 0, 24),
                LayoutOrder = index,
                BackgroundColor3 = Library.MainColor,
                BorderSizePixel = 0,
                TextTruncate = Enum.TextTruncate.AtEnd,
            })
            local connection = connectshared(button.MouseButton1Click, function()
                if not editor.Closed then
                    presetName.Text = name
                end
            end, editor, 'avatar preset select')
            presetConnections[#presetConnections + 1] = connection
            editor.Connections[#editor.Connections + 1] = connection
        end
        if #names == 0 then
            ui(
                'TextLabel',
                presetList,
                { Text = 'saved presets appear here', Size = UDim2.new(1, -4, 0, 24), BackgroundTransparency = 1 }
            )
        end
    end
    on(frame.Destroying, function()
        for _, connection in ipairs(presetConnections) do
            connection:Disconnect()
        end
    end)
    local save = ui('TextButton', controls, {
        Text = 'save preset',
        Position = UDim2.fromOffset(8, 430),
        Size = UDim2.new(1, -16, 0, 28),
        BackgroundColor3 = Library.MainColor,
        BorderSizePixel = 0,
    })
    on(save.MouseButton1Click, function()
        local ok, err = phowg:save_avatar_preset(presetName.Text, editor)
        editor.Status.Text = ok and 'Avatar preset saved locally' or err
        if ok then
            refresh_presets()
        end
    end)
    local loadPresetButton = ui('TextButton', controls, {
        Text = 'load',
        Position = UDim2.fromOffset(8, 466),
        Size = UDim2.fromOffset(110, 28),
        BackgroundColor3 = Library.MainColor,
        BorderSizePixel = 0,
    })
    on(loadPresetButton.MouseButton1Click, function()
        local ok, err = phowg:load_avatar_preset(presetName.Text)
        if not ok then
            editor.Status.Text = err
        end
    end)
    local delete = ui('TextButton', controls, {
        Text = 'delete',
        Position = UDim2.fromOffset(124, 466),
        Size = UDim2.fromOffset(110, 28),
        BackgroundColor3 = Library.MainColor,
        BorderSizePixel = 0,
    })
    on(delete.MouseButton1Click, function()
        local archive = phowg:avatar_presets()
        if not archive.Presets[presetName.Text] then
            editor.Status.Text = 'select a saved preset'
            return
        end
        local copyArchive = { Revision = 1, Presets = table.clone(archive.Presets) }
        copyArchive.Presets[presetName.Text] = nil
        local ok, err = phowg:write_avatar_presets(copyArchive)
        editor.Status.Text = ok and 'Avatar preset deleted' or err
        if ok then
            refresh_presets()
        end
    end)
    refresh_presets()
    local scaleAt = Library.UIScale
    on(RunService.RenderStepped, function(dt)
        if scaleAt ~= Library.UIScale then
            scaleAt = Library.UIScale
            layout()
        end
        if editor.Frame.Visible and editor.AutoRotate and not editor.Orbit then
            editor.Angle = (editor.Angle + math.min(dt, 0.1) * 0.22) % (math.pi * 2)
            editor.UpdateCamera()
        end
    end)
    if entries[1] then
        select_entry(entries[1])
    end
    phowg:avatar_editor_preview(editor)
end
phowg:register_cleanup('avatar editor', function(_, reason)
    if reason == 'unload' then
        phowg:close_avatar_editor()
    end
end)

function phowg:avatar_animation_ids(value)
    local key = tostring(value)
    Data.AvatarAnimationCache = Data.AvatarAnimationCache or {}
    local cached = Data.AvatarAnimationCache[key]
    if cached then
        return cached
    end
    local ids = {}
    local ok, objects = pcall(function()
        return game:GetObjects('rbxassetid://' .. key)
    end)
    if ok and type(objects) == 'table' then
        local function add(animation)
            if animation:IsA('Animation') and animation.AnimationId ~= '' then
                ids[animation.Name] = animation.AnimationId
                ids.First = ids.First or animation.AnimationId
            end
        end
        for _, object in ipairs(objects) do
            add(object)
            for _, child in ipairs(object:GetDescendants()) do
                add(child)
            end
            object:Destroy()
        end
    end
    if ids.First then
        Data.AvatarAnimationCache[key] = ids
    end
    ids.First = ids.First or 'rbxassetid://' .. key
    return ids
end
function phowg:apply_avatar_animations(char, desc, restore, weights)
    if Data.SafeMode and desc then
        local saved = Data.AvatarSpoof
        desc, restore, weights = nil, saved and saved.MyAnimations, saved and saved.MyAnimationWeights
    end
    local humanoid = char:FindFirstChildOfClass('Humanoid')
    local snapshot = Data.AvatarSpoof
    local version = Data.AvatarRequestVersion
    local animate = char:FindFirstChild('Animate')
    if humanoid and not animate and not Library.Unloaded and not Data.Unloading then
        animate = char:WaitForChild('Animate', 5)
    end
    if
        not humanoid
        or not animate
        or LocalPlayer.Character ~= char
        or Data.AvatarSpoof ~= snapshot
        or Data.AvatarRequestVersion ~= version
    then
        return false
    end
    local replacement = animate:Clone()
    if not replacement then
        return
    end
    local previousIds = {}
    for _, animation in ipairs(animate:GetDescendants()) do
        if animation:IsA('Animation') then
            previousIds[tostring(animation.AnimationId):match('%d+') or animation.AnimationId] = true
        end
    end
    local changed, assets = false, {}
    local damping = replacement:FindFirstChild('ScaleDampeningPercent')
    local copy = desc and (phowg:avatar_copy_enabled('animations'))
    if copy then
        if not damping then
            damping = Instance.new('NumberValue')
            damping.Name = 'ScaleDampeningPercent'
            damping.Parent = replacement
            changed = true
        end
        if damping.Value ~= 0 then
            damping.Value = 0
            changed = true
        end
    elseif snapshot then
        if snapshot.MyAnimationDampingPresent then
            if not damping then
                damping = Instance.new('NumberValue')
                damping.Name = 'ScaleDampeningPercent'
                damping.Parent = replacement
                changed = true
            end
            if damping.Value ~= snapshot.MyAnimationDamping then
                damping.Value = snapshot.MyAnimationDamping
                changed = true
            end
        elseif damping then
            damping:Destroy()
            changed = true
        end
    end
    local folders = {
        idle = 'IdleAnimation',
        walk = 'WalkAnimation',
        run = 'RunAnimation',
        jump = 'JumpAnimation',
        climb = 'ClimbAnimation',
        fall = 'FallAnimation',
        swim = 'SwimAnimation',
        swimidle = 'SwimAnimation',
    }
    local defaults = {
        idle = {
            Animation1 = 'rbxassetid://507766388',
            Animation2 = 'rbxassetid://507766666',
            First = 'rbxassetid://507766388',
        },
        walk = { First = 'rbxassetid://2510202577' },
        run = { First = 'rbxassetid://913376220' },
        jump = { First = 'rbxassetid://507765000' },
        climb = { First = 'rbxassetid://1213044953' },
        fall = { First = 'rbxassetid://507767968' },
    }
    for folder, property in pairs(folders) do
        local root = replacement:FindFirstChild(folder)
        local value = desc and tonumber(desc[property])
        local fallback = desc and (not value or value <= 0) and defaults[folder]
        local ids = value and value > 0 and phowg:avatar_animation_ids(value) or fallback
        if not root and (ids or restore) then
            root = Instance.new('StringValue')
            root.Name, root.Parent = folder, replacement
            changed = true
        end
        if root and desc and value == 0 and not fallback then
            for _, animation in ipairs(root:GetChildren()) do
                if animation:IsA('Animation') then
                    animation:Destroy()
                    changed = true
                end
            end
        elseif root then
            if ids then
                if fallback then
                    local names = folder == 'idle' and { Animation1 = true, Animation2 = true }
                        or {
                            [({
                                walk = 'WalkAnim',
                                run = 'RunAnim',
                                jump = 'JumpAnim',
                                climb = 'ClimbAnim',
                                fall = 'FallAnim',
                            })[folder]] = true,
                        }
                    for _, child in ipairs(root:GetChildren()) do
                        if child:IsA('Animation') and not names[child.Name] then
                            child:Destroy()
                            changed = true
                        end
                    end
                end
                local count = 0
                for _, child in ipairs(root:GetChildren()) do
                    if child:IsA('Animation') then
                        count = count + 1
                    end
                end
                if count == 0 or fallback then
                    local names = folder == 'idle' and { 'Animation1', 'Animation2' }
                        or {
                            ({
                                walk = 'WalkAnim',
                                run = 'RunAnim',
                                jump = 'JumpAnim',
                                climb = 'ClimbAnim',
                                fall = 'FallAnim',
                                swim = 'Swim',
                                swimidle = 'SwimIdle',
                            })[folder],
                        }
                    for _, name in ipairs(names) do
                        if not root:FindFirstChild(name) then
                            local animation = Instance.new('Animation')
                            animation.Name, animation.AnimationId, animation.Parent = name, ids[name] or ids.First, root
                            local weight = Instance.new('NumberValue')
                            weight.Name, weight.Value, weight.Parent =
                                'Weight', folder == 'idle' and name == 'Animation1' and 9 or 1, animation
                            changed = true
                        end
                    end
                end
            end
            if restore then
                for _, child in ipairs(root:GetChildren()) do
                    if child:IsA('Animation') and not restore[folder .. '/' .. child.Name] then
                        child:Destroy()
                        changed = true
                    end
                end
                local prefix = folder .. '/'
                for key, id in pairs(restore) do
                    if key:sub(1, #prefix) == prefix then
                        local name = key:sub(#prefix + 1)
                        if not root:FindFirstChild(name) then
                            local animation = Instance.new('Animation')
                            animation.Name, animation.AnimationId, animation.Parent = name, id, root
                            if weights and weights[key] then
                                local weight = Instance.new('NumberValue')
                                weight.Name, weight.Value, weight.Parent = 'Weight', weights[key], animation
                            end
                            changed = true
                        end
                    end
                end
            end
            for _, animation in ipairs(root:GetChildren()) do
                if animation:IsA('Animation') then
                    local id = restore and restore[folder .. '/' .. animation.Name]
                        or ids and (ids[animation.Name] or ids.First)
                    if id and id ~= '' then
                        local restoredWeight = restore and weights and weights[folder .. '/' .. animation.Name]
                        if restoredWeight ~= nil then
                            local weight = animation:FindFirstChild('Weight')
                            if not weight then
                                weight = Instance.new('NumberValue')
                                weight.Name, weight.Parent = 'Weight', animation
                                changed = true
                            end
                            if weight.Value ~= restoredWeight then
                                weight.Value = restoredWeight
                                changed = true
                            end
                        end
                        if fallback and folder == 'idle' then
                            local weight = animation:FindFirstChild('Weight')
                            if not weight then
                                weight = Instance.new('NumberValue')
                                weight.Name, weight.Parent = 'Weight', animation
                                changed = true
                            end
                            local idleWeight = animation.Name == 'Animation1' and 9 or 1
                            if weight.Value ~= idleWeight then
                                weight.Value = idleWeight
                                changed = true
                            end
                        end
                        if animation.AnimationId ~= id then
                            animation.AnimationId = id
                            changed = true
                        end
                        assets[#assets + 1] = id
                    end
                end
            end
        end
    end
    if
        LocalPlayer.Character ~= char
        or Data.AvatarSpoof ~= snapshot
        or Data.AvatarRequestVersion ~= version
        or char:FindFirstChild('Animate') ~= animate
        or (Library.Unloaded or Data.Unloading) and not restore
        or desc and not phowg:avatar_copy_enabled('animations')
    then
        replacement:Destroy()
        return false
    end
    phowg:queue_assets(assets)
    if changed then
        local animator = humanoid:FindFirstChildOfClass('Animator')
        if animator then
            for _, track in ipairs(animator:GetPlayingAnimationTracks()) do
                local animation = track.Animation
                local id = animation and (tostring(animation.AnimationId):match('%d+') or animation.AnimationId)
                if
                    previousIds[id]
                    and track ~= Data.AnimPlayerTrack
                    and track ~= Data.WallWalkIdleTrack
                    and track ~= Data.WallWalkMoveTrack
                then
                    track:Stop(0)
                end
            end
        end
        replacement.Disabled = true
        animate:Destroy()
        replacement.Parent = char
        replacement.Disabled = false
        task.defer(function()
            if
                LocalPlayer.Character ~= char
                or not humanoid.Parent
                or replacement.Parent ~= char
                or Library.Unloaded and not restore
            then
                return
            end
            local speed = humanoid.WalkSpeed
            humanoid.WalkSpeed = speed + 0.01
            humanoid.WalkSpeed = speed
            humanoid:ChangeState(Enum.HumanoidStateType.Running)
        end)
    else
        replacement:Destroy()
    end
    return true
end
function phowg:apply_avatar_emotes(humanoid, source)
    if not humanoid or not source then
        return false
    end
    local ok, emotes, equipped = pcall(function()
        return source:GetEmotes(), source:GetEquippedEmotes()
    end)
    if not ok then
        return false
    end
    local description = humanoid:FindFirstChildOfClass('HumanoidDescription')
    if not description then
        return false
    end
    return pcall(function()
        description:SetEmotes(emotes)
        description:SetEquippedEmotes(equipped)
    end)
end
function phowg:stop_avatar_mood(snapshot)
    if not snapshot then
        return
    end
    if snapshot.MoodTrack then
        snapshot.MoodTrack:Stop(0)
        snapshot.MoodTrack:Destroy()
        snapshot.MoodTrack = nil
    end
    if snapshot.MoodAnimation then
        snapshot.MoodAnimation:Destroy()
        snapshot.MoodAnimation = nil
    end
end
function phowg:apply_avatar_mood(char, snapshot)
    phowg:stop_avatar_mood(snapshot)
    if Data.SafeMode or not phowg:avatar_copy_enabled('animations') then
        return
    end
    local head, humanoid = char:FindFirstChild('Head'), char:FindFirstChildOfClass('Humanoid')
    local value = tonumber(snapshot.Desc.MoodAnimation)
    local animator = humanoid and humanoid:FindFirstChildOfClass('Animator')
    if not head or not head:FindFirstChildOfClass('FaceControls') or not animator or not value or value <= 0 then
        return
    end
    local ids = phowg:avatar_animation_ids(value)
    if not ids.First then
        return
    end
    local animation = Instance.new('Animation')
    animation.AnimationId = ids.First
    local ok, track = pcall(function()
        return animator:LoadAnimation(animation)
    end)
    if not ok or not track then
        animation:Destroy()
        return
    end
    snapshot.MoodAnimation, snapshot.MoodTrack = animation, track
    track.Priority, track.Looped = Enum.AnimationPriority.Idle, true
    track:Play(0, 1, 1)
end
function phowg:avatar_size_settings_changed(name, value)
    if Data.AvatarSizeUpdating then
        return
    end
    Data.AvatarSizeUpdating = true
    if value then
        for _, key in ipairs({
            'avatar_spoof_default_size',
            'avatar_spoof_perfect_size',
            'avatar_spoof_skinny',
            'avatar_spoof_big',
        }) do
            local other = key ~= name and Toggles[key]
            if other and other.Value then
                other:SetValue(false)
            end
        end
    end
    Data.AvatarSizeUpdating = nil
    phowg:refresh_avatar_spoof()
end
function phowg:avatar_copy_enabled(category)
    if Data.SafeMode and (category == 'animations' or category == 'emotes') then
        return false
    end
    local option = Options.avatar_spoof_copy
    if option and type(option.Value) == 'table' then
        return option.Value[category] == true
    end
    if category == 'animations' and Toggles.avatar_spoof_animations then
        return Toggles.avatar_spoof_animations.Value
    end
    if category == 'emotes' and Toggles.avatar_spoof_emotes then
        return Toggles.avatar_spoof_emotes.Value
    end
    return true
end
function phowg:avatar_accessory_category(item)
    local kind = item.AccessoryType and item.AccessoryType.Name
    if kind == 'Hair' then
        return 'hairs'
    end
    if
        item.IsLayered
        or ({
            TShirt = true,
            Shirt = true,
            Pants = true,
            Jacket = true,
            Sweater = true,
            Shorts = true,
            LeftShoe = true,
            RightShoe = true,
            DressSkirt = true,
        })[kind]
    then
        return 'clothing'
    end
    return 'accessories'
end
function phowg:filter_avatar_copy(description, snapshot)
    local original = snapshot.MyDesc
    if not original then
        return description
    end
    local groups = {
        body = {
            'Face',
            'Head',
            'Torso',
            'LeftArm',
            'RightArm',
            'LeftLeg',
            'RightLeg',
            'HeadColor',
            'TorsoColor',
            'LeftArmColor',
            'RightArmColor',
            'LeftLegColor',
            'RightLegColor',
            'HeightScale',
            'WidthScale',
            'DepthScale',
            'HeadScale',
            'BodyTypeScale',
            'ProportionScale',
        },
        clothing = { 'Shirt', 'Pants', 'GraphicTShirt' },
        animations = {
            'IdleAnimation',
            'WalkAnimation',
            'RunAnimation',
            'JumpAnimation',
            'ClimbAnimation',
            'FallAnimation',
            'SwimAnimation',
            'MoodAnimation',
        },
    }
    for category, properties in pairs(groups) do
        if not phowg:avatar_copy_enabled(category) then
            for _, property in ipairs(properties) do
                description[property] = original[property]
            end
        end
    end
    local accessories, transforms = {}, {}
    for _, pair in ipairs({ { description, true }, { original, false } }) do
        local source, selected = pair[1], pair[2]
        local included = {}
        for _, item in ipairs(source:GetAccessories(true)) do
            if phowg:avatar_copy_enabled(phowg:avatar_accessory_category(item)) == selected then
                accessories[#accessories + 1] = table.clone(item)
                included[item.AssetId] = true
            end
        end
        for _, child in ipairs(source:GetChildren()) do
            if child:IsA('AccessoryDescription') and included[child.AssetId] and not child.IsLayered then
                transforms[child.AssetId] =
                    { Position = child.Position, Rotation = child.Rotation, Scale = child.Scale }
            end
        end
    end
    description:SetAccessories(accessories, true)
    for _, child in ipairs(description:GetChildren()) do
        local transform = child:IsA('AccessoryDescription') and transforms[child.AssetId]
        if transform then
            child.Position, child.Rotation, child.Scale = transform.Position, transform.Rotation, transform.Scale
        end
    end
    if not phowg:avatar_copy_enabled('emotes') then
        description:SetEmotes(original:GetEmotes())
        description:SetEquippedEmotes(original:GetEquippedEmotes())
    end
    return description
end
function phowg:avatar_copy_changed()
    phowg:refresh_avatar_spoof()
    local editor = Data.AvatarEditor
    if editor and not editor.Closed then
        if editor.UpdateCopyButtons then
            editor.UpdateCopyButtons()
        end
        phowg:avatar_editor_preview(editor)
    end
end

function phowg:prepare_avatar_spoof(snapshot)
    if snapshot.ScalesPrepared then
        return
    end
    if not snapshot.BaseDesc and snapshot.Desc.Clone then
        snapshot.BaseDesc = snapshot.Desc:Clone()
    end
    local description = snapshot.Customization and phowg:avatar_editor_description(snapshot, snapshot.Customization)
        or snapshot.BaseDesc and snapshot.BaseDesc:Clone()
        or snapshot.Desc
    local skinny = Toggles.avatar_spoof_skinny and Toggles.avatar_spoof_skinny.Value
    local defaultSize = Toggles.avatar_spoof_default_size and Toggles.avatar_spoof_default_size.Value
    local perfect = Toggles.avatar_spoof_perfect_size and Toggles.avatar_spoof_perfect_size.Value
    local big = Toggles.avatar_spoof_big and Toggles.avatar_spoof_big.Value
    if defaultSize then
        for _, property in ipairs({ 'WidthScale', 'DepthScale', 'HeightScale', 'HeadScale' }) do
            description[property] = 1
        end
    elseif big then
        description.WidthScale, description.DepthScale, description.HeadScale, description.HeightScale =
            1.5, 1.5, 1.5, 1.25
    end
    for name, property in pairs({ BodyWidthScale = 'WidthScale', BodyDepthScale = 'DepthScale' }) do
        local value = snapshot.MyScales and snapshot.MyScales[name]
        if defaultSize then
            description[property] = 1
        elseif big then
            description[property] = 1.5
        elseif skinny then
            description[property] = 0.550
        elseif perfect then
            description[property] = 0.665
        elseif type(value) == 'number' and value > 0 and value < 0.7 then
            description[property] = value
        end
    end
    if not phowg:avatar_copy_enabled('animations') and snapshot.MyDesc then
        for _, property in ipairs({
            'IdleAnimation',
            'WalkAnimation',
            'RunAnimation',
            'JumpAnimation',
            'ClimbAnimation',
            'FallAnimation',
            'SwimAnimation',
        }) do
            description[property] = snapshot.MyDesc[property]
        end
    end
    if not phowg:avatar_copy_enabled('emotes') and snapshot.MyDesc then
        description:SetEmotes(snapshot.MyDesc:GetEmotes())
        description:SetEquippedEmotes(snapshot.MyDesc:GetEquippedEmotes())
    end
    phowg:filter_avatar_copy(description, snapshot)
    snapshot.Korblox = tonumber(description.RightLeg) == 139607718
    if snapshot.Korblox then
        description.RightLeg = 0
        if snapshot.ReferenceRig then
            snapshot.ReferenceRig:Destroy()
        end
        snapshot.ReferenceRig, snapshot.ReferenceRigType, snapshot.ReferenceFailed = nil, nil, nil
    end
    local old = snapshot.Desc
    snapshot.Desc, snapshot.ScalesPrepared = description, true
    snapshot.AccList, snapshot.LayeredList = collectspoofaccs(description)
    if old ~= description and old ~= snapshot.BaseDesc then
        old:Destroy()
    end
end
function phowg:refresh_avatar_spoof()
    local snapshot = Data.AvatarSpoof
    if not snapshot or not (Toggles.avatar_spoof_enabled and Toggles.avatar_spoof_enabled.Value) then
        return
    end
    local char = LocalPlayer.Character
    if Data.AvatarApplyJobs and Data.AvatarApplyJobs[char] then
        snapshot.SettingsPending = true
        return
    end
    phowg:stop_avatar_mood(snapshot)
    snapshot.ScalesPrepared, snapshot.AppliedCharacter, snapshot.ReferenceFailed = nil, nil, nil
    if snapshot.ReferenceRig then
        snapshot.ReferenceRig:Destroy()
        snapshot.ReferenceRig = nil
    end
    applyavatarspooftochar(char, true)
end
function phowg:finish_avatar_request()
    Data.SpoofBusy = false
    local query = Data.AvatarPendingQuery
    Data.AvatarPendingQuery = nil
    if query and Toggles.avatar_spoof_enabled and Toggles.avatar_spoof_enabled.Value and not Library.Unloaded then
        task.defer(function()
            applyavatarspoof(query)
        end)
    end
end
function applyavatarspooftochar(char, allowFetch)
    local snapshot = Data.AvatarSpoof
    if
        not char
        or char ~= LocalPlayer.Character
        or not char.Parent
        or not snapshot
        or not snapshot.Desc
        or snapshot.RemovePending
        or Library.Unloaded
        or Toggles.avatar_spoof_enabled and not Toggles.avatar_spoof_enabled.Value
    then
        return false
    end
    if snapshot.AppliedCharacter == char then
        return snapshot.FullOK == true
    end
    Data.AvatarApplyJobs = Data.AvatarApplyJobs or setmetatable({}, { __mode = 'k' })
    if Data.AvatarApplyJobs[char] then
        return false
    end
    local humanoid = char:FindFirstChildOfClass('Humanoid')
    if not humanoid then
        return false
    end
    Data.AvatarApplyJobs[char] = snapshot
    if phowg.suspend_local_materials then
        phowg:suspend_local_materials(char)
    end
    local ok, result = pcall(function()
        if updatekorbloxchar then
            updatekorbloxchar(char, false, true)
        end
        capturemyavatar(char)
        phowg:prepare_avatar_spoof(snapshot)
        local applied = pcall(function()
            if humanoid.ApplyDescriptionAsync then
                humanoid:ApplyDescriptionAsync(snapshot.Desc)
            else
                humanoid:ApplyDescription(snapshot.Desc)
            end
        end)
        if
            Data.AvatarSpoof ~= snapshot
            or snapshot.RemovePending
            or LocalPlayer.Character ~= char
            or not char.Parent
        then
            return false
        end
        if applied then
            phowg:apply_spoof_body_scales(humanoid, snapshot.Desc)
        end
        if not applied then
            applyspoofbodyparts(char, snapshot.Desc, allowFetch, true)
            applyavatarspooffallback(char, allowFetch)
        end
        if Data.AvatarSpoof ~= snapshot or LocalPlayer.Character ~= char then
            return false
        end
        if not applied then
            phowg:apply_avatar_mood(char, snapshot)
        end
        phowg:apply_avatar_emotes(humanoid, snapshot.Desc)
        if not phowg:avatar_copy_enabled('animations') then
            phowg:apply_avatar_animations(char, nil, snapshot.MyAnimations, snapshot.MyAnimationWeights)
        else
            phowg:apply_avatar_animations(char, snapshot.Desc)
        end
        local assets = {}
        local emotesOk, emotes = pcall(function()
            return snapshot.Desc:GetEmotes()
        end)
        if emotesOk then
            for _, ids in pairs(emotes) do
                for _, id in ipairs(ids) do
                    assets[#assets + 1] = 'rbxassetid://' .. tostring(id)
                end
            end
        end
        phowg:queue_assets(assets)
        if updatekorbloxchar then
            updatekorbloxchar(char, Toggles.local_korblox and Toggles.local_korblox.Value or false)
        end
        snapshot.FullOK, snapshot.AppliedCharacter = applied or snapshot.ReferenceRig ~= nil, char
        return true
    end)
    Data.AvatarApplyJobs[char] = nil
    if phowg.resume_local_materials then
        phowg:resume_local_materials(char)
    end
    Data.VisualDirty = true
    if Data.AvatarSpoof == snapshot and phowg.refresh_name_spoof then
        phowg:refresh_name_spoof()
    end
    if snapshot.RemovePending and Data.AvatarSpoof == snapshot then
        clearavatarspoof()
    elseif snapshot.SettingsPending and Data.AvatarSpoof == snapshot then
        snapshot.SettingsPending = nil
        task.defer(phowg.refresh_avatar_spoof)
    end
    if Data.AvatarSpoof ~= snapshot and Data.AvatarSpoof then
        task.defer(function()
            applyavatarspooftochar(char, allowFetch)
        end)
    end
    if not ok and Data.AvatarSpoof == snapshot then
        Library:Notify('spoof: appearance could not be fully applied', Library.NotifyDuration or 3)
    end
    return ok and result == true
end
function collectspoofaccs(desc)
    local rigid, layered, seen = {}, {}, {}
    local ok, list = pcall(function()
        return desc:GetAccessories(true)
    end)
    if not ok or type(list) ~= 'table' then
        return rigid, layered
    end
    for _, accessory in ipairs(list) do
        local id = tonumber(accessory.AssetId)
        if id and id > 0 and not seen[id] then
            seen[id] = true
            local kind = tostring(accessory.AccessoryType):match('[^.]+$'):lower()
            local isLayered = accessory.IsLayered
                or kind == 'shirt'
                or kind == 'jacket'
                or kind == 'sweater'
                or kind == 'pants'
                or kind == 'shorts'
                or kind == 'dressskirt'
                or kind == 'tshirt'
                or kind == 'leftshoe'
                or kind == 'rightshoe'
            local target = isLayered and layered or rigid
            target[#target + 1] = id
        end
    end
    return rigid, layered
end

