function phowg:set_admin_base_passage(enabled)
    local previous = Data.AdminBasePassage
    if not enabled then
        if not previous then
            return
        end
        Data.AdminBasePassage = nil
        previous.Closed = true
        for _, connection in ipairs(previous.Connections) do
            connection:Disconnect()
        end
        previous.Unbind()
        return
    end
    if previous or Library.Unloaded then
        return
    end
    local state: { [string]: any } =
        { Objects = {}, Connections = {}, BoundConnections = {}, Pending = false, Closed = false }
    Data.AdminBasePassage = state
    local tweens = game:GetService('TweenService')
    local function restore(object)
        local record = state.Objects[object]
        if not record then
            return
        end
        state.Objects[object] = nil
        if record.Connection then
            record.Connection:Disconnect()
        end
        if record.Tween then
            record.Tween:Cancel()
        end
        pcall(function()
            object.Transparency = record.Transparency
            if record.CanCollide ~= nil then
                object.CanCollide = record.CanCollide
            end
        end)
    end
    local function track(object)
        if state.Closed or state.Objects[object] then
            return
        end
        local physical = object:IsA('BasePart')
        if not physical and not object:IsA('Decal') and not object:IsA('Texture') then
            return
        end
        local record: { [string]: any } = { Transparency = object.Transparency }
        state.Objects[object] = record
        if physical then
            record.CanCollide = object.CanCollide
            object.CanCollide = false
            record.Connection = object:GetPropertyChangedSignal('CanCollide'):Connect(function()
                if not state.Closed and state.Objects[object] == record and object.CanCollide then
                    object.CanCollide = false
                end
            end)
        end
        if object.Transparency < 1 then
            record.Tween = tweens:Create(
                object,
                TweenInfo.new(2.5, Enum.EasingStyle.Sine, Enum.EasingDirection.Out),
                { Transparency = 1 }
            )
            record.Tween:Play()
        end
    end
    state.Unbind = function()
        for _, connection in ipairs(state.BoundConnections) do
            connection:Disconnect()
        end
        table.clear(state.BoundConnections)
        local objects = {}
        for object in pairs(state.Objects) do
            objects[#objects + 1] = object
        end
        for _, object in ipairs(objects) do
            restore(object)
        end
        state.Container, state.Map = nil, nil
    end
    local function bind()
        if state.Closed or Data.AdminBasePassage ~= state then
            return
        end
        local map = Workspace:FindFirstChild('MAP')
        local container = map and map:FindFirstChild('EVIL_SPECIAL')
        if container == state.Container and map == state.Map then
            return
        end
        state.Unbind()
        state.Container, state.Map = container, map
        if not container then
            return
        end
        state.BoundConnections[#state.BoundConnections + 1] = container.DescendantAdded:Connect(track)
        state.BoundConnections[#state.BoundConnections + 1] = container.DescendantRemoving:Connect(restore)
        track(container)
        for _, object in ipairs(container:GetDescendants()) do
            track(object)
        end
    end
    local function refresh()
        if state.Pending or state.Closed then
            return
        end
        state.Pending = true
        task.defer(function()
            state.Pending = false
            bind()
        end)
    end
    state.Connections[#state.Connections + 1] = Workspace.DescendantAdded:Connect(function(object)
        if object.Name == 'MAP' or object.Name == 'EVIL_SPECIAL' then
            refresh()
        end
    end)
    state.Connections[#state.Connections + 1] = Workspace.DescendantRemoving:Connect(function(object)
        if object == state.Container or object == state.Map then
            refresh()
        end
    end)
    bind()
end
function phowg:restore_world_leak(key)
    if key == 'admin_base' then
        phowg:set_admin_base_passage(false)
    end
    local state = Data.WorldLeaks and Data.WorldLeaks[key]
    if not state then
        return true
    end
    local ok, problem = pcall(function()
        state.Instance.Parent = state.Parent
        if state.Pivot then
            state.Instance:PivotTo(state.Pivot)
        end
    end)
    if ok then
        Data.WorldLeaks[key] = nil
    elseif not Library.Unloaded then
        Library:Notify('Could not restore world prop: ' .. tostring(problem), 3)
    end
    return ok
end
function phowg:set_super_sayan(value)
    phowg:set_character_observer('super sayan', value, function(state, character)
        local sounds = setmetatable({}, { __mode = 'k' })
        local desired = 'rbxassetid://132521221880216'
        local function track(sound)
            if not sound:IsA('Sound') or sound.Name ~= 'Weave' or sounds[sound] then
                return
            end
            local original = sound.SoundId
            sounds[sound] = { Original = original }
            local function enforce()
                if state.Closed or not sound.Parent or sound.SoundId == desired then
                    return
                end
                if sounds[sound].Original == '' and sound.SoundId ~= '' then
                    sounds[sound].Original = sound.SoundId
                end
                sound.SoundId = desired
            end
            state.Connections[sound] = connectshared(
                sound:GetPropertyChangedSignal('SoundId'),
                enforce,
                character,
                'super sayan/weave',
                0,
                'property/SoundId',
                sound
            )
            sound.SoundId = desired
        end
        state.Connections.Added = connectshared(
            character.DescendantAdded,
            track,
            character,
            'super sayan/sound added',
            0,
            'event/DescendantAdded',
            character
        )
        state.Restore = function()
            for sound, record in pairs(sounds) do
                if sound.Parent and sound.SoundId == desired then
                    sound.SoundId = record.Original
                end
            end
        end
        for _, sound in ipairs(character:GetDescendants()) do
            track(sound)
        end
    end)
end
function phowg:destroy_aim_view_record(record)
    for _, connection in pairs(record.Connections) do
        connection:Disconnect()
    end
    if record.Part then
        record.Part:Destroy()
    end
    if record.Endpoint then
        record.Endpoint:Destroy()
    end
end
function phowg:clear_sticky_aim_view()
    local state = Data.StickyAimView
    Data.StickyAimView = nil
    if not state then
        return
    end
    for _, record in pairs(state.Records) do
        phowg:destroy_aim_view_record(record)
    end
end
function phowg:create_aim_view_record(player, character)
    local record: { [string]: any } = { Player = player, Character = character, Connections = {} }
    local function refresh()
        record.Handle = nil
        for _, tool in ipairs(character:GetChildren()) do
            if tool:IsA('Tool') and tool:FindFirstChild('Ammo') then
                local handle = tool:FindFirstChild('Handle')
                if handle and handle:IsA('BasePart') then
                    record.Handle = handle
                    break
                end
            end
        end
        local effects = character:FindFirstChild('BodyEffects')
        local mouse = effects and effects:FindFirstChild('MousePos')
        if mouse == record.Mouse then
            return
        end
        if record.Connections.Value then
            record.Connections.Value:Disconnect()
            record.Connections.Value = nil
        end
        record.Mouse, record.Point = mouse, nil
        if mouse and mouse:IsA('ValueBase') then
            local function update()
                local value = mouse.Value
                record.Point = typeof(value) == 'CFrame' and value.Position
                    or typeof(value) == 'Vector3' and value
                    or nil
            end
            record.Connections.Value = connectshared(
                mouse:GetPropertyChangedSignal('Value'),
                update,
                character,
                'aim view/position',
                0,
                'property/Value',
                mouse
            )
            update()
        end
    end
    local function changed(object)
        if
            object:IsA('Tool')
            or object.Name == 'Handle'
            or object.Name == 'Ammo'
            or object.Name == 'BodyEffects'
            or object.Name == 'MousePos'
        then
            if record.RefreshQueued then
                return
            end
            record.RefreshQueued = true
            task.defer(function()
                record.RefreshQueued = nil
                local state = Data.StickyAimView
                if state and state.Records[player] == record then
                    refresh()
                end
            end)
        end
    end
    record.Connections.Added = connectshared(
        character.DescendantAdded,
        changed,
        character,
        'aim view/added',
        0,
        'event/DescendantAdded',
        character
    )
    record.Connections.Removed = connectshared(
        character.DescendantRemoving,
        changed,
        character,
        'aim view/removed',
        0,
        'event/DescendantRemoving',
        character
    )
    refresh()
    return record
end
function phowg:render_aim_view(record)
    local handle, point = record.Handle, record.Point
    local character = record.Character
    local source = handle and handle:IsDescendantOf(character) and handle
        or character and character:FindFirstChild('Head')
    local valid = source
        and source:IsA('BasePart')
        and source:IsDescendantOf(Workspace)
        and phowg:perfect_hit_vector(point)
    local origin = valid and source.Position
    local distance = origin and (point - origin).Magnitude
    local camera = Workspace.CurrentCamera
    if valid and camera and camera.CFrame then
        valid = (origin - camera.CFrame.Position).Magnitude < 2000
    end
    if not valid or not phowg:perfect_hit_vector(origin) or distance < 0.05 or distance > 10000 then
        if record.Part then
            record.Part.Parent = nil
            record.Endpoint.Parent = nil
        end
        return
    end
    if not record.Part then
        local part = Instance.new('Part')
        part.Name, part.Anchored, part.Transparency = 'PhowgAimView', true, 1
        part.CanCollide, part.CanTouch, part.CanQuery, part.CastShadow = false, false, false, false
        part.Size = Vector3.new(0.05, 0.05, 0.05)
        local start = Instance.new('Attachment')
        start.Parent = part
        local finish = Instance.new('Attachment')
        finish.Parent = part
        for index = 1, 2 do
            local beam = Instance.new('Beam')
            beam.Attachment0, beam.Attachment1, beam.FaceCamera = start, finish, true
            beam.LightEmission, beam.Brightness, beam.LightInfluence = 1, 3, 0
            beam.Width0, beam.Width1 = index == 1 and 0.2 or 0.055, index == 1 and 0.14 or 0.035
            beam.Color = ColorSequence.new(index == 1 and Color3.fromRGB(255, 25, 45) or Color3.fromRGB(255, 200, 205))
            beam.Transparency = NumberSequence.new(index == 1 and 0.4 or 0.05)
            beam.Parent = part
        end
        local endpoint = Instance.new('Part')
        endpoint.Name, endpoint.Anchored, endpoint.Material = 'PhowgAimPoint', true, Enum.Material.Neon
        endpoint.CanCollide, endpoint.CanTouch, endpoint.CanQuery, endpoint.CastShadow = false, false, false, false
        endpoint.Shape, endpoint.Size, endpoint.Color =
            Enum.PartType.Ball, Vector3.new(0.22, 0.22, 0.22), Color3.fromRGB(255, 65, 75)
        record.Part, record.Endpoint, record.Finish = part, endpoint, finish
    end
    record.Part.CFrame = CFrame.new(origin)
    record.Finish.Position = point - origin
    record.Endpoint.CFrame = CFrame.new(point)
    record.Part.Parent, record.Endpoint.Parent =
        Workspace:FindFirstChild('Ignored') or Workspace, Workspace:FindFirstChild('Ignored') or Workspace
end
function phowg:sticky_aim_view_tick()
    if not (Toggles.sticky_aim_view and Toggles.sticky_aim_view.Value) then
        phowg:clear_sticky_aim_view()
        return
    end
    local state = Data.StickyAimView
    if not state then
        state = { Records = {}, Targets = {}, RefreshAt = 0, RenderAt = 0 }
        Data.StickyAimView = state
    end
    local everyone = Options.sticky_aim_view_targets and Options.sticky_aim_view_targets.Value == 'everyone'
    local now = tick()
    if everyone and now - state.RenderAt < 1 / 30 then
        return
    end
    state.RenderAt = now
    if not everyone or now >= state.RefreshAt then
        state.Targets = {}
        if everyone then
            for _, player in ipairs(Players:GetPlayers()) do
                if player ~= LocalPlayer then
                    state.Targets[player] = true
                end
            end
        else
            local target = Toggles.sticky_aim_enabled and Toggles.sticky_aim_enabled.Value and get_sticky_target() or nil
            target = target or phowg:prediction_target(nil)
            if target and target ~= LocalPlayer then
                state.Targets[target] = true
            end
        end
        state.RefreshAt = now + 0.25
    end
    for player, record in pairs(state.Records) do
        if not state.Targets[player] or not player.Parent or player.Character ~= record.Character then
            phowg:destroy_aim_view_record(record)
            state.Records[player] = nil
        end
    end
    for player in pairs(state.Targets) do
        local character = player.Parent and player.Character
        if character and character.Parent then
            local record = state.Records[player]
            if not record then
                record = phowg:create_aim_view_record(player, character)
                state.Records[player] = record
            end
            phowg:render_aim_view(record)
        end
    end
end
function phowg:set_sticky_aim_view(enabled)
    if Data.StickyAimViewRender then
        Data.StickyAimViewRender:Disconnect()
        Data.StickyAimViewRender = nil
    end
    phowg:clear_sticky_aim_view()
    if enabled then
        Data.StickyAimViewRender = phowg:register_render(phowg.sticky_aim_view_tick, RunService, 'frame/aim view')
    end
end
phowg:register_cleanup('sticky aim view', function(scope, reason)
    if reason == 'unload' or not scope then
        phowg:set_sticky_aim_view(false)
        return
    end
    local state = Data.StickyAimView
    for player, record in pairs(state and state.Records or {}) do
        if scope == player or scope == record.Character then
            phowg:destroy_aim_view_record(record)
            state.Records[player] = nil
        end
    end
end)

getgenv().PhowgGetClientCFrame = function()
    if Data.CSyncTable and (Data.CSyncTable[2] or Data.MoveToInFlight) and typeof(Data.CSyncTable[1]) == 'CFrame' then
        return Data.CSyncTable[1]
    end
    local root = getroot(LocalPlayer.Character)
    return root and root.CFrame or Local_Data.ClientPos
end
