    if Data.FPSOverlayConnection then
        Data.FPSOverlayConnection:Disconnect()
    end
    if Data.FPSOverlay then
        Data.FPSOverlay:Destroy()
    end
    Data.FPSOverlay, Data.FPSOverlayConnection = nil, nil
