function phowg:update_fps_overlay()
    if Library.Unloaded or Data.SharedSignalsClosed or not phowg:toggle_enabled('fps_overlay') then
        phowg:clear_fps_overlay()
        return
    end
    local label = Data.FPSOverlay
    if not label then
        label = Instance.new('TextLabel')
        label.Name, label.BackgroundTransparency, label.BorderSizePixel = 'PhowgFPS', 1, 0
        label.Size, label.TextXAlignment, label.Font =
            UDim2.fromOffset(180, 30), Enum.TextXAlignment.Left, Enum.Font.Code
        label.TextStrokeTransparency, label.TextStrokeColor3, label.ZIndex = 0, Color3.new(0, 0, 0), 40
        label.Text, label.Parent = 'fps: --', Data.StatusGui
        Data.FPSOverlay = label
        local frames, elapsed = 0, 0
        Data.FPSOverlayConnection = phowg:register_render(function(dt)
            frames, elapsed = frames + 1, elapsed + dt
            if elapsed >= 0.5 then
                label.Text = 'fps: ' .. tostring(math.round(frames / elapsed))
                frames, elapsed = 0, 0
            end
        end, RunService, 'frame/fps overlay')
    end
    label.Position = UDim2.fromScale(
        phowg:visual_number('fps_overlay_x', 2, 0, 90) / 100,
        phowg:visual_number('fps_overlay_y', 45, 0, 95) / 100
    )
    label.TextSize = phowg:visual_number('fps_overlay_size', 18, 10, 32)
    label.TextColor3 = Options.fps_overlay_color and Options.fps_overlay_color.Value or Color3.new(1, 1, 1)
end
