function phowg:stop_music()
    Data.MusicGeneration = (Data.MusicGeneration or 0) + 1
    if Data.MusicEnded then
        Data.MusicEnded:Disconnect()
    end
    if Data.MusicSound then
        Data.MusicSound:Stop()
        Data.MusicSound:Destroy()
    end
    Data.MusicSound, Data.MusicEnded = nil, nil
end
function phowg:update_music_volume()
    if Data.MusicSound then
        Data.MusicSound.Volume = phowg:visual_number('music_volume', 25, 0, 100) / 100
    end
end
function phowg:next_music()
    if Library.Unloaded or Data.SharedSignalsClosed or not phowg:toggle_enabled('music_enabled') then
        return
    end
    local current = Options.music_track and Options.music_track.Value
    local index = table.find(Data.MusicTrackNames, current) or 0
    Options.music_track:SetValue(Data.MusicTrackNames[index % #Data.MusicTrackNames + 1])
end
function phowg:update_music()
    phowg:stop_music()
    if Library.Unloaded or Data.SharedSignalsClosed or not phowg:toggle_enabled('music_enabled') then
        return
    end
    local selected = Options.music_track and Options.music_track.Value
    local track = Data.MusicTracks[selected]
    local custom = selected == 'custom'
        and Options.music_custom_asset
        and tostring(Options.music_custom_asset.Value):match('%d+')
    if not track and not custom then
        return
    end
    local generation = Data.MusicGeneration
    local function current()
        return Data.MusicGeneration == generation
            and not Library.Unloaded
            and not Data.SharedSignalsClosed
            and phowg:toggle_enabled('music_enabled')
    end
    local function play(id)
        if not current() then
            return
        end
        local sound = Instance.new('Sound')
        sound.Name, sound.SoundId, sound.Volume, sound.Parent =
            'PhowgMusic', id, phowg:visual_number('music_volume', 25, 0, 100) / 100, game:GetService('SoundService')
        sound.Looped = phowg:toggle_enabled('music_loop')
        Data.MusicSound = sound
        Data.MusicEnded = connectshared(sound.Ended, function()
            if Data.MusicSound == sound and phowg:toggle_enabled('music_auto_next') then
                phowg:next_music()
            end
        end, sound, 'music/ended')
        sound:Play()
    end
    if custom then
        play('rbxassetid://' .. custom)
        return
    end
    Data.MusicAssetCache = Data.MusicAssetCache or {}
    if Data.MusicAssetCache[selected] then
        play(Data.MusicAssetCache[selected])
        return
    end
    phowg:queue_background('music assets', generation, function()
        if not current() then
            return
        end
        local ok, id = pcall(function()
            local asset = getcustomasset or getsynasset
            if not (asset and isfile and isfolder and makefolder and writefile) then
                error('local audio files are not supported by this executor')
            end
            local path = phowg:asset_cache_path('music', track.File, { 'PhowgAssets/Music/' .. track.File })
            if not isfile(path) then
                local bytes = game:HttpGet(track.Url)
                if not current() then
                    return nil
                end
                if type(bytes) ~= 'string' or #bytes == 0 then
                    error('empty audio download')
                end
                writefile(path, bytes)
            end
            return asset(path)
        end)
        if not current() then
            return
        end
        if ok and type(id) == 'string' and id ~= '' then
            Data.MusicAssetCache[selected] = id
            play(id)
        else
            Library:Notify('unable to load this song; try another track or a custom audio id', 4)
        end
    end)
end
function phowg:clear_roaming_models()
    local state = Data.RoamingModels
    Data.RoamingModels = nil
    if not state then
        return
    end
    if state.Connection then
        state.Connection:Disconnect()
    end
    for _, entry in ipairs(state.Entries) do
        phowg:release_visual(entry)
    end
    if state.Folder then
        state.Folder:Destroy()
    end
end
function phowg:roaming_origin()
    local getter = getgenv().PhowgGetClientCFrame
    local cf = type(getter) == 'function' and getter() or Local_Data.ClientPos
    if typeof(cf) == 'CFrame' and cf.Position.Y > -500 then
        return cf.Position
    end
    return nil
end
function phowg:roaming_destination(state, origin)
    local radius = phowg:visual_number('roaming_models_radius', 100, 20, 300)
    for _ = 1, 4 do
        local angle, distance = math.random() * math.pi * 2, math.random() * radius
        local position = origin + Vector3.new(math.cos(angle) * distance, 100, math.sin(angle) * distance)
        local hit = Workspace:Raycast(position, Vector3.new(0, -250, 0), state.Params)
        if hit and hit.Normal.Y > 0.5 then
            return hit.Position
        end
    end
    return nil
end
function phowg:tick_roaming_models(state, dt)
    if Data.RoamingModels ~= state then
        return
    end
    local origin = phowg:roaming_origin()
    if not origin then
        return
    end
    dt = math.min(dt, 0.1)
    local now = tick()
    for _, entry in ipairs(state.Entries) do
        if entry.Model.Parent and phowg:cosmetic_visible(entry.Position) then
            local delta = entry.Target - entry.Position
            local flat = Vector3.new(delta.X, 0, delta.Z)
            if now >= entry.CheckAt then
                entry.CheckAt = now + 0.2
                local forward = flat.Magnitude > 0.1 and flat.Unit or Vector3.new(0, 0, -1)
                local wall = Workspace:Raycast(entry.Position + Vector3.new(0, 2, 0), forward * 5, state.Params)
                local floor = Workspace:Raycast(
                    entry.Position + forward * 4 + Vector3.new(0, 15, 0),
                    Vector3.new(0, -40, 0),
                    state.Params
                )
                entry.CanWalk = not wall and floor ~= nil
                if entry.CanWalk then
                    entry.Ground = floor.Position.Y
                end
                local tooFar = (entry.Position - origin).Magnitude
                    > phowg:visual_number('roaming_models_radius', 100, 20, 300) * 2
                if (flat.Magnitude < 3 or not entry.CanWalk or tooFar) and now >= (entry.PathAt or 0) then
                    entry.PathAt = now + 1
                    local destination = phowg:roaming_destination(state, origin)
                    if destination then
                        entry.Target = destination
                    end
                end
                if not Library.ReducedMotion and not entry.JumpAt and math.random() < 0.08 then
                    entry.JumpAt = now
                    entry.Flip = math.random(1, 100) <= phowg:visual_number('roaming_models_backflip', 18, 0, 100)
                end
            end
            if entry.CanWalk and flat.Magnitude > 0.1 then
                local step = flat.Unit * math.min(flat.Magnitude, entry.Speed * dt)
                entry.Position = Vector3.new(
                    entry.Position.X + step.X,
                    entry.Position.Y + (entry.Ground - entry.Position.Y) * (1 - math.exp(-12 * dt)),
                    entry.Position.Z + step.Z
                )
                local facing = CFrame.lookAt(Vector3.zero, flat.Unit)
                entry.Rotation = entry.Rotation:Lerp(facing, 1 - math.exp(-6 * dt))
            end
            local jump, flip = 0, 0
            if entry.JumpAt then
                local progress = (now - entry.JumpAt) / 0.8
                if progress >= 1 or Library.ReducedMotion then
                    entry.JumpAt = nil
                else
                    jump = math.sin(progress * math.pi) * 4
                    flip = entry.Flip and progress * math.pi * 2 or 0
                end
            end
            local bob = Library.ReducedMotion and 0 or math.abs(math.sin(now * entry.Speed)) * 0.25
            entry.Model:PivotTo(
                CFrame.new(entry.Position + Vector3.new(0, entry.Height + jump + bob, 0))
                    * entry.Rotation
                    * CFrame.Angles(flip, 0, 0)
            )
        end
    end
end
function phowg:resize_roaming_models(state, template)
    if Data.RoamingModels ~= state or Library.Unloaded or Data.SharedSignalsClosed then
        return
    end
    local origin = phowg:roaming_origin()
    if not origin then
        return
    end
    local filter = { state.Folder }
    if LocalPlayer.Character then
        filter[#filter + 1] = LocalPlayer.Character
    end
    local players = Workspace:FindFirstChild('Players')
    if players then
        filter[#filter + 1] = players
    end
    state.Params.FilterDescendantsInstances = filter
    local count = phowg:visual_number('roaming_models_count', 5, 1, 50)
    for index = #state.Entries, count + 1, -1 do
        local entry = table.remove(state.Entries, index)
        phowg:release_visual(entry)
        entry.Model:Destroy()
    end
    for _ = #state.Entries + 1, count do
        local position = phowg:roaming_destination(state, origin)
        if position then
            local model = template:Clone()
            local entry = {
                Model = model,
                Position = position,
                Target = position,
                Ground = position.Y,
                CheckAt = 0,
                CanWalk = false,
                Speed = math.random(10, 16),
                Rotation = CFrame.new(),
            }
            local cf, size = model:GetBoundingBox()
            entry.Height = model:GetPivot().Position.Y - cf.Position.Y + size.Y / 2
            if phowg:acquire_visual(entry, #model:GetDescendants(), 'roaming models') then
                model.Parent = state.Folder
                model:PivotTo(CFrame.new(position + Vector3.new(0, entry.Height, 0)))
                state.Entries[#state.Entries + 1] = entry
            else
                model:Destroy()
                break
            end
        end
    end
    if #state.Entries > 0 and not state.Connection then
        state.Connection = phowg:register_render(function(dt)
            phowg:tick_roaming_models(state, dt)
        end, RunService, 'frame/roaming models')
    end
end
function phowg:update_roaming_models()
    if Library.Unloaded or Data.SharedSignalsClosed or not phowg:toggle_enabled('roaming_models') then
        phowg:clear_roaming_models()
        return
    end
    local state = Data.RoamingModels
    if state and (state.Loading or Data.RoamingTemplate) then
        if Data.RoamingTemplate then
            phowg:resize_roaming_models(state, Data.RoamingTemplate)
        end
        return
    end
    phowg:clear_roaming_models()
    state = { Entries = {}, Params = RaycastParams.new(), Loading = true }
    state.Params.FilterType = Enum.RaycastFilterType.Exclude
    local folder = Instance.new('Folder')
    folder.Name, folder.Parent = 'PhowgRoamingModels', Workspace
    state.Folder, Data.RoamingModels = folder, state

    if Data.RoamingTemplate then
        phowg:resize_roaming_models(state, Data.RoamingTemplate)
        return
    end
    phowg:queue_background('cosmetic models', state, function()
        if Data.RoamingModels ~= state or Library.Unloaded or Data.SharedSignalsClosed then
            return
        end
        local ok, objects = pcall(function()
            return game:GetObjects('rbxassetid://72466520546640')
        end)
        state.Loading = false
        if not ok or type(objects) ~= 'table' then
            if Data.RoamingModels == state then
                Library:Notify('unable to load the cosmetic model asset', 4)
            end
            return
        end
        local template = objects[1]
        for index = 2, #objects do
            objects[index]:Destroy()
        end
        if not template then
            return
        end
        if Data.RoamingModels ~= state or Library.Unloaded or Data.SharedSignalsClosed then
            template:Destroy()
            return
        end
        if not template:IsA('Model') then
            local model = Instance.new('Model')
            template.Parent = model
            template = model
        end
        for _, object in ipairs(template:GetDescendants()) do
            if object:IsA('LuaSourceContainer') then
                object:Destroy()
            elseif object:IsA('BasePart') then
                object.Anchored, object.CanCollide, object.CanTouch, object.CanQuery, object.CastShadow =
                    true, false, false, false, false
            elseif object:IsA('Humanoid') then
                object.DisplayDistanceType = Enum.HumanoidDisplayDistanceType.None
            end
        end
        if not template:FindFirstChildWhichIsA('BasePart', true) then
            template:Destroy()
            return
        end
        Data.RoamingTemplate = template
        phowg:queue_asset_tree(template)
        phowg:resize_roaming_models(state, template)
    end)
end
phowg:register_cleanup('sample visual additions', function(scope)
    if scope then
        return
    end
    phowg:clear_fps_overlay()
    phowg:stop_music()
    phowg:clear_roaming_models()
    if Data.RoamingTemplate then
        Data.RoamingTemplate:Destroy()
        Data.RoamingTemplate = nil
    end
end)
function phowg:parse_boxing_score(value)
    local text = tostring(value or ''):lower():gsub('[%s,_]', '')
    local number = tonumber(text)
    if not number then
        local amount, suffix = text:match('^(%d*%.?%d+)(%a+)$')
        local multipliers = { k = 1e3, m = 1e6, b = 1e9, t = 1e12, qd = 1e15, qn = 1e18 }
        if amount and multipliers[suffix] then
            number = tonumber(amount) * multipliers[suffix]
        end
    end
    if not number or number ~= number or number < 1 or number == math.huge then
        return nil
    end
    return math.floor(number)
end
function phowg:boxing_status(text)
    if Data.BoxingStatusText == text then
        return
    end
    Data.BoxingStatusText = text
    if Data.BoxingStatusLabel then
        Data.BoxingStatusLabel:SetText(text)
    end
end
function phowg:set_boxing_score(value)
    local number = phowg:parse_boxing_score(value)
    if not number then
        phowg:boxing_status('invalid value; keeping ' .. string.format('%.0f', Data.BoxingScore or 1000))
        return false
    end
    Data.BoxingScore = number
    if Data.BoxingValueLabel then
        Data.BoxingValueLabel:SetText('value: ' .. string.format('%.0f', number))
    end
    phowg:boxing_status('returns: ' .. string.format('%.0f', number))
    return true
end
function phowg:boxing_score_value()
    local option = Options.boxing_machine_score
    local selected = option and phowg:parse_boxing_score(option.Value)
    return selected or Data.BoxingScore or 1000
end
function phowg:read_boxing_callback(remote)
    if type(getcallbackvalue) == 'function' then
        local ok, value = pcall(getcallbackvalue, remote, 'OnClientInvoke')
        if ok and type(value) == 'function' then
            return true, value
        end
    end
    local ok, value = pcall(function()
        return remote.OnClientInvoke
    end)
    return ok and type(value) == 'function', type(value) == 'function' and value or nil
end
function phowg:boxing_machine_kind(remote)
    local current = remote
    for _ = 1, 20 do
        if not current then
            break
        end
        if current.Name == 'RedPunchingMachine' then
            return 'red'
        end
        if current.Name == 'BlackPunchingMachine' then
            return 'black'
        end
        current = current.Parent
    end
    return nil
end
function phowg:boxing_record_return(entry)
    local state = Data.BoxingMachine
    if state and entry.Enabled then
        state.Returns = (state.Returns or 0) + 1
        state.LastReturn = phowg:boxing_score_value()
        state.LastReturnAt = tick()
    end
end
function phowg:bind_boxing_environment(entry)
    local environment
    if type(getsenv) == 'function' then
        local ok, result = pcall(getsenv, entry.Handler)
        if ok and type(result) == 'table' and result.script == entry.Handler then
            environment = result
        end
    end
    if not environment and type(getfenv) == 'function' and type(entry.Original) == 'function' then
        local ok, result = pcall(getfenv, entry.Original)
        if ok and type(result) == 'table' and result.script == entry.Handler then
            environment = result
        end
    end
    if not environment then
        return false
    end
    if entry.Environment == environment and environment.evaluateProximity == entry.ProximityReplacement then
        return true
    end
    local original = environment.evaluateProximity
    if type(original) ~= 'function' or type(environment.oscillateBetweenZeroAndOne) ~= 'function' then
        return false
    end
    if entry.Environment and entry.Environment.evaluateProximity == entry.ProximityReplacement then
        entry.Environment.evaluateProximity = entry.ProximityOriginal
    end
    entry.Environment, entry.ProximityOriginal = environment, original
    entry.ProximityReplacement = function(...)
        if
            entry.Enabled
            and Data.BoxingMachine
            and not Library.Unloaded
            and not Data.SharedSignalsClosed
            and Toggles.boxing_machine_enabled
            and Toggles.boxing_machine_enabled.Value
        then
            phowg:boxing_record_return(entry)
            return phowg:boxing_score_value() / 1000
        end
        return original(...)
    end
    local assigned = pcall(function()
        environment.evaluateProximity = entry.ProximityReplacement
    end)
    return assigned and environment.evaluateProximity == entry.ProximityReplacement
end
function phowg:release_boxing_entry(entry)
    entry.Enabled = false
    if entry.Environment and entry.Environment.evaluateProximity == entry.ProximityReplacement then
        pcall(function()
            entry.Environment.evaluateProximity = entry.ProximityOriginal
        end)
    end
    if entry.Assigned then
        local ok, current = phowg:read_boxing_callback(entry.Remote)
        if not ok or current == entry.Replacement then
            pcall(function()
                entry.Remote.OnClientInvoke = entry.Original
            end)
        end
    end
end
function phowg:stop_boxing_machine()
    local state = Data.BoxingMachine
    Data.BoxingMachine = nil
    if not state then
        return
    end
    for _, entry in pairs(state.Entries) do
        phowg:release_boxing_entry(entry)
    end
    for _, connection in pairs(state.Connections) do
        connection:Disconnect()
    end
end
function phowg:boxing_candidate(state, remote)
    if not remote or not remote:IsA('RemoteFunction') or remote.Name ~= 'RemoteFunction' then
        return
    end
    local handler = remote.Parent
    local frame = handler and handler.Parent
    if not handler or handler.Name ~= 'Handler' or not frame then
        return
    end
    local kind = phowg:boxing_machine_kind(remote)
    if kind or frame:FindFirstChild('Arrow') then
        state.Candidates[remote] = kind or 'copy'
    end
end
function phowg:bind_boxing_candidates(state, key, root)
    if state.Roots[key] == root then
        return
    end
    if state.Connections[key] then
        state.Connections[key]:Disconnect()
        state.Connections[key] = nil
    end
    state.Roots[key] = root
    if not root then
        return
    end
    state.Connections[key] = connectshared(root.DescendantAdded, function(object)
        if Data.BoxingMachine ~= state then
            return
        end
        if object:IsA('RemoteFunction') then
            phowg:boxing_candidate(state, object)
        elseif object.Name == 'Arrow' and object.Parent then
            local handler = object.Parent:FindFirstChild('Handler')
            if handler then
                phowg:boxing_candidate(state, handler:FindFirstChild('RemoteFunction'))
            end
        end
        if object:IsA('RemoteFunction') or object.Name == 'Arrow' then
            task.defer(function()
                if Data.BoxingMachine == state then
                    phowg:update_boxing_machine()
                end
            end)
        end
    end, root, 'boxing/live callback added', 0, 'event/DescendantAdded', root)
    if key == 'gui' then
        for _, object in ipairs(root:GetDescendants()) do
            if object:IsA('RemoteFunction') then
                phowg:boxing_candidate(state, object)
            end
        end
    end
end
function phowg:update_boxing_machine()
    if
        Library.Unloaded
        or Data.SharedSignalsClosed
        or not (Toggles.boxing_machine_enabled and Toggles.boxing_machine_enabled.Value)
    then
        phowg:stop_boxing_machine()
        return
    end
    local state = Data.BoxingMachine
    if not state then
        state =
            { Entries = {}, Candidates = setmetatable({}, { __mode = 'k' }), Connections = {}, Roots = {}, Returns = 0 }
        Data.BoxingMachine = state
    end
    local mode = Options.boxing_machine_target and Options.boxing_machine_target.Value or 'both'
    local scoreRemote = MainEvent and MainEvent.Parent and MainEvent or ReplicatedStorage:FindFirstChild('MainEvent')
    if scoreRemote and state.ScoreRemote ~= scoreRemote then
        if state.Connections.Scores then
            state.Connections.Scores:Disconnect()
        end
        state.ScoreRemote = scoreRemote
        state.Connections.Scores = connectshared(scoreRemote.OnClientEvent, function(kind, label, value)
            if
                Data.BoxingMachine ~= state
                or (kind ~= 'SetArcadeMinigameScore' and kind ~= 'AnimateArcadeMinigameScore')
                or typeof(label) ~= 'Instance'
                or type(value) ~= 'number'
            then
                return
            end
            local machine = phowg:boxing_machine_kind(label)
            local selected = Options.boxing_machine_target and Options.boxing_machine_target.Value or 'both'
            if machine and (selected == 'both' or selected == machine) then
                state.GameScore = value
            end
        end, scoreRemote, 'boxing/game score acknowledgement', 0, 'event/OnClientEvent', scoreRemote)
    end
    local ignored = Workspace:FindFirstChild('Ignored')
    local arcade = ignored and ignored:FindFirstChild('ArcadeGames')
    phowg:bind_boxing_candidates(state, 'arcade', arcade)
    phowg:bind_boxing_candidates(state, 'gui', LocalPlayer:FindFirstChild('PlayerGui'))
    for _, name in ipairs({ 'RedPunchingMachine', 'BlackPunchingMachine' }) do
        local remote = arcade and arcade:FindFirstChild(name)
        for _, child in ipairs({ 'PunchingMachine', 'PunchingMachine', 'Frame', 'Handler', 'RemoteFunction' }) do
            remote = remote and remote:FindFirstChild(child)
        end
        phowg:boxing_candidate(state, remote)
    end
    for remote, entry in pairs(state.Entries) do
        local kind = state.Candidates[remote]
        if not remote.Parent or not kind or mode ~= 'both' and kind ~= mode then
            phowg:release_boxing_entry(entry)
            state.Entries[remote] = nil
        end
    end
    local ready, waiting, environments = 0, 0, 0
    for remote, kind in pairs(state.Candidates) do
        if not remote.Parent then
            state.Candidates[remote] = nil
            continue
        end
        if mode ~= 'both' and kind ~= mode then
            continue
        end
        local handler = remote.Parent
        if kind == 'copy' and not handler.Parent:FindFirstChild('Arrow') then
            continue
        end
        local readable, callback = phowg:read_boxing_callback(remote)
        local entry = state.Entries[remote]
        if entry and readable and callback ~= entry.Replacement then
            phowg:release_boxing_entry(entry)
            state.Entries[remote] = nil
            entry = nil
        end
        if not entry then
            entry = {
                Remote = remote,
                Handler = handler,
                Original = type(callback) == 'function' and callback or nil,
                Enabled = true,
            }
            entry.Replacement = function(...)
                if
                    entry.Enabled
                    and Data.BoxingMachine == state
                    and not Library.Unloaded
                    and not Data.SharedSignalsClosed
                    and Toggles.boxing_machine_enabled
                    and Toggles.boxing_machine_enabled.Value
                then
                    phowg:boxing_record_return(entry)
                    return phowg:boxing_score_value()
                end
                if entry.Original then
                    return entry.Original(...)
                end
                return nil
            end
            local assigned, problem = pcall(function()
                remote.OnClientInvoke = entry.Replacement
            end)
            if not assigned then
                entry.Enabled = false
                state.LastError = tostring(problem)
                waiting += 1
                continue
            end
            entry.Assigned = true
            state.Entries[remote] = entry
        elseif not readable then
            local assigned, problem = pcall(function()
                remote.OnClientInvoke = entry.Replacement
            end)
            if not assigned then
                state.LastError = tostring(problem)
                waiting += 1
                continue
            end
        end
        if phowg:bind_boxing_environment(entry) then
            environments += 1
        end
        ready += 1
    end
    local status = ready > 0
            and ('ready: ' .. ready .. ' callback' .. (ready == 1 and '' or 's') .. ' / ' .. environments .. ' live score environment' .. (environments == 1 and '' or 's'))
        or waiting > 0 and ('callback assignment failed: ' .. tostring(state.LastError or 'unavailable'))
        or 'waiting for boxing machine'
    phowg:boxing_status(status)
    if Data.BoxingReturnLabel then
        local text = state.LastReturn
                and ('last returned: ' .. string.format('%.0f', state.LastReturn) .. ' / ' .. state.Returns .. ' call' .. (state.Returns == 1 and '' or 's'))
            or 'no score requested yet'
        if state.GameScore then
            text = text .. ' / game reported: ' .. string.format('%.0f', state.GameScore)
        end
        if text ~= Data.BoxingReturnText then
            Data.BoxingReturnText = text
            Data.BoxingReturnLabel:SetText(text)
        end
    end
end
registerheartbeat('BoxingMachine', phowg.update_boxing_machine, 0.25, function()
    return Toggles.boxing_machine_enabled and Toggles.boxing_machine_enabled.Value
end)
phowg:register_cleanup('boxing machine', function(_, reason)
    if reason == 'unload' then
        phowg:stop_boxing_machine()
    end
end)

function phowg:gun_readiness(tool)
    local character = LocalPlayer.Character
    local humanoid = character and character:FindFirstChildOfClass('Humanoid')
    if not humanoid or humanoid.Health <= 0 or humanoid:GetState() == Enum.HumanoidStateType.Dead then
        return 'character unavailable'
    end
    if not tool then
        return 'not owned'
    end
    if tool.Parent ~= character then
        return 'not equipped'
    end
    if not character:FindFirstChild('FULLY_LOADED_CHAR') then
        return 'character loading'
    end
    if character:FindFirstChild('FORCEFIELD') then
        return 'forcefield'
    end
    if character:GetAttribute('BasketballTeam') or character:GetAttribute('BasketballZone') then
        return 'basketball active'
    end
    for _, name in ipairs({ 'GRABBING_CONSTRAINT', 'Christmas_Sock', '[CarHitBox]' }) do
        if character:FindFirstChild(name) then
            return name
        end
    end
    local body = character:FindFirstChild('BodyEffects')
    if not body then
        return 'body state unavailable'
    end
    for _, name in ipairs({ 'Cuff', 'Attacking', 'K.O', 'Grabbed', 'Dead' }) do
        local value = body:FindFirstChild(name)
        if
            value
            and value:IsA('ValueBase')
            and (value.Value == true or name == 'Grabbed' and value.Value ~= nil and value.Value ~= false)
        then
            return name
        end
    end
    if body:FindFirstChild('Block') then
        return 'blocking'
    end
    local ammo = tool:FindFirstChild('Ammo')
    if not ammo or type(ammo.Value) ~= 'number' then
        return 'ammo unavailable'
    end
    if ammo.Value <= 0 then
        return 'empty'
    end
    local reload = body:FindFirstChild('Reload')
    if
        reload
        and reload:IsA('BoolValue')
        and reload.Value
        and (reload:GetAttribute('ShellReload') ~= tool.Name or ammo.Value <= 0)
    then
        return 'reloading'
    end
    if
        workspace:GetAttribute('SERVER_AIM')
        or tool.Name == '[Flintlock]' and workspace:GetAttribute('FlintlockDisabled')
    then
        return 'disabled by game state'
    end
    if tool:GetAttribute('Cooldown') then
        return 'weapon cooldown'
    end
    local cooldown = tool:FindFirstChild('ShootingCooldown')
    local lastShot = tool:GetAttribute('LocalLastShotAt')
    if
        cooldown
        and type(cooldown.Value) == 'number'
        and type(lastShot) == 'number'
        and os.clock() - lastShot < cooldown.Value
    then
        return 'shot cooldown'
    end
    local previous = character:GetAttribute('LocalLastFiredGun')
    local previousAt = character:GetAttribute('LocalLastGunShotAt')
    local longSwitch = { ['[Deagle]'] = true, ['[Rifle]'] = true, ['[Glock]'] = true, ['[Silencer]'] = true }
    local switchDelay = longSwitch[previous] and longSwitch[tool.Name] and 0.5 or 0.1
    if previous ~= tool.Name and type(previousAt) == 'number' and os.clock() - previousAt < switchDelay then
        return 'weapon switch cooldown'
    end
    local serverGun = character:GetAttribute('LastFiredGun')
    local serverAt = character:GetAttribute('LastGunShotAt')
    local serverDelay = longSwitch[serverGun] and longSwitch[tool.Name] and 0.5 or 0.1
    if
        serverGun ~= tool.Name
        and type(serverAt) == 'number'
        and Workspace:GetServerTimeNow() - serverAt < serverDelay
    then
        return 'replicated switch cooldown'
    end
    return 'native checks ready'
end
function phowg:update_client_diagnostics()
    if
        not (Toggles.client_diagnostics and Toggles.client_diagnostics.Value)
        or not Library.MainVisible
        or not Data.StartupReady
    then
        return
    end
    local lines = { phowg:combat_diagnostics_text() }
    for _, name in ipairs(phowg:ragebot_gun_names()) do
        local tool = getweapontool(name)
        local ammo = tool and tool:FindFirstChild('Ammo')
        local reserve = tool and getgunreserve(tool)
        lines[#lines + 1] = name
            .. ': '
            .. phowg:gun_readiness(tool)
            .. (ammo and ' / ' .. tostring(ammo.Value) .. ' loaded' or '')
            .. (reserve ~= nil and ' / ' .. tostring(reserve) .. ' reserve' or '')
    end
    local owner = Data.NativeReloadOwner
    lines[#lines + 1] = 'reload owner: '
        .. (
            owner and (owner.Error and 'native coordination unavailable' or 'custom / native paused locally')
            or 'native setting'
        )
    if Data.GunReloadPending then
        lines[#lines + 1] = 'pending reload: ' .. Data.GunReloadPending.Tool.Name
    end
    local character = LocalPlayer.Character
    if Data.ClientBackpackModule and type(Data.ClientBackpackModule.GetSuppressReasons) == 'function' then
        local ok, reasons = pcall(Data.ClientBackpackModule.GetSuppressReasons)
        local names = {}
        if ok and type(reasons) == 'table' then
            for key, value in pairs(reasons) do
                if value then
                    names[#names + 1] = type(key) == 'number' and tostring(value) or tostring(key)
                end
            end
            table.sort(names)
        end
        lines[#lines + 1] = 'backpack: '
            .. (not ok and 'status unavailable' or #names > 0 and table.concat(names, ', ') or 'not suppressed')
    elseif not Data.ClientBackpackLoading and tick() >= (Data.ClientBackpackRetryAt or 0) then
        Data.ClientBackpackLoading = true
        phowg:queue_background('client compatibility', 'backpack status', function()
            local module = ReplicatedStorage:FindFirstChild('BackpackController')
            local ok, result = pcall(function()
                return module and require(module)
            end)
            if ok and type(result) == 'table' then
                Data.ClientBackpackModule = result
            end
            Data.ClientBackpackLoading = nil
            Data.ClientBackpackRetryAt = tick() + 5
        end)
    end
    local current = Data.CurrentActionTarget
    lines[#lines + 1] = 'action: '
        .. phowg:display_status()
        .. (current and ' / ' .. current.Name or '')
    lines[#lines + 1] = 'loaded: '
        .. tostring(character and character:FindFirstChild('FULLY_LOADED_CHAR') ~= nil or false)
    local text = table.concat(lines, '\n')
    if Data.ClientDiagnosticLabel and text ~= Data.ClientDiagnosticText then
        Data.ClientDiagnosticText = text
        Data.ClientDiagnosticLabel:SetText(text)
    end
end
registerheartbeat('ClientDiagnostics', phowg.update_client_diagnostics, 0.25, function()
    return Toggles.client_diagnostics and Toggles.client_diagnostics.Value and Library.MainVisible
end)
function phowg:bullet_visual_rate()
    return phowg:visual_number('bullet_visual_rate', 60, 10, 120)
end
function phowg:take_bullet_visual_budget()
    local now = tick()
    local rate = phowg:bullet_visual_rate()
    local burst = 8
    local state = Data.BulletVisualBudget
    if not state or state.Character ~= LocalPlayer.Character then
        state = { At = now, Tokens = burst, Character = LocalPlayer.Character }
        Data.BulletVisualBudget = state
    end
    state.Tokens = math.min(burst, state.Tokens + math.max(0, now - state.At) * rate)
    state.At = now
    if state.Tokens < 1 then
        return false
    end
    state.Tokens -= 1
    return true
end
function phowg:bullet_visual_interval()
    local state = Data.ChinaHackState
    local now = tick()
    local share = Data.BulletVisualShare
    if not share or now - share.At >= 0.2 or share.Character ~= LocalPlayer.Character then
        local count = 0
        if state and state.MultiTarget then
            for _, record in pairs(state.Guns or {}) do
                if record.Tool and record.Tool.Parent == LocalPlayer.Character then
                    count += 1
                end
            end
        end
        share = { At = now, Count = math.max(1, count), Character = LocalPlayer.Character }
        Data.BulletVisualShare = share
    end
    return math.max(1 / 30, share.Count / phowg:bullet_visual_rate())
end
function phowg:sync_native_gun_effects(stopping)
    local manual = stopping ~= true
            and not Library.Unloaded
            and not Data.SharedSignalsClosed
            and Toggles.reduce_native_gun_effects
            and Toggles.reduce_native_gun_effects.Value
        or false
    local enabled = manual
    local state = Data.NativeGunEffects
    if not enabled then
        Data.NativeGunEffects = nil
        if state then
            if state.Connection then
                state.Connection:Disconnect()
            end
            for player, saved in pairs(state.Foreign or {}) do
                if player.Parent and player:GetAttribute('GunFX') == true then
                    pcall(player.SetAttribute, player, 'GunFX', saved.Value)
                end
            end
            if state.Written and LocalPlayer:GetAttribute('GunFX') == true then
                pcall(LocalPlayer.SetAttribute, LocalPlayer, 'GunFX', state.Original)
            end
        end
        return
    end
    if not state then
        state = {
            Original = LocalPlayer:GetAttribute('GunFX'),
            Writing = false,
            Written = false,
            Foreign = setmetatable({}, { __mode = 'k' }),
        }
        Data.NativeGunEffects = state
        state.Connection = connectshared(LocalPlayer:GetAttributeChangedSignal('GunFX'), function()
            if Data.NativeGunEffects ~= state or state.Writing then
                return
            end
            local value = LocalPlayer:GetAttribute('GunFX')
            if value == true then
                return
            end
            state.Original = value
            phowg:sync_native_gun_effects()
        end, LocalPlayer, 'native gun effects ownership', 0, 'attribute/GunFX', LocalPlayer)
    end
    if not manual and state.ForeignEnabled then
        for player, saved in pairs(state.Foreign) do
            if player.Parent and player:GetAttribute('GunFX') == true then
                pcall(player.SetAttribute, player, 'GunFX', saved.Value)
            end
        end
        table.clear(state.Foreign)
    end
    state.ForeignEnabled = manual
    if LocalPlayer:GetAttribute('GunFX') ~= true then
        state.Writing = true
        local ok = pcall(LocalPlayer.SetAttribute, LocalPlayer, 'GunFX', true)
        state.Writing = false
        if ok then
            state.Written = true
        end
    end
end
registerheartbeat(
    'OtherNativeGunEffects',
    function()
        local state = Data.NativeGunEffects
        if not state or not state.ForeignEnabled then
            return
        end
        state.Foreign = state.Foreign or setmetatable({}, { __mode = 'k' })
        for _, player in ipairs(Players:GetPlayers()) do
            if player ~= LocalPlayer then
                local value = player:GetAttribute('GunFX')
                if value ~= true then
                    state.Foreign[player] = { Value = value }
                    pcall(player.SetAttribute, player, 'GunFX', true)
                end
            end
        end
    end,
    0.5,
    function()
        return Data.NativeGunEffects ~= nil and Data.NativeGunEffects.ForeignEnabled
    end
)
