function phowg:custom_camera_can_apply(camera)
    local character = LocalPlayer.Character
    local subject = camera and camera.CameraSubject
    if not character or not subject or (subject ~= character and not subject:IsDescendantOf(character)) then
        return false
    end
    if Data.SpectateActive then
        return false
    end
    if not Toggles.respect_native_cameras or Toggles.respect_native_cameras.Value then
        if
            camera.CameraType == Enum.CameraType.Scriptable
            or character:GetAttribute('BasketballTeam')
            or character:GetAttribute('BasketballZone')
        then
            return false
        end
    end
    return true
end
function phowg:set_custom_camera(enabled)
    local previous = Data.CustomCameraState
    Data.CustomCameraState = nil
    if previous then
        for _, connection in pairs(previous.Connections) do
            connection:Disconnect()
        end
    end
    if not enabled or Library.Unloaded or Data.SharedSignalsClosed then
        return
    end
    local state = { Connections = {}, Camera = nil :: any, Writing = false }
    Data.CustomCameraState = state
    local function apply()
        local camera = state.Camera
        if
            Data.CustomCameraState ~= state
            or state.Writing
            or not camera
            or camera ~= Workspace.CurrentCamera
            or not phowg:custom_camera_can_apply(camera)
            or camera.CameraType == Enum.CameraType.Custom
        then
            return
        end
        state.Writing = true
        camera.CameraType = Enum.CameraType.Custom
        state.Writing = false
    end
    local function bind()
        for _, key in ipairs({ 'Type', 'Subject' }) do
            if state.Connections[key] then
                state.Connections[key]:Disconnect()
                state.Connections[key] = nil
            end
        end
        state.Camera = Workspace.CurrentCamera
        if not state.Camera then
            return
        end
        state.Connections.Type = connectshared(
            state.Camera:GetPropertyChangedSignal('CameraType'),
            apply,
            state.Camera,
            'custom camera/type'
        )
        state.Connections.Subject = connectshared(
            state.Camera:GetPropertyChangedSignal('CameraSubject'),
            apply,
            state.Camera,
            'custom camera/subject'
        )
        apply()
    end
    state.Connections.Current = connectshared(
        Workspace:GetPropertyChangedSignal('CurrentCamera'),
        bind,
        Workspace,
        'custom camera/replaced',
        0,
        'property/CurrentCamera',
        Workspace
    )
    state.Connections.Character = connectshared(
        LocalPlayer.CharacterAdded,
        bind,
        LocalPlayer,
        'custom camera/respawn',
        0,
        'event/CharacterAdded',
        LocalPlayer
    )
    bind()
end
phowg:register_cleanup('custom camera', function(_, reason)
    if reason == 'unload' then
        phowg:set_custom_camera(false)
    end
end)

function phowg:capture_minigame_hud(gui)
    local snapshot = {}
    local main = gui:FindFirstChild('MainScreenGui')
    if main then
        for _, name in ipairs({ 'Bar', 'Energy', 'Health', 'Armor', 'Hotbar', 'ToolBar', 'BottomBar' }) do
            local object = main:FindFirstChild(name, true)
            if object and object:IsA('GuiObject') then
                snapshot[#snapshot + 1] = { Object = object, Property = 'Visible', Before = object.Visible }
            end
        end
    end
    for _, name in ipairs({ 'Satchel', 'Backpack' }) do
        local object = gui:FindFirstChild(name)
        if object and object:IsA('ScreenGui') then
            snapshot[#snapshot + 1] = { Object = object, Property = 'Enabled', Before = object.Enabled }
        end
    end
    return snapshot
end
function phowg:restore_minigame_hud(state, snapshot)
    if
        Data.MinigameHUD ~= state
        or Library.Unloaded
        or Data.SharedSignalsClosed
        or not (Toggles.preserve_minigame_hud and Toggles.preserve_minigame_hud.Value)
        or next(state.Active)
    then
        return
    end
    for _, item in ipairs(snapshot or {}) do
        local object = item.Object
        if
            item.Before == false
            and object.Parent
            and object:IsDescendantOf(state.Gui)
            and object[item.Property] == true
        then
            object[item.Property] = false
        end
    end
end
function phowg:stop_minigame_hud()
    local state = Data.MinigameHUD
    Data.MinigameHUD = nil
    if not state then
        return
    end
    for _, connection in pairs(state.Connections) do
        connection:Disconnect()
    end
    for _, entry in pairs(state.Active) do
        if entry.Connection then
            entry.Connection:Disconnect()
        end
    end
end
function phowg:update_minigame_hud()
    if
        Library.Unloaded
        or Data.SharedSignalsClosed
        or not (Toggles.preserve_minigame_hud and Toggles.preserve_minigame_hud.Value)
    then
        phowg:stop_minigame_hud()
        return
    end
    local gui = LocalPlayer:FindFirstChild('PlayerGui')
    local state = Data.MinigameHUD
    if state and state.Gui ~= gui then
        phowg:stop_minigame_hud()
        state = nil
    end
    if not gui then
        return
    end
    local now = tick()
    if not state then
        state = {
            Gui = gui,
            Connections = {},
            Candidates = {},
            Active = {},
            Seen = setmetatable({}, { __mode = 'k' }),
            Baseline = nil :: any,
            BaselineAt = 0,
        }
        Data.MinigameHUD = state
        state.Connections.Added = connectshared(gui.DescendantAdded, function(object)
            if Data.MinigameHUD ~= state then
                return
            end
            local handler = object:IsA('LocalScript') and object.Name == 'Handler' and object
                or object:IsA('RemoteFunction') and object.Parent
            if handler and handler.Name == 'Handler' and not state.Seen[handler] and not state.Candidates[handler] then
                state.Candidates[handler] = { At = tick(), Until = tick() + 2, Snapshot = state.Baseline }
            end
        end, gui, 'minigame HUD/handler added', 0, 'event/DescendantAdded', gui)
        for _, object in ipairs(gui:GetDescendants()) do
            if object:IsA('LocalScript') and object.Name == 'Handler' then
                state.Candidates[object] = { At = 0, Until = now + 2, Snapshot = nil }
            end
        end
    end
    for handler, candidate in pairs(state.Candidates) do
        local frame = handler.Parent
        local bar = frame and frame:FindFirstChild('Bar')
        local identified = bar
            and frame:FindFirstChild('Feed')
            and frame:FindFirstChild('Instr')
            and bar:FindFirstChild('Needle')
            and bar:FindFirstChild('Perfect')
            and bar:FindFirstChild('Sweet')
        if identified then
            state.Candidates[handler] = nil
            state.Seen[handler] = true
            local entry: { Snapshot: any, Connection: RBXScriptConnection? } =
                { Snapshot = candidate.At >= state.BaselineAt and candidate.Snapshot or nil }
            state.Active[handler] = entry
            entry.Connection = handler.Destroying:Connect(function()
                if Data.MinigameHUD ~= state then
                    return
                end
                state.Active[handler] = nil
                if entry.Connection then
                    entry.Connection:Disconnect()
                    entry.Connection = nil
                end
                local snapshot = entry.Snapshot
                task.defer(function()
                    phowg:restore_minigame_hud(state, snapshot)
                end)
            end)
        elseif not frame or now >= candidate.Until then
            state.Candidates[handler] = nil
            state.Seen[handler] = true
        end
    end
    if not next(state.Active) and not next(state.Candidates) then
        state.Baseline = phowg:capture_minigame_hud(gui)
        state.BaselineAt = now
    end
end
