function phowg:load_world_leak_model(definition)
    local asset = getcustomasset or getsynasset
    if type(asset) ~= 'function' then
        return nil, 'Local model loading is not supported by this executor'
    end
    if type(isfile) == 'function' then
        local ok, exists = pcall(isfile, definition.File)
        if not ok or not exists then
            return nil, 'Model file missing from executor workspace: ' .. definition.File
        end
    end
    local ok, objects = pcall(function()
        return game:GetObjects(asset(definition.File))
    end)
    if not ok then
        return nil, tostring(objects)
    end
    if type(objects) ~= 'table' then
        return nil, 'The model file did not return any instances'
    end
    local model
    if #objects == 1 and typeof(objects[1]) == 'Instance' and objects[1]:IsA('Model') then
        model = objects[1]
    end
    if not model then
        for _, object in pairs(objects) do
            if typeof(object) == 'Instance' then
                object:Destroy()
            end
        end
        return nil, 'Expected one complete model in ' .. definition.File
    end
    return model
end
function phowg:set_world_leak(key, enabled)
    Data.WorldLeakRevisions = Data.WorldLeakRevisions or {}
    local revision = (Data.WorldLeakRevisions[key] or 0) + 1
    Data.WorldLeakRevisions[key] = revision
    if not enabled then
        return phowg:restore_world_leak(key)
    end
    if Library.Unloaded or Data.WorldLeakImportsClosed then
        return false
    end
    local definition = Data.WorldLeakDefinitions[key]
    if not definition then
        return false
    end
    Data.WorldLeaks = Data.WorldLeaks or {}
    local state = Data.WorldLeaks[key]
    if not state then
        if definition.File then
            Data.WorldLeakImports = Data.WorldLeakImports or {}
            state = Data.WorldLeakImports[key]
            if not state then
                local source, problem = phowg:load_world_leak_model(definition)
                if Library.Unloaded or Data.WorldLeakImportsClosed or Data.WorldLeakRevisions[key] ~= revision then
                    if source then
                        source:Destroy()
                    end
                    return true
                end
                if not source then
                    Library:Notify('World prop unavailable: ' .. tostring(problem), 4)
                    return false
                end
                local ok, pivot = pcall(function()
                    local originalPivot = source:GetPivot()
                    source.Parent = ReplicatedStorage
                    return originalPivot
                end)
                if not ok then
                    source:Destroy()
                    Library:Notify('World prop could not be loaded: ' .. tostring(pivot), 3)
                    return false
                end
                state = { Instance = source, Parent = ReplicatedStorage, Pivot = pivot }
                Data.WorldLeakImports[key] = state
            end
        else
            local source = ReplicatedStorage
            for _, name in ipairs(definition.Path) do
                source = source and source:FindFirstChild(name)
            end
            if not source or definition.Position and not source:IsA('Model') then
                Library:Notify('World prop unavailable: ' .. definition.Path[#definition.Path], 3)
                return false
            end
            local ok, pivot = pcall(function()
                return definition.Position and source:GetPivot() or nil
            end)
            if not ok then
                Library:Notify('World prop could not be positioned', 3)
                return false
            end
            state = { Instance = source, Parent = source.Parent, Pivot = pivot }
        end
        Data.WorldLeaks[key] = state
    end
    local ok, problem = pcall(function()
        state.Instance.Parent = Workspace
        if definition.Position then
            state.Instance:PivotTo(CFrame.new(definition.Position) * state.Pivot.Rotation)
        end
        if key == 'admin_base' then
            phowg:set_admin_base_passage(true)
        end
    end)
    if not ok then
        phowg:restore_world_leak(key)
        Library:Notify('World prop failed: ' .. tostring(problem), 3)
    end
    return ok
end
phowg:register_cleanup('world leaks', function(scope)
    if scope then
        return
    end
    Data.WorldLeakImportsClosed = true
    phowg:set_admin_base_passage(false)
    for key in pairs(Data.WorldLeaks or {}) do
        phowg:restore_world_leak(key)
    end
    for key, state in pairs(Data.WorldLeakImports or {}) do
        state.Instance:Destroy()
        Data.WorldLeakImports[key] = nil
    end
end)
function phowg:new_rain_splash()
    local entry = phowg:new_jump_circle()
    local drop = Instance.new('Part')
    drop.Name, drop.Anchored, drop.CastShadow = 'PhowgRainDrop', true, false
    drop.CanCollide, drop.CanTouch, drop.CanQuery = false, false, false
    drop.Material, drop.Transparency = Enum.Material.Neon, 0.35
    drop.Size = Vector3.new(0.025, 0.55, 0.025)
    entry.Part = drop
    return entry
end
function phowg:clear_rain_splashes()
    Data.RainSplashFilter = nil
    Data.RainSplashElapsed = 0
    local pool = Data.EffectPools and Data.EffectPools.rainsplash
    if pool then
        for index = #pool.Active, 1, -1 do
            phowg:return_effect(pool.Active[index])
        end
    end
end
function phowg:animate_rain_splash(entry, age)
    local elapsed = age - entry.Delay
    if elapsed < 0 then
        local progress = math.clamp(age / entry.Delay, 0, 1)
        entry.Part.CFrame =
            CFrame.new(entry.Origin + (entry.Impact - entry.Origin) * progress + Vector3.new(0, 0.275, 0))
        return
    end
    entry.Part.Parent = nil
    if not entry.Model.Parent then
        entry.Model.Parent = Workspace:FindFirstChild('Ignored') or Workspace
    end
    local progress = math.clamp(elapsed / entry.FadeTime, 0, 1)
    local scale = Library.ReducedMotion and 1 or 0.1 + 0.9 * (1 - (1 - progress) ^ 2)
    local diameter = entry.Radius * 2 * scale
    entry.Model.Size = Vector3.new(diameter, 0.02, diameter)
    local visibility = math.min(1, elapsed / 0.025) * (1 - progress) ^ 1.5
    entry.Rings[1].Stroke.Transparency = 1 - visibility * 0.08
    entry.Rings[2].Stroke.Transparency = 1 - visibility * 0.65
    entry.Rings[3].Stroke.Transparency = 1 - visibility * 0.25
    entry.Rings[3].Frame.Size = UDim2.fromScale(0.65, 0.65)
end
function phowg:update_rain_splashes(dt, camera)
    if Data.WorldWeatherType ~= 'Light Rain' or not phowg:toggle_enabled('world_weather') then
        return
    end
    local rate = phowg:visual_number('world_weather_rate', 100, 0, 200)
    if rate <= 0 then
        return
    end
    local interval = 1 / (24 * rate / 100)
    local elapsed = math.min((Data.RainSplashElapsed or 0) + dt, interval * 2)
    Data.RainSplashElapsed = elapsed % interval
    local count = math.min(2, math.floor(elapsed / interval))
    if count == 0 then
        return
    end
    local ignored = Workspace:FindFirstChild('Ignored')
    local playersFolder = Workspace:FindFirstChild('Players')
    local filter = Data.RainSplashFilter
    if
        not filter
        or filter.Camera ~= camera
        or filter.Weather ~= Data.WorldWeatherPart
        or filter.Players ~= playersFolder
        or filter.Ignored ~= ignored
        or filter.Character ~= LocalPlayer.Character
        or not playersFolder and tick() >= filter.Expires
    then
        local params = RaycastParams.new()
        params.FilterType, params.RespectCanCollide, params.IgnoreWater = Enum.RaycastFilterType.Exclude, true, true
        local excluded = { Data.WorldWeatherPart, camera }
        if ignored then
            excluded[#excluded + 1] = ignored
        end
        if playersFolder then
            excluded[#excluded + 1] = playersFolder
        end
        for _, player in ipairs(Players:GetPlayers()) do
            local body = player.Character
            if body and (not playersFolder or not body:IsDescendantOf(playersFolder)) then
                excluded[#excluded + 1] = body
            end
        end
        params.FilterDescendantsInstances = excluded
        filter = {
            Camera = camera,
            Weather = Data.WorldWeatherPart,
            Players = playersFolder,
            Ignored = ignored,
            Character = LocalPlayer.Character,
            Params = params,
            Expires = tick() + 0.5,
        }
        Data.RainSplashFilter = filter
    end
    local params = filter.Params
    for _ = 1, count do
        local angle, radius = math.random() * math.pi * 2, math.sqrt(math.random()) * 24
        local origin = camera.CFrame.Position + Vector3.new(math.cos(angle) * radius, 25, math.sin(angle) * radius)
        local hit = Workspace:Raycast(origin, Vector3.new(0, -100, 0), params)
        if not hit or hit.Normal.Y <= 0.2 or not phowg:cosmetic_visible(hit.Position) then
            continue
        end
        local entry = phowg:get_effect('rainsplash', 12, phowg.new_rain_splash, 96)
        if not entry then
            break
        end
        entry.Character = nil
        entry.Origin, entry.Impact = origin, hit.Position
        entry.Model.Parent, entry.Model.CFrame = nil, phowg:ground_ring_c_frame(hit)
        entry.Delay, entry.FadeTime = (origin - hit.Position).Magnitude / (30 + math.random() * 20), 0.45
        entry.Lifetime, entry.Radius = entry.Delay + entry.FadeTime, 0.35 + math.random() * 0.35
        entry.Surface.MaxDistance = phowg:visual_number('cosmetic_distance', 1000, 100, 5000)
        phowg:set_ground_ring_color(
            entry,
            Options.world_weather_color and Options.world_weather_color.Value or Color3.new(1, 1, 1)
        )
        for _, ring in ipairs(entry.Rings) do
            ring.Stroke.Transparency = 1
        end
        entry.Part.Color = entry.Stroke.Color
        entry.Part.CFrame = CFrame.new(origin + Vector3.new(0, 0.275, 0))
        entry.Part.Parent = ignored or Workspace
        entry.Update = phowg_callbacks.animate_rain_splash
    end
end
function phowg:clear_world_weather()
    phowg:clear_rain_splashes()
    if Data.WorldWeatherPart then
        Data.WorldWeatherPart:Destroy()
    end
    Data.WorldWeatherPart, Data.WorldWeatherEmitter, Data.WorldWeatherType = nil, nil, nil
end
function phowg:update_world_weather()
    if phowg:defer_config_effect('weather', phowg.update_world_weather) then return end
    phowg:clear_rain_splashes()
    if Library.Unloaded or not (Toggles.world_weather and Toggles.world_weather.Value) then
        phowg:clear_world_weather()
        phowg:update_world_visual_connection()
        return
    end
    local kind = Options.world_weather_type and Options.world_weather_type.Value or 'Rain'
    local properties = Data.WorldWeatherTypes[kind] or Data.WorldWeatherTypes.Rain
    if not Data.WorldWeatherPart then
        local part = Instance.new('Part')
        part.Name, part.Size, part.Transparency, part.Anchored = 'PhowgWeather', Vector3.new(60, 4, 60), 1, true
        part.CanCollide, part.CanTouch, part.CanQuery, part.CastShadow = false, false, false, false
        local camera = Workspace.CurrentCamera
        part.CFrame = CFrame.new(camera and camera.CFrame.Position + Vector3.new(0, 25, 0) or Vector3.new(0, 25, 0))
        part.Parent = Workspace
        Data.WorldWeatherPart = part
    end
    if not Data.WorldWeatherEmitter or Data.WorldWeatherType ~= kind then
        if Data.WorldWeatherEmitter then
            Data.WorldWeatherEmitter:Destroy()
        end
        local emitter = Instance.new('ParticleEmitter')
        for property, value in pairs(properties) do
            emitter[property] = value
        end
        emitter.Name, emitter.Enabled, emitter.LightInfluence = 'PhowgWeatherEmitter', kind ~= 'Light Rain', 0
        if kind == 'Snow' then
            emitter.Lifetime = NumberRange.new(2, 3)
        end
        emitter.Parent = Data.WorldWeatherPart
        Data.WorldWeatherEmitter, Data.WorldWeatherType = emitter, kind
        phowg:queue_assets({ properties.Texture })
    end
    Data.WorldWeatherEmitter.Color = ColorSequence.new(
        Options.world_weather_color and Options.world_weather_color.Value or Color3.fromRGB(255, 136, 0)
    )
    Data.WorldWeatherEmitter.Rate = properties.Rate * phowg:visual_number('world_weather_rate', 100, 0, 200) / 100
    phowg:update_world_visual_connection()
end
function phowg:clear_world_color_correction()
    local effect = Data.WorldColorCorrection
    Data.WorldColorCorrection = nil
    if effect then
        effect:Destroy()
    end
end
function phowg:sync_world_color_correction()
    if phowg:defer_config_effect('world correction', phowg.sync_world_color_correction) then return end
    local contrast = phowg:toggle_enabled('contrast_changer')
    local brightness = phowg:toggle_enabled('correction_brightness_changer')
    if Library.Unloaded or Data.SharedSignalsClosed or not (contrast or brightness) then
        phowg:clear_world_color_correction()
        return
    end
    local effect = Data.WorldColorCorrection
    if not effect or effect.Parent ~= Service.Lighting then
        phowg:clear_world_color_correction()
        effect = Instance.new('ColorCorrectionEffect')
        effect.Name = 'PhowgColorCorrection'
        Data.WorldColorCorrection = effect
        effect.Parent = Service.Lighting
    end
    effect.Contrast = contrast and phowg:visual_number('contrast_changer_value', 0, -1, 1) or 0
    effect.Brightness = brightness and phowg:visual_number('correction_brightness_value', 0, -1, 1) or 0
end
phowg:register_cleanup('world color correction', function(scope)
    if not scope then
        phowg:clear_world_color_correction()
    end
end)
function phowg:clear_motion_blur()
    if Data.MotionBlur then
        Data.MotionBlur:Destroy()
    end
    Data.MotionBlur, Data.MotionBlurLook, Data.MotionBlurSize = nil, nil, nil
end
function phowg:world_visual_tick(dt)
    local camera = Workspace.CurrentCamera
    if not camera then
        return
    end
    if Data.WorldWeatherPart and not Data.WorldWeatherPart.Parent then
        phowg:clear_world_weather()
        phowg:update_world_weather()
    end
    if Data.WorldWeatherPart then
        Data.WorldWeatherPart.CFrame = CFrame.new(camera.CFrame.Position + Vector3.new(0, 25, 0))
        phowg:update_rain_splashes(dt, camera)
    end
    if Data.WorldSkyActive then
        phowg:apply_world_sky()
    end
    if Data.MotionBlur then
        local look = camera.CFrame.LookVector
        local previous = Data.MotionBlurLook or look
        local speed = (look - previous).Magnitude / math.max(dt, 0.0001)
        local target = math.clamp(speed * phowg:visual_number('world_motion_blur_intensity', 10, 0, 100) * 0.05, 0, 56)
        local size = (Data.MotionBlurSize or 0) + (target - (Data.MotionBlurSize or 0)) * (1 - math.exp(-30 * dt))
        Data.MotionBlur.Size, Data.MotionBlurSize, Data.MotionBlurLook = size, size, look
    end
end
function phowg:update_world_visual_connection()
    if not Library.Unloaded and (Data.WorldWeatherPart or Data.MotionBlur or Data.WorldSkyActive) then
        if not Data.WorldVisualConnection then
            Data.WorldVisualConnection = create_connection(
                'WorldVisuals',
                phowg:register_render(phowg_callbacks.world_visual_tick, RunService, 'world/weather and blur')
            )
        end
    elseif Data.WorldVisualConnection then
        Data.WorldVisualConnection:Disconnect()
        Data.WorldVisualConnection = nil
    end
end
function phowg:update_motion_blur()
    if not Library.Unloaded and Toggles.world_motion_blur and Toggles.world_motion_blur.Value then
        if not Data.MotionBlur then
            Data.MotionBlur = Instance.new('BlurEffect')
            Data.MotionBlur.Name, Data.MotionBlur.Size, Data.MotionBlur.Parent = 'PhowgMotionBlur', 0, Service.Lighting
        end
    else
        phowg:clear_motion_blur()
    end
    phowg:update_world_visual_connection()
end
function phowg:clear_map_textures()
    local state = Data.MapTextureState
    Data.MapTextureState = nil
    if not state then
        return
    end
    for _, connection in ipairs(state.Connections) do
        connection:Disconnect()
    end
    for part, saved in pairs(state.Parts) do
        pcall(function()
            if part.MaterialVariant == saved.Applied then
                part.MaterialVariant = saved.Variant
                if part.Material == saved.AppliedMaterial then
                    part.Material = saved.Material
                end
            end
            if part.Color == saved.AppliedColor then
                part.Color = saved.Color
            end
            if saved.Texture ~= nil and part.TextureID == '' then
                part.TextureID = saved.Texture
            end
            if saved.PhysicalChanged and part.CustomPhysicalProperties == saved.AppliedPhysical then
                part.CustomPhysicalProperties = saved.Physical
            end
        end)
    end
    for object, saved in pairs(state.Decorations) do
        pcall(function()
            if saved.Surface then
                if object.Parent == nil and saved.Parent and saved.Parent.Parent then
                    object.Parent = saved.Parent
                end
            elseif object.Transparency == 1 then
                object.Transparency = saved.Transparency
            end
        end)
    end
    local service = game:GetService('MaterialService')
    for material, previous in pairs(state.Overrides) do
        pcall(function()
            if service:GetBaseMaterialOverride(material) == state.Variants[material].Name then
                service:SetBaseMaterialOverride(material, previous)
            end
        end)
    end
    for _, variant in pairs(state.Variants) do
        variant:Destroy()
    end
end
function phowg:update_map_textures()
    phowg:clear_map_textures()
    if Library.Unloaded or not (Toggles.world_map_textures and Toggles.world_map_textures.Value) then
        return
    end
    local service = game:GetService('MaterialService')
    local theme = Options.world_map_texture_theme and Options.world_map_texture_theme.Value or 'minecraft'
    local state = {
        Parts = setmetatable({}, { __mode = 'k' }),
        Variants = {},
        Overrides = {},
        Decorations = {},
        Connections = {},
    }
    Data.MapTextureState = state
    local assets = {}
    for _, entry in ipairs(Data.MapTextureThemes[theme] or {}) do
        local variant = Instance.new('MaterialVariant')
        variant.Name, variant.BaseMaterial = 'PhowgMap_' .. entry[1], Enum.Material[entry[1]]
        local asset = tostring(entry[2])
        if not string.find(asset, 'rbxasset', 1, true) and not string.find(asset, 'http', 1, true) then
            asset = 'rbxassetid://' .. asset
        end
        variant.ColorMap, variant.StudsPerTile = asset, phowg:visual_number('world_map_texture_tile', 5, 1, 30)
        variant.Parent = service
        state.Variants[variant.BaseMaterial] = variant
        assets[#assets + 1] = variant.ColorMap
        pcall(function()
            local previous = service:GetBaseMaterialOverride(variant.BaseMaterial)
            service:SetBaseMaterialOverride(variant.BaseMaterial, variant.Name)
            state.Overrides[variant.BaseMaterial] = previous
        end)
    end
    local function decoration(object)
        if state.Decorations[object] or not state.Parts[object.Parent] then
            return
        end
        if object:IsA('SurfaceAppearance') then
            state.Decorations[object] = { Surface = true, Parent = object.Parent }
            object.Parent = nil
        elseif object:IsA('Decal') or object:IsA('Texture') then
            state.Decorations[object] = { Transparency = object.Transparency }
            object.Transparency = 1
        end
    end
    local function map_part(part)
        if not part.Anchored or part.Transparency >= 1 then
            return false
        end
        local parent = part.Parent
        while parent and parent ~= Workspace do
            if
                parent == LocalPlayer.Character
                or parent:IsA('Camera')
                or parent:IsA('Tool')
                or parent:IsA('Accessory')
                or parent.Name == 'Players'
                or parent.Name == 'Vehicles'
                or parent.Name == 'Ignored'
                or parent:IsA('Model') and parent:FindFirstChildOfClass('Humanoid')
            then
                return false
            end
            parent = parent.Parent
        end
        return parent == Workspace
    end
    local function apply(object)
        if Data.MapTextureState ~= state then
            return
        end
        if not object:IsA('BasePart') then
            pcall(decoration, object)
            return
        end
        if state.Parts[object] or not map_part(object) then
            return
        end
        local variant = state.Variants[object.Material]
            or state.Variants[Enum.Material.Concrete]
            or state.Variants[Enum.Material.Slate]
            or state.Variants[Enum.Material.Wood]
        if not variant then
            return
        end
        pcall(function()
            local saved: { [string]: any } = {
                Variant = object.MaterialVariant,
                Material = object.Material,
                Color = object.Color,
                Applied = variant.Name,
                AppliedMaterial = variant.BaseMaterial,
                AppliedColor = Color3.new(1, 1, 1),
            }
            if object:IsA('MeshPart') then
                saved.Texture = object.TextureID
            end
            if object.Material ~= variant.BaseMaterial then
                saved.Physical, saved.AppliedPhysical =
                    object.CustomPhysicalProperties, object.CurrentPhysicalProperties
                saved.PhysicalChanged = saved.AppliedPhysical ~= nil
            end
            state.Parts[object] = saved
            if saved.PhysicalChanged then
                object.CustomPhysicalProperties = saved.AppliedPhysical
            end
            object.Material, object.MaterialVariant, object.Color =
                saved.AppliedMaterial, saved.Applied, saved.AppliedColor
            if saved.Texture ~= nil then
                object.TextureID = ''
            end
            for _, child in ipairs(object:GetChildren()) do
                decoration(child)
            end
        end)
    end
    state.Connections[1] = connectshared(
        Workspace.DescendantAdded,
        apply,
        Workspace,
        'world/map appearance added',
        0,
        'event/DescendantAdded',
        Workspace
    )
    task.spawn(function()
        for index, object in ipairs(Workspace:GetDescendants()) do
            if Data.MapTextureState ~= state then
                return
            end
            apply(object)
            if index % 128 == 0 then
                RunService.Heartbeat:Wait()
            end
        end
    end)
    phowg:queue_assets(assets)
end
function phowg:clear_world_sky()
    Data.WorldSkyActive = nil
    for sky, state in pairs(Data.WorldSkyOriginals or {}) do
        pcall(function()
            if state.Created then
                sky:Destroy()
                return
            end
            for property, original in pairs(state.Original) do
                if sky[property] == state.Applied[property] then
                    sky[property] = original
                end
            end
        end)
    end
    Data.WorldSkyOriginals = nil
end
function phowg:apply_world_sky()
    if not Data.WorldSkyActive then
        return
    end
    local selected = Options.skybox_changer_value and Options.skybox_changer_value.Value or 'default'
    local preset = Data.SkyboxPresets[selected] or Data.SkyboxPresets.default
    if selected == 'custom' then
        local id = tostring(Data.CustomSkyboxText or '')
        if id ~= '' then
            if not string.find(id, 'rbxasset', 1, true) and not string.find(id, 'http', 1, true) then
                id = 'rbxassetid://' .. id
            end
            preset = { Bk = id, Dn = id, Ft = id, Lf = id, Rt = id, Up = id }
        end
    end
    local skies = {}
    for _, child in ipairs(Service.Lighting:GetChildren()) do
        if child:IsA('Sky') then
            skies[#skies + 1] = child
        end
    end
    local created
    if #skies == 0 then
        created = Instance.new('Sky')
        created.Name, created.Parent = 'PhowgSky', Service.Lighting
        skies[1] = created
    end
    Data.WorldSkyOriginals = Data.WorldSkyOriginals or setmetatable({}, { __mode = 'k' })
    for _, sky in ipairs(skies) do
        local state = Data.WorldSkyOriginals[sky]
        if not state then
            state = { Original = {}, Applied = {}, Created = sky == created }
            Data.WorldSkyOriginals[sky] = state
        end
        for _, face in ipairs({ 'Bk', 'Dn', 'Ft', 'Lf', 'Rt', 'Up' }) do
            local property = 'Skybox' .. face
            if state.Original[property] == nil then
                state.Original[property] = sky[property]
            end
            state.Applied[property] = preset[face]
            if sky[property] ~= preset[face] then
                sky[property] = preset[face]
            end
        end
    end
end
function phowg:update_world_sky()
    if Library.Unloaded or not (Toggles.skybox_changer and Toggles.skybox_changer.Value) then
        phowg:clear_world_sky()
    else
        Data.WorldSkyActive = true
        phowg:apply_world_sky()
    end
    phowg:update_world_visual_connection()
end
phowg:register_cleanup('sample world visuals', function(_, reason)
    if reason ~= 'unload' then
        return
    end
    phowg:clear_world_weather()
    phowg:clear_motion_blur()
    phowg:clear_map_textures()
    phowg:clear_world_sky()
    phowg:update_world_visual_connection()
end)

Data.NameSpoofOriginal = { Username = LocalPlayer.Name, DisplayName = LocalPlayer.DisplayName }
function phowg:name_spoof_text(text, username, displayName)
    local source = Data.NameSpoofOriginal
    local tokens = { { source.Username, username }, { source.DisplayName, displayName } }
    table.sort(tokens, function(a, b)
        return #a[1] > #b[1]
    end)
    local lower, out, index = text:lower(), {}, 1
    while index <= #text do
        local matched
        for _, token in ipairs(tokens) do
            local old = token[1]
            if #old > 0 and lower:sub(index, index + #old - 1) == old:lower() then
                local before, after = text:sub(index - 1, index - 1), text:sub(index + #old, index + #old)
                if (index == 1 or not before:match('[%w_]')) and (after == '' or not after:match('[%w_]')) then
                    out[#out + 1], index, matched = token[2], index + #old, true
                    break
                end
            end
        end
        if not matched then
            out[#out + 1] = text:sub(index, index)
            index = index + 1
        end
    end
    return table.concat(out)
end
function phowg:stop_name_spoof()
    local state = Data.NameSpoofState
    if not state then
        return
    end
    Data.NameSpoofState = nil
    for _, connection in ipairs(state.Connections) do
        connection:Disconnect()
    end
    for object, properties in pairs(state.Originals) do
        for property, record in pairs(properties) do
            pcall(function()
                if object[property] == record.Applied then
                    object[property] = record.Original
                end
            end)
        end
    end
end
function phowg:avatar_spoof_image(value, state)
    local mode = state.ImageMode
    if mode == 'unchanged' then
        return nil
    end
    local lower = value:lower()
    if lower:find('rbxthumb://type=avatar', 1, true) == 1 then
        local id = tonumber(lower:match('[?&]id=(%d+)'))
        if id ~= LocalPlayer.UserId then
            return nil
        end
        if mode == 'hide' then
            return ''
        end
        if not state.AvatarUserId then
            return nil
        end
        return (
            value:gsub('([?&][iI][dD]=)(%d+)', function(prefix, current)
                return prefix .. (tonumber(current) == LocalPlayer.UserId and tostring(state.AvatarUserId) or current)
            end, 1)
        )
    end
    local cache = Data.AvatarThumbnailSources
    local source = cache and cache.Images[value]
    if not source then
        return nil
    end
    if mode == 'hide' then
        return ''
    end
    if not state.AvatarUserId then
        return nil
    end
    local key = tostring(state.AvatarUserId) .. ':' .. source.Key
    local targets = Data.AvatarThumbnailTargets or {}
    Data.AvatarThumbnailTargets = targets
    if targets[key] then
        return targets[key]
    end
    if not state.ThumbnailRequests[key] then
        state.ThumbnailRequests[key] = true
        phowg:queue_background('avatar thumbnail target', { State = state, Key = key }, function()
            local ok, image, ready =
                pcall(Players.GetUserThumbnailAsync, Players, state.AvatarUserId, source.Type, source.Size)
            state.ThumbnailRequests[key] = nil
            if Data.NameSpoofState ~= state or Library.Unloaded then
                return
            end
            if ok and ready and type(image) == 'string' and image ~= '' then
                targets[key] = image
                phowg:queue_assets({ image })
                state.UpdateImages()
            end
        end)
    end
    return nil
end
function phowg:warm_avatar_thumbnails()
    local cache = Data.AvatarThumbnailSources
    if not cache then
        cache = { Images = {}, Complete = false }
        Data.AvatarThumbnailSources = cache
    end
    if cache.Complete then
        return
    end
    phowg:queue_background('avatar thumbnail source', cache, function()
        local complete = true
        for _, kind in ipairs(Enum.ThumbnailType:GetEnumItems()) do
            for _, size in ipairs(Enum.ThumbnailSize:GetEnumItems()) do
                if Library.Unloaded or Data.AvatarThumbnailSources ~= cache then
                    return
                end
                local ok, image, ready = pcall(Players.GetUserThumbnailAsync, Players, LocalPlayer.UserId, kind, size)
                if ok and ready and type(image) == 'string' and image ~= '' then
                    cache.Images[image] = { Type = kind, Size = size, Key = kind.Name .. ':' .. size.Name }
                else
                    complete = false
                end
            end
        end
        cache.Complete = complete
        local current = Data.NameSpoofState
        if current and current.UpdateImages then
            current.UpdateImages()
        end
    end)
end
function phowg:refresh_name_spoof()
    phowg:stop_name_spoof()
    if Library.Unloaded or not (Toggles.avatar_spoof_enabled and Toggles.avatar_spoof_enabled.Value) then
        return
    end
    local names = Toggles.avatar_spoof_name and Toggles.avatar_spoof_name.Value
    local imageMode = Options.avatar_spoof_thumbnail and Options.avatar_spoof_thumbnail.Value or 'unchanged'
    if not names and imageMode == 'unchanged' then
        return
    end
    local identity = Data.AvatarSpoof and Data.AvatarSpoof.Identity
    local copy = Toggles.avatar_spoof_copy_name and Toggles.avatar_spoof_copy_name.Value
    local username = copy and identity and identity.Username
        or not copy and Options.avatar_spoof_custom_name and Options.avatar_spoof_custom_name.Value
    if type(username) ~= 'string' or not username:match('%S') then
        names = false
        username = Data.NameSpoofOriginal.Username
    end
    local display = copy and identity and identity.DisplayName
        or Options.avatar_spoof_custom_display and Options.avatar_spoof_custom_display.Value
    if type(display) ~= 'string' or not display:match('%S') then
        display = username
    end
    local state: { [string]: any } = {
        Originals = setmetatable({}, { __mode = 'k' }),
        Connections = {},
        Roots = {},
        Username = username,
        DisplayName = display,
        Names = names,
        ImageMode = imageMode,
        AvatarUserId = Data.AvatarSpoof and Data.AvatarSpoof.UserId,
        Images = setmetatable({}, { __mode = 'k' }),
        ThumbnailRequests = {},
    }
    Data.NameSpoofState = state
    local function keep(connection)
        state.Connections[#state.Connections + 1] = connection
    end
    local function allowed(object)
        if object == LocalPlayer then
            return true
        end
        if object:IsA('Humanoid') then
            return object.Parent == LocalPlayer.Character
        end
        for _, root in ipairs(state.Roots) do
            if object:IsDescendantOf(root) then
                return true
            end
        end
        return false
    end
    local function update(object, property, force)
        if Data.NameSpoofState ~= state or state.Busy then
            return
        end
        pcall(function()
            if not allowed(object) then
                return
            end
            local value = object[property]
            if type(value) ~= 'string' then
                return
            end
            local records = state.Originals[object]
            local record = records and records[property]
            if record and value == record.Applied then
                return
            end
            local replacement
            if property == 'Image' then
                state.Images[object] = true
                replacement = phowg:avatar_spoof_image(value, state)
            elseif state.Names then
                replacement = force and display or phowg:name_spoof_text(value, username, display)
            end
            if replacement == nil or replacement == value then
                return
            end
            state.Originals[object] = records or {}
            record = { Original = value, Applied = replacement }
            state.Originals[object][property] = record
            state.Busy = true
            local ok = pcall(function()
                object[property] = replacement
            end)
            state.Busy = false
            if not ok then
                state.Originals[object][property] = nil
            end
        end)
    end
    state.UpdateImages = function()
        for object in pairs(state.Images) do
            update(object, 'Image')
        end
    end
    local global
    pcall(function()
        global = connectshared(game.ItemChanged, function(object, property)
            pcall(function()
                if property == 'Image' and (object:IsA('ImageLabel') or object:IsA('ImageButton')) then
                    update(object, property)
                elseif property == 'Text' and (object:IsA('TextLabel') or object:IsA('TextButton')) then
                    update(object, property)
                elseif property == 'ToolTip' and object:IsA('Tool') then
                    update(object, property)
                elseif
                    property == 'DisplayName'
                    and (object == LocalPlayer or object:IsA('Humanoid') and object.Parent == LocalPlayer.Character)
                then
                    update(object, property, true)
                end
            end)
        end, game, 'avatar/name text', 0, 'event/ItemChanged', game)
        keep(global)
    end)
    local function observe(object)
        pcall(function()
            local property = (object:IsA('ImageLabel') or object:IsA('ImageButton')) and 'Image'
                or (object:IsA('TextLabel') or object:IsA('TextButton')) and 'Text'
                or object:IsA('Tool') and 'ToolTip'
            if property then
                update(object, property)
                if not global then
                    keep(connectshared(object:GetPropertyChangedSignal(property), function()
                        update(object, property)
                    end, object, 'avatar/name label'))
                end
            end
        end)
    end
    local roots = { LocalPlayer:FindFirstChild('PlayerGui'), game:GetService('CoreGui'), LocalPlayer.Character }
    for _, root in pairs(roots) do
        state.Roots[#state.Roots + 1] = root
        keep(connectshared(root.DescendantAdded, observe, root, 'avatar/name added', 0, 'event/DescendantAdded', root))
        phowg:queue_background('avatar name', { State = state, Root = root }, function()
            local ok, descendants = pcall(function()
                return root:GetDescendants()
            end)
            if not ok then
                return
            end
            for index, object in ipairs(descendants) do
                if Data.NameSpoofState ~= state then
                    return
                end
                observe(object)
                if index % 256 == 0 then
                    RunService.Heartbeat:Wait()
                end
            end
        end)
    end
    update(LocalPlayer, 'DisplayName', true)
    local character = LocalPlayer.Character
    local humanoid = character and character:FindFirstChildOfClass('Humanoid')
    if humanoid then
        update(humanoid, 'DisplayName', true)
    end
    if imageMode ~= 'unchanged' then
        phowg:warm_avatar_thumbnails()
    end
end
function phowg:resolve_avatar_identity(snapshot)
    if not snapshot or not snapshot.UserId then
        return
    end
    local player = Players:GetPlayerByUserId(snapshot.UserId)
    if player then
        snapshot.Identity = { Username = player.Name, DisplayName = player.DisplayName }
        phowg:refresh_name_spoof()
        return
    end
    local identity = Data.AvatarIdentityCache and Data.AvatarIdentityCache[snapshot.UserId]
    if identity then
        snapshot.Identity = identity
        phowg:refresh_name_spoof()
        return
    end
    if not (Toggles.avatar_spoof_name and Toggles.avatar_spoof_name.Value and Toggles.avatar_spoof_copy_name.Value) then
        phowg:refresh_name_spoof()
        return
    end
    phowg:queue_background('avatar identity', snapshot, function()
        local ok, infos = pcall(function()
            return game:GetService('UserService'):GetUserInfosByUserIdsAsync({ snapshot.UserId })
        end)
        if Data.AvatarSpoof ~= snapshot or Library.Unloaded then
            return
        end
        if ok then
            for _, info in ipairs(infos) do
                if info.Id == snapshot.UserId then
                    snapshot.Identity = { Username = info.Username, DisplayName = info.DisplayName }
                    Data.AvatarIdentityCache = Data.AvatarIdentityCache or {}
                    Data.AvatarIdentityCache[snapshot.UserId] = snapshot.Identity
                    break
                end
            end
        end
        phowg:refresh_name_spoof()
    end)
end
function phowg:name_spoof_settings_changed()
    if Data.AvatarSpoof then
        phowg:resolve_avatar_identity(Data.AvatarSpoof)
    else
        phowg:refresh_name_spoof()
    end
end
phowg:register_cleanup('avatar name spoof', function(scope, reason)
    if reason == 'unload' then
        phowg:stop_name_spoof()
    elseif scope == LocalPlayer.Character then
        phowg:stop_name_spoof()
    end
end)

