function phowg:load_avatar_archive()
    if Data.AvatarArchive then
        return Data.AvatarArchive
    end
    local archive = { Revision = 2, Users = {}, Outfits = {} }
    if readfile and isfile then
        local ok, stored = pcall(function()
            local path = 'PhowgHosted/DaHood/avatar-cache.json'
            if isfile(path) then
                local contents = readfile(path)
                if type(contents) == 'string' and #contents <= 16000000 then
                    return HttpService:JSONDecode(contents)
                end
            end
            return nil
        end)
        if
            ok
            and type(stored) == 'table'
            and (stored.Revision == 1 or stored.Revision == 2)
            and type(stored.Users) == 'table'
        then
            archive = stored
            archive.Revision = 2
            if type(archive.Outfits) ~= 'table' then
                archive.Outfits = {}
            end
        end
    end
    Data.AvatarArchive = archive
    return archive
end
function phowg:resolve_archived_avatar_user(query)
    for id, entry in pairs(phowg:load_avatar_archive().Users) do
        if type(entry) == 'table' and type(entry.Username) == 'string' and entry.Username:lower() == query then
            return tonumber(id), entry.Username
        end
    end
    return nil, nil
end
function phowg:flush_avatar_archive()
    if not Data.AvatarArchiveDirty or not Data.AvatarArchive or not (writefile and makefolder and isfolder) then
        return
    end
    local revision = Data.AvatarArchiveRevision
    local ok = pcall(function()
        if not isfolder('PhowgHosted') then
            makefolder('PhowgHosted')
        end
        if not isfolder('PhowgHosted/DaHood') then
            makefolder('PhowgHosted/DaHood')
        end
        writefile('PhowgHosted/DaHood/avatar-cache.json', HttpService:JSONEncode(Data.AvatarArchive))
    end)
    if ok and revision == Data.AvatarArchiveRevision then
        Data.AvatarArchiveDirty = nil
    end
end
function phowg:queue_avatar_archive_save()
    Data.AvatarArchiveDirty = true
    Data.AvatarArchiveRevision = (Data.AvatarArchiveRevision or 0) + 1
    if Data.AvatarArchiveSave then
        return
    end
    Data.AvatarArchiveSave = task.delay(0.5, function()
        Data.AvatarArchiveSave = nil
        phowg:flush_avatar_archive()
    end)
end
function phowg:avatar_archive_key(entry)
    local function encode(value)
        if type(value) ~= 'table' then
            return HttpService:JSONEncode(value)
        end
        local keys, parts = {}, {}
        for key in pairs(value) do
            keys[#keys + 1] = key
        end
        table.sort(keys, function(a, b)
            return tostring(a) < tostring(b)
        end)
        for _, key in ipairs(keys) do
            parts[#parts + 1] = encode(key) .. ':' .. encode(value[key])
        end
        return '{' .. table.concat(parts, ',') .. '}'
    end
    return encode({
        Properties = entry.Properties,
        Colors = entry.Colors,
        Accessories = entry.Accessories,
        Emotes = entry.Emotes,
        EquippedEmotes = entry.EquippedEmotes,
    })
end
function phowg:store_avatar_description(userId, description, source, outfitId)
    local entry = {
        UserId = userId,
        OutfitId = outfitId,
        Username = userId and Data.SpoofNameCache and Data.SpoofNameCache[userId],
        Source = source,
        SavedAt = os.time(),
        Properties = {},
        Colors = {},
        Accessories = {},
    }
    local ok = pcall(function()
        for _, property in ipairs(phowg:avatar_description_properties()) do
            local found, value = pcall(function()
                return description[property]
            end)
            if found and (type(value) == 'number' or type(value) == 'string') then
                entry.Properties[property] = value
            end
        end
        for _, property in ipairs({
            'HeadColor',
            'TorsoColor',
            'LeftArmColor',
            'RightArmColor',
            'LeftLegColor',
            'RightLegColor',
        }) do
            local color = description[property]
            entry.Colors[property] = { color.R, color.G, color.B }
        end
        for _, accessory in ipairs(description:GetAccessories(true)) do
            entry.Accessories[#entry.Accessories + 1] = {
                AssetId = accessory.AssetId,
                AccessoryType = accessory.AccessoryType.Name,
                IsLayered = accessory.IsLayered,
                Order = accessory.Order,
                Puffiness = accessory.Puffiness,
            }
        end
        entry.Emotes, entry.EquippedEmotes = description:GetEmotes(), description:GetEquippedEmotes()
    end)
    if not ok then
        return
    end
    local archive = phowg:load_avatar_archive()
    local bucket = outfitId and archive.Outfits or archive.Users
    local id = tostring(outfitId or userId)
    local previous = bucket[id]
    if type(previous) == 'table' and phowg:avatar_archive_key(previous) == phowg:avatar_archive_key(entry) then
        if entry.Username and entry.Username ~= previous.Username then
            previous.Username = entry.Username
            phowg:queue_avatar_archive_save()
        end
        return true
    end
    entry.History = {}
    if type(previous) == 'table' then
        local saved = table.clone(previous)
        saved.History = nil
        entry.History[1] = saved
        for _, snapshot in ipairs(type(previous.History) == 'table' and previous.History or {}) do
            if #entry.History >= 4 then
                break
            end
            if type(snapshot) == 'table' then
                entry.History[#entry.History + 1] = snapshot
            end
        end
    end
    bucket[id] = entry
    local entries = {}
    for key, value in pairs(bucket) do
        entries[#entries + 1] = { Id = key, At = type(value) == 'table' and tonumber(value.SavedAt) or 0 }
    end
    table.sort(entries, function(a, b)
        return (a.At or 0) > (b.At or 0)
    end)
    for index = 101, #entries do
        bucket[entries[index].Id] = nil
    end
    phowg:queue_avatar_archive_save()
    return true
end
function phowg:read_archived_avatar_description(userId, version)
    local entry = phowg:load_avatar_archive().Users[tostring(userId)]
    if type(entry) ~= 'table' or entry.UserId ~= userId then
        return nil
    end
    if version and version > 0 then
        entry = type(entry.History) == 'table' and entry.History[version] or nil
    end
    return phowg:decode_archived_avatar_description(entry)
end
function phowg:decode_archived_avatar_description(entry)
    if type(entry) ~= 'table' or type(entry.Properties) ~= 'table' or not next(entry.Properties) then
        return nil
    end
    local description = Instance.new('HumanoidDescription')
    local ok = pcall(function()
        for _, property in ipairs(phowg:avatar_description_properties()) do
            local value = entry.Properties[property]
            if type(value) == 'number' or type(value) == 'string' then
                pcall(function()
                    description[property] = value
                end)
            end
        end
        for _, property in ipairs({
            'HeadColor',
            'TorsoColor',
            'LeftArmColor',
            'RightArmColor',
            'LeftLegColor',
            'RightLegColor',
        }) do
            local color = entry.Colors and entry.Colors[property]
            if type(color) == 'table' and tonumber(color[1]) and tonumber(color[2]) and tonumber(color[3]) then
                description[property] = Color3.new(color[1], color[2], color[3])
            end
        end
        local accessories = {}
        for _, item in ipairs(entry.Accessories or {}) do
            local kind = Enum.AccessoryType[item.AccessoryType]
            if kind and tonumber(item.AssetId) and item.AssetId > 0 then
                accessories[#accessories + 1] = {
                    AssetId = item.AssetId,
                    AccessoryType = kind,
                    IsLayered = item.IsLayered,
                    Order = item.Order,
                    Puffiness = item.Puffiness,
                }
            end
        end
        if #accessories > 0 then
            description:SetAccessories(accessories, true)
        end
        if type(entry.Emotes) == 'table' then
            description:SetEmotes(entry.Emotes)
        end
        if type(entry.EquippedEmotes) == 'table' then
            description:SetEquippedEmotes(entry.EquippedEmotes)
        end
    end)
    if not ok then
        description:Destroy()
        return nil
    end
    return description, entry.Source, entry.SavedAt
end
function phowg:cache_avatar_description(userId, description, source, fresh)
    Data.SpoofDescCache, Data.SpoofDescSources = Data.SpoofDescCache or {}, Data.SpoofDescSources or {}
    Data.SpoofDescAccess, Data.SpoofDescChecked = Data.SpoofDescAccess or {}, Data.SpoofDescChecked or {}
    local previous = Data.SpoofDescCache[userId]
    Data.SpoofDescCache[userId], Data.SpoofDescSources[userId], Data.SpoofDescAccess[userId] =
        description, source, os.clock()
    if fresh then
        Data.SpoofDescChecked[userId] = os.clock()
    end
    if previous and previous ~= description then
        previous:Destroy()
    end
    local entries = {}
    for id in pairs(Data.SpoofDescCache) do
        entries[#entries + 1] = id
    end
    table.sort(entries, function(a, b)
        return (Data.SpoofDescAccess[a] or 0) > (Data.SpoofDescAccess[b] or 0)
    end)
    for index = 51, #entries do
        local id = entries[index]
        if id ~= userId and not (Data.AvatarSpoof and Data.AvatarSpoof.UserId == id) then
            Data.SpoofDescCache[id]:Destroy()
            Data.SpoofDescCache[id], Data.SpoofDescSources[id], Data.SpoofDescAccess[id], Data.SpoofDescChecked[id] =
                nil, nil, nil, nil
        end
    end
end
function phowg:queue_avatar_refresh(userId)
    Data.AvatarRefreshes, Data.SpoofDescChecked = Data.AvatarRefreshes or {}, Data.SpoofDescChecked or {}
    if Data.AvatarRefreshes[userId] or os.clock() < (Data.SpoofDescChecked[userId] or -math.huge) + 120 then
        return
    end
    local count = 0
    for _ in pairs(Data.AvatarRefreshes) do
        count += 1
    end
    if count >= 2 then
        return
    end
    local token, displayed = {}, Data.AvatarSpoof
    Data.AvatarRefreshes[userId] = token
    task.spawn(function()
        local function active()
            return not Library.Unloaded and Data.AvatarRefreshes[userId] == token
        end
        local ok, description, source = pcall(phowg_callbacks.fetch_avatar_description, userId, active, true)
        if not active() then
            if ok and description then
                description:Destroy()
            end
            return
        end
        Data.AvatarRefreshes[userId] = nil
        Data.SpoofDescChecked[userId] = os.clock()
        if not ok or not description then
            return
        end
        local previous = phowg:load_avatar_archive().Users[tostring(userId)]
        phowg:cache_avatar_description(userId, description, source, true)
        phowg:store_avatar_description(userId, description, source)
        local changed = phowg:load_avatar_archive().Users[tostring(userId)] ~= previous
        if
            changed
            and Data.AvatarSpoof == displayed
            and displayed
            and displayed.UserId == userId
            and not displayed.Customization
            and not displayed.HistoryPinned
            and not Data.AvatarEditor
            and Toggles.avatar_spoof_enabled
            and Toggles.avatar_spoof_enabled.Value
        then
            applyavatarspoof(tostring(userId))
        end
        if phowg.refresh_avatar_history then
            phowg:refresh_avatar_history()
        end
    end)
end
phowg:register_cleanup('avatar cache', function(_, reason)
    if reason ~= 'unload' then
        return
    end
    if Data.AvatarArchiveSave then
        pcall(task.cancel, Data.AvatarArchiveSave)
        Data.AvatarArchiveSave = nil
    end
    phowg:flush_avatar_archive()
    table.clear(Data.AvatarRefreshes or {})
    for _, description in pairs(Data.SpoofDescCache or {}) do
        description:Destroy()
    end
    Data.SpoofDescCache, Data.SpoofDescSources, Data.SpoofDescAccess, Data.SpoofDescChecked = {}, {}, {}, {}
end)
function phowg:avatar_description_from_info(info)
    if type(info) ~= 'table' or type(info.assets) ~= 'table' or type(info.bodyColors) ~= 'table' then
        return nil
    end
    local description = Instance.new('HumanoidDescription')
    local properties = {
        TShirt = 'GraphicTShirt',
        Shirt = 'Shirt',
        Pants = 'Pants',
        Face = 'Face',
        Head = 'Head',
        DynamicHead = 'Head',
        Torso = 'Torso',
        LeftArm = 'LeftArm',
        RightArm = 'RightArm',
        LeftLeg = 'LeftLeg',
        RightLeg = 'RightLeg',
        ClimbAnimation = 'ClimbAnimation',
        FallAnimation = 'FallAnimation',
        IdleAnimation = 'IdleAnimation',
        JumpAnimation = 'JumpAnimation',
        RunAnimation = 'RunAnimation',
        SwimAnimation = 'SwimAnimation',
        WalkAnimation = 'WalkAnimation',
        MoodAnimation = 'MoodAnimation',
    }
    local kinds = {
        Hat = 'Hat',
        HatAccessory = 'Hat',
        HairAccessory = 'Hair',
        FaceAccessory = 'Face',
        NeckAccessory = 'Neck',
        ShoulderAccessory = 'Shoulder',
        ShouldersAccessory = 'Shoulder',
        FrontAccessory = 'Front',
        BackAccessory = 'Back',
        WaistAccessory = 'Waist',
        TShirtAccessory = 'TShirt',
        ShirtAccessory = 'Shirt',
        PantsAccessory = 'Pants',
        JacketAccessory = 'Jacket',
        SweaterAccessory = 'Sweater',
        ShortsAccessory = 'Shorts',
        LeftShoeAccessory = 'LeftShoe',
        RightShoeAccessory = 'RightShoe',
        DressSkirtAccessory = 'DressSkirt',
        EyebrowAccessory = 'Eyebrow',
        EyelashAccessory = 'Eyelash',
    }
    local typeNames = {}
    for _, kind in ipairs(Enum.AssetType:GetEnumItems()) do
        typeNames[kind.Value] = kind.Name
    end
    local ok = pcall(function()
        for key, property in pairs({
            height = 'HeightScale',
            width = 'WidthScale',
            depth = 'DepthScale',
            head = 'HeadScale',
            bodyType = 'BodyTypeScale',
            proportion = 'ProportionScale',
        }) do
            local value = info.scales and tonumber(info.scales[key])
            if value then
                description[property] = value
            end
        end
        local colorCount = 0
        for key, property in pairs({
            head = 'HeadColor',
            torso = 'TorsoColor',
            leftArm = 'LeftArmColor',
            rightArm = 'RightArmColor',
            leftLeg = 'LeftLegColor',
            rightLeg = 'RightLegColor',
        }) do
            local id = tonumber(info.bodyColors[key .. 'ColorId'])
            local hex = info.bodyColors[key .. 'Color'] or info.bodyColors[key .. 'Color3']
            if id then
                description[property] = BrickColor.new(id).Color
                colorCount += 1
            elseif type(hex) == 'string' and hex:gsub('^#', ''):match('^%x%x%x%x%x%x$') then
                description[property] = Color3.fromHex((hex:gsub('^#', '')))
                colorCount += 1
            end
        end
        if colorCount ~= 6 then
            error('Incomplete avatar colors')
        end
        local accessories = {}
        for _, asset in ipairs(info.assets) do
            local id = tonumber(asset.id or asset.assetId)
            local assetType = asset.assetType
            local typeId = type(assetType) == 'table' and tonumber(assetType.id)
                or tonumber(assetType or asset.assetTypeId)
            local name = typeNames[typeId]
                or type(assetType) == 'table' and assetType.name and assetType.name:gsub('[%s%-]', '')
            if id and id > 0 and name then
                local property = properties[name]
                local accessory = kinds[name]
                if property then
                    description[property] = id
                elseif accessory then
                    local kind = Enum.AccessoryType[accessory]
                    if kind then
                        local layered = accessory == 'TShirt'
                            or accessory == 'Shirt'
                            or accessory == 'Pants'
                            or accessory == 'Jacket'
                            or accessory == 'Sweater'
                            or accessory == 'Shorts'
                            or accessory == 'LeftShoe'
                            or accessory == 'RightShoe'
                            or accessory == 'DressSkirt'
                        local meta = type(asset.meta) == 'table' and asset.meta or {}
                        accessories[#accessories + 1] = {
                            AssetId = id,
                            AccessoryType = kind,
                            IsLayered = layered,
                            Order = layered and (tonumber(meta.order) or #accessories + 1) or nil,
                            Puffiness = layered and (tonumber(meta.puffiness) or 0) or nil,
                        }
                    end
                end
            end
        end
        description:SetAccessories(accessories, true)
        if type(info.emotes) == 'table' then
            local emotes, equipped = {}, {}
            for _, emote in ipairs(info.emotes) do
                if type(emote.name) == 'string' and tonumber(emote.assetId or emote.id) then
                    emotes[emote.name] = { tonumber(emote.assetId or emote.id) }
                    if tonumber(emote.position) then
                        equipped[#equipped + 1] = { Name = emote.name, Slot = tonumber(emote.position) }
                    end
                end
            end
            description:SetEmotes(emotes)
            description:SetEquippedEmotes(equipped)
        end
    end)
    if not ok then
        description:Destroy()
        return nil
    end
    return description
end
function phowg:avatar_fetch_attempt(callback, active, deadline)
    if not active() or os.clock() >= deadline then
        return false
    end
    local done, expired, success, result = false, false, false, nil
    Data.AvatarFetchWorkers = Data.AvatarFetchWorkers or {}
    local worker = coroutine.create(function()
        local ok, value = pcall(callback)
        if expired or not active() then
            if ok and typeof(value) == 'Instance' then
                value:Destroy()
            end
        else
            success, result = ok, value
        end
        done = true
        Data.AvatarFetchWorkers[coroutine.running()] = nil
    end)
    Data.AvatarFetchWorkers[worker] = true
    task.spawn(worker)
    local untilAt = math.min(deadline, os.clock() + 8)
    while not done and active() and os.clock() < untilAt do
        task.wait(0.05)
    end
    if not done or not active() then
        expired = true
        if not done then
            pcall(task.cancel, worker)
        end
        Data.AvatarFetchWorkers[worker] = nil
        if typeof(result) == 'Instance' then
            result:Destroy()
        end
        return false
    end
    return success, result
end
function phowg:avatar_fetch_json(url)
    local req = (syn and syn.request)
        or (http and http.request)
        or http_request
        or (fluxus and fluxus.request)
        or request
    local body
    if req then
        local ok, response = pcall(req, { Url = url, Method = 'GET', Timeout = 8 })
        if ok and type(response) == 'table' then
            local status = tonumber(response.StatusCode or response.Status)
            if status == 429 then
                return nil
            end
            if (not status or status >= 200 and status < 300) and type(response.Body) == 'string' then
                body = response.Body
            end
        end
    end
    if not body and game.HttpGet then
        body = game:HttpGet(url)
    end
    if type(body) ~= 'string' or #body > 2000000 then
        return nil
    end
    local decoded = HttpService:JSONDecode(body)
    if type(decoded) ~= 'table' or decoded.errors then
        return nil
    end
    return decoded
end
function phowg:fetch_avatar_description_direct(userId, active, refreshOnly)
    if not active() then
        return nil
    end
    if not refreshOnly then
        local cached = phowg:read_archived_avatar_description(userId)
        if cached then
            return cached, 'cached avatar'
        end
    end
    local deadline = os.clock() + 60
    local function attempt(callback)
        local ok, result = phowg:avatar_fetch_attempt(callback, active, deadline)
        return ok and result or nil
    end
    local function description(callback)
        local result = attempt(callback)
        if typeof(result) == 'Instance' then
            if result:IsA('HumanoidDescription') then
                return result
            end
            result:Destroy()
        end
        return nil
    end
    local result = description(function()
        return Players:GetHumanoidDescriptionFromUserIdAsync(userId)
    end)
    if result then
        return result, 'current avatar'
    end
    result = description(function()
        local player = Players:GetPlayerByUserId(userId)
        local humanoid = player and player.Character and player.Character:FindFirstChildOfClass('Humanoid')
        return humanoid and humanoid:GetAppliedDescription()
    end)
    if result then
        return result, 'in-server avatar'
    end
    result = description(function()
        return phowg:avatar_description_from_info(Players:GetCharacterAppearanceInfoAsync(userId))
    end)
    if result then
        return result, 'appearance data'
    end
    for _, path in ipairs({ '/v4/avatar/users/' }) do
        result = description(function()
            local info = phowg:avatar_fetch_json(
                'https://avatar.roblox.com'
                    .. path
                    .. tostring(userId)
                    .. (path ~= '/v4/avatar/users/' and '/avatar' or '')
            )
            return phowg:avatar_description_from_info(info)
        end)
        if result then
            return result, 'avatar API'
        end
    end
    result = description(function()
        local rig = Players:CreateHumanoidModelFromUserIdAsync(userId)
        local ok, desc = pcall(function()
            return rig:FindFirstChildOfClass('Humanoid'):GetAppliedDescription()
        end)
        rig:Destroy()
        return ok and desc or nil
    end)
    if result then
        return result, 'avatar model'
    end
    if not active() or refreshOnly then
        return nil
    end
    local outfits = attempt(function()
        return phowg:avatar_fetch_json(
            'https://avatar.roblox.com/v2/avatar/users/'
                .. tostring(userId)
                .. '/outfits?page=1&itemsPerPage=50&isEditable=true'
        )
    end)
    if type(outfits) ~= 'table' or type(outfits.data) ~= 'table' then
        return nil
    end
    local candidates = {}
    for _, outfit in ipairs(outfits.data) do
        if type(outfit) == 'table' and tonumber(outfit.id) and outfit.id > 0 then
            candidates[#candidates + 1] = outfit.id
        end
    end
    table.sort(candidates, function(a, b)
        return a > b
    end)
    for index = 1, math.min(5, #candidates) do
        local outfitId = candidates[index]
        result = description(function()
            return Players:GetHumanoidDescriptionFromOutfitIdAsync(outfitId)
        end)
        if not result then
            result = description(function()
                return phowg:avatar_description_from_info(
                    phowg:avatar_fetch_json('https://avatar.roblox.com/v4/outfits/' .. tostring(outfitId) .. '/details')
                )
            end)
        end
        if result then
            return result, 'saved outfit ' .. tostring(outfitId)
        end
    end
    return nil, nil
end

function phowg:fetch_avatar_description(userId, active, refreshOnly)
    if not active() or Library.Unloaded or Data.SharedSignalsClosed then
        return nil
    end
    if not refreshOnly then
        local archived = phowg:read_archived_avatar_description(userId)
        if archived then
            return archived, 'cached avatar'
        end
    end
    Data.AvatarFetchFlights = Data.AvatarFetchFlights or {}
    local flights = Data.AvatarFetchFlights
    local key = tostring(userId) .. ':' .. tostring(refreshOnly == true)
    local flight = flights[key]
    if not flight then
        flight = { Waiters = {}, Done = false }
        flights[key] = flight
    end
    local waiter = {}
    flight.Waiters[waiter] = active
    if not flight.Worker and not flight.Done then
        local function needed()
            if Library.Unloaded or Data.SharedSignalsClosed or flights[key] ~= flight then
                return false
            end
            for _, wantsResult in pairs(flight.Waiters) do
                if wantsResult() then
                    return true
                end
            end
            return false
        end
        flight.Worker = coroutine.create(function()
            local ok, description, source = pcall(phowg_callbacks.fetch_avatar_description_direct, userId, needed, refreshOnly)
            if ok then
                flight.Description, flight.Source = description, source
            end
            flight.Done = true
            flight.Worker = nil
        end)
        task.spawn(flight.Worker)
    end
    while not flight.Done and active() and not Library.Unloaded and not Data.SharedSignalsClosed do
        task.wait()
    end
    local description, source
    if active() and flight.Done and flight.Description and not Library.Unloaded and not Data.SharedSignalsClosed then
        description, source = flight.Description:Clone(), flight.Source
    end
    flight.Waiters[waiter] = nil
    if not next(flight.Waiters) then
        if flight.Worker then
            pcall(task.cancel, flight.Worker)
        end
        if flight.Description then
            flight.Description:Destroy()
            flight.Description = nil
        end
        if flights[key] == flight then
            flights[key] = nil
        end
    end
    return description, source
end
phowg:register_cleanup('avatar fetches', function(_, reason)
    if reason ~= 'unload' then
        return
    end
    for _, flight in pairs(Data.AvatarFetchFlights or {}) do
        if flight.Worker and flight.Worker ~= coroutine.running() then
            pcall(task.cancel, flight.Worker)
        end
        if flight.Description then
            flight.Description:Destroy()
            flight.Description = nil
        end
        table.clear(flight.Waiters)
    end
    for worker in pairs(Data.AvatarFetchWorkers or {}) do
        if worker ~= coroutine.running() then
            pcall(task.cancel, worker)
        end
    end
    table.clear(Data.AvatarFetchFlights or {})
    table.clear(Data.AvatarFetchWorkers or {})
end)

function phowg:apply_recorded_avatar(description, source, userId, outfitId, savedAt)
    if not description then
        return false, 'Appearance is unavailable'
    end
    if not (Toggles.avatar_spoof_enabled and Toggles.avatar_spoof_enabled.Value) or Library.Unloaded then
        description:Destroy()
        return false, 'Enable avatar spoof first'
    end
    local character = LocalPlayer.Character
    if
        not character
        or Data.SpoofBusy
        or Data.AvatarRestoreBusy
        or Data.AvatarApplyJobs and Data.AvatarApplyJobs[character]
    then
        description:Destroy()
        return false, 'Wait for the current avatar update'
    end
    local old = Data.AvatarSpoof
    phowg:close_avatar_editor()
    phowg:stop_avatar_mood(old)
    local snapshot = {
        Desc = description,
        UserId = userId,
        OutfitId = outfitId,
        Source = source,
        RecordedAt = savedAt,
        HistoryPinned = true,
    }
    if old then
        for _, key in ipairs({
            'My',
            'MyDesc',
            'MyMeshes',
            'MyAnimations',
            'MyAnimationWeights',
            'MyScales',
            'MyJoints',
            'MyAccessories',
            'MyAnimationDamping',
            'MyAnimationDampingPresent',
        }) do
            snapshot[key] = old[key]
        end
    end
    Data.AvatarRequestVersion = (Data.AvatarRequestVersion or 0) + 1
    Data.AvatarSpoof = snapshot
    if old then
        for _, key in ipairs({ 'ReferenceRig', 'BaseDesc', 'Desc' }) do
            if old[key] then
                old[key]:Destroy()
            end
        end
    else
        capturemyavatar(character)
    end
    phowg:resolve_avatar_identity(snapshot)
    task.spawn(function()
        if Data.AvatarSpoof ~= snapshot or Library.Unloaded then
            return
        end
        applyavatarspooftochar(character, true)
        if phowg.refresh_avatar_history then
            phowg:refresh_avatar_history()
        end
    end)
    return true
end
function phowg:refresh_avatar_history()
    local control = Options.avatar_recorded_snapshot
    if not control then
        return
    end
    local snapshot = Data.AvatarSpoof
    local archive = phowg:load_avatar_archive()
    local entry = snapshot
        and (
            snapshot.OutfitId and archive.Outfits[tostring(snapshot.OutfitId)]
            or snapshot.UserId and archive.Users[tostring(snapshot.UserId)]
        )
    local values, selections = {}, {}
    if type(entry) == 'table' then
        local function add(record, index)
            local timestamp = tonumber(record.SavedAt) or 0
            local label = (index == 0 and 'latest' or 'previous ' .. tostring(index))
                .. ' | '
                .. os.date('%Y-%m-%d %H:%M', timestamp)
                .. ' | '
                .. tostring(record.Source or 'recorded avatar')
            values[#values + 1], selections[label] = label, record
        end
        add(entry, 0)
        for index, record in ipairs(type(entry.History) == 'table' and entry.History or {}) do
            if type(record) == 'table' then
                add(record, index)
            end
        end
    end
    Data.AvatarHistorySelections = selections
    local selected = control.Value
    control:SetValues(values)
    control:SetValue(selections[selected] and selected or values[1], true)
end
function phowg:load_recorded_avatar()
    local label = Options.avatar_recorded_snapshot and Options.avatar_recorded_snapshot.Value
    local entry = Data.AvatarHistorySelections and Data.AvatarHistorySelections[label]
    local description, source, savedAt = phowg:decode_archived_avatar_description(entry)
    local ok, problem = phowg:apply_recorded_avatar(
        description,
        'recorded / ' .. tostring(source or 'avatar'),
        entry and entry.UserId,
        entry and entry.OutfitId,
        savedAt
    )
    if not ok then
        Library:Notify(problem, 3)
    end
end
function phowg:import_avatar_outfit()
    if Data.AvatarOutfitImport then
        return
    end
    local input = Options.avatar_outfit_id and tostring(Options.avatar_outfit_id.Value or '') or ''
    local id = tonumber(input:match('^%s*(%d+)%s*$'))
    if not id or id < 1 or id % 1 ~= 0 or id >= 9007199254740992 then
        Library:Notify('Enter a valid saved outfit id.', 3)
        return
    end
    if not (Toggles.avatar_spoof_enabled and Toggles.avatar_spoof_enabled.Value) then
        Library:Notify('Enable avatar spoof first.', 3)
        return
    end
    local token = {}
    local version = Data.AvatarRequestVersion
    Data.AvatarOutfitImport = token
    task.spawn(function()
        local function active()
            return Data.AvatarOutfitImport == token
                and Data.AvatarRequestVersion == version
                and not Library.Unloaded
                and Toggles.avatar_spoof_enabled.Value
        end
        local entry = phowg:load_avatar_archive().Outfits[tostring(id)]
        local description = phowg:decode_archived_avatar_description(entry)
        if not description then
            local ok, result = phowg:avatar_fetch_attempt(function()
                return Players:GetHumanoidDescriptionFromOutfitIdAsync(id)
            end, active, os.clock() + 8)
            if ok and typeof(result) == 'Instance' and result:IsA('HumanoidDescription') then
                description = result
            elseif ok and typeof(result) == 'Instance' then
                result:Destroy()
            end
            if not description and active() then
                local found, fallback = phowg:avatar_fetch_attempt(function()
                    return phowg:avatar_description_from_info(
                        phowg:avatar_fetch_json('https://avatar.roblox.com/v4/outfits/' .. tostring(id) .. '/details')
                    )
                end, active, os.clock() + 8)
                if found and typeof(fallback) == 'Instance' and fallback:IsA('HumanoidDescription') then
                    description = fallback
                elseif found and typeof(fallback) == 'Instance' then
                    fallback:Destroy()
                end
            end
        end
        if not active() then
            if description then
                description:Destroy()
            end
            if Data.AvatarOutfitImport == token then
                Data.AvatarOutfitImport = nil
            end
            return
        end
        if description then
            phowg:store_avatar_description(nil, description, 'imported outfit ' .. tostring(id), id)
        end
        Data.AvatarOutfitImport = nil
        local ok, problem = phowg:apply_recorded_avatar(
            description,
            'imported outfit ' .. tostring(id),
            nil,
            id,
            entry and entry.SavedAt or os.time()
        )
        if not ok then
            Library:Notify(problem, 3)
        end
    end)
end
function phowg:begin_avatar_spoof_session()
    Data.AvatarIdentityCache = Data.AvatarIdentityCache or {}
    Data.AvatarThumbnailTargets = Data.AvatarThumbnailTargets or {}
    Data.AvatarFetchGeneration = (Data.AvatarFetchGeneration or 0) + 1
    Data.SpoofDescCache, Data.SpoofDescSources = Data.SpoofDescCache or {}, Data.SpoofDescSources or {}
end
function applyavatarspoof(query)
    if Library.Unloaded or Toggles.avatar_spoof_enabled and not Toggles.avatar_spoof_enabled.Value then
        return
    end
    if not query or not tostring(query):match('%S') then
        return
    end
    Data.AvatarRequestVersion = (Data.AvatarRequestVersion or 0) + 1
    local version = Data.AvatarRequestVersion
    local generation = Data.AvatarFetchGeneration or 0
    if Data.SpoofBusy or Data.AvatarRestoreBusy then
        Data.AvatarPendingQuery = query
        return
    end
    task.spawn(function()
        Data['SpoofBusy'] = true
        Data['SpoofDescCache'] = Data['SpoofDescCache'] or {}
        Data['SpoofNameCache'] = Data['SpoofNameCache'] or {}
        Data['SpoofQueryToIdCache'] = Data['SpoofQueryToIdCache'] or {}
        local raw = tostring(query):match('^%s*(.-)%s*$')
        local rawLower = string.lower(raw)
        local userId = tonumber(raw)
        local resolvedName = nil
        if not userId and Data['SpoofQueryToIdCache'][rawLower] then
            userId = Data['SpoofQueryToIdCache'][rawLower]
            resolvedName = Data['SpoofNameCache'][userId]
        end
        if not userId then
            for _, p in ipairs(Players:GetPlayers()) do
                if string.lower(p.Name) == rawLower or string.lower(p.DisplayName) == rawLower then
                    userId = p.UserId
                    resolvedName = p.Name
                    Data['SpoofQueryToIdCache'][rawLower] = userId
                    Data['SpoofNameCache'][userId] = p.Name
                    break
                end
            end
        end
        if not userId and #raw >= 3 then
            for _, p in ipairs(Players:GetPlayers()) do
                if
                    string.find(string.lower(p.Name), rawLower, 1, true)
                    or string.find(string.lower(p.DisplayName), rawLower, 1, true)
                then
                    userId = p.UserId
                    resolvedName = p.Name
                    Data['SpoofQueryToIdCache'][rawLower] = userId
                    Data['SpoofNameCache'][userId] = p.Name
                    break
                end
            end
        end
        if not userId then
            userId, resolvedName = phowg:resolve_archived_avatar_user(rawLower)
        end
        if not userId then
            local req = (syn and syn.request)
                or (http and http.request)
                or http_request
                or (fluxus and fluxus.request)
                or request
            if req then
                local okReq, res = pcall(function()
                    return req({
                        Url = 'https://users.roblox.com/v1/usernames/users',
                        Method = 'POST',
                        Headers = { ['Content-Type'] = 'application/json' },
                        Body = HttpService:JSONEncode({ usernames = { raw }, excludeBannedUsers = false }),
                    })
                end)
                if okReq and res and res.Body then
                    local okJson, body = pcall(function()
                        return HttpService:JSONDecode(res.Body)
                    end)
                    if okJson and body and body.data and #body.data > 0 and body.data[1].id then
                        userId = tonumber(body.data[1].id)
                        resolvedName = body.data[1].name
                        if userId then
                            Data['SpoofQueryToIdCache'][rawLower] = userId
                            Data['SpoofNameCache'][userId] = resolvedName
                        end
                    end
                end
            end
        end
        if not userId and game.HttpGet then
            local okGet, rawJson = pcall(function()
                return game:HttpGet(
                    'https://users.roblox.com/v1/users/search?keyword=' .. HttpService:UrlEncode(raw) .. '&limit=10'
                )
            end)
            if okGet and rawJson and #rawJson > 2 and string.sub(rawJson, 1, 1) == '{' then
                local okJson, body = pcall(function()
                    return HttpService:JSONDecode(rawJson)
                end)
                if okJson and body and body.data and #body.data > 0 then
                    for _, u in ipairs(body.data) do
                        if string.lower(u.name) == rawLower then
                            userId = tonumber(u.id)
                            resolvedName = u.name
                            break
                        end
                    end
                    if userId then
                        Data['SpoofQueryToIdCache'][rawLower] = userId
                        Data['SpoofNameCache'][userId] = resolvedName
                    end
                end
            end
        end
        if not userId then
            local okN, idN = pcall(function()
                return Players:GetUserIdFromNameAsync(raw)
            end)
            if okN and idN then
                userId = idN
                Data['SpoofQueryToIdCache'][rawLower] = userId
            end
        end
        if not userId then
            userId, resolvedName = phowg:resolve_archived_avatar_user(rawLower)
        end
        if not userId then
            phowg:finish_avatar_request()
            Library:Notify(
                'spoof: user not found / rate-limited; try the numeric user id for deleted accounts',
                Library.NotifyDuration or 3
            )
            return
        end
        if userId < 1 or userId % 1 ~= 0 or userId >= 9007199254740992 then
            phowg:finish_avatar_request()
            Library:Notify('spoof: invalid user id', Library.NotifyDuration or 3)
            return
        end
        local function active()
            return generation == (Data.AvatarFetchGeneration or 0)
                and version == Data.AvatarRequestVersion
                and not Library.Unloaded
                and not (Toggles.avatar_spoof_enabled and not Toggles.avatar_spoof_enabled.Value)
        end
        local cachedDesc = Data['SpoofDescCache'][userId]
        Data.SpoofDescAccess = Data.SpoofDescAccess or {}
        Data.SpoofDescAccess[userId] = os.clock()
        local desc, source = cachedDesc, Data.SpoofDescSources and Data.SpoofDescSources[userId]
        if not desc then
            local fetched, found, method = pcall(phowg_callbacks.fetch_avatar_description, userId, active)
            if fetched then
                desc, source = found, method
            end
            if desc and active() then
                phowg:cache_avatar_description(userId, desc, source, source ~= 'cached avatar')
            end
        end
        if not active() then
            if desc and not cachedDesc and Data.SpoofDescCache[userId] ~= desc then
                desc:Destroy()
            end
            phowg:finish_avatar_request()
            return
        end
        if not desc then
            phowg:finish_avatar_request()
            Library:Notify(
                'spoof: no accessible avatar, cached appearance, or saved outfit found; try the numeric user id for deleted accounts',
                Library.NotifyDuration or 3
            )
            return
        end
        desc = desc:Clone()
        local targetPlayer = Players:GetPlayerByUserId(userId)
        local targetHumanoid = targetPlayer
            and targetPlayer.Character
            and targetPlayer.Character:FindFirstChildOfClass('Humanoid')
        if targetHumanoid then
            pcall(function()
                local current = targetHumanoid:GetAppliedDescription()
                for _, property in ipairs({
                    'IdleAnimation',
                    'WalkAnimation',
                    'RunAnimation',
                    'JumpAnimation',
                    'ClimbAnimation',
                    'FallAnimation',
                    'SwimAnimation',
                }) do
                    if tonumber(current[property]) == 0 and (tonumber(desc[property]) or 0) > 0 then
                        current[property] = desc[property]
                    end
                end
                desc:Destroy()
                desc = current
            end)
        end
        if
            version ~= Data.AvatarRequestVersion
            or Library.Unloaded
            or Toggles.avatar_spoof_enabled and not Toggles.avatar_spoof_enabled.Value
        then
            desc:Destroy()
            phowg:finish_avatar_request()
            return
        end
        local keepDesc = Data['AvatarSpoof'] and Data['AvatarSpoof'].MyDesc or nil
        local keepMeshes = Data['AvatarSpoof'] and Data['AvatarSpoof'].MyMeshes or nil
        local keepSaved = Data.AvatarSpoof and Data.AvatarSpoof.My
        local keepAnimations = Data.AvatarSpoof and Data.AvatarSpoof.MyAnimations
        local keepWeights = Data.AvatarSpoof and Data.AvatarSpoof.MyAnimationWeights
        local keepScales = Data.AvatarSpoof and Data.AvatarSpoof.MyScales
        local keepJoints = Data.AvatarSpoof and Data.AvatarSpoof.MyJoints
        local keepAccessories = Data.AvatarSpoof and Data.AvatarSpoof.MyAccessories
        local keepDamping = Data.AvatarSpoof and Data.AvatarSpoof.MyAnimationDamping
        local keepDampingPresent = Data.AvatarSpoof and Data.AvatarSpoof.MyAnimationDampingPresent
        phowg:stop_avatar_mood(Data.AvatarSpoof)
        if Data.AvatarSpoof and Data.AvatarSpoof.ReferenceRig then
            Data.AvatarSpoof.ReferenceRig:Destroy()
        end
        if Data.AvatarSpoof and Data.AvatarSpoof.BaseDesc then
            Data.AvatarSpoof.BaseDesc:Destroy()
        end
        if Data.AvatarSpoof and Data.AvatarSpoof.Desc then
            Data.AvatarSpoof.Desc:Destroy()
        end
        phowg:close_avatar_editor()
        Data['AvatarSpoof'] = { Desc = desc, UserId = userId, Prefetched = true, Source = source }
        phowg:resolve_avatar_identity(Data.AvatarSpoof)
        if keepDesc then
            Data['AvatarSpoof'].MyDesc = keepDesc
        end
        if keepMeshes then
            Data['AvatarSpoof'].MyMeshes = keepMeshes
        end
        Data.AvatarSpoof.My, Data.AvatarSpoof.MyAnimations, Data.AvatarSpoof.MyAnimationWeights =
            keepSaved, keepAnimations, keepWeights
        Data.AvatarSpoof.MyScales, Data.AvatarSpoof.MyJoints = keepScales, keepJoints
        Data.AvatarSpoof.MyAccessories = keepAccessories
        Data.AvatarSpoof.MyAnimationDamping, Data.AvatarSpoof.MyAnimationDampingPresent =
            keepDamping, keepDampingPresent
        capturemyavatar(LocalPlayer.Character)
        local accsSnap, layeredSnap = {}, {}
        pcall(function()
            accsSnap, layeredSnap = collectspoofaccs(desc)
        end)
        Data['AvatarSpoof'].AccList = accsSnap
        Data['AvatarSpoof'].LayeredList = layeredSnap
        local charNow = LocalPlayer.Character
        if charNow then
            applyavatarspooftochar(charNow, true)
        end
        buildvisualizer()
        local spoofName = resolvedName or Data['SpoofNameCache'][userId] or tostring(query)
        if not Data['SpoofNameCache'][userId] then
            local okG, nm = phowg:avatar_fetch_attempt(function()
                return Players:GetNameFromUserIdAsync(userId)
            end, active, os.clock() + 8)
            if okG and nm then
                spoofName = tostring(nm)
                Data['SpoofNameCache'][userId] = spoofName
            end
        end
        if not active() then
            phowg:finish_avatar_request()
            return
        end
        if source ~= 'cached avatar' then
            phowg:store_avatar_description(userId, Data.SpoofDescCache[userId], source)
        end
        local accCount = 0
        pcall(function()
            accCount = #desc:GetAccessories(true)
        end)
        Library:Notify(
            'spoofed '
                .. spoofName
                .. ' ('
                .. tostring(accCount)
                .. ' accs'
                .. (source and source ~= 'current avatar' and ', ' .. source or '')
                .. ')',
            Library.NotifyDuration or 3
        )
        if charNow and charNow.Parent then
            local humCheck = charNow:FindFirstChildOfClass('Humanoid')
            if not humCheck then
                Library:Notify('spoof: body swap failed', Library.NotifyDuration or 3)
            end
        end
        phowg:finish_avatar_request()
        phowg:queue_avatar_refresh(userId)
        if phowg.refresh_avatar_history then
            phowg:refresh_avatar_history()
        end
    end)
end
function clearavatarspoof()
    phowg:close_avatar_editor()
    phowg:stop_name_spoof()
    Data.AvatarRequestVersion = (Data.AvatarRequestVersion or 0) + 1
    Data.AvatarPendingQuery = nil
    local active = Data.AvatarSpoof
    if not active then
        return
    end
    if active and Data.AvatarApplyJobs and Data.AvatarApplyJobs[LocalPlayer.Character] then
        active.RemovePending = true
        return
    end
    Data.AvatarRestoreBusy = true
    if updatekorbloxchar then
        updatekorbloxchar(LocalPlayer.Character, false, true)
    end
    phowg:stop_avatar_mood(active)
    local saved = Data['AvatarSpoof'] and Data['AvatarSpoof'].My or nil
    local savedDesc = Data['AvatarSpoof'] and Data['AvatarSpoof'].MyDesc or nil
    local savedMeshes = Data['AvatarSpoof'] and Data['AvatarSpoof'].MyMeshes or nil
    local savedAnimations = Data.AvatarSpoof and Data.AvatarSpoof.MyAnimations
    local savedWeights = Data.AvatarSpoof and Data.AvatarSpoof.MyAnimationWeights
    local savedScales = Data.AvatarSpoof and Data.AvatarSpoof.MyScales
    local savedJoints = Data.AvatarSpoof and Data.AvatarSpoof.MyJoints
    local savedAccessories = Data.AvatarSpoof and Data.AvatarSpoof.MyAccessories
    local savedDamping = active and active.MyAnimationDamping
    local savedDampingPresent = active and active.MyAnimationDampingPresent
    local reference = Data.AvatarSpoof and Data.AvatarSpoof.ReferenceRig
    Data['AvatarSpoof'] = nil
    if reference then
        reference:Destroy()
    end
    if active then
        if active.BaseDesc then
            active.BaseDesc:Destroy()
        end
        if active.Desc and active.Desc ~= active.BaseDesc then
            active.Desc:Destroy()
        end
    end
    local c = LocalPlayer.Character
    if c and phowg.suspend_local_materials then
        phowg:suspend_local_materials(c)
    end
    if c then
        if savedDesc then
            (function()
                local hum = c:FindFirstChildOfClass('Humanoid')
                if hum then
                    pcall(function()
                        if hum.ApplyDescriptionAsync then
                            hum:ApplyDescriptionAsync(savedDesc)
                        else
                            hum:ApplyDescription(savedDesc)
                        end
                    end)
                    phowg:apply_avatar_emotes(hum, savedDesc)
                end
            end)()
        end
        clearspoofaccessories(c);
        (function()
            local s = c:FindFirstChildOfClass('Shirt')
            if saved and saved.ShirtX then
                if not s then
                    s = Instance.new('Shirt')
                    s.Parent = c
                end
                s.ShirtTemplate = saved.ShirtT or ''
            elseif s then
                s:Destroy()
            end
            local p = c:FindFirstChildOfClass('Pants')
            if saved and saved.PantsX then
                if not p then
                    p = Instance.new('Pants')
                    p.Parent = c
                end
                p.PantsTemplate = saved.PantsT or ''
            elseif p then
                p:Destroy()
            end
            local graphic = c:FindFirstChildOfClass('ShirtGraphic')
            if saved and saved.GraphicX then
                if not graphic then
                    graphic = Instance.new('ShirtGraphic')
                    graphic.Parent = c
                end
                graphic.Graphic = saved.GraphicT or ''
            elseif graphic then
                graphic:Destroy()
            end
            local head = c:FindFirstChild('Head')
            local f = head and head:FindFirstChildOfClass('Decal')
            if f and saved and saved.FaceT then
                f.Texture = saved.FaceT
            end
            local bc = c:FindFirstChildOfClass('BodyColors')
            if bc and saved and saved.Colors then
                for prop, val in pairs(saved.Colors) do
                    bc[prop] = val
                end
            end
        end)()
        if savedMeshes then
            for pname, e in pairs(savedMeshes) do
                local p = c:FindFirstChild(pname)
                if p and p:IsA('BasePart') then
                    if e.Part then
                        phowg:copy_spoof_body_part(p, e.Part)
                    end
                    if e.Texture ~= nil and p:IsA('MeshPart') then
                        p.TextureID = e.Texture
                    end
                    if e.Size ~= nil then
                        p.Size = e.Size
                    end
                end
            end
        end
        local humanoid = c:FindFirstChildOfClass('Humanoid')
        for name, value in pairs(savedScales or {}) do
            local scale = humanoid and humanoid:FindFirstChild(name)
            if scale then
                scale.Value = value
            end
        end
        for _, savedJoint in ipairs(savedJoints or {}) do
            local part = c:FindFirstChild(savedJoint.Parent)
            local joint = part and part:FindFirstChild(savedJoint.Name)
            if
                joint
                and joint:IsA('Motor6D')
                and joint.Part0
                and joint.Part1
                and joint.Part0.Name == savedJoint.Part0
                and joint.Part1.Name == savedJoint.Part1
            then
                joint.C0, joint.C1 = savedJoint.C0, savedJoint.C1
            end
        end
        if savedAccessories then
            for _, child in ipairs(c:GetChildren()) do
                if child:IsA('Accessory') then
                    child:Destroy()
                end
            end
            for _, accessory in ipairs(savedAccessories) do
                if not phowg:attach_spoof_accessory(accessory, c) then
                    accessory:Destroy()
                end
            end
            savedAccessories = nil
        end
        local animate = c:FindFirstChild('Animate')
        local damping = animate and animate:FindFirstChild('ScaleDampeningPercent')
        if animate and savedDampingPresent then
            if not damping then
                damping = Instance.new('NumberValue')
                damping.Name = 'ScaleDampeningPercent'
                damping.Parent = animate
            end
            damping.Value = savedDamping
        elseif damping then
            damping:Destroy()
        end
        if savedAnimations then
            phowg:apply_avatar_animations(c, nil, savedAnimations, savedWeights)
        end
        if updatekorbloxchar then
            updatekorbloxchar(c, Toggles.local_korblox and Toggles.local_korblox.Value or false)
        end
        if Toggles.remove_slowdowns and Toggles.remove_slowdowns.Value then
            startremoveslowdowns()
        end
        if Toggles.remove_jump_cooldown and Toggles.remove_jump_cooldown.Value then
            startremovejumpcooldown()
        end
        if phowg.resume_local_materials then
            phowg:resume_local_materials(c)
        end
        buildvisualizer()
    end
    for _, entry in pairs(savedMeshes or {}) do
        if entry.Part then
            entry.Part:Destroy()
        end
    end
    for _, accessory in ipairs(savedAccessories or {}) do
        accessory:Destroy()
    end
    if savedDesc and savedDesc.Destroy then
        savedDesc:Destroy()
    end
    Data.AvatarRestoreBusy = nil
    if Data.AvatarPendingQuery and not Data.SpoofBusy then
        phowg:finish_avatar_request()
    end
end
function resolveanimid(raw)
    local s = tostring(raw or '')
    if #s == 0 then
        return nil
    end
    if string.find(s, 'rbxasset', 1, true) then
        local d = string.match(s, '(%d+)')
        if d and tonumber(d) and tonumber(d) > 0 then
            return 'rbxassetid://' .. d
        end
        return nil
    end
    local digits = string.match(s, '(%d+)')
    if not digits or not tonumber(digits) or tonumber(digits) <= 0 then
        return nil
    end
    Data['AnimResolveCache'] = Data['AnimResolveCache'] or {}
    if Data['AnimResolveCache'][digits] then
        return Data['AnimResolveCache'][digits]
    end
    Data.AnimResolveRetry = Data.AnimResolveRetry or {}
    if tick() < (Data.AnimResolveRetry[digits] or 0) then
        return nil
    end
    local ok, objs = pcall(function()
        return game:GetObjects('rbxassetid://' .. digits)
    end)
    local found = nil
    if ok and objs then
        for _, o in ipairs(objs) do
            if not found and o:IsA('Animation') then
                local dd = string.match(tostring(o.AnimationId or ''), '(%d+)')
                if dd then
                    found = 'rbxassetid://' .. dd
                end
            end
            if not found and o.GetDescendants then
                for _, d in ipairs(o:GetDescendants()) do
                    if d:IsA('Animation') then
                        local dd = string.match(tostring(d.AnimationId or ''), '(%d+)')
                        if dd then
                            found = 'rbxassetid://' .. dd
                            break
                        end
                    end
                end
            end
            if found then
                break
            end
        end
        for _, o in ipairs(objs) do
            if o and o.Destroy then
                o:Destroy()
            end
        end
    end
    if found then
        Data['AnimResolveCache'][digits] = found
        Data.AnimResolveRetry[digits] = nil
        phowg:queue_assets({ found })
        return found
    end
    Data.AnimResolveRetry[digits] = tick() + 10
    return nil
end
function animplayerloop()
    while Toggles.anim_player_enabled and Toggles.anim_player_enabled.Value do
        local act = Data['AnimPlayerActive'] or false
        local hum = nil
        if act then
            local char = LocalPlayer.Character
            hum = char and char:FindFirstChildOfClass('Humanoid') or nil
        end
        if not act or not hum then
            local cur = Data['AnimPlayerTrack']
            if cur then
                pcall(function()
                    cur:Stop()
                end)
            end
            Data['AnimPlayerTrack'] = nil
            Data['AnimPlayerChar'] = nil
            Data['AnimPlayerId'] = nil
        else
            local customId = Options.anim_player_custom_id and Options.anim_player_custom_id.Value or nil
            local sel = Options.anim_player_animation and Options.anim_player_animation.Value or nil
            local id = nil
            if customId and #tostring(customId) > 0 then
                id = tostring(customId)
            elseif sel then
                id = Data['AnimPlayerList'] and Data['AnimPlayerList'][sel] or nil
                if id then
                    id = tostring(id)
                end
            end
            id = resolveanimid(id)
            local speed = (Options.anim_player_speed and Options.anim_player_speed.Value) or 100
            if speed < 1 then
                speed = 1
            end
            local startP = (Options.anim_player_start and Options.anim_player_start.Value) or 0
            local endP = (Options.anim_player_end and Options.anim_player_end.Value) or 100
            if startP > endP then
                startP, endP = endP, startP
            end
            local cur = Data['AnimPlayerTrack']
            if not id then
                if cur then
                    pcall(function()
                        cur:Stop()
                    end)
                end
                Data['AnimPlayerTrack'] = nil
                Data['AnimPlayerChar'] = nil
                Data['AnimPlayerId'] = nil
            elseif Data['AnimPlayerChar'] ~= LocalPlayer.Character or Data['AnimPlayerId'] ~= id then
                if cur then
                    pcall(function()
                        cur:Stop()
                    end)
                end
                local anim = Instance.new('Animation')
                anim.AnimationId = id
                cur = hum:LoadAnimation(anim)
                Data['AnimPlayerTrack'] = cur
                Data['AnimPlayerChar'] = LocalPlayer.Character
                Data['AnimPlayerId'] = id
                anim:Destroy()
            end
            if cur and Data['AnimPlayerId'] == id and hum.Parent then
                local len = cur.Length
                if len and len > 0 then
                    local sSec = len * math.clamp(startP, 0, 100) / 100
                    local eSec = len * math.clamp(endP, 0, 100) / 100
                    if not cur.IsPlaying then
                        cur:Play()
                    end
                    cur:AdjustSpeed(speed / 100)
                    if eSec > sSec then
                        local pos = cur.TimePosition
                        if pos < sSec or pos >= eSec then
                            cur.TimePosition = sSec
                        end
                    end
                else
                    if not cur.IsPlaying then
                        cur:Play()
                    end
                end
            end
        end
        RunService.Heartbeat:Wait()
    end
    local cur = Data['AnimPlayerTrack']
    if cur then
        pcall(function()
            cur:Stop()
        end)
    end
    Data['AnimPlayerTrack'] = nil
    Data['AnimPlayerChar'] = nil
    Data['AnimPlayerId'] = nil
    Data['AnimPlayerActive'] = false
end
local function clearspoofanimations()
    Data.SpoofGeneration = (Data.SpoofGeneration or 0) + 1
    for _, track in pairs(Data['SpoofAnims'] or {}) do
        if track then
            pcall(function()
                track:Stop(0)
                track:Destroy()
            end)
        end
    end
    Data['SpoofAnims'] = {}
    Data['SpoofId'] = nil
    Data['SpoofRaw'] = nil
    Data['SpoofCharacter'] = nil
    Data['SpoofPlayId'] = 0
end
function phowg:restore_local_animation_state()
    stopsilentanimations()
    clearspoofanimations()
    Data.AnimPlayerActive = false
    for _, key in ipairs({ 'AnimPlayerTrack', 'WallWalkIdleTrack', 'WallWalkMoveTrack' }) do
        local track = Data[key]
        Data[key] = nil
        if track then
            pcall(function()
                track:Stop(0)
                track:Destroy()
            end)
        end
    end
    Data.AnimPlayerChar, Data.AnimPlayerId = nil, nil
    local animations = ReplicatedStorage:FindFirstChild('ClientAnimations')
    local block = animations and animations:FindFirstChild('Block')
    if block and Data.AutoBlockAnimId and block.AnimationId == 'rbxassetid://0' then
        block.AnimationId = Data.AutoBlockAnimId
    end
    Data.AutoBlockAnimId = nil
end
phowg:register_cleanup('restore local animations', function(_, reason)
    if reason == 'unload' then
        phowg:restore_local_animation_state()
    end
end)
function play_animation(id)
    local digits = string.match(tostring(id or ''), '(%d+)')
    if not digits or not tonumber(digits) or tonumber(digits) <= 0 then
        return nil
    end
    local full = 'rbxassetid://' .. digits
    local char = LocalPlayer.Character
    local hum = char and char:FindFirstChildOfClass('Humanoid') or nil
    if not hum then
        return nil
    end
    if Data['SpoofAnims'] == nil then
        Data['SpoofAnims'] = {}
    end
    local cur = Data['SpoofAnims'][full]
    if cur == false then
        return nil
    end
    if cur then
        pcall(function()
            cur.Priority = Enum.AnimationPriority.Action4
            cur:Play(0, 1, 0)
        end)
        return cur
    end
    local anim = Instance.new('Animation')
    anim.AnimationId = full
    local ok, track = pcall(function()
        return hum:LoadAnimation(anim)
    end)
    anim:Destroy()
    if not (ok and track) then
        Data['SpoofAnims'][full] = false
        return nil
    end
    if
        LocalPlayer.Character ~= char
        or Data['SpoofCharacter'] ~= char
        or not Toggles.anim_spoof.Value
        or localactionblocked()
    then
        pcall(function()
            track:Stop(0)
            track:Destroy()
        end)
        return nil
    end
    pcall(function()
        track.Priority = Enum.AnimationPriority.Action4
        track:Play(0, 1, 0)
    end)
    Data['SpoofAnims'][full] = track
    return track
end
function spoofanimsync()
    if not (Toggles.anim_spoof and Toggles.anim_spoof.Value) or localactionblocked() then
        if Data['SpoofCharacter'] or next(Data['SpoofAnims'] or {}) then
            clearspoofanimations()
        end
        return
    end
    local raw = '126995783634131'
    local character = LocalPlayer.Character
    if Data['SpoofRaw'] ~= raw or Data['SpoofCharacter'] ~= character then
        clearspoofanimations()
        Data['SpoofRaw'] = raw
        Data['SpoofCharacter'] = character
        local digits = raw and string.match(raw, '(%d+)')
        local id = digits and ('rbxassetid://' .. digits) or nil
        if
            LocalPlayer.Character ~= character
            or not Toggles.anim_spoof.Value
            or localactionblocked()
            or Data['SpoofRaw'] ~= raw
        then
            clearspoofanimations()
            return
        end
        Data['SpoofId'] = id
    end
    local id = Data['SpoofId']
    if not id then
        return
    end
    local track = play_animation(id)
    if LocalPlayer.Character ~= character or not Toggles.anim_spoof.Value or localactionblocked() then
        clearspoofanimations()
        return
    end
    return track
end
function phowg:sync_animation_spoof()
    if phowg:defer_config_effect('animation spoof', phowg.sync_animation_spoof) then return end
    if Data.SpoofSyncing or Library.Unloaded or Data.SharedSignalsClosed then
        return
    end
    if not (Toggles.anim_spoof and Toggles.anim_spoof.Value) or Data.SafeMode or localactionblocked() then
        if Data.SpoofCharacter or next(Data.SpoofAnims or {}) then
            clearspoofanimations()
        end
        return
    end
    Data.SpoofSyncing = true
    local generation = Data.SpoofGeneration or 0
    local character = LocalPlayer.Character
    task.spawn(function()
        local ok, err = pcall(function()
            RunService.Heartbeat:Wait()
            if Library.Unloaded or Data.SharedSignalsClosed or Data.SafeMode or localactionblocked()
                or not Toggles.anim_spoof.Value or LocalPlayer.Character ~= character
                or (Data.SpoofGeneration or 0) ~= generation then
                return
            end
            local track = spoofanimsync()
            if not track then
                return
            end
            RunService.RenderStepped:Wait()
            if Data.SpoofAnims and Data.SpoofAnims[Data.SpoofId] == track then
                track:Stop(0)
            end
        end)
        Data.SpoofSyncing = false
        if not ok then
            clearspoofanimations()
            warn('[Phowg] server sided animation: ' .. tostring(err))
        end
    end)
end
function keepinventoryvisible()
    if
        (Toggles.keep_inventory and Toggles.keep_inventory.Value == true)
        or tick() < (Data.InventoryVisibleUntil or 0)
    then
        local on = false
        on = StarterGui:GetCoreGuiEnabled(Enum.CoreGuiType.Backpack)
        if on ~= true then
            (function()
                StarterGui:SetCoreGuiEnabled(Enum.CoreGuiType.Backpack, true)
            end)()
        end
    end
end
function phowg:preserve_inventory_visibility()
    if Library.Unloaded or Data.SharedSignalsClosed or Data.IsRespawning then
        return
    end
    Data.InventoryVisibleUntil = tick() + 0.5
    keepinventoryvisible()
end
function phowg:restore_crosshair_defaults()
    local state = Data.CrosshairAim
    if state and state.Instance.Parent then
        pcall(function()
            state.Instance.Visible = state.Visible
        end)
    end
    Data.CrosshairAim = nil
    if Library.SetMouseIconHidden then
        Library:SetMouseIconHidden('crosshair', false)
