function phowg:clear_crosshair()
    phowg:restore_crosshair_defaults()
    if Data.CrosshairGui then
        pcall(function()
            Data.CrosshairGui:Destroy()
        end)
    end
    for _, line in pairs(Data.CrosshairLines or {}) do
        pcall(function()
            line:Remove()
        end)
    end
    Data.CrosshairGui, Data.CrosshairLines, Data.CrosshairSegments = nil, nil, nil
    Data.CrosshairText = nil
    Data.CrosshairPos, Data.CrosshairAngle, Data.CrosshairRetryAt, Data.CrosshairShapeState = nil, nil, nil, nil
end
function phowg:get_crosshair_gui()
    local gui = Data.CrosshairGui
    if gui and gui.Parent then
        return gui
    end
    if tick() < (Data.CrosshairRetryAt or 0) then
        return nil
    end
    phowg:clear_crosshair()
    local ok, err = pcall(function()
        gui = Instance.new('ScreenGui')
        gui.Name = 'PhowgCrosshair'
        gui.IgnoreGuiInset = true
        gui.ResetOnSpawn = false
        gui.DisplayOrder = 10000
        gui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
        gui.Enabled = false
        local parent = CoreGui
        if gethui then
            local got, hidden = pcall(gethui)
            if got and typeof(hidden) == 'Instance' then
                parent = hidden
            end
        end
        local attached = pcall(function()
            gui.Parent = parent
        end)
        if not attached or not gui.Parent then
            gui.Parent = LocalPlayer:FindFirstChildOfClass('PlayerGui')
        end
        if not gui.Parent then
            error('crosshair UI parent is unavailable')
        end
    end)
    if not ok then
        if gui then
            pcall(function()
                gui:Destroy()
            end)
        end
        Data.CrosshairRetryAt = tick() + 0.25
        if not Data.CrosshairErrNotified then
            Data.CrosshairErrNotified = true
            warn('[Phowg] crosshair: ' .. tostring(err))
        end
        return nil
    end
    Data.CrosshairGui, Data.CrosshairSegments = gui, {}
    Data.CrosshairErrNotified = nil
    return gui
end
function phowg:draw_crosshair_segment(index, startPos, endPos, color, thickness, outlineOn, outlineColor, parent, storage)
    local gui, segments = parent or Data.CrosshairGui, storage or Data.CrosshairSegments
    local segment = segments[index]
    if not segment or segment.Line.Parent ~= gui or segment.Outline.Parent ~= gui then
        if segment then
            pcall(function()
                segment.Line:Destroy()
            end)
            pcall(function()
                segment.Outline:Destroy()
            end)
        end
        segment = {}
        for _, name in ipairs({ 'Outline', 'Line' }) do
            local frame = Instance.new('Frame')
            frame.Name = name .. tostring(index)
            frame.AnchorPoint = Vector2.new(0.5, 0.5)
            frame.BorderSizePixel = 0
            frame.BackgroundTransparency = 0
            frame.Active = false
            frame.ZIndex = (gui:IsA('GuiObject') and gui.ZIndex or 0) + (name == 'Line' and 2 or 1)
            frame.Parent = gui
            segment[name] = frame
        end
        segments[index] = segment
    end
    local offset = endPos - startPos
    local length = offset.Magnitude
    local center = (startPos + endPos) * 0.5
    local position = UDim2.fromOffset(center.X, center.Y)
    local rotation = math.deg(math.atan2(offset.Y, offset.X))
    local line, outline = segment.Line, segment.Outline
    line.Position, line.Rotation = position, rotation
    line.Size, line.BackgroundColor3 = UDim2.fromOffset(length, thickness), color
    line.Visible = length > 0
    outline.Visible = outlineOn and length > 0
    if outlineOn then
        outline.Position, outline.Rotation = position, rotation
        outline.Size, outline.BackgroundColor3 = UDim2.fromOffset(length, thickness + 2), outlineColor
    end
end
function phowg:render_crosshair_shape(parent, state, position, angle)
    state.Segments = state.Segments or {}
    local gap = math.max(
        0,
        phowg:visual_number('crosshair_offset', 15, 0, 50)
            + math.sin(tick() * 6) * phowg:visual_number('crosshair_bounce', 0, 0, 20)
    )
    local length = phowg:visual_number('crosshair_length', 15, 2, 50)
    local thickness = phowg:visual_number('crosshair_thickness', 2, 1, 5)
    local color = Options.custom_crosshair_color and Options.custom_crosshair_color.Value
    if typeof(color) ~= 'Color3' then
        color = Color3.new(1, 1, 1)
    end
    local outlineColor = Options.crosshair_outline_color and Options.crosshair_outline_color.Value
    if typeof(outlineColor) ~= 'Color3' then
        outlineColor = Color3.new(0, 0, 0)
    end
    local outlineOn = Toggles.crosshair_outline and Toggles.crosshair_outline.Value or false
    local realism = Toggles.realism and Toggles.realism.Value or false
    local shape = Options.crosshair_shape and Options.crosshair_shape.Value or 'cross'
    local count = 0
    if realism or shape:find('cross', 1, true) then
        for index = 1, 4 do
            local direction =
                Vector2.new(math.cos(angle + (index - 1) * math.pi / 2), math.sin(angle + (index - 1) * math.pi / 2))
            local a, b = position + direction * gap, position + direction * (gap + length)
            count += 1
            phowg:draw_crosshair_segment(count, a, b, color, thickness, outlineOn, outlineColor, parent, state.Segments)
            if realism then
                count += 1
                phowg:draw_crosshair_segment(
                    count,
                    b,
                    b + Vector2.new(-direction.Y, direction.X) * length * 0.7,
                    color,
                    thickness,
                    outlineOn,
                    outlineColor,
                    parent,
                    state.Segments
                )
            end
        end
    end
    for index = count + 1, #state.Segments do
        state.Segments[index].Line.Visible, state.Segments[index].Outline.Visible = false, false
    end
    for _, kind in ipairs({ 'dot', 'circle' }) do
        local widgets = state[kind]
        if not widgets or widgets.Inner.Parent ~= parent then
            widgets = {}
            for _, name in ipairs({ 'Outer', 'Inner' }) do
                local frame = Instance.new('Frame')
                frame.Name, frame.AnchorPoint, frame.BorderSizePixel, frame.BackgroundTransparency, frame.ZIndex =
                    kind .. name,
                    Vector2.new(0.5, 0.5),
                    0,
                    kind == 'circle' and 1 or 0,
                    (parent:IsA('GuiObject') and parent.ZIndex or 0) + (name == 'Inner' and 2 or 1)
                local corner = Instance.new('UICorner')
                corner.CornerRadius, corner.Parent = UDim.new(0, 0), frame
                if kind == 'circle' then
                    local stroke = Instance.new('UIStroke')
                    stroke.ApplyStrokeMode, stroke.Parent = Enum.ApplyStrokeMode.Border, frame
                    widgets[name .. 'Stroke'] = stroke
                end
                frame.Parent, widgets[name] = parent, frame
            end
            state[kind] = widgets
        end
        local visible = not realism and shape:find(kind, 1, true) ~= nil
        local diameter = kind == 'dot' and phowg:visual_number('crosshair_dot_size', 3, 1, 12)
            or phowg:visual_number('crosshair_circle_radius', 10, 2, 60) * 2
        widgets.Inner.Visible, widgets.Outer.Visible = visible, visible and outlineOn
        widgets.Inner.Position, widgets.Outer.Position =
            UDim2.fromOffset(position.X, position.Y), UDim2.fromOffset(position.X, position.Y)
        widgets.Inner.Size = UDim2.fromOffset(diameter, diameter)
        widgets.Outer.Size =
            UDim2.fromOffset(diameter + (kind == 'dot' and 2 or 0), diameter + (kind == 'dot' and 2 or 0))
        widgets.Inner.BackgroundColor3, widgets.Outer.BackgroundColor3 = color, outlineColor
        if kind == 'circle' then
            widgets.InnerStroke.Color, widgets.OuterStroke.Color = color, outlineColor
            widgets.InnerStroke.Thickness, widgets.OuterStroke.Thickness = thickness, thickness + 2
        end
    end
end
function phowg:render_crosshair_text(parent, position)
    local text = Options.crosshair_text and Options.crosshair_text.Value or ''
    local visible = phowg:toggle_enabled('crosshair_custom_text') and text ~= ''
    local label = Data.CrosshairText
    if visible and (not label or label.Parent ~= parent) then
        label = Instance.new('TextLabel')
        label.Name, label.BackgroundTransparency, label.BorderSizePixel = 'CrosshairText', 1, 0
        label.AnchorPoint, label.Size = Vector2.new(0.5, 0), UDim2.fromOffset(400, 24)
        label.Font, label.TextSize, label.TextStrokeTransparency = Enum.Font.Code, 13, 0
        label.TextStrokeColor3, label.RichText, label.ZIndex = Color3.new(0, 0, 0), false, 20
        label.Parent, Data.CrosshairText = parent, label
    end
    if label then
        label.Visible = visible
        label.Text = text
        label.TextColor3 = Options.custom_crosshair_color and Options.custom_crosshair_color.Value
            or Color3.new(1, 1, 1)
        label.Position = UDim2.fromOffset(
            position.X + phowg:visual_number('crosshair_text_x', 0, -300, 300),
            position.Y + 20 + phowg:visual_number('crosshair_text_y', 0, -300, 300)
        )
    end
end
function crosshairtick(Delta)
    if not (Toggles.custom_crosshair and Toggles.custom_crosshair.Value) then
        if Data.CrosshairGui then
            Data.CrosshairGui.Enabled = false
        end
        Data.CrosshairPos = nil
        phowg:restore_crosshair_defaults()
        return
    end
    local cam = Workspace.CurrentCamera
    if not cam then
        if Data.CrosshairGui then
            Data.CrosshairGui.Enabled = false
        end
        phowg:restore_crosshair_defaults()
        return
    end
    local gui = phowg:get_crosshair_gui()
    if not gui then
        return
    end
    local csel = (Options.crosshair_settings and Options.crosshair_settings.Value) or {}
    local function has(name)
        if type(csel) ~= 'table' then
            return csel == name
        end
        return csel[name] == true or table.find(csel, name) ~= nil
    end
    local function number(name, fallback, minimum, maximum)
        local value = tonumber(Options[name] and Options[name].Value)
        if not value or value ~= value or math.abs(value) == math.huge then
            return fallback
        end
        return math.clamp(value, minimum, maximum)
    end
    local center = cam.ViewportSize * 0.5
    local gotMouse, mouse = pcall(UserInputService.GetMouseLocation, UserInputService)
    if
        gotMouse
        and typeof(mouse) == 'Vector2'
        and mouse.X == mouse.X
        and mouse.Y == mouse.Y
        and math.abs(mouse.X) < 1e8
        and math.abs(mouse.Y) < 1e8
    then
        center = mouse
    end
    local anchor = nil
    if has('position on barrel') then
        local character = LocalPlayer.Character
        local tool = character and character:FindFirstChildOfClass('Tool')
        anchor = tool and tool:FindFirstChild('Handle')
    elseif has('position on target') then
        local record = phowg:get_active_target()
        local target = record and record.Player
        local character = target and target.Parent and target.Character
        anchor = character and character:FindFirstChild('Head')
    end
    if anchor and anchor:IsA('BasePart') then
        local ok, point, visible = pcall(cam.WorldToViewportPoint, cam, anchor.Position)
        if ok and visible and point then
            center = Vector2.new(point.X, point.Y)
        end
    end
    local dt = type(Delta) == 'number' and Delta > 0 and Delta < 1 and Delta or 1 / 60
    local speed = number('crosshair_speed', 1, 1, 10)
    local lerp = number('crosshair_lerp', 1, 1, 10)
    local pos = Data.CrosshairPos
    if
        typeof(pos) ~= 'Vector2'
        or pos.X ~= pos.X
        or pos.Y ~= pos.Y
        or math.abs(pos.X) >= 1e8
        or math.abs(pos.Y) >= 1e8
    then
        pos = center
    end
    pos = pos + (center - pos) * (1 - math.exp(-8 * speed * lerp * dt))
    Data.CrosshairPos = pos
    local ang = tonumber(Data.CrosshairAngle) or 0
    if ang ~= ang or math.abs(ang) == math.huge then
        ang = 0
    end
    ang = (ang + math.rad(number('crosshair_rotation', 0, 0, 360)) * dt) % (math.pi * 2)
    Data.CrosshairAngle = ang
    Data.CrosshairShapeState = Data.CrosshairShapeState or { Segments = Data.CrosshairSegments }
    phowg:render_crosshair_shape(gui, Data.CrosshairShapeState, pos, ang)
    phowg:render_crosshair_text(gui, pos)
    gui.Enabled = true
    local playerGui = LocalPlayer:FindFirstChildOfClass('PlayerGui')
    local screen = playerGui and playerGui:FindFirstChild('MainScreenGui')
    local aim = screen and screen:FindFirstChild('Aim')
    if has('disable gun crosshair') and aim then
        local state = Data.CrosshairAim
        if state and state.Instance ~= aim then
            phowg:restore_crosshair_defaults()
            state = nil
        end
        if not state then
            state = { Instance = aim, Visible = aim.Visible }
            Data.CrosshairAim = state
        end
        if aim.Visible then
            state.Visible = true
            aim.Visible = false
        end
    elseif Data.CrosshairAim then
        local state = Data.CrosshairAim
        if state.Instance.Parent then
            pcall(function()
                state.Instance.Visible = state.Visible
            end)
        end
        Data.CrosshairAim = nil
    end
    if Library.SetMouseIconHidden then
        Library:SetMouseIconHidden('crosshair', has('disable default cursor'))
    end
end
phowg:register_cleanup('crosshair', function(scope, reason)
    if not scope or reason == 'unload' then
        phowg:clear_crosshair()
    end
end)
function phowg:clear_server_position_indicator()
