phowg:register_cleanup('server position indicator', function(scope)
    if not scope or scope == LocalPlayer.Character then
        phowg:clear_server_position_indicator()
    end
end)
function serverpositionindicatortick(Delta)
    local drawings = Data.ServerPositionDrawings
    local function hide()
        if drawings then
            for _, object in pairs(drawings) do
                object.Visible = false
            end
        end
    end
    if not (Toggles.server_position_indicator and Toggles.server_position_indicator.Value) or Data.IsRespawning then
        hide()
        return
    end
    local character = LocalPlayer.Character
    local root = character and character:FindFirstChild('HumanoidRootPart')
    local camera = Workspace.CurrentCamera
    if not root or not camera then
        hide()
        return
    end
    local position, _, _, active = phowg:server_display_position(character, root)
    if
        not phowg:perfect_hit_vector(position)
        or Toggles.server_indicator_only_in_desync and Toggles.server_indicator_only_in_desync.Value and not active
    then
        hide()
        return
    end
    local point, visible = camera:WorldToViewportPoint(position)
    if not visible or point.Z <= 0 then
        hide()
        return
    end
    drawings = drawings or phowg:get_fake_position_drawings('ServerPositionDrawings')
    if not drawings then
        return
    end
    local screen = Vector2.new(point.X, point.Y)
    local offset = camera:WorldToViewportPoint(position + Vector3.new(0, 0.5, 0))
    local diameter = math.clamp((point.Y - offset.Y) * 10, 35, 45) * 0.7
    local color = Options.server_position_indicator_color and Options.server_position_indicator_color.Value
        or Color3.fromRGB(255, 100, 0)
    drawings.Fill.Position, drawings.Fill.Radius, drawings.Fill.Color, drawings.Fill.Transparency =
        screen, diameter * 0.5, color, 0.8
    drawings.Outline.Position, drawings.Outline.Radius, drawings.Outline.Transparency = screen, diameter * 0.5 + 1.4, 1
    local iconSize = Vector2.new(diameter * 0.6, diameter * 0.6)
    drawings.Icon.Position, drawings.Icon.Size, drawings.Icon.Transparency = screen - iconSize / 2, iconSize, 1
    drawings.Glow.Position, drawings.Glow.Radius, drawings.Glow.Transparency = screen, diameter * 0.5 + 2.8, 0.24
    drawings.GlowSoft.Position, drawings.GlowSoft.Radius, drawings.GlowSoft.Transparency =
        screen, diameter * 0.5 + 4.9, 0.1
    for _, name in ipairs({ 'Fill', 'Outline', 'Icon', 'Glow', 'GlowSoft' }) do
        drawings[name].Visible = true
    end
    local tracer = Toggles.server_indicator_tracer and Toggles.server_indicator_tracer.Value
    local client = Local_Data.ClientPos and Local_Data.ClientPos.Position or root.Position
    local from, onScreen = camera:WorldToViewportPoint(client)
    drawings.Tracer.Visible = tracer and onScreen and from.Z > 0 or false
    if drawings.Tracer.Visible then
        drawings.Tracer.From, drawings.Tracer.To = Vector2.new(from.X, from.Y), screen
        drawings.Tracer.Color, drawings.Tracer.Thickness = color, 1.5
    end
end
