function updateflashbang(enabled)
    local previous = Data.FlashbangState
    local full = Options.suppress_flashbang_value and Options.suppress_flashbang_value.Value == 'full'
    if enabled and previous and previous.Full == full and not Library.Unloaded and not Data.Unloading then
        return
    end
    Data.FlashbangState = nil
    if previous then
        for _, connection in ipairs(previous.Connections) do
            connection:Disconnect()
        end
        for object, record in pairs(previous.Properties) do
            for _, connection in ipairs(record.Connections) do
                connection:Disconnect()
            end
            if object.Parent then
                pcall(function()
                    if object[record.Property] == record.Applied then
                        object[record.Property] = record.Value
                    end
                end)
            end
        end
    end
    if not enabled or Library.Unloaded or Data.Unloading then
        return
    end
    local state = { Full = full, Connections = {}, Properties = {}, Animators = {} }
    Data.FlashbangState = state
    local function bind(signal, callback, scope, name)
        state.Connections[#state.Connections + 1] = connectshared(signal, function(...)
            if Data.FlashbangState == state then
                callback(...)
            end
        end, scope, name, 0, name, scope)
    end
    local function suppress(object, property, value)
        if state.Properties[object] then
            return
        end
        local record = { Property = property, Value = object[property], Applied = value, Connections = {} }
        state.Properties[object] = record
        record.Connections[1] = connectshared(object:GetPropertyChangedSignal(property), function()
            if Data.FlashbangState == state and object[property] ~= value then
                record.Value = object[property]
                object[property] = value
            end
        end, object, 'flashbang/' .. property)
        record.Connections[2] = connectshared(object.Destroying, function()
            state.Properties[object] = nil
            for _, connection in ipairs(record.Connections) do
                connection:Disconnect()
            end
        end, object, 'flashbang/destroyed')
        object[property] = value
    end
    local function inspect(object)
        if object.Name == 'whiteScreen' and object:IsA('GuiObject') then
            local parent = object.Parent
            if parent and parent.Name == 'MainScreenGui' then
                suppress(object, 'Visible', false)
            end
        elseif full and object:IsA('Sound') and object.SoundId:match('%d+') == '8754837104' then
            suppress(object, 'Volume', 0)
        end
    end
    local function character_added(character)
        if not full then
            return
        end
        local function inspect_animator(animator)
            if not animator:IsA('Animator') or state.Animators[animator] then
                return
            end
            state.Animators[animator] = true
            local function stop_flash(track)
                local animation = track.Animation
                local scripts = LocalPlayer:FindFirstChild('PlayerGui')
                local screen = scripts and scripts:FindFirstChild('MainScreenGui')
                local framework = screen and (screen:FindFirstChild('Framework') or screen:FindFirstChild('F'))
                local flash = framework and framework:FindFirstChild('FBAnimation')
                if animation and flash and animation.AnimationId == flash.AnimationId then
                    track:Stop(0)
                end
            end
            bind(animator.AnimationPlayed, stop_flash, animator, 'flashbang/animation')
            for _, track in ipairs(animator:GetPlayingAnimationTracks()) do
                stop_flash(track)
            end
        end
        bind(character.DescendantAdded, inspect_animator, character, 'flashbang/animator')
        for _, object in ipairs(character:GetDescendants()) do
            inspect_animator(object)
        end
    end
    bind(LocalPlayer.DescendantAdded, inspect, LocalPlayer, 'flashbang/effects')
    for _, object in ipairs(LocalPlayer:GetDescendants()) do
        inspect(object)
    end
    if full then
        bind(LocalPlayer.CharacterAdded, character_added, LocalPlayer, 'flashbang/character')
        if LocalPlayer.Character then
            character_added(LocalPlayer.Character)
        end
    end
end
phowg:register_cleanup('flashbang suppression', function(_, reason)
    if reason == 'unload' then
        updateflashbang(false)
    end
end)
function updateaspectratio(enabled)
