                cam.CFrame = cam.CFrame * CFrame.new(0, 0, 0, 1, 0, 0, 0, pct, 0, 0, 0, 1)
            end
        end, RunService, 'frame/aspect ratio')
    end
end
function phowg:clear_region_text()
    local state = Data.RegionTextState
    Data.RegionTextState = nil
    if not state then
        return
    end
    for _, connection in ipairs(state.Connections) do
        connection:Disconnect()
    end
    if state.Label and state.Label.Parent and state.Label.Text == state.Applied then
        state.Label.Text = state.Original
    end
end
function phowg:update_region_text()
    phowg:clear_region_text()
    local text = Options.world_region_text_value and Options.world_region_text_value.Value or ''
    if Library.Unloaded or Data.SharedSignalsClosed or not phowg:toggle_enabled('world_region_text') or text == '' then
        return
    end
    local state = { Connections = {}, Applied = text, Pending = false }
    Data.RegionTextState = state
    local function refresh()
        if Data.RegionTextState ~= state or state.Pending then
            return
        end
        state.Pending = true
        task.defer(function()
            if Data.RegionTextState == state then
                phowg:update_region_text()
            end
        end)
    end
    local parent = LocalPlayer
    for _, name in ipairs({
        'PlayerGui', 'TopbarStandard', 'Holders', 'Left', 'Widget', 'IconButton',
        'Menu', 'IconSpot', 'Contents', 'IconLabelContainer', 'IconLabel',
    }) do
        local expected = name
        local function changed(child)
            if child.Name == expected then
                refresh()
            end
        end
        state.Connections[#state.Connections + 1] =
            connectshared(parent.ChildAdded, changed, parent, 'region text/added')
        state.Connections[#state.Connections + 1] =
            connectshared(parent.ChildRemoved, changed, parent, 'region text/removed')
        parent = parent:FindFirstChild(name)
        if not parent then
            return
        end
    end
    if not (parent:IsA('TextLabel') or parent:IsA('TextButton')) then
        return
    end
    state.Label, state.Original = parent, parent.Text
    state.Connections[#state.Connections + 1] = connectshared(parent:GetPropertyChangedSignal('Text'), function()
        if Data.RegionTextState == state and parent.Text ~= state.Applied then
            state.Original = parent.Text
            parent.Text = state.Applied
        end
    end, parent, 'region text/value')
    parent.Text = state.Applied
end
phowg:register_cleanup('region text', function(scope)
    if not scope then
        phowg:clear_region_text()
    end
end)
function updatemoneytext()
    local pGui = LocalPlayer:FindFirstChild('PlayerGui')
    local mainGui = pGui and pGui:FindFirstChild('MainScreenGui')
    local moneyText = mainGui and mainGui:FindFirstChild('MoneyText')
    if not moneyText then
        return
    end
    if not Data['MoneyTextOrig'] or Data['MoneyTextOrig'].inst ~= moneyText then
        Data['MoneyTextOrig'] = { inst = moneyText }
        Data['MoneyTextOrig'].pos = moneyText.Position
        Data['MoneyTextOrig'].font = moneyText.Font
        Data['MoneyTextOrig'].size = moneyText.TextSize
        Data['MoneyTextOrig'].stroke = moneyText.TextStrokeTransparency
        Data['MoneyTextOrig'].anchor = moneyText.AnchorPoint
        Data['MoneyTextOrig'].color = moneyText.TextColor3
    end
    local orig = Data['MoneyTextOrig']
    local enabled = Toggles.custom_money_text and Toggles.custom_money_text.Value;
    (function()
        local promote = mainGui and mainGui:FindFirstChild('Promote')
        if promote then
            promote.Visible = not enabled
        end
    end)()
    local selected = (Options.custom_money_text_value and Options.custom_money_text_value.Value) or 'default'
    local col = (Options.custom_money_text_color and Options.custom_money_text_color.Value)
        or Color3.fromRGB(95, 255, 87)
    for _, child in ipairs(moneyText:GetChildren()) do
        if child.Name == '\0' then
            child:Destroy()
        end
    end
    if enabled then
        moneyText.TextColor3 = col
        if selected == 'simple' then
            moneyText.TextSize = 24
            moneyText.TextStrokeTransparency = 0
            moneyText.AnchorPoint = Vector2.new(1, 1)
            moneyText.Position = UDim2.new(1, -10, 1, -10)
        else
            (function()
                moneyText.Font = orig.font or Enum.Font.GothamMedium
                moneyText.TextSize = orig.size or 25
                moneyText.TextStrokeTransparency = (orig.stroke ~= nil) and orig.stroke or 1
                moneyText.AnchorPoint = orig.anchor or Vector2.new(0, 0)
                moneyText.Position = orig.pos or UDim2.new(1, -210, 1, -60)
            end)()
        end
    else
        (function()
            moneyText.TextColor3 = orig.color or Color3.fromRGB(95, 255, 87)
            moneyText.Font = orig.font or Enum.Font.GothamMedium
            moneyText.TextSize = orig.size or 25
            if orig.stroke ~= nil then
                moneyText.TextStrokeTransparency = orig.stroke
            end
            if orig.anchor then
                moneyText.AnchorPoint = orig.anchor
            end
            if orig.pos then
                moneyText.Position = orig.pos
            end
        end)()
    end
end
function formatmoneytext(raw)
    local s = tostring(raw or '')
    local neg = string.sub(s, 1, 1) == '-'
    local digits = s:gsub('%D', '')
    if digits == '' then
        return s
    end
    local out = ''
    while #digits > 3 do
        out = ',' .. string.sub(digits, -3) .. out
        digits = string.sub(digits, 1, -4)
    end
    local num = digits .. out
    if neg then
        return '-$' .. num
    end
    return '$' .. num
end
function applymoneylock()
    local pGui = LocalPlayer:FindFirstChild('PlayerGui')
    local mainGui = pGui and pGui:FindFirstChild('MainScreenGui')
    local moneyText = mainGui and mainGui:FindFirstChild('MoneyText')
    if not moneyText then
        return
    end
    if Data['MoneyLockConn'] then
        Data['MoneyLockConn']:Disconnect()
    end
    Data['MoneyLockConn'] = nil
    local lock = Data['CustomMoneyLock']
    if not lock or lock == '' then
        if moneyText then
            moneyText.Text = formatmoneytext(Local_Data['Currency'] or 0)
        end
        updatemoneytext()
        return
    end
    moneyText.Text = lock;
    (function()
        if Data['CustomMoneyNeg'] then
            moneyText.TextColor3 = Color3.fromRGB(255, 0, 0)
        else
            moneyText.TextColor3 = (Options.custom_money_text_color and Options.custom_money_text_color.Value)
                or Color3.fromRGB(95, 255, 87)
        end
    end)()
    Data['MoneyLockConn'] = connectshared(moneyText:GetPropertyChangedSignal('Text'), function()
        if Data['MoneySetting'] then
            return
        end
        if moneyText.Text ~= Data['CustomMoneyLock'] then
            Data['MoneySetting'] = true
            moneyText.Text = Data['CustomMoneyLock']
            Data['MoneySetting'] = false
        end
    end, moneyText, 'event/moneyText:GetPropertyChangedSignal(Text)', 0, 'property/Text', moneyText)
end
function applywalletmoneytext()
    local lock = Data['CustomMoneyLock']
    local live = formatmoneytext(Local_Data['Currency'] or 0)
    local neg = Data['CustomMoneyNeg'] or false
    local targets = {}
    (function()
        local wps = Workspace:FindFirstChild('Players')
        local mdl = wps and wps:FindFirstChild(LocalPlayer.Name) or nil
        local tool = mdl and mdl:FindFirstChild('[Wallet]') or nil
        local handle = tool and tool:FindFirstChild('Handle') or nil
        local bg = handle and handle:FindFirstChild('BillboardGui') or nil
        local tl = bg and bg:FindFirstChild('TextLabel') or nil
        if tl then
            table.insert(targets, tl)
        end
    end)();
    (function()
        local ch = LocalPlayer.Character
        local tool = ch and ch:FindFirstChild('[Wallet]') or nil
        local handle = tool and tool:FindFirstChild('Handle') or nil
        local bg = handle and handle:FindFirstChild('BillboardGui') or nil
        local tl = bg and bg:FindFirstChild('TextLabel') or nil
        if tl then
            local dup = false
            for _, e in ipairs(targets) do
                if e == tl then
                    dup = true
                    break
                end
            end
            if not dup then
                table.insert(targets, tl)
            end
        end
    end)()
    for _, tl in ipairs(targets) do
        if not lock or lock == '' then
            tl.Text = live
            tl.TextColor3 = Color3.fromRGB(255, 255, 255)
        else
            tl.Text = lock
            tl.Font = Enum.Font.GothamMedium
            if neg then
                tl.TextColor3 = Color3.fromRGB(255, 0, 0)
            end
        end
    end
end
