function phowg:prepare_esp_bars(source)
    if source:find('ESP.PhowgBarHookRevision = 1', 1, true) then
        return source
    end
    local marker = 'local Update_ESP = LPH_NO_VIRTUALIZE(function()'
    local at = source:find(marker, 1, true)
    if not at then
        error('ESP render hook is unavailable')
    end
    local hook = [[
ESP.PhowgBarHookRevision = 1
local PhowgNativeRenderPlayer = RenderPlayer
RenderPlayer = function(player, record, now)
    PhowgNativeRenderPlayer(player, record, now)
    if ESP.PhowgRenderBars then ESP.PhowgRenderBars(ESP, player, record, now) end
end
]]
    return source:sub(1, at - 1) .. hook .. source:sub(at)
end
function phowg:esp_bar_layout(position, size, side, thickness, gap, lane, ratio, inverted)
    local horizontal = side == 'top' or side == 'bottom'
    local offset = gap + lane * (thickness + 3)
    local origin
    if side == 'right' then
        origin = position + Vector2.new(size.X + offset, 0)
    elseif side == 'top' then
        origin = position - Vector2.new(0, offset + thickness)
    elseif side == 'bottom' then
        origin = position + Vector2.new(0, size.Y + offset)
    else
        origin = position - Vector2.new(offset + thickness, 0)
    end
    local track = horizontal and Vector2.new(size.X, thickness) or Vector2.new(thickness, size.Y)
    local length = (horizontal and size.X or size.Y) * math.clamp(ratio, 0, 1)
    local fillSize = horizontal and Vector2.new(length, thickness) or Vector2.new(thickness, length)
    local fillPosition = origin
    if horizontal and inverted then
        fillPosition = origin + Vector2.new(size.X - length, 0)
    elseif not horizontal and not inverted then
        fillPosition = origin + Vector2.new(0, size.Y - length)
    end
    return origin, track, fillPosition, fillSize, horizontal
end
