            Duration = phowg:visual_number(prefix .. '_smooth_time', 0.15, 0, 1),
            Side = Options[prefix .. '_side'] and Options[prefix .. '_side'].Value
                or (definition.Kind == 'Health' and 'left' or 'right'),
            Inverted = Options[prefix .. '_direction'] and Options[prefix .. '_direction'].Value == 'inverted' or false,
            Thickness = phowg:visual_number(prefix .. '_thickness', 2, 1, 8),
            Gap = phowg:visual_number(prefix .. '_gap', 4, 2, 16),
            Adaptive = Toggles[prefix .. '_adaptive'] and Toggles[prefix .. '_adaptive'].Value or false,
            LowColor = Options[prefix .. '_low_color'] and Options[prefix .. '_low_color'].Value
                or Color3.fromRGB(255, 70, 80),
        }
