function phowg:render_esp_bars(esp, player, record, now)
    if not record or not record.Rendering or not (Toggles.player_esp_enabled and Toggles.player_esp_enabled.Value) then
        return
    end
    local draws = record.Drawings
    local character = record.Character
    local anchor = record.Anchor
        or character and (character:FindFirstChild('UpperTorso') or character:FindFirstChild('Torso'))
    local camera = Workspace.CurrentCamera
    if not draws or not anchor or not camera then
        return
    end
    local position, size = record.LayoutPosition, record.LayoutSize
    if not position or not size then
        local upper, visible = camera:WorldToViewportPoint(anchor.Position + esp.Settings.Misc.Offset)
        local lower = camera:WorldToViewportPoint(anchor.Position - esp.Settings.Misc.Offset)
        local height, width = (lower.Y - upper.Y) * 6, (lower.Y - upper.Y) * 4
        if not visible or upper.Z <= 0 or height <= 0 or height ~= height then
            return
        end
        position, size = Vector2.new(lower.X - width / 2, lower.Y - height / 2), Vector2.new(width, height)
    end
    local width = size.X
    if record.PhowgBarCharacter ~= character then
        record.PhowgBarState, record.PhowgBarCharacter = {}, character
    end
    record.PhowgBarState = record.PhowgBarState or {}
    local elapsed = math.clamp(now - (record.PhowgBarAt or now), 0, 0.2)
    record.PhowgBarAt = now
    local lanes = record.PhowgBarLanes
    if not lanes then
        lanes = {}
        record.PhowgBarLanes = lanes
    end
    lanes.left, lanes.right, lanes.top, lanes.bottom = 0, 0, 0, 0
    local topSpace, bottomSpace, rightSpace, healthTextOffset = 0, 0, 0, nil
    for _, definition in ipairs(Data.ESPBarDefinitions) do
        local kind = definition.Kind
        local settings = esp.Settings.Bars[kind]
        local options = Data.ESPBarOptions and Data.ESPBarOptions[kind]
        local bar, outline = draws[definition.Bar], draws[definition.Outline]
        local raw = tonumber(kind == 'Health' and record.Fake_Health or record.Fake_Armor) or 0
        local maximum = kind == 'Health' and math.max(1, tonumber(record.Fake_MaxHealth) or 100) or 130
        if raw ~= raw or math.abs(raw) == math.huge then
            raw = 0
        end
        local ratio = math.clamp(raw / maximum, 0, 1)
        local shown = settings
            and settings.Enabled
            and bar
            and outline
            and bar.Visible
            and (kind ~= 'Armor' or not settings.Hide_If_Empty or raw > 0)
        local smooth = options and options.Smooth
        local duration = options and options.Duration or 0.15
        local previous = record.PhowgBarState[kind]
        local display = ratio
        if shown and smooth and previous and duration > 0 then
            display = previous + (ratio - previous) * (1 - math.exp(-elapsed * 5 / duration))
        end
        record.PhowgBarState[kind] = shown and display or nil
        if shown then
            local side = options and options.Side or (kind == 'Health' and 'left' or 'right')
            local inverted = options and options.Inverted or false
            local thickness = options and options.Thickness or 2
            local gap = options and options.Gap or 4
            local lane = lanes[side] or 0
            lanes[side] = lane + 1
            local origin, track, fillPosition, fillSize, horizontal =
                phowg:esp_bar_layout(position, size, side, thickness, gap, lane, display, inverted)
            outline.Position, outline.Size = origin - Vector2.new(1, 1), track + Vector2.new(2, 2)
            bar.Position, bar.Size = fillPosition, fillSize
            local first = settings.BaseColor or settings.Colors[1]
            local last = settings.GradientColor or settings.Colors[2] or first
            if options and options.Adaptive then
                local low = options.LowColor
                first, last = low:Lerp(first, ratio), low:Lerp(last, ratio)
            end
            if esp.Settings.Target.Enabled and (esp.ActiveTarget == player) then
                first, last = esp.Settings.Target.Color, esp.Settings.Target.Color
            end
            bar.Color = esp.NativeBarGradients and settings.Gradient and (esp.BarWhiteColor or Color3.new(1, 1, 1))
                or first
            local image = draws[definition.Gradient]
            if image then
                image.Visible = false
            end
            local shift = settings.Moving_Gradient and math.sin(now * esp.Settings.Bars.Speed * math.pi * 2) * 0.2 or 0
            if esp.NativeBarGradients and esp.SetBarGradient then
                esp:SetBarGradient(record, kind, first, last, horizontal, inverted, shift)
            end
            if not esp.NativeBarGradients then
                for index = 1, 12 do
                    local segment = draws[kind .. 'SpatialGradient' .. index]
                    if segment then
                        segment.Visible = settings.Gradient and display > 0
                        if segment.Visible then
                            local along = (horizontal and fillSize.X or fillSize.Y) / 12
                            segment.Position = fillPosition
                                + (
                                    horizontal and Vector2.new(along * (index - 1), 0)
                                    or Vector2.new(0, along * (index - 1))
                                )
                            segment.Size = horizontal and Vector2.new(along + 0.1, thickness)
                                or Vector2.new(thickness, along + 0.1)
                            segment.Color = first:Lerp(last, math.clamp((index - 0.5) / 12 + shift, 0, 1))
                            segment.Transparency = bar.Transparency
                        end
                    end
                end
            end
            if kind == 'Health' and draws.HealthText and draws.HealthText.Visible then
                local text = draws.HealthText
                local textPosition = horizontal and origin + Vector2.new(track.X + 4, -4)
                    or side == 'right' and origin + Vector2.new(thickness + 4, size.Y + 2)
                    or origin - Vector2.new(text.TextBounds.X + 4, 0)
                if text.Position ~= textPosition then
                    text.Position = textPosition
                end
                healthTextOffset = textPosition - position
            end
            if side == 'top' then
                topSpace = math.max(topSpace, gap + (lane + 1) * (thickness + 3))
            elseif side == 'bottom' then
                bottomSpace = math.max(bottomSpace, gap + (lane + 1) * (thickness + 3))
            end
            if side == 'right' then
                rightSpace = math.max(rightSpace, gap + lane * (thickness + 3) + thickness + 4)
            end
        end
    end
    local applied = esp.NativeLabelSpacing and record.PhowgAppliedBarSpacing
    local topDelta = topSpace - (applied and applied.Top or 0)
    local bottomDelta = bottomSpace - (applied and applied.Bottom or 0)
    if topDelta ~= 0 then
        for _, key in ipairs(Data.ESPBarTopLabels) do
            if draws[key] and draws[key].Visible then
                draws[key].Position = draws[key].Position - Vector2.new(0, topDelta)
            end
        end
    end
    if bottomDelta ~= 0 then
        for _, key in ipairs(Data.ESPBarBottomLabels) do
            if draws[key] and draws[key].Visible then
                draws[key].Position = draws[key].Position + Vector2.new(0, bottomDelta)
            end
        end
    end
    for _, key in ipairs(Data.ESPBarRightLabels) do
        local text = draws[key]
        if text and text.Visible then
            local textPosition = Vector2.new(position.X + width + math.max(4, rightSpace), text.Position.Y)
            if text.Position ~= textPosition then
                text.Position = textPosition
            end
        end
    end
    if esp.NativeLabelSpacing then
        local spacing = record.PhowgBarSpacing
        if not spacing then
            spacing = {}
            record.PhowgBarSpacing = spacing
        end
        spacing.Top, spacing.Bottom, spacing.Right, spacing.HealthText =
            topSpace, bottomSpace, rightSpace, healthTextOffset
    end
end
function phowg:clear_world_esp(kind)
    Data.WorldESP = Data.WorldESP or {}
    for owner, marker in pairs(Data.WorldESP) do
        if not kind or marker.Kind == kind then
            phowg:destroy_world_esp_marker(marker)
            Data.WorldESP[owner] = nil
        end
    end
    Data.WorldESPScanAt = 0
end
function phowg:cash_amount(owner)
    for _, name in ipairs({ 'Amount', 'Money', 'Cash', 'Value' }) do
        local amount = owner:GetAttribute(name)
        local value = owner:FindFirstChild(name)
        amount = tonumber(amount or value and value:IsA('ValueBase') and value.Value)
        if amount and amount == amount and amount >= 0 and amount < math.huge then
            return amount
        end
    end
    for _, value in ipairs(owner:GetDescendants()) do
        if value:IsA('TextLabel') or value:IsA('TextButton') then
            local digits = value.Text:match('%$%s*([%d,]+%.?%d*)')
            local amount = digits and tonumber((digits:gsub(',', '')))
            if amount then
                return amount
            end
        end
    end
    return nil
end
function phowg:stop_world_esp_index()
    local index = Data.WorldESPIndex
    Data.WorldESPIndex, Data.WorldESPCandidates = nil, nil
    if not index then
        return
    end
    for _, connection in pairs(index.Connections) do
        connection:Disconnect()
    end
    for _, group in pairs(index.Groups) do
        for _, connection in ipairs(group.Connections) do
            connection:Disconnect()
        end
    end
end
function phowg:sync_world_esp_index()
    phowg:stop_world_esp_index()
    local cash = Toggles.cash_esp and Toggles.cash_esp.Value or Toggles.cash_aura and Toggles.cash_aura.Value
    local rockets = Toggles.rpg_warnings and Toggles.rpg_warnings.Value
    local grenades = Toggles.grenade_warnings and Toggles.grenade_warnings.Value
    if not (cash or rockets or grenades) or Data.SharedSignalsClosed then
        return
    end
    local index: {
        Connections: { [string]: any },
        Groups: { [any]: any },
        Dirty: { [any]: boolean },
        Rebuild: boolean,
        Ignored: any,
    } =
        { Connections = {}, Groups = {}, Dirty = {}, Rebuild = true }
    Data.WorldESPIndex = index
    local function active()
        return Data.WorldESPIndex == index
    end
    local function dirty(instance)
        if not active() or not index.Ignored then
            return
        end
        local root = instance
        while root and root.Parent ~= index.Ignored do
            root = root.Parent
        end
        if not root or root.Name == 'Shop' then
            return
        end
        if root.Name == 'Drop' then
            if not cash then
                return
            end
            local drop = instance
            while drop and drop.Parent ~= root do
                drop = drop.Parent
            end
            if drop and drop.Name == 'MoneyDrop' then
                index.Dirty[drop] = true
            end
        elseif rockets or grenades then
            index.Dirty[root] = true
        end
    end
    local function bind(ignored)
        if not active() then
            return
        end
        for _, key in ipairs({ 'added', 'removed' }) do
            if index.Connections[key] then
                index.Connections[key]:Disconnect()
                index.Connections[key] = nil
            end
        end
        for _, group in pairs(index.Groups) do
            for _, connection in ipairs(group.Connections) do
                connection:Disconnect()
            end
        end
        table.clear(index.Groups)
        table.clear(index.Dirty)
        index.Ignored, index.Rebuild = ignored, true
        if not ignored then
            return
        end
        index.Connections.added = connectshared(
            ignored.DescendantAdded,
            dirty,
            ignored,
            'world esp/added',
            0,
            'event/DescendantAdded',
            ignored
        )
        -- DescendantRemoving fires while the old ancestry is still available.
        index.Connections.removed = connectshared(ignored.DescendantRemoving, function(instance)
            dirty(instance)
            if instance.Parent == ignored and instance.Name == 'Drop' then
                for owner in pairs(index.Groups) do
                    if owner:IsDescendantOf(instance) then
                        index.Dirty[owner] = true
                    end
                end
            end
        end, ignored, 'world esp/removed', 0, 'event/DescendantRemoving', ignored)
        for _, owner in ipairs(ignored:GetChildren()) do
            if owner.Name == 'Drop' and cash then
                for _, drop in ipairs(owner:GetChildren()) do
                    dirty(drop)
                end
            else
                dirty(owner)
            end
        end
    end
    index.Connections.workspaceAdded = connectshared(Workspace.ChildAdded, function(child)
        if child.Name == 'Ignored' then
            bind(child)
        end
    end, Workspace, 'world esp/folder added', 0, 'event/ChildAdded', Workspace)
    index.Connections.workspaceRemoved = connectshared(Workspace.ChildRemoved, function(child)
        if child == index.Ignored then
            bind(nil)
        end
    end, Workspace, 'world esp/folder removed', 0, 'event/ChildRemoved', Workspace)
    bind(Workspace:FindFirstChild('Ignored'))
end
function phowg:scan_world_esp()
    local index = Data.WorldESPIndex
    if not index then
        return
    end
    local ignored = index.Ignored
    local cash = Toggles.cash_esp and Toggles.cash_esp.Value or Toggles.cash_aura and Toggles.cash_aura.Value
    local rockets = Toggles.rpg_warnings and Toggles.rpg_warnings.Value
    local grenades = Toggles.grenade_warnings and Toggles.grenade_warnings.Value
    for owner in pairs(index.Dirty) do
        index.Dirty[owner] = nil
        local old = index.Groups[owner]
        if old then
            for _, connection in ipairs(old.Connections) do
                connection:Disconnect()
            end
        end
        index.Groups[owner] = nil
        index.Rebuild = true
        if ignored and owner:IsDescendantOf(ignored) then
            local group, seen = { Candidates = {}, Connections = {} }, {}
            local function add(target, part, kind)
                if target and part and part:IsA('BasePart') and part.Parent and not seen[target] then
                    seen[target] = true
                    group.Candidates[#group.Candidates + 1] = { Owner = target, Part = part, Kind = kind }
                end
            end
            if cash and owner.Name == 'MoneyDrop' and owner.Parent and owner.Parent.Name == 'Drop' then
                add(
                    owner,
                    owner:IsA('BasePart') and owner
                        or owner:IsA('Model')
                            and (owner.PrimaryPart or owner:FindFirstChildWhichIsA('BasePart', true)),
                    'cash'
                )
            elseif
                owner.Parent == ignored
                and owner.Name ~= 'Shop'
                and owner.Name ~= 'Drop'
                and not owner:IsA('Tool')
                and not owner:FindFirstChildOfClass('Humanoid')
            then
                if grenades and owner.Name == 'GrenadeLauncherAmmo' then
                    local main = owner:IsA('BasePart') and owner or owner:FindFirstChild('Main', true)
                    if not (main and main:IsA('BasePart')) then
                        main = owner:IsA('Model') and owner.PrimaryPart
                            or owner:FindFirstChildWhichIsA('BasePart', true)
                    end
                    add(owner, main, 'launcher')
                else
                    local parts = owner:IsA('BasePart') and { owner } or owner:GetDescendants()
                    for _, part in ipairs(parts) do
                        if part:IsA('BasePart') and not part:FindFirstAncestorOfClass('Tool') then
                            if rockets and part.Name == 'Launcher' then
                                add(owner, part, 'rocket')
                            elseif grenades and part.Name == 'Handle' then
                                group.Connections[#group.Connections + 1] = connectshared(
                                    part:GetPropertyChangedSignal('Anchored'),
                                    function()
                                        if Data.WorldESPIndex == index then
                                            index.Dirty[owner] = true
                                        end
                                    end,
                                    part,
                                    'world esp/grenade armed',
                                    0,
                                    'property/Anchored',
                                    part
                                )
                                if not part:FindFirstChild('TouchInterest') and isgrenadepart(part) then
                                    add(part, part, 'grenade')
                                end
                            end
                        end
                    end
                end
            end
            index.Groups[owner] = group
        end
    end
    if index.Rebuild then
        local candidates = {}
        for _, group in pairs(index.Groups) do
            for _, candidate in ipairs(group.Candidates) do
                candidates[#candidates + 1] = candidate
            end
        end
        Data.WorldESPCandidates, index.Rebuild = candidates, false
    end
end
function phowg:cash_aura_position()
    if
        Library.Unloaded
        or Data.SharedSignalsClosed
        or Data.IsRespawning
        or Data.VoidActive
        or Data.HideVoid
        or Data.RagebotIdle
        or Data.Buying
        or Data.MaskBuying
        or reloadvoidactive()
        or localactionblocked()
    then
        return nil
    end
    local character = LocalPlayer.Character
    local root = character and character:FindFirstChild('HumanoidRootPart')
    local humanoid = character and character:FindFirstChildOfClass('Humanoid')
    if not root or not humanoid or humanoid.Health <= 0 then
        return nil
    end
    local spam = Data.RagebotVoidSpam
    if spam and spam.Void then
        return nil
    end
    local age = tick() - (Data.AppliedServerAt or -math.huge)
    local fresh = Data.AppliedServerCharacter == character
        and age >= 0
        and age <= 0.25
        and typeof(Data.AppliedServerCF) == 'CFrame'
    if fresh then
        local tag = Data.AppliedServerTag
        local serverPosition = Data.AppliedServerCF.Position
        if
            tag == 'Void'
            or tag == 'VoidTwitch'
            or tag == 'ReloadVoid'
            or tag == 'RagebotVoid'
            or tag == 'RagebotIdle'
            or tag == 'PurchaseVoidReturn'
            or serverPosition.Y < -1000
            or serverPosition.Magnitude > 100000
        then
            return nil
        end
    end
    local getter = getgenv().PhowgGetClientCFrame
    local cf = type(getter) == 'function' and getter() or Local_Data.ClientPos
    if typeof(cf) ~= 'CFrame' then
        cf = Local_Data.ClientPos
    end
    local position = typeof(cf) == 'CFrame' and cf.Position or typeof(cf) == 'Vector3' and cf or nil
    if not position and not (Data.DesyncActive or Data.MoveToInFlight or Data.CSyncTable and Data.CSyncTable[2]) then
        position = root.Position
    end
    if not phowg:perfect_hit_vector(position) or position.Y < -1000 or position.Magnitude > 100000 then
        return nil
    end
    return position
end
function phowg:cash_aura_tick()
    if not Toggles.cash_aura or not Toggles.cash_aura.Value or type(fireclickdetector) ~= 'function' then
        return
    end
    if not phowg:cash_aura_position() then
        return
    end
    phowg:scan_world_esp()
    Data.CashAuraRetries = Data.CashAuraRetries or setmetatable({}, { __mode = 'k' })
    for _, candidate in ipairs(Data.WorldESPCandidates or {}) do
        local owner, part = candidate.Owner, candidate.Part
        if candidate.Kind ~= 'cash' or not owner.Parent or owner.Parent.Name ~= 'Drop' or not part.Parent then
            continue
        end
        local now = tick()
        if now < (Data.CashAuraRetries[owner] or 0) then
            continue
        end
        local detector = owner:FindFirstChildWhichIsA('ClickDetector', true)
        local position = phowg:cash_aura_position()
        if not position then
            return
        end
        local maximum = detector and math.min(15, math.max(0, detector.MaxActivationDistance)) or 0
        if detector and detector.Parent and (part.Position - position).Magnitude <= maximum then
            Data.CashAuraRetries[owner] = now + 0.5
            pcall(fireclickdetector, detector)
        end
    end
end
registerheartbeat('CashAura', phowg.cash_aura_tick, 0.1, function()
    return Toggles.cash_aura and Toggles.cash_aura.Value
end)

function phowg:destroy_world_esp_marker(marker)
    if marker.Connections then
        for _, connection in pairs(marker.Connections) do
            connection:Disconnect()
        end
    end
    if marker.Gui then
        marker.Gui:Destroy()
    end
    if marker.Volume then
        marker.Volume:Destroy()
    end
    phowg:release_visual(marker)
end
function phowg:observe_cash_amount(marker, owner)
    marker.Connections, marker.AmountDirty = {}, true
    local function dirty()
        marker.AmountDirty = true
    end
    local function observe(value)
        local property = (value:IsA('TextLabel') or value:IsA('TextButton')) and 'Text'
            or value:IsA('ValueBase') and 'Value'
        if not property then
            return
        end
        if marker.Connections[value] then
            marker.Connections[value]:Disconnect()
        end
        marker.Connections[value] =
            connectshared(value:GetPropertyChangedSignal(property), dirty, value, 'cash esp/amount')
    end
    marker.Connections.Attributes =
        connectshared(owner.AttributeChanged, dirty, owner, 'cash esp/attribute', 0, 'event/AttributeChanged', owner)
    marker.Connections.Added = connectshared(owner.DescendantAdded, function(value)
        observe(value)
        dirty()
    end, owner, 'cash esp/amount added', 0, 'event/DescendantAdded', owner)
    marker.Connections.Removed = connectshared(owner.DescendantRemoving, function(value)
        if marker.Connections[value] then
            marker.Connections[value]:Disconnect()
            marker.Connections[value] = nil
        end
        dirty()
    end, owner, 'cash esp/amount removed', 0, 'event/DescendantRemoving', owner)
    for _, value in ipairs(owner:GetDescendants()) do
        observe(value)
    end
end
function phowg:world_esp_marker(candidate)
    local marker = { Kind = candidate.Kind, Part = candidate.Part }
    if not phowg:acquire_visual(marker, 4, 'world esp') then
        return nil
    end
    local gui = Instance.new('BillboardGui')
    gui.Name = 'PhowgWorldESP'
    gui.Adornee = candidate.Part
    gui.AlwaysOnTop = true
    gui.Active = false
    gui.LightInfluence = 0
    gui.StudsOffsetWorldSpace = Vector3.new(0, 2, 0)
    local label = Instance.new('TextLabel')
    label.BackgroundTransparency = 1
    label.Size = UDim2.fromScale(1, 1)
    label.Font = Enum.Font.GothamBold
    label.TextStrokeColor3 = Color3.new(0, 0, 0)
    label.TextStrokeTransparency = 0.25
    label.Parent = gui
    gui.Parent = CoreGui
    marker.Gui, marker.Label = gui, label
    if candidate.Kind == 'cash' then
        phowg:observe_cash_amount(marker, candidate.Owner)
    end
    if candidate.Kind ~= 'cash' then
        local volume = Instance.new('SphereHandleAdornment')
        volume.Name = 'PhowgExplosiveDanger'
        volume.Adornee = candidate.Part
        volume.AlwaysOnTop = false
        volume.Transparency = 0.92
        volume.Parent = CoreGui
        marker.Volume = volume
    end
    return marker
end
function phowg:update_world_esp()
    local cash = Toggles.cash_esp and Toggles.cash_esp.Value
    local explosives = Toggles.rpg_warnings and Toggles.rpg_warnings.Value
        or Toggles.grenade_warnings and Toggles.grenade_warnings.Value
    if not cash and not explosives then
        if Data.WorldESP and next(Data.WorldESP) then
            phowg:clear_world_esp()
        end
        if not (Toggles.cash_aura and Toggles.cash_aura.Value) then
            Data.WorldESPCandidates = nil
        end
        return
    end
    local root = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild('HumanoidRootPart')
    if not root then
        phowg:clear_world_esp()
        return
    end
    local client = Data.CSyncTable and Data.CSyncTable[2] and Data.CSyncTable[1] or Local_Data.ClientPos
    local origin = typeof(client) == 'CFrame' and client.Position or root.Position
    phowg:scan_world_esp()
    local candidates = {}
    for _, candidate in ipairs(Data.WorldESPCandidates or {}) do
        local active = candidate.Kind == 'cash' and cash
            or candidate.Kind == 'rocket' and Toggles.rpg_warnings.Value
            or (candidate.Kind == 'launcher' or candidate.Kind == 'grenade') and Toggles.grenade_warnings.Value
        if active and candidate.Part.Parent and candidate.Owner.Parent then
            candidate.Distance = (candidate.Part.Position - origin).Magnitude
            local maximum = phowg:visual_number(
                candidate.Kind == 'cash' and 'cash_esp_distance' or 'explosive_warning_distance',
                candidate.Kind == 'cash' and 250 or 1000,
                25,
                2000
            )
            if candidate.Distance <= maximum then
                candidates[#candidates + 1] = candidate
            end
        end
    end
    table.sort(candidates, function(a, b)
        return a.Distance < b.Distance
    end)
    Data.WorldESP = Data.WorldESP or {}
    local present, counts = {}, { cash = 0, explosive = 0 }
    local scale, opacity = phowg:hud_settings()
    for _, candidate in ipairs(candidates) do
        local category = candidate.Kind == 'cash' and 'cash' or 'explosive'
        local limit = category == 'cash' and 60 or 24
        if counts[category] < limit then
            local marker = Data.WorldESP[candidate.Owner]
            if marker and (marker.Part ~= candidate.Part or marker.Kind ~= candidate.Kind) then
                phowg:destroy_world_esp_marker(marker)
                Data.WorldESP[candidate.Owner] = nil
                marker = nil
            end
            if marker and not phowg:acquire_visual(marker, 4, 'world esp') then
                phowg:destroy_world_esp_marker(marker)
                Data.WorldESP[candidate.Owner] = nil
                marker = nil
            end
            marker = marker or phowg:world_esp_marker(candidate)
            if marker then
                counts[category] = counts[category] + 1
                present[candidate.Owner] = true
                Data.WorldESP[candidate.Owner] = marker
                local text, color
                if category == 'cash' then
                    if Toggles.cash_esp_amount.Value and marker.AmountDirty then
                        marker.Amount, marker.AmountDirty = phowg:cash_amount(candidate.Owner), false
                    end
                    local amount = Toggles.cash_esp_amount.Value and marker.Amount
                    text = amount and formatmoneytext(amount) or 'CASH'
                    if Toggles.cash_esp_show_distance.Value then
                        text = text .. '\n' .. math.floor(candidate.Distance + 0.5) .. ' studs'
                    end
                    color = Options.cash_esp_color.Value
                else
                    local radius = phowg:visual_number(
                        'explosive_' .. candidate.Kind .. '_radius',
                        candidate.Kind == 'launcher' and 15 or 12,
                        1,
                        100
                    )
                    local danger = candidate.Distance <= radius
                    local kind = candidate.Kind == 'rocket' and 'RPG'
                        or candidate.Kind == 'launcher' and 'LAUNCHER'
                        or 'GRENADE'
                    text = (danger and 'DANGER | ' or 'SAFE | ')
                        .. kind
                        .. '\n'
                        .. math.floor(candidate.Distance + 0.5)
                        .. ' studs | zone '
                        .. radius
                    color = danger and Options.explosive_danger_color.Value or Options.explosive_safe_color.Value
                    marker.Volume.Radius = radius
                    marker.Volume.Color3 = color
                    marker.Volume.Transparency = 1 - 0.08 * opacity
                    marker.Volume.Visible = Toggles.explosive_warning_volumes.Value
                end
                marker.Label.Text, marker.Label.TextColor3 = text, color
                marker.Label.TextSize = phowg:visual_number(
                    category == 'cash' and 'cash_esp_size' or 'explosive_warning_size',
                    14,
                    10,
                    24
                ) * scale
                marker.Label.TextTransparency = 1 - opacity
                marker.Gui.Size = UDim2.fromOffset(250 * scale, 50 * scale)
                marker.Gui.MaxDistance = phowg:visual_number(
                    category == 'cash' and 'cash_esp_distance' or 'explosive_warning_distance',
                    category == 'cash' and 250 or 1000,
                    25,
                    2000
                ) + 100
            end
        end
    end
    for owner, marker in pairs(Data.WorldESP) do
        if not present[owner] then
            phowg:destroy_world_esp_marker(marker)
            Data.WorldESP[owner] = nil
        end
    end
end
registerheartbeat('WorldESP', phowg.update_world_esp, 0.1)
phowg:register_cleanup('world esp', function(scope)
    if not scope or scope == LocalPlayer.Character then
        phowg:clear_world_esp()
    end
    if not scope then
        phowg:stop_world_esp_index()
    end
end)
function loadesp()
    if Library.Unloaded or Data.SharedSignalsClosed then
        return nil
    end
    if type(Data.ESPLoading) == 'thread' and coroutine.status(Data.ESPLoading) == 'dead' then
        Data.ESPLoading = nil
    end
    local environment = getgenv()
    local existing = environment.ESP
    if
        type(existing) == 'table'
        and type(existing.Configure) == 'function'
        and existing.PhowgBarHookRevision == 1
        and existing.SupportsPlayerStats
        and existing.SupportsFlags
        and existing.SupportsVisionGlow
        and existing.SupportsCountryNames
        and existing.SupportsCountryIPv4
        and existing.LazyDrawings
        and type(existing.GetDiagnostics) == 'function'
        and (
            existing == Data.ESPInstance
            or (
                existing.HasForceField
                and (existing.StartupRevision or 0) == 23
                and existing.SharedConnectProvider == connectshared
            )
        )
    then
        if Data.ESPInstance ~= existing then
            Data.ESPSyncKey, Data.ESPWasOn = nil, false
        end
        Data.ESPInstance = existing
        return existing
    end
    if not Workspace.CurrentCamera or Data.ESPLoading or tick() < (Data.ESPNextRetryAt or 0) then
        return nil
    end
    Data.ESPLoading = coroutine.running()
    local stageAt = os.clock()
    local ok, result = pcall(function()
        if type(existing) == 'table' and type(existing._Cleanup) == 'function' then
            pcall(existing._Cleanup)
        end
        environment.ESP = nil
        local raw = Data.ESPSource or RuntimeSources['esp library.lua']
        if not raw then
            local url = ESPLibrary
            if type(url) ~= 'string' or url == '' then
                error('ESP source URL is missing')
            end
            local separator = url:find('?', 1, true) and '&' or '?'
            raw = game:HttpGet(
                url .. separator .. 'phowg=' .. tostring(os.time()) .. '-' .. tostring(math.floor(os.clock() * 1000)),
                true
            )
            if type(raw) ~= 'string' or #raw < 1000 then
                error('ESP download did not contain the library')
            end
        end
        raw = raw:gsub('^' .. string.char(239, 187, 191), '')
        if
            not raw:find('ESP.LazyDrawings = true', 1, true)
            or not raw:find('ESP.SupportsFlags = true', 1, true)
            or (tonumber(raw:match('StartupRevision%s*=%s*(%d+)')) or 0) ~= 23
        then
            error('ESP library is outdated; update esp library.lua alongside the main script')
        end
        Data.ESPSource = raw
        local function decode(data)
            local alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
            local map, out = {}, {}
            for i = 1, 64 do
                map[alphabet:sub(i, i)] = i - 1
            end
            local clean = tostring(data or ''):gsub('[^A-Za-z0-9%+/=]', '')
            for i = 1, #clean, 4 do
                local a, b = map[clean:sub(i, i)] or 0, map[clean:sub(i + 1, i + 1)] or 0
                local c, d = map[clean:sub(i + 2, i + 2)] or 0, map[clean:sub(i + 3, i + 3)] or 0
                local n = a * 262144 + b * 4096 + c * 64 + d
                out[#out + 1] = string.char(math.floor(n / 65536))
                if map[clean:sub(i + 2, i + 2)] then
                    out[#out + 1] = string.char(math.floor(n / 256) % 256)
                end
                if map[clean:sub(i + 3, i + 3)] then
                    out[#out + 1] = string.char(n % 256)
                end
            end
            return table.concat(out)
        end
        local loader = loadstring or load
        if type(loader) ~= 'function' then
            error('Lua source loading is unavailable')
        end
        local chunk, problem = loader(
            'return function(base64_decode, identifyexecutor, cleardrawcache)\nlocal LPH_NO_VIRTUALIZE = function(...) return ... end\n'
                .. phowg:prepare_esp_bars(raw)
                .. '\nend',
            '@PhowgESP'
        )
        if not chunk then
            error(problem)
        end
        local factory = chunk()
        local esp = factory(base64_decode or decode, identifyexecutor or function()
            return 'Unknown'
        end, function() end)
        if type(esp) ~= 'table' or type(esp.Configure) ~= 'function' then
            error('ESP initialization did not return a working library')
        end
        if Library.Unloaded or Data.SharedSignalsClosed then
            if esp._Cleanup then
                pcall(esp._Cleanup)
            end
            error('ESP initialization was cancelled')
        end
        return esp
    end)
    Data.ESPLoading = nil
    Data.StartupTiming.Stages['ESP library'] = os.clock() - stageAt
    if ok then
        environment.ESP = result
        Data.ESPInstance, Data.ESPLoadFailures, Data.ESPNextRetryAt = result, 0, nil
        Data.ESPSyncKey, Data.ESPWasOn = nil, false
        healdrawings()
        if phowg.classic_rail_bind_icons then
            phowg:classic_rail_bind_icons(result)
        end
        return result
    end
    local partial = environment.ESP
    if type(partial) == 'table' and type(partial._Cleanup) == 'function' then
        pcall(partial._Cleanup)
    end
    environment.ESP, Data.ESPInstance, Data.ESPSource = nil, nil, nil
    Data.ESPLoadFailures = (Data.ESPLoadFailures or 0) + 1
    Data.ESPNextRetryAt = tick() + math.min(30, 2 ^ math.min(Data.ESPLoadFailures, 5))
    if not Library.Unloaded and not Data.SharedSignalsClosed and tick() - (Data.ESPErrorAt or -math.huge) >= 10 then
        Data.ESPErrorAt = tick()
        Library:Notify('ESP failed to initialize; retrying shortly', 5)
        warn('[Phowg] ESP initialization failed: ' .. tostring(result))
    end
    return nil
end
function syncesp()
    if not Data.ESPInstance then
        if not Data.ESPBootstrapRunning and tick() >= (Data.ESPNextRetryAt or 0) then
            Data.ESPBootstrapRunning = true
            task.spawn(function()
                local ok, esp = pcall(loadesp)
                Data.ESPBootstrapRunning = false
                if not Library.Unloaded and not Data.SharedSignalsClosed then
                    Data.ESPSyncDirty = true
                    if not ok then
                        Data.ESPNextRetryAt = tick() + 5
                        warn('[Phowg] ESP load failed: ' .. tostring(esp))
                    end
                end
            end)
        end
        return
    end
    local ESP = loadesp()
    if not (ESP and ESP.Configure) then
        return
    end
    ESP.PhowgRenderBars = phowg_callbacks.render_esp_bars
    phowg:sync_esp_bar_options()
    if Data.ESPCrewInstance ~= ESP then
        Data.ESPCrewInstance = ESP
        pushcrewesp()
    end
    local white = Color3.fromRGB(255, 255, 255)
    local master = Toggles.player_esp_enabled and Toggles.player_esp_enabled.Value or false
    local forceFieldOn = master and Toggles.player_esp_forcefield and Toggles.player_esp_forcefield.Value or false
    local forceFieldColor = Options.player_esp_forcefield_color and Options.player_esp_forcefield_color.Value
