    local selfOn = master and Toggles.player_esp_self and Toggles.player_esp_self.Value or false
    local boxOn = master and Toggles.player_esp_box and Toggles.player_esp_box.Value or false
    local nameOn = master and Toggles.player_esp_name and Toggles.player_esp_name.Value or false
    local disableMasks = nameOn and Toggles.player_esp_disable_masks and Toggles.player_esp_disable_masks.Value or false
    local hideNormalNames = nameOn
            and Toggles.player_esp_hide_normal_names
            and Toggles.player_esp_hide_normal_names.Value
        or false
    local crewOn = master and Toggles.player_esp_crew and Toggles.player_esp_crew.Value or false
    local crewCountOn = master and crewOn and Toggles.player_esp_crew_count and Toggles.player_esp_crew_count.Value
        or false
    local healthOn = master and Toggles.player_esp_health_bar and Toggles.player_esp_health_bar.Value or false
    local armorOn = master and Toggles.player_esp_armor_bar and Toggles.player_esp_armor_bar.Value or false
    local distOn = master and Toggles.distance_esp and Toggles.distance_esp.Value or false
    local toolOn = master and Toggles.player_esp_tool and Toggles.player_esp_tool.Value or false
