    local wantedOn = master and Toggles.player_esp_wanted and Toggles.player_esp_wanted.Value or false
    local chamsOn = master and Toggles.player_esp_chams and Toggles.player_esp_chams.Value or false
    local highlightOn = master and Toggles.player_esp_highlight and Toggles.player_esp_highlight.Value or false
    local tracerOn = master and Toggles.player_esp_tracer and Toggles.player_esp_tracer.Value or false
    local imageOn = master and Toggles.player_esp_image and Toggles.player_esp_image.Value or false
    local boxCol = (boxOn and Options.player_esp_box_color and Options.player_esp_box_color.Value) or white
    local nameCol = (nameOn and Options.player_esp_name_color and Options.player_esp_name_color.Value) or white
    local crewCol = (crewOn and Options.player_esp_crew_color and Options.player_esp_crew_color.Value) or white
    local toolCol = (toolOn and Options.player_esp_tool_color and Options.player_esp_tool_color.Value) or white
    local healthCol = (healthOn and Options.player_esp_health_bar_color and Options.player_esp_health_bar_color.Value)
        or white
    local armorCol = (armorOn and Options.player_esp_armor_bar_color and Options.player_esp_armor_bar_color.Value)
        or white
    local healthGradient = Toggles.player_esp_health_gradient and Toggles.player_esp_health_gradient.Value or false
    local armorGradient = Toggles.player_esp_armor_gradient and Toggles.player_esp_armor_gradient.Value or false
    local healthEnd = Options.player_esp_health_gradient_end and Options.player_esp_health_gradient_end.Value
        or Color3.fromRGB(255, 60, 60)
    local armorEnd = Options.player_esp_armor_gradient_end and Options.player_esp_armor_gradient_end.Value
