    ) or white
    local wantedCol = (wantedOn and Options.player_esp_wanted_color and Options.player_esp_wanted_color.Value) or white
    local tracerCol = (tracerOn and Options.player_esp_tracer_color and Options.player_esp_tracer_color.Value) or white
    local highlightCol = (
        highlightOn
        and Options.player_esp_highlight_color
        and Options.player_esp_highlight_color.Value
    ) or white
    local imageCol = (imageOn and Options.player_esp_image_color and Options.player_esp_image_color.Value) or white
    local animMode = (master and Options.player_esp_animation and Options.player_esp_animation.Value) or 'none'
