    local nv = (nameOn and Options.player_esp_name_value and Options.player_esp_name_value.Value) or 'username'
    local bothN, dispN, userN = false, false, false
    if type(nv) == 'table' then
        for k, on in pairs(nv) do
            if on then
                if k == 'display name' then
                    dispN = true
                end
                if k == 'username' then
                    userN = true
                end
            end
        end
        for _, k in ipairs(nv) do
            if k == 'display name' then
                dispN = true
            end
            if k == 'username' then
                userN = true
            end
        end
        if dispN and userN then
            bothN = true
        end
    elseif nv == 'display name' then
        dispN = true
    else
        userN = true
    end
    local key = table.concat({
        tostring(master),
        tostring(selfOn),
        tostring(boxOn),
        tostring(nameOn),
        tostring(crewOn),
        tostring(crewCountOn),
        tostring(healthOn),
        tostring(armorOn),
        tostring(distOn),
        tostring(toolOn),
        tostring(weaponIconOn),
        tostring(healthTextOn),
