        tostring(animMode),
        tostring(chamsOn),
        tostring(highlightOn),
        tostring(tracerOn),
        tostring(imageOn),
        tostring(bothN),
        tostring(dispN),
        tostring(userN),
        tostring(boxCol),
        tostring(nameCol),
        tostring(crewCol),
        tostring(toolCol),
        tostring(weaponIconCol),
        tostring(healthCol),
        tostring(armorCol),
        tostring(chamsCol),
