            tostring(movingGradient),
            tostring(gradientSpeed),
        }, '|')
    key ..= '|' .. tostring(disableMasks) .. '|' .. tostring(hideNormalNames)
    key = key .. '|' .. tostring(forceFieldOn) .. '|' .. tostring(forceFieldColor)
    local targetOn = master and Toggles.player_esp_target_color and Toggles.player_esp_target_color.Value or false
    local targetColor = Options.player_esp_target_color_value and Options.player_esp_target_color_value.Value
        or Color3.fromRGB(255, 90, 90)
    key ..= table.concat({ tostring(targetOn), tostring(targetColor) }, '|')
    local detectOn = master and Toggles.player_esp_detect_cheaters and Toggles.player_esp_detect_cheaters.Value or false
    local redNames = Toggles.player_esp_cheater_red_name and Toggles.player_esp_cheater_red_name.Value or false
    local accuracyOn = master and Toggles.player_esp_accuracy and Toggles.player_esp_accuracy.Value or false
