    local accuracyColor = Options.player_esp_accuracy_color and Options.player_esp_accuracy_color.Value or white
    local countryOn = master and Toggles.player_esp_country and Toggles.player_esp_country.Value or false
    local countryIP = Toggles.player_esp_country_ip and Toggles.player_esp_country_ip.Value or false
    local countryColor = Options.player_esp_country_color and Options.player_esp_country_color.Value or white
    key ..= table.concat({
