    local inventoryOn = master and phowg:toggle_enabled('player_esp_inventory')
    local moneyColor = Options.player_esp_money_color and Options.player_esp_money_color.Value or white
    local deviceColor = Options.player_esp_device_color and Options.player_esp_device_color.Value or white
    local inventoryColor = Options.player_esp_inventory_color and Options.player_esp_inventory_color.Value or white
    local flagsOn = master and phowg:toggle_enabled('player_esp_flags')
    local flagTypes = Options.player_esp_flags_types and Options.player_esp_flags_types.Value or {}
