        tostring(deviceColor),
        tostring(inventoryColor),
    }, '|')
    local profileOn = phowg:toggle_enabled('player_esp_profile') or Data.Performance.Enabled
    local detailOn = phowg:toggle_enabled('player_esp_distance_detail')
    local detailDistance = phowg:visual_number('player_esp_detail_distance', 300, 50, 2000)
    local detailEffects, detailLabels =
