    }, '|')
    local hideNone = phowg:toggle_enabled('player_esp_hide_none')
    local espFont = Options.player_esp_font and Options.player_esp_font.Value or 'Code'
    local labelGap = phowg:visual_number('player_esp_label_gap', 1, 0, 8)
    local boxPalette = {}
    for index = 1, 3 do
        local option = Options['player_esp_box_gradient_' .. index]
        boxPalette[index] = option and option.Value or white
    end
    local boxStyle = {
        Gradient = phowg:toggle_enabled('player_esp_box_gradient'),
        Animate = phowg:toggle_enabled('player_esp_box_gradient_animate'),
        Mode = Options.player_esp_box_gradient_mode and Options.player_esp_box_gradient_mode.Value
