        Glow = phowg:toggle_enabled('player_esp_box_glow'),
        GlowColor = Options.player_esp_box_glow_color and Options.player_esp_box_glow_color.Value or white,
        GlowIntensity = phowg:visual_number('player_esp_box_glow_intensity', 20, 0, 100) / 100,
    }
    key ..= tostring(boxStyle.Gradient) .. tostring(boxStyle.Animate) .. boxStyle.Mode .. tostring(boxStyle.Speed) .. tostring(
        boxStyle.Glow
    ) .. tostring(boxStyle.GlowColor) .. tostring(boxStyle.GlowIntensity)
    for _, color in ipairs(boxPalette) do
