            DisableMasks = disableMasks,
            HideNormalNames = hideNormalNames,
            Use_Both_Name = bothN,
            Use_User_Name = userN,
            Use_Display_Name = dispN,
            Color = nameCol,
        },
        Crew = { Enabled = crewOn, Color = crewCol, Count = crewCountOn },
        Character = { Hide_Tags = true },
        Self = { Enabled = selfOn },
        ForceField = { Enabled = forceFieldOn, Color = forceFieldColor, Transparency = 0.7 },
        Bars = {
            Type = 'Gradient',
            Speed = gradientSpeed,
            Health = {
                Enabled = healthOn,
                Offset = Vector2.new(6, 1),
                Gradient = healthGradient,
                SpatialGradient = healthGradient,
                BaseColor = healthCol,
                GradientColor = healthEnd,
                Moving_Gradient = movingGradient,
                Colors = { healthCol, healthEnd, healthCol, healthEnd, healthCol },
            },
            Armor = {
                Enabled = armorOn,
                Offset = Vector2.new(10, 1),
                Gradient = armorGradient,
                SpatialGradient = armorGradient,
                BaseColor = armorCol,
                GradientColor = armorEnd,
                Moving_Gradient = movingGradient,
                Hide_If_Empty = true,
                Colors = { armorCol, armorEnd, armorCol, armorEnd, armorCol },
