        },
        Image = { Enabled = imageOn, Data = 'Gradient', Color = imageCol },
        Distance = { Enabled = distOn, Color = distCol },
        Tracer = {
            Enabled = tracerOn,
            Origin = 'Above',
            Outline = true,
            Origin_Position = Vector2.zero,
            Color = tracerCol,
            OutlineColor = tracerCol,
        },
        Highlight = {
            Enabled = highlightOn,
            DepthMode = Enum.HighlightDepthMode.AlwaysOnTop,
            FillColor = highlightCol,
            FillTransparency = 0.5,
            OutlineColor = highlightCol,
            OutlineTransparency = 0,
        },
        ToolText = { Enabled = toolOn, Color = toolCol, HideNone = hideNone },
        WeaponIcon = { Enabled = weaponIconOn, Color = weaponIconCol },
        HealthText = {
            Enabled = healthTextOn,
            NormalOffset = Vector2.new(12, 1),
            Offset = Vector2.new(12, 1),
            HideFullHealth = false,
            Color = healthTextCol,
        },
        Wanted = { Enabled = wantedOn, Color = wantedCol },
        Animation = { Mode = animMode },
        DistanceLimit = { Enabled = false, MaxDistance = 1000 },
        Misc = {
            FontName = espFont,
            LabelGap = labelGap,
            Glow = vision,
            Offset = Vector3.new(0, 0.5, 0),
            BarOffset = Vector2.new(0, 1),
            ZeroSize = Vector2.zero,
            MainFont = identifyexecutor() == 'Wave' and 1 or 2,
            MainSize = 13,
            SmallFont = identifyexecutor() == 'Wave' and 1 or 2,
            SmallSize = identifyexecutor() == 'Wave' and 13 or 11,
        },
    })
    if not SyncOk then
        Data['ESPSyncKey'] = nil
        if tick() - (Data.ESPConfigErrorAt or -math.huge) >= 10 then
            Data.ESPConfigErrorAt = tick()
            warn('[Phowg] ESP settings failed to apply: ' .. tostring(SyncError))
        end
    elseif master and not wasOn and ESP.FadeAll then
        pcall(ESP.FadeAll, ESP)
    end
    Data['ESPWasOn'] = master
end
function phowg:watch_esp_settings()
    for _, controls in ipairs({ Toggles, Options }) do
        for index, control in pairs(controls) do
            if
                type(index) == 'string'
                and type(control) == 'table'
                and (index:sub(1, 11) == 'player_esp_' or index == 'distance_esp' or index:sub(1, 13) == 'distance_esp_')
                and not control.PhowgESPSyncWatch
            then
                local changed, onChanged = control.Changed, control.OnChanged
                local function notify(...)
                    Data.ESPSyncDirty = true
                    if changed then
                        return changed(...)
                    end
                    return nil
                end
                control.PhowgESPSyncWatch = true
                control.Changed = notify
                if type(onChanged) == 'function' then
                    control.OnChanged = function(self, callback)
                        changed = callback
                        return onChanged(self, notify)
                    end
                end
            end
        end
    end
    Data.ESPSyncDirty = true
end
function updateesp()
    if Library.Unloaded or Data.SharedSignalsClosed or Library.ConfigLoading then
        return
    end
    local esp = Data.ESPInstance
    if not esp or esp ~= getgenv().ESP or Data.ESPSyncKey == nil then
        Data.ESPSyncDirty = true
    end
    if Data.ESPSyncDirty then
        Data.ESPSyncDirty = false
        syncesp()
        esp = Data.ESPInstance
        if not esp or Data.ESPSyncKey == nil then
            Data.ESPSyncDirty = true
        end
    end
    if esp and esp.Settings and esp.Settings.Target and esp.Settings.Target.Enabled then
        local record = phowg:get_active_target()
        esp.ActiveTarget = record and record.Player
    elseif esp then
        esp.ActiveTarget = nil
    end
    if Data['ESPBoxes'] ~= nil then
        for _, boxData in pairs(Data['ESPBoxes']) do
            if type(boxData) == 'table' then
                for _, d in pairs(boxData) do
                    pcall(function()
                        if d ~= nil and d.Remove ~= nil then
                            d:Remove()
                        elseif d ~= nil and d.Destroy ~= nil then
                            d:Destroy()
                        end
                    end)
                end
            end
        end
        Data['ESPBoxes'] = nil
    end
    if Data['ESPRoots'] ~= nil then
        Data['ESPRoots'] = nil
        Data['ESPRootsN'] = 0
    end
    if Data['ESPToolCache'] ~= nil then
        Data['ESPToolCache'] = nil
    end
end
function phowg:opsec_stat_icon()
    if Data.OpsecIconAsset then
        return Data.OpsecIconAsset
    end
    local asset = getcustomasset or getsynasset
    local path = RuntimeAssets['assets/icons/opsec.png'] or 'PhowgHosted/DaHood/cache/icons/opsec.png'
    if makefolder and isfolder and writefile then
        pcall(phowg_callbacks.asset_cache_path, 'icons', 'opsec.png', { 'PhowgAssets/Icons/opsec.png' })
    end
    if not asset or not isfile then
        return nil
    end
    if isfile(path) then
        local ok, id = pcall(asset, path)
        if ok and type(id) == 'string' and id ~= '' then
            Data.OpsecIconAsset = id
            return id
        end
    end
    if Data.OpsecIconQueued or tick() < (Data.OpsecIconRetryAt or 0) or not (writefile and makefolder and isfolder) then
        return nil
    end
    Data.OpsecIconQueued = true
    phowg:queue_background('stat bar assets', 'opsec icon', function()
        local ok, id = pcall(function()
            local url = 'https://qu.ax/x/Tubit.png'
            local fetch = request or http_request or syn and syn.request
            local bytes
            if fetch then
                local response = fetch({
                    Url = url,
                    Method = 'GET',
                    Headers = { Accept = 'image/png,image/*;q=0.9', ['Sec-Fetch-Dest'] = 'image', Referer = url },
                })
                bytes = response and response.Body
            else
                bytes = game:HttpGet(url)
            end
            if
                type(bytes) ~= 'string'
                or bytes:sub(1, 8) ~= string.char(137) .. 'PNG' .. string.char(13, 10, 26, 10)
            then
                error('Icon download did not return PNG data')
            end
            phowg:asset_cache_path('icons', 'opsec.png')
            writefile(path, bytes)
            return asset(path)
        end)
        Data.OpsecIconQueued = nil
        if ok and type(id) == 'string' and id ~= '' then
            Data.OpsecIconAsset = id
            phowg:queue_assets({ id })
            if
                not Library.Unloaded
                and Toggles.custom_stat_bars
                and Toggles.custom_stat_bars.Value
                and Options.custom_stat_bars_value.Value == 'opsec'
            then
                Data.lastCustomStatBarsUpdate = 0
                updatecustomstatbars()
            end
        else
            Data.OpsecIconRetryAt = tick() + 30
            if not Library.Unloaded then
                Library:Notify(
                    'OPSEC bars: the icon could not be loaded; the style is still available.',
                    Library.NotifyDuration or 4
                )
            end
        end
    end)
    return nil
end
function phowg:remember_opsec_stat(object, properties)
    if not object then
        return
    end
    Data.OpsecStatOriginal = Data.OpsecStatOriginal or {}
    local saved = Data.OpsecStatOriginal[object]
    if not saved then
        saved = {}
        Data.OpsecStatOriginal[object] = saved
    end
    for _, property in ipairs(properties) do
        if saved[property] == nil then
            saved[property] = object[property]
        end
    end
end
function phowg:restore_opsec_stats()
    for object, properties in pairs(Data.OpsecStatOriginal or {}) do
        if object.Parent then
            for property, value in pairs(properties) do
                pcall(function()
                    object[property] = value
                end)
            end
        end
    end
    Data.OpsecStatOriginal = nil
    for _, object in ipairs(Data.OpsecStatDecorations or {}) do
        pcall(function()
            object:Destroy()
        end)
    end
    Data.OpsecStatDecorations = nil
end
phowg:register_cleanup('opsec stat bars', function(scope)
    if not scope then
        phowg:restore_opsec_stats()
    end
end)
function updatecustomstatbars(selectedStyle)
    local now = tick()
    if now - Data['lastCustomStatBarsUpdate'] < 0.15 then
        return
    end
    Data['lastCustomStatBarsUpdate'] = now
    local playerGui = LocalPlayer:FindFirstChild('PlayerGui')
    local mainScreenGui = playerGui and playerGui:FindFirstChild('MainScreenGui')
    if not mainScreenGui then
        return
    end
    local bar = mainScreenGui:FindFirstChild('Bar')
    if not bar then
        return
    end
    local enabled = Toggles.custom_stat_bars and Toggles.custom_stat_bars.Value
    local selected = selectedStyle
        or (Options.custom_stat_bars_value and Options.custom_stat_bars_value.Value)
        or 'default'
    if not enabled or selected ~= 'opsec' then
        phowg:restore_opsec_stats()
    end
    local hpBar = bar:FindFirstChild('HP')
    local energyBar = bar:FindFirstChild('Energy')
    local armorBar = bar:FindFirstChild('Armor')
    local carHP = bar:FindFirstChild('CarHP')
    local hpC = Color3.fromRGB(36, 182, 3)
    local hpT = 0
    local enC = Color3.fromRGB(182, 182, 9)
    local enT = 0
    local arC = Color3.fromRGB(0, 136, 194)
    local arT = 0
    local fiC = Color3.fromRGB(253, 121, 33)
    local fiT = 0
    local carC = Color3.fromRGB(204, 59, 49)
    local carT = 0
    if hpBar and hpBar:FindFirstChild('bar') then
        hpBar.bar.BackgroundColor3 = (enabled and hpC) or Color3.fromRGB(36, 182, 3)
        hpBar.bar.BackgroundTransparency = (enabled and hpT) or 0
    end
    if energyBar and energyBar:FindFirstChild('bar') then
        energyBar.bar.BackgroundColor3 = (enabled and enC) or Color3.fromRGB(182, 182, 9)
        energyBar.bar.BackgroundTransparency = (enabled and enT) or 0
    end
    if armorBar and armorBar:FindFirstChild('bar') then
        armorBar.bar.BackgroundColor3 = (enabled and arC) or Color3.fromRGB(0, 136, 194)
        armorBar.bar.BackgroundTransparency = (enabled and arT) or 0.3
        if armorBar:FindFirstChild('firebar') then
            armorBar.firebar.BackgroundColor3 = (enabled and fiC) or Color3.fromRGB(253, 121, 33)
            armorBar.firebar.BackgroundTransparency = (enabled and fiT) or 0
        end
    end
    if carHP and carHP:FindFirstChild('BarContainer') and carHP.BarContainer:FindFirstChild('Bar') then
        carHP.BarContainer.Bar.BackgroundColor3 = (enabled and carC) or Color3.fromRGB(253, 121, 33)
        carHP.BarContainer.Bar.BackgroundTransparency = (enabled and carT) or 0
    end
    if carHP and carHP:FindFirstChild('BarContainer') then
        carHP.BarContainer.Position = (enabled and UDim2.new(0.019, -3, 0.1, -2)) or UDim2.new(0.019, -1, 0.1, 0)
    end
    if carHP then
        carHP.Position = (enabled and UDim2.new(0.5, 0, 1, -125)) or UDim2.new(0.5, 0, 1, -115)
    end
    for _, desc in ipairs(bar:GetDescendants()) do
        if desc.Name == '\0' or #desc.Name == 0 then
            desc:Destroy()
        end
    end
    if not enabled or selected == 'default' then
        for _, object in ipairs(bar:GetChildren()) do
            if object:IsA('GuiObject') then
                local text_label = object:FindFirstChild('TextLabel')
                local bar_obj = object.Name ~= 'CarHP' and object:FindFirstChild('bar')
                    or (carHP and carHP:FindFirstChild('BarContainer') and carHP.BarContainer:FindFirstChild('Bar'))
                object.BackgroundColor3 = Color3.fromRGB(58, 58, 58)
                if object:FindFirstChild('Picture') then
                    object.Picture.Visible = true
                end
                object.BackgroundTransparency = 0
                if bar_obj then
                    bar_obj.BackgroundTransparency = object.Name == 'Armor' and 0.3 or 0
                    bar_obj.Image = 'rbxassetid://131886135'
                    bar_obj.ImageColor3 = Color3.fromRGB(0, 0, 0)
                    bar_obj.Position = UDim2.new(0.019, 1, 0.1, 0)
                    bar_obj.ResampleMode = Enum.ResamplerMode.Default
                    bar_obj.ScaleType = Enum.ScaleType.Stretch
                end
                if object.Name == 'Armor' and object:FindFirstChild('firebar') then
                    object.firebar.BackgroundTransparency = 0
                    object.firebar.Image = 'rbxassetid://131886135'
                    object.firebar.Visible = true
                end
                if text_label then
                    text_label.TextXAlignment = object.Name == 'Energy' and Enum.TextXAlignment.Right
                        or object.Name == 'Armor' and Enum.TextXAlignment.Left
                        or Enum.TextXAlignment.Center
                    text_label.TextSize = 18
                    text_label.Font = Enum.Font.SourceSansBold
                    text_label.Text = string.upper(string.sub(text_label.Text, 1, 1))
                        .. string.sub(text_label.Text, 2, #text_label.Text)
                    text_label.Visible = true
                    text_label.TextStrokeTransparency = 0.25
                    text_label.TextStrokeColor3 = Color3.fromRGB(0, 0, 0)
                    text_label.Position = UDim2.new(0, 0, 0, 0)
                end
            end
        end
    elseif selected == 'opsec' then
        Data.OpsecStatDecorations = {}
        local iconAsset = phowg:opsec_stat_icon() or ''
        local palette = {
