                    elseif object.Name == 'CarHP' then
                        icon.Image = 'rbxassetid://139619875341441'
                        icon.Position = UDim2.new(1, 0, 0, -30)
                        icon.Size = UDim2.new(0, 34, 0, 34)
                    end
                    local cBar = Instance.new('UICorner', bar_obj)
                    cBar.CornerRadius = UDim.new(0, 0)
                    cBar.Name = '\0'
                end
                object.BackgroundColor3 = object.Name == 'HP' and Color3.fromRGB(255, 0, 4)
                    or object.Name == 'Energy' and Color3.fromRGB(255, 233, 110)
                    or object.Name == 'Armor' and Color3.fromRGB(0, 163, 212)
                    or Color3.fromRGB(13, 13, 13)
                local cObj = Instance.new('UICorner', object)
                cObj.CornerRadius = UDim.new(0, 0)
                cObj.Name = '\0'
            end
        end
    end
end
function statbarsready()
    local playerGui = LocalPlayer:FindFirstChild('PlayerGui')
    local mainScreenGui = playerGui and playerGui:FindFirstChild('MainScreenGui')
    local bar = mainScreenGui and mainScreenGui:FindFirstChild('Bar')
    if not bar then
        return false
    end
    local hp = bar:FindFirstChild('HP')
    local en = bar:FindFirstChild('Energy')
    local ar = bar:FindFirstChild('Armor')
    if not (hp and en and ar) then
        return false
    end
    if not (hp:FindFirstChild('bar') and en:FindFirstChild('bar') and ar:FindFirstChild('bar')) then
        return false
    end
    return true
end
function ensurecustomstatbars(Timeout)
    task.spawn(function()
        local Start = tick()
        while tick() - Start < (Timeout or 10) do
            if Library and Library.Unloaded then
                return
            end
            if not (Toggles.custom_stat_bars and Toggles.custom_stat_bars.Value) then
                return
            end
            updatecustomstatbars()
            if statbarsready() then
                task.wait(0.5)
                if Library and Library.Unloaded then
                    return
                end
                if Toggles.custom_stat_bars and Toggles.custom_stat_bars.Value then
                    updatecustomstatbars()
                end
                return
            end
            task.wait(0.5)
        end
    end)
end
function phowg:inventory_is_gun(tool)
    if not tool or not tool:IsA('Tool') then
        return false
    end
    if
        tool:FindFirstChild('Ammo')
        or tool:FindFirstChild('GunClient')
        or tool:FindFirstChild('GunClientShotgun')
        or tool:FindFirstChild('GunClientAutomatic')
    then
        return true
    end
    Data.InventoryGunCache = Data.InventoryGunCache or setmetatable({}, { __mode = 'k' })
    local cached = Data.InventoryGunCache[tool]
    if cached ~= nil then
        return cached
    end
    local gun = false
    for _, child in ipairs(tool:GetDescendants()) do
        if
            (child:IsA('LocalScript') or child:IsA('Script') or child:IsA('ModuleScript'))
            and string.find(child.Name:lower(), 'gun', 1, true)
        then
            gun = true
            break
        end
    end
    Data.InventoryGunCache[tool] = gun
    return gun
end
function phowg:inventory_pool(char, bp)
    local available, pool = {}, {}
    for _, container in ipairs({ bp, char }) do
        for _, tool in ipairs(container:GetChildren()) do
            if tool:IsA('Tool') then
                available[tool] = true
            end
        end
    end
    for _, tool in ipairs(Data.SortOrder or {}) do
        if available[tool] then
            pool[#pool + 1] = tool
            available[tool] = nil
        end
    end
    for _, container in ipairs({ bp, char }) do
        for _, tool in ipairs(container:GetChildren()) do
            if available[tool] then
                pool[#pool + 1] = tool
                available[tool] = nil
            end
        end
    end
    return pool
end
function phowg:inventory_order(pool)
    local priority = Toggles.auto_sort_prioritize_guns and Toggles.auto_sort_prioritize_guns.Value
    local guns, slots, used, names, order = {}, {}, {}, {}, {}
    for _, tool in ipairs(pool) do
        names[tool] = normalizeweaponname(tool.Name)
        guns[tool] = priority and phowg:inventory_is_gun(tool)
    end
    for slot = 1, math.min(9, #pool) do
        local option = Options['auto_sort_slot' .. slot]
        local query = normalizeweaponname(option and option.Value or '')
        if query ~= '' then
            for pass = 1, 2 do
                for _, tool in ipairs(pool) do
                    local matches = pass == 1 and names[tool] == query
                        or pass == 2 and string.find(names[tool], query, 1, true) ~= nil
                    if not used[tool] and matches then
                        slots[slot], used[tool] = tool, true
                        break
                    end
                end
                if slots[slot] then
                    break
                end
            end
        end
    end
    for slot = 1, #pool do
        if not slots[slot] then
            local nextTool
            for _, tool in ipairs(pool) do
                if not used[tool] then
                    nextTool = nextTool or tool
                    if guns[tool] then
                        nextTool = tool
                        break
                    end
                end
            end
            slots[slot], used[nextTool] = nextTool, true
        end
        order[slot] = slots[slot]
    end
    return order
end
function phowg:queue_inventory_equip(tool, char, bp, supportTarget)
    if not tool or not char or not bp or LocalPlayer.Character ~= char then
        return nil
    end
    local pending = {
        Tool = tool,
        Character = char,
        Backpack = bp,
        SupportTarget = supportTarget,
        Ready = true,
        Revision = Data.ToolEquipRevision or 0,
    }
    Data.InventoryEquip = pending
    return pending
end
function phowg:restore_inventory_equip()
    local pending = Data.InventoryEquip
    if not pending then
        return
    end
    if pending.Revision ~= (Data.ToolEquipRevision or 0) then
        Data.InventoryEquip = nil
        return
    end
    local char, tool, bp = pending.Character, pending.Tool, pending.Backpack
    if
        Library.Unloaded
        or LocalPlayer.Character ~= char
        or not char.Parent
        or LocalPlayer:FindFirstChild('Backpack') ~= bp
        or not bp.Parent
        or pending.SupportTarget and not (Data.PunishmentTargets and Data.PunishmentTargets[pending.SupportTarget])
    then
        Data.InventoryEquip = nil
        return
    end
    if
        not pending.Ready
        or Data.RagebotIdle
        or Data.Sorting
        or Data.Buying
        or Data.MaskBuying
        or Data.BuildActive
        or Data.LoadoutReloadJob
        or localactionblocked()
        or Data.SupportGunReloads and Data.SupportGunReloads[tool]
    then
        return
    end
    if tool.Parent == char then
        Data.InventoryEquip = nil
        return
    end
    if tool.Parent ~= bp then
        Data.InventoryEquip = nil
        return
    end
    local equipped = char:FindFirstChildOfClass('Tool')
    local effects = char:FindFirstChild('BodyEffects')
    local eating = effects and effects:FindFirstChild('Eating')
    if eating and eating.Value == true and not phowg:inventory_is_gun(equipped) then
        return
    end
    if equipped then
        Data.InventoryEquip = nil
        return
    end
    equip(tool)
    if tool.Parent == char and Data.InventoryEquip == pending then
        Data.InventoryEquip = nil
    end
end
function phowg:request_inventory_sort(force)
    if not (Toggles.auto_sort and Toggles.auto_sort.Value) then
        return
    end
    Data.SortRequested = true
    Data.SortForce = Data.SortForce or force == true
    Data.SortDue = tick() + 0.15
end
function aftershopbuy()
    phowg:request_inventory_sort()
end
function sortinventorykey()
    local char, bp = LocalPlayer.Character, LocalPlayer:FindFirstChild('Backpack')
    if not char or not bp then
        return ''
    end
    Data.SortToolIds = Data.SortToolIds or setmetatable({}, { __mode = 'k' })
    local keys = {}
    for _, tool in ipairs(phowg:inventory_pool(char, bp)) do
        if not Data.SortToolIds[tool] then
            Data.SortNextId = (Data.SortNextId or 0) + 1
            Data.SortToolIds[tool] = Data.SortNextId
        end
        keys[#keys + 1] = tostring(Data.SortToolIds[tool])
            .. ':'
            .. tool.Name
            .. ':'
            .. tostring(phowg:inventory_is_gun(tool))
    end
    table.sort(keys)
    keys[#keys + 1] = tostring(Toggles.auto_sort_prioritize_guns and Toggles.auto_sort_prioritize_guns.Value or false)
    for slot = 1, 9 do
        local option = Options['auto_sort_slot' .. slot]
        keys[#keys + 1] = normalizeweaponname(option and option.Value or '')
    end
    return table.concat(keys, '|')
end
function phowg:restore_sorted_tool(transaction, tool)
    local ok, restored = pcall(function()
        if tool.Parent ~= nil then
            return tool.Parent == transaction.Backpack or tool.Parent == transaction.Character
        end
        if not transaction.Detached[tool] then
            return false
        end
        if not transaction.Backpack.Parent then
            tool:Destroy()
            return false
        end
        tool.Parent = transaction.Backpack
        return tool.Parent == transaction.Backpack
    end)
    transaction.Detached[tool] = nil
    return ok and restored == true
end
function phowg:release_inventory_sort(transaction)
    if not transaction then
        return
    end
    for tool in pairs(transaction.Detached) do
        phowg:restore_sorted_tool(transaction, tool)
    end
    if Data.SortTransaction == transaction then
        Data.SortTransaction = nil
        Data.Sorting = false
    end
end
function autosorthotbar(force)
    if not (Toggles.auto_sort and Toggles.auto_sort.Value) or Library.Unloaded then
        return false
    end
    if
        Data.RagebotIdle
        or Data.GunReloadSelection
        or Data.HeldGunFire
        or phowg:china_multi_active()
        or Data.Sorting
        or Data.Buying
        or Data.MaskBuying
        or Data.BuildActive
        or Data.LoadoutReloadJob
        or next(Data.SupportGunReloads or {})
        or localactionblocked()
        or tick() - (Data.CombatActAt or 0) < 1
        or Data.InventoryEquip
    then
        phowg:request_inventory_sort(force)
        return false
    end
    local char, bp = LocalPlayer.Character, LocalPlayer:FindFirstChild('Backpack')
    if not char or not bp or not bp.Parent then
        return false
    end
    local key = sortinventorykey()
    if not force and key == Data.SortLastSet then
        return true
    end
    local pool = phowg:inventory_pool(char, bp)
    local order = phowg:inventory_order(pool)
    local held = char:FindFirstChildOfClass('Tool')
    if held then
        phowg:queue_inventory_equip(held, char, bp)
    end
    local transaction = { Character = char, Backpack = bp, Tools = pool, Detached = {} }
    Data.SortTransaction = transaction
    Data.Sorting = true
    phowg:preserve_inventory_visibility()
    local ok, err = pcall(function()
        phowg:stop_gun_fire()
        for _, tool in ipairs(pool) do
            pcall(function()
                if tool.Parent == char then
                    tool.Parent = bp
                end
                if tool.Parent == bp then
                    tool.Parent = nil
                    transaction.Detached[tool] = true
                end
            end)
        end
        RunService.Heartbeat:Wait()
        if
            Data.SortTransaction ~= transaction
            or LocalPlayer.Character ~= char
            or not bp.Parent
            or Library.Unloaded
        then
            return
        end
        local active = char:FindFirstChildOfClass('Tool')
        if active and active ~= held then
            Data.InventoryEquip = nil
        end
        local restored = {}
        for _, tool in ipairs(order) do
            if phowg:restore_sorted_tool(transaction, tool) then
                restored[#restored + 1] = tool
            end
        end
        order = restored
    end)
    local current = Data.SortTransaction == transaction
    phowg:release_inventory_sort(transaction)
    phowg:preserve_inventory_visibility()
    if ok and current and LocalPlayer.Character == char and bp.Parent and not Library.Unloaded then
        Data.SortOrder = order
        Data.SortLastSet = key
        if sortinventorykey() ~= key then
            phowg:request_inventory_sort()
        end
        phowg:restore_inventory_equip()
        return true
    end
    if not ok then
        warn('[Phowg] inventory sort: ' .. tostring(err))
        Data.SortRequested = nil
    end
    return false
end
function phowg:watch_inventory_tool(tool)
    if not tool:IsA('Tool') then
        return
    end
    Data.InventoryWatchedTools = Data.InventoryWatchedTools or setmetatable({}, { __mode = 'k' })
    local watched = Data.InventoryWatchedTools[tool]
    if watched and watched[1].Connected and watched[2].Connected and watched[3].Connected then
        return
    end
    for _, connection in ipairs(watched or {}) do
        connection:Disconnect()
    end
    local function changed(part)
        if part then
            local name = part.Name
            local direct = part.Parent == tool
                and (
                    name == 'Ammo'
                    or name == 'GunClient'
                    or name == 'GunClientShotgun'
                    or name == 'GunClientAutomatic'
                )
            local gunScript = (part:IsA('LocalScript') or part:IsA('Script') or part:IsA('ModuleScript'))
                and string.find(name:lower(), 'gun', 1, true)
            if not direct and not gunScript then
                return
            end
        end
        if Data.InventoryGunCache then
            Data.InventoryGunCache[tool] = nil
        end
        phowg:request_inventory_sort()
    end
    Data.InventoryWatchedTools[tool] = {
        connectshared(tool.DescendantAdded, changed, tool, 'inventory/tool added', 0, 'event/DescendantAdded', tool),
        connectshared(
            tool.DescendantRemoving,
            changed,
            tool,
            'inventory/tool removed',
            0,
            'event/DescendantRemoving',
            tool
        ),
        connectshared(
            tool:GetPropertyChangedSignal('Name'),
            changed,
            tool,
            'inventory/tool name',
            0,
            'property/Name',
            tool
        ),
    }
end
function phowg:hook_inventory_backpack(bp)
    if Data.SortBackpack == bp then
        return
    end
    Data.SortBackpack = bp
    for _, tool in ipairs(bp:GetChildren()) do
        phowg:watch_inventory_tool(tool)
    end
    create_connection(
        'InventoryBackpackAdded',
        connectshared(bp.ChildAdded, function(tool)
            if not tool:IsA('Tool') then
                return
            end
            phowg:watch_inventory_tool(tool)
            phowg:try_equip_purchased_knife(tool)
            if not Data.Sorting then
                phowg:request_inventory_sort()
            end
        end, bp, 'inventory/backpack added', 0, 'event/ChildAdded', bp)
    )
    create_connection(
        'InventoryBackpackRemoved',
        connectshared(bp.ChildRemoved, function(tool)
            if tool:IsA('Tool') and not Data.Sorting then
                phowg:request_inventory_sort()
            end
        end, bp, 'inventory/backpack removed', 0, 'event/ChildRemoved', bp)
    )
    phowg:request_inventory_sort(true)
end
function phowg:inventory_tool_added(tool)
    phowg:watch_inventory_tool(tool)
    phowg:try_equip_purchased_knife(tool)
    local pending = Data.InventoryEquip
    if pending and tool ~= pending.Tool and phowg:inventory_is_gun(tool) then
        Data.InventoryEquip = nil
    end
    if not Data.Sorting then
        phowg:request_inventory_sort()
    end
end
function phowg:inventory_tool_removed(tool)
    local character = LocalPlayer.Character
    if tool and character and not Data.IsRespawning and not Library.Unloaded and not Data.SharedSignalsClosed then
        local now, burst = tick(), Data.InventoryUnequipBurst
        if not burst or burst.Character ~= character or now - burst.At > 0.25 then
            burst = { Character = character, At = now, Tools = {}, Count = 0 }
            Data.InventoryUnequipBurst = burst
        end
        if not burst.Tools[tool] then
            burst.Tools[tool] = true
            burst.Count = burst.Count + 1
        end
        if burst.Count > 4 then
            phowg:preserve_inventory_visibility()
        end
    end
    if not Data.Sorting then
        phowg:request_inventory_sort()
    end
end
function hookautosort(char)
    if not char then
        return
    end
    Data.InventoryEquip = nil
    Data.SortOrder = nil
    Data.SortLastSet = nil
    local bp = LocalPlayer:FindFirstChild('Backpack')
    if bp then
        for _, tool in ipairs(bp:GetChildren()) do
            phowg:watch_inventory_tool(tool)
        end
    end
    for _, tool in ipairs(char:GetChildren()) do
        phowg:watch_inventory_tool(tool)
    end
    phowg:request_inventory_sort(true)
end
registerheartbeat('InventoryMaintenance', function()
