end)
phowg:register_cleanup('inventory sort', function(scope)
    local transaction = Data.SortTransaction
    if transaction and (not scope or scope == transaction.Character or scope == transaction.Backpack) then
        phowg:release_inventory_sort(transaction)
    end
    local pending = Data.InventoryEquip
    if pending and (not scope or scope == pending.Character or scope == pending.Backpack or scope == pending.Tool) then
        Data.InventoryEquip = nil
    end
    if not scope or scope == LocalPlayer.Character then
        Data.SortRequested = nil
        Data.SortForce = nil
        Data.SortOrder = nil
        Data.SortLastSet = nil
        Data.InventoryUnequipBurst = nil
        Data.InventoryVisibleUntil = nil
    end
    if not scope then
        Data.SortBackpack = nil
        Data.InventoryGunCache = nil
        Data.InventoryWatchedTools = nil
        Data.SortToolIds = nil
    end
end)
function executeautobuyitems()
    if localactionblocked() then
        return
    end
    if Data['LoadoutBusy'] then
        return
    end
    Data['LoadoutBusy'] = true
    local myChar = LocalPlayer.Character
    local wStart = tick()
    while Data['IsRespawning'] and tick() - wStart < 20 do
        RunService.Heartbeat:Wait()
        if LocalPlayer.Character ~= myChar then
            Data['LoadoutBusy'] = nil
            return
        end
    end
    if Data['IsRespawning'] then
        Data['LoadoutBusy'] = nil
        return
    end
    local char = LocalPlayer.Character
    if not char or char ~= myChar then
        Data['LoadoutBusy'] = nil
        return
    end
    if char then
        char:WaitForChild('HumanoidRootPart', 8)
        if LocalPlayer.Character ~= myChar then
            Data['LoadoutBusy'] = nil
            return
        end
        char:WaitForChild('Humanoid', 8)
        if LocalPlayer.Character ~= myChar then
            Data['LoadoutBusy'] = nil
            return
        end
        local fl = char:FindFirstChild('FULLY_LOADED_CHAR')
        if not fl then
            fl = char:WaitForChild('FULLY_LOADED_CHAR', 10)
        end
        if LocalPlayer.Character ~= myChar then
            Data['LoadoutBusy'] = nil
            return
        end
        if fl and fl:IsA('ValueBase') then
            local f0 = tick()
            repeat
                RunService.Heartbeat:Wait()
            until (fl.Value == true or fl.Value == 'true') or tick() - f0 > 10 or LocalPlayer.Character ~= myChar
        end
        if LocalPlayer.Character ~= myChar then
            Data['LoadoutBusy'] = nil
            return
        end
        task.wait(0.3)
    end
    local hum0 = LocalPlayer.Character and LocalPlayer.Character:FindFirstChildOfClass('Humanoid') or nil
    if not hum0 or hum0.Health <= 0 then
        Data['LoadoutBusy'] = nil
        return
    end
    local Items = {
        Options.auto_buy_item1 and Options.auto_buy_item1.Value,
        Options.auto_buy_item2 and Options.auto_buy_item2.Value,
        Options.auto_buy_item3 and Options.auto_buy_item3.Value,
    }
    local purchases = {}
    for _, query in ipairs(Items) do
        if type(query) == 'string' and query ~= '' then
            purchases[#purchases + 1] = {
                Query = query,
                ShouldContinue = function()
                    if LocalPlayer.Character ~= myChar or Data.IsRespawning or localactionblocked() then
                        return false
                    end
                    if phowg:is_armor_purchase(query) then
                        local armor = query:lower():find('fire', 1, true) and getfirearmorvalue() or getarmorvalue()
                        return armor == nil or armor < 100
                    end
                    return true
                end,
            }
        end
    end
    phowg:purchase_items(purchases)
    aftershopbuy()
    Data['LoadoutBusy'] = nil
end
function phowg:close_lookup_cache(state)
    if not state then
        return
    end
    for _, connection in pairs(state.Connections or {}) do
        connection:Disconnect()
    end
end
function phowg:loadout_catalog(force)
    local ignored = Workspace:FindFirstChild('Ignored')
    local shop = ignored and ignored:FindFirstChild('Shop')
    local state = Data.LoadoutCatalogCache
    local observe = Toggles.loadout_manager and Toggles.loadout_manager.Value == true
    local selected = phowg:ammo_supply_selection(Options.loadout_weapons and Options.loadout_weapons.Value)
    local selectedKeys = {}
    for name, wanted in pairs(selected) do
        if wanted then
            selectedKeys[#selectedKeys + 1] = normalizeweaponname(name)
        end
    end
    table.sort(selectedKeys)
    local selectionKey = table.concat(selectedKeys, '|')
    if not state or state.Shop ~= shop or state.Observe ~= observe then
        phowg:close_lookup_cache(state)
        state = { Shop = shop, Observe = observe, Dirty = true, Connections = {}, Names = {}, NextFullAt = 0 }
        Data.LoadoutCatalogCache = state
        if shop and observe then
            local function dirty()
                state.Dirty = true
                Data.LoadoutCheckAt = 0
            end
            state.MarkDirty = dirty
            state.Connections.Added =
                connectshared(shop.DescendantAdded, dirty, shop, 'loadout/shop added', 0, 'event/DescendantAdded', shop)
            state.Connections.Removed = connectshared(
                shop.DescendantRemoving,
                dirty,
                shop,
                'loadout/shop removed',
                0,
                'event/DescendantRemoving',
                shop
            )
            state.Connections.Names = {
                Disconnect = function()
                    for item, connection in pairs(state.Names) do
                        connection:Disconnect()
                        state.Names[item] = nil
                    end
                end,
            }
        end
    end
    if state.SelectionKey ~= selectionKey then
        state.SelectionKey = selectionKey
        state.Dirty = true
    end
    if not force and observe and not state.Dirty and tick() < state.NextFullAt then
        return state.Weapons, state.Values
    end
    local entries, ammo = {}, {}
    for _, item in ipairs(shop and shop:GetChildren() or {}) do
        local name = item.Name:match('%[(.-)%]')
        local price = shopitemprice(item)
        if
            name
            and price
            and item:FindFirstChildWhichIsA('ClickDetector', true)
            and item:FindFirstChildWhichIsA('BasePart', true)
        then
            local base = name:match('^(.-)%s+[Aa][Mm][Mm][Oo]$')
            local key = normalizeweaponname(base or name)
            local target = base and ammo or entries
            if not target[key] or price < target[key].Price then
                target[key] = { Item = item, Price = price, Name = '[' .. (base or name) .. ']' }
            end
        end
    end
    local weapons, values, changed = {}, {}, false
    for key, entry in pairs(entries) do
        if ammo[key] or key == 'knife' then
            entry.Ammo = key ~= 'knife' and ammo[key] or nil
            weapons[key] = entry
            values[#values + 1] = entry.Name
            if key ~= 'knife' and not Data.GunWeaponKeys[key] then
                Data.GunWeaponKeys[key] = true
                Data.GunWeaponNames[#Data.GunWeaponNames + 1] = entry.Name
                changed = true
            end
        end
    end
    if changed then
        phowg:sync_gun_weapon_choices()
    end
    table.sort(values)
    if observe and state.MarkDirty then
        local wanted = {}
        for _, key in ipairs(selectedKeys) do
            local entry = weapons[key]
            if entry then
                wanted[entry.Item] = true
                if entry.Ammo then
                    wanted[entry.Ammo.Item] = true
                end
            end
        end
        for item, connection in pairs(state.Names) do
            if not wanted[item] then
                connection:Disconnect()
                state.Names[item] = nil
            end
        end
        for item in pairs(wanted) do
            if not state.Names[item] then
                state.Names[item] = connectshared(
                    item:GetPropertyChangedSignal('Name'),
                    state.MarkDirty,
                    item,
                    'loadout/shop name',
                    0,
                    'property/Name',
                    item
                )
            end
        end
    end
    state.Weapons, state.Values, state.Dirty, state.NextFullAt = weapons, values, false, tick() + 5
    return weapons, values
end
function phowg:loadout_tool(key)
    local character, backpack = LocalPlayer.Character, LocalPlayer:FindFirstChild('Backpack')
    local containers = {}
    if character then
        containers[#containers + 1] = character
    end
    if backpack then
        containers[#containers + 1] = backpack
    end
    local state = Data.LoadoutToolCache
    if not state or state.Character ~= character or state.Backpack ~= backpack then
        phowg:close_lookup_cache(state)
        state = { Character = character, Backpack = backpack, Connections = {}, Names = {}, Dirty = true, Tools = {} }
        Data.LoadoutToolCache = state
        local function dirty()
            state.Dirty = true
        end
        local function added(tool)
            dirty()
            if not tool:IsA('Tool') or state.Names[tool] then
                return
            end
            state.Names[tool] = connectshared(
                tool:GetPropertyChangedSignal('Name'),
                dirty,
                tool,
                'loadout/tool name',
                0,
                'property/Name',
                tool
            )
        end
        local function removed(tool)
            dirty()
            local connection = state.Names[tool]
            if connection then
                connection:Disconnect()
                state.Names[tool] = nil
            end
        end
        for _, container in ipairs(containers) do
            state.Connections[#state.Connections + 1] = connectshared(
                container.ChildAdded,
                added,
                container,
                'loadout/tool added',
                0,
                'event/ChildAdded',
                container
            )
            state.Connections[#state.Connections + 1] = connectshared(
                container.ChildRemoved,
                removed,
                container,
                'loadout/tool removed',
                0,
                'event/ChildRemoved',
                container
            )
            for _, tool in ipairs(container:GetChildren()) do
                added(tool)
            end
        end
        state.Connections.Names = {
            Disconnect = function()
                for tool, connection in pairs(state.Names) do
                    connection:Disconnect()
                    state.Names[tool] = nil
                end
            end,
        }
    end
    if state.Dirty then
        table.clear(state.Tools)
        for _, container in ipairs(containers) do
            for _, tool in ipairs(container:GetChildren()) do
                if tool:IsA('Tool') then
                    local name = normalizeweaponname(tool.Name)
                    if not state.Tools[name] then
                        state.Tools[name] = tool
                    end
                end
            end
        end
        state.Dirty = false
    end
    return state.Tools[key]
end
phowg:register_cleanup('loadout lookups', function(scope)
    local state = Data.LoadoutToolCache
    if state and (not scope or scope == state.Character or scope == state.Backpack) then
        phowg:close_lookup_cache(state)
        Data.LoadoutToolCache = nil
    end
    state = Data.LoadoutCatalogCache
    if state and (not scope or scope == state.Shop) then
        phowg:close_lookup_cache(state)
        Data.LoadoutCatalogCache = nil
    end
end)
function phowg:loadout_ammo_purchase_allowed()
    local character = LocalPlayer.Character
    if
        Library.Unloaded
        or Data.IsRespawning
        or localactionblocked()
        or not character
        or not character:FindFirstChild('HumanoidRootPart')
    then
        return false
    end
    return not isdead(LocalPlayer) and not isknocked(LocalPlayer) and not isstomped(LocalPlayer)
end
function phowg:queue_loadout_ammo_check(character)
    if
        character ~= LocalPlayer.Character
        or not phowg:loadout_ammo_purchase_allowed()
        or not (Toggles.loadout_manager and Toggles.loadout_manager.Value)
        or not (Toggles.loadout_maintain_ammo and Toggles.loadout_maintain_ammo.Value)
    then
        return
    end
    Data.LoadoutCheckAt = 0
    for name, selected in pairs(phowg:ammo_supply_selection(Options.loadout_weapons and Options.loadout_weapons.Value)) do
        local key = normalizeweaponname(name)
        if selected and Data.LoadoutRetry and phowg:loadout_tool(key) then
            Data.LoadoutRetry[key] = nil
        end
    end
    if Data.LoadoutAmmoCheckQueued then
        return
    end
    Data.LoadoutAmmoCheckQueued = true
    task.defer(function()
        Data.LoadoutAmmoCheckQueued = nil
        if character == LocalPlayer.Character and phowg:loadout_ammo_purchase_allowed() and not Library.Unloaded then
            phowg:loadout_tick()
        end
    end)
end
function phowg:loadout_plan(catalog, selected, cash, now, ammoOnly)
    local reserve = phowg:visual_number('loadout_cash_reserve', 0, 0, 100000)
    local clips = phowg:visual_number('loadout_min_clips', 3, 1, 20)
    local batch = phowg:visual_number('loadout_ammo_batch', 3, 1, 10)
    local names = {}
    for name, enabled in pairs(selected or {}) do
        if enabled then
            names[#names + 1] = name
        end
    end
    table.sort(names)
    local missing, ammunition, unavailable, pending, poor = {}, {}, 0, 0, false
    for _, name in ipairs(names) do
        local key = normalizeweaponname(name)
        local entry = catalog[key]
        if not entry then
            unavailable = unavailable + 1
        elseif now >= ((Data.LoadoutRetry or {})[key] or 0) then
            local tool = phowg:loadout_tool(key)
            if not tool and not ammoOnly then
                if cash - entry.Price >= reserve then
                    missing[#missing + 1] = { Key = key, Query = entry.Item.Name, Count = 1 }
                else
                    poor = true
                end
            elseif
                tool
                and entry.Ammo
                and Toggles.loadout_maintain_ammo
                and Toggles.loadout_maintain_ammo.Value
                and phowg:loadout_ammo_purchase_allowed()
            then
                local maximum = tool:FindFirstChild('MaxAmmo')
                local capacity = tonumber(maximum and maximum.Value or tool:GetAttribute('MaxAmmo'))
                local stock = getgunreserve(tool)
                if capacity and capacity > 0 and stock and stock < capacity * clips then
                    local needed = math.max(1, math.ceil((capacity * clips - stock) / capacity))
                    local count =
                        math.min(batch, needed, math.floor(math.max(0, cash - reserve) / math.max(1, entry.Ammo.Price)))
                    if count > 0 then
                        ammunition[#ammunition + 1] =
                            { Key = key, Query = entry.Ammo.Item.Name, Count = count, Ammo = true }
                    else
                        poor = true
                    end
                elseif not capacity or capacity <= 0 or stock == nil then
                    pending = pending + 1
                end
            end
        end
    end
    return missing[1] or ammunition[1],
        #names == 0 and 'select weapons'
            or poor and 'cash reserve reached'
            or unavailable > 0 and 'some weapons unavailable in this shop'
            or pending > 0 and 'waiting for ammunition data'
            or 'loadout ready'
end
function phowg:track_loadout_reload(character, active)
    if character ~= LocalPlayer.Character then
        return
    end
    local state = Data.LoadoutActiveReload
    if active then
        if state and state.Character == character and state.Active then
            return
        end
        local tool = Local_Data.Current_Gun
        if not tool or tool.Parent ~= character or not tool:FindFirstChild('Ammo') then
            tool = nil
            for _, held in ipairs(character:GetChildren()) do
                if held:IsA('Tool') and held:FindFirstChild('Ammo') then
                    tool = held
                    break
                end
            end
        end
        Data.LoadoutActiveReload = { Character = character, Tool = tool, Active = true, StartedAt = tick() }
        phowg:queue_loadout_ammo_check(character)
    elseif state and state.Character == character and state.Active then
        state.Active, state.FinishedAt = false, tick()
    end
end
function phowg:loadout_reload_in_progress(tool)
    local character = LocalPlayer.Character
    local body = character and character:FindFirstChild('BodyEffects')
    local reload, reloading = body and body:FindFirstChild('Reload'), body and body:FindFirstChild('Reloading')
    local active = reload and reload:IsA('BoolValue') and reload.Value == true
        or reloading and reloading:IsA('BoolValue') and reloading.Value == true
        or false
    local state = Data.LoadoutActiveReload
    if state and state.Character ~= character then
        Data.LoadoutActiveReload = nil
        state = nil
    end
    if state and state.Active and not active then
        phowg:track_loadout_reload(character, false)
    end
    if not tool then
        return active
    end
    if not state or state.Tool ~= tool then
        return false
    end
    if tool.Parent ~= character and tool.Parent ~= LocalPlayer:FindFirstChild('Backpack') then
        Data.LoadoutActiveReload = nil
        return false
    end
    return state.Active or tick() - (state.FinishedAt or 0) < 0.5
end
function phowg:reload_backpack_guns()
    if Data.RagebotIdle or tick() < (Data.ToolCleanupUntil or 0) or phowg:china_multi_active() or Data.HeldGunFire then
        return
    end
    if
        Data.LoadoutReloadJob
        or Data.Buying
        or Data.LoadoutBusy
        or next(Data.SupportGunReloads or {})
        or Data.IsRespawning
        or Library.Unloaded
        or localactionblocked()
        or phowg:loadout_reload_in_progress()
    then
        return
    end
    local character, backpack = LocalPlayer.Character, LocalPlayer:FindFirstChild('Backpack')
    local humanoid = character and character:FindFirstChildOfClass('Humanoid')
    local remote = MainEvent or ReplicatedStorage:FindFirstChild('MainEvent')
    if not humanoid or humanoid.Health <= 0 or not backpack or not remote then
        return
    end
    local original = character:FindFirstChildOfClass('Tool')
    local tools = {}
    for _, tool in ipairs(backpack:GetChildren()) do
        if tool:IsA('Tool') then
            local ammo, maximum = tool:FindFirstChild('Ammo'), tool:FindFirstChild('MaxAmmo')
            local capacity = maximum and maximum.Value or tool:GetAttribute('MaxAmmo')
            local reserve = ammo and getgunreserve(tool)
            if
                ammo
                and ammo:IsA('ValueBase')
                and type(ammo.Value) == 'number'
                and (type(capacity) ~= 'number' or ammo.Value < capacity)
                and (reserve == nil or reserve > 0)
                and not phowg:loadout_reload_in_progress(tool)
            then
                tools[#tools + 1] = tool
            end
        end
    end
    if #tools == 0 then
        return
    end
    local job: { [string]: any } =
        { Character = character, ReturnMovement = phowg:capture_active_movement(), Revision = Data.ToolEquipRevision or 0 }
    Data.LoadoutReloadJob, Data.LoadoutBusy = job, true
    task.spawn(function()
        local owned
        local function valid()
            return Data.LoadoutReloadJob == job
                and job.Revision == (Data.ToolEquipRevision or 0)
                and not phowg:china_multi_active()
                and not Data.HeldGunFire
                and Toggles.loadout_manager.Value
                and Toggles.loadout_reload_backpack.Value
                and LocalPlayer.Character == character
                and humanoid.Parent == character
                and humanoid.Health > 0
                and not Data.IsRespawning
                and not Library.Unloaded
                and not Data.Buying
                and not Data.BuildActive
                and not Data.CurrentActionTarget
                and not Data.PunishmentGunActive
                and not localactionblocked()
        end
        local function sync_void()
            local enabled = Toggles.loadout_reload_void and Toggles.loadout_reload_void.Value
            if enabled and valid() then
                if not job.Hold then
                    job.Hold = startmovetohold('LoadoutReload', getvoidcframe(), Data.PRIO.LOADOUT, function()
                        return valid() and Toggles.loadout_reload_void.Value
                    end)
                    set_server_cframe(job.Hold.CFrame, nil, job.Hold.Priority, job.Hold.Tag, false, job.Hold)
                else
                    job.Hold:Update(getvoidcframe())
                end
            elseif job.Hold then
                job.Hold:Stop()
                job.Hold = nil
                phowg:resume_active_movement(job.ReturnMovement)
            end
        end
        local ok, problem = pcall(function()
            for _, tool in ipairs(tools) do
                if not valid() or phowg:loadout_reload_in_progress() then
                    break
                end
                local current = character:FindFirstChildOfClass('Tool')
                if owned and current and current ~= owned then
                    break
                end
                local ammo = tool:FindFirstChild('Ammo')
                local maximum = tool:FindFirstChild('MaxAmmo')
                local capacity = maximum and maximum.Value or tool:GetAttribute('MaxAmmo')
                local reserve = getgunreserve(tool)
                if
                    tool.Parent == backpack
                    and ammo
                    and ammo:IsA('ValueBase')
                    and type(ammo.Value) == 'number'
                    and (type(capacity) ~= 'number' or ammo.Value < capacity)
                    and (reserve == nil or reserve > 0)
                    and not phowg:loadout_reload_in_progress(tool)
                then
                    if not equip(tool, job) or tool.Parent ~= character then
                        break
                    end
                    owned = tool
                    sync_void()
                    local before, started, requestedAt = ammo.Value, false, tick()
                    local deadline = requestedAt + 8
                    if not phowg:request_gun_reload(tool, remote, job) then
                        break
                    end
                    repeat
                        RunService.Heartbeat:Wait()
                        sync_void()
                        local active = phowg:loadout_reload_in_progress()
                        local observed = Data.LoadoutActiveReload
                        if
                            active
                            or observed
                                and observed.Character == character
                                and observed.Tool == tool
                                and observed.StartedAt >= requestedAt
                        then
                            started = true
                        end
                        if ammo.Value > before and not active or started and not active then
                            break
                        end
                    until not valid() or tool.Parent ~= character or ammo.Parent ~= tool or tick() >= deadline
                end
            end
        end)
        if job.Hold then
            job.Hold:Stop()
            job.Hold = nil
        end
        if Data.LoadoutReloadJob == job then
            Data.LoadoutReloadJob, Data.LoadoutBusy = nil, nil
            phowg:resume_active_movement(job.ReturnMovement)
            if
                LocalPlayer.Character == character
                and humanoid.Parent == character
                and humanoid.Health > 0
                and not Library.Unloaded
            then
                local current = character:FindFirstChildOfClass('Tool')
                if not current or current == owned then
                    if owned and owned.Parent == character then
                        owned.Parent = backpack
                    end
                    if original and original.Parent == backpack and not localactionblocked() then
                        equip(original)
                    end
                end
            end
        end
        if not ok then
            warn('[Phowg] backpack reload: ' .. tostring(problem))
        end
    end)
    return true
end
function phowg:run_loadout_tick()
    if not (Toggles.loadout_manager and Toggles.loadout_manager.Value) then
        if Data.LoadoutStatus then
            Data.LoadoutStatus:SetText('manager: off')
        end
        return
    end
    local now = tick()
    if now < (Data.LoadoutCheckAt or 0) then
        return
    end
    Data.LoadoutCheckAt = now + phowg:visual_number('loadout_check_interval', 1, 0.5, 10)
    if
        Data.Buying
        or Data.LoadoutBusy
        or Data.BuildActive
        or next(Data.SupportGunReloads or {})
        or Data.IsRespawning
        or localactionblocked()
        or not phowg:loadout_ammo_purchase_allowed()
        or armorneedsbuy()
        or firearmorneedsbuy()
    then
        return
    end
    local character = LocalPlayer.Character
    if not character or not character:FindFirstChild('HumanoidRootPart') then
        return
    end
    local loaded = character:FindFirstChild('FULLY_LOADED_CHAR')
    if not loaded or loaded:IsA('ValueBase') and loaded.Value ~= true and loaded.Value ~= 'true' then
        return
    end
    local df = LocalPlayer:FindFirstChild('DataFolder')
    local currency = df and df:FindFirstChild('Currency')
    if not currency or type(currency.Value) ~= 'number' then
        return
    end
    local catalog = phowg:loadout_catalog()
    local previous
    local function next_purchase()
        if
            not Toggles.loadout_manager.Value
            or LocalPlayer.Character ~= character
            or Data.IsRespawning
            or localactionblocked()
            or not phowg:loadout_ammo_purchase_allowed()
            or armorneedsbuy()
            or firearmorneedsbuy()
            or currency.Parent == nil
        then
            return nil
        end
        if previous and not previous.Ammo and phowg:loadout_tool(previous.Key) then
            Data.LoadoutRetry[previous.Key] = nil
        end
        previous = nil
        local action, status = phowg:loadout_plan(
            catalog,
            phowg:ammo_supply_selection(Options.loadout_weapons and Options.loadout_weapons.Value),
            currency.Value,
            tick(),
            Data.CurrentActionTarget ~= nil or phowg:combat_ammo_active()
        )
        if Data.LoadoutStatus then
            Data.LoadoutStatus:SetText('manager: ' .. (action and 'buying ' .. action.Query or status))
        end
        if not action then
            return nil
        end
        Data.LoadoutRetry = Data.LoadoutRetry or {}
        Data.LoadoutRetry[action.Key] = tick() + (action.Ammo and 0.5 or 5)
        previous = action
        local entry = catalog[action.Key]
        local price = action.Ammo and entry.Ammo.Price or entry.Price
        return {
            Query = action.Query,
            Prio = action.Ammo and Data.PRIO.AMMO or Data.PRIO.LOADOUT,
            Count = action.Count,
            Quiet = true,
            ShouldContinue = function()
                local selected = phowg:ammo_supply_selection(Options.loadout_weapons and Options.loadout_weapons.Value)
                local wanted = false
                for name, enabled in pairs(selected) do
                    if enabled and normalizeweaponname(name) == action.Key then
                        wanted = true
                        break
                    end
                end
                return Toggles.loadout_manager.Value
                    and wanted
                    and LocalPlayer.Character == character
                    and not Data.IsRespawning
                    and (action.Ammo or not Data.CurrentActionTarget and not Data.PunishmentGunActive)
                    and not armorneedsbuy()
                    and not firearmorneedsbuy()
                    and currency.Parent ~= nil
                    and currency.Value - price >= phowg:visual_number('loadout_cash_reserve', 0, 0, 100000)
                    and (not action.Ammo or phowg:loadout_ammo_purchase_allowed())
                    and (
                        action.Ammo and Toggles.loadout_maintain_ammo.Value
                        or not action.Ammo and not phowg:loadout_tool(action.Key)
                    )
            end,
        }
    end
    local first = next_purchase()
    if first then
        phowg:purchase_items({ first }, next_purchase)
    end
    if
        LocalPlayer.Character == character
        and Toggles.loadout_manager.Value
        and not Data.Buying
        and not Data.IsRespawning
        and not localactionblocked()
        and not Data.CurrentActionTarget
        and not Data.PunishmentGunActive
        and not armorneedsbuy()
        and not firearmorneedsbuy()
        and Toggles.loadout_reload_backpack
        and Toggles.loadout_reload_backpack.Value
    then
        phowg:reload_backpack_guns()
    end
    Data.LoadoutCheckAt = tick() + phowg:visual_number('loadout_check_interval', 1, 0.5, 10)
end
function phowg:loadout_tick()
    if Data.LoadoutTickRunning or Data.AmmoSupplyOwner then
        return
    end
    local job = { Character = LocalPlayer.Character }
    Data.LoadoutTickRunning = job
    Data.AmmoSupplyOwner = job
    local ok, problem = pcall(phowg.run_loadout_tick)
    if Data.AmmoSupplyOwner == job then
        Data.AmmoSupplyOwner = nil
    end
    if Data.LoadoutTickRunning == job then
        Data.LoadoutTickRunning = nil
    end
    if not ok then
        error(problem, 0)
    end
end
registerheartbeat('LoadoutManager', phowg.loadout_tick, 0.5)
