        if job.Hold then
            job.Hold:Stop()
            job.Hold = nil
        end
        Data.LoadoutReloadJob, Data.LoadoutBusy = nil, nil
    end
    local reload = Data.LoadoutActiveReload
    if reload and (not scope or scope == reload.Character or scope == reload.Tool) then
        Data.LoadoutActiveReload = nil
    end
    if not scope or scope == LocalPlayer.Character then
        Data.LoadoutCheckAt = 0
        Data.LoadoutRetry = {}
        Data.LoadoutAmmoCheckQueued = nil
        Data.LoadoutAmmoWindow = nil
    end
    if Data.LoadoutTickRunning and (not scope or scope == Data.LoadoutTickRunning.Character) then
        Data.LoadoutTickRunning = nil
    end
end)
function getmuscle()
    local Cache = intelligence:get_data_cache(LocalPlayer)
    local v = Cache and tonumber(Cache.MuscleInformation) or nil
    return v
end
function gethealthpercent()
    local char = LocalPlayer.Character
    local hum = char and char:FindFirstChildOfClass('Humanoid') or nil
    if not hum then
        return nil
    end
    local max = hum.MaxHealth
    if not max or max <= 0 then
        return nil
    end
    return (hum.Health / max) * 100
end
function armorneedsbuy()
    if not (Toggles.auto_armor and Toggles.auto_armor.Value) then
        return false
    end
    local val = getarmorvalue()
    if val == nil then
        return false
    end
    if Toggles.armor_buy_on_damage and Toggles.armor_buy_on_damage.Value then
        return val <= 0
    end
    return val < 100
end
function firearmorneedsbuy()
    if not (Toggles.auto_fire_armor and Toggles.auto_fire_armor.Value) then
        return false
    end
    local fav = phowg:get_fire_armor_save()
    if fav == nil then
        return false
    end
    return fav < 100
end
function autohealloop()
    if Toggles.auto_heal and Toggles.auto_heal.Value then
        if localactionblocked() then
            task.wait(0.05)
            return
        end
        local threshold = Options.heal_at and Options.heal_at.Value or 50
        local pctNow = gethealthpercent()
        local char = LocalPlayer.Character
        local hum = char and char:FindFirstChildOfClass('Humanoid') or nil
        if not char or not hum or Data['IsRespawning'] or hum.Health <= 0 or isdead(LocalPlayer) then
            task.wait(0.25)
        elseif punishmentactive() and not Data['Buying'] then
            task.wait(0.25)
        elseif rageboton() and not Data['Buying'] and (Data['CurrentActionTarget'] ~= nil or hasactionabletarget()) then
            task.wait(0.25)
        elseif (pctNow == nil or pctNow >= threshold) and (armorneedsbuy() or firearmorneedsbuy()) then
            task.wait(0.25)
        elseif (pctNow == nil or pctNow >= threshold) and Data['Buying'] then
            task.wait(0.1)
        else
            local pct = gethealthpercent()
            if pct == nil or pct >= threshold then
                if not punishmentactive() then
                    local ch0 = LocalPlayer.Character
                    local pack0 = LocalPlayer:FindFirstChild('Backpack')
                    if ch0 and pack0 then
                        for _, t in ipairs(ch0:GetChildren()) do
                            if t:IsA('Tool') and t.Name:lower():match('burger') then
                                t.Parent = pack0
                            end
                        end
                    end
                end
                task.wait(0.25)
            else
                local tool = findtoolbypattern('burger')
                if not tool and not Data['Buying'] then
                    purchase_item('burger', Data['PRIO'].HEAL)
                    tool = findtoolbypattern('burger')
                end
                if tool then
                    if
                        not Data['Buying']
                        and not armorneedsbuy()
                        and not firearmorneedsbuy()
                        and Toggles.auto_heal_in_void
                        and Toggles.auto_heal_in_void.Value
                    then
                        set_server_cframe(getvoidcframe(), nil, Data['PRIO'].HEAL, 'Heal')
                    end
                    local pack = LocalPlayer:FindFirstChild('Backpack')
                    if tool.Parent ~= LocalPlayer.Character then
                        equip(tool)
                        RunService.Heartbeat:Wait()
                        tool = findtoolbypattern('burger')
                    end
                    if tool and tool.Parent == LocalPlayer.Character then
                        if not localactionblocked() then
                            tool:Activate()
                        end
                        task.wait()
                        if tool.Parent == LocalPlayer.Character and pack then
                            tool.Parent = pack
                        end
                    end
                    local ch = LocalPlayer.Character
                    if ch and pack then
                        for _, t in ipairs(ch:GetChildren()) do
                            if t:IsA('Tool') and t.Name:lower():match('burger') then
                                t.Parent = pack
                            end
                        end
                    end
                    releasemovement('Heal')
                    task.wait(0.3)
                else
                    RunService.Heartbeat:Wait()
                end
            end
        end
    end
end
function buylettuceafk()
    if localactionblocked() then
        return
    end
    if Data['Buying'] then
        return
    end
    local ShopItem, Head, ClickDetector = findshopitem('lettuce')
    if not ShopItem or not Head or not ClickDetector then
        return
    end
    local char = LocalPlayer.Character
    if not char or not char:FindFirstChild('HumanoidRootPart') then
        return
