    char:WaitForChild('FULLY_LOADED_CHAR', 5)
    char:WaitForChild('HumanoidRootPart', 5)
    char:WaitForChild('Humanoid', 5)
    Data['Buying'] = true
    setbuyingstatus('lettuce')
    local padCF = CFrame.new(Head.Position - Vector3.new(0, 7, 0)) * CFrame.Angles(0, 0, math.rad(180))
    set_server_cframe(padCF, nil, Data['PRIO'].LOADOUT, 'Buy')
    local t0 = tick()
    local lastHold = 0
    while tick() - t0 < 1 do
        if Data['IsRespawning'] then
            break
        end
        if findtoolbypattern('lettuce') then
            break
        end
        if tick() - lastHold > 0.5 then
            lastHold = tick()
            set_server_cframe(padCF, nil, Data['PRIO'].LOADOUT, 'Buy')
        end
        if not localactionblocked() then
            fireclickdetector(ClickDetector)
        end
        RunService.Heartbeat:Wait()
    end
    clearbuyingstatus('lettuce')
    Data['Buying'] = false
    for i = #Data['CSync'].Queue, 1, -1 do
        if Data['CSync'].Queue[i].tag == 'Buy' then
            table.remove(Data['CSync'].Queue, i)
        end
    end
    if LocalPlayer.Character and LocalPlayer.Character:FindFirstChild('HumanoidRootPart') then
        Data['LastServerCF'] = LocalPlayer.Character.HumanoidRootPart.CFrame
        Data['LastMoveToAt'] = tick()
    end
end
function clearlettuceprogress()
    stopmovetohold('Lettuce')
    local notice = Data['LettuceProgressNotice']
    Data['LettuceProgressNotice'] = nil
    Data['LettuceProgressStart'] = nil
    Data['LettuceProgressTarget'] = nil
    if notice then
        notice:Complete()
    end
end
function updatelettuceprogress(muscle, target)
    if type(muscle) ~= 'number' then
        return
    end
    if Data['LettuceProgressTarget'] ~= target then
        Data['LettuceProgressStart'] = muscle
        Data['LettuceProgressTarget'] = target
    end
    local start = Data['LettuceProgressStart'] or muscle
    local fraction = muscle <= target and 1 or math.clamp((start - muscle) / math.max(start - target, 1), 0, 1)
    local text = ('eating lettuce %d/%d %d%%'):format(math.floor(muscle), target, math.floor(fraction * 100))
    local notice = Data['LettuceProgressNotice']
    if not notice or notice.Closed then
        if Library.NotifyProgress then
            Data['LettuceProgressNotice'] = Library:NotifyProgress(text, fraction)
        end
    else
        notice:Update(text, fraction)
    end
end
function ensurelettucehold()
    local current = Data['MoveToHolds'] and Data['MoveToHolds'].Lettuce
    if current and validmovetohold(current) then
        return current
    end
    local item, head = findshopitem('lettuce')
    if not item or not head or not head.Parent then
        return nil
    end
    local character = LocalPlayer.Character
    return startmovetohold(
        'Lettuce',
        CFrame.new(head.Position - Vector3.new(0, 7, 0)) * CFrame.Angles(0, 0, math.rad(180)),
        79,
        function()
            return Toggles.auto_lettuce
                and Toggles.auto_lettuce.Value
                and character == LocalPlayer.Character
                and head.Parent ~= nil
        end,
        function()
            local tool = findtoolbypattern('lettuce')
            if tool and tool.Parent == character and not localactionblocked() then
                tool:Activate()
            end
        end
    )
end
function autolettuceloop()
    while Toggles.auto_lettuce and Toggles.auto_lettuce.Value do
        local SkinnyTarget = -15000
        if Options.skinny_level and Options.skinny_level.Value == 'perfect' then
            SkinnyTarget = -10000
        end
        local m = getmuscle()
        updatelettuceprogress(m, SkinnyTarget)
        if localactionblocked() then
            task.wait(0.05)
            continue
        end
        ensurelettucehold()
        if m and m <= SkinnyTarget then
            clearlettuceprogress()
            if SkinnyTarget == -15000 then
                (function()
                    local hum = LocalPlayer.Character and LocalPlayer.Character:FindFirstChildOfClass('Humanoid')
                    if hum then
                        hum.Health = 0
                    end
                end)()
                Library:Notify('you are max now.', Library.NotifyDuration or 4)
            else
                Library:Notify('you are now perfectly skinny', Library.NotifyDuration or 4)
            end
            if Toggles.auto_lettuce and Toggles.auto_lettuce.SetValue then
                Toggles.auto_lettuce:SetValue(false)
            end
        else
            local tool = findtoolbypattern('lettuce')
            if not tool and not Data['Buying'] then
                if Toggles.lettuce_afk and Toggles.lettuce_afk.Value then
                    buylettuceafk()
                else
                    purchase_item('lettuce', Data['PRIO'].LOADOUT)
                end
                tool = findtoolbypattern('lettuce')
            end
            if tool then
                if tool.Parent ~= LocalPlayer.Character then
                    equip(tool)
                end
                task.wait(0)
                tool = findtoolbypattern('lettuce')
                if tool and tool.Parent == LocalPlayer.Character then
                    local hold = Data['MoveToHolds'] and Data['MoveToHolds'].Lettuce
                    if not hold and not localactionblocked() then
                        tool:Activate()
                    end
                end
                task.wait()
            else
                RunService.Heartbeat:Wait()
            end
        end
    end
    clearlettuceprogress()
end
function getignoreditemnames()
    local out = {}
    local seen = {}
    local ok, shop =
        true, (function()
            local ig = Workspace:FindFirstChild('Ignored')
            return ig and ig:FindFirstChild('Shop') or nil
        end)()
    if ok and shop then
        local ignore = {
            foodscart = true,
            flowers = true,
            antibodies = true,
            defaultmoveset = true,
            tele = true,
            flame = true,
            flamethrower = true,
        }
        (function()
            for _, item in ipairs(shop:GetChildren()) do
                local bracket = string.match(item.Name, '%b[]')
                if bracket then
                    if not string.find(bracket, 'Phone') then
                        local n = string.lower((string.gsub(bracket, '%s', '')))
                        n = string.sub(n, 2, -2)
                        if not ignore[n] then
                            if not string.find(n, 'ammo', 1, true) then
                                if not tonumber(string.sub(n, #n, #n)) then
                                    local head = item:FindFirstChild('Head')
                                    if head and head:IsA('BasePart') then
                                        if head.Position.Y > -30 then
                                            if not seen[n] then
                                                seen[n] = true
                                                table.insert(out, n)
                                            end
                                        end
                                    end
                                end
                            end
                        end
                    end
                end
            end
        end)()
    end
    if #out == 0 then
        out = { 'bloxycola', 'rpg', 'deagle', 'firework', 'lmg', 'aug', 'rifle', 'revolver' }
    end
    local known = {}
    for _, name in ipairs(out) do
        known[normalizeweaponname(name)] = true
    end
    for _, name in ipairs(Data.GunWeaponNames) do
        local key = normalizeweaponname(name)
        if not known[key] then
            out[#out + 1] = name:sub(2, -2):lower():gsub('%s', '')
            known[key] = true
        end
    end
    table.sort(out)
    return out
end
function shopbracketname(shopName)
    local b = string.match(tostring(shopName or ''), '%b[]')
    if not b then
        return nil
    end
    return string.sub(string.lower((string.gsub(b, '%s', ''))), 2, -2)
end
function findexactshoptool(toolName)
    local clean = tostring(toolName or ''):gsub('%[', '')
    clean = clean:gsub('%]', '')
    local want = string.lower((string.gsub(clean, '%s', '')))
    want = string.gsub(want, '%-', '')
    if want == '' then
        return nil
    end
    local Shop = Workspace:FindFirstChild('Ignored') and Workspace.Ignored:FindFirstChild('Shop')
    if not Shop then
        return nil
    end
    local bestTool = nil
    local bestToolHead = nil
    local bestToolClick = nil
    local bestToolPrice = math.huge
    for _, Item in ipairs(Shop:GetChildren()) do
        local gotTool = shopbracketname(Item.Name)
        if gotTool then
            gotTool = string.gsub(gotTool, '%-', '')
        end
        if gotTool == want then
            local Head = Item:FindFirstChild('Head') or Item:FindFirstChildWhichIsA('BasePart')
            local ClickDetector = Item:FindFirstChildOfClass('ClickDetector') or Item:FindFirstChild('ClickDetector')
            if Head and ClickDetector then
                local price = shopitemprice(Item)
                if price and price < bestToolPrice then
                    bestTool = Item
                    bestToolHead = Head
                    bestToolClick = ClickDetector
                    bestToolPrice = price
                elseif not bestTool then
                    bestTool = Item
                    bestToolHead = Head
                    bestToolClick = ClickDetector
                end
            end
        end
    end
    if not bestTool then
        return nil
    end
    return bestTool, bestToolHead, bestToolClick
end
function countexacttools(toolName)
    local normWant = string.lower(tostring(toolName or ''))
    normWant = string.gsub(normWant, '[%[%]%s%-]', '')
    local n = 0
    local pack = LocalPlayer:FindFirstChild('Backpack')
    if pack then
        for _, Tool in ipairs(pack:GetChildren()) do
            if Tool:IsA('Tool') then
                local nm = string.gsub(string.lower(Tool.Name), '[%[%]%s%-]', '')
                if nm == normWant then
                    n = n + 1
                end
            end
        end
    end
    local char = LocalPlayer.Character
    if char then
        for _, Tool in ipairs(char:GetChildren()) do
            if Tool:IsA('Tool') then
                local nm = string.gsub(string.lower(Tool.Name), '[%[%]%s%-]', '')
                if nm == normWant then
                    n = n + 1
                end
            end
        end
    end
    return n
end
function equiponewithgrip(toolName, grip)
    local g = grip
    if type(g) == 'table' and g.grip then
        g = g.grip
    end
    if typeof(g) ~= 'CFrame' then
        return
    end
    local want = string.lower(tostring(toolName or ''));
    (function()
        local pack = LocalPlayer:FindFirstChild('Backpack')
        local char = LocalPlayer.Character
        local target = nil
        if pack then
            for _, v in ipairs(pack:GetChildren()) do
                if v:IsA('Tool') and string.lower(v.Name) == want and not Data['GrippedTools'][v] then
                    target = v
                    break
                end
            end
        end
        if not target and char then
            for _, v in ipairs(char:GetChildren()) do
                if v:IsA('Tool') and string.lower(v.Name) == want and not Data['GrippedTools'][v] then
                    target = v
                    break
                end
            end
        end
        if target and phowg:tool_grip_allowed(target) then
            target.Grip = g
            Data['GrippedTools'][target] = true
            equiptoolgentle(target)
        end
    end)()
end
function buildnotify(text)
    Library:Notify(tostring(text), Library.NotifyDuration or 3)
end
function phowg:buy_prop_plan(plan)
    if
        Data.Buying
        or Data.BuildActive
        or Data.LoadoutReloadJob
        or Data.IsRespawning
        or localactionblocked()
        or punishmentactive()
    then
        return
    end
    local character = LocalPlayer.Character
    if not character then
        return
    end
    Data.BuildActive = true
    local index, previousCount = 1, nil
    local ping = 0.08
    local pingOk, networkPing = pcall(LocalPlayer.GetNetworkPing, LocalPlayer)
    if pingOk and type(networkPing) == 'number' and networkPing == networkPing then
        ping = math.clamp(networkPing, 0, 2)
    end
    local equipSettle = math.clamp(ping * 2 + 0.05, 0.15, 4.1)
    local replicationWait = math.clamp(ping * 4 + 1.5, 2, 6)
    local function valid()
        return not Library.Unloaded
            and not Data.IsRespawning
            and LocalPlayer.Character == character
            and not localactionblocked()
            and not punishmentactive()
    end
    local function equip_owned(entry)
        if not valid() then
            return false
        end
        local backpack = LocalPlayer:FindFirstChild('Backpack')
        if not backpack then
            return false
        end
        local key = normalizeweaponname(entry.name)
        for _, tool in ipairs(backpack:GetChildren()) do
            if tool:IsA('Tool') and normalizeweaponname(tool.Name) == key then
                if not phowg:request_equipment('purchase', tool, 'equip') or tool.Parent ~= character then
                    return false
                end
            end
        end
        for _, tool in ipairs(backpack:GetChildren()) do
            if tool:IsA('Tool') and normalizeweaponname(tool.Name) == key then
                return false
            end
        end
        return valid()
    end
    local ok, problem = pcall(function()
        unequipall()
        phowg:purchase_items({}, function()
            while valid() do
                local entry = plan and plan[index]
                if not entry then
                    return nil
                end
                local count = countexacttools(entry.name)
                if previousCount and count <= previousCount then
                    local deadline = tick() + replicationWait
                    repeat
                        RunService.Heartbeat:Wait()
                        if not valid() then
                            return nil
                        end
                        phowg:maintain_purchase_movement(Data.PurchaseBatch)
                        count = countexacttools(entry.name)
                    until count > previousCount or tick() >= deadline
                    if count <= previousCount then
                        buildnotify('could not buy another ' .. entry.name)
                        return nil
                    end
                end
                if count >= #entry.grips then
                    unequipall()
                    index, previousCount = index + 1, nil
                else
                    local shop = findexactshoptool(entry.name)
                    if not shop then
                        buildnotify('shop item unavailable: ' .. entry.name)
                        return nil
                    end
                    if not equip_owned(entry) then
                        return nil
                    end
                    if count > 0 then
                        local readyAt = tick() + equipSettle
                        repeat
                            RunService.Heartbeat:Wait()
                            if not equip_owned(entry) then
                                return nil
                            end
                            phowg:maintain_purchase_movement(Data.PurchaseBatch)
                        until tick() >= readyAt
                    end
                    previousCount = count
                    return {
                        Query = getshopiteminfo(shop),
                        Count = 1,
                        Prio = Data.PRIO.LOADOUT,
                        ShouldContinue = function()
                            return equip_owned(entry)
                        end,
                    }
                end
            end
            return nil
        end)
    end)
    if LocalPlayer.Character == character then
        pcall(unequipall)
    end
    Data.BuildActive = nil
    if not ok then
        warn('[Phowg] prop purchase: ' .. tostring(problem))
    end
end
function gripallowned(toolName, grips, character)
    for _, grip in ipairs(grips) do
        if
            Data.IsRespawning
            or Library.Unloaded
            or localactionblocked()
            or character and LocalPlayer.Character ~= character
        then
            break
        end
        equiponewithgrip(toolName, grip)
        task.wait(0.15)
    end
end
