function buildskintable()
    local mods = ReplicatedStorage:FindFirstChild('SkinModules')
    if not mods then
        return Data.SkinTableCache or {}
    end
    local ok, skins = pcall(require, mods)
    local cache = {}
    if ok and type(skins) == 'table' then
        for weapon, entries in pairs(skins) do
            if type(entries) == 'table' then
                cache[weapon] = table.clone(entries)
            end
        end
    else
        for weapon, entries in pairs(Data.SkinTableCache or {}) do
            cache[weapon] = table.clone(entries)
        end
    end
    local knives = mods:FindFirstChild('Knives')
    if knives then
        cache['[Knife]'] = cache['[Knife]'] or {}
        for _, source in ipairs(knives:GetChildren()) do
            if not cache['[Knife]'][source.Name] then
                cache['[Knife]'][source.Name] = {}
            end
        end
    end
    local knifeEntries = cache['[Knife]']
    if knifeEntries and knifeEntries.DualCryptos and typeof(knifeEntries.DualCryptos.CFrame) == 'CFrame' then
        for _, name in ipairs({ 'Bit', 'Mon', 'Ether' }) do
            if knifeEntries[name] and typeof(knifeEntries[name].CFrame) ~= 'CFrame' then
                local entry = table.clone(knifeEntries[name])
                entry.CFrame = knifeEntries.DualCryptos.CFrame
                knifeEntries[name] = entry
            end
        end
    end
    if
        knifeEntries
        and knifeEntries['Golden Age Tanto']
        and typeof(knifeEntries['Golden Age Tanto'].CFrame) == 'CFrame'
    then
        local white = knifeEntries['White Tanto']
        if not white or typeof(white.CFrame) ~= 'CFrame' then
            white = table.clone(white or {})
            white.CFrame = knifeEntries['Golden Age Tanto'].CFrame
            knifeEntries['White Tanto'] = white
        end
    end
    Data.SkinTableCache = cache
    return cache
end
function getskinnamesforweapon(weapon)
    local names, seen = {}, { Default = true, None = true }
    local cache = Data.SkinTableCache
    local entries = cache and cache[weapon]
    local key = phowg:skin_asset_key(weapon)
    if not entries and cache then
        for name, value in pairs(cache) do
            if phowg:skin_asset_key(name) == key then
                entries = value
                break
            end
        end
    end
    local modules = key == 'knife' and ReplicatedStorage:FindFirstChild('SkinModules')
    local knives = modules and modules:FindFirstChild('Knives')
    if knives then
        for _, source in ipairs(knives:GetChildren()) do
            local name = source.Name
            if not seen[name] and (source:IsA('BasePart') or source:IsA('Model')) then
                seen[name] = true
                names[#names + 1] = name
            end
        end
    elseif type(entries) == 'table' then
        for name in pairs(entries) do
            if type(name) == 'string' and name ~= '' and not seen[name] then
                seen[name] = true
                names[#names + 1] = name
            end
        end
    end
    table.sort(names)
    table.insert(names, 1, 'Default')
    return names
end
