function phowg:restore_skin_model(tool)
    local state: { [string]: any }? = Data.SkinModelStates and Data.SkinModelStates[tool]
    if not state then
        return
    end
    Data.SkinModelStates[tool] = nil
    for _, connection in ipairs(state.BindSignals or {}) do
        connection:Disconnect()
    end
    if state.Particle then
        state.Particle:Destroy()
    end
    for particle, enabled in pairs(state.NativeParticles or {}) do
        if particle.Parent then
            particle.Enabled = enabled
        end
    end
    for object, properties in pairs(state.NativeGeometry or {}) do
        if object.Parent then
            if properties.Transparency ~= nil then
                object.Transparency = properties.Transparency
            end
            if properties.Enabled ~= nil then
                object.Enabled = properties.Enabled
            end
        end
    end
    for _, object in ipairs(state.Objects) do
        object:Destroy()
    end
    if state.Base.Parent then
        state.Base.Transparency = state.Transparency
        if state.Texture ~= nil then
            state.Base.TextureID = state.Texture
        end
        for _, object in ipairs(state.Hidden) do
            if not object.Parent then
                object.Parent = state.Base
            end
        end
    else
        for _, object in ipairs(state.Hidden) do
            object:Destroy()
        end
    end
    if state.AssignedKnifeSkin and tool:GetAttribute('CurrentKnifeSkin') == state.AssignedKnifeSkin then
        tool:SetAttribute('CurrentKnifeSkin', state.OriginalKnifeSkin)
    end
end
function phowg:skin_knife_grip(hand, side)
    local attachment = hand:FindFirstChild((side or 'Right') .. 'GripAttachment')
    if attachment and attachment:IsA('Attachment') then
        return attachment.CFrame
    end
    return CFrame.new(0, -0.25, 0) * CFrame.Angles(-math.pi / 2, 0, 0)
end
function phowg:skin_knife_bind_offset(tool, base, hand)
    local links = {}
    local function add(joint)
        if not (joint:IsA('JointInstance') or joint:IsA('WeldConstraint')) then
            return
        end
        local first, second = joint.Part0, joint.Part1
        if not first or not second or first == second then
            return
        end
        if
            (first ~= hand and not first:IsDescendantOf(tool)) or (second ~= hand and not second:IsDescendantOf(tool))
        then
            return
        end
        local relative = joint:IsA('WeldConstraint') and first.CFrame:ToObjectSpace(second.CFrame)
            or joint.C0 * joint.C1:Inverse()
        links[first] = links[first] or {}
        links[second] = links[second] or {}
        links[first][#links[first] + 1] = { Part = second, Offset = relative }
        links[second][#links[second] + 1] = { Part = first, Offset = relative:Inverse() }
    end
    for _, joint in ipairs(hand:GetChildren()) do
        add(joint)
    end
    for _, joint in ipairs(tool:GetDescendants()) do
        add(joint)
    end
    local function find(start, target)
        local offsets, queue = { [start] = CFrame.new() }, { start }
        local index = 1
        while index <= #queue do
            local current = queue[index]
            index = index + 1
            if current == target then
                return offsets[current]
            end
            for _, link in ipairs(links[current] or {}) do
                if not offsets[link.Part] then
                    offsets[link.Part] = offsets[current] * link.Offset
                    queue[#queue + 1] = link.Part
                end
            end
        end
        return nil
    end
    local bind = find(hand, base)
    if bind then
        return bind
    end
    local handle = tool:FindFirstChild('Handle')
    local grip = typeof(tool.Grip) == 'CFrame' and tool.Grip or CFrame.new()
    if handle and handle:IsA('BasePart') then
        local relative = find(handle, base) or handle.CFrame:ToObjectSpace(base.CFrame)
        return phowg:skin_knife_grip(hand) * grip:Inverse() * relative
    end
    return phowg:skin_knife_grip(hand) * grip:Inverse()
end
function phowg:skin_knife_anchor(clone, origin, name)
    local point = clone:FindFirstChild(name, true)
    if not point then
        return nil
    end
    if point:IsA('BasePart') then
        return origin:PointToObjectSpace(point.Position)
    end
    if not point:IsA('Attachment') then
        return nil
    end
    local relative, parent = point.CFrame, point.Parent
    while parent and not parent:IsA('BasePart') do
        if parent:IsA('Attachment') then
            relative = parent.CFrame * relative
        end
        parent = parent.Parent
    end
    return parent and origin:PointToObjectSpace((parent.CFrame * relative).Position) or nil
end
function phowg:skin_knife_placement(state, clone, origin, skinKey, offset)
    if skinKey == 'bubu' or skinKey == 'rgbbubu' then
        local rigRoot = clone:FindFirstChild('RootPart', true)
        local top = clone:FindFirstChild('KeychainTop', true)
        if rigRoot and rigRoot:IsA('BasePart') and top and top:IsA('Attachment') then
            local point = phowg:skin_knife_anchor(clone, origin, 'KeychainTop')
            if point then
                state.GripAnchor, state.AuthoredSkinOffset = point, offset
                state.HangingRootRotation = origin:ToObjectSpace(rigRoot.CFrame).Rotation
            end
        end
        return
    end
    local anchor, rotation
    if skinKey == 'beary' or skinKey == 'bubu' or skinKey == 'rgbbubu' then
        anchor = 'RootPart'
    elseif skinKey == 'cyankarambit' then
        anchor, rotation = 'RingFX', CFrame.Angles(0, 0, math.pi)
    elseif skinKey == 'dog' then
        anchor, rotation = 'circlearea', CFrame.Angles(0, 0, math.pi / 2)
    elseif skinKey == 'winterkarambit' then
        anchor, rotation = 'Hilt', CFrame.new()
    elseif skinKey == 'popsicle' or skinKey == 'popsicle2' then
        anchor, rotation = 'Start1', CFrame.Angles(0, 0, -math.pi / 2)
    elseif skinKey == 'gothic' then
        anchor = 'Controller'
    elseif skinKey == 'dualcryptos' or skinKey == 'bit' or skinKey == 'mon' or skinKey == 'ether' then
        anchor = 'Start1'
    end
    local point = anchor and phowg:skin_knife_anchor(clone, origin, anchor)
    if anchor == 'Start1' and not point and (skinKey == 'dualcryptos' or skinKey == 'ether') then
        local modules = ReplicatedStorage:FindFirstChild('SkinModules')
        local knives = modules and modules:FindFirstChild('Knives')
        local sharedTemplate = knives and knives:FindFirstChild('Bit')
        if
            sharedTemplate
            and sharedTemplate:IsA('MeshPart')
            and clone:IsA('MeshPart')
            and sharedTemplate.MeshId == clone.MeshId
        then
            point = phowg:skin_knife_anchor(sharedTemplate, sharedTemplate.CFrame, anchor)
            if point then
                point = Vector3.new(
                    point.X * clone.Size.X / sharedTemplate.Size.X,
                    point.Y * clone.Size.Y / sharedTemplate.Size.Y,
                    point.Z * clone.Size.Z / sharedTemplate.Size.Z
                )
            end
        end
    end
    if point then
        state.GripAnchor, state.AuthoredSkinOffset, state.HandSkinRotation = point, offset, rotation
    end
end
function phowg:add_crypto_knife_effects(clone, knives)
    local source = knives and knives:FindFirstChild('Bit')
    if not source or not source:IsA('BasePart') or not clone:IsA('BasePart') then
        return
    end
    local effects = source:Clone()
    if not effects then
        return
    end
    effects.Name = 'PhowgCryptoEffects'
    local origin, parts = effects.CFrame, { effects }
    for _, object in ipairs(effects:GetDescendants()) do
        if object:IsA('BasePart') then
            parts[#parts + 1] = object
        elseif
            object:IsA('Script')
            or object:IsA('LocalScript')
            or object:IsA('ModuleScript')
            or object:IsA('Highlight')
            or object:IsA('SurfaceAppearance')
        then
            object:Destroy()
        end
    end
    for _, part in ipairs(parts) do
        part.Transparency = 1
        part.CFrame = clone.CFrame * origin:ToObjectSpace(part.CFrame)
    end
    effects.Parent = clone
end
function phowg:sync_skin_knife_bind(tool, state)
    if not phowg:tool_grip_allowed(tool) then
        for _, connection in ipairs(state.BindSignals or {}) do
            connection:Disconnect()
        end
        state.BindSignals = nil
        return
    end
    if not state.NativeBind then
        return
    end
    local hand = state.RightHand
    local grip = hand:FindFirstChild('RightGrip')
    if grip and not grip:IsA('JointInstance') then
        grip = nil
    end
    local c0, c1 = grip and grip.C0, grip and grip.C1
    local first, second = grip and grip.Part0, grip and grip.Part1
    local handGrip = phowg:skin_knife_grip(hand)
    local leftGrip = state.LeftHand and phowg:skin_knife_grip(state.LeftHand, 'Left')
    if state.NativeGrip ~= grip or not state.BindSignals then
        for _, connection in ipairs(state.BindSignals or {}) do
            connection:Disconnect()
        end
        state.BindSignals = {}
        if grip then
            for _, property in ipairs({ 'C0', 'C1', 'Part0', 'Part1' }) do
                state.BindSignals[#state.BindSignals + 1] = connectshared(
                    grip:GetPropertyChangedSignal(property),
                    function()
                        if
                            Data.SkinModelStates
                            and Data.SkinModelStates[tool] == state
                            and tool.Parent == LocalPlayer.Character
                        then
                            state.BindDirty = true
                            onskintooladded(tool)
                        end
                    end,
                    tool,
                    'knife/native grip'
                )
            end
        end
    end
    if
        not state.HangingRootRotation
        and not state.BindDirty
        and state.BindOffset
        and state.NativeGrip == grip
        and state.NativeGripC0 == c0
        and state.NativeGripC1 == c1
        and state.NativeGripPart0 == first
        and state.NativeGripPart1 == second
        and state.NativeToolGrip == tool.Grip
        and state.BindHandGrip == handGrip
        and state.BindLeftGrip == leftGrip
    then
        return
    end
    state.BindDirty = nil
    state.NativeGrip, state.NativeGripC0, state.NativeGripC1 = grip, c0, c1
    state.NativeGripPart0, state.NativeGripPart1, state.NativeToolGrip = first, second, tool.Grip
    state.BindHandGrip, state.BindLeftGrip = handGrip, leftGrip
    local bind = phowg:skin_knife_bind_offset(tool, state.Base, hand)
    if state.GripAnchor then
        local authored = bind * state.AuthoredSkinOffset
        local rotation = state.HandSkinRotation or authored.Rotation
        if state.HangingRootRotation then
            local root = state.Character:FindFirstChild('HumanoidRootPart')
            if root then
                local look = root.CFrame.LookVector * Vector3.new(1, 0, 1)
                if look.Magnitude > 0.001 then
                    local upright = CFrame.lookAt(Vector3.zero, look.Unit)
                    rotation = hand.CFrame.Rotation:Inverse() * upright * state.HangingRootRotation:Inverse()
                end
            end
        end
        local placement = CFrame.new(handGrip.Position - rotation:VectorToWorldSpace(state.GripAnchor)) * rotation
        state.SkinOffset = bind:Inverse() * placement
    end
    local rightBind = state.RightGripRotation and handGrip * state.RightGripRotation * handGrip:Inverse() * bind or bind
    state.BindOffset, state.Offset = rightBind, rightBind * state.SkinOffset
    for _, weld in ipairs(state.SkinWelds or {}) do
        if weld.Parent then
            weld.C0 = state.SkinOffset
        end
    end
    for _, weld in ipairs(state.LeftSkinWelds or {}) do
        if weld.Parent then
            weld.C0 = state.SkinOffset
        end
    end
    if state.Motor then
        state.Motor.C0 = rightBind
    end
    if state.LeftHand then
        local leftBind = leftGrip * (state.LeftGripRotation or CFrame.new()) * handGrip:Inverse() * bind
        state.LeftBindOffset, state.LeftOffset = leftBind, leftBind * state.SkinOffset
        if state.LeftMotor then
            state.LeftMotor.C0 = leftBind
        end
    end
end
function phowg:set_skin_model_equipped(tool, equipped)
    local state: { [string]: any }? = Data.SkinModelStates and Data.SkinModelStates[tool]
    if not state then
        return
    end
    local character = equipped and LocalPlayer.Character
    if not equipped then
        for _, connection in ipairs(state.BindSignals or {}) do
            connection:Disconnect()
        end
        state.BindSignals = nil
    end
    for _, mount in ipairs(state.Mounts or {}) do
        local motor = mount.Motor
        if motor.Parent then
            motor.Part0 = character
                    and (character:FindFirstChild(mount.Side .. 'Hand') or character:FindFirstChild(
                        mount.Side .. ' Arm'
                    ))
                or nil
            if not equipped then
                motor.Transform = CFrame.new()
            end
        end
    end
end
function applyskintotool(tool, skinName, isKnife)
    if not tool or tool.Parent ~= LocalPlayer.Character then
        return false
    end
    local assets = Data.SkinToolStates and Data.SkinToolStates[tool]
    if
        assets
        and (
            assets.Skin ~= skinName
            or assets.Character ~= LocalPlayer.Character
            or assets.Handle ~= tool:FindFirstChild('Handle')
        )
    then
        phowg:stop_skin_tool(tool, true)
    end
    if not skinName or skinName == '' or skinName == 'None' or skinName == 'Default' then
        phowg:restore_skin_model(tool)
        return true
    end
    local base = tool:FindFirstChild('Default')
    if not base or not base:IsA('BasePart') then
        base = tool:FindFirstChildOfClass('MeshPart')
    end
    if not base then
        return false
    end
    local entries = Data.SkinTableCache and Data.SkinTableCache[tool.Name]
    local info = entries and entries[skinName]
    local profile = isKnife and phowg:knife_skin_profile(skinName) or nil
    local modules = ReplicatedStorage:FindFirstChild('SkinModules')
    local knives = isKnife and modules and modules:FindFirstChild('Knives')
    local source = knives and knives:FindFirstChild(profile and profile.Name or skinName)
    local rig = isKnife
        and Data.SkinAssetCatalog
        and Data.SkinAssetCatalog.KnifeRigs
        and Data.SkinAssetCatalog.KnifeRigs[phowg:skin_asset_key(skinName)]
    local reference = rig and rig.Reference
    if rig and rig.Model and rig.Model.Parent and reference and reference:IsDescendantOf(rig.Model) then
        source = rig.Model
    else
        reference = nil
    end
    local texture = info and (info.TextureID or info.TextureId)
    if not source and typeof(texture) == 'Instance' then
        source = texture
    end
    if not source and not info then
        phowg:restore_skin_model(tool)
        return false
    end
    Data.SkinModelStates = Data.SkinModelStates or setmetatable({}, { __mode = 'k' })
    local skinKey = phowg:skin_asset_key(skinName)
    local dual = isKnife and (skinKey == 'dualbayonets' or skinKey == 'rgbdualbayonets' or skinKey == 'dualcryptos')
    local hand = isKnife
        and (LocalPlayer.Character:FindFirstChild('RightHand') or LocalPlayer.Character:FindFirstChild('Right Arm'))
    local leftHand = dual
        and (LocalPlayer.Character:FindFirstChild('LeftHand') or LocalPlayer.Character:FindFirstChild('Left Arm'))
    local state: { [string]: any }? = Data.SkinModelStates[tool]
    if
        state
        and state.Character == LocalPlayer.Character
        and state.Base == base
        and state.Skin == skinName
        and state.Source == source
        and state.Info == info
        and state.Profile == profile
        and state.MetadataOffset == (info and info.CFrame)
        and state.Reference == reference
        and state.RightHand == hand
        and state.LeftHand == leftHand
    then
        phowg:sync_skin_knife_bind(tool, state)
        phowg:set_skin_model_equipped(tool, true)
        return true
    end
    if assets then
        phowg:stop_skin_tool(tool, true)
    else
        phowg:restore_skin_model(tool)
    end
    local clone
    if source then
        if not (source:IsA('BasePart') or source:IsA('Model')) then
            return false
        end
        clone = source:Clone()
        if not clone then
            return false
        end
    elseif info.MeshId and info.Scale then
        clone = Instance.new('Part')
        clone.Color, clone.Material =
            info.Color or Color3.fromRGB(255, 255, 255), info.Material or Enum.Material.Plastic
        local mesh = Instance.new('SpecialMesh')
        mesh.MeshId, mesh.Scale, mesh.TextureId = info.MeshId, info.Scale, info.TextureId or texture or ''
        mesh.Parent = clone
    elseif type(texture) ~= 'string' or not base:IsA('MeshPart') then
        return false
    end
    state = {
        Character = LocalPlayer.Character,
        Base = base,
        Skin = skinName,
        Source = source,
        Info = info,
        Profile = profile,
        Reference = reference,
        MetadataOffset = info and info.CFrame,
        RightHand = hand,
        LeftHand = leftHand,
        Objects = {},
        Hidden = {},
        NativeParticles = {},
        Transparency = base.Transparency,
        Texture = base:IsA('MeshPart') and base.TextureID or nil,
        OriginalKnifeSkin = tool:GetAttribute('CurrentKnifeSkin'),
    }
    if skinKey == 'dualbayonets' or skinKey == 'rgbdualbayonets' or skinKey == 'dualcryptos' then
        state.LeftGripRotation = CFrame.Angles(0, 0, math.pi)
    end
    if skinKey == 'dualbayonets' or skinKey == 'rgbdualbayonets' then
        state.RightGripRotation = CFrame.Angles(0, 0, math.pi)
    end
    Data.SkinModelStates[tool] = state
    if not clone then
        base.TextureID, base.Transparency = texture, 0
        return true
    end
    if not isKnife then
        state.NativeGeometry = {}
        for _, object in ipairs(base:GetDescendants()) do
            if object:IsA('BasePart') then
                state.NativeGeometry[object] = { Transparency = object.Transparency }
                object.Transparency = 1
            elseif object:IsA('ParticleEmitter') or object:IsA('Beam') or object:IsA('Trail') then
                state.NativeGeometry[object] = { Enabled = object.Enabled }
                object.Enabled = false
            end
        end
    end
    local parts = {}
    if skinKey == 'dualcryptos' then
        phowg:add_crypto_knife_effects(clone, knives)
    end
    if clone:IsA('BasePart') then
        parts[#parts + 1] = clone
    end
    for _, object in ipairs(clone:GetDescendants()) do
        if object:IsA('BasePart') then
            parts[#parts + 1] = object
        elseif object:IsA('Script') or object:IsA('LocalScript') then
            object:Destroy()
        end
    end
    local root = clone:IsA('Model') and clone.PrimaryPart or parts[1]
    if not root then
        clone:Destroy()
        phowg:restore_skin_model(tool)
        return false
    end
    if clone:IsA('Model') and not clone.PrimaryPart then
        clone.PrimaryPart = root
    end
    local origin = root.CFrame
    if reference then
        for _, part in ipairs(parts) do
            if part.Name == reference.Name and part:IsA('MeshPart') and part.MeshId == reference.MeshId then
                origin = part.CFrame
                break
            end
        end
    end
    if skinKey == 'beary' or skinKey == 'bubu' or skinKey == 'rgbbubu' then
        local rigRoot = clone:FindFirstChild('RootPart', true)
        if rigRoot and rigRoot:IsA('BasePart') then
            root = rigRoot
        end
    end
    if source and phowg.queue_asset_tree then
        phowg:queue_asset_tree(source)
    end
    local moduleOffset = info and typeof(info.CFrame) == 'CFrame' and info.CFrame
    if isKnife and skinName == 'White Tanto' and not moduleOffset then
        local golden = entries and entries['Golden Age Tanto']
        moduleOffset = golden and typeof(golden.CFrame) == 'CFrame' and golden.CFrame
    end
    if isKnife and (not hand or not hand:IsA('BasePart')) then
        clone:Destroy()
        phowg:restore_skin_model(tool)
        return false
    end
    local offset = moduleOffset or CFrame.new()
    local leftClone = leftHand and leftHand:IsA('BasePart') and clone:Clone() or nil
    if isKnife then
        local marker = clone:FindFirstChild('Handle.R', true)
        local karambit = skinKey == 'rgbkarambit' and phowg:knife_skin_profile('Heaven')
        if karambit and source:IsA('MeshPart') then
            local heaven = knives and knives:FindFirstChild('Heaven')
            if heaven and heaven:IsA('MeshPart') and heaven.MeshId == source.MeshId then
                offset = karambit.Offset
            else
                state.NativeBind, state.SkinOffset = true, offset
                phowg:sync_skin_knife_bind(tool, state)
            end
        elseif profile then
            offset = profile.Offset
        elseif marker and marker:IsA('BasePart') then
            offset = marker.CFrame:ToObjectSpace(origin)
        elseif skinKey == 'mochi' and clone:FindFirstChild('MochiKnife') then
            offset = phowg:skin_knife_grip(hand)
        else
            state.NativeBind, state.SkinOffset = true, offset
            phowg:skin_knife_placement(state, clone, origin, skinKey, offset)
            local gripName = skinKey == 'cyankarambit' and 'RingFX' or skinKey == 'winterkarambit' and 'Hilt'
            local gripPoint = gripName and clone:FindFirstChild(gripName)
            if not state.GripAnchor and gripPoint and gripPoint:IsA('Attachment') then
                state.GripAnchor, state.AuthoredSkinOffset = gripPoint.Position, offset
            end
            phowg:sync_skin_knife_bind(tool, state)
            offset = state.SkinOffset
        end
    end
    local anchor = base
    local handMounted = isKnife
    local function mount_hand(side, limb, bind)
        bind = bind or CFrame.new()
        local part = Instance.new('Part')
        part.Name, part.Transparency, part.Size = 'Handle.' .. side:sub(1, 1), 1, Vector3.new(0.001, 0.001, 0.001)
        part.CanCollide, part.CanTouch, part.CanQuery, part.Massless, part.Anchored = false, false, false, true, false
        part.CFrame, part.Parent = limb.CFrame * bind, base
        local motor = Instance.new('Motor6D')
        motor.Name, motor.Part0, motor.Part1, motor.C0, motor.C1, motor.Parent =
            part.Name, limb, part, bind, CFrame.new(), part
        state.Mounts = state.Mounts or {}
        state.Mounts[#state.Mounts + 1] = { Motor = motor, Side = side }
        state.Objects[#state.Objects + 1] = part
        return part, motor
    end
    if isKnife then
        for _, object in ipairs(base:GetChildren()) do
            if object.Name == 'Handle.R' or object:IsA('Model') or object:IsA('BasePart') then
                state.Hidden[#state.Hidden + 1] = object
                object.Parent = nil
            end
        end
        anchor, state.Motor = mount_hand('Right', hand, state.BindOffset)
        state.AssignedKnifeSkin = profile and profile.Name or skinName
        tool:SetAttribute('CurrentKnifeSkin', state.AssignedKnifeSkin)
    end
    clone.Name = isKnife and (profile and profile.Name or skinName) or 'CurrentSkin'
    if profile and profile.Texture and clone:IsA('MeshPart') then
        clone.TextureID = profile.Texture
    end
    local function mount_assembly(model, modelRoot, modelOrigin, mount, mountOffset, modelParts)
        local components, relatives = {}, {}
        for _, part in ipairs(modelParts) do
            components[part] = part
            relatives[part] = modelOrigin:ToObjectSpace(part.CFrame)
        end
        local function component(part)
            local result = part
            while components[result] ~= result do
                result = components[result]
            end
            while components[part] ~= result do
                local nextPart = components[part]
                components[part] = result
                part = nextPart
            end
            return result
        end
        for _, joint in ipairs(model:GetDescendants()) do
            if joint:IsA('JointInstance') or joint:IsA('WeldConstraint') then
                local first, second = joint.Part0, joint.Part1
                if components[first] and components[second] then
                    local a, b = component(first), component(second)
                    if a ~= b then
                        components[b] = a
                    end
                else
                    joint:Destroy()
                end
            end
        end
        local attached, ordered = {}, { modelRoot }
        for _, part in ipairs(modelParts) do
            if part ~= modelRoot then
                ordered[#ordered + 1] = part
            end
        end
        for _, part in ipairs(ordered) do
            part.CanCollide, part.CanTouch, part.CanQuery, part.Massless, part.Anchored =
                false, false, false, true, false
            part.CFrame = mount.CFrame * mountOffset * relatives[part]
        end
        for _, part in ipairs(ordered) do
            local relative = relatives[part]
            local group = component(part)
            if not attached[group] then
                attached[group] = true
                local weld = Instance.new('Weld')
                if handMounted then
                    weld.Part0, weld.Part1, weld.C0, weld.C1 = mount, part, mountOffset, relative:Inverse()
                    if state.NativeBind then
                        local key = mount == anchor and 'SkinWelds' or 'LeftSkinWelds'
                        state[key] = state[key] or {}
                        state[key][#state[key] + 1] = weld
                    end
                else
                    weld.Part0, weld.Part1, weld.C0 = part, mount, (mountOffset * relative):Inverse()
                end
                weld.Parent = part
            end
        end
    end
    if leftClone then
        local leftParts = {}
        if leftClone:IsA('BasePart') then
            leftParts[#leftParts + 1] = leftClone
        end
        for _, part in ipairs(leftClone:GetDescendants()) do
            if part:IsA('BasePart') then
                leftParts[#leftParts + 1] = part
            end
        end
        local leftRoot = leftClone:IsA('Model') and leftClone.PrimaryPart or leftParts[1]
        if leftRoot then
            local leftAnchor
            leftAnchor, state.LeftMotor = mount_hand('Left', leftHand, state.LeftBindOffset)
            local leftOffset = state.NativeBind and offset
                or phowg:skin_knife_grip(leftHand, 'Left')
                    * (state.LeftGripRotation or CFrame.new())
                    * phowg:skin_knife_grip(hand):Inverse()
                    * offset
            mount_assembly(leftClone, leftRoot, leftRoot.CFrame, leftAnchor, leftOffset, leftParts)
            leftClone.Name, leftClone.Parent = 'LeftKnifeSkin', base
            state.LeftClone, state.LeftRoot, state.LeftOffset =
                leftClone, leftRoot, (state.LeftBindOffset or CFrame.new()) * leftOffset
            state.Objects[#state.Objects + 1] = leftClone
        else
            leftClone:Destroy()
        end
    end
    mount_assembly(clone, root, origin, anchor, offset, parts)
    clone.Parent = isKnife and base or tool
    state.Objects[#state.Objects + 1] = clone
    state.Clone, state.Root, state.Offset = clone, root, (state.BindOffset or CFrame.new()) * offset
    base.Transparency = 1
    return true
end
phowg:register_render(function()
    for tool, state in pairs(Data.SkinModelStates or {}) do
        if
            state.HangingRootRotation
            and tool.Parent == LocalPlayer.Character
            and state.Character == LocalPlayer.Character
            and state.Motor
            and state.Motor.Parent
        then
            phowg:sync_skin_knife_bind(tool, state)
        end
    end
end, RunService, 'frame/hanging knife placement')
function phowg:apply_skin_model_particles(tool)
    local state: { [string]: any }? = Data.SkinModelStates and Data.SkinModelStates[tool]
    if not state or state.Character ~= LocalPlayer.Character or tool.Parent ~= state.Character then
        return
    end
    local catalog = Data.SkinAssetCatalog
    local source = catalog and catalog.Particles[phowg:skin_asset_key(state.Skin)]
    local target = tool.Name == '[Knife]' and state.Profile and state.Profile.Particle and state.Root
        or tool.Name ~= '[Knife]' and tool:FindFirstChild('Handle')
        or nil
    if state.Particle and (state.ParticleSource ~= source or state.Particle.Parent ~= target) then
        state.Particle:Destroy()
        state.Particle = nil
    end
    if not source or not target then
        for particle, enabled in pairs(state.NativeParticles) do
            if particle.Parent then
                particle.Enabled = enabled
            end
        end
        table.clear(state.NativeParticles)
        return
    end
    if not state.Particle then
        if target.Name == 'Handle' then
            for _, particle in ipairs(target:GetChildren()) do
                if particle:IsA('ParticleEmitter') then
                    if state.NativeParticles[particle] == nil then
                        state.NativeParticles[particle] = particle.Enabled
                    end
                    particle.Enabled = false
                end
            end
        end
        state.Particle = source:Clone()
        state.Particle.Name, state.Particle.Parent = 'PhowgSkinParticle', target
        state.ParticleSource = source
    end
end
function phowg:skin_asset_key(name)
    return type(name) == 'string' and name:lower():gsub('[^%w]', '') or ''
end
function phowg:skin_pullout_rank(asset, root)
    if not asset:IsA('Animation') then
        return 0
    end
    local current, rank = asset, 0
    while current and current ~= root do
        local name = phowg:skin_asset_key(current.Name)
        if
            name:find('attack', 1, true)
            or name:find('slash', 1, true)
            or name:find('swing', 1, true)
            or name:find('stab', 1, true)
            or name:find('unequip', 1, true)
            or name:find('holster', 1, true)
        then
            return 0
        end
        if
            name == 'knifeequip'
            or name == 'equip'
            or name == 'knifepullout'
            or name == 'pullout'
            or name == 'knifedraw'
            or name == 'draw'
        then
            rank = math.max(rank, 4)
        elseif name:find('equip', 1, true) or name:find('pullout', 1, true) then
            rank = math.max(rank, 2)
        end
        current = current.Parent
    end
    return rank
end
function phowg:register_skin_knife_animations(catalog, storage)
    local aliases = {
        ['RGB Butterfly'] = 'Soul',
        ['Ruby Fan'] = 'Ruby',
        ['Penguin Ice Cream'] = 'Penguin',
        ['Banana'] = 'Barbie',
        ['Ice Sword'] = 'IceSword',
        ['RGB Dual Bayonets'] = 'DualBayonets',
        ['RGB Karambit'] = 'Heaven',
        ['Popsicle2'] = 'Popsicle',
        ['Emerald-Bayonet'] = 'Emerald',
        ['Boy'] = 'Match',
        ['Girl'] = 'Match',
        ['Bit'] = 'DualCryptos',
        ['Mon'] = 'DualCryptos',
        ['Ether'] = 'DualCryptos',
        ['Blue Dagger'] = 'Daggers',
        ['Red Dagger'] = 'Daggers',
        ['Purple Dagger'] = 'Daggers',
        ['Green Dagger'] = 'Daggers',
    }
    local modelNames = {
        ['Banana'] = 'BananaKnife',
        ['Soul'] = 'SoulKnife',
        ['RGB Butterfly'] = 'SoulKnifeRGB',
        ['Emerald Butterfly'] = 'Emerald Butterfly',
        ['Crystal Karambit'] = 'CrystalKarambitRIG',
        ['Gothic'] = 'CrowRig',
    }
    local folders = {}
    for _, source in ipairs(storage:GetChildren()) do
        folders[phowg:skin_asset_key(source.Name)] = source
    end
    local candidates = {}
    local modules = ReplicatedStorage:FindFirstChild('SkinModules')
    local knives = modules and modules:FindFirstChild('Knives')
    if knives then
        for _, skin in ipairs(knives:GetChildren()) do
            candidates[skin.Name] = aliases[skin.Name] or skin.Name
        end
    end
    for skin, folder in pairs(aliases) do
        candidates[skin] = folder
    end
    local candidateKeys = {}
    for skin in pairs(candidates) do
        candidateKeys[phowg:skin_asset_key(skin)] = true
    end
    for _, source in ipairs(storage:GetChildren()) do
        local key = phowg:skin_asset_key(source.Name)
        if not candidateKeys[key] then
            candidates[source.Name] = source.Name
            candidateKeys[key] = true
        end
    end
    for skin, folderName in pairs(candidates) do
        local folder = folders[phowg:skin_asset_key(skin)] or folders[phowg:skin_asset_key(folderName)]
        if folder then
            local scope = folder:FindFirstChild('knife')
            if not scope or not (scope:IsA('Folder') or scope:IsA('Model')) then
                scope = folder
            end
            local animations = {}
            for _, source in ipairs(scope:GetDescendants()) do
                if source:IsA('Animation') then
                    local parent, blocked = source.Parent, false
                    while parent and parent ~= scope do
                        local name = phowg:skin_asset_key(parent.Name)
                        if
                            name:find('attack', 1, true)
                            or name:find('slash', 1, true)
                            or name:find('swing', 1, true)
                            or name:find('unequip', 1, true)
                        then
                            blocked = true
                            break
                        end
                        parent = parent.Parent
                    end
                    local key = phowg:skin_asset_key(source.Name)
                    if not blocked and not animations[key] then
                        animations[key] = source
                    end
                end
            end
            local function pick(names)
                for _, name in ipairs(names) do
                    if animations[name] then
                        return animations[name]
                    end
                end
                return nil
            end
            local character = pick({ 'charknife', 'knifechar', 'knifecharacteranim', 'drawr15', 'draw15', 'char' })
            local mesh = character
                and pick({ 'knifemesh', 'knifeequip', 'drawknife', 'knifedraw', 'knifeanimation', 'knife' })
            if not character then
                character = pick({
                    'knifeequip',
                    'runicequip',
                    'knifeanimation',
                    'knifeanim',
                    'knife',
                    'equip',
                    'karambit1',
                    'pixelsword',
                    'voidknife',
                    'raygunknife',
                    'scythe',
                    'ethknife',
                    'draw',
                })
                if character then
                    mesh = pick({
                        'knifemesh',
                        'knifereptile',
                        'ethknife',
                        'fananim',
                        'kniferiganimation',
                        'knifeanimation',
                    })
                end
                if mesh == character then
                    mesh = nil
                end
            end
            local key = phowg:skin_asset_key(skin)
            if key == 'rubyfan' or phowg:skin_asset_key(folderName) == 'ruby' then
                character, mesh = animations.knifeanim, animations.fananim
            end
            if key == 'rgbdualbayonets' and animations.rgbknifeequip then
                character = animations.rgbknifeequip
            end
            if phowg:skin_asset_key(folderName) == 'dualcryptos' then
                character = pick({ 'knifeequip1', 'knifeequip2', 'knifeequip3' }) or character
            end
            if key == 'rgbkarambit' and animations.rgb then
                character = animations.rgb
            end
            if key == 'boy' then
                character = animations.boy
            elseif key == 'girl' then
                character = animations.girl
            end
            local dagger = key:match('^(%a+)dagger$')
            if dagger and phowg:skin_asset_key(folderName) == 'daggers' then
                character = animations[dagger]
            end
            if not character and (knives and knives:FindFirstChild(skin)) then
                character = animations.animation
            end
            if key == 'gothic' then
                character, mesh = nil, nil
                catalog.Animations[key] = nil
            end
            if character then
                if not catalog.Animations[key] then
                    catalog.AnimationNames[#catalog.AnimationNames + 1] = skin
                end
                catalog.Animations[key] = character
            end
            local attack = pick({ 'slash', 'slash1', 'swing1' })
            if key == 'gothic' then
                character, attack = nil, nil
            end
            if attack and not catalog.Attacks[key] then
                catalog.Attacks[key] = attack
            end
            local model = modelNames[skin] and folder:FindFirstChild(modelNames[skin])
            local template = knives and knives:FindFirstChild(skin)
            local reference, matches, controller = nil, 0, nil
            if model and model:IsA('Model') and template and template:IsA('MeshPart') and template.MeshId ~= '' then
                for _, object in ipairs(model:GetDescendants()) do
                    if object:IsA('AnimationController') then
                        controller = object
                    end
                    if object:IsA('MeshPart') and object.MeshId == template.MeshId then
                        reference = object
                        matches = matches + 1
                    end
                end
            end
            if not controller or matches ~= 1 then
                model, reference = nil, nil
            end
            if
                mesh
                or model
                or animations.knifeidle
                or animations.knifemeshidle
                or animations.knifeloop
                or animations.spideridle
                or animations.spiderslash
            then
                catalog.KnifeRigs[key] = {
                    Equip = mesh,
                    Idle = key == 'gothic' and animations.idle
                        or pick({ 'knifeidle', 'knifemeshidle', 'knifeloop', 'spideridle' }),
                    Attack = key == 'gothic' and animations.slash or animations.spiderslash,
                    Model = model,
                    Reference = reference,
                }
            end
        end
    end
end
function phowg:build_skin_asset_catalog()
    local catalog = {
        Effects = {},
        Animations = {},
        AnimationNames = {},
        Attacks = {},
        KnifeRigs = {},
        Beams = {},
        ShootSounds = {},
        Particles = {},
    }
    local pulloutRanks = {}
    local function register_pullout(source, asset)
        local rank = phowg:skin_pullout_rank(asset, source)
        if rank == 0 then
            return
        end
        local key = phowg:skin_asset_key(source.Name)
        if key == '' or rank <= (pulloutRanks[key] or 0) then
            return
        end
        if not catalog.Animations[key] then
            catalog.AnimationNames[#catalog.AnimationNames + 1] = source.Name
        end
        catalog.Animations[key], pulloutRanks[key] = asset, rank
    end
    local assets = ReplicatedStorage:FindFirstChild('SkinAssets')
    local scripts = assets and assets:FindFirstChild('SkinScripts')
    if scripts then
        for _, source in ipairs(scripts:GetChildren()) do
            local entry: { [string]: any } = { Source = source }
            for _, asset in ipairs(source:GetDescendants()) do
                if asset:IsA('Sound') then
                    local key = phowg:skin_asset_key(asset.Name)
                    if
                        key == 'equipsfx'
                        or (not entry.EquipSound and (key:find('equip', 1, true) or key:find('pullout', 1, true)))
                    then
                        entry.EquipSound = asset
                    elseif
                        key == 'attacksfx'
                        or (
                            not entry.AttackSound
                            and (
                                key:find('attack', 1, true)
                                or key:find('slash', 1, true)
                                or key:find('swing', 1, true)
                            )
                        )
                    then
                        entry.AttackSound = asset
                    end
                elseif asset:IsA('Animation') then
                    register_pullout(source, asset)
                end
            end
            catalog.Effects[phowg:skin_asset_key(source.Name)] = entry
        end
    end
    local storage = assets and assets:FindFirstChild('SkinScriptsStorage')
    if storage then
        phowg:register_skin_knife_animations(catalog, storage)
    end
    local beams = assets and assets:FindFirstChild('GunBeam')
    if beams then
        for _, source in ipairs(beams:GetChildren()) do
            local beam = source:FindFirstChild('GunBeam')
            if beam and (beam:IsA('Beam') or beam:IsA('BasePart')) then
                catalog.Beams[phowg:skin_asset_key(source.Name)] = source
            end
        end
    end
    local shootSounds = assets and assets:FindFirstChild('GunShootSounds')
    if shootSounds then
        for _, gun in ipairs(shootSounds:GetChildren()) do
            local sounds = {}
            for _, source in ipairs(gun:GetChildren()) do
                if source:IsA('StringValue') then
                    local key = phowg:skin_asset_key(source.Name)
                    if not sounds[key] then
                        sounds[key] = source
                    end
                end
            end
            catalog.ShootSounds[phowg:skin_asset_key(gun.Name)] = sounds
        end
    end
    local attacks = assets and assets:FindFirstChild('KnifeSkinAnimation')
    if attacks then
        for _, animation in ipairs(attacks:GetChildren()) do
            if animation:IsA('Animation') then
                catalog.Attacks[phowg:skin_asset_key(animation.Name)] = animation
            end
        end
    end
    local particles = assets and assets:FindFirstChild('GunHandleParticle')
    if particles then
        for _, source in ipairs(particles:GetChildren()) do
            local particle = source:FindFirstChildOfClass('ParticleEmitter')
            if particle then
                catalog.Particles[phowg:skin_asset_key(source.Name)] = particle
            end
        end
    end
    table.sort(catalog.AnimationNames)
    local preload = {}
    for _, animation in pairs(catalog.Animations) do
        preload[#preload + 1] = animation.AnimationId
    end
    for _, animation in pairs(catalog.Attacks) do
        preload[#preload + 1] = animation.AnimationId
    end
    for _, rig in pairs(catalog.KnifeRigs) do
        for _, role in ipairs({ 'Equip', 'Idle', 'Attack' }) do
            if rig[role] then
                preload[#preload + 1] = rig[role].AnimationId
            end
        end
    end
    phowg:queue_assets(preload)
    Data.SkinAssetCatalog = catalog
    return catalog
end
function phowg:skin_pullout_values()
    local catalog = Data.SkinAssetCatalog or phowg:build_skin_asset_catalog()
    local values, seen = { 'None', 'Skin' }, { none = true, skin = true }
    for _, name in ipairs(catalog.AnimationNames) do
        local key = phowg:skin_asset_key(name)
        if not seen[key] then
            seen[key] = true
            values[#values + 1] = name
        end
    end
    local extra = { 'Soul', 'Mystical' }
    for name, profile in pairs(Data.SkinKnifeProfiles or {}) do
        if profile.Animation and profile.Animation ~= '' then
            extra[#extra + 1] = name
        end
    end
    table.sort(extra)
    for _, name in ipairs(extra) do
        local key = phowg:skin_asset_key(name)
        if not seen[key] then
            seen[key] = true
            values[#values + 1] = name
        end
    end
    return values
end
function phowg:stop_skin_rig(state, release, role)
    for name, entry in pairs(state.RigTracks or {}) do
        if not role or role == name then
            pcall(function()
                entry.Track:Stop(0)
            end)
            if release then
                pcall(function()
                    entry.Track:Destroy()
                end)
                entry.Animation:Destroy()
                state.RigTracks[name] = nil
            end
        end
    end
end
function phowg:play_skin_rig(tool, state, role, source)
    local model = Data.SkinModelStates and Data.SkinModelStates[tool]
    local root = model and model.Clone
    if not root or tool.Parent ~= state.Character then
        return
    end
    if state.RigRoot ~= root or state.RigAnimator and not state.RigAnimator.Parent then
        phowg:stop_skin_rig(state, true)
        state.RigRoot, state.RigAnimator = root, nil
        for _, object in ipairs(root:GetDescendants()) do
            if object:IsA('AnimationController') then
                state.RigAnimator = object:FindFirstChildOfClass('Animator')
                if not state.RigAnimator then
                    state.RigAnimator = Instance.new('Animator')
                    state.RigAnimator.Parent = object
                end
                break
            end
        end
    end
    local animator = state.RigAnimator
    local id = source and source.Parent and source.AnimationId
    state.RigTracks = state.RigTracks or {}
    local entry = state.RigTracks[role]
    if entry and (entry.Id ~= id or entry.Animator ~= animator) then
        phowg:stop_skin_rig(state, true, role)
        entry = nil
    end
    if not animator or type(id) ~= 'string' or id == '' then
        return
    end
    if not entry then
        local animation = Instance.new('Animation')
        animation.AnimationId = id
        phowg:queue_assets({ id })
        local ok, track = pcall(function()
            return animator:LoadAnimation(animation)
        end)
        if not ok or not track then
            animation:Destroy()
            return
        end
        track.Looped, track.Priority =
            role == 'Idle', role == 'Idle' and Enum.AnimationPriority.Action or Enum.AnimationPriority.Action2
        entry = { Track = track, Animation = animation, Animator = animator, Id = id }
        state.RigTracks[role] = entry
    end
    entry.Track:Stop(0)
    entry.Track:Play(
        0,
        1,
        phowg:visual_number(role == 'Attack' and 'skin_attack_speed' or 'skin_pullout_speed', 1, 0.1, 3)
    )
end
function phowg:set_skin_attack_override(tool, state, enabled)
    if enabled then
        if not state.OwnsIgnoreAnimation then
            state.OriginalIgnoreAnimation = tool:GetAttribute('IgnoreAnimation')
            state.OwnsIgnoreAnimation = true
        end
        tool:SetAttribute('IgnoreAnimation', true)
    elseif state.OwnsIgnoreAnimation then
        if tool:GetAttribute('IgnoreAnimation') == true then
            tool:SetAttribute('IgnoreAnimation', state.OriginalIgnoreAnimation)
        end
        state.OwnsIgnoreAnimation = nil
    end
end
function phowg:stop_skin_tool(tool, release)
    local state = Data.SkinToolStates and Data.SkinToolStates[tool]
    if not state then
        if release then
            phowg:restore_skin_model(tool)
        else
            phowg:set_skin_model_equipped(tool, false)
        end
        return
    end
    phowg:set_skin_model_equipped(tool, false)
    state.AttributeAttackPlayed = nil
    if release then
        phowg:stop_skin_rig(state, true)
    else
        phowg:stop_skin_rig(state, false, 'Idle')
        phowg:stop_skin_rig(state, false, 'Attack')
    end
    if release then
        phowg:set_skin_attack_override(tool, state, false)
    end
    if release and state.Track then
        pcall(function()
            state.Track:Stop(0)
        end)
    end
    for _, sound in pairs(state.Sounds) do
        if sound.Parent then
            sound:Stop()
        end
    end
    if state.AttackTrack then
        pcall(function()
            state.AttackTrack:Stop(0)
        end)
    end
    if state.AttackBlockConnection then
        state.AttackBlockConnection:Disconnect()
        state.AttackBlockConnection = nil
    end
    state.AttackBlockAnimator = nil
    if not release then
        return
    end
    if state.Track then
        pcall(function()
            state.Track:Destroy()
        end)
    end
    if state.Animation then
        state.Animation:Destroy()
    end
    if state.AttackTrack then
        pcall(function()
            state.AttackTrack:Destroy()
        end)
    end
    if state.AttackAnimation then
        state.AttackAnimation:Destroy()
    end
    for _, sound in pairs(state.Sounds) do
        sound:Destroy()
    end
    local handle = state.Handle
    if handle and handle.Parent and handle:GetAttribute('SkinName') == state.AssignedSkinName then
        handle:SetAttribute('SkinName', state.OriginalSkinName)
    end
    Data.SkinToolStates[tool] = nil
    if Data.SkinToolPending then
        Data.SkinToolPending[tool] = nil
    end
    phowg:stop_tool_shoot_sounds(tool)
    phowg:restore_tool_sounds(tool)
    phowg:restore_skin_model(tool)
    hooktoolshootsound(tool)
end
function phowg:clear_skin_tools(scope)
    for tool, state in pairs(table.clone(Data.SkinToolStates or {})) do
        if not scope or tool == scope or state.Character == scope or tool:IsDescendantOf(scope) then
            phowg:stop_skin_tool(tool, true)
        end
    end
    for tool, state in pairs(table.clone(Data.SkinModelStates or {})) do
        if not scope or tool == scope or state.Character == scope or tool:IsDescendantOf(scope) then
            phowg:restore_skin_model(tool)
        end
    end
end
function phowg:skin_sound(state, role, source, fallback)
    local id = source and source.SoundId or fallback and fallback.Sound
    local sound = state.Sounds[role]
    if type(id) ~= 'string' or id == '' then
        if sound then
            sound:Destroy()
            state.Sounds[role] = nil
        end
        state.Sources[role] = nil
        return nil
    end
    if not sound or not sound.Parent or state.Sources[role] ~= source then
        if sound then
            sound:Destroy()
        end
        sound = source and source:Clone() or Instance.new('Sound')
        sound:Stop()
        sound.Name = 'PhowgSkin' .. role
        sound.PlayOnRemove = false
        sound.Looped = false
        sound.Parent = state.Handle
        state.Sounds[role], state.Sources[role] = sound, source
    end
    sound.SoundId = id
    state.SoundVolumes = state.SoundVolumes or {}
    state.SoundVolumes[role] = source and source.Volume or fallback and fallback.Volume or 1
    sound.Volume = state.SoundVolumes[role]
    sound.PlaybackSpeed = source and source.PlaybackSpeed or 1
    return sound
end
function phowg:play_skin_sound(state, role)
    local toggle = role == 'Equip' and Toggles.skin_equip_sounds or Toggles.skin_attack_sounds
    if toggle and not toggle.Value then
        return
    end
    local sound = state.Sounds[role]
    if not sound or not sound.Parent then
        return
    end
    local source = state.Sources[role]
    if source and source.Parent then
        sound.SoundId, sound.Volume, sound.PlaybackSpeed = source.SoundId, source.Volume, source.PlaybackSpeed
    end
    local volume = source and source.Parent and source.Volume
        or state.SoundVolumes and state.SoundVolumes[role]
        or sound.Volume
    sound.Volume = volume * phowg:visual_number('skin_action_volume', 1, 0, 3)
    sound.TimePosition = 0
    sound:Play()
end
function phowg:refresh_skin_audio()
    for tool, state in pairs(Data.SkinToolStates or {}) do
        if state.Character == LocalPlayer.Character then
            phowg:stop_tool_shoot_sounds(tool)
            hooktoolshootsound(tool)
            for role, sound in pairs(state.Sounds) do
                local toggle = role == 'Equip' and Toggles.skin_equip_sounds or Toggles.skin_attack_sounds
                if toggle and not toggle.Value then
                    sound:Stop()
                end
                local source = state.Sources[role]
                local volume = source and source.Parent and source.Volume
                    or state.SoundVolumes and state.SoundVolumes[role]
                    or 1
                sound.Volume = volume * phowg:visual_number('skin_action_volume', 1, 0, 3)
            end
        end
    end
end
function phowg:play_skin_pullout(tool, state)
    if state.AttackTrack then
        state.AttackTrack:Stop(0)
    end
    phowg:stop_skin_rig(state, false)
    local selection = Options.skin_pullout_animation and Options.skin_pullout_animation.Value or 'None'
    local catalog = Data.SkinAssetCatalog or phowg:build_skin_asset_catalog()
    local key = phowg:skin_asset_key(selection == 'Skin' and state.Skin or selection)
    local source = catalog.Animations[key]
    local name = selection == 'Skin' and state.Skin or selection
    local profile = phowg:knife_skin_profile(name)
    local detail = Data.SkinPullouts and Data.SkinPullouts[name]
    local id = profile and profile.Animation
    if type(id) ~= 'string' or id == '' then
        id = source and source.Parent and source.AnimationId
    end
    if type(id) ~= 'string' or id == '' then
        id = detail and detail.Animation
    end
    if selection == 'None' then
        id = nil
    end
    if
        selection ~= 'None' and (selection == 'Skin' or phowg:skin_asset_key(selection) == phowg:skin_asset_key(state.Skin))
    then
        local rig = catalog.KnifeRigs and catalog.KnifeRigs[phowg:skin_asset_key(state.Skin)]
        if rig then
            phowg:play_skin_rig(tool, state, 'Idle', rig.Idle)
            phowg:play_skin_rig(tool, state, 'Equip', rig.Equip)
        end
    end
    local humanoid = state.Character:FindFirstChildOfClass('Humanoid')
    local animator = humanoid and (humanoid:FindFirstChildOfClass('Animator') or humanoid)
    if state.Track and (state.AnimationId ~= id or state.Animator ~= animator) then
        pcall(function()
            state.Track:Stop(0)
            state.Track:Destroy()
        end)
        if state.Animation then
            state.Animation:Destroy()
        end
        state.Track, state.Animation, state.AnimationId, state.Animator = nil, nil, nil, nil
    end
    if type(id) ~= 'string' or id == '' or not animator or tool.Parent ~= state.Character then
        return
    end
    if not state.Track then
        local animation = Instance.new('Animation')
        animation.AnimationId = id
        phowg:queue_assets({ id })
        local ok, track = pcall(function()
            return animator:LoadAnimation(animation)
        end)
        if not ok or not track then
            animation:Destroy()
            return
        end
        state.Animation, state.Track, state.AnimationId, state.Animator = animation, track, id, animator
        track.Looped = false
        track.Priority = Enum.AnimationPriority.Action2
    end
    state.Track:Stop(0)
    state.Track:Play(0, 1, phowg:visual_number('skin_pullout_speed', 1, 0.1, 3))
end
function phowg:apply_skin_assets(tool, skin)
    local character, handle = LocalPlayer.Character, tool:FindFirstChild('Handle')
    if not character or tool.Parent ~= character or not handle or not handle:IsA('BasePart') then
        return
    end
    local catalog = Data.SkinAssetCatalog or phowg:build_skin_asset_catalog()
    local key = phowg:skin_asset_key(skin)
    Data.SkinToolStates = Data.SkinToolStates or setmetatable({}, { __mode = 'k' })
    local state: { [string]: any }? = Data.SkinToolStates[tool]
    if state and (state.Character ~= character or state.Handle ~= handle or state.Skin ~= skin) then
        phowg:stop_skin_tool(tool, true)
        state = nil
    end
    if skin == 'None' or skin == 'Default' or skin == '' then
        phowg:stop_skin_tool(tool, true)
        return
    end
    if not state then
        state = {
            Character = character,
            Handle = handle,
            Skin = skin,
            Sounds = {},
            Sources = {},
            OriginalSkinName = handle:GetAttribute('SkinName'),
        }
        Data.SkinToolStates[tool] = state
    end
    local entry = catalog.Effects[key]
    local gunSounds = catalog.ShootSounds[phowg:skin_asset_key(tool.Name)]
    state.ShootSoundSource = gunSounds and gunSounds[key] or nil
    local beam = tool.Name ~= '[Knife]' and catalog.Beams[key]
    state.AssignedSkinName = beam and beam.Name or entry and entry.Source and entry.Source.Name or skin
    phowg:stop_tool_shoot_sounds(tool)
    phowg:restore_tool_sounds(tool)
    handle:SetAttribute('SkinName', state.AssignedSkinName)
    hooktoolshootsound(tool)
    local profile = tool.Name == '[Knife]' and phowg:knife_skin_profile(skin)
    local detail = profile and profile.Sound ~= '' and profile
        or tool.Name == '[Knife]' and Data.SkinPullouts and Data.SkinPullouts[skin]
    phowg:apply_skin_model_particles(tool)
    phowg:skin_sound(state, 'Equip', entry and entry.EquipSound, detail)
    phowg:skin_sound(state, 'Attack', entry and entry.AttackSound)
    phowg:play_skin_sound(state, 'Equip')
    if tool.Name == '[Knife]' then
        phowg:update_skin_attack(tool, state)
        if tool:GetAttribute('Attacking') == true then
            if not state.AttributeAttackPlayed then
                phowg:play_skin_attack(tool)
            end
        else
            phowg:play_skin_pullout(tool, state)
        end
    end
end
function phowg:bind_skin_attack_block(tool, state)
    local animator = state.AttackTrack and state.AttackAnimator
    if state.AttackBlockAnimator == animator and state.AttackBlockConnection then
        return
    end
    if state.AttackBlockConnection then
        state.AttackBlockConnection:Disconnect()
        state.AttackBlockConnection = nil
    end
    state.AttackBlockAnimator = nil
    if not animator or not animator.AnimationPlayed or tool.Parent ~= state.Character then
        return
    end
    local function block(track)
        if
            Library.Unloaded
            or tool.Parent ~= LocalPlayer.Character
            or not state.AttackTrack
            or Data.SkinToolStates[tool] ~= state
            or not phowg:skin_cosmetics_enabled()
        then
            return
        end
        local animation = track.Animation
        local id = animation and tostring(animation.AnimationId):match('%d+')
        if id == '3033700364' or id == '3033717454' then
            track:Stop(0)
        end
    end
    state.AttackBlockAnimator = animator
    state.AttackBlockConnection =
        connectshared(animator.AnimationPlayed, block, state.Character, 'knife default attack block')
    for _, track in ipairs(animator:GetPlayingAnimationTracks()) do
        block(track)
    end
end
function phowg:skin_attack_values()
    local catalog = Data.SkinAssetCatalog or phowg:build_skin_asset_catalog()
    local values, seen = { 'None', 'Skin' }, { none = true, skin = true }
    for _, source in pairs(catalog.Attacks) do
        local key = phowg:skin_asset_key(source.Name)
        if not seen[key] then
            seen[key] = true
            values[#values + 1] = source.Name
        end
    end
    for name, profile in pairs(Data.SkinKnifeProfiles or {}) do
        local key = phowg:skin_asset_key(name)
        if profile.Attack and not seen[key] then
            seen[key] = true
            values[#values + 1] = name
        end
    end
    table.sort(values, function(a, b)
        if a == 'None' then
            return b ~= 'None'
        end
        if b == 'None' then
            return false
        end
        if a == 'Skin' then
            return b ~= 'Skin'
        end
        if b == 'Skin' then
            return false
        end
        return a:lower() < b:lower()
    end)
    return values
end
function phowg:refresh_skin_attack_selection()
    local character = LocalPlayer.Character
    local tool = character and character:FindFirstChild('[Knife]')
    local state = tool and Data.SkinToolStates and Data.SkinToolStates[tool]
    if state then
        phowg:update_skin_attack(tool, state)
    end
end
function phowg:update_skin_attack(tool, state)
    local selection = Options.skin_attack_animation and Options.skin_attack_animation.Value or 'Skin'
    local skin = selection == 'Skin' and state.Skin or selection
    local profile = phowg:knife_skin_profile(skin)
    local catalog = Data.SkinAssetCatalog
    local source = selection ~= 'None' and catalog and catalog.Attacks[phowg:skin_asset_key(skin)]
    local id = selection ~= 'None' and (profile and profile.Attack or source and source.Parent and source.AnimationId)
        or nil
    local humanoid = state.Character:FindFirstChildOfClass('Humanoid')
    local animator = humanoid and (humanoid:FindFirstChildOfClass('Animator') or humanoid)
    if state.AttackTrack and (state.AttackAnimationId ~= id or state.AttackAnimator ~= animator) then
        if state.AttackBlockConnection then
            state.AttackBlockConnection:Disconnect()
            state.AttackBlockConnection = nil
        end
        state.AttackBlockAnimator = nil
        pcall(function()
            state.AttackTrack:Stop(0)
            state.AttackTrack:Destroy()
        end)
        if state.AttackAnimation then
            state.AttackAnimation:Destroy()
        end
        state.AttackTrack, state.AttackAnimation, state.AttackAnimationId, state.AttackAnimator = nil, nil, nil, nil
    end
    if state.AttackTrack then
        phowg:set_skin_attack_override(tool, state, true)
        phowg:bind_skin_attack_block(tool, state)
        return
    end
    if type(id) ~= 'string' or id == '' or not animator then
        phowg:set_skin_attack_override(tool, state, false)
        if state.AttackBlockConnection then
            state.AttackBlockConnection:Disconnect()
            state.AttackBlockConnection = nil
        end
        state.AttackBlockAnimator = nil
        return
    end
    phowg:queue_assets({ id })
    local animation = Instance.new('Animation')
    animation.AnimationId = id
    local ok, track = pcall(function()
        return animator:LoadAnimation(animation)
    end)
    if not ok or not track then
        animation:Destroy()
        phowg:set_skin_attack_override(tool, state, false)
        return
    end
    track.Looped, track.Priority = false, Enum.AnimationPriority.Action2
    state.AttackTrack, state.AttackAnimation, state.AttackAnimationId, state.AttackAnimator =
        track, animation, id, animator
    phowg:set_skin_attack_override(tool, state, true)
    phowg:bind_skin_attack_block(tool, state)
end
function phowg:play_skin_attack(tool)
    if not tool or tool.Parent ~= LocalPlayer.Character or not phowg:skin_cosmetics_enabled() then
        return
    end
    local state = Data.SkinToolStates and Data.SkinToolStates[tool]
    if not state or state.Character ~= LocalPlayer.Character or state.Skin ~= Data.SkinEquipped[tool.Name] then
        return
    end
    if tool:GetAttribute('Attacking') == true then
        if state.AttributeAttackPlayed then
            return
        end
        state.AttributeAttackPlayed = true
    end
    if state.Track then
        state.Track:Stop(0)
    end
    if tool.Name == '[Knife]' then
        phowg:stop_skin_rig(state, false, 'Equip')
        local catalog = Data.SkinAssetCatalog
        local rig = catalog and catalog.KnifeRigs and catalog.KnifeRigs[phowg:skin_asset_key(state.Skin)]
        if rig then
            phowg:play_skin_rig(tool, state, 'Attack', rig.Attack)
        end
        if not state.AttackTrack then
            phowg:update_skin_attack(tool, state)
        end
        if state.AttackTrack then
            state.AttackTrack:Stop(0)
            state.AttackTrack:Play(0, 1, phowg:visual_number('skin_attack_speed', 1, 0.1, 3))
        end
    end
    phowg:play_skin_sound(state, 'Attack')
end
function phowg:refresh_skin_pullout()
    if Library.ConfigLoading or Data.SkinConfigLoading or not phowg:skin_cosmetics_enabled() then
        return
    end
    local character = LocalPlayer.Character
    local tool = character and character:FindFirstChild('[Knife]')
    local state = tool and Data.SkinToolStates and Data.SkinToolStates[tool]
    if state then
        phowg:play_skin_pullout(tool, state)
    elseif tool then
        onskintooladded(tool)
    end
end
function phowg:native_gun_skin_available(handle, shot)
    if not handle or not handle.Parent then
        return false
    end
    local ok, available = pcall(function()
        local tool = handle.Parent
        local skin = handle:GetAttribute('SkinName')
        local assets = ReplicatedStorage:FindFirstChild('SkinAssets')
        if not assets then
            return false
        end
        local muzzles, beams = assets:FindFirstChild('GunSkinMuzzleParticle'), assets:FindFirstChild('GunBeam')
        if not muzzles or not beams then
            return false
        end
        local key = type(skin) == 'string' and skin ~= '' and skin or tool.Name
        local left = shot and shot.IsLeftHand == true
        local muzzleSkin = muzzles:FindFirstChild(key)
        if muzzleSkin and not (shot and (shot.isReflecting or shot.TrailOnly)) then
            local muzzle = muzzleSkin:FindFirstChild(left and 'LeftMuzzle' or 'Muzzle')
            if muzzleSkin:FindFirstChild('Muzzle') or left then
                if not muzzle or not muzzleSkin:FindFirstChild('Muzzle') then
                    return false
                end
                local different = muzzle:FindFirstChild('Different_GunMuzzle')
                if different and not different:FindFirstChild(tool.Name) then
                    return false
                end
            else
                local children = muzzleSkin:GetChildren()
                if #children == 0 then
                    return false
                end
                for _, child in ipairs(children) do
                    if not child:IsA('ParticleEmitter') or not child.Archivable then
                        return false
                    end
                end
            end
        end
        local beamSkin = beams:FindFirstChild(key)
        if beamSkin then
            local beamName = left and 'LeftGunBeam' or 'GunBeam'
            local beam = beamSkin:FindFirstChild(beamName) or beamSkin:FindFirstChild('GunBeam')
            if not beam then
                return false
            end
            local different = beam:IsA('BasePart') and beam:FindFirstChild('Different_GunBeam')
            local weapon = different and different:FindFirstChild(tool.Name)
            if weapon then
                beam = weapon:FindFirstChild(beamName)
            end
            if not beam or not beam.Archivable or not (beam:IsA('Beam') or beam:IsA('BasePart')) then
                return false
            end
        end
        return true
    end)
    return ok and available == true
end
function phowg:prepare_native_gun_skin(shot)
    if type(shot) ~= 'table' then
        return nil
    end
    local handle = shot.Handle
    if typeof(handle) ~= 'Instance' or not handle:IsA('BasePart') or not handle.Parent then
        return nil
    end
    if not ReplicatedStorage:FindFirstChild('GunBeam') then
        local beam = Instance.new('Beam')
        beam.Name, beam.FaceCamera, beam.Width0, beam.Width1 = 'GunBeam', true, 0.06, 0.06
        beam.Color, beam.LightEmission = ColorSequence.new(Color3.fromRGB(255, 235, 150)), 1
        beam.Parent = ReplicatedStorage
        Data.NativeFallbackBeam = beam
    end
    if phowg:native_gun_skin_available(handle, shot) then
        return nil
    end
    local original = handle:GetAttribute('SkinName')
    local fallback = '__PhowgDefaultGun'
    if original == fallback then
        return nil
    end
    handle:SetAttribute('SkinName', fallback)
    return { Handle = handle, Original = original, Applied = fallback }
end
function phowg:restore_native_gun_skin(state)
    if not state then
        return
    end
    pcall(function()
        if state.Handle:GetAttribute('SkinName') == state.Applied then
            state.Handle:SetAttribute('SkinName', state.Original)
        end
    end)
end
phowg:register_cleanup('native fallback beam', function(_, reason)
    if reason ~= 'unload' then
        return
    end
    if Data.NativeFallbackBeam then
        Data.NativeFallbackBeam:Destroy()
        Data.NativeFallbackBeam = nil
    end
end)
function phowg:use_skin_tracer(handle, shot)
    if not phowg:skin_cosmetics_enabled() then
        return false
    end
    local character = LocalPlayer.Character
    local tool = handle and handle.Parent or character and character:FindFirstChildOfClass('Tool')
    local state = tool and Data.SkinToolStates and Data.SkinToolStates[tool]
    local catalog = Data.SkinAssetCatalog
    local beam = state and catalog and catalog.Beams[phowg:skin_asset_key(state.Skin)]
    return state ~= nil
        and tool.Parent == character
        and state.Handle.Parent == tool
        and state.Handle:GetAttribute('SkinName') == state.AssignedSkinName
        and beam ~= nil
        and beam.Parent ~= nil
        and phowg:native_gun_skin_available(state.Handle, shot or { TrailOnly = true })
end
function phowg:render_skin_tracer(handle, startPos, endPos)
    if type(Data.NativeGunShoot) ~= 'function' or not phowg:use_skin_tracer(handle) then
        return false
    end
    local previous = Data.NativeSkinRendering
    local context = { Rendering = true, SkinTracer = true }
    Data.NativeSkinRendering = context
    local ok = pcall(Data.NativeGunShoot, {
        Shooter = LocalPlayer.Character,
        Handle = handle,
        ForcedOrigin = startPos,
        AimPosition = endPos,
        Range = (endPos - startPos).Magnitude,
        Normal = Vector3.new(0, 1, 0),
        ReplicatedShot = true,
        TrailOnly = true,
    })
    context.Rendering = false
    if Data.NativeSkinRendering == context then
        Data.NativeSkinRendering = previous and previous.Rendering and previous or nil
    end
    return ok
end
function phowg:refresh_skin_assets()
    phowg:build_skin_asset_catalog()
    local dropdown = Options.skin_pullout_animation
    if dropdown then
        local selected = dropdown.Value
        local values = phowg:skin_pullout_values()
        dropdown:SetValues(values)
        dropdown:SetValue(table.find(values, selected) and selected or 'None', true)
    end
    local attack = Options.skin_attack_animation
    if attack then
        local selected, values = attack.Value, phowg:skin_attack_values()
        attack:SetValues(values)
        attack:SetValue(table.find(values, selected) and selected or 'Skin', true)
    end
    phowg:apply_equipped_skins()
    Data.WeaponPreviewScanned = nil
    if Data.WeaponWorkspace then
        Data.WeaponWorkspace.QueueRefresh()
    end
end
function phowg:queue_skin_asset_refresh(asset)
    if asset.Name == 'GunSoundPlay' and asset.Parent == ReplicatedStorage then
        phowg:install_shoot_sound_handler()
        return
    end
    local folder = asset
    while folder and folder.Parent ~= ReplicatedStorage and folder.Parent and folder.Parent.Name ~= 'SkinAssets' do
        folder = folder.Parent
    end
    if
        not folder
        or (
            folder.Name ~= 'SkinModules'
            and folder.Name ~= 'SkinAssets'
            and folder.Name ~= 'SkinScripts'
            and folder.Name ~= 'SkinScriptsStorage'
            and folder.Name ~= 'KnifeSkinAnimation'
            and folder.Name ~= 'GunBeam'
            and folder.Name ~= 'GunShootSounds'
            and folder.Name ~= 'GunHandleParticle'
        )
    then
        return
    end
    if folder.Name == 'SkinModules' then
        Data.SkinModuleRefreshNeeded = true
    end
    if Data.SkinAssetRefreshPending then
        return
    end
    local pending = {}
    Data.SkinAssetRefreshPending = pending
    task.defer(function()
        if Data.SkinAssetRefreshPending ~= pending then
            return
        end
        Data.SkinAssetRefreshPending = nil
        if not Library.Unloaded and not Data.SharedSignalsClosed then
            if Data.SkinModuleRefreshNeeded then
                Data.SkinModuleRefreshNeeded = nil
                buildskintable()
                refreshskindropdown()
            end
            phowg:refresh_skin_assets()
            phowg:queue_skin_inventory_refresh()
        end
    end)
end
function onskintooladded(tool)
    if not phowg:skin_cosmetics_enabled() then
        return
    end
    if not tool or not tool:IsA('Tool') then
        return
    end
    if not tool:FindFirstChild('Handle') then
        return
    end
    local gun = tool.Name
    if not Data.SkinEquipped[gun] then
        return
    end
    Data.SkinToolPending = Data.SkinToolPending or setmetatable({}, { __mode = 'k' })
    if Data.SkinToolPending[tool] then
        return
    end
    local character = LocalPlayer.Character
    local pending = {}
    Data.SkinToolPending[tool] = pending
    task.defer(function()
        if Data.SkinToolPending[tool] ~= pending then
            return
        end
        Data.SkinToolPending[tool] = nil
        if LocalPlayer.Character ~= character or tool.Parent ~= character or not phowg:skin_cosmetics_enabled() then
            return
        end
        local skin = Data.SkinEquipped[gun]
        if not skin then
            return
        end
        if applyskintotool(tool, skin, gun == '[Knife]') then
            phowg:apply_skin_assets(tool, skin)
        else
            phowg:stop_skin_tool(tool, true)
        end
    end)
end
function phowg:apply_equipped_skins()
    if phowg:defer_config_effect('skins', phowg.apply_equipped_skins) then return end
    if Library.ConfigLoading or Data.SkinConfigLoading then
        Data.SkinRefreshRequested = true
        return
    end
    Data.SkinRefreshRequested = nil
    if not phowg:skin_cosmetics_enabled() then
        return
    end
    local character = LocalPlayer.Character
    if character then
        for _, tool in ipairs(character:GetChildren()) do
            if tool:IsA('Tool') then
                onskintooladded(tool)
            end
        end
    end
    if phowg.sync_skin_inventory_selection then
        phowg:sync_skin_inventory_selection()
    end
end
function refreshskindropdown()
    local weapon = Options.skin_selected_weapon and Options.skin_selected_weapon.Value or '[Revolver]'
    if type(weapon) == 'table' then
        for name, enabled in pairs(weapon) do
            if enabled then
                weapon = name
                break
            end
        end
    end
    if type(weapon) ~= 'string' then
        return
    end
    local dropdown = Options.skin_weapon_skin
    if not dropdown then
        return
    end
    local names = getskinnamesforweapon(weapon)
    local equipped = Data.SkinEquipped[weapon]
    local selected = equipped
    if not selected or not table.find(names, selected) then
        selected = Data.SkinVisibleWeapon == weapon and table.find(names, dropdown.Value) and dropdown.Value or names[1]
    end
    if selected and equipped ~= selected then
        Data.SkinEquipped[weapon] = selected
        if SaveManager.MarkStateChanged then
            SaveManager:MarkStateChanged('weapon_skins')
        end
    end
    local weaponChanged = Data.SkinVisibleWeapon ~= weapon
    Data.SkinVisibleWeapon = weapon
    Data.SkinDropdownSync = true
    dropdown:SetValues(names, weaponChanged)
    dropdown:SetValue(selected, true)
    Data.SkinDropdownSync = nil
end
function phowg:restore_skin_inventory_entry(row)
    local state = Data.SkinInventoryCards and Data.SkinInventoryCards[row]
    if not state then
        return
    end
    Data.SkinInventoryCards[row] = nil
    if state.Connection then
        state.Connection:Disconnect()
    end
    if state.Button then
        state.Button:Destroy()
    end
    local original = state.OriginalButton
    if original then
        local replacement = row:FindFirstChild('Button')
        if row.Parent and not replacement then
            pcall(function()
                original.Parent = row
            end)
        elseif not original.Parent then
            original:Destroy()
        end
    end
    for object, properties in pairs(state.Properties) do
        if object.Parent then
            for property, record in pairs(properties) do
                if object[property] == record.Applied then
                    object[property] = record.Original
                end
            end
        end
    end
end
function phowg:clear_skin_inventory_gui()
    if Data.SkinInventoryPanelConnection then
        Data.SkinInventoryPanelConnection:Disconnect()
        Data.SkinInventoryPanelConnection = nil
    end
    Data.SkinInventoryPending = nil
    Data.SkinInventoryDirty = nil
    Data.SkinInventoryDirtyAll = nil
    for _, connection in ipairs(Data.SkinInventorySignals or {}) do
        connection:Disconnect()
    end
    Data.SkinInventorySignals = nil
    for row in pairs(table.clone(Data.SkinInventoryCards or {})) do
        phowg:restore_skin_inventory_entry(row)
    end
    Data.SkinInventoryCards = nil
    Data.SkinInventoryEntries = nil
    Data.SkinInventoryPanel = nil
    Data.SkinInventoryGui = nil
end
function phowg:write_skin_inventory_property(state, object, property, value)
    if not object then
        return
    end
    local properties = state.Properties[object]
    if not properties then
        properties = {}
        state.Properties[object] = properties
    end
    local record = properties[property]
    if not record then
        record = { Original = object[property] }
        properties[property] = record
    elseif object[property] ~= record.Applied then
        record.Original = object[property]
    end
    record.Applied = value
    if object[property] ~= value then
        object[property] = value
    end
end
function phowg:inventory_skin_equipped(state, marker)
    local selected = Data.SkinEquipped[state.Weapon]
    if selected and selected ~= 'Default' then
        return selected == state.Skin
    end
    local properties = state.Properties[marker]
    local record = properties and properties.Visible
    if record and marker.Visible == record.Applied then
        return record.Original
    end
    return marker.Visible
end
function phowg:sync_skin_inventory_selection(weapon)
    for row, state in pairs(Data.SkinInventoryCards or {}) do
        if (not weapon or state.Weapon == weapon) and row.Parent == Data.SkinInventoryEntries then
            local preview = row:FindFirstChild('Preview')
            local marker = preview and preview:FindFirstChild('Equipped')
            if marker and marker:IsA('GuiObject') then
                phowg:write_skin_inventory_property(state, marker, 'Visible', phowg:inventory_skin_equipped(state, marker))
            end
        end
    end
end
function phowg:select_inventory_skin(weapon, skin)
    if
        Library.Unloaded
        or Library.ConfigLoading
        or Data.SkinConfigLoading
        or not (Toggles.inventory_changer_enabled and Toggles.inventory_changer_enabled.Value)
    then
        return
    end
    local entries = Data.SkinTableCache and Data.SkinTableCache[weapon]
    if not entries or not entries[skin] then
        return
    end
    Data.SkinEquipped[weapon] = Data.SkinEquipped[weapon] == skin and 'Default' or skin
    if SaveManager.MarkStateChanged then
        SaveManager:MarkStateChanged('weapon_skins')
    end
    phowg:sync_skin_inventory_selection(weapon)
    if phowg.refresh_classic_weapon_profiles then
        phowg:refresh_classic_weapon_profiles()
    end
    local selected = Options.skin_selected_weapon and Options.skin_selected_weapon.Value
    if selected == weapon then
        refreshskindropdown()
    end
    local character = LocalPlayer.Character
    if character then
        for _, tool in ipairs(character:GetChildren()) do
            if tool:IsA('Tool') and tool.Name == weapon then
                onskintooladded(tool)
            end
        end
    end
    if Library.AttemptSave then
        Library:AttemptSave()
    end
end
function phowg:apply_skin_inventory_entry(row)
    local weapon, skin = row.Name:match('^(%b[])(.+)$')
    local entries = weapon and Data.SkinTableCache and Data.SkinTableCache[weapon]
    local state = Data.SkinInventoryCards and Data.SkinInventoryCards[row]
    if not row:IsA('GuiObject') or not entries or not entries[skin] then
        if state then
            phowg:restore_skin_inventory_entry(row)
        end
        return
    end
    local preview, button = row:FindFirstChild('Preview'), row:FindFirstChild('Button')
    if not preview or not button or not button:IsA('GuiButton') then
        if state then
            phowg:restore_skin_inventory_entry(row)
        end
        return
    end
    if state and (state.Button ~= button or state.Weapon ~= weapon or state.Skin ~= skin) then
        phowg:restore_skin_inventory_entry(row)
        state = nil
        button = row:FindFirstChild('Button')
    end
    if not button or not button:IsA('GuiButton') then
        return
    end
    if not state then
        local clone = button:Clone()
        if not clone then
            return
        end
        for _, object in ipairs(clone:GetDescendants()) do
            if object:IsA('LocalScript') or object:IsA('Script') then
                object:Destroy()
            end
        end
        state = { Weapon = weapon, Skin = skin, Properties = {}, OriginalButton = button, Button = clone }
        Data.SkinInventoryCards = Data.SkinInventoryCards or {}
        Data.SkinInventoryCards[row] = state
        button.Parent = nil
        clone.Name, clone.Visible, clone.Active, clone.Parent = 'Button', true, true, row
        state.Connection = connectshared(clone.Activated, function()
            if
                Data.SkinInventoryCards
                and Data.SkinInventoryCards[row] == state
                and row.Parent == Data.SkinInventoryEntries
            then
                phowg:select_inventory_skin(state.Weapon, state.Skin)
            end
        end, row, 'inventory/skin selection', 0, 'event/Activated', clone)
    end
    for object in pairs(state.Properties) do
        if not object:IsDescendantOf(row) then
            state.Properties[object] = nil
        end
    end
    local lock, amount = preview:FindFirstChild('LockImageLabel'), preview:FindFirstChild('AmountValue')
    local locked = lock and lock:IsA('GuiObject') and lock.Visible
    if lock and lock:IsA('GuiObject') then
        phowg:write_skin_inventory_property(state, lock, 'Visible', false)
    end
    if amount and (amount:IsA('TextLabel') or amount:IsA('TextButton') or amount:IsA('TextBox')) then
        local properties = state.Properties[amount]
        local record = properties and properties.Text
        local text = amount.Text
        if record and text == record.Applied then
            text = record.Original
        end
        local count = tonumber(tostring(text):match('%d+')) or 0
        phowg:write_skin_inventory_property(state, amount, 'Text', 'x' .. tostring(math.max(1, count)))
        phowg:write_skin_inventory_property(state, amount, 'Visible', true)
        locked = locked or count == 0
    end
    local info = row:FindFirstChild('SkinInfo')
    local container = info and info:FindFirstChild('Container')
    local sell = container and container:FindFirstChild('SellButton')
    if locked and sell and sell:IsA('GuiObject') then
        phowg:write_skin_inventory_property(state, sell, 'Visible', false)
    end
    local marker = preview:FindFirstChild('Equipped')
    if marker and marker:IsA('GuiObject') then
        phowg:write_skin_inventory_property(state, marker, 'Visible', phowg:inventory_skin_equipped(state, marker))
    end
end
function phowg:find_skin_inventory_entries(gui)
    local current = gui
    for _, name in ipairs({
        'MainScreenGui',
        'WeaponSkinsGUI',
        'Body',
        'Wrapper',
        'SkinView',
        'Frame',
        'Skins',
        'Contents',
        'Entries',
    }) do
        current = current and current:FindFirstChild(name)
    end
    return current
end
function phowg:refresh_skin_inventory_gui()
    if
        Library.Unloaded
        or Data.SharedSignalsClosed
        or not (Toggles.inventory_changer_enabled and Toggles.inventory_changer_enabled.Value)
    then
        return
    end
    local gui = LocalPlayer:FindFirstChildOfClass('PlayerGui')
    if not gui then
        phowg:clear_skin_inventory_gui()
        return
    end
    if Data.SkinInventoryGui ~= gui then
        phowg:clear_skin_inventory_gui()
        Data.SkinInventoryGui = gui
        Data.SkinInventorySignals = {
            connectshared(
                gui.DescendantAdded,
                phowg_callbacks.queue_skin_inventory_refresh,
                gui,
                'inventory/gui added',
                0,
                'event/DescendantAdded',
                gui
            ),
            connectshared(gui.DescendantRemoving, function(object)
                if Data.SkinInventoryCards and Data.SkinInventoryCards[object] then
                    phowg:restore_skin_inventory_entry(object)
                end
                phowg:queue_skin_inventory_refresh(object)
            end, gui, 'inventory/gui removed', 0, 'event/DescendantRemoving', gui),
            connectshared(gui.AncestryChanged, function()
                if Data.SkinInventoryGui == gui and gui.Parent ~= LocalPlayer then
                    phowg:clear_skin_inventory_gui()
                end
            end, gui, 'inventory/gui ancestry', 0, 'event/AncestryChanged', gui),
        }
    end
    local entries = phowg:find_skin_inventory_entries(gui)
    if entries ~= Data.SkinInventoryEntries then
        for row in pairs(table.clone(Data.SkinInventoryCards or {})) do
            phowg:restore_skin_inventory_entry(row)
        end
        Data.SkinInventoryEntries = entries
        if Data.SkinInventoryPanelConnection then
            Data.SkinInventoryPanelConnection:Disconnect()
            Data.SkinInventoryPanelConnection = nil
        end
        local main = gui:FindFirstChild('MainScreenGui')
        local panel = main and main:FindFirstChild('WeaponSkinsGUI')
        Data.SkinInventoryPanel = panel
        if panel and panel:IsA('GuiObject') then
            Data.SkinInventoryPanelConnection = connectshared(panel:GetPropertyChangedSignal('Visible'), function()
                if panel.Visible then
                    phowg:queue_skin_inventory_refresh()
                end
            end, panel, 'inventory/panel visibility', 0, 'property/Visible', panel)
        end
        Data.SkinInventoryDirtyAll = true
    end
    if not entries then
        return
    end
    local dirty, all = Data.SkinInventoryDirty, Data.SkinInventoryDirtyAll
    Data.SkinInventoryDirty, Data.SkinInventoryDirtyAll = nil, nil
    if all or not dirty then
        for _, row in ipairs(entries:GetChildren()) do
            phowg:apply_skin_inventory_entry(row)
        end
    else
        for row in pairs(dirty) do
            if row.Parent == entries then
                phowg:apply_skin_inventory_entry(row)
            end
        end
    end
end
function phowg:queue_skin_inventory_refresh(object)
    if
        Library.Unloaded
        or Data.SharedSignalsClosed
        or not (Toggles.inventory_changer_enabled and Toggles.inventory_changer_enabled.Value)
    then
        return
    end
    if object then
        local row = object
        local entries = Data.SkinInventoryEntries
        while row and row.Parent ~= entries and row ~= Data.SkinInventoryGui do
            row = row.Parent
        end
        if entries and row and row.Parent == entries then
            Data.SkinInventoryDirty = Data.SkinInventoryDirty or {}
            Data.SkinInventoryDirty[row] = true
        else
            local current, relevant = object, false
            while current do
                if current.Name == 'WeaponSkinsGUI' or current.Name == 'MainScreenGui' then
                    relevant = true
                    break
                end
                current = current.Parent
            end
            if not relevant then
                return
            end
            Data.SkinInventoryDirtyAll = true
        end
    else
        Data.SkinInventoryDirtyAll = true
    end
    if Data.SkinInventoryPending then
        return
    end
    local pending = {}
    Data.SkinInventoryPending = pending
    task.defer(function()
        if Data.SkinInventoryPending ~= pending then
            return
        end
        Data.SkinInventoryPending = nil
        phowg:refresh_skin_inventory_gui()
    end)
end
function phowg:sync_skin_cosmetics()
    if phowg:skin_cosmetics_enabled() then
        buildskintable()
        refreshskindropdown()
        phowg:build_skin_asset_catalog()
        phowg:apply_equipped_skins()
    else
        phowg:clear_skin_tools()
        if Data.SkinToolPending then
            table.clear(Data.SkinToolPending)
        end
        hookshootsound()
    end
end
function aimassistloop()
    while Toggles.aim_assist_enabled and Toggles.aim_assist_enabled.Value do
        if localactionblocked(true) then
            phowg:update_main_fov('aim_assist', nil, nil, nil, false)
            task.wait(0.05)
            continue
        end
        local key = Options.aim_assist_key and Options.aim_assist_key:GetState()
        local rising = key and not Data['AssistKeyPrev']
        Data['AssistKeyPrev'] = key
        if key and not UserInputService:GetFocusedTextBox() then
            local cam = Workspace.CurrentCamera
            if cam then
                local mousePos = UserInputService:GetMouseLocation()
                local fov = (Options.aim_assist_fov and Options.aim_assist_fov.Value) or 150
                local smooth = (Options.aim_assist_smoothing and Options.aim_assist_smoothing.Value) or 0
                if smooth < 0 then
                    smooth = 0
                end
                if smooth > 1 then
                    smooth = 1
                end
                local amt = 1 - smooth
                local partSel = Toggles.aim_assist_closest_part and Toggles.aim_assist_closest_part.Value and 'closest'
                    or Options.aim_assist_part and Options.aim_assist_part.Value
                    or 'head'
                local visOn = Toggles.aim_assist_visible_check and Toggles.aim_assist_visible_check.Value
                local allowKnocked = Toggles.aim_assist_knocked and Toggles.aim_assist_knocked.Value
                local allowDead = Toggles.aim_assist_dead and Toggles.aim_assist_dead.Value
                local allowCrew = Toggles.aim_assist_crew and Toggles.aim_assist_crew.Value
                local assistType = Options.aim_assist_type and Options.aim_assist_type.Value or 'mouse'
                local locked = Data['AssistLockedTarget']
                if locked and (not locked.Parent or not locked.Character or not locked.Character.Parent) then
                    locked = nil
                    Data['AssistLockedTarget'] = nil
                    Data['AssistAimPart'] = nil
                    Data['AssistAimPos'] = nil
                end
                if
                    locked
                    and (
                        iscrewwhitelisted(locked)
                        or iswhitelistedplayer(locked)
                        or (Data['RageWhitelist'] and Data['RageWhitelist'][locked])
                    )
                then
                    locked = nil
                    Data['AssistLockedTarget'] = nil
                    Data['AssistAimPart'] = nil
                    Data['AssistAimPos'] = nil
                end
                if rising or not locked then
                    local best, bestDist = nil, 9e9
                    for _, plr in ipairs(Players:GetPlayers()) do
                        local ch = plr ~= LocalPlayer and plr.Character or nil
                        if ch and ch.Parent and not ch:FindFirstChildOfClass('ForceField') then
                            local dead = not intelligence:get_character_cache(plr)
                            local knocked = not dead and isknocked(plr)
                            local crewId = getplayercrewid(plr)
                            local inCrew = (crewId and Data['WhitelistedCrews'][tostring(crewId)])
                                or iswhitelistedplayer(plr)
                            local ok = true
                            if dead and not allowDead then
                                ok = false
                            end
                            if knocked and not allowKnocked then
                                ok = false
                            end
                            if inCrew and not allowCrew then
                                ok = false
                            end
                            if Data['RageWhitelist'] and Data['RageWhitelist'][plr] then
                                ok = false
                            end
                            if iscrewwhitelisted(plr) or iswhitelistedplayer(plr) then
                                ok = false
                            end
                            if ok then
                                local parts = {
                                    Head = ch:FindFirstChild('Head'),
                                    HumanoidRootPart = ch:FindFirstChild('HumanoidRootPart'),
                                    UpperTorso = ch:FindFirstChild('UpperTorso') or ch:FindFirstChild('Torso'),
                                    LowerTorso = ch:FindFirstChild('LowerTorso'),
                                }
                                local canon = canonicalhitbox(partSel)
                                local tp = nil
                                if canon == 'Closest' then
                                    local cd, cb = 9e9, nil
                                    for _, pn in ipairs({ 'Head', 'HumanoidRootPart', 'UpperTorso', 'LowerTorso' }) do
                                        local part = parts[pn]
                                        if part then
                                            local p, on = cam:WorldToViewportPoint(part.Position)
                                            if on then
                                                local d = (Vector2.new(p.X, p.Y) - mousePos).Magnitude
                                                if d < cd then
                                                    cd = d
                                                    cb = part
                                                end
                                            end
                                        end
                                    end
                                    tp = cb
                                elseif canon == 'Random' then
                                    tp = parts.Head
                                else
                                    tp = parts[canon] or parts.Head
                                end
                                if tp then
                                    local sp, on = cam:WorldToViewportPoint(tp.Position)
                                    if on then
                                        local dist = (Vector2.new(sp.X, sp.Y) - mousePos).Magnitude
                                        if dist <= fov and dist < bestDist then
                                            local blocked = false
                                            if visOn then
                                                local params = RaycastParams.new()
                                                params.FilterDescendantsInstances =
                                                    { LocalPlayer.Character, plr.Character }
                                                params.FilterType = Enum.RaycastFilterType.Blacklist
                                                local res = Workspace:Raycast(
                                                    cam.CFrame.Position,
                                                    (tp.Position - cam.CFrame.Position),
                                                    params
                                                )
                                                if
                                                    res
                                                    and res.Instance
                                                    and not res.Instance:IsDescendantOf(plr.Character)
                                                then
                                                    blocked = true
                                                end
                                            end
                                            if not blocked then
                                                bestDist = dist
                                                best = plr
                                            end
                                        end
                                    end
                                end
                            end
                        end
                    end
                    locked = best
                    Data['AssistLockedTarget'] = best
                end
                local bestPart = nil
                if locked then
                    local ch = locked.Character
                    if ch and ch.Parent then
                        local parts = {
                            Head = ch:FindFirstChild('Head'),
                            HumanoidRootPart = ch:FindFirstChild('HumanoidRootPart'),
                            UpperTorso = ch:FindFirstChild('UpperTorso') or ch:FindFirstChild('Torso'),
                            LowerTorso = ch:FindFirstChild('LowerTorso'),
                        }
                        local canon = canonicalhitbox(partSel)
                        if canon == 'Closest' then
                            local cd, cb = 9e9, nil
                            for _, pn in ipairs({ 'Head', 'HumanoidRootPart', 'UpperTorso', 'LowerTorso' }) do
                                local part = parts[pn]
                                if part and phowg:closest_part_allowed(pn) then
                                    local p, on = cam:WorldToViewportPoint(part.Position)
                                    if on then
                                        local d = (Vector2.new(p.X, p.Y) - mousePos).Magnitude
                                        if d < cd then
                                            cd = d
                                            cb = part
                                        end
                                    end
                                end
                            end
                            bestPart = cb
                        elseif canon == 'Random' then
                            bestPart = parts.Head
                        else
                            bestPart = parts[canon] or parts.Head
                        end
                    end
                end
                if bestPart and amt > 0 then
                    if assistType == 'cam' then
                        local camPos = cam.CFrame.Position
                        local off = bestPart.Position - camPos
                        if off.Magnitude > 0.5 then
                            local nl = cam.CFrame.LookVector:Lerp(off.Unit, amt)
                            if Toggles.aim_assist_match_y and Toggles.aim_assist_match_y.Value then
                                nl = Vector3.new(nl.X, off.Unit.Y, nl.Z)
                            end
                            if nl.Magnitude > 0.001 then
                                cam.CFrame = CFrame.lookAt(camPos, camPos + nl)
                            end
                        end
                    else
                        local sp, on = cam:WorldToViewportPoint(bestPart.Position)
                        if on then
                            local dx = sp.X - mousePos.X
                            local dy = sp.Y - mousePos.Y
                            if dx * dx + dy * dy > 1 and mousemoverel then
                                mousemoverel(
                                    dx * amt,
                                    dy * (Toggles.aim_assist_match_y and Toggles.aim_assist_match_y.Value and 1 or amt)
                                )
                            end
                        end
                    end
                end
                Data['AssistAimPart'] = bestPart
                Data['AssistAimPos'] = bestPart and bestPart.CFrame or nil
                local showFov = Toggles.aim_assist_show_fov and Toggles.aim_assist_show_fov.Value or false
                local fovCol = (Options.aim_assist_fov_color and Options.aim_assist_fov_color.Value)
                    or Color3.fromRGB(255, 255, 255)
                phowg:update_main_fov('aim_assist', mousePos, fov, fovCol, showFov)
            end
        else
            Data['AssistLockedTarget'] = nil
            Data['AssistAimPart'] = nil
            Data['AssistAimPos'] = nil
            phowg:update_main_fov('aim_assist', nil, nil, nil, false)
            for _, Line in pairs(Data['AssistFOVRing'] or {}) do
                if Line then
                    Line.Visible = false
                end
            end
        end
        RunService.RenderStepped:Wait()
    end
    Data['AssistLockedTarget'] = nil
    Data['AssistAimPart'] = nil
    Data['AssistAimPos'] = nil
    phowg:update_main_fov('aim_assist', nil, nil, nil, false)
    for _, Line in pairs(Data['AssistFOVRing'] or {}) do
        if Line then
            Line.Visible = false
        end
    end
end
Library.ActionNotifications = {}
function Library:NotifyActions(Text, Actions, Time)
    if Library.Unloaded or type(Actions) ~= 'table' or #Actions == 0 then
        return
    end
    local notice = Library:BuildNotification(Text, 'Default', false, true)
    if not notice then
        return
    end
    local handle = { Closed = false, Buttons = {} }
    local outer = notice.Frame
    outer.Name, outer.Active = 'ActionNotification', true
    handle.Frame = outer
    function handle:Dismiss(destroying)
        if self.Closed then
            return
        end
        self.Closed = true
        Library.ActionNotifications[self] = nil
        if self.Timer and self.Timer ~= coroutine.running() then
            pcall(task.cancel, self.Timer)
        end
        self.Timer = nil
        if not destroying then
            outer:Destroy()
        end
    end
    handle.Destroy = handle.Dismiss
    outer.Destroying:Connect(function()
        handle:Dismiss(true)
    end)
    for index, action in ipairs(Actions) do
        local button = Library:Create('TextButton', {
            BackgroundColor3 = Library.BackgroundColor,
            BorderColor3 = Library.OutlineColor,
            Position = UDim2.new((index - 1) / #Actions, (index - 1) * 4 / #Actions, 0, 0),
            Size = UDim2.new(1 / #Actions, -4 * (#Actions - 1) / #Actions, 1, 0),
            AutoButtonColor = false,
            Modal = true,
            Text = tostring(action.Text or action.Label or index),
            TextColor3 = Library.FontColor,
            Font = Library.Font,
            TextSize = 14,
            TextTruncate = Enum.TextTruncate.AtEnd,
            ZIndex = 103,
            Parent = notice.Actions,
        })
        Library:AddToRegistry(
            button,
            { BackgroundColor3 = 'BackgroundColor', BorderColor3 = 'OutlineColor', TextColor3 = 'FontColor' },
            true
        )
        Library:StyleControl(button, button, 4)
        handle.Buttons[index] = button
        button.Activated:Connect(function()
            if handle.Closed or not outer.Parent or Library.Unloaded then
                return
            end
            handle:Dismiss()
            if type(action.Callback) == 'function' then
                task.spawn(function()
                    local ok, err = pcall(action.Callback, handle)
                    if not ok then
                        warn('[Phowg] notification action failed: ' .. tostring(err))
                    end
                end)
            end
        end)
    end
    Library.ActionNotifications[handle] = true
    if type(Time) == 'number' and Time > 0 then
        handle.Timer = task.delay(Time, function()
            handle:Dismiss()
        end)
    end
    return handle
end
phowg:register_cleanup('action notifications', function(_, reason)
    if reason ~= 'unload' then
        return
    end
    for handle in pairs(Library.ActionNotifications) do
        handle:Dismiss()
    end
end)
function shieldsave(CheckPlayers)
    local S = Data['Shield']
    local function strkeys(t)
        local o = {}
        for k, v in pairs(t) do
            o[tostring(k)] = v
        end
        return o
    end
    local out = {
        WhitelistIds = strkeys(S.WhitelistIds),
        WhitelistNames = strkeys(S.WhitelistNames),
        WhitelistGroups = strkeys(S.WhitelistGroups),
        MarkedIds = strkeys(S.MarkedIds),
        StalkUsers = strkeys(S.StalkUsers),
        StalkGroups = strkeys(S.StalkGroups),
        KickGroups = S.KickGroups,
        NotifyGroups = S.NotifyGroups,
        ModGroups = S.ModGroups,
        ReporterGroups = S.ReporterGroups,
        UserNames = strkeys(Data['ShieldUserNames']),
        GroupNames = strkeys(Data['ShieldGroupNames']),
    }
    local ok, enc = pcall(HttpService.JSONEncode, HttpService, out)
    if ok and enc then
        pcall(writefile, Data['ShieldFile'], enc)
    end
    if CheckPlayers ~= false and phowg.recheck_protection then
        phowg:recheck_protection()
    end
end
function shieldload()
    local f = Data['ShieldFile']
    local has = false
    pcall(function()
        has = isfile(f)
    end)
    if not has then
        shieldsave()
        return
    end
    local ok, raw = pcall(readfile, f)
    if not ok or not raw or raw == '' then
        return
    end
    local ok2, dec = pcall(HttpService.JSONDecode, HttpService, raw)
    if not ok2 or type(dec) ~= 'table' then
        return
    end
    local function idset(v)
        local o = {}
        if type(v) == 'table' then
            for k, on in pairs(v) do
                local id = tonumber(k)
                if id and on then
                    o[id] = true
                end
            end
        end
        return o
    end
    local function idmap(v)
        local o = {}
        if type(v) == 'table' then
            for k, msg in pairs(v) do
                local id = tonumber(k)
                if id then
                    o[id] = msg
                end
            end
        end
        return o
    end
    local function nameset(v)
        local o = {}
        if type(v) == 'table' then
            for k, on in pairs(v) do
                if on then
                    o[string.lower(tostring(k))] = true
                end
            end
        end
        return o
    end
    local function groupmap(v)
        local o = {}
        if type(v) == 'table' then
            for k, g in pairs(v) do
                local id = tonumber(k)
                if id and type(g) == 'table' then
                    o[id] = g
                end
            end
        end
        return o
    end
    local S = Data['Shield']
    if dec.WhitelistIds ~= nil then
        S.WhitelistIds = idset(dec.WhitelistIds)
    end
    if dec.WhitelistNames ~= nil then
        S.WhitelistNames = nameset(dec.WhitelistNames)
    end
    if dec.WhitelistGroups ~= nil then
        S.WhitelistGroups = idset(dec.WhitelistGroups)
    end
    if dec.MarkedIds ~= nil then
        S.MarkedIds = idset(dec.MarkedIds)
    end
    if dec.StalkUsers ~= nil then
        S.StalkUsers = idmap(dec.StalkUsers)
    end
    if dec.StalkGroups ~= nil then
        S.StalkGroups = idset(dec.StalkGroups)
    end
    if dec.KickGroups ~= nil then
        S.KickGroups = groupmap(dec.KickGroups)
    end
    if dec.NotifyGroups ~= nil then
        S.NotifyGroups = groupmap(dec.NotifyGroups)
    end
    if dec.ModGroups ~= nil then
        S.ModGroups = groupmap(dec.ModGroups)
    end
    if dec.ReporterGroups ~= nil then
        S.ReporterGroups = groupmap(dec.ReporterGroups)
    end
    if dec.UserNames ~= nil then
        Data['ShieldUserNames'] = idmap(dec.UserNames)
    end
    if dec.GroupNames ~= nil then
        Data['ShieldGroupNames'] = idmap(dec.GroupNames)
    end
end
function shieldidkeys(t)
    local o = {}
    for k, _ in pairs(t) do
        table.insert(o, tostring(k))
    end
    table.sort(o)
    return o
end
function shieldstalkeys(t)
    local o = {}
    for k, v in pairs(t) do
        table.insert(o, tostring(k) .. ' | ' .. shieldusername(k) .. ' | ' .. tostring(v))
    end
    table.sort(o)
    return o
end
function shieldgroupkeys(t)
    local o = {}
    for k, v in pairs(t) do
        table.insert(o, tostring(k) .. ' | ' .. tostring(type(v) == 'table' and v.Name or v))
    end
    table.sort(o)
    return o
end
function shieldmodkeys(t)
    local o = {}
    for k, v in pairs(t) do
        local r = ''
        if type(v) == 'table' and type(v.Forbidden) == 'table' then
            r = table.concat(v.Forbidden, ',')
        end
        table.insert(o, tostring(k) .. ' | ' .. tostring(type(v) == 'table' and v.Name or '') .. ' | ' .. r)
    end
    table.sort(o)
    return o
end
function shieldrefreshlists()
    if not Options then
        return
    end
    local lists = {
        shield_wl_ids = function()
            return shielduserkeys(Data['Shield'].WhitelistIds)
        end,
        shield_marked = function()
            return shielduserkeys(Data['Shield'].MarkedIds)
        end,
        shield_stalk_list = function()
            return shieldstalkeys(Data['Shield'].StalkUsers)
        end,
        shield_wl_groups = function()
            return shieldplainkeys(Data['Shield'].WhitelistGroups)
        end,
        shield_stalkgroups = function()
            return shieldplainkeys(Data['Shield'].StalkGroups)
        end,
        shield_reportergroups = function()
            return shieldgroupkeys(Data['Shield'].ReporterGroups)
        end,
    }
    for name, values in pairs(lists) do
        phowg:queue_background('ui', name, function()
            local option = Options[name]
            if not option then
                return
            end
            local nextValues, previous = values(), option.Values or {}
            local changed = #nextValues ~= #previous
            if not changed then
                for index, value in ipairs(nextValues) do
                    if previous[index] ~= value then
                        changed = true
                        break
                    end
                end
            end
            if changed then
                option:SetValues(nextValues)
            end
        end)
    end
end
function shieldsavesoon()
    if Data['ShieldSaveDue'] then
        return
    end
    Data['ShieldSaveDue'] = true
    task.delay(1, function()
        Data['ShieldSaveDue'] = nil
        if not Data.SharedSignalsClosed then
            shieldsave(false)
        end
    end)
end
function shieldlistssoon()
    if Data['ShieldListsDue'] then
        return
    end
    Data['ShieldListsDue'] = true
    task.delay(0.3, function()
        Data['ShieldListsDue'] = nil
        if not Data.SharedSignalsClosed then
            shieldrefreshlists()
        end
    end)
end
function shieldusername(Id)
    local num = tonumber(Id)
    if not num then
        return tostring(Id)
    end
    if Data['ShieldUserNames'][num] then
        return Data['ShieldUserNames'][num]
    end
    phowg:resolve_shield_name('user', num)
    return '...'
end
function shieldgrouplabel(Id)
    local num = tonumber(Id)
    if not num then
        return tostring(Id)
    end
    if Data['ShieldGroupNames'][num] then
        return tostring(num) .. ' | ' .. Data['ShieldGroupNames'][num]
    end
    phowg:resolve_shield_name('group', num)
    return tostring(num) .. ' | ...'
end
function phowg:resolve_shield_name(kind, id)
    local key = kind .. '/' .. tostring(id)
    Data.ShieldNameRetries = Data.ShieldNameRetries or {}
    local retry = Data.ShieldNameRetries[key]
    if retry and tick() < retry.At then
        return
    end
    phowg:queue_background('metadata', key, function()
        local cache = kind == 'user' and Data.ShieldUserNames or Data.ShieldGroupNames
        if cache[id] then
            return
        end
        local ok, result = pcall(function()
            if kind == 'user' then
                return Players:GetNameFromUserIdAsync(id)
            end
            local info = GroupService:GetGroupInfoAsync(id)
            return info and info.Name
        end)
        if ok and type(result) == 'string' and result ~= '' then
            cache[id] = result
            Data.ShieldNameRetries[key] = nil
            shieldlistssoon()
            shieldsavesoon()
        else
            local attempts = (retry and retry.Attempts or 0) + 1
            Data.ShieldNameRetries[key] =
                { Attempts = attempts, At = tick() + math.min(60, 5 * 2 ^ math.min(attempts - 1, 4)) }
        end
    end)
end
function shielduserkeys(t)
    local o = {}
    for k, _ in pairs(t) do
        table.insert(o, tostring(k) .. ' | ' .. shieldusername(k))
    end
    table.sort(o)
    return o
end
function shieldplainkeys(t)
    local o = {}
    for k, _ in pairs(t) do
        table.insert(o, shieldgrouplabel(k))
    end
    table.sort(o)
    return o
end
function shieldparseid(s)
    if not s then
        return nil
    end
    return tonumber(tostring(s):match('%d+'))
end
function shieldgroupname(Id)
    local n = tonumber(Id)
    if not n then
        return tostring(Id)
    end
    if Data['ShieldGroupNames'][n] then
        return Data['ShieldGroupNames'][n]
    end
    local ok, info = pcall(function()
        return GroupService:GetGroupInfoAsync(n)
    end)
    if ok and info and info.Name then
        Data['ShieldGroupNames'][n] = info.Name
        return info.Name
    end
    return tostring(n)
end
function phowg:load_protection_groups(player, record)
    if record.GroupsLoaded then
        return true
    end
    if player.Parent ~= Players or tick() < (Data.ShieldGroupRetryAt or 0) then
        return false
    end
    local ok, groups = pcall(function()
        return GroupService:GetGroupsAsync(player.UserId)
    end)
    if player.Parent ~= Players or Data.SharedSignalsClosed then
        return false
    end
    if not ok or type(groups) ~= 'table' then
        record.GroupError = tostring(groups)
        Data.ShieldGroupError, Data.ShieldGroupRetryAt = record.GroupError, tick() + 5
        return false
    end
    for _, group in ipairs(groups) do
        local id = tonumber(group.Id)
        if id and id > 0 then
            record.Memberships[id] = true
            if type(group.Role) == 'string' then
                record.Roles[id] = group.Role
            end
            if type(group.Name) == 'string' then
                Data.ShieldGroupNames[id] = group.Name
            end
        end
    end
    record.GroupsLoaded, record.GroupError = true, nil
    Data.ShieldGroupRetryAt, Data.ShieldGroupError = nil, nil
    return true
end
function shieldiswhitelisted(Player, membership)
    if not Player then
        return false
    end
    local S = Data['Shield']
    if S.WhitelistIds[Player.UserId] then
        return true
    end
    if S.WhitelistNames[string.lower(Player.Name)] then
        return true
    end
    if S.WhitelistNames[string.lower(Player.DisplayName)] then
        return true
    end
    for gid in pairs(S.WhitelistGroups) do
        local ok, ing
        if membership then
            ok, ing = membership(gid)
        else
            local record = Data.ShieldChecks and Data.ShieldChecks[Player]
            if record and record.GroupsLoaded then
                ok, ing = true, record.Memberships[tonumber(gid)] == true
            else
                ok, ing = pcall(function()
                    return Player:IsInGroupAsync(tonumber(gid))
                end)
            end
        end
        if ok and ing then
            return true
        end
    end
    return false
end
function shieldcheck(Player, revision, record)
    if not (Toggles.shield_enable and Toggles.shield_enable.Value) then
        return
    end
    if not Player or Player == LocalPlayer then
        return
    end
    local S = Data['Shield']
    local tag = Player.DisplayName .. ' (@' .. Player.Name .. ')'
    local memberships, roles, failed = record and record.Memberships or {}, record and record.Roles or {}, false
    local function notify(text, duration)
        if record then
            if record.Notices[text] then
                return
            end
            record.Notices[text] = true
        end
        Library:Notify(text, duration)
    end
    local groupRecord: { [string]: any } = record or { Memberships = memberships, Roles = roles }
    local function membership(gid)
        local id = tonumber(gid)
        if not id or id <= 0 or id % 1 ~= 0 then
            return true, false
        end
        if memberships[id] ~= nil then
            return true, memberships[id]
        end
        if not phowg:load_protection_groups(Player, groupRecord) then
            failed = true
            return false, false
        end
        memberships[id] = memberships[id] == true
        return true, memberships[id]
    end
    local function roleof(gid)
        local id = tonumber(gid)
        if not id then
            return ''
        end
        if roles[id] ~= nil then
            return roles[id]
        end
        local ok, role = pcall(function()
            return Player:GetRoleInGroupAsync(id)
        end)
        if ok then
            roles[id] = role
        else
            failed = true
            groupRecord.GroupError = tostring(role)
        end
        return ok and role or ''
    end
    local function groupname(gid, entry)
        return tostring(Data.ShieldGroupNames[tonumber(gid)] or (type(entry) == 'table' and entry.Name) or gid)
    end
    local function enabled(name)
        return Toggles[name] and Toggles[name].Value
    end
    local whitelisted = shieldiswhitelisted(Player, membership)
    local flags, kickflags, notices, modnames, repnames, leaveReasons = {}, {}, {}, {}, {}, {}
    local confirmLeave = enabled('shield_confirm_leave') and not whitelisted
    local function notice(text, duration, leaveReason)
        if confirmLeave and leaveReason then
            leaveReasons[#leaveReasons + 1] = leaveReason
            return
        end
        notices[#notices + 1] = { text, duration }
    end
    local function kicknow()
        if not Data.ShieldConfigReady then
            return true
        end
        if whitelisted or #kickflags == 0 or not enabled('shield_kick') or not enabled('shield_enable') then
            return false
        end
        if revision and revision ~= Data.ShieldRevision then
            return true
        end
        if Player.Parent ~= Players then
            return true
        end
        if confirmLeave then
            return false
        end
        local seen, uniq = {}, {}
        for _, flag in ipairs(kickflags) do
            if not seen[flag] then
                seen[flag] = true
                uniq[#uniq + 1] = flag
            end
        end
        LocalPlayer:Kick(
            'User: '
                .. tag
                .. '\nId: '
                .. tostring(Player.UserId)
                .. '\n\nFlags:\n'
                .. table.concat(uniq, '\n')
                .. '\n\nProtection: flagged player detected.'
        )
        return true
    end
    if S.MarkedIds[Player.UserId] then
        flags[#flags + 1] = 'reporter list'
        if enabled('shield_notify_marked') then
            if confirmLeave then
                leaveReasons[#leaveReasons + 1] = 'a reporter'
            else
                notice('reporter joined: ' .. tag, 8)
            end
        end
        if enabled('shield_kick_marked') then
            kickflags[#kickflags + 1] = 'reporter list'
        end
        if kicknow() then
            return
        end
    end
    for gid, entry in pairs(S.KickGroups) do
        local ok, ing = membership(gid)
        if ok and ing then
            local name = groupname(gid, entry)
            flags[#flags + 1] = 'member of ' .. name
            modnames[#modnames + 1] = name
            if confirmLeave and enabled('shield_notify_groups') then
                leaveReasons[#leaveReasons + 1] = 'a member of ' .. name
            end
            if enabled('shield_kick_groups') then
                kickflags[#kickflags + 1] = 'member of ' .. name
            end
            if enabled('shield_kick_mods') then
                kickflags[#kickflags + 1] = 'moderator in ' .. name
            end
            if kicknow() then
                return
            end
        end
    end
    for gid, g in pairs(S.ModGroups) do
        local ok, ing = membership(gid)
        if ok and ing and type(g) == 'table' then
            local name = groupname(gid, g)
            local groupKick = g.Kick and enabled('shield_kick_groups')
            if g.Kick and (groupKick or enabled('shield_kick_mods')) then
                kickflags[#kickflags + 1] = 'moderator in ' .. name
                if kicknow() then
                    return
                end
            end
            local role = not groupKick and roleof(gid) or ''
            local forbidden = type(g.Forbidden) == 'table' and table.find(g.Forbidden, role)
            if g.Kick or forbidden then
                local flag = 'member of ' .. name .. (not groupKick and forbidden and (' as ' .. tostring(role)) or '')
                if groupKick or forbidden then
                    flags[#flags + 1] = flag
                end
                modnames[#modnames + 1] = name .. (not g.Kick and (' as ' .. tostring(role)) or '')
                if groupKick or (forbidden and enabled('shield_kick_forbidden')) then
                    kickflags[#kickflags + 1] = flag
                end
                if enabled('shield_kick_mods') then
                    kickflags[#kickflags + 1] = 'moderator in ' .. name
                end
                if kicknow() then
                    return
                end
                if not groupKick and not forbidden and enabled('shield_notify_groups') then
                    if type(g.NotifyRoles) == 'table' and table.find(g.NotifyRoles, role) then
                        notice(
                            'group member: ' .. tag .. ' ' .. tostring(role) .. ' in ' .. name,
                            6,
                            'a ' .. tostring(role) .. ' in ' .. name
                        )
                    elseif g.Notify then
                        notice('group member: ' .. tag .. ' in ' .. name, 6, 'a member of ' .. name)
                    end
                end
            elseif enabled('shield_notify_groups') then
                if type(g.NotifyRoles) == 'table' and table.find(g.NotifyRoles, role) then
                    notice(
                        'group member: ' .. tag .. ' ' .. tostring(role) .. ' in ' .. name,
                        6,
                        'a ' .. tostring(role) .. ' in ' .. name
                    )
                elseif g.Notify then
                    notice('group member: ' .. tag .. ' in ' .. name, 6, 'a member of ' .. name)
                end
            end
        end
    end
    for gid, entry in pairs(S.ReporterGroups) do
        local ok, ing = membership(gid)
        if ok and ing then
            local name = groupname(gid, entry)
            repnames[#repnames + 1] = name
            if confirmLeave and enabled('shield_notify_reporters') then
                leaveReasons[#leaveReasons + 1] = 'a reporter in ' .. name
            end
            if enabled('shield_kick_reporters') then
                kickflags[#kickflags + 1] = 'reporter in ' .. name
                if kicknow() then
                    return
                end
            end
        end
    end
    if enabled('shield_notify_groups') then
        for gid, entry in pairs(S.NotifyGroups) do
            local ok, ing = membership(gid)
            if ok and ing then
                local name = groupname(gid, entry)
                notice('group member: ' .. tag .. ' in ' .. name, 6, 'a member of ' .. name)
            end
        end
    end
    if revision and revision ~= Data.ShieldRevision then
        return
    end
    if not enabled('shield_enable') or Player.Parent ~= Players then
        return
    end
    local leavePrompt = false
    if confirmLeave and (#leaveReasons > 0 or (enabled('shield_kick') and #kickflags > 0)) then
        leavePrompt = true
        local seen, reasons = {}, {}
        for _, reason in ipairs(#leaveReasons > 0 and leaveReasons or kickflags) do
            if not seen[reason] then
                seen[reason] = true
                reasons[#reasons + 1] = reason
            end
        end
        if not record or not record.Notices['protection leave prompt'] then
            local approveDecline = Options.shield_prompt_buttons
                and Options.shield_prompt_buttons.Value == 'Approve / Decline'
            local description = #leaveReasons > 0 and (tag .. ', ' .. table.concat(reasons, ', ') .. ', has joined.')
                or (tag .. ' has joined and was flagged: ' .. table.concat(reasons, ', ') .. '.')
            local prompt = Library:NotifyActions(description .. ' Would you like to leave?', {
                {
                    Text = approveDecline and 'Approve' or 'Yes',
                    Callback = function()
                        if
                            Library.Unloaded
                            or Data.SharedSignalsClosed
                            or Player.Parent ~= Players
                            or not enabled('shield_enable')
                        then
                            return
                        end
                        if shieldiswhitelisted(Player) then
                            return
                        end
                        LocalPlayer:Kick(
                            'You chose to leave because ' .. tag .. ' joined.\nReason: ' .. table.concat(reasons, ', ')
                        )
                    end,
                },
                {
                    Text = approveDecline and 'Decline' or 'No',
                    Callback = function()
                        if record then
                            record.LeavePrompt = nil
                        end
                    end,
                },
            })
            if record then
                record.LeavePrompt = prompt
                record.Notices['protection leave prompt'] = true
            end
        end
    end
    if not leavePrompt and #modnames > 0 and enabled('shield_notify_mods') then
        notice('moderator here: ' .. tag .. ' ' .. table.concat(modnames, ', '), 8)
    end
    if not leavePrompt and #repnames > 0 and enabled('shield_notify_reporters') then
        notice('reporter here: ' .. tag .. ' ' .. table.concat(repnames, ', '), 8)
    end
    if S.StalkUsers[Player.UserId] and enabled('shield_notify_stalkers') then
        notice('stalker here: ' .. tag .. ' ' .. tostring(S.StalkUsers[Player.UserId]), 8)
    end
    if enabled('shield_notify_stalkgroups') then
        local matched = {}
        for gid in pairs(S.StalkGroups) do
            local ok, ing = membership(gid)
            if ok and ing then
                matched[#matched + 1] = groupname(gid) .. ' as ' .. tostring(roleof(gid))
            end
        end
        if #matched > 0 then
            table.sort(matched)
            notice(
                Player.DisplayName .. ' ' .. Player.Name .. ' has joined and is in ' .. table.concat(matched, ', '),
                8
            )
        end
    end
    if revision and revision ~= Data.ShieldRevision then
        return
    end
    if not enabled('shield_enable') or Player.Parent ~= Players then
        return
    end
    for _, message in ipairs(notices) do
        notify(message[1], message[2])
    end
    if #flags > 0 then
        if whitelisted then
            if enabled('shield_notify_whitelisted') then
                notify('whitelisted with flags: ' .. tag .. ' ' .. table.concat(flags, ' | '), 8)
            end
        elseif not leavePrompt then
            notify('flagged: ' .. tag .. ' ' .. table.concat(flags, ' | '), 8)
        end
        return failed
    end
    if not whitelisted and enabled('shield_notify_joins') then
        notify(tag .. ' joined', 4)
    end
    return failed
end
function phowg:start_protection_check(player, allowConfig)
    if not player or player == LocalPlayer or player.Parent ~= Players or Data.SharedSignalsClosed then
        return
    end
    if not Data.StartupReady or not Data.ShieldConfigReady or Library.SuppressSave and not allowConfig then
        Data.ShieldPendingPlayers = Data.ShieldPendingPlayers or {}
        Data.ShieldPendingPlayers[player] = true
        return
    end
    if not (Toggles.shield_enable and Toggles.shield_enable.Value) then
        return
    end
    Data.ShieldChecks = Data.ShieldChecks or {}
    Data.ShieldRevision = Data.ShieldRevision or 0
    local record: { [string]: any }? = Data.ShieldChecks[player]
    if record then
        if record.Worker or record.Queued or record.Completed or record.RetryThread then
            return
        end
    else
        record = {
            Completed = false,
            Worker = nil,
            RetryThread = nil,
            Failures = 0,
            Memberships = {},
            Roles = {},
            Notices = {},
        }
        Data.ShieldChecks[player] = record
    end
    record.Queued = true
    phowg:queue_background('protection', player, function()
        record.Queued = false
        if
            player.Parent ~= Players
            or Data.SharedSignalsClosed
            or Data.ShieldChecks[player] ~= record
            or not (Toggles.shield_enable and Toggles.shield_enable.Value)
        then
            return
        end
        local worker = coroutine.create(function()
            Data.ShieldActiveChecks = (Data.ShieldActiveChecks or 0) + 1
            while not record.Completed and not Data.SharedSignalsClosed do
                local requested = Data.ShieldRevision
                local ok, retry = pcall(shieldcheck, player, requested, record)
                if player.Parent ~= Players or Data.ShieldChecks[player] ~= record then
                    break
                end
                if not Data.ShieldConfigReady then
                    Data.ShieldPendingPlayers = Data.ShieldPendingPlayers or {}
                    Data.ShieldPendingPlayers[player] = true
                    break
                end
                if requested ~= Data.ShieldRevision then
                    continue
                end
                record.Completed = true
                if not ok or retry then
                    record.Failures += 1
                    record.RetryThread = task.delay(math.min(60, 5 * 2 ^ math.min(record.Failures - 1, 4)), function()
                        record.RetryThread = nil
                        if
                            Data.SharedSignalsClosed
                            or Data.ShieldChecks[player] ~= record
                            or player.Parent ~= Players
                        then
                            return
                        end
                        record.Completed = false
                        phowg:start_protection_check(player)
                    end)
                    if record.Failures >= 3 and tick() - (Data.ShieldLookupWarningAt or -math.huge) >= 60 then
                        Data.ShieldLookupWarningAt = tick()
                        warn(
                            '[Phowg] protection lookup unavailable; retrying in background: '
                                .. tostring(ok and (record.GroupError or Data.ShieldGroupError) or retry)
                        )
                    end
                elseif ok then
                    record.Failures = 0
                end
            end
            Data.ShieldActiveChecks = math.max(0, (Data.ShieldActiveChecks or 1) - 1)
            record.Worker = nil
        end)
        record.Worker = worker
        task.spawn(worker)
    end)
end
function phowg:recheck_protection()
    Data.ShieldRevision = (Data.ShieldRevision or 0) + 1
    for _, player in ipairs(Players:GetPlayers()) do
        local record = Data.ShieldChecks and Data.ShieldChecks[player]
        if record then
            record.Completed = false
            if record.RetryThread then
                pcall(task.cancel, record.RetryThread)
                record.RetryThread = nil
            end
        end
        phowg:start_protection_check(player)
    end
    phowg:flush_protection_checks()
end
function phowg:flush_protection_checks(allowConfig)
    if
        not Data.StartupReady
        or not Data.ShieldConfigReady
        or Library.SuppressSave and not allowConfig
        or Data.SharedSignalsClosed
    then
        return
    end
    if not (Toggles.shield_enable and Toggles.shield_enable.Value) then
        return
    end
    if not Data.ShieldInitialScanDone then
        Data.ShieldInitialScanDone = true
        for _, player in ipairs(Players:GetPlayers()) do
            phowg:start_protection_check(player, allowConfig)
        end
    end
    local pending = Data.ShieldPendingPlayers
    Data.ShieldPendingPlayers = nil
    for player in pairs(pending or {}) do
        phowg:start_protection_check(player, allowConfig)
    end
end
phowg:register_cleanup('protection checks', function(scope, reason)
    if reason ~= 'unload' and scope == LocalPlayer.Character then
        return
    end
    if reason == 'unload' then
        Data.ShieldPendingPlayers = nil
    elseif Data.ShieldPendingPlayers then
        Data.ShieldPendingPlayers[scope] = nil
    end
    for player, record in pairs(Data.ShieldChecks or {}) do
        if reason == 'unload' or scope == player then
            if record.LeavePrompt then
                record.LeavePrompt:Dismiss()
            end
            if record.RetryThread then
                pcall(task.cancel, record.RetryThread)
            end
            if record.Worker then
                if record.Worker ~= coroutine.running() then
                    pcall(task.cancel, record.Worker)
                end
                Data.ShieldActiveChecks = math.max(0, (Data.ShieldActiveChecks or 1) - 1)
            end
            Data.ShieldChecks[player] = nil
        end
    end
end)
function phowg:start_loop(key, callback)
    if Library.Unloaded or Data.SharedSignalsClosed or Data.LoopTokens[key] then
        return
    end
    local token = {}
    Data.LoopTokens[key] = token
    Data.LoopThreads = Data.LoopThreads or {}
    local thread = coroutine.create(function()
        local ok, problem = pcall(callback)
        if Data.LoopTokens[key] == token then
            Data.LoopTokens[key], Data.LoopThreads[key] = nil, nil
        end
        if ok then
            if Data.LoopErrors then Data.LoopErrors[key] = nil end
        elseif not Library.Unloaded and not Data.SharedSignalsClosed then
            Data.LoopErrors = Data.LoopErrors or {}
            Data.LoopErrors[key] = (Data.LoopErrors[key] or 0) + 1
            warn('[phowg] loop ' .. key .. ': ' .. tostring(problem))
        end
    end)
    Data.LoopThreads[key] = thread
    task.spawn(thread)
end
phowg:register_cleanup('loops', function(scope)
    if scope then
        return
    end
    for key, thread in pairs(Data.LoopThreads or {}) do
        if thread ~= coroutine.running() then
            pcall(task.cancel, thread)
        end
        Data.LoopTokens[key] = nil
    end
    table.clear(Data.LoopThreads or {})
end)
phowg:register_cleanup('heartbeat jobs', function(scope)
    for _, job in pairs(Data.HeartbeatJobs) do
        if not scope or (job.Scope == scope and job.Running) then
            if job.Worker and job.Worker ~= coroutine.running() then
                pcall(task.cancel, job.Worker)
            end
            job.Worker = nil
            job.Scope = nil
            job.Running = false
            job.First = true
        end
    end
end)
phowg:register_cleanup('character state', function(scope)
    if scope and scope ~= Data.ManagedCharacter and scope ~= LocalPlayer.Character then
        return
    end
    Data.IsRespawning = scope ~= nil
    if scope then
        updatesuspension()
    end
    Data._CSyncResetGen += 1
    phowg:cancel_c_frame_movement()
    table.clear(Data.CSync.Queue)
    Data.CSync.PendingCF = nil
    for name in pairs(Data.MoveToHolds or {}) do
        stopmovetohold(name)
    end
    table.clear(Data.MovementOverrides or {})
    Data.MoveToActive = false
    Data.MoveToTargetCF = nil
    Data.AppliedServerCF = nil
    Data.AppliedServerAt = nil
    Data.AppliedServerTag = nil
    Data.DisplayCF = nil
    Data.LastServerCF = nil
    Data.CSyncTable[2] = false
    Data.CSyncTable[1] = CFrame.new()
    phowg:finish_purchases(Data.PurchaseBatch, true)
    Data.Buying = false
    Data.BuyingSupportTarget = nil
    Data.ReloadedAwait = {}
    Data.GrippedTools = {}
    Data.CombatArrivalAt = nil
    Data.CombatArrivalLastAt = nil
    Data.StompHideTarget, Data.StompHideCharacter = nil, nil
    Data.RPGReturnCF = nil
    stoprpgmove(false)
    hidevisualizer()
    stoprapidfire()
    phowg:restore_tool_sounds(scope or Data.ToolCharacter)
    for _, connection in pairs(Data.LocalToolConns or {}) do
        connection:Disconnect()
    end
    Data.LocalToolConns = {}
    Data.ToolObservers = nil
    Data.ToolCharacter = nil
    Data.ToolAddedConnection = nil
    phowg:clear_local_data(scope)
    Local_Data.Current_Gun = nil
    Local_Data.Ammo = nil
    Local_Data.MaxAmmo = nil
    if clearlettuceprogress then
        clearlettuceprogress()
    end
end)
function phowg:bind_player_lifecycle(player)
    Data.LifecyclePlayers = Data.LifecyclePlayers or setmetatable({}, { __mode = 'k' })
    if Data.LifecyclePlayers[player] then
        return
    end
    Data.LifecyclePlayers[player] = true
    connectshared(player.CharacterRemoving, function(character)
        phowg:cleanup_scope(character, 'respawn')
    end, player, 'lifecycle/character removed', -200, 'event/CharacterRemoving', player)
    if player == LocalPlayer then
        Data.ManagedCharacter = player.Character
        connectshared(player.CharacterAdded, function(character)
            local previous = Data.ManagedCharacter
            if previous and previous ~= character and not Data.RetiredScopes[previous] then
                phowg:cleanup_scope(previous, 'respawn')
            end
            Data.ManagedCharacter = character
            Data.IsRespawning = true
        end, player, 'lifecycle/character added', -200, 'event/CharacterAdded', player)
    end
end
function phowg:stop_runtime_features()
    if Data.FeaturesStopped then
        return
    end
    Data.FeaturesStopped = true
    Data.Unloading = true
    Library.SuppressSave = true
    local function stop(callback, ...)
        local ok, problem = pcall(callback, ...)
        if not ok then
            Data.UnloadErrors = Data.UnloadErrors or {}
            Data.UnloadErrors[#Data.UnloadErrors + 1] = tostring(problem)
            warn('[phowg] unload cleanup: ' .. tostring(problem))
        end
    end
    if not Data.UnloadBlockReleased and MainEvent then
        Data.UnloadBlockReleased = true
        pcall(function()
            MainEvent:FireServer('Block', false)
        end)
    end
    Data['RPGUnloading'] = true
    for name in pairs(Data['MoveToHolds'] or {}) do
        stop(stopmovetohold, name)
    end
    if setdeflectrpg then
        stop(setdeflectrpg, false)
    end
    for name, tg in pairs(Toggles) do
        if name ~= 'KeybindIndicator' and name ~= 'ReducedMotion' and tg and tg.Value then
            stop(tg.SetValue, tg, false)
        end
    end
    stop(stoprapidfire)
    stop(stopflingstate)
    for name in pairs(Data['GunModuleHooks'] or {}) do
        stop(stopgunmodulehook, name)
    end
    stop(phowg_callbacks.cleanup_scope, nil, 'unload')
    for k, _ in pairs(Data['LoopTokens']) do
        Data['LoopTokens'][k] = nil
    end
    Data['VoidActive'] = false
    Data['UndergroundActive'] = false
    Data['DesyncActive'] = false
    Data['CurrentStatus'] = 'Idle'
    Data['CurrentActionTarget'] = nil
end
function phowg:china_hat_settings()
    local function value(name, default)
        local option = Options[name]
        return option and option.Value or default
    end
    local settings = {
        Radius = math.clamp(tonumber(value('china_hat_radius', 2.25)) or 2.25, 0.5, 5),
        Height = math.clamp(tonumber(value('china_hat_height', 1.25)) or 1.25, 0.2, 3),
        Offset = math.clamp(tonumber(value('china_hat_offset', 0.08)) or 0.08, -0.5, 3),
        Layers = math.floor(math.clamp(tonumber(value('china_hat_layers', 40)) or 40, 12, 48)),
        Transparency = math.clamp(tonumber(value('china_hat_transparency', 0)) or 0, 0, 0.9),
        Style = value('china_hat_color_style', 'solid'),
        Speed = math.clamp(tonumber(value('china_hat_speed', 1)) or 1, 0.1, 5),
        Secondary = value('china_hat_secondary', Color3.fromRGB(110, 80, 255)),
    }
    local materials = {
        forcefield = Enum.Material.ForceField,
        neon = Enum.Material.Neon,
        glass = Enum.Material.Glass,
        metal = Enum.Material.Metal,
        plastic = Enum.Material.SmoothPlastic,
    }
    settings.Material = materials[value('china_hat_material', 'forcefield')] or Enum.Material.ForceField
    settings.Geometry = table.concat({ settings.Radius, settings.Height, settings.Offset, settings.Layers }, '|')
    return settings
end
function phowg:china_hat_layer_color(color, index, layers, settings, now)
    local fraction = (index - 1) / math.max(1, layers - 1)
    if settings.Style == 'gradient' then
        return color:Lerp(settings.Secondary, fraction)
    end
    if settings.Style == 'rainbow' then
        return Color3.fromHSV((now * settings.Speed * 0.2 + fraction * 0.35) % 1, 0.85, 1)
    end
    if settings.Style == 'pulse' then
        return color:Lerp(settings.Secondary, (math.sin(now * settings.Speed * math.pi * 2) + 1) * 0.5)
    end
    return color
end
function phowg:china_hat_part_c_frame(headCF, headHeight, index, layers, settings)
    settings = settings or phowg:china_hat_settings()
    local fraction = (index - 1) / layers
    return headCF
        * CFrame.new(0, headHeight * 0.5 + settings.Offset + fraction * settings.Height, 0)
        * CFrame.Angles(0, 0, math.pi / 2)
end
function phowg:update_china_hat_visibility()
    local state = Data.AfterimageStates and Data.AfterimageStates['local player']
    if not Data.ChinaHats and not (state and state.HadHat) then
        return
    end
    local character, camera = LocalPlayer.Character, Workspace.CurrentCamera
    local head = character and character:FindFirstChild('Head')
    local root = character and character:FindFirstChild('HumanoidRootPart')
    local hidden = false
    if head and camera then
        local headPosition = head.Position
        if root and (Data.CSyncTable[2] or Data.MoveToInFlight == root) and typeof(Data.CSyncTable[1]) == 'CFrame' then
            headPosition = (Data.CSyncTable[1] * root.CFrame:ToObjectSpace(head.CFrame)).Position
        end
        local distance = (camera.CFrame.Position - headPosition).Magnitude
        hidden = distance < (Data.ChinaHatFirstPerson and 3.25 or 2.75)
    end
    Data.ChinaHatFirstPerson = hidden
    local entry = head and Data.ChinaHats and Data.ChinaHats[head]
    if entry and entry.Hidden ~= hidden then
        for _, part in ipairs(entry.parts or {}) do
            if part.Parent then
                part.LocalTransparencyModifier = hidden and 1 or 0
            end
        end
        entry.Hidden = hidden
    end
    if state then
        for _, slot in ipairs(state.Slots) do
            if slot.HatHidden ~= hidden then
                for _, part in ipairs(slot.HatParts or {}) do
                    if part.Parent then
                        part.LocalTransparencyModifier = hidden and 1 or 0
                    end
                end
                slot.HatHidden = hidden
            end
        end
    end
end
function createchinahatparts(head, parent, color, anchored, settings)
    settings = settings or phowg:china_hat_settings()
    local parts = {}
    local layers = settings.Layers
    local height = settings.Height
    local now = tick()
    for index = 1, layers do
        local fraction = (index - 1) / layers
        local radius = settings.Radius * (1 - fraction)
        local part = Instance.new('Part')
        part.Name = 'ChinaHat' .. index
        part.Shape = Enum.PartType.Cylinder
        part.Size = Vector3.new(height / layers + 0.005, radius * 2, radius * 2)
        part.Material = settings.Material
        part.Color = phowg:china_hat_layer_color(color, index, layers, settings, now)
        part.Transparency = settings.Transparency
        part.Anchored = true
        part.CanCollide = false
        part.CanQuery = false
        part.CanTouch = false
        part.CastShadow = false
        part.Massless = true
        part.CFrame = phowg:china_hat_part_c_frame(head.CFrame, head.Size.Y, index, layers, settings)
        part.Parent = parent
        if not anchored then
            local weld = Instance.new('WeldConstraint')
            weld.Part0 = head
            weld.Part1 = part
            weld.Parent = part
            part.Anchored = false
        end
        parts[index] = part
    end
    return parts
end
