registerheartbeat('MovementState', function()
    if Data['CSyncTable'][2] and tick() - (Data['LastMoveToAt'] or 0) > 1.2 then
        Data['CSyncTable'][2] = false
    end
    if
        Data['MoveToActive']
        and (tick() - (Data['MoveToLastAt'] or 0) >= 0.35)
        and (not Data['CSync'] or not Data['CSync'].Queue or #Data['CSync'].Queue == 0)
    then
        Data['MoveToActive'] = false
        Data['MoveToTargetCF'] = nil
    end
    if Data['Buying'] and tick() - (Data['BuyingSince'] or 0) > 25 then
        Data['Buying'] = false
        Data['MaskBuying'] = nil
        if Data['CSync'] and Data['CSync'].Queue then
            for i = #Data['CSync'].Queue, 1, -1 do
                if Data['CSync'].Queue[i].tag == 'Buy' then
                    table.remove(Data['CSync'].Queue, i)
                end
            end
        end
    end
    local char = LocalPlayer.Character
    local hrp = char and char:FindFirstChild('HumanoidRootPart') or nil
    if hrp and hrp.Parent and not Data['IsRespawning'] then
        local cf = nil
        if Data['CSyncTable'][2] then
            local stash = Data['CSyncTable'][1]
            if typeof(stash) == 'CFrame' then
                cf = stash
            end
        else
            cf = hrp.CFrame
        end
        if cf and cf.Position.Magnitude < 10000 then
            Local_Data['ClientPos'] = cf
            getgenv().PhowgClientPos = cf
        end
    end
end, nil, nil, true)
