function phowg:add_main_fov_settings(group, prefix)
    group
        :AddToggle(prefix .. '_show_fov', { Text = 'show fov', Default = false })
        :AddColorPicker(prefix .. '_fov_color', { Default = Color3.new(1, 1, 1), Title = 'fov color' })
        :AddColorPicker(
            prefix .. '_fov_fill_color',
            { Default = Color3.new(1, 1, 1), Title = 'filled color', Transparency = 0.85 }
        )
        :AddColorPicker(prefix .. '_fov_outline_color', { Default = Color3.new(1, 1, 1), Title = 'outline color' })
    local settings = group:AddDependencyBox()
    settings:SetupDependencies({ { Toggles[prefix .. '_show_fov'], true } })
    settings:AddToggle(prefix .. '_fov_filled', { Text = 'filled', Default = false })
    settings:AddToggle(prefix .. '_fov_outline', { Text = 'outline', Default = false })
    group:AddToggle(prefix .. '_closest_part', { Text = 'closest part', Default = false })
    group:AddToggle(prefix .. '_match_y', { Text = 'match y axis', Default = false })
end
