Data.KillAuraAdvancedBox = Data.Tabs.Misc:AddLeftGroupbox('kill aura settings')
function killauravalidtarget(plr)
    if not plr or plr == LocalPlayer then
        return false
    end
    local zombie = phowg:is_zombie_target(plr)
    local playersOnly = not Toggles.kill_aura_players_only or Toggles.kill_aura_players_only.Value == true
    if playersOnly then
        if zombie or typeof(plr) ~= 'Instance' or not plr:IsA('Player') then
            return false
        end
    elseif not zombie then
        return false
    end
    if iswhitelistedplayer(plr) or iscrewwhitelisted(plr) then
        return false
    end
    if Data['RageWhitelist'] and Data['RageWhitelist'][plr] then
        return false
    end
    local myCrew = getplayercrewid(LocalPlayer)
    local theirCrew = getplayercrewid(plr)
    if myCrew and theirCrew and tostring(myCrew) == tostring(theirCrew) then
        return false
    end
    if not intelligence:get_character_cache(plr) then
        return false
    end
    if isknocked(plr) or isdead(plr) then
        return false
    end
    if plr.Character:FindFirstChildOfClass('ForceField') then
        return false
    end
    return true
end
function killaurawallcheck(plr)
    if not (Toggles.kill_aura_wall_check and Toggles.kill_aura_wall_check.Value) then
        return true
    end
    if not (plr and plr.Character) then
        return false
    end
    if Data.WallbangIgnored then
        return gunwallclear(plr, getsilentorigin())
    end
    return ispartvisiblefrom(getsilentorigin(), plr.Character)
end
function killaurafindtarget(Radius)
    if Data['PunishmentGunActive'] then
        local iSel = phowg:auto_kill_gun_mode()
        local kSel = normalizeweaponname((Options.kill_aura_weapon and Options.kill_aura_weapon.Value) or 'aug')
        if iSel ~= kSel then
            return nil
        end
    end
    local myChar = LocalPlayer.Character
    local myRoot = myChar and myChar:FindFirstChild('HumanoidRootPart')
    if not myRoot then
        return nil
    end
    local myPos = (Local_Data['ClientPos'] and Local_Data['ClientPos'].Position) or myRoot.CFrame.Position
    local cands = {}
    local zombiesOnly = Toggles.kill_aura_players_only and not Toggles.kill_aura_players_only.Value
    for _, plr in ipairs(phowg:aim_candidates(zombiesOnly, zombiesOnly)) do
        if killauravalidtarget(plr) then
            local root = plr.Character:FindFirstChild('HumanoidRootPart')
            if root then
                local dist = (myPos - root.Position).Magnitude
                if dist <= Radius then
                    cands[#cands + 1] = { plr = plr, d = dist }
                end
            end
        end
    end
    if #cands == 0 then
        return nil
    end
    table.sort(cands, function(a, b)
        return a.d < b.d
    end)
    for _, e in ipairs(cands) do
        if killaurawallcheck(e.plr) then
            return e.plr
        end
    end
    return nil
end
function killaurafindgun()
    local tool = getweapontool(Options.kill_aura_weapon and Options.kill_aura_weapon.Value or 'aug')
    if tool and istoolvalid(tool) then
        return tool
    end
    return nil
end
function killaurabusy()
    if not rageboton() then
        return false
    end
    local status = Data['CurrentStatus']
    if status == nil or status == '' or status == 'Idle' then
        return false
    end
    return intelligence:get_character_cache(Data['CurrentActionTarget'])
end
function phowg:kill_aura_in_void()
    local character = LocalPlayer.Character
    local root = character and character:FindFirstChild('HumanoidRootPart')
    if not root then
        return true
    end
    if Data.VoidActive or reloadvoidactive() or phowg.ragebot_idle_hiding and phowg:ragebot_idle_hiding(Data.RagebotIdle) then
        return true
    end
    local pose = root.CFrame
    if Data.AppliedServerCharacter == character and typeof(Data.AppliedServerCF) == 'CFrame' then
        local tag = Data.AppliedServerTag
        if
            tag == 'Void'
            or tag == 'VoidTwitch'
            or tag == 'ReloadVoid'
            or tag == 'RagebotVoid'
            or tag == 'RagebotIdle'
            or tag == 'PurchaseVoidReturn'
        then
            return true
        end
        pose = Data.AppliedServerCF
    end
    local position = pose.Position
    return position.X ~= position.X
        or position.Y ~= position.Y
        or position.Z ~= position.Z
        or position.Magnitude >= 50000
        or position.Y <= -1000
        or position.Y >= 20000
end
function phowg:cancel_kill_aura_purchase()
    local state = Data.KillAuraPurchase
    if not state then
        return
    end
    state.Cancelled = true
    Data.KillAuraPurchase = nil
    if not state.Thread or state.Thread == coroutine.running() then
        return
    end
    local batch = Data.PurchaseBatch
    if batch and batch.Owner == state.Thread then
        local batchShared = #(batch.Producers or {}) > 0
        for _, purchaseRequest in pairs(batch.Requests or {}) do
            if not purchaseRequest.Done and purchaseRequest.ShouldContinue ~= state.Valid then
                batchShared = true
                break
            end
        end
        if batchShared then
            return
        end
        phowg:finish_purchases(batch, true)
    end
    pcall(task.cancel, state.Thread)
end
function phowg:ensure_kill_aura_gun()
    local tool = killaurafindgun()
    if tool then
        return tool
    end
    if
        not killauraenabled()
        or localactionblocked()
        or killaurabusy()
        or Library.Unloaded
        or Data.SharedSignalsClosed
    then
        return nil
    end
    local query = normalizeweaponname(Options.kill_aura_weapon and Options.kill_aura_weapon.Value or 'aug')
    local character = LocalPlayer.Character
    local current = Data.KillAuraPurchase
    if current and (current.Query ~= query or current.Character ~= character) then
        phowg:cancel_kill_aura_purchase()
        current = nil
    end
    if current and (current.Thread or tick() < (current.RetryAt or 0)) or Data.Buying or Data.PurchaseBatch then
        return nil
    end
    local state = { Character = character, Query = query, RetryAt = math.huge, Cancelled = false }
    Data.KillAuraPurchase = state
    state.Valid = function()
        return Data.KillAuraPurchase == state
            and not state.Cancelled
            and LocalPlayer.Character == character
            and killauraenabled()
            and not localactionblocked()
            and not killaurabusy()
            and not Library.Unloaded
            and not Data.SharedSignalsClosed
            and normalizeweaponname(Options.kill_aura_weapon and Options.kill_aura_weapon.Value or 'aug') == query
            and not getweapontool(query)
    end
    state.Thread = coroutine.create(function()
        local ok, result = pcall(purchase_item, query, Data.PRIO.KNIFE, 1, true, nil, state.Valid)
        state.Thread = nil
        state.RetryAt = tick() + (ok and result and 0.5 or 3)
        if not ok then
            warn('[Phowg] kill aura purchase: ' .. tostring(result))
        end
    end)
    task.spawn(state.Thread)
    return nil
end
phowg:register_cleanup('kill aura purchase', function(scope, reason)
    local state = Data.KillAuraPurchase
    if state and (reason == 'unload' or not scope or scope == state.Character) then
        phowg:cancel_kill_aura_purchase()
    end
end)
function killauraworker()
    while killauraenabled() do
        if localactionblocked() then
            phowg:stop_gun_fire('KillAura')
            task.wait(0.05)
            continue
        end
        if killaurabusy() or isreloading() then
            phowg:stop_gun_fire('KillAura')
            task.wait()
        else
            local readyTool = phowg:ensure_kill_aura_gun()
            if not readyTool then
                phowg:stop_gun_fire('KillAura')
                Data.KillAuraTarget = nil
                task.wait(0.1)
                continue
            end
            local radius = (Options.kill_aura_radius and Options.kill_aura_radius.Value) or 50
            if Toggles.full_rage and Toggles.full_rage.Value then
                radius = 500
            end
            local target = killaurafindtarget(radius)
            if not target then
                task.wait(0.1)
            else
                local tool = readyTool
                if not tool or not istoolvalid(tool) then
                    task.wait()
                else
                    if tool.Parent ~= LocalPlayer.Character then
                        equip(tool)
                        task.wait(0.05)
                    end
                    Data['KillAuraTarget'] = target
                    local deadline = tick() + 3
                    while tick() < deadline and killauraenabled() and tool.Parent == LocalPlayer.Character do
                        if killaurabusy() or localactionblocked() or not killauravalidtarget(target) then
                            break
                        end
                        if Toggles.full_rage and Toggles.full_rage.Value and not isreloading() then
                            local mode = Options.target_strafe_mode and Options.target_strafe_mode.Value or 'orbit'
                            local strafe = getgunstrafecframe(target, tool, mode)
                            if strafe then
                                set_server_cframe(strafe, nil, Data['PRIO'].KNIFE, 'KillAura')
                            else
                                releasemovement('KillAura')
                            end
                        else
                            releasemovement('KillAura')
                        end
                        if
                            Toggles.kill_aura_smart
                            and Toggles.kill_aura_smart.Value
                            and tick() - (Data['AuraSwapAt'] or 0) > 1
                        then
                            local am = tool:FindFirstChild('Ammo')
                            if am and am.Value <= 0 then
                                local nxt = nil
                                for _, nm in ipairs({ 'smg', 'p90', 'ak47' }) do
                                    local cand = findtoolbypattern(nm)
                                    if cand and cand ~= tool and istoolvalid(cand) then
                                        local ca = cand:FindFirstChild('Ammo')
                                        if not ca or ca.Value > 0 then
                                            nxt = cand
                                            break
                                        end
                                    end
                                end
                                if not nxt then
                                    local bp = LocalPlayer:FindFirstChild('Backpack')
                                    if bp then
                                        for _, t in ipairs(bp:GetChildren()) do
                                            if t ~= tool and t:IsA('Tool') and istoolvalid(t) then
                                                local ta = t:FindFirstChild('Ammo')
                                                if not ta or ta.Value > 0 then
                                                    local okC, cl = pcall(function()
                                                        return intelligence:classify_tool(t)
                                                    end)
                                                    if okC and cl and (cl.gun or cl.shotgun or cl.automatic) then
                                                        nxt = t
                                                        break
                                                    end
                                                end
                                            end
                                        end
                                    end
                                end
                                if nxt then
                                    Data['AuraSwapAt'] = tick()
                                    phowg:stop_gun_fire('KillAura')
                                    local bp0 = LocalPlayer:FindFirstChild('Backpack')
                                    if bp0 then
                                        tool.Parent = bp0
                                    end
                                    equip(nxt)
                                    task.wait(0.05)
                                    if nxt.Parent == LocalPlayer.Character then
                                        tool = nxt
                                    end
                                end
                            end
                        end
                        if isreloading() then
                            phowg:stop_gun_fire('KillAura')
                            task.wait(0.15)
                        else
                            if
                                tick() - (Data['KillAuraWallAt'] or 0) > 0.25
                                or Data['KillAuraWallTarget'] ~= target
                            then
                                Data['KillAuraWallTarget'] = target
                                Data['KillAuraWallAt'] = tick()
                                Data['KillAuraWallOk'] = killaurawallcheck(target)
                            end
                            if not Data['KillAuraWallOk'] then
                                break
                            end
                            if phowg:kill_aura_in_void() then
                                phowg:stop_gun_fire('KillAura')
                            else
                                phowg:fire_gun('KillAura', tool, target, 0)
                            end
                            task.wait(0.02)
                        end
                    end
                    phowg:stop_gun_fire('KillAura')
                    Data['KillAuraTarget'] = nil
                    releasemovement('KillAura')
                    local backpack = LocalPlayer:FindFirstChild('Backpack')
                    if
                        tool.Parent == LocalPlayer.Character
                        and backpack
                        and not Data.Buying
                        and not Data.Sorting
                        and not Data.GunReloadSelection
                    then
                        tool.Parent = backpack
                    end
                end
            end
        end
    end
end
function killauraenabled()
    if not (Toggles.kill_aura_enabled and Toggles.kill_aura_enabled.Value) then
        return false
    end
    if not (Options.kill_aura_keybind and Options.kill_aura_keybind:GetState()) then
        return false
    end
    return true
end
function kill_aura_loop()
    if not killauraenabled() or localactionblocked() then
        phowg:cancel_kill_aura_purchase()
        phowg:stop_gun_fire('KillAura')
        Data.KillAuraTarget = nil
        releasemovement('KillAura')
        return
    end
    local purchase = Data.KillAuraPurchase
    if
        purchase
        and normalizeweaponname(Options.kill_aura_weapon and Options.kill_aura_weapon.Value or 'aug')
            ~= purchase.Query
    then
        phowg:cancel_kill_aura_purchase()
    end
    if Data['KillAuraRunning'] then
        return
    end
    Data['KillAuraRunning'] = true
    task.spawn(function()
        local ok, err = pcall(killauraworker)
        phowg:stop_gun_fire('KillAura')
        Data['KillAuraRunning'] = false
        Data['KillAuraTarget'] = nil
        releasemovement('KillAura')
        if not ok and tick() - (Data['KillAuraErrAt'] or 0) > 5 then
            Data['KillAuraErrAt'] = tick()
            warn('[Phowg] kill aura: ' .. tostring(err))
        end
    end)
end
function rapefindgun()
    return getweapontool(phowg:auto_kill_gun_mode())
end
function getrapeattacker()
    local myChar = LocalPlayer.Character
    if not myChar then
        return nil
    end
    local be = myChar:FindFirstChild('BodyEffects')
    local lastDmg = be and be:FindFirstChild('LastDamager')
    local v = lastDmg and lastDmg.Value or nil
    if v == nil then
        return nil
    end
    local damager = Players:GetPlayerFromCharacter(v)
    if damager == nil or damager == LocalPlayer then
        return nil
    end
    return damager
end
function rapestopfiring()
    phowg:stop_gun_fire('Support')
    Data['RapeTarget'] = nil
    Data['RapeAimTarget'] = nil
    Data['RapeAimAt'] = nil
    Data['RapeFiring'] = nil
end
function pickrapetarget(cands)
    local myChar = LocalPlayer and LocalPlayer.Character
    local myRoot = myChar and getroot(myChar)
    if not myRoot then
        return nil
    end
    local myPos = (Local_Data['ClientPos'] and Local_Data['ClientPos'].Position) or myRoot.Position
    local best, bestD = nil, math.huge
    for _, plr in ipairs(cands) do
        if Data['SupportCompletedTargets'] and Data['SupportCompletedTargets'][plr] then
            continue
        end
        if
            intelligence:get_character_cache(plr)
            and not isknocked(plr)
            and not isdead(plr)
            and not iscrewwhitelisted(plr)
            and not iswhitelistedplayer(plr)
            and not (Data['RageWhitelist'] and Data['RageWhitelist'][plr])
        then
            local ch = plr.Character
            if ch and not ch:FindFirstChildOfClass('ForceField') and gunwallclear(plr) then
                local r = getroot(ch)
                if r then
                    local d = (myPos - r.Position).Magnitude
                    if d < bestD then
                        bestD = d
                        best = plr
                    end
                end
            end
        end
    end
    return best
end
registerheartbeat('RapeTarget', function()
    if Data['PunishmentGunActive'] then
        rapestopfiring()
        return
    end
    if not phowg:israel_support_enabled() or not (Toggles.full_rage and Toggles.full_rage.Value) then
        rapestopfiring()
        return
    end
    local myChar = LocalPlayer.Character
    local myHum = myChar and gethumanoid(myChar)
    if not (myChar and myHum and myHum.Health > 0) then
        rapestopfiring()
        return
    end
    local cands = {}
    for plr, mode in pairs(Data['PunishmentTargets'] or {}) do
        if mode == 'stomp target' and plr and plr.Parent and plr ~= LocalPlayer then
            cands[#cands + 1] = plr
        end
    end
    local atk = getrapeattacker()
    if atk then
        local dup = false
        for _, p in ipairs(cands) do
            if p == atk then
                dup = true
                break
            end
        end
        if not dup then
            cands[#cands + 1] = atk
        end
    end
    local tgt = pickrapetarget(cands)
    Data['RapeTarget'] = tgt
    if not tgt or phowg:support_armor_blocked(tgt) then
        rapestopfiring()
        return
    end
    local tRoot = tgt.Character and tgt.Character:FindFirstChild('HumanoidRootPart')
    if not (tRoot and tRoot.Parent) then
        rapestopfiring()
        return
    end
    if phowg:support_multi_selected(tgt, 'Support') then
        phowg:prepare_support_loadout(tgt, 'Support')
    end
    local aug = rapefindgun()
    if aug and aug.Parent ~= myChar then
        equip(aug)
        return
    end
    local eq = aug
    local rsel = phowg:auto_kill_gun_mode()
    local reqOk = eq and normalizeweaponname(eq.Name) == rsel
    if not reqOk then
        rapestopfiring()
        return
    end
    local tp = predpos(tRoot.Position, tgt.Character, 2.5, nil, true)
    local pos = tp + Vector3.new(math.random(-10, 10), math.random(-10, 10), math.random(-10, 10))
    set_server_cframe(
        CFrame.new(pos) * getstraferotation('random', getroot(myChar)),
        nil,
        Data['PRIO'].PUNISH,
        'Combat'
    )
    if Data['RapeAimTarget'] ~= tgt then
        Data['RapeAimTarget'] = tgt
        Data['RapeAimAt'] = tick()
    end
    local am = eq:FindFirstChild('Ammo')
    if eq.Parent == myChar and (not am or am.Value > 0) and tick() - (Data['RapeAimAt'] or 0) >= 0.5 then
        Data['RapeFiring'] = phowg:fire_gun('Support', eq, tgt, 0.12)
    else
        phowg:stop_gun_fire('Support')
        Data['RapeFiring'] = nil
    end
end)
