Data['ProtectionBox']:AddSearchDropdown('israel_whitelist_select', {
    SpecialType = 'Player',
    Multi = true,
    Text = 'search players',
    Callback = function(Value)
        if Data['IsraelWhitelist'] == nil then
            Data['IsraelWhitelist'] = {}
        end
        local keep = {}
        local function pickwl(x)
            if typeof(x) == 'Instance' and x:IsA('Player') and x ~= LocalPlayer then
                return x
            end
            if type(x) == 'string' and x ~= '' then
                return Players:FindFirstChild(x)
            end
            return nil
        end
        if type(Value) == 'table' then
            for k, on in pairs(Value) do
                if on then
                    local p = pickwl(k)
                    if p and p.Parent then
                        keep[p] = true
                    end
                end
            end
            for _, v in ipairs(Value) do
                local p = pickwl(v)
                if p and p.Parent then
                    keep[p] = true
                end
            end
        else
            local p = pickwl(Value)
            if p and p.Parent then
                keep[p] = true
            end
        end
        for p, _ in pairs(Data['IsraelWhitelist']) do
            if not keep[p] then
                Data['IsraelWhitelist'][p] = nil
            end
        end
        for p, _ in pairs(keep) do
            Data['IsraelWhitelist'][p] = true
        end
        phowg:sync_israel_protection()
        if updatetargetlabel then
            updatetargetlabel()
        end
    end,
})
