Data['CombatBox']
    :AddToggle('ragebot_enable', {
        Text = 'enable',
        Default = false,
        Callback = function(v)
            if not v then
                phowg:clear_melee_replication_root()
                Data.RagebotBait, Data.RagebotBaitTargets = nil, nil
                phowg:clear_ragebot_idle()
                phowg:stop_gun_fire('Ragebot')
                Data['RagebotActive'] = false
                Data['CurrentStatus'] = 'Idle'
                Data['CurrentActionTarget'] = nil
                if Data['FrozenRoots'] then
                    for P, R in pairs(Data['FrozenRoots']) do
                        if R and R.Parent then
                            R.Anchored = false
                        end
                        Data['FrozenRoots'][P] = nil
                    end
                end
                if Data['FlameFrozenTarget'] ~= nil then
                    local ffm = Data['FlameFrozenTarget']
                    local ffc = ffm and ffm.Parent and ffm.Character or nil
                    local ffr = ffc and ffc:FindFirstChild('HumanoidRootPart') or nil
                    if ffr and ffr.Parent then
                        ffr.Anchored = false
                    end
                    Data['FlameFrozenTarget'] = nil
                end
                if Data['StatusText'] then
                    Data['StatusShown'] = nil
                    Data['StatusText'].Text = ''
                    Data['StatusText'].Visible = false
                end
                hidevisualizer()
                pcall(function()
                    unequipall()
                end)
            end
        end,
    })
    :AddKeyPicker('ragebot_enable_key', { Default = 'Y', SyncToggleState = false, Mode = 'Toggle', Text = 'ragebot' })
Data['CombatBox']:AddToggle('auto_kill', {
    Text = 'auto kill',
