            Data['RifleVoidWait'] = nil
            Data['RifleVoidTarget'] = nil
            Data['RifleTarget'] = nil
            Data['GunFocusTarget'] = nil
            Data['GunFocusAt'] = nil
            if Data['FlameFrozenTarget'] ~= nil then
                local ffm = Data['FlameFrozenTarget']
                local ffc = ffm and ffm.Parent and ffm.Character or nil
                local ffr = ffc and ffc:FindFirstChild('HumanoidRootPart') or nil
                if ffr and ffr.Parent then
                    ffr.Anchored = false
                end
                if Data['FrozenRoots'] then
                    Data['FrozenRoots'][ffm] = nil
                end
                Data['FlameFrozenTarget'] = nil
            end
            if not Data['ManualVoid'] and not Data.HideVoid then
                Data['VoidActive'] = false
            end
            if
                not (Toggles.auto_stomp and Toggles.auto_stomp.Value)
                and not (Toggles.auto_arrest and Toggles.auto_arrest.Value)
