do
    local statePath = 'PhowgHosted/DaHood/cache/server-target-search.json'
    local sourcePath = 'PhowgHosted/DaHood/cache/server-target-search.luau'
    local teleport = game:GetService('TeleportService')
    local function status(text)
        Data.TargetSearchStatus = text
        if Data.ServerTargetSearchLabel then
            Data.ServerTargetSearchLabel:SetText('status: ' .. text)
        end
    end
    local function persist(state)
        local ok, problem = pcall(function()
            writefile(statePath, HttpService:JSONEncode(state))
        end)
        return ok, problem
    end
    local function valid(state)
        return Data.TargetSearch == state
            and state.Active
            and not Library.Unloaded
            and not Data.Unloading
            and not Data.SafeMode
    end
    function phowg:target_search_stop(message)
        Data.TargetSearchStartRevision = (Data.TargetSearchStartRevision or 0) + 1
        local state = Data.TargetSearch
        if state then
            state.Active = false
            for _, connection in ipairs(state.Connections or {}) do
                connection:Disconnect()
            end
            phowg:stop_gun_fire('Ragebot')
            if state.Target then
                if Data.StompWatch then
                    Data.StompWatch[state.Target] = nil
                end
                if Data.ArrestWatch then
                    Data.ArrestWatch[state.Target] = nil
                end
                for _, key in ipairs({
                    'CurrentActionTarget',
                    'CurrentMainTarget',
                    'SingleLockedTarget',
                    'GunFocusTarget',
                    'GunAimTarget',
                    'RifleTarget',
                    'PrevMainTarget',
                }) do
                    if Data[key] == state.Target then
                        Data[key] = nil
                    end
                end
            end
        end
        Data.TargetSearch = nil
        if type(writefile) == 'function' then
            persist({ Active = false })
        end
        Data.TargetListCache, Data._ActionableAt = nil, nil
        if Toggles.server_target_search and Toggles.server_target_search.Value then
            Toggles.server_target_search:SetValue(false)
        end
        status(message or 'idle')
    end
    local function found(state, player)
        if not valid(state) or player.UserId ~= state.UserId or player == LocalPlayer then
            return false
        end
        state.Target, state.Mode, state.Hopping = player, 'target', false
        if Data.StompWatch then
            Data.StompWatch[player] = nil
        end
        if Data.ArrestWatch then
            Data.ArrestWatch[player] = nil
        end
        state.ExpectedJob = nil
        persist({ Active = false })
        Data.TargetListCache, Data._ActionableAt = nil, nil
        phowg:stop_gun_fire('Ragebot')
        Data.CurrentActionTarget, Data.CurrentMainTarget, Data.RifleTarget = player, player, nil
        status('target found: ' .. player.Name .. '; gun only')
        ragebot_on()
        return true
    end
    local function queue_function()
        local env = getgenv()
        return env.queue_on_teleport
            or env.queueonteleport
            or env.syn and env.syn.queue_on_teleport
            or env.fluxus and env.fluxus.queue_on_teleport
    end
    local function cache_source()
        local ok, source = pcall(function()
            return game:HttpGet(RuntimeRepository .. 'main/Phowg%20Hosted%20DH.lua', true)
        end)
        if ok and type(source) == 'string' and source:find('function phowg:target_search_start', 1, true) and loadstring(source) then
            return pcall(writefile, sourcePath, source)
        end
        return false
    end
    function phowg:target_search_start(query, resume)
        if Data.TargetSearch or Library.Unloaded or Data.SafeMode then
            return
        end
        Data.TargetSearchStartRevision = (Data.TargetSearchStartRevision or 0) + 1
        local revision = Data.TargetSearchStartRevision
        local userId
        local raw = tostring(query or ''):match('^%s*(.-)%s*$'):gsub('^@', '')
        if resume then
            userId = tonumber(resume.UserId)
        elseif raw:match('^%d+$') then
            userId = tonumber(raw)
        elseif raw:match('^[%w_]+$') then
            status('resolving username')
            local ok, result = pcall(Players.GetUserIdFromNameAsync, Players, raw)
            if ok then
                userId = result
            end
        end
        if revision ~= Data.TargetSearchStartRevision then
            return
        end
        if not userId or userId < 1 or userId % 1 ~= 0 or userId == LocalPlayer.UserId then
            phowg:target_search_stop("enter another player's username or userid")
            return
        end
        if not Toggles.server_target_search.Value or Library.Unloaded or Data.SafeMode then
            return
        end
        local state: { [string]: any } = {
            Active = true,
            UserId = userId,
            Mode = 'search',
            Token = resume and resume.Token or HttpService:GenerateGUID(false),
            PlaceId = game.PlaceId,
            Connections = {},
            Cursor = resume and resume.Cursor,
            Queue = resume and resume.Queue or {},
            Visited = resume and resume.Visited or {},
            Pass = resume and resume.Pass or 1,
            NextAt = tick() + 5,
        }
        Data.TargetSearch = state
        state.Visited[game.JobId] = true
        state.Connections = {
            connectshared(Players.PlayerAdded, function(player)
                found(state, player)
            end, Players, 'target search/player added', 0, 'event/PlayerAdded', Players),
            connectshared(Players.PlayerRemoving, function(player)
                if state.Target == player then
                    phowg:target_search_stop('target left; stopped')
                end
            end, Players, 'target search/player removed', 0, 'event/PlayerRemoving', Players),
            connectshared(teleport.TeleportInitFailed, function(player, _, message)
                if player == LocalPlayer and valid(state) and state.Hopping then
                    state.Hopping, state.NextAt = false, tick() + 8
                    status('teleport failed; retrying: ' .. tostring(message))
                end
            end, teleport, 'target search/teleport failed', 0, 'event/TeleportInitFailed', teleport),
        }
        local player = Players:GetPlayerByUserId(userId)
        if player and found(state, player) then
            return
        end
        if
            type(readfile) ~= 'function'
            or type(writefile) ~= 'function'
            or type(makefolder) ~= 'function'
            or type(isfolder) ~= 'function'
            or type(queue_function()) ~= 'function'
        then
            phowg:target_search_stop('server hopping needs file and teleport-queue support')
            return
        end
        local foldersOK = pcall(function()
            for _, folder in ipairs({ 'PhowgHosted', 'PhowgHosted/DaHood', 'PhowgHosted/DaHood/cache' }) do
                if not isfolder(folder) then
                    makefolder(folder)
                end
            end
        end)
        if not foldersOK or not cache_source() then
            phowg:target_search_stop('could not cache this script for the next server')
            return
        end
        status('searching public servers for userid ' .. string.format('%.0f', userId))
    end
    local function hop(state, jobId)
        if not valid(state) then
            return
        end
        state.Visited[jobId], state.ExpectedJob, state.Hopping, state.HopAt = true, jobId, true, tick()
        local config = SaveManager:CaptureCurrent()
        local record = {
            Active = true,
            UserId = state.UserId,
            Token = state.Token,
            PlaceId = state.PlaceId,
            ExpectedJob = jobId,
            Cursor = state.Cursor,
            Queue = state.Queue,
            Visited = state.Visited,
            Pass = state.Pass,
            Config = config,
            Expires = os.time() + 1800,
        }
        local ok = persist(record)
        if not ok then
            phowg:target_search_stop('could not save search continuation')
            return
        end
        local queued = string.format(
            [[
local ok, state = pcall(function() return game:GetService('HttpService'):JSONDecode(readfile(%q)) end)
if not ok or not state.Active or state.Token ~= %q or state.PlaceId ~= game.PlaceId or state.ExpectedJob ~= game.JobId or state.Expires < os.time() then return end
local environment = getgenv()
if environment.PhowgTargetSearchResume == state.Token .. game.JobId then return end
environment.PhowgTargetSearchResume = state.Token .. game.JobId
if environment.PhowgLibrary and not environment.PhowgLibrary.Unloaded then return end
local source = readfile(%q)
loadstring(source, '@Phowg Hosted DH.lua')()
]],
            statePath,
            state.Token,
            sourcePath
        )
        local queueOK, problem = pcall(queue_function(), queued)
        if not queueOK then
            phowg:target_search_stop('could not queue continuation: ' .. tostring(problem))
            return
        end
        status('hopping; search pass ' .. tostring(state.Pass))
        local accepted, failure = pcall(teleport.TeleportToPlaceInstance, teleport, game.PlaceId, jobId, LocalPlayer)
        if not accepted then
            state.Hopping, state.NextAt = false, tick() + 8
            persist({ Active = false })
            status('teleport failed; retrying: ' .. tostring(failure))
        end
    end
    function phowg:target_search_step()
        local state = Data.TargetSearch
        if not state then
            return
        end
        if not valid(state) then
            phowg:target_search_stop('stopped')
            return
        end
        if state.Mode == 'target' then
            if state.Target.Parent ~= Players then
                phowg:target_search_stop('target left; stopped')
            end
            return
        end
        if state.Hopping then
            if tick() - state.HopAt >= 20 then
                state.Hopping, state.NextAt = false, tick() + 8
                persist({ Active = false })
                status('teleport timed out; retrying')
            end
            return
        end
        if state.Busy or tick() < state.NextAt then
            return
        end
        local player = Players:GetPlayerByUserId(state.UserId)
        if player and found(state, player) then
            return
        end
        state.Busy = true
        phowg:queue_background('metadata', 'server target search', function()
            local ok, problem = pcall(function()
                if not valid(state) then
                    return
                end
                if #state.Queue == 0 then
                    local url = 'https://games.roblox.com/v1/games/'
                        .. string.format('%.0f', game.PlaceId)
                        .. '/servers/Public?sortOrder=Desc&limit=100'
                    if state.Cursor then
                        url ..= '&cursor=' .. HttpService:UrlEncode(state.Cursor)
                    end
                    local page = HttpService:JSONDecode(game:HttpGet(url))
                    if not valid(state) then
                        return
                    end
                    if type(page) ~= 'table' or type(page.data) ~= 'table' then
                        error('invalid public server response')
                    end
                    for _, server in ipairs(page.data) do
                        if
                            type(server.id) == 'string'
                            and server.id ~= game.JobId
                            and not state.Visited[server.id]
                            and type(server.playing) == 'number'
                            and type(server.maxPlayers) == 'number'
                            and server.playing < server.maxPlayers
                        then
                            state.Queue[#state.Queue + 1] = server.id
                        end
                    end
                    state.Cursor = type(page.nextPageCursor) == 'string'
                            and page.nextPageCursor ~= ''
                            and page.nextPageCursor
                        or nil
                    if #state.Queue == 0 and not state.Cursor then
                        state.Visited, state.Pass, state.NextAt = { [game.JobId] = true }, state.Pass + 1, tick() + 30
                        status('public scan complete; retrying in 30 seconds')
                        return
                    end
                end
                if not valid(state) or state.Mode ~= 'search' then
                    return
                end
                local target = Players:GetPlayerByUserId(state.UserId)
                if target and found(state, target) then
                    return
                end
                local jobId = table.remove(state.Queue, 1)
                if jobId then
                    hop(state, jobId)
                else
                    state.NextAt = tick() + 1
                end
            end)
            if Data.TargetSearch == state then
                state.Busy = false
                if not ok then
                    state.NextAt, state.Cursor = tick() + 8, nil
                    status('server list unavailable; retrying: ' .. tostring(problem))
                end
            end
        end)
    end
    function phowg:resume_target_search()
        if type(readfile) ~= 'function' then
            return
        end
        local ok, state = pcall(function()
            return HttpService:JSONDecode(readfile(statePath))
        end)
        if
            not ok
            or type(state) ~= 'table'
            or state.Active ~= true
            or state.PlaceId ~= game.PlaceId
            or state.ExpectedJob ~= game.JobId
            or type(state.Expires) ~= 'number'
            or state.Expires < os.time()
        then
            return
        end
        if
            type(state.UserId) ~= 'number'
            or state.UserId < 1
            or state.UserId % 1 ~= 0
            or type(state.Token) ~= 'string'
            or state.Token == ''
            or type(state.Queue) ~= 'table'
            or type(state.Visited) ~= 'table'
            or type(state.Pass) ~= 'number'
        then
            persist({ Active = false })
            status('invalid search continuation')
            return
        end
        persist({ Active = false })
        if type(state.Config) == 'table' then
            local applied = SaveManager:ApplyConfig(state.Config, 'server search continuation')
            if not applied then
                status('could not restore search settings')
                return
            end
        end
        if Library.Unloaded or Data.SafeMode then
            return
        end
        Options.server_target_query:SetValue(tostring(state.UserId), true)
        Toggles.server_target_search:SetValue(true, true)
        phowg:target_search_start(tostring(state.UserId), state)
    end
    phowg:register_cleanup('server target search', function(_, reason)
        if reason == 'unload' then
            phowg:target_search_stop('unloaded')
        end
    end)
    registerheartbeat('ServerTargetSearch', phowg.target_search_step, 0.5, function()
        return Data.TargetSearch ~= nil
    end)
end
