Data['TargetBox']:AddDropdown('target_select', {
    SpecialType = 'Player',
    Text = 'select targets',
    Multi = true,
    Callback = function(Value)
        local function pick_player(v)
            if typeof(v) == 'Instance' and v:IsA('Player') then
                if v ~= LocalPlayer then
                    return v
                end
                return nil
            elseif typeof(v) == 'string' and v ~= '' then
                local found = Players:FindFirstChild(v)
                if found and found ~= LocalPlayer then
                    return found
                end
            end
            return nil
        end
        if type(Value) == 'table' then
            local Selected = {}
            for v, on in pairs(Value) do
                if on then
                    local plr = pick_player(v)
                    if plr and plr.Parent then
                        Selected[plr] = true
                    end
                end
            end
            for _, v in ipairs(Value) do
                local plr = pick_player(v)
                if plr and plr.Parent then
                    Selected[plr] = true
                end
            end

            if Data['DropdownTargets'] == nil then
                Data['DropdownTargets'] = {}
            end
            for plr, _ in pairs(Data['DropdownTargets']) do
                if not Selected[plr] then
                    Data['DropdownTargets'][plr] = nil
                    if not (Data['PunishmentTargets'] and Data['PunishmentTargets'][plr]) then
                        Data['LockedTargets'][plr] = nil
                        if Data['TargetWatchlist'] then
                            pcall(function()
                                Data['TargetWatchlist'][plr.UserId] = nil
                            end)
                            pcall(function()
                                Data['TargetWatchlist'][plr.Name] = nil
                            end)
                        end
                    end
                end
            end
            for plr, _ in pairs(Selected) do
                Data['DropdownTargets'][plr] = true
                Data['LockedTargets'][plr] = true
                pcall(function()
                    Data['TargetWatchlist'][plr.UserId] = true
                end)
                pcall(function()
                    Data['TargetWatchlist'][plr.Name] = true
                end)
            end
            Data['SingleLockedTarget'] = nil
            updatetracers()
            updatetargetlabel()
            if Toggles.spectate and Toggles.spectate.Value and Data['SpectateActive'] then
                updatespectate()
            end
            return
        end
        local plr = nil
        if typeof(Value) == 'Instance' and Value:IsA('Player') then
            plr = Value
        elseif typeof(Value) == 'string' and Value ~= '' then
            plr = Players:FindFirstChild(Value)
        else
            local cur = Options.target_select and Options.target_select.Value
            if typeof(cur) == 'Instance' and cur:IsA('Player') then
                plr = cur
            elseif typeof(cur) == 'string' and cur ~= '' then
                plr = Players:FindFirstChild(cur)
            end
        end

        if plr then
            local hasExisting = false
            for k, _ in pairs(Data['LockedTargets']) do
                hasExisting = true
                break
            end
            if hasExisting or (Data['SingleLockedTarget'] and Data['SingleLockedTarget'] ~= plr) then
                Data['LockedTargets'][plr] = true
                Data['TargetWatchlist'][plr.UserId] = true
                Data['TargetWatchlist'][plr.Name] = true
                if
                    Data['SingleLockedTarget']
                    and Data['SingleLockedTarget'] ~= plr
                    and Data['SingleLockedTarget'].Parent
                then
                    Data['LockedTargets'][Data['SingleLockedTarget']] = true
                    Data['TargetWatchlist'][Data['SingleLockedTarget'].UserId] = true
                    Data['TargetWatchlist'][Data['SingleLockedTarget'].Name] = true
                    Data['SingleLockedTarget'] = nil
                end
                if Data['DropdownTargets'] == nil then
                    Data['DropdownTargets'] = {}
                end
                Data['DropdownTargets'][plr] = true
            else
                Data['SingleLockedTarget'] = plr
            end
        else
            Data['SingleLockedTarget'] = nil
        end

        updatetracers()
        updatetargetlabel()
        if Toggles.spectate and Toggles.spectate.Value and Data['SpectateActive'] then
            updatespectate()
        end
    end,
})
Data['RageWhitelist'] = Data['RageWhitelist'] or {}
