                end
            end
            for p, _ in pairs(Data['RageWhitelist']) do
                set[p.Name] = nil
            end
            Options.target_select:SetValue(set)
        end
        updatetargetlabel()
        updatetracers()
        purgesilentwhitelisted()
    end,
})
