Data['TargetBox']:AddInput('target_search', {
    Text = 'search target',
    Placeholder = 'type name...',
    Numeric = false,
    Finished = true,
    Callback = function(Value)
        local q = string.lower(tostring(Value or ''))
        local matches = {}
        if q ~= '' then
            for _, plr in ipairs(Players:GetPlayers()) do
                if
                    plr ~= LocalPlayer
                    and (plr.Name:lower():find(q, 1, true) or plr.DisplayName:lower():find(q, 1, true))
                then
                    matches[#matches + 1] = plr
                end
            end
        end
        if #matches == 0 then
            Data['TargetSearchLabel']:SetText('found: None')
            return
        end
        local lines = {}
        for i, plr in ipairs(matches) do
            lines[#lines + 1] = plr.Name .. ' (@' .. plr.DisplayName .. ')'
        end
        Data['TargetSearchLabel']:SetText(table.concat(lines, '\n'))
        if not (Options.target_select and Options.target_select.SetValue) then
            return
        end
        local set = {}
        local cur = Options.target_select.Value
        if type(cur) == 'table' then
            for name, on in pairs(cur) do
                if on and Players:FindFirstChild(name) then
                    set[name] = true
                end
            end
        end
        for _, plr in ipairs(matches) do
            if plr.Parent then
                set[plr.Name] = true
            end
        end
        Options.target_select:SetValue(set)
    end,
})
local function targetsearchplayers()
    local q = string.lower(tostring(Options.target_search and Options.target_search.Value or ''))
    local ms = {}
    if q ~= '' then
        for _, plr in ipairs(Players:GetPlayers()) do
            if
                plr ~= LocalPlayer and (plr.Name:lower():find(q, 1, true) or plr.DisplayName:lower():find(q, 1, true))
            then
                ms[#ms + 1] = plr
            end
        end
    end
    if #ms == 0 then
        local cur = Data['SingleLockedTarget'] or getselectedtarget()
        if cur and cur.Parent then
            ms = { cur }
        end
    end
    return ms
end
