do
    function phowg:clear_zombie_visual_gui(state)
        if state.VisualAdded then
            state.VisualAdded:Disconnect()
            state.VisualAdded = nil
        end
        if state.VisualRemoved then
            state.VisualRemoved:Disconnect()
            state.VisualRemoved = nil
        end
        for gui, record in pairs(state.VisualRecords or {}) do
            record.Connection:Disconnect()
            if gui.Parent then
                gui.Enabled = record.Original
            end
        end
        state.VisualRecords, state.VisualPlayerGui = {}, nil
    end
    function phowg:bind_zombie_visual_gui(state, playerGui)
        if Data.ZombieSpoofState ~= state or state.VisualPlayerGui == playerGui then
            return
        end
        phowg:clear_zombie_visual_gui(state)
        if not playerGui then
            return
        end
        state.VisualPlayerGui = playerGui
        local function track(gui)
            if gui.Name ~= 'ZombieVision' or not gui:IsA('ScreenGui') or state.VisualRecords[gui] then
                return
            end
            local record = { Original = gui.Enabled, Writing = false }
            state.VisualRecords[gui] = record
            local function apply()
                if Data.ZombieSpoofState ~= state or not gui.Parent then
                    return
                end
                local show = Toggles.zombie_spoof_visuals and Toggles.zombie_spoof_visuals.Value == true or false
                if gui.Enabled ~= show then
                    record.Writing = true
                    gui.Enabled = show
                    record.Writing = false
                end
            end
            record.Connection = gui:GetPropertyChangedSignal('Enabled'):Connect(function()
                if record.Writing or Data.ZombieSpoofState ~= state then
                    return
                end
                record.Original = gui.Enabled
                apply()
            end)
            apply()
        end
        state.VisualAdded = playerGui.ChildAdded:Connect(track)
        state.VisualRemoved = playerGui.ChildRemoved:Connect(function(gui)
            local record = state.VisualRecords[gui]
            if record then
                record.Connection:Disconnect()
                state.VisualRecords[gui] = nil
                if gui.Parent then
                    gui.Enabled = record.Original
                end
            end
        end)
        for _, gui in ipairs(playerGui:GetChildren()) do
            track(gui)
        end
    end
    function phowg:sync_zombie_spoof_visuals()
        local state = Data.ZombieSpoofState
        if not state then
            return
        end
        phowg:bind_zombie_visual_gui(state, LocalPlayer:FindFirstChildOfClass('PlayerGui'))
        local show = Toggles.zombie_spoof_visuals and Toggles.zombie_spoof_visuals.Value == true or false
        for gui, record in pairs(state.VisualRecords or {}) do
            if gui.Parent and gui.Enabled ~= show then
                record.Writing = true
                gui.Enabled = show
                record.Writing = false
            end
        end
    end
    function phowg:set_zombie_spoof(enabled)
        local state = Data.ZombieSpoofState
        if enabled then
            if state then
                phowg:sync_zombie_spoof_visuals()
                return
            end
            state = { Original = LocalPlayer:GetAttribute('Infected'), VisualRecords = {} }
            Data.ZombieSpoofState = state
            state.PlayerGuiAdded = LocalPlayer.ChildAdded:Connect(function(child)
                if child:IsA('PlayerGui') then
                    phowg:bind_zombie_visual_gui(state, child)
                end
            end)
            phowg:sync_zombie_spoof_visuals()
            state.Connection = LocalPlayer:GetAttributeChangedSignal('Infected'):Connect(function()
                if Data.ZombieSpoofState ~= state then
                    return
                end
                local value = LocalPlayer:GetAttribute('Infected')
                if value ~= true then
                    state.Original = value
                    LocalPlayer:SetAttribute('Infected', true)
                end
            end)
            LocalPlayer:SetAttribute('Infected', true)
        elseif state then
            Data.ZombieSpoofState = nil
            state.Connection:Disconnect()
            if state.PlayerGuiAdded then
                state.PlayerGuiAdded:Disconnect()
            end
            phowg:clear_zombie_visual_gui(state)
            LocalPlayer:SetAttribute('Infected', state.Original)
        end
    end
    phowg:register_cleanup('zombie spoof', function(_, reason)
        if reason == 'unload' then
            phowg:set_zombie_spoof(false)
        end
    end)
end
