function phowg:set_auto_block_animation(enabled)
    phowg:set_character_observer('block animation', enabled, function(state, character)
        local animator
        local function stop(track)
            if state.Closed or not (Toggles.auto_block and Toggles.auto_block.Value) then
                return
            end
            local animations = ReplicatedStorage:FindFirstChild('ClientAnimations')
            local block = animations and animations:FindFirstChild('Block')
            local animation = track.Animation
            if animation and block and (animation == block or animation.AnimationId == block.AnimationId) then
                pcall(track.Stop, track, 0)
            end
        end
        local function refresh()
            local humanoid = character:FindFirstChildOfClass('Humanoid')
            local nextAnimator = humanoid and humanoid:FindFirstChildOfClass('Animator')
            if nextAnimator == animator then
                return
            end
            if state.Connections.Animation then
                state.Connections.Animation:Disconnect()
                state.Connections.Animation = nil
            end
            animator = nextAnimator
            if animator then
                state.Connections.Animation = connectshared(
                    animator.AnimationPlayed,
                    stop,
                    character,
                    'auto block/animation',
                    0,
                    'event/AnimationPlayed',
                    animator
                )
                for _, track in ipairs(animator:GetPlayingAnimationTracks()) do
                    stop(track)
                end
            end
        end
        state.Connections.Added = connectshared(character.DescendantAdded, function(child)
            if child:IsA('Animator') then
                refresh()
            end
        end, character, 'auto block/animator', 0, 'event/DescendantAdded', character)
        refresh()
    end)
end
