registerheartbeat('Utility', function()
    antiflingloop()
    if Data['FrozenRoots'] and Data['FrozenAt'] then
        for P, R in pairs(Data['FrozenRoots']) do
            local at = Data['FrozenAt'][P]
            if
                at
                and tick() - at > 1
                and not (Data['StompWatch'] and Data['StompWatch'][P])
                and not (Data['ArrestWatch'] and Data['ArrestWatch'][P])
            then
                if R and R.Parent then
                    R.Anchored = false
                end
                Data['FrozenRoots'][P] = nil
                Data['FrozenAt'][P] = nil
            end
        end
    end
    if Data['Buying'] then
        local bc = LocalPlayer.Character
        local bh = bc and bc:FindFirstChildOfClass('Humanoid') or nil
        if not bc or not bh or bh.Health <= 0 then
            Data['Buying'] = false
        end
    end
    if Data['IsRespawning'] then
        lockcameratolocal()
    elseif Data['SpectateActive'] and Toggles.spectate and Toggles.spectate.Value then
        updatespectate()
    end
end)
