function updatekorbloxchar(character, enabled, forceOff)
    local snapshot = Data.AvatarSpoof
    enabled = not forceOff
        and not Library.Unloaded
        and not Data.Unloading
        and (enabled or snapshot and snapshot.Korblox == true and phowg:toggle_enabled('avatar_spoof_enabled'))
    local source = character and (character:FindFirstChild('RightUpperLeg') or character:FindFirstChild('Right Leg'))
    local state = Data['KorbloxState']
    local changed = false
    if state and (not enabled or state.character ~= character or not state.leg.Parent or state.source ~= source) then
        for part, transparency in pairs(state.originals) do
            pcall(function()
                part.Transparency = transparency
            end)
        end
        if state.leg then
            if Data['LocalModelsOrig'] then
                Data['LocalModelsOrig'][state.leg] = nil
            end
            state.leg:Destroy()
        end
        Data['KorbloxState'] = nil
        state = nil
        changed = true
    end
    if enabled and character and character.Parent then
        if source and source:IsA('BasePart') then
            if not state then
                local leg = Instance.new('Part')
                leg.Name = 'PhowgKorbloxLeg'
                leg.Size = source.Size
                leg.CFrame = source.CFrame
                leg.CanCollide = false
                leg.CanTouch = false
                leg.CanQuery = false
                leg.Massless = true
                local mesh = Instance.new('SpecialMesh')
                mesh.MeshType = Enum.MeshType.FileMesh
                mesh.MeshId = 'rbxassetid://902942096'
                mesh.TextureId = 'rbxassetid://902843398'
                mesh.Parent = leg
                local weld = Instance.new('WeldConstraint')
                weld.Part0 = source
                weld.Part1 = leg
                weld.Parent = leg
                leg.Parent = character
                state = { character = character, source = source, leg = leg, mesh = mesh, originals = {} }
                Data['KorbloxState'] = state
                changed = true
            end
            local size = source.Size
            if state.size ~= size then
                local base = source.Name == 'Right Leg' and Vector3.new(1, 2, 1)
                    or Vector3.new(1, 1.216600418091, 0.999898910522)
                state.leg.Size = size
                state.mesh.Scale = Vector3.new(size.X / base.X, size.Y / base.Y, size.Z / base.Z)
                state.size = size
                changed = true
            end
            state.leg.Color = source.Color
            state.leg.Material = source.Material
            for _, name in ipairs({ 'RightFoot', 'RightLowerLeg', 'RightUpperLeg', 'Right Leg' }) do
                local part = character:FindFirstChild(name)
                if part and part:IsA('BasePart') then
                    if state.originals[part] == nil then
                        state.originals[part] = part.Transparency
                    end
                    part.Transparency = 1
                end
            end
        end
    end
    if changed then
        if character and character.Parent then
            buildvisualizer(character)
            syncvisualizer()
        end
    end
end
phowg:register_cleanup('korblox', function(scope)
    local state = Data.KorbloxState
    if not scope or state and state.character == scope then
        updatekorbloxchar(nil, false, true)
    end
end)
