do
    local function china_hat_model()
        local m = Data['ChinaHatModel']
        if m and m.Parent then
            return m
        end
        if m then
            pcall(function()
                m:Destroy()
            end)
        end
        m = Instance.new('Model')
        m.Name = 'PhowgChinaHats'
        m.Parent = Workspace
        Data['ChinaHatModel'] = m
        return m
    end
    local function destroy_china_hats()
        for _, entry in pairs(Data.ChinaHats or {}) do
            phowg:release_visual(entry)
        end
        Data['ChinaHats'] = nil
        local m = Data['ChinaHatModel']
        Data['ChinaHatModel'] = nil
        if m then
            pcall(function()
                m:Destroy()
            end)
        end
    end
    local function ensure_china_hat(head, color, settings, now)
        Data['ChinaHats'] = Data['ChinaHats'] or {}
        local entry = Data['ChinaHats'][head]
        local parts = entry and entry.parts or nil
        local ok = parts
            and head
            and head.Parent
            and entry.Geometry == settings.Geometry
            and entry.HeadHeight == head.Size.Y
        if ok then
            for _, p in ipairs(parts) do
                if not (p and p.Parent) then
                    ok = false
                    break
                end
            end
        end
        if ok then
            for index, p in ipairs(parts) do
                local layerColor = phowg:china_hat_layer_color(color, index, #parts, settings, now)
                if p.Color ~= layerColor then
                    p.Color = layerColor
                end
                if p.Material ~= settings.Material then
                    p.Material = settings.Material
                end
                if p.Transparency ~= settings.Transparency then
                    p.Transparency = settings.Transparency
                end
            end
            entry.Color = color
            return
        end
        if parts then
            for _, p in ipairs(parts) do
                pcall(function()
                    p:Destroy()
                end)
            end
        end
        if entry then
            phowg:release_visual(entry)
        end
        Data['ChinaHats'][head] = nil
        if not (head and head.Parent) then
            return
        end
        local model = china_hat_model()
        local newEntry = { parts = {}, Color = color, Geometry = settings.Geometry, HeadHeight = head.Size.Y }
        if not phowg:acquire_visual(newEntry, settings.Layers, 'china hats') then
            return
        end
        newEntry.parts = createchinahatparts(head, model, color, false, settings)
        Data['ChinaHats'][head] = newEntry
    end
    registerheartbeat('ChinaHat', function()
        if not (Toggles.china_hat and Toggles.china_hat.Value) then
            if Data['ChinaHats'] or Data['ChinaHatModel'] then
                destroy_china_hats()
            end
            return
        end
        local mode = (Options.china_hat_mode and Options.china_hat_mode.Value) or 'self'
        local color = (Options.china_hat_color and Options.china_hat_color.Value)
            or Color3.fromHSV(tick() % 5 / 5, 1, 1)
        local settings, now = phowg:china_hat_settings(), tick()
        local active = {}
        if mode == 'self' then
            local ch = LocalPlayer.Character
            local head = ch and ch:FindFirstChild('Head') or nil
            if head and head:IsA('BasePart') then
                active[head] = true
                ensure_china_hat(head, color, settings, now)
            end
        else
            for _, plr in ipairs(Players:GetPlayers()) do
                if mode == 'everyone' or plr ~= LocalPlayer then
                    local ch = plr and plr.Character or nil
                    local head = ch and ch:FindFirstChild('Head') or nil
                    if head and head:IsA('BasePart') and phowg:cosmetic_visible(head.Position, plr == LocalPlayer) then
                        active[head] = true
                        ensure_china_hat(head, color, settings, now)
                    end
                end
            end
        end
        if Data['ChinaHats'] then
            for head, entry in pairs(Data['ChinaHats']) do
                if not active[head] or not head.Parent then
                    if entry and entry.parts then
                        for _, p in ipairs(entry.parts) do
                            pcall(function()
                                p:Destroy()
                            end)
                        end
                    end
                    if entry then
                        phowg:release_visual(entry)
                    end
                    Data['ChinaHats'][head] = nil
                end
            end
        end
    end, 0.05)
end
