Data['LocalModelRight']:AddDropdown('accessories_dropdown', {
    Values = {
        'valk',
        'emerald valk',
        'void star',
        'ice valk',
        'sparkle time fedora',
        'purple sparkle time fedora',
        'red sparkle time fedora',
        'white sparkle time fedora',
        'toxic horns',
        'fiery horns',
        'frozen horns',
        'dominus astra',
        'dominus frigidus',
        'dominus infernus',
        'dominus empyreus',
    },
    Default = 0,
    Text = 'accessories',
    AllowNull = true,
    Multi = true,
    Callback = function(Value)
        for Index in pairs(Data['ActiveAccessories']) do
            if not Value[Index] then
                removeattachment(Index)
                Data['ActiveAccessories'][Index] = nil
            end
        end
        for Index, Selected in pairs(Value) do
            if Selected and not Data['ActiveAccessories'][Index] then
                local Id = nil
                if Index == 'valk' then
                    Id = 1402432199
                elseif Index == 'emerald valk' then
                    Id = 2830437685
                elseif Index == 'void star' then
                    Id = 1125510
                elseif Index == 'ice valk' then
                    Id = 4390891467
                elseif Index == 'sparkle time fedora' then
                    Id = 1285307
                elseif Index == 'purple sparkle time fedora' then
                    Id = 63043890
                elseif Index == 'red sparkle time fedora' then
                    Id = 72082328
                elseif Index == 'white sparkle time fedora' then
                    Id = 1016143686
                elseif Index == 'toxic horns' then
                    Id = 1744060292
                elseif Index == 'fiery horns' then
                    Id = 215718515
                elseif Index == 'frozen horns' then
                    Id = 74891470
                elseif Index == 'dominus astra' then
                    Id = 162067148
                elseif Index == 'dominus frigidus' then
                    Id = 48545806
                elseif Index == 'dominus infernus' then
                    Id = 31101391
                elseif Index == 'dominus empyreus' then
                    Id = 21070012
                end
                if Id then
                    createattachment(Id, Index)
                    Data['ActiveAccessories'][Index] = true
                end
            end
        end
    end,
})
