do
    local control = Options.indicator_sources
    local setValue = control.SetValue
    control.SetValue = function(item, value)
        if type(value) == 'table' then
            value = table.clone(value)
            if value['rpg dodge'] ~= nil then
                value['evade explosives'], value['rpg dodge'] = value['rpg dodge'], nil
            end
            for key, entry in pairs(value) do
                if entry == 'rpg dodge' then
                    value[key] = 'evade explosives'
                end
            end
        end
        return setValue(item, value)
    end
end
