})
do
    local option = Options.afterimages_sources
    local setValue = option.SetValue
    function option:SetValue(value)
        if type(value) == 'table' then
            value = table.clone(value)
            if value['local player'] then
                value['local player'], value['self only'] = nil, true
            end
            for index, name in ipairs(value) do
                if name == 'local player' then
                    value[index] = 'self only'
                end
            end
        elseif value == 'local player' then
            value = 'self only'
        end
        return setValue(self, value)
    end
end
