    Default = '',
    Numeric = false,
    Finished = false,
    Text = 'money value',
    Placeholder = 'e.g. 9999',
    Callback = function(Value)
        local txt = tostring(Value or '')
        if txt == '' then
            Data['CustomMoneyLock'] = nil
            Data['CustomMoneyNeg'] = nil
        else
            if string.sub(txt, 1, 1) == '-' then
                Data['CustomMoneyNeg'] = true
            else
                Data['CustomMoneyNeg'] = nil
            end
            Data['CustomMoneyLock'] = formatmoneytext(txt)
        end
        applymoneylock()
        applywalletmoneytext()
    end,
})
