task.spawn(function()
    while not (Library and Library.Unloaded) do
        local playerGui = LocalPlayer:FindFirstChild('PlayerGui')
        local mainScreenGui = playerGui and playerGui:FindFirstChild('MainScreenGui')
        if mainScreenGui and mainScreenGui ~= Data['CustomStatBarsHookedGui'] then
            Data['CustomStatBarsHookedGui'] = mainScreenGui
            create_connection(
                'Top_19_mainScreenGui_ChildAdded_Connect_functio',
                connectshared(mainScreenGui.ChildAdded, function(child)
                    if child.Name == 'Bar' then
                        task.wait(0.5)
                        if Library and Library.Unloaded then
                            return
                        end
                        if Toggles.custom_stat_bars and Toggles.custom_stat_bars.Value then
                            ensurecustomstatbars(8)
                        end
                    end
                end, mainScreenGui, 'event/mainScreenGui.ChildAdded', 0, 'event/ChildAdded', mainScreenGui)
            )
        end
        local bar = mainScreenGui and mainScreenGui:FindFirstChild('Bar')
        if bar and bar ~= Data['StatBarsHookedBar'] then
            Data['StatBarsHookedBar'] = bar
            create_connection(
                'Top_20_bar_DescendantAdded_Connect_function_chi',
                connectshared(bar.DescendantAdded, function(child)
                    if child.Name == string.char(0) then
                        return
                    end
                    Data['StatBarsReapplyAt'] = tick() + 0.5
                end, bar, 'event/bar.DescendantAdded', 0, 'event/DescendantAdded', bar)
            )
        end
        if Data['StatBarsReapplyAt'] ~= 0 and tick() >= Data['StatBarsReapplyAt'] then
            Data['StatBarsReapplyAt'] = 0
            if Toggles.custom_stat_bars and Toggles.custom_stat_bars.Value then
                ensurecustomstatbars(8)
            end
        end
        task.wait(1)
    end
end)
