do
    local last_update = tick()
    local last_freeze = tick()
    local freeze = false
    local old_positions = {}
    setmetatable(old_positions, { __mode = 'k' })
    local last_updatez = tick()
    local doLag = function()
        if tick() - last_updatez < 0.02 then
            return
        end
        last_updatez = tick()
        if not (Toggles.animation_lag and Toggles.animation_lag.Value) then
            return
        end
        local humanoid = LocalPlayer.Character and LocalPlayer.Character:FindFirstChildOfClass('Humanoid')
        if not humanoid then
            return
        end
        local lagVal = (Options.animation_lag_value and Options.animation_lag_value.Value) or 25
        if tick() - last_update > lagVal / 150 then
            last_update = tick()
            task.delay(0, function()
                last_freeze = tick()
            end)
            freeze = false
        else
            freeze = true
        end
        for _, animation in ipairs(humanoid:GetPlayingAnimationTracks()) do
            if not freeze then
                old_positions[animation] = animation.TimePosition + tick() - last_freeze
            else
                animation.TimePosition = (old_positions[animation] or 0)
            end
        end
    end
    create_connection(
        'Top_23_RunService_Heartbeat_Connect_doLag_RunSe',
        connectshared(RunService.Heartbeat, doLag, RunService, 'frame/animation lag', 0, 'event/Heartbeat', RunService)
    )
end
do
    local materialCharacter = nil
    local materialParts = setmetatable({}, { __mode = 'k' })
    local appearances = {}
    Data.LocalModelsOrig = setmetatable(Data.LocalModelsOrig or {}, { __mode = 'k' })
    local function restore_material(part)
        phowg:restore_material_part(part, Data.LocalModelsOrig)
    end
    local function kind_for(object)
        local record = appearances[object]
        local parent = object.Parent or record and record.Parent
        local kind = 'body'
        while parent and parent ~= materialCharacter do
            if parent:IsA('Tool') then
                kind = 'tools'
            elseif parent:IsA('Accessory') and kind ~= 'tools' then
                kind = 'hats'
            end
            parent = parent.Parent
        end
        return parent == materialCharacter and kind or nil
    end
    local function active_kind(kind)
        local toggle = kind == 'tools' and Toggles.local_material_tools
            or kind == 'hats' and Toggles.local_forcefield_hats
            or kind == 'body' and Toggles.local_forcefield_body
        return not Library.Unloaded and not Data.Unloading and toggle and toggle.Value == true
    end
    local function apply_appearance(object)
        if Data.LocalMaterialsSuspendedCharacter == materialCharacter then
            return
        end
        local kind = kind_for(object)
        Data.LocalAppearanceChanging = true
        phowg:material_appearance(
            object,
            kind ~= nil and active_kind(kind) and object.Name ~= 'HumanoidRootPart',
            appearances
        )
        Data.LocalAppearanceChanging = nil
    end
    local function apply_material(part)
        if Data.LocalMaterialsSuspendedCharacter == materialCharacter or not part:IsA('BasePart') then
            return
        end
        local kind = kind_for(part)
        if not kind then
            restore_material(part)
            return
        end
        materialParts[part] = true
        if not active_kind(kind) or kind == 'body' and part.Name == 'HumanoidRootPart' then
            restore_material(part)
            return
        end
        local option = kind == 'tools' and Options.local_material_tools_color
            or kind == 'hats' and Options.local_forcefield_hats_color
            or Options.local_forcefield_body_color
        local color = option and option.Value or Color3.fromRGB(255, 255, 255)
        local material = kind == 'tools'
                and Options.local_material_tools_value
                and Options.local_material_tools_value.Value == 'neon'
                and Enum.Material.Neon
            or Enum.Material.ForceField
        if not Data.LocalModelsOrig[part] then
            Data.LocalModelsOrig[part] = { m = part.Material, c = part.Color }
        end
        if part.Material ~= material then
            part.Material = material
        end
        if part.Color ~= color then
            part.Color = color
        end
    end
    local function restore_all()
        Data.LocalAppearanceChanging = true
        phowg:restore_material_appearances(appearances)
        Data.LocalAppearanceChanging = nil
        for part in pairs(Data.LocalModelsOrig) do
            restore_material(part)
        end
    end
    function phowg:bind_local_materials(character)
        if materialCharacter == character then
            return
        end
        restore_all()
        table.clear(materialParts)
        materialCharacter = character
        if not character then
            return
        end
        for _, object in ipairs(character:GetDescendants()) do
            apply_material(object)
            apply_appearance(object)
        end
    end
    function phowg:local_material_added(object)
        if Data.LocalAppearanceChanging then
            return
        end
        apply_material(object)
        apply_appearance(object)
    end
    function phowg:local_material_removed(object)
        if Data.LocalAppearanceChanging then
            return
        end
        if object:IsA('BasePart') then
            restore_material(object)
            materialParts[object] = nil
        end
        Data.LocalAppearanceChanging = true
        phowg:material_appearance(object, false, appearances)
        Data.LocalAppearanceChanging = nil
    end
    function phowg:refresh_local_materials()
        phowg:bind_local_materials(LocalPlayer.Character)
        if not materialCharacter or Data.LocalMaterialsSuspendedCharacter == materialCharacter then
            return
        end
        for part in pairs(materialParts) do
            apply_material(part)
        end
        for object in pairs(appearances) do
            apply_appearance(object)
        end
        for _, object in ipairs(materialCharacter:GetDescendants()) do
            apply_material(object)
            apply_appearance(object)
        end
    end
    function phowg:suspend_local_materials(character)
        if character ~= materialCharacter then
            return
        end
        Data.LocalMaterialsSuspendedCharacter = character
        restore_all()
    end
    function phowg:resume_local_materials(character)
        if Data.LocalMaterialsSuspendedCharacter == character then
            Data.LocalMaterialsSuspendedCharacter = nil
        end
        if character == LocalPlayer.Character and not Library.Unloaded then
            phowg:refresh_local_materials()
        end
    end
    phowg:register_cleanup('local materials', function(scope, reason)
        if not scope or reason == 'unload' or scope == materialCharacter then
            restore_all()
            phowg:bind_local_materials(nil)
        end
        if reason == 'unload' or scope == Data.LocalMaterialsSuspendedCharacter then
            Data.LocalMaterialsSuspendedCharacter = nil
        end
    end)
    phowg:bind_local_materials(LocalPlayer.Character)
    for _, name in ipairs({ 'local_forcefield_body', 'local_forcefield_hats', 'local_material_tools' }) do
        if Toggles[name] then
            Toggles[name]:OnChanged(phowg.refresh_local_materials)
        end
    end
    for _, name in ipairs({
        'local_forcefield_body_color',
        'local_forcefield_hats_color',
        'local_material_tools_color',
        'local_material_tools_value',
    }) do
        if Options[name] then
            Options[name]:OnChanged(phowg.refresh_local_materials)
        end
    end
    function phowg:set_local_headless(enabled)
        phowg:set_character_observer('headless', enabled, function(state, character)
            local originals, partConnections, sequence = {}, {}, 0
            state.Restore = function()
                for part, transparency in pairs(originals) do
                    if part.Parent then
                        part.Transparency = transparency
                    end
                end
            end
            local function observe(part)
                local head = character:FindFirstChild('Head')
                if
                    not head
                    or not (part == head or part:IsA('Decal') and part:IsDescendantOf(head))
                    or originals[part] ~= nil
                then
                    return
                end
                originals[part] = part.Transparency
                sequence += 1
                local key = 'transparency/' .. sequence
                partConnections[part] = key
                state.Connections[key] = connectshared(part:GetPropertyChangedSignal('Transparency'), function()
                    if not state.Closed and state.Character == character and part.Parent and part.Transparency ~= 1 then
                        part.Transparency = 1
                    end
                end, part, 'headless/transparency', 0, 'property/Transparency', part)
                if part.Transparency ~= 1 then
                    part.Transparency = 1
                end
            end
            state.Connections.Added = connectshared(character.DescendantAdded, function(part)
                observe(part)
                if part.Name == 'Head' and part.Parent == character then
                    for _, child in ipairs(part:GetDescendants()) do
                        observe(child)
                    end
                end
            end, character, 'headless/added', 0, 'event/DescendantAdded', character)
            state.Connections.Removed = connectshared(character.DescendantRemoving, function(part)
                local key = partConnections[part]
                if key then
                    state.Connections[key]:Disconnect()
                    state.Connections[key], partConnections[part] = nil, nil
                    local original = originals[part]
                    originals[part] = nil
                    if original ~= nil then
                        part.Transparency = original
                    end
                end
            end, character, 'headless/removed', 0, 'event/DescendantRemoving', character)
            local head = character:FindFirstChild('Head')
            if head then
                observe(head)
                for _, part in ipairs(head:GetDescendants()) do
                    observe(part)
                end
            end
        end)
    end
    Toggles.local_headless:OnChanged(phowg_callbacks.set_local_headless)
    phowg:set_local_headless(Toggles.local_headless.Value)
    local function update_forcefield()
        local char = LocalPlayer.Character
        phowg:bind_local_materials(char)
        if not char then
            return
        end
        updatekorbloxchar(char, Toggles.local_korblox and Toggles.local_korblox.Value or false)
    end
    local trailCharacter, trailItems, trailColor, trailLife
    local trailConnections = {}
    local function ensure_trail()
        local char = LocalPlayer.Character
        if not (Toggles.local_trail and Toggles.local_trail.Value) or not char then
            if Data['TrailCleaned'] == char then
                return
            end
            Data['TrailCleaned'] = char
            trailItems, trailColor, trailLife = nil, nil, nil
            if char then
                for _, a in ipairs(char:GetDescendants()) do
                    if a.Name == 'SFXTRAIL' or a.Name == 'Attachment0' or a.Name == 'Attachment1' then
                        a:Destroy()
                    end
                end
            end
            if Data['VisualizeModel'] then
                for _, a in ipairs(Data['VisualizeModel']:GetDescendants()) do
                    if
                        a:IsA('Trail')
                        or a:IsA('beam')
                        or a:IsA('ParticleEmitter')
                        or a.Name == 'SFXTRAIL'
                        or a.Name == 'Attachment0'
                        or a.Name == 'Attachment1'
                    then
                        a:Destroy()
                    end
                end
            end
            return
        end
        if trailCharacter ~= char then
            for _, connection in ipairs(trailConnections) do
                connection:Disconnect()
            end
            trailConnections = {}
            trailCharacter, trailItems, trailColor, trailLife = char, nil, nil, nil
            local function invalidate(part)
                if part:IsA('BasePart') or part:IsA('Trail') then
                    trailItems = nil
                end
            end
            trailConnections[#trailConnections + 1] =
                connectshared(char.DescendantAdded, invalidate, char, 'trail added', 0, 'event/DescendantAdded', char)
            trailConnections[#trailConnections + 1] = connectshared(
                char.DescendantRemoving,
                invalidate,
                char,
                'trail removed',
                0,
                'event/DescendantRemoving',
                char
            )
        end
        local root = getroot(char)
        if not root then
            return
        end
        local col = (Options.local_trail_color and Options.local_trail_color.Value) or Color3.fromRGB(255, 255, 255)
        local life = (Options.local_trail_lifetime and Options.local_trail_lifetime.Value) or 1
        if trailItems and trailColor == col and trailLife == life then
            return
        end
        if not trailItems then
            for _, v in ipairs(char:GetChildren()) do
                if
                    v:IsA('BasePart')
                    and v ~= root
                    and not string.match(v.Name, 'Fake')
                    and not v:FindFirstChild('SFXTRAIL')
                then
                    local Trail = Instance.new('Trail')
                    Trail.Texture = 'rbxassetid://1390780157'
                    Trail.Name = 'SFXTRAIL'
                    local Attachment0 = Instance.new('Attachment')
                    Attachment0.Name = 'Attachment0'
                    Attachment0.Parent = v
                    local Attachment1 = Instance.new('Attachment')
                    Attachment1.Name = 'Attachment1'
                    Attachment1.Parent = root
                    Trail.Color =
                        ColorSequence.new({ ColorSequenceKeypoint.new(0, col), ColorSequenceKeypoint.new(1, col) })
                    Trail.Lifetime = life
                    Trail.Attachment0 = Attachment0
                    Trail.Attachment1 = Attachment1
                    Trail.Parent = v
                end
            end
        end
        if not trailItems then
            trailItems = {}
            for _, part in ipairs(char:GetDescendants()) do
                if part.Name == 'SFXTRAIL' and part:IsA('Trail') then
                    trailItems[#trailItems + 1] = part
                end
            end
        end
        local sequence = ColorSequence.new({ ColorSequenceKeypoint.new(0, col), ColorSequenceKeypoint.new(1, col) })
        for _, a in ipairs(trailItems) do
            if a.Name == 'SFXTRAIL' and a:IsA('Trail') then
                a.Color = sequence
                a.Lifetime = life
            end
        end
        trailColor, trailLife = col, life
        Data['TrailCleaned'] = nil
    end
    phowg:register_cleanup('local trails', function(scope, reason)
        if reason == 'unload' or scope == trailCharacter then
            for _, connection in ipairs(trailConnections) do
                connection:Disconnect()
            end
            trailConnections = {}
            trailCharacter, trailItems, trailColor, trailLife = nil, nil, nil, nil
        end
    end)
