    local function aura_color_seq()
        local c = (Options.local_particle_aura_color and Options.local_particle_aura_color.Value)
            or Color3.fromRGB(0, 255, 38)
        return ColorSequence.new({ ColorSequenceKeypoint.new(0, c), ColorSequenceKeypoint.new(1, c) })
    end
    local function clear_aura_emitters()
        if AuraPart then
            for _, ch in ipairs(AuraPart:GetChildren()) do
                ch:Destroy()
            end
        end
    end
    local AuraCharacter, AuraEmitters = nil, {}
    function phowg:native_aura_template(name)
        Data.NativeAuraTemplates = Data.NativeAuraTemplates or {}
        if Data.NativeAuraTemplates[name] then
            return Data.NativeAuraTemplates[name]
        end
        local properties = AuraTemplates[name]
        if not properties then
            return nil
        end
        local folder = Instance.new('Folder')
        folder.Name = name
        for index, props in ipairs(properties) do
            local emitter = Instance.new('ParticleEmitter')
            for key, value in pairs(props) do
                emitter[key] = value
            end
            emitter.Name, emitter.Enabled, emitter.Parent = tostring(index), false, folder
        end
        Data.NativeAuraTemplates[name] = folder
        phowg:queue_asset_tree(folder)
        return folder
    end
    function phowg:warm_native_aura_caches()
        local assets = {}
        for _, properties in pairs(AuraTemplates) do
            for _, emitter in ipairs(properties) do
                if type(emitter.Texture) == 'string' then
                    assets[#assets + 1] = emitter.Texture
                end
            end
        end
        phowg:queue_assets(assets)
    end
    local function rebuild_aura()
        phowg:sync_symbol_auras()
        local doAura = Toggles.local_particle_aura and Toggles.local_particle_aura.Value
        local auraType = (Options.local_particle_aura_value and Options.local_particle_aura_value.Value) or 'swirl'
        local symbolAura = Data.SymbolAuraNames[auraType]
        auraType = string.upper(string.sub(tostring(auraType), 1, 1)) .. string.lower(string.sub(tostring(auraType), 2))
        if not doAura or symbolAura then
            if AuraPart then
                AuraPart:Destroy()
            end
            AuraPart = nil
            Data['AuraPart'] = nil
            AuraCharacter, AuraEmitters = nil, {}
            return
        end
        local char = LocalPlayer.Character
        local hrp = char and char:FindFirstChild('HumanoidRootPart')
        if Data.IsRespawning or not hrp then
            return
        end
        if not AuraPart or not AuraPart.Parent then
            AuraPart = Instance.new('Part')
            AuraPart.Size = Vector3.new(0.01, 0.01, 0.01)
            AuraPart.Transparency = 1
            AuraPart.Anchored = true
            AuraPart.CanCollide = false
            AuraPart.CanQuery = false
            AuraPart.CanTouch = false
            AuraPart.Parent = Workspace
            Data['AuraPart'] = AuraPart
        end
        clear_aura_emitters()
        AuraCharacter, AuraEmitters = char, {}
        local list = AuraTemplates[auraType] or AuraTemplates.Swirl
        local seq = nil
        seq = aura_color_seq()
        if not seq then
            seq = ColorSequence.new(Color3.fromRGB(0, 255, 38))
        end
        for _, props in ipairs(list) do
            local template = phowg:native_aura_template(auraType)
            local e = template and template:FindFirstChild(tostring(#AuraEmitters + 1)):Clone()
                or Instance.new('ParticleEmitter')
            if not template then
                for k, v in pairs(props) do
                    e[k] = v
                end
            end
            e.Color = seq
            e.Enabled = true
            e.Parent = AuraPart
            AuraEmitters[#AuraEmitters + 1] = e
        end
        phowg:preload_visual_assets(AuraEmitters)
        AuraPart.Size = AuraSizes[auraType] or Vector3.new(0.01, 0.01, 0.01)
        AuraOffset = AuraOffsets[auraType] or Vector3.new()
        AuraPart.CFrame = hrp.CFrame + AuraOffset
    end
    Data['AuraTemplates'] = AuraTemplates
    if Toggles.local_particle_aura then
        Toggles.local_particle_aura:OnChanged(function()
            rebuild_aura()
        end)
    end
    if Options.local_particle_aura_value then
        Options.local_particle_aura_value:OnChanged(function()
            rebuild_aura()
        end)
    end
    if Options.local_particle_aura_color then
        Options.local_particle_aura_color:OnChanged(function()
            phowg:sync_symbol_auras()
            local seq = aura_color_seq()
            if AuraPart then
                for _, ch in ipairs(AuraEmitters) do
                    if ch:IsA('ParticleEmitter') then
                        ch.Color = seq
                    end
                end
            end
        end)
    end
    create_connection(
        'Top_24_RunService_Heartbeat_Connect_function_en',
        connectshared(RunService.Heartbeat, function()
            ensure_trail()
            update_forcefield()
            phowg:sync_symbol_auras()
            if Data.IsRespawning then
                if AuraPart then
                    AuraPart:Destroy()
                    AuraPart = nil
                    Data.AuraPart = nil
                end
                return
            end
            if
                Toggles.local_particle_aura
                and Toggles.local_particle_aura.Value
                and not Data.SymbolAuraNames[Options.local_particle_aura_value and Options.local_particle_aura_value.Value]
            then
                local char = LocalPlayer.Character
                local hrp = char and char:FindFirstChild('HumanoidRootPart')
                if hrp then
                    if not AuraPart or not AuraPart.Parent or AuraCharacter ~= char or #AuraEmitters == 0 then
                        rebuild_aura()
                    else
                        local cf = hrp.CFrame + AuraOffset
                        if AuraPart.CFrame ~= cf then
                            AuraPart.CFrame = cf
                        end
                    end
                end
            elseif AuraPart then
                AuraPart:Destroy()
                AuraPart = nil
                Data['AuraPart'] = nil
            end
        end, RunService, 'frame/character visuals', 0, 'event/Heartbeat', RunService)
    )
    local function models_enabled()
        return not Library.Unloaded
            and not Data.Unloading
            and (
                Toggles.forcefield_hats2 and Toggles.forcefield_hats2.Value
                or Toggles.body_material and Toggles.body_material.Value
            )
    end
    function phowg:restore_remote_materials(scope, kind)
        for part, original in pairs(Data.ModelsOrig or {}) do
            local belongs = not scope
                or original.Character == scope
                or original.Player == scope
                or typeof(scope) == 'Instance' and part:IsDescendantOf(scope)
            if belongs and (not kind or original.Kind == kind) then
                phowg:restore_material_part(part, Data.ModelsOrig)
            end
        end
    end
    Data.ModelsOrig = setmetatable(Data.ModelsOrig or {}, { __mode = 'k' })
    local function apply_model_part(player, character, part)
        if not part:IsA('BasePart') or part.Name == 'HumanoidRootPart' then
            return
        end
        local kind = part:FindFirstAncestorOfClass('Accessory') and 'hats' or 'body'
        local toggle = kind == 'hats' and Toggles.forcefield_hats2 or Toggles.body_material
        local enabled = models_enabled() and toggle and toggle.Value
        if not enabled then
            phowg:restore_material_part(part, Data.ModelsOrig)
            return
        end
        if not Data.ModelsOrig[part] then
            Data.ModelsOrig[part] = {
                m = part.Material,
                c = part.Color,
                Kind = kind,
                Character = character,
                Player = player,
            }
        end
        local option = kind == 'hats' and Options.forcefield_hats2_color or Options.body_material_color
        local material = kind == 'body'
                and Options.body_material_value
                and Options.body_material_value.Value == 'neon'
                and Enum.Material.Neon
            or Enum.Material.ForceField
        local color = option and option.Value or Color3.new(1, 1, 1)
        if part.Material ~= material then
            part.Material = material
        end
        if part.Color ~= color then
            part.Color = color
        end
    end
    local function apply_models_esp()
        for part, original in pairs(Data.ModelsOrig) do
            local toggle = original.Kind == 'hats' and Toggles.forcefield_hats2 or Toggles.body_material
            if
                not models_enabled()
                or not toggle
                or not toggle.Value
                or original.Player.Character ~= original.Character
                or not part:IsDescendantOf(original.Character)
            then
                phowg:restore_material_part(part, Data.ModelsOrig)
            end
        end
        if not models_enabled() then
            return
        end
        for _, player in ipairs(Players:GetPlayers()) do
            local character = player.Character
            if player ~= LocalPlayer and character and character.Parent then
                for _, part in ipairs(character:GetDescendants()) do
                    apply_model_part(player, character, part)
                end
            end
        end
    end
    local modelObservers = {}
    local function unbind_model_character(observer)
        for _, connection in ipairs(observer.CharacterConnections) do
            connection:Disconnect()
        end
        table.clear(observer.CharacterConnections)
        if observer.Character then
            phowg:restore_remote_materials(observer.Character)
            observer.Character = nil
        end
    end
    local function unwatch_model_player(player)
        local observer = modelObservers[player]
        if not observer then
            return
        end
        unbind_model_character(observer)
        for _, connection in ipairs(observer.Connections) do
            connection:Disconnect()
        end
        modelObservers[player] = nil
    end
    local function bind_model_character(player, observer, character)
        unbind_model_character(observer)
        if not models_enabled() or player.Character ~= character then
            return
        end
        observer.Character = character
        observer.CharacterConnections = {
            connectshared(character.DescendantAdded, function(part)
                if models_enabled() and player.Character == character and part:IsDescendantOf(character) then
                    apply_model_part(player, character, part)
                end
            end, character, 'models/part added', 0, 'event/DescendantAdded', character),
            connectshared(character.DescendantRemoving, function(part)
                phowg:restore_material_part(part, Data.ModelsOrig)
            end, character, 'models/part removed', 0, 'event/DescendantRemoving', character),
        }
        for _, part in ipairs(character:GetDescendants()) do
            apply_model_part(player, character, part)
        end
    end
    local function watch_model_player(player)
        if player == LocalPlayer or modelObservers[player] or not models_enabled() then
            return
        end
        local observer = { Connections = {}, CharacterConnections = {}, Character = nil }
        modelObservers[player] = observer
        observer.Connections = {
            connectshared(player.CharacterAdded, function(character)
                bind_model_character(player, observer, character)
            end, player, 'models/respawn', 0, 'event/CharacterAdded', player),
            connectshared(player.CharacterRemoving, function(character)
                if observer.Character == character then
                    unbind_model_character(observer)
                end
            end, player, 'models/character removed', 0, 'event/CharacterRemoving', player),
        }
        if player.Character then
            bind_model_character(player, observer, player.Character)
        end
    end
    phowg:register_cleanup('remote materials', function(scope)
        for player, observer in pairs(modelObservers) do
            if not scope or scope == player then
                unwatch_model_player(player)
            elseif scope == observer.Character then
                unbind_model_character(observer)
            end
        end
        phowg:restore_remote_materials(scope)
    end)
    local function sync_model_observers()
        if models_enabled() then
            for _, player in ipairs(Players:GetPlayers()) do
                watch_model_player(player)
            end
        else
            for player in pairs(modelObservers) do
                unwatch_model_player(player)
            end
        end
        apply_models_esp()
    end
    if Toggles.forcefield_hats2 then
        Toggles.forcefield_hats2:OnChanged(sync_model_observers)
    end
    if Toggles.body_material then
        Toggles.body_material:OnChanged(sync_model_observers)
    end
    for _, name in ipairs({ 'body_material_value', 'forcefield_hats2_color', 'body_material_color' }) do
        if Options[name] then
            Options[name]:OnChanged(apply_models_esp)
        end
    end
    sync_model_observers()
    create_connection(
        'Top_26_Players_PlayerAdded_Connect_function_plr',
        connectshared(
            Players.PlayerAdded,
            watch_model_player,
            Players,
            'models/player added',
            0,
            'event/PlayerAdded',
            Players
        )
    )
    create_connection(
        'ModelsESPPlayerRemoved',
        connectshared(Players.PlayerRemoving, function(player)
            unwatch_model_player(player)
            phowg:restore_remote_materials(player)
        end, Players, 'models/player removed', 0, 'event/PlayerRemoving', Players)
    )
    do
        local hotbarTempConn = nil
        local hotbarConns = {}
        local hotbarConns2 = {}
        local function get_hotbar()
            local ok, result =
                true, (function()
                    return CoreGui.RobloxGui.Backpack.Hotbar
                end)()
            if ok then
                return result
            end
            return nil
        end
        local function get_hotbar_inventory(hotbar)
            local backpack = hotbar and hotbar.Parent
            return backpack and backpack:FindFirstChild('Inventory') or nil
        end
        local function new_hotbar_object(className, props)
            local obj = Instance.new(className)
            for k, v in pairs(props) do
                if k ~= 'Parent' then
                    obj[k] = v
                end
            end
            if props.Parent then
                obj.Parent = props.Parent
            end
            return obj
        end
        local function apply_minimalistic_outline(object)
            local children = object:GetChildren()
            for i = 1, #children do
                local line = children[i]
                if line.ClassName ~= 'Frame' then
                else
                    line.Visible = true
                    line.BackgroundTransparency = 1
                end
            end
            new_hotbar_object('UICorner', { CornerRadius = UDim.new(0, 0), Parent = object, Name = string.char(0) })
            new_hotbar_object('UIStroke', { Thickness = 2, Transparency = 0.56, Name = string.char(0), Parent = object })
            children['Visible'] = true
        end
        local function apply_default_outline(object)
            local children = object:GetChildren()
            for i = 1, #children do
                local line = children[i]
                if #line.Name == 0 then
                    line:Destroy()
                elseif line.ClassName == 'Frame' then
                    line.Visible = true
                    line.BackgroundColor3 = Color3.fromRGB(90, 142, 233)
                    line.BackgroundTransparency = 0
                end
            end
            children['Visible'] = true
        end
        local function update_custom_hotbar(selected)
            local hotbar = get_hotbar()
            if not hotbar then
                return
            end
            for _, descendant in ipairs(hotbar:GetDescendants()) do
                if #descendant.Name == 0 then
                    descendant:Destroy()
                end
            end
            for i = 1, #hotbarConns do
                hotbarConns[i]:Disconnect()
            end
            hotbarConns = {}
            for i = 1, #hotbarConns2 do
                hotbarConns2[i]:Disconnect()
            end
            hotbarConns2 = {}
            local outline_function = selected == 'minimalistic' and apply_minimalistic_outline or apply_default_outline
            if selected == 'minimalistic' then
                for i, object in ipairs(hotbar:GetChildren()) do
                    new_hotbar_object(
                        'UICorner',
                        { CornerRadius = UDim.new(0, 0), Parent = object, Name = string.char(0) }
                    )
                    local num = object:FindFirstChild('Number')
                    if num then
                        num.Font = Enum.Font.GothamMedium
                        num.TextSize = 12
                    end
                    new_hotbar_object('ImageLabel', {
                        ImageColor3 = Color3.fromRGB(0, 0, 0),
                        ScaleType = Enum.ScaleType.Slice,
                        ImageTransparency = 0.8,
                        AnchorPoint = Vector2.new(0.5, 0.5),
                        Image = 'rbxassetid://1316045217',
                        BackgroundTransparency = 1,
                        Position = UDim2.new(0.5, 0, 0.5, 0),
                        Name = string.char(0),
                        ZIndex = 0,
                        Size = UDim2.new(1, 6, 1, 6),
                        SliceCenter = Rect.new(Vector2.new(10, 10), Vector2.new(118, 118)),
                        Parent = object,
                    })
                    local outline = object:FindFirstChild('Equipped')
                    if outline then
                        task.spawn(outline_function, outline)
                    end
                    hotbarConns[i] = create_connection(
                        'Top_27_hotbarConns_i_object_ChildAdded_Conne',
                        connectshared(
                            object.ChildAdded,
                            outline_function,
                            object,
                            'event/object.ChildAdded',
                            0,
                            'event/ChildAdded',
                            object
                        )
                    )
                    hotbarConns2[i] = create_connection(
                        'Top_28_hotbarConns2_i_object_ChildRemoved_Co',
                        connectshared(
                            object.ChildRemoved,
                            apply_default_outline,
                            object,
                            'event/object.ChildRemoved',
                            0,
                            'event/ChildRemoved',
                            object
                        )
                    )
                end
            elseif selected == 'default' then
                for _, object in ipairs(hotbar:GetChildren()) do
                    local outline = object:FindFirstChild('Equipped')
                    if outline then
                        task.spawn(apply_default_outline, outline)
                    end
                    local num = object:FindFirstChild('Number')
                    if num then
                        num.Font = Enum.Font.SourceSans
                        num.TextSize = 14
                    end
                end
            end
        end
        local function hotbar_selected()
            return (Options.custom_hotbar_value and Options.custom_hotbar_value.Value) or 'default'
        end
        if Toggles.custom_hotbar then
            Toggles.custom_hotbar:OnChanged(function(v)
                if hotbarTempConn then
                    hotbarTempConn:Disconnect()
