    do
        local visuals, recentShots = {}, {}
        local visualCost = 0
        local shots = { Items = {}, Head = 1, Tail = 0 }
        local traced = setmetatable({}, { __mode = 'k' })
        local pendingRays = {}
        local rayContainer = nil
        local rayConnections = {}
        local rayDeferred = false
        local rayGeneration = 0
        local restorePendingRays = nil
        local syncDefaultRays = nil
        local captureState = nil
        local captureWarning = false
        local function valid_point(point)
            return typeof(point) == 'Vector3'
                and point.X == point.X
                and point.Y == point.Y
                and point.Z == point.Z
                and math.abs(point.X) < 1e8
                and math.abs(point.Y) < 1e8
                and math.abs(point.Z) < 1e8
        end
        local function enabled(name)
            return Toggles[name] and Toggles[name].Value
        end
        local targetSources = {
            { 'RifleTarget', 'Ragebot' },
            { 'GunFocusTarget', 'Ragebot' },
            { 'CurrentActionTarget', 'Ragebot' },
            { 'RapeTarget', 'Support' },
            { 'KillAuraTarget', 'KillAura' },
            { 'SilentAimTarget', 'SilentAim' },
            { 'AssistLockedTarget', 'AimAssist' },
            { 'StickyTarget', 'StickyAim' },
            { 'TargetStrafeTarget', 'TargetStrafe' },
        }
        local function key_active(name)
            local key = Options[name]
            if not key then
                return false
            end
            if key.Mode == 'Always' then
                return true
            end
            if not key.AllowWhileTyping and UserInputService.GetFocusedTextBox(UserInputService) then
                return false
            end
            if key.Mode ~= 'Hold' then
                return key.Toggled == true
            end
            local value = key.Value
            if value == 'MB1' or value == 'MB2' then
                return UserInputService.IsMouseButtonPressed(
                    UserInputService,
                    value == 'MB1' and Enum.UserInputType.MouseButton1 or Enum.UserInputType.MouseButton2
                )
            end
            local code = value and Enum.KeyCode[value]
            return code ~= nil and UserInputService.IsKeyDown(UserInputService, code)
        end
        local function perfect_source_active(source)
            if source == 'Ragebot' then
                return Data.PunishmentGunActive == true
                    or phowg:target_search_engaged()
                    or phowg:auto_bounty_enabled()
                    or (enabled('ragebot_enable') and Data.RagebotActive == true and key_active('ragebot_enable_key'))
            end
            if source == 'Support' then
                return phowg:israel_support_enabled() and not Data.PunishmentGunActive and enabled('full_rage')
            end
            if source == 'KillAura' then
                return enabled('kill_aura_enabled') and key_active('kill_aura_keybind')
            end
            if source == 'SilentAim' then
                return enabled('silent_aim_enabled') and key_active('silent_aim_keybind')
            end
            if source == 'AimAssist' then
                return enabled('aim_assist_enabled') and key_active('aim_assist_key')
            end
            if source == 'StickyAim' then
                return enabled('sticky_aim_enabled')
            end
            if source == 'TargetStrafe' then
                return enabled('target_strafe_enabled')
                    and Data.TargetStrafeActive == true
                    and key_active('target_strafe_key')
            end
            return false
        end
        local function perfect_target_match(target, hitPart, validHit, source)
            if not target or target == LocalPlayer or not target.Parent then
                return false, false
            end
            if source == 'Support' and Data.SupportCompletedTargets and Data.SupportCompletedTargets[target] then
                return false, false
            end
            local character = target.Character
            if not character or not character.Parent then
                return false, false
            end
            local humanoid = character.FindFirstChildOfClass(character, 'Humanoid')
            if
                not humanoid
                or humanoid.Health <= 0
                    and not (phowg:current_sticky_shot(target, source) and phowg:sticky_shoot_allowed(target))
            then
                return false, false
            end
            return validHit and hitPart.IsDescendantOf(hitPart, character), true
        end
        function phowg:perfect_bullet_allowed(hitPart)
            local aura = Data.HeldGunFire
            if
                aura
                and aura.Owner == 'KillAura'
                and (phowg:kill_aura_in_void() or not killauravalidtarget(aura.Target))
            then
                return false
            end
            if phowg:sticky_shot_blocked() then
                return false
            end
            if not enabled('perfect_bullets') then
                return true
            end
            local validHit = typeof(hitPart) == 'Instance' and hitPart.IsA(hitPart, 'BasePart')
            local hasTarget = false
            local held = Data.HeldGunFire
            if
                held
                and held.Tool
                and held.Character == LocalPlayer.Character
                and held.Tool.Parent == held.Character
                and perfect_source_active(held.Owner)
            then
                local hit, found = perfect_target_match(held.Target, hitPart, validHit, held.Owner)
                if hit then
                    return true
                end
                hasTarget = found
            end
            local previousTarget = nil
            for _, entry in ipairs(targetSources) do
                local target = Data[entry[1]]
                if target and target ~= previousTarget and perfect_source_active(entry[2]) then
                    previousTarget = target
                    local hit, found = perfect_target_match(target, hitPart, validHit, entry[2])
                    if hit then
                        return true
                    end
                    hasTarget = hasTarget or found
                end
            end
            return not hasTarget
        end
        local function remove_visual(visual)
            phowg:release_visual(visual)
            visualCost -= visual.Cost or 0
            visual.Cost = 0
            for _, object in ipairs(visual.Objects) do
                pcall(function()
                    if typeof(object) == 'Instance' then
                        object:Destroy()
                    else
                        object:Remove()
                    end
                end)
            end
        end
        local function new_visual(kind, lifetime, cost)
            cost = cost or 1
            while visualCost + cost > 256 and #visuals > 0 do
                remove_visual(visuals[1])
                visuals[1] = visuals[#visuals]
                visuals[#visuals] = nil
            end
            local visual = {
                Kind = kind,
                Cost = cost,
                Lifetime = lifetime,
                At = tick(),
                Objects = {},
                Line = nil,
                Outline = nil,
                Segments = nil,
                Beam = nil,
                Part = nil,
                Start = nil,
                Finish = nil,
                FadeDuration = 0.25,
                Alpha = 0,
                EndAlpha = 0,
                Fade = -1,
            }
            if not phowg:acquire_visual(visual, cost * 2, 'tracers') then
                return nil
            end
            visualCost += cost
            visuals[#visuals + 1] = visual
            return visual
        end
        local function tracer_number(name, fallback, minimum, maximum)
            local value = tonumber(Options[name] and Options[name].Value)
            if not value or value ~= value or math.abs(value) == math.huge then
                return fallback
            end
            return math.clamp(value, minimum, maximum)
        end
        local function tracer_style(prefix, isLocal)
            local colorOption = Options[prefix .. '_color']
            local color = colorOption and colorOption.Value
            if typeof(color) ~= 'Color3' then
                color = isLocal and Color3.fromRGB(0, 213, 255) or Color3.fromRGB(252, 136, 3)
            end
            local gradient = enabled(prefix .. '_gradient')
            local endOption = gradient and Options[prefix .. '_end_color'] or colorOption
            local endColor = endOption and endOption.Value
            if typeof(endColor) ~= 'Color3' then
                endColor = color
            end
            local alpha = tonumber(colorOption and colorOption.Transparency) or 0
            local endAlpha = tonumber(endOption and endOption.Transparency) or alpha
            if alpha ~= alpha or math.abs(alpha) == math.huge then
                alpha = 0
            end
            if endAlpha ~= endAlpha or math.abs(endAlpha) == math.huge then
                endAlpha = alpha
            end
            local fade = Toggles[prefix .. '_fade']
            return {
                Color = color,
                EndColor = gradient and endColor or color,
                Gradient = gradient,
                Alpha = math.clamp(alpha, 0, 1),
                EndAlpha = math.clamp(gradient and endAlpha or alpha, 0, 1),
                WidthStart = tracer_number(prefix .. '_width_start', 1, 0.1, 10),
                WidthEnd = tracer_number(prefix .. '_width_end', 1, 0.1, 10),
                BeamWidthStart = tracer_number(prefix .. '_beam_width_start', 0.06, 0.01, 1),
                BeamWidthEnd = tracer_number(prefix .. '_beam_width_end', 0.06, 0.01, 1),
                Texture = tostring(
                    Options[prefix .. '_texture'] and Options[prefix .. '_texture'].Value or '446111271'
                ),
                TextureSpeed = tracer_number(prefix .. '_texture_speed', 0, -10, 10),
                TextureLength = tracer_number(prefix .. '_texture_length', 10, 0.1, 50),
                Lifetime = tracer_number(prefix .. '_lifetime', 0.6, 0.1, 5),
                FadeDuration = (not fade or fade.Value) and tracer_number(prefix .. '_fade_duration', 0.25, 0.05, 5)
                    or 0,
            }
        end
        local function drawing_tracer(startPos, endPos, style)
            if not Drawing or not Drawing.new then
                return
            end
            local count = (
                style.WidthStart ~= style.WidthEnd
                or (style.Gradient and (style.Color ~= style.EndColor or style.Alpha ~= style.EndAlpha))
            )
                    and 8
                or 1
            local visual = new_visual('drawing', style.Lifetime, count)
            if not visual then
                return
            end
            visual.Start, visual.Finish, visual.FadeDuration = startPos, endPos, style.FadeDuration
            visual.Segments = {}
            for index = 1, count do
                local blend = count > 1 and (index - 1) / (count - 1) or 0
                local opacity = 1 - (style.Alpha + (style.EndAlpha - style.Alpha) * blend)
                local color = count > 1 and style.Color:Lerp(style.EndColor, blend) or style.Color
                local line = Drawing.new('Line')
                visual.Objects[#visual.Objects + 1] = line
                local width = style.WidthStart + (style.WidthEnd - style.WidthStart) * blend
                line.Thickness, line.Color, line.Transparency, line.ZIndex, line.Visible =
                    width, color, opacity, 2, false
                local outline = Drawing.new('Line')
                visual.Objects[#visual.Objects + 1] = outline
                outline.Thickness, outline.Color, outline.Transparency, outline.ZIndex, outline.Visible =
                    width + 2, Color3.fromRGB(0, 0, 0), opacity, 1, false
                visual.Segments[index] = { Line = line, Outline = outline, Opacity = opacity }
            end
            visual.Line, visual.Outline = visual.Segments[1].Line, visual.Segments[1].Outline
        end
        local function beam_transparency(startAlpha, endAlpha)
            return startAlpha == endAlpha and NumberSequence.new(startAlpha)
                or NumberSequence.new({
                    NumberSequenceKeypoint.new(0, startAlpha),
                    NumberSequenceKeypoint.new(1, endAlpha),
                })
        end
        local function beam_tracer(startPos, endPos, style)
            local visual = new_visual('beam', style.Lifetime)
            if not visual then
                return
            end
            visual.FadeDuration, visual.Alpha, visual.EndAlpha = style.FadeDuration, style.Alpha, style.EndAlpha
            local startAttachment = Instance.new('Attachment')
            visual.Objects[#visual.Objects + 1] = startAttachment
            startAttachment.CFrame, startAttachment.Parent = CFrame.new(startPos), Workspace.Terrain
            local endAttachment = Instance.new('Attachment')
            visual.Objects[#visual.Objects + 1] = endAttachment
            endAttachment.CFrame, endAttachment.Parent = CFrame.new(endPos), Workspace.Terrain
            local beam = Instance.new('Beam')
            visual.Objects[#visual.Objects + 1] = beam
            visual.Beam = beam
            beam.Texture, beam.TextureMode, beam.TextureLength =
                'rbxassetid://' .. (style.Texture:match('%d+') or '446111271'),
                Enum.TextureMode.Wrap,
                style.TextureLength
            beam.TextureSpeed, beam.Width0, beam.Width1 = style.TextureSpeed, style.BeamWidthStart, style.BeamWidthEnd
            beam.LightEmission, beam.LightInfluence, beam.FaceCamera = 1, 1, true
            beam.Color, beam.Attachment0, beam.Attachment1 =
                ColorSequence.new(style.Color, style.EndColor), startAttachment, endAttachment
            beam.Transparency = beam_transparency(style.Alpha, style.EndAlpha)
            beam.Parent = Workspace:FindFirstChild('Ignored') or Workspace
        end
        local function default_china_tracer(startPos, endPos)
            local template = ReplicatedStorage:FindFirstChild('GunBeam')
            if not template or not template:IsA('Beam') then
                return
            end
            local visual = new_visual('default beam', 0.4)
            if not visual then
                return
            end
            visual.FadeDuration = 0
            local startAttachment = Instance.new('Attachment')
            visual.Objects[#visual.Objects + 1] = startAttachment
            startAttachment.CFrame, startAttachment.Parent = CFrame.new(startPos), Workspace.Terrain
            local endAttachment = Instance.new('Attachment')
            visual.Objects[#visual.Objects + 1] = endAttachment
            endAttachment.CFrame, endAttachment.Parent = CFrame.new(endPos), Workspace.Terrain
            local beam = template:Clone()
            visual.Objects[#visual.Objects + 1] = beam
            visual.Beam = beam
            beam.Name, beam.Attachment0, beam.Attachment1 = 'PhowgGunBeam', startAttachment, endAttachment
            beam.Enabled = true
            beam.Parent = Workspace:FindFirstChild('Ignored') or Workspace
        end
        local function impact(endPos)
            if not phowg:cosmetic_visible(endPos) then
                return
            end
            local entry = phowg:get_effect('impact', 2, function()
                local part, box = Instance.new('Part'), Instance.new('SelectionBox')
                part.Name, part.Anchored, part.CanCollide, part.CanTouch, part.CanQuery, part.CastShadow =
                    'PhowgImpact', true, false, false, false, false
                part.Material = Enum.Material.Neon
                box.Adornee, box.Parent, box.SurfaceTransparency, box.LineThickness = part, part, 1, 0.01
                return { Part = part, Box = box }
            end, 64)
            if not entry then
                return
            end
            local size = tracer_number('bullet_impacts_size', 0.2, 0.05, 2)
            entry.Part.Size, entry.Part.CFrame = Vector3.new(size, size, size), CFrame.new(endPos)
            entry.Part.Color = Options.bullet_impacts_color and Options.bullet_impacts_color.Value
                or Color3.new(1, 1, 1)
            entry.Box.Color3 = entry.Part.Color
            entry.Part.Transparency, entry.Box.Transparency, entry.Part.Parent =
                0, 0, Workspace:FindFirstChild('Ignored') or Workspace
            entry.Duration = tracer_number('bullet_impacts_lifetime', 0.6, 0.1, 5)
            entry.FadeDuration = (not Toggles.bullet_impacts_fade or Toggles.bullet_impacts_fade.Value)
                    and tracer_number('bullet_impacts_fade_duration', 0.25, 0.05, 2)
                or 0
            entry.Lifetime = entry.Duration + entry.FadeDuration
            entry.Update = function(e, age)
                local fade = e.FadeDuration > 0 and math.clamp((age - e.Duration) / e.FadeDuration, 0, 1) or 0
                e.Part.Transparency, e.Box.Transparency = fade, fade
            end
        end
        function phowg:emit_bullet_shot(startPos, endPos, isLocal, skinTracer)
            if not valid_point(startPos) or not valid_point(endPos) then
                return
            end
            local prefix = isLocal and 'local_bullet_tracers' or 'enemy_bullet_tracers'
            if enabled(prefix) and not (isLocal and skinTracer) then
                local mode = (Options[prefix .. '_value'] and Options[prefix .. '_value'].Value) or 'drawing'
                if mode == 'drawing' and (not Drawing or not Drawing.new) then
                    mode = 'beam'
                end
                local style = tracer_style(prefix, isLocal)
                if mode == 'beam' then
                    beam_tracer(startPos, endPos, style)
                else
                    drawing_tracer(startPos, endPos, style)
                end
            end
            if isLocal and enabled('bullet_impacts') then
                impact(endPos)
            end
        end
        function phowg:capture_bullet_shot(handle, startPos, endPos, directChina)
            if Data.SharedSignalsClosed or (Library and Library.Unloaded) then
                return
            end
            if
                (handle ~= nil and typeof(handle) ~= 'Instance')
                or not valid_point(startPos)
                or not valid_point(endPos)
            then
                return
            end
            local now = tick()
            local china = directChina == true
            if
                not china
                and not enabled('local_bullet_tracers')
                and not enabled('enemy_bullet_tracers')
                and not enabled('bullet_impacts')
            then
                return
            end
            if china then
                Data.ChinaTracerTimes = Data.ChinaTracerTimes or setmetatable({}, { __mode = 'k' })
                local key = handle or Data
                if
                    now - (Data.ChinaTracerTimes[key] or -math.huge)
                    < (phowg.bullet_visual_interval and phowg:bullet_visual_interval() or 1 / 30)
                then
                    return
                end
            end
            local previous = Data.LastCapturedBulletShot
            if
                not china
                and previous
                and now - previous.At < 0.05
                and (previous.Start - startPos).Magnitude < 0.05
                and (previous.Finish - endPos).Magnitude < 0.05
            then
                return
            end
            if phowg.take_bullet_visual_budget and not phowg:take_bullet_visual_budget() then
                Data.BulletVisualDropped = (Data.BulletVisualDropped or 0) + 1
                return
            end
            if china then
                Data.ChinaTracerTimes[handle or Data] = now
            end
            local skinTracer = china and phowg:render_skin_tracer(handle, startPos, endPos)
                or not china and phowg:use_skin_tracer(handle)
            local shot = { Start = startPos, Finish = endPos, At = tick(), SkinTracer = skinTracer == true }
            Data.LastCapturedBulletShot = shot
            Data.BulletCaptureSerial = (Data.BulletCaptureSerial or 0) + 1
            if enabled('enemy_bullet_tracers') or enabled('local_bullet_tracers') then
                if #recentShots >= 64 then
                    table.remove(recentShots, 1)
                end
                recentShots[#recentShots + 1] = shot
            end
            if china then
                if not enabled('local_bullet_tracers') and not shot.SkinTracer then
                    pcall(default_china_tracer, startPos, endPos)
                end
                pcall(phowg_callbacks.emit_bullet_shot, startPos, endPos, true, shot.SkinTracer)
                return
            end
            if not enabled('local_bullet_tracers') and not enabled('bullet_impacts') then
                return
            end
            if shots.Tail - shots.Head + 1 >= 128 then
                shots.Items[shots.Head] = nil
                shots.Head += 1
            end
            shots.Tail += 1
            shots.Items[shots.Tail] = shot
        end
        function phowg:perfect_hit_mode()
            if Library.Unloaded or Data.SharedSignalsClosed then
                return false
            end
            local target, source
            if phowg.get_gun_shot_target then
                local resolved, _, _, owner = phowg:get_gun_shot_target()
                target, source = resolved, owner
            end
            local method = phowg:gun_shoot_method(source, target)
            return method == 'perfect hit' or method == 'china hack'
        end
        function phowg:perfect_hit_vector(value)
            return typeof(value) == 'Vector3'
                and value.X == value.X
                and value.Y == value.Y
                and value.Z == value.Z
                and math.abs(value.X) < 1e8
                and math.abs(value.Y) < 1e8
                and math.abs(value.Z) < 1e8
        end
        function phowg:perfect_hit_point(part, desired, target, lead)
            local size = part.Size
            local expanded = Data.HitboxSet and Data.HitboxSet[target]
            if expanded and expanded.part == part and phowg:perfect_hit_vector(expanded.size) then
                size = expanded.size
            elseif part.Name == 'HumanoidRootPart' and (size.X > 3 or size.Y > 3 or size.Z > 3) then
                size = Vector3.new(2, 2, 1)
            end
            local half = size * 0.44
            local frame = part.CFrame + (lead or Vector3.zero)
            local relative = frame:PointToObjectSpace(desired)
            return frame:PointToWorldSpace(
                Vector3.new(
                    math.clamp(relative.X, -half.X, half.X),
                    math.clamp(relative.Y, -half.Y, half.Y),
                    math.clamp(relative.Z, -half.Z, half.Z)
                )
            )
        end
        function phowg:perfect_hit_ping()
            if tick() < (Data.PerfectHitPingAt or 0) then
                return Data.PerfectHitPing or 0.07
            end
            local ok, milliseconds = pcall(function()
                return game:GetService('Stats').Network.ServerStatsItem['Data Ping']:GetValue()
            end)
            if not ok or type(milliseconds) ~= 'number' or milliseconds ~= milliseconds then
                local valid, seconds = pcall(LocalPlayer.GetNetworkPing, LocalPlayer)
                milliseconds = valid and type(seconds) == 'number' and seconds == seconds and seconds * 2000 or 70
            end
            Data.PerfectHitPing, Data.PerfectHitPingAt = math.clamp(milliseconds / 1000, 0, 0.8), tick() + 0.5
            return Data.PerfectHitPing
        end
        function phowg:perfect_hit_solution(target, position, part)
            local character = target and target.Character
            if not character then
                return nil
            end
            if typeof(part) ~= 'Instance' or not part:IsA('BasePart') or part.Parent ~= character then
                part = character:FindFirstChild('Head')
                    or character:FindFirstChild('UpperTorso')
                    or character:FindFirstChild('Torso')
                    or character:FindFirstChild('HumanoidRootPart')
            end
            if not part or not part:IsA('BasePart') then
                return nil
            end
            local root = character:FindFirstChild('HumanoidRootPart')
            local horizon = math.min(0.4, phowg:perfect_hit_ping() * 0.5)
            local lead, velocity, heldAge = phowg:motion_lead(character, root, horizon)
            if root then
                local predicted = predpos(part.Position, character)
                if phowg:perfect_hit_vector(predicted) then
                    lead = predicted - part.Position
                end
            end
            local desired = typeof(position) == 'CFrame' and position.Position or position
            if not phowg:perfect_hit_vector(desired) then
                desired = part.Position
            end
            if (desired - part.Position).Magnitude < 0.001 then
                desired = desired + lead
            end
            local point = phowg:perfect_hit_point(part, desired, target, lead)
            return {
                Target = target,
                Character = character,
                Part = part,
                Root = root,
                RootPosition = root and root.Position,
                Velocity = velocity,
                Lead = lead,
                Point = point,
                At = os.clock(),
                Uncertainty = velocity.Magnitude * heldAge,
            }
        end
        function phowg:perfect_hit_aim(origin)
            if not Data.PerfectHitHookReady or not phowg:perfect_hit_vector(origin) or localshootblocked() then
                return nil
            end
            local target, position, part, source = phowg:get_gun_shot_target()
            if
                not target
                or not target.Character
                or phowg:sticky_shot_blocked(target, source)
                or not phowg:current_sticky_shot(target, source) and target.Character:FindFirstChildOfClass('ForceField')
            then
                return nil
            end
            local automatic = source == 'Ragebot' or source == 'Support' or source == 'KillAura'
            local chance = (automatic or phowg:is_sticky_aim_source(target, source)) and 100
                or tonumber(Options.silent_aim_hit_chance and Options.silent_aim_hit_chance.Value)
                or 100
            if math.random(1, 100) > math.clamp(chance, 0, 100) then
                return nil
            end
            local solution = phowg:perfect_hit_solution(target, position, part)
            if not solution then
                return nil
            end
            if source == 'SilentAim' and Toggles.silent_aim_match_y and Toggles.silent_aim_match_y.Value then
                local aimPart = part or target.Character:FindFirstChild('Head')
                if aimPart then
                    solution.Point = Vector3.new(solution.Point.X, aimPart.Position.Y, solution.Point.Z)
                end
            end
            local character = LocalPlayer.Character
            local held = Data.HeldGunFire
            local tool = held and held.Character == character and held.Tool and held.Tool.Parent == character and held.Tool
                or character and character:FindFirstChildOfClass('Tool')
            local handle = tool and tool:FindFirstChild('Handle')
            if
                not handle
                or not handle:IsA('BasePart')
                or not tool:FindFirstChild('Ammo')
                or not tool:FindFirstChild('Range')
            then
                return nil
            end
            local name = normalizeweaponname(tool.Name)
            if name == 'rpg' or name == 'grenadelauncher' or name == 'flamethrower' or name == 'fireworklauncher' then
                return nil
            end
            local observer = getgenv().PhowgBulletShotObserver
            local corrected = observer
                    and observer.Owner == Data
                    and observer.Transform == phowg.redirect_gun_packet
                    and gunshootorigin(handle, origin)
                or origin
            if not phowg:perfect_hit_vector(corrected) then
                corrected = origin
            end
            corrected = phowg:resolve_wallbang_origin(tool, target, corrected, solution.Point, source)
            if not corrected then
                return nil
            end
            local delta = solution.Point - corrected
            if not phowg:perfect_hit_vector(delta) or delta.Magnitude < 0.001 then
                return nil
            end
            return delta.Unit,
                delta.Magnitude,
                {
                    NativeOrigin = origin,
                    Origin = corrected,
                    Distance = delta.Magnitude,
                    Target = target,
                    TargetCharacter = target.Character,
                    Character = character,
                    Tool = tool,
                    Source = source,
                    At = tick(),
                }
        end
        function phowg:force_hit_packet(handle, suppliedPoint, suppliedHead)
            if not phowg:perfect_hit_mode() or localshootblocked() then
                return nil
            end
            if typeof(handle) ~= 'Instance' or not handle:IsA('BasePart') then
                return nil
            end
            local tool = handle.Parent
            if not tool or tool.Parent ~= LocalPlayer.Character or not tool:IsA('Tool') or not tool:FindFirstChild('Ammo') then
                return nil
            end
            local name = normalizeweaponname(tool.Name)
            if name == 'rpg' or name == 'grenadelauncher' or name == 'flamethrower' or name == 'fireworklauncher' then
                return nil
            end
            local target, position, _part, source = phowg:get_gun_shot_target()
            local character = target and target.Character
            local head = character and character:FindFirstChild('Head')
            if
                not head
                or not head:IsA('BasePart')
                or phowg:sticky_shot_blocked(target, source)
                or not phowg:current_sticky_shot(target, source) and character:FindFirstChildOfClass('ForceField')
            then
                return nil
            end
            if
                phowg:gun_shoot_method(source, target) == 'china hack'
                and suppliedHead == head
                and phowg:perfect_hit_vector(suppliedPoint)
            then
                return suppliedPoint, head
            end
            local automatic = source == 'Ragebot' or source == 'Support' or source == 'KillAura'
            local chance = (automatic or phowg:is_sticky_aim_source(target, source)) and 100
                or tonumber(Options.silent_aim_hit_chance and Options.silent_aim_hit_chance.Value)
                or 100
            if math.random(1, 100) > math.clamp(chance, 0, 100) then
                return nil
            end
            if typeof(position) == 'CFrame' then
                position = position.Position
            end
            if automatic or not phowg:perfect_hit_vector(position) then
                position = predpos(head.Position, character)
            end
            if source == 'SilentAim' and Toggles.silent_aim_match_y and Toggles.silent_aim_match_y.Value then
                position = Vector3.new(position.X, head.Position.Y, position.Z)
            end
            if phowg:around_wallbang_enabled(target, source) then
                local origin = gunshootorigin(handle, handle.Position)
                if not phowg:resolve_wallbang_origin(tool, target, origin, position, source) then
                    return nil
                end
            end
            return position, head
        end
        function phowg:sync_force_hit()
            local observer = getgenv().PhowgBulletShotObserver
            Data.PerfectHitHookReady = phowg:perfect_hit_mode()
                    and observer
                    and observer.Owner == Data
                    and observer.ForceHit == phowg.force_hit_packet
                or nil
        end
        function phowg:update_bullet_capture()
            phowg:sync_hit_watchers()
            if syncDefaultRays then
                syncDefaultRays(true)
            end
            if not MainEvent or not MainEvent.Parent then
                MainEvent = ReplicatedStorage:FindFirstChild('MainEvent')
            end
            local environment = getgenv()
            local state = environment.PhowgBulletShotObserver
            if state and state.Version ~= 15 then
                state.Emitting = true
                state.Handler, state.Filter, state.Transform, state.Emitter, state.Owner, state.Remote, state.HitHandler, state.ForceHit =
                    nil, nil, nil, nil, nil, nil, nil, nil
                state = nil
            end
            local hitFeedback = phowg:native_hit_feedback_enabled()
            local wanted = not Library.Unloaded and not Data.SharedSignalsClosed
            if not wanted then
                if state and state.Owner == Data then
                    state.Handler, state.Filter, state.Transform, state.HitHandler, state.ForceHit =
                        nil, nil, nil, nil, nil
                    state.Owner, state.Remote, state.Runtime, state.API = nil, nil, nil, nil
                end
                table.clear(shots.Items)
                table.clear(recentShots)
                shots.Head, shots.Tail = 1, 0
                phowg:sync_force_hit()
                return
            end
            if not state then
                if not hookmm or not getnamecallmethod then
                    if not captureWarning then
                        captureWarning = true
                        Library:Notify('bullet tracers: namecall hooks unavailable', 5)
                    end
                    phowg:sync_force_hit()
                    return
                end
                state = { Version = 15 }
                local method, setMethod = getnamecallmethod, setnamecallmethod
                local function forward(self, callerMethod, ...)
                    if method() ~= callerMethod then
                        local restored = type(setMethod) == 'function'
                            and pcall(setMethod, callerMethod)
                            and method() == callerMethod
                        if not restored then
                            if
                                callerMethod == 'FireServer'
                                and self == state.Remote
                                and type(state.FireServer) == 'function'
                            then
                                return state.FireServer(self, ...)
                            end
                            local nativeMethod = self[callerMethod]
                            if type(nativeMethod) == 'function' then
                                return nativeMethod(self, ...)
                            end
                        end
                    end
                    return state.Original(self, ...)
                end
                local callback = function(self, ...)
                    local callerMethod = method()
                    if callerMethod ~= 'FireServer' or self ~= state.Remote or not state.Owner then
                        return state.Original(self, ...)
                    end
                    if not state.Emitting and self == state.Remote and callerMethod == 'FireServer' then
                        local action, handle, origin, point, hitPart = ...
                        if action == 'ShootGun' then
                            local arguments
                            local directChina = typeof(handle) == 'Instance'
                                and state.Runtime.ChinaRemoteEmission == handle.Parent
                            if state.Transform and not directChina then
                                local ok, redirectedOrigin, redirectedPoint, redirectedHit, redirectedNormal =
                                    pcall(state.Transform, handle, origin, point, hitPart)
                                if ok and typeof(redirectedOrigin) == 'Vector3' then
                                    arguments = table.pack(...)
                                    arguments[3] = redirectedOrigin
                                    origin = redirectedOrigin
                                    if typeof(redirectedPoint) == 'Vector3' then
                                        arguments[4], arguments[5] = redirectedPoint, redirectedHit
                                        arguments[6], arguments.n = redirectedNormal, math.max(6, arguments.n)
                                        point, hitPart = redirectedPoint, redirectedHit
                                    end
                                end
                            end
                            if state.ForceHit and not directChina then
                                local ok, targetPosition, targetHead = pcall(state.ForceHit, handle, point, hitPart)
                                if ok and typeof(targetPosition) == 'Vector3' and typeof(targetHead) == 'Instance' then
                                    arguments = arguments or table.pack(...)
                                    arguments[4], arguments[5] = targetPosition, targetHead
                                    arguments[6], arguments.n = Vector3.new(0, 1, 0), math.max(6, arguments.n)
                                    point, hitPart = targetPosition, targetHead
                                end
                            end
                            if state.Filter then
                                local ok, allowed = pcall(state.Filter, hitPart)
                                if ok and not allowed then
                                    return
                                end
                            end
                            if not directChina then
                                local randomized = state.API.RandomizeStickyBullet(point)
                                if randomized ~= point then
                                    arguments = arguments or table.pack(...)
                                    arguments[4], point = randomized, randomized
                                end
                            end
                            if not directChina and typeof(handle) == 'Instance' and state.API.RecordCombatRequest then
                                state.API.RecordCombatRequest(handle.Parent, 1, false)
                            end
                            if state.Handler then
                                pcall(state.Handler, handle, origin, point, directChina)
                            end
                            if state.HitHandler then
                                local results
                                if arguments then
                                    results =
                                        table.pack(forward(self, callerMethod, table.unpack(arguments, 1, arguments.n)))
                                else
                                    results = table.pack(forward(self, callerMethod, ...))
                                end
                                pcall(state.HitHandler, handle, origin, point, hitPart)
                                return table.unpack(results, 1, results.n)
                            end
                            if arguments then
                                return forward(self, callerMethod, table.unpack(arguments, 1, arguments.n))
                            end
                            return forward(self, callerMethod, ...)
                        end
                    end
                    return forward(self, callerMethod, ...)
                end
                local wrap = newcclosure or LPH_NO_VIRTUALIZE
                local ok, original = pcall(hookmm, game, '__namecall', wrap(callback))
                if not ok or type(original) ~= 'function' then
                    if not captureWarning then
                        captureWarning = true
                        Library:Notify('bullet tracers: failed to install shot observer', 5)
                    end
                    phowg:sync_force_hit()
                    return
                end
                state.Original, environment.PhowgBulletShotObserver = original, state
            end
            captureState = state
            state.Owner, state.Remote, state.Runtime, state.API = Data, MainEvent, Data, phowg
            state.FireServer = MainEvent and MainEvent.FireServer
            state.Handler = (
                enabled('local_bullet_tracers')
                or enabled('enemy_bullet_tracers')
                or enabled('bullet_impacts')
            )
                    and phowg.capture_bullet_shot
                or nil
            state.HitHandler = hitFeedback and phowg.record_bullet_hit or nil
            state.Filter = phowg_callbacks.perfect_bullet_allowed
            state.Transform, state.ForceHit = phowg_callbacks.redirect_gun_packet, phowg_callbacks.force_hit_packet
            phowg:sync_force_hit()
        end
        registerheartbeat('TargetMotion', phowg.sample_target_motion)
        registerheartbeat(
            'BulletShotQueue',
            function()
                if captureState and captureState.Owner == Data then
                    captureState.Remote = MainEvent
                end
                if shots.Head > shots.Tail then
                    return
                end
                local began, processed = os.clock(), 0
                while shots.Head <= shots.Tail and processed < 32 do
                    local shot = shots.Items[shots.Head]
                    shots.Items[shots.Head] = nil
                    shots.Head += 1
                    if tick() - shot.At <= 1 then
                        pcall(phowg_callbacks.emit_bullet_shot, shot.Start, shot.Finish, true, shot.SkinTracer)
                    end
                    processed += 1
                    if os.clock() - began >= 0.002 then
                        break
                    end
                end
                if shots.Head > shots.Tail then
                    shots.Head, shots.Tail = 1, 0
                end
            end,
            nil,
            function()
                return shots.Head <= shots.Tail
            end
        )
        registerheartbeat(
            'BulletVisuals',
            function()
                if #visuals == 0 then
                    return
                end
                local camera, now = Workspace.CurrentCamera, tick()
                local index = #visuals
                while index > 0 do
                    local visual = visuals[index]
                    local elapsed = now - visual.At
                    local ok = true
                    if elapsed < visual.Lifetime + visual.FadeDuration then
                        ok = pcall(function()
                            local fade = visual.FadeDuration > 0
                                    and math.clamp((elapsed - visual.Lifetime) / visual.FadeDuration, 0, 1)
                                or 0
                            if visual.Kind == 'drawing' then
                                local start, finish, startVisible, finishVisible = nil, nil, false, false
                                if camera then
                                    start, startVisible = camera:WorldToViewportPoint(visual.Start)
                                    finish, finishVisible = camera:WorldToViewportPoint(visual.Finish)
                                    start, finish = Vector2.new(start.X, start.Y), Vector2.new(finish.X, finish.Y)
                                end
                                local count = #visual.Segments
                                local delta = start and count > 1 and finish - start
                                for segmentIndex, segment in ipairs(visual.Segments) do
                                    local line, outline = segment.Line, segment.Outline
                                    if not alivedrawing(line) or not alivedrawing(outline) then
                                        error('expired drawing')
                                    end
                                    if visual.Fade ~= fade then
                                        line.Transparency, outline.Transparency =
                                            segment.Opacity * (1 - fade), segment.Opacity * (1 - fade)
                                    end
                                    line.Visible, outline.Visible =
                                        startVisible and finishVisible, startVisible and finishVisible
                                    if start then
                                        line.From = count == 1 and start or start + delta * ((segmentIndex - 1) / count)
                                        line.To = count == 1 and finish or start + delta * (segmentIndex / count)
                                        outline.From, outline.To = line.From, line.To
                                    end
                                end
                            elseif visual.Kind == 'beam' then
                                if not visual.Beam or not visual.Beam.Parent then
                                    error('expired beam')
                                end
                                if visual.Fade ~= fade then
                                    local startAlpha = visual.Alpha + (1 - visual.Alpha) * fade
                                    local endAlpha = visual.EndAlpha + (1 - visual.EndAlpha) * fade
                                    visual.Beam.Transparency = beam_transparency(startAlpha, endAlpha)
                                end
                            elseif visual.Kind == 'impact' then
                                if not visual.Part or not visual.Part.Parent then
                                    error('expired impact')
                                end
                                if visual.Fade ~= fade then
                                    visual.Part.Transparency = fade
                                end
                            end
                            visual.Fade = fade
                        end)
                    end
                    if elapsed >= visual.Lifetime + visual.FadeDuration or not ok then
                        remove_visual(visual)
                        visuals[index] = visuals[#visuals]
                        visuals[#visuals] = nil
                    end
                    index -= 1
                end
            end,
            nil,
            function()
                return #visuals > 0
            end
        )
        local function is_default_ray(object)
            return object.Name == 'BULLET_RAYS' or object.Name == 'BULLET_RAY'
        end
        local function restore_ray(record)
            for renderer, state in pairs(record.Hidden) do
                if renderer.Parent then
                    if state.Part then
                        renderer.LocalTransparencyModifier = state.Value
                    else
                        renderer.Enabled = state.Value
                    end
                end
            end
            table.clear(record.Hidden)
        end
        restorePendingRays = function()
            rayGeneration += 1
            rayDeferred = false
            for _, record in pairs(pendingRays) do
                pcall(restore_ray, record)
            end
            table.clear(pendingRays)
        end
        local function hide_ray_renderer(renderer, record)
            if renderer:IsA('BasePart') then
                if not record.Hidden[renderer] then
                    record.Hidden[renderer] = { Part = true, Value = renderer.LocalTransparencyModifier or 0 }
                end
                if renderer.LocalTransparencyModifier ~= 1 then
                    renderer.LocalTransparencyModifier = 1
                end
            elseif renderer:IsA('Beam') or renderer:IsA('Trail') then
                if not record.Hidden[renderer] then
                    record.Hidden[renderer] = { Part = false, Value = renderer.Enabled ~= false }
                end
                if renderer.Enabled ~= false then
                    renderer.Enabled = false
                end
            end
        end
        local function hide_default_ray(object, record, descendant)
            local owner = object:GetAttribute('OwnerCharacter')
            local isLocal = owner == LocalPlayer.Name
                or owner == tostring(LocalPlayer.UserId)
                or owner == LocalPlayer.UserId
            local unknown = owner == nil or owner == ''
            if isLocal and record.SkinTracer and phowg:skin_cosmetics_enabled() and enabled('local_bullet_tracers') then
                restore_ray(record)
                return
            end
            if not unknown and not enabled(isLocal and 'local_bullet_tracers' or 'enemy_bullet_tracers') then
                restore_ray(record)
                return
            end
            if not enabled('local_bullet_tracers') and not enabled('enemy_bullet_tracers') then
                restore_ray(record)
                return
            end
            hide_ray_renderer(object, record)
            if descendant then
                hide_ray_renderer(descendant, record)
            else
                for renderer in pairs(record.Hidden) do
                    hide_ray_renderer(renderer, record)
                end
            end
        end
        local function process_default_ray(object, record)
            if traced[object] or not object.Parent then
                return true
            end
            hide_default_ray(object, record)
            local owner = object:GetAttribute('OwnerCharacter')
            local isLocal = owner == LocalPlayer.Name
                or owner == tostring(LocalPlayer.UserId)
                or owner == LocalPlayer.UserId
            if isLocal then
                if record.SkinTracer and phowg:skin_cosmetics_enabled() and enabled('local_bullet_tracers') then
                    traced[object] = true
                    restore_ray(record)
                elseif enabled('local_bullet_tracers') then
                    traced[object] = true
                    object:Destroy()
                else
                    restore_ray(record)
                end
                return true
            end
            if owner ~= nil and owner ~= '' and not enabled('enemy_bullet_tracers') then
                restore_ray(record)
                return true
            end
            local beam = object:FindFirstChildOfClass('Beam')
            if not beam or not beam.Attachment1 then
                return false
            end
            local startPos = beam.Attachment0 and beam.Attachment0.WorldPosition
                or (object:IsA('BasePart') and object.Position)
            local endPos = beam.Attachment1.WorldPosition
            if not valid_point(startPos) or not valid_point(endPos) then
                return false
            end
            if owner == nil or owner == '' then
                for _, shot in ipairs(recentShots) do
                    if
                        tick() - shot.At < 0.6
                        and (shot.Start - startPos).Magnitude < 2
                        and (shot.Finish - endPos).Magnitude < 2
                    then
                        isLocal = true
                        record.SkinTracer = shot.SkinTracer
                        break
                    end
                end
                if not isLocal and tick() - record.At < 0.05 then
                    return false
                end
            end
            if isLocal and record.SkinTracer and phowg:skin_cosmetics_enabled() and enabled('local_bullet_tracers') then
                traced[object] = true
                restore_ray(record)
                return true
            end
            local replacement = enabled(isLocal and 'local_bullet_tracers' or 'enemy_bullet_tracers')
            if replacement then
                traced[object] = true
                if not isLocal then
                    pcall(phowg_callbacks.emit_bullet_shot, startPos, endPos, false)
                end
                object:Destroy()
            else
                restore_ray(record)
            end
            return true
        end
        local function drain_default_rays()
            if next(pendingRays) == nil then
                return
            end
            local began, processed = os.clock(), 0
            for object, record in pairs(pendingRays) do
                if process_default_ray(object, record) then
                    pendingRays[object] = nil
                elseif tick() - record.At > 1 then
                    restore_ray(record)
                    pendingRays[object] = nil
                end
                processed += 1
                if processed >= 32 or os.clock() - began >= 0.002 then
                    break
                end
            end
        end
        local function observe_default_ray(object, descendant)
            if not is_default_ray(object) or traced[object] then
                return
            end
            local record = pendingRays[object]
            if not record then
                local owner = object:GetAttribute('OwnerCharacter')
                local isLocal = owner == LocalPlayer.Name
                    or owner == tostring(LocalPlayer.UserId)
                    or owner == LocalPlayer.UserId
                local rendering = Data.NativeSkinRendering
                local skinTracer = rendering and rendering.Rendering and rendering.SkinTracer
                    or not (rendering and rendering.Rendering) and phowg:use_skin_tracer()
                record = { At = tick(), Hidden = {}, SkinTracer = isLocal and skinTracer }
                pendingRays[object] = record
                hide_default_ray(object, record)
                for _, renderer in ipairs(object:GetDescendants()) do
                    hide_default_ray(object, record, renderer)
                end
            else
                hide_default_ray(object, record, descendant)
            end
            if rayDeferred then
                return
            end
            rayDeferred = true
            local generation = rayGeneration
            task.defer(function()
                if generation ~= rayGeneration or Data.SharedSignalsClosed or (Library and Library.Unloaded) then
                    return
                end
                rayDeferred = false
                drain_default_rays()
            end)
        end
        syncDefaultRays = function(rescan)
            local wanted = enabled('local_bullet_tracers') or enabled('enemy_bullet_tracers')
            if not wanted and not rayContainer then
                return
            end
            local ignored = Workspace:FindFirstChild('Ignored')
            local siren = ignored and ignored:FindFirstChild('Siren')
            local radius = wanted and siren and siren:FindFirstChild('Radius') or nil
            if rayContainer ~= radius then
                for _, connection in ipairs(rayConnections) do
                    connection:Disconnect()
                end
                table.clear(rayConnections)
                restorePendingRays()
                rayContainer = radius
                if radius then
                    rayConnections[#rayConnections + 1] = connectshared(
                        radius.ChildAdded,
                        observe_default_ray,
                        radius,
                        'visuals/default ray added',
                        0,
                        'event/ChildAdded',
                        radius
                    )
                    rayConnections[#rayConnections + 1] = connectshared(radius.DescendantAdded, function(object)
                        local parent = object.Parent
                        while parent and parent.Parent ~= radius do
                            parent = parent.Parent
                        end
                        if parent and parent.Parent == radius then
                            observe_default_ray(parent, object)
                        end
                    end, radius, 'visuals/default ray ready', 0, 'event/DescendantAdded', radius)
                    rayConnections[#rayConnections + 1] = connectshared(radius.ChildRemoved, function(object)
                        local record = pendingRays[object]
                        if record and object.Parent then
                            restore_ray(record)
                        end
                        pendingRays[object] = nil
                    end, radius, 'visuals/default ray removed', 0, 'event/ChildRemoved', radius)
                    rescan = true
                end
            end
            if rescan and radius then
                for _, object in ipairs(radius:GetChildren()) do
                    observe_default_ray(object)
                end
            end
        end
        registerheartbeat(
            'BulletRayScan',
            function()
                syncDefaultRays(false)
            end,
            0.1,
            function()
                return enabled('local_bullet_tracers') or enabled('enemy_bullet_tracers') or rayContainer ~= nil
            end
        )
        registerheartbeat('BulletRayPending', drain_default_rays, nil, function()
            return next(pendingRays) ~= nil
        end)
        phowg:register_cleanup('bullet visuals', function(scope, reason)
            if reason ~= 'unload' and scope ~= LocalPlayer.Character and scope ~= Data.ManagedCharacter then
                return
            end
            for _, visual in ipairs(visuals) do
                remove_visual(visual)
            end
            table.clear(visuals)
            table.clear(shots.Items)
            table.clear(recentShots)
            restorePendingRays()
            shots.Head, shots.Tail = 1, 0
            if reason == 'unload' then
                for _, connection in ipairs(rayConnections) do
                    connection:Disconnect()
                end
                table.clear(rayConnections)
                rayContainer = nil
            end
            if reason == 'unload' and captureState and captureState.Owner == Data then
                captureState.Handler, captureState.Filter, captureState.Remote, captureState.Owner, captureState.HitHandler =
                    nil, nil, nil, nil, nil
                captureState.Transform, captureState.Emitter, captureState.ForceHit, captureState.Runtime, captureState.API = nil, nil, nil, nil, nil
                Data.PerfectHitHookReady = nil
            end
        end)
        for _, name in ipairs({
            'local_bullet_tracers',
            'enemy_bullet_tracers',
            'bullet_impacts',
            'perfect_bullets',
            'randomize_bullets',
            'on_hit_enabled',
            'hit_sound',
            'hit_skeleton',
            'hit_effect',
            'hit_marker',
            'hit_chams',
            'damage_number',
            'hit_notifications',
        }) do
            if Toggles[name] then
                Toggles[name]:OnChanged(phowg.update_bullet_capture)
            end
        end
        registerheartbeat('GunShotMode', function()
            if
                Library.Unloaded
                or Data.SharedSignalsClosed
                or Library.ControlsReady == false
                or Library.ConfigLoading
            then
                return
            end
            local key = tostring(Options.gun_shoot_method and Options.gun_shoot_method.Value) .. tostring(MainEvent)
            for _, name in ipairs({
                'local_bullet_tracers',
                'enemy_bullet_tracers',
                'bullet_impacts',
                'perfect_bullets',
                'randomize_bullets',
                'on_hit_enabled',
                'hit_sound',
                'hit_skeleton',
                'hit_effect',
                'hit_marker',
                'hit_chams',
                'damage_number',
                'hit_notifications',
            }) do
                key = key .. tostring(enabled(name))
            end
            if
                key ~= Data.BulletCaptureSettings
                or phowg:perfect_hit_mode()
                    and not Data.PerfectHitHookReady
                    and tick() >= (Data.BulletCaptureRetryAt or 0)
            then
                Data.BulletCaptureSettings, Data.BulletCaptureRetryAt = key, tick() + 5
                phowg:update_bullet_capture()
            end
        end, 0.5)
    end

    function phowg:set_property_override(key, object, property, enabled, value)
        Data.PropertyOverrides = Data.PropertyOverrides or {}
        local state = Data.PropertyOverrides[key]
        if state and (not enabled or state.Object ~= object) then
            state.Connection:Disconnect()
            Data.PropertyOverrides[key], state = nil, nil
        end
        if not enabled or not object then
            return
        end
        if not state then
            state = { Object = object, Value = value, Connection = nil :: any }
            Data.PropertyOverrides[key] = state
            local current = state
            current.Connection = connectshared(object:GetPropertyChangedSignal(property), function()
                if Data.PropertyOverrides[key] == current and object[property] ~= current.Value then
                    object[property] = current.Value
                end
            end, object, 'property override/' .. key)
        end
        state.Value = value
        if object[property] ~= value then
            object[property] = value
        end
    end
    function phowg:sync_lighting_overrides()
        if Data.LightingSyncing or Data.SharedSignalsClosed or Library.Unloaded then
            return
        end
        Data.LightingSyncing = true
        local ok, problem = pcall(function()
            local function option(name, fallback)
                local setting = Options[name]
                if setting then
                    return setting.Value
                end
                return fallback
            end
            local function apply(key, object, property, toggle, setting, fallback)
                phowg:set_property_override(key, object, property, phowg:toggle_enabled(toggle), option(setting, fallback))
            end
            apply('fog color', Lighting, 'FogColor', 'fog_changer', 'fog_changer_color', Color3.fromRGB(191, 191, 191))
            apply('fog start', Lighting, 'FogStart', 'fog_changer', 'fog_changer_start', 0)
            apply('fog end', Lighting, 'FogEnd', 'fog_changer', 'fog_changer_end', 100000)
            apply('clock', Lighting, 'ClockTime', 'time_changer', 'time_changer_value', 12)
            apply(
                'ambient',
                Lighting,
                'Ambient',
                'ambient_changer',
                'ambient_changer_color',
                Color3.fromRGB(127, 127, 127)
            )
            apply('brightness', Lighting, 'Brightness', 'brightness_changer', 'brightness_changer_value', 2)
            apply('exposure', Lighting, 'ExposureCompensation', 'exposure_changer', 'exposure_changer_value', 0)
            phowg:sync_world_color_correction()
            local correction = Lighting:FindFirstChild('ColorCorrection')
            if phowg:toggle_enabled('saturation_changer') and not correction then
                correction = Instance.new('ColorCorrectionEffect')
                correction.Name = 'ColorCorrection'
                correction.Parent = Lighting
            end
            apply('saturation', correction, 'Saturation', 'saturation_changer', 'saturation_changer_value', 0)
            local atmosphere = Lighting:FindFirstChild('Atmosphere')
            local atmosphereOn = phowg:toggle_enabled('atmosphere_changer')
            if atmosphereOn and not atmosphere then
                atmosphere = Instance.new('Atmosphere')
                atmosphere.Parent = Lighting
            end
            for _, spec in ipairs({
                { 'Color', 'atmosphere_color', Color3.fromRGB(199, 199, 199) },
                { 'Decay', 'atmosphere_decay', Color3.fromRGB(255, 255, 255) },
                { 'Density', 'atmosphere_density', 0.3 },
                { 'Glare', 'atmosphere_glare', 0 },
                { 'Haze', 'atmosphere_haze', 0 },
            }) do
                apply('atmosphere/' .. spec[1], atmosphere, spec[1], 'atmosphere_changer', spec[2], spec[3])
            end
            if not atmosphereOn and atmosphere then
                atmosphere:Destroy()
            end
        end)
        Data.LightingSyncing = false
        if not ok then
            warn('[Phowg] lighting overrides: ' .. tostring(problem))
        end
    end
    for _, name in ipairs({
        'fog_changer',
        'time_changer',
        'ambient_changer',
        'brightness_changer',
        'exposure_changer',
        'saturation_changer',
        'contrast_changer',
        'correction_brightness_changer',
        'atmosphere_changer',
    }) do
        Toggles[name]:OnChanged(phowg.sync_lighting_overrides)
    end
    for _, name in ipairs({
        'fog_changer_color',
        'fog_changer_start',
        'fog_changer_end',
        'time_changer_value',
        'ambient_changer_color',
        'brightness_changer_value',
        'exposure_changer_value',
        'saturation_changer_value',
        'contrast_changer_value',
        'correction_brightness_value',
        'atmosphere_color',
        'atmosphere_decay',
        'atmosphere_density',
        'atmosphere_glare',
        'atmosphere_haze',
    }) do
        Options[name]:OnChanged(phowg.sync_lighting_overrides)
    end
    local function lighting_child_changed(child)
        if child.Name == 'Atmosphere' or child.Name == 'ColorCorrection' or child.Name == 'PhowgColorCorrection' then
            phowg:sync_lighting_overrides()
        end
    end
    create_connection(
        'LightingOverrideAdded',
        connectshared(
            Lighting.ChildAdded,
            lighting_child_changed,
            Lighting,
            'lighting/effect added',
            0,
            'event/ChildAdded',
            Lighting
        )
    )
    create_connection(
        'LightingOverrideRemoved',
        connectshared(
            Lighting.ChildRemoved,
            lighting_child_changed,
            Lighting,
            'lighting/effect removed',
            0,
            'event/ChildRemoved',
            Lighting
        )
    )
    phowg:register_cleanup('property overrides', function(scope)
        for key, state in pairs(Data.PropertyOverrides or {}) do
            if not scope or phowg:scope_contains(scope, state.Object) then
                state.Connection:Disconnect()
                Data.PropertyOverrides[key] = nil
            end
        end
    end)
    phowg:sync_lighting_overrides()
end
