function phowg:explosive_movement_active(tag)
    if tag == 'Buy' then
        return Data.Buying == true and typeof(Data.BuyTargetCF) == 'CFrame'
    elseif tag == 'Desync' then
        return Data.DesyncActive == true
    elseif tag == 'Underground' then
        return Data.UndergroundActive == true
    elseif tag == 'VoidSpamOut' then
        return phowg:void_spam_out_active()
    elseif tag == 'Void' or tag == 'VoidTwitch' then
        return Data.VoidActive == true
    elseif tag == 'ReloadVoid' then
        return reloadvoidactive()
    elseif tag == 'TargetStrafe' then
        return Data.TargetStrafeActive and Toggles.target_strafe_enabled and Toggles.target_strafe_enabled.Value
    elseif tag == 'Combat' then
        return (rageboton() or punishmentactive())
            and (Data.CurrentActionTarget ~= nil or Data.Settings and Data.Settings.Hide)
    elseif tag == 'KillAura' then
        return killauraenabled() and Toggles.full_rage and Toggles.full_rage.Value and Data.KillAuraTarget ~= nil
    elseif tag == 'RagebotVoid' then
        return phowg:ragebot_void_move_valid(Data.RagebotVoidSpam)
    elseif tag == 'RagebotIdle' then
        return phowg:ragebot_idle_hiding(Data.RagebotIdle)
    elseif tag == 'PurchaseVoidReturn' then
        return phowg:purchase_void_return_valid(Data.PurchaseVoidReturn)
    elseif tag == 'DeflectRPG' then
        return Data.RPGMoveActive == true
    elseif tag == 'DeflectRPGReturn' then
        return false
    end
    return Data.MoveToActive == true
end
function stoprpgmove(returnToClient)
    local restore, tag, priority, hold = Data.RPGReturnCF, Data.RPGReturnTag, Data.RPGReturnPriority, Data.RPGReturnHold
    local character = Data.RPGThreatCharacter
    local clientCF = typeof(Local_Data.ClientPos) == 'CFrame' and Local_Data.ClientPos or Data.RPGClientCF
    Data.RPGClientCF = nil
    Data.RPGMoveActive, Data.RPGThreatKind, Data.RPGThreatCF, Data.RPGThreatCharacter = nil, nil, nil, nil
    Data.RPGReturnCF, Data.RPGReturnTag, Data.RPGReturnPriority, Data.RPGReturnHold = nil, nil, nil, nil
    Data.RPGEscapeCF, Data.RPGEscapeAt = nil, nil
    if Data.CSync and Data.CSync.Queue then
        for index = #Data.CSync.Queue, 1, -1 do
            local queuedTag = Data.CSync.Queue[index].tag
            if queuedTag == 'DeflectRPG' or queuedTag == 'DeflectRPGReturn' then
                table.remove(Data.CSync.Queue, index)
            end
        end
    end
    releasemovement('DeflectRPG')
    releasemovement('DeflectRPGReturn')
    if not returnToClient or character ~= LocalPlayer.Character or localactionblocked() then
        return
    end
    if Data.Buying and typeof(Data.BuyTargetCF) == 'CFrame' then
        set_server_cframe(Data.BuyTargetCF, nil, Data.BuyPriority or Data.PRIO.LOADOUT, 'Buy')
    elseif Data.VoidActive then
        set_server_cframe(getvoidcframe(), nil, Data.PRIO.IDLE, 'Void')
    elseif hold and validmovetohold(hold) then
        set_server_cframe(hold.CFrame, nil, hold.Priority, hold.Tag, false, hold, hold.Arrive)
    elseif not hold and tag and phowg:explosive_movement_active(tag) and typeof(restore) == 'CFrame' then
        set_server_cframe(restore, nil, priority or Data.PRIO.KNIFE, tag)
    elseif typeof(clientCF) == 'CFrame' then
        set_server_cframe(clientCF, nil, 0.5, 'DeflectRPGReturn')
    end
end
local function explosivepositioncf(character, root, clientCF)
    if Data.RPGMoveActive and Data.RPGThreatCharacter == character and typeof(Data.RPGEscapeCF) == 'CFrame' then
        if
            Data.AppliedServerTag == 'DeflectRPG'
            and Data.AppliedServerCharacter == character
            and typeof(Data.AppliedServerCF) == 'CFrame'
        then
            return Data.AppliedServerCF
        end
        return Data.RPGEscapeCF
    end
    local applied, tag = Data.AppliedServerCF, Data.AppliedServerTag
    local active = phowg:explosive_movement_active(tag)
    if Data.AppliedServerHold then
        active = validmovetohold(Data.AppliedServerHold)
    end
    if active and Data.AppliedServerCharacter == character and typeof(applied) == 'CFrame' then
        local position = applied.Position
        local age = tick() - (Data.AppliedServerAt or -math.huge)
        local sustained = tag == 'Buy'
            or tag == 'Desync'
            or tag == 'Underground'
            or tag == 'Void'
            or tag == 'VoidTwitch'
            or tag == 'ReloadVoid'
            or tag == 'TargetStrafe'
            or tag == 'Combat'
            or tag == 'KillAura'
            or tag == 'RagebotVoid'
            or tag == 'RagebotIdle'
            or tag == 'PurchaseVoidReturn'
            or Data.AppliedServerHold ~= nil
        if
            age >= 0
            and (sustained or type(Data.CSyncTable) == 'table' and Data.CSyncTable[2] or Data.MoveToInFlight == root or age < 0.15)
            and position.X == position.X
            and position.Y == position.Y
            and position.Z == position.Z
            and phowg:explosive_vector(position)
        then
            return applied
        end
    end
    return clientCF
end
local function explosivepart(projectile)
    if projectile:IsA('BasePart') then
        return projectile
    end
    local main = projectile:FindFirstChild('Main', true)
    if main and main:IsA('BasePart') then
        return main
    end
    return projectile:FindFirstChildWhichIsA('BasePart', true)
end
function phowg:explosive_vector(value)
    return typeof(value) == 'Vector3'
        and value.X == value.X
        and value.Y == value.Y
        and value.Z == value.Z
        and math.abs(value.X) < 1e12
        and math.abs(value.Y) < 1e12
        and math.abs(value.Z) < 1e12
end
function phowg:explosive_approach_distance(part, position)
    if
        typeof(part) ~= 'Instance'
        or not part:IsA('BasePart')
        or not part.Parent
        or not phowg:explosive_vector(position)
        or not phowg:explosive_vector(part.Position)
    then
        return math.huge
    end
    local offset = position - part.Position
    local velocity = part.AssemblyLinearVelocity
    if not phowg:explosive_vector(velocity) then
        return offset.Magnitude
    end
    local speedSquared = velocity:Dot(velocity)
    if speedSquared < 1 then
        return offset.Magnitude
    end
    local approach = math.clamp(offset:Dot(velocity) / speedSquared, 0, 0.35)
    return math.min(offset.Magnitude, (offset - velocity * approach).Magnitude)
end
local function neutralizeexplosive(projectile, primary, serverPosition, orbit)
    Data['RPGReflectionMovers'] = Data['RPGReflectionMovers'] or {}
    local movers = Data['RPGReflectionMovers']
    local origin = primary.Position
    local velocity = primary.AssemblyLinearVelocity
    local away = Vector3.new(origin.X - serverPosition.X, 0, origin.Z - serverPosition.Z)
    if away.Magnitude < 0.001 then
        away = Vector3.new(-velocity.X, 0, -velocity.Z)
    end
    if away.Magnitude < 0.001 then
        away = Vector3.new(1, 0, 0)
    end
    away = away.Unit
    local destination = origin + away * 150
    destination = Vector3.new(destination.X, math.min(origin.Y, serverPosition.Y) - 1000, destination.Z)
    local offset = destination - origin
    local outwardVelocity = away * math.max(150, velocity.Magnitude) - Vector3.new(0, 80, 0)
    local orbitState
    if orbit then
        Data['RPGOrbitProjectiles'] = Data['RPGOrbitProjectiles'] or {}
        orbitState = Data['RPGOrbitProjectiles'][projectile]
        if not orbitState then
            Data['RPGOrbitSerial'] = (Data['RPGOrbitSerial'] or 0) + 1
            orbitState =
                { Phase = (Data['RPGOrbitSerial'] - 1) * math.pi / 4, Primary = primary, Offsets = {}, Touches = {} }
            Data['RPGOrbitProjectiles'][projectile] = orbitState
        elseif orbitState.Primary ~= primary then
            orbitState.Primary = primary
            orbitState.Offsets = {}
        end
        local orbitRadius, angularSpeed = 25, 4
        local angle = tick() * angularSpeed + orbitState.Phase
        destination = serverPosition + Vector3.new(math.cos(angle) * orbitRadius, 0, math.sin(angle) * orbitRadius)
        outwardVelocity =
            Vector3.new(-math.sin(angle) * orbitRadius * angularSpeed, 0, math.cos(angle) * orbitRadius * angularSpeed)
    end
    local parts = {}
    if projectile:IsA('BasePart') then
        parts[1] = projectile
    end
    for _, instance in ipairs(projectile:GetDescendants()) do
        if instance:IsA('BasePart') then
            parts[#parts + 1] = instance
        elseif
            instance:IsA('BodyMover')
            or instance:IsA('LinearVelocity')
            or instance:IsA('AngularVelocity')
            or instance:IsA('VectorForce')
            or instance:IsA('LineForce')
            or instance:IsA('Torque')
            or instance:IsA('AlignPosition')
            or instance:IsA('AlignOrientation')
            or (instance:IsA('TouchTransmitter') and not orbit)
        then
            if not (instance:IsA('BodyPosition') and movers[instance.Parent] == instance) then
                pcall(function()
                    instance:Destroy()
                end)
            end
        end
    end
    local moved = false
    for _, part in ipairs(parts) do
        if part.Parent then
            if orbitState then
                if orbitState.Touches[part] == nil then
                    orbitState.Touches[part] = part.CanTouch
                end
                if not orbitState.Offsets[part] then
                    orbitState.Offsets[part] = part.Position - origin
                end
            end
            Data['RPGReflectionProperties'] = Data['RPGReflectionProperties'] or {}
            if not Data['RPGReflectionProperties'][part] then
                Data['RPGReflectionProperties'][part] = { CanTouch = part.CanTouch, CanCollide = part.CanCollide }
            end
            pcall(function()
                part.CanTouch = false
                part.CanCollide = false
            end)
            local ok = pcall(function()
                part.Anchored = false
                part.AssemblyLinearVelocity = outwardVelocity
                part.AssemblyAngularVelocity = Vector3.zero
                local bodyPosition = movers[part]
                if not bodyPosition or bodyPosition.Parent ~= part then
                    bodyPosition = createbodymover('BodyPosition', part)
                    bodyPosition.Name = 'PhowgExplosiveReflect'
                    movers[part] = bodyPosition
                end
                bodyPosition.MaxForce = Vector3.new(math.huge, math.huge, math.huge)
                bodyPosition.P = 100000
                bodyPosition.D = 1000
                bodyPosition.Position = orbitState and destination + orbitState.Offsets[part] or part.Position + offset
            end)
            moved = moved or ok
        end
    end
    return moved
end
local function clearreflectedexplosives()
    for _, mover in pairs(Data['RPGReflectionMovers'] or {}) do
        pcall(function()
            mover:Destroy()
        end)
    end
    for _, state in pairs(Data['RPGOrbitProjectiles'] or {}) do
        for part, canTouch in pairs(state.Touches) do
            if part.Parent then
                pcall(function()
                    part.CanTouch = canTouch
                end)
            end
        end
    end
    for part, properties in pairs(Data['RPGReflectionProperties'] or {}) do
        if part.Parent then
            pcall(function()
                part.CanTouch = properties.CanTouch
                part.CanCollide = properties.CanCollide
            end)
        end
    end
    Data['RPGReflectionProperties'] = nil
    Data['RPGReflectionMovers'] = nil
    Data['RPGOrbitProjectiles'] = nil
    Data['RPGOrbitSerial'] = nil
end
phowg:register_cleanup('explosive reflection', function(scope)
    if not scope then
        clearreflectedexplosives()
    end
end)
function setdeflectrpg(enabled)
    local connection = Connections['DeflectRPGAdded']
    if connection then
        connection:Disconnect()
        Connections['DeflectRPGAdded'] = nil
    end
    stoprpgmove(not Data['RPGUnloading'] and not (Library and Library.Unloaded))
    clearreflectedexplosives()
    Data['RPGProjectiles'] = {}
    Data['RPGFolder'] = nil
    if not enabled then
        return
    end
    local ignored = Workspace:FindFirstChild('Ignored')
    if not ignored then
        return
    end
    Data['RPGFolder'] = ignored
    local function track(instance)
        if Data.RPGFolder ~= ignored or type(Data.RPGProjectiles) ~= 'table' or not instance:IsA('BasePart') then
            return
        end
        local owner = grenadelauncherowner(instance)
        if owner then
            Data['RPGProjectiles'][owner] = 'grenade launcher'
            return
        end
        if isrocketpart(instance) then
            Data['RPGProjectiles'][instance] = 'rocket'
        elseif instance.Name == 'Handle' and isgrenadepart(instance) then
            Data['RPGProjectiles'][instance] = 'grenade'
        end
    end
    create_connection(
        'DeflectRPGAdded',
        connectshared(
            ignored.DescendantAdded,
            track,
            ignored,
            'event/ignored.DescendantAdded',
            0,
            'event/DescendantAdded',
            ignored
        )
    )
    for _, instance in ipairs(ignored:GetDescendants()) do
        track(instance)
    end
end
registerheartbeat('DeflectRPG', function()
    if Data['RPGUnloading'] or (Library and Library.Unloaded) then
        return
    end
    if not (Toggles.deflect_rpg and Toggles.deflect_rpg.Value) then
        return
    end
    for part, mover in pairs(Data['RPGReflectionMovers'] or {}) do
        if typeof(part) ~= 'Instance' or typeof(mover) ~= 'Instance' or not part.Parent or mover.Parent ~= part then
            if typeof(mover) == 'Instance' then
                pcall(function()
                    mover:Destroy()
                end)
            end
            Data['RPGReflectionMovers'][part] = nil
            if (typeof(part) ~= 'Instance' or not part.Parent) and Data['RPGReflectionProperties'] then
                Data['RPGReflectionProperties'][part] = nil
            end
        end
    end
    if localactionblocked(true) then
        stoprpgmove(false)
        return
    end
    local ignored = Workspace:FindFirstChild('Ignored')
    if Data['RPGFolder'] ~= ignored then
        setdeflectrpg(true)
    end
    local character = LocalPlayer.Character
    local root = character and character:FindFirstChild('HumanoidRootPart')
    if not root or Data['IsRespawning'] then
        stoprpgmove(false)
        return
    end
    local clientCF = Local_Data['ClientPos']
    if typeof(clientCF) ~= 'CFrame' then
        local sync = type(Data.CSyncTable) == 'table' and Data.CSyncTable or {}
        clientCF = (sync[2] or Data.MoveToInFlight == root) and sync[1] or root.CFrame
        if typeof(clientCF) ~= 'CFrame' then
            clientCF = root.CFrame
        end
    end
    local threatCF = explosivepositioncf(character, root, clientCF)
    local threatPosition = threatCF.Position
    local resumeCF = Data.RPGMoveActive and Data.RPGThreatCharacter == character and Data.RPGThreatCF or threatCF
    if Data.RPGMoveActive and Data.RPGReturnTag then
        local active = Data.RPGReturnHold and validmovetohold(Data.RPGReturnHold)
            or not Data.RPGReturnHold and phowg:explosive_movement_active(Data.RPGReturnTag)
        if not active then
            resumeCF = clientCF
        end
    end
    if Data.Buying and typeof(Data.BuyTargetCF) == 'CFrame' then
        resumeCF = Data.BuyTargetCF
    end
    if typeof(resumeCF) ~= 'CFrame' then
        resumeCF = threatCF
    end
    local method = Options.deflect_rpg_method and Options.deflect_rpg_method.Value or 'move'
    local radius = method == 'reflect' and 50 or 30
    local nearest, nearestDistance, nearestKind, nearestCF = nil, radius + 0.001, nil, nil
    local canMove = not localactionblocked(true)
    local reflectNow = tick() - (Data['RPGReflectAt'] or 0) >= 0.03
    if reflectNow then
        Data['RPGReflectAt'] = tick()
    end
    for projectile, state in pairs(Data['RPGProjectiles'] or {}) do
        if typeof(projectile) ~= 'Instance' then
            Data['RPGProjectiles'][projectile] = nil
        elseif not ignored or not projectile.Parent or not projectile:IsDescendantOf(ignored) then
            releaseexplosivereflection(projectile)
            Data['RPGProjectiles'][projectile] = nil
        elseif state == 'rocket' or state == 'grenade' or state == 'grenade launcher' then
            local primary = explosivepart(projectile)
            local owner = projectile:IsA('BasePart') and projectile.Parent or projectile
            local controlledRocket = Data.RocketTPParts and Data.RocketTPParts[owner]
            local controlledGrenade = primary and Data.GrenadeControlledParts and Data.GrenadeControlledParts[primary]
            local teleporting = type(controlledRocket) == 'table'
                    and not controlledRocket.Released
                    and controlledRocket.Follow
                or type(controlledGrenade) == 'table' and not controlledGrenade.released
            if teleporting then
                releaseexplosivereflection(projectile)
            else
                local distance = primary and phowg:explosive_approach_distance(primary, threatPosition) or math.huge
                local moveDistance = primary and phowg:explosive_approach_distance(primary, resumeCF.Position) or math.huge
                local moveCF = distance <= moveDistance and threatCF or resumeCF
                moveDistance = math.min(distance, moveDistance)
                local moveProjectile = method == 'move' or method == 'hide' or method == 'reflect' and state == 'rocket'
                local projectileRadius = method == 'reflect' and state == 'grenade launcher' and 1000
                    or moveProjectile and 30
                    or radius
                local orbiting = method == 'reflect'
                    and state == 'grenade launcher'
                    and Data['RPGOrbitProjectiles']
                    and Data['RPGOrbitProjectiles'][projectile]
                if primary and ((moveProjectile and moveDistance or distance) <= projectileRadius or orbiting) then
                    if method == 'reflect' and state ~= 'rocket' and reflectNow then
                        local ok, err =
                            pcall(neutralizeexplosive, projectile, primary, threatPosition, state == 'grenade launcher')
                        if not ok and tick() - (Data['RPGReflectErrorAt'] or 0) >= 5 then
                            Data['RPGReflectErrorAt'] = tick()
                            warn('[Phowg] projectile reflection: ' .. tostring(err))
                        end
                    elseif moveProjectile and canMove and moveDistance < nearestDistance then
                        nearest = projectile
                        nearestDistance = moveDistance
                        nearestKind = state
                        nearestCF = moveCF
                    end
                end
            end
        end
    end
    if not nearest then
        if Data['RPGMoveActive'] then
            stoprpgmove(true)
        end
        return
    end
    if not Data['RPGMoveActive'] then
        Data.RPGClientCF = clientCF
        Data.RPGReturnCF = threatCF
        Data.RPGReturnTag = Data.AppliedServerCharacter == character and Data.AppliedServerTag or nil
        local override = Data.MovementOverrides and Data.MovementOverrides[Data.RPGReturnTag]
        Data.RPGReturnPriority = type(override) == 'table' and override.prio or Data.PRIO.DESYNC
        Data.RPGReturnHold = Data.AppliedServerCharacter == character and Data.AppliedServerHold or nil
        Data['RPGThreatCF'] = nearestCF
        Data['RPGThreatCharacter'] = character
        Data['CombatArrivalAt'] = nil
        Data['CombatArrivalLastAt'] = nil
        if Data['CSync'] and Data['CSync'].Queue then
            table.clear(Data['CSync'].Queue)
        end
    end
    Data.RPGThreatCF = nearestCF
    threatCF = nearestCF
    threatPosition = nearestCF.Position
    if method == 'hide' then
        Data['RPGEscapeCF'] = CFrame.new(threatPosition - Vector3.new(0, 65, 0)) * threatCF.Rotation
        Data['RPGEscapeAt'] = tick()
    elseif not Data['RPGEscapeCF'] or tick() - (Data['RPGEscapeAt'] or 0) >= 0.15 then
        local params = OverlapParams.new()
        params.FilterType = Enum.RaycastFilterType.Exclude
        params.FilterDescendantsInstances = { character, ignored }
        params.RespectCanCollide = true
        params.MaxParts = 1
        local escapeCF
        for _ = 1, 12 do
            local angle = math.random() * math.pi * 2
            local escapeRadius = math.random(65, 85)
            local position = threatPosition
                + Vector3.new(math.cos(angle) * escapeRadius, math.random(-20, 20), math.sin(angle) * escapeRadius)
            local cf = CFrame.new(position) * threatCF.Rotation
            if #Workspace:GetPartBoundsInBox(cf, Vector3.new(3, 6, 3), params) == 0 then
                escapeCF = cf
                break
            end
        end
        if not escapeCF then
            escapeCF = CFrame.new(threatPosition - Vector3.new(0, 65, 0)) * threatCF.Rotation
        end
        Data['RPGEscapeCF'] = escapeCF
        Data['RPGEscapeAt'] = tick()
    end
    Data['RPGMoveActive'] = true
    Data['RPGThreatKind'] = nearestKind
    local equipped = character:FindFirstChildOfClass('Tool')
    if equipped then
        phowg:deactivate_tool(equipped)
    end
    set_server_cframe(Data['RPGEscapeCF'], nil, 0.5, 'DeflectRPG')
end)
