function phowg:build_weapon_preview(weapon, skin)
    if type(weapon) ~= 'string' then
        return nil, 'Select a weapon'
    end
    local key, skinKey = phowg:skin_asset_key(weapon), phowg:skin_asset_key(skin or 'Default')
    local entries = Data.SkinTableCache and Data.SkinTableCache[weapon]
    if not entries then
        for name, value in pairs(Data.SkinTableCache or {}) do
            if phowg:skin_asset_key(name) == key then
                entries = value
                break
            end
        end
    end
    local info = entries and entries[skin]
    local isDefault = skin == nil or skin == 'Default' or skin == 'None'
    local source, base, sourceTool
    local modules = ReplicatedStorage:FindFirstChild('SkinModules')
    if key == 'knife' and not isDefault then
        local profile = phowg:knife_skin_profile(skin)
        local knives = modules and modules:FindFirstChild('Knives')
        source = knives and knives:FindFirstChild(profile and profile.Name or skin)
        local rig = Data.SkinAssetCatalog
            and Data.SkinAssetCatalog.KnifeRigs
            and Data.SkinAssetCatalog.KnifeRigs[skinKey]
        if rig and rig.Model and rig.Model.Parent then
            source = rig.Model
        end
    end
    local texture = info and (info.TextureID or info.TextureId)
    if not source and typeof(texture) == 'Instance' then
        source = texture
    end
    for _, parent in ipairs({ LocalPlayer.Character or false, LocalPlayer:FindFirstChildOfClass('Backpack') or false }) do
        if parent then
            local tool = parent:FindFirstChild(weapon)
            if tool and tool:IsA('Tool') then
                sourceTool = tool
                break
            end
        end
    end
    if sourceTool then
        base = sourceTool:FindFirstChild('Default')
            or sourceTool:FindFirstChildOfClass('MeshPart')
            or sourceTool:FindFirstChild('Handle')
    end
    if not base then
        local models = modules and modules:FindFirstChild('GunModels')
        if key == 'knife' then
            models = modules and modules:FindFirstChild('Knives')
            base = models and models:FindFirstChild('Default')
        else
            base = models and models:FindFirstChild(weapon)
        end
    end
    if base and not (base:IsA('BasePart') or base:IsA('Model')) then
        base = nil
    end
    local geometry
    if source and (source:IsA('BasePart') or source:IsA('Model')) then
        geometry = source:Clone()
    elseif not isDefault and info and info.MeshId and info.Scale then
        geometry = Instance.new('Part')
        geometry.Color, geometry.Material = info.Color or Color3.new(1, 1, 1), info.Material or Enum.Material.Plastic
        local mesh = Instance.new('SpecialMesh')
        mesh.MeshType, mesh.MeshId, mesh.Scale, mesh.TextureId =
            Enum.MeshType.FileMesh, info.MeshId, info.Scale, type(texture) == 'string' and texture or ''
        mesh.Parent = geometry
    elseif base then
        geometry = base:Clone()
        if geometry then
            local state = Data.SkinModelStates and Data.SkinModelStates[sourceTool]
            if state and state.Base == base then
                geometry.Transparency = state.Transparency
                if geometry:IsA('MeshPart') and state.Texture then
                    geometry.TextureID = state.Texture
                end
                local originals, copies = base:GetDescendants(), geometry:GetDescendants()
                for i, original in ipairs(originals) do
                    local saved = state.NativeGeometry and state.NativeGeometry[original]
                    if saved and saved.Transparency and copies[i] and copies[i]:IsA('BasePart') then
                        copies[i].Transparency = saved.Transparency
                    end
                end
            end
            if not isDefault then
                if not info or type(texture) ~= 'string' or not geometry:IsA('MeshPart') then
                    geometry:Destroy()
                    return nil, 'Skin geometry is not available in this client'
                end
                geometry.TextureID = texture
                if info.Color then
                    geometry.Color = info.Color
                end
                if info.Material then
                    geometry.Material = info.Material
                end
            end
        end
    end
    if not geometry then
        return nil, 'Weapon model unavailable. Equip this weapon to load its preview.'
    end
    local model = Instance.new('Model')
    model.Name = 'SkinPreview'
    local reference = geometry:IsA('BasePart') and geometry.CFrame or geometry:GetPivot()
    local offset = info and typeof(info.CFrame) == 'CFrame' and info.CFrame or CFrame.new()
    model:SetAttribute('PhowgPreviewBasis', (reference * offset:Inverse()).Rotation)
    geometry.Parent = model
    local parts = 0
    for _, object in ipairs(model:GetDescendants()) do
        if object:IsA('BasePart') then
            object.Anchored, object.CanCollide, object.CanTouch, object.CanQuery = true, false, false, false
            object.LocalTransparencyModifier = 0
            parts += 1
        elseif
            object:IsA('LuaSourceContainer')
            or object:IsA('Sound')
            or object:IsA('JointInstance')
            or object:IsA('Constraint')
            or object:IsA('ParticleEmitter')
            or object:IsA('Beam')
            or object:IsA('Trail')
        then
            object:Destroy()
        end
    end
    if parts == 0 then
        model:Destroy()
        return nil, 'No renderable geometry in this skin'
    end
    return model
end
function phowg:weapon_workspace_summary()
    local weapon = Options.skin_selected_weapon and Options.skin_selected_weapon.Value
    local tool
    local character, backpack = LocalPlayer.Character, LocalPlayer:FindFirstChildOfClass('Backpack')
    if character then
        tool = character:FindFirstChild(weapon or '')
    end
    if not tool and backpack then
        tool = backpack:FindFirstChild(weapon or '')
    end
    local ammo = tool and tool:FindFirstChild('Ammo')
    local capacity = tool and tool:FindFirstChild('MaxAmmo')
    local reserve = tool and getgunreserve(tool)
    local manager = Toggles.loadout_manager and Toggles.loadout_manager.Value
    return (manager and 'Loadout active' or 'Loadout off')
        .. (
            ammo
                and '  /  ' .. tostring(ammo.Value) .. (capacity and '/' .. tostring(capacity.Value) or '') .. ' loaded' .. (reserve ~= nil and '  /  ' .. tostring(
                    reserve
                ) .. ' reserve' or '')
            or '  /  weapon not owned'
        )
end
function phowg:bind_classic_weapon_rail()
    local window = Data['Window']
    local option = Options.skin_selected_weapon
    if not window.SetWeaponProfiles or not option then
        return
    end
    local function icon(weapon)
        local esp = Data.ESPInstance or getgenv().ESP
        if esp and esp.GetWeaponIconAsset then
            return esp:GetWeaponIconAsset(weapon)
        end
        return nil
    end
    local function rebuild()
        if Library.Unloaded then
            return
        end
        window:SetWeaponProfiles(
            option.Values,
            icon,
            function(weapon)
                option:SetValue(weapon)
                Library:AttemptSave()
            end,
            option.Value,
            function(weapon)
                return Data.SkinEquipped[weapon] or 'Default'
            end
        )
    end
    phowg.refresh_classic_weapon_profiles = function(self)
        if not Library.Unloaded then
            window:UpdateSelectedWeapon(option.Value)
        end
        if Data.WeaponWorkspace then
            Data.WeaponWorkspace.QueueRefresh()
        end
    end
    local setValue, setValues = option.SetValue, option.SetValues
    option.SetValue = function(item, ...)
        local result = setValue(item, ...)
        window:UpdateSelectedWeapon(item.Value)
        if Data.WeaponWorkspace then
            Data.WeaponWorkspace.QueueRefresh()
        end
        return result
    end
    option.SetValues = function(item, ...)
        local result = setValues(item, ...)
        rebuild()
        return result
    end
    local skin = Options.skin_weapon_skin
    if skin and skin.SetValue then
        local setSkin = skin.SetValue
        skin.SetValue = function(item, ...)
            local result = setSkin(item, ...)
            window:UpdateSelectedWeapon(option.Value)
            if Data.WeaponWorkspace then
                Data.WeaponWorkspace.QueueRefresh()
            end
            return result
        end
    end
    rebuild()
    local bound, readyConnection
    phowg.classic_rail_bind_icons = function(self, esp)
        if bound == esp then
            return
        end
        if readyConnection then
            readyConnection:Disconnect()
            readyConnection = nil
        end
        bound = esp
        if esp and esp.WatchWeaponIcons then
            readyConnection = esp:WatchWeaponIcons(function()
                if not Library.Unloaded then
                    window:RefreshWeaponIcons()
                end
            end)
            if readyConnection then
                Library:GiveSignal(readyConnection)
            end
        end
        window:RefreshWeaponIcons()
    end
    phowg:classic_rail_bind_icons(Data.ESPInstance or getgenv().ESP)
end
