if Options.skin_weapon_skin then
    Options.skin_weapon_skin:OnChanged(function(val)
        if Data.SkinDropdownSync or Data.SkinConfigLoading or Library.ConfigLoading then
            return
        end
        if val ~= Options.skin_weapon_skin.Value then
            return
        end
        local sel = Options.skin_selected_weapon and Options.skin_selected_weapon.Value or '[Revolver]'
        if type(sel) == 'table' then
            for k, v in pairs(sel) do
                if v then
                    sel = k
                    break
                end
            end
        end
        if type(sel) ~= 'string' then
            return
        end
        local skin = val
        if type(skin) == 'table' then
            for k, v in pairs(skin) do
                if v then
                    skin = k
                    break
                end
            end
        end
        if type(skin) == 'string' and #skin > 0 then
            Data['SkinEquipped'][sel] = skin
            if SaveManager.MarkStateChanged then
                SaveManager:MarkStateChanged('weapon_skins')
            end
            if phowg.refresh_classic_weapon_profiles then
                phowg:refresh_classic_weapon_profiles()
            end
            Data.SkinVisibleWeapon = sel
            phowg:sync_skin_inventory_selection(sel)
            local char = LocalPlayer.Character
            if char then
                for _, t in ipairs(char:GetChildren()) do
                    if t:IsA('Tool') and t.Name == sel then
                        onskintooladded(t)
                    end
                end
            end
        end
    end)
end
