if Library.CreateWeaponWorkspace and Data.Window.ConfigureItemWorkspace then
    Data.WeaponPreviewBox = Data.Tabs.Items:AddLeftGroupbox('skin preview')
    Data.WeaponWorkspace = Library:CreateWeaponWorkspace(Data.WeaponPreviewBox, phowg_callbacks.build_weapon_preview, function()
        local weapon = Options.skin_selected_weapon.Value
        local character, backpack = LocalPlayer.Character, LocalPlayer:FindFirstChildOfClass('Backpack')
        local tool = character and character:FindFirstChild(weapon) or backpack and backpack:FindFirstChild(weapon)
        local selectedSkin = Options.skin_weapon_skin.Value
        local entries = Data.SkinTableCache and Data.SkinTableCache[weapon]
        return weapon, selectedSkin, Options.skin_weapon_skin.Values, tool, entries and entries[selectedSkin]
