}) do
    Data.SafeModeFeatures[name] = true
end
function phowg:safe_mode_blocks_toggle(name)
    return type(name) == 'string'
        and (
            Data.SafeModeFeatures[name] == true
            or name:match('^auto_') ~= nil
            or name:match('^loadout_') ~= nil
            or name:match('^armor_buy_') ~= nil
            or name:match('^israel_') ~= nil
            or name:match('^neckgrab_tool_') ~= nil
        )
end
function Library.SafeModeControlAllowed(name, control, value)
    if control.Type ~= 'Toggle' or not Data.SafeMode or not phowg:safe_mode_blocks_toggle(name) or value ~= true then
        return true
    end
    return Data.SafeModeRestoring == true
        and Data.SafeModeSnapshot ~= nil
        and Data.SafeModeSnapshot.Toggles[name] == true
end
function phowg:guard_safe_mode_controls()
    for name, control in pairs(Toggles) do
        if phowg:safe_mode_blocks_toggle(name) and not control.PhowgSafeModeGuard then
            local setValue = control.SetValue
            control.PhowgSafeModeGuard = true
            control.SetValue = function(item, value, ...)
                if Data.SafeMode then
                    local desired = Data.SafeModeRestoring
                            and Data.SafeModeSnapshot
                            and Data.SafeModeSnapshot.Toggles[name] == true
                        or false
                    if (not not value) ~= desired then
                        if item.Value == desired then
                            return
                        end
                        value = desired
                    end
                end
                return setValue(item, value, ...)
            end
        end
    end
    local copy = Options.avatar_spoof_copy
    if copy and not copy.PhowgSafeModeGuard then
        local setValue = copy.SetValue
        copy.PhowgSafeModeGuard = true
        copy.SetValue = function(item, value, ...)
            if Data.SafeMode and not Data.SafeModeRestoring and type(value) == 'table' then
                value = table.clone(value)
                value.animations, value.emotes = nil, nil
                for index = #value, 1, -1 do
                    if value[index] == 'animations' or value[index] == 'emotes' then
                        table.remove(value, index)
                    end
                end
            end
            return setValue(item, value, ...)
        end
    end
end
function phowg:set_safe_mode(enabled)
    if Data.Unloading or Library.Unloaded then
        Data.SafeMode, Data.SafeModeSnapshot, Data.SafeModePending = false, nil, nil
        Data.SafeModeChanging, Data.SafeModeRestoring = nil, nil
        return
    end
    enabled = enabled == true
    if Data.SafeModeChanging then
        Data.SafeModePending = enabled
        return
    end
    if enabled == (Data.SafeMode == true) then
        return
    end
    Data.SafeModeChanging = true
    phowg:guard_safe_mode_controls()
    local function run(callback, ...)
        if type(callback) ~= 'function' then
            return
        end
        local ok, problem = pcall(callback, ...)
        if not ok then
            warn('[Phowg] safe mode: ' .. tostring(problem))
        end
    end
    if enabled then
        local snapshot = { Toggles = {}, Keys = {}, Flags = {}, WasFlying = Data.Flying == true }
        for name, control in pairs(Toggles) do
            if phowg:safe_mode_blocks_toggle(name) then
                snapshot.Toggles[name] = control.Value == true
            end
        end
        for _, name in ipairs({
            'RagebotActive',
            'TargetStrafeActive',
            'DesyncActive',
            'UndergroundActive',
            'VelocityActive',
            'SpinbotActive',
            'VoidActive',
            'ManualVoid',
            'HideVoid',
        }) do
            snapshot.Flags[name] = Data[name]
        end
        for name, option in pairs(Options) do
            if option.Type == 'KeyPicker' then
                snapshot.Keys[name] = option.Toggled
            end
        end
        local copy = Options.avatar_spoof_copy
        if copy then
            snapshot.AvatarCopy = type(copy.Value) == 'table' and table.clone(copy.Value) or copy.Value
        end
        Data.SafeModeSnapshot, Data.SafeMode = snapshot, true
        run(phowg_callbacks.stop_gun_fire)
        run(phowg_callbacks.cancel_pending_support)
        if Data.PurchaseBatch then
            run(phowg_callbacks.finish_purchases, Data.PurchaseBatch, true)
        end
        run(phowg_callbacks.stop_auto_grenade_throw)
        Data.NukeGrenadeJob = nil
        run(phowg.clear_ragebot_idle)
        run(phowg.clear_ragebot_void_spam)
        for name in pairs(snapshot.Toggles) do
            if Toggles[name].Value then
                run(Toggles[name].SetValue, Toggles[name], false)
            end
        end
        Data.RagebotActive, Data.TargetStrafeActive, Data.DesyncActive, Data.UndergroundActive =
            false, false, false, false
        Data.VoidActive, Data.ManualVoid, Data.HideVoid, Data.BuildActive = false, nil, nil, nil
        if Data.CSync and Data.CSync.Queue then
            table.clear(Data.CSync.Queue)
            Data.CSync.PendingCF = nil
        end
        for name in pairs(Data.MoveToHolds or {}) do
            run(stopmovetohold, name)
        end
        if Data.MovementOverrides then
            table.clear(Data.MovementOverrides)
        end
        run(phowg_callbacks.cancel_c_frame_movement)
        run(stopfly)
        run(stopvelocity)
        run(stopspinbot)
        run(stopgrenadetp)
        run(hidevisualizer)
        if copy and type(snapshot.AvatarCopy) == 'table' then
            run(copy.SetValue, copy, snapshot.AvatarCopy, true)
        end
        run(phowg_callbacks.stop_avatar_mood, Data.AvatarSpoof)
        task.defer(function()
            if not Library.Unloaded then
                phowg:avatar_copy_changed()
            end
        end)
    else
        local snapshot = Data.SafeModeSnapshot
        Data.SafeModeRestoring = true
        if snapshot then
            if Options.avatar_spoof_copy and snapshot.AvatarCopy ~= nil then
                run(Options.avatar_spoof_copy.SetValue, Options.avatar_spoof_copy, snapshot.AvatarCopy, true)
            end
            for name, value in pairs(snapshot.Toggles) do
                if Toggles[name] and Toggles[name].Value ~= value then
                    run(Toggles[name].SetValue, Toggles[name], value, true)
                end
            end
            for name, value in pairs(snapshot.Keys) do
                local option = Options[name]
                if option then
                    option.Toggled = value
                    run(option.Update, option)
                end
            end
            for _, name in ipairs({
                'RagebotActive',
                'TargetStrafeActive',
                'DesyncActive',
                'UndergroundActive',
                'VelocityActive',
                'SpinbotActive',
                'VoidActive',
                'ManualVoid',
                'HideVoid',
            }) do
                Data[name] = snapshot.Flags[name]
            end
        end
        Data.SafeMode, Data.SafeModeRestoring, Data.SafeModeSnapshot = false, nil, nil
        task.defer(function()
            if not Library.Unloaded then
                phowg:avatar_copy_changed()
            end
        end)
        if snapshot then
            if snapshot.WasFlying and Toggles.fly and Toggles.fly.Value then
                run(startfly)
            end
            if Data.VelocityActive and Toggles.speed_velocity and Toggles.speed_velocity.Value then
                run(startvelocity)
            end
            if rageboton() or punishmentactive() then
                run(ragebot_on)
            end
            if Data.TargetStrafeActive then
                run(spawnlooponce, 'TargetStrafe', targetstrafeloop)
            end
            if Data.UndergroundActive then
                run(spawnlooponce, 'Underground', undergroundloop)
            end
            if Data.VoidActive then
                run(spawnlooponce, 'VoidHide', voidhideloop)
            end
            if Data.DesyncActive then
                run(spawnlooponce, 'UnifiedCharacter', unified_character_loop)
            end
        end
    end
    Data.SafeModeChanging = nil
    local pending = Data.SafeModePending
    Data.SafeModePending = nil
    if pending ~= nil and pending ~= (Data.SafeMode == true) then
        task.defer(function()
            if not Library.Unloaded then
                phowg:set_safe_mode(pending)
            end
        end)
    end
end
