phowg:register_cleanup('esp runtime', function(_, reason)
    if reason ~= 'unload' then
        return
    end
    local esp = Data.ESPInstance
    Data.ESPInstance = nil
    if esp and type(esp._Cleanup) == 'function' then
        pcall(esp._Cleanup)
    end
    if getgenv().ESP == esp then
        getgenv().ESP = nil
    end
end)
phowg:register_cleanup('legacy visuals', function(_, reason)
    if reason == 'unload' then
        phowg:destroy_runtime_visuals()
    end
end)
phowg:register_cleanup('runtime exports', function(_, reason)
    if reason ~= 'unload' then
        return
    end
    local environment = getgenv()
    for key, value in pairs({
        PhowgData = Data,
        PhowgFunc = phowg,
        PhowgLibrary = Library,
        Library = Library,
        SaveManager = SaveManager,
        Toggles = Toggles,
        Options = Options,
    }) do
        if environment[key] == value then
            environment[key] = nil
        end
    end
    if type(environment.Data) == 'table' and environment.Data.WhitelistedLabel == Data.WhitelistedLabel then
        environment.Data.WhitelistedLabel = nil
    end
    if _G and _G.SaveManager == SaveManager then
        pcall(function()
            _G.SaveManager = nil
        end)
    end
end)
function phowg:unload_script()
    if Data.UnloadRequested then
        return
    end
    Data.UnloadRequested = true
    phowg:stop_runtime_features()
    Library:Unload()
end
