            local part = charParts and charParts[name] or nil
            if part and phowg:closest_part_allowed(name) then
                local p, on = Workspace.CurrentCamera:WorldToViewportPoint(part.Position)
                if on then
                    local d = (mousePos - Vector2.new(p.X, p.Y)).Magnitude
                    if d < closest then
                        closest = d
                        best = part
                    end
                end
            end
        end
        return best
    end
    function canonicalhitbox(name)
        local n = string.lower(tostring(name or ''))
        if n == 'humanoidrootpart' then
            return 'HumanoidRootPart'
        end
        if n == 'uppertorso' then
            return 'UpperTorso'
        end
        if n == 'lowertorso' then
            return 'LowerTorso'
        end
        if n == 'closest' then
            return 'Closest'
        end
        if n == 'random' then
            return 'Random'
        end
        return 'Head'
    end
    function getsilentorigin()
        local okCache, toolCache = pcall(function()
            return IntelligenceHandler:Cache_Tool()
        end)
        toolCache = okCache and toolCache or nil
        if toolCache and toolCache.handle and toolCache.handle.Parent then
            local okMuz, muz = pcall(function()
                return toolCache.handle.CFrame * toolCache.offset
            end)
            if okMuz and typeof(muz) == 'Vector3' then
                return muz
            end
            if toolCache.handle.Position then
                return toolCache.handle.Position
            end
        end
        local myChar = LocalPlayer and LocalPlayer.Character
        local myRoot = myChar and myChar:FindFirstChild('HumanoidRootPart')
        if myRoot then
            return myRoot.Position
        end
        local cam = Workspace.CurrentCamera
        if cam then
            return cam.CFrame.Position
        end
        return nil
    end
    function ispartvisiblefrom(OriginPos, TargetChar)
        if not TargetChar then
            return false
        end
        if not OriginPos then
            return true
        end
        local Filter = { TargetChar }
        local MyChar = LocalPlayer and LocalPlayer.Character
        if MyChar then
            Filter[#Filter + 1] = MyChar
        end
        local params = RaycastParams.new()
        params.FilterDescendantsInstances = phowg:wallbang_filter(Filter)
        params.FilterType = Enum.RaycastFilterType.Blacklist
        for _, PartName in ipairs({ 'Head', 'UpperTorso', 'LowerTorso', 'HumanoidRootPart' }) do
            local Part = TargetChar:FindFirstChild(PartName)
            if not Part and PartName == 'UpperTorso' then
                Part = TargetChar:FindFirstChild('Torso')
            end
            if Part and Part:IsA('BasePart') then
                local res = Workspace:Raycast(OriginPos, (Part.Position - OriginPos), params)
                if not res or (res.Instance and res.Instance:IsDescendantOf(TargetChar)) then
                    return true
                end
            end
        end
        return false
    end
    local function refresh_silent_fov()
        if not alivedrawing(SilentFOVCircle) then
            SilentFOVCircle = newdrawingcircle()
            Data['SilentFOVAt'] = tick()
        elseif tick() - (Data['SilentFOVAt'] or 0) > 2 then
            local freshFov = newdrawingcircle()
            if freshFov then
                pcall(function()
                    if SilentFOVCircle then
                        SilentFOVCircle:Remove()
                    end
                end)
                SilentFOVCircle = freshFov
                Data['SilentFOVAt'] = tick()
            end
        end
    end
    local function do_silent_aim()
        refresh_silent_fov()
        local toggleOn = Toggles.silent_aim_enabled and Toggles.silent_aim_enabled.Value
        local hasKey = false
        hasKey = Options.silent_aim_keybind and Options.silent_aim_keybind:GetState()
        if not toggleOn then
            Data['SilentAimTarget'] = nil
            Data['SilentAimPos'] = nil
            Data['SilentAimHitPart'] = nil
            pcall(function()
                if SilentFOVCircle then
                    SilentFOVCircle.Visible = false
                end
            end)
            for _, Line in pairs(Data['SilentFOVRing'] or {}) do
                pcall(function()
                    if Line then
                        Line.Visible = false
                    end
                end)
            end
            phowg:update_main_fov('silent_aim', nil, nil, nil, false)
            Data['SilentAimKeyPrev'] = hasKey
            return
        end
        local cam = Workspace.CurrentCamera
        if not cam then
            return
        end
        local mousePos = UserInputService:GetMouseLocation()
        local silentFov = (Options.silent_aim_fov and Options.silent_aim_fov.Value) or 150
        local silentFovCol = (Options.silent_aim_fov_color and Options.silent_aim_fov_color.Value)
            or Color3.fromRGB(255, 255, 255)
        local silentFovShow = (
            (Toggles.silent_aim_show_fov and Toggles.silent_aim_show_fov.Value)
            and (Toggles.silent_aim_enabled and Toggles.silent_aim_enabled.Value)
        ) or false
        if SilentFOVCircle then
            SilentFOVCircle.Visible = false
        end
        phowg:update_main_fov('silent_aim', mousePos, silentFov, silentFovCol, silentFovShow)
        local stickyOn = Toggles.sticky_aim_enabled and Toggles.sticky_aim_enabled.Value
        if Data['SilentAimStickyTargets'] == nil then
            Data['SilentAimStickyTargets'] = {}
        end
        local candidates = {}
        for _, plr in ipairs(Players:GetPlayers()) do
            if
                plr ~= LocalPlayer
                and intelligence:get_character_cache(plr)
                and not plr.Character:FindFirstChildOfClass('ForceField')
            then
                if
                    iscrewwhitelisted(plr)
                    or iswhitelistedplayer(plr)
                    or (Data['RageWhitelist'] and Data['RageWhitelist'][plr])
                then
                else
                    table.insert(candidates, plr)
                end
            end
        end
        local best, bestDist, bestCF, bestPart = nil, 9e9, nil, nil
        local fov = (Options.silent_aim_fov and Options.silent_aim_fov.Value) or 150
        local useFov = Toggles.silent_aim_use_fov and Toggles.silent_aim_use_fov.Value
        local noKnocked = false
        do
            local disSel = (Options.silent_aim_disablers and Options.silent_aim_disablers.Value) or {}
            if disSel['target knocked'] then
                noKnocked = true
            end
            if not noKnocked and type(disSel) == 'table' then
                for _, v in ipairs(disSel) do
                    if v == 'target knocked' then
                        noKnocked = true
                        break
                    end
                end
            end
        end
        for plr, _ in pairs(Data['SilentAimStickyTargets']) do
            if not is_sticky_valid(plr) then
                Data['SilentAimStickyTargets'][plr] = nil
                if Data['StickyTarget'] == plr then
                    clear_sticky_target('silent invalid')
                end
            end
        end
        Data['SilentAimStickyLocked'] = nil
        if not stickyOn then
            if Data['StickyTarget'] ~= nil then
                clear_sticky_target('silent toggle off')
            end
            Data['SilentAimStickyTargets'] = {}
        end
        do
            local _curST = get_sticky_target()
            if _curST then
                Data['SilentAimStickyTargets'][_curST] = true
            end
        end
        if not hasKey then
            Data['SilentAimTarget'] = nil
            Data['SilentAimPos'] = nil
            Data['SilentAimHitPart'] = nil
            if Data['CurrentActionTarget'] ~= nil and Data['CurrentActionTarget'] == Data['SilentAimLastTarget'] then
                Data['CurrentActionTarget'] = nil
            end
            Data['SilentAimLastTarget'] = nil
            return
        end
        for _, plr in ipairs(candidates) do
            if noKnocked and isknocked(plr) then
            else
                local parts = {
                    Head = plr.Character:FindFirstChild('Head'),
                    HumanoidRootPart = plr.Character:FindFirstChild('HumanoidRootPart'),
                    UpperTorso = plr.Character:FindFirstChild('UpperTorso') or plr.Character:FindFirstChild('Torso'),
                    LowerTorso = plr.Character:FindFirstChild('LowerTorso'),
                }
                local hitName = canonicalhitbox(
                        Toggles.silent_aim_closest_part and Toggles.silent_aim_closest_part.Value and 'closest'
                            or (Options.silent_aim_hitbox and Options.silent_aim_hitbox.Value)
                            or 'head'
                    )
                local targetPart = hitName == 'Closest' and get_closest_hitbox(mousePos, parts)
                    or parts[hitName]
                    or parts['Head']
                if targetPart then
                    local sp, on = cam:WorldToViewportPoint(targetPart.Position)
                    if on then
                        local dist = (Vector2.new(sp.X, sp.Y) - mousePos).Magnitude
                        if not useFov or dist <= fov then
                            if dist < bestDist then
                                bestDist = dist
                                best = plr
                                bestCF = targetPart.CFrame
                                bestPart = targetPart
                            end
                        end
                    end
                end
            end
        end
        local lockedBest, lockedDist, lockedCF, lockedPart = nil, 9e9, nil, nil
        for plr, _ in pairs(Data['SilentAimStickyTargets']) do
            if not is_sticky_valid(plr) then
                Data['SilentAimStickyTargets'][plr] = nil
            elseif phowg:sticky_character(plr) then
                local parts = {
                    Head = plr.Character:FindFirstChild('Head'),
                    HumanoidRootPart = plr.Character:FindFirstChild('HumanoidRootPart'),
                    UpperTorso = plr.Character:FindFirstChild('UpperTorso') or plr.Character:FindFirstChild('Torso'),
                    LowerTorso = plr.Character:FindFirstChild('LowerTorso'),
                }
                local hitName = canonicalhitbox(
                        Toggles.silent_aim_closest_part and Toggles.silent_aim_closest_part.Value and 'closest'
                            or (Options.silent_aim_hitbox and Options.silent_aim_hitbox.Value)
                            or 'head'
                    )
                local targetPart = hitName == 'Closest' and get_closest_hitbox(mousePos, parts)
                    or parts[hitName]
                    or parts['Head']
                if targetPart then
                    local sp, on = cam:WorldToViewportPoint(targetPart.Position)
                    if on then
                        local dist = (Vector2.new(sp.X, sp.Y) - mousePos).Magnitude
                        if not useFov or dist <= fov then
                            if dist < lockedDist then
                                lockedDist = dist
                                lockedBest = plr
                                lockedCF = targetPart.CFrame
                                lockedPart = targetPart
                            end
                        end
                    end
                end
            end
        end
        if lockedBest then
            best = lockedBest
            bestDist = lockedDist
            bestCF = lockedCF
            bestPart = lockedPart
        end
        if
            (Options.silent_aim_hitbox and Options.silent_aim_hitbox.Value) == 'random'
            and intelligence:get_character_cache(best)
        then
            local rp = get_random_hitbox(nil, best.Character)
            if rp then
                bestPart = rp
                bestCF = rp.CFrame
            end
        end
        if not hasKey then
            Data['SilentAimTarget'] = nil
            Data['SilentAimPos'] = nil
            Data['SilentAimHitPart'] = nil
            return
        end
        if
            best
            and best ~= lockedBest
            and (
                iscrewwhitelisted(best)
                or iswhitelistedplayer(best)
                or (Data['RageWhitelist'] and Data['RageWhitelist'][best])
            )
        then
            best = nil
            bestCF = nil
            bestPart = nil
        end
        if noKnocked and best and best ~= lockedBest and isknocked(best) then
            if Data['SilentAimStickyTargets'] then
                Data['SilentAimStickyTargets'][best] = nil
            end
            best = nil
            bestCF = nil
            bestPart = nil
        end
        Data['SilentAimTarget'] = best
        Data['SilentAimPos'] = bestCF
        Data['SilentAimHitPart'] = bestPart
        if best then
            Data['CurrentMainTarget'] = best
            Data['CurrentActionTarget'] = best
            Data['SilentAimLastTarget'] = best
        end
        if not best or not bestCF then
            return
        end
        local dis = (Options.silent_aim_disablers and Options.silent_aim_disablers.Value) or {}
        if dis['outside of fov'] and useFov and bestDist > fov then
            Data['SilentAimTarget'] = nil
            Data['SilentAimPos'] = nil
            return
        end
        if dis['off screen'] then
            local _, on = cam:WorldToViewportPoint(bestCF.Position)
            if not on then
                Data['SilentAimTarget'] = nil
                Data['SilentAimPos'] = nil
                return
            end
        end
        if dis['behind wall'] and Toggles.silent_aim_visible_check and Toggles.silent_aim_visible_check.Value then
            if not ispartvisiblefrom(getsilentorigin(), best.Character) then
                Data['SilentAimTarget'] = nil
                Data['SilentAimPos'] = nil
                return
            end
        end
    end
    registerheartbeat('SilentAim', do_silent_aim)
    function phowg:redirect_range(value)
        if value == math.huge then
            return 99999
        end
        if type(value) ~= 'number' or value ~= value or value <= 0 then
            return 200
        end
        return math.min(value, 99999)
    end
    function applysilentredir(ShootData, Target, Pos, Part, Source, Prepared)
        if type(ShootData) ~= 'table' or ShootData.Shooter ~= LocalPlayer.Character or localshootblocked() then
            return false
        end
        local character = Target and Target.Character
        if not character or not Target.Parent then
            return false
        end
        if phowg:is_sticky_aim_source(Target, Source) then
            if not is_sticky_valid(Target) then
                return false
            end
        elseif
            isdead(Target)
            or iscrewwhitelisted(Target)
            or iswhitelistedplayer(Target)
            or (Data.RageWhitelist and Data.RageWhitelist[Target])
        then
            return false
        end
        local cached = Prepared
            and Prepared.Target == Target
            and Prepared.TargetCharacter == character
            and Prepared.Shooter == LocalPlayer.Character
            and Prepared.Source == Source
            and tick() - Prepared.At >= 0
            and tick() - Prepared.At <= 0.15
        if cached and Prepared.Bypass then
            return false
        end
        local automatic = Source == 'Support' or Source == 'Ragebot' or Source == 'KillAura'
        local sticky = phowg:is_sticky_aim_source(Target, Source)
        if sticky and (not phowg:sticky_checks_pass(Target) or not phowg:sticky_shoot_allowed(Target)) then
            return false
        end
        local chance = (automatic or sticky) and 100
            or tonumber(Options.silent_aim_hit_chance and Options.silent_aim_hit_chance.Value)
            or 100
        if not cached and math.random(1, 100) > math.clamp(chance, 0, 100) then
            return false
        end
        local targetPart = Part
        if
            typeof(targetPart) ~= 'Instance'
            or not targetPart:IsA('BasePart')
            or not targetPart:IsDescendantOf(character)
        then
            targetPart = character:FindFirstChild('Head')
                or character:FindFirstChild('UpperTorso')
                or character:FindFirstChild('Torso')
                or character:FindFirstChild('HumanoidRootPart')
        end
        if not targetPart then
            return false
        end
        local origin = gunshootorigin(ShootData.Handle, ShootData.ForcedOrigin)
        if not phowg:perfect_hit_vector(origin) then
            return false
        end
        local position = targetPart.Position
        if phowg:gun_shoot_method(Source, Target) ~= 'shoot redirect' then
            position = cached and Prepared.Position
                or typeof(Pos) == 'CFrame' and Pos.Position
                or typeof(Pos) == 'Vector3' and Pos
                or position
            if not cached then
                position = predpos(position, character)
            end
        end
        if Source == 'SilentAim' and Toggles.silent_aim_match_y and Toggles.silent_aim_match_y.Value then
            position = Vector3.new(position.X, targetPart.Position.Y, position.Z)
        end
        if not phowg:perfect_hit_vector(position) then
            return false
        end
        local disablers = sticky and (Options.sticky_aim_disablers and Options.sticky_aim_disablers.Value or {})
            or (Options.silent_aim_disablers and Options.silent_aim_disablers.Value or {})
        local visibility = sticky and Toggles.sticky_aim_visible_check or Toggles.silent_aim_visible_check
        if not automatic and disablers['behind wall'] and visibility and visibility.Value then
            local expanded = Toggles.wallbang and Toggles.wallbang.Value and Data.HitboxSet and Data.HitboxSet[Target]
            if not expanded and not ispartvisiblefrom(origin, character) then
                return false
            end
        end
        local delta = position - origin
        if delta.Magnitude < 0.001 then
            return false
        end
        local range = phowg:redirect_range(ShootData.Range)
        local aim = position
        if Toggles.custom_spread and Toggles.custom_spread.Value and typeof(ShootData.AimPosition) == 'Vector3' then
            local spread = ShootData.AimPosition - origin
            if spread.Magnitude > 0.001 then
                local amount = math.clamp(
                    tonumber(Options.custom_spread_amount and Options.custom_spread_amount.Value) or 100,
                    0,
                    100
                ) / 100
                local spreadState = Data.GunModuleHooks and Data.GunModuleHooks.Spread
                local tool = ShootData.Handle and ShootData.Handle.Parent
                if
                    amount > 0
                    and spreadState
                    and spreadState.Enabled
                    and tool
                    and type(spreadState.Scales[tool.Name]) == 'number'
                then
                    amount = 1
                end
                local direction = spread.Unit:Lerp(delta.Unit, 1 - amount)
                if direction.Magnitude > 0.001 then
                    aim = origin + direction.Unit * range
                end
            end
        end
        ShootData.ForcedOrigin, ShootData.Origin = origin, origin
        ShootData.AimPosition, ShootData.Position = aim, position
        ShootData.Normal, ShootData.Range = Vector3.new(0, 1, 0), range
        if ShootData.Handle then
            Data.CurrentActionTarget = Target
        end
        return true,
            {
                Target = Target,
                TargetCharacter = character,
                Shooter = LocalPlayer.Character,
                Source = Source,
                Position = position,
                At = tick(),
            }
    end
    function phowg:sticky_redirect_packet(handle, origin)
        if Library.Unloaded or Data.SharedSignalsClosed or localshootblocked() then
            return nil
        end
        local character = LocalPlayer.Character
        local tool = typeof(handle) == 'Instance' and handle.Parent
        if not tool or not tool:IsA('Tool') or tool.Parent ~= character or not tool:FindFirstChild('Ammo') then
            return nil
        end
        local target, position, part, source = phowg:get_gun_shot_target()
        if
            not target
            or not phowg:is_sticky_aim_source(target, source)
            or phowg:gun_shoot_method(source, target) ~= 'shoot redirect'
        then
            return nil
        end
        local range = tool:FindFirstChild('Range')
        local packet: { [string]: any } =
            { Shooter = character, Handle = handle, ForcedOrigin = origin, Range = range and range.Value }
        if not applysilentredir(packet, target, position, part, source) then
            return nil
        end
        local delta = packet.AimPosition - packet.ForcedOrigin
        if delta.Magnitude < 0.001 then
            return nil
        end
        local ignored = Data.StickyRayIgnored
        if not ignored then
            local module = ReplicatedStorage:FindFirstChild('MainModule')
            local ok, result = pcall(require, module)
            if ok and type(result) == 'table' and type(result.Ignored) == 'table' then
                ignored = result.Ignored
                Data.StickyRayIgnored = ignored
            end
        end
        local filter = { character }
        for _, object in ipairs(ignored or {}) do
            if typeof(object) == 'Instance' then
                filter[#filter + 1] = object
            end
        end
        for _, player in ipairs(Players:GetPlayers()) do
            local body = player.Character
            local flight = body and body:FindFirstChild('BatmanFlight')
            if
                body
                and (
                    body:GetAttribute('AdminInvisible') == true
                    or body:GetAttribute('BatmanFlight') == true
                        and flight
                        and flight:GetAttribute('HumanoidFlight') ~= true
                )
            then
                filter[#filter + 1] = body
            end
        end
        local params = RaycastParams.new()
        params.FilterType = Enum.RaycastFilterType.Exclude
        params.FilterDescendantsInstances = filter
        params.IgnoreWater = true
        local direction = delta.Unit * packet.Range
        local result = Workspace:Raycast(packet.ForcedOrigin, direction, params)
        return packet.ForcedOrigin,
            result and result.Position or packet.ForcedOrigin + direction,
            result and result.Instance,
            result and result.Normal or Vector3.new(0, 1, 0)
    end
    function phowg:get_gun_shot_target()
        local function enabled(name)
            return Toggles[name] and Toggles[name].Value
        end
        local function active(owner)
            if owner == 'Ragebot' then
                local gun = phowg:auto_kill_gun_mode()
                return phowg:ragebot_action_enabled('auto_kill')
                    and (rageboton() or Data.PunishmentGunActive)
                    and phowg:is_gun_weapon(gun)
            end
            if owner == 'Support' then
                return phowg:israel_support_enabled() and enabled('full_rage') and not Data.PunishmentGunActive
            end
            if owner == 'KillAura' then
                return killauraenabled() and not killaurabusy()
            end
            if owner == 'SilentAim' then
                return enabled('silent_aim_enabled')
                    and Options.silent_aim_keybind
                    and Options.silent_aim_keybind:GetState()
            end
            if owner == 'AimAssist' then
                return enabled('aim_assist_enabled')
                    and enabled('aim_assist_include_silent')
                    and Options.aim_assist_key
                    and Options.aim_assist_key:GetState()
            end
            if owner == 'StickyAim' then
                return enabled('sticky_aim_enabled')
            end
            return false
        end
        local function valid(target, owner, character)
            if
                not target
                or target == LocalPlayer
                or not target.Parent
                or not target.Character
                or (character and target.Character ~= character)
            then
                return false
            end
            if owner == 'Ragebot' and phowg:target_search_active()
                and (not phowg:target_search_engaged() or target ~= Data.TargetSearch.Target) then
                return false
            end
            if
                owner == 'Ragebot'
                and phowg:auto_bounty_enabled()
                and not Data.PunishmentGunActive
                and not phowg:auto_bounty_target_allowed(target)
            then
                return false
            end
            if owner == 'KillAura' and not killauravalidtarget(target) then
                return false
            end
            if phowg:is_sticky_aim_source(target, owner) then
                return is_sticky_valid(target)
            end
            if
                isdead(target)
                or iscrewwhitelisted(target)
                or iswhitelistedplayer(target)
                or (Data.RageWhitelist and Data.RageWhitelist[target])
            then
                return false
            end
            if owner == 'Support' or owner == 'Ragebot' or owner == 'KillAura' then
                if isknocked(target) or (Data.SupportCompletedTargets and Data.SupportCompletedTargets[target]) then
                    return false
                end
                if target.Character:FindFirstChild('GRABBING_CONSTRAINT') then
                    return false
                end
            end
            return true
        end
        local held = Data.HeldGunFire
        if held and (held.Owner == 'Ragebot' or held.Owner == 'Support' or held.Owner == 'KillAura') then
            if
                held.Character ~= LocalPlayer.Character
                or not held.Tool
                or held.Tool.Parent ~= held.Character
                or not active(held.Owner)
                or not valid(held.Target, held.Owner, held.TargetCharacter)
            then
                return nil
            end
            return held.Target, nil, nil, held.Owner
        end
        if (phowg:target_search_active() or phowg:auto_bounty_enabled()) and not Data.PunishmentGunActive then
            local target = Data.CurrentActionTarget or Data.RifleTarget
            if active('Ragebot') and valid(target, 'Ragebot') then
                return target, nil, nil, 'Ragebot'
            end
            if Data.RagebotTicking or Data.RagebotArrival then
                return nil
            end
        end
        if active('Ragebot') and valid(Data.RifleTarget, 'Ragebot') then
            return Data.RifleTarget, nil, nil, 'Ragebot'
        end
        if active('Support') and valid(Data.RapeTarget, 'Support') then
            return Data.RapeTarget, nil, nil, 'Support'
        end
        if active('KillAura') and valid(Data.KillAuraTarget, 'KillAura') then
            return Data.KillAuraTarget, nil, nil, 'KillAura'
        end
        if active('SilentAim') and Data.SilentAimPos and valid(Data.SilentAimTarget, 'SilentAim') then
            return Data.SilentAimTarget, Data.SilentAimPos, Data.SilentAimHitPart, 'SilentAim'
        end
        if active('AimAssist') and valid(Data.AssistLockedTarget, 'AimAssist') then
            return Data.AssistLockedTarget, Data.AssistAimPos, Data.AssistAimPart, 'AimAssist'
        end
        if active('StickyAim') then
            local target = get_sticky_target()
            if valid(target, 'StickyAim') then
                return target, nil, nil, 'StickyAim'
            end
        end
        return nil
    end
    task.defer(function()
        local ok, GunHandler = pcall(function()
            local mods = ReplicatedStorage:WaitForChild('Modules', 5)
            local module = mods and (mods:FindFirstChild('GunHandler') or mods:WaitForChild('GunHandler', 5))
            return module and require(module)
        end)
        if Library.Unloaded or Data.SharedSignalsClosed then
            return
        end
        if ok and type(GunHandler) == 'table' and type(GunHandler.shoot) == 'function' then
            local OriginalShoot, OriginalAim = GunHandler.shoot, GunHandler.getAim
            Data.NativeGunAim, Data.NativeGunShoot = OriginalAim, OriginalShoot
            Data.NativeShotgunSpread = GunHandler.shotgunSpread
            local aimContexts = setmetatable({}, { __mode = 'k' })
            local forceAimContexts = setmetatable({}, { __mode = 'k' })
            local redirectAimContexts = setmetatable({}, { __mode = 'k' })
            Data.RedirectGunShots = setmetatable({}, { __mode = 'k' })
            local aimReplacement
            if type(OriginalAim) == 'function' then
                aimReplacement = LPH_NO_VIRTUALIZE(function(origin, range, ...)
                    if Library.Unloaded or Data.SharedSignalsClosed then return OriginalAim(origin, range, ...) end
                    local thread = coroutine.running()
                    local context = aimContexts[thread]
                    if context then
                        if not context.Bypass and not Library.Unloaded and context.Shooter == LocalPlayer.Character then
                            local delta = context.AimPosition - context.ForcedOrigin
                            if delta.Magnitude > 0.001 then
                                return delta.Unit,
                                    context.Distance or math.min(delta.Magnitude, phowg:redirect_range(range))
                            end
                        end
                        return OriginalAim(origin, range, ...)
                    end
                    forceAimContexts[thread] = nil
                    if phowg.perfect_hit_mode and phowg:perfect_hit_mode() and phowg.perfect_hit_aim then
                        local aimAt = Data.Performance and Data.Performance.Enabled and os.clock()
                        local aimed, direction, distance, shot = pcall(phowg_callbacks.perfect_hit_aim, origin)
                        if aimAt then
                            phowg:record_performance('gun/aim solution', os.clock() - aimAt)
                        end
                        if aimed and direction then
                            forceAimContexts[thread] = shot
                            return direction, distance
                        end
                    end
                    local target, position, part, source = phowg:get_gun_shot_target()
                    redirectAimContexts[thread] = nil
                    if
                        not Library.Unloaded
                        and not Data.SharedSignalsClosed
                        and target
                        and phowg:gun_shoot_method(source, target) == 'shoot redirect'
                    then
                        local packet: { [string]: any } =
                            { Shooter = LocalPlayer.Character, ForcedOrigin = origin, Range = range }
                        local success, redirected, prepared =
                            pcall(applysilentredir, packet, target, position, part, source)
                        if success and redirected then
                            local delta = packet.AimPosition - origin
                            redirectAimContexts[thread] = prepared
                            return delta.Unit, math.min(delta.Magnitude, phowg:redirect_range(range))
                        end
                        redirectAimContexts[thread] = {
                            Target = target,
                            TargetCharacter = target.Character,
                            Shooter = LocalPlayer.Character,
                            Source = source,
                            At = tick(),
                            Bypass = true,
                        }
                    end
                    return OriginalAim(origin, phowg:redirect_range(range), ...)
                end)
                GunHandler.getAim = aimReplacement
            end
            local function call_native(ShootData, context, ...)
                local thread = coroutine.running()
                local previous = aimContexts[thread]
                local previousSkin = Data.NativeSkinRendering
                local cosmeticsAt = Data.Performance and Data.Performance.Enabled and os.clock()
                local prepared, skinState = pcall(phowg_callbacks.prepare_native_gun_skin, ShootData)
                if cosmeticsAt then
                    phowg:record_performance('gun/cosmetics', os.clock() - cosmeticsAt)
                end
                if not prepared then
                    skinState = nil
                end
                aimContexts[thread] = context
                context.Rendering = true
                context.SkinTracer = type(ShootData) == 'table'
                        and ShootData.Shooter == LocalPlayer.Character
                        and phowg:use_skin_tracer(ShootData.Handle, ShootData)
                    or false
                Data.NativeSkinRendering = context
                local nativeAt = Data.Performance and Data.Performance.Enabled and os.clock()
                local results = table.pack(pcall(OriginalShoot, ShootData, ...))
                if nativeAt then
                    phowg:record_performance('gun/native shot', os.clock() - nativeAt)
                end
                phowg:restore_native_gun_skin(skinState)
                aimContexts[thread] = previous
                context.Rendering = false
                if Data.NativeSkinRendering == context then
                    Data.NativeSkinRendering = previousSkin and previousSkin.Rendering and previousSkin or nil
                end
                if not results[1] then
                    error(results[2], 0)
                end
                return results
            end
            local replacement = LPH_NO_VIRTUALIZE(function(ShootData, ...)
                if Library.Unloaded or Data.SharedSignalsClosed then return OriginalShoot(ShootData, ...) end
                if
                    not Library.Unloaded
                    and not Data.SharedSignalsClosed
                    and type(ShootData) == 'table'
                    and LocalPlayer.Character
                    and ShootData.Shooter == LocalPlayer.Character
                    and (localshootblocked() or phowg:sticky_shot_blocked())
                then
                    return
                end
                if
                    Library.Unloaded
                    or Data.SharedSignalsClosed
                    or Data.GunRedirecting
                    or localactionblocked()
                    or type(ShootData) ~= 'table'
                    or not LocalPlayer.Character
                    or ShootData.Shooter ~= LocalPlayer.Character
                    or ShootData.ReplicatedShot
                    or ShootData.IsLeftHand
                    or ShootData.isReflecting
                    or ShootData.TrailOnly
                then
                    if not Library.Unloaded and not Data.SharedSignalsClosed and not localactionblocked() then
                        phowg:rebase_gun_origin(ShootData)
                    end
                    local results = call_native(ShootData, { Bypass = true }, ...)
                    return table.unpack(results, 2, results.n)
                end
                phowg:record_strafe_muzzle(ShootData)
                Data.RecentlyShotAt = tick()
                local capturedBefore = Data.BulletCaptureSerial or 0
                local target, pos, part, source = phowg:get_gun_shot_target()
                local perfectHit = phowg.perfect_hit_mode and phowg:perfect_hit_mode() and Data.PerfectHitHookReady
                local redirectedShot, forceShot = false, nil
                local thread = coroutine.running()
                if perfectHit then
                    local shot = forceAimContexts[thread]
                    if
                        shot
                        and shot.Character == ShootData.Shooter
                        and shot.Tool
                        and shot.Tool.Parent == shot.Character
                        and ShootData.Handle
                        and ShootData.Handle.Parent == shot.Tool
                        and shot.Target == target
                        and shot.Source == source
                        and shot.Target.Character == shot.TargetCharacter
                        and tick() - shot.At >= 0
                        and tick() - shot.At <= 0.15
                        and typeof(ShootData.ForcedOrigin) == 'Vector3'
                        and typeof(ShootData.AimPosition) == 'Vector3'
                        and (ShootData.ForcedOrigin - shot.NativeOrigin).Magnitude < 0.05
                    then
                        if shot.Origin ~= ShootData.ForcedOrigin then
                            ShootData.AimPosition = ShootData.AimPosition + (shot.Origin - ShootData.ForcedOrigin)
                            ShootData.ForcedOrigin = shot.Origin
                        end
                        forceShot, redirectedShot = shot, true
                    end
                elseif target then
                    Data.GunRedirecting = true
                    local prepared = redirectAimContexts[thread]
                    redirectAimContexts[thread] = nil
                    local redirected, result = pcall(applysilentredir, ShootData, target, pos, part, source, prepared)
                    Data.GunRedirecting = nil
                    if redirected and result then
                        redirectedShot = typeof(ShootData.ForcedOrigin) == 'Vector3'
                            and typeof(ShootData.AimPosition) == 'Vector3'
                    elseif not redirected and tick() - (Data.GunRedirectErrorAt or -math.huge) >= 5 then
                        Data.GunRedirectErrorAt = tick()
                        warn('[Phowg] gun target redirect failed: ' .. tostring(result))
                    end
                end
                local movedOrigin = not redirectedShot and phowg:rebase_gun_origin(ShootData)
                Data.RedirectGunShots[thread] = nil
                local context = redirectedShot
                        and {
                            Shooter = ShootData.Shooter,
                            AimPosition = ShootData.AimPosition,
                            ForcedOrigin = ShootData.ForcedOrigin,
                            Distance = forceShot and forceShot.Distance,
                        }
                    or { Bypass = true }
                local results = call_native(ShootData, context, ...)
                if
                    (redirectedShot or movedOrigin)
                    and Data.RedirectGunShots
                    and typeof(results[2]) == 'Vector3'
                    and typeof(ShootData.Handle) == 'Instance'
                then
                    Data.RedirectGunShots[thread] = {
                        Handle = ShootData.Handle,
                        Origin = ShootData.ForcedOrigin,
                        Point = results[2],
                        Hit = results[3],
                        At = tick(),
                        Character = ShootData.Shooter,
                        Target = target,
                        TargetCharacter = target and target.Character,
                        Source = source,
                    }
                end
                if perfectHit then
                    Data.PerfectHitLastResult = 'native_returned'
                end
                if phowg.capture_bullet_shot and (Data.BulletCaptureSerial or 0) == capturedBefore then
                    pcall(
                        phowg_callbacks.capture_bullet_shot,
                        ShootData.Handle,
                        ShootData.ForcedOrigin or ShootData.Origin,
                        results[2] or ShootData.AimPosition or ShootData.Position
                    )
                end
                return table.unpack(results, 2, results.n)
            end)
            GunHandler.shoot = replacement
            Data.NativeGunHandlerReady = aimReplacement ~= nil
            if phowg.update_bullet_capture then
                phowg:update_bullet_capture()
            end
            phowg:register_cleanup('gun handler', function(scope, reason)
                if not scope or scope == LocalPlayer.Character or scope == Data.ManagedCharacter then
                    table.clear(aimContexts)
                    table.clear(forceAimContexts)
                    table.clear(redirectAimContexts)
                    if Data.RedirectGunShots then
                        table.clear(Data.RedirectGunShots)
                    end
                end
                if reason ~= 'unload' then
                    return
                end
                if GunHandler.shoot == replacement then
                    GunHandler.shoot = OriginalShoot
                end
                if aimReplacement and GunHandler.getAim == aimReplacement then
                    GunHandler.getAim = OriginalAim
                end
                Data.GunRedirecting, Data.RedirectGunShots, Data.NativeGunHandlerReady, Data.PerfectHitHookReady, Data.NativeSkinRendering, Data.NativeGunAim, Data.NativeShotgunSpread, Data.NativeGunShoot =
                    nil, nil, nil, nil, nil, nil, nil, nil
            end)
        else
            warn('[Phowg] GunHandler not found - silent aim fallback to Tool.Activated')
        end
    end)
    Data['SilentFOVCircle'] = SilentFOVCircle
    local StickyFOVCircle = Drawing and Drawing.new and Drawing.new('Circle') or nil
    if StickyFOVCircle then
        StickyFOVCircle.Thickness = 1
        StickyFOVCircle.Transparency = 1
        StickyFOVCircle.Filled = false
        StickyFOVCircle.NumSides = 64
        StickyFOVCircle.Visible = false
        StickyFOVCircle.ZIndex = 2
    end
    Data['StickyFOVCircle'] = StickyFOVCircle
    Data['StickyAimWatchlist'] = Data['StickyAimWatchlist'] or {}
    function Data.RebuildAimDrawings()
        pcall(function()
            if SilentFOVCircle and SilentFOVCircle.Remove then
                SilentFOVCircle:Remove()
            end
        end)
        pcall(function()
            if StickyFOVCircle and StickyFOVCircle.Remove then
                StickyFOVCircle:Remove()
            end
        end)
        SilentFOVCircle = nil
        StickyFOVCircle = nil
        Data['SilentFOVCircle'] = nil
        Data['StickyFOVCircle'] = nil
        Data['SilentFOVAt'] = nil
    end
    Data['StickyAimKeyPrev'] = false
    local function do_sticky_aim()
        local toggleOn = Toggles.sticky_aim_enabled and Toggles.sticky_aim_enabled.Value
        if not toggleOn then
            if Data['StickyTarget'] ~= nil then
                clear_sticky_target('toggle off')
            end
            Data['StickyAimKeyPrev'] = false
            pcall(function()
                if StickyFOVCircle then
                    StickyFOVCircle.Visible = false
                end
            end)
            for _, Line in pairs(Data['StickyFOVRing'] or {}) do
                pcall(function()
                    if Line then
                        Line.Visible = false
                    end
                end)
            end
            return
        end
        if UserInputService:GetFocusedTextBox() then
            Data.StickyAimTyping = true
            return
        end
        if Data.StickyAimTyping then
            Data.StickyAimTyping = nil
            Data.StickyAimKeyPrev = Options.sticky_aim_key and Options.sticky_aim_key:GetState() or false
            return
        end
        StickyFOVCircle = (alivedrawing(StickyFOVCircle) and StickyFOVCircle) or newdrawingcircle()
        local cam = Workspace.CurrentCamera
        if not cam then
            return
        end
        local mousePos = UserInputService:GetMouseLocation()
        local stickyFov = (Options.sticky_aim_fov and Options.sticky_aim_fov.Value) or 150
        local stickyFovCol = (Options.sticky_aim_fov_color and Options.sticky_aim_fov_color.Value)
            or Color3.fromRGB(255, 255, 255)
        local stickyFovShow = ((Toggles.sticky_aim_show_fov and Toggles.sticky_aim_show_fov.Value) and toggleOn)
            or false
        if circleworks() and StickyFOVCircle then
            StickyFOVCircle.Position = mousePos
            StickyFOVCircle.Radius = stickyFov
            StickyFOVCircle.Color = stickyFovCol
            StickyFOVCircle.Visible = stickyFovShow
        else
            if StickyFOVCircle then
                StickyFOVCircle.Visible = false
            end
            updatefovring('StickyFOVRing', mousePos, stickyFov, stickyFovCol, stickyFovShow)
        end
        if Data['SilentAimStickyTargets'] == nil then
            Data['SilentAimStickyTargets'] = {}
        end
        local cur = get_sticky_target()
        if cur then
            Data['SilentAimStickyTargets'][cur] = true
            Data['SilentAimStickyTarget'] = cur
            local ch = cur.Character
            if ch ~= Data['StickyChar'] then
                Data['StickyChar'] = ch
                Data['StickyRepTarget'] = nil
                if Data['FrozenRoots'] and Data['FrozenRoots'][cur] then
                    local _fr = Data['FrozenRoots'][cur]
                    if not (_fr and _fr.Parent) then
                        Data['FrozenRoots'][cur] = nil
                    end
                end
                Data['TargetListCache'] = nil
            end
        end
        if Data['SilentAimStickyTargets'] == nil then
            Data['SilentAimStickyTargets'] = {}
        end
        for plr, _ in pairs(Data['SilentAimStickyTargets']) do
            if not is_sticky_valid(plr) then
                Data['SilentAimStickyTargets'][plr] = nil
            end
        end
        local stickyKey = false
        stickyKey = Options.sticky_aim_key and Options.sticky_aim_key:GetState()
        local isToggle = Options.sticky_aim_key and Options.sticky_aim_key.Mode == 'Toggle'
        local pressedEvent = isToggle and stickyKey ~= Data.StickyAimKeyPrev
            or not isToggle and stickyKey and not Data.StickyAimKeyPrev
        Data.StickyAimKeyPrev = stickyKey
        if not pressedEvent then
            return
        end
        if get_sticky_target() then
            clear_sticky_target('manual unlock')
            return
        end
        local fov = (Options.sticky_aim_fov and Options.sticky_aim_fov.Value) or 150
        local useFov = Toggles.sticky_aim_use_fov and Toggles.sticky_aim_use_fov.Value
        local dis = (Options.sticky_aim_disablers and Options.sticky_aim_disablers.Value) or {}
        local best = nil
        local bestDist = 9e9
        local stickyParams = RaycastParams.new()
        stickyParams.FilterType = Enum.RaycastFilterType.Blacklist
        for _, plr in ipairs(phowg:aim_candidates(true)) do
            if is_sticky_valid(plr) and phowg:sticky_checks_pass(plr) and phowg:sticky_character(plr) then
                local head = plr.Character:FindFirstChild('Head')
                if head then
                    local sp, on = cam:WorldToViewportPoint(head.Position)
                    if on then
                        local dist = (Vector2.new(sp.X, sp.Y) - mousePos).Magnitude
                        if not useFov or dist <= fov then
                            local blocked = false
                            if dis['outside of fov'] and useFov and dist > fov then
                                blocked = true
                            end
                            if
                                not blocked
                                and dis['behind wall']
                                and Toggles.sticky_aim_visible_check
                                and Toggles.sticky_aim_visible_check.Value
                            then
                                stickyParams.FilterDescendantsInstances = { LocalPlayer.Character, plr.Character }
                                local res = Workspace:Raycast(
                                    cam.CFrame.Position,
                                    (head.Position - cam.CFrame.Position),
                                    stickyParams
                                )
                                if res and res.Instance and not res.Instance:IsDescendantOf(plr.Character) then
                                    blocked = true
                                end
                            end
                            if not blocked and dist < bestDist then
                                bestDist = dist
                                best = plr
                            end
                        end
                    end
                end
            end
        end
        if best then
            set_sticky_target(best)
        end
    end
    registerheartbeat('StickyAim', do_sticky_aim)
end
do
    local flagNames = { 'SDeath', 'SDead', 'Dead', 'K.O', 'KO' }
    local function client_position(character)
        local root = character and character:FindFirstChild('HumanoidRootPart')
        if not root then
            return nil
        end
        local cf = Data['CSyncTable'][2] and Data['CSyncTable'][1] or root.CFrame
        if typeof(cf) ~= 'CFrame' then
            return nil
        end
        local position = cf.Position
        if position.Magnitude >= 50000 or position.Y <= -1000 or position.Y >= 20000 then
            return nil
        end
        if position.X ~= position.X or position.Y ~= position.Y or position.Z ~= position.Z then
            return nil
        end
        return cf
    end
    local function save_death_position(character)
        if
            LocalPlayer.Character ~= character or not (Toggles.flashback_enabled and Toggles.flashback_enabled.Value)
        then
            return
        end
        if Data['FlashbackDeathCharacter'] == character then
            return
        end
        local cf = client_position(character)
        if not cf and Data['FlashbackLastAliveCharacter'] == character then
            cf = Data['FlashbackLastAliveCF']
        end
        if not cf then
            return
        end
        Data['FlashbackDeathPos'] = cf
        Data['FlashbackDeathCharacter'] = character
    end
    local function hook_death(character)
        if not character then
            return
        end
        for _, name in ipairs(flagNames) do
            local connection = Connections['FlashbackFlag_' .. name]
            if connection then
                connection:Disconnect()
                Connections['FlashbackFlag_' .. name] = nil
            end
        end
        for _, name in ipairs({ 'FlashbackEffectsAdded', 'FlashbackCharacterAdded', 'FlashbackHumanoidDied' }) do
            local connection = Connections[name]
            if connection then
                connection:Disconnect()
                Connections[name] = nil
            end
        end
        Data['FlashbackLastAliveCF'] = nil
        Data['FlashbackLastAliveCharacter'] = character
        Data['FlashbackReadyCharacter'] = nil
        local function bind_flag(value)
            if not table.find(flagNames, value.Name) or not value:IsA('BoolValue') then
                return
            end
            create_connection(
                'FlashbackFlag_' .. value.Name,
                connectshared(value:GetPropertyChangedSignal('Value'), function()
                    if value.Value then
                        save_death_position(character)
                    end
                end, value, 'event/value:GetPropertyChangedSignal(Value)', 0, 'property/Value', value)
            )
            if value.Value then
                save_death_position(character)
            end
        end
        local function bind_child(child)
            if LocalPlayer.Character ~= character then
                return
            end
            if child:IsA('Humanoid') then
                create_connection(
                    'FlashbackHumanoidDied',
                    connectshared(child.Died, function()
                        save_death_position(character)
                    end, child, 'event/child.Died', 0, 'event/Died', child)
                )
            elseif child.Name == 'BodyEffects' then
                create_connection(
                    'FlashbackEffectsAdded',
                    connectshared(
                        child.ChildAdded,
                        bind_flag,
                        child,
                        'event/child.ChildAdded',
                        0,
                        'event/ChildAdded',
                        child
                    )
                )
                for _, value in ipairs(child:GetChildren()) do
                    bind_flag(value)
                end
            end
        end
        create_connection(
            'FlashbackCharacterAdded',
            connectshared(
                character.ChildAdded,
                bind_child,
                character,
                'event/character.ChildAdded',
                0,
                'event/ChildAdded',
                character
            )
        )
        for _, child in ipairs(character:GetChildren()) do
            bind_child(child)
        end
    end
    create_connection(
        'FlashbackPlayerCharacterAdded',
        connectshared(
            LocalPlayer.CharacterAdded,
            hook_death,
            LocalPlayer,
            'event/LocalPlayer.CharacterAdded',
            0,
            'event/CharacterAdded',
            LocalPlayer
        )
    )
    if LocalPlayer.Character then
        hook_death(LocalPlayer.Character)
    end
    registerheartbeat('Flashback', function()
        if not (Toggles.flashback_enabled and Toggles.flashback_enabled.Value) then
            Data['FlashbackDeathPos'] = nil
            Data['FlashbackDeathCharacter'] = nil
            Data['FlashbackLastAliveCF'] = nil
            return
        end
        local character = LocalPlayer.Character
        local humanoid = character and character:FindFirstChildOfClass('Humanoid')
        if not character or not humanoid then
            return
        end
        local effects = character:FindFirstChild('BodyEffects')
        local dead = humanoid.Health <= 0
        if effects then
            for _, name in ipairs(flagNames) do
                local value = effects:FindFirstChild(name)
                if value and value.Value == true then
                    dead = true
                    break
                end
            end
        end
        if dead then
            save_death_position(character)
            return
        end
        if localactionblocked() then
            return
        end
        local destination = Data['FlashbackDeathPos']
        if destination and Data['FlashbackDeathCharacter'] ~= character then
            if Data['FlashbackReadyCharacter'] ~= character then
                return
            end
            if not restoreflashback(character) then
                return
            end
        elseif Data['FlashbackDeathCharacter'] == character then
            Data['FlashbackDeathPos'] = nil
            Data['FlashbackDeathCharacter'] = nil
        end
        local cf = client_position(character)
        if cf then
            Data['FlashbackLastAliveCF'] = cf
            Data['FlashbackLastAliveCharacter'] = character
        end
    end)
end
do
    for _, option in ipairs({ Options.auto_kill_weapon, Options.kill_aura_weapon }) do
        local setValue = option.SetValue
        function option:SetValue(value, silent)
            if self == Options.auto_kill_weapon then
                if Library.ConfigLoading and type(value) == 'table' then
                    Data.RagebotConfigGuns = table.clone(value)
                end
                local multi = Options.gun_shoot_method and Options.gun_shoot_method.Value == 'china hack'
                    and not phowg:ragebot_melee_weapon(value) or false
                if self.SetMulti then
                    self:SetMulti(multi, phowg:ragebot_gun_value(value, multi))
                end
                return setValue(self, phowg:ragebot_gun_value(value, multi), silent)
            end
            if type(value) == 'string' and Data.GunWeaponKeys[normalizeweaponname(value)] then
                value = normalizeweaponname(value)
            end
            if
                type(value) == 'string'
                and not Data.GunWeaponKeys[normalizeweaponname(value)]
                and (normalizeweaponname(value) == 'flamethrower' or normalizeweaponname(value) == 'flame')
            then
                value = self == Options.auto_kill_weapon and 'knife' or 'aug'
            end
            return setValue(self, value, silent)
        end
    end
end
function phowg:ui_visible(object)
    while object do
        if object:IsA('GuiObject') and not object.Visible then
            return false
        end
        if object:IsA('ScreenGui') and not object.Enabled then
            return false
        end
        object = object.Parent
    end
    return true
end
function phowg:create_navigation_hud()
    if Data.NavigationGui and Data.NavigationGui.Parent then
        return
    end
    local gui = Instance.new('ScreenGui')
    gui.Name, gui.IgnoreGuiInset, gui.ResetOnSpawn, gui.DisplayOrder = 'PhowgNavigation', true, false, 9800
    local parent = CoreGui
    if gethui then
        local ok, hidden = pcall(gethui)
        if ok and typeof(hidden) == 'Instance' then
            parent = hidden
        end
    end
    local ok = pcall(function()
        gui.Parent = parent
    end)
    if not ok or not gui.Parent then
        gui.Parent = LocalPlayer:FindFirstChildOfClass('PlayerGui')
    end
    if not gui.Parent then
        gui:Destroy()
        return
    end
    Data.NavigationGui, Data.NavigationMarkers, Data.NavigationPresent = gui, {}, {}
    Data.NavigationRoster, Data.NavigationRosterDirty = Players:GetPlayers(), false
    local function roster_changed()
        Data.NavigationRosterDirty = true
    end
    Data.NavigationConnections = {
        connectshared(
            Players.PlayerAdded,
            roster_changed,
            Players,
            'navigation/player added',
            0,
            'event/PlayerAdded',
            Players
        ),
        connectshared(
            Players.PlayerRemoving,
            roster_changed,
            Players,
            'navigation/player removed',
            0,
            'event/PlayerRemoving',
            Players
        ),
    }
end
function phowg:clear_navigation_hud()
    for _, marker in pairs(Data.NavigationMarkers or {}) do
        phowg:release_visual(marker)
    end
    for _, connection in pairs(Data.NavigationConnections or {}) do
        connection:Disconnect()
    end
    if Data.NavigationGui then
        Data.NavigationGui:Destroy()
    end
    Data.NavigationGui, Data.NavigationMarkers, Data.NavigationRoster, Data.NavigationPresent = nil, nil, nil, nil
    Data.NavigationConnections, Data.NavigationRosterDirty = nil, nil
end
function phowg:navigation_allowed(player, filter, target)
    if filter == 'current target' then
        return player == target
    end
    if filter == 'exclude whitelisted' then
        return not iswhitelistedplayer(player)
            and not iscrewwhitelisted(player)
            and not (Data.RageWhitelist and Data.RageWhitelist[player])
    end
    if filter == 'exclude crew' then
        local crew = getplayercrewid(LocalPlayer)
        return not crew or getplayercrewid(player) ~= crew
    end
    return true
end
function phowg:update_navigation_hud()
    if not Toggles.offscreen_arrows or not Toggles.offscreen_arrows.Value then
        if Data.NavigationGui then
            phowg:clear_navigation_hud()
        end
        return
    end
    local camera, character = Workspace.CurrentCamera, LocalPlayer.Character
    local root = character and character:FindFirstChild('HumanoidRootPart')
    if not camera or not root or Data.IsRespawning then
        if Data.NavigationGui then
            Data.NavigationGui.Enabled = false
            for _, marker in pairs(Data.NavigationMarkers or {}) do
                phowg:release_visual(marker)
            end
        end
        return
    end
    phowg:create_navigation_hud()
    if not Data.NavigationGui then
        return
    end
    if Data.NavigationRosterDirty then
        Data.NavigationRoster, Data.NavigationRosterDirty = Players:GetPlayers(), false
    end
    local _, opacity = phowg:hud_settings()
    local center, half = camera.ViewportSize * 0.5, camera.ViewportSize * 0.5
    local record = phowg:get_active_target()
    local target = record and record.Player
    local arrowRange = phowg:visual_number('offscreen_distance', 500, 25, 2500)
    local origin = typeof(Data.CSyncTable[1]) == 'CFrame' and Data.CSyncTable[2] and Data.CSyncTable[1].Position
        or root.Position
    local filter = Options.offscreen_filter and Options.offscreen_filter.Value
    local padding = phowg:visual_number('offscreen_padding', 40, 24, 120)
    local showName = not Toggles.offscreen_names or Toggles.offscreen_names.Value
    local normalColor = Options.navigation_color and Options.navigation_color.Value or Library.AccentColor
    local targetColor = Options.player_esp_target_color_value and Options.player_esp_target_color_value.Value
        or Color3.fromRGB(255, 90, 90)
    local present = Data.NavigationPresent
    table.clear(present)
    local function set(object, key, value)
        if object[key] ~= value then
            object[key] = value
        end
    end
    for _, player in ipairs(Data.NavigationRoster) do
        if player ~= LocalPlayer and player.Parent then
            present[player] = true
            local char = player.Character
            local targetRoot, humanoid =
                char and char:FindFirstChild('HumanoidRootPart'), char and char:FindFirstChildOfClass('Humanoid')
            local point, onScreen, distance
            if targetRoot and humanoid and humanoid.Health > 0 then
                distance = (targetRoot.Position - origin).Magnitude
                if distance <= arrowRange and phowg:navigation_allowed(player, filter, target) then
                    point, onScreen = camera:WorldToViewportPoint(targetRoot.Position)
                end
            end
            local arrowOn = point and not onScreen
            local marker = Data.NavigationMarkers[player]
            if arrowOn and not marker then
                local arrow = Instance.new('TextLabel')
                arrow.AnchorPoint, arrow.Size, arrow.BackgroundTransparency, arrow.Text, arrow.Font, arrow.TextSize, arrow.TextStrokeTransparency, arrow.Parent =
                    Vector2.new(0.5, 0.5),
                    UDim2.fromOffset(24, 24),
                    1,
                    'Ã¢â€“Â²',
                    Enum.Font.Code,
                    24,
                    0,
                    Data.NavigationGui
                local text = Instance.new('TextLabel')
                text.AnchorPoint, text.Size, text.BackgroundTransparency, text.Font, text.TextSize, text.TextStrokeTransparency, text.Parent =
                    Vector2.new(0.5, 0.5), UDim2.fromOffset(140, 30), 1, Enum.Font.Code, 11, 0, Data.NavigationGui
                marker = { Arrow = arrow, Text = text }
                Data.NavigationMarkers[player] = marker
            end
            if marker then
                if arrowOn and not phowg:acquire_visual(marker, 2, 'navigation') then
                    arrowOn = false
                end
                if not arrowOn then
                    phowg:release_visual(marker)
                end
                set(marker.Arrow, 'Visible', arrowOn == true)
                set(marker.Text, 'Visible', arrowOn == true)
                if arrowOn then
                    local color = player == target and targetColor or normalColor
                    set(marker.Arrow, 'TextColor3', color)
                    set(marker.Text, 'TextColor3', color)
                    set(marker.Arrow, 'TextTransparency', 1 - opacity)
                    set(marker.Text, 'TextTransparency', 1 - opacity)
                    set(marker.Arrow, 'TextStrokeTransparency', 1 - opacity)
                    set(marker.Text, 'TextStrokeTransparency', 1 - opacity)
                    local direction = Vector2.new(point.X - center.X, point.Y - center.Y)
                    if point.Z < 0 then
                        direction = direction * -1
                    end
                    if direction.Magnitude < 0.001 then
                        direction = Vector2.new(0, 1)
                    end
                    local factor = math.min(
                        math.max(10, half.X - padding) / math.max(0.001, math.abs(direction.X)),
                        math.max(10, half.Y - padding) / math.max(0.001, math.abs(direction.Y))
                    )
                    local p = center + direction * factor
                    set(marker.Arrow, 'Position', UDim2.fromOffset(p.X, p.Y))
                    set(marker.Arrow, 'Rotation', math.deg(math.atan2(direction.Y, direction.X)) + 90)
                    local labelPosition = phowg:clamp_hud(Vector2.new(p.X - 70, p.Y + 14), Vector2.new(140, 30))
                    set(marker.Text, 'Position', UDim2.fromOffset(labelPosition.X + 70, labelPosition.Y + 15))
                    set(
                        marker.Text,
                        'Text',
                        (showName and (player.DisplayName .. '\n') or '') .. math.floor(distance) .. 'm'
                    )
                end
            end
        end
    end
    for player, marker in pairs(Data.NavigationMarkers) do
        if not present[player] then
            phowg:release_visual(marker)
            marker.Arrow:Destroy()
            marker.Text:Destroy()
            Data.NavigationMarkers[player] = nil
        end
    end
    Data.NavigationGui.Enabled = true
end
