function phowg:update_interface_watermark()
    if Library.Unloaded or not Toggles.ui_watermark.Value then
        return
    end
    local selected = Options.ui_watermark_fields.Value
    local parts = { 'phowg host' }
    if selected.date then
        parts[#parts + 1] = os.date('%b %d %Y')
    end
    if selected.game then
        parts[#parts + 1] = Library:GetGameName()
    end
    if selected.time then
        parts[#parts + 1] = os.date('%H:%M:%S')
    end
    if selected.fps then
        parts[#parts + 1] = tostring(math.round(Library.IndicatorFPS or 0)) .. ' fps'
    end
    if selected.ping then
        local ok, ping = pcall(LocalPlayer.GetNetworkPing, LocalPlayer)
        if ok and type(ping) == 'number' and ping == ping and ping >= 0 and ping < math.huge then
            parts[#parts + 1] = tostring(math.round(ping * 1000)) .. ' ms'
        end
    end
    if selected.username then
        parts[#parts + 1] = LocalPlayer.Name
    end
    if selected.status then
        local status = phowg:display_status():gsub('%c', ''):lower()
        local record = phowg.get_active_target and phowg:get_active_target()
        local target = record and record.Player or Data.CurrentActionTarget
        if status ~= 'void' and target and target.Parent then
            local name = '@' .. target.Name
            if Library.StreamerMode ~= 'Off' then
                name = typeof(target) == 'Instance' and target:IsA('Player') and Library:PlayerDisplayName(target)
                    or 'target'
            end
            status = status .. ' ' .. name
        end
        parts[#parts + 1] = status
    end
    local suffix = tostring(Options.ui_watermark_suffix.Value or ''):match('^%s*(.-)%s*$')
    if suffix ~= '' then
        parts[#parts + 1] = suffix
    end
    local text = table.concat(parts, ' ~ ')
    if Data.WatermarkLastText ~= text then
        Data.WatermarkLastText = text
        Library:SetWatermark(text)
    end
end
