function phowg:movement_status()
    if Data.IsRespawning then
        local flashback = Toggles.flashback_enabled and Toggles.flashback_enabled.Value and Data.FlashbackDeathPos
        return flashback and 'movement: respawning; waiting for flashback'
            or 'movement: respawning; waiting for character'
    end
    if localactionblocked() then
        return 'movement: paused; character unavailable'
    end
    local owner, priority = nil, math.huge
    for key, entry in pairs(Data.MovementOverrides or {}) do
        if entry.character == LocalPlayer.Character and entry.expires > tick() and entry.prio < priority then
            owner, priority = entry.tag or key, entry.prio
        end
    end
    for name, hold in pairs(Data.MoveToHolds or {}) do
        if not hold.Stopped and hold.Character == LocalPlayer.Character and hold.Priority < priority then
            owner, priority = hold.Tag or name, hold.Priority
        end
    end
    if not owner and Data.AppliedServerTag and tick() - (Data.AppliedServerAt or 0) < 0.15 then
        owner = Data.AppliedServerTag
    end
    owner = owner or 'character'
    local paused = {}
    if priority < (Data.PRIO.IDLE or math.huge) or Data.Buying then
        if Data.DesyncActive then
            table.insert(paused, 'desynchronization')
        end
        if Data.UndergroundActive then
            table.insert(paused, 'underground')
        end
        if Data.VoidActive then
            table.insert(paused, 'void')
        end
    end
    local text = 'movement: ' .. tostring(owner)
    if #paused > 0 then
        text ..= '\npaused: ' .. table.concat(paused, ', ') .. '; ' .. tostring(owner) .. ' has priority'
    end
    if Data.Buying then
        text ..= '\n' .. tostring(Data.CurrentStatus or 'buying')
    end
    return text
end
function phowg:performance_top_costs(samples)
    local costs = {}
    for name, sample in pairs(samples) do
        if name:sub(-18) == '/initial execution' and sample.Count > 0 then
            local average = sample.Total / sample.Count
            if #costs < 5 or average > costs[#costs].Average then
                local original = name:sub(1, -19)
                local wall = samples[original]
                local cost = {
                    Name = original,
                    Count = sample.Count,
                    Average = average,
                    Wall = wall and wall.Total / math.max(1, wall.Count) or 0,
                }
                local index = #costs + 1
                for position, previous in ipairs(costs) do
                    if average > previous.Average then
                        index = position
                        break
                    end
                end
                table.insert(costs, index, cost)
                if #costs > 5 then
                    costs[6] = nil
                end
            end
        end
    end
    return costs
end
function phowg:frame_time_quantiles()
    local values = table.clone(Data.Performance.FrameTimes or {})
    if #values == 0 then
        return 0, 0, 0
    end
    table.sort(values)
    return values[math.max(1, math.ceil(#values * 0.5))],
        values[math.max(1, math.ceil(#values * 0.95))],
        values[math.max(1, math.ceil(#values * 0.99))]
end
function phowg:set_diagnostics_property(object, property, value)
    if object[property] ~= value then
        object[property] = value
    end
end
function phowg:audit_connections()
    local audit = {
        Signals = 0,
        Handlers = 0,
        Duplicates = 0,
        Retired = 0,
        Players = #Players:GetPlayers(),
        Labels = {},
        Top = {},
    }
    for _, record in pairs(Data.SharedSignals) do
        audit.Signals += 1
        local callbacks = {}
        for _, entry in ipairs(record.List) do
            if entry.Connected then
                audit.Handlers += 1
                local label = entry.Label or 'event'
                audit.Labels[label] = (audit.Labels[label] or 0) + 1
                if phowg:scope_retired(entry.Owner) then
                    audit.Retired += 1
                end
                if entry.Callback then
                    local owners = callbacks[entry.Callback]
                    if not owners then
                        owners = {}
                        callbacks[entry.Callback] = owners
                    end
                    local owner = entry.Owner or false
                    local labels = owners[owner]
                    if not labels then
                        labels = {}
                        owners[owner] = labels
                    end
                    if labels[label] then
                        audit.Duplicates += 1
                    else
                        labels[label] = true
                    end
                end
            end
        end
    end
    local seen = {}
    audit.LibrarySignals = 0
    for _, connection in ipairs(Library.Signals or {}) do
        if connection.Connected and not seen[connection] then
            seen[connection] = true
            audit.LibrarySignals += 1
        end
    end
    for label, count in pairs(audit.Labels) do
        audit.Top[#audit.Top + 1] = { Label = label, Count = count }
    end
    table.sort(audit.Top, function(a, b)
        return a.Count > b.Count or a.Count == b.Count and a.Label < b.Label
    end)
    local esp = Data.ESPInstance
    if esp and esp.GetDiagnostics then
        audit.ESP = esp:GetDiagnostics()
    end
    Data.ConnectionAudit = audit
    Data.ConnectionAuditAt = tick()
    return audit
end
function phowg:connection_audit_text(audit)
    local lines = {
        string.format(
            'connections: %d signals / %d handlers / %d players',
            audit.Signals,
            audit.Handlers,
            audit.Players
        ),
        string.format(
            'duplicates: %d | retired owners: %d | UI listeners: %d',
            audit.Duplicates,
            audit.Retired,
            audit.LibrarySignals
        ),
    }
    if audit.ESP then
        lines[#lines + 1] = string.format(
            'ESP: %d listeners / %d tracked characters',
            audit.ESP.Connections or 0,
            audit.ESP.Tracked or 0
        )
    end
    for index = 1, math.min(4, #audit.Top) do
        local item = audit.Top[index]
        lines[#lines + 1] = item.Label .. ': ' .. tostring(item.Count)
    end
    local baseline = Data.ConnectionAuditBaseline
    if baseline then
        lines[#lines + 1] = string.format(
            'since baseline: %+d handlers / %+d players',
            audit.Handlers - baseline.Handlers,
            audit.Players - baseline.Players
        )
    end
    return table.concat(lines, '\n')
end
function phowg:update_diagnostics()
    local showPerformance = Data.Performance.Enabled
    local showMovement = Toggles.movement_status and Toggles.movement_status.Value
    local showAudit = phowg:toggle_enabled('connection_audit')
    local showESP = phowg:toggle_enabled('player_esp_profile') or showPerformance
    local gui = Data.DiagnosticsGui
    if not showPerformance and not showMovement and not showAudit and not showESP then
        if gui then
            phowg:set_diagnostics_property(gui, 'Enabled', false)
        end
        return
    end
    if not gui then
        gui = Instance.new('ScreenGui')
        gui.Name = 'PhowgDiagnostics'
        gui.ResetOnSpawn = false
        gui.DisplayOrder = 110
        gui.Parent = Data.StatusGui.Parent
        local label = Instance.new('TextLabel')
        label.Name = 'Status'
        label.AnchorPoint = Vector2.new(1, 0)
        label.Position = UDim2.new(1, -16, 0, 16)
        label.Size = UDim2.fromOffset(390, 0)
        label.AutomaticSize = Enum.AutomaticSize.Y
        label.Font = Enum.Font.Code
        label.TextSize = 13
        label.TextXAlignment = Enum.TextXAlignment.Left
        label.TextYAlignment = Enum.TextYAlignment.Top
        label.TextWrapped = true
        label.BorderSizePixel = 0
        label.Parent = gui
        local padding = Instance.new('UIPadding')
        padding.PaddingLeft = UDim.new(0, 10)
        padding.PaddingRight = UDim.new(0, 10)
        padding.PaddingTop = UDim.new(0, 8)
        padding.PaddingBottom = UDim.new(0, 8)
        padding.Parent = label
        local outline = Instance.new('UIStroke')
        outline.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
        outline.Thickness = 1
        outline.Parent = label
        Data.DiagnosticsGui, Data.DiagnosticsLabel, Data.DiagnosticsOutline = gui, label, outline
    end
    phowg:set_diagnostics_property(gui, 'Enabled', true)
    local lines = {}
    if showPerformance then
        local performance = Data.Performance
        local seconds = math.max(performance.Seconds, 0.001)
        local frames = math.max(performance.Frames, 1)
        table.insert(
            lines,
            string.format(
                '%.0f fps | %.2f ms/frame | max %.2f ms',
                performance.Frames / seconds,
                seconds * 1000 / frames,
                performance.MaxFrame * 1000
            )
        )
        local median, p95, p99 = phowg:frame_time_quantiles()
        table.insert(lines, string.format('frame ms median %.2f | p95 %.2f | p99 %.2f (last 600)', median, p95, p99))
        local counts = Data.SharedSignalCounts
        local connections, listeners, loops, threads = counts.Signals, counts.Handlers, 0, counts.Workers
        for _ in pairs(Data.LoopTokens) do
            loops += 1
        end
        for _, job in pairs(Data.HeartbeatJobs) do
            if job.Running then
                threads += 1
            end
        end
        table.insert(
            lines,
            string.format(
                '%d signals / %d handlers | %d loops / %d active workers',
                connections,
                listeners,
                loops,
                threads
            )
        )
        table.insert(lines, string.format('%d slow frames | visual usage %d', performance.Spikes, Data.VisualUsage))
        table.insert(
            lines,
            string.format(
                'background %d active | %d failed | retained UI signals %d',
                Data.BackgroundActive or 0,
                Data.BackgroundFailures or 0,
                #Library.Signals
            )
        )
        for file, revision in pairs(Data.StartupTiming.ComponentVersions or {}) do
            table.insert(
                lines,
                file .. ' r' .. tostring(revision) .. ' | ' .. tostring(Data.StartupTiming.Sources[file])
            )
        end
        table.insert(lines, phowg:combat_diagnostics_text())
        table.insert(lines, 'Callback initial execution / total elapsed:')
        local costs = phowg:performance_top_costs(performance.Samples)
        for index = 1, math.min(5, #costs) do
            local cost = costs[index]
            table.insert(
                lines,
                string.format(
                    '%s: %.2f / %.2f ms | %.1f/s',
                    cost.Name:gsub('event/RunService.', 'frame/'),
                    cost.Average * 1000,
                    cost.Wall * 1000,
                    cost.Count / seconds
                )
            )
        end
        local native = performance.Samples['gun/native shot']
        if native and native.Count > 0 then
            local aim, cosmetics = performance.Samples['gun/aim solution'], performance.Samples['gun/cosmetics']
            table.insert(
                lines,
                string.format(
                    'gun calls %.0f/s | native %.2f | aim %.2f | cosmetics %.2f ms',
                    native.Count / seconds,
                    native.Total * 1000 / native.Count,
                    aim and aim.Total * 1000 / math.max(1, aim.Count) or 0,
                    cosmetics and cosmetics.Total * 1000 / math.max(1, cosmetics.Count) or 0
                )
            )
        end
        table.insert(lines, 'Parent timings include child callbacks; elapsed includes waits and later resumes.')
        local scan = Data.GrenadeScanStats
        if scan then
            lines[#lines + 1] = string.format(
                'projectiles: %d active / %d candidates (%d pending) | %d folder seeds',
                scan.Parts,
                scan.Candidates,
                scan.Pending or 0,
                scan.Seeds
            )
        end
        local cleanup = Data.CleanupCounts
        if cleanup then
            table.insert(
                lines,
                string.format(
                    'watchdog: %d signals, %d handlers, %d active effects',
                    cleanup.Signals,
                    cleanup.Handlers,
                    cleanup.Effects
                )
            )
        end
        if performance.Seconds >= 5 then
            table.clear(performance.Samples)
            performance.Frames, performance.Seconds, performance.Spikes, performance.MaxFrame = 0, 0, 0, 0
        end
    end
    if showESP then
        local esp = Data.ESPInstance
        local profile = esp and esp.Performance
        local average = profile and profile.Average
        if average and (profile.Frames or 0) > 0 then
            lines[#lines + 1] = string.format(
                'ESP projection %.2f | labels/icons %.2f | effects %.2f ms',
                average.ProjectionMs or 0,
                average.LabelsIconsMs or 0,
                average.EffectsMs or 0
            )
            lines[#lines + 1] = string.format(
                'ESP total %.2f ms | peak %.2f ms | %d visible / %d tracked',
                average.TotalMs or 0,
                profile.Peak and profile.Peak.TotalMs or 0,
                profile.Visible or 0,
                profile.Tracked or 0
            )
        end
    end
    if showAudit then
        local audit = Data.ConnectionAudit
        if not audit or tick() - (Data.ConnectionAuditAt or -math.huge) >= 2 then
            audit = phowg:audit_connections()
        end
        lines[#lines + 1] = phowg:connection_audit_text(audit)
    end
    if showMovement then
        table.insert(lines, phowg:movement_status())
    end
    phowg:set_diagnostics_property(Data.DiagnosticsLabel, 'Text', table.concat(lines, '\n'))
    local scale, opacity = phowg:hud_settings()
    local label = Data.DiagnosticsLabel
    if not Data.DiagnosticsScale then
        Data.DiagnosticsScale = Instance.new('UIScale')
        Data.DiagnosticsScale.Parent = label
    end
    phowg:set_diagnostics_property(Data.DiagnosticsScale, 'Scale', scale)
    phowg:set_diagnostics_property(label, 'AnchorPoint', Vector2.new(0, 0))
    phowg:set_diagnostics_property(label, 'TextTransparency', 1 - opacity)
    phowg:set_diagnostics_property(label, 'BackgroundTransparency', 1 - opacity)
    local camera = Workspace.CurrentCamera
    if camera then
        local size = label.AbsoluteSize
        local position = phowg:clamp_hud(
            Vector2.new(
                (camera.ViewportSize.X - size.X) * phowg:visual_number('diagnostics_x', 98, 0, 100) / 100,
                (camera.ViewportSize.Y - size.Y) * phowg:visual_number('diagnostics_y', 2, 0, 100) / 100
            ),
            size
        )
        phowg:set_diagnostics_property(label, 'Position', UDim2.fromOffset(position.X, position.Y))
    end
    phowg:set_diagnostics_property(label, 'BackgroundColor3', Library.MainColor)
    phowg:set_diagnostics_property(label, 'TextColor3', Library.FontColor)
    phowg:set_diagnostics_property(Data.DiagnosticsOutline, 'Color', Library.OutlineColor)
    phowg:set_diagnostics_property(Data.DiagnosticsOutline, 'Transparency', 1 - opacity)
end
