function phowg:cleanup_watchdog()
    if not Toggles.cleanup_watchdog or not Toggles.cleanup_watchdog.Value then
        return
    end
    for owner, _lease in pairs(Data.VisualLeases) do
        if typeof(owner) == 'Instance' and not owner.Parent then
            phowg:release_visual(owner)
        end
    end
    if Data.IsRespawning then
        phowg:clear_afterimages()
        phowg:clear_effects()
    end
    if not Toggles.character_afterimages.Value and Data.AfterimageStates then
        phowg:clear_afterimages()
    end
    if not Toggles.target_hud.Value and Data.TargetHUDGui then
        phowg:hide_target_hud()
    end
    if not Toggles.custom_crosshair.Value and Data.CrosshairGui then
        Data.CrosshairGui.Enabled = false
        phowg:restore_crosshair_defaults()
    end
    local counts = Data.SharedSignalCounts
    Data.CleanupCounts =
        { Visuals = Data.VisualUsage, Signals = counts.Signals, Handlers = counts.Handlers, Effects = 0 }
    for _, pool in pairs(Data.EffectPools or {}) do
        Data.CleanupCounts.Effects += #pool.Active
    end
end
