    { Text = 'forbidden roles csv', Tooltip = 'roles separated by commas' }
)
Data['ShieldModBox']:AddButton('add mod group', function()
    local id = shieldparseid(Options.shield_modgroup.Value)
    if not id then
        Library:Notify('invalid id', 2)
        return
    end
    local roles = {}
    for r in string.gmatch(tostring(Options.shield_modroles.Value or ''), '([^,]+)') do
        local clean = r:match('^%s*(.-)%s*$')
        if clean ~= '' then
            table.insert(roles, clean)
        end
    end
    Data['Shield'].ModGroups[id] =
        { Name = shieldgroupname(id), Forbidden = roles, NotifyRoles = {}, Kick = false, Notify = #roles == 0 }
    Options.shield_modgroup:SetValue('')
    Options.shield_modroles:SetValue('')
    Options.shield_modgroups:SetValues(shieldmodkeys(Data['Shield'].ModGroups))
    shieldsave()
    Library:Notify('mod group ' .. tostring(id), 2)
end)
