Library.BeforeConfigLoad = function(decoded, categories)
    Library.ConfigEffectBatch = true
    Data.ConfigEffects = {}
    Data.RagebotConfigGuns = nil
    phowg:clear_ragebot_idle()
    local objects = decoded and decoded.objects or {}
    local sharedStrafe = false
    for _, option in ipairs(objects) do
        if option.idx == 'target_strafe_mode' then
            sharedStrafe = true
            break
        end
    end
    for index = #objects, 1, -1 do
        if objects[index].idx == 'auto_kill_position' then
            if sharedStrafe then
                table.remove(objects, index)
            else
                objects[index].idx = 'target_strafe_mode'
                sharedStrafe = true
            end
        end
    end
    for _, option in ipairs(decoded and decoded.objects or {}) do
        if option.idx == 'player_esp_accuracy_mode' and option.value == 'this session' then
            option.value = 'this server'
        end
    end
    Data.SkinConfigLoading = true
    Data.SkinConfigMapApplied = nil
    Data.SkinLegacySelection = nil
    local category = SaveManager:GetCategory('skin_selected_weapon')
    if not categories or not next(categories) or categories[category] or table.find(categories, category) then
        for _, option in ipairs(decoded and decoded.objects or {}) do
            if option.idx == 'skin_weapon_skin' and type(option.value) == 'string' then
                Data.SkinLegacySelection = option.value
            end
        end
    end
    Data.ShieldConfigReady = false
    Data.ShieldRevision = (Data.ShieldRevision or 0) + 1
end
Library.AfterProtectionConfigLoad = function()
    Data.ShieldConfigReady = true
    Data.ShieldRevision = (Data.ShieldRevision or 0) + 1
    phowg:flush_protection_checks(true)
end
Library.AfterConfigLoad = function(cancelled)
    local selected = Data.RagebotConfigGuns
    Data.RagebotConfigGuns = nil
    if selected and Options.auto_kill_weapon then
        Options.auto_kill_weapon:SetValue(selected, true)
    end
    phowg:sync_ragebot_weapon_mode()
    if not Data.SkinConfigMapApplied and Data.SkinLegacySelection then
        local weapon = Options.skin_selected_weapon and Options.skin_selected_weapon.Value
        if type(weapon) == 'string' then
            Data.SkinEquipped[weapon] = Data.SkinLegacySelection
        end
    end
    refreshskindropdown()
    Data.ShieldConfigReady = true
    phowg:flush_protection_checks()
    Library:FlushControlCallbacks()
    Data.SkinConfigLoading = nil
    Data.SkinConfigMapApplied = nil
    Data.SkinLegacySelection = nil
    phowg:apply_equipped_skins()
    phowg:flush_config_effects(cancelled)
end
