create_connection(
    'Top_9_Players_PlayerRemoving_Connect_function_',
    connectshared(Players.PlayerRemoving, function(plr)
        if Data['HitConns'] then
            local c = Data['HitConns'][plr]
            if c then
                c:Disconnect()
            end
            Data['HitConns'][plr] = nil
        end
        if Data['HitHealth'] then
            Data['HitHealth'][plr] = nil
        end
        if Data['BloodConns'] then
            local b = Data['BloodConns'][plr]
            if b then
                b:Disconnect()
            end
            Data['BloodConns'][plr] = nil
        end
        if Data['BloodHitAt'] then
            Data['BloodHitAt'][plr] = nil
        end
        if Data['LastHitAt'] then
            Data['LastHitAt'][plr] = nil
        end
        if Data['DamagerConns'] then
            local dc = Data['DamagerConns'][plr]
            if dc then
                if type(dc) == 'table' then
                    for _, cc in pairs(dc) do
                        cc:Disconnect()
                    end
                else
                    dc:Disconnect()
                end
            end
            Data['DamagerConns'][plr] = nil
        end
        if Data['TargetDamagerAt'] then
            Data['TargetDamagerAt'][plr] = nil
        end
        if Data.DamagerCharacters then
            Data.DamagerCharacters[plr] = nil
        end
        if Data['TargetRespawnConns'] then
            local tc = Data['TargetRespawnConns'][plr]
            if tc then
                pcall(function()
                    tc:Disconnect()
                end)
            end
            Data['TargetRespawnConns'][plr] = nil
        end
    end, Players, 'event/Players.PlayerRemoving', 0, 'event/PlayerRemoving', Players)
)
