create_connection(
    'Top_42_Players_PlayerAdded_Connect_function_Plr',
    connectshared(Players.PlayerAdded, function(Plr)
        monitorplayercrew(Plr)
        if Data['PlayerJoinAt'] == nil then
            Data['PlayerJoinAt'] = {}
        end
        Data['PlayerJoinAt'][Plr] = tick()
        if
            Data['StickyAimWatchlist']
            and (Data['StickyAimWatchlist'][Plr.UserId] or Data['StickyAimWatchlist'][Plr.Name])
        then
            Data['SilentAimStickyTargets'][Plr] = true
            Data['LockedTargets'][Plr] = true
            Data['TargetWatchlist'][Plr.UserId] = true
            Data['TargetWatchlist'][Plr.Name] = true
            if Data['SingleLockedTarget'] == nil then
                Data['SingleLockedTarget'] = Plr
            end
            Data['CurrentMainTarget'] = Plr
        end
        if Data['TargetWatchlist'][Plr.UserId] or Data['TargetWatchlist'][Plr.Name] then
            Data['LockedTargets'][Plr] = true
            Data['CurrentMainTarget'] = Plr;
            (function()
                Library:Notify(
                    'tracked player rejoined: ' .. Library:PlayerDisplayName(Plr),
                    Library.NotifyDuration or 4
                )
            end)()
            task.spawn(function()
                local c = Plr.Character
                if not c then
                    return
                end
                if c then
                    c:WaitForChild('HumanoidRootPart', 5)
                end
                if Library.Unloaded or Data.SharedSignalsClosed or Plr.Character ~= c then return end
                updatetracers()
            end)
        end
        requestcrewdropdown()
    end, Players, 'event/Players.PlayerAdded', 0, 'event/PlayerAdded', Players)
)
create_connection(
    'Top_43_Players_PlayerRemoving_Connect_function_',
    connectshared(Players.PlayerRemoving, function(Plr)
        if Data['PlayerJoinAt'] then
            Data['PlayerJoinAt'][Plr] = nil
        end
        if Data['LockedTargets'][Plr] then
            Data['TargetWatchlist'][Plr.UserId] = true
            Data['TargetWatchlist'][Plr.Name] = true
            Data['LockedTargets'][Plr] = nil
        end
        if Data['PrevMainTarget'] == Plr then
            Data['PrevMainTarget'] = nil
        end
        task.delay(5, function()
            requestcrewdropdown()
        end)
    end, Players, 'event/Players.PlayerRemoving', 0, 'event/PlayerRemoving', Players)
)

Data.StartupTiming.Stages['protection setup'] = os.clock() - Data.StartupTiming.ProtectionAt
Data.StartupTiming.Stages['interface and visual setup'] =
    math.max(0, Data.StartupTiming.ProtectionAt - Data.StartupTiming.SetupAt)
Data.ShieldConfigReady = true
Data.StartupReady = true
phowg:watch_esp_settings()
do
    local at = os.clock()
    Library:SetStartupProgress('loading config', 0.55)
    for _, option in pairs(Options) do
        if option.Type == 'Dropdown' then
            option:SetValue(option.Multi and {} or nil, true)
        end
    end
    SaveManager:LoadAutoloadConfig(true)
    Data.StartupTiming.Stages['config load'] = os.clock() - at
    Data.StartupTiming.Total = os.clock() - Data.StartupTiming.Started
end
Library.ControlsReady = true
Library:FlushControlCallbacks()
if
    SaveManager.SetBaseline
    and not SaveManager.CurrentConfig
    and not SaveManager.LastLoadReport
    and not (SaveManager.LastAction and SaveManager.LastAction.Kind == 'load')
then
    SaveManager:SetBaseline()
end
phowg:flush_protection_checks()
Library:SetStartupProgress('warming assets', 0.65)
phowg:queue_background('startup asset warmup', 'known assets', function()
    if not Library.Unloaded and not Data.SharedSignalsClosed then
        phowg:preload_known_assets()
    end
end)
Library.StartupProgressProvider = function()
    local pending = 0
    for _, lane in ipairs({
        'startup asset warmup',
        'animation assets',
        'asset discovery',
        'effect assets',
        'sound assets',
        'particle aura assets',
        'aura templates',
    }) do
        local queue = Data.BackgroundQueues and Data.BackgroundQueues[lane]
        if queue then
            for _ in pairs(queue.Keys) do
                pending += 1
            end
        end
    end
    local queue = Data.AssetPreloadQueue
    local busy = pending > 0 or queue and queue.Worker ~= nil
    local total, completed = Data.AssetLoadTotal or 0, Data.AssetLoadCompleted or 0
    local text = pending > 0 and 'discovering assets; ' .. tostring(pending) .. ' jobs remaining' or 'loading assets'
    text ..= '  ' .. tostring(completed) .. '/' .. tostring(total)
    if (Data.AssetLoadFailed or 0) > 0 then
        text ..= ' (' .. tostring(Data.AssetLoadFailed) .. ' unavailable)'
    end
    if busy then
        text = 'ready; assets caching in background'
    end
    return true, text, 0.99
end
Library:FinishStartupIntro()
task.defer(phowg.resume_target_search)
